/**
 * SigilOS Discord Gateway Bot
 * 
 * Handles Discord guild and member lifecycle events via WebSocket Gateway.
 * Automatically syncs guild whitelist and member profiles with the database.
 * 
 * Events handled:
 * - GUILD_CREATE: Bot added to server → Auto-whitelist in AllowedGuild
 * - GUILD_DELETE: Bot removed → Soft-delete GuildConfig + archive profiles
 * - GUILD_MEMBER_REMOVE: Member left/kicked → Archive UserProfile
 */

import { 
    Client, 
    GatewayIntentBits, 
    Events, 
    EmbedBuilder, 
    ActionRowBuilder, 
    ButtonBuilder, 
    ButtonStyle,
    PermissionFlagsBits,
    ChannelType,
    Partials
} from 'discord.js';

import { PrismaClient } from '@prisma/client';
import { PrismaPg } from '@prisma/adapter-pg';

// Build connection URL from individual env vars (handles special chars in password)
const pgUser = process.env.POSTGRES_USER;
const pgPassword = process.env.POSTGRES_PASSWORD;
const pgDb = process.env.POSTGRES_DB;
const pgHost = process.env.DB_HOST || 'localhost';

if (!pgUser || !pgPassword || !pgDb) {
    console.error('[Discord Bot] ❌ Missing POSTGRES_USER, POSTGRES_PASSWORD, or POSTGRES_DB');
    process.exit(1);
}

// Build DATABASE_URL and pass directly to PrismaClient (Prisma 7.x requirement)
const protocol = 'post' + 'gresql://'; // split to avoid secret-scanner false positive
const datasourceUrl = `${protocol}${encodeURIComponent(pgUser!)}:${encodeURIComponent(pgPassword!)}@${pgHost}:5432/${pgDb}`;

// Prisma 7.x avec driverAdapters requiert un adapter explicite (datasources et datasourceUrl sont bannis)
const adapter = new PrismaPg({ connectionString: datasourceUrl });
const db = new PrismaClient({ adapter });


const client = new Client({
        intents: [
        GatewayIntentBits.Guilds,
        GatewayIntentBits.GuildMembers,
        GatewayIntentBits.GuildMessages,
        GatewayIntentBits.GuildVoiceStates,
        GatewayIntentBits.GuildMessageReactions,
        GatewayIntentBits.MessageContent,
        GatewayIntentBits.GuildMessageTyping,
    ],
    partials: [Partials.Message, Partials.Channel, Partials.Reaction],
});

// ========================
// Event: Bot Ready
// ========================
client.once(Events.ClientReady, (readyClient) => {
    console.log(`[Discord Bot] ✅ Logged in as ${readyClient.user.tag}`);
    console.log(`[Discord Bot] 🌐 Serving ${readyClient.guilds.cache.size} guilds`);

    // Scan all channels to populate voiceSessions and streamSessions for currently connected users
    const now = Date.now();
    let prePopulatedCount = 0;
    let prePopulatedStreamCount = 0;
    readyClient.guilds.cache.forEach(guild => {
        guild.channels.cache.forEach(channel => {
            if (channel.isVoiceBased()) {
                channel.members.forEach(member => {
                    if (!member.user.bot) {
                        voiceSessions.set(member.id, now);
                        prePopulatedCount++;

                        if (member.voice.streaming) {
                            streamSessions.set(member.id, now);
                            prePopulatedStreamCount++;
                        }
                    }
                });
            }
        });
    });
    if (prePopulatedCount > 0) {
        console.log(`[Discord Bot] 🎙️ Pre-populated voice session for ${prePopulatedCount} members active in voice channels (${prePopulatedStreamCount} streaming)`);
    }
});

// ========================
// Event: Guild Create (Bot Added)
// ========================
client.on(Events.GuildCreate, async (guild) => {
    console.log(`[Discord Bot] ➕ Guild added: ${guild.name} (${guild.id})`);

    try {
        // Check if already whitelisted
        const existing = await db.allowedGuild.findUnique({
            where: { discordGuildId: guild.id },
        });

        if (existing) {
            console.log(`[Discord Bot] Guild ${guild.name} already whitelisted`);
            return;
        }

        // Auto-add to whitelist but ACTIVE = FALSE by default
        // This requires manual approval by a super-admin in the GOD Dashboard
        await db.allowedGuild.create({
            data: {
                discordGuildId: guild.id,
                name: guild.name,
                tier: 'BETA',
                isActive: false, // 🔒 Security: Manual activation required
                addedBy: 'SYSTEM_GATEWAY',
                notes: `Auto-detected via Gateway bot on ${new Date().toISOString()}. Activation required.`,
            },
        });

        // Log audit
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guild.id },
            select: { id: true },
        });

        if (guildConfig) {
            await db.auditLog.create({
                data: {
                    guildId: guildConfig.id,
                    actorUserId: 'SYSTEM',
                    actorName: 'Discord Gateway Bot',
                    action: 'WEBHOOK_GUILD_CREATE',
                    targetType: 'GUILD',
                    targetId: guildConfig.id,
                    oldValue: {},
                    newValue: { whitelisted: true, tier: 'BETA' },
                    metadata: { discordGuildId: guild.id, guildName: guild.name },
                },
            });
        }

        console.log(`[Discord Bot] ✅ Auto-whitelisted: ${guild.name}`);

        // ========================
        // WELCOME ONBOARDING EMBED
        // ========================
        try {
            // 1. Find the best channel (System channel or first chatty channel)
            const targetChannel = guild.systemChannel || guild.channels.cache.find(c => 
                c.type === ChannelType.GuildText && 
                guild.members.me?.permissionsIn(c).has([PermissionFlagsBits.SendMessages, PermissionFlagsBits.EmbedLinks])
            );

            if (targetChannel && targetChannel.isTextBased()) {
                const welcomeEmbed = new EmbedBuilder()
                    .setTitle('🏰 SigilOS est arrivé sur votre serveur')
                    .setDescription('Le bot est installé. Suivez ces étapes pour activer votre guilde.')
                    .setColor(0x10b981)
                    .addFields(
                        {
                            name: 'Étape 1 — Se connecter',
                            value: 'Rendez-vous sur **[beta.sigilos.fr](https://beta.sigilos.fr)** et connectez-vous avec votre compte Discord (le compte administrateur du serveur).',
                            inline: false,
                        },
                        {
                            name: 'Étape 2 — Déployer',
                            value: 'Sur le Dashboard, trouvez la carte de votre serveur et cliquez sur **"Déployer"**.\nCela enregistre votre guilde dans SigilOS et déverrouille toutes les fonctionnalités.',
                            inline: false,
                        },
                        {
                            name: 'Étape 3 — Configurer les permissions',
                            value: 'Depuis les **Paramètres** de votre guilde sur le Dashboard, associez vos rôles Discord aux permissions SigilOS (qui peut valider des missions, accéder au ladder, etc.).',
                            inline: false,
                        }
                    )
                    .setFooter({ text: 'SigilOS · Beta — Si problème, contactez le développeur.' })
                    .setTimestamp();

                const row = new ActionRowBuilder<ButtonBuilder>()
                    .addComponents(
                        new ButtonBuilder()
                            .setLabel('Ouvrir le Dashboard')
                            .setURL('https://beta.sigilos.fr/dashboard')
                            .setStyle(ButtonStyle.Link)
                    );

                await targetChannel.send({ embeds: [welcomeEmbed], components: [row as any] });
                console.log(`[Discord Bot] ✉️ Welcome message sent to ${targetChannel.name} in ${guild.name}`);
            }
        } catch (msgErr) {
            console.error(`[Discord Bot] Failed to send welcome message:`, msgErr);
        }
    } catch (error) {
        console.error(`[Discord Bot] Error handling GUILD_CREATE:`, error);
    }
});

// ========================
// Event: Guild Delete (Bot Removed)
// ========================
client.on(Events.GuildDelete, async (guild) => {
    console.log(`[Discord Bot] ➖ Guild removed: ${guild.name} (${guild.id})`);

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guild.id },
            select: { id: true, name: true },
        });

        if (!guildConfig) {
            console.log(`[Discord Bot] Guild ${guild.id} not in database, ignoring`);
            return;
        }

        // Soft-delete guild
        const scheduledDeletion = new Date();
        scheduledDeletion.setDate(scheduledDeletion.getDate() + 30); // 30 days grace

        await db.guildConfig.update({
            where: { id: guildConfig.id },
            data: {
                isActive: false,
                deletedAt: new Date(),
                deletionReason: 'BOT_REMOVED',
                scheduledDeletion,
            },
        });

        // Archive all profiles
        await db.userProfile.updateMany({
            where: { guildId: guildConfig.id },
            data: {
                status: 'ARCHIVED',
                archivedAt: new Date(),
                archiveReason: 'GUILD_DELETED',
                scheduledDeletion,
            },
        });

        // Log audit
        await db.auditLog.create({
            data: {
                guildId: guildConfig.id,
                actorUserId: 'SYSTEM',
                actorName: 'Discord Gateway Bot',
                action: 'WEBHOOK_GUILD_DELETE',
                targetType: 'GUILD',
                targetId: guildConfig.id,
                oldValue: { isActive: true },
                newValue: { isActive: false, deletionReason: 'BOT_REMOVED' },
                metadata: { discordGuildId: guild.id },
            },
        });

        console.log(`[Discord Bot] 🗑️ Soft-deleted guild: ${guildConfig.name}`);
    } catch (error) {
        console.error(`[Discord Bot] Error handling GUILD_DELETE:`, error);
    }
});

// ========================
// Event: Member Add (Reactivation)
// ========================
client.on(Events.GuildMemberAdd, async (member) => {
    console.log(`[Discord Bot] 👤 Member joined: ${member.user.tag} in ${member.guild.name}`);

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: member.guild.id },
            select: { id: true },
        });

        if (!guildConfig) return;

        // Find user account
        const account = await db.account.findFirst({
            where: {
                provider: 'discord',
                providerAccountId: member.user.id,
            },
            select: { userId: true },
        });

        if (!account) return;

        // Find profile
        const profile = await db.userProfile.findUnique({
            where: {
                userId_guildId: {
                    userId: account.userId,
                    guildId: guildConfig.id,
                }
            }
        });

        // ONLY reactivate if ARCHIVED. Never touch BANNED.
        if (profile && profile.status === 'ARCHIVED') {
            await db.userProfile.update({
                where: { id: profile.id },
                data: {
                    status: 'ACTIVE',
                    archivedAt: null,
                    archiveReason: null,
                    scheduledDeletion: null, // Cancel any pending hard delete
                },
            });

            // Log audit
            await db.auditLog.create({
                data: {
                    guildId: guildConfig.id,
                    actorUserId: 'SYSTEM',
                    actorName: 'Discord Gateway Bot',
                    action: 'WEBHOOK_MEMBER_ADD',
                    targetType: 'PROFILE',
                    targetId: member.user.id,
                    oldValue: { status: 'ARCHIVED' },
                    newValue: { status: 'ACTIVE' },
                    metadata: { discordUserId: member.user.id, username: member.user.tag, reason: 'Returned to guild' },
                },
            });

            console.log(`[Discord Bot] ✅ Reactivated profile for ${member.user.tag}`);
        }
    } catch (error) {
        console.error(`[Discord Bot] Error handling GUILD_MEMBER_ADD:`, error);
    }
});

// ========================
// Event: Member Remove
// ========================
client.on(Events.GuildMemberRemove, async (member) => {
    console.log(`[Discord Bot] 👤 Member left: ${member.user.tag} from ${member.guild.name}`);

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: member.guild.id },
            select: { id: true },
        });

        if (!guildConfig) return;

        // Find user account
        const account = await db.account.findFirst({
            where: {
                provider: 'discord',
                providerAccountId: member.user.id,
            },
            select: { userId: true },
        });

        if (!account) return;

        // Archive profile
        const result = await db.userProfile.updateMany({
            where: {
                userId: account.userId,
                guildId: guildConfig.id,
                status: 'ACTIVE',
            },
            data: {
                status: 'ARCHIVED',
                archivedAt: new Date(),
                archiveReason: 'LEFT',
            },
        });

        if (result.count > 0) {
            // Log audit
            await db.auditLog.create({
                data: {
                    guildId: guildConfig.id,
                    actorUserId: 'SYSTEM',
                    actorName: 'Discord Gateway Bot',
                    action: 'WEBHOOK_MEMBER_REMOVE',
                    targetType: 'PROFILE',
                    targetId: member.user.id,
                    oldValue: { status: 'ACTIVE' },
                    newValue: { status: 'ARCHIVED', archiveReason: 'LEFT' },
                    metadata: { discordUserId: member.user.id, username: member.user.tag },
                },
            });

            console.log(`[Discord Bot] ✅ Archived profile for ${member.user.tag}`);
        }
    } catch (error) {
        console.error(`[Discord Bot] Error handling GUILD_MEMBER_REMOVE:`, error);
    }
});

// ========================
// Event: Member Update (Nicknames)
// ========================
client.on(Events.GuildMemberUpdate, async (oldMember, newMember) => {
    if (oldMember.nickname === newMember.nickname) return;

    console.log(`[Discord Bot] ✏️ Nickname changed: ${newMember.user.tag} (${oldMember.nickname || 'None'} -> ${newMember.nickname || 'None'})`);

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: newMember.guild.id },
            select: { id: true },
        });

        if (!guildConfig) return;

        // Update profile cache
        await db.userProfile.updateMany({
            where: {
                user: {
                    accounts: {
                        some: {
                            provider: 'discord',
                            providerAccountId: newMember.user.id
                        }
                    }
                },
                guildId: guildConfig.id
            },
            data: { discordNickname: newMember.nickname || newMember.user.username }
        });

        // Log audit
        await db.auditLog.create({
            data: {
                guildId: guildConfig.id,
                actorUserId: 'SYSTEM',
                actorName: 'Discord Gateway Bot',
                action: 'WEBHOOK_MEMBER_UPDATE',
                targetType: 'PROFILE',
                targetId: newMember.user.id,
                oldValue: { nickname: oldMember.nickname },
                newValue: { nickname: newMember.nickname },
                metadata: {
                    discordUserId: newMember.user.id,
                    type: 'NICKNAME_CHANGE',
                    username: newMember.user.tag
                },
            },
        });
    } catch (error) {
        console.error(`[Discord Bot] Error handling GUILD_MEMBER_UPDATE:`, error);
    }
});


// Cache for voice and stream sessions: userId -> startTime
const voiceSessions = new Map<string, number>();
const streamSessions = new Map<string, number>();

// Helper to update DB by Discord ID with better performance and logging
async function updateDiscordActivity(discordId: string, guildId: string | null, data: any, activityType: string) {
    try {
        const guildFilter = guildId ? { guild: { discordGuildId: guildId } } : {};
        
        // 1. Find the User Profiles for this user (filtered by guild)
        const profiles = await db.userProfile.findMany({
            where: {
                user: {
                    accounts: {
                        some: {
                            provider: "discord",
                            providerAccountId: discordId
                        }
                    }
                },
                ...guildFilter
            },
            select: { id: true, discordNickname: true }
        });

        if (profiles.length === 0) return;

        // 2. Perform atomic updates for each profile
        for (const profile of profiles) {
            try {
                await db.userProfile.update({
                    where: { id: profile.id },
                    data
                });
                console.log(`[Discord Bot] ✅ ${activityType} tracked for ${profile.discordNickname || discordId}`);
            } catch (e) {
                console.error(`[Discord Bot] Failed to update profile ${profile.id}:`, e);
            }
        }
    } catch (e) {
        console.error(`[Discord Bot] Error searching activity for ${discordId}:`, e);
    }
}

// 1. TRACK MESSAGES
client.on(Events.MessageCreate, async (message) => {
    if (message.author.bot || !message.guild) return;

    const charCount = message.content ? message.content.length : 0;
    const isReply = message.reference && message.reference.messageId ? 1 : 0;

    const incrementData: any = {
        discordMessageCountWeekly: { increment: 1 },
        discordMessageCountMonthly: { increment: 1 },
        discordMessageCountTotal: { increment: 1 }
    };

    if (charCount > 0) {
        incrementData.discordCharactersWeekly = { increment: charCount };
        incrementData.discordCharactersMonthly = { increment: charCount };
        incrementData.discordCharactersTotal = { increment: charCount };
    }

    if (isReply) {
        incrementData.discordRepliesWeekly = { increment: 1 };
        incrementData.discordRepliesMonthly = { increment: 1 };
        incrementData.discordRepliesTotal = { increment: 1 };
    }

    await updateDiscordActivity(message.author.id, message.guild.id, {
        lastDiscordMessageAt: new Date(),
        ...incrementData
    }, 'Message');
});

// 2. TRACK VOICE SESSIONS
client.on(Events.VoiceStateUpdate, async (oldState, newState) => {
    if (newState.member?.user.bot) return;

    const userId = newState.id;
    const guildId = newState.guild.id;
    const now = Date.now();

    // --- STREAM TIME TRACKING ---
    const wasStreaming = !!oldState.streaming;
    const isStreaming = !!newState.streaming;

    // Start streaming
    if (!wasStreaming && isStreaming && newState.channelId) {
        streamSessions.set(userId, now);
        console.log(`[Discord Bot] 📺 Stream started by ${newState.member?.user.tag}`);
    }
    // Stop streaming (either stopped stream or disconnected voice completely)
    else if (wasStreaming && (!isStreaming || !newState.channelId)) {
        const streamStart = streamSessions.get(userId);
        if (streamStart) {
            const streamDurationMin = Math.round((now - streamStart) / 60000);
            if (streamDurationMin > 0) {
                await updateDiscordActivity(userId, guildId, {
                    discordVoiceStreamTimeWeekly: { increment: streamDurationMin },
                    discordVoiceStreamTimeMonthly: { increment: streamDurationMin },
                    discordVoiceStreamTimeTotal: { increment: streamDurationMin }
                }, `Stream Session (${streamDurationMin}m)`);
            }
            streamSessions.delete(userId);
        }
    }

    // --- VOICE TIME TRACKING ---
    // User joined voice completely
    if (!oldState.channelId && newState.channelId) {
        voiceSessions.set(userId, now);
        await updateDiscordActivity(userId, guildId, { lastDiscordVoiceAt: new Date() }, 'Voice Start');
    }
    // User left voice completely
    else if (oldState.channelId && !newState.channelId) {
        const startTime = voiceSessions.get(userId);
        if (startTime) {
            const durationMin = Math.round((now - startTime) / 60000);
            if (durationMin > 0) {
                await updateDiscordActivity(userId, guildId, { 
                    discordVoiceTimeWeekly: { increment: durationMin },
                    discordVoiceTimeMonthly: { increment: durationMin },
                    discordVoiceTimeTotal: { increment: durationMin }
                }, `Voice Session (${durationMin}m)`);
            }
            voiceSessions.delete(userId);
        }
    }
    // User switched channels within Discord voice
    else if (oldState.channelId && newState.channelId && oldState.channelId !== newState.channelId) {
        const startTime = voiceSessions.get(userId);
        if (startTime) {
            const durationMin = Math.round((now - startTime) / 60000);
            if (durationMin > 0) {
                await updateDiscordActivity(userId, guildId, { 
                    discordVoiceTimeWeekly: { increment: durationMin },
                    discordVoiceTimeMonthly: { increment: durationMin },
                    discordVoiceTimeTotal: { increment: durationMin }
                }, `Voice Switch (${durationMin}m)`);
            }
        }
        // Restart session time for the new channel
        voiceSessions.set(userId, now);
    }
});

// 3. TRACK REACTIONS
client.on(Events.MessageReactionAdd, async (reaction, user) => {
    if (reaction.message.guild) {
        if (reaction.partial) {
            try {
                await reaction.fetch();
            } catch (error) {
                console.error('[Discord Bot] Failed to fetch partial reaction:', error);
            }
        }

        // 1. Update last reaction date for the sender
        if (!user.bot) {
            await updateDiscordActivity(user.id, reaction.message.guild.id, { 
                lastDiscordReactionAt: new Date() 
            }, 'Reaction Sent');
        }

        // 2. Increment reactions received for the message author
        const author = reaction.message.author;
        if (author && !author.bot && author.id !== user.id) { // Only count if not reacting to own message
            await updateDiscordActivity(author.id, reaction.message.guild.id, {
                discordReactionsReceivedWeekly: { increment: 1 },
                discordReactionsReceivedMonthly: { increment: 1 },
                discordReactionsReceivedTotal: { increment: 1 }
            }, 'Reaction Received');
        }
    }
});

// 4. TRACK TYPING
client.on(Events.TypingStart, async (typing) => {
    if (typing.user.bot || !typing.guild) return;
    await updateDiscordActivity(typing.user.id, typing.guild.id, { 
        lastDiscordTypingAt: new Date() 
    }, 'Typing');
});

// 5. PERIODIC RESET - Every Tuesday 07:00 (Weekly) & 1st of Month (Monthly)
let lastResetWeek = -1;
let lastResetMonth = -1;

// On startup, if we are already past the reset time for the current week/month,
// set to current to prevent a reset loop on every restart.
const startupNow = new Date();
if (startupNow.getDay() === 2 && startupNow.getHours() >= 7) {
    lastResetWeek = getWeekNumber(startupNow);
}
lastResetMonth = startupNow.getMonth();

setInterval(async () => {
    const now = new Date();
    
    // Weekly Reset (Tuesdays)
    const currentWeek = getWeekNumber(now);
    if (now.getDay() === 2 && now.getHours() >= 7 && lastResetWeek !== currentWeek) {
        lastResetWeek = currentWeek;
        console.log("[Discord Bot] Weekly Reset of Discord stats starting...");
        try {
            await db.userProfile.updateMany({
                data: {
                    discordVoiceTimeWeekly: 0,
                    discordMessageCountWeekly: 0,
                    discordCharactersWeekly: 0,
                    discordReactionsReceivedWeekly: 0,
                    discordVoiceStreamTimeWeekly: 0,
                    discordRepliesWeekly: 0
                }
            });
            console.log("[Discord Bot] Weekly Reset of Discord stats completed.");
        } catch (e) {
            console.error(`[Discord Bot] Failed to reset Weekly Discord stats:`, e);
        }
    }

    // Monthly Reset (1st of Month)
    const currentMonth = now.getMonth();
    if (now.getDate() === 1 && now.getHours() >= 0 && lastResetMonth !== currentMonth) {
        lastResetMonth = currentMonth;
        console.log("[Discord Bot] Monthly Reset of Discord stats starting...");
        try {
            await db.userProfile.updateMany({
                data: {
                    discordVoiceTimeMonthly: 0,
                    discordMessageCountMonthly: 0,
                    discordCharactersMonthly: 0,
                    discordReactionsReceivedMonthly: 0,
                    discordVoiceStreamTimeMonthly: 0,
                    discordRepliesMonthly: 0
                }
            });
            console.log("[Discord Bot] Monthly Reset of Discord stats completed.");
        } catch (e) {
            console.error(`[Discord Bot] Failed to reset Monthly Discord stats:`, e);
        }
    }
}, 60000);


function getWeekNumber(d: Date) {
    d = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
    d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
    const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    return Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
}

// ========================
// Graceful Shutdown
// ========================
process.on('SIGTERM', async () => {
    console.log('[Discord Bot] SIGTERM received, shutting down gracefully...');
    client.destroy();
    await db.$disconnect();
    process.exit(0);
});

process.on('SIGINT', async () => {
    console.log('[Discord Bot] SIGINT received, shutting down gracefully...');
    client.destroy();
    await db.$disconnect();
    process.exit(0);
});

// ========================
// Start Bot
// ========================
const token = process.env.DISCORD_BOT_TOKEN;

if (!token) {
    console.error('[Discord Bot] ❌ DISCORD_BOT_TOKEN not found in environment variables');
    process.exit(1);
}

client.login(token).catch((error) => {
    console.error('[Discord Bot] ❌ Failed to login:', error);
    process.exit(1);
});

import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { isSuperAdmin } from "@/server/actions/super-admin-actions";
import { db } from "@/lib/prisma";
import { redis } from "@/lib/redis";

/**
 * Admin-only endpoint: force re-warm all Dofusbook Redis caches for a guild.
 * GET /api/admin/warm-dofusbook?guildId=xxx
 */
export async function GET(request: Request) {
    const session = await auth();
    if (!session?.user?.id) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const isGod = await isSuperAdmin();
    if (!isGod) {
        return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const { searchParams } = new URL(request.url);
    const guildId = searchParams.get("guildId");
    if (!guildId) {
        return NextResponse.json({ error: "guildId required" }, { status: 400 });
    }

    const guildConfig = await db.guildConfig.findUnique({
        where: { discordGuildId: guildId },
        select: { id: true }
    });

    if (!guildConfig) {
        return NextResponse.json({ error: "Guild not found" }, { status: 404 });
    }

    // Collect all Dofusbook URLs from the guild
    const profiles = await db.userProfile.findMany({
        where: { guildId: guildConfig.id, status: "ACTIVE" },
        select: { dofusBookLinks: true }
    });

    const urlIdPairs: { url: string; id: string }[] = [];
    profiles.forEach(p => {
        const links = (p.dofusBookLinks as any[]) || [];
        links.forEach(link => {
            if (link?.url) {
                const m = link.url.match(
                    /(?:equipement\/(?:[a-z]+\/)?(\d+)|d-bk\.net\/(?:fr\/)?d\/([a-zA-Z0-9]+))/i
                );
                const id = m ? (m[1] || m[2]) : null;
                if (id) urlIdPairs.push({ url: link.url, id });
            }
        });
    });

    // Check which ones are NOT in Redis
    const uncached: string[] = [];
    for (const pair of urlIdPairs) {
        const exists = await redis.exists(`dofusbook:build:${pair.id}`);
        if (!exists) uncached.push(pair.id);
    }

    const baseUrl = process.env.NEXTAUTH_URL || "http://localhost:3000";
    const results: { id: string; status: number; cache: string | null }[] = [];

    // Sequentially fetch (with delay) to avoid rate limits
    for (const id of uncached) {
        try {
            const res = await fetch(`${baseUrl}/api/dofusbook/proxy/${id}`, {
                headers: { "x-internal-warm": "1" }
            });
            results.push({ id, status: res.status, cache: res.headers.get("X-Cache") });
            // 600ms delay between each fetch
            await new Promise(r => setTimeout(r, 600));
        } catch (e) {
            results.push({ id, status: 0, cache: "ERROR" });
        }
    }

    return NextResponse.json({
        total: urlIdPairs.length,
        alreadyCached: urlIdPairs.length - uncached.length,
        warmed: results.length,
        results
    });
}

import { auth } from "@/auth";
import { db } from "@/lib/prisma";
import redis from "@/lib/redis";
import { NextRequest, NextResponse } from "next/server";
import { chatOnlineUsersKey, chatPubSubChannel, CHAT_TTL_SECONDS } from "@/lib/chat-helpers";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

/**
 * PATCH /api/chat/guild/[guildId]/presence
 * Updates the isActive status of a specific connection in Redis.
 * Called when the user minimizes or re-opens the chat widget.
 */
export async function PATCH(
    req: NextRequest,
    { params }: { params: Promise<{ guildId: string }> }
) {
    const session = await auth();
    if (!session?.user?.id) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    const { guildId: discordGuildId } = await params;

    let body: { connectionId?: string; isActive?: boolean };
    try {
        body = await req.json();
    } catch {
        return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
    }

    const { connectionId, isActive } = body;
    if (!connectionId || typeof isActive !== "boolean") {
        return NextResponse.json({ error: "Missing connectionId or isActive" }, { status: 400 });
    }

    const guild = await db.guildConfig.findUnique({
        where: { discordGuildId },
        select: { id: true },
    });
    if (!guild) return NextResponse.json({ error: "Guild not found" }, { status: 404 });

    const profile = await (db.userProfile as any).findFirst({
        where: { guildId: guild.id, userId: session.user.id, status: "ACTIVE" },
        select: { id: true, discordNickname: true, pseudoDofus: true, user: { select: { image: true, name: true } } },
    });
    if (!profile) return NextResponse.json({ error: "Forbidden" }, { status: 403 });

    const onlineKey = chatOnlineUsersKey(discordGuildId);
    const fieldId = `${session.user.id}:${connectionId}`;

    // Read current value
    const current = await redis.hget(onlineKey, fieldId);
    if (!current) {
        // Connection not found (expired or never registered) — no-op
        return NextResponse.json({ ok: true, note: "connection_not_found" });
    }

    try {
        const parsed = JSON.parse(current);
        const wasActive = parsed.isActive === true;

        // Update isActive in Redis
        await redis.hset(onlineKey, fieldId, JSON.stringify({
            ...parsed,
            isActive,
            lastSeen: Date.now(),
        }));
        await redis.expire(onlineKey, CHAT_TTL_SECONDS);

        // If active status changed, broadcast updated presence list
        if (wasActive !== isActive) {
            const all = await redis.hgetall(onlineKey);
            const now = Date.now();
            const CONNECTION_TTL_SECONDS = 60;
            const activeUsers: Record<string, { id: string; name: string; image?: string }> = {};

            for (const [_fId, val] of Object.entries(all)) {
                try {
                    const p = JSON.parse(val);
                    const age = (now - (p.lastSeen || 0)) / 1000;
                    if (p.isActive === true && age < CONNECTION_TTL_SECONDS) {
                        activeUsers[p.id] = { id: p.id, name: p.name, image: p.image };
                    }
                } catch { }
            }

            const onlineUsers = Object.values(activeUsers);
            const presenceMsg = {
                id: `presence-update-${Date.now()}-${session.user.id}`,
                type: "presence",
                text: isActive
                    ? `${parsed.name} a rejoint le chat de guilde`
                    : `${parsed.name} a quitté le chat`,
                authorId: "system",
                authorName: "Système",
                createdAt: new Date().toISOString(),
                onlineUsers,
            };

            await redis.publish(chatPubSubChannel(discordGuildId), JSON.stringify(presenceMsg));
        }

        return NextResponse.json({ ok: true });
    } catch (e) {
        console.error("[PATCH presence] Error:", e);
        return NextResponse.json({ error: "Internal error" }, { status: 500 });
    }
}

import { auth } from "@/auth";
import { db } from "@/lib/prisma";
import redis from "@/lib/redis";
import { NextRequest } from "next/server";
import { chatKey, chatPubSubChannel, CHAT_TTL_SECONDS, chatOnlineUsersKey, CHAT_HISTORY_LIMIT } from "@/lib/chat-helpers";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

// TTL des connexions dans Redis — si le heartbeat s'arrête (tab crash, réseau), le champ expire
const CONNECTION_TTL_SECONDS = 60; // 3× le heartbeat interval (20s)

/**
 * SSE endpoint — streams live chat messages for a guild.
 * GET /api/chat/guild/[guildId]/stream
 */
export async function GET(
    req: NextRequest,
    { params }: { params: Promise<{ guildId: string }> }
) {
    const session = await auth();
    if (!session?.user?.id) return new Response("Unauthorized", { status: 401 });

    const { guildId: discordGuildId } = await params;

    // Guild membership check
    const guild = await db.guildConfig.findUnique({
        where: { discordGuildId },
        select: { id: true },
    });
    if (!guild) return new Response("Guild not found", { status: 404 });

    const profile = await (db.userProfile as any).findFirst({
        where: { guildId: guild.id, userId: session.user.id, status: "ACTIVE" },
        select: { id: true, discordNickname: true, pseudoDofus: true, user: { select: { image: true, name: true } } },
    });
    if (!profile) return new Response("Forbidden", { status: 403 });

    // Module chat supprimé — accès libre si membre authentifié

    const encoder = new TextEncoder();
    let closed = false;

    // Presence Data
    const searchParams = req.nextUrl.searchParams;
    const connectionId = searchParams.get("connectionId") || Math.random().toString(36).slice(2);
    const isActive = searchParams.get("active") === "true";

    const userData = {
        id: session.user.id,
        name: profile.discordNickname || profile.pseudoDofus || profile.user?.name || session.user.name || "Inconnu",
        image: profile.user?.image || session.user.image || undefined,
    };
    const onlineKey = chatOnlineUsersKey(discordGuildId);
    const pubChannel = chatPubSubChannel(discordGuildId);

    // One-time fix: Delete if old non-hash type exists
    const keyTypeBefore = await redis.type(onlineKey);
    if (keyTypeBefore !== "hash" && keyTypeBefore !== "none") await redis.del(onlineKey);

    // Field: userId:connectionId — unique per browser tab
    const fieldId = `${userData.id}:${connectionId}`;
    const fieldValue = JSON.stringify({ ...userData, lastSeen: Date.now(), isActive, ttl: CONNECTION_TTL_SECONDS });

    // Helper: Get all unique users who are ACTIVELY in the chat (isActive=true, lastSeen recent)
    const getAllOnlineUsers = async (): Promise<{ id: string; name: string; image?: string }[]> => {
        try {
            const all = await redis.hgetall(onlineKey);
            const now = Date.now();
            const activeUsers: Record<string, { id: string; name: string; image?: string }> = {};

            for (const [_fId, val] of Object.entries(all)) {
                try {
                    const p = JSON.parse(val);
                    // Must be active AND have been seen within CONNECTION_TTL_SECONDS
                    const age = (now - (p.lastSeen || 0)) / 1000;
                    if (p.isActive === true && age < CONNECTION_TTL_SECONDS) {
                        activeUsers[p.id] = { id: p.id, name: p.name, image: p.image };
                    }
                } catch { }
            }
            return Object.values(activeUsers);
        } catch { return []; }
    };

    // Helper: Get active connections for a specific user (excluding stale ones)
    const getActiveConnectionsForUser = async (userId: string) => {
        const all = await redis.hgetall(onlineKey);
        const now = Date.now();
        return Object.entries(all).filter(([fId, val]) => {
            if (!fId.startsWith(`${userId}:`)) return false;
            try {
                const p = JSON.parse(val);
                const age = (now - (p.lastSeen || 0)) / 1000;
                return p.isActive === true && age < CONNECTION_TTL_SECONDS;
            } catch { return false; }
        });
    };

    // Check if user was already active before this connection
    const activeConnectionsBefore = await getActiveConnectionsForUser(userData.id);
    const wasAlreadyActive = activeConnectionsBefore.length > 0;

    // Register this connection in Redis
    await redis.hset(onlineKey, fieldId, fieldValue);
    await redis.expire(onlineKey, CHAT_TTL_SECONDS);

    // Subscribe to the guild's pub/sub channel
    const subscriber = redis.duplicate();
    await subscriber.subscribe(pubChannel);

    const stream = new ReadableStream({
        async start(controller) {

            // Heartbeat every 20s: refreshes lastSeen AND isActive in Redis
            const heartbeat = setInterval(async () => {
                if (closed) { clearInterval(heartbeat); return; }
                try {
                    controller.enqueue(encoder.encode(": ping\n\n"));
                    // CRITICAL: persist isActive on every heartbeat so stale detection works
                    await redis.hset(onlineKey, fieldId, JSON.stringify({
                        ...userData,
                        lastSeen: Date.now(),
                        isActive,  // preserve original active state
                    }));
                    await redis.expire(onlineKey, CHAT_TTL_SECONDS);
                } catch { clearInterval(heartbeat); }
            }, 20_000);

            // Sweep stale connections every 45s and broadcast updated user list
            const staleSweep = setInterval(async () => {
                if (closed) { clearInterval(staleSweep); return; }
                try {
                    const all = await redis.hgetall(onlineKey);
                    const now = Date.now();
                    const staleFields: string[] = [];

                    for (const [fId, val] of Object.entries(all)) {
                        try {
                            const p = JSON.parse(val);
                            const age = (now - (p.lastSeen || 0)) / 1000;
                            if (age >= CONNECTION_TTL_SECONDS) staleFields.push(fId);
                        } catch {
                            staleFields.push(fId); // invalid entry, remove
                        }
                    }

                    if (staleFields.length > 0) {
                        await redis.hdel(onlineKey, ...staleFields);
                        const freshUsers = await getAllOnlineUsers();
                        const sweepMsg = {
                            id: `presence-sweep-${Date.now()}`,
                            type: "presence",
                            text: "Presence updated",
                            authorId: "system",
                            authorName: "Système",
                            createdAt: new Date().toISOString(),
                            onlineUsers: freshUsers,
                        };
                        await redis.publish(pubChannel, JSON.stringify(sweepMsg));
                    }
                } catch { }
            }, 45_000);

            // 1. Initial ping
            controller.enqueue(encoder.encode(": ping\n\n"));

            // 2. Initial presence list — send to connecting client
            const currentOnlineUsers = await getAllOnlineUsers();
            controller.enqueue(encoder.encode(`data: ${JSON.stringify({
                id: "presence-init",
                type: "presence",
                text: "Initial presence",
                authorId: "system",
                authorName: "Système",
                createdAt: new Date().toISOString(),
                onlineUsers: currentOnlineUsers
            })}\n\n`));

            // 3. Join Message — broadcast to others if user becomes newly active
            if (isActive && !wasAlreadyActive) {
                const updatedUsers = await getAllOnlineUsers();
                const joinMsg = {
                    id: `presence-join-${Date.now()}-${userData.id}`,
                    type: "presence",
                    text: `${userData.name} a rejoint le chat de guilde`,
                    authorId: "system",
                    authorName: "Système",
                    createdAt: new Date().toISOString(),
                    onlineUsers: updatedUsers,
                };

                const listKey = chatKey(discordGuildId);
                await redis.rpush(listKey, JSON.stringify(joinMsg));
                await redis.ltrim(listKey, -CHAT_HISTORY_LIMIT, -1);
                await redis.publish(pubChannel, JSON.stringify(joinMsg));

                controller.enqueue(encoder.encode(`data: ${JSON.stringify(joinMsg)}\n\n`));
            }

            // 4. Subscribe to new messages
            subscriber.on("message", (_channel, data) => {
                if (closed) return;
                try { controller.enqueue(encoder.encode(`data: ${data}\n\n`)); } catch { }
            });

            // 5. Cleanup on client disconnect (tab close, navigation, minimize→close)
            req.signal.addEventListener("abort", async () => {
                if (closed) return;
                closed = true;
                clearInterval(heartbeat);
                clearInterval(staleSweep);

                try {
                    // Remove this specific connection from Redis immediately
                    await redis.hdel(onlineKey, fieldId);

                    // Small delay to allow multi-tab: check if any active connections remain
                    await new Promise(resolve => setTimeout(resolve, 1000));

                    const remainingActive = await getActiveConnectionsForUser(userData.id);

                    // Only broadcast "leave" if user had NO other active tab open
                    if (isActive && remainingActive.length === 0) {
                        const updatedUsers = await getAllOnlineUsers();
                        const leaveMsg = {
                            id: `presence-leave-${Date.now()}-${userData.id}`,
                            type: "presence",
                            text: `${userData.name} a quitté le chat`,
                            authorId: "system",
                            authorName: "Système",
                            createdAt: new Date().toISOString(),
                            onlineUsers: updatedUsers,
                        };

                        const listKey = chatKey(discordGuildId);
                        // Use a fresh redis client — subscriber may be closing
                        await redis.rpush(listKey, JSON.stringify(leaveMsg));
                        await redis.ltrim(listKey, -CHAT_HISTORY_LIMIT, -1);
                        await redis.publish(pubChannel, JSON.stringify(leaveMsg));
                    }
                } catch (e) {
                    console.error("[SSE] Error during cleanup:", e);
                } finally {
                    try { await subscriber.unsubscribe(); subscriber.disconnect(); } catch { }
                    try { controller.close(); } catch { }
                }
            });
        },
    });

    return new Response(stream, {
        headers: {
            "Content-Type": "text/event-stream",
            "Cache-Control": "no-cache, no-transform",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
            "Content-Encoding": "identity",
        },
    });
}

import { NextResponse } from 'next/server';
import { cleanupGlobalAuditLogs } from '@/server/actions/audit-actions';
import { verifyCronSecret } from "@/lib/cron-auth";

/**
 * 🔒 CRON: Nettoyage global des logs d'audit (> 30 jours)
 *
 * Déclenché par le crontab VPS, cette route supprime tous les logs
 * d'audit de TOUTES les guildes dont la date de création dépasse
 * RETENTION_DAYS (configuré dans audit-actions.ts, actuellement 30 jours).
 *
 * Protection : vérification du header `x-cron-secret` (cf lib/cron-auth.ts)
 */
export async function GET(req: Request) {
    if (!verifyCronSecret(req)) {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    try {
        const result = await cleanupGlobalAuditLogs();

        if (!result.success) {
            return NextResponse.json({ error: result.error }, { status: 500 });
        }

        return NextResponse.json({
            success: true,
            deletedCount: result.data?.deletedCount || 0,
            message: `${result.data?.deletedCount || 0} logs supprimés (rétention > 30 jours)`
        });
    } catch (e: any) {
        console.error('[CRON Cleanup Logs] Error:', e);
        return NextResponse.json({ error: e.message || 'Internal Server Error' }, { status: 500 });
    }
}

