import { NextResponse } from "next/server";
import { db } from "@/lib/prisma";
import { verifyCronSecret } from "@/lib/cron-auth";

// Wait function to avoid spamming the worker / Ankama
const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

export async function GET(req: Request) {
    try {
        // CRIT-02 FIX — suppression du fallback ?token= (secret dans l'URL = fuite dans les logs)
        if (!verifyCronSecret(req)) {
            return new NextResponse("Unauthorized", { status: 401 });
        }

        const workerUrl = process.env.DOFUS_LADDER_WORKER_URL;
        const workerSecret = process.env.DOFUS_LADDER_WORKER_KEY || process.env.DOFUS_LADDER_WORKER_SECRET;

        if (!workerUrl) {
            return new NextResponse("Worker URL not configured", { status: 500 });
        }

        // 2. Fetch profiles that need updating
        // Cutoff time: older than 12 hours
        const cutoff = new Date(Date.now() - 12 * 60 * 60 * 1000);
        
        // Let's process 5 members per run to be safe
        const profiles = await db.userProfile.findMany({
            where: {
                status: "ACTIVE",
                pseudoDofus: { not: null },
                OR: [
                    { lastLadderUpdate: null },
                    { lastLadderUpdate: { lt: cutoff } }
                ]
            },
            take: 5,
            orderBy: {
                lastLadderUpdate: 'asc'
            },
            select: { 
                id: true, 
                pseudoDofus: true, 
                guildId: true,
                guild: {
                    select: { dofusServerId: true }
                }
            }
        });

        if (profiles.length === 0) {
            return NextResponse.json({ message: "No profiles to update.", count: 0 });
        }

        const results = [];

        // 3. Process each profile sequentially
        for (const profile of profiles) {
            const pseudo = profile.pseudoDofus as string;
            const serverId = profile.guild?.dofusServerId || "295"; // Default to Draconiros
            
            try {
                const headers: any = {};
                if (workerSecret) headers["X-SigilOS-Key"] = workerSecret;

                // --- FETCH SUCCES ---
                const succesRes = await fetch(`${workerUrl}?type=succes&server_id=${serverId}&name=${encodeURIComponent(pseudo)}`, { headers });
                const succesData = await succesRes.json();
                
                // Be gentle with the target server
                await delay(2000);

                // --- FETCH GENERAL ---
                const generalRes = await fetch(`${workerUrl}?type=general&server_id=${serverId}&name=${encodeURIComponent(pseudo)}`, { headers });
                const generalData = await generalRes.json();

                // Wait between members
                await delay(3000);

                // Check if we found them
                if (succesData.success || generalData.success) {
                    const updateData: any = {
                        lastLadderUpdate: new Date()
                    };

                    if (succesData.success && typeof succesData.points === 'number') {
                        updateData.successPoints = succesData.points;
                        if (succesData.level) updateData.dofusLevel = succesData.level;
                    }

                    if (generalData.success) {
                        if (generalData.level) updateData.dofusLevel = generalData.level;
                        if (generalData.totalXp) updateData.totalXp = BigInt(generalData.totalXp);
                        if (generalData.classe) updateData.classe = generalData.classe;
                    }

                    await db.userProfile.update({
                        where: { id: profile.id },
                        data: updateData
                    });

                    results.push({ pseudo, success: true, points: succesData.points, level: generalData.level || succesData.level });
                } else {
                    // Character not found or API error.
                    // We still update the lastLadderUpdate so we don't infinitely retry them in the next 12h
                    await db.userProfile.update({
                        where: { id: profile.id },
                        data: { lastLadderUpdate: new Date() }
                    });
                    results.push({ pseudo, success: false, reason: "Not found on ladder" });
                }

            } catch (err) {
                console.error(`Error updating ladder for ${pseudo}:`, err);
                results.push({ pseudo, success: false, error: String(err) });
            }
        }

        const summary = `Synchronisation effectuée sur ${profiles.length} profils.\n- Réussis : ${results.filter(r => r.success).length}\n- Échecs : ${results.filter(r => !r.success).length}`;

        // SEND NOTIFICATION TO GOD DASHBOARD & DISCORD
        const { notifyGod } = await import("@/server/actions/god-notif-actions");
        await notifyGod({
            title: "Ladder General/Succès Sync",
            message: summary,
            type: "WORKER_SYNC",
            success: results.some(r => r.success) || profiles.length === 0, // Success if at least one worked or nothing to do
            metadata: { 
                batch_size: profiles.length,
                success_count: results.filter(r => r.success).length,
                fail_count: results.filter(r => !r.success).length
            }
        });

        return NextResponse.json({
            message: "Batch completed",
            count: profiles.length,
            results
        });

    } catch (error: any) {
        console.error("Cron Ladder Sync Error:", error);
        
        // Notify of fatal failure
        const { notifyGod } = await import("@/server/actions/god-notif-actions");
        await notifyGod({
            title: "CRITICAL: Ladder Sync Failed",
            message: `Erreur fatale dans le cron ladder sync : ${error.message || String(error)}`,
            type: "WORKER_SYNC",
            success: false,
            ping: true // Fatal failure should ping discord
        });

        return new NextResponse("Internal Server Error", { status: 500 });
    }
}

import { NextResponse } from "next/server";
export const dynamic = "force-dynamic";
import { db } from "@/lib/prisma";
import { sendChannelMessage } from "@/server/discord";
import { verifyCronSecret } from "@/lib/cron-auth";

/**
 * CRON: Mission Management Reset Notification
 * Triggered every Tuesday at 08h00 (Paris Time / Dofus Reset)
 * ✅ Protégé par x-cron-secret (fail-closed si secret absent)
 */
export async function GET(req: Request) {
    try {
        // CRIT-02 FIX — suppression du fallback ?token= (secret dans l'URL = fuite dans les logs)
        if (!verifyCronSecret(req)) {
            return new NextResponse("Unauthorized", { status: 401 });
        }

        // 2. Day Check (Just in case the scheduler triggers too often)
        const now = new Date();
        const isTuesday = now.getUTCDay() === 2; // 0 = Sunday, 1 = Monday, 2 = Tuesday
        
        if (!isTuesday) {
            return NextResponse.json({ message: "Today is not Tuesday. Skipping." });
        }

        // 3. GLOBAL RESET: Clear all mission XP overrides for the new week
        await db.guildConfig.updateMany({
            where: { missionWeekXpOverride: { not: null } },
            data: { missionWeekXpOverride: null } as any
        });

        // 4. Fetch guilds with Management Notification enabled
        const guilds = await db.guildConfig.findMany({
            where: {
                missionManagementNotifyChannelId: { not: null },
                isActive: true
            },
            select: {
                id: true,
                name: true,
                discordGuildId: true,
                missionManagementNotifyChannelId: true,
                missionManagementNotifyRoleId: true
            }
        });

        if (guilds.length === 0) {
            return NextResponse.json({ message: "No guilds configured for management notifications." });
        }

        const results = [];

        for (const guild of guilds) {
            const channelId = guild.missionManagementNotifyChannelId!;
            const roleId = guild.missionManagementNotifyRoleId;
            
            // Build the Ping & Embed
            const pings = roleId ? `<@&${roleId}>` : "";
            const dashboardUrl = `${process.env.NEXT_PUBLIC_APP_URL}/dashboard/${guild.discordGuildId}/admin/validation`;

            const messageId = await sendChannelMessage(
                channelId,
                "", // empty content if using mentionContent
                {
                    embedTitle: "🚀 Reset Hebdomadaire & Nouvelles Missions",
                    embedDescription: `Le reset Dofus vient d'avoir lieu !\n\nIl est temps de **générer les nouvelles missions** hebdomadaires et de vérifier si des preuves de la semaine dernière sont encore en attente.\n\nCliquez sur le bouton ci-dessous pour accéder directement à l'interface de gestion.`,
                    embedColor: 0x6366f1, // Indigo
                    mentionContent: pings,
                    embedThumbnail: "https://sigilos.fr/assets/ui/mission-reset.png", // Use a generic image or placeholder
                    components: [
                        {
                            type: 1, // Action Row
                            components: [
                                {
                                    type: 2, // Button
                                    label: "Gérer les Missions",
                                    style: 5, // Link
                                    url: dashboardUrl,
                                    emoji: { name: "🛠️" }
                                }
                            ]
                        }
                    ]
                }
            );

            results.push({ 
                guild: guild.name, 
                success: !!messageId, 
                channelId 
            });
        }

        // 5. GLOBAL GOD NOTIFICATION (New for SigilOS Administration)
        try {
            const platformConfig = await db.platformConfig.findUnique({ where: { id: "singleton" } });
            if ((platformConfig as any)?.godNotifyChannelId) {
                const ping = (platformConfig as any).godNotifyRoleId ? `<@&${(platformConfig as any).godNotifyRoleId}>` : "";
                await sendChannelMessage(
                    (platformConfig as any).godNotifyChannelId,
                    "",
                    {
                        embedTitle: "📣 Reset Hebdomadaire Global",
                        embedDescription: `Le reset hebdomadaire vient d'être effectué sur l'ensemble de la plateforme !\n\n- Toutes les missions ont été réinitialisées.\n- Les XP Overrides ont été purgés.\n- Les notifications de guilde ont été envoyées aux ${guilds.length} serveurs actifs.`,
                        embedColor: 0x8b5cf6, // Violet
                        mentionContent: ping,
                        embedFooter: "SigilOS Platform Management",
                        embedThumbnail: "https://sigilos.fr/assets/ui/icons/admin-reset.png"
                    }
                );
            }
        } catch (e) {
            console.error("[Cron] God notification failed:", e);
        }

        return NextResponse.json({
            message: "Notifications process completed",
            guildsCount: guilds.length,
            results
        });

    } catch (error) {
        console.error("Cron Mission Management Reset Error:", error);
        return new NextResponse("Internal Server Error", { status: 500 });
    }
}

import { NextResponse } from 'next/server';
import { sendGlobalStatusPing } from '@/server/actions/status-actions';
import { verifyCronSecret } from "@/lib/cron-auth";

export async function GET(req: Request) {
    // CRIT-02 FIX — avant le bug : si CRON_SECRET=undefined,
    // "Bearer undefined" ne correspondait à aucun header réel →
    // tout le monde était autorisé car on tombait dans le fallback ?key=undefined
    // qui lui aussi ne matche jamais → la route était OUVERTE sans secret configuré.
    if (!verifyCronSecret(req)) {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    try {
        const result = await sendGlobalStatusPing(false);
        
        if (!result.success) {
            return NextResponse.json({ error: result.error }, { status: 500 });
        }

        return NextResponse.json({ 
            success: true, 
            status: 'Systems Nominal',
            stats: result.stats 
        });
    } catch (e: any) {
        console.error('[CRON Status Ping] Fatal Error:', e);
        return NextResponse.json({ error: e.message || 'Internal Server Error' }, { status: 500 });
    }
}

// UptimeRobot utilise souvent des requêtes HEAD par défaut pour le monitoring.
// En autorisant HEAD et en le redirigeant vers GET, le CRON s'activera correctement.
export async function HEAD(req: Request) {
    return GET(req);
}

import { NextRequest, NextResponse } from "next/server";
import { verifyDiscordSignature } from "@/server/discord";
import { db } from "@/lib/prisma";
import { getAppBaseUrl } from "@/lib/utils";

// ============================================
// DOFUS CLASSES for Modal validation
// ============================================
const VALID_CLASSES = [
    "Cra", "Ecaflip", "Eliotrope", "Eniripsa", "Enutrof",
    "Féca", "Forgelance", "Huppermage", "Iop", "Osamodas",
    "Ouginak", "Pandawa", "Roublard", "Sacrieur", "Sadida",
    "Sram", "Steamer", "Xélor", "Zobal",
];

// ============================================
// RATE LIMIT (simple in-memory, per Discord user)
// ============================================
const rateLimitMap = new Map<string, { count: number; resetAt: number }>();

function checkRateLimit(key: string, maxRequests: number, windowMs: number): boolean {
    const now = Date.now();
    const entry = rateLimitMap.get(key);

    if (!entry || now > entry.resetAt) {
        rateLimitMap.set(key, { count: 1, resetAt: now + windowMs });
        return true;
    }

    if (entry.count >= maxRequests) return false;

    entry.count++;
    return true;
}

/** Returns remaining wait seconds (0 = not rate-limited) */
function getRateLimitRemaining(key: string, maxRequests: number, windowMs: number): number {
    const now = Date.now();
    const entry = rateLimitMap.get(key);

    if (!entry || now > entry.resetAt) {
        rateLimitMap.set(key, { count: 1, resetAt: now + windowMs });
        return 0;
    }

    if (entry.count >= maxRequests) {
        return Math.ceil((entry.resetAt - now) / 1000);
    }

    entry.count++;
    return 0;
}

// ============================================
// HELPERS
// ============================================

async function findUserByDiscordId(discordId: string) {
    return db.account.findFirst({
        where: { provider: "discord", providerAccountId: discordId },
        select: { userId: true },
    });
}

export async function POST(request: NextRequest) {
    try {
        const bodyText = await request.text();
        const isValid = await verifyDiscordSignature(request, bodyText);

        if (!isValid) {
            return NextResponse.json({ error: "Invalid signature" }, { status: 401 });
        }

        const payload = JSON.parse(bodyText);

        // 1. Handle Ping
        if (payload.type === 1) {
            return NextResponse.json({ type: 1 });
        }

        // 2. Handle Component Interaction (Button click)
        if (payload.type === 3) {
            const { custom_id } = payload.data;
            const { member, guild_id } = payload;

            // Rate limit: 10 interactions per 60s per discord user
            if (!checkRateLimit(`interaction:${member.user.id}`, 10, 60_000)) {
                return NextResponse.json({
                    type: 4,
                    data: { content: "⏳ Tu fais trop de requêtes. Réessaie dans quelques secondes.", flags: 64 },
                });
            }

            const [prefix, action, entityId] = custom_id.split(":");

            const account = await findUserByDiscordId(member.user.id);
            if (!account && prefix !== "ticket") {
                return NextResponse.json({
                    type: 4,
                    data: { content: "❌ Tu dois t'être connecté au moins une fois sur le site pour utiliser ce bouton.", flags: 64 },
                });
            }

            // =============================================================
            // RBAC Permission Gate (centralized for ALL Discord interactions)
            // --
            // Maps interaction prefix → required permission.
            // When adding a NEW MODULE with Discord buttons:
            //   1. Add the permission constant in lib/permissions.ts
            //   2. Add an entry here: "prefix": PERMISSIONS.XXX
            //   3. Handle the prefix logic below (join/leave/etc.)
            // Owners and Discord admins bypass automatically (see internalCheckPermission).
            // =============================================================
            const { internalCheckPermission } = await import("@/server/actions/user-actions");
            const { PERMISSIONS } = await import("@/lib/permissions");

            const DISCORD_PERM_MAP: Record<string, string> = {
                calendar: PERMISSIONS.COMMUNITY_ACCESS,   // Calendrier = participation sociale
                songes: PERMISSIONS.GAME_OPERATIONS,      // Songes = organisation d'activités
                dj: PERMISSIONS.GAME_OPERATIONS,          // Donjons = organisation d'activités
                // NOTE: 'poll' is intentionally NOT in this map.
                // Poll vote security is enforced downstream via SigilOS profile check
                // (db.userProfile lookup). The Discord API gate can false-negative
                // on rate limits or temporary API failures, blocking valid members.
                svc: PERMISSIONS.GAME_OPERATIONS,         // Services = organisation d'activités
            };

            const requiredPerm = DISCORD_PERM_MAP[prefix];
            if (requiredPerm) {
                const isAuthorized = await internalCheckPermission(guild_id, member.user.id, requiredPerm as any);
                if (!isAuthorized) {
                    return NextResponse.json({
                        type: 4,
                        data: {
                            content: "🚫 Tes rôles Discord ne t'autorisent pas à utiliser cette fonctionnalité. Contacte un admin de ta guilde.",
                            flags: 64,
                        },
                    });
                }
            }

            let result;

            if (prefix === "calendar") {
                if (action === "join") {
                    const { processRegistration } = await import("@/server/calendar-service");
                    result = await processRegistration(guild_id, entityId, account!.userId);
                } else if (action === "leave") {
                    const { processUnregistration } = await import("@/server/calendar-service");
                    result = await processUnregistration(guild_id, entityId, account!.userId);
                }
            } else if (prefix === "songes") {
                if (action === "join") {
                    // Open a Modal for class selection + optional message
                    return NextResponse.json({
                        type: 9, // MODAL
                        data: {
                            custom_id: `songes:apply:${entityId}`,
                            title: "📩 Candidature Run Songes",
                            components: [
                                {
                                    type: 1, // Action Row
                                    components: [
                                        {
                                            type: 4, // Text Input
                                            custom_id: "classe",
                                            label: "Ta classe Dofus",
                                            style: 1, // Short
                                            placeholder: "Ex: Cra, Iop, Eniripsa...",
                                            required: true,
                                            min_length: 2,
                                            max_length: 30,
                                        },
                                    ],
                                },
                                {
                                    type: 1, // Action Row 
                                    components: [
                                        {
                                            type: 4, // Text Input
                                            custom_id: "message",
                                            label: "Message (optionnel)",
                                            style: 2, // Paragraph
                                            placeholder: "Ex: Cra opti dispo 21h",
                                            required: false,
                                            max_length: 200,
                                        },
                                    ],
                                },
                            ],
                        },
                    });
                } else if (action === "leave") {
                    const { processRunLeave } = await import("@/server/songes-service");
                    result = await processRunLeave(guild_id, entityId, account!.userId);
                }
            } else if (prefix === "poll") {
                if (action === "vote") {
                    // Find the internal guild config by discordGuildId (guild_id)
                    const { processPollVote } = await import("@/server/actions/poll-actions");
                    const guild = await (db as any).guildConfig.findFirst({
                        where: {
                            OR: [{ id: guild_id }, { discordGuildId: guild_id }],
                        },
                        select: { id: true },
                    });

                    if (!guild) {
                        return NextResponse.json({
                            type: 4,
                            data: { content: "❌ Guilde introuvable sur SigilOS.", flags: 64 },
                        });
                    }

                    const profile = await db.userProfile.findUnique({
                        where: { userId_guildId: { userId: account!.userId, guildId: guild.id } }
                    });

                    if (!profile) {
                        return NextResponse.json({
                            type: 4,
                            data: { content: "❌ Tu n'es pas membre de cette guilde sur SigilOS.", flags: 64 },
                        });
                    }

                    result = await processPollVote(guild_id, profile.id, entityId);

                    if (result.success) {
                        const actionLabel = result.data?.action === "voted" ? "enregistré" : "retiré";
                        return NextResponse.json({
                            type: 4,
                            data: { content: `✅ Ton vote a été ${actionLabel} avec succès !`, flags: 64 },
                        });
                    }
                }
            } else if (prefix === "dj") {
                // Rate limit spécifique DJ : 3 actions (join/leave) par post par user / 30s
                const djKey = `dj:${member.user.id}:${entityId}`;
                const waitSecs = getRateLimitRemaining(djKey, 3, 30_000);
                if (waitSecs > 0) {
                    return NextResponse.json({
                        type: 4,
                        data: { content: `⏳ Doucement ! Réessaie dans **${waitSecs}s**.`, flags: 64 },
                    });
                }

                if (action === "join" || action === "leave") {
                    // Récupérer le post pour obtenir le guildId Prisma interne (≠ Discord guild_id snowflake)
                    const post = await (db as any).djSearchPost.findUnique({
                        where: { id: entityId },
                        select: { id: true, status: true, guildId: true },
                    });

                    if (!post) {
                        return NextResponse.json({
                            type: 4,
                            data: { content: "❌ Ce groupe n'existe plus ou a expiré.", flags: 64 },
                        });
                    }

                    if (post.status !== "OPEN" && post.status !== "FULL") {
                        return NextResponse.json({
                            type: 4,
                            data: { content: "❌ Ce groupe est fermé.", flags: 64 },
                        });
                    }

                    // Chercher le profil via post.guildId (CUID Prisma), PAS via guild_id (Discord snowflake)
                    const profile = await db.userProfile.findFirst({
                        where: { userId: account!.userId, guildId: post.guildId },
                    });

                    if (!profile) {
                        return NextResponse.json({
                            type: 4,
                            data: { content: "❌ Tu n'es pas membre de cette guilde sur SigilOS.", flags: 64 },
                        });
                    }

                    if (action === "join") {
                        const { internalJoinDjPost } = await import("@/server/actions/dungeon-finder-actions");
                        result = await internalJoinDjPost(entityId, profile.id, account!.userId);

                        if (result?.success) {
                            return NextResponse.json({
                                type: 4,
                                data: { content: "✅ Tu as rejoint le groupe ! Retrouve les détails sur le site.", flags: 64 },
                            });
                        }
                    } else if (action === "leave") {
                        const { internalLeaveDjPost } = await import("@/server/actions/dungeon-finder-actions");
                        result = await internalLeaveDjPost(entityId, profile.id);

                        if (result?.success) {
                            return NextResponse.json({
                                type: 4,
                                data: { content: "👋 Tu as quitté le groupe.", flags: 64 },
                            });
                        }
                    }
                }
            } else if (prefix === "svc") {
                if (action === "contact") {
                    const { internalContactService } = await import("@/server/actions/service-actions");
                    result = await internalContactService(entityId, "", account!.userId);

                    if (result?.success && result.data) {
                        const lines = [`📩 **Prestataire :** ${result.data.pseudo}`];
                        if (result.data.contactMethod) lines.push(`📌 **Contact :** ${result.data.contactMethod}`);
                        lines.push(`\n_Envoie-lui un MP Discord ou en jeu pour organiser le service !_`);
                        return NextResponse.json({
                            type: 4,
                            data: { content: lines.join("\n"), flags: 64 },
                        });
                    }
                } else if (action === "reply") {
                    const parts = custom_id.split(":");
                    const requesterUserId = parts[2];
                    const listingId = parts[3];

                    const listing = await db.serviceListing.findUnique({
                        where: { id: listingId },
                        select: { profile: { select: { userId: true } } }
                    });

                    if (!listing) {
                        return NextResponse.json({
                            type: 4,
                            data: { content: "❌ Ce service n'existe plus.", flags: 64 },
                        });
                    }

                    if (listing.profile.userId !== account!.userId) {
                        return NextResponse.json({
                            type: 4,
                            data: { content: "❌ Seul le prestataire de ce service peut répondre à la demande.", flags: 64 },
                        });
                    }

                    return NextResponse.json({
                        type: 9, // MODAL
                        data: {
                            custom_id: `svc:submit_reply:${requesterUserId}:${listingId}`,
                            title: "💬 Répondre au client",
                            components: [
                                {
                                    type: 1,
                                    components: [
                                        {
                                            type: 4,
                                            custom_id: "reply_message",
                                            label: "Votre message",
                                            style: 2, // Paragraph style
                                            placeholder: "Ex: Salut ! C'est d'accord pour ce soir 21h ! MP moi en jeu.",
                                            required: true,
                                            min_length: 5,
                                            max_length: 500,
                                        }
                                    ]
                                }
                            ]
                        }
                    });
                }
            } else if (prefix === "validate") {
                // =========================================================
                // VALIDATE / REJECT — Mission, Achievement, KamaDonation
                // custom_id: validate:{type}:{entityId}:{discordGuildId}
                //         or validate:{type}_reject:{entityId}:{discordGuildId}
                // =========================================================
                const isReject = action.endsWith("_reject");
                const entityType = isReject ? action.replace("_reject", "") : action; // "mission" | "achievement" | "kama"
                // custom_id format: validate:{type}[:_reject]:{entityId}:{discordGuildId}
                const parts = custom_id.split(":");
                const entityId = parts[2];
                const targetGuildId = parts[3];

                // Permission check (MISSIONS_VALIDATE required)
                const { internalCheckPermission } = await import("@/server/actions/user-actions");
                const { PERMISSIONS } = await import("@/lib/permissions");
                const isValidator = await internalCheckPermission(targetGuildId, member.user.id, PERMISSIONS.MISSIONS_OFFICER);
                if (!isValidator) {
                    return NextResponse.json({
                        type: 4,
                        data: { content: "🚫 Tu n'as pas la permission de valider des preuves.", flags: 64 },
                    });
                }

                // ACK immediately (defer update) — gives us 15 min to respond
                // We'll use type 7 (update message) after processing

                const { internalValidateMissionSubmission, internalReviewKamaDonation } =
                    await import("@/server/actions/discord-validation-actions");

                let resultMsg = "";
                const adminTag = `${member.user.username}`;

                if (entityType === "mission") {
                    const status = isReject ? "REJECTED" : "VALIDATED";
                    const res = await internalValidateMissionSubmission(entityId, status, targetGuildId, member.user.id);
                    if (res.success) {
                        resultMsg = isReject
                            ? `❌ Mission **refusée** par ${adminTag} — Membre: **${res.memberName}** — **${res.missionTitle}**`
                            : `✅ Mission **validée** par ${adminTag} — Membre: **${res.memberName}** — **${res.missionTitle}**`;
                    } else {
                        return NextResponse.json({ type: 4, data: { content: `❌ Erreur: ${res.error}`, flags: 64 } });
                    }
                } else if (entityType === "kama") {
                    const action_kama = isReject ? "REJECT" : "VALIDATE";
                    const res = await internalReviewKamaDonation(entityId, action_kama, targetGuildId, member.user.id);
                    if (res.success) {
                        const amountStr = res.amount?.toLocaleString("fr-FR") ?? "?";
                        resultMsg = isReject
                            ? `❌ Don **refusé** par ${adminTag} — Membre: **${res.memberName}** — ${amountStr} kamas`
                            : `✅ Don **validé** par ${adminTag} — Membre: **${res.memberName}** — ${amountStr} kamas`;
                    } else {
                        return NextResponse.json({ type: 4, data: { content: `❌ Erreur: ${res.error}`, flags: 64 } });
                    }
                } else if (entityType === "reactivation") {
                    // custom_id format: validate:reactivation:{action}:{profileId}:{guildId}
                    // where action is "approve" or "reject"
                    // The standard parts[2] = "approve"|"reject" (not the entity ID)
                    // For reactivation, entityId is at parts[3] and guildId at parts[4]
                    const reactivationProfileId = parts[3];
                    const reactivationGuildId = parts[4];
                    
                    const status = isReject ? "ARCHIVED" : "ACTIVE";
                    const { internalUpdateMemberProfileStatus } = await import("@/server/actions/user-actions");
                    
                    try {
                        await internalUpdateMemberProfileStatus(
                            reactivationProfileId, 
                            status, 
                            isReject ? "REACTIVATION_REJECTED" : "REACTIVATION_APPROVED",
                            undefined,
                            undefined,
                            member.user.id
                        );

                        // Also 🔔 send lifecycle notification if approved
                        if (!isReject) {
                            try {
                                const { reactivateProfileByAdmin } = await import("@/server/actions/lifecycle-actions");
                                await reactivateProfileByAdmin(reactivationGuildId, reactivationProfileId, "Approbation via Discord");
                            } catch (_) { /* notification is best-effort */ }
                        }

                        resultMsg = isReject
                            ? `❌ Demande de **réintégration refusée** par ${adminTag}`
                            : `✅ Demande de **réintégration validée** par ${adminTag}`;
                    } catch (err: any) {
                        return NextResponse.json({ type: 4, data: { content: `❌ Erreur: ${err.message}`, flags: 64 } });
                    }
                } else if (entityType === "achievement") {
                    const action_ach = isReject ? "REJECT" : "VALIDATE";
                    const { internalReviewAchievementSubmission } = await import("@/server/actions/discord-validation-actions");
                    const res = await internalReviewAchievementSubmission(entityId, action_ach, targetGuildId, member.user.id);
                    if (res.success) {
                        const pointsStr = res.points?.toLocaleString("fr-FR") ?? "?";
                        resultMsg = isReject
                            ? `❌ Succès **refusé** par ${adminTag} — Membre: **${res.memberName}** — ${pointsStr} pts`
                            : `✅ Succès **validé** par ${adminTag} — Membre: **${res.memberName}** — ${pointsStr} pts`;
                    } else {
                        return NextResponse.json({ type: 4, data: { content: `❌ Erreur: ${res.error}`, flags: 64 } });
                    }
                } else {
                    return NextResponse.json({ type: 4, data: { content: "Type de validation inconnu.", flags: 64 } });
                }

                // Réponse éphémère à l'admin (l'embed a été supprimé par internalValidate*)
                return NextResponse.json({
                    type: 4, // CHANNEL_MESSAGE_WITH_SOURCE (éphémère)
                    data: {
                        content: resultMsg,
                        flags: 64, // EPHEMERAL — visible uniquement par l'admin qui a cliqué
                        components: [],
                    },
                });

            } else if (prefix === "ticket") {
                // =========================================================
                // TICKET SYSTEM V2 — 2-step flow: Select Menu → Adapted Modal
                // =========================================================
                if (action === "open") {
                    // RATE LIMIT: 1 ticket every 10 seconds per user
                    const waitSec = getRateLimitRemaining(`ticket:${member.user.id}`, 1, 10_000);
                    if (waitSec > 0) {
                        return NextResponse.json({
                            type: 4,
                            data: { content: `⏳ Vous avez atteint la limite. Réessayez dans **${waitSec}s**.`, flags: 64 },
                        });
                    }
                    // Step 1: Send ephemeral message with category Select Menu
                    return NextResponse.json({
                        type: 4,
                        data: {
                            content: "🎫 **Ouvrir un ticket** — Choisissez la catégorie qui correspond à votre demande :",
                            flags: 64, // EPHEMERAL
                            components: [
                                {
                                    type: 1, // ACTION_ROW
                                    components: [
                                        {
                                            type: 3, // STRING_SELECT
                                            custom_id: `ticket:select:${entityId}`,
                                            placeholder: "Sélectionnez une catégorie...",
                                            min_values: 1,
                                            max_values: 1,
                                            options: [
                                                {
                                                    label: "Demande d'accès",
                                                    value: "ACCESS_REQUEST",
                                                    description: "Rejoindre SigilOS pour votre guilde",
                                                    emoji: { name: "🔑" },
                                                },
                                                {
                                                    label: "Signaler un bug",
                                                    value: "BUG_REPORT",
                                                    description: "Un problème sur le dashboard ou le bot",
                                                    emoji: { name: "🐛" },
                                                },
                                                {
                                                    label: "Proposer une feature",
                                                    value: "FEATURE_REQUEST",
                                                    description: "Suggérer une amélioration",
                                                    emoji: { name: "💡" },
                                                },
                                                {
                                                    label: "Autre / Question",
                                                    value: "OTHER",
                                                    description: "Question générale",
                                                    emoji: { name: "📩" },
                                                },
                                            ],
                                        },
                                    ],
                                },
                            ],
                        },
                    });
                } else if (action === "select") {
                    // Step 2: User selected a category from dropdown → open adapted modal
                    const selectedCategory = payload.data?.values?.[0] || "OTHER";

                    const categoryLabels: Record<string, string> = {
                        ACCESS_REQUEST: "🔑 Demande d'accès",
                        BUG_REPORT: "🐛 Signaler un bug",
                        FEATURE_REQUEST: "💡 Proposer une feature",
                        OTHER: "📩 Autre demande",
                    };

                    // [DUP-CHECK] Verify user doesn't have an active ticket in this category
                    const existingTicket = await db.supportTicket.findFirst({
                        where: {
                            creatorDiscordId: member.user.id,
                            category: selectedCategory as any,
                            status: { not: "CLOSED" },
                        },
                        select: { ticketNumber: true }
                    });

                    if (existingTicket) {
                        return NextResponse.json({
                            type: 4,
                            data: { 
                                content: `⚠️ Tu as déjà un ticket ouvert pour la catégorie **${categoryLabels[selectedCategory] || selectedCategory}**.\n\nFerme ton ticket **#${existingTicket.ticketNumber}** avant d'en ouvrir un nouveau.`, 
                                flags: 64 
                            },
                        });
                    }

                    // Build modal fields based on category
                    const modalComponents: any[] = [];

                    if (selectedCategory === "ACCESS_REQUEST") {
                        // Discord modals allow max 5 action rows
                        modalComponents.push(
                            {
                                type: 1,
                                components: [{
                                    type: 4, custom_id: "discord_guild_id",
                                    label: "ID de votre serveur Discord",
                                    style: 1, placeholder: "Ex: 1234567890123456789 (17-20 chiffres)",
                                    required: true, min_length: 17, max_length: 20,
                                }],
                            },
                            {
                                type: 1,
                                components: [{
                                    type: 4, custom_id: "guild_name",
                                    label: "Nom de votre guilde Dofus",
                                    style: 1, placeholder: "Uniquement des lettres (Ex: Les Gardiens)",
                                    required: true, min_length: 2, max_length: 50,
                                }],
                            },
                            {
                                type: 1,
                                components: [{
                                    type: 4, custom_id: "pseudo_dofus",
                                    label: "Votre pseudo Dofus",
                                    style: 1, placeholder: "Uniquement des lettres (Ex: Klyx)",
                                    required: true, min_length: 2, max_length: 30,
                                }],
                            },
                            {
                                type: 1,
                                components: [{
                                    type: 4, custom_id: "member_count",
                                    label: "Nombre de membres",
                                    style: 1, placeholder: "Entre 1 et 500 (chiffres uniquement)",
                                    required: true, min_length: 1, max_length: 3,
                                }],
                            },
                            {
                                type: 1,
                                components: [{
                                    type: 4, custom_id: "description",
                                    label: "Pourquoi souhaitez-vous utiliser SigilOS ?",
                                    style: 2, placeholder: "Décrivez brièvement votre guilde et vos besoins...",
                                    required: true, min_length: 10, max_length: 1000,
                                }],
                            },
                        );
                    } else if (selectedCategory === "BUG_REPORT") {
                        modalComponents.push(
                            {
                                type: 1,
                                components: [{
                                    type: 4, custom_id: "subject",
                                    label: "Description courte du bug",
                                    style: 1, placeholder: "Ex: Les missions ne s'affichent plus",
                                    required: true, min_length: 5, max_length: 100,
                                }],
                            },
                            {
                                type: 1,
                                components: [{
                                    type: 4, custom_id: "page",
                                    label: "Page / Fonctionnalité concernée",
                                    style: 1, placeholder: "Ex: Dashboard > Missions, Bot Discord, Landing page...",
                                    required: true, min_length: 3, max_length: 100,
                                }],
                            },
                            {
                                type: 1,
                                components: [{
                                    type: 4, custom_id: "description",
                                    label: "Étapes pour reproduire + détails",
                                    style: 2, placeholder: "1. Je clique sur...\n2. Je vois...\n3. Comportement attendu vs réel",
                                    required: true, min_length: 10, max_length: 1500,
                                }],
                            },
                        );
                    } else if (selectedCategory === "FEATURE_REQUEST") {
                        modalComponents.push(
                            {
                                type: 1,
                                components: [{
                                    type: 4, custom_id: "subject",
                                    label: "Titre de la fonctionnalité",
                                    style: 1, placeholder: "Ex: Système de classement PvP",
                                    required: true, min_length: 5, max_length: 100,
                                }],
                            },
                            {
                                type: 1,
                                components: [{
                                    type: 4, custom_id: "description",
                                    label: "Description détaillée de votre idée",
                                    style: 2, placeholder: "Décrivez la fonctionnalité, son utilité, et comment vous l'imaginez...",
                                    required: true, min_length: 10, max_length: 1500,
                                }],
                            },
                        );
                    } else {
                        // OTHER
                        modalComponents.push(
                            {
                                type: 1,
                                components: [{
                                    type: 4, custom_id: "subject",
                                    label: "Sujet",
                                    style: 1, placeholder: "De quoi s'agit-il ?",
                                    required: true, min_length: 3, max_length: 100,
                                }],
                            },
                            {
                                type: 1,
                                components: [{
                                    type: 4, custom_id: "description",
                                    label: "Votre message",
                                    style: 2, placeholder: "Détaillez votre demande...",
                                    required: true, min_length: 10, max_length: 1500,
                                }],
                            },
                        );
                    }

                    const categoryTitles: Record<string, string> = {
                        ACCESS_REQUEST: "🔑 Demande d'accès",
                        BUG_REPORT: "🐛 Signaler un bug",
                        FEATURE_REQUEST: "💡 Proposer une feature",
                        OTHER: "📩 Autre demande",
                    };

                    return NextResponse.json({
                        type: 9, // MODAL
                        data: {
                            custom_id: `ticket:create:${entityId}:${selectedCategory}`,
                            title: categoryTitles[selectedCategory] || "📩 Ticket",
                            components: modalComponents,
                        },
                    });
                } else if (action === "close") {
                    // ACK immediately (Deferred update)
                    const response = NextResponse.json({ type: 6 }); 

                    // Background heavy lifting
                    const { closeSupportTicket } = await import("@/server/actions/ticket-actions");
                    closeSupportTicket(
                        entityId,
                        member.user.id,
                        member.user.global_name || member.user.username
                    ).catch(err => console.error("Discord Close Error:", err));

                    return response;
                }
            } else {
                return NextResponse.json({ type: 4, data: { content: "Interaction inconnue", flags: 64 } });
            }

            if (result?.success) {
                // DJ interactions: give ephemeral feedback
                if (prefix === "dj") {
                    const label = action === "join" ? "✅ Tu as rejoint le groupe !" : "👋 Tu as quitté le groupe.";
                    return NextResponse.json({
                        type: 4,
                        data: { content: label, flags: 64 },
                    });
                }
                return NextResponse.json({ type: 6 }); // ACK silencieux (others)
            } else {
                return NextResponse.json({
                    type: 4,
                    data: { content: `❌ ${result?.error || "Erreur inconnue"}`, flags: 64 },
                });
            }
        }

        // 3. Handle Modal Submit (Songes candidature form)
        if (payload.type === 5) {
            const { custom_id, components } = payload.data;
            const { member, guild_id } = payload;

            const [prefix, action, entityId] = custom_id.split(":");

            // Rate limit: 5 modal submits per 5min per discord user
            if (!checkRateLimit(`modal:${member.user.id}`, 5, 5 * 60_000)) {
                return NextResponse.json({
                    type: 4,
                    data: { content: "⏳ Trop de candidatures. Réessaie dans quelques minutes.", flags: 64 },
                });
            }

            if (prefix === "songes" && action === "apply") {
                const account = await findUserByDiscordId(member.user.id);
                if (!account) {
                    return NextResponse.json({
                        type: 4,
                        data: { content: "❌ Tu dois t'être connecté au moins une fois sur le site.", flags: 64 },
                    });
                }

                // RBAC check for modal submits (same gate as button clicks)
                const { internalCheckPermission } = await import("@/server/actions/user-actions");
                const { PERMISSIONS } = await import("@/lib/permissions");
                const canJoinSonges = await internalCheckPermission(guild_id, member.user.id, PERMISSIONS.GAME_OPERATIONS);
                if (!canJoinSonges) {
                    return NextResponse.json({
                        type: 4,
                        data: {
                            content: "🚫 Tes rôles Discord ne t'autorisent pas à postuler aux Songes. Contacte un admin de ta guilde.",
                            flags: 64,
                        },
                    });
                }

                // Extract modal fields
                let classe = "";
                let message = "";

                for (const row of components) {
                    for (const comp of row.components) {
                        if (comp.custom_id === "classe") classe = comp.value?.trim() || "";
                        if (comp.custom_id === "message") message = comp.value?.trim() || "";
                    }
                }

                // Validate class - try to match against known classes (case-insensitive)
                const matchedClass = VALID_CLASSES.find(
                    c => c.toLowerCase() === classe.toLowerCase()
                );

                if (!matchedClass) {
                    const classesList = VALID_CLASSES.join(", ");
                    return NextResponse.json({
                        type: 4,
                        data: {
                            content: `❌ Classe « ${classe} » non reconnue.\n\n**Classes disponibles :** ${classesList}`,
                            flags: 64,
                        },
                    });
                }

                // Create candidature via service
                const { processRunJoin } = await import("@/server/songes-service");
                const result = await processRunJoin(guild_id, entityId, account.userId, matchedClass, message);

                if (result?.success) {
                    return NextResponse.json({
                        type: 4,
                        data: {
                            content: `✅ Candidature envoyée ! Classe: **${matchedClass}**${message ? `\nMessage: *${message}*` : ""}\n\nLe leader de la run sera notifié.`,
                            flags: 64,
                        },
                    });
                } else {
                    return NextResponse.json({
                        type: 4,
                        data: { content: `❌ ${result?.error || "Erreur inconnue"}`, flags: 64 },
                    });
                }
            } else if (prefix === "svc" && action === "submit_reply") {
                const account = await findUserByDiscordId(member.user.id);
                if (!account) {
                    return NextResponse.json({
                        type: 4,
                        data: { content: "❌ Tu dois t'être connecté au moins une fois sur le site.", flags: 64 },
                    });
                }

                const parts = custom_id.split(":");
                const requesterUserId = parts[2];
                const listingId = parts[3];

                let replyMessage = "";
                for (const row of components) {
                    for (const comp of row.components) {
                        if (comp.custom_id === "reply_message") {
                            replyMessage = comp.value?.trim() || "";
                        }
                    }
                }

                const { replyToServiceRequestAction } = await import("@/server/actions/service-actions");
                const res = await replyToServiceRequestAction(guild_id, requesterUserId, listingId, replyMessage, account.userId);

                if (res.success) {
                    return NextResponse.json({
                        type: 4,
                        data: { content: "✅ Votre réponse a été envoyée au client !", flags: 64 },
                    });
                } else {
                    return NextResponse.json({
                        type: 4,
                        data: { content: `❌ ${res.error || "Impossible d'envoyer la réponse."}`, flags: 64 },
                    });
                }
            }

            // =========================================================
            // TICKET CREATION V2 (from category-adapted modal submit)
            // custom_id format: ticket:create:{guildId}:{category}
            // =========================================================
            if (prefix === "ticket" && action === "create") {
                // V2: Category is in the 4th part of custom_id
                const parts = custom_id.split(":");
                const ticketGuildId = parts[2] || guild_id;
                const ticketCategory = (parts[3] || "OTHER") as "ACCESS_REQUEST" | "BUG_REPORT" | "FEATURE_REQUEST" | "OTHER";

                // Extract all possible fields from modal
                const fields: Record<string, string> = {};
                for (const row of components) {
                    for (const comp of row.components) {
                        if (comp.custom_id && comp.value) {
                            fields[comp.custom_id] = comp.value.trim();
                        }
                    }
                }

                // Build subject and description based on category
                let targetMeta: any = {};
                let subject = "";
                let description = "";

                if (ticketCategory === "ACCESS_REQUEST") {
                    // 1. Validate Discord Guild ID
                    const discordGuildIdInput = fields.discord_guild_id || "";
                    if (!/^\d{17,20}$/.test(discordGuildIdInput)) {
                        return NextResponse.json({
                            type: 4,
                            data: {
                                content: "❌ L'ID de serveur Discord est invalide (17-20 chiffres).\n💡 Clic droit sur votre serveur -> Copier l'identifiant.",
                                flags: 64,
                            },
                        });
                    }

                    // 2. Validate Names (STRICT: Letters and spaces only)
                    const nameRegex = /^[a-zA-ZÀ-ÿ\s'-]+$/; // Added hyphen and apostrophe
                    const guildName = fields.guild_name || "";
                    const pseudoDofus = fields.pseudo_dofus || "";

                    if (!nameRegex.test(guildName)) {
                        return NextResponse.json({
                            type: 4,
                            data: { content: "❌ Le nom de guilde ne doit contenir que des lettres (pas de chiffres ou caractères spéciaux).", flags: 64 },
                        });
                    }
                    if (!nameRegex.test(pseudoDofus)) {
                        return NextResponse.json({
                            type: 4,
                            data: { content: "❌ Le pseudo Dofus ne doit contenir que des lettres (pas de chiffres ou caractères spéciaux).", flags: 64 },
                        });
                    }

                    // 3. Validate Member Count
                    const memberCountRaw = fields.member_count || "";
                    const count = parseInt(memberCountRaw, 10);
                    if (isNaN(count) || count < 1 || count > 500) {
                        return NextResponse.json({
                            type: 4,
                            data: { content: "❌ Le nombre de membres doit être un chiffre entre 1 et 500.", flags: 64 },
                        });
                    }

                    targetMeta = {
                        targetGuildId: discordGuildIdInput,
                        targetGuildName: guildName,
                        targetGuildMemberCount: count,
                    };

                    subject = `Accès — ${guildName} (${pseudoDofus})`;
                    description = [
                        `🔹 **Serveur Discord :** \`${discordGuildIdInput}\``,
                        `🏰 **Guilde :** ${guildName}`,
                        `👤 **Leader :** ${pseudoDofus}`,
                        `👥 **Membres :** ${count}`,
                        "",
                        `📝 **Message :**`,
                        fields.description || "Aucune description",
                    ].join("\n");
                } else if (ticketCategory === "BUG_REPORT") {
                    subject = fields.subject || "Bug sans titre";
                    description = [
                        `📍 **Page/Feature :** ${fields.page || "Non précisé"}`,
                        "",
                        `🔍 **Détails :**`,
                        fields.description || "Aucune description",
                    ].join("\n");
                } else {
                    subject = fields.subject || "Ticket sans titre";
                    description = fields.description || "Aucune description";
                }

                // Get channel for thread creation
                const channelId = payload.channel_id || payload.channel?.id;
                if (!channelId) {
                    return NextResponse.json({
                        type: 4,
                        data: { content: "❌ Impossible de déterminer le salon.", flags: 64 },
                    });
                }

                const { createSupportTicket } = await import("@/server/actions/ticket-actions");
                const ticketResult = await createSupportTicket({
                    channelId,
                    discordGuildId: ticketGuildId,
                    category: ticketCategory,
                    subject,
                    description,
                    creatorDiscordId: member.user.id,
                    creatorDiscordName: member.user.global_name || member.user.username,
                    ...targetMeta,
                });

                if (ticketResult.success) {
                    // AUTO-PROVISION: For ACCESS_REQUEST, auto-create AllowedGuild as PENDING
                    if (ticketCategory === "ACCESS_REQUEST" && fields.discord_guild_id) {
                        try {
                            const existingGuild = await db.allowedGuild.findUnique({
                                where: { discordGuildId: fields.discord_guild_id },
                            });
                            if (!existingGuild) {
                                await db.allowedGuild.create({
                                    data: {
                                        discordGuildId: fields.discord_guild_id,
                                        name: fields.guild_name || null,
                                        tier: "PENDING",
                                        isActive: false,
                                        addedBy: member.user.id,
                                        notes: `[AUTO] Ticket #${ticketResult.ticketNumber} — ${fields.pseudo_dofus || "?"} — En attente d'approbation`,
                                    },
                                });
                            }
                        } catch (e) {
                            // Non-blocking: if auto-provision fails, ticket is still created
                            console.error("[Tickets] Auto-provision AllowedGuild failed:", e);
                        }
                    }

                    return NextResponse.json({
                        type: 4,
                        data: {
                            content: `✅ Ticket **#${ticketResult.ticketNumber}** créé ! Un fil privé a été ouvert — regarde dans tes fils.`,
                            flags: 64,
                        },
                    });
                } else {
                    return NextResponse.json({
                        type: 4,
                        data: { content: `❌ ${ticketResult.error}`, flags: 64 },
                    });
                }
            }

            return NextResponse.json({ type: 4, data: { content: "Modal inconnu", flags: 64 } });
        }

        // 4. Handle Slash Command (/status)
        if (payload.type === 2) {
            const { name } = payload.data;

            if (name === "status") {
                try {
                    const baseUrl = getAppBaseUrl();
                    const healthRes = await fetch(`${baseUrl}/api/health`);
                    const health = await healthRes.json();

                    const statusEmoji = health.status === "healthy" ? "🟢" : health.status === "degraded" ? "🟡" : "🔴";
                    const dbStatus = health.services.database.status === "up" ? "🟢 Opérationnel" : "🔴 Hors ligne";
                    const redisStatus = health.services.redis.status === "up" ? "🟢 Opérationnel" :
                        health.services.redis.status === "not_configured" ? "⚪ Non configuré" : "🔴 Hors ligne";

                    return NextResponse.json({
                        type: 4,
                        data: {
                            embeds: [{
                                title: "🏰 SigilOS Status",
                                color: health.status === "healthy" ? 0x10b981 : health.status === "degraded" ? 0xf59e0b : 0xef4444,
                                fields: [
                                    { name: "État Global", value: `${statusEmoji} ${health.status === "healthy" ? "Opérationnel" : health.status === "degraded" ? "Dégradé" : "Critique"}`, inline: false },
                                    { name: "Base de données", value: `${dbStatus}${health.services.database.latency ? ` (${health.services.database.latency}ms)` : ""}`, inline: true },
                                    { name: "Cache Redis", value: `${redisStatus}${health.services.redis.latency ? ` (${health.services.redis.latency}ms)` : ""}`, inline: true },
                                ],
                                footer: { text: `Version: ${health.version || "unknown"}` },
                                timestamp: new Date().toISOString()
                            }]
                        }
                    });
                } catch (error) {
                    console.error("[Discord Status Command] Error:", error);
                    return NextResponse.json({
                        type: 4,
                        data: { content: "❌ Impossible de récupérer le statut.", flags: 64 }
                    });
                }
            }

            return NextResponse.json({ type: 4, data: { content: "Commande inconnue", flags: 64 } });
        }

        return NextResponse.json({ error: "Unknown type" }, { status: 400 });

    } catch (error) {
        console.error("[Discord Interaction] Error:", error);
        return NextResponse.json({ error: "Internal error" }, { status: 500 });
    }
}

/**
 * Discord Webhook Handler
 * Handles Discord Gateway Events for Guild & Member Lifecycle Management
 * 
 * Events handled:
 * - GUILD_CREATE: Bot added to server → Auto-whitelist
 * - GUILD_DELETE: Bot removed from server → Soft-delete guild
 * - GUILD_MEMBER_REMOVE: User left or was kicked → Archive profile
 * - GUILD_BAN_ADD: User was banned → Anonymize profile
 * - MESSAGE_CREATE: New message in blacklist channel → Add blacklist entry
 * - MESSAGE_UPDATE: Message edited in blacklist channel → Update blacklist entry
 * - MESSAGE_DELETE: Message deleted in blacklist channel → Remove blacklist entry
 * 
 * Security:
 * - Ed25519 signature verification required
 * - All actions logged to AuditLog for transparency
 */

import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/prisma";
import { Prisma } from "@prisma/client";

// Discord uses Ed25519 for webhook signatures
// We'll use the Web Crypto API for verification
async function verifyDiscordSignature(
    request: NextRequest,
    body: string
): Promise<boolean> {
    const signature = request.headers.get("X-Signature-Ed25519");
    const timestamp = request.headers.get("X-Signature-Timestamp");
    const publicKey = process.env.DISCORD_APPLICATION_PUBLIC_KEY || process.env.DISCORD_PUBLIC_KEY;

    if (!signature || !timestamp || !publicKey) {
        console.warn("[Discord Webhook] Missing signature headers or public key");
        return false;
    }

    try {
        // Import the public key
        const keyData = hexToUint8Array(publicKey);
        const key = await crypto.subtle.importKey(
            "raw",
            keyData.buffer as ArrayBuffer,
            { name: "Ed25519" },
            false,
            ["verify"]
        );

        // Verify the signature
        const message = new TextEncoder().encode(timestamp + body);
        const sig = hexToUint8Array(signature);

        return await crypto.subtle.verify("Ed25519", key, sig.buffer as ArrayBuffer, message);
    } catch (error) {
        console.error("[Discord Webhook] Signature verification error:", error);
        return false;
    }
}

function hexToUint8Array(hex: string): Uint8Array {
    const matches = hex.match(/.{1,2}/g);
    if (!matches) return new Uint8Array();
    return new Uint8Array(matches.map(byte => parseInt(byte, 16)));
}

// Auto-whitelist a new guild when bot is added
async function handleGuildCreate(guildId: string, guildName: string) {
    // Check if already in AllowedGuild
    const existing = await db.allowedGuild.findUnique({
        where: { discordGuildId: guildId }
    });

    if (existing) {
        return;
    }

    // Auto-add to whitelist with BETA tier
    await db.allowedGuild.create({
        data: {
            discordGuildId: guildId,
            name: guildName,
            tier: "BETA",
            isActive: true,
            addedBy: "SYSTEM", // System-generated
            notes: "Auto-added via webhook (bot invited)"
        }
    });

    // --- NEW: Send Welcome Embed to the Guild ---
    try {
        const { sendGuildWelcomeEmbed, fetchGuild } = await import("@/server/discord");
        const guild = await fetchGuild(guildId) as any;
        
        // Try system channel first, then general-ish channels
        const targetChannelId = guild.system_channel_id;
        
        if (targetChannelId) {
            await sendGuildWelcomeEmbed(targetChannelId, guildName);
        } else {
            // Fallback: Find the first text channel the bot can write to
            const { fetchGuildChannels } = await import("@/server/discord");
            const channels = await fetchGuildChannels(guildId);
            const firstTextChannel = channels.find(c => c.type === 0); // 0 = GUILD_TEXT
            if (firstTextChannel) {
                await sendGuildWelcomeEmbed(firstTextChannel.id, guildName);
            }
        }
    } catch (err) {
        console.error("[handleGuildCreate] Failed to send welcome embed:", err);
    }
}

// Soft-delete a guild when bot is removed
async function handleGuildDelete(guildId: string) {
    const guild = await db.guildConfig.findUnique({
        where: { discordGuildId: guildId },
        select: { id: true, name: true }
    });

    if (!guild) {
        return;
    }

    // Soft-delete the guild (same logic as god-lifecycle-actions)
    const scheduledDeletion = new Date();
    scheduledDeletion.setDate(scheduledDeletion.getDate() + 30); // 30 days grace period

    await db.guildConfig.update({
        where: { id: guild.id },
        data: {
            isActive: false,
            deletedAt: new Date(),
            deletionReason: "BOT_REMOVED",
            scheduledDeletion
        }
    });

    // Soft-delete all profiles in this guild
    await db.userProfile.updateMany({
        where: { guildId: guild.id },
        data: {
            status: "ARCHIVED",
            archivedAt: new Date(),
            archiveReason: "GUILD_DELETED",
            scheduledDeletion
        }
    });

    // Log to audit trail
    await db.auditLog.create({
        data: {
            guildId: guild.id,
            actorUserId: "SYSTEM",
            actorName: "Discord Webhook",
            action: "WEBHOOK_GUILD_DELETE",
            targetType: "GUILD",
            targetId: guild.id,
            oldValue: { isActive: true },
            newValue: { isActive: false, deletionReason: "BOT_REMOVED" },
            metadata: { discordGuildId: guildId }
        }
    });
}

// Handle new member arrival
async function handleMemberAdd(guildId: string, memberData: any) {
    const guild = await db.guildConfig.findUnique({
        where: { discordGuildId: guildId },
        select: { id: true, name: true }
    });

    if (!guild) return;

    const userId = memberData.user.id;
    const pseudo = memberData.nick || memberData.user.global_name || memberData.user.username;

    // Log the arrival
    await db.auditLog.create({
        data: {
            guildId: guild.id,
            actorUserId: "SYSTEM",
            actorName: "Discord Gateway Bot",
            action: "WEBHOOK_MEMBER_ADD",
            targetType: "PROFILE",
            targetId: userId,
            metadata: { 
                discordUserId: userId,
                description: pseudo,
                username: memberData.user.username,
                roles: memberData.roles,
                joinedAt: memberData.joined_at
            }
        }
    });

    // --- PRO-ACTIVE SYNC ---
    // If the user already has an account, we could auto-create/reactivate their profile here.
    const account = await db.account.findFirst({
        where: { provider: "discord", providerAccountId: userId },
        select: { userId: true }
    });

    if (account) {
        const profile = await db.userProfile.findUnique({
            where: { userId_guildId: { userId: account.userId, guildId: guild.id } }
        });

        if (profile && profile.status === "ARCHIVED") {
            await db.userProfile.update({
                where: { id: profile.id },
                data: { 
                    status: "ACTIVE", 
                    archivedAt: null, 
                    archiveReason: null, 
                    scheduledDeletion: null,
                    discordNickname: memberData.nick || null
                }
            });
            
            await db.auditLog.create({
                data: {
                    guildId: guild.id,
                    actorUserId: "SYSTEM",
                    actorName: "Discord Gateway Bot",
                    action: "PROFILE_REACTIVATED",
                    targetType: "PROFILE",
                    targetId: userId,
                    metadata: { description: pseudo, reason: "WEBHOOK_REJOIN" }
                }
            });
        }
    }
}

// Handle member profile updates (nickname, roles)
