"use client";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { 
    Trophy, 
    Crown,
    Star,
    Flame
} from "lucide-react";
import { LadderEntry } from "@/server/actions/ladder-actions";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { cn } from "@/lib/utils";

export function TopActivityWidget({ 
    entries = []
}: { 
    entries?: LadderEntry[];
}) {
    // Only take top 3
    const top3 = entries.slice(0, 3);
    const podiumOrder = top3.length === 3 ? [top3[1], top3[0], top3[2]] : top3;

    if (entries.length === 0) return null;

    return (
        <Card className="glass-premium border-white/5 relative overflow-hidden group">
            <CardHeader className="pb-2 pt-6">
                <CardTitle className="text-[10px] font-black uppercase tracking-[0.3em] text-yellow-500 flex items-center gap-2">
                    <Trophy className="w-3 h-3" />
                    Top Activité Missions
                </CardTitle>
            </CardHeader>
            
            <CardContent className="pt-4 pb-8">
                <div className="flex items-end justify-center gap-2 md:gap-4 h-48">
                    {podiumOrder.map((entry, idx) => {
                        if (!entry) return null;
                        
                        // Original rank (idx in podiumOrder is not rank)
                        const rank = entry.rank;
                        const isFirst = rank === 1;
                        const isSecond = rank === 2;
                        
                        const height = isFirst ? "h-40" : isSecond ? "h-32" : "h-28";
                        const avatarSize = isFirst ? "h-16 w-16" : "h-12 w-12";
                        const name = entry.pseudoDofus || entry.discordNickname || "Membre";

                        return (
                            <div key={entry.profileId} className={cn("flex flex-col items-center gap-3 relative", height)}>
                                <div className="relative group/avatar">
                                    {isFirst && <Crown className="w-6 h-6 text-yellow-400 absolute -top-5 left-1/2 -translate-x-1/2 drop-shadow-[0_0_10px_rgba(250,204,21,0.5)] animate-bounce" />}
                                    
                                    <Avatar className={cn(avatarSize, "ring-2 ring-white/10 group-hover/avatar:ring-yellow-500/50 transition-all duration-500")}>
                                        <AvatarImage src={entry.discordImage ?? undefined} />
                                        <AvatarFallback className="text-sm font-black text-white bg-zinc-800">{name[0]}</AvatarFallback>
                                    </Avatar>
                                    
                                    <div className={cn(
                                        "absolute -bottom-2 left-1/2 -translate-x-1/2 px-2 py-0.5 rounded-full text-[8px] font-black border border-white/10 shadow-xl",
                                        isFirst ? "bg-yellow-500 text-black" : "bg-zinc-800 text-white"
                                    )}>
                                        #{rank}
                                    </div>
                                </div>
                                
                                <div className="text-center w-full max-w-[80px]">
                                    <p className="text-[10px] font-black text-white truncate uppercase italic">{name}</p>
                                    <p className="text-[9px] font-bold text-emerald-400">{entry.value} pts</p>
                                </div>

                                {/* Base structure */}
                                <div className={cn(
                                    "absolute bottom-0 w-full rounded-t-xl bg-gradient-to-t border-t border-x border-white/5 -z-10",
                                    isFirst ? "from-yellow-500/10 to-yellow-500/20 h-16" : "from-white/5 to-white/10 h-10"
                                )} />
                            </div>
                        );
                    })}
                </div>
            </CardContent>
            
            <div className="absolute -bottom-8 -left-8 opacity-[0.03] group-hover:opacity-[0.06] transition-opacity">
                <Flame className="w-32 h-32 text-yellow-500" />
            </div>
            <div className="absolute top-2 right-2 opacity-[0.05]">
                <Star className="w-4 h-4 text-emerald-500 animate-pulse" />
            </div>
        </Card>
    );
}

"use client";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Calendar, Users, MapPin, Clock, ChevronRight, Swords, Infinity, Flame, Target, Star, Coffee, RefreshCw } from "lucide-react";
import Link from "next/link";
import { format, formatDistanceToNow, isToday, isTomorrow, isThisWeek } from "date-fns";
import { fr } from "date-fns/locale";
import { cn } from "@/lib/utils";

interface UpcomingEvent {
    id: string;
    title: string;
    type: string;
    startDate: Date;
    endDate: Date;
    location?: string | null;
    maxParticipants?: number | null;
    _count?: { participants: number };
}

const EVENT_CONFIG: Record<string, { label: string; icon: any; color: string; bg: string; border: string }> = {
    RAID_OFFICIAL:    { label: "Raid Officiel",     icon: Swords,    color: "text-red-400",     bg: "bg-red-500/10",     border: "border-red-500/20" },
    EVENT_GUILD:      { label: "Événement",         icon: Star,      color: "text-yellow-400",  bg: "bg-yellow-500/10",  border: "border-yellow-500/20" },
    SESSION_MISSIONS: { label: "Missions",          icon: Target,    color: "text-blue-400",    bg: "bg-blue-500/10",    border: "border-blue-500/20" },
    SORTIE_FARM:      { label: "Sortie Farm",       icon: Flame,     color: "text-orange-400",  bg: "bg-orange-500/10",  border: "border-orange-500/20" },
    SONGES_RUN:       { label: "Songes",            icon: Infinity,  color: "text-purple-400",  bg: "bg-purple-500/10",  border: "border-purple-500/20" },
    DUNGEON_FARM:     { label: "Donjons",           icon: Flame,     color: "text-amber-400",   bg: "bg-amber-500/10",   border: "border-amber-500/20" },
    SOCIAL:           { label: "Social",            icon: Coffee,    color: "text-pink-400",    bg: "bg-pink-500/10",    border: "border-pink-500/20" },
    GUILD_MISSION:    { label: "Mission Guilde",    icon: Target,    color: "text-teal-400",    bg: "bg-teal-500/10",    border: "border-teal-500/20" },
    ALMANAX_BONUS:    { label: "Almanax",           icon: Star,      color: "text-emerald-400", bg: "bg-emerald-500/10", border: "border-emerald-500/20" },
    OFFICIAL_RESET:   { label: "Reset Officiel",    icon: RefreshCw, color: "text-zinc-400",    bg: "bg-zinc-800/50",    border: "border-zinc-700/30" },
    OTHERS:           { label: "Autre",             icon: Calendar,  color: "text-zinc-400",    bg: "bg-zinc-800/50",    border: "border-zinc-700/30" },
};

function getWhenLabel(date: Date): { label: string; urgent: boolean } {
    const d = new Date(date);
    if (isToday(d))     return { label: "Aujourd'hui", urgent: true };
    if (isTomorrow(d))  return { label: "Demain",      urgent: false };
    if (isThisWeek(d, { locale: fr }))
        return { label: format(d, "EEEE", { locale: fr }), urgent: false };
    return { label: format(d, "dd MMM", { locale: fr }), urgent: false };
}

export function UpcomingEventsWidget({
    guildId,
    events = []
}: {
    guildId: string;
    events: UpcomingEvent[];
}) {
    return (
        <Card className="glass-premium border-white/5 flex flex-col h-full overflow-hidden">
            <CardHeader className="pb-4 pt-6 px-6">
                <div className="flex items-center justify-between">
                    <CardTitle className="text-[10px] font-black uppercase tracking-[0.3em] text-emerald-400 flex items-center gap-2">
                        <Calendar className="w-3.5 h-3.5" />
                        Agenda de Guilde
                        {events.length > 0 && (
                            <span className="ml-1 px-1.5 py-0.5 rounded-md bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 text-[8px] font-black tabular-nums">
                                {events.length}
                            </span>
                        )}
                    </CardTitle>
                    <Link
                        href={`/dashboard/${guildId}/calendar`}
                        className="text-[8px] font-black text-zinc-600 hover:text-emerald-400 uppercase tracking-widest border border-white/5 px-2 py-1 rounded-md transition-all hover:border-emerald-500/20"
                    >
                        Calendrier →
                    </Link>
                </div>
            </CardHeader>

            <CardContent className="px-4 pb-4 flex-1 flex flex-col gap-2">
                {events.length > 0 ? (
                    <>
                        {events.map((event) => {
                            const cfg = EVENT_CONFIG[event.type] ?? EVENT_CONFIG.OTHERS;
                            const Icon = cfg.icon;
                            const when = getWhenLabel(new Date(event.startDate));
                            const participants = event._count?.participants ?? 0;
                            const maxParts = event.maxParticipants;
                            const fillPct = maxParts ? Math.min(100, (participants / maxParts) * 100) : null;
                            const isFull = maxParts ? participants >= maxParts : false;

                            return (
                                <Link
                                    key={event.id}
                                    href={`/dashboard/${guildId}/calendar?event=${event.id}`}
                                    className="group flex items-start gap-3 p-3 rounded-2xl bg-zinc-950/40 hover:bg-zinc-900/60 border border-white/5 hover:border-emerald-500/20 transition-all duration-200 hover:scale-[1.01]"
                                >
                                    {/* Type Icon */}
                                    <div className={cn("shrink-0 h-10 w-10 rounded-xl flex items-center justify-center border", cfg.bg, cfg.border)}>
                                        <Icon className={cn("w-4.5 h-4.5", cfg.color)} style={{ width: "1.125rem", height: "1.125rem" }} />
                                    </div>

                                    {/* Content */}
                                    <div className="flex-1 min-w-0 space-y-1">
                                        <div className="flex items-center gap-2 flex-wrap">
                                            <span className={cn(
                                                "text-[8px] font-black uppercase px-1.5 py-0.5 rounded shrink-0",
                                                when.urgent
                                                    ? "bg-emerald-500 text-black"
                                                    : "bg-zinc-800 text-zinc-400"
                                            )}>
                                                {when.label}
                                            </span>
                                            <span className={cn("text-[9px] font-black uppercase px-1.5 py-0.5 rounded border shrink-0", cfg.bg, cfg.border, cfg.color)}>
                                                {cfg.label}
                                            </span>
                                            {isFull && (
                                                <span className="text-[8px] font-black uppercase px-1.5 py-0.5 rounded bg-red-950/40 border border-red-500/20 text-red-400 shrink-0">
                                                    Complet
                                                </span>
                                            )}
                                        </div>

                                        <p className="text-[11px] font-black text-white/90 group-hover:text-emerald-400 transition-colors uppercase italic truncate">
                                            {event.title}
                                        </p>

                                        <div className="flex items-center gap-3 text-[9px] text-zinc-500 font-bold uppercase tracking-tighter">
                                            <span className="flex items-center gap-1">
                                                <Clock className="w-3 h-3" />
                                                {format(new Date(event.startDate), "HH:mm")}
                                            </span>
                                            {event.location && (
                                                <span className="flex items-center gap-1 truncate max-w-[100px]">
                                                    <MapPin className="w-3 h-3 shrink-0" />
                                                    {event.location}
                                                </span>
                                            )}
                                            <span className="flex items-center gap-1">
                                                <Users className="w-3 h-3" />
                                                {participants}{maxParts ? `/${maxParts}` : ""}
                                            </span>
                                        </div>

                                        {/* Participation bar */}
                                        {fillPct !== null && (
                                            <div className="h-1 bg-zinc-900 rounded-full overflow-hidden w-full mt-1">
                                                <div
                                                    className={cn(
                                                        "h-full rounded-full transition-all duration-500",
                                                        fillPct >= 100
                                                            ? "bg-red-500"
                                                            : fillPct >= 75
                                                                ? "bg-orange-500"
                                                                : "bg-emerald-500"
                                                    )}
                                                    style={{ width: `${fillPct}%` }}
                                                />
                                            </div>
                                        )}
                                    </div>

                                    <ChevronRight className="w-4 h-4 text-zinc-700 group-hover:text-emerald-400 transition-colors shrink-0 mt-2" />
                                </Link>
                            );
                        })}

                        <Link
                            href={`/dashboard/${guildId}/calendar`}
                            className="flex items-center justify-center gap-2 text-[9px] font-black text-zinc-700 hover:text-emerald-400 uppercase tracking-widest pt-2 transition-colors border-t border-white/5 mt-auto"
                        >
                            Voir tout le calendrier
                        </Link>
                    </>
                ) : (
                    <div className="flex-1 flex flex-col items-center justify-center py-10 text-center space-y-4 border border-dashed border-white/5 rounded-2xl">
                        <div className="w-12 h-12 rounded-full bg-zinc-900 flex items-center justify-center">
                            <Calendar className="w-6 h-6 text-zinc-700" />
                        </div>
                        <div className="space-y-1">
                            <p className="text-[10px] text-zinc-500 font-black uppercase tracking-widest">
                                Aucun événement cette semaine
                            </p>
                            <p className="text-[9px] text-zinc-700 font-medium">
                                Planifiez le prochain raid ou événement de guilde
                            </p>
                        </div>
                        <Link
                            href={`/dashboard/${guildId}/calendar`}
                            className="text-[9px] font-black text-emerald-500/70 hover:text-emerald-400 uppercase tracking-widest transition-colors"
                        >
                            Ouvrir le calendrier →
                        </Link>
                    </div>
                )}
            </CardContent>
        </Card>
    );
}

"use client";
import { useState, useEffect } from "react";
import { ClipboardList, FileImage, Trophy, Coins, ChevronRight, Activity } from "lucide-react";
import Link from "next/link";
import { getPendingValidationsCount } from "@/server/actions/admin-actions";
import { cn } from "@/lib/utils";
import { motion, AnimatePresence } from "framer-motion";

interface ValidatorInboxClientProps {
    guildId: string;
    initialData: {
        pendingMissions: number;
        pendingAchievements: number;
        pendingKamas?: number;
        pendingReactivations?: number;
        total: number;
    }
}

type FilterType = "all" | "missions" | "achievements" | "kamas" | "reactivations";

const FILTER_CFG: Record<FilterType, { label: string; color: string; textActive: string; textInactive: string; icon: any; shadow: string }> = {
    all: { 
        label: "Tout", 
        color: "bg-orange-500", 
        textActive: "text-white", 
        textInactive: "text-orange-400", 
        icon: Activity,
        shadow: "shadow-orange-500/20"
    },
    missions: { 
        label: "Missions", 
        color: "bg-rose-500", 
        textActive: "text-white", 
        textInactive: "text-rose-400", 
        icon: FileImage,
        shadow: "shadow-rose-500/20"
    },
    achievements: { 
        label: "Succès", 
        color: "bg-amber-500", 
        textActive: "text-white", 
        textInactive: "text-amber-400", 
        icon: Trophy,
        shadow: "shadow-amber-500/20"
    },
    kamas: { 
        label: "Kamas", 
        color: "bg-yellow-500", 
        textActive: "text-black", 
        textInactive: "text-yellow-400", 
        icon: Coins,
        shadow: "shadow-yellow-500/20"
    },
    reactivations: { 
        label: "Retours", 
        color: "bg-emerald-500", 
        textActive: "text-white", 
        textInactive: "text-emerald-400", 
        icon: ClipboardList,
        shadow: "shadow-emerald-500/20"
    },
};

export function ValidatorInboxClient({ guildId, initialData }: ValidatorInboxClientProps) {
    const [data, setData] = useState(initialData);
    const [filter, setFilter] = useState<FilterType>("all");

    useEffect(() => {
        const interval = setInterval(async () => {
            try {
                const res = await getPendingValidationsCount(guildId);
                if (res.success && res.data) {
                    setData(res.data as any);
                }
            } catch (err) {
                console.error("Failed to poll pending validations", err);
            }
        }, 60000);
        return () => clearInterval(interval);
    }, [guildId]);

    const pendingKamas = (data as any).pendingKamas ?? 0;
    const pendingReactivations = (data as any).pendingReactivations ?? 0;
    
    const displayCount =
        filter === "missions" ? data.pendingMissions :
            filter === "achievements" ? data.pendingAchievements :
                filter === "kamas" ? pendingKamas :
                    filter === "reactivations" ? pendingReactivations :
                        data.total;

    if (data.total === 0) return null;

    const href = `/dashboard/${guildId}/admin/validation` + (filter !== "all" ? `?type=${filter === "reactivations" ? "retours" : filter}` : "");
    const currentCfg = FILTER_CFG[filter];

    return (
        <motion.div 
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            className="group relative flex flex-col gap-4 px-5 py-5 rounded-[2.5rem] border border-white/5 bg-zinc-950/40 backdrop-blur-3xl shadow-[0_20px_50px_rgba(0,0,0,0.5)] overflow-hidden"
        >
            {/* Ambient Background Glow */}
            <div className={cn("absolute -top-12 -right-12 w-32 h-32 blur-[60px] opacity-20 transition-all duration-700", currentCfg.color)} />
            
            {/* Header: Title & Heartbeat */}
            <div className="flex items-center justify-between relative z-10">
                <div className="flex items-center gap-3">
                    <div className="relative flex h-2 w-2">
                        <span className={cn("animate-ping absolute inline-flex h-full w-full rounded-full opacity-75", currentCfg.color)} />
                        <span className={cn("relative inline-flex rounded-full h-2 w-2", currentCfg.color)} />
                    </div>
                    <p className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-400 group-hover:text-white transition-colors">
                        Action Requise
                    </p>
                </div>
                <div className="p-2 bg-white/5 rounded-xl border border-white/5 group-hover:border-white/10 transition-all">
                    <currentCfg.icon className={cn("w-3.5 h-3.5 transition-all", currentCfg.textInactive)} />
                </div>
            </div>

            {/* Filter Chips Layer */}
            <div className="flex items-center gap-1.5 flex-wrap relative z-10">
                {(["all", "missions", "achievements", "kamas", "reactivations"] as FilterType[]).map((f) => {
                    const count = f === "all" ? data.total : f === "missions" ? data.pendingMissions : f === "achievements" ? data.pendingAchievements : f === "kamas" ? pendingKamas : pendingReactivations;
                    if (f !== "all" && count === 0) return null;
                    const cfg = FILTER_CFG[f];
                    const active = filter === f;
                    
                    return (
                        <button
                            key={f}
                            onClick={() => setFilter(f)}
                            className={cn(
                                "relative flex items-center gap-1.5 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border transition-all duration-300",
                                active 
                                    ? `${cfg.color} ${cfg.textActive} border-transparent shadow-lg ${cfg.shadow}` 
                                    : "bg-white/5 text-zinc-500 border-white/5 hover:bg-white/10 hover:text-zinc-300"
                            )}
                        >
                            <cfg.icon className="w-2.5 h-2.5" />
                            {cfg.label}
                            <span className={cn("ml-1 tabular-nums font-black opacity-60", active && "opacity-100")}>{count}</span>
                        </button>
                    );
                })}
            </div>

            {/* Main Action Area */}
            <Link 
                href={href} 
                className="group/action relative flex items-center justify-between bg-white/[0.03] hover:bg-white/[0.06] border border-white/5 hover:border-white/10 px-4 py-3 rounded-2xl transition-all duration-500 overflow-hidden"
            >
                <div className="flex items-center gap-4">
                    <AnimatePresence mode="wait">
                        <motion.span 
                            key={displayCount}
                            initial={{ scale: 0.8, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            className="text-4xl font-black text-white tabular-nums tracking-tighter"
                        >
                            {displayCount}
                        </motion.span>
                    </AnimatePresence>
                    <div className="flex flex-col">
                        <span className="text-[10px] text-zinc-400 font-black uppercase tracking-[0.2em] leading-none mb-1">
                            En Attente
                        </span>
                        <span className="text-[9px] text-zinc-500 font-bold uppercase tracking-widest opacity-60">
                            {filter === "all" ? "Demandes globales" : currentCfg.label}
                        </span>
                    </div>
                </div>
                <div className="p-2 rounded-full bg-white/5 group-hover/action:bg-white/10 transition-colors">
                    <ChevronRight className={cn("w-4 h-4 transition-all duration-500 group-hover/action:translate-x-0.5", currentCfg.textInactive)} />
                </div>
            </Link>

            {/* Modern Segmented Progress HUD */}
            <div className="space-y-2">
                <div className="flex items-center justify-between text-[8px] font-black uppercase tracking-[0.2em] text-zinc-600">
                    <span>Répartition</span>
                    <span className="text-zinc-400">Détails Système</span>
                </div>
                <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden flex gap-0.5 p-[1px]">
                    {data.pendingMissions > 0 && (
                        <motion.div 
                            initial={{ width: 0 }} 
                            animate={{ width: `${(data.pendingMissions / data.total) * 100}%` }} 
                            className="h-full bg-rose-500 rounded-sm shadow-[0_0_8px_rgba(244,63,94,0.4)]" 
                        />
                    )}
                    {data.pendingAchievements > 0 && (
                        <motion.div 
                            initial={{ width: 0 }} 
                            animate={{ width: `${(data.pendingAchievements / data.total) * 100}%` }} 
                            className="h-full bg-amber-500 rounded-sm shadow-[0_0_8px_rgba(245,158,11,0.4)]" 
                        />
                    )}
                    {pendingKamas > 0 && (
                        <motion.div 
                            initial={{ width: 0 }} 
                            animate={{ width: `${(pendingKamas / data.total) * 100}%` }} 
                            className="h-full bg-yellow-400 rounded-sm shadow-[0_0_8px_rgba(250,204,21,0.4)]" 
                        />
                    )}
                    {pendingReactivations > 0 && (
                        <motion.div 
                            initial={{ width: 0 }} 
                            animate={{ width: `${(pendingReactivations / data.total) * 100}%` }} 
                            className="h-full bg-emerald-500 rounded-sm shadow-[0_0_8px_rgba(16,185,129,0.4)]" 
                        />
                    )}
                </div>
            </div>
        </motion.div>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Loader2, Save, AlertTriangle, Hash, ShieldAlert, Sparkles, MessageSquare, ArrowRightLeft } from "lucide-react";
import { toast } from "sonner";
import { getBlacklistConfig, updateBlacklistSettings } from "@/server/actions/blacklist-actions";
import { cn } from "@/lib/utils";

interface BlacklistSettingsClientProps {
    guildId: string;
}

export function BlacklistSettingsClient({ guildId }: BlacklistSettingsClientProps) {
    const [channelId, setChannelId] = useState<string>("");
    const [isLoading, setIsLoading] = useState(true);
    const [isPending, startTransition] = useTransition();
    const [isConfigured, setIsConfigured] = useState(false);

    useEffect(() => {
        async function loadConfig() {
            const result = await getBlacklistConfig(guildId);
            if (result.success && result.data) {
                setChannelId(result.data.blacklistChannelId || "");
                setIsConfigured(!!result.data.blacklistChannelId);
            }
            setIsLoading(false);
        }
        loadConfig();
    }, [guildId]);

    const handleSave = () => {
        const trimmed = channelId.trim();
        if (trimmed && !/^\d{17,20}$/.test(trimmed)) {
            toast.error("ID de salon Discord invalide");
            return;
        }

        startTransition(async () => {
            const result = await updateBlacklistSettings(guildId, trimmed || null);
            if (result.success) {
                toast.success("Synchronisation Blacklist mise à jour !");
                setIsConfigured(!!trimmed);
            } else {
                toast.error(result.error || "Erreur lors de la sauvegarde");
            }
        });
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <Loader2 className="w-8 h-8 animate-spin text-red-500/50" />
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-10">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* ── MAIN CONFIG ── */}
                <Card className="lg:col-span-2 bg-zinc-900/40 border-white/5 backdrop-blur-xl shrink-0 overflow-hidden relative group">
                    <div className="absolute inset-0 bg-gradient-to-br from-red-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
                    
                    <CardHeader className="relative z-10">
                        <div className="flex items-center justify-between">
                            <CardTitle className="text-xl font-black uppercase tracking-tighter flex items-center gap-3">
                                <span className="bg-red-500/20 text-red-400 p-2.5 rounded-2xl border border-red-500/20">
                                    <ShieldAlert className="w-6 h-6" />
                                </span>
                                Synchronisation Discord
                            </CardTitle>
                            {isConfigured ? (
                                <Badge className="bg-red-500/10 text-red-400 border-red-500/20 px-3 py-1 font-black uppercase tracking-widest animate-pulse">
                                    SYNCHRO ACTIVE
                                </Badge>
                            ) : (
                                <Badge variant="outline" className="text-zinc-500 border-white/10 px-3 py-1 font-black uppercase tracking-widest">
                                    DÉSACTIVÉ
                                </Badge>
                            )}
                        </div>
                        <CardDescription className="text-zinc-400 font-medium">
                            Couplez votre salon de signalement Discord avec le Dashboard SigilOS pour une gestion centralisée.
                        </CardDescription>
                    </CardHeader>

                    <CardContent className="space-y-8 relative z-10">
                        <div className="p-4 rounded-2xl bg-black/40 border border-white/5 space-y-4">
                            <div className="flex items-center gap-4">
                                <div className="w-10 h-10 rounded-xl bg-red-500/10 border border-red-500/20 flex items-center justify-center shrink-0">
                                    <Hash className="w-5 h-5 text-red-400" />
                                </div>
                                <div className="space-y-0.5">
                                    <p className="text-xs font-black uppercase text-white tracking-widest">ID du Salon Blacklist</p>
                                    <p className="text-[10px] text-zinc-500 font-medium">Récupérez l&apos;ID via Discord (Clic droit {'>'} Copier l&apos;ID)</p>
                                </div>
                            </div>
                            
                            <div className="flex gap-2">
                                <Input 
                                    value={channelId}
                                    onChange={(e) => setChannelId(e.target.value)}
                                    placeholder="Ex: 1290442961380835451"
                                    className="bg-black/40 border-white/10 font-mono text-red-400 h-12 rounded-xl focus:ring-red-500/50"
                                />
                                <Button 
                                    onClick={handleSave} 
                                    disabled={isPending}
                                    className="bg-red-600 hover:bg-red-500 text-white font-black px-6 h-12 rounded-xl"
                                >
                                    {isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                                </Button>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="p-4 rounded-2xl bg-white/[0.02] border border-white/5 space-y-2">
                                <div className="flex items-center gap-2 text-white font-black text-[10px] uppercase tracking-widest">
                                    <ArrowRightLeft className="w-3.5 h-3.5 text-red-400" />
                                    Synchro Bidirectionnelle
                                </div>
                                <p className="text-[11px] text-zinc-500 leading-relaxed italic">
                                    Ajoutez, modifiez ou supprimez des entrées sur Discord ou le Dashboard, les changements se répercutent instantanément des deux côtés.
                                </p>
                            </div>
                            <div className="p-4 rounded-2xl bg-white/[0.02] border border-white/5 space-y-2">
                                <div className="flex items-center gap-2 text-white font-black text-[10px] uppercase tracking-widest">
                                    <MessageSquare className="w-3.5 h-3.5 text-red-400" />
                                    Formatage Automatique
                                </div>
                                <p className="text-[11px] text-zinc-500 leading-relaxed italic">
                                    Le bot formate proprement les signalements sur Discord avec des embeds colorés pour une lecture rapide par vos modérateurs.
                                </p>
                            </div>
                        </div>
                    </CardContent>
                </Card>

                {/* ── INFO PANEL ── */}
                <div className="space-y-6">
                    <Card className="bg-zinc-900/60 border-white/10 overflow-hidden relative">
                        <CardHeader className="bg-red-500/5 pb-4 border-b border-white/5">
                            <CardTitle className="text-xs font-black uppercase tracking-widest text-red-400 flex items-center gap-2">
                                <Sparkles className="w-3.5 h-3.5" />
                                Comment ça marche ?
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="pt-6 space-y-4">
                            <div className="space-y-3">
                                <div className="flex gap-3">
                                    <div className="w-5 h-5 rounded-full bg-red-500/20 text-red-400 flex items-center justify-center text-[10px] font-black shrink-0 mt-0.5">1</div>
                                    <p className="text-xs text-zinc-400 leading-relaxed font-medium">
                                        Créez ou choisissez un salon dédié aux signalements sur votre Discord.
                                    </p>
                                </div>
                                <div className="flex gap-3">
                                    <div className="w-5 h-5 rounded-full bg-red-500/20 text-red-400 flex items-center justify-center text-[10px] font-black shrink-0 mt-0.5">2</div>
                                    <p className="text-xs text-zinc-400 leading-relaxed font-medium">
                                        Saisissez son ID ici. Le Bot SigilOS doit avoir accès en <span className="text-white">lecture/écriture</span>.
                                    </p>
                                </div>
                                <div className="flex gap-3">
                                    <div className="w-5 h-5 rounded-full bg-red-500/20 text-red-400 flex items-center justify-center text-[10px] font-black shrink-0 mt-0.5">3</div>
                                    <p className="text-xs text-zinc-400 leading-relaxed font-medium">
                                        Postez n&apos;importe quoi dans ce salon : SigilOS le capturera et l&apos;ajoutera à la blacklist dashboard !
                                    </p>
                                </div>
                            </div>

                            <div className="pt-4 border-t border-white/5">
                                <div className="p-3 rounded-xl bg-amber-500/5 border border-amber-500/10 flex items-start gap-3">
                                    <AlertTriangle className="w-4 h-4 text-amber-500 shrink-0 mt-0.5" />
                                    <p className="text-[10px] text-amber-200/70 italic leading-relaxed font-medium">
                                        Note: Seuls les messages textuels sont synchronisés. Les images/fichiers ne sont pas importés.
                                    </p>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Loader2, Save, Hash, Users, Bell, Sparkles, Megaphone, ShieldAlert, ExternalLink, Trash2 } from "lucide-react";
import { toast } from "sonner";
import { getMissionConfig, updateMissionNotifySettings } from "@/server/actions/admin-actions";
import { getDiscordRolesAction } from "@/server/actions/user-actions";
import { cn } from "@/lib/utils";
import { Label } from "@/components/ui/label";

interface DiscordSettingsClientProps {
    guildId: string;
}

export function DiscordSettingsClient({ guildId }: DiscordSettingsClientProps) {
    const [newsEnabled, setNewsEnabled] = useState<boolean>(false);
    const [lifecycleChannelId, setLifecycleChannelId] = useState<string>("");
    
    const [fullConfig, setFullConfig] = useState<any>(null);
    const [roles, setRoles] = useState<{ id: string; name: string }[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isPending, startTransition] = useTransition();

    useEffect(() => {
        async function loadData() {
            const [configRes, rolesRes] = await Promise.all([
                getMissionConfig(guildId),
                getDiscordRolesAction(guildId, { ignoreWhitelist: true })

            ]);

            if (configRes.success && configRes.data) {
                setFullConfig(configRes.data);
                setNewsEnabled(configRes.data.newsBroadcastEnabled || false);
                setLifecycleChannelId(configRes.data.lifecycleNotifyChannelId || "");
            }

            if (rolesRes.success && rolesRes.roles) {
                setRoles(rolesRes.roles);
            }

            setIsLoading(false);
        }
        loadData();
    }, [guildId]);

    const handleSave = () => {
        if (!fullConfig) return;

        startTransition(async () => {
            const result = await updateMissionNotifySettings(guildId, {
                channelId: fullConfig.missionChannelId,
                roleId: fullConfig.missionNotifyRoleId,
                validationChannelId: fullConfig.missionValidationChannelId,
                validationRoleId: fullConfig.missionValidationNotifyRoleId,
                kamaNotifyChannelId: fullConfig.kamaNotifyChannelId,
                kamaNotifyRoleId: fullConfig.kamaNotifyRoleId,
                missionManagementNotifyChannelId: fullConfig.missionManagementNotifyChannelId,
                missionManagementNotifyRoleId: fullConfig.missionManagementNotifyRoleId,
                newsBroadcastEnabled: newsEnabled,
                lifecycleNotifyChannelId: lifecycleChannelId.trim() || null,
            });

            if (result.success) {
                toast.success("Paramètres Discord mis à jour !");
                setFullConfig({
                    ...fullConfig,
                    newsBroadcastEnabled: newsEnabled,
                    lifecycleNotifyChannelId: lifecycleChannelId.trim() || null,
                });
            } else {
                toast.error(result.error || "Erreur lors de la sauvegarde");
            }
        });
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <Loader2 className="w-8 h-8 animate-spin text-indigo-500/50" />
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-2 duration-500 text-left">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Configuration Panel */}
                <div className="lg:col-span-2 space-y-6">
                    {/* FLUX D'ACTUALITÉS */}
                    <Card className="bg-zinc-900/60 border-white/5 overflow-hidden group relative">
                        <div className="absolute inset-0 bg-gradient-to-br from-emerald-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
                        <CardHeader>
                            <CardTitle className="flex items-center gap-2 text-white font-black uppercase tracking-tighter">
