"use client";

import { useState, useEffect, useTransition } from "react";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Loader2, Save, AlertTriangle, Hash, Bell } from "lucide-react";
import { toast } from "sonner";
import { getDungeonFinderConfig, updateDjSettings } from "@/server/actions/dungeon-finder-actions";
import { getDiscordRolesAction, updateAllowedPingRolesAction } from "@/server/actions/user-actions";
import { PingRolesSelector } from "@/components/admin/ping-roles-selector";

interface DjSettingsClientProps {
    guildId: string;
}

export function DjSettingsClient({ guildId }: DjSettingsClientProps) {
    const [channelId, setChannelId] = useState<string>("");
    const [isLoading, setIsLoading] = useState(true);
    const [isPending, startTransition] = useTransition();
    const [isConfigured, setIsConfigured] = useState(false);
    
    const [djPingRoleIds, setDjPingRoleIds] = useState<string[]>([]);
    const [discordRoles, setDiscordRoles] = useState<{ id: string, name: string, color: string }[]>([]);

    useEffect(() => {
        async function loadConfig() {
            const [result, rolesRes] = await Promise.all([
                getDungeonFinderConfig(guildId),
                getDiscordRolesAction(guildId, { ignoreWhitelist: true })
            ]);
            if (result.success && result.data) {
                setChannelId(result.data.djNotifyChannelId || "");
                setIsConfigured(!!result.data.djNotifyChannelId);
                setDjPingRoleIds(result.data.djPingRoleIds || []);
            }
            if (rolesRes.success && rolesRes.roles) {
                setDiscordRoles(rolesRes.roles.filter((r: any) => r.name !== "@everyone") as any);
            }
            setIsLoading(false);
        }
        loadConfig();
    }, [guildId]);

    const handleSave = () => {
        startTransition(async () => {
            const result = await updateDjSettings(guildId, {
                djNotifyChannelId: channelId.trim() || null
            });
            const pingRolesResult = await updateAllowedPingRolesAction(guildId, djPingRoleIds, "dj");

            if (result.success && pingRolesResult.success) {
                toast.success("Configuration Donjons & Quêtes sauvegardée !");
                setIsConfigured(!!channelId.trim());
            } else {
                toast.error(result.error || pingRolesResult.error || "Erreur lors de la sauvegarde");
            }
        });
    };

    const handleClear = () => {
        startTransition(async () => {
            const result = await updateDjSettings(guildId, { djNotifyChannelId: null });
            if (result.success) {
                setChannelId("");
                setIsConfigured(false);
                toast.success("Notifications Donjons désactivées");
            } else {
                toast.error(result.error || "Erreur lors de la désactivation");
            }
        });
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <Loader2 className="w-8 h-8 animate-spin text-indigo-500" />
            </div>
        );
    }

    return (
        <div className="space-y-8">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Configuration Panel */}
                <Card className="lg:col-span-2 bg-zinc-900/60 border-white/5 overflow-hidden">
                    <CardHeader>
                        <div className="flex items-center justify-between">
                            <CardTitle className="flex items-center gap-2">
                                <span className="bg-indigo-500/20 text-indigo-400 p-2 rounded-lg">
                                    <Bell className="w-5 h-5" />
                                </span>
                                Notifications Donjons & Quêtes
                            </CardTitle>
                            {isConfigured ? (
                                <Badge className="bg-emerald-500/10 text-emerald-400 border-emerald-500/20 hover:bg-emerald-500/20">
                                    Actif
                                </Badge>
                            ) : (
                                <Badge variant="outline" className="text-zinc-500">
                                    Inactif
                                </Badge>
                            )}
                        </div>
                        <CardDescription>
                            Configurez le salon Discord qui recevra les annonces de recherche de joueurs pour les Donjons et Quêtes.
                        </CardDescription>
                    </CardHeader>

                    <CardContent className="space-y-6">
                        {/* Step 1 */}
                        <div className="relative pl-6 border-l-2 border-white/5 pb-6 last:pb-0">
                            <div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-zinc-800 border-2 border-zinc-950 flex items-center justify-center">
                                <div className="w-1.5 h-1.5 rounded-full bg-zinc-400" />
                            </div>
                            <h3 className="text-sm font-medium text-white mb-2">1. Récupérer l'ID du salon</h3>
                            <p className="text-xs text-zinc-500 mb-3">
                                Activez le mode développeur Discord, puis faites <span className="text-zinc-300">Clic Droit</span> sur le salon voulu {'>'} <span className="text-zinc-300">Copier l'identifiant</span>.
                            </p>
                        </div>

                        {/* Step 2 */}
                        <div className="relative pl-6 border-l-2 border-indigo-500/50">
                            <div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-indigo-500 border-2 border-zinc-950 shadow-[0_0_10px_rgba(99,102,241,0.5)]" />
                            <h3 className="text-sm font-medium text-white mb-4">2. Coller l'identifiant</h3>

                            <div className="space-y-4">
                                <div className="flex gap-2">
                                    <Input
                                        value={channelId}
                                        onChange={(e) => setChannelId(e.target.value)}
                                        placeholder="Ex: 123456789012345678"
                                        className="font-mono bg-black/20 border-white/10"
                                    />
                                    <Button onClick={handleSave} disabled={isPending} className="min-w-[120px] bg-indigo-600 hover:bg-indigo-500">
                                        {isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                                        Sauvegarder
                                    </Button>
                                </div>
                                {isConfigured && (
                                    <div className="flex justify-end">
                                        <Button variant="ghost" size="sm" onClick={handleClear} disabled={isPending} className="text-red-400 hover:text-red-300 hover:bg-red-900/20 h-auto py-1 px-3 text-xs">
                                            Désactiver l'intégration
                                        </Button>
                                    </div>
                                )}
                            </div>
                        </div>
                        {/* Step 3 - Pings */}
                        <div className="relative pl-6 border-l-2 border-transparent">
                            <div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-zinc-800 border-2 border-zinc-950 flex items-center justify-center">
                                <div className="w-1.5 h-1.5 rounded-full bg-zinc-400" />
                            </div>
                            <h3 className="text-sm font-medium text-white mb-2">3. Rôles de Ping Autorisés (Whitelist)</h3>
                            <p className="text-xs text-zinc-500 mb-4">
                                Définissez quels rôles Discord les membres peuvent mentionner lors de la création d'événements Donjons/Quêtes.
                            </p>
                            <PingRolesSelector 
                                value={djPingRoleIds} 
                                onChange={setDjPingRoleIds} 
                                roles={discordRoles} 
                                description="Si la liste est vide, aucun rôle Discord ne sera disponible pour le ping/sélection dans les modales de création (seuls les administrateurs verront toujours tous les rôles)." 
                            />
                        </div>
                    </CardContent>
                </Card>

                {/* Preview Panel */}
                <div className="space-y-6">
                    <Card className="bg-zinc-900/60 border-white/5 overflow-hidden">
                        <CardHeader className="bg-white/5 pb-4">
                            <CardTitle className="text-sm text-zinc-300">Aperçu du message</CardTitle>
                        </CardHeader>
                        <CardContent className="pt-6 relative">
                            {/* Discord Message Mockup */}
                            <div className="flex items-start gap-4 text-left">
                                <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center shrink-0">
                                    <Bell className="w-5 h-5 text-white" />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-baseline gap-2 mb-1">
                                        <span className="font-medium text-indigo-400">SigilOS</span>
                                        <span className="bg-indigo-500/20 text-indigo-300 text-[10px] px-1 rounded">BOT</span>
                                        <span className="text-xs text-zinc-500">Maintenant</span>
                                    </div>

                                    {/* Embed */}
                                    <div className="bg-[#2b2d31] rounded border-l-4 border-indigo-400 p-4 max-w-sm">
                                        <div className="flex items-center gap-2 mb-2">
                                            <span className="text-lg">⚔️</span>
                                            <h4 className="font-semibold text-white text-sm">Recherche de Groupe</h4>
                                        </div>

                                        <p className="text-zinc-300 text-xs mb-3 leading-relaxed">
                                            <span className="text-indigo-400 font-medium hover:underline cursor-pointer">Wylan</span> a ouvert un recrutement pour le donjon **Tal Kasha**.
                                        </p>

                                        <div className="grid grid-cols-2 gap-y-3 gap-x-4">
                                            <div>
                                                <div className="text-[#b5bac1] text-[9px] font-bold uppercase tracking-wider mb-0.5">Activité</div>
                                                <div className="text-zinc-200 text-xs">SUCCÈS / SCORE</div>
                                            </div>
                                            <div>
                                                <div className="text-[#b5bac1] text-[9px] font-bold uppercase tracking-wider mb-0.5">Places</div>
                                                <div className="text-zinc-200 text-xs">👥 2 / 4</div>
                                            </div>
                                            <div className="col-span-2">
                                                <div className="text-[#b5bac1] text-[9px] font-bold uppercase tracking-wider mb-0.5">Description</div>
                                                <div className="text-zinc-200 text-xs">Besoin d'un Panda et Enu pour le succès.</div>
                                            </div>
                                        </div>

                                        <div className="mt-3 pt-3 border-t border-[#3f4147] flex items-center gap-2">
                                            <div className="w-4 h-4 rounded-full bg-zinc-700" />
                                            <span className="text-[#949ba4] text-[10px]">SigilOS • Dungeon Finder</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </CardContent>
                    </Card>

                    <Card className="bg-blue-500/5 border-blue-500/10">
                        <CardContent className="p-4 flex gap-3 text-left">
                            <div className="p-2 bg-blue-500/20 rounded-lg shrink-0 h-fit">
                                <AlertTriangle className="w-4 h-4 text-blue-400" />
                            </div>
                            <div className="space-y-1">
                                <h4 className="text-sm font-medium text-blue-200">Permissions requises</h4>
                                <p className="text-xs text-blue-300/70 leading-relaxed">
                                    Le bot <strong>SigilOS</strong> doit avoir les droits "Voir le salon" et "Envoyer des messages".
                                </p>
                            </div>
                        </CardContent>
                    </Card>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Trash2, Loader2 } from "lucide-react";
import { wipeUserProfile } from "@/server/actions/lifecycle-actions";
import { toast } from "sonner";

interface HistoryWipeButtonProps {
    profileId: string;
    guildId: string;
    nickname: string;
}

export function HistoryWipeButton({ profileId, guildId, nickname }: HistoryWipeButtonProps) {
    const [isWiping, setIsWiping] = useState(false);

    const handleWipe = async () => {
        if (!confirm(`Es-tu sûr de vouloir nettoyer définitivement les données de ${nickname} ? Cette action est irréversible.`)) {
            return;
        }

        setIsWiping(true);
        try {
            const res = await wipeUserProfile(profileId, guildId);
            if (res.success) {
                toast.success("Profil nettoyé avec succès");
            } else {
                toast.error(res.error || "Erreur lors du nettoyage");
            }
        } catch (e) {
            toast.error("Erreur réseau");
        } finally {
            setIsWiping(false);
        }
    };

    return (
        <button
            onClick={handleWipe}
            disabled={isWiping}
            className="p-2 text-zinc-500 hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-all group"
            title="Nettoyer les données (Wipe RGPD)"
        >
            {isWiping ? (
                <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
                <Trash2 className="w-4 h-4" />
            )}
        </button>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Loader2, Save, Hash, AlertTriangle } from "lucide-react";
import { toast } from "sonner";
import { getLoansConfig, updateLoansChannel, getServicesStatusConfig, updateServicesStatusConfig } from "@/server/actions/admin-actions";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Separator } from "@/components/ui/separator";

interface LoansSettingsClientProps {
    guildId: string;
}

export function LoansSettingsClient({ guildId }: LoansSettingsClientProps) {
    const [channelId, setChannelId] = useState<string>("");
    const [isLoading, setIsLoading] = useState(true);
    const [isPending, startTransition] = useTransition();
    const [isConfigured, setIsConfigured] = useState(false);

    // Maintenance States
    const [marketplaceEnabled, setMarketplaceEnabled] = useState(true);
    const [marketplaceMessage, setMarketplaceMessage] = useState("");
    const [loansEnabled, setLoansEnabled] = useState(true);
    const [loansMessage, setLoansMessage] = useState("");
    const [vaultEnabled, setVaultEnabled] = useState(true);
    const [vaultMessage, setVaultMessage] = useState("");

    useEffect(() => {
        async function loadConfig() {
            const [loansRes, servicesRes] = await Promise.all([
                getLoansConfig(guildId),
                getServicesStatusConfig(guildId)
            ]);

            if (loansRes.success && loansRes.data) {
                setChannelId(loansRes.data.loansNotifyChannelId || "");
                setIsConfigured(!!loansRes.data.loansNotifyChannelId);
            }

            if (servicesRes.success && servicesRes.data) {
                setMarketplaceEnabled(servicesRes.data.serviceMarketplaceEnabled);
                setMarketplaceMessage(servicesRes.data.serviceMarketplaceMessage || "");
                setLoansEnabled(servicesRes.data.serviceLoansEnabled);
                setLoansMessage(servicesRes.data.serviceLoansMessage || "");
                setVaultEnabled(servicesRes.data.serviceVaultEnabled);
                setVaultMessage(servicesRes.data.serviceVaultMessage || "");
            }

            setIsLoading(false);
        }
        loadConfig();
    }, [guildId]);

    const handleSaveChannel = () => {
        startTransition(async () => {
            const result = await updateLoansChannel(guildId, channelId.trim() || null);
            if (result.success) {
                toast.success("Salon configuré !");
                setIsConfigured(!!channelId.trim());
            } else {
                toast.error(result.error || "Erreur lors de la sauvegarde");
            }
        });
    };

    const handleSaveMaintenance = () => {
        startTransition(async () => {
            const result = await updateServicesStatusConfig(guildId, {
                serviceMarketplaceEnabled: marketplaceEnabled,
                serviceMarketplaceMessage: marketplaceMessage.trim() || null,
                serviceLoansEnabled: loansEnabled,
                serviceLoansMessage: loansMessage.trim() || null,
                serviceVaultEnabled: vaultEnabled,
                serviceVaultMessage: vaultMessage.trim() || null,
            });

            if (result.success) {
                toast.success("Statuts des services mis à jour !");
            } else {
                toast.error(result.error || "Erreur lors de la sauvegarde");
            }
        });
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center py-8">
                <Loader2 className="w-6 h-6 animate-spin text-primary" />
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <Card className="lg:col-span-2 bg-zinc-900/60 border-white/5">
                    <CardHeader>
                        <div className="flex items-center justify-between">
                            <CardTitle className="flex items-center gap-2 text-base">
                                <span className="bg-emerald-500/20 text-emerald-400 p-2 rounded-lg">
                                    <Hash className="w-4 h-4" />
                                </span>
                                Salon de notifications
                            </CardTitle>
                            {isConfigured ? (
                                <Badge className="bg-emerald-500/10 text-emerald-400 border-emerald-500/20">Actif</Badge>
                            ) : (
                                <Badge variant="outline" className="text-zinc-500">Inactif</Badge>
                            )}
                        </div>
                        <CardDescription>
                            Quand un prêt est créé/rendu ou qu&apos;un mouvement de coffre est enregistré, le bot postera un message récapitulatif dans ce salon.
                        </CardDescription>
                    </CardHeader>
                    <CardContent className="space-y-4">
                        <div className="space-y-2">
                            <p className="text-xs text-zinc-500">
                                Mode développeur Discord → Clic droit sur le salon → <span className="text-zinc-300">Copier l&apos;identifiant</span>
                            </p>
                            <div className="flex gap-2">
                                <Input
                                    value={channelId}
                                    onChange={(e) => setChannelId(e.target.value)}
                                    placeholder="Ex: 123456789012345678"
                                    className="font-mono bg-black/20 border-white/10"
                                />
                                <Button onClick={handleSaveChannel} disabled={isPending} className="min-w-[120px] bg-emerald-600 hover:bg-emerald-500">
                                    {isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                                    Sauvegarder
                                </Button>
                            </div>
                            {isConfigured && (
                                <div className="flex justify-end">
                                    <Button
                                        variant="ghost" size="sm"
                                        onClick={() => { setChannelId(""); handleSaveChannel(); }}
                                        disabled={isPending}
                                        className="text-rose-400 hover:text-rose-300 hover:bg-rose-900/20 text-xs"
                                    >
                                        Désactiver
                                    </Button>
                                </div>
                            )}
                        </div>
                    </CardContent>
                </Card>

                <Card className="bg-blue-500/5 border-blue-500/10 h-fit">
                    <CardContent className="p-4 flex gap-3">
                        <div className="p-2 bg-blue-500/20 rounded-lg shrink-0 h-fit">
                            <AlertTriangle className="w-4 h-4 text-blue-400" />
                        </div>
                        <div className="space-y-1">
                            <h4 className="text-sm font-medium text-blue-200">Permissions requises</h4>
                            <p className="text-xs text-blue-300/70 leading-relaxed">
                                Le bot <strong>SigilOS</strong> doit avoir les droits <em>Voir le salon</em> et <em>Envoyer des messages</em> dans le salon cible.
                            </p>
                        </div>
                    </CardContent>
                </Card>
            </div>

            <Card className="bg-zinc-900/60 border-white/5 overflow-hidden relative">
                <div className="absolute top-0 right-0 p-4">
                    <Button onClick={handleSaveMaintenance} disabled={isPending} className="bg-emerald-600 hover:bg-emerald-500">
                        {isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                        Enregistrer les statuts
                    </Button>
                </div>
                <CardHeader>
                    <CardTitle className="text-base flex items-center gap-2">
                        <AlertTriangle className="w-4 h-4 text-amber-500" />
                        Maintenance & Accès aux Services
                    </CardTitle>
                    <CardDescription>
                        Désactivez temporairement des onglets spécifiques et affichez un message personnalisé aux membres.
                    </CardDescription>
                </CardHeader>
                <CardContent className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                        {/* Marketplace */}
                        <div className="space-y-4">
                            <div className="flex items-center justify-between">
                                <div className="space-y-0.5">
                                    <Label className="text-sm font-bold">Services (Marketplace)</Label>
                                    <p className="text-[10px] text-zinc-500 uppercase tracking-widest">Onglet principal</p>
                                </div>
                                <Switch
                                    checked={marketplaceEnabled}
                                    onCheckedChange={setMarketplaceEnabled}
                                />
                            </div>
                            {!marketplaceEnabled && (
                                <div className="space-y-1.5 animate-in slide-in-from-top-1 duration-200">
                                    <Label className="text-[10px] text-zinc-400 font-black uppercase tracking-widest">Message d&apos;indisponibilité</Label>
                                    <Textarea
                                        value={marketplaceMessage}
                                        onChange={(e) => setMarketplaceMessage(e.target.value)}
                                        placeholder="Ex: Le marketplace est en maintenance..."
                                        className="h-20 bg-black/40 border-white/10 text-xs resize-none"
                                    />
                                </div>
                            )}
                        </div>

                        {/* Loans */}
                        <div className="space-y-4">
                            <div className="flex items-center justify-between">
                                <div className="space-y-0.5">
                                    <Label className="text-sm font-bold">Prêts</Label>
                                    <p className="text-[10px] text-zinc-500 uppercase tracking-widest">Emprunts & Retours</p>
                                </div>
                                <Switch
                                    checked={loansEnabled}
                                    onCheckedChange={setLoansEnabled}
                                />
                            </div>
                            {!loansEnabled && (
                                <div className="space-y-1.5 animate-in slide-in-from-top-1 duration-200">
                                    <Label className="text-[10px] text-zinc-400 font-black uppercase tracking-widest">Message d&apos;indisponibilité</Label>
                                    <Textarea
                                        value={loansMessage}
                                        onChange={(e) => setLoansMessage(e.target.value)}
                                        placeholder="Ex: Les prêts sont suspendus pour inventaire..."
                                        className="h-20 bg-black/40 border-white/10 text-xs resize-none"
                                    />
                                </div>
                            )}
                        </div>

                        {/* Vault */}
                        <div className="space-y-4">
                            <div className="flex items-center justify-between">
                                <div className="space-y-0.5">
                                    <Label className="text-sm font-bold">Coffre</Label>
                                    <p className="text-[10px] text-zinc-500 uppercase tracking-widest">Historique & Trésorerie</p>
                                </div>
                                <Switch
                                    checked={vaultEnabled}
                                    onCheckedChange={setVaultEnabled}
                                />
                            </div>
                            {!vaultEnabled && (
                                <div className="space-y-1.5 animate-in slide-in-from-top-1 duration-200">
                                    <Label className="text-[10px] text-zinc-400 font-black uppercase tracking-widest">Message d&apos;indisponibilité</Label>
                                    <Textarea
                                        value={vaultMessage}
                                        onChange={(e) => setVaultMessage(e.target.value)}
                                        placeholder="Ex: Le coffre est inaccessible suite à une réorganisation..."
                                        className="h-20 bg-black/40 border-white/10 text-xs resize-none"
                                    />
                                </div>
                            )}
                        </div>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Loader2, Save, Hash, Target, Users, Bell, Search, ShieldCheck, Coins, Trophy, Clock, Eye } from "lucide-react";
import { toast } from "sonner";
import { getMissionConfig, updateMissionNotifySettings } from "@/server/actions/admin-actions";
import { getDiscordRolesAction } from "@/server/actions/user-actions";
import { RoleSelector } from "@/components/admin/role-selector";

interface MissionSettingsClientProps {
    guildId: string;
}

export function MissionSettingsClient({ guildId }: MissionSettingsClientProps) {
    // Publication (missions hebdo)
    const [channelId, setChannelId] = useState<string>("");
    const [roleId, setRoleId] = useState<string | null>(null);

    // Validation Missions
    const [validationChannelId, setValidationChannelId] = useState<string>("");
    const [validationRoleId, setValidationRoleId] = useState<string | null>(null);

    // Contributions Kamas
    const [kamaChannelId, setKamaChannelId] = useState<string>("");
    const [kamaRoleId, setKamaRoleId] = useState<string | null>(null);
    
    // Rappel Reset Staff (Mardi 8h00)
    const [managementChannelId, setManagementChannelId] = useState<string>("");
    const [managementRoleId, setManagementRoleId] = useState<string | null>(null);

    // Mode Vitrine
    const [missionVitrineMode, setMissionVitrineMode] = useState<boolean>(false);

    const [roles, setRoles] = useState<{ id: string; name: string }[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isPending, startTransition] = useTransition();

    useEffect(() => {
        async function loadData() {
            const [configRes, rolesRes] = await Promise.all([
                getMissionConfig(guildId),
                getDiscordRolesAction(guildId, { ignoreWhitelist: true })

            ]);

            if (configRes.success && configRes.data) {
                setChannelId(configRes.data.missionChannelId || "");
                setValidationChannelId(configRes.data.missionValidationChannelId || "");
                setKamaChannelId(configRes.data.kamaNotifyChannelId || "");
                setRoleId(configRes.data.missionNotifyRoleId || null);
                setValidationRoleId(configRes.data.missionValidationNotifyRoleId || null);
                // New fields (may not exist in older configs, graceful fallback)
                setKamaRoleId((configRes.data as any).kamaNotifyRoleId || null);
                setManagementChannelId(configRes.data.missionManagementNotifyChannelId || "");
                setManagementRoleId(configRes.data.missionManagementNotifyRoleId || null);
                setMissionVitrineMode(configRes.data.missionVitrineMode || false);
            }

            if (rolesRes.success && rolesRes.roles) {
                setRoles(rolesRes.roles);
            }

            setIsLoading(false);
        }
        loadData();
    }, [guildId]);

    const handleSave = () => {
        startTransition(async () => {
            const result = await updateMissionNotifySettings(guildId, {
                channelId: channelId.trim() || null,
                roleId: roleId,
                validationChannelId: validationChannelId.trim() || null,
                validationRoleId: validationRoleId,
                kamaNotifyChannelId: kamaChannelId.trim() || null,
                kamaNotifyRoleId: kamaRoleId,
                missionManagementNotifyChannelId: managementChannelId.trim() || null,
                missionManagementNotifyRoleId: managementRoleId,
                missionVitrineMode: missionVitrineMode,
            });
            if (result.success) {
                toast.success("Paramètres mis à jour !");
            } else {
                toast.error(result.error || "Erreur lors de la sauvegarde");
            }
        });
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <Loader2 className="w-8 h-8 animate-spin text-amber-500/50" />
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Configuration Panel */}
                <div className="lg:col-span-2 space-y-6">
                    {/* SECTION 1: PUBLICATION */}
                    <Card className="bg-zinc-900/60 border-white/5 overflow-hidden">
                        <CardHeader>
                            <CardTitle className="flex items-center gap-2 text-white">
                                <span className="bg-amber-500/20 text-amber-400 p-2 rounded-lg">
                                    <Target className="w-5 h-5" />
                                </span>
                                Publication Hebdomadaire
                            </CardTitle>
                            <CardDescription>
                                Annonce automatique des 12 missions de la semaine.
                            </CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500 flex items-center gap-2">
                                        <Hash className="w-3 h-3" /> Salon de Publication
                                    </label>
                                    <Input
                                        value={channelId}
                                        onChange={(e) => setChannelId(e.target.value)}
                                        placeholder="ID du salon..."
                                        className="font-mono bg-black/20 border-white/10 h-10"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500 flex items-center gap-2">
                                        <Users className="w-3 h-3" /> Rôle à Mentionner
                                    </label>
                                    <RoleSelector value={roleId} onChange={setRoleId} roles={roles} className="h-10" />
                                </div>
                            </div>
                        </CardContent>
                    </Card>

                    {/* SECTION 2: NOTIFICATIONS UPLOADS */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                        <Card className="bg-zinc-900/60 border-white/5">
                            <CardHeader className="pb-4">
                                <CardTitle className="text-sm flex items-center gap-2 text-purple-400 uppercase tracking-tight">
                                    <ShieldCheck className="w-4 h-4" /> Validation Missions
                                </CardTitle>
                            </CardHeader>
                            <CardContent className="space-y-4">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Salon ID</label>
                                    <Input value={validationChannelId} onChange={(e) => setValidationChannelId(e.target.value)} className="font-mono bg-black/20 border-white/10 h-9" />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Staff à alerter</label>
                                    <RoleSelector value={validationRoleId} onChange={setValidationRoleId} roles={roles} className="h-9" />
                                </div>
                            </CardContent>
                        </Card>

                        <Card className="bg-zinc-900/60 border-white/5">
                            <CardHeader className="pb-4">
                                <CardTitle className="text-sm flex items-center gap-2 text-yellow-400 uppercase tracking-tight">
                                    <Coins className="w-4 h-4" /> Contributions Kamas
                                </CardTitle>
                            </CardHeader>
                            <CardContent className="space-y-4">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Salon ID</label>
                                    <Input value={kamaChannelId} onChange={(e) => setKamaChannelId(e.target.value)} className="font-mono bg-black/20 border-white/10 h-9" />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Staff à alerter</label>
                                    <RoleSelector value={kamaRoleId} onChange={setKamaRoleId} roles={roles} className="h-9" />
                                </div>
                            </CardContent>
                        </Card>
                    </div>

                    {/* SECTION 3: RAPPEL RESET */}
                    <Card className="bg-zinc-900/60 border-white/5">
                        <CardHeader>
                            <CardTitle className="flex items-center gap-2 text-indigo-400 text-sm uppercase tracking-tight">
                                <Bell className="w-4 h-4" /> Rappel Reset Hebdo (Mardi 08:00)
                            </CardTitle>
                            <CardDescription>Rappelle aux officiers de générer les missions après la maintenance Dofus.</CardDescription>
                        </CardHeader>
                        <CardContent className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Salon de Rappel</label>
                                <Input value={managementChannelId} onChange={(e) => setManagementChannelId(e.target.value)} className="font-mono bg-black/20 border-white/10 h-10" />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Rôle Staff</label>
                                <RoleSelector value={managementRoleId} onChange={setManagementRoleId} roles={roles} className="h-10" />
                            </div>
                        </CardContent>
                    </Card>

                    {/* SECTION 4: MODE VITRINE */}
                    <Card className="bg-zinc-900/60 border-white/5">
                        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-4">
                            <div className="space-y-1">
                                <CardTitle className="flex items-center gap-2 text-blue-400 text-sm uppercase tracking-tight">
                                    <Eye className="w-4 h-4" /> Mode Vitrine (Lecture seule)
                                </CardTitle>
                                <CardDescription className="text-zinc-400 text-xs">
                                    Masque la possibilité d'uploader des captures (bouton PREUVE), le statut "Validé" sur les missions, et cache les ladders aux membres.
                                </CardDescription>
                            </div>
                            <Switch checked={missionVitrineMode} onCheckedChange={setMissionVitrineMode} />
                        </CardHeader>
                    </Card>

                    <div className="flex justify-end pt-4">
                        <Button onClick={handleSave} disabled={isPending} className="bg-amber-600 hover:bg-amber-500 text-white min-w-[200px] font-bold h-12 shadow-xl shadow-amber-600/20">
                            {isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                            SAUVEGARDER TOUT
                        </Button>
                    </div>
                </div>

                {/* Preview Panel */}
                <div className="space-y-6">
                    <Card className="bg-zinc-900/60 border-white/5 overflow-hidden">
                        <CardHeader className="bg-white/5 pb-4 px-4 py-3">
                            <CardTitle className="text-[10px] font-black uppercase tracking-widest text-zinc-400">Aperçu : Validation</CardTitle>
                        </CardHeader>
                        <CardContent className="pt-6 relative text-left px-4">
                            <div className="flex items-start gap-3">
                                <div className="w-8 h-8 rounded-full bg-purple-500 flex items-center justify-center shrink-0">
                                    <ShieldCheck className="w-4 h-4 text-white" />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-baseline gap-2 mb-1">
                                        <span className="font-medium text-purple-400 text-xs">SigilOS</span>
                                        <span className="text-[9px] text-zinc-500 uppercase">Maintenant</span>
                                    </div>
                                    <div className="bg-[#2b2d31] rounded border-l-4 border-purple-400 p-3 max-w-sm shadow-xl">
                                        <div className="flex items-center gap-2 mb-2">
                                            <span className="text-sm">🛡️</span>
                                            <h4 className="font-semibold text-white text-[11px]">Preuve de Mission</h4>
                                        </div>
                                        <p className="text-zinc-300 text-[10px] mb-3 leading-relaxed">
                                            <span className="text-purple-400 font-medium">@Wylan</span> a soumis une preuve pour **Donjon Kralamoure**.
                                        </p>
                                        <div className="flex gap-2">
                                            <div className="px-3 py-1 bg-emerald-500/20 border border-emerald-500/30 text-emerald-400 text-[9px] font-bold rounded">VALIDER</div>
                                            <div className="px-3 py-1 bg-rose-500/20 border border-rose-500/30 text-rose-400 text-[9px] font-bold rounded">REFUSER</div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </CardContent>
                    </Card>

                    <Card className="bg-zinc-900/60 border-white/5 overflow-hidden">
                        <CardHeader className="bg-white/5 pb-4 px-4 py-3">
                            <CardTitle className="text-[10px] font-black uppercase tracking-widest text-zinc-400">Aperçu : Reset Hebdo</CardTitle>
                        </CardHeader>
                        <CardContent className="pt-6 relative text-left px-4">
                            <div className="flex items-start gap-3">
                                <div className="w-8 h-8 rounded-full bg-indigo-500 flex items-center justify-center shrink-0">
                                    <Bell className="w-4 h-4 text-white" />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-baseline gap-2 mb-1">
                                        <span className="font-medium text-indigo-400 text-xs">SigilOS</span>
                                        <span className="text-[9px] text-zinc-500 uppercase font-black">Mardi 08:00</span>
                                    </div>
                                    <div className="bg-[#2b2d31] rounded border-l-4 border-indigo-400 p-3 max-w-sm">
                                        <div className="flex items-center gap-2 mb-2">
                                            <span className="text-sm">🚀</span>
                                            <h4 className="font-semibold text-white text-[11px]">Reset Hebdomadaire</h4>
                                        </div>
                                        <p className="text-zinc-300 text-[10px] leading-relaxed mb-3">
                                            Le reset Dofus a eu lieu. Il est temps de générer les missions !
                                        </p>
                                        <div className="w-full py-1.5 bg-zinc-700 hover:bg-zinc-600 text-white text-[9px] font-bold rounded flex items-center justify-center gap-2">
                                            <span>🛠️</span> GÉRER LES MISSIONS
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import {
    Sparkles,
    Bell,
    Save,
    Loader2,
    Info,
    LayoutDashboard,
    Eye,
    ShieldCheck,
    MessageSquareText,
    HelpCircle,
    Copy,
    ChevronRight,
    Trophy,
    UserPlus
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { toast } from "sonner";
import { Card } from "@/components/ui/card";
import {
    getOnboardingSettings,
    updateWelcomeSettings,
    updateWelcomeBadgeName
} from "@/server/actions/onboarding-admin-actions";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import ReactMarkdown from "react-markdown";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { cn } from "@/lib/utils";
import { RoleSelector } from "@/components/admin/role-selector";
import {
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from "@/components/ui/tooltip";

interface OnboardingSettingsClientProps {
    guildId: string;
}

export function OnboardingSettingsClient({ guildId }: OnboardingSettingsClientProps) {
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const router = useRouter();

    const switchTabParam = (tabId: string) => {
        router.push(`/dashboard/${guildId}/admin/settings?tab=${tabId}`);
    };

    const [welcomeEnabled, setWelcomeEnabled] = useState(false);
    const [welcomeChannelId, setWelcomeChannelId] = useState<string>("");
    const [welcomeTemplate, setWelcomeTemplate] = useState<string>("");
    const [welcomeDiscordTemplate, setWelcomeDiscordTemplate] = useState<string>("");
    const [welcomeMentionRoleId, setWelcomeMentionRoleId] = useState<string>("");
    const [welcomeDashboardEnabled, setWelcomeDashboardEnabled] = useState(true);
    const [welcomeDiscordEnabled, setWelcomeDiscordEnabled] = useState(false);
    const [availableRoles, setAvailableRoles] = useState<{ id: string; name: string }[]>([]);

    const [welcomeBadgeName, setWelcomeBadgeName] = useState("Nouveau");

    useEffect(() => {
        const load = async () => {
            const res = await getOnboardingSettings(guildId);
            if (res.success && res.data) {
                setWelcomeEnabled(res.data.enabled);
                setWelcomeChannelId(res.data.channelId || "");
                setWelcomeTemplate(res.data.template || "");
                setWelcomeDiscordTemplate(res.data.discordTemplate || "");
                setWelcomeMentionRoleId(res.data.mentionRoleId || "");
                setWelcomeDashboardEnabled(res.data.dashboardEnabled);
                setWelcomeDiscordEnabled(res.data.discordEnabled);
                setWelcomeBadgeName(res.data.welcomeBadgeName || "Nouveau");
                if (res.data.availableRoles) setAvailableRoles(res.data.availableRoles);
            }
            setLoading(false);
        };
        load();
    }, [guildId]);

    const handleSaveWelcome = async () => {
        setSaving(true);
        try {
            const res = await updateWelcomeSettings({
                guildId,
                enabled: welcomeEnabled,
                channelId: welcomeChannelId || null,
                template: welcomeTemplate || null,
                discordTemplate: welcomeDiscordTemplate || null,
                mentionRoleId: welcomeMentionRoleId || null,
                dashboardEnabled: welcomeDashboardEnabled,
                discordEnabled: welcomeDiscordEnabled,
            });
            if (res.success) toast.success("Paramètres d'accueil enregistrés");
            else toast.error(res.error || "Erreur");
        } catch (e) {
            toast.error("Erreur de communication");
        } finally {
            setSaving(false);
        }
    };

    const handleSaveBadge = async () => {
        setSaving(true);
        try {
            const res = await updateWelcomeBadgeName({
                guildId,
                badgeName: welcomeBadgeName,
            });
            if (res.success) toast.success("Nom du badge mis à jour");
            else toast.error(res.error || "Erreur");
        } catch (e) {
            toast.error("Erreur de communication");
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center p-12">
                <Loader2 className="w-6 h-6 animate-spin text-zinc-500" />
            </div>
        );
    }

    const previewUser = "Voyageur";
    const previewGuild = "SigilOS";

    const insertVariable = (variable: string, target: 'dash' | 'discord') => {
        if (target === 'dash') {
            setWelcomeTemplate(prev => prev + variable);
        } else {
            setWelcomeDiscordTemplate(prev => prev + variable);
        }
        toast.info(`Variable ${variable} ajoutée !`);
    };

    const renderPreview = (content: string, isDiscord: boolean) => {
        if (!content || !content.trim()) {
            return <p className="text-zinc-600 italic text-sm">Le message apparaîtra ici...</p>;
        }

