}

"use client";

import { useState, useTransition, useMemo } from "react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { updateRBACMapping } from "@/server/actions/admin-actions";
import { PERMISSIONS, PERMISSION_DETAILS, PERMISSION_MODULES, MODULE_ORDER as PERM_MODULE_ORDER, type PermissionId, type PermissionModule } from "@/lib/permissions";
import { PermissionCard } from "./permission-card";
import { cn } from "@/lib/utils";
import { Save, Filter, ChevronDown, ChevronRight, Search, X, Users, ShieldAlert, Loader2 } from "lucide-react";
import { Input } from "@/components/ui/input";

type Role = {
    id: string;
    name: string;
    color: number;
};

type Props = {
    guildId: string;
    roles: Role[];
    members: any[];
    currentMapping: Record<string, PermissionId[]>;
    currentUsersMapping: Record<string, PermissionId[]>;
};

const MODULE_ORDER = PERM_MODULE_ORDER;

export function PermissionsManager({ guildId, roles, members, currentMapping, currentUsersMapping }: Props) {
    // Transform: DB (Role -> Perms)  ==>  UI (Perm -> Roles)
    const initialPermState: Record<PermissionId, string[]> = Object.values(PERMISSIONS).reduce((acc, perm) => {
        acc[perm] = [];
        return acc;
    }, {} as Record<PermissionId, string[]>);

    Object.entries(currentMapping).forEach(([roleId, perms]) => {
        perms.forEach(perm => {
            // Only include permissions that still exist in the new system
            if (initialPermState[perm]) {
                initialPermState[perm].push(roleId);
            }
        });
    });

    // Transform: DB (User -> Perms) ==> UI (Perm -> Users)
    const initialUserState: Record<PermissionId, string[]> = Object.values(PERMISSIONS).reduce((acc, perm) => {
        acc[perm] = [];
        return acc;
    }, {} as Record<PermissionId, string[]>);

    Object.entries(currentUsersMapping).forEach(([discordUserId, perms]) => {
        perms.forEach(perm => {
            // Only include permissions that still exist in the new system
            if (initialUserState[perm]) {
                initialUserState[perm].push(discordUserId);
            }
        });
    });

    const [permState, setPermState] = useState(initialPermState);
    const [userState, setUserState] = useState(initialUserState);
    const [isPending, startTransition] = useTransition();
    const [activeModule, setActiveModule] = useState<PermissionModule | "all">("all");
    const [searchQuery, setSearchQuery] = useState("");
    // Track which module sections are collapsed (only relevant in "all" view)
    const [collapsed, setCollapsed] = useState<Record<PermissionModule, boolean>>({} as Record<PermissionModule, boolean>);

    // Roles that currently have DASHBOARD_ACCESS assigned
    const rolesWithDashboardAccess = new Set(permState[PERMISSIONS.DASHBOARD_LOGIN] || []);

    const handlePermChange = (permId: PermissionId, newRoleIds: string[]) => {
        setPermState(prev => {
            const next = { ...prev, [permId]: newRoleIds };
            // Auto-add DASHBOARD_ACCESS when any permission is granted to a role
            if (permId !== PERMISSIONS.DASHBOARD_LOGIN && newRoleIds.length > 0) {
                const currentAccess = new Set(prev[PERMISSIONS.DASHBOARD_LOGIN] || []);
                newRoleIds.forEach(roleId => currentAccess.add(roleId));
                next[PERMISSIONS.DASHBOARD_LOGIN] = Array.from(currentAccess);
            }
            return next;
        });
    };

    const handleUserChange = (permId: PermissionId, newUserIds: string[]) => {
        setUserState(prev => ({ ...prev, [permId]: newUserIds }));
    };

    const handleSave = () => {
        startTransition(async () => {
            // Reconstruct rolesMapping
            const rolesMapping: Record<string, PermissionId[]> = {};
            Object.entries(permState).forEach(([permId, roleIds]) => {
                roleIds.forEach(roleId => {
                    if (!rolesMapping[roleId]) rolesMapping[roleId] = [];
                    if (!rolesMapping[roleId].includes(permId as PermissionId)) {
                        rolesMapping[roleId].push(permId as PermissionId);
                    }
                });
            });

            // Reconstruct usersMapping
            const usersMapping: Record<string, PermissionId[]> = {};
            Object.entries(userState).forEach(([permId, userIds]) => {
                userIds.forEach(userId => {
                    const discordUserId = userId; // The ID passed should be the discord provider account ID
                    if (!usersMapping[discordUserId]) usersMapping[discordUserId] = [];
                    if (!usersMapping[discordUserId].includes(permId as PermissionId)) {
                        usersMapping[discordUserId].push(permId as PermissionId);
                    }
                });
            });

            const res = await updateRBACMapping(guildId, rolesMapping, usersMapping);
            if (res.success) {
                toast.success("Permissions sauvegardées");
            } else {
                toast.error(res.error || "Erreur lors de la sauvegarde");
            }
        });
    };

    const toggleCollapse = (mod: PermissionModule) => {
        setCollapsed(prev => ({ ...prev, [mod]: !prev[mod] }));
    };

    const roleOptions = roles.map(r => ({ label: r.name, value: r.id, color: r.color }));
    const memberOptions = members.map(m => {
        // Find discord account ID
        const discordAccount = m.user.accounts.find((a: any) => a.provider === "discord");
        return {
            label: m.pseudoDofus || m.discordNickname || m.user.name || "Inconnu",
            value: discordAccount?.providerAccountId || m.userId,
            image: m.user.image
        };
    });

    const permissionsByModule = useMemo(() => {
        const grouped = {} as Record<PermissionModule, PermissionId[]>;
        MODULE_ORDER.forEach(m => grouped[m] = []);
        Object.entries(PERMISSION_DETAILS).forEach(([permId, details]) => {
            grouped[details.module].push(permId as PermissionId);
        });
        return grouped;
    }, []);

    const visiblePermissions = useMemo(() => {
        const base = activeModule === "all"
            ? Object.keys(PERMISSION_DETAILS) as PermissionId[]
            : permissionsByModule[activeModule] || [];

        if (!searchQuery.trim()) return base;

        const q = searchQuery.toLowerCase().trim();
        return base.filter(permId => {
            const detail = PERMISSION_DETAILS[permId];
            // Match on permission label
            if (detail.label.toLowerCase().includes(q)) return true;
            // Match on description
            if (detail.description.toLowerCase().includes(q)) return true;
            // Match on permission ID (technical)
            if (permId.toLowerCase().includes(q)) return true;
            // Match on assigned role names
            const assignedRoleIds = permState[permId] || [];
            const assignedRoleNames = assignedRoleIds
                .map(id => roles.find(r => r.id === id)?.name || "")
                .join(" ");
            if (assignedRoleNames.toLowerCase().includes(q)) return true;
            return false;
        });
    }, [activeModule, permissionsByModule, searchQuery, permState, roles]);

    const isSearchActive = searchQuery.trim().length > 0;

    const moduleStats = useMemo(() => {
        const stats = {} as Record<PermissionModule, number>;
        MODULE_ORDER.forEach(m => stats[m] = 0);
        Object.entries(permState).forEach(([permId, roleIds]) => {
            const module = PERMISSION_DETAILS[permId as PermissionId]?.module;
            if (module && roleIds.length > 0) stats[module]++;
        });
        return stats;
    }, [permState]);

    const totalConfigured = useMemo(() => Object.values(permState).filter(r => r.length > 0).length, [permState]);

    // Roles that have any permission but are missing DASHBOARD_ACCESS (need migration)
    const rolesNeedingMigration = useMemo(() => {
        const allMappedRoles = new Set<string>();
        Object.entries(permState).forEach(([permId, roleIds]) => {
            if (permId !== PERMISSIONS.DASHBOARD_LOGIN && roleIds.length > 0) {
                roleIds.forEach(id => allMappedRoles.add(id));
            }
        });
        const withAccess = new Set(permState[PERMISSIONS.DASHBOARD_LOGIN] || []);
        return [...allMappedRoles].filter(rId => !withAccess.has(rId));
    }, [permState]);

    return (
        <div className="space-y-8 relative">
            {/* Background Ambient Glow */}
            <div className="absolute -top-40 -right-40 w-96 h-96 bg-primary/5 blur-[120px] rounded-full pointer-events-none" />
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] bg-white/[0.02] radial-gradient blur-[160px] rounded-full pointer-events-none" />

            {/* ⚠️ Warning Banner: roles missing DASHBOARD_ACCESS */}
            {rolesNeedingMigration.length > 0 && (
                <div className="flex items-start gap-4 bg-amber-500/10 border border-amber-500/30 rounded-2xl px-6 py-4">
                    <span className="text-2xl mt-0.5">⚠️</span>
                    <div>
                        <p className="text-amber-400 font-black uppercase tracking-widest text-sm">
                            Accès non explicite détecté
                        </p>
                        <p className="text-amber-400/80 text-xs mt-1 leading-relaxed">
                            {rolesNeedingMigration.length > 0 && (
                                <>
                                    {rolesNeedingMigration.map(rId => roles.find(r => r.id === rId)?.name || rId).join(", ")} — 
                                    {" "}Ces rôles ont des permissions mais n'ont pas <strong>🚪 Accès Dashboard</strong> coché.
                                    Les nouvelles permissions cochées ci-dessus l'ont automatiquement ajouté.
                                    <strong> Pensez à sauvegarder.</strong>
                                </>
                            )}
                        </p>
                    </div>
                </div>
            )}

            {/* Sticky Action Bar — Sigma 2026 Style */}
            <div className="flex flex-col sm:flex-row justify-between items-center bg-zinc-800/90 backdrop-blur-2xl px-6 py-5 rounded-[2rem] border border-white/20 sticky top-4 z-20 gap-4 shadow-[0_30px_60px_-15px_rgba(0,0,0,0.7)]">
                <div className="flex items-center gap-5">
                    <div className="p-3 bg-primary/20 rounded-2xl border border-primary/40 shadow-[0_0_20px_rgba(var(--primary),0.3)]">
                        <ShieldAlert className="w-6 h-6 text-primary" />
                    </div>
                    <div>
                        <h2 className="text-base font-black text-white leading-none tracking-tight uppercase">Matrice des Droits</h2>
                        <div className="flex items-center gap-3 mt-2">
                            <div className="h-2 w-48 bg-white/10 rounded-full overflow-hidden border border-white/5">
                                <div 
                                    className="h-full bg-primary transition-all duration-700"
                                    style={{ 
                                        width: `${(totalConfigured / Object.values(PERMISSIONS).length) * 100}%`,
                                        boxShadow: `0 0 15px var(--primary)`
                                    }}
                                />
                            </div>
                            <span className="text-[10px] font-black text-white tracking-widest uppercase">
                                {totalConfigured} / {Object.values(PERMISSIONS).length} Activés
                            </span>
                        </div>
                    </div>
                </div>
                
                <div className="flex items-center gap-3 w-full sm:w-auto">
                    <div className="relative flex-1 sm:w-72">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-300" />
                        <Input
                            value={searchQuery}
                            onChange={e => setSearchQuery(e.target.value)}
                            placeholder="Search nodes..."
                            className="pl-11 bg-black/40 border-white/10 h-12 rounded-2xl text-sm focus-visible:ring-primary/40 w-full placeholder:text-zinc-500 text-white"
                        />
                    </div>
                    <Button
                        onClick={handleSave}
                        disabled={isPending}
                        className="bg-white hover:bg-primary text-black font-black rounded-2xl h-12 px-8 transition-all hover:scale-[1.05] active:scale-95 shadow-[0_0_20px_rgba(255,255,255,0.3)]"
                    >
                        {isPending ? <Loader2 className="w-5 h-5 animate-spin" /> : <Save className="w-5 h-5 mr-3" />}
                        {isPending ? "SYNCHRONIZING..." : "SAUVEGARDER"}
                    </Button>
                </div>
            </div>

            {/* Module Filter Island */}
            <div className="flex flex-wrap gap-2.5 p-2.5 bg-zinc-800/40 backdrop-blur-md rounded-2xl border border-white/10 overflow-x-auto no-scrollbar shadow-xl">
                <button
                    onClick={() => setActiveModule("all")}
                    className={cn(
                        "px-5 py-2.5 rounded-xl text-[11px] font-black tracking-widest uppercase transition-all whitespace-nowrap border",
                        activeModule === "all"
                            ? "bg-white text-black border-white shadow-[0_0_25px_rgba(255,255,255,0.25)]"
                            : "bg-transparent text-zinc-400 border-transparent hover:text-white hover:bg-white/10"
                    )}
                >
                    ALL MODULES
                </button>
                {MODULE_ORDER.map(moduleKey => {
                    const module = PERMISSION_MODULES[moduleKey];
                    const isActive = activeModule === moduleKey;
                    return (
                        <button
                            key={moduleKey}
                            onClick={() => setActiveModule(moduleKey)}
                            className={cn(
                                "px-5 py-2.5 rounded-xl text-[11px] font-black tracking-widest uppercase transition-all whitespace-nowrap flex items-center gap-2.5 border",
                                isActive
                                    ? "text-white shadow-lg border-white/20"
                                    : "text-zinc-400 border-transparent hover:text-white hover:bg-white/10"
                            )}
                            style={{ 
                                backgroundColor: isActive ? `${module.color}40` : undefined,
                                borderColor: isActive ? `${module.color}80` : undefined,
                                boxShadow: isActive ? `0 0 25px ${module.color}30` : undefined
                            }}
                        >
                            <span className="text-sm">{module.icon}</span>
                            <span>{module.label}</span>
                        </button>
                    );
                })}
            </div>

            {/* Content Area */}
            {isSearchActive ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {visiblePermissions.length === 0 ? (
                        <div className="col-span-full py-32 text-center bg-zinc-800/20 rounded-[2rem] border border-dashed border-white/20">
                            <Search className="w-12 h-12 text-zinc-700 mx-auto mb-4" />
                            <p className="text-zinc-400 font-extrabold uppercase tracking-widest text-sm">No assignments found for "{searchQuery}"</p>
                        </div>
                    ) : (
                        visiblePermissions.map(permId => (
                            <PermissionCard
                                key={permId}
                                permissionId={permId}
                                allRoles={roleOptions}
                                allUsers={memberOptions}
                                selectedRoleIds={permState[permId] || []}
                                selectedUserIds={userState[permId] || []}
                                onRolesChange={(ids) => handlePermChange(permId, ids)}
                                onUsersChange={(ids) => handleUserChange(permId, ids)}
                                onSave={handleSave}
                                moduleColor={PERMISSION_MODULES[PERMISSION_DETAILS[permId].module].color}
                                locked={permId !== PERMISSIONS.DASHBOARD_LOGIN && rolesWithDashboardAccess.size === 0}
                                hideUsers={permId === PERMISSIONS.DASHBOARD_LOGIN}
                            />
                        ))
                    )}
                </div>
            ) : activeModule === "all" ? (
                <div className="space-y-20">
                    {MODULE_ORDER.map(moduleKey => {
                        const module = PERMISSION_MODULES[moduleKey];
                        const modulePerms = permissionsByModule[moduleKey];
                        if (modulePerms.length === 0) return null;
                        const configuredCount = moduleStats[moduleKey];

                        return (
                            <section key={moduleKey} className="space-y-8">
                                <div className="flex items-center justify-between px-4">
                                    <div className="flex items-center gap-4">
                                        <div 
                                            className="w-14 h-14 rounded-2xl flex items-center justify-center text-2xl shadow-2xl relative overflow-hidden group"
                                            style={{ backgroundColor: `${module.color}20`, border: `1px solid ${module.color}40` }}
                                        >
                                            <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform" />
                                            <span className="relative z-10">{module.icon}</span>
                                        </div>
                                        <div>
                                            <h2 className="text-2xl font-black tracking-tighter uppercase italic" style={{ color: module.color }}>
                                                {module.label}
                                            </h2>
                                            <div className="flex items-center gap-2 mt-1">
                                                <span className="px-2 py-0.5 bg-zinc-800 text-zinc-300 text-[9px] font-black rounded uppercase tracking-tighter border border-white/10">
                                                    {modulePerms.length} NODES
                                                </span>
                                                <span className="text-[10px] text-zinc-400 font-bold uppercase tracking-widest">
                                                    Protocol Matrix Ready
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                    
                                    <div className="hidden md:flex flex-col items-end gap-2">
                                        <div className="text-[10px] font-black text-white tracking-[0.2em] uppercase opacity-40">Validation Status</div>
                                        <div className="flex gap-2">
                                            {Array.from({ length: modulePerms.length }).map((_, i) => (
                                                <div 
                                                    key={i}
                                                    className="h-2 w-7 rounded-[2px] transition-all duration-500 border border-white/5"
                                                    style={{ 
                                                        backgroundColor: i < configuredCount ? module.color : 'rgba(255,255,255,0.08)',
                                                        boxShadow: i < configuredCount ? `0 0 12px ${module.color}50` : 'none'
                                                    }}
                                                />
                                            ))}
                                        </div>
                                    </div>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                    {modulePerms.map(permId => (
                                        <PermissionCard
                                            key={permId}
                                            permissionId={permId}
                                            allRoles={roleOptions}
                                            allUsers={memberOptions}
                                            selectedRoleIds={permState[permId] || []}
                                            selectedUserIds={userState[permId] || []}
                                            onRolesChange={(ids) => handlePermChange(permId, ids)}
                                            onUsersChange={(ids) => handleUserChange(permId, ids)}
                                            onSave={handleSave}
                                            moduleColor={module.color}
                                            locked={permId !== PERMISSIONS.DASHBOARD_LOGIN && rolesWithDashboardAccess.size === 0}
                                            hideUsers={permId === PERMISSIONS.DASHBOARD_LOGIN}
                                        />
                                    ))}
                                </div>
                                
                                {moduleKey !== MODULE_ORDER[MODULE_ORDER.length - 1] && (
                                    <div className="h-px w-full bg-gradient-to-r from-transparent via-white/5 to-transparent pt-12" />
                                )}
                            </section>
                        );
                    })}
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {visiblePermissions.map(permId => (
                        <PermissionCard
                            key={permId}
                            permissionId={permId}
                            allRoles={roleOptions}
                            allUsers={memberOptions}
                            selectedRoleIds={permState[permId] || []}
                            selectedUserIds={userState[permId] || []}
                            onRolesChange={(ids) => handlePermChange(permId, ids)}
                            onUsersChange={(ids) => handleUserChange(permId, ids)}
                            onSave={handleSave}
                            moduleColor={PERMISSION_MODULES[PERMISSION_DETAILS[permId].module].color}
                            locked={permId !== PERMISSIONS.DASHBOARD_LOGIN && rolesWithDashboardAccess.size === 0}
                            hideUsers={permId === PERMISSIONS.DASHBOARD_LOGIN}
                        />
                    ))}
                </div>
            )}
        </div>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Loader2, Save, AlertTriangle, Hash, Bell, Users } from "lucide-react";
import { toast } from "sonner";
import { getPollSettings, updatePollSettings } from "@/server/actions/poll-actions";
import { cn } from "@/lib/utils";
import { getDiscordRolesAction, updateAllowedPingRolesAction } from "@/server/actions/user-actions";
import { PingRolesSelector } from "@/components/admin/ping-roles-selector";

interface PollSettingsClientProps {
    guildId: string;
}

export function PollSettingsClient({ guildId }: PollSettingsClientProps) {
    const [channelId, setChannelId] = useState<string>("");
    const [roleId, setRoleId] = useState<string>("");
    const [isLoading, setIsLoading] = useState(true);
    const [isPending, startTransition] = useTransition();
    const [isConfigured, setIsConfigured] = useState(false);
    const [pollsPingRoleIds, setPollsPingRoleIds] = useState<string[]>([]);
    const [discordRoles, setDiscordRoles] = useState<{ id: string, name: string, color: string }[]>([]);

    useEffect(() => {
        async function loadConfig() {
            const [result, rolesRes] = await Promise.all([
                getPollSettings(guildId),
                getDiscordRolesAction(guildId, { ignoreWhitelist: true })
            ]);
            if (result.success && result.data) {
                setChannelId(result.data.pollsNotifyChannelId || "");
                setRoleId(result.data.pollsNotifyRoleId || "");
                setIsConfigured(!!result.data.pollsNotifyChannelId);
                setPollsPingRoleIds(result.data.pollsPingRoleIds || []);
            }
            if (rolesRes.success && rolesRes.roles) {
                setDiscordRoles(rolesRes.roles.filter((r: any) => r.name !== "@everyone") as any);
            }
            setIsLoading(false);
        }
        loadConfig();
    }, [guildId]);

    const handleSave = () => {
        startTransition(async () => {
            const result = await updatePollSettings(guildId, {
                pollsNotifyChannelId: channelId.trim() || null,
                pollsNotifyRoleId: roleId.trim() || null
            });
            const pingRolesResult = await updateAllowedPingRolesAction(guildId, pollsPingRoleIds, "polls");

            if (result.success && pingRolesResult.success) {
                toast.success("Configuration des sondages sauvegardée !");
                setIsConfigured(!!channelId.trim());
            } else {
                toast.error(result.error || pingRolesResult.error || "Erreur lors de la sauvegarde");
            }
        });
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center min-h-[300px]">
                <Loader2 className="w-8 h-8 animate-spin text-cyan-500" />
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <Card className="bg-zinc-900/60 border-white/5">
                <CardHeader>
                    <div className="flex items-center justify-between">
                        <CardTitle className="flex items-center gap-2">
                            <span className="bg-cyan-500/20 text-cyan-400 p-2 rounded-lg">
                                <Bell className="w-5 h-5" />
                            </span>
                            Notifications de Sondages
                        </CardTitle>
                        {isConfigured ? (
                            <Badge className="bg-emerald-500/10 text-emerald-400 border-emerald-500/20">
                                Connecté à Discord
                            </Badge>
                        ) : (
                            <Badge variant="outline" className="text-zinc-500">
                                Mode Manuel
                            </Badge>
                        )}
                    </div>
                    <CardDescription>
                        Configurez les paramètres par défaut pour la publication de vos sondages sur Discord.
                    </CardDescription>
                </CardHeader>

                <CardContent className="space-y-6">
                    {/* Channel ID */}
                    <div className="space-y-2">
                        <Label className="text-zinc-400 flex items-center gap-2">
                            <Hash className="w-3.5 h-3.5" />
                            Salon d'annonce par défaut
                        </Label>
                        <Input
                            value={channelId}
                            onChange={(e) => setChannelId(e.target.value)}
                            placeholder="ID du salon Discord (ex: 123456789...)"
                            className="font-mono bg-black/20 border-white/10 focus:border-cyan-500/50"
                        />
                        <p className="text-[10px] text-zinc-500 italic">
                            Le salon où les nouveaux sondages seront publiés automatiquement si l'option est cochée lors de la création.
                        </p>
                    </div>

                    {/* Role ID */}
                    <div className="space-y-2">
                        <Label className="text-zinc-400 flex items-center gap-2">
                            <Users className="w-3.5 h-3.5" />
                            Rôle à mentionner par défaut
                        </Label>
                        <Input
                            value={roleId}
                            onChange={(e) => setRoleId(e.target.value)}
                            placeholder="ID du rôle (laisser vide pour ne mentionner personne)"
                            className="font-mono bg-black/20 border-white/10 focus:border-cyan-500/50"
                        />
                        <p className="text-[10px] text-zinc-500 italic">
                            Identifiant du rôle Discord à notifier (pings) lors de la publication d'un sondage.
                        </p>
                    </div>

                    {/* Whitelist of Ping Roles */}
                    <div className="space-y-2 pt-2 border-t border-white/5">
                        <Label className="text-zinc-400 flex items-center gap-2">
                            <Users className="w-3.5 h-3.5 text-cyan-400" />
                            Rôles autorisés pour les mentions (Whitelist)
                        </Label>
                        <p className="text-[10px] text-zinc-500 italic mb-2">
                            Définissez quels rôles Discord les créateurs de sondages peuvent mentionner lors de la publication.
                        </p>
                        <PingRolesSelector
                            value={pollsPingRoleIds}
                            onChange={setPollsPingRoleIds}
                            roles={discordRoles}
                            description="Si la liste est vide, aucun rôle Discord ne sera disponible pour le ping/sélection dans les modales de création (seuls les administrateurs verront toujours tous les rôles)."
                        />
                    </div>

                    <div className="pt-4 flex items-center justify-between border-t border-white/5">
                        <div className="flex items-center gap-2 text-amber-500/80">
                            <AlertTriangle className="w-4 h-4" />
                            <span className="text-[10px] font-medium uppercase tracking-wider">
                                Vérifiez que le bot a les droits d'écriture
                            </span>
                        </div>
                        <Button
                            onClick={handleSave}
                            disabled={isPending}
                            className="bg-cyan-600 hover:bg-cyan-500 text-white min-w-[140px]"
                        >
                            {isPending ? (
                                <Loader2 className="w-4 h-4 animate-spin mr-2" />
                            ) : (
                                <Save className="w-4 h-4 mr-2" />
                            )}
                            Sauvegarder
                        </Button>
                    </div>
                </CardContent>
            </Card>

            {/* Help Card */}
            <Card className="bg-blue-500/5 border-blue-500/10">
                <CardContent className="p-4 flex gap-3">
                    <div className="p-2 bg-blue-500/20 rounded-lg shrink-0 h-fit">
                        <Hash className="w-4 h-4 text-blue-400" />
                    </div>
                    <div className="space-y-1">
                        <h4 className="text-sm font-medium text-blue-200">Comment obtenir les IDs ?</h4>
                        <p className="text-xs text-blue-300/70 leading-relaxed">
                            Activez le <strong>Mode Développeur</strong> dans vos paramètres Discord (Apparence {'>'} Avancé).
                            Ensuite, faites un clic droit sur un salon ou un rôle et choisissez <strong>"Copier l'identifiant"</strong>.
                        </p>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState } from "react";
import {
    Sparkles,
    Calendar,
    ShieldCheck,
    Loader2,
    Info
} from "lucide-react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
    DialogFooter
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { grantWelcomeBadge } from "@/server/actions/onboarding-admin-actions";

interface WelcomeBadgeDialogProps {
    guildId: string;
    profileId: string;
    memberName: string;
    roleName: string;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSuccess?: () => void;
}

export function WelcomeBadgeDialog({
    guildId,
    profileId,
    memberName,
    roleName,
    open,
    onOpenChange,
    onSuccess
}: WelcomeBadgeDialogProps) {
    const [days, setDays] = useState(30);
    const [loading, setLoading] = useState(false);

    const handleGrant = async () => {
        setLoading(true);
        try {
            const res = await grantWelcomeBadge({
                guildId,
                profileId,
                days
            });
            if (res.success) {
                toast.success(`Le badge "${roleName}" a été attribué à ${memberName} pour ${days} jours.`);
                onOpenChange(false);
                onSuccess?.();
            } else {
                toast.error(res.error || "Erreur");
            }
        } catch (e) {
            toast.error("Erreur de communication");
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-[425px] bg-zinc-950 border-white/10 text-white">
                <DialogHeader>
                    <div className="w-12 h-12 rounded-2xl bg-amber-500/10 border border-amber-500/20 flex items-center justify-center mb-4">
                        <Sparkles className="w-6 h-6 text-amber-400" />
                    </div>
                    <DialogTitle className="text-xl font-black tracking-tight flex items-center gap-2">
                        Attribuer un badge spécial
                    </DialogTitle>
                    <DialogDescription className="text-zinc-500 italic">
                        Le membre recevra le badge "{roleName}" sur son profil pendant la durée choisie.
                    </DialogDescription>
                </DialogHeader>

                <div className="space-y-6 py-4">
                    <div className="p-4 rounded-xl bg-white/5 border border-white/10 flex items-center gap-4">
                        <div className="flex-1">
                            <p className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Membre ciblé</p>
                            <p className="text-sm font-bold text-white">{memberName}</p>
                        </div>
                        <div className="text-right">
                            <p className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Badge</p>
                            <p className="text-sm font-bold text-amber-400">{roleName}</p>
                        </div>
                    </div>

                    <div className="space-y-3">
                        <label className="text-xs font-bold text-amber-400 flex items-center gap-2">
                            <Calendar className="w-3 h-3" /> Durée (en jours)
                        </label>
                        <div className="flex gap-2">
                            {[7, 14, 30, 60].map((d) => (
                                <Button
                                    key={d}
                                    type="button"
                                    variant="outline"
                                    size="sm"
                                    onClick={() => setDays(d)}
                                    className={`flex-1 font-bold h-9 transition-all ${days === d ? "bg-amber-500/20 border-amber-500 text-amber-400" : "bg-zinc-900 border-white/5 text-zinc-500 hover:text-zinc-300"}`}
                                >
                                    {d}j
                                </Button>
                            ))}
                        </div>
                        <Input
                            type="number"
                            value={days}
                            onChange={(e) => setDays(parseInt(e.target.value) || 0)}
                            className="bg-zinc-900 border-white/10 text-center font-bold text-lg"
                        />
                    </div>

                    <div className="p-3 rounded-xl bg-blue-500/5 border border-blue-500/10 flex items-start gap-3">
                        <Info className="w-4 h-4 text-blue-400 shrink-0 mt-0.5" />
                        <p className="text-[10px] text-zinc-500 leading-relaxed italic">
                            Ce badge est purement visuel sur SigilOS et n'affecte pas les permissions Discord. Il sera automatiquement retiré à l'expiration.
                        </p>
                    </div>
                </div>

                <DialogFooter className="gap-2 sm:gap-0">
                    <Button
                        variant="ghost"
                        onClick={() => onOpenChange(false)}
                        className="font-bold text-zinc-500 hover:text-white"
                    >
                        Annuler
                    </Button>
                    <Button
                        onClick={handleGrant}
                        disabled={loading || days <= 0}
                        className="bg-amber-600 hover:bg-amber-500 text-white font-black px-8 gap-2"
                    >
                        {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <ShieldCheck className="w-4 h-4" />}
                        Appliquer le badge
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

