import { auth } from "@/auth";
import { redirect } from "next/navigation";
import { getUserContext } from "@/server/actions/user-actions";
import { logAdminAccessDenied } from "@/server/actions/audit-actions";
import AccessDenied from "@/components/access-denied";
import { AbsenceSettingsClient } from "./_components/absence-settings-client";
import { UnifiedModuleHeader } from "@/components/layout/unified-module-header";
import { Bell } from "lucide-react";

export default async function AbsenceSettingsPage({
    params
}: {
    params: Promise<{ guildId: string }>
}) {
    const session = await auth();
    if (!session?.user) redirect("/");

    const { guildId } = await params;

    // Verify permission
    const user = await getUserContext(guildId);
    if (!user.canManageRelance) {
        await logAdminAccessDenied(guildId, "/admin/absence");
        return <AccessDenied />;
    }

    return (
        <div className="space-y-6 pb-12">
            <UnifiedModuleHeader
                title="Notifications Absences"
                description="Configurez les notifications Discord pour les absences des membres."
                imageSrc="/assets/ui/icons/calendar.png"
                backHref={`/dashboard/${guildId}/admin/settings`}
            />
            <AbsenceSettingsClient guildId={guildId} />
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Unlink, ShieldAlert, Loader2, Search, User, X, AlertTriangle, ArrowRight } from "lucide-react";
import { adminForceUnlink, searchMetamobPseudos } from "@/server/actions/ocre-actions";
import { toast } from "sonner";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
    AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { cn } from "@/lib/utils";

export function MetamobUnlocker({ guildId }: { guildId: string }) {
    const [targetPseudo, setTargetPseudo] = useState("");
    const [suggestions, setSuggestions] = useState<string[]>([]);
    const [isSearching, setIsSearching] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [status, setStatus] = useState<"idle" | "success" | "error">("idle");
    const [showSuggestions, setShowSuggestions] = useState(false);

    useEffect(() => {
        const timer = setTimeout(async () => {
            if (targetPseudo.length >= 2) {
                setIsSearching(true);
                const res = await searchMetamobPseudos(guildId, targetPseudo);
                if (res.success && res.data) {
                    setSuggestions(res.data);
                    setShowSuggestions(res.data.length > 0);
                }
                setIsSearching(false);
            } else {
                setSuggestions([]);
                setShowSuggestions(false);
            }
        }, 300);

        return () => clearTimeout(timer);
    }, [targetPseudo, guildId]);

    const handleUnlock = async () => {
        if (!targetPseudo.trim()) return;

        setIsLoading(true);
        setStatus("idle");

        try {
            const result = await adminForceUnlink({
                guildId,
                targetPseudo: targetPseudo.trim()
            });

            if (result.success) {
                toast.success(`Compte "${targetPseudo}" libéré !`);
                setStatus("success");
                setTargetPseudo("");
            } else {
                toast.error(result.error || "Erreur lors du déblocage");
                setStatus("error");
            }
        } catch (e) {
            toast.error("Erreur technique");
            setStatus("error");
        } finally {
            setIsLoading(false);
        }
    }

    return (
        <Card className="bg-zinc-950/40 border-amber-500/10 overflow-visible relative group">
            <div className="absolute inset-0 bg-gradient-to-br from-amber-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
            
            <CardHeader className="pb-4">
                <div className="flex items-center gap-3">
                    <div className="p-2 rounded-xl bg-amber-500/10 border border-amber-500/20 text-amber-500">
                        <ShieldAlert className="w-5 h-5" />
                    </div>
                    <div>
                        <CardTitle className="text-white font-black uppercase tracking-tighter text-base">
                            Déblocage d'Urgence
                        </CardTitle>
                        <CardDescription className="text-[10px] font-medium text-zinc-500">
                            Libérez un pseudo Metamob lié par erreur ou par un ancien membre.
                        </CardDescription>
                    </div>
                </div>
            </CardHeader>

            <CardContent className="space-y-6 relative">
                <div className="flex flex-col sm:flex-row gap-3 relative">
                    <div className="relative flex-1">
                        <div className="relative group/input">
                            <Input
                                placeholder="Rechercher un pseudo Metamob..."
                                value={targetPseudo}
                                onChange={(e) => setTargetPseudo(e.target.value)}
                                onFocus={() => targetPseudo.length >= 2 && setShowSuggestions(true)}
                                className={cn(
                                    "pl-10 h-12 bg-black/40 border-white/5 focus:border-amber-500/30 transition-all font-mono text-sm",
                                    status === "success" && "border-emerald-500/30"
                                )}
                            />
                            <Search className={cn(
                                "absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 transition-colors",
                                isSearching ? "text-amber-500 animate-pulse" : "text-zinc-600 group-focus-within/input:text-amber-500"
                            )} />
                            
                            {targetPseudo && (
                                <button 
                                    onClick={() => setTargetPseudo("")}
                                    className="absolute right-3 top-1/2 -translate-y-1/2 p-1 hover:bg-white/5 rounded-full text-zinc-500 hover:text-white transition-colors"
                                >
                                    <X className="w-3.5 h-3.5" />
                                </button>
                            )}
                        </div>

                        {/* Suggestions Dropdown (Refined) */}
                        {showSuggestions && suggestions.length > 0 && (
                            <div className="absolute top-full left-0 right-0 mt-2 bg-zinc-900 border border-white/10 rounded-xl shadow-2xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-2">
                                <div className="px-3 py-2 bg-white/5 border-b border-white/5 text-[9px] font-black uppercase tracking-widest text-zinc-500 flex justify-between">
                                    <span>Résultats Trouvés</span>
                                    <span>{suggestions.length}</span>
                                </div>
                                <div className="max-h-48 overflow-y-auto">
                                    {suggestions.map((s) => (
                                        <button
                                            key={s}
                                            onClick={() => {
                                                setTargetPseudo(s);
                                                setShowSuggestions(false);
                                            }}
                                            className="w-full text-left px-4 py-3 text-sm text-zinc-300 hover:bg-amber-500/10 hover:text-white flex items-center justify-between group/item transition-colors"
                                        >
                                            <div className="flex items-center gap-3">
                                                <div className="w-6 h-6 rounded-lg bg-zinc-800 flex items-center justify-center text-zinc-500 group-hover/item:text-amber-400">
                                                    <User className="w-3.5 h-3.5" />
                                                </div>
                                                <span className="font-mono">{s}</span>
                                            </div>
                                            <ArrowRight className="w-3.5 h-3.5 opacity-0 group-hover/item:opacity-100 -translate-x-2 group-hover/item:translate-x-0 transition-all text-amber-500" />
                                        </button>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>

                    <AlertDialog>
                        <AlertDialogTrigger asChild>
                            <Button
                                variant="destructive"
                                disabled={!targetPseudo.trim() || isLoading}
                                className="h-12 px-6 bg-red-600/10 hover:bg-red-600 text-red-500 hover:text-white border border-red-500/20 transition-all font-black uppercase tracking-widest text-[10px]"
                            >
                                {isLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Unlink className="h-4 w-4 mr-2" />}
                                Libérer le compte
                            </Button>
                        </AlertDialogTrigger>
                        <AlertDialogContent className="bg-zinc-950 border border-white/10 shadow-2xl">
                            <AlertDialogHeader>
                                <div className="w-12 h-12 rounded-2xl bg-red-500/10 border border-red-500/20 flex items-center justify-center mb-4">
                                    <AlertTriangle className="w-6 h-6 text-red-500" />
                                </div>
                                <AlertDialogTitle className="text-white text-xl font-black tracking-tighter uppercase">Confirmation Requise</AlertDialogTitle>
                                <AlertDialogDescription className="text-zinc-400 text-sm leading-relaxed">
                                    Vous allez détacher le compte Metamob <span className="text-red-400 font-mono font-bold bg-red-500/10 px-2 py-0.5 rounded">"{targetPseudo}"</span>. 
                                    <br /><br />
                                    Cette action est <span className="text-white underline">immédiate</span>. L'utilisateur qui l'utilisait perdra l'accès à sa collection synchronisée sur SigilOS jusqu'à ce qu'il se reconnecte.
                                </AlertDialogDescription>
                            </AlertDialogHeader>
                            <AlertDialogFooter className="mt-6">
                                <AlertDialogCancel className="bg-zinc-900 border-white/5 text-zinc-400 hover:bg-zinc-800 transition-colors">Annuler</AlertDialogCancel>
                                <AlertDialogAction onClick={handleUnlock} className="bg-red-600 hover:bg-red-500 text-white font-bold border-none shadow-lg shadow-red-600/20">
                                    Confirmer le déblocage
                                </AlertDialogAction>
                            </AlertDialogFooter>
                        </AlertDialogContent>
                    </AlertDialog>
                </div>

                {status === "success" && (
                    <div className="flex items-center gap-3 p-3 bg-emerald-500/5 border border-emerald-500/20 rounded-xl text-[11px] text-emerald-400 font-medium animate-in slide-in-from-top-2">
                        <div className="w-5 h-5 rounded-full bg-emerald-500/20 flex items-center justify-center shrink-0">
                            <ArrowRight className="w-3 h-3" />
                        </div>
                        Opération réussie. Le pseudo est désormais libre pour une nouvelle liaison.
                    </div>
                )}
            </CardContent>
        </Card>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Loader2, Save, AlertTriangle, Hash, Handshake, ExternalLink, ShieldCheck } from "lucide-react";
import { toast } from "sonner";
import { getOcreConfig, updateOcreChannel } from "@/server/actions/admin-actions";
import { cn } from "@/lib/utils";
import { Label } from "@/components/ui/label";

interface OcreSettingsClientProps {
    guildId: string;
}

export function OcreSettingsClient({ guildId }: OcreSettingsClientProps) {
    const [channelId, setChannelId] = useState<string>("");
    const [isLoading, setIsLoading] = useState(true);
    const [isPending, startTransition] = useTransition();
    const [isConfigured, setIsConfigured] = useState(false);

    useEffect(() => {
        async function loadConfig() {
            const result = await getOcreConfig(guildId);
            if (result.success && result.data) {
                setChannelId(result.data.ocreChannelId || "");
                setIsConfigured(!!result.data.ocreChannelId);
            }
            setIsLoading(false);
        }
        loadConfig();
    }, [guildId]);

    const handleSave = () => {
        startTransition(async () => {
            const result = await updateOcreChannel(guildId, channelId.trim() || null);
            if (result.success) {
                toast.success("Configuration sauvegardée !");
                setIsConfigured(!!channelId.trim());
            } else {
                toast.error(result.error || "Erreur lors de la sauvegarde");
            }
        });
    };

    const handleClear = () => {
        startTransition(async () => {
            const result = await updateOcreChannel(guildId, null);
            if (result.success) {
                setChannelId("");
                setIsConfigured(false);
                toast.success("Notifications Ocre désactivées");
            } else {
                toast.error(result.error || "Erreur lors de la désactivation");
            }
        });
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <Loader2 className="w-8 h-8 animate-spin text-emerald-500" />
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-2 duration-500 text-left">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Configuration Panel */}
                <div className="lg:col-span-2 space-y-6">
                    <Card className="bg-zinc-900/60 border-white/5 overflow-hidden group relative">
                        <div className="absolute inset-0 bg-gradient-to-br from-emerald-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
                        <CardHeader>
                            <div className="flex items-center justify-between">
                                <CardTitle className="flex items-center gap-2 text-white font-black uppercase tracking-tighter">
                                    <span className="bg-emerald-500/20 text-emerald-400 p-2 rounded-lg">
                                        <Hash className="w-5 h-5" />
                                    </span>
                                    Salon des Échanges Ocre
                                </CardTitle>
                                {isConfigured ? (
                                    <Badge className="bg-emerald-500/10 text-emerald-400 border-emerald-500/20">Actif</Badge>
                                ) : (
                                    <Badge variant="outline" className="text-zinc-600 border-white/5 uppercase text-[10px] font-black tracking-widest">Inactif</Badge>
                                )}
                            </div>
                            <CardDescription className="text-xs font-medium text-zinc-500">
                                Centralisez les demandes d'échange d'archimonstres de vos membres.
                            </CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-8">
                            <div className="space-y-6">
                                <div className="relative pl-6 border-l-2 border-white/5 pb-6 last:pb-0">
                                    <div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-zinc-800 border-2 border-zinc-950 flex items-center justify-center">
                                        <div className="w-1.5 h-1.5 rounded-full bg-zinc-400" />
                                    </div>
                                    <h3 className="text-sm font-medium text-white mb-2 text-left">1. Récupérer l'ID du salon</h3>
                                    <p className="text-xs text-zinc-500 mb-3 leading-relaxed">
                                        Créez un salon dédié (ex: <span className="text-emerald-400">🤝┊échanges-ocre</span>) pour que le bot puisse avertir les membres quand ils peuvent s'entraider.
                                    </p>
                                </div>

                                <div className="relative pl-6 border-l-2 border-emerald-500/50">
                                    <div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-emerald-500 border-2 border-zinc-950 shadow-[0_0_10px_rgba(16,185,129,0.5)]" />
                                    <h3 className="text-sm font-medium text-white mb-4 text-left">2. Coller l'identifiant</h3>

                                    <div className="space-y-4">
                                        <div className="flex flex-col sm:flex-row gap-3">
                                            <div className="relative flex-1 group/input">
                                                <Input
                                                    value={channelId}
                                                    onChange={(e) => setChannelId(e.target.value)}
                                                    placeholder="ID du salon (ex: 123...)"
                                                    className="font-mono bg-black/20 border-white/10 h-11 pl-10 focus:border-emerald-500/50 transition-colors"
                                                />
                                                <Hash className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-600 group-hover/input:text-emerald-400 transition-colors" />
                                            </div>
                                            <Button onClick={handleSave} disabled={isPending} className="min-w-[140px] bg-emerald-600 hover:bg-emerald-500 h-11 font-bold shadow-lg shadow-emerald-600/20">
                                                {isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                                                SAUVEGARDER
                                            </Button>
                                        </div>
                                        
                                        {isConfigured ? (
                                            <div className="flex justify-end">
                                                <Button variant="ghost" size="sm" onClick={handleClear} disabled={isPending} className="text-red-400 hover:text-red-300 hover:bg-red-900/20 h-auto py-1 px-3 text-[10px] font-black uppercase tracking-widest">
                                                    Désactiver l'intégration
                                                </Button>
                                            </div>
                                        ) : (
                                            <div className="p-3 rounded-xl bg-amber-500/5 border border-amber-500/10 flex items-start gap-3">
                                                <AlertTriangle className="w-3.5 h-3.5 text-amber-500 mt-0.5 shrink-0" />
