                            {filteredModules.map((mod) => {
                                const isEnabled = modules[mod.key];
                                const isLoading = pending === mod.key && isPending;
                                const Icon = mod.icon;

                                return (
                                    <div
                                        key={mod.key}
                                        className={cn(
                                            "group relative rounded-[2rem] border transition-all duration-500 overflow-hidden",
