                                            <div className={cn(
                                                "absolute -inset-[100px] opacity-[0.03] group-hover:opacity-[0.08] transition-opacity duration-700 blur-[100px] pointer-events-none",
                                                mod.bgColor.replace("/10", "/100")
                                            )} />
