import { auth } from "@/auth";
import { getUserProfile, getProfileStats } from "@/server/actions/profile-actions";
import { getUserContext } from "@/server/actions/user-actions";
import { db } from "@/lib/prisma";
import { ProfileBentoGrid } from "@/components/profile/profile-bento-grid";
import { redirect } from "next/navigation";
import { AuroraBackground } from "@/components/ui/aurora-background";
import type { AvailabilityMap } from "@/lib/dofus-assets";
import AccessDenied from "@/components/access-denied";
import { UnifiedModuleHeader } from "@/components/layout/unified-module-header";
import { UserCircle } from "lucide-react";

export default async function ProfilePage({ params }: { params: Promise<{ guildId: string }> }) {
    const session = await auth();
    if (!session?.user) redirect("/");

    const { guildId } = await params;

    // Fetch all data in parallel to avoid waterfalls
    const [userContext, profileResponse, statsResponse, guildConfig] = await Promise.all([
        getUserContext(guildId),
        getUserProfile(guildId),
        getProfileStats(guildId),
        db.guildConfig.findUnique({ where: { discordGuildId: guildId }, select: { absenceChannelId: true } })
    ]);

    // RBAC: Must be authenticated member of the guild with profile view permission
    if (!userContext.isAuthenticated || !userContext.isMember || !userContext.canViewProfile) {
        return <AccessDenied />;
    }

    if (!profileResponse.success || !profileResponse.data) {
        return (
            <div className="p-8 text-center text-red-400">
                <h2 className="text-xl font-bold">Erreur de chargement</h2>
                <p>{profileResponse.error}</p>
            </div>
        );
    }

    const profile = profileResponse.data;
    const stats = statsResponse.success && statsResponse.data
        ? {
            ...statsResponse.data,
            joinedAt: (userContext.joinedAt ?? statsResponse.data.joinedAt) as string | null,
            totalGuildMissions: (statsResponse.data as any).totalGuildMissions ?? 0
        }
        : {
            xp: profile.xp || 0,
            weeklyXp: 0,
            guildatons: profile.guildatons || 0,
            missionsValidated: 0,
            weeklyMissions: 0,
            lastActivity: null as { description: string; date: string | Date } | null,
            joinedAt: (userContext.joinedAt || null) as string | null,
            isTopContributor: false,
            weeklyActivity: [],
            missionsByCategory: [],
            totalGuildMissions: 0,
            discordStats: statsResponse.success && (statsResponse.data as any).discordStats ? (statsResponse.data as any).discordStats : {
                weekly: { messages: 0, voice: 0 },
                monthly: { messages: 0, voice: 0 },
                total: { messages: 0, voice: 0 }
            }
        };

    return (
        <div className="relative min-h-[calc(100vh-4rem)] pb-12">
            <AuroraBackground className="absolute inset-0 z-0 opacity-20 pointer-events-none" />

            <div className="relative z-10 max-w-6xl mx-auto space-y-8">
                <UnifiedModuleHeader
                    title="Mon Profil"
                    description="Gérez votre identité de guilde, votre classe et vos métiers."
                    imageSrc="/assets/ui/icons/profile.png"
                    backHref={`/dashboard/${guildId}`}
                />

                <ProfileBentoGrid
                    profile={{
                        id: profile.id,
                        userId: profile.userId,
                        pseudoDofus: profile.pseudoDofus,
                        classe: profile.classe,
                        classeSecondaires: (profile.classeSecondaires as string[]) || [],
                        metiers: (profile.metiers as string[]) || [],
                        forgemagieStatus: profile.forgemagieStatus,
                        fmPriceClassic: profile.fmPriceClassic,
                        fmPriceTrans: profile.fmPriceTrans,
                        fmPriceExo: profile.fmPriceExo,
                        availability: (profile.availability as AvailabilityMap) || {},
                        vacationStart: profile.vacationStart ? new Date(profile.vacationStart) : null,
                        vacationEnd: profile.vacationEnd ? new Date(profile.vacationEnd) : null,
                        vacationNotify: profile.vacationNotify || false,
                        metamobPseudo: profile.metamobPseudo,
                        metamobVerified: profile.metamobVerified,
                        metamobLastSync: profile.metamobLastSync ? new Date(profile.metamobLastSync) : null,
                        altPseudos: (profile.altPseudos as string[]) || [],
                        dofusBookLinks: (profile.dofusBookLinks as any) || [],
                        introduction: profile.introduction,
                        notificationPrefs: profile.notificationPrefs as any,
                        successPoints: profile.successPoints,
                        lastLadderUpdate: profile.lastLadderUpdate ? new Date(profile.lastLadderUpdate) : null,
                        roleGrants: profile.roleGrants || [],
                        skins: profile.skins || [],
                        alignment: profile.alignment,
                        alignmentOrder: profile.alignmentOrder,
                        alignmentLevel: profile.alignmentLevel,
                        hasLegendaryPet: profile.hasLegendaryPet ?? false,
                    }}
                    user={{
                        name: profile.user.name,
                        image: profile.user.image,
                    }}
                    stats={stats}
                    guildId={guildId}
                    guildName={userContext.guildName}
                    dofusServerId={userContext.dofusServerId}
                    discordNickname={userContext.name}
                    isAdmin={userContext.isAdmin}
                    permissions={{
                        canViewOcre: userContext.canViewOcre,
                        canViewSonges: userContext.canViewSonges,
                        canViewLadder: userContext.canViewLadder,
                        canSyncLadder: userContext.canSyncLadder,
                        canManualSyncLadder: userContext.canManualSyncLadder,
                        canViewMissions: userContext.canViewMissions,
                    }}
                    roleName={userContext.roleName}
                    roleColor={userContext.roleColor}
                    readOnly={false}
                    isSuperAdmin={userContext.isSuperAdmin}
                    hasAbsenceChannel={!!guildConfig?.absenceChannelId}
                />
            </div>
        </div>
    );
}

import { auth } from "@/auth";
import { redirect } from "next/navigation";
import AccessDenied from "@/components/access-denied";
import { getUserContext } from "@/server/actions/user-actions";
import { isModuleEnabled } from "@/server/actions/module-actions";
import { Gem, ArrowLeft, Trophy, TreePine, Sparkles } from "lucide-react";
import Link from "next/link";
import {
    getDofusDetailWithChains,
    getGuildHeatmapForDofus,
    updateDolmanaxProgress,
    getUserCompletedQuestIds,
} from "@/server/actions/dofus-quest-actions";
import { DofusQuestManagerV3 } from "@/components/dofus-quests/DofusQuestManagerV3";
import { DofusProgressRing } from "@/components/dofus-quests/DofusProgressRing";
import { DofusIcon } from "@/components/dofus-quests/DofusIcon";
import { DofusOcreMetamob } from "@/components/dofus-quests/DofusOcreMetamob";
import { DofusDolmanaxTracker } from "@/components/dofus-quests/DofusDolmanaxTracker";
import { notFound } from "next/navigation";
import { linkOcreAccount } from "@/server/actions/ocre-actions";
import { CharacterQuestSelector } from "@/components/dofus-quests/CharacterQuestSelector";

type Props = {
    params: Promise<{ guildId: string; dofusSlug: string }>;
    searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
};

export default async function DofusDetailPage({ params, searchParams }: Props) {
    const session = await auth();
    if (!session?.user) redirect("/");

    const { guildId, dofusSlug } = await params;
    const character = (await searchParams)?.character as string || "PRINCIPAL";

    const user = await getUserContext(guildId);
    if (!user.canViewQuests) return <AccessDenied />;

    const enabled = await isModuleEnabled(guildId, "quests");
    if (!enabled) return <AccessDenied />;

    const [result, heatmapResult, globalCompletedResult] = await Promise.all([
        getDofusDetailWithChains(guildId, dofusSlug, character),
        getGuildHeatmapForDofus(guildId, dofusSlug),
        getUserCompletedQuestIds(guildId, character),
    ]);

    if (!result.success || !result.data) return notFound();

    const { dofus, chains } = result.data;
    const color = dofus.color || "#6366f1";
    const heatmapData = heatmapResult.success ? heatmapResult.data ?? null : null;

    // Extract pages from notes if available (Format: "PAGES:X")
    let initialPages = 0;
    if (dofus.notes && dofus.notes.startsWith("PAGES:")) {
        initialPages = parseInt(dofus.notes.split(":")[1], 10) || 0;
    } else if (dofusSlug === "dolmanax") {
        initialPages = Math.round((dofus.progressPercent * 365) / 100);
    }

    return (
        <div className="space-y-6 pb-12">
            <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-4">
                <Link
                    href={`/dashboard/${guildId}/quetes-dofus${character !== "PRINCIPAL" ? `?character=${character}` : ""}`}
                    className="inline-flex items-center gap-2 text-base font-bold text-muted-foreground hover:text-foreground transition-all group/back"
                >
                    <ArrowLeft className="w-5 h-5 transition-transform group-hover/back:-translate-x-1" />
                    Retour à la liste des Dofus
                </Link>

                <div className="flex-shrink-0">
                    <CharacterQuestSelector 
                        mainCharacter={{ 
                            pseudo: user.pseudoDofus || user.name || "Principal", 
                            classe: user.classe 
                        }}
                        mules={user.altPseudos as any || []}
                    />
                </div>
            </div>

            {/* Dofus hero header */}
            <div
                className="relative overflow-hidden rounded-2xl px-6 py-8 flex flex-col sm:flex-row items-center gap-6"
                style={{
                    background: `linear-gradient(135deg, ${color}18 0%, var(--foreground)/[0.02] 60%, ${color}08 100%)`,
                    border: `1px solid ${color}33`,
                    boxShadow: `0 8px 32px ${color}18`,
                }}
            >
                {/* Top accent line */}
                <div
                    className="absolute top-0 left-0 right-0 h-[2px]"
                    style={{ background: `linear-gradient(90deg, transparent, ${color}88, transparent)` }}
                />
                {/* Ambient glow */}
                <div
                    className="absolute -top-12 -left-12 w-40 h-40 rounded-full pointer-events-none"
                    style={{ background: `radial-gradient(circle, ${color}20 0%, transparent 70%)` }}
                />

                {/* Dofus image + ring */}
                <div className="relative flex-shrink-0">
                    <DofusProgressRing
                        percent={dofus.progressPercent}
                        size={120}
                        strokeWidth={6}
                        color={color}
                        isObtained={dofus.isObtained}
                    />
                    <div className="absolute inset-0 flex items-center justify-center">
                        {(dofus as any).imageUrl ? (
                            <div className="relative w-16 h-16">
                                {/* eslint-disable-next-line @next/next/no-img-element */}
                                <img
                                    src={dofus.slug === "dofoozbz" ? "/module-dofus/Dofus_dofoozbz.png" : (dofus as any).imageUrl.replace(/^\/public/, "")}
                                    alt={dofus.nameShort || dofus.name}
                                    className="w-full h-full object-contain drop-shadow-[0_0_12px_rgba(255,255,255,0.3)]"
                                    style={{ filter: dofus.isObtained ? `drop-shadow(0 0 16px ${color})` : undefined }}
                                />
                            </div>
                        ) : dofus.name ? (
                            <DofusIcon
                                name={dofus.nameShort || "Argenté"}
                                size={64}
                                color={color}
                                isObtained={dofus.isObtained}
                            />
                        ) : (
                            <Gem className="w-12 h-12" style={{ color }} />
                        )}
                    </div>
                </div>

                {/* Info */}
                <div className="flex-1 text-center sm:text-left">
                    <div className="flex items-center gap-2 justify-center sm:justify-start mb-1 flex-wrap">
                        <span
                            className="text-[10px] font-semibold uppercase tracking-widest px-2 py-0.5 rounded-full"
                            style={{ background: `${color}20`, color, border: `1px solid ${color}44` }}
                        >
                            {dofus.isPrimordial ? "Primordial" : dofus.rarity}
                        </span>
                        {(dofus as any).isMeta && (
                            <span
                                className="flex items-center gap-1 text-[10px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full text-emerald-400"
                                style={{ background: "rgba(34,197,94,0.15)", border: "1px solid rgba(34,197,94,0.35)" }}
                            >
                                <TreePine className="w-2.5 h-2.5" /> Méta-Dofus
                            </span>
                        )}
                        {(dofus as any).isSylvestreReq && !(dofus as any).isMeta && (
                            <span
                                className="flex items-center gap-1 text-[10px] font-bold uppercase tracking-widest px-2 py-0.5 rounded-full text-emerald-500/70"
                                style={{ background: "rgba(34,197,94,0.08)", border: "1px solid rgba(34,197,94,0.2)" }}
                            >
                                <Sparkles className="w-2.5 h-2.5" /> Requis Sylvestre
                            </span>
                        )}
                        <span className="text-xs text-muted-foreground/50">Niveau {dofus.levelRecommended}+</span>
                    </div>
                    <h1 className="text-2xl sm:text-3xl font-black text-foreground mb-1 uppercase tracking-tight">{dofus.name}</h1>
                    {dofus.successName && (
                        <p className="text-sm text-muted-foreground">
                            Succès : <span style={{ color }} className="font-bold">{dofus.successName}</span>
                        </p>
                    )}
                    {(dofus as any).bonusSummary && (
                        <p className="text-xs text-muted-foreground/60 mt-1 font-medium">
                            ✦ {(dofus as any).bonusSummary}
                        </p>
                    )}
                    {dofus.description && (
                        <p className="text-sm text-muted-foreground/80 mt-2 max-w-4xl font-medium leading-relaxed">{dofus.description}</p>
                    )}

                    {/* Progress bar + stats */}
                    <div className="mt-4 flex flex-col gap-2 max-w-xl mx-auto sm:mx-0">
                        <div className="flex items-center justify-between text-xs text-muted-foreground">
                            <span className="font-black uppercase tracking-widest text-[10px]">Progression</span>
                            <span className="tabular-nums font-bold">{dofus.completedQuests}/{dofus.totalQuests} étapes</span>
                        </div>
                        <div className="h-2 rounded-full overflow-hidden bg-foreground/[0.08]">
                            <div
                                className="h-full rounded-full transition-all duration-700 shadow-[0_0_15px_var(--primary)/30]"
                                style={{
                                    width: `${dofus.progressPercent}%`,
                                    background: dofus.isObtained
                                        ? `linear-gradient(90deg, ${color}, #fbbf24)`
                                        : `linear-gradient(90deg, ${color}cc, ${color})`,
                                    boxShadow: `0 0 12px ${color}66`,
                                }}
                            />
                        </div>
                    </div>

                    {/* Obtained badge */}
                    {dofus.isObtained && (
                        <div
                            className="mt-3 inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-semibold"
                            style={{ background: `${color}22`, color, border: `1px solid ${color}44` }}
                        >
                            <Trophy className="w-4 h-4" />
                            Dofus obtenu !
                            {dofus.obtainedAt && (
                                <span className="text-xs opacity-60 ml-1">
                                    le {new Date(dofus.obtainedAt).toLocaleDateString("fr-FR")}
                                </span>
                            )}
                        </div>
                    )}
                </div>
            </div>


            {/* ── Special slug renderers ── */}
            {dofusSlug === "ocre" && (
                <div
                    className="rounded-3xl p-6 border transition-all duration-500"
                    style={{
                        background: `linear-gradient(135deg, ${color}10 0%, var(--foreground)/[0.05] 100%)`,
                        border: `1px solid ${color}25`,
                    }}
                >
                    <div className="text-[9px] font-black text-zinc-500 uppercase tracking-[0.4em] mb-4 flex items-center gap-2">
                        <span style={{ color }}>⬡</span> Progression Metamob
                    </div>
                    <DofusOcreMetamob
                        guildId={guildId}
                        metamobUsername={user.metamobPseudo || null}
                        onLinkMetamob={async (pseudo) => {
                            "use server";
                            return linkOcreAccount({ guildId, pseudo });
                        }}
                    />
                </div>
            )}

            {dofusSlug === "dolmanax" && (
                <div
                    className="rounded-3xl p-6 border transition-all duration-500"
                    style={{
                        background: `linear-gradient(135deg, ${color}10 0%, var(--foreground)/[0.05] 100%)`,
                        border: `1px solid ${color}25`,
                    }}
                >
                    <div className="text-[9px] font-black text-zinc-500 uppercase tracking-[0.4em] mb-4 flex items-center gap-2">
                        <span style={{ color }}>📖</span> Progression Almanax
                    </div>
                    <DofusDolmanaxTracker
                        guildId={guildId}
                        initialPages={initialPages}
                        onSave={async (pages) => {
                            "use server";
                            await updateDolmanaxProgress(guildId, dofus.id, pages, character);
                        }}
                    />
                </div>
            )}

            <DofusQuestManagerV3
                guildId={guildId}
                dofus={dofus}
                chains={chains}
                dofusColor={color}
                heatmapData={heatmapData}
                selectedCharacter={character}
                initialGlobalCompletedIds={globalCompletedResult.success ? globalCompletedResult.data : []}
            />
        </div>
    );
}

"use client";
import { useMemo, memo, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Users, X, ExternalLink, ChevronRight } from "lucide-react";

// ─── Types ────────────────────────────────────────────────────────────────────

type Milestone = {
  id: string;
  title: string;
  chapter: number;
  chapterLabel: string;
  accentColor?: string | null;
  dofusId?: string | null;
};

type GuildMemberProgress = {
  profileId: string;
  milestoneId: string;
  isCompleted: boolean;
  userName: string;
  userAvatar?: string;
};

// Dofus definitions
const DOFUS_DEFS: Record<string, { label: string; color: string; imageUrl: string }> = {
  ocre:               { label: "Ocre",               color: "#f59e0b", imageUrl: "/assets/icons/ocre.png" },
  turquoise:          { label: "Turquoise",          color: "#06b6d4", imageUrl: "/module-dofus/Dofus_Turquoise.png" },
  argente:            { label: "Argenté",            color: "#a1a1aa", imageUrl: "/module-dofus/Dofus_Argente.png" },
  argente_scintillant:{ label: "Arg. Scintillant",   color: "#c0c0c0", imageUrl: "/module-dofus/Dofus_Argente_Scintillant.png" },
  ebene:              { label: "Ébène",              color: "#52525b", imageUrl: "/module-dofus/Dofus_Ebene.png" },
  pourpre:            { label: "Pourpre",            color: "#a855f7", imageUrl: "/module-dofus/Dofus_Pourpre.png" },
  ivoire:             { label: "Ivoire",             color: "#e2e8f0", imageUrl: "/module-dofus/Dofus_Ivoire.png" },
  emeraude:           { label: "Émeraude",           color: "#10b981", imageUrl: "/module-dofus/Dofus_Emeraude.png" },
  dolmanax:           { label: "Dolmanax",           color: "#ef4444", imageUrl: "/module-dofus/Dofus_Dolmanax.png" },
  des_glaces:         { label: "Des Glaces",         color: "#93c5fd", imageUrl: "/module-dofus/Dofus_Des_Glaces.png" },
  du_cauchemar:       { label: "Du Cauchemar",       color: "#7c3aed", imageUrl: "/module-dofus/Dofus_Du_Cauchemar.png" },
  des_veilleurs:      { label: "Des Veilleurs",      color: "#38bdf8", imageUrl: "/module-dofus/Dofus_Veilleur.png" },
  domakuro:           { label: "Domakuro",           color: "#84cc16", imageUrl: "/module-dofus/Dofus_Domakuro.png" },
  dorigami:           { label: "Dorigami",           color: "#f472b6", imageUrl: "/module-dofus/Dofus_Dorigami.png" },
  tachete:            { label: "Tacheté",            color: "#c084fc", imageUrl: "/module-dofus/Dofus_Tacheté.png" },
  dom_de_pin:         { label: "Dom de Pin",         color: "#a3e635", imageUrl: "/module-dofus/Dom_De_Pin.png" },
};

type DofusStat = {
  id: string;
  label: string;
  color: string;
  imageUrl: string;
  totalMilestones: number;
  completedMilestones: number;
  pct: number;
  membersInProgress: { profileId: string; userName: string; userAvatar?: string; completed: number; total: number; pct: number }[];
};

// ─── GuildStatusPanel ─────────────────────────────────────────────────────────

export const GuildStatusPanel = memo(function GuildStatusPanel({
  milestones,
  guildProgress,
}: {
  milestones: Milestone[];
  guildProgress: GuildMemberProgress[];
}) {
  const [modalDofus, setModalDofus] = useState<string | null>(null);

  const dofusStats = useMemo(() => {
    const map = new Map<string, DofusStat>();

    milestones.forEach((ms) => {
      const dofusId = ms.dofusId;
      if (!dofusId) return;
      const def = DOFUS_DEFS[dofusId];
      if (!def) return;

      if (!map.has(dofusId)) {
        map.set(dofusId, {
          id: dofusId,
          label: def.label,
          color: def.color,
          imageUrl: def.imageUrl,
          totalMilestones: 0,
          completedMilestones: 0,
          pct: 0,
          membersInProgress: [],
        });
      }

      const stat = map.get(dofusId)!;
      stat.totalMilestones++;

      // Check if this milestone is completed by at least one member
      const completedBySome = guildProgress.some(
        (p) => p.milestoneId === ms.id && p.isCompleted
      );
      if (completedBySome) stat.completedMilestones++;
    });

    // Calculate per-member progress per Dofus
    const profileIds = [...new Set(guildProgress.map((p) => p.profileId))];

    map.forEach((stat, dofusId) => {
      const dofusMilestoneIds = new Set(
        milestones.filter((m) => m.dofusId === dofusId).map((m) => m.id)
      );

      stat.membersInProgress = profileIds
        .map((profileId) => {
          const memberProgress = guildProgress.filter(
            (p) => p.profileId === profileId && dofusMilestoneIds.has(p.milestoneId)
          );
          const userName = memberProgress[0]?.userName || "Inconnu";
          const userAvatar = memberProgress[0]?.userAvatar;
          const completed = memberProgress.filter((p) => p.isCompleted).length;
          const total = dofusMilestoneIds.size;
          const pct = total > 0 ? Math.round((completed / total) * 100) : 0;
          return { profileId, userName, userAvatar, completed, total, pct };
        })
        .filter((m) => m.total > 0)
        .sort((a, b) => b.pct - a.pct);
    });

    return Array.from(map.values()).sort((a, b) => b.totalMilestones - a.totalMilestones);
  }, [milestones, guildProgress]);

  const totalMembers = useMemo(
    () => new Set(guildProgress.map((p) => p.profileId)).size,
    [guildProgress]
  );

  if (dofusStats.length === 0) return null;

  const selectedDofus = modalDofus ? dofusStats.find((d) => d.id === modalDofus) : null;

  return (
    <>
      <div className="p-4 rounded-2xl bg-gradient-to-br from-zinc-900/70 to-zinc-950/70 border border-zinc-800/60">
        {/* Header */}
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-2">
            <Users className="w-4 h-4 text-indigo-400" />
            <span className="text-[10px] font-black uppercase tracking-widest text-zinc-400">
              Progression Dofus
            </span>
          </div>
          <span className="text-[9px] font-black text-indigo-400">
            {totalMembers} membre{totalMembers > 1 ? "s" : ""}
          </span>
        </div>

        {/* Dofus cards — horizontal scroll, compact */}
        <div className="flex gap-1.5 overflow-x-auto pb-1 scrollbar-thin scrollbar-thumb-zinc-800 scrollbar-track-transparent -mx-1 px-1">
          {dofusStats.map((d) => {
            const isAllDone = d.completedMilestones === d.totalMilestones && d.totalMilestones > 0;

            return (
              <button
                key={d.id}
                onClick={() => setModalDofus(d.id)}
                className="relative flex flex-col items-center gap-1 p-2 rounded-xl border transition-all text-center group cursor-pointer hover:scale-[1.02] active:scale-[0.98] shrink-0 w-[72px]"
                style={{
                  borderColor: isAllDone ? `${d.color}50` : `${d.color}20`,
                  background: isAllDone ? `${d.color}08` : undefined,
                }}
                title={`${d.label} — ${d.pct}% (${d.completedMilestones}/${d.totalMilestones})`}
              >
                {/* Dofus icon */}
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img
                  src={d.imageUrl}
                  alt={d.label}
                  className="w-7 h-7 object-contain drop-shadow-lg group-hover:scale-110 transition-transform"
                />

                {/* Label — truncated */}
                <span className="text-[7px] font-black uppercase tracking-widest truncate max-w-full leading-tight" style={{ color: d.color }}>
                  {d.label}
                </span>

                {/* Mini progress bar */}
                <div className="w-full h-1 bg-zinc-800/60 rounded-full overflow-hidden">
                  <div
                    className="h-full rounded-full transition-all duration-500"
                    style={{
                      width: `${d.pct}%`,
                      background: `linear-gradient(90deg, ${d.color}, ${d.color}99)`,
                    }}
                  />
                </div>

                {/* Percentage compact */}
                <span className="text-[7px] font-mono font-bold text-zinc-500">
                  {d.pct}%
                </span>
              </button>
            );
          })}
        </div>
      </div>

      {/* ── Detail Modal ── */}
      <AnimatePresence>
        {modalDofus && selectedDofus && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-md p-4"
            onClick={() => setModalDofus(null)}
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              exit={{ scale: 0.95, opacity: 0, y: 20 }}
              transition={{ type: "spring", duration: 0.4 }}
              className="bg-zinc-900 border border-zinc-800 rounded-3xl p-5 max-w-lg w-full max-h-[85vh] overflow-y-auto shadow-2xl"
              onClick={(e) => e.stopPropagation()}
            >
              {/* Header */}
              <div className="flex items-start justify-between mb-5">
                <div className="flex items-center gap-3">
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img
                    src={selectedDofus.imageUrl}
                    alt={selectedDofus.label}
                    className="w-12 h-12 object-contain"
                  />
                  <div>
                    <h3 className="text-base font-black text-white">{selectedDofus.label}</h3>
                    <p className="text-[10px] text-zinc-500 font-mono">
                      {selectedDofus.completedMilestones}/{selectedDofus.totalMilestones} blocs — {selectedDofus.pct}%
                    </p>
                  </div>
                </div>
                <button
                  onClick={() => setModalDofus(null)}
                  className="p-1.5 rounded-xl bg-zinc-800 hover:bg-zinc-700 transition-colors"
                >
                  <X className="w-4 h-4 text-zinc-400" />
                </button>
              </div>

              {/* Progress bar large */}
              <div className="h-2 bg-zinc-800/60 rounded-full overflow-hidden mb-5">
                <div
                  className="h-full rounded-full transition-all duration-700"
                  style={{
                    width: `${selectedDofus.pct}%`,
                    background: `linear-gradient(90deg, ${selectedDofus.color}, ${selectedDofus.color}99)`,
                    boxShadow: `0 0 12px ${selectedDofus.color}50`,
                  }}
                />
              </div>

              {/* Members list */}
              {selectedDofus.membersInProgress.length === 0 ? (
                <p className="text-xs text-zinc-600 italic text-center py-8">
                  Aucun membre n'a encore commencé ce Dofus.
                </p>
              ) : (
                <div className="space-y-1.5">
                  <p className="text-[9px] font-black uppercase tracking-widest text-zinc-500 mb-2">
                    Membres ({selectedDofus.membersInProgress.length})
                  </p>
                  {selectedDofus.membersInProgress.map((m) => (
                    <div
                      key={m.profileId}
                      className="flex items-center gap-3 p-2.5 rounded-xl bg-zinc-800/40 border border-zinc-800/50 hover:border-zinc-700/50 transition-colors"
                    >
                      <div className="w-8 h-8 rounded-full bg-zinc-800 border border-zinc-700 flex items-center justify-center text-[10px] font-black text-zinc-300 overflow-hidden shrink-0">
                        {m.userAvatar ? (
                          // eslint-disable-next-line @next/next/no-img-element
                          <img src={m.userAvatar} alt={m.userName} className="w-full h-full object-cover" />
                        ) : (
                          m.userName[0]?.toUpperCase()
                        )}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center justify-between">
                          <p className="text-xs font-bold text-white truncate">{m.userName}</p>
                          <span className="text-[10px] font-mono font-black" style={{ color: selectedDofus.color }}>
                            {m.pct}%
                          </span>
                        </div>
                        <div className="h-1.5 bg-zinc-800/60 rounded-full overflow-hidden mt-1.5">
                          <div
                            className="h-full rounded-full transition-all duration-500"
                            style={{
                              width: `${m.pct}%`,
                              background: selectedDofus.color,
                            }}
                          />
                        </div>
                        <p className="text-[8px] text-zinc-500 mt-0.5 font-mono">
                          {m.completed}/{m.total} blocs
                        </p>
                      </div>
                    </div>
