                <a href="https://www.metamob.fr/settings#api" target="_blank" rel="noopener noreferrer" className="text-xs text-amber-500 hover:text-amber-400 font-semibold flex items-center gap-1 transition-colors">
                  Où trouver ma clé API ? <ExternalLink className="w-3 h-3" />
                </a>
              </div>
              <Input type="password" placeholder="64 caractères..." value={metamobApiKeyInput} onChange={(e) => setMetamobApiKeyInput(e.target.value)} className="h-12 bg-zinc-900/50 border-zinc-800" />
              <p className="text-xs text-zinc-500 leading-relaxed">
                Votre clé API est requise pour synchroniser automatiquement vos archimonstres et vos quêtes. Elle est disponible dans l'onglet <strong>API</strong> des paramètres de votre compte Metamob.fr.
              </p>
            </div>
          )}
          {metamobLinkError && <div className="p-4 rounded-xl bg-red-500/10 text-red-400 border border-red-500/20 text-sm font-bold">{metamobLinkError}</div>}
        </div>
        <DialogFooter className="p-8 border-t border-white/5 flex gap-3">
          {metamobStep === 1 ? (
            <Button onClick={() => setMetamobStep(2)} disabled={!metamobPseudoInput.trim()} className="w-full bg-amber-600 font-bold">Suivant</Button>
          ) : (
            <>
              <Button variant="ghost" onClick={() => setMetamobStep(1)} className="text-zinc-400">Retour</Button>
              <Button onClick={async () => {
                if (!metamobPseudoInput.trim()) { toast.error("Veuillez entrer un pseudo"); return; }
                setMetamobLinking(true); setMetamobLinkError(null);
                try {
                  const res = await linkOcreAccount({ guildId, pseudo: metamobPseudoInput.trim(), apiKey: metamobApiKeyInput.trim() || undefined, force: false });
                  if (res.success) { toast.success("Compte Metamob lié !"); setMetamobLinkOpen(false); setMetamobPseudoInput(""); setMetamobApiKeyInput(""); window.location.reload(); }
                  else { setMetamobLinkError(res.error || "Erreur de liaison"); }
                } catch { setMetamobLinkError("Erreur réseau"); }
                finally { setMetamobLinking(false); }
              }} disabled={metamobLinking} className="bg-emerald-600 font-bold">
                {metamobLinking ? <Loader2 className="w-4 h-4 animate-spin" /> : "Lier le compte"}
              </Button>
            </>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  </div></ScrollToPrereqCtx.Provider></AllCompletedSeqIdsCtx.Provider></AllMilestonesCtx.Provider></CapturedMonsterCtx.Provider></CapturedMonsterNamesCtx.Provider>
  {/* ── Alignment Edit Dialog ───────────────────────────────────────────── */}
  <Dialog open={alignEditOpen} onOpenChange={setAlignEditOpen}>
    <DialogContent className="max-w-lg w-[95vw] bg-zinc-950 border-zinc-800 rounded-3xl p-0 overflow-hidden shadow-2xl">
      <DialogHeader className="p-6 pb-4 border-b border-white/5">
        <DialogTitle className="text-lg font-black uppercase tracking-widest text-white flex items-center gap-2">
          <Shield className="w-5 h-5 text-emerald-400"/>Alignement & Ordre
        </DialogTitle>
        {/* Step pills */}
        <div className="flex items-center gap-2 mt-3">
          {(["alignment","order","tranche"] as const).map((s,i)=>(
            <button key={s} type="button" onClick={()=>{if(s==="order"&&(!alignEditAlignment||alignEditAlignment==="neutre"))return;if(s==="tranche"&&!alignEditOrder)return;setAlignEditStep(s);}} className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest border transition-all ${alignEditStep===s?"bg-emerald-500/20 border-emerald-500/40 text-emerald-300":"border-zinc-700/50 text-zinc-500 hover:border-zinc-600 hover:text-zinc-300"}`}>
              <span className={`w-4 h-4 rounded-full flex items-center justify-center text-[8px] font-black ${alignEditStep===s?"bg-emerald-500 text-white":"bg-zinc-800 text-zinc-500"}`}>{i+1}</span>
              {s==="alignment"?"Alignement":s==="order"?"Ordre":"Tranche"}
            </button>
          ))}
        </div>
      </DialogHeader>

      <div className="p-6 space-y-4 max-h-[60vh] overflow-y-auto">
        {/* STEP 1 — Alignment */}
        {alignEditStep==="alignment"&&(
          <div className="grid grid-cols-3 gap-3">
            {ALIGNMENTS.map(align=>(
              <button key={align.id} type="button" onClick={()=>{setAlignEditAlignment(align.id);if(align.id==="neutre"){setAlignEditOrder(null);setAlignEditLevel(0);}else setAlignEditStep("order");}} className={`relative flex flex-col items-center gap-3 p-4 rounded-2xl border-2 transition-all duration-300 ${alignEditAlignment===align.id?"border-emerald-500/60 bg-emerald-500/10":"border-zinc-800/60 bg-zinc-900/40 hover:border-zinc-700 hover:bg-zinc-900/70"}`}>
                <div className={`w-12 h-12 rounded-full flex items-center justify-center border overflow-hidden ${align.id==="bontarien"?"bg-blue-500/20 border-blue-500/30":align.id==="brakmarien"?"bg-red-500/20 border-red-500/30":"bg-zinc-800 border-zinc-700"}`}>
                  <img src={align.icon} alt={align.name} className="w-8 h-8 object-contain"/>
                </div>
                <span className={`text-[10px] font-black uppercase tracking-widest ${alignEditAlignment===align.id?"text-white":"text-zinc-400"}`}>{align.name}</span>
                {alignEditAlignment===align.id&&<div className="absolute top-2 right-2 w-5 h-5 rounded-full bg-emerald-500 flex items-center justify-center"><Check className="w-3 h-3 text-white"/></div>}
              </button>
            ))}
          </div>
        )}

        {/* STEP 2 — Order */}
        {alignEditStep==="order"&&alignEditAlignment&&alignEditAlignment!=="neutre"&&(
          <div className="grid grid-cols-1 gap-3">
            {((ORDERS as any)[alignEditAlignment]||[]).map((order:any)=>{
              const isSel=alignEditOrder===order.id;
              const ib=alignEditAlignment==="bontarien";
              return(
                <button key={order.id} type="button" onClick={()=>{setAlignEditOrder(order.id);setAlignEditStep("tranche");}} className={`relative flex items-center gap-4 p-4 rounded-2xl border-2 transition-all ${isSel?(ib?"border-blue-500/60 bg-blue-500/10":"border-red-500/60 bg-red-500/10"):"border-zinc-800/60 bg-zinc-900/40 hover:border-zinc-700 hover:bg-zinc-900/70"}`}>
                  <div className="w-12 h-12 rounded-xl bg-zinc-900 border border-white/10 flex items-center justify-center shrink-0 overflow-hidden">
                    <img src={order.icon} alt={order.name} className="w-9 h-9 object-contain p-1"/>
                  </div>
                  <span className={`text-sm font-black ${isSel?"text-white":"text-zinc-300"}`}>{order.name}</span>
                  {isSel&&<div className={`absolute top-2 right-2 w-5 h-5 rounded-full flex items-center justify-center ${ib?"bg-blue-500":"bg-red-500"}`}><Check className="w-3 h-3 text-white"/></div>}
                </button>
              );
            })}
          </div>
        )}

        {/* STEP 3 — Tranche */}
        {alignEditStep==="tranche"&&(
          <div className="space-y-4">
            <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Niveau d'alignement (Tranche)</p>
            <div className="grid grid-cols-1 gap-2">
              {[20,40,60,80,100].map(lvl=>{
                const isSel=alignEditLevel===lvl;
                const orderData=alignEditAlignment&&alignEditOrder?(ORDERS as any)[alignEditAlignment]?.find((o:any)=>o.id===alignEditOrder):null;
                const title=orderData?.levels?.[lvl]||"";
                return(
                  <button key={lvl} type="button" onClick={()=>setAlignEditLevel(lvl)} className={`flex items-center gap-4 px-4 py-3 rounded-xl border-2 transition-all text-left ${isSel?"border-amber-500 bg-amber-500/15 shadow-[0_0_12px_rgba(245,158,11,0.15)]":"border-zinc-800/60 bg-zinc-900/50 hover:border-zinc-600 hover:bg-zinc-900"}`}>
                    <span className={`text-sm font-black w-8 shrink-0 ${isSel?"text-amber-400":"text-zinc-500"}`}>{">"}{lvl}</span>
                    <span className={`text-xs font-bold flex-1 ${isSel?"text-white":"text-zinc-400"}`}>{title}</span>
                    {isSel&&<Check className="w-4 h-4 text-amber-400 shrink-0"/>}
                  </button>
                );
              })}
            </div>
          </div>
        )}

      </div>

      <DialogFooter className="p-5 border-t border-white/5 flex items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          {alignEditStep!=="alignment"&&<Button variant="ghost" size="sm" onClick={()=>setAlignEditStep(alignEditStep==="tranche"?"order":"alignment")} className="text-zinc-400 hover:text-white text-xs">← Retour</Button>}
        </div>
        <div className="flex items-center gap-2">
          <Button variant="ghost" size="sm" onClick={()=>setAlignEditOpen(false)} className="text-zinc-500 hover:text-white text-xs">Annuler</Button>
          <Button onClick={handleAlignEditSave} disabled={alignEditSaving||(!alignEditAlignment)} size="sm" className="bg-emerald-600 hover:bg-emerald-500 text-white font-black text-xs px-5">
            {alignEditSaving?<Loader2 className="w-3.5 h-3.5 animate-spin"/>:"Enregistrer"}
          </Button>
        </div>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</>);}

"use client";
import React from "react";
import { motion } from "framer-motion";
import { Check, MapPin, Skull, Target, Copy } from "lucide-react";
import { toast } from "sonner";
import { sanitizeHtml } from "@/lib/security";

export const GlassCard = ({ children, className = "", style = {} }: any) => (
  <div className={`bg-zinc-950/40 backdrop-blur-xl border border-white/5 rounded-2xl overflow-hidden shadow-2xl ${className}`} style={style}>
    {children}
  </div>
);

export const Badge = ({ children, color = "emerald", className = "" }: any) => {
  const colors: any = {
    emerald: "bg-emerald-500/10 text-emerald-400 border-emerald-500/20",
    purple: "bg-purple-500/10 text-purple-400 border-purple-500/20",
    blue: "bg-blue-500/10 text-blue-400 border-blue-500/20",
    gold: "bg-amber-500/10 text-amber-400 border-amber-500/20",
    zinc: "bg-zinc-500/10 text-zinc-400 border-zinc-500/20",
  };
  return (
    <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider border ${colors[color]} ${className}`}>
      {children}
    </span>
  );
};

export const MapBadge = ({ posX, posY, mapName, onClick }: { posX: number; posY: number; mapName?: string; onClick: any }) => (
  <button onClick={(e) => { e.stopPropagation(); onClick(posX, posY, mapName); }}
    className="inline-flex items-center gap-1.5 px-2.5 py-1 bg-cyan-500/5 hover:bg-cyan-500/10 border border-cyan-500/20 rounded-lg text-[10px] font-bold text-cyan-400 transition-all group active:scale-95">
    <MapPin className="w-3 h-3 group-hover:scale-110 transition-transform text-cyan-500" />
    <span>{mapName || `[${posX},${posY}]`}</span>
  </button>
);

export const StepRow = ({ step, isChecked, onToggle, onMapClick, guideRef }: any) => {
  const hasPos = step.pos_x !== 0 || step.pos_y !== 0;

  const handleTextClick = (e: React.MouseEvent) => {
    const target = e.target as HTMLElement;
    
    // 1. Détection des liens DofusDB (items, monstres, etc)
    const customTag = target.closest('[data-type="custom-tag"]');
    if (customTag) {
      e.stopPropagation();
      const id = customTag.getAttribute('data-id') || customTag.getAttribute('dofusdbid');
      const type = customTag.getAttribute('type');
      if (id && type) {
        let url = `https://dofusdb.fr/fr/database/${type}/${id}`;
        // Cas particulier pour les donjons si nécessaire
        if (type === 'dungeon') url = `https://dofusdb.fr/fr/database/dungeon/${id}`;
        window.open(url, '_blank');
        return;
      }
    }

    // 2. Détection des positions [x, y]
    const text = target.innerText || "";
    const posMatch = text.match(/\[\s*(-?\d+)\s*,\s*(-?\d+)\s*\]/);
    
    if (posMatch) {
      e.stopPropagation();
      const x = posMatch[1];
      const y = posMatch[2];
      const cmd = `/travel ${x} ${y}`;
      navigator.clipboard.writeText(cmd);
      toast.success(`Position ${posMatch[0]} copiée !`, {
        description: "La commande /travel est dans ton presse-papier.",
        icon: <Copy className="w-4 h-4 text-emerald-500" />,
      });
    }
  };

  return (
    <motion.div
      layout
      initial={{ opacity: 0, x: -10 }}
      animate={{ opacity: isChecked ? 0.4 : 1, x: 0 }}
      exit={{ opacity: 0, scale: 0.95, filter: "blur(10px)" }}
      transition={{ duration: 0.3 }}
      onClick={() => onToggle(`${guideRef}-${step.stepNumber}`)}
      className={`group flex items-start gap-3 p-3 rounded-xl border transition-all cursor-default relative overflow-hidden ${isChecked ? "bg-emerald-500/5 border-emerald-500/20" : "bg-white/5 border-white/5 hover:border-white/10"}`}
    >
      {isChecked && (
        <motion.div 
          initial={{ width: 0 }} 
          animate={{ width: "100%" }} 
          className="absolute inset-y-0 left-0 bg-emerald-500/5 pointer-events-none" 
        />
      )}

      {isChecked && (
        <motion.div 
          initial={{ opacity: 0 }} 
          animate={{ opacity: 1 }} 
          className="absolute inset-0 bg-emerald-500/5 ring-1 ring-inset ring-emerald-500/20 pointer-events-none z-0" 
        />
      )}

      <div className={`w-6 h-6 rounded-lg flex items-center justify-center flex-shrink-0 border transition-all z-10 cursor-pointer ${isChecked ? "bg-emerald-500 border-emerald-400 text-emerald-950 shadow-[0_0_15px_rgba(16,185,129,0.4)] scale-90" : "bg-zinc-900 border-zinc-800 text-zinc-600 group-hover:border-zinc-700"}`}>
        {isChecked ? <Check className="w-4 h-4 font-black" /> : <span className="text-[10px] font-black">{step.stepNumber}</span>}
      </div>

      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2 flex-wrap mb-1 transition-all">
          {step.name && (
            <span className={`text-[11px] font-black transition-all ${isChecked ? "text-emerald-500/50 line-through" : "text-zinc-200"}`}>
              {step.name}
            </span>
          )}
          {hasPos && <MapBadge posX={step.pos_x} posY={step.pos_y} mapName={step.map} onClick={onMapClick} />}
        </div>
        <div 
          className={`text-[11px] leading-relaxed ganymade-step-text transition-all duration-500 ${isChecked ? "text-zinc-600 grayscale opacity-40 italic line-through decoration-emerald-500/30" : "text-zinc-400"}`} 
          onClick={handleTextClick}
          // nosemgrep: typescript.react.security.audit.react-dangerouslysetinnerhtml.react-dangerouslysetinnerhtml
          dangerouslySetInnerHTML={{ __html: sanitizeHtml(
                step.web_text
                  .replace(/<input[^>]*type="checkbox"[^>]*>/g, '')
                  .replace(/\[\s*(-?\d+)\s*,\s*(-?\d+)\s*\]/g, '<span class="pos-interactive">$&</span>')
              ) ?? ""
          }}
        />
      </div>
    </motion.div>
  );
};

import { notFound, redirect } from "next/navigation";
export const dynamic = "force-dynamic";
import { Suspense } from "react";
import { auth } from "@/auth";
import { getUserContext } from "@/server/actions/user-actions";
import { getOptimizedGuideDetail, getGuildOptimizedGuideProgress } from "@/server/actions/optimized-guide-actions";
import { getMemberProfile } from "@/server/actions/profile-actions";
import { CharacterQuestSelector } from "@/components/dofus-quests/CharacterQuestSelector";
import OptimizedGuideClient from "./OptimizedGuideClient";
import RushTimelineClient from "./RushTimelineClient";

type Props = {
    params: Promise<{ guildId: string; slug: string }>;
    searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
};

export default async function OptimizedGuideUserPage({ params, searchParams }: Props) {
    const { guildId, slug } = await params;
    const resolvedSearchParams = await searchParams;
    const session = await auth();
    if (!session?.user?.id) redirect("/");

    const character = (resolvedSearchParams?.character as string) || "PRINCIPAL";
    const altPseudo = character !== "PRINCIPAL" ? character : undefined;

    const user = await getUserContext(guildId);

    let guideContext: Awaited<ReturnType<typeof getOptimizedGuideDetail>>;
    try {
        guideContext = await getOptimizedGuideDetail(slug, guildId, altPseudo);
    } catch (e: any) {
        console.error("[Guide Page] Error fetching guide:", slug, e?.message);
        notFound();
    }

    if (!guideContext.success || !guideContext.guide) {
        notFound();
    }

    const guide = guideContext.guide as any;
    const isTimeline = guide.displayMode === "TIMELINE";

    // Fetch Guild members progress (non-blocking)
    let allProgress: any[] = [];
    try {
        const membersContext = await getGuildOptimizedGuideProgress(slug, guildId);
        allProgress = (membersContext.allProgress || []).map((p: any) => ({
            profileId: p.profileId,
            milestoneId: p.milestoneId,
            isCompleted: p.isCompleted || false,
            completedSteps: Array.isArray(p.completedSteps) ? p.completedSteps : [],
            currentStep: p.currentStep || null,
            userName: p.profile?.displayName || p.profile?.pseudoDofus || p.profile?.user?.name || "Voyageur",
            userAvatar: p.profile?.user?.image || undefined,
            profileSlug: p.profile?.pseudoDofus || p.profileId
        }));
    } catch (e) {
        console.error("[Guide Page] Guild progress fetch failed (non-fatal):", e);
    }

    // Fetch full profile to get alignment, alignmentOrder, alignmentLevel, altPseudos, class & metamob
    let userProfile: { 
        alignment?: string | null; 
        alignmentOrder?: string | null; 
        alignmentLevel?: number; 
        altPseudos?: any[]; 
        dofusClass?: string | null;
        metamobPseudo?: string | null;
        pseudoDofus?: string | null;
    } = {};
    try {
        const profileId = user.profileId;
        if (!profileId) throw new Error("Profile ID not found");
        const profileRes = await getMemberProfile(guildId, profileId);
        if (profileRes.success && profileRes.data) {
            const p = profileRes.data;
            userProfile = {
                alignment: p.alignment,
                alignmentOrder: p.alignmentOrder,
                alignmentLevel: p.alignmentLevel ?? 0,
                altPseudos: Array.isArray(p.altPseudos) ? p.altPseudos : [],
                dofusClass: p.classe,
                metamobPseudo: p.metamobPseudo,
                pseudoDofus: p.pseudoDofus,
            };
        }
    } catch (e) {
        console.error("[Guide Page] Profile fetch failed (non-fatal):", e);
    }

    // Fetch Ocre progress stats if metamob is linked
    let ocreStats: any = null;
    let capturedOcreMonsterIds: number[] = [];
    let capturedMonsterNames: string[] = [];
    if (userProfile.metamobPseudo) {
        try {
            const { getMyOcreProgress } = await import("@/server/actions/ocre-actions");
            const ocreRes = await getMyOcreProgress(guildId);
            if (ocreRes.success && ocreRes.data?.stats) {
                ocreStats = {
                    bosses: ocreRes.data.stats.bosses,
                    archis: ocreRes.data.stats.archis,
                    progressPercent: ocreRes.data.stats.progressPercent,
                    currentStep: ocreRes.data.questInfo?.currentStep ?? 1,
                    serverName: ocreRes.data.questInfo?.serverName || "Dofus Unity",
                };
                // Build lists of captured monster IDs and names for dungeon detection
                const monsters = ocreRes.data.monsters;
                if (Array.isArray(monsters)) {
                    const captured = monsters.filter((m: any) => m.owned != null && m.owned > 0);
                    capturedOcreMonsterIds = captured.map((m: any) => m.id);
                    capturedMonsterNames = captured
                        .map((m: any) => m.name?.fr || m.name || "")
                        .filter(Boolean);
                }
            }
        } catch (e) {
            console.error("[Guide Page] Metamob stats fetch error (non-fatal):", e);
        }
    }

    const mules = (user.altPseudos as any[] | undefined) || [];

    return (
        <div className="flex flex-col w-full h-full overflow-hidden">
            {/* Character selector bar */}
            {mules.length > 0 && (
                <div className="flex items-center justify-between px-4 py-2 bg-zinc-950/80 border-b border-white/5 shrink-0">
                    <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-emerald-400/60">
                        <span>📖 {guide.name}</span>
                    </div>
                    <CharacterQuestSelector
                        mainCharacter={{
                            pseudo: user.pseudoDofus || user.name || "Principal",
                            classe: user.classe,
                        }}
                        mules={mules}
                    />
                </div>
            )}

            <Suspense fallback={
                <div className="flex items-center justify-center w-full h-full">
                    <div className="animate-spin w-8 h-8 border-4 border-emerald-500 border-t-transparent rounded-full" />
                </div>
            }>
                {isTimeline ? (
                    <div className="flex-1 overflow-y-auto p-6">
                        <RushTimelineClient
                            key={character}
                            guide={{
                                id: guide.id,
                                name: guide.name,
                                slug: guide.slug,
                                description: guide.description,
                                imageUrl: guide.imageUrl,
                                isUnderConstruction: guide.isUnderConstruction ?? false,
                            }}
                            milestones={guide.milestones as any}
                            guildProgress={allProgress}
                            guildId={guildId}
                            selectedCharacter={character}
                            mules={mules}
                            currentUserProfile={{
                                alignment: userProfile.alignment,
                                alignmentOrder: userProfile.alignmentOrder,
                                alignmentLevel: userProfile.alignmentLevel,
                                altPseudos: mules,
                                dofusClass: userProfile.dofusClass,
                                metamobPseudo: userProfile.metamobPseudo,
                                pseudoDofus: userProfile.pseudoDofus,
                            }}
                            ocreStats={ocreStats}
                            capturedOcreMonsterIds={Array.from(capturedOcreMonsterIds)}
                            capturedMonsterNames={capturedMonsterNames}
                        />
                    </div>
                ) : (
                    <OptimizedGuideClient
                        guide={guide}
                        milestones={guide.milestones as any}
                        userProgress={guide.milestones.flatMap((m: any) => m.playerProgress || [])}
                        guildProgress={allProgress}
                        guildId={guildId}
                        selectedCharacter={character}
                        mainCharacter={{
                            pseudo: user.pseudoDofus || user.name || "Principal",
                            classe: user.classe,
                        }}
                        mules={mules}
                    />
                )}
            </Suspense>
        </div>
    );
}

import { auth } from "@/auth";
import { redirect } from "next/navigation";
import AccessDenied from "@/components/access-denied";
import { getUserContext } from "@/server/actions/user-actions";
import { isModuleEnabled } from "@/server/actions/module-actions";
import { UnifiedModuleHeader } from "@/components/layout/unified-module-header";
import { Gem } from "lucide-react";
import { getDofusListWithProgress, getGuildDofusStats } from "@/server/actions/dofus-quest-actions";
import { getOptimizedGuides, getOptimizedGuideDetail, getGuildOptimizedGuideProgress } from "@/server/actions/optimized-guide-actions";
import { DofusQuestHub } from "@/components/dofus-quests/DofusQuestHub";
import { CharacterQuestSelector } from "@/components/dofus-quests/CharacterQuestSelector";
import { db } from "@/lib/prisma";

import { ActivitiesNav } from "@/components/layout/activities-nav";
import { AuroraBackground } from "@/components/ui/aurora-background";

type Props = {
    params: Promise<{ guildId: string }>;
    searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
};

export default async function QuetesDofusPage({ params, searchParams }: Props) {
    const session = await auth();
    if (!session?.user) redirect("/");

    const { guildId } = await params;
    const resolvedSearchParams = await searchParams;
    const character = resolvedSearchParams?.character as string || "PRINCIPAL";

    const user = await getUserContext(guildId);
    if (!user.canViewQuests) return <AccessDenied />;

    const enabled = await isModuleEnabled(guildId, "quests");
    if (!enabled) return <AccessDenied />;

    // Fetch data in parallel
    const [dofusResult, guildStatsResult, guidesResult, rushSylvestre] = await Promise.all([
        getDofusListWithProgress(guildId, character),
        getGuildDofusStats(guildId),
        getOptimizedGuides(guildId),
        db.optimizedGuide.findUnique({
            where: { slug: "rush-sylvestre" },
            select: { isUnderConstruction: true, isActive: true },
        }).catch(() => null),
    ]);

    const dofusList = dofusResult.success ? (dofusResult.data ?? []) : [];
    const guildStats = guildStatsResult.success ? guildStatsResult.data ?? null : null;
    const guides = guidesResult.success ? guidesResult.guides ?? [] : [];

    // Fetch user profile for Metamob sync status
    const profile = user.profileId ? await db.userProfile.findUnique({
        where: { id: user.profileId },
        select: {
            metamobPseudo: true,
            metamobVerified: true,
            metamobLastSync: true,
            metamobQuestSlug: true,
        }
    }) : null;

    const userProfile = profile ? {
        metamobPseudo: profile.metamobPseudo,
        metamobVerified: profile.metamobVerified,
        metamobLastSync: profile.metamobLastSync?.toISOString() || null,
        metamobQuestSlug: profile.metamobQuestSlug,
    } : null;

    const guideSlug = resolvedSearchParams?.guide as string || (guides.length > 0 ? guides[0].slug : null);

    let guideDetail = null;
    let guideUserProgress = null;
    let guideGuildProgress = null;

    if (guideSlug) {
        try {
            const detailRes = await getOptimizedGuideDetail(guideSlug, guildId);
            if (detailRes.success && detailRes.guide) {
                guideDetail = detailRes.guide;
                guideUserProgress = detailRes.guide.milestones.flatMap((m: any) => m.playerProgress || []);
                
                const membersContext = await getGuildOptimizedGuideProgress(guideSlug, guildId);
                guideGuildProgress = (membersContext.allProgress || []).map((p: any) => ({
                    profileId: p.profileId,
                    milestoneId: p.milestoneId,
                    isCompleted: p.isCompleted,
                    userName: p.profile?.displayName || p.profile?.pseudoDofus || p.profile?.user?.name || "Voyageur",
                    userAvatar: p.profile?.user?.image || undefined,
                    profileSlug: p.profile?.pseudoDofus || p.profileId
                }));
            }
        } catch (e) {
            console.error("[Quest Page] Error fetching guide details:", e);
        }
    }

    const serializedGuides = JSON.parse(JSON.stringify(guides));
    const serializedGuideDetail = guideDetail ? JSON.parse(JSON.stringify(guideDetail)) : null;
    const serializedGuideUserProgress = guideUserProgress ? JSON.parse(JSON.stringify(guideUserProgress)) : null;
    const serializedGuideGuildProgress = guideGuildProgress ? JSON.parse(JSON.stringify(guideGuildProgress)) : null;

    return (
        <div className="relative min-h-[calc(100vh-4rem)] pb-12">
            <AuroraBackground className="absolute inset-0 z-0 opacity-20 pointer-events-none" />

            <div className="relative z-10 max-w-7xl mx-auto space-y-8">
                <ActivitiesNav guildId={guildId} />

                <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-6">
                    <UnifiedModuleHeader
                        title="Quêtes Dofus"
                        description="Suivez votre progression vers chaque Dofus et comparez-vous à votre guilde"
                        icon={Gem}
                        backHref={`/dashboard/${guildId}`}
                    />
                    
                    <div className="flex-shrink-0 lg:mb-1">
                        <CharacterQuestSelector 
                            mainCharacter={{ 
                                pseudo: user.pseudoDofus || user.name || "Principal", 
                                classe: user.classe 
                             }}
                            mules={user.altPseudos as any || []}
                        />
                    </div>
                </div>

                {dofusList.length === 0 ? (
                    <EmptyState guildId={guildId} isAdmin={user.isAdmin} />
                ) : (
                    <DofusQuestHub
                        dofusList={dofusList}
                        guildStats={guildStats}
                        guides={serializedGuides}
                        rushSylvestreGuide={rushSylvestre}
                        guildId={guildId}
                        selectedCharacter={character}
                        userProfile={userProfile}
                        selectedGuideSlug={guideSlug}
                        selectedGuideDetail={serializedGuideDetail}
                        selectedGuideUserProgress={serializedGuideUserProgress}
                        selectedGuideGuildProgress={serializedGuideGuildProgress}
                    />
                )}
            </div>
        </div>
    );
}

function EmptyState({ guildId, isAdmin }: { guildId: string; isAdmin: boolean }) {
    return (
        <div className="flex flex-col items-center justify-center py-20 gap-4 text-center">
            <div
                className="w-16 h-16 rounded-2xl flex items-center justify-center"
                style={{ background: "rgba(99,102,241,0.12)", border: "1px solid rgba(99,102,241,0.3)" }}
            >
                <Gem className="w-8 h-8 text-indigo-400" />
            </div>
            <div className="max-w-sm">
                <h3 className="text-white/80 font-semibold text-lg mb-1">Données en cours d'initialisation</h3>
                <p className="text-white/40 text-sm">
                    Les données des Dofus doivent encore être chargées dans la base de données.
                </p>
                {isAdmin && (
                    <p className="text-indigo-400/70 text-xs mt-3">
                        (Admin) Utilisez le panneau d'administration pour lancer le seed des données Dofus.
                    </p>
                )}
            </div>
        </div>
    );
}

