                            {/* Right: DPLN */}
                            <NewsGrid defaultFeed="dpln" title="Dofuspourlesnoobs (DPLN)" maxItems={6} showKralamoure={false} />
                        </div>

                        {/* Bottom: Patch Notes Full Width */}
