            {/* Actions */}
            {canManage && isActive && (
                <div className="flex items-center gap-3 pt-5 border-t border-white/10 mt-auto">
                    <Button
                        size="sm"
                        onClick={handleReturn}
                        disabled={returnLoading || cancelLoading}
                        className="h-10 px-6 rounded-xl text-[10px] font-black uppercase tracking-widest bg-emerald-600/20 text-emerald-400 hover:bg-emerald-600/30 border border-emerald-500/20 shadow-[0_0_15px_rgba(16,185,129,0.1)] transition-all"
                    >
                        {returnLoading
                            ? <span className="h-4 w-4 rounded-full border-2 border-emerald-400 border-t-transparent animate-spin mr-2" />
                            : <Check className="h-4 w-4 mr-2" strokeWidth={3} />}
                        Marquer comme rendu
                    </Button>
                    <div className="flex-1" />
                    <Button
                        size="icon"
                        variant="ghost"
                        onClick={handleCancel}
                        disabled={returnLoading || cancelLoading}
                        className="h-10 w-10 rounded-xl bg-rose-500/5 hover:bg-rose-500/15 text-rose-400/60 hover:text-rose-400 transition-all"
                    >
                        {cancelLoading
                            ? <span className="h-4 w-4 rounded-full border-2 border-zinc-500 border-t-transparent animate-spin" />
                            : <X className="h-4 w-4" strokeWidth={3} />}
                    </Button>
                </div>
            )}
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Dialog, DialogContent } from "@/components/ui/dialog";

interface ProofThumbnailProps {
    src: string | null | undefined;
    alt?: string;
    size?: "sm" | "md" | "card";
}

export function ProofThumbnail({ src, alt = "Preuve", size = "sm" }: ProofThumbnailProps) {
    const [open, setOpen] = useState(false);

    if (!src) return null;

    const sizeClasses =
        size === "card" ? "h-28 w-full" :
            size === "md" ? "h-16 w-16" :
                "h-10 w-10";

    return (
        <>
            <button
                onClick={() => setOpen(true)}
                className={`${sizeClasses} relative rounded-lg overflow-hidden border border-white/10 hover:border-cyan-500/50 transition-all cursor-pointer group shrink-0`}
            >
                <img
                    src={src}
                    alt={alt}
                    className="absolute inset-0 w-full h-full object-cover group-hover:scale-110 transition-transform"
                />
                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors flex items-center justify-center">
                    <span className="text-white opacity-0 group-hover:opacity-100 text-[10px] font-bold">🔍</span>
                </div>
            </button>

            <Dialog open={open} onOpenChange={setOpen}>
                <DialogContent className="max-w-2xl bg-zinc-950 border-white/10 p-2">
                    <div className="relative w-full aspect-video">
                        <img
                            src={src}
                            alt={alt}
                            className="absolute inset-0 w-full h-full object-contain rounded-lg"
                        />
                    </div>
                </DialogContent>
            </Dialog>
        </>
    );
}

