"use client";

import { MessageSquare, Mic, Trophy } from "lucide-react";
import type { GuildStats } from "@/server/actions/guild-stats-actions";

interface SocialStatsProps {
    social: GuildStats["social"];
}

export default function SocialStats({ social }: SocialStatsProps) {
    return (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Messages */}
            <div className="space-y-4">
                <div className="flex items-center gap-2 text-violet-400 font-medium">
                    <MessageSquare className="w-4 h-4" />
                    Top Bavards (Messages / Semaine)
                </div>
                <div className="space-y-3">
                    {social.topTalkers.map((user, i) => (
                        <div key={i} className="flex items-center justify-between p-3 rounded-lg bg-white/5 border border-white/10">
                            <div className="flex items-center gap-3">
                                <span className="text-zinc-500 font-mono text-sm">#{i + 1}</span>
                                <span className="text-white font-medium">{user.name}</span>
                            </div>
                            <span className="text-violet-400 font-bold">{user.value.toLocaleString()} msgs</span>
                        </div>
                    ))}
                    {social.topTalkers.length === 0 && <p className="text-zinc-500 text-sm italic">Aucune donnée cette semaine.</p>}
                </div>
            </div>

            {/* Vocal */}
            <div className="space-y-4">
                <div className="flex items-center gap-2 text-blue-400 font-medium">
                    <Mic className="w-4 h-4" />
                    Top Vocal (Heures / Semaine)
                </div>
                <div className="space-y-3">
                    {social.topVocal.map((user, i) => (
                        <div key={i} className="flex items-center justify-between p-3 rounded-lg bg-white/5 border border-white/10">
                            <div className="flex items-center gap-3">
                                <span className="text-zinc-500 font-mono text-sm">#{i + 1}</span>
                                <span className="text-white font-medium">{user.name}</span>
                            </div>
                            <span className="text-blue-400 font-bold">
                                {user.value < 60 
                                    ? `${user.value} min` 
                                    : `${Math.floor(user.value / 60)}h ${user.value % 60 > 0 ? `${user.value % 60}m` : ""}`
                                }
                            </span>
                        </div>
                    ))}
                    {social.topVocal.length === 0 && <p className="text-zinc-500 text-sm italic">Aucun temps vocal enregistré.</p>}
                </div>
            </div>
        </div>
    );
}

import { auth } from "@/auth";
import { redirect } from "next/navigation";
import { getUserContext } from "@/server/actions/user-actions";
import { UnifiedModuleHeader } from "@/components/layout/unified-module-header";
import Link from "next/link";
import { 
    Sparkles, 
    Trophy, 
    Compass, 
    ArrowRight, 
    Briefcase,
    Joystick
} from "lucide-react";
import { cn } from "@/lib/utils";

type HubCard = {
    href: string;
    icon: any;
    title: string;
    description: string;
    accent: "emerald" | "amber" | "indigo" | "violet" | "rose" | "cyan" | "slate";
    visible: boolean;
};

const ACCENT = {
    emerald: { border: "hover:border-emerald-500/50", hover: "hover:bg-emerald-500/5", text: "text-emerald-400", bg: "bg-emerald-500/10" },
    amber: { border: "hover:border-amber-500/50", hover: "hover:bg-amber-500/5", text: "text-amber-400", bg: "bg-amber-500/10" },
    indigo: { border: "hover:border-indigo-500/50", hover: "hover:bg-indigo-500/5", text: "text-indigo-400", bg: "bg-indigo-500/10" },
    violet: { border: "hover:border-violet-500/50", hover: "hover:bg-violet-500/5", text: "text-violet-400", bg: "bg-violet-500/10" },
    rose: { border: "hover:border-rose-500/50", hover: "hover:bg-rose-500/5", text: "text-rose-400", bg: "bg-rose-500/10" },
    cyan: { border: "hover:border-cyan-500/50", hover: "hover:bg-cyan-500/5", text: "text-cyan-400", bg: "bg-cyan-500/10" },
    slate: { border: "hover:border-slate-500/50", hover: "hover:bg-slate-500/5", text: "text-slate-400", bg: "bg-slate-500/10" },
};

export default async function StuffHubPage({
    params,
}: {
    params: Promise<{ guildId: string }>;
}) {
    const session = await auth();
    if (!session?.user) redirect("/");

    const { guildId } = await params;
    const user = await getUserContext(guildId);

    const cards: HubCard[] = [
        {
            href: `/dashboard/${guildId}/galerie-stuff`,
            icon: Sparkles,
            title: "Galerie Guilde",
            description: "Partagez et consultez les meilleurs builds de la guilde. Optimisez votre équipement.",
            accent: "indigo",
            visible: !!(user.isMember && user.canViewStuffGallery),
        },
        {
            href: `/dashboard/${guildId}/mini-jeux`,
            icon: Joystick,
            title: "Mini-Jeux",
            description: "Détendez-vous avec des jeux arcade intégrés. Gagnez des points pour le ladder.",
            accent: "rose",
            visible: !!(user.canViewMiniGames),
        },
        {
            href: `/dashboard/${guildId}/worldmap`,
            icon: Compass,
            title: "Carte du Monde",
            description: "Visualisez les zones importantes et les ressources stratégiques sur la carte.",
            accent: "emerald",
            visible: !!(user.isMember && user.canViewWorldmap),
        }
    ];

    return (
        <div className="space-y-16 pb-32 max-w-[1600px] mx-auto pt-10 px-6">
            <UnifiedModuleHeader
                title="Galerie & Outils"
                description="Espace créatif et utilitaire • Équipement, divertissement et exploration."
                icon={Briefcase}
                iconColor="#6366f1"
                backHref={`/dashboard/${guildId}`}
            />

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 animate-in fade-in slide-in-from-bottom-8 duration-700">
                {cards.map((card) => {
                    const Icon = card.icon;
                    const a = ACCENT[card.accent];
                    
                    if (!card.visible) return null;

                    return (
                        <Link key={card.href} href={card.href} className="group outline-none">
                            <div className={cn(
                                "relative flex flex-col h-full rounded-[2.5rem] border border-white/5 bg-white/[0.02] p-8 transition-all duration-700 hover:border-white/10 hover:bg-white/[0.04] hover:shadow-[0_40px_80px_-20px_rgba(0,0,0,0.6)] overflow-hidden",
                                "before:absolute before:inset-0 before:bg-gradient-to-br before:from-white/[0.05] before:to-transparent before:opacity-0 group-hover:before:opacity-100 before:transition-opacity before:duration-700"
                            )}>
                                <div className={cn(
                                    "absolute -top-24 -right-24 w-48 h-48 blur-[100px] opacity-0 group-hover:opacity-20 transition-opacity duration-700 rounded-full z-0",
                                    a.bg
                                )} />

                                <div className="relative z-10 flex flex-col h-full">
                                    <div className="flex items-center justify-between mb-8">
                                        <div className={cn(
                                            "w-14 h-14 rounded-2xl flex items-center justify-center transition-all duration-500 border group-hover:scale-110 group-hover:rotate-3 shadow-xl",
                                            a.bg,
                                            a.border.replace("hover:", "")
                                        )}>
                                            <Icon className={cn("w-7 h-7", a.text)} strokeWidth={1.5} />
                                        </div>
                                    </div>

                                    <div className="space-y-4 flex-1">
                                        <h3 className="text-xl font-black text-white tracking-tighter uppercase leading-tight">
                                            {card.title}
                                        </h3>
                                        <p className="text-[13px] text-zinc-500 font-medium leading-relaxed group-hover:text-zinc-400 transition-colors">
                                            {card.description}
                                        </p>
                                    </div>

                                    <div className="mt-8 pt-6 border-t border-white/5 flex items-center justify-between">
                                        <div className={cn(
                                            "flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.2em] transition-all",
                                            a.text,
                                            "opacity-40 group-hover:opacity-100"
                                        )}>
                                            <span className="group-hover:translate-x-1 transition-transform">Consulter</span>
                                            <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-1.5 transition-transform" />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </Link>
                    );
                })}
            </div>
        </div>
    );
}

import { getMemberSystemIssues } from "@/server/actions/god-bugs-actions";
import { SystemTrackerView } from "@/components/tracker/system-tracker-view";
import { AuroraBackground } from "@/components/ui/aurora-background";
import { BugIcon, ShieldCheck } from "lucide-react";
import { redirect } from "next/navigation";
import { auth } from "@/auth";

interface TrackerPageProps {
    params: Promise<{
        guildId: string;
    }>;
}

export const metadata = {
    title: "Tracker de Bugs & Améliorations — SigilOS",
    description: "Suivez l'évolution technique de SigilOS, les bugs en cours de résolution et les améliorations prévues.",
};

export default async function MemberTrackerPage({ params }: TrackerPageProps) {
    const { guildId } = await params;
    const session = await auth();

    if (!session?.user?.id) {
        redirect("/login");
    }

    const response = await getMemberSystemIssues(guildId);

    if (!response.success) {
        // If not a member or error, redirect to dashboard root
        redirect(`/dashboard/${guildId}`);
    }

    const issues = response.data || [];

    return (
        <div className="flex-1 flex flex-col relative overflow-hidden">
            <AuroraBackground className="absolute inset-0 z-0 opacity-10 pointer-events-none" />
            
            {/* Header Area */}
            <div className="relative z-10 px-8 pt-10 pb-6 border-b border-white/5 bg-zinc-950/40 backdrop-blur-3xl">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div className="space-y-2">
                        <div className="flex items-center gap-3 mb-1">
                            <div className="p-2 rounded-xl bg-amber-500/10 border border-amber-500/20">
                                <BugIcon className="w-5 h-5 text-amber-500" />
                            </div>
                            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-amber-500/60">Système de Suivi</span>
                        </div>
                        <h1 className="text-3xl font-black text-white tracking-tight flex items-center gap-4">
                            Tracker de Bugs & Améliorations
                        </h1>
                        <p className="text-zinc-500 text-sm font-medium max-w-2xl">
                            Transparence totale sur l&apos;état technique du projet. Suivez les correctifs en temps réel et les évolutions à venir.
                        </p>
                    </div>

                    <div className="flex items-center gap-6 px-6 py-4 rounded-3xl bg-white/[0.03] border border-white/5 backdrop-blur-xl">
                        <div className="text-center">
                            <p className="text-[10px] font-black text-zinc-600 uppercase tracking-widest mb-1">Total</p>
                            <p className="text-xl font-black text-white">{issues.length}</p>
                        </div>
                        <div className="w-px h-8 bg-white/5" />
