    "Normal": "bg-blue-500/10 text-blue-500 border-blue-500/20",
    "Faible": "bg-slate-500/10 text-slate-500 border-slate-500/20",
};

const StatusBadge = ({ status }: { status: SystemIssueStatus }) => {
