} from "lucide-react";
import { toast } from "sonner";
import { updatePlatformConfig, testStatusPing, testBackupNotification, toggleMaintenanceMode } from "@/server/actions/changelog-actions";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { diagnoseDiscordConnectivity } from "@/server/actions/god-discord-actions";
import { 
    Tooltip, 
    TooltipContent, 
    TooltipProvider, 
    TooltipTrigger 
} from "@/components/ui/tooltip";

interface PlatformConfigPanelProps {
    config: {
        id: string;
        hubChannelId: string | null;
        serviceStatusChannelId: string | null;
        godNotifyChannelId: string | null;
        godNotifyRoleId: string | null;
        godNotifyWebEnabled: boolean;
        ticketAutoRoleId: string | null;
        ticketSupportGuildId: string | null;
        statusIsLite: boolean;
        statusMode: string;
        statusMention: string;
        statusFrequency: number;
        nsfwFilterEnabled: boolean;
        donationsEnabled: boolean;
        maintenanceMode: boolean;
        maintenanceMessage: string | null;
    } | null;
    availableGuilds: { id: string, name: string }[];
    availableRoles: { id: string, name: string }[];
}

export function PlatformConfigPanel({ config, availableGuilds, availableRoles }: PlatformConfigPanelProps) {
    const [isPending, startTransition] = useTransition();
    const [formData, setFormData] = useState({
        hubChannelId: config?.hubChannelId || "",
        serviceStatusChannelId: config?.serviceStatusChannelId || "",
        godNotifyChannelId: config?.godNotifyChannelId || "",
        godNotifyRoleId: config?.godNotifyRoleId || "",
        godNotifyWebEnabled: config?.godNotifyWebEnabled !== undefined ? config?.godNotifyWebEnabled : true,
        ticketAutoRoleId: config?.ticketAutoRoleId || "",
        ticketSupportGuildId: config?.ticketSupportGuildId || "",
        statusIsLite: config?.statusIsLite || false,
        statusMode: config?.statusMode || "living",
        statusMention: config?.statusMention || "none",
        statusFrequency: config?.statusFrequency || 15,
        nsfwFilterEnabled: config?.nsfwFilterEnabled !== undefined ? config?.nsfwFilterEnabled : true,
        donationsEnabled: config?.donationsEnabled !== undefined ? config?.donationsEnabled : true,
        maintenanceMode: config?.maintenanceMode || false,
        maintenanceMessage: config?.maintenanceMessage || ""
    });

    const [diagResults, setDiagResults] = useState<any>(null);
    const [isDiagPending, setIsDiagPending] = useState(false);

    const handleSave = () => {
        startTransition(async () => {
            const res = await updatePlatformConfig(formData);
            if (res.success) {
                toast.success("Configuration sauvegardée !");
            } else {
                toast.error(res.error || "Erreur de sauvegarde");
            }
        });
    };

    const handleTestPing = () => {
        startTransition(async () => {
            toast.promise(testStatusPing(formData.serviceStatusChannelId), {
                loading: "Envoi du ping de service...",
                success: (res: any) => {
                    if (res.success) return `Message de STATUT envoyé avec succès !`;
                    throw new Error(res.error);
                },
                error: (err: any) => `Erreur : ${err.message}`
            });
        });
    };

    const handleTestBackup = () => {
        startTransition(async () => {
            toast.promise(testBackupNotification(formData.godNotifyChannelId), {
                loading: "Envoi de l'alerte ADMIN (Test)...",
                success: (res: any) => {
                    if (res.success) return `Alerte ADMIN envoyée avec succès !`;
                    throw new Error(res.error);
                },
                error: (err: any) => `Erreur : ${err.message}`
            });
        });
    };

    const handleToggleMaintenance = () => {
        const newValue = !formData.maintenanceMode;
        startTransition(async () => {
            const res = await toggleMaintenanceMode(newValue, formData.maintenanceMessage);
            if (res.success) {
                setFormData(prev => ({ ...prev, maintenanceMode: newValue }));
                toast.success(`Mode maintenance ${newValue ? "activé" : "désactivé"} !`, {
                    description: newValue ? "Le site est maintenant réservé aux admins." : "Le site est de nouveau public.",
                    icon: newValue ? <Lock className="w-4 h-4 text-rose-500" /> : <Globe className="w-4 h-4 text-emerald-500" />
                });
            } else {
                toast.error(res.error || "Erreur de mise à jour");
            }
        });
    };

    const handleDiagnose = async () => {
        setIsDiagPending(true);
        try {
            const res = await diagnoseDiscordConnectivity();
            if (res.success) {
                setDiagResults(res.results);
                toast.success("Diagnostic terminé ! Regarde le rapport juste en dessous.");
            } else {
                toast.error(res.error || "Échec du diagnostic");
            }
        } catch (e: any) {
            toast.error(e.message);
        } finally {
            setIsDiagPending(false);
        }
    };

    const inputClasses = "w-full h-14 px-6 bg-zinc-900 border border-white/10 rounded-2xl text-sm text-white focus:outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 transition-all font-mono shadow-inner placeholder:text-zinc-700";

    return (
        <div className="space-y-10 animate-in fade-in duration-500 pb-20">
            
            {/* BARRE D'ACTIONS PRO */}
            <div className="bg-zinc-950/60 border border-white/10 rounded-3xl p-6 backdrop-blur-xl flex flex-col sm:flex-row items-start sm:items-center justify-between gap-6 shadow-2xl">
                <div className="flex items-center gap-4">
                    <div className="w-12 h-12 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-center">
                        <Settings className="w-6 h-6 text-indigo-400" />
                    </div>
                    <div>
                        <h3 className="text-lg font-black text-white uppercase tracking-wider">Infrastructure & Configuration</h3>
                        <p className="text-zinc-500 text-xs font-semibold">Gestion des intégrations Discord, routage des alertes et statut d'accès.</p>
                    </div>
                </div>

                <div className="flex items-center gap-3 w-full sm:w-auto">
                    <button
                        onClick={handleDiagnose}
                        disabled={isDiagPending}
                        className="flex-1 sm:flex-none px-4 py-3 bg-zinc-900 hover:bg-zinc-800 border border-white/10 text-zinc-300 text-xs font-bold rounded-xl flex items-center justify-center gap-2 transition-all active:scale-95"
                    >
                        {isDiagPending ? <Loader2 className="w-4 h-4 animate-spin text-indigo-400" /> : <ClipboardList className="w-4 h-4" />}
                        Scan Accès
                    </button>
                    
                    <button
                        onClick={handleSave}
                        disabled={isPending}
                        className="flex-1 sm:flex-none px-6 py-3 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-black uppercase tracking-wider rounded-xl flex items-center justify-center gap-2 transition-all shadow-lg shadow-indigo-500/20 active:scale-95"
                    >
                        {isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                        Sauvegarder
                    </button>
                </div>
            </div>

            {/* RAPPORT DE DIAGNOSTIC DISCORD */}
            {diagResults && (
                <div className="bg-indigo-500/10 border border-indigo-500/20 rounded-3xl p-6 space-y-4 animate-in slide-in-from-top-4 duration-300">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2 text-xs font-black text-indigo-300 uppercase tracking-wider">
                            <ShieldCheck className="w-4 h-4" /> Rapport de Diagnostic Discord
                        </div>
                        <button onClick={() => setDiagResults(null)} className="text-[10px] text-zinc-500 hover:text-white font-bold uppercase">Fermer</button>
                    </div>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-xs font-bold">
                        <div className="p-4 rounded-xl bg-zinc-950/80 border border-white/5 space-y-1">
                            <span className="text-[9px] text-zinc-500 uppercase block">Connexion Bot</span>
                            <span className={cn(diagResults.token.status === "OK" ? "text-emerald-400" : "text-rose-400")}>{diagResults.token.message}</span>
                        </div>
                        <div className="p-4 rounded-xl bg-zinc-950/80 border border-white/5 space-y-1">
                            <span className="text-[9px] text-zinc-500 uppercase block">Identité Bot</span>
                            <span className="text-white font-mono">{diagResults.botIdentity?.username || "N/A"}</span>
                        </div>
                        <div className="p-4 rounded-xl bg-zinc-950/80 border border-white/5 space-y-1">
                            <span className="text-[9px] text-zinc-500 uppercase block">Serveurs</span>
                            <span className="text-white">{diagResults.guilds.length} actifs</span>
                        </div>
                        <div className="p-4 rounded-xl bg-zinc-950/80 border border-white/5 space-y-1">
                            <span className="text-[9px] text-zinc-500 uppercase block">Salons accessibles</span>
                            <div className="flex flex-wrap gap-1">
                                {Object.entries(diagResults.channels).map(([k, v]: any) => (
                                    <span key={k} className={cn("text-[9px] font-mono px-1.5 py-0.5 rounded", v.status === "OK" ? "bg-emerald-500/20 text-emerald-400" : "bg-rose-500/20 text-rose-400")}>{k}</span>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* CARTE 1: ROUTAGE DES SALONS DISCORD */}
            <div className="p-8 rounded-3xl bg-zinc-950/40 border border-white/5 space-y-6">
                <div className="border-b border-white/5 pb-4 space-y-1">
                    <h4 className="text-sm font-black text-white uppercase tracking-wider flex items-center gap-2">
                        <Server className="w-4 h-4 text-indigo-400" />
                        Routage des Salons Discord (Core System)
                    </h4>
                    <p className="text-zinc-500 text-xs font-medium">Définissez les canaux d'émission pour les Changelogs, la surveillance de santé et les alertes d'administration.</p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {/* Salon Hub */}
                    <div className="p-5 rounded-2xl bg-zinc-900/30 border border-white/5 space-y-4">
                        <div className="space-y-1">
                            <span className="text-xs font-black text-white uppercase block">1. Salon Hub (Changelog)</span>
                            <p className="text-[10px] text-zinc-500 leading-normal">Diffusion des mises à jour publiques.</p>
                        </div>
                        <Input
                            type="text"
                            value={formData.hubChannelId}
                            onChange={(e) => setFormData(prev => ({ ...prev, hubChannelId: e.target.value }))}
                            placeholder="ID Discord du salon..."
                            className="bg-zinc-900 border-white/10 text-xs font-mono"
                        />
                    </div>

                    {/* Salon Santé */}
                    <div className="p-5 rounded-2xl bg-zinc-900/30 border border-white/5 space-y-4">
                        <div className="flex justify-between items-start">
                            <div className="space-y-1">
                                <span className="text-xs font-black text-white uppercase block">2. Salon Santé (Ping Status)</span>
                                <p className="text-[10px] text-zinc-500 leading-normal">Surveillance automatique du bot.</p>
                            </div>
                            <Button size="sm" variant="ghost" onClick={handleTestPing} className="text-[9px] font-black uppercase text-emerald-400 bg-emerald-500/10 border border-emerald-500/20 hover:bg-emerald-500/20">
                                Test Ping
                            </Button>
                        </div>
                        <Input
                            type="text"
                            value={formData.serviceStatusChannelId}
                            onChange={(e) => setFormData(prev => ({ ...prev, serviceStatusChannelId: e.target.value }))}
                            placeholder="ID Discord du salon..."
                            className="bg-zinc-900 border-white/10 text-xs font-mono"
                        />
                        <div className="grid grid-cols-2 gap-2">
                            <Select value={String(formData.statusFrequency)} onValueChange={(val) => setFormData(prev => ({ ...prev, statusFrequency: parseInt(val) }))}>
                                <SelectTrigger className="bg-zinc-900 border-white/10 text-[10px] font-bold uppercase"><SelectValue /></SelectTrigger>
                                <SelectContent><SelectItem value="5">Toutes les 5m</SelectItem><SelectItem value="15">Toutes les 15m</SelectItem><SelectItem value="60">Toutes les 1h</SelectItem></SelectContent>
                            </Select>
                            <Select value={formData.statusMention} onValueChange={(val) => setFormData(prev => ({ ...prev, statusMention: val }))}>
                                <SelectTrigger className="bg-zinc-900 border-white/10 text-[10px] font-bold uppercase"><SelectValue /></SelectTrigger>
                                <SelectContent><SelectItem value="none">Sans mention</SelectItem><SelectItem value="@here">@here</SelectItem></SelectContent>
                            </Select>
                        </div>
                    </div>

                    {/* Salon Alertes God */}
                    <div className="p-5 rounded-2xl bg-zinc-900/30 border border-white/5 space-y-4">
                        <div className="flex justify-between items-start">
                            <div className="space-y-1">
                                <span className="text-xs font-black text-white uppercase block">3. Salon Alertes GOD (Privé)</span>
                                <p className="text-[10px] text-zinc-500 leading-normal">Rapports d'erreurs critiques & backups.</p>
                            </div>
                            <Button size="sm" variant="ghost" onClick={handleTestBackup} className="text-[9px] font-black uppercase text-rose-400 bg-rose-500/10 border border-rose-500/20 hover:bg-rose-500/20">
                                Test Alerte
                            </Button>
                        </div>
                        <Input
                            type="text"
                            value={formData.godNotifyChannelId}
                            onChange={(e) => setFormData(prev => ({ ...prev, godNotifyChannelId: e.target.value }))}
                            placeholder="ID Salon alertes..."
                            className="bg-zinc-900 border-white/10 text-xs font-mono"
                        />
                        <Input
                            type="text"
                            value={formData.godNotifyRoleId}
                            onChange={(e) => setFormData(prev => ({ ...prev, godNotifyRoleId: e.target.value }))}
                            placeholder="ID Rôle GOD (à ping)..."
                            className="bg-zinc-900 border-white/10 text-xs font-mono"
                        />
                    </div>
                </div>
            </div>

            {/* CARTE 2 & 3: OPTIONS SYSTÈME ET MAINTENANCE EN 2 COLONNES */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Options de sécurité / Fonctionnalités */}
                <div className="p-8 rounded-3xl bg-zinc-950/40 border border-white/5 space-y-6">
                    <div className="border-b border-white/5 pb-4 space-y-1">
                        <h4 className="text-sm font-black text-white uppercase tracking-wider flex items-center gap-2">
                            <ShieldCheck className="w-4 h-4 text-amber-400" />
                            Modules Plateforme & Sécurité
                        </h4>
                        <p className="text-zinc-500 text-xs font-medium">Interrupteurs d'activation globale des services optionnels.</p>
                    </div>

                    <div className="space-y-3">
                        {[
                            { key: "nsfwFilterEnabled", label: "IA Filtre NSFW", desc: "Inspection automatique des captures pour filtrer le contenu inapproprié." },
                            { key: "godNotifyWebEnabled", label: "Notifications Web Admin", desc: "Affichage des bannières d'alerte en temps réel sur l'interface." },
                            { key: "donationsEnabled", label: "Module Dons Orbes", desc: "Activation du widget de contribution financière sur les guildes." }
                        ].map((opt) => {
                            const active = (formData as any)[opt.key];
                            return (
                                <button
                                    key={opt.key}
                                    onClick={() => setFormData(prev => ({ ...prev, [opt.key]: !active }))}
                                    className={cn(
                                        "w-full p-4 rounded-2xl border transition-all text-left flex items-center justify-between gap-4",
                                        active ? "bg-indigo-500/10 border-indigo-500/30 text-white" : "bg-zinc-900/30 border-white/5 text-zinc-500 hover:border-white/10"
                                    )}
                                >
                                    <div className="space-y-0.5 min-w-0">
                                        <span className="text-xs font-bold block">{opt.label}</span>
                                        <span className="text-[10px] text-zinc-500 block truncate">{opt.desc}</span>
                                    </div>
                                    <span className={cn("text-[9px] font-black uppercase px-2.5 py-1 rounded-lg shrink-0", active ? "bg-emerald-500/20 text-emerald-400 border border-emerald-500/30" : "bg-zinc-900 text-zinc-600")}>
                                        {active ? "Actif" : "Inactif"}
                                    </span>
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* Mode Maintenance (Killswitch) */}
                <div className="p-8 rounded-3xl bg-zinc-950/40 border border-white/5 space-y-6 flex flex-col justify-between">
                    <div className="border-b border-white/5 pb-4 space-y-1">
                        <h4 className="text-sm font-black text-white uppercase tracking-wider flex items-center gap-2">
                            <Power className="w-4 h-4 text-rose-400" />
                            Accès Plateforme & Maintenance
                        </h4>
                        <p className="text-zinc-500 text-xs font-medium">Restreint l'accès au site uniquement aux Super-Admins.</p>
                    </div>

                    <div className="space-y-4">
                        <Input
                            type="text"
                            value={formData.maintenanceMessage}
                            onChange={(e) => setFormData(prev => ({ ...prev, maintenanceMessage: e.target.value }))}
                            placeholder="Message de maintenance personnalisé..."
                            className="bg-zinc-900 border-white/10 text-xs font-medium"
                        />

                        <button
                            onClick={handleToggleMaintenance}
                            className={cn(
                                "w-full h-16 rounded-2xl text-xs font-black uppercase tracking-widest transition-all border flex items-center justify-center gap-3 shadow-lg active:scale-98",
                                formData.maintenanceMode
                                    ? "bg-rose-500 hover:bg-rose-600 text-white border-rose-400 shadow-rose-500/20"
                                    : "bg-zinc-900 hover:bg-zinc-800 text-zinc-300 border-white/10"
                            )}
                        >
                            <Lock className="w-4 h-4" />
                            {formData.maintenanceMode ? "DÉSACTIVER LA MAINTENANCE (Site En Ligne)" : "ACTIVER LA MAINTENANCE (Verrouiller le site)"}
                        </button>
                    </div>
                </div>
            </div>

        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { getGuildsStorageStats } from "@/server/actions/god-storage-actions";
import { HardDrive, Activity, Image as ImageIcon, Loader2 } from "lucide-react";

export function StoragePanel() {
    const [stats, setStats] = useState<any[] | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        getGuildsStorageStats().then((data) => {
            setStats(data);
            setIsLoading(false);
        });
    }, []);

    const formatBytes = (bytes: number) => {
        if (bytes === 0) return '0 B';
        const k = 1024;
        const sizes = ['B', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
    };

    if (isLoading) {
        return (
            <div className="bg-zinc-900/30 border border-white/5 rounded-3xl p-8 backdrop-blur-xl flex items-center justify-center min-h-[300px]">
                <Loader2 className="w-8 h-8 animate-spin text-zinc-500" />
            </div>
        );
    }

    return (
        <div className="bg-zinc-900/30 border border-white/5 rounded-3xl p-8 backdrop-blur-xl space-y-8">
            <div className="flex items-center gap-3">
                <HardDrive className="w-6 h-6 text-blue-500" />
                <h3 className="text-xl font-black text-white uppercase tracking-widest">
                    Ressources Disque & Captures
                </h3>
            </div>

            <div className="grid gap-4">
                {stats?.map((guild) => (
                    <div key={guild.id} className="bg-black/40 border border-white/5 rounded-2xl p-6">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <h4 className="font-bold text-lg text-white">{guild.name}</h4>
                                <p className="text-xs text-zinc-500">{guild.members} membres inscrits</p>
                            </div>
                            <div className="text-right">
                                <p className="font-mono text-xl text-blue-400 font-bold">{formatBytes(guild.sizeBytes)}</p>
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-4 mt-6">
                            <div className="bg-zinc-900/50 rounded-xl p-4 border border-white/5 flex items-center gap-4">
                                <div className="p-3 bg-amber-500/10 rounded-lg">
                                    <ImageIcon className="w-5 h-5 text-amber-500" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black uppercase tracking-widest text-zinc-500">
                                        Captures en attente
                                    </p>
                                    <p className="text-xl font-black text-white">{guild.pendingSubmissions}</p>
                                </div>
                            </div>

                            <div className="bg-zinc-900/50 rounded-xl p-4 border border-white/5 flex items-center gap-4">
                                <div className="p-3 bg-emerald-500/10 rounded-lg">
                                    <Activity className="w-5 h-5 text-emerald-500" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black uppercase tracking-widest text-zinc-500">
                                        Captures (/jour)
                                    </p>
                                    <p className="text-xl font-black text-white">{guild.submissionsToday} ajoutées ajd.</p>
                                </div>
                            </div>
                        </div>
                    </div>
                ))}

                {stats?.length === 0 && (
                    <div className="text-center text-zinc-500 py-12 border border-white/5 rounded-2xl bg-black/20">
                        Aucune guilde active pour les statistiques.
                    </div>
                )}
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { 
    Database, 
    Zap, 
    ShieldCheck, 
    RefreshCw, 
    CheckCircle2, 
    AlertTriangle, 
    Loader2,
    Clock,
    TerminalSquare,
    Cpu
} from "lucide-react";
import { getInternalSystemStatus } from "@/server/actions/god-system-actions";
import { formatDistanceToNow } from "date-fns";
import { fr } from "date-fns/locale";

interface SystemStatus {
    database: { 
        status: string; 
        latency: number; 
        insights?: { auditLogs: number; profiles: number; missions: number } 
    };
    cache: { status: string; latency: number };
    backup: { status: string; lastAt: Date | null };
    worker: { 
        status: string; 
        lastAt: Date | null; 
        queues?: { 
            metamob: { waiting: number; active: number; failed: number };
            ladder: { waiting: number; active: number; failed: number };
        } 
    };
    maintenance: { status: string; lastAt: Date | null; metrics?: any };
    disk?: { totalMb: number; freeMb: number; usagePercent: number };
    ram?: { totalMb: number; freeMb: number; usagePercent: number };
}

export function SystemHealthDashboard() {
    const [status, setStatus] = useState<SystemStatus | null>(null);
    const [loading, setLoading] = useState(true);

    const fetchStatus = async () => {
        const res = await getInternalSystemStatus();
        if (res) setStatus(res as SystemStatus);
        setLoading(false);
    };

    useEffect(() => {
        fetchStatus();
        const interval = setInterval(fetchStatus, 30000); // Poll every 30s
        return () => clearInterval(interval);
    }, []);

    if (loading) return (
        <div className="flex items-center justify-center p-12 bg-zinc-900/20 border border-white/5 rounded-3xl animate-pulse">
            <div className="flex flex-col items-center gap-4">
                <Loader2 className="w-6 h-6 text-zinc-600 animate-spin" />
                <span className="text-[10px] font-black text-zinc-700 uppercase tracking-widest">Analyse des systèmes...</span>
            </div>
        </div>
    );

    if (!status) return (
        <div className="p-12 bg-rose-500/5 border border-rose-500/10 rounded-3xl text-center space-y-4">
            <AlertTriangle className="w-8 h-8 text-rose-500 mx-auto" />
            <div className="space-y-1">
                <p className="text-sm font-bold text-white uppercase tracking-tight">Erreur de Diagnostic</p>
                <p className="text-xs text-zinc-500 max-w-sm mx-auto">Le serveur n'a pas pu renvoyer l'état de santé. Vérifiez les logs ou réessayez.</p>
            </div>
            <button onClick={() => { setLoading(true); fetchStatus(); }} className="px-4 py-2 bg-rose-500/10 hover:bg-rose-500/20 text-rose-500 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all">
                Réessayer la connexion
            </button>
        </div>
    );

    const getDiskDisplay = () => {
        if (!status.disk || status.disk.totalMb === 0) return "Jamais";
        const totalGb = (status.disk.totalMb / 1024).toFixed(1);
        const freeGb = (status.disk.freeMb / 1024).toFixed(1);
        return `${freeGb}Go libres / ${totalGb}Go`;
    };

    const getRamDisplay = () => {
        if (!status.ram || status.ram.totalMb === 0) return "Jamais";
        const totalGb = (status.ram.totalMb / 1024).toFixed(1);
        const freeGb = (status.ram.freeMb / 1024).toFixed(1);
        return `${freeGb}Go libres / ${totalGb}Go`;
    };

    const totalWaitingJobs = (status.worker.queues?.metamob.waiting || 0) + (status.worker.queues?.ladder.waiting || 0);

    const cards = [
        {
            label: "Base de données",
            subLabel: "PostgreSQL Prisma",
            value: status.database.status === "ONLINE" ? `${status.database.latency}ms` : "OFFLINE",
            status: status.database.status,
            icon: Database,
            color: "emerald",
            footer: status.database.insights ? `${(status.database.insights.auditLogs / 1000).toFixed(1)}k logs / ${status.database.insights.profiles} profils` : null
        },
        {
            label: "Moteur Cache",
            subLabel: "Redis WebSocket",
            value: status.cache.status === "ONLINE" ? `${status.cache.latency}ms` : "OFFLINE",
            status: status.cache.status,
            icon: Zap,
            color: "amber"
        },
        {
            label: "Stockage Système",
            subLabel: "/dev/root OS Disk",
            value: getDiskDisplay(),
            status: status.disk && status.disk.usagePercent < 85 ? "ONLINE" : "OFFLINE",
            icon: TerminalSquare,
            color: status.disk && status.disk.usagePercent >= 85 ? "rose" : "cyan"
        },
        {
            label: "Mémoire Vive (RAM)",
            subLabel: "OS Node Allocation",
            value: getRamDisplay(),
            status: status.ram && status.ram.usagePercent < 90 ? "ONLINE" : "OFFLINE",
            icon: Cpu,
            color: status.ram && status.ram.usagePercent >= 90 ? "rose" : "violet"
        },
        {
            label: "Worker Platforms",
            subLabel: "Ladder & Metamob",
            value: status.worker.lastAt ? formatDistanceToNow(new Date(status.worker.lastAt), { addSuffix: true, locale: fr }) : "En attente",
            status: status.worker.status === "IDLE" ? "ONLINE" : "OFFLINE",
            icon: RefreshCw,
            color: "rose",
            footer: status.worker.queues ? `${totalWaitingJobs} tâches en attente` : null
        },
        {
            label: "Dernier Backup",
            subLabel: "Cloudflare R2 Storage",
            value: status.backup.lastAt ? formatDistanceToNow(new Date(status.backup.lastAt), { addSuffix: true, locale: fr }) : "Aucun",
            status: status.backup.status === "SUCCESS" ? "ONLINE" : "OFFLINE",
            icon: ShieldCheck,
            color: status.backup.status === "SUCCESS" ? "indigo" : "rose",
            footer: status.backup.status === "FAILED" ? "La sauvegarde a échoué" : (status.backup.status === "SUCCESS" ? "Stockage R2 OK" : "Non configuré")
        }
    ];

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4 mb-8">
            {cards.map((card, i) => (
                <div key={i} className="group relative overflow-hidden bg-zinc-900/40 border border-white/5 p-5 rounded-3xl transition-all hover:bg-zinc-900/60 hover:border-white/10">
                    {/* Background Glow */}
                    <div className={`absolute top-0 right-0 w-24 h-24 bg-${card.color}-500/5 blur-[40px] -translate-y-1/2 translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity`} />
                    
                    <div className="flex items-start justify-between mb-4">
                        <div className={`p-2 rounded-xl bg-zinc-900 border border-white/5 text-zinc-400 group-hover:text-${card.color}-400 group-hover:border-${card.color}-500/20 transition-all`}>
                            <card.icon className="w-4 h-4" />
                        </div>
                        <div className={`flex items-center gap-1.5 px-2 py-1 rounded-full bg-zinc-900/50 border border-white/5`}>
                            <div className={`w-1.5 h-1.5 rounded-full ${card.status === 'ONLINE' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-rose-500 shadow-[0_0_8px_rgba(239,68,68,0.5)]'}`} />
                            <span className="text-[8px] font-black uppercase tracking-widest text-zinc-500">
                                {card.status === 'ONLINE' ? 'Ok' : 'Err'}
                            </span>
                        </div>
                    </div>

                    <div className="space-y-1">
                        <div className="text-[10px] font-black text-zinc-600 uppercase tracking-widest leading-none">
                            {card.subLabel}
                        </div>
                        <div className="text-sm font-bold text-white group-hover:tracking-wide transition-all truncate">
                            {card.label}
                        </div>
                    </div>

                    <div className="mt-4 flex items-end justify-between">
                        <div className="space-y-1">
                            <div className="text-lg font-black text-zinc-400 group-hover:text-white transition-colors">
                                {card.value}
                            </div>
                            {card.footer && (
                                <div className="text-[8px] font-black text-zinc-600 uppercase tracking-widest whitespace-nowrap">
                                    {card.footer}
                                </div>
                            )}
                        </div>
                        <Clock className="w-3.5 h-3.5 text-zinc-800" />
                    </div>
                </div>
            ))}
        </div>
    );
}

"use client";

import { useState, useMemo } from "react";
import { deleteGhostUser, cleanupGhostUsers } from "@/server/actions/super-admin-actions";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { Trash2, AlertTriangle, UserX, Loader2, CheckCircle2, Search, Copy, Clock, Calendar, MousePointer2, CalendarCheck } from "lucide-react";
import { cn } from "@/lib/utils";

interface TargetPurgePanelProps {
    ghostUsers: any[];
}

export function TargetPurgePanel({ ghostUsers }: TargetPurgePanelProps) {
    const [isPurgingAll, setIsPurgingAll] = useState(false);
    const [purgingId, setPurgingId] = useState<string | null>(null);
    const [search, setSearch] = useState("");

    const filteredUsers = useMemo(() => {
        if (!search) return ghostUsers;
        const s = search.toLowerCase();
        return ghostUsers.filter(u => 
            u.name?.toLowerCase().includes(s) || 
            u.id.toLowerCase().includes(s) || 
            u.accounts?.[0]?.providerAccountId?.includes(s)
        );
    }, [ghostUsers, search]);

    const handlePurgeAll = async () => {
        if (!confirm("Voulez-vous purger TOUS les comptes orphelins vieux de plus de 24h ?")) return;
        setIsPurgingAll(true);
        try {
            const res = await cleanupGhostUsers();
            if (res.success) {
                toast.success(`${res.count} comptes purgés !`);
            } else {
                toast.error("Erreur lors de la purge.");
            }
        } catch (e: any) {
            toast.error(e.message || "Erreur inattendue");
        } finally {
            setIsPurgingAll(false);
        }
    };

    const handleDeleteUser = async (user: any) => {
        if (!confirm(`Purger définitivement le compte de ${user.name || "Inconnu"} ?`)) return;
        setPurgingId(user.id);
        try {
            const res = await deleteGhostUser(user.id);
            if (res.success) {
                toast.success(`Compte ${user.name || user.id} purgé avec succès.`);
            }
        } catch (e: any) {
            toast.error(e.message || "Impossible de purger l'utilisateur.");
        } finally {
            setPurgingId(null);
        }
    };

    const copyToClipboard = (text: string) => {
        navigator.clipboard.writeText(text);
        toast.success("ID copié !");
    };

    return (
        <div className="bg-zinc-900/10 border border-white/5 rounded-3xl p-8 backdrop-blur-xl h-full flex flex-col gap-6 shadow-2xl relative overflow-hidden">
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 relative z-10">
                <div className="space-y-1">
                    <h3 className="text-xs font-black text-amber-500 uppercase tracking-[0.3em] flex items-center gap-3">
                        <AlertTriangle className="w-4 h-4" />
                        Target Purge Zone
                    </h3>
                    <p className="text-zinc-500 text-[10px] font-bold uppercase tracking-widest">Identification & Nettoyage des Ghost Users</p>
                </div>
                
                <div className="flex flex-wrap items-center gap-4">
                    <div className="relative group flex-1 min-w-[200px]">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-600 group-focus-within:text-amber-500 transition-colors" />
                        <Input 
                            placeholder="Rechercher (Nom, ID, Discord)..." 
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            className="pl-12 h-12 bg-black/40 border-white/5 focus:border-amber-500/50 rounded-2xl text-xs font-bold uppercase tracking-widest transition-all"
                        />
                    </div>

                    <div className="flex items-center gap-6 bg-black/40 px-6 py-3 rounded-2xl border border-white/5 shadow-inner">
                        <div className="flex flex-col items-center">
                            <span className="text-3xl font-black text-rose-500 leading-none">{ghostUsers.length}</span>
                            <span className="text-[8px] font-black text-rose-500/50 uppercase tracking-tighter mt-1">Total</span>
                        </div>
                        {ghostUsers.length > 0 && (
                            <Button
                                variant="destructive"
                                size="sm"
                                disabled={isPurgingAll}
                                onClick={handlePurgeAll}
                                className="bg-rose-500 text-white hover:bg-rose-600 font-black uppercase tracking-widest text-[9px] h-10 px-5 shadow-[0_0_20px_rgba(244,63,94,0.3)]"
                            >
                                {isPurgingAll ? <Loader2 className="w-3 h-3 mr-2 animate-spin" /> : <Trash2 className="w-3 h-3 mr-2" />}
                                Purge Globale
                            </Button>
                        )}
                    </div>
                </div>
            </div>

            {/* Explanatory Banner */}
            <div className="bg-amber-500/5 border border-amber-500/10 rounded-2xl p-5 flex gap-4 items-start relative z-10">
                <div className="p-2.5 rounded-xl bg-amber-500/10 text-amber-500 shrink-0">
                    <UserX className="w-5 h-5" />
                </div>
                <div className="space-y-1">
                    <h4 className="text-[10px] font-black text-amber-500 uppercase tracking-widest leading-none">Aide au Diagnostic</h4>
                    <p className="text-[10px] text-zinc-500 leading-relaxed font-bold uppercase tracking-tight">
                        Ces utilisateurs ont un compte mais **aucun** profil de guilde. 
                        Vérifie l'activité (sessions) avant de purger. Un utilisateur avec 0 session est probablement un robot ou une erreur de connexion.
                    </p>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto pr-2 space-y-3 custom-scrollbar relative z-10">
                {filteredUsers.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-16 border border-dashed border-white/5 rounded-[2.5rem] bg-black/20 text-zinc-600 mt-2">
                        {search ? (
                            <p className="font-black uppercase tracking-widest text-xs">Aucun résultat pour "{search}"</p>
                        ) : (
                            <>
                                <CheckCircle2 className="w-12 h-12 mb-4 opacity-20" />
                                <p className="font-black uppercase tracking-widest text-xs">Aucune cible détectée</p>
                            </>
                        )}
                    </div>
                ) : (
                    filteredUsers.map((user) => {
                        const discordId = user.accounts?.[0]?.providerAccountId;
                        const lastActivity = user.sessions?.[0]?.expires;
                        
                        return (
                            <div key={user.id} className="flex flex-col sm:flex-row sm:items-center justify-between p-4 bg-black/40 border border-white/5 rounded-2xl hover:bg-black/60 hover:border-white/10 transition-all group gap-4">
                                <div className="flex items-center gap-4">
                                    <div className="relative shrink-0">
                                        {user.image ? (
                                            <img src={user.image} alt="" className="w-12 h-12 rounded-xl opacity-80 group-hover:opacity-100 transition-opacity" />
                                        ) : (
                                            <div className="w-12 h-12 rounded-xl bg-zinc-800 flex items-center justify-center border border-white/5">
                                                <UserX className="w-5 h-5 text-zinc-600" />
                                            </div>
                                        )}
                                        {user._count?.sessions > 0 && (
                                            <div className="absolute -top-1 -right-1 w-3 h-3 bg-emerald-500 rounded-full border-2 border-black animate-pulse" title="Session active" />
                                        )}
                                    </div>
                                    
                                    <div className="space-y-1.5 overflow-hidden">
                                        <div className="flex items-center gap-3">
                                            <h4 className="font-black text-sm text-white tracking-tight truncate uppercase italic">{user.name || "Utilisateur"}</h4>
                                            {discordId && (
                                                <button 
                                                    onClick={() => copyToClipboard(discordId)}
                                                    className="p-1.5 rounded-md hover:bg-white/5 text-zinc-600 hover:text-white transition-all"
                                                    title="Copier Discord ID"
                                                >
                                                    <Copy className="w-3 h-3" />
                                                </button>
                                            )}
                                        </div>
                                        
                                        <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
                                            <div className="flex items-center gap-1.5 text-zinc-500">
                                                <Calendar className="w-3 h-3" />
                                                <span className="text-[9px] font-bold uppercase tracking-tighter">Créé: {new Date(user.createdAt).toLocaleDateString()}</span>
                                            </div>
                                            
                                            <div className="flex items-center gap-1.5 text-zinc-500">
                                                <MousePointer2 className="w-3 h-3" />
                                                <span className="text-[9px] font-bold uppercase tracking-tighter">{user._count?.sessions} sessions</span>
                                            </div>

                                            {user._count?.guildEvents > 0 && (
                                                <div className="flex items-center gap-1.5 text-amber-500">
                                                    <CalendarCheck className="w-3 h-3" />
                                                    <span className="text-[9px] font-bold uppercase tracking-tighter text-amber-500/80">{user._count.guildEvents} events</span>
                                                </div>
                                            )}

                                            {lastActivity && (
                                                <div className="flex items-center gap-1.5 text-blue-400/70 italic">
                                                    <Clock className="w-3 h-3" />
                                                    <span className="text-[9px] font-bold uppercase tracking-tighter">Actif: {new Date(lastActivity).toLocaleDateString()}</span>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                </div>

                                <div className="flex items-center gap-2 justify-end shrink-0">
                                    <div className="flex flex-col items-end mr-4 hidden md:flex gap-1.5">
                                         <span className={cn(
                                             "text-[8px] font-black uppercase tracking-widest px-2 py-0.5 rounded-md border",
                                             user._count?.sessions > 0 ? "text-emerald-500 border-emerald-500/20 bg-emerald-500/5" : "text-zinc-600 border-white/5 bg-white/5"
                                         )}>
                                             {user._count?.sessions > 0 ? "Interactif" : "Visiteur"}
                                         </span>
                                         
                                         {/* New indicator for Whitelist membership */}
                                         {user.memberInWhitelists && user.memberInWhitelists.length > 0 && (
                                             <div className="flex flex-col items-end gap-1">
                                                 <span className="text-[7px] font-black uppercase tracking-tighter text-amber-500/80 bg-amber-500/5 border border-amber-500/10 px-1.5 rounded-sm">
                                                     Sur Whitelist
                                                 </span>
                                                 <div className="flex flex-wrap gap-1 justify-end max-w-[150px]">
                                                     {user.memberInWhitelists.map((gName: string, idx: number) => (
                                                         <span key={idx} className="text-[7px] text-zinc-500 whitespace-nowrap">{gName}</span>
                                                     ))}
                                                 </div>
                                             </div>
                                         )}
                                     </div>

                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        onClick={() => handleDeleteUser(user)}
                                        disabled={purgingId === user.id || isPurgingAll}
                                        className="h-10 w-10 text-zinc-600 hover:text-rose-400 hover:bg-rose-500/10 rounded-xl transition-all"
                                    >
                                        {purgingId === user.id ? <Loader2 className="w-4 h-4 animate-spin text-rose-500" /> : <Trash2 className="w-4 h-4" />}
                                    </Button>
                                </div>
                            </div>
                        );
                    })
                )}
            </div>
            
            <div className="absolute bottom-0 right-0 w-64 h-64 bg-rose-500/5 blur-[120px] rounded-full -mr-32 -mb-32 pointer-events-none" />
        </div>
    );
}

"use client";

import { useEffect, useState, useCallback, useRef } from "react";
import { 
    ResponsiveContainer, 
    AreaChart, 
    Area, 
    XAxis, 
    YAxis, 
    Tooltip, 
    CartesianGrid 
} from "recharts";
import { 
    Activity, 
    MousePointer, 
    Users, 
    Flame, 
    RefreshCw,
    TrendingUp, 
    Calendar,
    Search,
    UserCheck,
    Globe,
    Cpu
} from "lucide-react";
import { cn } from "@/lib/utils";
import { getTelemetryStats } from "@/server/actions/telemetry-actions";

type TelemetryStatsType = Awaited<ReturnType<typeof getTelemetryStats>>;

export function TelemetryDashboard({ initialStats }: { initialStats: TelemetryStatsType }) {
    const [stats, setStats] = useState<TelemetryStatsType>(initialStats);
    const [selectedGuildId, setSelectedGuildId] = useState<string>("all");
    const [isAutoRefresh, setIsAutoRefresh] = useState(true);
    const [countdown, setCountdown] = useState(5);
    const [isPending, setIsPending] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");
    const [telemetryTab, setTelemetryTab] = useState<"live" | "modules" | "analytics" | "users" | "guilds">("live");
    const isRefreshingRef = useRef(false);

    // Stable refresh function — accepts target guild filter
    const refreshData = useCallback(async (overrideGuildId?: string) => {
        if (isRefreshingRef.current) return;
        isRefreshingRef.current = true;
        setIsPending(true);
        try {
            const targetGuild = overrideGuildId !== undefined ? overrideGuildId : selectedGuildId;
            const filterArg = targetGuild === "all" ? undefined : targetGuild;
            const newStats = await getTelemetryStats(filterArg);
            setStats(newStats);
            setCountdown(5);
        } catch (err) {
            console.error("Refresh failed", err);
        } finally {
            isRefreshingRef.current = false;
            setIsPending(false);
        }
    }, [selectedGuildId]);

    // Handle guild selection change
    const handleGuildChange = (newGuildId: string) => {
        setSelectedGuildId(newGuildId);
        refreshData(newGuildId);
    };

    // Auto-refresh timer — countdown only, triggers refresh outside render via ref
    useEffect(() => {
        if (!isAutoRefresh) return;

        const interval = setInterval(() => {
            setCountdown((prev) => {
                if (prev <= 1) {
                    Promise.resolve().then(() => refreshData());
                    return 5;
                }
                return prev - 1;
            });
        }, 1000);

        return () => clearInterval(interval);
    }, [isAutoRefresh, refreshData]);

    // Filter live events based on search query
    const filteredEvents = stats.liveEvents.filter((e: any) => {
        if (!searchQuery) return true;

        const query = searchQuery.toLowerCase();
        return (
            e.userName.toLowerCase().includes(query) ||
            e.path.toLowerCase().includes(query) ||
            (e.elementId && e.elementId.toLowerCase().includes(query)) ||
            e.eventType.toLowerCase().includes(query)
        );
    });

    const activeUserCount = stats.usersLastSeen.length;

    return (
        <div className="space-y-10">
            {/* Header / Control Bar */}
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6 pb-6 border-b border-white/5">
                <div className="space-y-1">
                    <h2 className="text-2xl font-black text-white uppercase italic tracking-tight flex items-center gap-3">
                        <Cpu className="w-6 h-6 text-violet-400 animate-pulse" />
                        Télémétrie & Analyse d'usage
                    </h2>
                    <p className="text-zinc-500 text-xs font-semibold uppercase tracking-widest">
                        Activité, fréquentation des modules et comportements par guilde
                    </p>
                </div>

                <div className="flex flex-wrap items-center gap-4">
                    {/* Guild Filter Dropdown */}
                    <div className="flex items-center gap-2 bg-zinc-900/80 border border-white/10 px-3 py-1.5 rounded-xl">
                        <Globe className="w-4 h-4 text-violet-400 shrink-0" />
                        <select
                            value={selectedGuildId}
                            onChange={(e) => handleGuildChange(e.target.value)}
                            className="bg-transparent text-xs font-bold text-white focus:outline-none cursor-pointer pr-2"
                        >
                            <option value="all" className="bg-zinc-900 text-white">Toutes les Guildes (Global)</option>
                            {stats.availableGuilds?.map((g: any) => (
                                <option key={g.id} value={g.id} className="bg-zinc-900 text-white">
                                    Guilde: {g.name}
                                </option>
                            ))}
                        </select>
                    </div>

                    {/* Auto-Refresh Toggle */}
                    <button
                        onClick={() => setIsAutoRefresh(!isAutoRefresh)}
                        className={cn(
                            "flex items-center gap-2.5 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-wider transition-all border",
                            isAutoRefresh 
                                ? "bg-violet-500/10 text-violet-400 border-violet-500/20" 
                                : "bg-zinc-900/50 text-zinc-500 border-white/5 hover:text-zinc-300"
                        )}
                    >
                        <span className={cn(
                            "w-2.5 h-2.5 rounded-full",
                            isAutoRefresh ? "bg-violet-400 animate-ping" : "bg-zinc-600"
                        )} />
                        {isAutoRefresh ? `Auto : ${countdown}s` : "Auto-Refresh Off"}
                    </button>

                    {/* Manual Refresh Button */}
                    <button
                        onClick={() => refreshData()}
                        disabled={isPending}
                        className="p-2.5 rounded-xl bg-zinc-900 border border-white/5 hover:border-white/10 text-zinc-400 hover:text-white transition-all disabled:opacity-50 disabled:cursor-not-allowed group"
                    >
                        <RefreshCw className={cn("w-4 h-4 group-hover:rotate-180 transition-all duration-700", isPending && "animate-spin")} />
                    </button>
                </div>
            </div>

            {/* Sub Tabs Selection */}
            <div className="flex border-b border-white/5 pb-1 gap-2 overflow-x-auto no-scrollbar">
                {[
                    { id: "live", label: "Flux Temps Réel", count: filteredEvents.length },
                    { id: "modules", label: "Consommation Modules", count: stats.moduleStats?.length || 0 },
                    { id: "analytics", label: "Analyses de Trafic", count: null },
                    { id: "users", label: "Membres Actifs", count: activeUserCount },
                    { id: "guilds", label: "Activité Guildes", count: stats.guildActivity.length },
                ].map((t) => (
                    <button
                        key={t.id}
                        onClick={() => setTelemetryTab(t.id as any)}
                        className={cn(
                            "px-6 py-3.5 rounded-xl text-xs font-black uppercase tracking-wider transition-all border flex items-center gap-2 whitespace-nowrap",
                            telemetryTab === t.id
                                ? "bg-violet-500/10 text-violet-400 border-violet-500/25"
                                : "bg-transparent text-zinc-500 border-transparent hover:text-zinc-300 hover:bg-white/5"
                        )}
                    >
                        {t.label}
                        {t.count !== null && (
                            <span className={cn(
                                "text-[9px] font-black px-1.5 py-0.5 rounded-md",
                                telemetryTab === t.id ? "bg-violet-500/20 text-violet-300" : "bg-zinc-900 text-zinc-600"
                            )}>
