                    <div className="w-px h-6 bg-white/5 mx-2" />
                    <Button
                        type="button"
                        variant="ghost"
                        onClick={() => router.back()}
                        className="rounded-xl text-zinc-500 hover:text-white hover:bg-white/5 font-bold px-4"
