                                                                          const n = [...activeBlocks];
                                                                          (n[bIdx] as any).name = r.name;
                                                                          (n[bIdx] as any).id = r.id;
                                                                          (n[bIdx] as any).imageUrl = r.imageUrl;
                                                                          setActiveBlocks(n);
                                                                          setSearchingBlockIdx(null);
                                                                          setSearchResults([]);
