                                <div className="absolute right-0 top-0 bottom-0 w-1 bg-amber-500 shadow-[0_0_20px_rgba(245,158,11,1)]" />
                            )}
                        </button>
                    ))}
                </div>

                {/* Editor Section */}
                <div className={cn(
