                                                        <span className={cn(
                                                            "text-[8px] font-black uppercase px-2 py-0.5 rounded-md",
                                                            subareaNames.includes(selectedBounty.zoneName)
                                                                ? "bg-emerald-500/10 text-emerald-400"
                                                                : "bg-rose-500/10 text-rose-400"
                                                        )}>
                                                            {subareaNames.includes(selectedBounty.zoneName) ? '✓ Zone trouvée' : '⚠ Zone introuvable'}
                                                        </span>
                                                    )}
                                                </label>
                                                <div className="relative">
                                                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-600 pointer-events-none" size={16} />
                                                    <input
                                                        value={zoneOpen ? zoneSearch : (selectedBounty.zoneName || '')}
                                                        onChange={(e) => {
                                                            setZoneSearch(e.target.value);
                                                            if (!zoneOpen) setZoneOpen(true);
                                                        }}
                                                        onFocus={() => {
                                                            setZoneSearch(selectedBounty.zoneName || '');
                                                            setZoneOpen(true);
                                                        }}
                                                        onBlur={() => setTimeout(() => setZoneOpen(false), 150)}
                                                        placeholder="Rechercher une zone du worldmap..."
                                                        className="w-full pl-12 pr-4 bg-black/40 border border-white/5 font-bold h-14 rounded-2xl text-white text-sm focus:outline-none focus:border-amber-500/40 focus:ring-1 focus:ring-amber-500/20 transition-all"
                                                    />
                                                    {zoneOpen && (
                                                        <div className="absolute top-full left-0 right-0 mt-1 max-h-64 overflow-y-auto bg-[#0d1117] border border-white/10 rounded-2xl shadow-2xl z-50">
                                                            {(() => {
                                                                const q = zoneSearch.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
                                                                const filtered = subareaNames.filter(n =>
                                                                    n.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().includes(q)
                                                                ).slice(0, 40);
                                                                if (filtered.length === 0) return (
                                                                    <div className="px-4 py-3 text-zinc-600 text-[10px] italic text-center">Aucune zone trouvée</div>
                                                                );
                                                                return filtered.map(name => (
                                                                    <button
                                                                        key={name}
                                                                        type="button"
                                                                        onMouseDown={() => {
                                                                            setSelectedBounty({ ...selectedBounty, zoneName: name });
                                                                            setZoneSearch(name);
                                                                            setZoneOpen(false);
                                                                        }}
                                                                        className={cn(
                                                                            "w-full text-left px-4 py-2.5 text-sm font-bold transition-colors border-b border-white/5 last:border-0 flex items-center justify-between group",
                                                                            selectedBounty.zoneName === name
                                                                                ? "bg-amber-500/10 text-amber-400"
                                                                                : "text-zinc-300 hover:bg-white/5 hover:text-white"
                                                                        )}
                                                                    >
                                                                        <span>{name}</span>
                                                                        {selectedBounty.zoneName === name && <Check size={12} className="text-amber-400 flex-shrink-0" />}
                                                                    </button>
                                                                ));
                                                            })()}
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </TabsContent>

                                <TabsContent value="rewards" className="mt-0 space-y-8">
                                    <div className="flex items-center justify-between">
                                        <div className="flex flex-col">
                                            <h3 className="text-xl font-black text-white uppercase italic tracking-tight flex items-center gap-3">
                                                <Coins className="text-amber-500" size={24} />
                                                Dotations de Capture
                                            </h3>
                                            <p className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest mt-1">Liste des récompenses obtenues à la remise de l'avis</p>
                                        </div>
                                        <Button
                                            onClick={addReward}
                                            className="bg-white/5 border border-white/10 hover:bg-white/10 text-white font-black uppercase italic rounded-xl px-6 h-12"
                                        >
                                            <Plus size={18} className="mr-2" /> Ajouter
                                        </Button>
                                    </div>

                                    <div className="grid grid-cols-1 gap-4">
                                        {selectedBounty.rewards?.map((reward: any, idx: number) => (
                                            <div key={idx} className="p-6 rounded-3xl bg-black/40 border border-white/5 flex items-center gap-8 relative group hover:border-amber-500/30 transition-all">
                                                <div className="w-16 h-16 rounded-2xl bg-black border border-white/5 flex items-center justify-center shrink-0">
                                                    <img
                                                        src={REWARD_TYPES.find(t => t.id === reward.type)?.icon || "/assets/avis/aliton.png"}
                                                        alt=""
                                                        className="w-12 h-12 object-contain"
                                                    />
                                                </div>

                                                <div className="flex-1 grid grid-cols-3 gap-8">
                                                    <div className="space-y-2">
                                                        <label className="text-[9px] font-black text-zinc-600 uppercase tracking-[0.2em] italic ml-1">Type de monnaie</label>
                                                        <div className="flex flex-wrap gap-2">
                                                            {REWARD_TYPES.map(type => (
                                                                <button
                                                                    key={type.id}
                                                                    onClick={() => updateReward(idx, "type", type.id)}
                                                                    className={cn(
                                                                        "px-4 py-2 rounded-xl text-[10px] font-black uppercase italic transition-all border",
                                                                        reward.type === type.id
                                                                            ? "bg-amber-500 text-black border-amber-500 shadow-[0_0_15px_rgba(245,158,11,0.3)]"
                                                                            : "bg-white/5 text-zinc-500 border-white/5 hover:border-white/10"
                                                                    )}
                                                                >
                                                                    {type.label}
                                                                </button>
                                                            ))}
                                                        </div>
                                                    </div>
                                                    <div className="space-y-2">
                                                        <label className="text-[9px] font-black text-zinc-600 uppercase tracking-[0.2em] italic ml-1">Montant</label>
                                                        <Input
                                                            type="number"
                                                            value={reward.amount}
                                                            onChange={(e) => updateReward(idx, "amount", parseInt(e.target.value) || 0)}
                                                            className="bg-black/60 border-white/5 font-black h-12 rounded-xl text-lg text-amber-500 focus-visible:ring-amber-500/30"
                                                        />
                                                    </div>
                                                </div>

                                                <button
                                                    onClick={() => removeReward(idx)}
                                                    className="p-3 text-zinc-700 hover:text-rose-500 transition-colors bg-white/5 rounded-xl border border-white/5 hover:border-rose-500/20"
                                                >
                                                    <Trash2 size={20} />
                                                </button>
                                            </div>
                                        ))}
                                    </div>
                                </TabsContent>

                                <TabsContent value="mechanics" className="mt-0 space-y-8">
                                    <div className="flex items-center justify-between">
                                        <div className="flex flex-col">
                                            <h3 className="text-xl font-black text-white uppercase italic tracking-tight flex items-center gap-3">
                                                <Sparkles className="text-amber-500" size={24} />
                                                Briefing Tactique
                                            </h3>
                                            <p className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest mt-1">Supporte le Markdown pour un formattage riche</p>
                                        </div>
                                        <div className="flex bg-white/5 p-1 rounded-xl border border-white/10">
                                            <button
                                                onClick={() => setPreviewMode(false)}
                                                className={cn("px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all", !previewMode ? "bg-amber-500 text-black" : "text-zinc-500 hover:text-white")}
                                            >
                                                Édition
                                            </button>
                                            <button
                                                onClick={() => setPreviewMode(true)}
                                                className={cn("px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all", previewMode ? "bg-amber-500 text-black" : "text-zinc-500 hover:text-white")}
                                            >
                                                Aperçu
                                            </button>
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-1 gap-6">
                                        <div className="p-1 rounded-[2.5rem] bg-gradient-to-br from-white/5 to-transparent border border-white/5 shadow-2xl relative overflow-hidden group min-h-[500px]">
                                            <div className="absolute top-0 left-0 w-1 h-full bg-amber-500/20 group-hover:bg-amber-500 transition-all shadow-[0_0_20px_rgba(245,158,11,0.5)]" />
                                            {!previewMode ? (
                                                <div className="relative h-full">
                                                    <AdvancedEditor
                                                        initialContent={selectedBounty.mechanics || ""}
                                                        onChange={(html) => setSelectedBounty({ ...selectedBounty, mechanics: html })}
                                                        contentClassName="min-h-[500px]"
                                                    />
                                                </div>
                                            ) : (
                                                <div className="p-10">
                                                    <DocContent 
                                                        content={selectedBounty.mechanics || "<p><em>Aucun contenu à prévisualiser</em></p>"} 
                                                    />
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                </TabsContent>
                            </Tabs>
                        </div>
                    ) : (
                        <div className="h-full flex flex-col items-center justify-center text-center space-y-8 opacity-40 min-h-[600px]">
                            <div className="relative">
                                <ShieldAlert size={120} className="text-zinc-900" />
                                <div className="absolute inset-0 animate-pulse bg-amber-500/5 rounded-full blur-3xl" />
                            </div>
                            <div className="space-y-4">
                                <p className="text-4xl font-black uppercase italic tracking-tighter text-zinc-800">Archive Scellée</p>
                                <p className="text-[10px] font-black uppercase tracking-[0.5em] text-zinc-600">Sélectionnez une cible pour engager le protocole d'édition</p>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            <AssetGalleryModal
                open={galleryOpen}
                onOpenChange={setGalleryOpen}
                initialType={galleryType}
                onSelect={(url) => {
                    if (galleryType === "portraits") {
                        setSelectedBounty({ ...selectedBounty, imageUrl: url });
                    } else {
                        setSelectedBounty({ ...selectedBounty, mapUrl: url });
                    }
                }}
                title={galleryType === "portraits" ? "Sélecteur de Portraits" : "Sélecteur de Minimaps"}
            />

            <style jsx global>{`
                .custom-scrollbar::-webkit-scrollbar {
                    width: 4px;
                }
                .custom-scrollbar::-webkit-scrollbar-track {
                    background: transparent;
                }
                .custom-scrollbar::-webkit-scrollbar-thumb {
                    background: rgba(255, 255, 255, 0.03);
                    border-radius: 10px;
                }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover {
                    background: rgba(255, 255, 255, 0.08);
                }
            `}</style>
        </div>
    );
}

"use client";

import { useSearchParams, useRouter } from "next/navigation";
import { cn } from "@/lib/utils";

interface GodDashboardClientProps {
    children: React.ReactNode;
    activeTab: string;
}

export function GodDashboardClient({
    children,
    activeTab,
}: GodDashboardClientProps) {
    const searchParams = useSearchParams();
    const router = useRouter();

    const handleTabChange = (newTab: string) => {
        // Update URL without full refresh to maintain state on reload
        const params = new URLSearchParams(searchParams.toString());
        params.set("tab", newTab);
        router.push(`/god?${params.toString()}`, { scroll: false });
    };

    return (
        <div className="flex flex-col flex-1 h-full overflow-hidden bg-black">
            {/* MAIN CONTENT */}
            <main className="flex-1 overflow-y-auto bg-black block">
                <div className="w-full max-w-[2500px] mx-auto px-4 lg:px-12 pt-10 pb-40 relative">
                    {children}
                </div>
                
            </main>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Plus, Trash2, Power, PowerOff, Copy, Check } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { addAllowedGuild, removeAllowedGuild, toggleGuildActive } from "@/server/actions/super-admin-actions";
import { toast } from "sonner";

interface AllowedGuild {
    id: string;
    discordGuildId: string;
    name: string | null;
    tier: string;
    isActive: boolean;
    addedBy: string;
    addedAt: Date;
    expiresAt: Date | null;
    notes: string | null;
}

interface GuildManagerProps {
    initialGuilds: AllowedGuild[];
}

export function GuildManager({ initialGuilds }: GuildManagerProps) {
    const [guilds, setGuilds] = useState(initialGuilds);
    const [newGuildId, setNewGuildId] = useState("");
    const [newGuildName, setNewGuildName] = useState("");
    const [newGuildNotes, setNewGuildNotes] = useState("");
    const [isAdding, setIsAdding] = useState(false);
    const [copiedId, setCopiedId] = useState<string | null>(null);

    const handleAdd = async () => {
        if (!newGuildId.trim()) {
            toast.error("L'ID Discord est requis");
            return;
        }

        setIsAdding(true);
        try {
            const guild = await addAllowedGuild({
                discordGuildId: newGuildId.trim(),
                name: newGuildName.trim() || undefined,
                notes: newGuildNotes.trim() || undefined,
            });
            setGuilds([guild, ...guilds]);
            setNewGuildId("");
            setNewGuildName("");
            setNewGuildNotes("");
            toast.success("Guilde ajoutée à la liste blanche");
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "Erreur lors de l'ajout");
        } finally {
            setIsAdding(false);
        }
    };

    const handleRemove = async (discordGuildId: string) => {
        if (!confirm("Supprimer cette guilde de la liste blanche ?")) return;

        try {
            await removeAllowedGuild(discordGuildId);
            setGuilds(guilds.filter(g => g.discordGuildId !== discordGuildId));
            toast.success("Guilde retirée");
        } catch (error) {
            toast.error("Erreur lors de la suppression");
        }
    };

    const handleToggle = async (discordGuildId: string) => {
        try {
            const updated = await toggleGuildActive(discordGuildId);
            setGuilds(guilds.map(g => g.discordGuildId === discordGuildId ? updated : g));
            toast.success(updated.isActive ? "Guilde activée" : "Guilde désactivée");
        } catch (error) {
            toast.error("Erreur lors du changement de statut");
        }
    };

    const handleCopy = (id: string) => {
        navigator.clipboard.writeText(id);
        setCopiedId(id);
        setTimeout(() => setCopiedId(null), 2000);
    };

    return (
        <div className="space-y-6">
            {/* UI Clarification Alert */}
            <div className="bg-blue-500/10 border border-blue-500/20 rounded-xl p-4 flex items-start gap-3">
                <div className="mt-1">
                    <Check className="w-5 h-5 text-blue-400" />
                </div>
                <div className="space-y-1">
                    <p className="text-sm font-bold text-blue-400 uppercase tracking-wider">Note sur la Liste Blanche</p>
                    <p className="text-xs text-zinc-400 leading-relaxed">
                        Cette page gère l'autorisation de <strong>première connexion</strong>. Ajouter un ID ici permet au bot de rejoindre le serveur et de commencer l'onboarding. Une fois onboardée, la guilde apparaîtra dans la section <strong className="text-zinc-200">Guildes Actives</strong> pour la gestion au quotidien.
                    </p>
                </div>
            </div>

            {/* Add Form */}
            <div className="bg-zinc-900/50 border border-zinc-800 rounded-lg p-6">
                <div className="flex items-center justify-between mb-4">
                    <h2 className="text-lg font-semibold text-white">Autoriser une Guilde</h2>
                    <span className="text-[10px] bg-zinc-800 text-zinc-500 px-2 py-1 rounded uppercase font-black tracking-widest border border-white/5">Etape 1: Permission</span>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <Input
                        placeholder="Discord Guild ID *"
                        value={newGuildId}
                        onChange={(e) => setNewGuildId(e.target.value)}
                        className="bg-zinc-800 border-zinc-700"
                    />
                    <Input
                        placeholder="Nom (optionnel)"
                        value={newGuildName}
                        onChange={(e) => setNewGuildName(e.target.value)}
                        className="bg-zinc-800 border-zinc-700"
                    />
                    <Input
                        placeholder="Notes (optionnel)"
                        value={newGuildNotes}
                        onChange={(e) => setNewGuildNotes(e.target.value)}
                        className="bg-zinc-800 border-zinc-700"
                    />
                    <Button
                        onClick={handleAdd}
                        disabled={isAdding}
                        className="bg-amber-600 hover:bg-amber-700"
                    >
                        <Plus className="w-4 h-4 mr-2" />
                        {isAdding ? "Ajout..." : "Ajouter"}
                    </Button>
                </div>
            </div>

            {/* Guilds Table */}
            <div className="bg-zinc-900/50 border border-zinc-800 rounded-lg overflow-hidden">
                <table className="w-full">
                    <thead className="bg-zinc-800/50">
                        <tr>
                            <th className="text-left px-4 py-3 text-xs text-zinc-400 font-medium">Statut</th>
                            <th className="text-left px-4 py-3 text-xs text-zinc-400 font-medium">ID Discord</th>
                            <th className="text-left px-4 py-3 text-xs text-zinc-400 font-medium">Nom</th>
                            <th className="text-left px-4 py-3 text-xs text-zinc-400 font-medium">Tier</th>
                            <th className="text-left px-4 py-3 text-xs text-zinc-400 font-medium">Notes</th>
                            <th className="text-left px-4 py-3 text-xs text-zinc-400 font-medium">Ajouté le</th>
                            <th className="text-right px-4 py-3 text-xs text-zinc-400 font-medium">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-zinc-800">
                        {guilds.length === 0 ? (
                            <tr>
                                <td colSpan={7} className="px-4 py-8 text-center text-zinc-500">
                                    Aucune guilde autorisée. Ajoutez-en une ci-dessus.
                                </td>
                            </tr>
                        ) : guilds.map((guild) => (
                            <tr key={guild.id} className={!guild.isActive ? "opacity-50" : ""}>
                                <td className="px-4 py-3">
                                    <button
                                        onClick={() => handleToggle(guild.discordGuildId)}
                                        className={`p-1.5 rounded ${guild.isActive ? "text-green-400 hover:bg-green-500/10" : "text-zinc-500 hover:bg-zinc-700/50"}`}
                                        title={guild.isActive ? "Désactiver" : "Activer"}
                                    >
                                        {guild.isActive ? <Power className="w-4 h-4" /> : <PowerOff className="w-4 h-4" />}
                                    </button>
                                </td>
                                <td className="px-4 py-3">
                                    <div className="flex items-center gap-2">
                                        <code className="text-xs text-zinc-300 font-mono">{guild.discordGuildId}</code>
                                        <button
                                            onClick={() => handleCopy(guild.discordGuildId)}
                                            className="text-zinc-500 hover:text-white"
                                        >
                                            {copiedId === guild.discordGuildId ? (
                                                <Check className="w-3 h-3 text-green-400" />
                                            ) : (
                                                <Copy className="w-3 h-3" />
                                            )}
                                        </button>
                                    </div>
                                </td>
                                <td className="px-4 py-3 text-sm text-white">
                                    {guild.name || <span className="text-zinc-500">—</span>}
                                </td>
                                <td className="px-4 py-3">
                                    <span className={`text-xs px-2 py-1 rounded ${guild.tier === "PREMIUM" ? "bg-amber-500/20 text-amber-400" :
                                        guild.tier === "FREE" ? "bg-green-500/20 text-green-400" :
                                            "bg-zinc-700 text-zinc-300"
                                        }`}>
                                        {guild.tier}
                                    </span>
                                </td>
                                <td className="px-4 py-3 text-xs text-zinc-400 max-w-[200px] truncate">
                                    {guild.notes || <span className="text-zinc-600">—</span>}
                                </td>
                                <td className="px-4 py-3 text-xs text-zinc-400">
                                    {new Date(guild.addedAt).toLocaleDateString("fr-FR")}
                                </td>
                                <td className="px-4 py-3 text-right">
                                    <button
                                        onClick={() => handleRemove(guild.discordGuildId)}
                                        className="text-red-400/60 hover:text-red-400 p-1.5 rounded hover:bg-red-500/10"
                                        title="Supprimer"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}

import { redirect, notFound } from "next/navigation";
import { isSuperAdmin } from "@/server/actions/super-admin-actions";
import { getGuildMembersForGod } from "@/server/actions/god-lifecycle-actions";
import { MemberManagementTable } from "@/components/admin/member-management-table";
import { Shield, ChevronLeft, Users } from "lucide-react";
import Link from "next/link";
import { db } from "@/lib/prisma";

interface GodGuildDetailsPageProps {
    params: Promise<{ id: string }>;
}

export default async function GodGuildDetailsPage({ params }: GodGuildDetailsPageProps) {
    const isAdmin = await isSuperAdmin();

    if (!isAdmin) {
        redirect("/");
    }

    const { id: guildId } = await params;

    // Fetch individual guild config for the header
    const guild = await db.guildConfig.findUnique({
        where: { id: guildId },
        select: { name: true, discordGuildId: true, iconUrl: true, welcomeBadgeName: true }
    });

    if (!guild) {
        return notFound();
    }

    const members = await getGuildMembersForGod(guildId);

    return (
        <div className="space-y-8 py-8">
            {/* Header */}
            <div className="flex flex-col gap-6">
                <Link
                    href="/god"
                    className="inline-flex items-center gap-2 text-zinc-500 hover:text-white transition-colors text-xs font-black uppercase tracking-widest group"
                >
                    <ChevronLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
                    Retour au Panneau de Contrôle
                </Link>

                <div className="flex items-center justify-between gap-4">
                    <div className="flex items-center gap-6">
                        <div className="relative group/icon">
                            <div className="absolute -inset-4 bg-violet-500/20 blur-2xl rounded-full opacity-0 group-hover/icon:opacity-100 transition-opacity" />
                            {guild.iconUrl && guild.iconUrl.length > 5 ? (
                                <div className="relative w-24 h-24 rounded-3xl overflow-hidden border-2 border-white/10 bg-zinc-900 shadow-2xl">
                                    <img
                                        src={`https://cdn.discordapp.com/icons/${guild.discordGuildId}/${guild.iconUrl}.png?size=256`}
                                        alt=""
                                        className="w-full h-full object-cover"
                                    />
                                    <div className="absolute inset-0 bg-gradient-to-t from-black/40 to-transparent" />
                                </div>
                            ) : (
                                <div className="w-24 h-24 rounded-3xl bg-gradient-to-br from-violet-500 to-violet-700 flex items-center justify-center text-4xl font-black text-white border-2 border-white/10 shadow-2xl relative z-10 uppercase">
                                    {guild.name[0]}
                                </div>
                            )}
                        </div>

                        <div className="space-y-1">
                            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-violet-500/10 border border-violet-500/20 text-[10px] font-black text-violet-400 uppercase tracking-widest">
                                <Shield className="w-3 h-3" />
                                Inspection God Mode
                            </div>
                            <h1 className="text-4xl font-black text-white tracking-tighter">
                                {guild.name}
                            </h1>
                            <p className="text-zinc-500 font-mono text-xs uppercase tracking-widest">
                                {guild.discordGuildId}
                            </p>
                        </div>
                    </div>

                    <div className="px-6 py-4 bg-zinc-900/50 border border-white/5 rounded-2xl text-center min-w-[140px]">
                        <div className="text-2xl font-black text-white tracking-tighter">{members.members.length}</div>
                        <div className="text-[10px] font-black text-zinc-600 uppercase tracking-widest">Membres Totaux</div>
                    </div>
                </div>
            </div>

