        </div>
    );
}

"use client";

import { useState } from "react";
import { formatDistanceToNow } from "date-fns";
import { fr } from "date-fns/locale";
import {
    History,
    User,
    AlertCircle,
    Key,
    Terminal,
    Plus,
    X,
    Search,
    Filter,
    ChevronLeft,
    ChevronRight,
    Clock,
    UserMinus,
    Trash2,
    Shield,
    Building2,
    Settings,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue
} from "@/components/ui/select";
import { useEffect, useCallback } from "react";

interface AuditLog {
    id: string;
    actorUserId: string;
    actorName: string;
    action: string;
    targetType: string;
    targetId: string | null;
    oldValue: any;
    newValue: any;
    metadata: any;
    createdAt: Date;
    guild?: {
        name: string;
        discordGuildId: string;
    };
}

interface LogViewerProps {
    initialLogs: AuditLog[];
    initialTotal: number;
}

const ITEMS_PER_PAGE = 50;

const ACTION_OPTIONS = [
    { value: "all", label: "Toutes les actions" },
    { value: "SECURITY_ALERT", label: "🚨 Alertes de Sécurité" },
    { value: "RBAC_UPDATE,RBAC_ROLE_ADD,RBAC_ROLE_REMOVE", label: "Permissions" },
    { value: "GOD_GUILD_WHITELIST,GOD_USER_PLATFORM_BAN,GOD_CONFIG_OVERRIDE,GOD_DATABASE_SYNC", label: "🛡️ Actions God" },
    { value: "WEBHOOK_MEMBER_ADD,WEBHOOK_MEMBER_REMOVE,WEBHOOK_MEMBER_UPDATE", label: "🔄 Mouvements" },
    { value: "USER_GDPR_DELETE", label: "🗑️ Suppressions RGPD" },
    { value: "CONFIG_UPDATED", label: "Configuration" },
    { value: "ADMIN_FULL_DENIED", label: "Accès refusé" },
];

export function LogViewer({ initialLogs, initialTotal }: LogViewerProps) {
    const [logs, setLogs] = useState(initialLogs);
    const [total, setTotal] = useState(initialTotal);
    const [page, setPage] = useState(1);
    const [loading, setLoading] = useState(false);

    // Filters
    const [actionFilter, setActionFilter] = useState<string>("all");
    const [searchQuery, setSearchQuery] = useState("");
    const [debouncedSearch, setDebouncedSearch] = useState("");

    const totalPages = Math.ceil(total / ITEMS_PER_PAGE);

    // Debounce search
    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedSearch(searchQuery);
        }, 300);
        return () => clearTimeout(timer);
    }, [searchQuery]);

    // Fetch logs when filters or page change
    const fetchLogs = useCallback(async () => {
        setLoading(true);
        try {
            const params = new URLSearchParams({
                page: page.toString(),
                limit: ITEMS_PER_PAGE.toString(),
            });

            if (actionFilter && actionFilter !== "all") {
                params.set("action", actionFilter);
            }
            if (debouncedSearch) {
                params.set("search", debouncedSearch);
            }

            const res = await fetch(`/api/god/audit-logs?${params.toString()}`);
            if (res.ok) {
                const data = await res.json();
                setLogs(data.logs);
                setTotal(data.total);
            }
        } catch (error) {
            console.error("Failed to fetch logs:", error);
        } finally {
            setLoading(false);
        }
    }, [page, actionFilter, debouncedSearch]);

    useEffect(() => {
        // Skip initial fetch since we have initialLogs
        if (page === 1 && actionFilter === "all" && !debouncedSearch) {
            return;
        }
        fetchLogs();
    }, [page, actionFilter, debouncedSearch, fetchLogs]);

    // Reset page when filters change
    useEffect(() => {
        setPage(1);
    }, [actionFilter, debouncedSearch]);

    const clearFilters = () => {
        setActionFilter("all");
        setSearchQuery("");
        setDebouncedSearch("");
        setPage(1);
    };

    const hasActiveFilters = actionFilter !== "all" || debouncedSearch;

    const getActionColors = (action: string) => {
        if (action.includes("RBAC")) return "bg-amber-500/10 text-amber-400 border-amber-500/20";
        if (action.includes("SECURITY")) return "bg-red-500/10 text-red-400 border-red-500/20 animate-pulse";
        if (action.includes("CONFIG")) return "bg-blue-500/10 text-blue-400 border-blue-500/20";
        if (action.startsWith("GOD_")) return "bg-violet-500/10 text-violet-400 border-violet-500/20 shadow-[0_0_10px_rgba(139,92,246,0.1)]";
        if (action === "WEBHOOK_MEMBER_ADD") return "bg-emerald-500/10 text-emerald-400 border-emerald-500/20";
        if (action === "WEBHOOK_MEMBER_REMOVE") return "bg-zinc-500/10 text-zinc-400 border-white/10";
        if (action === "WEBHOOK_MEMBER_UPDATE") return "bg-indigo-500/10 text-indigo-400 border-indigo-500/20";
        if (action === "USER_GDPR_DELETE") return "bg-red-500/10 text-red-400 border-red-500/50 hover:bg-red-500/20";
        return "bg-zinc-500/10 text-zinc-400 border-white/5";
    };

    const getActionIcon = (action: string) => {
        if (action.includes("RBAC")) return <Key className="w-3.5 h-3.5" />;
        if (action.includes("SECURITY")) return <AlertCircle className="w-3.5 h-3.5" />;
        if (action.includes("CONFIG")) return <Settings className="w-3.5 h-3.5" />;
        if (action.includes("MEMBER_ADD")) return <Plus className="w-3.5 h-3.5" />;
        if (action === "WEBHOOK_MEMBER_REMOVE") return <UserMinus className="w-3.5 h-3.5" />;
        if (action === "USER_GDPR_DELETE") return <Trash2 className="w-3.5 h-3.5" />;
        if (action.startsWith("GOD_")) return <Terminal className="w-3.5 h-3.5 text-violet-400" />;
        return <Shield className="w-3.5 h-3.5" />;
    };

    const formatActionLabel = (action: string) => {
        if (action === "WEBHOOK_MEMBER_ADD") return "Arrivée Membre";
        if (action === "WEBHOOK_MEMBER_REMOVE") return "Départ Membre";
        if (action === "WEBHOOK_MEMBER_UPDATE") return "MàJ Membre";
        return action.replace(/_/g, " ");
    };

    const formatValue = (val: any) => {
        if (!val || typeof val !== "object") return String(val);
        return JSON.stringify(val, null, 2);
    };

    return (
        <div className="space-y-4">
            {/* Filters Toolbar */}
            <div className="flex flex-wrap items-center gap-3 bg-zinc-900/40 p-3 rounded-2xl border border-white/5 backdrop-blur-md">
                <div className="flex items-center gap-2 px-2 border-r border-white/10 mr-2">
                    <Filter className="h-4 w-4 text-zinc-500" />
                    <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Filtres</span>
                </div>

                <Select value={actionFilter} onValueChange={setActionFilter}>
                    <SelectTrigger className="w-[180px] h-9 text-[11px] font-bold bg-zinc-800/50 border-white/10 rounded-xl">
                        <SelectValue placeholder="Type d'action" />
                    </SelectTrigger>
                    <SelectContent className="bg-zinc-900 border-white/10">
                        {ACTION_OPTIONS.map(opt => (
                            <SelectItem key={opt.value} value={opt.value} className="text-xs">
                                {opt.label}
                            </SelectItem>
                        ))}
                    </SelectContent>
                </Select>

                <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-zinc-500" />
                    <Input
                        type="text"
                        placeholder="Rechercher par acteur, guilde..."
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        className="h-9 w-[260px] pl-9 text-[11px] font-bold bg-zinc-800/50 border-white/10 rounded-xl"
                    />
                </div>

                {hasActiveFilters && (
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={clearFilters}
                        className="h-9 text-[10px] font-black text-zinc-500 hover:text-white uppercase tracking-widest"
                    >
                        <X className="h-3 w-3 mr-2" />
                        Réinitialiser
                    </Button>
                )}

                <div className="ml-auto flex items-center gap-4">
                    <div className="flex items-center gap-2 text-[10px] font-black text-zinc-500 uppercase tracking-widest">
                        Page <span className="text-zinc-300">{page}</span> / <span className="text-zinc-300">{totalPages || 1}</span>
                    </div>
                    <div className="flex gap-1">
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => setPage(p => Math.max(1, p - 1))}
                            disabled={page === 1 || loading}
                            className="h-8 w-8 p-0 bg-zinc-800/50 border-white/10 rounded-lg disabled:opacity-30"
                        >
                            <ChevronLeft className="h-4 h-4" />
                        </Button>
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                            disabled={page >= totalPages || loading}
                            className="h-8 w-8 p-0 bg-zinc-800/50 border-white/10 rounded-lg disabled:opacity-30"
                        >
                            <ChevronRight className="h-4 h-4" />
                        </Button>
                    </div>
                </div>
            </div>

            {/* Table */}
            <div className="bg-zinc-900/30 border border-white/5 rounded-2xl overflow-hidden backdrop-blur-xl max-h-[600px] overflow-y-auto">
                <table className="w-full text-left border-collapse">
                    <thead className="bg-white/5">
                        <tr>
                            <th className="px-6 py-4 text-[10px] font-black text-zinc-500 uppercase tracking-widest">Événement</th>
                            <th className="px-6 py-4 text-[10px] font-black text-zinc-500 uppercase tracking-widest">Acteur</th>
                            <th className="px-6 py-4 text-[10px] font-black text-zinc-500 uppercase tracking-widest">Cible / Guilde</th>
                            <th className="px-6 py-4 text-[10px] font-black text-zinc-500 uppercase tracking-widest">Détails</th>
                            <th className="px-6 py-4 text-[10px] font-black text-zinc-500 uppercase tracking-widest text-right">Date</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-white/5">
                        {logs.length === 0 ? (
                            <tr>
                                <td colSpan={5} className="px-6 py-20 text-center text-zinc-600 font-medium">
                                    Aucun log détecté dans la base de données.
                                </td>
                            </tr>
                        ) : logs.map((log) => (
                            <tr key={log.id} className="group hover:bg-white/[0.02] transition-colors">
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-3">
                                        <div className={cn(
                                            "flex items-center justify-center w-8 h-8 rounded-lg border transition-all duration-300",
                                            getActionColors(log.action)
                                        )}>
                                            {getActionIcon(log.action)}
                                        </div>
                                        <div className="flex flex-col">
                                            <span className="text-[11px] font-black uppercase tracking-tight text-white leading-none">
                                                {formatActionLabel(log.action)}
                                            </span>
                                            <span className="text-[9px] font-bold text-zinc-500 uppercase tracking-widest mt-1">
                                                {log.targetType}
                                            </span>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-2">
                                        <div className="w-6 h-6 rounded flex items-center justify-center bg-violet-500/10 border border-violet-500/20">
                                            <User className="w-3 h-3 text-violet-400" />
                                        </div>
                                        <span className="text-sm font-medium text-zinc-300">{log.actorName}</span>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="flex flex-col">
                                        <div className="flex items-center gap-2">
                                            <Building2 className="w-3 h-3 text-zinc-600" />
                                            <span className="text-sm font-medium text-zinc-400">{log.guild?.name || "Global / System"}</span>
                                        </div>
                                        {log.targetId && (
                                            <span className="text-[10px] font-mono text-zinc-600 ml-5">{log.targetId}</span>
                                        )}
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    {log.metadata && (
                                        <div className="max-w-xs truncate text-xs text-zinc-500 font-mono italic">
                                            {typeof log.metadata === 'string' ? log.metadata : JSON.stringify(log.metadata)}
                                        </div>
                                    )}
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <div className="text-sm font-medium text-zinc-400">
                                        {formatDistanceToNow(new Date(log.createdAt), { addSuffix: true, locale: fr })}
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Bottom Info */}
            <div className="flex items-center justify-between text-[10px] font-black text-zinc-600 uppercase tracking-widest px-2">
                <span>Affichage de <span className="text-zinc-400">{logs.length}</span> entrées sur un total de <span className="text-zinc-400">{total}</span></span>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Gamepad2, AlertTriangle, CheckCircle2, Save, Power, MessageSquare, RotateCcw, Ban, Flag, Trash2, Map, Plus, Loader2 } from "lucide-react";
import { updateMiniGameStatus, updateGeoguesserConfig, getMapsInfo } from "@/server/actions/god-mini-games-actions";
import { toast } from "sonner";
import { useSearchParams } from "next/navigation";
import { cn } from "@/lib/utils";

const WORLD_NAMES: Record<number, string> = {
    1: "Monde des Douze",
    2: "Incarnam",
    3: "Souterrains",
    4: "Souterrains d'Astrub",
    19: "Mappemondes",
    29: "Ecaflip City",
    156: "Dimension Divine",
    157: "Dimension Divine", // Often same
    312: "Havre-Sac",
    150: "Nimbos",
};

interface MiniGame {
    gameId: string;
    name: string;
    color: string;
}

const GAMES: MiniGame[] = [
    { gameId: "guesser", name: "Sigil-Guesser", color: "emerald" },
    { gameId: "bomb", name: "Sigil-Bomb", color: "red" },
];

type Tab = "MAINTENANCE" | "GUESSER";

export default function MiniGamesGodClient({ 
    initialStatuses, 
    initialPlatformConfig 
}: { 
    initialStatuses: any[],
    initialPlatformConfig: any
}) {
    const searchParams = useSearchParams();
    const activeTab = (searchParams.get("sub") as Tab) || "MAINTENANCE";

    const [statuses, setStatuses] = useState(
        GAMES.map(game => {
            const status = initialStatuses.find(s => s.gameId === game.gameId);
            return {
                ...game,
                isEnabled: status?.isEnabled ?? true,
                maintenanceMsg: status?.maintenanceMsg ?? "🔧 Ce jeu est temporairement indisponible pour maintenance.",
                isSaving: false
            };
        })
    );

    // Guesser Blacklist State
    const [blacklist, setBlacklist] = useState<number[]>(initialPlatformConfig?.geoguesserBlacklist || []);
    const [reportedIds, setReportedIds] = useState<number[]>((initialPlatformConfig?.geoguesserReportedMaps as number[]) || []);
    const [mapDetails, setMapDetails] = useState<Record<number, any>>({});
    const [isLoadingDetails, setIsLoadingDetails] = useState(false);
    const [manualId, setManualId] = useState("");
    const [isRefreshing, setIsRefreshing] = useState(false);
    const [worldFilter, setWorldFilter] = useState<string>("ALL");

    const refreshDataFromServer = async () => {
        setIsRefreshing(true);
        try {
            const { getPlatformConfig } = await import("@/server/actions/god-mini-games-actions");
            const freshConfig = await getPlatformConfig();
            setBlacklist(freshConfig.geoguesserBlacklist || []);
            setReportedIds((freshConfig.geoguesserReportedMaps as number[]) || []);
        } catch (err) {
            console.error("Failed to refresh config", err);
        } finally {
            setIsRefreshing(false);
        }
    };

    // Auto-refresh every 10s when on GUESSER tab
    useEffect(() => {
        if (activeTab !== "GUESSER") return;
        refreshDataFromServer(); // immediate refresh on tab switch
        const interval = setInterval(refreshDataFromServer, 10000);
        return () => clearInterval(interval);
    }, [activeTab]);

    // Fetch map details for reported and blacklisted maps
    useEffect(() => {
        const fetchDetails = async () => {
            const allIds = Array.from(new Set([...blacklist, ...reportedIds]));
            if (allIds.length === 0) return;
            
            setIsLoadingDetails(true);
            try {
                const details = await getMapsInfo(allIds);
                const detailMap: Record<number, any> = {};
                details.forEach(d => { detailMap[d.id] = d; });
                setMapDetails(detailMap);
            } catch (err) {
                console.error("Failed to fetch map details", err);
            } finally {
                setIsLoadingDetails(false);
            }
        };
        fetchDetails();
    }, [blacklist, reportedIds]);

    const handleToggle = (gameId: string) => {
        setStatuses(prev => prev.map(s => 
            s.gameId === gameId ? { ...s, isEnabled: !s.isEnabled } : s
        ));
    };

    const handleMsgChange = (gameId: string, msg: string) => {
        setStatuses(prev => prev.map(s => 
            s.gameId === gameId ? { ...s, maintenanceMsg: msg } : s
        ));
    };

    const saveStatus = async (gameId: string) => {
        const game = statuses.find(s => s.gameId === gameId);
        if (!game) return;

        setStatuses(prev => prev.map(s => s.gameId === gameId ? { ...s, isSaving: true } : s));

        try {
            await updateMiniGameStatus(gameId, game.isEnabled, game.maintenanceMsg);
            toast.success(`${game.name} mis à jour avec succès`);
        } catch (error) {
            toast.error("Erreur lors de la mise à jour");
            console.error(error);
        } finally {
            setStatuses(prev => prev.map(s => s.gameId === gameId ? { ...s, isSaving: false } : s));
        }
    };



    const addToBlacklist = async (id: number) => {
        if (!blacklist.includes(id)) {
            const newBlacklist = [...blacklist, id];
            const newReported = reportedIds.filter(rid => rid !== id);
            setBlacklist(newBlacklist);
            setReportedIds(newReported);
            
            try {
                await updateGeoguesserConfig({ blacklist: newBlacklist, reportedMaps: newReported });
                toast.info(`Map ${id} ajoutée à la blacklist`);
            } catch (err) {
                toast.error("Erreur lors de l'ajout");
            }
        }
    };

    const removeFromBlacklist = async (id: number) => {
        const newBlacklist = blacklist.filter(bid => bid !== id);
        setBlacklist(newBlacklist);
        try {
            await updateGeoguesserConfig({ blacklist: newBlacklist, reportedMaps: reportedIds });
            toast.success("Carte retirée de la blacklist");
        } catch (err) {
            toast.error("Erreur lors du retrait");
        }
    };

    const removeFromReported = async (id: number) => {
        const newReported = reportedIds.filter(rid => rid !== id);
        setReportedIds(newReported);
        try {
            await updateGeoguesserConfig({ blacklist: blacklist, reportedMaps: newReported });
            toast.success("Signalement supprimé");
        } catch (err) {
            toast.error("Erreur lors de la suppression");
        }
    };

    const handleManualAdd = () => {
        const id = parseInt(manualId);
        if (!isNaN(id)) {
            addToBlacklist(id);
            setManualId("");
        }
    };

    return (
        <div className="flex flex-col flex-1 h-full overflow-hidden">
            <main className="flex-1 overflow-y-auto no-scrollbar bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-zinc-900/10 via-transparent to-transparent">
                <div className="max-w-6xl mx-auto px-6 lg:px-12 py-10 space-y-8">
                    <AnimatePresence mode="wait">
                        {activeTab === "MAINTENANCE" ? (
                            <motion.div
                                key="maintenance"
                                initial={{ opacity: 0, x: -20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: 20 }}
                                className="grid grid-cols-1 gap-6"
                    >
                        {statuses.map((game) => (
                            <motion.div
                                key={game.gameId}
                                className={cn(
                                    "group relative bg-zinc-900/50 backdrop-blur-xl border rounded-[2rem] p-8 transition-all overflow-hidden",
                                    game.isEnabled ? "border-white/5" : "border-red-500/30 bg-red-500/5"
                                )}
                            >
                                <div className="relative z-10 flex flex-col md:flex-row md:items-center gap-8">
                                    <div className="flex items-center gap-6 min-w-[240px]">
                                        <div className={cn(
                                            "w-16 h-16 rounded-2xl flex items-center justify-center border transition-all shadow-lg",
                                            game.isEnabled 
                                                ? `bg-${game.color}-500/10 border-${game.color}-500/20 text-${game.color}-400`
                                                : "bg-red-500/20 border-red-500/30 text-red-500"
                                        )}>
                                            <Power size={28} />
                                        </div>
                                        <div>
                                            <h3 className="text-2xl font-black text-white uppercase italic tracking-tight">{game.name}</h3>
                                            <div className="flex items-center gap-2 mt-1">
                                                {game.isEnabled ? (
                                                    <span className="flex items-center gap-1.5 text-emerald-400 text-[10px] font-black uppercase tracking-widest">
                                                        <CheckCircle2 size={12} /> OPÉRATIONNEL
                                                    </span>
                                                ) : (
                                                    <span className="flex items-center gap-1.5 text-red-500 text-[10px] font-black uppercase tracking-widest">
                                                        <AlertTriangle size={12} /> MAINTENANCE
                                                    </span>
                                                )}
                                            </div>
                                        </div>
                                    </div>

                                    <div className="flex-1 space-y-4">
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                                                <MessageSquare size={12} /> Message de Maintenance
                                            </label>
                                            <input
                                                type="text"
                                                value={game.maintenanceMsg}
                                                onChange={(e) => handleMsgChange(game.gameId, e.target.value)}
                                                className="w-full bg-zinc-950/50 border border-white/10 rounded-xl px-4 py-3 text-sm text-white focus:outline-none focus:border-amber-500/50 transition-all font-medium"
                                                placeholder="Ex: Le jeu est en cours de mise à jour..."
                                            />
                                        </div>
                                    </div>

                                    <div className="flex items-center gap-3">
                                        <button
                                            onClick={() => handleToggle(game.gameId)}
                                            className={cn(
                                                "px-6 py-4 rounded-xl font-black uppercase text-[10px] italic transition-all flex items-center gap-2",
                                                game.isEnabled 
                                                    ? "bg-red-500/10 text-red-500 border border-red-500/20 hover:bg-red-500 hover:text-white"
                                                    : "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 hover:bg-emerald-500 hover:text-white"
                                            )}
                                        >
                                            {game.isEnabled ? "Désactiver" : "Réactiver"}
                                        </button>
                                        <button
                                            onClick={() => saveStatus(game.gameId)}
                                            disabled={game.isSaving}
                                            className="px-6 py-4 rounded-xl bg-white text-black font-black uppercase text-[10px] italic hover:bg-amber-500 hover:text-white transition-all flex items-center gap-2 disabled:opacity-50"
                                        >
                                            {game.isSaving ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />}
                                            Sauvegarder
                                        </button>
                                    </div>
                                </div>
                                <div className={cn(
                                    "absolute -right-20 -bottom-20 w-64 h-64 blur-[100px] opacity-10 transition-all duration-1000",
                                    game.isEnabled ? `bg-${game.color}-500` : "bg-red-500"
                                )} />
                            </motion.div>
                        ))}
                    </motion.div>
                ) : (
                    <motion.div
                        key="guesser"
                        initial={{ opacity: 0, x: 20 }}
                        animate={{ opacity: 1, x: 0 }}
                        exit={{ opacity: 0, x: -20 }}
                        className="space-y-8"
                    >
                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                            {/* Reported Maps */}
                            <div className="bg-zinc-900/50 backdrop-blur-xl border border-white/5 rounded-[2rem] p-8 flex flex-col gap-6">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-4">
                                        <div className="w-12 h-12 rounded-xl bg-amber-500/10 border border-amber-500/20 flex items-center justify-center text-amber-500">
                                            <Flag size={20} />
                                        </div>
                                        <div>
                                            <h2 className="text-xl font-black text-white uppercase italic">Signalements</h2>
                                            <p className="text-zinc-500 text-[10px] font-bold uppercase tracking-widest">Maps signalées par les joueurs</p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <button
                                            onClick={refreshDataFromServer}
                                            disabled={isRefreshing}
                                            className="p-2 rounded-xl bg-white/5 hover:bg-white/10 text-white/40 hover:text-white transition-all disabled:opacity-30"
                                            title="Rafraîchir les données"
                                        >
                                            <Loader2 size={14} className={isRefreshing ? "animate-spin" : ""} />
                                        </button>
                                        <span className="bg-amber-500/20 text-amber-500 px-3 py-1 rounded-full text-[10px] font-black uppercase">
                                            {reportedIds.length} Total
                                        </span>
                                    </div>
                                </div>

                                <div className="flex-1 overflow-y-auto max-h-[500px] space-y-3 pr-2 custom-scrollbar">
                                    {reportedIds.length === 0 ? (
                                        <div className="h-40 flex flex-col items-center justify-center text-zinc-600 border border-dashed border-white/5 rounded-3xl">
                                            <CheckCircle2 size={32} className="mb-2 opacity-20" />
                                            <p className="text-xs font-bold uppercase tracking-widest">Aucun signalement</p>
                                        </div>
                                    ) : (
                                        reportedIds.map(id => {
                                            const details = mapDetails[id];
                                            return (
                                                <div key={id} className="bg-zinc-950/50 border border-white/5 rounded-2xl p-3 flex items-center justify-between group hover:border-amber-500/30 transition-all">
                                                    <div className="flex items-center gap-4">
                                                        <div className="relative group/map">
                                                            <div className="w-16 h-12 rounded-xl bg-white/5 overflow-hidden border border-white/5 flex items-center justify-center text-white/20 transition-all group-hover/map:border-amber-500/50">
                                                                <img 
                                                                    src={`/game-data/hd_maps/${id}.webp`}
                                                                    alt=""
                                                                    className="w-full h-full object-cover opacity-60 group-hover/map:opacity-100 group-hover/map:scale-110 transition-all duration-500"
                                                                    onError={(e) => {
                                                                        (e.currentTarget as any).style.display = 'none';
                                                                    }}
                                                                />
                                                                <Map size={16} className="absolute inset-0 m-auto pointer-events-none opacity-20 group-hover/map:opacity-0" />
                                                            </div>
                                                            {/* HD Preview on Hover */}
                                                            <div className="fixed pointer-events-none z-[9999] opacity-0 group-hover/map:opacity-100 transition-all duration-300 scale-90 group-hover/map:scale-100 left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] aspect-video rounded-[2.5rem] overflow-hidden border-4 border-amber-500/50 shadow-[0_50px_100px_rgba(0,0,0,0.9)] bg-zinc-950">
                                                                <img 
                                                                    src={`/game-data/hd_maps/${id}.webp`}
                                                                    alt=""
                                                                    className="w-full h-full object-cover"
                                                                />
                                                                <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-transparent" />
                                                                <div className="absolute bottom-8 left-10 flex flex-col gap-1">
                                                                    <div className="flex items-center gap-3">
                                                                        <div className="w-2 h-2 rounded-full bg-amber-500 animate-pulse" />
                                                                        <span className="text-white font-black text-2xl uppercase italic tracking-tighter">Vérification HD #{id}</span>
                                                                    </div>
                                                                    <span className="text-amber-500/60 text-xs font-black uppercase tracking-[0.3em] italic">
                                                                        Signalement par un joueur • {details ? `[${details.x}, ${details.y}]` : "Coords inconnues"} 
                                                                        {details && ` • ${WORLD_NAMES[details.worldMap] || `Monde ${details.worldMap}`}`}
                                                                    </span>
                                                                </div>
                                                            </div>
                                                        </div>
                                                        <div>
                                                            <div className="text-xs font-black text-white group-hover:text-amber-500 transition-colors tracking-tight">ID: {id}</div>
                                                            <div className="text-[10px] text-zinc-500 font-mono mt-0.5">
                                                                {details ? (
                                                                    <>
                                                                        Pos: [{details.x}, {details.y}] • 
                                                                        <span className="text-amber-500/60 ml-1">
                                                                            {WORLD_NAMES[details.worldMap] || `Monde ${details.worldMap}`}
                                                                        </span>
                                                                    </>
                                                                ) : (isLoadingDetails ? "Chargement..." : "Détails inconnus")}
                                                            </div>
                                                        </div>
                                                    </div>
                                                    <div className="flex items-center gap-2">
                                                        <button 
                                                            onClick={() => addToBlacklist(id)}
                                                            className="p-2.5 rounded-lg bg-emerald-500/10 text-emerald-500 hover:bg-emerald-500 hover:text-white transition-all"
                                                            title="Blacklister"
                                                        >
                                                            <Ban size={14} />
                                                        </button>
                                                        <button 
                                                            onClick={() => removeFromReported(id)}
                                                            className="p-2.5 rounded-lg bg-red-500/10 text-red-500 hover:bg-red-500 hover:text-white transition-all"
                                                            title="Supprimer"
                                                        >
                                                            <Trash2 size={14} />
                                                        </button>
                                                    </div>
                                                </div>
                                            );
                                        })
                                    )}
                                </div>
                            </div>

                            {/* Blacklisted Maps */}
                            <div className="bg-zinc-900/50 backdrop-blur-xl border border-white/5 rounded-[2rem] p-8 flex flex-col gap-6">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-4">
                                        <div className="w-12 h-12 rounded-xl bg-red-500/10 border border-red-500/20 flex items-center justify-center text-red-500">
                                            <Ban size={20} />
                                        </div>
                                        <div>
                                            <h2 className="text-xl font-black text-white uppercase italic">Blacklist</h2>
                                            <p className="text-zinc-500 text-[10px] font-bold uppercase tracking-widest">Maps totalement exclues du pool</p>
                                        </div>
                                    </div>
                                </div>

                                {/* Manual Add & Filter */}
                                <div className="flex gap-2 flex-col sm:flex-row">
                                    <div className="flex flex-1 gap-2">
                                        <input 
                                            type="number" 
                                            value={manualId}
                                            onChange={(e) => setManualId(e.target.value)}
                                            placeholder="Ajouter un Map ID..."
                                            className="flex-1 bg-zinc-950/50 border border-white/10 rounded-xl px-4 py-3 text-xs text-white focus:outline-none focus:border-emerald-500/50 transition-all font-mono"
                                        />
                                        <button 
                                            onClick={handleManualAdd}
                                            className="px-4 py-3 rounded-xl bg-emerald-500 text-white hover:bg-emerald-400 transition-all flex items-center justify-center shrink-0"
                                        >
                                            <Plus size={18} />
                                        </button>
                                    </div>
                                    <select
                                        value={worldFilter}
                                        onChange={(e) => setWorldFilter(e.target.value)}
                                        className="sm:w-48 bg-zinc-950/50 border border-white/10 rounded-xl px-3 py-3 text-xs text-zinc-400 focus:outline-none focus:border-amber-500/50 transition-all shrink-0"
                                    >
                                        <option value="ALL">Tous les mondes</option>
                                        {Array.from(new Set(blacklist.map(id => mapDetails[id]?.worldMap).filter(Boolean))).map((worldId: any) => (
                                            <option key={worldId} value={worldId}>
                                                {WORLD_NAMES[worldId] || `Monde ${worldId}`}
                                            </option>
                                        ))}
                                    </select>
                                </div>

                                <div className="flex-1 overflow-y-auto max-h-[440px] space-y-3 pr-2 custom-scrollbar">
                                    {blacklist.length === 0 ? (
                                        <div className="h-40 flex flex-col items-center justify-center text-zinc-600 border border-dashed border-white/5 rounded-3xl">
                                            <Ban size={32} className="mb-2 opacity-20" />
                                            <p className="text-xs font-bold uppercase tracking-widest">Blacklist vide</p>
                                        </div>
                                    ) : (
                                        blacklist
                                            .filter(id => worldFilter === "ALL" || mapDetails[id]?.worldMap?.toString() === worldFilter)
                                            .map(id => {
                                                const details = mapDetails[id];
                                                return (
                                                    <div key={id} className="bg-zinc-950/50 border border-white/5 rounded-2xl p-3 flex items-center justify-between group hover:border-red-500/30 transition-all">
                                                    <div className="flex items-center gap-4">
                                                        <div className="relative group/map">
                                                            <div className="w-16 h-12 rounded-xl bg-red-500/5 overflow-hidden border border-white/5 flex items-center justify-center text-red-500/20 transition-all group-hover/map:border-red-500/50">
                                                                <img 
                                                                    src={`/game-data/hd_maps/${id}.webp`}
                                                                    alt=""
                                                                    className="w-full h-full object-cover opacity-40 group-hover/map:opacity-80 group-hover/map:scale-110 transition-all duration-500"
                                                                    onError={(e) => {
                                                                        (e.currentTarget as any).style.display = 'none';
                                                                    }}
                                                                />
                                                                <Ban size={16} className="absolute inset-0 m-auto pointer-events-none opacity-20 group-hover/map:opacity-0" />
                                                            </div>
                                                            {/* HD Preview on Hover */}
                                                            <div className="fixed pointer-events-none z-[9999] opacity-0 group-hover/map:opacity-100 transition-all duration-300 scale-90 group-hover/map:scale-100 left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] aspect-video rounded-[2.5rem] overflow-hidden border-4 border-red-500/50 shadow-[0_50px_100px_rgba(0,0,0,0.9)] bg-zinc-950">
                                                                <img 
                                                                    src={`/game-data/hd_maps/${id}.webp`}
                                                                    alt=""
                                                                    className="w-full h-full object-cover"
                                                                />
                                                                <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-transparent" />
                                                                <div className="absolute bottom-8 left-10 flex flex-col gap-1">
                                                                    <div className="flex items-center gap-3">
                                                                        <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />
                                                                        <span className="text-white font-black text-2xl uppercase italic tracking-tighter">Blacklist HD #{id}</span>
                                                                    </div>
                                                                    <span className="text-red-500/60 text-xs font-black uppercase tracking-[0.3em] italic">
                                                                        Exclusion active • {details ? `[${details.x}, ${details.y}]` : "Coords inconnues"}
                                                                        {details && ` • ${WORLD_NAMES[details.worldMap] || `Monde ${details.worldMap}`}`}
                                                                    </span>
                                                                </div>
                                                            </div>
                                                        </div>
                                                        <div>
                                                            <div className="text-xs font-black text-white group-hover:text-red-500 transition-colors tracking-tight">ID: {id}</div>
                                                            <div className="text-[10px] text-zinc-500 font-mono mt-0.5">
                                                                {details ? (
                                                                    <>
                                                                        Pos: [{details.x}, {details.y}] • 
                                                                        <span className="text-red-500/60 ml-1">
                                                                            {WORLD_NAMES[details.worldMap] || `Monde ${details.worldMap}`}
                                                                        </span>
                                                                    </>
                                                                ) : (isLoadingDetails ? "Chargement..." : "Détails inconnus")}
                                                            </div>
                                                        </div>
                                                    </div>
                                                    <button 
                                                        onClick={() => removeFromBlacklist(id)}
                                                        className="p-2.5 rounded-lg text-zinc-500 hover:bg-red-500/20 hover:text-red-500 transition-all"
                                                        title="Retirer"
                                                    >
                                                        <Trash2 size={14} />
                                                    </button>
                                                </div>
                                            );
                                        })
                                    )}
                                </div>
                            </div>
                        </div>
                    </motion.div>
                )}
                    </AnimatePresence>
                </div>
            </main>
        </div>
    );
}

import { redirect } from "next/navigation";
import Link from "next/link";
import { auth } from "@/auth";
import { db } from "@/lib/prisma";
import { cn } from "@/lib/utils";
import {
    Shield,
    Activity,
    Database,
    Sparkles,
    Layers,
    MapPin,
    Trophy,
    Gamepad2,
    Flag,
    Book
} from "lucide-react";
import {
    isSuperAdmin,
    getPlatformStats,
    getPlatformActivityStats,
    getOcrApiStats,
    getAllowedGuilds
} from "@/server/actions/super-admin-actions";
import {
    getSoftDeletedGuilds,
    getSoftDeletedProfiles,
    getArchivedProfiles,
    getPlatformBans,
    getActiveGuilds,
} from "@/server/actions/god-lifecycle-actions";
import { LiveStats } from "./components/live-stats";
import { GuildTable } from "./components/guild-table";
import { ActivityChart } from "./activity-chart";
import { JanitorButton } from "./janitor-button";
import { GodDashboardClient } from "./god-dashboard-client";
import { AnnouncementPanel } from "./components/announcement-panel";
import { GhostRadarPanel } from "./components/ghost-radar-panel";
import { StorageOverviewPanel } from "@/components/admin/storage-overview-panel";
import { TicketDashboard } from "./components/ticket-dashboard";
import GameDataInterface from "@/components/admin/GameDataInterface";
import { EventZoneManager } from "@/components/admin/EventZoneManager";

import { OverviewTabs } from "./components/overview-tabs";
import { BlacklistSection } from "./components/blacklist-section";
import { DeletionPendingPanel } from "@/components/admin/deletion-pending-panel";
import { getSystemAnnouncement } from "@/server/actions/announcement-actions";
import { Suspense } from "react";
import { WorkerTester } from "./components/worker-tester";
import { getPlatformConfig } from "@/server/actions/god-mini-games-actions";
import { getTelemetryStats } from "@/server/actions/telemetry-actions";
import { TelemetryDashboard } from "./components/telemetry-dashboard";


export default async function SuperAdminPage(props: {
    searchParams: Promise<{ tab?: string }>;
}) {
    const session = await auth();
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) {
        // Log failed GOD attempt
        if (session?.user?.id) {
            const { logAdminAccessDenied } = await import("@/server/actions/audit-actions");
            // Crée un log dans la première guilde disponible pour tracer qui tente le GOD
            const firstGuild = await db.guildConfig.findFirst({ select: { discordGuildId: true } });
            if (firstGuild) {
                await logAdminAccessDenied(firstGuild.discordGuildId, "/god");
            }
        }
        redirect("/");
    }

    const resolvedSearchParams = await props.searchParams;
    const tab = resolvedSearchParams.tab || "overview";


    // Fetch data for LifecyclePanel
    const { getGhostUsers, getUnauthorizedBotConnections } = await import("@/server/actions/super-admin-actions");
    const [softDeletedGuilds, softDeletedProfiles, archivedProfiles, platformBans, activeGuilds, ghostUsers, unauthorizedConnections] = await Promise.all([
        getSoftDeletedGuilds(),
        getSoftDeletedProfiles(),
        getArchivedProfiles(),
        getPlatformBans(),
        getActiveGuilds(),
        getGhostUsers(),
        getUnauthorizedBotConnections()
    ]);

    const resolvedData = {
        softDeletedGuilds,
        softDeletedProfiles,
        archivedProfiles,
        platformBans,
        activeGuilds,
        ghostUsers,
        unauthorizedConnections
    };

    return (
        <div className="flex-1 flex flex-col min-h-0">
            <Suspense fallback={
                <div className="flex-1 flex items-center justify-center bg-black py-20">
                    <div className="flex flex-col items-center gap-6">
                        <div className="w-16 h-16 border-4 border-amber-500/20 border-t-amber-500 rounded-full animate-spin" />
                        <span className="text-[10px] font-black text-zinc-600 uppercase tracking-[0.4em] animate-pulse">Initializing Interface...</span>
                    </div>
                </div>
            }>
                <GodDashboardClient activeTab={tab}>
                    {tab === "overview" && (
                        <div className="space-y-12">
                            {/* Header Area */}
                            <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-8 pb-12 border-b border-white/5">
                                <div className="space-y-4 min-w-0">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2 rounded-xl bg-blue-500/10 border border-blue-500/20 shrink-0">
                                            <Activity className="w-5 h-5 text-blue-400" />
                                        </div>
                                        <span className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-400">
                                            Central Operations
                                        </span>
                                    </div>

                                    <div className="space-y-2">
                                        <h1 className="text-3xl sm:text-5xl md:text-7xl font-bold text-white tracking-tight">
                                            Command Center
                                        </h1>
                                        <p className="text-zinc-500 text-base md:text-lg font-medium max-w-3xl leading-relaxed">
                                            Supervision directe des services, diffusion des annonces système et déclencheurs d'infrastructures.
                                        </p>
                                    </div>
                                </div>
                            </div>

                            <OverviewTabs
                                stats={
                                    <Suspense fallback={<div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-pulse"><div className="h-24 bg-zinc-900 rounded-2xl" /></div>}>
                                        <LiveStatsServer />
                                    </Suspense>
                                }
                                chart={
                                    <Suspense fallback={<div className="h-64 bg-zinc-900/50 rounded-3xl animate-pulse" />}>
                                        <ActivityChartServer />
                                    </Suspense>
                                }
                                communication={
                                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                                        <div className="lg:col-span-2">
