"use client";

import { useState, useEffect } from "react";
import { io, Socket } from "socket.io-client";
import { buildWsUrl } from "../../lib/socket-utils";
import { GamePhase, PublicPlayer } from "../../types/socket-events";

// Global connection state so we don't spam reconnections across unmounts 
// in development mode thanks to React Strict Mode
let socketInstance: Socket | null = null;

export interface GarticGameState {
    id: string;
    phase: GamePhase;
    players: (PublicPlayer & { hasSubmitted?: boolean })[];
    currentRound: number;
    maxRounds: number;
    timer: number;
    maxTimer: number;
    hostId?: string;
    task?: {
        type: "text" | "drawing";
        content: string;
    } | null;
    albums?: any[]; // The final results
}

export function useGarticSocket() {
    const [socket, setSocket] = useState<Socket | null>(socketInstance);
    const [isConnected, setIsConnected] = useState(false);
    const [gameState, setGameState] = useState<GarticGameState | null>(null);

    useEffect(() => {
        if (!socketInstance) {
            socketInstance = io(buildWsUrl(), {
                path: "/socket.io/",
            });
        }

        setSocket(socketInstance);

        const onConnect = () => setIsConnected(true);
        const onDisconnect = () => setIsConnected(false);
        const onStateUpdate = (state: GarticGameState) => {
             // For the sake of simplicity right now we just drop it into the global store
             setGameState(state);
        }

        socketInstance.on("connect", onConnect);
        socketInstance.on("disconnect", onDisconnect);
        socketInstance.on("gartic:state:update", onStateUpdate);
        socketInstance.on("gartic:reveal:ready", ({ albums }) => {
            setGameState(prev => prev ? { ...prev, albums } : null);
        });

        return () => {
             // Cleanup listeners when unmounting so we don't leak memory, 
             // but keep the connection open.
             if(socketInstance) {
                  socketInstance.off("connect", onConnect);
                  socketInstance.off("disconnect", onDisconnect);
                  socketInstance.off("gartic:state:update", onStateUpdate);
             }
        };
    }, []);

    // Helper functions for easy emittion
    const createRoom = (config: any) => socket?.emit("gartic:room:create", config);
    const joinRoom = (roomId: string, psuedo: string) => socket?.emit("gartic:room:join", { roomId, userName: psuedo });
    const startGame = () => socket?.emit("gartic:game:start");
    const leaveRoom = () => {
        socket?.emit("gartic:room:leave");
        setGameState(null);
    };
    const submitText = (text: string) => socket?.emit("gartic:text:submit", { text });
    const submitDraw = (dataUrl: string) => socket?.emit("gartic:draw:submit", { dataUrl });

    return {
        socket,
        isConnected,
        gameState,
        
        createRoom,
        joinRoom,
        startGame,
        leaveRoom,
        submitText,
        submitDraw
    };
}

"use client";

import { useEffect, useState, useCallback } from "react";
import { Clock, Sparkles } from "lucide-react";

interface ActiveBonusBarProps {
    guildId: string;
}

interface BonusData {
    id: string;
    bonusType: string;
    status: "PURCHASED" | "ACTIVE";
    activatesAt: string;
    expiresAt?: string | null;
    purchaserName?: string;
    config: {
        name: string;
        description: string;
    };
}

// Map bonus type to icon filename
const ICON_MAP: Record<string, string> = {
    FORTUNE: "oracle_de_fortune",
    GLADIATOR: "oracle_de_gladiateur",
    HARVESTER: "oracle_de_recolteur",
    WISDOM: "oracle_de_savoir",
    DIVINE: "oracle_divin",
};

function getCountdown(bonus: BonusData) {
    const now = new Date();

    if (bonus.status === "PURCHASED") {
        const expiresAt = new Date(bonus.activatesAt); // activatesAt in DB is actually the 24h deadline
        const totalDuration = 24 * 60 * 60 * 1000;
        const timeLeft = expiresAt.getTime() - now.getTime();

        if (timeLeft <= 0) return { text: "Expiré", progress: 100 };

        const hours = Math.floor(timeLeft / (60 * 60 * 1000));
        const minutes = Math.floor((timeLeft % (60 * 60 * 1000)) / (60 * 1000));
        return {
            text: `${hours}h ${String(minutes).padStart(2, "0")}m`,
            progress: 100 - ((timeLeft / totalDuration) * 100),
        };
    }

    if (bonus.status === "ACTIVE" && bonus.expiresAt) {
        const expiresAt = new Date(bonus.expiresAt);
        const totalDuration = 2 * 60 * 60 * 1000;
        const timeLeft = expiresAt.getTime() - now.getTime();

        if (timeLeft <= 0) return { text: "Expiré", progress: 100 };

        const hours = Math.floor(timeLeft / (60 * 60 * 1000));
        const minutes = Math.floor((timeLeft % (60 * 60 * 1000)) / (60 * 1000));
        return {
            text: `${hours}h ${String(minutes).padStart(2, "0")}m`,
            progress: ((totalDuration - timeLeft) / totalDuration) * 100,
        };
    }

    return { text: "", progress: 0 };
}

function BonusBarItem({ bonus }: { bonus: BonusData }) {
    const [countdown, setCountdown] = useState(() => getCountdown(bonus));
    const isActive = bonus.status === "ACTIVE";
    const iconFile = ICON_MAP[bonus.bonusType] || "oracle_de_fortune";

    useEffect(() => {
        const interval = setInterval(() => {
            setCountdown(getCountdown(bonus));
        }, 30000); // Refresh every 30s
        return () => clearInterval(interval);
    }, [bonus]);

    return (
        <div className="flex items-center gap-3 rounded-lg border-2 px-3 py-2 transition-all border-green-500/50 bg-green-500/5">
            {/* Icon + Info */}
            <div className="flex items-center gap-2 min-w-0">
                <img
                    src={`/bonus_guilde/${iconFile}.png`}
                    alt={bonus.config.name}
                    className="w-8 h-8 rounded-full bg-slate-900/50 p-0.5 flex-shrink-0"
                    onError={(e) => {
                        e.currentTarget.src = "/bonus_guilde/oracle_de_fortune.png";
                    }}
                />
                <div className="min-w-0">
                    <div className="flex items-center gap-1.5">
                        <h4 className="font-bold text-white text-xs truncate uppercase">{bonus.config.name}</h4>
                        <Sparkles className="w-3 h-3 text-green-400 animate-pulse flex-shrink-0" />
                    </div>
                    <p className="text-[10px] text-slate-400 truncate">
                        Acheté par {bonus.purchaserName || "un membre"}
                    </p>
                </div>
            </div>

            {/* Progress Bar + Counter */}
            <div className="flex-1 min-w-[100px]">
                <div className="relative h-1.5 bg-slate-800 rounded-full overflow-hidden mb-0.5">
                    <div
                        className="h-full transition-all duration-1000 rounded-full bg-gradient-to-r from-green-500 to-emerald-400"
                        style={{ width: `${countdown.progress}%` }}
                    />
                </div>
                <div className="flex items-center justify-between text-[10px]">
                    <span className="text-green-400">
                        Expire dans
                    </span>
                    <span className="font-mono font-bold text-white">{countdown.text}</span>
                </div>
            </div>

            {/* Status Badge */}
            <div className="px-2 py-0.5 rounded-full text-[10px] font-bold uppercase whitespace-nowrap flex-shrink-0 bg-green-500/20 text-green-400">
                ✨ DISPONIBLE
            </div>
        </div>
    );
}

export function ActiveBonusBar({ guildId }: ActiveBonusBarProps) {
    const [bonuses, setBonuses] = useState<BonusData[]>([]);

    const loadBonuses = useCallback(async () => {
        try {
            const res = await fetch(`/api/guild/${guildId}/active-bonus`);
            if (res.ok) {
                const data = await res.json();
                setBonuses(data.bonuses || []);
            }
        } catch {
            // Silently fail
        }
    }, [guildId]);

    useEffect(() => {
        loadBonuses();
        const interval = setInterval(loadBonuses, 60000);
        return () => clearInterval(interval);
    }, [loadBonuses]);

    if (bonuses.length === 0) return null;

    return (
        <div className="space-y-2">
            {bonuses.map((bonus) => (
                <BonusBarItem key={bonus.id} bonus={bonus} />
            ))}
        </div>
    );
}

'use client';

import { useState, useEffect, useTransition } from 'react';
import { getArchimonstres, syncOcreArchimonstres, deleteArchimonstre } from '@/server/actions/game-data-actions';
import { RefreshCw, Trash2, Search, Loader2, CheckCircle2, XCircle, MapPin } from 'lucide-react';

const TYPE_LABELS: Record<string, { label: string; color: string }> = {
    archimonstre: { label: 'Archi', color: 'bg-amber-500/20 text-amber-300 border-amber-500/30' },
    boss:         { label: 'Boss',  color: 'bg-red-500/20 text-red-300 border-red-500/30' },
    monstre:      { label: 'Mob',   color: 'bg-slate-500/20 text-slate-300 border-slate-500/30' },
};

const WORLD_LABELS: Record<number, string> = {
    1: '🌍 Monde XII', 2: '❄️ Frigost', 3: '🐲 Pandala', 4: '🌀 Dim.',
};

export default function ArchimonstreManager() {
    const [rows, setRows]     = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState('');
    const [typeFilter, setTypeFilter] = useState('all');
    const [syncStatus, setSyncStatus] = useState<{ synced?: number; skipped?: number; error?: string } | null>(null);
    const [isPending, startTransition] = useTransition();
    const [deletingId, setDeletingId] = useState<string | null>(null);
    const [searchTimer, setSearchTimer] = useState<ReturnType<typeof setTimeout> | null>(null);

    const loadData = async (s = search, t = typeFilter) => {
        setLoading(true);
        const res = await getArchimonstres({ search: s || undefined, type: t });
        if (res.success && res.data) setRows(res.data);
        setLoading(false);
    };

    useEffect(() => { loadData(); }, []); // eslint-disable-line

    const handleSync = () => {
        setSyncStatus(null);
        startTransition(async () => {
            const res = await syncOcreArchimonstres();
            if (res.success && res.data) {
                setSyncStatus({ synced: res.data.synced, skipped: res.data.skipped });
                await loadData();
            } else {
                setSyncStatus({ error: res.error });
            }
        });
    };

    const handleDelete = async (id: string) => {
        setDeletingId(id);
        await deleteArchimonstre(id);
        setRows(r => r.filter(x => x.id !== id));
        setDeletingId(null);
    };

    const handleSearch = (v: string) => {
        setSearch(v);
        if (searchTimer) clearTimeout(searchTimer);
        setSearchTimer(setTimeout(() => loadData(v, typeFilter), 400));
    };

    const handleType = (t: string) => { setTypeFilter(t); loadData(search, t); };

    const types = ['all', 'archimonstre', 'boss', 'monstre'];
    const withSubarea = rows.filter(r => Array.isArray(r.subareaIds) && r.subareaIds.length > 0).length;

    return (
        <div className="space-y-5">
            {/* Header + Sync */}
            <div className="flex items-start justify-between gap-4 flex-wrap">
                <div>
                    <p className="text-sm text-slate-400">
                        <span className="text-white font-bold">{rows.length}</span> archimonstres en base
                        {rows.length > 0 && (
                            <> · <span className={withSubarea === rows.length ? 'text-emerald-400' : 'text-amber-400'}>
                                {withSubarea}/{rows.length} avec zone résolue
                            </span></>
                        )}
                    </p>
                    <p className="text-xs text-slate-500 mt-0.5">
                        Synchronisé depuis Metamob (zones) + DofusDB (images/coords)
                    </p>
                </div>
                <button
                    onClick={handleSync}
                    disabled={isPending}
                    className="flex items-center gap-2 px-4 py-2 rounded-lg bg-amber-500 hover:bg-amber-400 disabled:opacity-50 text-black font-bold text-sm transition-all active:scale-95 shadow-lg shadow-amber-500/20"
                >
                    {isPending ? <Loader2 size={15} className="animate-spin" /> : <RefreshCw size={15} />}
                    {isPending ? 'Synchronisation…' : 'Sync depuis Metamob'}
                </button>
            </div>

            {/* Sync status banner */}
            {syncStatus && (
                <div className={`flex items-center gap-2 px-4 py-3 rounded-xl border text-sm ${
                    syncStatus.error
                        ? 'bg-red-500/10 border-red-500/20 text-red-300'
                        : 'bg-emerald-500/10 border-emerald-500/20 text-emerald-300'
                }`}>
                    {syncStatus.error ? <XCircle size={16} /> : <CheckCircle2 size={16} />}
                    {syncStatus.error
                        ? syncStatus.error
                        : `✅ ${syncStatus.synced} synchronisés · ${syncStatus.skipped} ignorés`}
                </div>
            )}

            {/* Filters */}
            <div className="flex items-center gap-2 flex-wrap">
                <div className="relative flex-1 min-w-[180px]">
                    <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
                    <input
                        type="text"
                        placeholder="Rechercher…"
                        value={search}
                        onChange={e => handleSearch(e.target.value)}
                        className="w-full pl-8 pr-3 py-2 rounded-lg bg-slate-800 border border-slate-700 text-white placeholder-slate-500 text-sm focus:outline-none focus:border-amber-500/50"
                    />
                </div>
                <div className="flex gap-1">
                    {types.map(t => (
                        <button key={t} onClick={() => handleType(t)}
                            className={`px-3 py-2 rounded-lg text-xs font-semibold border transition-all ${
                                typeFilter === t
                                    ? 'bg-amber-500/20 border-amber-500/40 text-amber-300'
                                    : 'bg-slate-800 border-slate-700 text-slate-400 hover:text-white'
                            }`}>
                            {t === 'all' ? 'Tous' : TYPE_LABELS[t]?.label ?? t}
                        </button>
                    ))}
                </div>
            </div>

            {/* Table */}
            {loading ? (
                <div className="flex items-center justify-center py-16 text-slate-500">
                    <Loader2 size={20} className="animate-spin mr-2" /> Chargement…
                </div>
            ) : rows.length === 0 ? (
                <div className="text-center py-16 text-slate-500 border border-dashed border-slate-700 rounded-xl">
                    <p className="font-semibold">Aucun archimonstre</p>
