                                            <>
                                                <Save className="w-4 h-4 mr-2 transition-transform group-hover:scale-110" />
                                                Confirmer l'achat
                                            </>
                                        )}
                                        <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000" />
                                    </Button>
                                    
                                    {/* Ambient background glow for purchase button */}
                                    <div className="absolute -right-4 -bottom-4 w-32 h-32 bg-purple-500/10 blur-[60px] rounded-full pointer-events-none" />
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    getChallenges,
    createChallenge,
    updateChallenge,
    deleteChallenge,
} from "@/server/actions/game-data-admin-actions";
import { Trophy, Trash2, Edit2, Plus, Search, MoreHorizontal, ImageIcon } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { ImageDownloader } from "./ImageDownloader";
import { LocalImagePicker } from "./LocalImagePicker";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { motion } from "framer-motion";

interface Challenge {
    id: string;
    name: string;
    slug: string;
    description?: string | null;
    iconUrl?: string | null;
    _count?: { dungeonAchievements: number };
}

export default function ChallengeManager() {
    const [challenges, setChallenges] = useState<Challenge[]>([]);
    const [loading, setLoading] = useState(true);
    const [editing, setEditing] = useState<string | null>(null);
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");

    const [formData, setFormData] = useState({
        name: "",
        slug: "",
        description: "",
        iconUrl: "",
    });

    useEffect(() => {
        loadChallenges();
    }, []);

    async function loadChallenges() {
        setLoading(true);
        const result = await getChallenges();
        if (result.success && result.data) {
            setChallenges(result.data);
        }
        setLoading(false);
    }

    async function handleSubmit(e: React.FormEvent) {
        e.preventDefault();
        const result = editing
            ? await updateChallenge(editing, formData)
            : await createChallenge(formData);

        if (result.success) {
            toast.success(editing ? "Challenge mis à jour" : "Challenge créé");
            resetForm();
            setIsDialogOpen(false);
            loadChallenges();
        } else {
            toast.error(result.error || "Erreur");
        }
    }

    async function handleDelete(id: string) {
        if (!confirm("Supprimer ce challenge ?")) return;
        const result = await deleteChallenge(id);
        if (result.success) {
            toast.success("Challenge supprimé");
            loadChallenges();
        }
    }

    function resetForm() {
        setFormData({ name: "", slug: "", description: "", iconUrl: "" });
        setEditing(null);
    }

    function startEdit(challenge: Challenge) {
        setEditing(challenge.id);
        setFormData({
            name: challenge.name,
            slug: challenge.slug,
            description: challenge.description || "",
            iconUrl: challenge.iconUrl || "",
        });
        setIsDialogOpen(true);
    }

    const filteredChallenges = challenges.filter(c =>
        c.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.slug.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return (
        <div className="space-y-4">
            {/* Toolbar */}
            <div className="flex flex-col md:flex-row items-center gap-4 bg-slate-900/50 p-4 rounded-lg border border-slate-700/50 backdrop-blur-sm">
                <div className="relative flex-1 w-full">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <Input
                        placeholder="Rechercher un succès..."
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        className="pl-9 bg-slate-800 border-slate-700 text-slate-200 placeholder:text-slate-500 focus:ring-indigo-500/50"
                    />
                </div>
                <Button
                    onClick={() => { resetForm(); setIsDialogOpen(true); }}
                    className="w-full md:w-auto bg-indigo-600 hover:bg-indigo-700 shadow-lg shadow-indigo-900/20 transition-all font-medium"
                >
                    <Plus className="w-4 h-4 mr-2" />
                    Nouveau Succès
                </Button>
            </div>

            {/* Grid List */}
            {loading ? (
                <div className="p-12 text-center text-slate-400 animate-pulse">Chargement des challenges...</div>
            ) : filteredChallenges.length === 0 ? (
                <div className="p-12 text-center text-slate-500 bg-slate-900/30 rounded-lg border border-dashed border-slate-700">
                    Aucun challenge trouvé
                </div>
            ) : (
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4">
                    {filteredChallenges.map((challenge) => (
                        <div
                            key={challenge.id}
                            className="group relative bg-slate-900/40 border border-slate-800 rounded-xl p-4 hover:border-indigo-500/30 hover:shadow-lg hover:shadow-indigo-900/10 transition-all duration-300"
                        >
                            <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity z-10">
                                <DropdownMenu>
                                    <DropdownMenuTrigger asChild>
                                        <Button variant="ghost" size="icon" className="h-6 w-6 bg-slate-950/80 hover:bg-slate-800 text-slate-400">
                                            <MoreHorizontal className="w-3 h-3" />
                                        </Button>
                                    </DropdownMenuTrigger>
                                    <DropdownMenuContent align="end" className="bg-slate-900 border-slate-700">
                                        <DropdownMenuItem onClick={() => startEdit(challenge)} className="text-slate-300 focus:bg-slate-800 cursor-pointer">
                                            <Edit2 className="w-3 h-3 mr-2 text-indigo-400" /> Modifier
                                        </DropdownMenuItem>
                                        <DropdownMenuItem onClick={() => handleDelete(challenge.id)} className="text-red-400 focus:bg-red-950/30 cursor-pointer">
                                            <Trash2 className="w-3 h-3 mr-2" /> Supprimer
                                        </DropdownMenuItem>
                                    </DropdownMenuContent>
                                </DropdownMenu>
                            </div>

                            <div className="flex flex-col items-center text-center gap-3">
                                <div className="w-12 h-12 rounded-lg bg-slate-800 border border-slate-700 flex items-center justify-center p-1 group-hover:border-indigo-500/50 transition-colors">
                                    {challenge.iconUrl ? (
                                        <img src={challenge.iconUrl} alt={challenge.name} className="w-full h-full object-contain" />
                                    ) : (
                                        <Trophy className="w-6 h-6 text-slate-600" />
                                    )}
                                </div>

                                <div className="space-y-1 w-full">
                                    <h4 className="font-semibold text-slate-200 text-sm truncate" title={challenge.name}>{challenge.name}</h4>
                                    <div className="text-[10px] text-slate-500 font-mono truncate bg-slate-950/50 rounded px-1.5 py-0.5 mx-auto w-max max-w-full">
                                        {challenge.slug}
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Form Dialog */}
            <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
                <DialogContent draggable className="w-[95vw] max-w-7xl max-h-[95vh] bg-slate-950 border-slate-800 p-0 overflow-hidden shadow-2xl flex flex-col h-full">
                    {/* Header Draggable */}
                    <div className="p-8 bg-slate-900/50 border-b border-slate-800 flex items-center justify-between shrink-0">
                        <DialogHeader>
                            <DialogTitle className="text-3xl font-black text-white flex items-center gap-4">
                                <Trophy className="w-8 h-8 text-indigo-500" />
                                {editing ? "Modifier le succès" : "Nouveau succès"}
                            </DialogTitle>
                            <DialogDescription className="text-slate-400 text-lg">
                                Configurez les détails du succès et son icône représentative.
                            </DialogDescription>
                        </DialogHeader>
                    </div>

                    <div className="p-10 overflow-y-auto flex-1 custom-scrollbar">
                        <form onSubmit={handleSubmit} className="space-y-10 pb-6">
                            <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
                                {/* Left Column: Info */}
                                <div className="lg:col-span-7 space-y-10">
                                    <div className="space-y-8 bg-slate-900/30 p-8 rounded-3xl border border-slate-800/50">
                                        <h3 className="text-sm font-black text-indigo-400 uppercase tracking-[0.2em] border-b border-slate-800 pb-4 mb-2">Configuration du Succès</h3>

                                        <div className="space-y-6">
                                            <div className="space-y-3">
                                                <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Nom du Succès <span className="text-rose-500 text-lg">*</span></label>
                                                <Input
                                                    value={formData.name}
                                                    onChange={(e) => {
                                                        const name = e.target.value;
                                                        if (!editing) {
                                                            const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
                                                            setFormData({ ...formData, name, slug });
                                                        } else {
                                                            setFormData({ ...formData, name });
                                                        }
                                                    }}
                                                    required
                                                    placeholder="Ex: Misanthrope"
                                                    className="h-16 bg-slate-950 border-slate-800 focus:border-indigo-500/50 focus:ring-indigo-500/20 text-xl font-bold transition-all rounded-2xl"
                                                />
                                            </div>

                                            {/* Slug and description fields are hidden from UI as they are handled automatically or unused online */}
                                            <div className="hidden space-y-3">
                                                <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Identifiant (Slug)</label>
                                                <Input
                                                    value={formData.slug}
                                                    readOnly={!!editing}
                                                    onChange={(e) => setFormData({ ...formData, slug: e.target.value })}
                                                    placeholder="identifiant-unique"
                                                    className={`h-12 bg-slate-950/50 border-slate-800 text-slate-500 font-mono text-sm rounded-xl ${editing ? 'opacity-50 cursor-not-allowed' : ''}`}
                                                />
                                            </div>

                                            <div className="hidden space-y-3">
                                                <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Description</label>
                                                <textarea
                                                    value={formData.description || ""}
                                                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                                    rows={4}
                                                    placeholder="Expliquez les conditions de réussite du challenge..."
                                                    className="w-full px-5 py-4 bg-slate-950 border border-slate-800 rounded-2xl text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500/50 resize-none text-lg transition-all"
                                                />
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                {/* Right Column: Icon */}
                                <div className="lg:col-span-5 space-y-8">
                                    <div className="bg-slate-950/50 p-8 rounded-3xl border border-slate-800 shadow-inner flex flex-col h-full">
                                        <h3 className="text-sm font-black text-indigo-400 uppercase tracking-[0.2em] border-b border-slate-800 pb-4 mb-6">Icône du Challenge</h3>

                                        <ImageDownloader
                                            type="achievement"
                                            imageUrl={formData.iconUrl}
                                            identifier={formData.name || formData.slug}
                                            onImageDownloaded={(path) => setFormData({ ...formData, iconUrl: path })}
                                            className="w-full"
                                        />
                                    </div>
                                </div>
                            </div>

                            <div className="flex gap-4 pt-6 border-t border-slate-800 sticky bottom-0 bg-slate-950 py-4 shrink-0">
                                <Button type="submit" className="flex-[3] bg-indigo-600 hover:bg-indigo-500 h-14 text-lg font-black uppercase tracking-widest shadow-xl shadow-indigo-600/20 transition-all rounded-xl active:scale-[0.98]">
                                    {editing ? "💾 Enregistrer" : "➕ Créer le Succès"}
                                </Button>
                                <Button
                                    type="button"
                                    variant="outline"
                                    onClick={() => setIsDialogOpen(false)}
                                    className="flex-1 h-14 border-white/10 hover:bg-white/5 text-slate-300 text-sm font-bold uppercase tracking-widest transition-all rounded-xl"
                                >
                                    Fermer
                                </Button>
                            </div>
                        </form>
                    </div>
                </DialogContent>
            </Dialog>

        </div>
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { exportGameData, importGameData, exportGameDataToGit } from "@/server/actions/game-data-admin-actions";

export default function DataExportImport() {
    const [exporting, setExporting] = useState(false);
    const [exportingGit, setExportingGit] = useState(false);
    const [importing, setImporting] = useState(false);

    async function handleExport() {
        setExporting(true);
        const result = await exportGameData();

        if (result.success && result.data) {
            const blob = new Blob([JSON.stringify(result.data, null, 2)], {
                type: "application/json",
            });
            const url = URL.createObjectURL(blob);
            const a = document.createElement("a");
            a.href = url;
            a.download = `game-data-backup-${new Date().toISOString().split("T")[0]}.json`;
            a.click();
            URL.revokeObjectURL(url);
            toast.success("Export réussi");
        } else {
            toast.error(result.error || "Erreur d'export");
        }

        setExporting(false);
    }

    async function handleExportToGit() {
        setExportingGit(true);
        const result = await exportGameDataToGit();

        if (result.success) {
            toast.success(result.data || "Export Git réussi", { duration: 5000 });
        } else {
            toast.error(result.error || "Erreur d'export Git");
        }

        setExportingGit(false);
    }

    async function handleImport(e: React.ChangeEvent<HTMLInputElement>) {
        const file = e.target.files?.[0];
        if (!file) return;

        setImporting(true);

        try {
            const text = await file.text();
            const result = await importGameData(text);

            if (result.success) {
                toast.success(result.data || "Import réussi");
            } else {
                toast.error(result.error || "Erreur d'import");
            }
        } catch (error) {
            toast.error("Fichier invalide");
        }

        setImporting(false);
        e.target.value = "";
    }

    return (
        <div className="space-y-6">
            <div className="bg-gradient-to-r from-indigo-600/20 to-purple-600/20 p-6 rounded-lg border border-indigo-500/30">
                <h3 className="text-lg font-semibold text-white mb-2">📦 Export / Import</h3>
                <p className="text-sm text-slate-300">
                    Utilisez ces fonctions pour synchroniser les données entre environnements (local → beta → prod)
                </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Export */}
                <div className="bg-slate-800/30 p-6 rounded-lg border border-slate-700/30 space-y-4">
                    <div>
                        <h4 className="font-semibold text-white mb-2">📤 Export</h4>
                        <p className="text-sm text-slate-400 mb-4">
                            Télécharger toutes les données (familles, challenges, donjons) en JSON
                        </p>
                    </div>

                    <Button
                        onClick={handleExport}
                        disabled={exporting}
                        className="w-full bg-indigo-600 hover:bg-indigo-700"
                    >
                        {exporting ? "⏳ Export en cours..." : "📥 Télécharger l'export JSON"}
                    </Button>

                    <div className="text-xs text-slate-500 space-y-1">
                        <p>✅ Inclut toutes les familles de monstres</p>
                        <p>✅ Inclut tous les challenges</p>
                        <p>✅ Inclut tous les donjons + succès associés</p>
                    </div>
                </div>

                {/* Export to Git (Development Only) */}
                <div className="bg-gradient-to-br from-green-900/20 to-emerald-900/20 p-6 rounded-lg border border-green-500/30 space-y-4">
                    <div>
                        <h4 className="font-semibold text-white mb-2 flex items-center gap-2">
                            🌱 Export vers Git
                            <span className="text-xs bg-green-600 px-2 py-0.5 rounded-full">DEV ONLY</span>
                        </h4>
                        <p className="text-sm text-slate-400 mb-4">
                            Sauvegarder directement dans <code className="px-1.5 py-0.5 bg-slate-900 rounded text-green-400">prisma/seed-data/game-data.json</code>
                        </p>
                    </div>

                    <Button
                        onClick={handleExportToGit}
                        disabled={exportingGit}
                        className="w-full bg-green-600 hover:bg-green-700"
                    >
                        {exportingGit ? "⏳ Export en cours..." : "📦 Sauvegarder dans Git"}
                    </Button>

                    <div className="text-xs text-green-400/80 space-y-1">
                        <p>✅ Sauvegarde dans le fichier de seed</p>
                        <p>✅ Prêt pour commit Git</p>
                        <p>✅ Auto-deployed via deploy.sh</p>
                    </div>
                </div>

                {/* Import */}
                <div className="bg-slate-800/30 p-6 rounded-lg border border-slate-700/30 space-y-4">
                    <div>
                        <h4 className="font-semibold text-white mb-2">📥 Import</h4>
                        <p className="text-sm text-slate-400 mb-4">
                            Importer des données depuis un fichier JSON (upsert)
                        </p>
                    </div>

                    <label className="block">
                        <input
                            type="file"
                            accept=".json"
                            onChange={handleImport}
                            disabled={importing}
                            className="hidden"
                            id="import-file"
                        />
                        <Button
                            onClick={() => document.getElementById("import-file")?.click()}
                            disabled={importing}
                            className="w-full bg-purple-600 hover:bg-purple-700"
                            type="button"
                        >
                            {importing ? "⏳ Import en cours..." : "📤 Choisir un fichier JSON"}
                        </Button>
                    </label>

                    <div className="text-xs text-orange-400/80 space-y-1">
                        <p>⚠️ Les données existantes seront mises à jour (upsert)</p>
                        <p>⚠️ Pas de suppression, seulement ajout/modification</p>
                    </div>
                </div>
            </div>

            {/* Instructions */}
            <div className="bg-slate-800/30 p-6 rounded-lg border border-slate-700/30">
                <h4 className="font-semibold text-white mb-3">🔄 Workflow Local → Beta → Prod</h4>
                <ol className="space-y-2 text-sm text-slate-300">
                    <li>
                        <span className="inline-block w-6 text-indigo-400">1.</span>
                        Saisir les données en local via cette interface
                    </li>
                    <li>
                        <span className="inline-block w-6 text-indigo-400">2.</span>
                        Exporter le JSON en local
                    </li>
                    <li>
                        <span className="inline-block w-6 text-indigo-400">3.</span>
                        Déployer le code sur beta (<code className="px-2 py-1 bg-slate-900 rounded">./scripts/deploy.sh beta</code>)
                    </li>
                    <li>
                        <span className="inline-block w-6 text-indigo-400">4.</span>
                        Importer le JSON sur <code className="px-2 py-1 bg-slate-900 rounded">beta.sigilos.fr/god/game-data</code>
                    </li>
                    <li>
                        <span className="inline-block w-6 text-indigo-400">5.</span>
                        Tester sur beta, puis merger vers main
                    </li>
                    <li>
                        <span className="inline-block w-6 text-indigo-400">6.</span>
                        Déployer sur prod et importer le même JSON
                    </li>
                </ol>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { useParams } from "next/navigation";
import { 
    getDofusManagementData, 
    upsertDofusItem, 
    deleteDofusItem,
    upsertQuestChain,
    deleteQuestChain,
    upsertQuestEntry,
    deleteQuestEntry
} from "@/server/actions/dofus-quest-admin-actions";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { 
    Gem, Plus, Trash2, Edit2, ChevronRight, 
    MapPin, BookOpen, Castle, Trophy, Search,
    ArrowUp, ArrowDown, Crosshair, Package, Sword,
    ExternalLink, Info
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { 
    Dialog, DialogContent, DialogHeader, DialogTitle 
} from "@/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

export default function DofusQuestGodManager() {
    const params = useParams();
    const guildId = (params?.guildId as string) || "";

    const [dofusList, setDofusList] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedDofusId, setSelectedDofusId] = useState<string | null>(null);
    const [searchQuery, setSearchQuery] = useState("");

    const [editingDofus, setEditingDofus] = useState<any | null>(null);
    const [editingChain, setEditingChain] = useState<any | null>(null);
    const [editingEntry, setEditingEntry] = useState<any | null>(null);
    const [isDofusDialogOpen, setIsDofusDialogOpen] = useState(false);
    const [isChainDialogOpen, setIsChainDialogOpen] = useState(false);
    const [isEntryDialogOpen, setIsEntryDialogOpen] = useState(false);

    const loadData = useCallback(async () => {
        setLoading(true);
        const result = await getDofusManagementData();
        if (result.success && result.data) {
            setDofusList(result.data);
            if (!selectedDofusId && result.data.length > 0) {
                setSelectedDofusId(result.data[0].id);
            }
        }
        setLoading(false);
    }, [selectedDofusId]);

    useEffect(() => { loadData(); }, [loadData]);

    const selectedDofus = dofusList.find(d => d.id === selectedDofusId);
    const filteredDofus = dofusList.filter(d => 
        d.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
        d.slug.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return (
        <div className="space-y-8">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-4xl font-black text-white italic tracking-tighter uppercase">God Mode: Quêtes Dofus</h1>
                    <p className="text-zinc-500 text-sm font-bold uppercase tracking-widest mt-1">Édition de la matrice</p>
                </div>
            </div>

            <Tabs defaultValue="editor" className="w-full">
                <TabsList className="bg-zinc-950/50 border border-white/5 p-1 rounded-2xl mb-8">
                    <TabsTrigger value="editor" className="data-[state=active]:bg-white data-[state=active]:text-black rounded-xl px-6 font-black uppercase text-[10px] tracking-widest">
                        Éditeur de Matrice
                    </TabsTrigger>
                </TabsList>

                <TabsContent value="editor">
                    <div className="flex flex-col lg:flex-row gap-6 items-start">
            <div className="w-full lg:w-80 shrink-0 bg-zinc-950/40 backdrop-blur-xl border border-white/5 rounded-3xl flex flex-col group/sidebar shadow-2xl overflow-hidden">
                <div className="p-5 border-b border-white/5 space-y-4 bg-zinc-900/20">
                    <div className="flex items-center justify-between">
                        <h3 className="text-sm font-black text-white uppercase tracking-widest italic flex items-center gap-2">
                            <BookOpen className="w-4 h-4 text-indigo-400" />
                            Catalogue
                        </h3>
                    </div>
                    <div className="relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500" />
                        <Input value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Rechercher un Dofus..." className="pl-9 bg-black/40 border-white/10 text-white placeholder:text-zinc-600 rounded-xl focus-visible:ring-indigo-500/50" />
                    </div>
                </div>
                <div className="flex-1 overflow-y-auto custom-scrollbar max-h-[500px] p-3 space-y-1 relative">
                    {loading ? (
                        <div className="p-8 text-center text-zinc-500 animate-pulse text-xs uppercase font-black tracking-widest">Chargement...</div>
                    ) : filteredDofus.length === 0 ? (
                        <div className="p-8 text-center text-zinc-600 text-xs uppercase font-black">Aucun résultat</div>
                    ) : (
                        filteredDofus.map(dofus => (
                            <button key={dofus.id} onClick={() => setSelectedDofusId(dofus.id)} className={`w-full flex items-center gap-4 p-3 rounded-2xl transition-all duration-300 ${selectedDofusId === dofus.id ? "bg-indigo-500/10 border border-indigo-500/20" : "hover:bg-white/5 border border-transparent"}`}>
                                <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 border ${selectedDofusId === dofus.id ? "bg-indigo-500/20 border-indigo-500/30" : "bg-black/50 border-white/5"}`}>
                                    {dofus.imageUrl ? <img src={dofus.imageUrl} alt={dofus.name} className="w-6 h-6 object-contain drop-shadow-lg" /> : <Gem className={`w-5 h-5 ${selectedDofusId === dofus.id ? "text-indigo-400" : "text-zinc-600"}`} />}
                                </div>
                                <div className="flex-1 text-left min-w-0">
