                            </div>
                        </div>

                        {/* Lien DPLN + Notes */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="space-y-1">
                                <label className="text-[10px] font-black uppercase tracking-widest text-indigo-400 flex items-center gap-2"><BookOpen className="w-3 h-3" /> Lien DofusNoobs</label>
                                <Input value={formData.externalRef || ""} onChange={e => setFormData({...formData, externalRef: e.target.value})} className="bg-indigo-500/10 border-indigo-500/20 h-11 rounded-xl text-xs" placeholder="https://www.dofuspourlesnoobs.com/..." />
                            </div>
                            <div className="space-y-1">
                                <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500 flex items-center gap-2"><Info className="w-3 h-3" /> Notes</label>
                                <textarea value={formData.notes || ""} onChange={e => setFormData({...formData, notes: e.target.value})} className="w-full h-20 bg-black/40 border border-white/5 rounded-xl text-xs p-3 text-white placeholder:text-zinc-600 focus:outline-none focus:border-indigo-500/50 resize-none" placeholder="Infos complémentaires..." />
                            </div>
                        </div>

                        {/* Prérequis section (already done) */}
                        {entry?.id && (
                            <div className="border-t border-white/5 pt-4">
                                <div className="flex items-center justify-between mb-3">
                                    <h4 className="text-[10px] font-black uppercase tracking-widest text-zinc-500 flex items-center gap-2"><span>🔗</span> PRÉREQUIS</h4>
                                    <span className="text-[10px] text-zinc-600 font-bold">{prerequisites.length} lié{prerequisites.length > 1 ? "s" : ""}</span>
                                </div>
                                {loadingPrereqs ? <div className="text-[10px] text-zinc-500 italic py-2">Chargement...</div> : prerequisites.length > 0 ? (
                                    <div className="flex flex-wrap gap-1.5 mb-3">
                                        {prerequisites.map((p: any) => (
                                            <div key={p.id} className="inline-flex items-center gap-1 px-2 py-1 rounded-lg bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 text-[10px] font-bold">
                                                <span className="truncate max-w-[120px]">{p.name}</span>
                                                <button onClick={async () => {
                                                    const { getQuestPrerequisites, removeQuestPrerequisite } = await import("@/server/actions/dofus-quest-admin-actions");
                                                    const res = await getQuestPrerequisites(entry.id);
                                                    if (res.success && res.data) {
                                                        const link = res.data.from.find((f: any) => f.fromQuest?.id === p.id);
                                                        if (link) {
                                                            const delRes = await removeQuestPrerequisite(link.id);
                                                            if (delRes.success) { toast.success(`Prérequis "${p.name}" retiré`); setPrerequisites(prev => prev.filter((x: any) => x.id !== p.id)); }
                                                            else toast.error(delRes.error || "Erreur");
                                                        }
                                                    }
                                                }} className="text-rose-400/50 hover:text-rose-400"><Trash2 className="w-2.5 h-2.5" /></button>
                                            </div>
                                        ))}
                                    </div>
                                ) : <p className="text-[10px] text-zinc-600 italic mb-3">Aucun prérequis défini</p>}
                                {siblingEntries.length > 0 && (
                                    <div className="space-y-2">
                                        <input value={prereqSearch} onChange={e => setPrereqSearch(e.target.value)} placeholder="Rechercher une quête comme prérequis..." className="w-full h-9 bg-black/40 border border-white/5 rounded-xl text-xs px-3 text-white placeholder:text-zinc-600 focus:outline-none focus:border-indigo-500/50" />
                                        <div className="max-h-[120px] overflow-y-auto custom-scrollbar space-y-0.5">
                                            {siblingEntries.filter((s: any) => !prerequisites.some((p: any) => p.id === s.id) && s.name.toLowerCase().includes(prereqSearch.toLowerCase())).slice(0, 8).map((s: any) => (
                                                <button key={s.id} onClick={async () => {
                                                    const { addQuestPrerequisite } = await import("@/server/actions/dofus-quest-admin-actions");
                                                    const res = await addQuestPrerequisite(s.id, entry.id);
                                                    if (res.success) { toast.success(`Prérequis "${s.name}" ajouté`); setPrerequisites(prev => [...prev, s]); }
                                                    else toast.error(res.error || "Erreur");
                                                }} className="w-full flex items-center gap-2 px-2.5 py-1.5 rounded-lg hover:bg-indigo-500/10 text-left transition-all text-[10px] text-zinc-400 hover:text-indigo-300 font-medium">
                                                    <Plus className="w-2.5 h-2.5 shrink-0" />
                                                    <span className="truncate">{s.name}</span>
                                                    <span className="text-zinc-600 shrink-0 ml-auto">{s.chain?.sectionName}</span>
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </div>
                <div className="flex justify-between items-center p-6 border-t border-white/5 bg-zinc-900/30">
                    {entry?.id ? <Button type="button" variant="ghost" onClick={handleDelete} className="text-rose-500 hover:text-rose-400 hover:bg-rose-500/10 rounded-xl"><Trash2 className="w-4 h-4 mr-2" /> Expulser</Button> : <div/>}
                    <div className="flex gap-3 ml-auto">
                        <Button type="button" variant="ghost" onClick={() => onOpenChange(false)} className="rounded-xl text-zinc-400 hover:text-white">Fermer</Button>
                        <Button type="button" onClick={handleSubmit} disabled={loading} className="bg-indigo-600 hover:bg-indigo-500 text-white font-black italic text-[10px] uppercase tracking-widest rounded-xl px-8 shadow-xl">Sauvegarder</Button>
                    </div>
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState, useTransition, useEffect, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { getDofusItemsForTagging, updateDofusTags, upsertDofusItem, deleteDofusItem } from "@/server/actions/dofus-quest-admin-actions";
import { toast } from "sonner";
import { 
    Crown, 
    Star, 
    Sparkles, 
    GripVertical, 
    ArrowUp, 
    ArrowDown, 
    Loader2, 
    CheckCircle, 
    Check, 
    X, 
    Plus, 
    Tag, 
    Trash2 
} from "lucide-react";

type DofusTag = {
    id: string;
    name: string;
    nameShort: string;
    slug: string;
    imageUrl: string | null;
    localImageUrl: string | null;
    color: string | null;
    isPrimordial: boolean;
    isMeta: boolean;
    isSylvestreReq: boolean;
    displayOrder: number;
    rarity: string;
    filterCategory: string;
};

const TAG_CONFIG = [
    {
        key: "isPrimordial",
        label: "Primordial",
        icon: Crown,
        color: "#fbbf24",
        bg: "bg-amber-500/10",
        border: "border-amber-500/30",
        activeBg: "bg-amber-500/20",
        activeBorder: "border-amber-500",
        textColor: "text-amber-400",
        desc: "Dofus de niveau haut, difficile à obtenir",
    },
    {
        key: "isSylvestreReq",
        label: "Prérequis Sylvestre",
        icon: Star,
        color: "#34d399",
        bg: "bg-emerald-500/10",
        border: "border-emerald-500/30",
        activeBg: "bg-emerald-500/20",
        activeBorder: "border-emerald-500",
        textColor: "text-emerald-400",
        desc: "Requis pour obtenir le Dofus Sylvestre",
    },
    {
        key: "isMeta",
        label: "Méta / Objectif final",
        icon: Sparkles,
        color: "#818cf8",
        bg: "bg-indigo-500/10",
        border: "border-indigo-500/30",
        activeBg: "bg-indigo-500/20",
        activeBorder: "border-indigo-500",
        textColor: "text-indigo-400",
        desc: "Dofus final comme le Sylvestre (1 max)",
    },
] as const;

export function DofusTagManager() {
    const [items, setItems] = useState<DofusTag[]>([]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState<string | null>(null);
    const [isPending, startTransition] = useTransition();

    const loadData = () => {
        setLoading(true);
        getDofusItemsForTagging().then((res) => {
            if (res.success && res.data) setItems(res.data);
            setLoading(false);
        });
    };

    useEffect(() => {
        loadData();
    }, []);

    const updateItemLocally = (id: string, updates: Partial<DofusTag>) => {
        setItems((prev) => prev.map((i) => i.id === id ? { ...i, ...updates } : i));
    };

    const handleTagToggle = async (item: DofusTag, tagKey: keyof Pick<DofusTag, "isPrimordial" | "isMeta" | "isSylvestreReq">) => {
        const newVal = !item[tagKey];

        // isMeta only 1 at a time
        if (tagKey === "isMeta" && newVal) {
            const existing = items.find((i) => i.isMeta && i.id !== item.id);
            if (existing) {
                toast.warning(`Le tag "Méta" est déjà attribué à : ${existing.name}. Retirez-le d'abord.`);
                return;
            }
        }

        // Optimistic update
        updateItemLocally(item.id, { [tagKey]: newVal });
        setSaving(item.id);

        startTransition(async () => {
            const res = await updateDofusTags(item.id, { [tagKey]: newVal });
            setSaving(null);
            if (!res.success) {
                toast.error(res.error || "Erreur");
                // Rollback
                updateItemLocally(item.id, { [tagKey]: !newVal });
            } else {
                toast.success(`Tag mis à jour pour "${item.nameShort}"`);
            }
        });
    };

    const handleFieldUpdate = async (item: DofusTag, field: "rarity" | "filterCategory", value: string) => {
        if (item[field] === value) return;

        updateItemLocally(item.id, { [field]: value });
        setSaving(item.id);

        startTransition(async () => {
            const res = await updateDofusTags(item.id, { [field]: value });
            setSaving(null);
            if (!res.success) {
                toast.error(res.error || "Erreur");
                // Rollback
                updateItemLocally(item.id, { [field]: item[field] });
            }
        });
    };

    const handleOrderChange = async (item: DofusTag, direction: "up" | "down") => {
        const idx = items.findIndex((i) => i.id === item.id);
        const swapIdx = direction === "up" ? idx - 1 : idx + 1;
        if (swapIdx < 0 || swapIdx >= items.length) return;

        const swapItem = items[swapIdx];
        const newItems = [...items];
        [newItems[idx], newItems[swapIdx]] = [newItems[swapIdx], newItems[idx]];
        
        const newOrder1 = swapItem.displayOrder;
        const newOrder2 = item.displayOrder;
        newItems[idx] = { ...newItems[idx], displayOrder: newOrder2 };
        newItems[swapIdx] = { ...newItems[swapIdx], displayOrder: newOrder1 };
        setItems(newItems);

        setSaving(item.id);
        await Promise.all([
            updateDofusTags(item.id, { displayOrder: newOrder1 }),
            updateDofusTags(swapItem.id, { displayOrder: newOrder2 }),
        ]);
        setSaving(null);
        toast.success("Ordre mis à jour");
    };

    const [showCreate, setShowCreate] = useState(false);
    const [newItem, setNewItem] = useState({ name: "", slug: "", rarity: "Nouveau", filterCategory: "Autres" });

    // Derive unique tags for suggestions
    const uniqueRarities = useMemo(() => Array.from(new Set(items.map(i => i.rarity).filter(Boolean))), [items]);
    const uniqueCategories = useMemo(() => Array.from(new Set(items.map(i => i.filterCategory).filter(Boolean))), [items]);

    const handleCreate = async () => {
        setLoading(true);
        const res = await upsertDofusItem(null, {
            name: newItem.name,
            nameShort: newItem.name,
            slug: newItem.slug.toLowerCase().replace(/\s+/g, "-"),
            rarity: newItem.rarity,
            filterCategory: newItem.filterCategory,
            isPrimordial: false,
            levelRecommended: 200,
            displayOrder: items.length + 1
        } as any);

        if (res.success) {
            toast.success("Dofus créé !");
            setShowCreate(false);
            setNewItem({ name: "", slug: "", rarity: "Nouveau", filterCategory: "Autres" });
            loadData();
        } else {
            toast.error(res.error || "Erreur lors de la création");
            setLoading(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm("Supprimer ce Dofus ?")) return;
        setLoading(true);
        const res = await deleteDofusItem(id);
        if (res.success) {
            toast.success("Supprimé");
            loadData();
        } else {
            toast.error(res.error || "Erreur");
            setLoading(false);
        }
    };

    if (loading && items.length === 0) {
        return (
            <div className="flex items-center justify-center py-20 gap-3 text-zinc-500">
                <Loader2 className="w-5 h-5 animate-spin" />
                <span className="text-sm font-bold uppercase tracking-widest">Chargement…</span>
            </div>
        );
    }

    return (
        <div className="space-y-4">
            {/* Header & Tag Library */}
            <div className="flex flex-col gap-6 bg-zinc-950/40 p-6 rounded-3xl border border-white/5 backdrop-blur-md">
                <div className="flex items-center justify-between">
                   <div>
                        <h3 className="text-lg font-black text-white italic uppercase tracking-tighter flex items-center gap-2">
                            <Tag className="w-5 h-5 text-indigo-400" />
                            Bibliothèque & Création
                        </h3>
                        <p className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest mt-1">Gérez vos tags et créez des coquilles vides</p>
                   </div>
                   <button 
                        onClick={() => setShowCreate(!showCreate)}
                        className={`flex items-center gap-2 px-5 py-2.5 rounded-2xl font-black uppercase text-[10px] tracking-widest transition-all ${showCreate ? 'bg-rose-500/10 text-rose-500 border border-rose-500/20' : 'bg-indigo-600 text-white hover:bg-indigo-500 shadow-lg shadow-indigo-600/20'}`}
                   >
                        {showCreate ? <X className="w-4 h-4" /> : <Plus className="w-4 h-4" />}
                        {showCreate ? "Annuler" : "Ajouter une Coquille Vide"}
                   </button>
                </div>

                <AnimatePresence>
                    {showCreate && (
                        <motion.div 
                            initial={{ height: 0, opacity: 0 }}
                            animate={{ height: "auto", opacity: 1 }}
                            exit={{ height: 0, opacity: 0 }}
                            className="overflow-hidden border-t border-white/5 pt-6"
                        >
                            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 bg-white/[0.02] p-4 rounded-2xl border border-white/5">
                                <div className="space-y-1">
                                    <label className="text-[9px] font-black uppercase text-zinc-500 tracking-widest ml-2">Nom du Dofus</label>
                                    <input 
                                        type="text" 
                                        placeholder="Ex: Forgelave"
                                        value={newItem.name}
                                        onChange={e => setNewItem({...newItem, name: e.target.value})}
                                        className="w-full bg-black/40 border border-white/10 rounded-xl px-4 py-2 text-sm text-white focus:outline-none focus:border-indigo-500/50"
                                    />
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[9px] font-black uppercase text-zinc-500 tracking-widest ml-2">Slug (URL)</label>
                                    <input 
                                        type="text" 
                                        placeholder="ex: forgelave"
                                        value={newItem.slug}
                                        onChange={e => setNewItem({...newItem, slug: e.target.value})}
                                        className="w-full bg-black/40 border border-white/10 rounded-xl px-4 py-2 text-sm text-white focus:outline-none focus:border-indigo-500/50"
                                    />
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[9px] font-black uppercase text-zinc-500 tracking-widest ml-2">Rareté</label>
                                    <input 
                                        type="text" 
                                        list="rarities"
                                        placeholder="Primordial, Rare..."
                                        value={newItem.rarity}
                                        onChange={e => setNewItem({...newItem, rarity: e.target.value})}
                                        className="w-full bg-black/40 border border-white/10 rounded-xl px-4 py-2 text-sm text-white focus:outline-none focus:border-indigo-500/50"
                                    />
                                </div>
                                <div className="flex items-end pb-0.5">
                                    <button 
                                        onClick={handleCreate}
                                        disabled={!newItem.name || !newItem.slug}
                                        className="w-full h-10 bg-emerald-600 hover:bg-emerald-500 disabled:opacity-30 disabled:hover:bg-emerald-600 text-white font-black uppercase text-[10px] tracking-widest rounded-xl transition-all shadow-lg shadow-emerald-950"
                                    >
                                        Confirmer la Création
                                    </button>
                                </div>
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>

                <div className="flex flex-wrap gap-4 items-center">
                    <div className="flex items-center gap-3">
                        <span className="text-[9px] font-black uppercase text-zinc-600 tracking-widest">Vos Raretés :</span>
                        <div className="flex flex-wrap gap-2">
                            {uniqueRarities.map(r => (
                                <span key={r} className="px-2 py-0.5 bg-zinc-800 border border-white/5 rounded text-[9px] font-bold text-zinc-400 uppercase">{r}</span>
                            ))}
                        </div>
                    </div>
                    <div className="w-px h-4 bg-white/10" />
                    <div className="flex items-center gap-3">
                        <span className="text-[9px] font-black uppercase text-zinc-600 tracking-widest">Vos Catégories :</span>
                        <div className="flex flex-wrap gap-2">
                            {uniqueCategories.map(c => (
                                <span key={c} className="px-2 py-0.5 bg-indigo-500/10 border border-indigo-500/20 rounded text-[9px] font-bold text-indigo-400 uppercase">{c}</span>
                            ))}
                        </div>
                    </div>
                </div>

                <datalist id="rarities">
                    {uniqueRarities.map(r => <option key={r} value={r} />)}
                </datalist>
                <datalist id="categories">
                    {uniqueCategories.map(c => <option key={c} value={c} />)}
                </datalist>
            </div>

            {/* Legend */}
            <div className="flex flex-wrap gap-3 pb-4 border-b border-white/5">
                {TAG_CONFIG.map((tag) => {
                    const Icon = tag.icon;
                    return (
                        <div
                            key={tag.key}
                            className={`flex items-center gap-2 px-3 py-1.5 rounded-full border ${tag.bg} ${tag.border}`}
                        >
                            <Icon className={`w-3.5 h-3.5 ${tag.textColor}`} />
                            <span className={`text-xs font-black uppercase tracking-widest ${tag.textColor}`}>{tag.label}</span>
                        </div>
                    );
                })}
                <div className="flex items-center gap-2 px-3 py-1.5 rounded-full border bg-white/5 border-white/10">
                    <GripVertical className="w-3.5 h-3.5 text-zinc-500" />
                    <span className="text-xs font-black uppercase tracking-widest text-zinc-500">Ordre d'affichage</span>
                </div>
            </div>

            {/* Table */}
            <div className="overflow-hidden rounded-2xl border border-white/5">
                <div className="overflow-x-auto">
                    <table className="w-full">
                        <thead>
                            <tr className="border-b border-white/5 bg-white/[0.02]">
                                <th className="text-left px-5 py-3 text-[10px] font-black uppercase tracking-widest text-zinc-500">Dofus</th>
                                <th className="text-center px-4 py-3 text-[10px] font-black uppercase tracking-widest text-zinc-500">Rareté / Tag Principal</th>
                                {TAG_CONFIG.map((tag) => (
                                    <th key={tag.key} className="text-center px-4 py-3 text-[10px] font-black uppercase tracking-widest text-zinc-500 whitespace-nowrap">
                                        {tag.label}
                                    </th>
                                ))}
                                <th className="text-center px-4 py-3 text-[10px] font-black uppercase tracking-widest text-zinc-500 whitespace-nowrap">Catégorie Filtre</th>
                                <th className="text-center px-4 py-3 text-[10px] font-black uppercase tracking-widest text-zinc-500">Ordre</th>
                                <th className="text-center px-4 py-3 text-[10px] font-black uppercase tracking-widest text-zinc-500">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/[0.03]">
                            {items.map((item, idx) => {
                                const isSaving = saving === item.id;
                                const img = item.localImageUrl || item.imageUrl;

                                return (
                                    <tr
                                        key={item.id}
                                        className="group hover:bg-white/[0.02] transition-colors"
                                    >
                                        {/* Name */}
                                        <td className="px-5 py-3">
                                            <div className="flex items-center gap-3">
                                                <div className="w-9 h-9 rounded-xl flex-shrink-0 flex items-center justify-center border border-white/10 bg-black/40">
                                                    {img ? (
                                                        <img src={img} alt={item.nameShort} className="w-7 h-7 object-contain" />
                                                    ) : (
                                                        <div className="w-5 h-5 rounded-full" style={{ background: item.color || "#6366f1" }} />
                                                    )}
                                                </div>
                                                <div>
                                                    <p className="text-sm font-black text-white italic uppercase tracking-tight">{item.nameShort}</p>
                                                    <p className="text-[10px] text-zinc-600 font-medium">{item.slug}</p>
                                                </div>
                                                {isSaving && <Loader2 className="w-3.5 h-3.5 text-zinc-500 animate-spin ml-1" />}
                                            </div>
                                        </td>

                                        {/* Rarity Input */}
                                        <td className="px-4 py-3">
                                            <input
                                                type="text"
                                                defaultValue={item.rarity}
                                                onBlur={(e) => handleFieldUpdate(item, "rarity", e.target.value)}
                                                className="w-full max-w-[120px] mx-auto block bg-black/40 border border-white/10 rounded-lg px-2 py-1 text-[10px] font-black uppercase tracking-widest text-white text-center focus:outline-none focus:border-white/30"
                                            />
                                        </td>

                                        {/* Tag toggles */}
                                        {TAG_CONFIG.map((tag) => {
                                            const Icon = tag.icon;
                                            const isActive = !!item[tag.key as keyof DofusTag];
                                            return (
                                                <td key={tag.key} className="text-center px-4 py-3">
                                                    <button
                                                        onClick={() => handleTagToggle(item, tag.key as any)}
                                                        disabled={isSaving}
                                                        title={tag.desc}
                                                        className={`
                                                            w-9 h-9 rounded-xl mx-auto flex items-center justify-center border transition-all duration-200
                                                            ${isActive
                                                                ? `${tag.activeBg} ${tag.activeBorder} ${tag.textColor} shadow-[0_0_12px_rgba(0,0,0,0.3)]`
                                                                : "bg-white/[0.03] border-white/10 text-zinc-700 hover:text-zinc-400 hover:border-white/20"
                                                            }
                                                            disabled:opacity-40 cursor-pointer
                                                        `}
                                                    >
                                                        <Icon className="w-4 h-4" />
                                                    </button>
                                                </td>
                                            );
                                        })}

                                        {/* Filter Category Input */}
                                        <td className="px-4 py-3">
                                            <input
                                                type="text"
                                                defaultValue={item.filterCategory}
                                                onBlur={(e) => handleFieldUpdate(item, "filterCategory", e.target.value)}
                                                className="w-full max-w-[100px] mx-auto block bg-black/40 border border-white/10 rounded-lg px-2 py-1 text-[10px] font-black uppercase tracking-widest text-zinc-500 text-center focus:outline-none focus:border-white/30"
                                            />
                                        </td>

                                        {/* Order */}
                                        <td className="text-center px-4 py-3">
                                            <div className="flex items-center justify-center gap-1">
                                                <button
                                                    onClick={() => handleOrderChange(item, "up")}
                                                    disabled={idx === 0 || isSaving}
                                                    className="w-7 h-7 rounded-lg flex items-center justify-center bg-white/[0.03] border border-white/10 text-zinc-600 hover:text-white hover:border-white/30 transition-all disabled:opacity-20 cursor-pointer"
                                                >
                                                    <ArrowUp className="w-3.5 h-3.5" />
                                                </button>
                                                <span className="text-xs font-black text-zinc-600 w-6 text-center tabular-nums">{item.displayOrder}</span>
                                                <button
                                                    onClick={() => handleOrderChange(item, "down")}
                                                    disabled={idx === items.length - 1 || isSaving}
                                                    className="w-7 h-7 rounded-lg flex items-center justify-center bg-white/[0.03] border border-white/10 text-zinc-600 hover:text-white hover:border-white/30 transition-all disabled:opacity-20 cursor-pointer"
                                                >
                                                    <ArrowDown className="w-3.5 h-3.5" />
                                                </button>
                                            </div>
                                        </td>

                                        {/* Actions */}
                                        <td className="px-4 py-3 text-center">
                                            <button 
                                                onClick={() => handleDelete(item.id)}
                                                className="p-2 text-zinc-700 hover:text-rose-500 hover:bg-rose-500/10 rounded-lg transition-all"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    getDreamBonuses,
    createDreamBonus,
    updateDreamBonus,
    deleteDreamBonus,
} from "@/server/actions/game-data-admin-actions";
import { Moon, Trash2, Edit2, Plus, Search, MoreHorizontal } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { ImageDownloader } from "./ImageDownloader";

interface DreamBonus {
    id: string;
    name: string;
    type: "ACTIF" | "PASSIF" | "CONSOMMABLE";
    description?: string | null;
    imageUrl?: string | null;
    costMin?: number | null;
    costMax?: number | null;
}

const TYPE_COLORS: Record<string, string> = {
    ACTIF: "bg-cyan-500/10 text-cyan-400 border-cyan-500/20",
    PASSIF: "bg-purple-500/10 text-purple-400 border-purple-500/20",
    CONSOMMABLE: "bg-amber-500/10 text-amber-400 border-amber-500/20",
};

const TYPE_EMOJI: Record<string, string> = {
    ACTIF: "⚡",
    PASSIF: "🌙",
    CONSOMMABLE: "🧪",
};

export default function DreamBonusManager() {
    const [bonuses, setBonuses] = useState<DreamBonus[]>([]);
    const [loading, setLoading] = useState(true);
    const [editing, setEditing] = useState<string | null>(null);
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");

    const [formData, setFormData] = useState({
        name: "",
        type: "ACTIF" as "ACTIF" | "PASSIF" | "CONSOMMABLE",
        description: "",
        imageUrl: "",
        costMin: "" as string | number,
        costMax: "" as string | number,
    });

    useEffect(() => { loadBonuses(); }, []);

    async function loadBonuses() {
        setLoading(true);
        const result = await getDreamBonuses();
        if (result.success && result.data) setBonuses(result.data);
        setLoading(false);
    }

    async function handleSubmit(e: React.FormEvent) {
        e.preventDefault();
        const payload = {
            name: formData.name,
            type: formData.type,
            description: formData.description || undefined,
            imageUrl: formData.imageUrl || undefined,
            costMin: formData.costMin !== "" ? Number(formData.costMin) : null,
            costMax: formData.costMax !== "" ? Number(formData.costMax) : null,
        };
        const result = editing
            ? await updateDreamBonus(editing, payload)
            : await createDreamBonus(payload);

        if (result.success) {
            toast.success(editing ? "Bonus mis à jour" : "Bonus créé");
            resetForm();
            setIsDialogOpen(false);
            loadBonuses();
        } else {
            toast.error(result.error || "Erreur");
        }
    }

    async function handleDelete(id: string) {
        if (!confirm("Supprimer ce bonus de rêve ?")) return;
        const result = await deleteDreamBonus(id);
        if (result.success) { toast.success("Bonus supprimé"); loadBonuses(); }
        else toast.error(result.error);
    }

    function resetForm() {
        setFormData({ name: "", type: "ACTIF", description: "", imageUrl: "", costMin: "", costMax: "" });
        setEditing(null);
    }

    function startEdit(bonus: DreamBonus) {
        setEditing(bonus.id);
        setFormData({
            name: bonus.name,
            type: bonus.type,
            description: bonus.description || "",
            imageUrl: bonus.imageUrl || "",
            costMin: bonus.costMin ?? "",
            costMax: bonus.costMax ?? "",
        });
        setIsDialogOpen(true);
    }

    const filtered = bonuses.filter(b =>
        b.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        b.type.toLowerCase().includes(searchQuery.toLowerCase())
    );

    // Group by type
    const byType = {
        ACTIF: filtered.filter(b => b.type === "ACTIF"),
        PASSIF: filtered.filter(b => b.type === "PASSIF"),
        CONSOMMABLE: filtered.filter(b => b.type === "CONSOMMABLE"),
    };

    return (
        <div className="space-y-4">
            {/* Toolbar */}
            <div className="flex flex-col md:flex-row items-center gap-4 bg-slate-900/50 p-4 rounded-lg border border-slate-700/50">
                <div className="relative flex-1 w-full">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <Input
                        placeholder="Rechercher un bonus..."
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        className="pl-9 bg-slate-800 border-slate-700 text-slate-200 placeholder:text-slate-500"
                    />
                </div>
                <Button
                    onClick={() => { resetForm(); setIsDialogOpen(true); }}
                    className="w-full md:w-auto bg-indigo-600 hover:bg-indigo-700 font-medium"
                >
                    <Plus className="w-4 h-4 mr-2" /> Nouveau Bonus
                </Button>
            </div>

            {loading ? (
                <div className="p-12 text-center text-slate-400 animate-pulse">Chargement...</div>
            ) : filtered.length === 0 ? (
                <div className="p-12 text-center text-slate-500 border border-dashed border-slate-700 rounded-lg">
                    Aucun bonus de rêve trouvé
                </div>
            ) : (
                <div className="space-y-6">
                    {(["ACTIF", "PASSIF", "CONSOMMABLE"] as const).map(type => {
                        const items = byType[type];
                        if (items.length === 0) return null;
                        return (
                            <div key={type}>
                                <h3 className={`text-xs font-black uppercase tracking-widest mb-3 flex items-center gap-2 border-b border-slate-800 pb-2 ${TYPE_COLORS[type].split(" ")[1]}`}>
                                    <span>{TYPE_EMOJI[type]}</span> {type} ({items.length})
                                </h3>
                                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3">
                                    {items.map(bonus => (
                                        <div
                                            key={bonus.id}
                                            className="group relative bg-slate-900/40 border border-slate-800 rounded-xl p-4 hover:border-indigo-500/30 transition-all"
                                        >
                                            <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity z-10">
                                                <DropdownMenu>
                                                    <DropdownMenuTrigger asChild>
                                                        <Button variant="ghost" size="icon" className="h-6 w-6 bg-slate-950/80 hover:bg-slate-800 text-slate-400">
                                                            <MoreHorizontal className="w-3 h-3" />
                                                        </Button>
                                                    </DropdownMenuTrigger>
                                                    <DropdownMenuContent align="end" className="bg-slate-900 border-slate-700">
                                                        <DropdownMenuItem onClick={() => startEdit(bonus)} className="text-slate-300 focus:bg-slate-800 cursor-pointer">
                                                            <Edit2 className="w-3 h-3 mr-2 text-indigo-400" /> Modifier
                                                        </DropdownMenuItem>
                                                        <DropdownMenuItem onClick={() => handleDelete(bonus.id)} className="text-red-400 focus:bg-red-950/30 cursor-pointer">
                                                            <Trash2 className="w-3 h-3 mr-2" /> Supprimer
                                                        </DropdownMenuItem>
                                                    </DropdownMenuContent>
                                                </DropdownMenu>
                                            </div>
                                            <div className="flex flex-col items-center text-center gap-2">
                                                <div className="w-10 h-10 rounded-lg bg-slate-800 border border-slate-700 flex items-center justify-center text-lg">
                                                    {bonus.imageUrl
                                                        ? <img src={bonus.imageUrl} alt={bonus.name} className="w-full h-full object-contain rounded-lg" />
                                                        : <Moon className="w-5 h-5 text-slate-600" />
                                                    }
                                                </div>
                                                <h4 className="font-semibold text-slate-200 text-sm leading-tight">{bonus.name}</h4>
                                                {(bonus.costMin != null || bonus.costMax != null) && (
                                                    <span className="text-[10px] text-slate-500">
                                                        {bonus.costMin ?? "?"}{bonus.costMax && bonus.costMax !== bonus.costMin ? `–${bonus.costMax}` : ""} PR
                                                    </span>
                                                )}
                                                <Badge className={`text-[10px] border ${TYPE_COLORS[bonus.type]}`}>{bonus.type}</Badge>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}

            {/* Form Dialog */}
            <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
                <DialogContent className="w-[95vw] max-w-lg bg-slate-950 border-slate-800">
                    <DialogHeader>
                        <DialogTitle className="text-xl font-black text-white flex items-center gap-3">
                            <Moon className="w-6 h-6 text-indigo-400" />
                            {editing ? "Modifier le bonus" : "Nouveau bonus de rêve"}
                        </DialogTitle>
                        <DialogDescription className="text-slate-400">
                            Configurez les détails du bonus de rêve (Songes).
                        </DialogDescription>
                    </DialogHeader>
                    <form onSubmit={handleSubmit} className="space-y-4 pt-2">
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Nom *</label>
                            <Input
                                value={formData.name}
                                onChange={e => setFormData({ ...formData, name: e.target.value })}
                                required
                                placeholder="Ex: Abondance"
                                className="bg-slate-900 border-slate-700 text-white"
                            />
                        </div>
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Type</label>
                            <select
                                value={formData.type}
                                onChange={e => setFormData({ ...formData, type: e.target.value as any })}
                                className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-sm text-white"
                            >
                                <option value="ACTIF">⚡ Actif</option>
                                <option value="PASSIF">🌙 Passif</option>
                                <option value="CONSOMMABLE">🧪 Consommable</option>
                            </select>
                        </div>
                        <div className="grid grid-cols-2 gap-3">
                            <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Coût min (PR)</label>
                                <Input
                                    type="number" min={0}
                                    value={formData.costMin}
                                    onChange={e => setFormData({ ...formData, costMin: e.target.value })}
                                    placeholder="0"
                                    className="bg-slate-900 border-slate-700 text-white"
                                />
                            </div>
                            <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Coût max (PR)</label>
                                <Input
                                    type="number" min={0}
                                    value={formData.costMax}
                                    onChange={e => setFormData({ ...formData, costMax: e.target.value })}
                                    placeholder="0"
                                    className="bg-slate-900 border-slate-700 text-white"
                                />
                            </div>
                        </div>
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Description</label>
                            <textarea
                                value={formData.description}
                                onChange={e => setFormData({ ...formData, description: e.target.value })}
                                rows={3}
                                placeholder="Effets du bonus..."
                                className="w-full px-3 py-2 bg-slate-900 border border-slate-700 rounded-lg text-sm text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 resize-none"
                            />
                        </div>
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Illustration</label>
                            <ImageDownloader
                                type="item"
                                imageUrl={formData.imageUrl || ""}
                                identifier={formData.name}
                                onImageDownloaded={(path) => setFormData({ ...formData, imageUrl: path })}
                                className="w-full"
                            />
                        </div>
                        <div className="flex gap-3 pt-2">
                            <Button type="submit" className="flex-1 bg-indigo-600 hover:bg-indigo-500 font-bold">
                                {editing ? "💾 Enregistrer" : "➕ Créer"}
                            </Button>
                            <Button type="button" variant="outline" onClick={() => setIsDialogOpen(false)}
                                className="border-slate-700 text-slate-300 hover:bg-slate-800">
                                Annuler
                            </Button>
                        </div>
                    </form>
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { MultiSelect } from "@/components/ui/multi-select";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import { motion } from "framer-motion";
import {
    getDungeonsWithAchievements,
    createDungeon,
    updateDungeon,
    deleteDungeon,
    getChallenges,
} from "@/server/actions/game-data-admin-actions";
import { ImageDownloader } from "./ImageDownloader";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue
} from "@/components/ui/select";
import { Search, Plus, MapPin, Trophy, ShieldAlert, Swords, Skull, MoreHorizontal, Edit2, Trash2, ImageIcon } from "lucide-react";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

// Types
interface Dungeon {
    id: string;
    name: string;
    bossName: string;
    level: number;
    dpnlUrl?: string | null;
    dofuspourlesnoobsUrl?: string | null;
    dofensiveUrl?: string | null;
    imageUrl?: string | null;
    isExpedition: boolean;
    expeditionModes?: string[] | null;
    expeditionMechanics?: string | null;
    achievements: { challengeId: string; challenge: { name: string; slug: string; iconUrl?: string | null } }[];
}

interface Challenge {
    id: string;
    name: string;
    slug: string;
    iconUrl?: string | null;
}

const EXPEDITION_MODES = [
    { label: "Bravoure", value: "BRAVOURE", color: 0xeab308 }, // Yellow
    { label: "Audace", value: "AUDACE", color: 0xef4444 },   // Red
    { label: "Normal", value: "NORMAL", color: 0x3b82f6 },   // Blue
];

export default function DungeonManager() {
    const [dungeons, setDungeons] = useState<Dungeon[]>([]);
    const [challenges, setChallenges] = useState<Challenge[]>([]);
    const [loading, setLoading] = useState(true);
    const [editing, setEditing] = useState<string | null>(null);
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");
    const [challengeSearch, setChallengeSearch] = useState("");
    const [selectedLevel, setSelectedLevel] = useState<string>("all");

    // Form State
    const [formData, setFormData] = useState({
        name: "",
        bossName: "",
        level: 100,
        dpnlUrl: "",
        dofuspourlesnoobsUrl: "",
        dofensiveUrl: "",
        imageUrl: "",
        isExpedition: false,
        expeditionModes: [] as string[],
        expeditionMechanics: "",
        challengeIds: [] as string[],
    });

    useEffect(() => {
        loadData();
    }, [selectedLevel]);

    async function loadData() {
        setLoading(true);
        
        const filters: any = {};
        if (selectedLevel !== "all") {
            if (selectedLevel === "200") {
                filters.minLevel = 200;
                filters.maxLevel = 1000;
            } else {
                const [min, max] = selectedLevel.split("-").map(Number);
                if (!isNaN(min)) filters.minLevel = min;
                if (!isNaN(max)) filters.maxLevel = max;
            }
        }

        const [dungeonsRes, challengesRes] = await Promise.all([
            getDungeonsWithAchievements(filters),
            getChallenges()
        ]);

        if (dungeonsRes.success && dungeonsRes.data) {
            setDungeons(dungeonsRes.data);
            if (selectedLevel !== "all") {
                toast.info(`${dungeonsRes.data.length} donjons trouvés`);
            }
        } else {
            toast.error(dungeonsRes.error || "Erreur chargement donjons");
        }

        if (challengesRes.success && challengesRes.data) {
            setChallenges(challengesRes.data);
        }

        setLoading(false);
    }

    async function handleSubmit(e: React.FormEvent) {
        e.preventDefault();

        // Validation simple
        if (!formData.name || !formData.bossName) {
            toast.error("Nom et Boss requis");
            return;
        }

        const payload = {
            ...formData,
            // Ensure expedition modes is undefined if not expedition
            expeditionModes: formData.isExpedition ? formData.expeditionModes : undefined,
            expeditionMechanics: formData.isExpedition ? formData.expeditionMechanics : undefined,
        } as any; // Type cast to avoid excessive TS strictness with the exact Enum types on client side

        const result = editing
            ? await updateDungeon(editing, payload)
            : await createDungeon(payload);

        if (result.success) {
            toast.success(editing ? "Donjon mis à jour" : "Donjon créé");
            resetForm();
            setIsDialogOpen(false);
            loadData();
        } else {
            toast.error(result.error || "Erreur");
        }
    }

    async function handleDelete(id: string) {
        if (!confirm("Êtes-vous sûr de supprimer ce donjon ?")) return;

        const result = await deleteDungeon(id);
        if (result.success) {
            toast.success("Donjon supprimé");
            loadData();
        } else {
            toast.error(result.error || "Erreur de suppression");
        }
    }

    function resetForm() {
        setEditing(null);
        setChallengeSearch("");
        setFormData({
            name: "",
            bossName: "",
            level: 100,
            dpnlUrl: "",
            dofuspourlesnoobsUrl: "",
            dofensiveUrl: "",
            imageUrl: "",
            isExpedition: false,
            expeditionModes: [],
            expeditionMechanics: "",
            challengeIds: [],
        });
    }

    function startEdit(dungeon: Dungeon) {
        setEditing(dungeon.id);
        setChallengeSearch("");
        setFormData({
            name: dungeon.name,
            bossName: dungeon.bossName,
            level: dungeon.level,
            dpnlUrl: dungeon.dpnlUrl || "",
            dofuspourlesnoobsUrl: dungeon.dofuspourlesnoobsUrl || "",
            dofensiveUrl: dungeon.dofensiveUrl || "",
            imageUrl: dungeon.imageUrl || "",
            isExpedition: dungeon.isExpedition,
            expeditionModes: dungeon.expeditionModes || [],
            expeditionMechanics: dungeon.expeditionMechanics || "",
            challengeIds: dungeon.achievements.map(a => a.challengeId),
        });
        setIsDialogOpen(true);
    }



    const filteredDungeons = dungeons.filter(d =>
        d.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        d.bossName.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return (
        <div className="space-y-4">
            {/* Toolbar */}
            <div className="flex flex-col md:flex-row items-center gap-4 bg-slate-900/50 p-4 rounded-lg border border-slate-700/50 backdrop-blur-sm">
                <div className="relative flex-1 w-full">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <Input
                        placeholder="Rechercher un donjon ou un boss..."
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        className="pl-9 bg-slate-800 border-slate-700 text-slate-200 placeholder:text-slate-500 focus:ring-indigo-500/50"
                    />
                </div>

                {/* Level Filter */}
                <div className="w-full md:w-48">
                    <Select value={selectedLevel} onValueChange={setSelectedLevel}>
                        <SelectTrigger className="bg-slate-800 border-slate-700 text-slate-200">
                            <SelectValue placeholder="Filtrer par niveau" />
                        </SelectTrigger>
                        <SelectContent className="bg-slate-900 border-slate-700">
                            <SelectItem value="all">Tous les niveaux</SelectItem>
                            <SelectItem value="1-50">Niveau 1 - 50</SelectItem>
                            <SelectItem value="51-100">Niveau 51 - 100</SelectItem>
                            <SelectItem value="101-150">Niveau 101 - 150</SelectItem>
                            <SelectItem value="151-199">Niveau 151 - 199</SelectItem>
                            <SelectItem value="200">Niveau 200</SelectItem>
                        </SelectContent>
                    </Select>
                </div>
                <Button
                    onClick={() => { resetForm(); setIsDialogOpen(true); }}
                    className="w-full md:w-auto bg-indigo-600 hover:bg-indigo-700 shadow-lg shadow-indigo-900/20 transition-all font-medium"
                >
                    <Plus className="w-4 h-4 mr-2" />
                    Nouveau Donjon
                </Button>
            </div>

            {/* Grid List */}
            {loading ? (
                <div className="p-12 text-center text-slate-400 animate-pulse">Chargement des donjons...</div>
            ) : filteredDungeons.length === 0 ? (
                <div className="p-12 text-center text-slate-500 bg-slate-900/30 rounded-lg border border-dashed border-slate-700">
                    Aucun donjon trouvé
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                    {filteredDungeons.map((dungeon) => (
                        <div
                            key={dungeon.id}
                            className="group relative bg-slate-900/40 border border-slate-800 rounded-xl overflow-hidden hover:border-indigo-500/30 hover:shadow-xl hover:shadow-indigo-900/10 transition-all duration-300"
                        >
                            <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity z-10">
                                <DropdownMenu>
                                    <DropdownMenuTrigger asChild>
                                        <Button variant="ghost" size="icon" className="h-8 w-8 bg-slate-950/50 hover:bg-slate-800 text-slate-400">
                                            <MoreHorizontal className="w-4 h-4" />
                                        </Button>
                                    </DropdownMenuTrigger>
                                    <DropdownMenuContent align="end" className="bg-slate-900 border-slate-700">
                                        <DropdownMenuItem onClick={() => startEdit(dungeon)} className="text-slate-300 focus:bg-slate-800 cursor-pointer">
                                            <Edit2 className="w-4 h-4 mr-2 text-indigo-400" /> Modifier
                                        </DropdownMenuItem>
                                        <DropdownMenuItem onClick={() => handleDelete(dungeon.id)} className="text-red-400 focus:bg-red-950/30 cursor-pointer">
                                            <Trash2 className="w-4 h-4 mr-2" /> Supprimer
                                        </DropdownMenuItem>
                                    </DropdownMenuContent>
                                </DropdownMenu>
                            </div>

                            <div className="p-4 flex flex-col h-full gap-4">
                                <div className="flex items-start gap-4">
                                    <div className="relative w-16 h-16 rounded-lg overflow-hidden bg-slate-800 shrink-0 border border-slate-700 group-hover:border-indigo-500/50 transition-colors">
                                        {dungeon.imageUrl ? (
                                            <img
                                                src={dungeon.imageUrl}
                                                alt={dungeon.bossName}
                                                className="w-full h-full object-cover"
                                            />
                                        ) : (
                                            <div className="w-full h-full flex items-center justify-center text-slate-600">
                                                <ImageIcon className="w-8 h-8" />
                                            </div>
                                        )}
                                        {dungeon.isExpedition && (
                                            <div className="absolute bottom-0 inset-x-0 bg-indigo-600/90 text-[9px] text-center text-white py-0.5 font-bold uppercase tracking-wider">
                                                Expé
                                            </div>
                                        )}
                                    </div>

                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2 mb-1">
                                            <h3 className="font-bold text-slate-200 truncate group-hover:text-indigo-300 transition-colors">
                                                {dungeon.name}
                                            </h3>
                                        </div>
                                        <div className="flex items-center gap-2 text-sm text-slate-400">
                                            <Skull className="w-3.5 h-3.5" />
                                            <span className="truncate">{dungeon.bossName}</span>
                                        </div>
                                        <div className="mt-2 flex items-center gap-2">
                                            <Badge variant="outline" className="bg-slate-950/50 border-slate-700 text-slate-400 text-[10px] h-5">
                                                Lvl {dungeon.level}
                                            </Badge>
                                            {dungeon.achievements.length > 0 && (
                                                <Badge variant="outline" className="bg-yellow-950/20 border-yellow-900/30 text-yellow-500 text-[10px] h-5 gap-1">
                                                    <Trophy className="w-3 h-3" />
                                                    {dungeon.achievements.length}
                                                </Badge>
                                            )}
                                        </div>
                                    </div>
                                </div>

                                {/* Expedition Modes */}
                                {dungeon.isExpedition && dungeon.expeditionModes && dungeon.expeditionModes.length > 0 && (
                                    <div className="flex flex-wrap gap-1 pt-2 border-t border-slate-800/50">
                                        {dungeon.expeditionModes.map(mode => (
                                            <span key={mode} className="text-[10px] uppercase font-bold px-1.5 py-0.5 rounded bg-indigo-950/30 text-indigo-400 border border-indigo-900/30">
                                                {mode}
                                            </span>
                                        ))}
                                    </div>
                                )}

                                {/* Challenges Preview (Compact) */}
                                {dungeon.achievements.length > 0 && (
                                    <div className="flex gap-1 overflow-hidden pt-2 mt-auto border-t border-slate-800/50">
                                        {dungeon.achievements.slice(0, 5).map(({ challenge }) => (
                                            <div key={challenge.slug} className="w-6 h-6 rounded bg-slate-800/80 p-0.5 border border-slate-700" title={challenge.name}>
                                                {challenge.iconUrl && (
                                                    <img src={challenge.iconUrl} alt={challenge.name} className="w-full h-full object-contain" />
                                                )}
                                            </div>
                                        ))}
                                        {dungeon.achievements.length > 5 && (
                                            <div className="w-6 h-6 rounded bg-slate-800 text-[9px] flex items-center justify-center text-slate-500 border border-slate-700">
                                                +{dungeon.achievements.length - 5}
                                            </div>
                                        )}
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Form Dialog */}
            <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
                <DialogContent draggable className="w-[95vw] max-w-7xl max-h-[95vh] bg-slate-950 border-slate-800 p-0 overflow-hidden shadow-2xl flex flex-col">
                    {/* Header Draggable Handle */}
                    <div className="p-8 bg-slate-900/50 border-b border-slate-800 flex items-center justify-between shrink-0">
                        <DialogHeader>
                            <DialogTitle className="text-3xl font-black text-white flex items-center gap-4">
                                <Plus className="w-8 h-8 text-indigo-500" />
                                {editing ? "Modifier le donjon" : "Nouveau donjon"}
                            </DialogTitle>
                            <DialogDescription className="text-slate-400 text-lg">
                                Configurez les détails du donjon, son boss et les succès associés.
                            </DialogDescription>
                        </DialogHeader>
                    </div>

                    <div className="p-10 overflow-y-auto flex-1 custom-scrollbar">
                        <form onSubmit={handleSubmit} className="space-y-10 pb-6">
                            <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
                                {/* Left Column: Core Info & Illustration */}
                                <div className="lg:col-span-7 space-y-10">
                                    <div className="space-y-8 bg-slate-900/30 p-8 rounded-3xl border border-slate-800/50">
                                        <div className="flex items-center justify-between border-b border-slate-800 pb-4 mb-2">
                                            <h3 className="text-sm font-black text-indigo-400 uppercase tracking-[0.2em]">Informations Principales</h3>
                                            <div className="flex items-center gap-4 bg-slate-950 px-4 py-2 rounded-xl border border-slate-800">
                                                <span className="text-sm font-bold text-slate-400 uppercase">Expédition</span>
                                                <Switch
                                                    checked={formData.isExpedition}
                                                    onCheckedChange={(checked) => setFormData({ ...formData, isExpedition: checked })}
                                                    className="data-[state=checked]:bg-indigo-600"
                                                />
                                            </div>
                                        </div>

                                        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                                            <div className="md:col-span-3 space-y-3">
                                                <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Nom du Donjon <span className="text-rose-500 text-lg">*</span></label>
                                                <Input
                                                    value={formData.name}
                                                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                                    required
                                                    placeholder="Ex: Antre du Kralamoure"
                                                    className="h-16 bg-slate-950 border-slate-800 focus:border-indigo-500/50 focus:ring-indigo-500/20 text-xl font-bold transition-all rounded-2xl"
                                                />
                                            </div>
                                            <div className="space-y-3">
                                                <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Niveau <span className="text-rose-500 text-lg">*</span></label>
                                                <div className="relative">
                                                    <Input
                                                        type="number"
                                                        value={formData.level}
                                                        onChange={(e) => setFormData({ ...formData, level: parseInt(e.target.value) || 1 })}
                                                        required
                                                        min={1}
                                                        max={1000}
                                                        className="h-16 bg-slate-950 border-slate-800 focus:border-indigo-500/50 focus:ring-indigo-500/20 pl-14 font-black italic text-indigo-400 text-2xl transition-all rounded-2xl"
                                                    />
                                                    <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600 font-bold select-none text-sm">Lvl</div>
                                                </div>
                                            </div>
                                        </div>

                                        <div className="space-y-3">
                                            <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Nom du Boss <span className="text-rose-500 text-lg">*</span></label>
                                            <Input
                                                value={formData.bossName}
                                                onChange={(e) => setFormData({ ...formData, bossName: e.target.value })}
                                                required
                                                placeholder="Ex: Kralamoure Géant"
                                                className="h-16 bg-slate-950 border-slate-800 focus:border-indigo-500/50 focus:ring-indigo-500/20 text-xl font-bold transition-all rounded-2xl"
                                            />
                                        </div>

                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                            <div className="space-y-3">
                                                <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Lien DofusPourLesNoobs</label>
                                                <Input
                                                    value={formData.dofuspourlesnoobsUrl}
                                                    onChange={(e) => setFormData({ ...formData, dofuspourlesnoobsUrl: e.target.value })}
                                                    placeholder="https://www.dofuspourlesnoobs.com/..."
                                                    className="h-14 bg-slate-950 border-slate-800 focus:border-indigo-500/50 focus:ring-indigo-500/20 text-sm transition-all rounded-xl"
                                                />
                                            </div>
                                            <div className="space-y-3">
                                                <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Lien Dofensive</label>
                                                <Input
                                                    value={formData.dofensiveUrl}
                                                    onChange={(e) => setFormData({ ...formData, dofensiveUrl: e.target.value })}
                                                    placeholder="https://dofensive.com/fr/monster/..."
                                                    className="h-14 bg-slate-950 border-slate-800 focus:border-indigo-500/50 focus:ring-indigo-500/20 text-sm transition-all rounded-xl"
                                                />
                                            </div>
                                        </div>
                                    </div>

                                    {/* Expedition Settings */}
                                    {formData.isExpedition && (
                                        <motion.div
                                            initial={{ opacity: 0, y: -10 }}
                                            animate={{ opacity: 1, y: 0 }}
                                            className="space-y-8 p-8 bg-indigo-500/5 rounded-3xl border border-indigo-500/20 shadow-inner shadow-indigo-500/5"
                                        >
                                            <div className="space-y-3">
                                                <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Modes Disponibles</label>
                                                <MultiSelect
                                                    options={EXPEDITION_MODES}
                                                    selected={formData.expeditionModes}
                                                    onChange={(selected) => setFormData({ ...formData, expeditionModes: selected })}
                                                    placeholder="Choisir les modes..."
                                                    className="bg-slate-950 border-slate-800 min-h-[50px] rounded-xl"
                                                />
                                            </div>
                                            <div className="space-y-3">
                                                <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Mécaniques</label>
                                                <textarea
                                                    value={formData.expeditionMechanics || ""}
                                                    onChange={(e) => setFormData({ ...formData, expeditionMechanics: e.target.value })}
                                                    placeholder="Détails spécifiques des mécaniques..."
                                                    className="w-full px-4 py-3 bg-slate-950 border border-slate-800 rounded-xl text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500/50 resize-none min-h-[100px]"
                                                />
                                            </div>
                                        </motion.div>
                                    )}

                                    <div className="bg-slate-950/50 p-8 rounded-3xl border border-slate-800 shadow-inner">
                                        <h3 className="text-sm font-black text-indigo-400 uppercase tracking-[0.2em] border-b border-slate-800 pb-4 mb-6">Illustration</h3>
                                        <ImageDownloader
                                            type="dungeon"
                                            imageUrl={formData.imageUrl}
                                            identifier={formData.name}
                                            onImageDownloaded={(path) => setFormData({ ...formData, imageUrl: path })}
                                            className="w-full"
                                        />
                                    </div>
                                </div>

                                {/* Right Column: Success & Challenges */}
                                <div className="lg:col-span-5 h-full">
                                    <div className="h-full space-y-4 bg-slate-900/30 p-8 rounded-3xl border border-slate-800/50 flex flex-col">
                                         <div className="border-b border-slate-800 pb-4">
                                            <h3 className="text-sm font-black text-indigo-400 uppercase tracking-[0.2em]">Succès du Boss</h3>
                                            <p className="text-xs text-slate-500 mt-2 font-medium">
                                                Assurez-vous qu'ils correspondent aux mécaniques du donjon.
                                            </p>
                                        </div>

                                        <div className="flex-1 flex flex-col min-h-[500px]">
                                            <div className="space-y-4 mb-4">
                                                <div className="flex items-center justify-between">
                                                    <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">
                                                        Succès Associés
                                                    </label>
                                                    <Badge variant="outline" className="bg-indigo-500/10 border-indigo-500/20 text-indigo-400">
                                                        {formData.challengeIds.length} sélectionné(s)
                                                    </Badge>
                                                </div>
                                                <div className="relative">
                                                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-500" />
                                                    <Input
                                                        placeholder="Filtrer les succès..."
                                                        value={challengeSearch}
                                                        onChange={e => setChallengeSearch(e.target.value)}
                                                        className="h-10 pl-9 bg-slate-950 border-slate-800 text-xs text-slate-300 placeholder:text-zinc-700"
                                                    />
                                                </div>
                                            </div>

                                            <div className="grid grid-cols-4 sm:grid-cols-5 gap-2 overflow-y-auto pr-2 custom-scrollbar flex-1 max-h-[500px]">
                                                {challenges
                                                    .filter(c => c.name.toLowerCase().includes(challengeSearch.toLowerCase()))
                                                    .map((challenge) => {
                                                    const isSelected = formData.challengeIds.includes(challenge.id);
                                                    return (
                                                        <button
                                                            key={challenge.id}
                                                            type="button"
                                                            onClick={() => {
                                                                setFormData((prev) => ({
                                                                    ...prev,
                                                                    challengeIds: isSelected
                                                                        ? prev.challengeIds.filter((id) => id !== challenge.id)
                                                                        : [...prev.challengeIds, challenge.id],
                                                                }));
                                                            }}
                                                            className={`
                                                                relative aspect-square rounded-xl p-2 border-2 transition-all group flex flex-col items-center justify-center gap-1
                                                                ${isSelected
                                                                    ? "border-indigo-500 bg-indigo-500/10 shadow-[0_0_15px_rgba(99,102,241,0.2)]"
                                                                    : "border-slate-800 bg-slate-900/50 hover:border-slate-600 hover:bg-slate-800"
                                                                }
                                                            `}
                                                            title={challenge.name}
                                                        >
                                                            {challenge.iconUrl ? (
                                                                <img
                                                                    src={challenge.iconUrl}
                                                                    alt={challenge.name}
                                                                    className={`w-8 h-8 object-contain transition-transform ${isSelected ? "scale-110" : "group-hover:scale-110"}`}
                                                                />
                                                            ) : (
                                                                <Trophy className={`w-6 h-6 ${isSelected ? "text-indigo-400" : "text-slate-600"}`} />
                                                            )}
                                                            <span className="text-[9px] font-bold text-slate-400 text-center leading-tight line-clamp-2 w-full mt-1">
                                                                {challenge.name}
                                                            </span>

                                                            {isSelected && (
                                                                <div className="absolute -top-1.5 -right-1.5 bg-indigo-500 text-white rounded-full p-0.5 shadow-lg">
                                                                    <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                                                                        <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                                                                    </svg>
                                                                </div>
                                                            )}
                                                        </button>
                                                    );
                                                })}
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="flex gap-4 pt-6 border-t border-slate-800 sticky bottom-0 bg-slate-950 py-4 shrink-0">
                                <Button type="submit" className="flex-[3] bg-indigo-600 hover:bg-indigo-500 h-14 text-lg font-black uppercase tracking-widest shadow-xl shadow-indigo-600/20 transition-all rounded-xl active:scale-[0.98]">
                                    {editing ? "💾 Enregistrer" : "➕ Créer le Donjon"}
                                </Button>
                                <Button
                                    type="button"
                                    variant="outline"
                                    onClick={() => setIsDialogOpen(false)}
                                    className="flex-1 h-14 border-white/10 hover:bg-white/5 text-slate-300 text-sm font-bold uppercase tracking-widest transition-all rounded-xl"
                                >
                                    Fermer
                                </Button>
                            </div>
                        </form>
                    </div>
                </DialogContent>
            </Dialog>
        </div >
    );
}

'use client';

import { useState, useCallback, useEffect } from 'react';
import { toast } from 'sonner';
import { Sparkles, Plus, Trash2, Link, Unlink, ChevronDown, ChevronRight, Loader2, Swords, Castle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { cn } from '@/lib/utils';
import { AsyncCombobox } from '@/components/ui/async-combobox';
import {
    getEventZones,
    upsertEventZone,
    deleteEventZone,
    linkFamilyToZone,
    unlinkFamilyFromZone,
    linkDungeonToZone,
    unlinkDungeonFromZone,
    getMonsterFamilies,
    searchDungeonsAdvanced,
} from '@/server/actions/game-data-actions';

// ─── Constants ────────────────────────────────────────────────

const PRESET_ZONES = [
    { key: 'VULKANIA', label: 'Vulkania', emoji: '🦕', period: 'Été', color: 'text-green-300', border: 'border-green-500/30 bg-green-500/5' },
    { key: 'PWAK', label: 'Île de Pwâk', emoji: '🐣', period: 'Pâques', color: 'text-yellow-300', border: 'border-yellow-500/30 bg-yellow-500/5' },
    { key: 'HALOUINE', label: 'Halouine', emoji: '🎃', period: 'Halloween', color: 'text-orange-300', border: 'border-orange-500/30 bg-orange-500/5' },
    { key: 'NOWEL', label: 'Île de Nowel', emoji: '🎄', period: 'Noël', color: 'text-red-300', border: 'border-red-500/30 bg-red-500/5' },
] as const;

type PresetKey = typeof PRESET_ZONES[number]['key'];

// ─── Component ────────────────────────────────────────────────

export function EventZoneManager() {
    const [eventZones, setEventZones] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [expandedZone, setExpandedZone] = useState<string | null>(null);
    const [saving, setSaving] = useState<string | null>(null);

    // Form for creating a custom zone
    const [showCustomForm, setShowCustomForm] = useState(false);
    const [customName, setCustomName] = useState('');
    const [customKey, setCustomKey] = useState('AUTRE');
    const [customLevel, setCustomLevel] = useState(1);
    const [creatingCustom, setCreatingCustom] = useState(false);

    // Family/dungeon search local caches
    const [familyCache, setFamilyCache] = useState<Record<string, any[]>>({});

    const load = useCallback(async () => {
        setIsLoading(true);
        const res = await getEventZones();
        if (res.success && res.data) setEventZones(res.data);
        setIsLoading(false);
    }, []);

    useEffect(() => { load(); }, [load]);

    // Check which presets are already created
    const existingKeys = eventZones.map(z => z.eventZoneKey);

    const handleCreatePreset = async (preset: typeof PRESET_ZONES[number]) => {
        setSaving(preset.key);
        const res = await upsertEventZone({ name: preset.label, level: 1, eventZoneKey: preset.key });
        if (res.success) {
            toast.success(`Zone "${preset.label}" créée !`);
            await load();
            setExpandedZone(res.data?.id ?? null);
        } else {
            toast.error(res.error);
        }
        setSaving(null);
    };

    const handleCreateCustom = async () => {
        if (!customName.trim()) return;
        setCreatingCustom(true);
        const res = await upsertEventZone({ name: customName.trim(), level: customLevel, eventZoneKey: 'AUTRE' });
        if (res.success) {
            toast.success(`Zone événement "${customName}" créée !`);
            setCustomName('');
            setCustomKey('AUTRE');
            setCustomLevel(1);
            setShowCustomForm(false);
            await load();
            setExpandedZone(res.data?.id ?? null);
        } else {
            toast.error(res.error);
        }
        setCreatingCustom(false);
    };

    const handleDeleteZone = async (zone: any) => {
        if (!confirm(`Supprimer la zone "${zone.name}" ? Cela supprimera aussi les liens avec familles et donjons.`)) return;
        const res = await deleteEventZone(zone.id);
        if (res.success) {
            toast.success('Zone supprimée');
            setExpandedZone(null);
            await load();
        } else {
            toast.error(res.error);
        }
    };

    const familyFetcher = useCallback(async (query: string) => {
        const res = await getMonsterFamilies({ search: query });
        if (res.success && res.data) {
            const items = res.data.map((f: any) => ({ value: f.id, label: f.name }));
            setFamilyCache(prev => {
                const next = { ...prev };
                res.data?.forEach((f: any) => { next[f.id] = f; });
                return next;
            });
            return items;
        }
        return [];
    }, []);

    const dungeonFetcher = useCallback(async (query: string) => {
        const res = await searchDungeonsAdvanced({ query });
        if (res.success && res.data) {
            return res.data.map((d: any) => ({ value: d.id, label: d.name, subLabel: `Niv. ${d.level} · Boss: ${d.bossName}` }));
        }
        return [];
    }, []);

    const handleLinkFamily = async (zoneId: string, familyId: string) => {
        const res = await linkFamilyToZone(zoneId, familyId);
        if (res.success) { toast.success('Famille liée !'); await load(); }
        else toast.error(res.error);
    };

    const handleUnlinkFamily = async (zoneId: string, familyId: string) => {
        const res = await unlinkFamilyFromZone(zoneId, familyId);
        if (res.success) { toast.success('Famille retirée'); await load(); }
        else toast.error(res.error);
    };

    const handleLinkDungeon = async (zoneId: string, dungeonId: string) => {
        const res = await linkDungeonToZone(zoneId, dungeonId);
        if (res.success) { toast.success('Donjon lié !'); await load(); }
        else toast.error(res.error);
    };

    const handleUnlinkDungeon = async (zoneId: string, dungeonId: string) => {
        const res = await unlinkDungeonFromZone(zoneId, dungeonId);
        if (res.success) { toast.success('Donjon retiré'); await load(); }
        else toast.error(res.error);
    };

    return (
        <div className="space-y-8">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <div className="p-2.5 rounded-xl bg-yellow-500/10 border border-yellow-500/20">
                        <Sparkles className="w-5 h-5 text-yellow-400" />
                    </div>
                    <div>
                        <h2 className="text-lg font-black text-white">Zones Événements</h2>
                        <p className="text-xs text-zinc-500">Zones saisonnières Dofus · familles de monstres et donjons associés</p>
                    </div>
                </div>
                <Button
                    size="sm"
                    variant="outline"
                    className="border-zinc-700 text-zinc-400 hover:text-white hover:border-zinc-500"
                    onClick={() => setShowCustomForm(v => !v)}
                >
                    <Plus className="w-3.5 h-3.5 mr-1.5" />
                    Zone personnalisée
                </Button>
            </div>

            {/* Preset zone buttons (4 saisons) */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                {PRESET_ZONES.map(preset => {
                    const exists = existingKeys.includes(preset.key);
                    const zone = eventZones.find(z => z.eventZoneKey === preset.key);
                    return (
                        <button
                            key={preset.key}
                            onClick={exists ? () => setExpandedZone(z => z === zone?.id ? null : zone?.id) : () => handleCreatePreset(preset)}
                            disabled={saving === preset.key}
                            className={cn(
                                'flex flex-col items-center gap-2 p-5 rounded-2xl border text-center transition-all duration-300 group',
                                exists
                                    ? cn(preset.border, 'hover:brightness-110')
                                    : 'bg-zinc-900/60 border-zinc-800 hover:border-zinc-600 opacity-60 hover:opacity-100'
                            )}
                        >
                            <span className="text-3xl">{preset.emoji}</span>
                            <div>
                                <div className={cn('text-xs font-black', exists ? preset.color : 'text-zinc-400')}>{preset.label}</div>
                                <div className="text-[9px] text-zinc-500 uppercase tracking-widest">{preset.period}</div>
                            </div>
                            {exists ? (
                                <div className="flex items-center gap-1.5 text-[10px] font-bold text-zinc-400">
                                    <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" />
                                    {zone?.families?.length ?? 0} familles · {zone?.dungeons?.length ?? 0} donjons
                                </div>
                            ) : (
                                <div className="text-[10px] text-zinc-600 group-hover:text-zinc-400 transition-colors">
                                    {saving === preset.key ? <Loader2 className="w-3 h-3 animate-spin" /> : 'Cliquer pour créer'}
                                </div>
                            )}
                        </button>
                    );
                })}
            </div>

            {/* Custom zone form */}
            {showCustomForm && (
                <div className="p-4 bg-zinc-900 border border-zinc-700 rounded-xl space-y-3">
                    <p className="text-xs text-zinc-400 font-bold uppercase tracking-widest">Zone événement personnalisée</p>
                    <div className="flex gap-3">
                        <Input
                            className="flex-1 bg-zinc-950 border-zinc-700"
                            placeholder="Nom de la zone (ex: Temporis IX, Krosmoz de Feu...)"
                            value={customName}
                            onChange={e => setCustomName(e.target.value)}
                        />
                        <Input
                            type="number"
                            className="w-24 bg-zinc-950 border-zinc-700"
                            placeholder="Niv."
                            min={1}
                            max={230}
                            value={customLevel}
                            onChange={e => setCustomLevel(parseInt(e.target.value) || 1)}
                        />
                        <Button onClick={handleCreateCustom} disabled={creatingCustom || !customName.trim()} size="sm">
                            {creatingCustom ? <Loader2 className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4" />}
                        </Button>
                    </div>
                </div>
            )}

            {/* Zone detail panels */}
            {isLoading ? (
                <div className="flex justify-center py-12">
                    <Loader2 className="w-8 h-8 animate-spin text-zinc-600" />
                </div>
            ) : (
                <div className="space-y-3">
                    {eventZones.length === 0 && (
                        <div className="text-center py-12 text-zinc-600 text-sm">
                            Aucune zone événement — clique sur un preset ci-dessus pour commencer.
                        </div>
                    )}
                    {eventZones.map(zone => {
                        const preset = PRESET_ZONES.find(p => p.key === zone.eventZoneKey);
                        const isExpanded = expandedZone === zone.id;
                        return (
                            <div key={zone.id} className={cn('rounded-2xl border transition-all', preset?.border ?? 'border-zinc-800 bg-zinc-900/60')}>
                                {/* Zone header */}
                                <div
                                    className="w-full flex items-center justify-between p-4 cursor-pointer"
                                    onClick={() => setExpandedZone(v => v === zone.id ? null : zone.id)}
                                    role="button"
                                    tabIndex={0}
                                    onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') setExpandedZone(v => v === zone.id ? null : zone.id); }}
                                >
                                    <div className="flex items-center gap-3">
                                        <span className="text-2xl">{preset?.emoji ?? '✨'}</span>
                                        <div>
                                            <div className={cn('font-black text-sm', preset?.color ?? 'text-zinc-200')}>{zone.name}</div>
                                            <div className="text-[10px] text-zinc-500">{zone.families?.length} familles · {zone.dungeons?.length} donjons</div>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <button
                                            onClick={e => { e.stopPropagation(); handleDeleteZone(zone); }}
                                            className="p-1.5 rounded-lg hover:bg-red-500/10 text-zinc-600 hover:text-red-400 transition-colors"
                                        >
                                            <Trash2 className="w-3.5 h-3.5" />
                                        </button>
                                        {isExpanded ? <ChevronDown className="w-4 h-4 text-zinc-500" /> : <ChevronRight className="w-4 h-4 text-zinc-500" />}
                                    </div>
                                </div>

                                {/* Expanded content */}
                                {isExpanded && (
                                    <div className="px-4 pb-4 space-y-5 border-t border-white/5 pt-4">
                                        {/* Familles de monstres */}
                                        <div className="space-y-3">
                                            <div className="flex items-center gap-2 text-xs font-black text-zinc-400 uppercase tracking-widest">
                                                <Swords className="w-3.5 h-3.5" /> Familles de monstres
                                            </div>
                                            <div className="flex flex-wrap gap-2">
                                                {zone.families?.map((f: any) => (
                                                    <div key={f.id} className="flex items-center gap-1.5 px-2.5 py-1 bg-zinc-800 rounded-full text-xs text-zinc-300 border border-zinc-700">
                                                        {f.name}
                                                        <button onClick={() => handleUnlinkFamily(zone.id, f.id)} className="hover:text-red-400 transition-colors ml-0.5">
                                                            <Unlink className="w-3 h-3" />
                                                        </button>
                                                    </div>
                                                ))}
                                                {zone.families?.length === 0 && <span className="text-xs text-zinc-600">Aucune famille liée</span>}
                                            </div>
                                            <AsyncCombobox
                                                value=""
                                                onSelect={id => handleLinkFamily(zone.id, id)}
                                                fetcher={familyFetcher}
                                                placeholder="Ajouter une famille de monstres..."
                                                searchPlaceholder="Rechercher une famille..."
                                            />
                                        </div>

                                        {/* Donjons */}
                                        <div className="space-y-3">
                                            <div className="flex items-center gap-2 text-xs font-black text-zinc-400 uppercase tracking-widest">
                                                <Castle className="w-3.5 h-3.5" /> Donjons événement
                                            </div>
                                            <div className="flex flex-wrap gap-2">
                                                {zone.dungeons?.map((d: any) => (
                                                    <div key={d.id} className="flex items-center gap-1.5 px-2.5 py-1 bg-zinc-800 rounded-full text-xs text-zinc-300 border border-zinc-700">
                                                        {d.name}
                                                        <span className="text-zinc-600 text-[9px]">· {d.bossName}</span>
                                                        <button onClick={() => handleUnlinkDungeon(zone.id, d.id)} className="hover:text-red-400 transition-colors ml-0.5">
                                                            <Unlink className="w-3 h-3" />
                                                        </button>
                                                    </div>
                                                ))}
                                                {zone.dungeons?.length === 0 && <span className="text-xs text-zinc-600">Aucun donjon lié</span>}
                                            </div>
                                            <AsyncCombobox
                                                value=""
                                                onSelect={id => handleLinkDungeon(zone.id, id)}
                                                fetcher={dungeonFetcher}
                                                placeholder="Ajouter un donjon..."
                                                searchPlaceholder="Rechercher un donjon..."
                                            />
                                        </div>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
    );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    getGameQuests,
    createGameQuest,
    updateGameQuest,
    deleteGameQuest,
} from "@/server/actions/game-data-admin-actions";
import { Map, Trash2, Edit2, Plus, Search, MoreHorizontal, ExternalLink, Loader2, ChevronDown, ChevronUp, BookOpen, Award } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { getQuestPrerequisites } from "@/server/actions/dofus-search-actions";

interface GameQuest {
    id: string;
    name: string;
    dofusDbId?: number | null;
    levelMin?: number | null;
    levelMax?: number | null;
    description?: string | null;
    imageUrl?: string | null;
    category?: string | null;
}

const CATEGORIES = [
    "Épique", "Dimensionnelle", "Quête de Zone", "Scénario", "Légendaire", "Autre"
];

export default function GameQuestManager() {
    const [quests, setQuests] = useState<GameQuest[]>([]);
    const [loading, setLoading] = useState(true);
    const [editing, setEditing] = useState<string | null>(null);
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");

    // Advanced Filters state
    const [selectedCategory, setSelectedCategory] = useState<string>("");
    const [minLevel, setMinLevel] = useState<string>("");
    const [maxLevel, setMaxLevel] = useState<string>("");
    const [selectedSource, setSelectedSource] = useState<string>("ALL");

    // Prerequisites dynamic loader state
    const [expandedQuestId, setExpandedQuestId] = useState<string | null>(null);
    const [loadedPrereqs, setLoadedPrereqs] = useState<Record<number, any>>({});
    const [loadingPrereqs, setLoadingPrereqs] = useState<Record<number, boolean>>({});

    const togglePrerequisites = useCallback(async (questId: string, dofusDbId: number) => {
        if (expandedQuestId === questId) {
            setExpandedQuestId(null);
            return;
        }
        setExpandedQuestId(questId);
        if (loadedPrereqs[dofusDbId]) return;

        setLoadingPrereqs(prev => ({ ...prev, [dofusDbId]: true }));
        const res = await getQuestPrerequisites(dofusDbId);
        if (res.success && res.data) {
            setLoadedPrereqs(prev => ({ ...prev, [dofusDbId]: res.data }));
        } else {
            toast.error(res.error || "Impossible de charger les prérequis");
        }
        setLoadingPrereqs(prev => ({ ...prev, [dofusDbId]: false }));
    }, [expandedQuestId, loadedPrereqs]);

    const [formData, setFormData] = useState({
        name: "",
        dofusDbId: "" as string | number,
        levelMin: "" as string | number,
        levelMax: "" as string | number,
        description: "",
        imageUrl: "",
        category: "",
    });

    const loadQuests = useCallback(async () => {
        setLoading(true);
        const result = await getGameQuests();
        if (result.success && result.data) setQuests(result.data);
        setLoading(false);
    }, []);

    useEffect(() => { loadQuests(); }, [loadQuests]);

    async function handleSubmit(e: React.FormEvent) {
        e.preventDefault();
        const payload = {
            name: formData.name,
            dofusDbId: formData.dofusDbId !== "" ? Number(formData.dofusDbId) : null,
            levelMin: formData.levelMin !== "" ? Number(formData.levelMin) : null,
            levelMax: formData.levelMax !== "" ? Number(formData.levelMax) : null,
            description: formData.description || undefined,
            imageUrl: formData.imageUrl || undefined,
            category: formData.category || undefined,
        };
        const result = editing
            ? await updateGameQuest(editing, payload)
            : await createGameQuest(payload);

        if (result.success) {
            toast.success(editing ? "Quête mise à jour" : "Quête créée");
            resetForm();
            setIsDialogOpen(false);
            loadQuests();
        } else {
            toast.error(result.error || "Erreur");
        }
    }

    async function handleDelete(id: string) {
        if (!confirm("Supprimer cette quête ?")) return;
        const result = await deleteGameQuest(id);
        if (result.success) { toast.success("Quête supprimée"); loadQuests(); }
        else toast.error(result.error);
    }

    function resetForm() {
        setFormData({ name: "", dofusDbId: "", levelMin: "", levelMax: "", description: "", imageUrl: "", category: "" });
        setEditing(null);
    }

    function startEdit(quest: GameQuest) {
        setEditing(quest.id);
        setFormData({
            name: quest.name,
            dofusDbId: quest.dofusDbId ?? "",
            levelMin: quest.levelMin ?? "",
            levelMax: quest.levelMax ?? "",
            description: quest.description || "",
            imageUrl: quest.imageUrl || "",
            category: quest.category || "",
        });
        setIsDialogOpen(true);
    }

    // Dynamically build all categories from all quests
    const allCategories = [...new Set(quests.map(q => q.category).filter(Boolean))].sort() as string[];

    const filtered = quests.filter(q => {
        // Search query
        const matchSearch = searchQuery === "" ||
            q.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            (q.category || "").toLowerCase().includes(searchQuery.toLowerCase()) ||
            (q.dofusDbId?.toString() || "").includes(searchQuery);

        // Category/Zone
        const matchCategory = selectedCategory === "" || q.category === selectedCategory;

        // Level bounds
        const qMin = q.levelMin ?? 1;
        const passMin = minLevel === "" || qMin >= Number(minLevel);
        const passMax = maxLevel === "" || qMin <= Number(maxLevel);

        // Source filter
        const isDofusDb = q.dofusDbId !== null && q.dofusDbId !== undefined;
        const matchSource = selectedSource === "ALL" ||
            (selectedSource === "DOFUSDB" && isDofusDb) ||
            (selectedSource === "MANUAL" && !isDofusDb);

        return matchSearch && matchCategory && passMin && passMax && matchSource;
    });

    const hasActiveFilters = selectedCategory !== "" || minLevel !== "" || maxLevel !== "" || selectedSource !== "ALL" || searchQuery !== "";

    // Group by category
    const categories = [...new Set(filtered.map(q => q.category || "Non classé"))].sort();

    return (
        <div className="space-y-4">
            {/* Toolbar & Filters */}
            <div className="bg-slate-900/50 p-4 rounded-lg border border-slate-700/50 space-y-4">
                <div className="flex flex-col md:flex-row items-center gap-4">
                    <div className="relative flex-1 w-full">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                        <Input
                            placeholder="Rechercher une quête par nom ou catégorie..."
                            value={searchQuery}
                            onChange={e => setSearchQuery(e.target.value)}
                            className="pl-9 bg-slate-800 border-slate-700 text-slate-200 placeholder:text-slate-500 focus:ring-indigo-500/20 focus:border-indigo-500"
                        />
                    </div>
                    <Button
                        onClick={() => { resetForm(); setIsDialogOpen(true); }}
                        className="w-full md:w-auto bg-indigo-600 hover:bg-indigo-700 font-semibold transition-all shadow-lg shadow-indigo-600/10 hover:shadow-indigo-600/20 shrink-0"
                    >
                        <Plus className="w-4 h-4 mr-2" /> Nouvelle Quête
                    </Button>
                </div>

                {/* Advanced Filters */}
                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-3 pt-4 border-t border-slate-800/60">
                    {/* Zone/Category dropdown */}
                    <div className="space-y-1">
                        <label className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Zone / Catégorie</label>
                        <select
                            value={selectedCategory}
                            onChange={e => setSelectedCategory(e.target.value)}
                            className="w-full bg-slate-800 border border-slate-700/60 rounded-md px-3 py-1.5 text-xs text-slate-200 focus:outline-none focus:ring-1 focus:ring-indigo-500/40 focus:border-indigo-500 cursor-pointer"
                        >
                            <option value="">Toutes les zones</option>
                            {allCategories.map(cat => (
                                <option key={cat} value={cat}>{cat}</option>
                            ))}
                        </select>
                    </div>

                    {/* Min Level */}
                    <div className="space-y-1">
                        <label className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Niveau Min</label>
                        <Input
                            type="number"
                            placeholder="1"
                            min={1}
                            max={200}
                            value={minLevel}
                            onChange={e => setMinLevel(e.target.value)}
                            className="h-8 bg-slate-800 border-slate-700/60 text-xs text-slate-200 placeholder:text-slate-600 focus:ring-1 focus:ring-indigo-500/40 focus:border-indigo-500"
                        />
                    </div>

                    {/* Max Level */}
                    <div className="space-y-1">
                        <label className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Niveau Max</label>
                        <Input
                            type="number"
                            placeholder="200"
                            min={1}
                            max={200}
                            value={maxLevel}
                            onChange={e => setMaxLevel(e.target.value)}
                            className="h-8 bg-slate-800 border-slate-700/60 text-xs text-slate-200 placeholder:text-slate-600 focus:ring-1 focus:ring-indigo-500/40 focus:border-indigo-500"
                        />
                    </div>

                    {/* Source */}
                    <div className="space-y-1">
                        <label className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Source</label>
                        <select
                            value={selectedSource}
                            onChange={e => setSelectedSource(e.target.value)}
                            className="w-full bg-slate-800 border border-slate-700/60 rounded-md px-3 py-1.5 text-xs text-slate-200 focus:outline-none focus:ring-1 focus:ring-indigo-500/40 focus:border-indigo-500 cursor-pointer"
                        >
                            <option value="ALL">Toutes les sources</option>
                            <option value="DOFUSDB">DofusDB uniquement</option>
                            <option value="MANUAL">Manuelle uniquement</option>
                        </select>
                    </div>
                </div>

                {hasActiveFilters && (
                    <div className="flex justify-end pt-1">
                        <button
                            onClick={() => {
                                setSearchQuery("");
                                setSelectedCategory("");
                                setMinLevel("");
                                setMaxLevel("");
                                setSelectedSource("ALL");
                            }}
                            className="text-xs text-rose-400 hover:text-rose-300 font-semibold transition-all underline decoration-dotted underline-offset-4 cursor-pointer"
                        >
                            Réinitialiser les filtres
                        </button>
                    </div>
                )}
            </div>

            {loading ? (
                <div className="p-12 text-center text-slate-400 animate-pulse">Chargement...</div>
            ) : filtered.length === 0 ? (
                <div className="p-12 text-center text-slate-500 border border-dashed border-slate-700 rounded-lg">
                    Aucune quête trouvée
                </div>
            ) : (
                <div className="space-y-6">
                    {categories.map(cat => {
                        const items = filtered.filter(q => (q.category || "Non classé") === cat);
                        return (
                            <div key={cat}>
                                <h3 className="text-xs font-black uppercase tracking-widest text-cyan-400 mb-3 flex items-center gap-2 border-b border-slate-800 pb-2">
                                    <Map className="w-3 h-3" /> {cat} ({items.length})
                                </h3>
                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                                    {items.map(quest => (
                                        <div
                                            key={quest.id}
                                            className="group relative bg-slate-900/40 border border-slate-800 rounded-xl p-4 hover:border-indigo-500/30 transition-all flex flex-col gap-3"
                                        >
                                            <div className="flex items-start gap-3 w-full">
                                                <div className="w-10 h-10 rounded-lg bg-slate-800 border border-slate-700 flex items-center justify-center shrink-0">
                                                    {quest.imageUrl
                                                        ? <img src={quest.imageUrl} alt={quest.name} className="w-full h-full object-contain rounded-lg" />
                                                        : <Map className="w-5 h-5 text-slate-600" />
                                                    }
                                                </div>
                                                <div className="flex-1 min-w-0">
                                                    <h4 className="font-semibold text-slate-200 text-sm truncate">{quest.name}</h4>
                                                    <div className="flex items-center gap-2 mt-1 flex-wrap">
                                                        {(quest.levelMin || quest.levelMax) && (
                                                            <span className="text-[10px] text-slate-500">
                                                                Niv. {quest.levelMin ?? "?"}{quest.levelMax && quest.levelMax !== quest.levelMin ? `–${quest.levelMax}` : ""}
                                                            </span>
                                                        )}
                                                        {quest.dofusDbId ? (
                                                            <div className="flex items-center gap-2">
                                                                <a
                                                                    href={`https://dofusdb.fr/fr/database/quest/${quest.dofusDbId}`}
                                                                    target="_blank" rel="noopener noreferrer"
                                                                    onClick={e => e.stopPropagation()}
                                                                    className="text-[10px] text-cyan-500 hover:text-cyan-400 flex items-center gap-0.5"
                                                                >
                                                                    <ExternalLink className="w-2.5 h-2.5" /> DofusDB
                                                                </a>
                                                                <button
                                                                    onClick={() => togglePrerequisites(quest.id, quest.dofusDbId!)}
                                                                    className="text-[10px] text-indigo-400 hover:text-indigo-300 font-medium flex items-center gap-1 transition-colors"
                                                                >
                                                                    {loadingPrereqs[quest.dofusDbId] ? (
                                                                        <Loader2 className="w-2.5 h-2.5 animate-spin" />
                                                                    ) : expandedQuestId === quest.id ? (
                                                                        <ChevronUp className="w-2.5 h-2.5" />
                                                                    ) : (
                                                                        <ChevronDown className="w-2.5 h-2.5" />
                                                                    )}
                                                                    Prérequis
                                                                </button>
                                                            </div>
                                                        ) : (
                                                            <span className="text-[10px] text-amber-500 font-medium">Manuel</span>
                                                        )}
                                                    </div>
                                                </div>
                                                <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <DropdownMenu>
                                                        <DropdownMenuTrigger asChild>
                                                            <Button variant="ghost" size="icon" className="h-6 w-6 bg-slate-950/80 hover:bg-slate-800 text-slate-400">
                                                                <MoreHorizontal className="w-3 h-3" />
                                                            </Button>
                                                        </DropdownMenuTrigger>
                                                        <DropdownMenuContent align="end" className="bg-slate-900 border-slate-700">
                                                            <DropdownMenuItem onClick={() => startEdit(quest)} className="text-slate-300 focus:bg-slate-800 cursor-pointer">
                                                                <Edit2 className="w-3 h-3 mr-2 text-indigo-400" /> Modifier
                                                            </DropdownMenuItem>
                                                            <DropdownMenuItem onClick={() => handleDelete(quest.id)} className="text-red-400 focus:bg-red-950/30 cursor-pointer">
                                                                <Trash2 className="w-3 h-3 mr-2" /> Supprimer
                                                            </DropdownMenuItem>
                                                        </DropdownMenuContent>
                                                    </DropdownMenu>
                                                </div>
                                            </div>

                                            {/* Prerequisites Section */}
                                            {quest.dofusDbId && expandedQuestId === quest.id && (
                                                <div className="mt-2 pt-2 border-t border-slate-800/80 space-y-2.5 animate-fadeIn">
                                                    {loadingPrereqs[quest.dofusDbId] ? (
                                                        <div className="flex items-center justify-center py-4">
                                                            <Loader2 className="w-5 h-5 text-indigo-500 animate-spin" />
                                                        </div>
                                                    ) : loadedPrereqs[quest.dofusDbId] ? (
                                                        (() => {
                                                            const prereqs = loadedPrereqs[quest.dofusDbId];
                                                            const hasConditions = prereqs.conditions && prereqs.conditions.length > 0;
                                                            const hasQuests = prereqs.prerequisiteQuests && prereqs.prerequisiteQuests.length > 0;
                                                            const hasAchievements = prereqs.prerequisiteAchievements && prereqs.prerequisiteAchievements.length > 0;

                                                            if (!hasConditions && !hasQuests && !hasAchievements) {
                                                                return (
                                                                    <div className="text-[10px] text-slate-500 italic py-1">
                                                                        Aucun prérequis spécifique enregistré pour cette quête.
                                                                    </div>
                                                                );
                                                            }

                                                            return (
                                                                <div className="space-y-2 text-left">
                                                                    {hasConditions && (
                                                                        <div className="space-y-0.5">
                                                                            <span className="text-[9px] uppercase font-bold text-slate-500 tracking-wider">Conditions de départ</span>
                                                                            <ul className="space-y-0.5">
                                                                                {prereqs.conditions.map((cond: string, idx: number) => (
                                                                                    <li key={idx} className="text-[10px] text-slate-300 flex items-center gap-1">
                                                                                        <span className="w-1.5 h-1.5 rounded-full bg-emerald-500/85 shrink-0" />
                                                                                        <span>{cond}</span>
                                                                                    </li>
                                                                                ))}
                                                                            </ul>
                                                                        </div>
                                                                    )}

                                                                    {hasQuests && (
                                                                        <div className="space-y-1">
                                                                            <span className="text-[9px] uppercase font-bold text-slate-500 tracking-wider">Quêtes requises ({prereqs.prerequisiteQuests.length})</span>
                                                                            <div className="flex flex-wrap gap-1">
                                                                                {prereqs.prerequisiteQuests.map((pq: any) => (
                                                                                    <a
                                                                                        key={pq.id}
                                                                                        href={`https://dofusdb.fr/fr/database/quest/${pq.id}`}
                                                                                        target="_blank"
                                                                                        rel="noopener noreferrer"
                                                                                        className="text-[9px] px-1.5 py-0.5 bg-indigo-950/40 border border-indigo-900/60 text-indigo-300 rounded hover:bg-indigo-900/50 hover:text-indigo-200 transition-all flex items-center gap-1 max-w-full"
                                                                                    >
                                                                                        <BookOpen className="w-2.5 h-2.5 shrink-0 text-indigo-400" />
                                                                                        <span className="truncate">{pq.name}</span>
                                                                                    </a>
                                                                                ))}
                                                                            </div>
                                                                        </div>
                                                                    )}

                                                                    {hasAchievements && (
                                                                        <div className="space-y-1">
                                                                            <span className="text-[9px] uppercase font-bold text-slate-500 tracking-wider">Succès requis ({prereqs.prerequisiteAchievements.length})</span>
                                                                            <div className="flex flex-wrap gap-1">
                                                                                {prereqs.prerequisiteAchievements.map((pa: any) => (
                                                                                    <a
                                                                                        key={pa.id}
                                                                                        href={`https://dofusdb.fr/fr/database/achievement/${pa.id}`}
                                                                                        target="_blank"
                                                                                        rel="noopener noreferrer"
                                                                                        className="text-[9px] px-1.5 py-0.5 bg-amber-950/40 border border-amber-900/60 text-amber-300 rounded hover:bg-amber-900/50 hover:text-amber-200 transition-all flex items-center gap-1 max-w-full"
                                                                                    >
                                                                                        <Award className="w-2.5 h-2.5 shrink-0 text-amber-400" />
                                                                                        <span className="truncate">{pa.name}</span>
                                                                                    </a>
                                                                                ))}
                                                                            </div>
                                                                        </div>
                                                                    )}
                                                                </div>
                                                            );
                                                        })()
                                                    ) : null}
                                                </div>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}

            {/* Form Dialog */}
            <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
                <DialogContent className="w-[95vw] max-w-lg bg-slate-950 border-slate-800">
                    <DialogHeader>
                        <DialogTitle className="text-xl font-black text-white flex items-center gap-3">
                            <Map className="w-6 h-6 text-cyan-400" />
                            {editing ? "Modifier la quête" : "Nouvelle quête"}
                        </DialogTitle>
                        <DialogDescription className="text-slate-400">
                            Ajoutez une quête Dofus au catalogue de référence.
                        </DialogDescription>
                    </DialogHeader>
                    <form onSubmit={handleSubmit} className="space-y-4 pt-2">
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Nom *</label>
                            <Input
                                value={formData.name}
                                onChange={e => setFormData({ ...formData, name: e.target.value })}
                                required
                                placeholder="Ex: La Quête du Requin"
                                className="bg-slate-900 border-slate-700 text-white"
                            />
                        </div>
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Catégorie</label>
                            <select
                                value={formData.category}
                                onChange={e => setFormData({ ...formData, category: e.target.value })}
                                className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-sm text-white"
                            >
                                <option value="">-- Choisir --</option>
                                {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                            </select>
                        </div>
                        <div className="grid grid-cols-3 gap-3">
                            <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">ID DofusDB</label>
                                <Input
                                    type="number" min={1}
                                    value={formData.dofusDbId}
                                    onChange={e => setFormData({ ...formData, dofusDbId: e.target.value })}
                                    placeholder="1699"
                                    className="bg-slate-900 border-slate-700 text-white"
                                />
                            </div>
                            <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Niv. min</label>
                                <Input
                                    type="number" min={1}
                                    value={formData.levelMin}
                                    onChange={e => setFormData({ ...formData, levelMin: e.target.value })}
                                    placeholder="1"
                                    className="bg-slate-900 border-slate-700 text-white"
                                />
                            </div>
                            <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Niv. max</label>
                                <Input
                                    type="number" min={1}
                                    value={formData.levelMax}
                                    onChange={e => setFormData({ ...formData, levelMax: e.target.value })}
                                    placeholder="200"
                                    className="bg-slate-900 border-slate-700 text-white"
                                />
                            </div>
                        </div>
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Description</label>
                            <textarea
                                value={formData.description}
                                onChange={e => setFormData({ ...formData, description: e.target.value })}
                                rows={3}
                                placeholder="Description de la quête..."
                                className="w-full px-3 py-2 bg-slate-900 border border-slate-700 rounded-lg text-sm text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 resize-none"
                            />
                        </div>
                        <div className="flex gap-3 pt-2">
                            <Button type="submit" className="flex-1 bg-indigo-600 hover:bg-indigo-500 font-bold">
                                {editing ? "💾 Enregistrer" : "➕ Créer"}
                            </Button>
                            <Button type="button" variant="outline" onClick={() => setIsDialogOpen(false)}
                                className="border-slate-700 text-slate-300 hover:bg-slate-800">
                                Annuler
                            </Button>
                        </div>
                    </form>
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Loader2, Download, CheckCircle2, AlertCircle, Upload } from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { LocalImagePicker } from "./LocalImagePicker";

type Props = {
    imageUrl: string;
    type: "monster" | "achievement" | "dungeon" | "item" | "legendary";
    identifier: string;
    onImageDownloaded: (localPath: string) => void;
    className?: string;
};

type DownloadResult = {
    success: boolean;
    path?: string;
    error?: string;
    sizeReduction?: string;
};

export function ImageDownloader({ imageUrl, type, identifier, onImageDownloaded, className }: Props) {
    const [externalUrl, setExternalUrl] = useState("");
    const [selectedFile, setSelectedFile] = useState<File | null>(null);
    const [downloading, setDownloading] = useState(false);
    const [uploading, setUploading] = useState(false);
    const [lastResult, setLastResult] = useState<DownloadResult | null>(null);

    const handleDownload = async () => {
        if (!externalUrl.trim()) {
            toast.error("URL requise");
            return;
        }

        // Generate slug from identifier
        const slug = identifier.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

        if (!slug) {
            toast.error("Identifiant invalide");
            return;
        }

        setDownloading(true);
        setLastResult(null);

        try {
            const res = await fetch("/api/god/download-image", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    url: externalUrl,
                    type,
                    identifier: slug
                })
            });

            const data = await res.json();

            if (data.success) {
                setLastResult({
                    success: true,
                    path: data.localPath,
                    sizeReduction: data.sizeReduction
                });
                onImageDownloaded(data.localPath);
                toast.success(`Image téléchargée ! ${data.sizeReduction || ""}`);
            } else {
                setLastResult({ success: false, error: data.error });
                toast.error(data.error || "Échec du téléchargement");
            }
        } catch (error: any) {
            setLastResult({ success: false, error: error.message });
            toast.error("Erreur réseau");
        } finally {
            setDownloading(false);
        }
    };

    const handleUpload = async () => {
        if (!selectedFile) {
            toast.error("Veuillez sélectionner un fichier");
            return;
        }

        const slug = identifier.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
        if (!slug) {
            toast.error("Identifiant invalide");
            return;
        }

        setUploading(true);
        setLastResult(null);

        try {
            const formData = new FormData();
            formData.append("file", selectedFile);
            formData.append("type", type);
            formData.append("identifier", slug);

            const res = await fetch("/api/god/upload-image", {
                method: "POST",
                body: formData
            });

            const data = await res.json();

            if (data.success) {
                setLastResult({
                    success: true,
                    path: data.localPath,
                    sizeReduction: data.sizeReduction
                });
                onImageDownloaded(data.localPath);
                setSelectedFile(null);
                toast.success(`Image envoyée ! ${data.sizeReduction || ""}`);
            } else {
                setLastResult({ success: false, error: data.error });
                toast.error(data.error || "Échec de l'envoi");
            }
        } catch (error: any) {
            setLastResult({ success: false, error: error.message });
            toast.error("Erreur réseau");
        } finally {
            setUploading(false);
        }
    };

    // Map type to directory name for LocalImagePicker
    // const directory = type === "achievement" ? "achievements" : type === "dungeon" ? "dungeons" : "monsters";

    return (
        <div className={cn("space-y-3", className)}>
            <Label>Image</Label>

            <Tabs defaultValue="gallery" className="w-full">
                <TabsList className="flex flex-col sm:flex-row w-full bg-slate-800/50 p-1 h-auto gap-1">
                    <TabsTrigger value="gallery" className="flex-1 w-full sm:w-auto py-2.5 data-[state=active]:bg-indigo-600 font-bold transition-all whitespace-nowrap">
                        🖼️ Galerie
                    </TabsTrigger>
                    <TabsTrigger value="download" className="flex-1 w-full sm:w-auto py-2.5 data-[state=active]:bg-indigo-600 font-bold transition-all whitespace-nowrap">
                        🌐 Web (URL)
                    </TabsTrigger>
                    <TabsTrigger value="upload" className="flex-1 w-full sm:w-auto py-2.5 data-[state=active]:bg-indigo-600 font-bold transition-all whitespace-nowrap">
                        💻 Uploader
                    </TabsTrigger>
                </TabsList>

                <TabsContent value="gallery" className="space-y-3 mt-6">
                    <LocalImagePicker
                        type={type}
                        selected={imageUrl}
                        onImageSelect={(path) => {
                            onImageDownloaded(path);
                            toast.success("Image sélectionnée !");
                        }}
                        gridSize="small"
                        className="max-h-[400px]"
                    />
                </TabsContent>

                <TabsContent value="download" className="space-y-3 mt-4">
                    <div className="flex gap-2">
                        <Input
                            type="url"
                            placeholder="https://doflex.fr/s/monsters/png/..."
                            value={externalUrl}
                            onChange={(e) => setExternalUrl(e.target.value)}
                            className="flex-1 bg-slate-800/50 border-slate-600 text-white placeholder:text-slate-500"
                            disabled={downloading}
                        />
                        <Button
                            type="button"
                            onClick={handleDownload}
                            disabled={downloading || !externalUrl.trim() || !identifier.trim()}
                            className="bg-indigo-600 hover:bg-indigo-500"
                            size="sm"
                        >
                            {downloading ? (
                                <>
                                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                    Téléchargement...
                                </>
                            ) : (
                                <>
                                    <Download className="w-4 h-4 mr-2" />
                                    Télécharger
                                </>
                            )}
                        </Button>
                    </div>

                    {lastResult && (
                        <div className={cn(
                            "flex items-center gap-2 p-3 rounded-lg text-sm border",
                            lastResult.success
                                ? "bg-green-900/20 border-green-500/30 text-green-400"
                                : "bg-red-900/20 border-red-500/30 text-red-400"
                        )}>
                            {lastResult.success ? (
                                <>
                                    <CheckCircle2 className="w-4 h-4 flex-shrink-0" />
                                    <span className="flex-1 truncate">
                                        {lastResult.path}
                                    </span>
                                </>
                            ) : (
                                <>
                                    <AlertCircle className="w-4 h-4 flex-shrink-0" />
                                    <span>{lastResult.error}</span>
                                </>
                            )}
                        </div>
                    )}
                </TabsContent>

                <TabsContent value="upload" className="space-y-3 mt-4">
                    <div className="flex gap-2 items-center">
                        <Input
                            type="file"
                            accept="image/*"
                            onChange={(e) => setSelectedFile(e.target.files?.[0] || null)}
                            className="flex-1 bg-slate-800/50 border-slate-600 text-white cursor-pointer"
                            disabled={uploading}
                        />
                        <Button
                            type="button"
                            onClick={handleUpload}
                            disabled={uploading || !selectedFile || !identifier.trim()}
                            className="bg-indigo-600 hover:bg-indigo-500"
                            size="sm"
                        >
                            {uploading ? (
                                <>
                                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                    Envoi...
                                </>
                            ) : (
                                <>
                                    <Upload className="w-4 h-4 mr-2" />
                                    Uploader
                                </>
                            )}
                        </Button>
                    </div>

                    {lastResult && (
                        <div className={cn(
                            "flex items-center gap-2 p-3 rounded-lg text-sm border",
                            lastResult.success
                                ? "bg-green-900/20 border-green-500/30 text-green-400"
                                : "bg-red-900/20 border-red-500/30 text-red-400"
                        )}>
                            {lastResult.success ? (
                                <>
                                    <CheckCircle2 className="w-4 h-4 flex-shrink-0" />
                                    <span className="flex-1 truncate">
                                        {lastResult.path}
                                    </span>
                                </>
                            ) : (
                                <>
                                    <AlertCircle className="w-4 h-4 flex-shrink-0" />
                                    <span>{lastResult.error}</span>
                                </>
                            )}
                        </div>
                    )}
                </TabsContent>
            </Tabs>

            {/* Current Image Preview */}
            {imageUrl && (
                <div className="flex items-center gap-2 p-2 bg-slate-800/30 rounded border border-slate-700">
                    <img src={imageUrl} alt="Preview" className="w-8 h-8 rounded bg-slate-900 p-1" />
                    <code className="text-xs text-slate-400 flex-1 truncate">{imageUrl}</code>
                </div>
            )}
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    getLegendaryItems,
    createLegendaryItem,
    updateLegendaryItem,
    deleteLegendaryItem,
} from "@/server/actions/legendary-actions";
import {
    Sparkles, Trash2, Edit2, Plus, Search, MoreHorizontal, Hammer, Users
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { ImageDownloader } from "./ImageDownloader";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import Image from "next/image";

// Métiers pouvant créer des légendaires
const LEGENDARY_JOBS = [
    { id: "bijoutier",  name: "Bijoutier",   icon: "/assets/dofus/jobs/bijoutier.png" },
    { id: "cordonnier", name: "Cordonnier",  icon: "/assets/dofus/jobs/cordonnier.png" },
    { id: "faconneur",  name: "Façonneur",   icon: "/assets/dofus/jobs/façonneur.png" },
    { id: "sculpteur",  name: "Sculpteur",   icon: "/assets/dofus/jobs/sculpteur.png" },
    { id: "tailleur",   name: "Tailleur",    icon: "/assets/dofus/jobs/tailleur.png" },
];

const CATEGORIES = ["Chapeau", "Cape", "Bottes", "Ceinture", "Amulette", "Anneau", "Bouclier", "Arme"];

interface LegendaryItem {
    id: string;
    name: string;
    category: string;
    jobRequired: string;
    imageUrl?: string | null;
    _count?: { crafters: number };
}

export default function LegendaryManager() {
    const [items, setItems] = useState<LegendaryItem[]>([]);
    const [loading, setLoading] = useState(true);
    const [editing, setEditing] = useState<string | null>(null);
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");

    const [formData, setFormData] = useState({
        name: "",
        category: "Chapeau",
        jobRequired: "tailleur",
        imageUrl: "",
    });

    useEffect(() => { loadItems(); }, []);

    async function loadItems() {
        setLoading(true);
        const result = await getLegendaryItems();
        if (result.success && result.data) setItems(result.data as LegendaryItem[]);
        setLoading(false);
    }

    async function handleSubmit(e: React.FormEvent) {
        e.preventDefault();
        const result = editing
            ? await updateLegendaryItem(editing, formData)
            : await createLegendaryItem(formData);

        if (result.success) {
            toast.success(editing ? "Item mis à jour" : "Item créé");
            resetForm();
            setIsDialogOpen(false);
            loadItems();
        } else {
            toast.error(result.error || "Erreur");
        }
    }

    async function handleDelete(id: string) {
        if (!confirm("Supprimer cet objet légendaire ?")) return;
        const result = await deleteLegendaryItem(id);
        if (result.success) { toast.success("Item supprimé"); loadItems(); }
    }

    function resetForm() {
        setFormData({ name: "", category: "Chapeau", jobRequired: "tailleur", imageUrl: "" });
        setEditing(null);
    }

    function startEdit(item: LegendaryItem) {
        setEditing(item.id);
        setFormData({
            name: item.name,
            category: item.category,
            jobRequired: item.jobRequired,
            imageUrl: item.imageUrl || "",
        });
        setIsDialogOpen(true);
    }

    const filtered = items.filter(i =>
        i.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        i.category.toLowerCase().includes(searchQuery.toLowerCase()) ||
        i.jobRequired.toLowerCase().includes(searchQuery.toLowerCase())
    );

    const selectedJob = LEGENDARY_JOBS.find(j => j.id === formData.jobRequired);

    return (
        <div className="space-y-4">
            {/* Toolbar */}
            <div className="flex flex-col md:flex-row items-center gap-4 bg-slate-900/50 p-4 rounded-lg border border-slate-700/50 backdrop-blur-sm">
                <div className="relative flex-1 w-full">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <Input
                        placeholder="Rechercher un objet légendaire..."
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        className="pl-9 bg-slate-800 border-slate-700 text-slate-200 placeholder:text-slate-500"
                    />
                </div>
                <Button
                    onClick={() => { resetForm(); setIsDialogOpen(true); }}
                    className="w-full md:w-auto bg-purple-600 hover:bg-purple-700 shadow-lg shadow-purple-900/20"
                >
                    <Plus className="w-4 h-4 mr-2" />
                    Nouvel Objet
                </Button>
            </div>

            {/* Stats bar */}
            <div className="flex items-center gap-4 text-xs text-slate-500 px-1">
                <span className="font-mono">{items.length} objets légendaires</span>
                <span>·</span>
                <span>{items.reduce((acc, i) => acc + (i._count?.crafters ?? 0), 0)} artisans déclarés au total</span>
            </div>

            {/* Grid */}
            {loading ? (
                <div className="p-12 text-center text-slate-400 animate-pulse">Chargement...</div>
            ) : filtered.length === 0 ? (
                <div className="p-12 text-center text-slate-500 bg-slate-900/30 rounded-lg border border-dashed border-slate-700">
                    Aucun objet légendaire trouvé
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                    {filtered.map((item) => {
                        const job = LEGENDARY_JOBS.find(j => j.id === item.jobRequired);
                        return (
                            <div
                                key={item.id}
                                className="group relative bg-slate-900/40 border border-slate-800 rounded-xl p-4 hover:border-purple-500/30 hover:shadow-lg hover:shadow-purple-900/10 transition-all duration-300"
                            >
                                {/* Actions */}
                                <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity z-10">
                                    <DropdownMenu>
                                        <DropdownMenuTrigger asChild>
                                            <Button variant="ghost" size="icon" className="h-6 w-6 bg-slate-950/80 hover:bg-slate-800 text-slate-400">
                                                <MoreHorizontal className="w-3 h-3" />
                                            </Button>
                                        </DropdownMenuTrigger>
                                        <DropdownMenuContent align="end" className="bg-slate-900 border-slate-700">
                                            <DropdownMenuItem onClick={() => startEdit(item)} className="text-slate-300 focus:bg-slate-800 cursor-pointer">
                                                <Edit2 className="w-3 h-3 mr-2 text-purple-400" /> Modifier
                                            </DropdownMenuItem>
                                            <DropdownMenuItem onClick={() => handleDelete(item.id)} className="text-red-400 focus:bg-red-950/30 cursor-pointer">
                                                <Trash2 className="w-3 h-3 mr-2" /> Supprimer
                                            </DropdownMenuItem>
                                        </DropdownMenuContent>
                                    </DropdownMenu>
                                </div>

                                <div className="flex items-center gap-4">
                                    {/* Image */}
                                    <div className="w-14 h-14 rounded-xl bg-slate-800 border border-slate-700 flex items-center justify-center shrink-0 overflow-hidden p-1.5 group-hover:border-purple-500/50 transition-colors">
                                        {item.imageUrl ? (
                                            <Image src={item.imageUrl} alt={item.name} width={48} height={48} className="object-contain" />
                                        ) : (
                                            <Sparkles className="w-7 h-7 text-slate-600" />
                                        )}
                                    </div>

                                    {/* Info */}
                                    <div className="flex-1 min-w-0 space-y-1.5">
                                        <h4 className="font-bold text-slate-200 text-sm truncate leading-none" title={item.name}>
                                            {item.name}
                                        </h4>
                                        <div className="flex items-center gap-1.5 flex-wrap">
                                            <Badge variant="outline" className="text-[9px] px-1.5 py-0 border-slate-700 text-slate-400 bg-slate-800/50">
                                                {item.category}
                                            </Badge>
                                        </div>
                                        <div className="flex items-center gap-2 text-[10px] text-slate-500">
                                            {job && (
                                                <div className="flex items-center gap-1">
                                                    <div className="relative w-3.5 h-3.5">
                                                        <Image src={job.icon} alt={job.name} fill className="object-contain" />
                                                    </div>
                                                    <span className="font-bold">{job.name}</span>
                                                </div>
                                            )}
                                            {item._count && (
                                                <div className="flex items-center gap-1 ml-auto text-purple-400/70">
                                                    <Users className="w-3 h-3" />
                                                    <span>{item._count.crafters}</span>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}

            {/* Edit / Create Dialog */}
            <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
                <DialogContent className="w-[95vw] max-w-4xl bg-slate-950 border-slate-800 p-0 overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
                    <div className="p-6 bg-slate-900/50 border-b border-slate-800 shrink-0">
                        <DialogHeader>
                            <DialogTitle className="text-2xl font-black text-white flex items-center gap-3">
                                <Sparkles className="w-6 h-6 text-purple-400" />
                                {editing ? "Modifier l'objet légendaire" : "Nouvel Objet Légendaire"}
                            </DialogTitle>
                            <DialogDescription className="text-slate-400">
                                Configurez le nom, la catégorie, le métier requis et l'icône.
                            </DialogDescription>
                        </DialogHeader>
                    </div>

                    <div className="p-6 overflow-y-auto flex-1">
                        <form onSubmit={handleSubmit} className="space-y-6">
                            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                                {/* Left: Info */}
                                <div className="space-y-5 bg-slate-900/30 p-5 rounded-2xl border border-slate-800/50">
                                    <h3 className="text-xs font-black text-purple-400 uppercase tracking-widest border-b border-slate-800 pb-3">
                                        Informations
                                    </h3>

                                    {/* Name */}
                                    <div className="space-y-2">
                                        <label className="text-xs font-black text-slate-500 uppercase tracking-widest">
                                            Nom <span className="text-rose-500">*</span>
                                        </label>
                                        <Input
                                            value={formData.name}
                                            onChange={e => setFormData({ ...formData, name: e.target.value })}
                                            required
                                            placeholder="Ex: Noblesse de Jahash Jurgen"
                                            className="bg-slate-950 border-slate-800 focus:border-purple-500/50 text-white"
                                        />
                                    </div>

                                    {/* Category */}
                                    <div className="space-y-2">
                                        <label className="text-xs font-black text-slate-500 uppercase tracking-widest">
                                            Catégorie <span className="text-rose-500">*</span>
                                        </label>
                                        <div className="grid grid-cols-4 gap-2">
                                            {CATEGORIES.map(cat => (
                                                <button
                                                    key={cat}
                                                    type="button"
                                                    onClick={() => setFormData({ ...formData, category: cat })}
                                                    className={cn(
                                                        "px-2 py-2 rounded-lg text-[11px] font-bold uppercase tracking-wide border transition-all",
                                                        formData.category === cat
                                                            ? "bg-purple-600 border-purple-500 text-white shadow-lg shadow-purple-900/30"
                                                            : "bg-slate-900 border-slate-700 text-slate-400 hover:border-slate-600 hover:text-slate-200"
                                                    )}
                                                >
                                                    {cat}
                                                </button>
                                            ))}
                                        </div>
                                    </div>

                                    {/* Job Required */}
                                    <div className="space-y-2">
                                        <label className="text-xs font-black text-slate-500 uppercase tracking-widest">
                                            Métier Requis (niveau 200) <span className="text-rose-500">*</span>
                                        </label>
                                        <div className="grid grid-cols-5 gap-2">
                                            {LEGENDARY_JOBS.map(job => (
                                                <button
                                                    key={job.id}
                                                    type="button"
                                                    onClick={() => setFormData({ ...formData, jobRequired: job.id })}
                                                    className={cn(
                                                        "flex flex-col items-center gap-1.5 p-2.5 rounded-xl border transition-all",
                                                        formData.jobRequired === job.id
                                                            ? "bg-purple-600/20 border-purple-500/60 text-purple-200 shadow-lg shadow-purple-900/20"
                                                            : "bg-slate-900 border-slate-700 text-slate-400 hover:border-slate-600 hover:text-slate-200"
                                                    )}
                                                >
                                                    <div className="relative w-8 h-8">
                                                        <Image src={job.icon} alt={job.name} fill className="object-contain" />
                                                    </div>
                                                    <span className="text-[9px] font-black uppercase tracking-tight leading-none text-center">
                                                        {job.name}
                                                    </span>
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                </div>

                                {/* Right: Image */}
                                <div className="bg-slate-950/50 p-5 rounded-2xl border border-slate-800">
                                    <h3 className="text-xs font-black text-purple-400 uppercase tracking-widest border-b border-slate-800 pb-3 mb-4">
                                        Icône de l'Objet
                                    </h3>
                                    <ImageDownloader
                                        type="legendary"
                                        imageUrl={formData.imageUrl}
                                        identifier={formData.name || "legendary-item"}
                                        onImageDownloaded={(path) => setFormData({ ...formData, imageUrl: path })}
                                        className="w-full"
                                    />
                                </div>
                            </div>

                            {/* Actions */}
                            <div className="flex gap-3 pt-4 border-t border-slate-800">
                                <Button
                                    type="submit"
                                    className="flex-[3] bg-purple-600 hover:bg-purple-500 h-12 font-black uppercase tracking-widest shadow-xl shadow-purple-600/20 rounded-xl"
                                >
                                    {editing ? "💾 Enregistrer" : "✨ Créer l'Objet"}
                                </Button>
                                <Button
                                    type="button"
                                    variant="outline"
                                    onClick={() => { setIsDialogOpen(false); resetForm(); }}
                                    className="flex-1 h-12 border-white/10 hover:bg-white/5 text-slate-300 font-bold uppercase tracking-widest rounded-xl"
                                >
                                    Annuler
                                </Button>
                            </div>
                        </form>
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Loader2 } from "lucide-react";
import Image from "next/image";
import { cn } from "@/lib/utils";

interface LocalImage {
    filename: string;
    path: string;
    name: string;
}

interface LocalImagePickerProps {
    type: "monster" | "achievement" | "dungeon" | "item" | "legendary";
    selected?: string;
    onImageSelect: (path: string) => void;
    gridSize?: "small" | "medium" | "large";
    className?: string;
}

export function LocalImagePicker({ type, selected, onImageSelect, gridSize = "medium", className = "" }: LocalImagePickerProps) {
    const [images, setImages] = useState<LocalImage[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    // Map gridSize to grid columns
    const gridCols = gridSize === "small" ? "grid-cols-6" : gridSize === "large" ? "grid-cols-3" : "grid-cols-4";

    useEffect(() => {
        loadImages();
    }, [type]);

    async function loadImages() {
        setLoading(true);
        setError(null);

        try {
            const res = await fetch(`/api/god/list-local-images?type=${type}`);
            const data = await res.json();

            if (data.success) {
                setImages(data.images || []);
            } else {
                setError(data.error || "Erreur de chargement");
            }
        } catch (err: any) {
            setError(err.message || "Erreur réseau");
        } finally {
            setLoading(false);
        }
    }

    if (loading) {
        return (
            <div className="flex items-center justify-center p-8">
                <Loader2 className="w-6 h-6 animate-spin text-indigo-400" />
            </div>
        );
    }

    if (error) {
        return (
            <div className="p-4 bg-red-900/20 border border-red-500/30 rounded-lg text-red-400 text-sm">
                ⚠️ {error}
            </div>
        );
    }

    if (images.length === 0) {
        return (
            <div className="p-8 text-center text-slate-400 text-sm">
                Aucune image trouvée dans <code className="text-xs bg-slate-800 px-2 py-1 rounded">/game-data/{type}s/</code>
            </div>
        );
    }

    return (
        <div className="space-y-3">
            <p className="text-xs text-slate-400">
                {images.length} image{images.length > 1 ? "s" : ""} disponible{images.length > 1 ? "s" : ""}
            </p>
            <div className={cn(
                "grid gap-2 overflow-y-auto p-2 scrollbar-thin scrollbar-thumb-slate-700/50 scrollbar-track-transparent bg-slate-900/50 rounded-xl border border-slate-800 shadow-inner",
                gridCols,
                className
            )}>
                {images.map((img) => (
                    <button
                        key={img.path}
                        type="button"
                        onClick={() => onImageSelect(img.path)}
                        className={`
                            relative aspect-square rounded-lg overflow-hidden border-2 transition-all
                            hover:scale-105 hover:shadow-lg group
                            ${selected === img.path
                                ? "border-indigo-500 ring-2 ring-indigo-500/50"
                                : "border-slate-700/50 hover:border-indigo-400"
                            }
                        `}
                    >
                        <Image
                            src={img.path}
                            alt={img.name}
                            fill
                            className="object-contain bg-slate-950/50 p-0.5"
                        />
                        <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity">
                            <div className="absolute bottom-0 left-0 right-0 p-1">
                                <p className="text-[7px] text-white font-medium truncate leading-tight">
                                    {img.name}
                                </p>
                            </div>
                        </div>
                        {selected === img.path && (
                            <div className="absolute top-1 right-1 bg-indigo-500 text-white rounded-full p-0.5 shadow-lg">
                                <svg className="w-2.5 h-2.5" fill="currentColor" viewBox="0 0 20 20">
                                    <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                                </svg>
                            </div>
                        )}
                    </button>
                ))}
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import { motion } from "framer-motion";
import {
    getMonsterFamilies,
    createMonsterFamily,
    updateMonsterFamily,
    deleteMonsterFamily,
    getAdminZones,
} from "@/server/actions/game-data-admin-actions";
import { Search, Plus, MoreHorizontal, Edit2, Trash2, MapPin, ImageIcon } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { ImageDownloader } from "./ImageDownloader";
import { MultiSelect } from "@/components/ui/multi-select";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue
} from "@/components/ui/select";

interface MonsterFamily {
    id: string;
    name: string;
    level?: number | null;
    description?: string | null;
    imageUrl?: string | null;
    _count?: { monsters: number };
    zones?: { id: string; name: string }[];
}

export default function MonsterFamilyManager() {
    const [families, setFamilies] = useState<MonsterFamily[]>([]);
    const [zones, setZones] = useState<{ id: string; name: string }[]>([]);
    const [loading, setLoading] = useState(true);
    const [editing, setEditing] = useState<string | null>(null);
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");
    const [selectedZone, setSelectedZone] = useState<string>("all");
    const [selectedLevel, setSelectedLevel] = useState<string>("all");

    const [formData, setFormData] = useState({
        name: "",
        level: undefined as number | undefined,
        description: "",
        imageUrl: "",
        zoneIds: [] as string[],
    });

    useEffect(() => {
        loadData();
    }, []);

    async function loadData() {
        // loadData is now just for initial auxiliary data like zones
        const zonesRes = await getAdminZones();
        if (zonesRes.success && zonesRes.data) {
            setZones(zonesRes.data);
        }
    }

    useEffect(() => {
        loadFamilies();
    }, [selectedZone, selectedLevel]);

    async function loadFamilies() {
        setLoading(true);
        const filters: any = {};
        if (selectedZone !== "all") filters.zoneId = selectedZone;
        
        if (selectedLevel !== "all") {
            if (selectedLevel === "200") {
                filters.minLevel = 200;
                filters.maxLevel = 1000;
            } else {
                const [min, max] = selectedLevel.split("-").map(Number);
                if (!isNaN(min)) filters.minLevel = min;
                if (!isNaN(max)) filters.maxLevel = max;
            }
        }
        
        try {
            const result = await getMonsterFamilies(filters);
            if (result.success && result.data) {
                setFamilies(result.data);
                if (selectedLevel !== "all" || selectedZone !== "all") {
                   toast.info(`${result.data.length} familles trouvées avec ces filtres`);
                }
            } else {
                toast.error(result.error || "Erreur de filtrage");
            }
        } catch (e) {
            toast.error("Erreur réseau ou serveur");
        } finally {
            setLoading(false);
        }
    }

    async function handleSubmit(e: React.FormEvent) {
        e.preventDefault();

        const result = editing
            ? await updateMonsterFamily(editing, formData)
            : await createMonsterFamily(formData);

        if (result.success) {
            toast.success(editing ? "Famille mise à jour" : "Famille créée");
            resetForm();
            setIsDialogOpen(false);
            loadFamilies();
        } else {
            toast.error(result.error || "Erreur");
        }
    }

    async function handleDelete(id: string) {
        if (!confirm("Êtes-vous sûr de supprimer cette famille ?")) return;

        const result = await deleteMonsterFamily(id);
        if (result.success) {
            toast.success("Famille supprimée");
            loadFamilies();
        } else {
            toast.error(result.error || "Erreur de suppression");
        }
    }

    function resetForm() {
        setFormData({ name: "", level: undefined, description: "", imageUrl: "", zoneIds: [] });
        setEditing(null);
    }

    function startEdit(family: MonsterFamily) {
        setEditing(family.id);
        setFormData({
            name: family.name,
            level: family.level ?? undefined,
            description: family.description || "",
            imageUrl: family.imageUrl || "",
            zoneIds: family.zones?.map(z => z.id) || [],
        });
        setIsDialogOpen(true);
    }

    const zoneOptions = zones.map(z => ({
        label: z.name,
        value: z.id,
    }));

    const filteredFamilies = families.filter(f =>
        f.name.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return (
        <div className="space-y-4">
            {/* Toolbar */}
            <div className="flex flex-col md:flex-row items-center gap-4 bg-slate-900/50 p-4 rounded-lg border border-slate-700/50 backdrop-blur-sm">
                <div className="relative flex-1 w-full">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <Input
                        placeholder="Rechercher une famille..."
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        className="pl-9 bg-slate-800 border-slate-700 text-slate-200 placeholder:text-slate-500 focus:ring-indigo-500/50"
                    />
                </div>

                {/* Zone Filter */}
                <div className="w-full md:w-64">
                    <Select value={selectedZone} onValueChange={setSelectedZone}>
                        <SelectTrigger className="bg-slate-800 border-slate-700 text-slate-200">
                            <SelectValue placeholder="Filtrer par zone" />
                        </SelectTrigger>
                        <SelectContent className="bg-slate-900 border-slate-700">
                            <SelectItem value="all">Toutes les zones</SelectItem>
                            {zones.map(zone => (
                                <SelectItem key={zone.id} value={zone.id}>
                                    {zone.name}
                                </SelectItem>
                            ))}
                        </SelectContent>
                    </Select>
                </div>

                {/* Level Filter */}
                <div className="w-full md:w-48">
                    <Select value={selectedLevel} onValueChange={setSelectedLevel}>
                        <SelectTrigger className="bg-slate-800 border-slate-700 text-slate-200">
                            <SelectValue placeholder="Filtrer par niveau" />
                        </SelectTrigger>
                        <SelectContent className="bg-slate-900 border-slate-700">
                            <SelectItem value="all">Tous les niveaux</SelectItem>
                            <SelectItem value="1-50">Niveau 1 - 50</SelectItem>
                            <SelectItem value="51-100">Niveau 51 - 100</SelectItem>
                            <SelectItem value="101-150">Niveau 101 - 150</SelectItem>
                            <SelectItem value="151-199">Niveau 151 - 199</SelectItem>
                            <SelectItem value="200">Niveau 200</SelectItem>
                        </SelectContent>
                    </Select>
                </div>

                <Button
                    onClick={() => { resetForm(); setIsDialogOpen(true); }}
                    className="w-full md:w-auto bg-indigo-600 hover:bg-indigo-700 shadow-lg shadow-indigo-900/20 transition-all font-medium"
                >
                    <Plus className="w-4 h-4 mr-2" />
                    Nouvelle Famille
                </Button>
            </div>

            {/* Grid List */}
            {loading ? (
                <div className="p-12 text-center text-slate-400 animate-pulse">Chargement des familles...</div>
            ) : filteredFamilies.length === 0 ? (
                <div className="p-12 text-center text-slate-500 bg-slate-900/30 rounded-lg border border-dashed border-slate-700">
                    Aucune famille trouvée
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                    {filteredFamilies.map((family) => (
                        <div
                            key={family.id}
                            className="group relative bg-slate-900/40 border border-slate-800 rounded-xl overflow-hidden hover:border-indigo-500/30 hover:shadow-xl hover:shadow-indigo-900/10 transition-all duration-300"
                        >
                            <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity z-10">
                                <DropdownMenu>
                                    <DropdownMenuTrigger asChild>
                                        <Button variant="ghost" size="icon" className="h-8 w-8 bg-slate-950/50 hover:bg-slate-800 text-slate-400">
                                            <MoreHorizontal className="w-4 h-4" />
                                        </Button>
                                    </DropdownMenuTrigger>
                                    <DropdownMenuContent align="end" className="bg-slate-900 border-slate-700">
                                        <DropdownMenuItem onClick={() => startEdit(family)} className="text-slate-300 focus:bg-slate-800 cursor-pointer">
                                            <Edit2 className="w-4 h-4 mr-2 text-indigo-400" /> Modifier
                                        </DropdownMenuItem>
                                        <DropdownMenuItem onClick={() => handleDelete(family.id)} className="text-red-400 focus:bg-red-950/30 cursor-pointer">
                                            <Trash2 className="w-4 h-4 mr-2" /> Supprimer
                                        </DropdownMenuItem>
                                    </DropdownMenuContent>
                                </DropdownMenu>
                            </div>

                            <div className="p-4 flex gap-4">
                                <div className="relative w-16 h-16 rounded-lg overflow-hidden bg-slate-800 shrink-0 border border-slate-700 group-hover:border-indigo-500/50 transition-colors">
                                    {family.imageUrl ? (
                                        <img
                                            src={family.imageUrl}
                                            alt={family.name}
                                            className="w-full h-full object-cover"
                                        />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center text-slate-600">
                                            <ImageIcon className="w-8 h-8" />
                                        </div>
                                    )}
                                </div>

                                <div className="flex-1 min-w-0">
                                    <div className="flex items-center justify-between">
                                        <h3 className="font-bold text-slate-200 truncate group-hover:text-indigo-300 transition-colors">
                                            {family.name}
                                        </h3>
                                        {(family.level !== null && family.level !== undefined) ? (
                                            <Badge variant="outline" className="ml-2 border-indigo-500/30 text-indigo-400 font-bold bg-indigo-500/5">
                                                Lvl {family.level}
                                            </Badge>
                                        ) : (
                                            <Badge variant="outline" className="ml-2 border-slate-700 text-slate-500 font-medium bg-slate-800/50">
                                                Lvl ?
                                            </Badge>
                                        )}
                                    </div>
                                    <p className="text-xs text-slate-500 mt-0.5">
                                        {family._count?.monsters || 0} monstres
                                    </p>

                                    {family.zones && family.zones.length > 0 && (
                                        <div className="flex flex-wrap gap-1 mt-2">
                                            {family.zones.slice(0, 2).map(z => (
                                                <div key={z.id} className="text-[10px] px-1.5 py-0.5 rounded bg-slate-800 border border-slate-700 text-slate-400 flex items-center gap-1 max-w-full truncate">
                                                    <MapPin className="w-2.5 h-2.5 shrink-0" />
                                                    <span className="truncate">{z.name}</span>
                                                </div>
                                            ))}
                                            {family.zones.length > 2 && (
                                                <div className="text-[10px] px-1.5 py-0.5 rounded bg-slate-800 border border-slate-700 text-slate-500">
                                                    +{family.zones.length - 2}
                                                </div>
                                            )}
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Form Dialog */}
            <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
                <DialogContent draggable className="w-[95vw] max-w-7xl max-h-[95vh] bg-slate-950 border-slate-800 p-0 overflow-hidden shadow-2xl flex flex-col">
                    {/* Header Draggable */}
                    <div className="p-8 bg-slate-900/50 border-b border-slate-800 flex items-center justify-between shrink-0">
                        <DialogHeader>
                            <DialogTitle className="text-3xl font-black text-white flex items-center gap-4">
                                <Plus className="w-8 h-8 text-indigo-500" />
                                {editing ? "Modifier la famille" : "Nouvelle famille"}
                            </DialogTitle>
                            <DialogDescription className="text-slate-400 text-lg">
                                Gérez les familles de monstres, leurs descriptions et leurs zones de présence.
                            </DialogDescription>
                        </DialogHeader>
                    </div>

                    <div className="p-10 overflow-y-auto flex-1 custom-scrollbar">
                        <form onSubmit={handleSubmit} className="space-y-10 pb-6">
                            <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
                                {/* Left Column: Core Info */}
                                <div className="lg:col-span-7 space-y-10">
                                    <div className="space-y-8 bg-slate-900/30 p-8 rounded-3xl border border-slate-800/50">
                                        <h3 className="text-sm font-black text-indigo-400 uppercase tracking-[0.2em] border-b border-slate-800 pb-4 mb-2">Informations Principales</h3>

                                        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                                            <div className="md:col-span-3 space-y-3">
                                                <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Nom de la Famille <span className="text-rose-500 text-lg">*</span></label>
                                                <Input
                                                    value={formData.name}
                                                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                                    required
                                                    placeholder="Ex: Blops"
                                                    className="h-16 bg-slate-950 border-slate-800 focus:border-indigo-500/50 focus:ring-indigo-500/20 text-xl font-bold transition-all rounded-2xl"
                                                />
                                            </div>
                                            <div className="space-y-3">
                                                <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Lvl</label>
                                                <div className="relative">
                                                    <Input
                                                        type="number"
                                                        value={(formData.level === undefined || formData.level === null) ? "" : formData.level}
                                                        onChange={(e) => {
                                                            const val = e.target.value === "" ? undefined : parseInt(e.target.value);
                                                            setFormData({ ...formData, level: val });
                                                        }}
                                                        placeholder="Niveau..."
                                                        className="h-16 pl-12 bg-slate-950 border-slate-800 focus:border-indigo-500/50 focus:ring-indigo-500/20 text-xl font-bold transition-all rounded-2xl"
                                                    />
                                                    <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 font-bold">Lvl</span>
                                                </div>
                                            </div>
                                        </div>

                                        <div className="space-y-3">
                                            <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Description</label>
                                            <textarea
                                                value={formData.description || ""}
                                                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                                rows={4}
                                                className="w-full px-5 py-4 bg-slate-950 border border-slate-800 rounded-2xl text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500/50 resize-none text-lg transition-all"
                                                placeholder="Partagez l'histoire ou les caractéristiques de cette famille..."
                                            />
                                        </div>
                                    </div>

                                    <div className="bg-slate-950/50 p-8 rounded-3xl border border-slate-800 shadow-inner">
                                        <h3 className="text-sm font-black text-indigo-400 uppercase tracking-[0.2em] border-b border-slate-800 pb-4 mb-6">Illustration</h3>
                                        <ImageDownloader
                                            type="monster"
                                            imageUrl={formData.imageUrl}
                                            identifier={formData.name}
                                            onImageDownloaded={(path) => setFormData({ ...formData, imageUrl: path })}
                                            className="w-full"
                                        />
                                    </div>
                                </div>

                                {/* Right Column: Zones */}
                                <div className="lg:col-span-5 h-full">
                                    <div className="space-y-8 bg-slate-900/30 p-8 rounded-3xl border border-slate-800/50 h-full flex flex-col">
                                        <div className="flex items-center justify-between border-b border-slate-800 pb-4 mb-2">
                                            <h3 className="text-sm font-black text-indigo-400 uppercase tracking-[0.2em]">Zones de Présence</h3>
                                            <span className="bg-indigo-500/10 text-indigo-400 text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-widest border border-indigo-500/20">
                                                {formData.zoneIds.length} sélectionnée(s)
                                            </span>
                                        </div>

                                        <div className="flex-1 overflow-visible">
                                            <MultiSelect
                                                options={zones.map(z => ({ label: z.name, value: z.id }))}
                                                selected={formData.zoneIds}
                                                onChange={(val) => setFormData({ ...formData, zoneIds: val })}
                                                placeholder="Sélectionner les zones..."
                                            />
                                            <p className="mt-4 text-[11px] text-slate-500 leading-relaxed font-medium italic">
                                                ⚠️ Les monstres de cette famille apparaîtront automatiquement dans les zones sélectionnées.
                                            </p>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="flex gap-4 pt-6 border-t border-slate-800 shrink-0 sticky bottom-0 bg-slate-950 py-4">
                                <Button type="submit" className="flex-[3] bg-indigo-600 hover:bg-indigo-500 h-14 text-lg font-black uppercase tracking-widest shadow-xl shadow-indigo-600/20 transition-all rounded-xl active:scale-[0.98]">
                                    {editing ? "💾 Enregistrer" : "➕ Créer la Famille"}
                                </Button>
                                <Button
                                    type="button"
                                    variant="outline"
                                    onClick={() => setIsDialogOpen(false)}
                                    className="flex-1 h-14 border-white/10 hover:bg-white/5 text-slate-300 text-sm font-bold uppercase tracking-widest transition-all rounded-xl"
                                >
                                    Fermer
                                </Button>
                            </div>
                        </form>
                    </div>
                </DialogContent>
            </Dialog>

        </div>
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { 
    RefreshCw, 
    CheckSquare, 
    Square, 
    ArrowRight, 
    Loader2, 
    CheckCircle2, 
    AlertTriangle,
    Database,
    Sparkles,
    ShieldAlert
} from "lucide-react";
import { checkDofusDbDeltas, syncDeltas, type QuestDelta } from "@/server/actions/game-quest-sync-actions";
import { Badge } from "@/components/ui/badge";

export default function QuestSyncPanel() {
    const [loading, setLoading] = useState(false);
    const [syncing, setSyncing] = useState(false);
    const [checked, setChecked] = useState(false);
    const [stats, setStats] = useState<{
        totalLocal: number;
        totalRemote: number;
        deltas: QuestDelta[];
    } | null>(null);
    const [selectedIds, setSelectedIds] = useState<number[]>([]);

    async function handleCheckDeltas() {
        setLoading(true);
        try {
            // Passing empty string so it falls back to the default guild config / super admin bypass
            const res = await checkDofusDbDeltas("");
            if (res.success && res.data) {
                setStats(res.data);
                setChecked(true);
                // Pre-select all deltas
                setSelectedIds(res.data.deltas.map(d => d.dofusDbId));
                toast.success("Analyse des modifications DofusDB terminée !");
            } else {
                toast.error(res.error || "Erreur lors de la vérification");
            }
        } catch (e: any) {
            toast.error(e.message || "Erreur de connexion");
        } finally {
            setLoading(false);
        }
    }

    async function handleSync() {
        if (selectedIds.length === 0) {
            toast.error("Veuillez sélectionner au moins une quête à synchroniser.");
            return;
        }

        setSyncing(true);
        try {
            const res = await syncDeltas("", selectedIds);
            if (res.success) {
                toast.success(`${res.count} quêtes synchronisées avec succès !`);
                // Re-run checking to clear synced deltas
                await handleCheckDeltas();
            } else {
                toast.error(res.error || "Erreur lors de la synchronisation");
            }
        } catch (e: any) {
            toast.error(e.message || "Erreur de connexion");
        } finally {
            setSyncing(false);
        }
    }

    function toggleSelectAll() {
        if (!stats) return;
        if (selectedIds.length === stats.deltas.length) {
            setSelectedIds([]);
        } else {
            setSelectedIds(stats.deltas.map(d => d.dofusDbId));
        }
    }

    function toggleSelect(id: number) {
        setSelectedIds(prev => 
            prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
        );
    }

    return (
        <div className="bg-slate-950/40 border border-slate-800 rounded-2xl p-6 backdrop-blur-md space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-800 pb-4">
                <div className="space-y-1">
                    <h3 className="text-lg font-bold text-white flex items-center gap-2">
                        <Database className="w-5 h-5 text-indigo-400" />
                        Synchronisation DofusDB Quêtes
                    </h3>
                    <p className="text-xs text-slate-400">
                        Détectez et synchronisez en temps réel les nouveautés et les modifications de DofusDB.
                    </p>
                </div>
                <div className="flex items-center gap-2">
                    <Button
                        onClick={handleCheckDeltas}
                        disabled={loading || syncing}
                        variant="outline"
                        className="border-indigo-500/20 text-indigo-300 hover:bg-indigo-500/10 font-semibold"
                    >
                        {loading ? (
                            <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                        ) : (
                            <RefreshCw className="w-4 h-4 mr-2" />
                        )}
                        Vérifier les modifications
                    </Button>
                </div>
            </div>

            {stats && (
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    <div className="bg-slate-900/50 border border-slate-800/80 p-4 rounded-xl space-y-1">
                        <div className="text-[10px] uppercase font-black tracking-widest text-slate-500">Quêtes Locales</div>
                        <div className="text-2xl font-black text-white">{stats.totalLocal}</div>
                    </div>
                    <div className="bg-slate-900/50 border border-slate-800/80 p-4 rounded-xl space-y-1">
                        <div className="text-[10px] uppercase font-black tracking-widest text-slate-500">DofusDB Remote</div>
                        <div className="text-2xl font-black text-indigo-400">{stats.totalRemote}</div>
                    </div>
                    <div className="bg-slate-900/50 border border-slate-800/80 p-4 rounded-xl space-y-1">
                        <div className="text-[10px] uppercase font-black tracking-widest text-slate-500">Nouveautés détectées</div>
                        <div className="text-2xl font-black text-emerald-400">
                            {stats.deltas.filter(d => d.type === "NEW").length}
                        </div>
                    </div>
                    <div className="bg-slate-900/50 border border-slate-800/80 p-4 rounded-xl space-y-1">
                        <div className="text-[10px] uppercase font-black tracking-widest text-slate-500">Modifications</div>
                        <div className="text-2xl font-black text-amber-400">
                            {stats.deltas.filter(d => d.type === "MODIFIED").length}
                        </div>
                    </div>
                </div>
            )}

            {checked && stats && stats.deltas.length === 0 && (
                <div className="flex flex-col items-center justify-center py-12 px-4 border border-dashed border-emerald-500/20 rounded-xl bg-emerald-500/5 text-center space-y-3">
                    <CheckCircle2 className="w-12 h-12 text-emerald-400" />
                    <div className="space-y-1">
                        <h4 className="font-bold text-white text-base">Base de données à jour !</h4>
                        <p className="text-xs text-slate-400 max-w-sm">
                            Toutes les quêtes locales correspondent à 100% avec les données de DofusDB.
                        </p>
                    </div>
                </div>
            )}

            {checked && stats && stats.deltas.length > 0 && (
                <div className="space-y-4">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                            <Button
                                size="sm"
                                variant="ghost"
                                onClick={toggleSelectAll}
                                className="text-xs font-semibold text-slate-400 hover:text-white flex items-center gap-1.5 p-0 hover:bg-transparent"
                            >
                                {selectedIds.length === stats.deltas.length ? (
                                    <CheckSquare className="w-4 h-4 text-indigo-400" />
                                ) : (
                                    <Square className="w-4 h-4" />
                                )}
                                {selectedIds.length === stats.deltas.length ? "Tout désélectionner" : "Tout sélectionner"}
                            </Button>
                            <span className="text-xs text-slate-500">
                                ({selectedIds.length} sélectionnée{selectedIds.length > 1 ? "s" : ""})
                            </span>
                        </div>
                        <Button
                            onClick={handleSync}
                            disabled={syncing || selectedIds.length === 0}
                            size="sm"
                            className="bg-indigo-600 hover:bg-indigo-500 text-white font-bold"
                        >
                            {syncing ? (
                                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                            ) : (
                                <Sparkles className="w-4 h-4 mr-2" />
                            )}
                            Synchroniser la sélection
                        </Button>
                    </div>

                    <div className="max-h-[350px] overflow-y-auto border border-slate-800 rounded-xl divide-y divide-slate-800 bg-slate-950/20 pr-1">
                        {stats.deltas.map(delta => {
                            const isSelected = selectedIds.includes(delta.dofusDbId);
                            const isNew = delta.type === "NEW";

                            return (
                                <div
                                    key={delta.dofusDbId}
                                    onClick={() => toggleSelect(delta.dofusDbId)}
                                    className={`flex items-center gap-4 p-3 hover:bg-slate-900/30 transition-colors cursor-pointer ${
                                        isSelected ? "bg-indigo-500/5" : ""
                                    }`}
                                >
                                    <div className="shrink-0 text-slate-500 hover:text-indigo-400 transition-colors">
                                        {isSelected ? (
                                            <CheckSquare className="w-4 h-4 text-indigo-400" />
                                        ) : (
                                            <Square className="w-4 h-4" />
                                        )}
                                    </div>
                                    
                                    <div className="flex-1 min-w-0 space-y-0.5">
                                        <div className="flex items-center gap-2 flex-wrap">
                                            <span className="font-bold text-slate-200 text-sm truncate">
                                                {delta.name}
                                            </span>
                                            <Badge className="bg-slate-800 text-[10px] text-slate-400 border border-slate-700">
                                                ID: {delta.dofusDbId}
                                            </Badge>
                                            {delta.levelMin && (
                                                <Badge variant="outline" className="text-[10px] border-slate-800 text-slate-400">
                                                    Niv. {delta.levelMin}
                                                </Badge>
                                            )}
                                        </div>
                                        {!isNew && delta.localName && (
                                            <div className="flex items-center gap-2 text-xs text-amber-500/80">
                                                <AlertTriangle className="w-3 h-3 shrink-0" />
                                                <span className="truncate">Local: "{delta.localName}"</span>
                                                <ArrowRight className="w-3 h-3 shrink-0" />
                                                <span className="font-semibold text-slate-400">Restaurer</span>
                                            </div>
                                        )}
                                    </div>

                                    <div className="shrink-0">
                                        <Badge className={
                                            isNew 
                                                ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20" 
                                                : "bg-amber-500/10 text-amber-400 border border-amber-500/20"
                                        }>
                                            {isNew ? "Nouveau" : "Modifié"}
                                        </Badge>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    getAdminZones,
    createZone,
    updateZone,
    deleteZone,
} from "@/server/actions/game-data-admin-actions";
import { getMonsterFamilies, getDungeons } from "@/server/actions/game-data-actions";
import { MapPin, Trash2, Edit2, Plus, Search, MoreHorizontal } from "lucide-react";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { MultiSelect } from "@/components/ui/multi-select";
import { motion } from "framer-motion";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue
} from "@/components/ui/select";

interface Zone {
    id: string;
    name: string;
    level: number;
    families?: { id: string; name: string }[];
    dungeons?: { id: string; name: string }[];
}

export default function ZoneManager() {
    const [zones, setZones] = useState<Zone[]>([]);
    const [families, setFamilies] = useState<{ id: string; name: string }[]>([]);
    const [dungeons, setDungeons] = useState<{ id: string; name: string }[]>([]);
    const [loading, setLoading] = useState(true);
    const [editing, setEditing] = useState<string | null>(null);
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");
    const [selectedLevel, setSelectedLevel] = useState<string>("all");

    const [formData, setFormData] = useState({
        name: "",
        level: 200,
        familyIds: [] as string[],
        dungeonIds: [] as string[],
    });

    useEffect(() => {
        loadData();
    }, [selectedLevel]);

    async function loadData() {
        setLoading(true);

        const filters: any = {};
        if (selectedLevel !== "all") {
            if (selectedLevel === "200") {
                filters.minLevel = 200;
                filters.maxLevel = 1000;
            } else {
                const [min, max] = selectedLevel.split("-").map(Number);
                if (!isNaN(min)) filters.minLevel = min;
                if (!isNaN(max)) filters.maxLevel = max;
            }
        }

        const [zonesRes, familiesRes, dungeonsRes] = await Promise.all([
            getAdminZones(filters),
            getMonsterFamilies(),
            getDungeons()
        ]);

        if (zonesRes.success && zonesRes.data) {
            setZones(zonesRes.data);
            if (selectedLevel !== "all") {
                toast.info(`${zonesRes.data.length} zones trouvées`);
            }
        }
        if (familiesRes.success && familiesRes.data) {
            setFamilies(familiesRes.data);
        }
        if (dungeonsRes.success && dungeonsRes.data) {
            setDungeons(dungeonsRes.data);
        }
        setLoading(false);
    }

    async function handleSubmit(e: React.FormEvent) {
        e.preventDefault();
        const result = editing
            ? await updateZone(editing, formData)
            : await createZone(formData);

        if (result.success) {
            toast.success(editing ? "Zone mise à jour" : "Zone créée");
            resetForm();
            setIsDialogOpen(false);
            loadData();
        } else {
            toast.error(result.error || "Erreur");
        }
    }

    async function handleDelete(id: string) {
        if (!confirm("Supprimer cette zone ?")) return;
        const result = await deleteZone(id);
        if (result.success) {
            toast.success("Zone supprimée");
            loadData();
        }
    }

    function resetForm() {
        setFormData({ name: "", level: 200, familyIds: [], dungeonIds: [] });
        setEditing(null);
    }

    function startEdit(zone: Zone) {
        setEditing(zone.id);
        setFormData({
            name: zone.name,
            level: zone.level,
            familyIds: zone.families?.map(f => f.id) || [],
            dungeonIds: zone.dungeons?.map(d => d.id) || [],
        });
        setIsDialogOpen(true);
    }

    const filteredZones = zones.filter(z =>
        z.name.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return (
        <div className="space-y-4">
            {/* Toolbar */}
            <div className="flex flex-col md:flex-row items-center gap-4 bg-slate-900/50 p-4 rounded-lg border border-slate-700/50 backdrop-blur-sm">
                <div className="relative flex-1 w-full">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <Input
                        placeholder="Rechercher une zone..."
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        className="pl-9 bg-slate-800 border-slate-700 text-slate-200 placeholder:text-slate-500 focus:ring-indigo-500/50"
                    />
                </div>

                {/* Level Filter */}
                <div className="w-full md:w-48">
                    <Select value={selectedLevel} onValueChange={setSelectedLevel}>
                        <SelectTrigger className="bg-slate-800 border-slate-700 text-slate-200">
                            <SelectValue placeholder="Filtrer par niveau" />
                        </SelectTrigger>
                        <SelectContent className="bg-slate-900 border-slate-700">
                            <SelectItem value="all">Tous les niveaux</SelectItem>
                            <SelectItem value="1-50">Niveau 1 - 50</SelectItem>
                            <SelectItem value="51-100">Niveau 51 - 100</SelectItem>
                            <SelectItem value="101-150">Niveau 101 - 150</SelectItem>
                            <SelectItem value="151-199">Niveau 151 - 199</SelectItem>
                            <SelectItem value="200">Niveau 200</SelectItem>
                        </SelectContent>
                    </Select>
                </div>
                <Button
                    onClick={() => { resetForm(); setIsDialogOpen(true); }}
                    className="w-full md:w-auto bg-indigo-600 hover:bg-indigo-700 shadow-lg shadow-indigo-900/20 transition-all font-medium"
                >
                    <Plus className="w-4 h-4 mr-2" />
                    Nouvelle Zone
                </Button>
            </div>

            {/* Grid List */}
            {loading ? (
                <div className="p-12 text-center text-slate-400 animate-pulse">Chargement des zones...</div>
            ) : filteredZones.length === 0 ? (
                <div className="p-12 text-center text-slate-500 bg-slate-900/30 rounded-lg border border-dashed border-slate-700">
                    Aucune zone trouvée
                </div>
            ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                    {filteredZones.map((zone) => (
                        <div
                            key={zone.id}
                            className="group relative bg-slate-900/40 border border-slate-800 rounded-xl overflow-hidden hover:border-indigo-500/30 hover:shadow-lg hover:shadow-indigo-900/10 transition-all duration-300"
                        >
                            <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity z-10">
                                <DropdownMenu>
                                    <DropdownMenuTrigger asChild>
                                        <Button variant="ghost" size="icon" className="h-8 w-8 bg-slate-950/50 hover:bg-slate-800 text-slate-400">
                                            <MoreHorizontal className="w-4 h-4" />
                                        </Button>
                                    </DropdownMenuTrigger>
                                    <DropdownMenuContent align="end" className="bg-slate-900 border-slate-700">
                                        <DropdownMenuItem onClick={() => startEdit(zone)} className="text-slate-300 focus:bg-slate-800 cursor-pointer">
                                            <Edit2 className="w-4 h-4 mr-2 text-indigo-400" /> Modifier
                                        </DropdownMenuItem>
                                        <DropdownMenuItem onClick={() => handleDelete(zone.id)} className="text-red-400 focus:bg-red-950/30 cursor-pointer">
                                            <Trash2 className="w-4 h-4 mr-2" /> Supprimer
                                        </DropdownMenuItem>
                                    </DropdownMenuContent>
                                </DropdownMenu>
                            </div>

                            <div className="p-4 flex items-center gap-4">
                                <div className="w-10 h-10 rounded-lg bg-green-900/20 flex items-center justify-center border border-green-500/20 text-green-400 shrink-0">
                                    <MapPin className="w-5 h-5" />
                                </div>

                                <div className="flex-1 min-w-0">
                                    <h3 className="font-bold text-slate-200 truncate group-hover:text-green-300 transition-colors">
                                        {zone.name}
                                    </h3>
                                    <p className="text-xs text-slate-500 mt-0.5">
                                        Niveau {zone.level}
                                    </p>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
                <DialogContent draggable className="w-[95vw] max-w-6xl bg-slate-950 border-slate-800 p-0 overflow-hidden shadow-2xl flex flex-col">
                    {/* Header Draggable */}
                    <div className="p-8 bg-slate-900/50 border-b border-slate-800 flex items-center justify-between shrink-0">
                        <DialogHeader>
                            <DialogTitle className="text-3xl font-black text-white flex items-center gap-4">
                                <Plus className="w-8 h-8 text-indigo-500" />
                                {editing ? "Modifier la zone" : "Nouvelle zone"}
                            </DialogTitle>
                            <DialogDescription className="text-slate-400 text-lg">
                                Configurez les détails géographiques de la zone et son niveau recommandé.
                            </DialogDescription>
                        </DialogHeader>
                    </div>

                    <div className="p-10 overflow-y-auto flex-1 custom-scrollbar">
                        <form onSubmit={handleSubmit} className="space-y-10 pb-6">
                            <div className="space-y-8 bg-slate-900/30 p-8 rounded-3xl border border-slate-800/50">
                                <h3 className="text-sm font-black text-indigo-400 uppercase tracking-[0.2em] border-b border-slate-800 pb-4 mb-2">Informations de Zone</h3>

                                <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                                    <div className="md:col-span-3 space-y-3">
                                        <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Nom de la Zone <span className="text-rose-500 text-lg">*</span></label>
                                        <Input
                                            value={formData.name}
                                            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                            required
                                            placeholder="Ex: Pandala, Frigost, Saharach..."
                                            className="h-16 bg-slate-950 border-slate-800 focus:border-indigo-500/50 focus:ring-indigo-500/20 text-xl font-bold transition-all rounded-2xl"
                                        />
                                    </div>
                                    <div className="space-y-3">
                                        <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Niveau Max</label>
                                        <div className="relative">
                                            <Input
                                                type="number"
                                                value={formData.level || ""}
                                                onChange={(e) => setFormData({ ...formData, level: parseInt(e.target.value) || 0 })}
                                                placeholder="200"
                                                className="h-16 pl-12 bg-slate-950 border-slate-800 focus:border-indigo-500/50 focus:ring-indigo-500/20 text-xl font-bold transition-all rounded-2xl"
                                            />
                                            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 font-bold">Lvl</span>
                                        </div>
                                    </div>
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-6 border-t border-slate-800">
                                    <div className="space-y-3">
                                        <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Familles Associées</label>
                                        <div className="flex-1 overflow-visible">
                                            <MultiSelect
                                                options={families.map(f => ({ label: f.name, value: f.id }))}
                                                selected={formData.familyIds}
                                                onChange={(val) => setFormData({ ...formData, familyIds: val })}
                                                placeholder="Sélectionner les familles..."
                                            />
                                            <p className="mt-3 text-[11px] text-slate-500 leading-relaxed font-medium italic">
                                                Optionnel: lier des familles de monstres à cette zone.
                                            </p>
                                        </div>
                                    </div>
                                    <div className="space-y-3">
                                        <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-1">Donjons Associés</label>
                                        <div className="flex-1 overflow-visible">
                                            <MultiSelect
                                                options={dungeons.map(d => ({ label: d.name, value: d.id }))}
                                                selected={formData.dungeonIds}
                                                onChange={(val) => setFormData({ ...formData, dungeonIds: val })}
                                                placeholder="Sélectionner les donjons..."
                                            />
                                            <p className="mt-3 text-[11px] text-slate-500 leading-relaxed font-medium italic">
                                                Optionnel: lier des boss de donjon à cette zone.
                                            </p>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="flex gap-4 pt-6 border-t border-slate-800 shrink-0 sticky bottom-0 bg-slate-950 py-4">
                                <Button type="submit" className="flex-[3] bg-indigo-600 hover:bg-indigo-700 h-14 text-lg font-black uppercase tracking-widest shadow-xl shadow-indigo-600/20 transition-all rounded-xl active:scale-[0.98]">
                                    {editing ? "💾 Enregistrer" : "➕ Créer la Zone"}
                                </Button>
                                <Button
                                    type="button"
                                    variant="outline"
                                    onClick={() => setIsDialogOpen(false)}
                                    className="flex-1 h-14 border-white/10 hover:bg-white/5 text-slate-300 text-sm font-bold uppercase tracking-widest transition-all rounded-xl"
                                >
                                    Fermer
                                </Button>
                            </div>
                        </form>
                    </div>
                </DialogContent>
            </Dialog>


        </div>
    );
}

"use client";

import { useState, useTransition } from "react";
import Link from "next/link";
import { cn } from "@/lib/utils";
import { togglePinnedNavItem } from "@/server/actions/profile-actions";
import { toast } from "sonner";
import { 
    Star, 
    ArrowRight, 
    Settings, 
    Shield, 
    Hammer, 
    BookOpen, 
    Swords, 
    CheckCircle, 
    Users, 
    Gavel, 
    FileText,
    ShieldAlert,
    Puzzle,
    type LucideIcon 
} from "lucide-react";

interface AdminCardProps {
    href: string;
    iconName: string;
    title: string;
    description: string;
    accent: string;
    guildId: string;
    initialPinned: boolean;
    warningBadge?: string;
}

const ICONS: Record<string, LucideIcon> = {
    Settings,
    Shield,
    Hammer,
    BookOpen,
    Swords,
    CheckCircle,
    Users,
    Gavel,
    FileText,
    ShieldAlert,
    Puzzle
};

const ACCENT: Record<string, { border: string; hover: string; text: string; bg: string; shadow: string }> = {
    violet: { border: "border-violet-500/20", hover: "hover:border-violet-500/50", text: "text-violet-400", bg: "bg-violet-500/10", shadow: "shadow-violet-500/20" },
    blue: { border: "border-blue-500/20", hover: "hover:border-blue-500/50", text: "text-blue-400", bg: "bg-blue-500/10", shadow: "shadow-blue-500/20" },
    slate: { border: "border-slate-500/20", hover: "hover:border-slate-500/50", text: "text-slate-400", bg: "bg-slate-500/10", shadow: "shadow-slate-500/20" },
    indigo: { border: "border-indigo-500/20", hover: "hover:border-indigo-500/50", text: "text-indigo-400", bg: "bg-indigo-500/10", shadow: "shadow-indigo-500/20" },
    green: { border: "border-green-500/20", hover: "hover:border-green-500/50", text: "text-green-400", bg: "bg-green-500/10", shadow: "shadow-green-500/20" },
    emerald: { border: "border-emerald-500/20", hover: "hover:border-emerald-500/50", text: "text-emerald-400", bg: "bg-emerald-500/10", shadow: "shadow-emerald-500/20" },
    amber: { border: "border-amber-500/20", hover: "hover:border-amber-500/50", text: "text-amber-400", bg: "bg-amber-500/10", shadow: "shadow-amber-500/20" },
    rose: { border: "border-rose-500/20", hover: "hover:border-rose-500/50", text: "text-rose-400", bg: "bg-rose-500/10", shadow: "shadow-rose-500/20" },
    cyan: { border: "border-cyan-500/20", hover: "hover:border-cyan-500/50", text: "text-cyan-400", bg: "bg-cyan-500/10", shadow: "shadow-cyan-500/20" },
};

export function AdminCard({
    href,
    iconName,
    title,
    description,
    accent,
    guildId,
    initialPinned,
    warningBadge,
}: AdminCardProps) {
    const [isPinned, setIsPinned] = useState(initialPinned);
    const [isPending, startTransition] = useTransition();
    const a = ACCENT[accent] ?? ACCENT.slate;
    const Icon = ICONS[iconName] || Shield;

    const handleTogglePin = async (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();

        if (isPending) return;

        const newState = !isPinned;
        setIsPinned(newState);

        startTransition(async () => {
            try {
                const res = await togglePinnedNavItem({ guildId, href });
                if (!res.success) {
                    setIsPinned(!newState);
                    toast.error("Erreur lors du changement de favori");
                } else {
                    toast.success(newState ? "Ajouté aux favoris" : "Retiré des favoris", {
                        description: title,
                        icon: newState ? <Star className="w-4 h-4 text-amber-400 fill-amber-400" /> : undefined
                    });
                }
            } catch (err) {
                setIsPinned(!newState);
                toast.error("Erreur serveur");
            }
        });
    };

    return (
        <Link href={href} className="group outline-none relative block h-full">
            <div className={cn(
                "relative flex flex-col h-full rounded-[2.5rem] border border-white/5 bg-white/[0.02] p-8 transition-all duration-700 hover:bg-white/[0.04] hover:shadow-[0_40px_80px_-20px_rgba(0,0,0,0.6)] overflow-hidden",
                a.hover,
                "before:absolute before:inset-0 before:bg-gradient-to-br before:from-white/[0.05] before:to-transparent before:opacity-0 group-hover:before:opacity-100 before:transition-opacity before:duration-700"
            )}>
                {/* Favorite Toggle */}
                <button
                    onClick={handleTogglePin}
                    disabled={isPending}
                    className={cn(
                        "absolute top-6 right-6 z-20 p-2.5 rounded-xl border transition-all duration-500 hover:scale-110 active:scale-95",
                        isPinned 
                            ? "bg-amber-500/10 border-amber-500/30 text-amber-400 shadow-[0_0_15px_rgba(245,158,11,0.2)]" 
                            : "bg-white/5 border-white/10 text-white/20 hover:text-white/60 hover:bg-white/10 hover:border-white/20"
                    )}
                >
                    <Star className={cn("w-4 h-4 transition-all duration-500", isPinned && "fill-current scale-110")} />
                </button>

                {/* Card Accent Glow */}
                <div className={cn(
                    "absolute -top-24 -right-24 w-48 h-48 blur-[100px] opacity-0 group-hover:opacity-20 transition-opacity duration-700 rounded-full z-0",
                    a.bg
                )} />

                <div className="relative z-10 flex flex-col h-full">
                    {/* Header: Icon & Tech ID */}
                    <div className="flex items-center justify-between mb-8">
                        <div className={cn(
                            "w-14 h-14 rounded-2xl flex items-center justify-center transition-all duration-500 border group-hover:scale-110 group-hover:rotate-3 shadow-xl",
                            a.bg,
                            a.border
                        )}>
                            <Icon className={cn("w-7 h-7", a.text)} strokeWidth={1.5} />
                        </div>
                    </div>

                    {/* Body: Title & Intro */}
                    <div className="space-y-4 flex-1 mt-2">
                        <div className="flex items-center gap-3">
                            <h3 className="text-xl font-black text-white tracking-tighter uppercase leading-tight">
                                {title}
                            </h3>
                            {warningBadge && (
                                <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-amber-500/10 border border-amber-500/30 text-amber-500 text-[9px] font-black uppercase tracking-[0.2em] whitespace-nowrap shadow-[0_0_10px_rgba(245,158,11,0.1)]">
                                    <ShieldAlert className="w-3 h-3" />
                                    {warningBadge}
                                </span>
                            )}
                        </div>
                        <p className="text-[13px] text-zinc-500 font-medium leading-relaxed group-hover:text-zinc-400 transition-colors">
                            {description}
                        </p>
                    </div>

                    {/* Footer: Action & Decoration */}
                    <div className="mt-8 pt-6 border-t border-white/5 flex items-center justify-between">
                        <div className={cn(
                            "flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.2em] transition-all",
                            a.text,
                            "opacity-40 group-hover:opacity-100"
                        )}>
                            <span className="group-hover:translate-x-1 transition-transform">Accès Panel</span>
                            <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-1.5 transition-transform" />
                        </div>
                        
                        {/* Industrial Corner Detail */}
                        <div className="flex gap-1">
                            {[...Array(3)].map((_, i) => (
                                <div key={i} className="h-1 w-1 rounded-full bg-white/5 group-hover:bg-white/20 transition-colors" />
                            ))}
                        </div>
                    </div>
                </div>

                {/* Corner Decoration */}
                <div className="absolute top-0 right-0 p-3 opacity-10 group-hover:opacity-30 transition-opacity">
                    <div className="h-[1px] w-12 bg-white/40" />
                    <div className="h-12 w-[1px] bg-white/40 absolute top-3 right-3" />
                </div>
            </div>
        </Link>
    );
}

"use client";

import { useState } from "react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
    DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Calendar, ShieldAlert, Archive, Clock, History } from "lucide-react";
import { toast } from "sonner";
import { updateMemberProfileStatus } from "@/server/actions/user-actions";

interface ArchiveDurationDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    memberId: string;
    memberName: string;
    onSuccess: () => void;
}

const DURATIONS = [
    { label: "30 Jours", value: 1, description: "Action standard pour un départ temporaire.", icon: Clock },
    { label: "3 Mois", value: 3, description: "Idéal pour une pause prolongée.", icon: Calendar },
    { label: "6 Mois", value: 6, description: "Archive longue durée pour absence indéfinie.", icon: History },
    { label: "12 Mois", value: 12, description: "Conservation maximale avant suppression.", icon: Archive },
];

export function ArchiveDurationDialog({
    open,
    onOpenChange,
    memberId,
    memberName,
    onSuccess,
}: ArchiveDurationDialogProps) {
    const [selectedDuration, setSelectedDuration] = useState<number>(1);
    const [isSubmitting, setIsSubmitting] = useState(false);

    const handleConfirm = async () => {
        setIsSubmitting(true);
        try {
            const res = await updateMemberProfileStatus(memberId, "ARCHIVED", "MANUAL_ADMIN_ACTION", selectedDuration);
            if (res) {
                toast.success(`Membre ${memberName} archivé pour ${selectedDuration} mois.`);
                onSuccess();
                onOpenChange(false);
            }
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "Erreur lors de l'archivage");
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-md bg-zinc-950 border-white/5 p-0 overflow-hidden rounded-3xl">
                <div className="bg-amber-500/10 p-8 flex flex-col items-center gap-4 text-center border-b border-amber-500/10">
                    <div className="w-16 h-16 rounded-2xl bg-amber-500/20 flex items-center justify-center border border-amber-500/20 shadow-lg shadow-amber-500/10">
                        <Archive className="w-8 h-8 text-amber-500" />
                    </div>
                    <div className="space-y-1">
                        <DialogTitle className="text-2xl font-black tracking-tight text-white uppercase">Archivage</DialogTitle>
                        <DialogDescription className="text-amber-500/60 font-medium">
                            Définissez la durée de conservation pour <span className="text-amber-400 font-bold">{memberName}</span>
                        </DialogDescription>
                    </div>
                </div>

                <div className="p-6 space-y-4">
                    <div className="grid grid-cols-1 gap-3">
                        {DURATIONS.map((duration) => {
                            const Icon = duration.icon;
                            const isSelected = selectedDuration === duration.value;
                            return (
                                <button
                                    key={duration.value}
                                    onClick={() => setSelectedDuration(duration.value)}
                                    className={`flex items-center gap-4 p-4 rounded-2xl border transition-all text-left group ${
                                        isSelected 
                                            ? "bg-amber-500/10 border-amber-500/30 ring-1 ring-amber-500/20" 
                                            : "bg-white/[0.02] border-white/5 hover:border-white/10 hover:bg-white/[0.04]"
                                    }`}
                                >
                                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-colors ${
                                        isSelected ? "bg-amber-500/20 text-amber-500" : "bg-white/5 text-zinc-500 group-hover:text-zinc-400"
                                    }`}>
                                        <Icon className="w-5 h-5" />
                                    </div>
                                    <div className="flex-1">
                                        <p className={`font-bold text-sm ${isSelected ? "text-amber-400" : "text-zinc-300"}`}>
                                            {duration.label}
                                        </p>
                                        <p className="text-[10px] text-zinc-500 font-medium leading-tight">
                                            {duration.description}
                                        </p>
                                    </div>
                                    {isSelected && (
                                        <div className="w-2 h-2 rounded-full bg-amber-500 shadow-[0_0_8px_rgba(245,158,11,0.5)]" />
                                    )}
                                </button>
                            );
                        })}
                    </div>

                    <div className="p-4 rounded-xl bg-red-500/5 border border-red-500/10 flex items-start gap-3">
                        <ShieldAlert className="w-4 h-4 text-red-400 shrink-0 mt-0.5" />
                        <p className="text-[10px] text-zinc-500 italic leading-snug">
                            Attention : À l'issue de cette période, toutes les données du membre (missions, succès, progression) seront **définitivement supprimées** du système pour respecter le RGPD.
                        </p>
                    </div>
                </div>

                <DialogFooter className="p-6 bg-white/[0.02] border-t border-white/5 gap-2 sm:gap-0">
                    <Button 
                        variant="ghost" 
                        onClick={() => onOpenChange(false)}
                        className="text-zinc-500 hover:text-white font-bold uppercase tracking-widest text-[10px]"
                    >
                        Annuler
                    </Button>
                    <Button 
                        disabled={isSubmitting}
                        onClick={handleConfirm}
                        className="bg-amber-600 hover:bg-amber-500 text-white font-black uppercase tracking-widest text-[10px] px-8 rounded-xl shadow-lg shadow-amber-600/20"
                    >
                        {isSubmitting ? "Archivage..." : "Confirmer l'archivage"}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import React, { useState, useEffect, useMemo } from "react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { 
    Search, 
    ImageIcon, 
    Map as MapIcon, 
    Loader2, 
    X, 
    Check,
    Image as ImageIconLucide
} from "lucide-react";
import { cn } from "@/lib/utils";
import { getBountyAssets, type AssetInfo, type AssetType } from "@/server/actions/game-assets-actions";

interface AssetGalleryModalProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSelect: (url: string) => void;
    initialType?: AssetType;
    title?: string;
}

export function AssetGalleryModal({
    open,
    onOpenChange,
    onSelect,
    initialType = "portraits",
    title = "Galerie d'Assets"
}: AssetGalleryModalProps) {
    const [type, setType] = useState<AssetType>(initialType);
    const [assets, setAssets] = useState<AssetInfo[]>([]);
    const [loading, setLoading] = useState(false);
    const [search, setSearch] = useState("");
    const [selectedUrl, setSelectedUrl] = useState<string | null>(null);

    useEffect(() => {
        if (open) {
            fetchAssets(type);
        }
    }, [open, type]);

    const fetchAssets = async (assetType: AssetType) => {
        setLoading(true);
        try {
            const res = await getBountyAssets(assetType);
            if (res.success && res.data) {
                setAssets(res.data);
            }
        } catch (error) {
            console.error("Gallery Fetch Error:", error);
        } finally {
            setLoading(false);
        }
    };

    const filteredAssets = useMemo(() => {
        return assets.filter(a => a.name.toLowerCase().includes(search.toLowerCase()));
    }, [assets, search]);

    const handleConfirm = () => {
        if (selectedUrl) {
            onSelect(selectedUrl);
            onOpenChange(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="w-[95vw] sm:max-w-4xl bg-zinc-950 border-zinc-800 p-0 overflow-hidden flex flex-col h-[80vh] shadow-2xl">
                <DialogHeader className="p-4 sm:p-6 border-b border-white/5 bg-black/40">
                    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                        <div>
                            <DialogTitle className="text-xl sm:text-2xl font-black text-white uppercase italic tracking-tighter flex items-center gap-3">
                                {type === "portraits" ? <ImageIconLucide className="text-amber-500" /> : <MapIcon className="text-amber-500" />}
                                {title}
                            </DialogTitle>
                            <DialogDescription className="text-zinc-500 text-[9px] sm:text-[10px] font-black uppercase tracking-[0.3em] mt-1">
                                {assets.length} fichiers détectés dans /assets/avis/{type}
                            </DialogDescription>
                        </div>
                        
                        <div className="flex bg-zinc-900 p-1 rounded-xl border border-white/5 self-start sm:self-auto">
                            <button
                                onClick={() => setType("portraits")}
                                className={cn(
                                    "px-3 sm:px-4 py-1.5 sm:py-2 rounded-lg text-[9px] sm:text-[10px] font-black uppercase italic transition-all flex items-center gap-2",
                                    type === "portraits" ? "bg-amber-500 text-black shadow-lg" : "text-zinc-500 hover:text-white"
                                )}
                            >
                                <ImageIconLucide size={14} />
                                Portraits
                            </button>
                            <button
                                onClick={() => setType("maps")}
                                className={cn(
                                    "px-3 sm:px-4 py-1.5 sm:py-2 rounded-lg text-[9px] sm:text-[10px] font-black uppercase italic transition-all flex items-center gap-2",
                                    type === "maps" ? "bg-amber-500 text-black shadow-lg" : "text-zinc-500 hover:text-white"
                                )}
                            >
                                <MapIcon size={14} />
                                Maps
                            </button>
                        </div>
                    </div>

                    <div className="mt-6 relative group">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-600 group-focus-within:text-amber-500 transition-colors" size={18} />
                        <Input
                            placeholder="Rechercher un fichier..."
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            className="pl-12 bg-zinc-900/50 border-white/5 text-white font-bold h-12 rounded-xl focus-visible:ring-amber-500/50"
                        />
                    </div>
                </DialogHeader>

                <div className="flex-1 min-h-0 flex flex-col p-6 bg-zinc-950">
                    {loading ? (
                        <div className="flex-1 flex flex-col items-center justify-center gap-4">
                            <Loader2 className="animate-spin text-amber-500" size={40} />
                            <span className="text-[10px] font-black text-zinc-600 uppercase tracking-widest">Indexation des fichiers...</span>
                        </div>
                    ) : filteredAssets.length > 0 ? (
                        <ScrollArea className="h-full pr-4">
                            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 sm:gap-4">
                                {filteredAssets.map((asset) => (
                                    <button
                                        key={asset.url}
                                        onClick={() => setSelectedUrl(asset.url)}
                                        onDoubleClick={() => {
                                            onSelect(asset.url);
                                            onOpenChange(false);
                                        }}
                                        className={cn(
                                            "group relative aspect-square rounded-2xl border-2 overflow-hidden transition-all duration-300",
                                            selectedUrl === asset.url
                                                ? "border-amber-500 bg-amber-500/10 shadow-[0_0_20px_rgba(245,158,11,0.2)]"
                                                : "border-white/5 bg-zinc-900 hover:border-white/20"
                                        )}
                                    >
                                        <div className="absolute inset-0 flex items-center justify-center p-2">
                                            <img
                                                src={asset.url}
                                                alt={asset.name}
                                                className={cn(
                                                    "w-full h-full transition-transform duration-500",
                                                    type === "portraits" ? "object-contain" : "object-cover",
                                                    selectedUrl === asset.url ? "scale-110" : "group-hover:scale-105"
                                                )}
                                            />
                                        </div>
                                        
                                        <div className={cn(
                                            "absolute inset-x-0 bottom-0 p-2 bg-black/80 backdrop-blur-sm border-t border-white/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300",
                                            selectedUrl === asset.url && "translate-y-0"
                                        )}>
                                            <p className="text-[9px] font-bold text-zinc-300 truncate text-center">
                                                {asset.name}
                                            </p>
                                        </div>

                                        {selectedUrl === asset.url && (
                                            <div className="absolute top-2 right-2 w-6 h-6 rounded-full bg-amber-500 flex items-center justify-center shadow-lg animate-in zoom-in">
                                                <Check size={14} className="text-black font-bold" />
                                            </div>
                                        )}
                                    </button>
                                ))}
                            </div>
                        </ScrollArea>
                    ) : (
                        <div className="flex-1 flex flex-col items-center justify-center text-zinc-700 gap-4">
                            <ImageIconLucide size={64} className="opacity-20" />
                            <p className="text-sm font-bold italic">Aucun asset trouvé</p>
                        </div>
                    )}
                </div>

                <div className="p-4 sm:p-6 border-t border-white/5 bg-black/40 flex flex-col sm:flex-row items-center justify-between gap-4">
                    <p className="text-[9px] sm:text-[10px] font-bold text-zinc-500 text-center sm:text-left">
                        Double-cliquez pour sélectionner instantanément
                    </p>
                    <div className="flex items-center gap-3 w-full sm:w-auto">
                        <Button
                            variant="ghost"
                            onClick={() => onOpenChange(false)}
                            className="flex-1 sm:flex-none text-zinc-500 hover:text-white text-[10px] sm:text-sm"
                        >
                            Annuler
                        </Button>
                        <Button
                            disabled={!selectedUrl}
                            onClick={handleConfirm}
                            className="flex-1 sm:flex-none bg-amber-500 hover:bg-amber-600 text-black font-black uppercase italic px-4 sm:px-8 text-[10px] sm:text-sm"
                        >
                            Confirmer
                        </Button>
                    </div>
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
