                                                )}
                                                {m.discordId.startsWith("manual_") && (
                                                    <Badge variant="outline" className="border-violet-500/30 text-violet-500/80 text-[8px] font-black uppercase tracking-tighter w-fit italic">Ligne Manuelle</Badge>
                                                )}
