                                                        }));
                                                    }}
                                                    onBlur={() => handleUpdateValue(m, m.currentValue)}
                                                    className="pl-10 h-10 bg-black/40 border-white/5 focus:border-violet-500/50 rounded-xl font-black text-zinc-200 w-full tabular-nums"
                                                />
