                                <Tooltip>
                                    <TooltipTrigger asChild>
                                        <div className="p-1.5 cursor-help bg-white/5 hover:bg-red-500/20 rounded-lg transition-all group/tooltip border border-white/5 hover:border-red-500/20">
                                            <HelpCircle className="w-4 h-4 text-zinc-400 group-hover/tooltip:text-red-400 transition-colors" />
                                        </div>
                                    </TooltipTrigger>
                                    <TooltipContent side="right" sideOffset={15} className="bg-zinc-950 border border-white/10 p-5 max-w-[300px] space-y-3 rounded-2xl shadow-[0_20px_50px_rgba(0,0,0,0.5)] animate-in zoom-in-95 duration-200 z-[100]">
                                        <div className="flex items-center gap-3 mb-1">
                                            <div className="w-1.5 h-4 bg-red-600 rounded-full shadow-[0_0_10px_rgba(239,68,68,0.5)]" />
                                            <p className="text-xs font-black uppercase text-white tracking-widest">Comment remplir ?</p>
                                        </div>
                                        <div className="space-y-2">
                                            <p className="text-[11px] text-zinc-300 leading-relaxed italic">
                                                Tapez <span className="text-red-400 font-black italic">/whois pseudo</span> en jeu ou cliquez sur un joueur <span className="text-white font-bold">&gt; Informations &gt; Détails</span>.
                                            </p>
                                            <p className="text-[11px] text-zinc-400 leading-relaxed">
                                                Copiez ensuite <span className="text-white font-medium">toute la ligne</span> de log et collez-la ici. SigilOS s&apos;occupe du reste !
                                            </p>
                                        </div>
                                    </TooltipContent>
                                </Tooltip>
                            </div>
                            <Textarea 
                                placeholder="Pseudo, compte Dofus, raison... (Pas de liens autorisés)"
                                value={newContent}
                                onChange={(e) => setNewContent(e.target.value)}
                                className="min-h-[120px] bg-black/40 border-white/5 text-white rounded-3xl focus:ring-red-500/20 focus:border-red-500/50 transition-all placeholder:text-zinc-600 font-medium resize-none p-4"
                            />
                        </div>

                        {blacklistChannelId && newContent.trim() && (
                            <div className="space-y-2 pt-2 animate-in fade-in slide-in-from-top-2">
                                <div className="flex items-center gap-2 p-3 bg-red-500/10 border border-red-500/20 rounded-xl shadow-inner">
                                    <div className="w-8 h-8 rounded-lg bg-red-500/20 flex items-center justify-center border border-red-500/30">
                                        <Hash className="w-4 h-4 text-red-400" />
                                    </div>
                                    <div className="flex flex-col">
                                        <span className="text-[10px] font-black uppercase tracking-widest text-zinc-500">Destination Discord</span>
                                        <span className="text-xs font-bold text-white">Log envoyé dans <span className="text-red-400 italic">#{targetChannelName}</span></span>
                                    </div>
                                </div>
                            </div>
                        )}

                        <Button 
                            className="w-full h-12 bg-red-600 hover:bg-red-500 text-white rounded-2xl font-black uppercase tracking-widest gap-2 shadow-lg shadow-red-600/20"
                            onClick={handleAdd}
                            disabled={isPending}
                        >
                            {isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Ban className="w-4 h-4" />}
                            Inscrire à la Blacklist
                        </Button>
                        <p className="text-[9px] text-zinc-600 italic text-center px-4 leading-relaxed">
                            Cette liste est purement informative et n&apos;influence pas l&apos;accès automatique au dashboard.
                        </p>

                        {/* Discord Sync Promo */}
                        <Link 
                            href={`/dashboard/${guildId}/admin/settings?tab=blacklist`}
                            className="block group/sync mt-4"
                        >
                            <div className="p-4 rounded-2xl bg-white/[0.03] border border-white/5 hover:border-red-500/30 hover:bg-red-500/5 transition-all duration-300">
                                <div className="flex items-center gap-3 mb-2">
                                    <div className="p-1.5 rounded-lg bg-zinc-800 border border-white/5 group-hover/sync:bg-red-500/20 group-hover/sync:border-red-500/30 transition-colors">
                                        <ShieldAlert className="w-3.5 h-3.5 text-zinc-500 group-hover/sync:text-red-400" />
                                    </div>
                                    <p className="text-[10px] font-black uppercase tracking-widest text-zinc-400 group-hover/sync:text-white transition-colors">Synchro Discord</p>
                                </div>
                                <p className="text-[10px] text-zinc-500 group-hover/sync:text-zinc-300 leading-loose">
                                    Les administrateurs peuvent <span className="text-zinc-300 font-bold">coupler un salon Discord</span> pour une synchro en temps réel.
                                </p>
                                <div className="mt-3 flex items-center gap-1.5 text-[9px] font-black uppercase tracking-widest text-red-500/60 group-hover/sync:text-red-400 transition-colors">
                                    Configurer maintenant
                                    <Plus className="w-3 h-3 group-hover/sync:translate-x-0.5 transition-transform" />
                                </div>
                            </div>
                        </Link>
                    </CardContent>
                </Card>

                <div className="lg:col-span-2 space-y-6">
                    {/* Search Bar */}
                    <div className="relative group">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500 group-focus-within:text-red-400 transition-colors" />
                        <Input 
                            placeholder="Rechercher dans la blacklist..." 
                            value={search}
                            onChange={(e) => handleSearch(e.target.value)}
                            className="pl-12 h-14 bg-zinc-900/40 backdrop-blur-xl border-white/5 text-white rounded-[1.5rem] focus:ring-red-500/20 focus:border-red-500/50 transition-all placeholder:text-zinc-600 font-medium shadow-2xl"
                        />
                    </div>

                    {/* Entries List */}
                    <div className="rounded-[2.5rem] border border-white/10 bg-zinc-900/40 backdrop-blur-2xl overflow-hidden shadow-2xl relative group">
                        <div className="absolute inset-0 bg-gradient-to-br from-red-500/5 to-transparent pointer-events-none" />
                        <Table>
                            <TableHeader className="bg-white/[0.02] border-b border-white/5 relative z-10">
                                <TableRow className="hover:bg-transparent border-none">
                                    <TableHead className="pl-8 py-6 text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em]">Détails du Signalement</TableHead>
                                    <TableHead className="py-6 text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em] w-[200px]">Auteur & Date</TableHead>
                                    <TableHead className="text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em] pr-8 text-right py-6 w-[80px]"></TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody className="relative z-10">
                                <AnimatePresence mode="popLayout">
                                    {loading ? (
                                        <TableRow>
                                            <TableCell colSpan={3} className="h-64 text-center">
                                                <div className="flex flex-col items-center gap-4">
                                                    <Loader2 className="w-8 h-8 text-red-500 animate-spin" />
                                                    <span className="text-xs font-black uppercase tracking-widest text-zinc-500">Chargement de la blacklist...</span>
                                                </div>
                                            </TableCell>
                                        </TableRow>
                                    ) : entries.length === 0 ? (
                                        <TableRow>
                                            <TableCell colSpan={3} className="h-64 text-center">
                                                <div className="flex flex-col items-center gap-4 opacity-40">
                                                    <BanIcon className="w-12 h-12 text-zinc-600" />
                                                    <div className="space-y-1">
                                                        <p className="text-sm font-black uppercase tracking-widest text-zinc-300">Blacklist vide</p>
                                                        <p className="text-[10px] text-zinc-500 italic">Aucun signalement ne correspond à votre recherche.</p>
                                                    </div>
                                                </div>
                                            </TableCell>
                                        </TableRow>
                                    ) : (
                                        entries.map((entry) => (
                                            <motion.tr 
                                                layout
                                                key={entry.id} 
                                                initial={{ opacity: 0, y: 10 }}
                                                animate={{ opacity: 1, y: 0 }}
                                                exit={{ opacity: 0, scale: 0.95 }}
                                                className="group border-b border-white/[0.03] hover:bg-white/[0.02] transition-colors"
                                            >
                                                <TableCell className="pl-8 py-6">
                                                    {editingId === entry.id ? (
                                                        <div className="space-y-3 animate-in fade-in zoom-in-95 duration-200">
                                                            <Textarea 
                                                                value={editContent}
                                                                onChange={(e) => setEditContent(e.target.value)}
                                                                className="bg-black/60 border-white/10 text-zinc-200 text-sm font-medium rounded-2xl min-h-[80px]"
                                                            />
                                                            <div className="flex items-center gap-2">
                                                                <Button 
                                                                    size="sm" 
                                                                    className="bg-emerald-600 hover:bg-emerald-500 text-white h-8 px-4 font-black uppercase tracking-widest text-[10px] rounded-lg"
                                                                    onClick={handleSaveEdit}
                                                                    disabled={isPending}
                                                                >
                                                                    {isPending ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Check className="w-3.5 h-3.5 mr-2" />}
                                                                    Valider
                                                                </Button>
                                                                <Button 
                                                                    size="sm" 
                                                                    variant="ghost"
                                                                    className="text-zinc-500 hover:text-white h-8 px-4 font-black uppercase tracking-widest text-[10px] rounded-lg"
                                                                    onClick={() => setEditingId(null)}
                                                                    disabled={isPending}
                                                                >
                                                                    Annuler
                                                                </Button>
                                                            </div>
                                                        </div>
                                                    ) : (
                                                        <div className="space-y-1">
                                                            <div className="text-sm font-bold text-zinc-200 group-hover:text-white transition-colors leading-relaxed whitespace-pre-wrap break-words italic">
                                                                &ldquo;{renderFormattedContent(entry.content)}&rdquo;
                                                            </div>
                                                        </div>
                                                    )}
                                                </TableCell>
                                                <TableCell className="py-6">
                                                    <div className="flex flex-col gap-1.5 justify-center h-full">
                                                        <div className="flex items-center gap-2 text-zinc-400 group-hover:text-red-400 transition-colors">
                                                            <User className="w-3 h-3" />
                                                            <span className="text-[10px] font-black uppercase tracking-wider">{entry.addedByName}</span>
                                                        </div>
                                                        <div className="flex items-center gap-2 text-zinc-500">
                                                            <Clock className="w-3 h-3" />
                                                            <span className="text-[9px] font-bold tabular-nums">
                                                                {format(new Date(entry.createdAt), "dd MMM yyyy, HH:mm", { locale: fr })}
                                                            </span>
                                                        </div>
                                                    </div>
                                                </TableCell>
                                                <TableCell className="pr-8 text-right">
                                                    <div className="flex items-center justify-end gap-1">
                                                        <Button 
                                                            variant="ghost" 
                                                            size="sm" 
                                                            className="h-9 w-9 p-0 rounded-xl text-zinc-600 hover:text-amber-500 hover:bg-amber-500/10 transition-all opacity-0 group-hover:opacity-100"
                                                            onClick={() => handleStartEdit(entry)}
                                                            disabled={editingId === entry.id}
                                                        >
                                                            <Pencil className="w-4 h-4" />
                                                        </Button>
                                                        <Button 
                                                            variant="ghost" 
                                                            size="sm" 
                                                            className="h-9 w-9 p-0 rounded-xl text-zinc-600 hover:text-red-500 hover:bg-red-500/10 transition-all opacity-0 group-hover:opacity-100"
                                                            onClick={() => handleDelete(entry.id)}
                                                            disabled={editingId === entry.id}
                                                        >
                                                            <Trash2 className="w-4 h-4" />
                                                        </Button>
                                                    </div>
                                                </TableCell>
                                            </motion.tr>
                                        ))
                                    )}
                                </AnimatePresence>
                            </TableBody>
                        </Table>
                    </div>
                </div>
            </div>
        </div>
    );
}

import React, { useState } from "react";
import { 
    BarChart, 
    Bar, 
    XAxis, 
    YAxis, 
    Tooltip, 
    ResponsiveContainer, 
    Cell,
    PieChart,
    Pie
} from "recharts";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { MessageSquare, Mic, Activity, Maximize2, Search } from "lucide-react";
import { MemberReconciliationData, RoleStats } from "@/server/actions/member-actions";
import { 
    Dialog, 
    DialogContent, 
    DialogHeader, 
    DialogTitle, 
    DialogTrigger,
    DialogDescription
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { 
    Table, 
    TableBody, 
    TableCell, 
    TableHead, 
    TableHeader, 
    TableRow 
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { 
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";

interface MemberDiscordChartsProps {
    members: MemberReconciliationData[];
    roleStats: RoleStats[];
}

const CustomTooltip = ({ active, payload, label, suffix = "" }: any) => {
    if (active && payload && payload.length) {
        return (
            <div className="bg-zinc-950/90 border border-violet-500/20 px-4 py-3 rounded-2xl shadow-[0_8px_32px_rgba(0,0,0,0.6)] backdrop-blur-xl">
                <p className="text-[9px] font-black text-zinc-500 uppercase tracking-[0.2em] mb-1">{label}</p>
                <p className="text-[18px] font-black text-white tabular-nums leading-none">
                    {payload[0].value.toLocaleString()}
                    <span className="text-[10px] text-zinc-400 uppercase font-bold ml-1.5">{suffix}</span>
                </p>
            </div>
        );
    }
    return null;
};

export function MemberDiscordCharts({ members, roleStats }: MemberDiscordChartsProps) {
    const [mounted, setMounted] = React.useState(false);
    const [searchTerm, setSearchTerm] = useState("");
    const [timeframe, setTimeframe] = useState<"weekly" | "monthly" | "total">("weekly");
    const [sortKey, setSortKey] = useState<string>("messages");
    const [sortOrder, setSortOrder] = useState<"desc" | "asc">("desc");
    const [selectedRole, setSelectedRole] = useState<string>("all");

    React.useEffect(() => {
        setMounted(true);
    }, []);

    const getKeys = () => {
        switch (timeframe) {
            case "monthly":
                return { msg: "discordMessageCountMonthly", voice: "discordVoiceTimeMonthly" };
            case "total":
                return { msg: "discordMessageCountTotal", voice: "discordVoiceTimeTotal" };
            default:
                return { msg: "discordMessageCountWeekly", voice: "discordVoiceTimeWeekly" };
        }
    };

    const keys = getKeys();

    const activeCount = members.filter(m => ((m as any)[keys.msg] || 0) > 0 || ((m as any)[keys.voice] || 0) > 0).length;
    const silentCount = Math.max(0, members.length - activeCount);

    const activityData = [
        { name: "Actifs", value: activeCount, color: "#8b5cf6" },
        { name: "Silencieux", value: silentCount, color: "#27272a" }
    ];

    if (!mounted) {
        return (
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[300px]">
                {[1, 2, 3].map(i => (
                    <Card key={i} className="bg-zinc-900/30 border-white/5 animate-pulse rounded-[32px] overflow-hidden shadow-2xl" />
                ))}
            </div>
        );
    }

    const topTalkers = [...members]
        .sort((a, b) => ((b as any)[keys.msg] || 0) - ((a as any)[keys.msg] || 0))
        .slice(0, 5)
        .map(m => ({
            name: m.displayName.split(" ")[0].slice(0, 10),
            value: (m as any)[keys.msg] || 0
        }));

    const topVocal = [...members]
        .sort((a, b) => ((b as any)[keys.voice] || 0) - ((a as any)[keys.voice] || 0))
        .slice(0, 5)
        .map(m => ({
            name: m.displayName.split(" ")[0].slice(0, 10),
            value: Math.round(((m as any)[keys.voice] || 0) / 60)
        }));

    const sortedMembers = [...members]
        .filter(m => {
            const matchesSearch = m.displayName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                                m.username.toLowerCase().includes(searchTerm.toLowerCase());
            const matchesRole = selectedRole === "all" || m.roles.includes(selectedRole);
            return matchesSearch && matchesRole;
        })
        .sort((a, b) => {
            let valA = 0;
            let valB = 0;
            if (sortKey === "messages") {
                valA = (a as any)[keys.msg] || 0;
                valB = (b as any)[keys.msg] || 0;
            } else if (sortKey === "vocal") {
                valA = (a as any)[keys.voice] || 0;
                valB = (b as any)[keys.voice] || 0;
            } else {
                valA = (a as any)[sortKey] || 0;
                valB = (b as any)[sortKey] || 0;
            }
            return sortOrder === "desc" ? (valB > valA ? 1 : -1) : (valA > valB ? 1 : -1);
        });

    const timeframeLabel = timeframe === "weekly" ? "cette semaine" : timeframe === "monthly" ? "ce mois-ci" : "all-time";

    // Bar chart gradient colors per index
    const MSG_GRADIENT_ID = "msgGradient";
    const VOICE_GRADIENT_ID = "voiceGradient";

    return (
        <div className="space-y-6">
            {/* Global Timeframe Selector */}
            <div className="flex justify-end">
                <div className="bg-zinc-900/60 p-1 rounded-2xl border border-white/5 backdrop-blur-xl flex gap-1">
                    {[
                        { id: "weekly", label: "Semaine" },
                        { id: "monthly", label: "Mois" },
                        { id: "total", label: "Global" }
                    ].map((t) => (
                        <button
                            key={t.id}
                            onClick={() => setTimeframe(t.id as any)}
                            className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                                timeframe === t.id 
                                ? "bg-violet-600 text-white shadow-[0_0_20px_rgba(139,92,246,0.4)]" 
                                : "text-zinc-500 hover:text-zinc-300 hover:bg-white/5"
                            }`}
                        >
                            {t.label}
                        </button>
                    ))}
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Activity Overview — Donut */}
                <Card className="bg-zinc-900/30 border-white/5 backdrop-blur-xl rounded-[32px] overflow-hidden shadow-2xl relative group">
                    <div className="absolute inset-0 bg-gradient-to-br from-violet-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                    <CardHeader className="pb-2">
                        <CardTitle className="text-sm font-black uppercase tracking-[0.2em] text-white italic flex items-center gap-2">
                            <Activity className="w-4 h-4 text-violet-400" />
                            État d&apos;activité
                        </CardTitle>
                        <CardDescription className="text-[10px] uppercase font-bold text-zinc-500">Membres actifs {timeframeLabel}</CardDescription>
                    </CardHeader>
                    <CardContent className="h-[250px] relative min-h-[250px]">
                        <ResponsiveContainer width="100%" height="100%" minHeight={200} minWidth={0}>
                            <PieChart>
                                <Pie
                                    data={activityData}
                                    cx="50%"
                                    cy="50%"
                                    innerRadius={62}
                                    outerRadius={84}
                                    paddingAngle={4}
                                    dataKey="value"
                                    strokeWidth={0}
                                >
                                    {activityData.map((entry, index) => (
                                        <Cell 
                                            key={`cell-${index}`} 
                                            fill={entry.color} 
                                            stroke="none"
                                            style={{ filter: index === 0 ? "drop-shadow(0 0 12px rgba(139,92,246,0.5))" : "none" }}
                                        />
                                    ))}
                                </Pie>
                                <Tooltip content={<CustomTooltip suffix="membres" />} />
                            </PieChart>
                        </ResponsiveContainer>
                        {/* Center label */}
                        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none mt-4">
                            <span className="text-3xl font-black text-white">{members.length > 0 ? Math.round((activeCount / members.length) * 100) : 0}%</span>
                            <span className="text-[10px] font-black text-violet-400 uppercase tracking-widest">Actif</span>
                        </div>
                    </CardContent>
                    {/* Legend */}
                    <div className="px-6 pb-5 flex items-center justify-center gap-6">
                        <div className="flex items-center gap-2">
                            <div className="w-2.5 h-2.5 rounded-full bg-violet-500 shadow-[0_0_8px_rgba(139,92,246,0.6)]" />
                            <span className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">Actifs <span className="text-white">{activeCount}</span></span>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="w-2.5 h-2.5 rounded-full bg-zinc-700" />
                            <span className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">Silencieux <span className="text-white">{silentCount}</span></span>
                        </div>
                    </div>
                </Card>

                {/* Top Messages */}
                <Card className="bg-zinc-900/30 border-white/5 backdrop-blur-xl rounded-[32px] overflow-hidden shadow-2xl relative group">
                    <div className="absolute inset-0 bg-gradient-to-br from-blue-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                    <CardHeader className="pb-2 flex flex-row items-center justify-between">
                        <div>
                            <CardTitle className="text-sm font-black uppercase tracking-[0.2em] text-white italic flex items-center gap-2">
                                <MessageSquare className="w-4 h-4 text-blue-400" />
                                Top Bavards
                            </CardTitle>
                            <CardDescription className="text-[10px] uppercase font-bold text-zinc-500">Volume messages {timeframeLabel}</CardDescription>
                        </div>
                        
                        <Dialog>
                            <DialogTrigger asChild>
                                <button className="p-2 bg-white/5 hover:bg-white/10 rounded-xl transition-all border border-white/5 flex items-center gap-2 group/btn">
                                    <Maximize2 className="w-3.5 h-3.5 text-zinc-400 group-hover/btn:text-white transition-colors" />
                                    <span className="text-[8px] font-black uppercase text-zinc-500 group-hover/btn:text-white transition-colors">Détails</span>
                                </button>
                            </DialogTrigger>
                            <DialogContent className="max-w-4xl bg-zinc-950 border-white/10 p-0 rounded-[32px] overflow-hidden shadow-[0_0_100px_rgba(0,0,0,0.8)]">
                                <DialogHeader className="p-8 border-b border-white/5">
                                    <DialogTitle className="text-2xl font-black uppercase tracking-tight text-white italic flex items-center gap-3">
