                                                        </TableCell>
                                                        <TableCell className="text-right">
                                                            {m.hasDashboardProfile ? (
                                                                <Badge className="bg-emerald-500/10 text-emerald-500 border-none text-[8px] font-black uppercase">Inscrit</Badge>
