                                    </div>
                                </div>
                            </DialogContent>
                        </Dialog>
                    </CardHeader>
                    <CardContent className="h-[250px] pt-2 min-h-[250px]">
                        <ResponsiveContainer width="100%" height="100%" minHeight={200} minWidth={0}>
