    const [pendingOpen, setPendingOpen] = useState(false);
    const cfg = TYPE_CFG[type];
    
    // Filtre les fichiers en attente de validation pour cette catégorie
    const myPending = pendingFiles.filter(pf => {
        if (pf.type === "MISSION") return type === "MISSION";
        if (pf.type === "KAMA") return type === "KAMA";
        if (pf.type === "ACHIEVEMENT") return type === "ACHIEVEMENT";
        return false;
    });

    const icon = type === "MISSION" ? <FileImage className="w-4 h-4" /> :
                type === "KAMA" ? <Coins className="w-4 h-4" /> :
                type === "PRESENTATION" ? <ImageIcon className="w-4 h-4" /> :
                type === "LOAN_PROOF" ? <Handshake className="w-4 h-4" /> :
                <Trophy className="w-4 h-4" />;

    return (
        <>
            <div 
                className={cn(
                    "p-5 rounded-[2.5rem] border transition-all relative group/item overflow-hidden",
                    count > 0 || myPending.length > 0 ? "bg-zinc-900/40 border-white/5" : "bg-zinc-950/20 border-white/[0.02] opacity-50 grayscale"
                )}
            >
                <div className="flex items-start justify-between mb-4">
                    <div className={cn("w-12 h-12 rounded-2xl flex items-center justify-center transition-transform group-hover/item:rotate-12 shadow-2xl", cfg.bg, cfg.color)}>
                        {icon}
                    </div>
                    <div className="flex items-center gap-2">
                        {myPending.length > 0 && (
                            <button 
                                onClick={() => setPendingOpen(true)}
                                className="px-3 py-1.5 bg-amber-500/10 hover:bg-amber-500/20 rounded-xl text-amber-500 text-[10px] font-black uppercase tracking-widest transition-all border border-amber-500/20 shadow-xl flex items-center gap-2"
                            >
                                <Clock className="w-3.5 h-3.5" />
                                {myPending.length} EN ATTENTE
                            </button>
                        )}
                        {count > 0 && (
                            <button 
                                onClick={() => setExplorerOpen(true)}
                                className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl text-zinc-500 hover:text-white transition-all shadow-xl"
                            >
                                <FolderOpen className="w-5 h-5" />
                            </button>
                        )}
                    </div>
                </div>

                <div className="space-y-4">
                    <div>
                        <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest leading-none">{cfg.label}</p>
                        <div className="flex items-center gap-2 mt-2">
                            <p className="text-[28px] font-black text-white tracking-tighter leading-none">{count}</p>
                            <p className="text-[10px] font-mono text-zinc-500 uppercase">{formatBytes(bytes)}</p>
                        </div>
                    </div>

                    <div className="pt-4 border-t border-white/[0.03]">
                        <p className="text-[8px] font-black text-zinc-600 uppercase tracking-widest mb-1.5 flex items-center gap-1.5">
                            <HardDrive className="w-2.5 h-2.5" />
                            Chemin Physique
                        </p>
                        <PathDisplay path={dir} colorClass={cfg.color} />
                    </div>
                </div>
            </div>

            <FileExplorerDialog 
                open={explorerOpen} 
                onOpenChange={setExplorerOpen} 
                files={files} 
                label={cfg.label} 
                type={type} 
                onDeleted={onReload} 
            />

            {/* Salle d'attente (pending validation) */}
            <PendingValidationDialog 
                open={pendingOpen} 
                onOpenChange={setPendingOpen} 
                files={myPending} 
                label={cfg.label} 
                type={type} 
                onDeleted={onReload} 
            />
        </>
    );
}

function DeleteButton({ fileUrl, dbClear, onDeleted, label = "Supprimer" }: { fileUrl: string; dbClear?: { guildId: string; field: AssetDbField }; onDeleted: () => void; label?: string }) {
    const [loading, setLoading] = useState(false);
    const del = async () => {
        if (!confirm(`Confirmer la suppression irréversible de : ${fileUrl} ?`)) return;
        setLoading(true);
        const res = await godDeleteFile(fileUrl, dbClear);
        if (res.success) {
            toast.success("Fichier supprimé définitivement");
            onDeleted(); 
        } else {
            toast.error(res.error || "Erreur lors de la suppression");
        }
        setLoading(false);
    };
    return (
        <button onClick={del} disabled={loading} className="px-4 py-2 bg-red-500/10 hover:bg-red-500/20 text-red-500 border border-red-500/20 rounded-xl flex items-center gap-2 font-black uppercase text-[10px] tracking-widest transition-colors shadow-2xl" title={label}>
            {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Trash2 className="w-4 h-4 shrink-0" />}
            {label}
        </button>
    );
}

function GuildRow({ guild, onReload }: { guild: StorageGuildEntry; onReload: () => void }) {
    const subTotal = guild.missionsBytes + guild.kamaBytes + guild.achievementBytes + guild.presentationBytes;
    const totalCount = guild.missionsCount + guild.kamaCount + guild.achievementCount + guild.presentationCount;
    const [isExpanded, setIsExpanded] = useState(false);

    return (
        <>
            <tr className={cn(
                "group/row hover:bg-white/[0.02] transition-colors cursor-pointer border-b border-white/[0.02]",
                isExpanded && "bg-white/[0.03]"
            )} onClick={() => setIsExpanded(!isExpanded)}>
                <td className="px-8 py-6">
                    <div className="flex items-center gap-4 text-left">
                        <div className="w-8 h-8 rounded-lg bg-zinc-950 border border-white/5 flex items-center justify-center overflow-hidden shrink-0">
                            {guild.assets.find(a => a.type === "ICON") ? (
                                <img src={guild.assets.find(a => a.type === "ICON")!.url} alt="" className="w-full h-full object-cover" />
                            ) : <Shield className="w-3.5 h-3.5 text-zinc-600" />}
                        </div>
                        <div>
                            <p className="text-sm font-black text-white uppercase tracking-tighter group-hover/row:text-indigo-400 transition-colors leading-tight">{guild.name}</p>
                            <p className="text-[9px] font-mono font-bold text-zinc-600 tracking-tighter">{guild.discordGuildId}</p>
                        </div>
                    </div>
                </td>
                <td className="px-8 py-6 text-right font-mono font-black text-indigo-400">{formatBytes(subTotal)}</td>
                <td className="px-8 py-6 text-center font-black text-zinc-400 text-xs">{totalCount}</td>
                <td className="px-8 py-6">
                    <div className="flex items-center gap-1.5">
                        <TooltipProvider>
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <div className="flex items-center gap-1 bg-rose-500/5 px-2 py-1 rounded-md border border-rose-500/10">
                                        <div className="w-1.5 h-1.5 rounded-full bg-rose-500" />
                                        <span className="text-[10px] font-black text-rose-500/80">{guild.missionsCount}</span>
                                    </div>
                                </TooltipTrigger>
                                <TooltipContent className="bg-zinc-950 border-rose-500/20 text-rose-400 font-black text-[10px] uppercase tracking-widest">
                                    Missions: {formatBytes(guild.missionsBytes)}
                                </TooltipContent>
                            </Tooltip>
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <div className="flex items-center gap-1 bg-amber-500/5 px-2 py-1 rounded-md border border-amber-500/10">
                                        <div className="w-1.5 h-1.5 rounded-full bg-amber-500" />
                                        <span className="text-[10px] font-black text-amber-500/80">{guild.kamaCount}</span>
                                    </div>
                                </TooltipTrigger>
                                <TooltipContent className="bg-zinc-950 border-amber-500/20 text-amber-400 font-black text-[10px] uppercase tracking-widest">
                                    Kamas: {formatBytes(guild.kamaBytes)}
                                </TooltipContent>
                            </Tooltip>
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <div className="flex items-center gap-1 bg-purple-500/5 px-2 py-1 rounded-md border border-purple-500/10">
                                        <div className="w-1.5 h-1.5 rounded-full bg-purple-500" />
                                        <span className="text-[10px] font-black text-purple-500/80">{guild.achievementCount}</span>
                                    </div>
                                </TooltipTrigger>
                                <TooltipContent className="bg-zinc-950 border-purple-500/20 text-purple-400 font-black text-[10px] uppercase tracking-widest">
                                    Succès: {formatBytes(guild.achievementBytes)}
                                </TooltipContent>
                            </Tooltip>
                        </TooltipProvider>
                    </div>
                </td>
                <td className="px-8 py-6 text-right">
                    <div className={cn("inline-flex items-center justify-center p-2 rounded-xl bg-white/5 transition-all", isExpanded && "bg-indigo-500 text-black shadow-lg shadow-indigo-500/20")}>
                        <ChevronRight className={cn("w-4 h-4 text-zinc-500 transition-all", isExpanded ? "rotate-90 text-black" : "group-hover/row:translate-x-1")} />
                    </div>
                </td>
            </tr>
            {isExpanded && (
                <tr className="bg-zinc-950 animate-in slide-in-from-top-2 duration-300">
                    <td colSpan={5} className="px-8 py-10">
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
                            <StorageMiniItem type="MISSION" count={guild.missionsCount} bytes={guild.missionsBytes} files={guild.missionsFiles} dir={guild.missionsDir} pendingFiles={guild.pendingFiles} onReload={onReload} />
                            <StorageMiniItem type="KAMA" count={guild.kamaCount} bytes={guild.kamaBytes} files={guild.kamaFiles} dir={guild.kamaDir} pendingFiles={guild.pendingFiles} onReload={onReload} />
                            <StorageMiniItem type="ACHIEVEMENT" count={guild.achievementCount} bytes={guild.achievementBytes} files={guild.achievementFiles} dir={guild.achievementDir} pendingFiles={guild.pendingFiles} onReload={onReload} />
                            <StorageMiniItem type="LOAN_PROOF" count={guild.loansProofsCount} bytes={guild.loansProofsBytes} files={guild.loansProofsFiles} dir={guild.loansProofsDir} pendingFiles={guild.pendingFiles} onReload={onReload} />
                            <StorageMiniItem type="PRESENTATION" count={guild.presentationCount} bytes={guild.presentationBytes} files={guild.presentationFiles} dir={guild.presentationDir} pendingFiles={guild.pendingFiles} onReload={onReload} />
                        </div>
                    </td>
                </tr>
            )}
        </>
    );
}

function Lightbox({ item, onClose, onDeleted }: { item: LightboxItem; onClose: () => void; onDeleted: () => void }) {
    const cfg = TYPE_CFG[item.type as keyof typeof TYPE_CFG] || TYPE_CFG.MISSION;
    const [isZoomed, setIsZoomed] = useState(false);
    
    return (
        <div className="fixed inset-0 z-[100] bg-black/95 backdrop-blur-xl flex flex-col p-4 md:p-8 animate-in fade-in duration-300">
            <div className="absolute inset-0" onClick={onClose} />
            <div className="relative w-full max-w-6xl mx-auto h-full flex flex-col space-y-6" onClick={e => e.stopPropagation()}>
                {/* Header pinned to top */}
                <div className="flex-none flex items-center justify-between px-2 md:px-6">
                    <div className="flex items-center gap-4">
                        <div className={cn("p-3 rounded-2xl hidden md:block", cfg.bg, cfg.color)}>
                            <ImageIcon className="w-6 h-6" />
                        </div>
                        <div>
                            <p className="text-sm md:text-xl font-black text-white uppercase tracking-tight truncate max-w-[200px] md:max-w-md">{item.filename}</p>
                            <p className="text-xs font-medium text-zinc-500">{formatBytes(item.sizeBytes || 0)} · {item.label}</p>
                        </div>
                    </div>
                    <div className="flex items-center gap-3">
                        <DeleteButton fileUrl={item.url} onDeleted={onDeleted} label="Supprimer Définitivement" />
                        <button onClick={onClose} className="p-3 shrink-0 text-zinc-500 hover:text-white transition-colors bg-white/5 rounded-2xl hover:bg-white/10">
                            <X className="w-5 h-5 md:w-6 md:h-6" />
                        </button>
                    </div>
                </div>
                
                {/* Image restricted to available height */}
                <div 
                    className={cn(
                        "flex-1 min-h-0 relative rounded-[2rem] bg-black/50 border border-white/5 shadow-2xl p-4 transition-all",
                        isZoomed ? "overflow-auto flex items-start justify-start cursor-zoom-out" : "overflow-hidden flex items-center justify-center text-center cursor-zoom-in"
                    )}
                    onClick={() => setIsZoomed(!isZoomed)}
                >
                    <img 
                        src={item.url} 
                        alt="Aperçu" 
                        className={cn(
                            "select-none transition-transform duration-300",
                            isZoomed ? "w-auto h-auto max-w-none max-h-none origin-top-left" : "max-h-full max-w-full object-contain"
                        )}
                        onError={(e) => {
                            e.currentTarget.style.display = 'none';
                            e.currentTarget.parentElement?.setAttribute('data-error', 'Image indisponible (404/403) ou corrompue');
                        }}
                    />
                    <style jsx>{`
                        div[data-error]::before {
                            content: attr(data-error);
                            color: #ef4444;
                            font-size: 14px;
                            font-weight: 900;
                            text-transform: uppercase;
                        }
                    `}</style>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useMemo, useEffect } from "react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Input } from "@/components/ui/input";
import { MonsterCard } from "./monster-card";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Progress } from "@/components/ui/progress";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue
} from "@/components/ui/select";
import { Search, AlertTriangle, Package, Gift, Bug, RefreshCw, MapPin, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Toggle } from "@/components/ui/toggle";
import {
    forceRefreshOcre,
    getGuildExchangeMap,
    type OcreProgressData,
    type GuildExchangeMapData,
} from "@/server/actions/ocre-actions";
import type { OcreMonster } from "@/lib/metamob-client";
import { toast } from "sonner";


interface ArchiHubProps {
    data: OcreProgressData;
    guildId: string;
}

export function ArchiHub({ data, guildId }: ArchiHubProps) {
    const [searchQuery, setSearchQuery] = useState("");
    const [selectedZone, setSelectedZone] = useState<string>("all");
    const [showExchangeableOnly, setShowExchangeableOnly] = useState(false);
    const [isRefreshing, setIsRefreshing] = useState(false);

    // Pre-loaded exchange availability map
    const [doublonsMap, setDoublonsMap] = useState<Record<number, number>>({});
    const [doublonsLoading, setDoublonsLoading] = useState(true);

    const loadDoublonsMap = async () => {
        setDoublonsLoading(true);
        const result = await getGuildExchangeMap(guildId);
        if (result.success && result.data) {
            setDoublonsMap(result.data.availableExchanges);
        }
        setDoublonsLoading(false);
    };

    // Load doublons map once on mount
    useEffect(() => {
        loadDoublonsMap();
    }, [guildId]);

    // Extract unique zones from monsters
    const zones = useMemo(() => {
        const uniqueZones = new Set<string>();
        data.monsters.forEach((m) => {
            if (m.zone) uniqueZones.add(m.zone);
        });
        return Array.from(uniqueZones).sort();
    }, [data.monsters]);

    // Categorize monsters
    const { manquants, possedes, doublons } = useMemo(() => {
        return {
            manquants: data.monsters.filter((m) => m.state === "MANQUANT"),
            possedes: data.monsters.filter((m) => m.state === "POSSEDE"),
            doublons: data.monsters.filter((m) => m.state === "DOUBLON"),
        };
    }, [data.monsters]);

    // Count monsters with available exchanges
    const monstersWithExchanges = useMemo(() => {
        return manquants.filter(m => doublonsMap[m.id] && doublonsMap[m.id] > 0).length;
    }, [manquants, doublonsMap]);

    // Filter monsters by search query, zone, and exchangeable
    const filterMonsters = (monsters: OcreMonster[], applyExchangeFilter = false) => {
        let filtered = monsters;

        // Filter by zone
        if (selectedZone !== "all") {
            filtered = filtered.filter((m) => m.zone === selectedZone);
        }

        // Filter by search query
        if (searchQuery.trim()) {
            const query = searchQuery.toLowerCase();
            filtered = filtered.filter(
                (m) =>
                    m.name.toLowerCase().includes(query) ||
                    (m.zone && m.zone.toLowerCase().includes(query)) ||
                    (m.subzone && m.subzone.toLowerCase().includes(query))
            );
        }

        // Filter exchangeable only (only for manquants tab)
        if (applyExchangeFilter && showExchangeableOnly) {
            filtered = filtered.filter(m => doublonsMap[m.id] && doublonsMap[m.id] > 0);
        }

        return filtered;
    };

    const handleRefresh = async () => {
        setIsRefreshing(true);
        const result = await forceRefreshOcre(guildId);
        if (result.success) {
            toast.success("Données actualisées ! Rechargez la page pour voir les changements.");
            // Also refresh the doublons map
            loadDoublonsMap();
        } else {
            toast.error(result.error || "Erreur lors du rafraîchissement");
        }
        setIsRefreshing(false);
    };

    const clearFilters = () => {
        setSearchQuery("");
        setSelectedZone("all");
        setShowExchangeableOnly(false);
    };

    const hasActiveFilters = searchQuery.trim() !== "" || selectedZone !== "all" || showExchangeableOnly;



    // Progress Calculation Helpers
    const getProgressColor = (current: number, total: number) => {
        if (current === total) return "bg-emerald-500";
        if (current > total * 0.7) return "bg-emerald-400";
        if (current > total * 0.3) return "bg-amber-400";
        return "bg-red-400";
    };

    const renderProgressBar = (label: string, category: { total: number; gathered: number }, max: number) => {
        const percent = Math.min(100, Math.round((category.gathered / max) * 100));
        return (
            <div className="space-y-1">
                <div className="flex items-center justify-between text-xs">
                    <span className="font-medium text-muted-foreground">{label}</span>
                    <span className="text-muted-foreground">
                        <span className={category.gathered === max ? "text-emerald-500 font-bold" : "text-foreground"}>
                            {category.gathered}
                        </span>
                        /{max}
                    </span>
                </div>
                <Progress value={percent} className="h-1.5" indicatorClassName={getProgressColor(category.gathered, max)} />
            </div>
        );
    };

    return (
        <div className="space-y-6">
            {/* Detailed Progress Section (Metamob Style) */}
            <Card className="border-border/50 bg-card/50 backdrop-blur-sm overflow-hidden">
                <CardContent className="p-6 space-y-4">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 rounded-full bg-amber-500/10 text-amber-500">
                            <span className="text-xl">🏆</span>
                        </div>
                        <div>
                            <h3 className="font-semibold text-lg">Quête de l'Éternelle Moisson</h3>
                            <p className="text-sm text-muted-foreground">Avancement détaillé par catégorie</p>
                        </div>
                    </div>

                    <div className="grid gap-6 md:grid-cols-3">
                        {renderProgressBar("Gardiens de Donjon", data.stats.bosses, data.stats.bosses.total)}
                        {renderProgressBar("Archimonstres", data.stats.archis, data.stats.archis.total)}
                    </div>
                </CardContent>
            </Card>

            {/* Stats Overview */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <StatCard
                    label="Gardiens & Archis"
                    value={data.stats.total}
                    icon={<Bug className="h-5 w-5" />}
                    color="text-primary"
                />
                <StatCard
                    label="Manquants"
                    value={manquants.length}
                    icon={<AlertTriangle className="h-5 w-5" />}
                    color="text-red-500"
                    subValue={!doublonsLoading && monstersWithExchanges > 0
                        ? `${monstersWithExchanges} échangeables`
                        : undefined
                    }
                    subColor="text-emerald-500"
                />
                <StatCard
                    label="Possédés"
                    value={possedes.length}
                    icon={<Package className="h-5 w-5" />}
                    color="text-emerald-500"
                />
                <StatCard
                    label="Doublons"
                    value={doublons.length}
                    icon={<Gift className="h-5 w-5" />}
                    color="text-amber-500"
                />
            </div>

            {/* Filters Bar */}
            <div className="flex flex-wrap items-center gap-3">
                {/* Search */}
                <div className="relative flex-1 min-w-[200px]">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                    <Input
                        placeholder="Rechercher un archimonstre..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="pl-10"
                    />
                </div>

                {/* Zone Filter */}
                <Select value={selectedZone} onValueChange={setSelectedZone}>
                    <SelectTrigger className="w-[180px]">
                        <MapPin className="h-4 w-4 mr-2 text-muted-foreground" />
                        <SelectValue placeholder="Toutes les zones" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">Toutes les zones</SelectItem>
                        {zones.map((zone) => (
                            <SelectItem key={zone} value={zone}>
                                {zone}
                            </SelectItem>
                        ))}
                    </SelectContent>
                </Select>

                {/* Exchangeable Only Toggle */}
                <Toggle
                    pressed={showExchangeableOnly}
                    onPressedChange={setShowExchangeableOnly}
                    className="gap-2 data-[state=on]:bg-emerald-600 data-[state=on]:text-white"
                    disabled={doublonsLoading || monstersWithExchanges === 0}
                >
                    <Sparkles className="h-4 w-4" />
                    <span className="hidden sm:inline">Échangeables</span>
                    {monstersWithExchanges > 0 && (
                        <Badge variant="secondary" className="h-5 px-1.5 text-xs">
                            {monstersWithExchanges}
                        </Badge>
                    )}
                </Toggle>

                {/* Clear Filters */}
                {hasActiveFilters && (
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={clearFilters}
                        className="text-muted-foreground hover:text-foreground"
                    >
                        Effacer
                    </Button>
                )}

                {/* Refresh */}
                <Button
                    variant="outline"
                    size="icon"
                    onClick={handleRefresh}
                    disabled={isRefreshing}
                >
                    <RefreshCw className={`h-4 w-4 ${isRefreshing ? "animate-spin" : ""}`} />
                </Button>
            </div>

            {/* Tabs */}
            <Tabs defaultValue="manquants" className="w-full">
                <TabsList className="grid w-full grid-cols-3">
                    <TabsTrigger value="manquants" className="gap-2">
                        <span className="hidden sm:inline">🔴</span>
                        Manquants
                        <Badge variant="secondary" className="ml-1 h-5 px-1.5">
                            {filterMonsters(manquants, true).length}
                        </Badge>
                    </TabsTrigger>
                    <TabsTrigger value="possedes" className="gap-2">
                        <span className="hidden sm:inline">🟢</span>
                        Possédés
                        <Badge variant="secondary" className="ml-1 h-5 px-1.5">
                            {filterMonsters(possedes).length}
                        </Badge>
                    </TabsTrigger>
                    <TabsTrigger value="doublons" className="gap-2">
                        <span className="hidden sm:inline">🟡</span>
                        Doublons
                        <Badge variant="secondary" className="ml-1 h-5 px-1.5">
                            {filterMonsters(doublons).length}
                        </Badge>
                    </TabsTrigger>
                </TabsList>

                <TabsContent value="manquants" className="mt-6">
                    <MonsterGrid
                        monsters={filterMonsters(manquants, true)}
                        guildId={guildId}
                        emptyMessage={hasActiveFilters
                            ? showExchangeableOnly
                                ? "Aucun monstre échangeable ne correspond aux filtres"
                                : "Aucun monstre manquant ne correspond aux filtres"
                            : "Vous avez tous les archimonstres ! 🎉"
                        }
                        showOwners
                        doublonsMap={doublonsMap}
                    />
                </TabsContent>

                <TabsContent value="possedes" className="mt-6">
                    <MonsterGrid
                        monsters={filterMonsters(possedes)}
                        guildId={guildId}
                        emptyMessage={hasActiveFilters
                            ? "Aucun monstre possédé ne correspond aux filtres"
                            : "Aucun archimonstre avec un seul exemplaire"
                        }
                        showOwners={false}
                        doublonsMap={{}}
                    />
                </TabsContent>

                <TabsContent value="doublons" className="mt-6">
                    <MonsterGrid
                        monsters={filterMonsters(doublons)}
                        guildId={guildId}
                        emptyMessage={hasActiveFilters
                            ? "Aucun doublon ne correspond aux filtres"
                            : "Vous n'avez pas de doublons à proposer"
                        }
                        showOwners={false}
