                    <div className="absolute inset-0 bg-gradient-to-br from-amber-500/5 via-transparent to-primary/5 pointer-events-none" />

                    <div className="relative flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                        <div className="flex items-center gap-5">
                            <div className="relative group shrink-0">
                                <div className="absolute inset-0 bg-gradient-to-br from-amber-500/20 to-orange-600/20 rounded-xl blur-lg group-hover:blur-xl transition-all opacity-70" />
                                <div className="relative h-12 w-12 md:h-14 md:w-14 rounded-xl bg-gradient-to-br from-amber-500/10 to-orange-600/10 flex items-center justify-center border border-amber-500/20 shrink-0">
                                    <CalendarIcon className="h-6 w-6 md:h-7 md:w-7 text-amber-500" />
                                </div>
                            </div>
                            <div className="min-w-0">
                                <h2 className="text-2xl md:text-3xl font-black italic uppercase tracking-tighter text-zinc-100 truncate">Agenda</h2>
                                <p className="text-zinc-500 font-bold text-xs md:text-sm mt-1">
                                    {filteredEvents.length} événements programmés
                                </p>
                            </div>
                        </div>

                        <div className="flex items-center gap-3">
                            <Button
                                variant="outline"
                                onClick={() => setShowFilters(!showFilters)}
                                className={cn(
                                    "h-10 rounded-full px-4 md:px-5 text-[10px] md:text-sm font-black uppercase italic tracking-widest transition-all border-2",
                                    (showFilters || selectedFilter !== "ALL")
                                        ? "bg-zinc-100 text-zinc-950 border-white shadow-xl scale-105"
                                        : "bg-zinc-900/50 text-zinc-400 border-zinc-800 hover:border-zinc-700 hover:text-zinc-200"
                                )}
                            >
                                <Filter className={cn("h-4 w-4 mr-2", selectedFilter !== "ALL" && "text-amber-500")} />
                                Filtres
                                {selectedFilter !== "ALL" && (
                                    <span className="ml-1 h-4 w-4 rounded-full bg-amber-500 text-zinc-950 text-[9px] font-black flex items-center justify-center">1</span>
                                )}
                            </Button>

                            {/* Conseil Raid button — visible for all members */}
                            <Button
                                variant="outline"
                                onClick={() => setIsRaidHubOpen(true)}
                                className="h-10 rounded-full px-4 text-[10px] md:text-sm font-black uppercase italic tracking-widest border-2 bg-red-500/10 text-red-400 border-red-500/30 hover:bg-red-500/20 hover:border-red-500/50 transition-all"
                            >
                                <Swords className="h-4 w-4 mr-2" />
                                Conseil Raid
                            </Button>

                            {canManage && (
                                <Button
                                    onClick={() => setIsCreateOpen(true)}
                                    className="h-10 px-5 rounded-full bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-400 hover:to-orange-400 text-zinc-950 font-bold shadow-lg shadow-amber-500/25 transition-all hover:shadow-amber-500/40 hover:scale-105"
                                >
                                    <Plus className="h-4 w-4 mr-2" />
                                    Nouvel évent
                                </Button>
                            )}
                        </div>
                    </div>
                </div>

                {/* Filters Bar (Improved Aesthetics) */}
                {showFilters && (
                    <div className="flex items-center gap-3 overflow-x-auto pb-4 scrollbar-hide animate-in slide-in-from-top-2 duration-300">
                        <button
                            onClick={() => setSelectedFilter("ALL")}
                            className={cn(
                                "flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-black uppercase italic tracking-widest transition-all border-2 whitespace-nowrap",
                                selectedFilter === "ALL"
                                    ? "bg-zinc-100 text-zinc-950 border-white shadow-xl"
                                    : "bg-zinc-900 text-zinc-500 border-zinc-800 hover:border-zinc-700 hover:text-zinc-300"
                            )}
                        >
                            Tous
                            <span className={cn(
                                "px-2 py-0.5 rounded-md text-[10px] font-black",
                                selectedFilter === "ALL" ? "bg-zinc-900 text-zinc-100" : "bg-zinc-800 text-zinc-500"
                            )}>
                                {events.length}
                            </span>
                        </button>

                        <div className="h-6 w-px bg-zinc-800 mx-1 shrink-0" />

                        {Object.entries(FILTER_TYPES).map(([type, config]) => {
                            const count = typeCounts[type] || 0;
                            const Icon = config.icon;
                            const isActive = selectedFilter === type;

                            return (
                                <button
                                    key={type}
                                    onClick={() => setSelectedFilter(isActive ? "ALL" : type)}
                                    className={cn(
                                        "flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-black uppercase italic tracking-widest transition-all border-2 whitespace-nowrap",
                                        isActive
                                            ? cn(config.bg, config.color, config.border, "shadow-lg scale-105 z-10")
                                            : "bg-zinc-900 text-zinc-500 border-zinc-800 hover:border-zinc-700 hover:text-zinc-300"
                                    )}
                                >
                                    <Icon className="h-4 w-4" />
                                    {config.label}
                                    <span className={cn(
                                        "px-2 py-0.5 rounded-md text-[10px] font-black",
                                        isActive ? "bg-current/20" : "bg-zinc-800 text-zinc-500"
                                    )}>
                                        {count}
                                    </span>
                                </button>
                            );
                        })}
                    </div>
                )}
            </div>

            {/* ============ ACTIVE PERIOD BANNER (FRESH & ELEGANT) ============ */}
            <div className="relative overflow-hidden rounded-2xl border border-white/[0.04] bg-[#0c1012]/60 backdrop-blur-xl p-5 shadow-[0_12px_40px_rgba(0,0,0,0.35)] flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
                {/* Decorative background ambient lights */}
                <div className="absolute -top-12 -left-12 w-48 h-48 bg-amber-500/10 rounded-full blur-[60px] pointer-events-none" />
                <div className="absolute -bottom-12 -right-12 w-48 h-48 bg-orange-500/10 rounded-full blur-[60px] pointer-events-none" />

                <div className="relative flex items-center gap-4">
                    <div className="h-11 w-11 rounded-xl bg-amber-500/10 flex items-center justify-center border border-amber-500/20 shrink-0">
                        <Sparkles className="h-5 w-5 text-amber-400" />
                    </div>
                    <div>
                        <h3 className="text-xl md:text-2xl font-black uppercase tracking-wider text-zinc-100 flex items-center gap-3">
                            <span className="bg-gradient-to-r from-zinc-100 via-amber-200 to-amber-400 bg-clip-text text-transparent">
                                {(() => {
                                    const monthStr = format(currentDate, "MMMM yyyy", { locale: fr });
                                    return monthStr.charAt(0).toUpperCase() + monthStr.slice(1);
                                })()}
                            </span>
                            {gridType === "week" && (
                                <Badge className="bg-amber-500/10 text-amber-400 border border-amber-500/20 text-[10px] font-black uppercase px-2 py-0.5 tracking-wider shrink-0">
                                    Semaine {format(currentDate, "I", { locale: fr })}
                                </Badge>
                            )}
                        </h3>
                        <p className="text-xs text-zinc-400 font-bold tracking-tight mt-0.5">
                            {gridType === "week" ? "Agenda hebdomadaire complet" : "Agenda mensuel de la guilde"}
                        </p>
                    </div>
                </div>

                <div className="relative flex items-center gap-3">
                    {/* Week/Month Toggle */}
                    <div className="flex bg-[#070b0c]/90 border border-white/5 rounded-xl p-1 shadow-inner">
                        <button
                            onClick={() => setGridType("week")}
                            className={cn(
                                "px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all",
                                gridType === "week" ? "bg-amber-500 text-zinc-950 shadow-lg" : "text-zinc-400 hover:text-zinc-200 hover:bg-white/5"
                            )}
                        >
                            Semaine
                        </button>
                        <button
                            onClick={() => setGridType("month")}
                            className={cn(
                                "px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all",
                                gridType === "month" ? "bg-amber-500 text-zinc-950 shadow-lg" : "text-zinc-400 hover:text-zinc-200 hover:bg-white/5"
                            )}
                        >
                            Mois
                        </button>
                    </div>

                    {/* Navigation Controls */}
                    <div className="flex bg-[#070b0c]/90 border border-white/5 rounded-xl p-1 shadow-inner">
                        <button
                            onClick={() => {
                                const date = gridType === "week" ? subWeeks(currentDate, 1) : subMonths(currentDate, 1);
                                setCurrentDate(date);
                            }}
                            className="p-2 hover:bg-white/5 rounded-lg transition-all active:scale-95"
                            title="Période précédente"
                        >
                            <ChevronLeft className="h-4.5 w-4.5 text-zinc-300" />
                        </button>
                        <button
                            onClick={() => setCurrentDate(new Date())}
                            className="px-4 py-1.5 text-xs font-black uppercase tracking-wider text-zinc-300 hover:text-white rounded-lg hover:bg-white/5 transition-all"
                        >
                            Aujourd'hui
                        </button>
                        <button
                            onClick={() => {
                                const date = gridType === "week" ? addWeeks(currentDate, 1) : addMonths(currentDate, 1);
                                setCurrentDate(date);
                            }}
                            className="p-2 hover:bg-white/5 rounded-lg transition-all active:scale-95"
                            title="Période suivante"
                        >
                            <ChevronRight className="h-4.5 w-4.5 text-zinc-300" />
                        </button>
                    </div>
                </div>
            </div>

            {/* ============ MAIN CONTENT AREA ============ */}
            <div className="min-h-[500px]">
                {loading ? (
                <div className="flex flex-col items-center justify-center py-24 space-y-4">
                    <div className="relative">
                        <div className="h-16 w-16 rounded-full bg-amber-500/10 flex items-center justify-center animate-pulse">
                            <CalendarIcon className="h-8 w-8 text-amber-500/50" />
                        </div>
                        <Loader2 className="absolute -top-1 -right-1 h-6 w-6 text-amber-500 animate-spin" />
                    </div>
                    <p className="text-zinc-400 text-sm animate-pulse">Chargement de l'agenda...</p>
                </div>
            ) : (
                // ============ GRID VIEW ============
                <CalendarGrid
                    events={filteredEvents}
                    currentDate={currentDate}
                    onDateChange={setCurrentDate}
                    onEventClick={handleEventClick}
                    onDayClick={handleDayClick}
                    canManage={canManage}
                    viewMode={gridType}
                    onViewModeChange={setGridType}
                />
            )}
        </div>

        <Dialog 
                open={isCreateOpen} 
                onOpenChange={(open) => {
                    setIsCreateOpen(open);
                    if (!open) setPrefilledDate(null);
                }}
            >
                <DialogContent draggable className="max-w-2xl max-h-[90vh] overflow-y-auto bg-zinc-950/98 border border-white/10 ring-1 ring-orange-500/25 shadow-[0_0_50px_rgba(249,115,22,0.2)]">
                    <DialogTitle className="text-xl font-black uppercase italic tracking-tighter text-foreground">
                        Créer un événement
                    </DialogTitle>
                    <DialogDescription className="text-muted-foreground font-bold">
                        Remplissez les informations pour créer un nouvel événement de guilde.
                    </DialogDescription>
                    <EventForm 
                        guildId={guildId}
                        onSubmit={handleCreate} 
                        isDiscordConfigured={isDiscordConfigured}
                        canManageRaid={canManageRaid}
                        userPseudo={userPseudo}
                        initialData={prefilledDate ? { startDate: prefilledDate } : undefined}
                        discordRoles={discordRoles}
                    />
                </DialogContent>
            </Dialog>

            {/* ============ DETAIL MODAL ============ */}
            <EventDetailModal
                event={selectedEvent}
                open={!!selectedEventId}
                onOpenChange={(open) => {
                    if (!open) {
                        setSelectedEventId(null);
                        // Optional: Clear URL param
                        const url = new URL(window.location.href);
                        url.searchParams.delete("event");
                        window.history.replaceState({}, "", url);
                    }
                }}
                currentUserId={currentUserId}
                guildId={guildId}
                canManage={canManage}
                isAdmin={isAdmin}
                isDiscordConfigured={isDiscordConfigured}
                discordRoles={discordRoles}
                everyoneAllowed={everyoneAllowed}
                hasMetamobKey={hasMetamobKey}
                raidEligibility={raidEligibility}
                onRegister={handleRegister}
                onUnregister={handleUnregister}
                onEdit={() => {
                    setEditingEvent(selectedEvent);
                    setSelectedEventId(null);
                }}
                onDelete={handleDelete}
                onCancel={handleCancel}
                onPublish={handlePublish}
                onComplete={handleComplete}
                onUndoComplete={handleUndoComplete}
                onSendReminder={handleSendReminder}
                onShareDiscord={handleShareDiscord}
            />

            {/* ============ RAID HUB MODAL ============ */}
            <RaidHubModal
                open={isRaidHubOpen}
                onOpenChange={setIsRaidHubOpen}
                guildId={guildId}
                isAdmin={isAdmin}
            />

            {/* ============ EDIT DIALOG ============ */}
            <Dialog open={!!editingEvent} onOpenChange={(open) => !open && setEditingEvent(null)}>
                <DialogContent draggable className="max-w-2xl max-h-[90vh] overflow-y-auto bg-zinc-950/98 border border-white/10 ring-1 ring-orange-500/25 shadow-[0_0_50px_rgba(249,115,22,0.2)]">
                    <DialogTitle className="text-xl font-black uppercase italic tracking-tighter text-foreground">
                        Modifier l'événement
                    </DialogTitle>
                    <DialogDescription className="text-muted-foreground font-bold">
                        Modifiez les informations de l'événement.
                    </DialogDescription>
                    {editingEvent && (
                        <EventForm
                            guildId={guildId}
                            initialData={editingEvent}
                            onSubmit={handleUpdate}
                            isDiscordConfigured={isDiscordConfigured}
                            canManageRaid={canManageRaid}
                            userPseudo={userPseudo}
                            discordRoles={discordRoles}
                        />
                    )}
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import { useState, useTransition } from "react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Loader2, Send, Share2, Bell, BellOff, AtSign, Check, Users } from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

interface DiscordRole {
    id: string;
    name: string;
    color?: number;
}

interface CalendarDiscordDialogProps {
    isOpen: boolean;
    onOpenChange: (open: boolean) => void;
    guildId: string;
    eventId: string;
    roles: DiscordRole[];
    everyoneAllowed?: boolean;
    mode: "REMINDER" | "SHARE";
    onConfirm: (roleId?: string | "everyone") => Promise<{ success: boolean; sentCount?: number; discordSent?: boolean; error?: string }>;
}

type PingType = "EVERYONE" | "ROLE" | "NONE";

export function CalendarDiscordDialog({
    isOpen,
    onOpenChange,
    guildId,
    eventId,
    roles,
    everyoneAllowed = false,
    mode,
    onConfirm
}: CalendarDiscordDialogProps) {
    const [pingType, setPingType] = useState<PingType>("NONE");
    const [selectedRoleId, setSelectedRoleId] = useState<string | null>(null);
    const [isPending, startTransition] = useTransition();

    const isReminder = mode === "REMINDER";

    const handleConfirm = () => {
        startTransition(async () => {
            const roleId = pingType === "EVERYONE" ? "everyone" : (pingType === "ROLE" ? selectedRoleId || undefined : undefined);
            const res = await onConfirm(roleId);

            if (res.success) {
                if (isReminder) {
                    let msg = `Rappel envoyé à ${res.sentCount} participants`;
                    if (res.discordSent) msg += " et publié sur Discord";
                    toast.success(msg);
                } else {
                    toast.success("Événement partagé sur Discord !");
                }
                onOpenChange(false);
            } else {
                toast.error(res.error || "Une erreur est survenue");
            }
        });
    };

    return (
        <Dialog open={isOpen} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-xs sm:max-w-sm bg-zinc-950 border-white/10 shadow-2xl rounded-2xl p-0 overflow-hidden outline-none">
                {/* Header */}
                <div className="px-5 pt-5 pb-4 border-b border-white/5">
                    <DialogHeader>
                        <DialogTitle className="text-base font-black text-white flex items-center gap-2.5">
                            <div className={cn(
                                "p-1.5 rounded-xl",
                                isReminder ? "bg-amber-500/20 text-amber-400" : "bg-indigo-500/20 text-indigo-400"
                            )}>
                                {isReminder ? <Bell className="w-4 h-4" /> : <Share2 className="w-4 h-4" />}
                            </div>
                            {isReminder ? "Envoyer un rappel" : "Partager sur Discord"}
                        </DialogTitle>
                        <DialogDescription className="text-zinc-500 text-xs mt-1">
                            {isReminder
                                ? "Notifiez les participants avec un ping optionnel."
                                : "Qui mentionner pour cette annonce d'événement ?"
                            }
                        </DialogDescription>
                    </DialogHeader>
                </div>

                <div className="px-5 py-4 space-y-4">
                    {/* Mode: 2 compact buttons */}
                    <div className={cn("grid gap-2", everyoneAllowed ? "grid-cols-2" : "grid-cols-1")}>
                        {/* Option 1: Sans ping / Participants seulement */}
                        <button
                            onClick={() => { setPingType("NONE"); setSelectedRoleId(null); }}
                            className={cn(
                                "flex items-center gap-2.5 p-3 rounded-xl border transition-all text-left",
                                pingType === "NONE"
                                    ? isReminder
                                        ? "bg-amber-500/10 border-amber-500/40 text-amber-300"
                                        : "bg-indigo-500/10 border-indigo-500/40 text-indigo-300"
                                    : "bg-zinc-900 border-white/5 text-zinc-400 hover:border-white/20 hover:text-zinc-200"
                            )}
                        >
                            {isReminder ? <Users className="w-4 h-4 shrink-0" /> : <BellOff className="w-4 h-4 shrink-0" />}
                            <div>
                                <div className="text-xs font-black">{isReminder ? "Participants" : "Sans ping"}</div>
                                <div className="text-[10px] text-zinc-600 font-medium">{isReminder ? "App seulement" : "Discret"}</div>
                            </div>
                            {pingType === "NONE" && <Check className={cn("w-3.5 h-3.5 ml-auto", isReminder ? "text-amber-400" : "text-indigo-400")} />}
                        </button>

                        {/* Option 2: @everyone — ONLY if whitelisted */}
                        {everyoneAllowed && (
                            <button
                                onClick={() => { setPingType("EVERYONE"); setSelectedRoleId(null); }}
                                className={cn(
                                    "flex items-center gap-2.5 p-3 rounded-xl border transition-all text-left",
                                    pingType === "EVERYONE"
                                        ? "bg-red-500/10 border-red-500/40 text-red-300"
                                        : "bg-zinc-900 border-white/5 text-zinc-400 hover:border-white/20 hover:text-zinc-200"
                                )}
                            >
                                <AtSign className="w-4 h-4 shrink-0" />
                                <div>
                                    <div className="text-xs font-black">@everyone</div>
                                    <div className="text-[10px] text-zinc-600 font-medium">{isReminder ? "App + Discord" : "Toute la guilde"}</div>
                                </div>
                                {pingType === "EVERYONE" && <Check className="w-3.5 h-3.5 ml-auto text-red-400" />}
                            </button>
                        )}
                    </div>

                    {/* Role list */}
                    <div>
                        <div className="flex items-center justify-between mb-2">
                            <span className="text-[10px] font-black uppercase tracking-wider text-zinc-500">Ou un rôle spécifique</span>
                            {selectedRoleId && (
                                <button
                                    onClick={() => { setSelectedRoleId(null); if (pingType === "ROLE") setPingType("NONE"); }}
                                    className={cn(
                                        "text-[10px] font-bold transition-colors",
                                        isReminder ? "text-amber-400 hover:text-amber-300" : "text-indigo-400 hover:text-indigo-300"
                                    )}
                                >
                                    Effacer
                                </button>
                            )}
                        </div>

                        <div className="bg-zinc-900/80 border border-white/5 rounded-xl overflow-hidden max-h-40 overflow-y-auto custom-scrollbar">
                            {roles.length === 0 ? (
                                <div className="py-6 text-center text-xs text-zinc-600">Aucun rôle trouvé</div>
                            ) : (
                                <div className="p-1.5 space-y-0.5">
                                    {roles.map(role => {
                                        const hex = role.color ? `#${role.color.toString(16).padStart(6, "0")}` : "#71717a";
                                        const isSelected = selectedRoleId === role.id;
                                        return (
                                            <button
                                                key={role.id}
                                                onClick={() => { setPingType("ROLE"); setSelectedRoleId(role.id); }}
                                                className={cn(
                                                    "w-full flex items-center gap-2.5 px-3 py-2 rounded-lg text-left transition-all",
                                                    isSelected
                                                        ? isReminder
                                                            ? "bg-amber-500/10 text-amber-100"
                                                            : "bg-indigo-500/10 text-indigo-100"
                                                        : "text-zinc-400 hover:bg-white/5 hover:text-zinc-200"
                                                )}
                                            >
                                                <span className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: hex }} />
                                                <span className="text-sm font-bold truncate flex-1">@{role.name}</span>
                                                {isSelected && (
                                                    <Check className={cn("w-3.5 h-3.5 shrink-0", isReminder ? "text-amber-400" : "text-indigo-400")} />
                                                )}
                                            </button>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                {/* Footer */}
                <div className="px-5 pb-5">
                    <Button
                        onClick={handleConfirm}
                        disabled={isPending}
                        className={cn(
                            "w-full h-10 font-black text-sm transition-all",
                            pingType === "EVERYONE"
                                ? "bg-red-600 hover:bg-red-500"
                                : isReminder
                                    ? "bg-amber-600 hover:bg-amber-500"
                                    : "bg-indigo-600 hover:bg-indigo-500"
                        )}
                    >
                        {isPending
                            ? <Loader2 className="w-4 h-4 animate-spin mr-2" />
                            : <Send className="w-4 h-4 mr-2" />
                        }
                        {isReminder ? "Envoyer le rappel" : "Envoyer sur Discord"}
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

/**
 * CalendarGrid V5 - BIGGER & CLEARER
 * Everything sized for comfortable reading
 */

import { useState, useMemo } from "react";
import {
    format,
    startOfWeek,
    endOfWeek,
    eachDayOfInterval,
    isToday,
    addWeeks,
    subWeeks,
    getWeek,
    startOfMonth,
    endOfMonth,
    addMonths,
    subMonths
} from "date-fns";
import { fr } from "date-fns/locale";
import {
    ChevronLeft,
    ChevronRight,
    Plus,
    Calendar as CalendarIcon,
    Users,
    Swords,
    PartyPopper,
    Target,
    Wheat,
    CalendarDays,
    LayoutGrid,
    Eye
} from "lucide-react";
import { Button } from "@/components/ui/button";
import {
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

// ============================================
// 4 EVENT TYPES
// ============================================

interface TypeConfig {
    label: string;
    icon: React.ElementType;
    color: string;
    bg: string;
    border: string;
    dot: string;
}

const TYPE_CONFIG: Record<string, TypeConfig> = {
    RAID_OFFICIAL: {
        label: "Raid 3.6",
        icon: Swords,
        color: "text-red-400",
        bg: "bg-red-500/15",
        border: "border-red-500/40",
        dot: "bg-red-500"
    },
    EVENT_GUILD: {
        label: "Event Guilde",
        icon: PartyPopper,
        color: "text-purple-400",
        bg: "bg-purple-500/15",
        border: "border-purple-500/40",
        dot: "bg-purple-500"
    },
    SESSION_MISSIONS: {
        label: "Missions Guilde",
        icon: Target,
        color: "text-amber-400",
        bg: "bg-amber-500/15",
        border: "border-amber-500/40",
        dot: "bg-amber-500"
    },
    SORTIE_FARM: {
        label: "Sortie Farm",
        icon: Wheat,
        color: "text-emerald-400",
        bg: "bg-emerald-500/15",
        border: "border-emerald-500/40",
        dot: "bg-emerald-500"
    },
    KRALAMOURE: {
        label: "Kralamoure",
        icon: Eye,
        color: "text-pink-400",
        bg: "bg-pink-500/15",
        border: "border-pink-500/40",
        dot: "bg-pink-500"
    },
};

// ============================================
// INTERFACES
// ============================================

interface CalendarEvent {
    id: string;
    title: string;
    type: string;
    status: string;
    startDate: Date | string;
    endDate: Date | string;
    maxParticipants?: number | null;
    _count?: { participants: number };
}

type ViewMode = "week" | "month";

interface CalendarGridProps {
    events: CalendarEvent[];
    currentDate: Date;
    onDateChange: (date: Date) => void;
    onEventClick: (eventId: string) => void;
    onDayClick?: (date: Date) => void;
    canManage?: boolean;
    viewMode: ViewMode;
    onViewModeChange: (mode: ViewMode) => void;
}

// ============================================
// COMPONENT
// ============================================

export function CalendarGrid({
    events,
    currentDate,
    onDateChange,
    onEventClick,
    onDayClick,
    canManage = false,
    viewMode,
    onViewModeChange
}: CalendarGridProps) {
    // Calendar days



    // Calendar days
    const calendarDays = useMemo(() => {
        if (viewMode === "week") {
            const weekStart = startOfWeek(currentDate, { weekStartsOn: 1 });
            const weekEnd = endOfWeek(currentDate, { weekStartsOn: 1 });
            return eachDayOfInterval({ start: weekStart, end: weekEnd });
        } else {
            const monthStart = startOfMonth(currentDate);
            const monthEnd = endOfMonth(currentDate);
            const calendarStart = startOfWeek(monthStart, { weekStartsOn: 1 });
            const calendarEnd = endOfWeek(monthEnd, { weekStartsOn: 1 });
            return eachDayOfInterval({ start: calendarStart, end: calendarEnd });
        }
    }, [currentDate, viewMode]);

    // Events by day
    const eventsByDay = useMemo(() => {
        const map = new Map<string, CalendarEvent[]>();
        events.forEach(event => {
            const eventDate = new Date(event.startDate);
            const key = format(eventDate, "yyyy-MM-dd");
            const existing = map.get(key) || [];
            map.set(key, [...existing, event]);
        });
        return map;
    }, [events]);



    const handlePrev = () => {
        if (viewMode === "week") onDateChange(subWeeks(currentDate, 1));
        else onDateChange(subMonths(currentDate, 1));
    };

    const handleNext = () => {
        if (viewMode === "week") onDateChange(addWeeks(currentDate, 1));
        else onDateChange(addMonths(currentDate, 1));
    };

    const weekDays = ["LUN", "MAR", "MER", "JEU", "VEN", "SAM", "DIM"];
    const currentWeek = getWeek(currentDate, { weekStartsOn: 1 });

    return (
        <div className="space-y-6">
            {/* ============ CALENDAR GRID ============ */}
            <div className="rounded-2xl border border-white/[0.08] bg-[#0d1214] overflow-hidden shadow-[0_24px_64px_rgba(0,0,0,0.7)] relative">
                {/* Subtle top ambient glow inside the grid */}
                <div className="absolute top-0 left-1/4 right-1/4 h-[1px] bg-gradient-to-r from-transparent via-amber-500/40 to-transparent pointer-events-none" />

                {/* Days Header - BOLDER, HIGHER CONTRAST & SLATE BACKED */}
                <div className="grid grid-cols-7 bg-[#1c262a] border-b-2 border-white/[0.08]">
                    {weekDays.map((day, i) => (
                        <div key={day} className={cn(
                            "py-4 text-center text-xs font-black tracking-widest uppercase",
                            i >= 5 ? "text-amber-400" : "text-zinc-100"
                        )}>
                            {day}
                        </div>
                    ))}
                </div>

                {/* Days Grid */}
                <div className="grid grid-cols-7 bg-[#0b0e10]">
                    {calendarDays.map((day, index) => {
                        const dayKey = format(day, "yyyy-MM-dd");
                        const dayEvents = eventsByDay.get(dayKey) || [];
                        const isCurrentDay = isToday(day);
                        const isWeekend = index % 7 >= 5;
                        const minHeight = viewMode === "week" ? "min-h-[190px]" : "min-h-[130px]";
                        const maxEvents = viewMode === "week" ? 4 : 2;

                        return (
                            <div
                                key={dayKey}
                                className={cn(
                                    "group relative border-b border-r border-white/[0.07] p-0 transition-all duration-300 flex flex-col",
                                    minHeight,
                                    canManage ? "cursor-pointer" : "cursor-default",
                                    isWeekend 
                                        ? "bg-[#111618] hover:bg-[#161c1f]" 
                                        : "bg-[#151c1f] hover:bg-[#1a2327]",
                                    index % 7 === 6 && "border-r-0"
                                )}
                                onClick={(e) => {
                                    // Only trigger if we clicked the cell itself, not an event button
                                    if (canManage && onDayClick) {
                                        onDayClick(day);
                                    }
                                }}
                            >
                                {/* Premium Today Highlight Box with High Contrast Amber Border */}
                                {isCurrentDay && (
                                    <div className="absolute inset-0 border-2 border-amber-500 bg-amber-500/[0.06] pointer-events-none shadow-[inset_0_0_24px_rgba(245,158,11,0.1)] z-10" />
                                )}

                                <div className="p-3.5 flex-1 flex flex-col relative z-20">
                                    {/* Day Number - BIGGER & BRIGHTER */}
                                    <div className="flex items-center justify-between mb-3">
                                        <span className={cn(
                                            "h-9 w-9 flex items-center justify-center rounded-xl text-sm font-black transition-all duration-300",
                                            isCurrentDay
                                                ? "bg-gradient-to-r from-amber-400 to-amber-600 text-zinc-950 shadow-[0_4px_16px_rgba(245,158,11,0.5)] scale-105"
                                                : "text-zinc-100 group-hover:text-amber-400 group-hover:scale-110"
                                        )}>
                                            {format(day, "d")}
                                        </span>
                                        {dayEvents.length > maxEvents && (
                                            <span className="text-xs text-zinc-300 font-extrabold bg-[#0d1214] border border-white/10 px-2 py-0.5 rounded-full">
                                                +{dayEvents.length - maxEvents}
                                            </span>
                                        )}
                                    </div>

                                    {/* Events - BIGGER PILLS */}
                                    <div className="space-y-2 mt-auto">
                                        {dayEvents.slice(0, maxEvents).map((event) => {
                                            const start = event.startDate ? new Date(event.startDate) : null;
                                            if (!start || isNaN(start.getTime())) return null;

                                            const config = TYPE_CONFIG[event.type] || TYPE_CONFIG.EVENT_GUILD;
                                            const Icon = config.icon;
                                            const time = format(start, "HH:mm");

                                            return (
                                                <TooltipProvider key={event.id}>
                                                    <Tooltip delayDuration={100}>
                                                        <TooltipTrigger asChild>
                                                            <button
                                                                onClick={(e) => {
                                                                    e.stopPropagation();
                                                                    onEventClick(event.id);
                                                                }}
                                                                className={cn(
                                                                    "w-full group/btn relative flex items-center gap-2.5 px-3 py-2 rounded-xl text-xs font-bold transition-all text-left",
                                                                    "bg-zinc-950/70 backdrop-blur-md border border-white/[0.06]",
                                                                    "hover:bg-[#1c262a] hover:border-white/15 hover:shadow-xl hover:shadow-black/50 hover:-translate-y-0.5",
                                                                    "active:scale-[0.98] active:translate-y-0"
                                                                )}
                                                            >
                                                                {/* Side Accent Line */}
                                                                <div className={cn("absolute left-0 top-1.5 bottom-1.5 w-0.75 rounded-r-full transition-all group-hover/btn:top-1 group-hover/btn:bottom-1", config.dot)} />
                                                                
                                                                <div className={cn("h-7 w-7 rounded-lg flex items-center justify-center shrink-0 border border-white/5", config.bg)}>
                                                                    <Icon className={cn("h-3.5 w-3.5", config.color)} />
                                                                </div>
                                                                
                                                                <div className="flex flex-col min-w-0">
                                                                    <span className="text-[9px] font-black uppercase tracking-wider opacity-60 leading-none mb-0.5">
                                                                        {time}
                                                                    </span>
                                                                    <span className="truncate text-zinc-200 group-hover/btn:text-white transition-colors">
                                                                        {event.title}
                                                                    </span>
                                                                </div>
                                                            </button>
                                                        </TooltipTrigger>
                                                        <TooltipContent
                                                            side="right"
                                                            className="bg-[#0e1417] border-white/10 p-3.5 max-w-[240px] shadow-2xl rounded-xl backdrop-blur-xl"
                                                        >
                                                            <p className="font-extrabold text-zinc-100 text-sm tracking-tight">{event.title}</p>
                                                            <p className="text-xs text-zinc-400 mt-1 font-medium">
                                                                {time} → {format(new Date(event.endDate), "HH:mm")}
                                                            </p>
                                                            {event._count && (
                                                                <div className="flex items-center gap-1.5 mt-2.5 text-xs text-zinc-500 font-bold">
                                                                    <Users className="h-3.5 w-3.5" />
                                                                    {event._count.participants}
                                                                    {event.maxParticipants && ` / ${event.maxParticipants}`}
                                                                </div>
                                                            )}
                                                        </TooltipContent>
                                                    </Tooltip>
                                                </TooltipProvider>
                                            );
                                        })}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* ============ LEGEND (BIG & FRESH) ============ */}
            <div className="flex flex-wrap items-center justify-center gap-4 py-4 bg-[#0a0f12]/40 border border-white/[0.03] rounded-2xl backdrop-blur-md px-6 shadow-inner">
                {Object.entries(TYPE_CONFIG).map(([type, config]) => (
                    <div key={type} className="flex items-center gap-2.5 px-3 py-1.5 rounded-xl bg-white/[0.02] border border-white/[0.03] hover:border-white/[0.06] hover:bg-white/[0.03] transition-all">
                        <div className={cn("h-2.5 w-2.5 rounded-full shadow-[0_0_8px_currentColor]", config.dot)} />
                        <span className="text-xs font-bold text-zinc-400 tracking-wide">{config.label}</span>
                    </div>
                ))}
            </div>
        </div>
    );
}

"use client";

import { format } from "date-fns";
import { fr } from "date-fns/locale";
import {
    Users,
    MapPin,
    Calendar,
    Clock,
    CheckCircle2,
    HelpCircle,
    XCircle,
    Trash2,
    Edit,
    Target,
    Swords,
    PartyPopper,
    Wheat,
    Eye,
    Diamond
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle, CardFooter } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Separator } from "@/components/ui/separator";
import {
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

// Local type definitions
type AttendeeStatus = "GOING" | "MAYBE" | "DECLINED";

interface EventCardProps {
    event: any; // Using any for now to handle Prisma includes
    currentUserId: string;
    onRespond: (status: AttendeeStatus) => void;
    onEdit?: () => void;
    onDelete?: () => void;
    canManage: boolean;
}

const TYPE_THEMES: Record<string, { label: string; color: string; bg: string; border: string; icon: any; gradient: string }> = {
    RAID_OFFICIAL: { label: "Raid 3.6", color: "text-red-400", bg: "bg-red-500/10", border: "border-red-500/20", icon: Swords, gradient: "from-red-600 to-rose-600" },
    EVENT_GUILD: { label: "Event Guilde", color: "text-purple-400", bg: "bg-purple-500/10", border: "border-purple-500/20", icon: PartyPopper, gradient: "from-purple-600 to-fuchsia-600" },
    SESSION_MISSIONS: { label: "Missions Guilde", color: "text-amber-400", bg: "bg-amber-500/10", border: "border-amber-500/20", icon: Target, gradient: "from-amber-600 to-orange-600" },
    SORTIE_FARM: { label: "Sortie Farm", color: "text-emerald-400", bg: "bg-emerald-500/10", border: "border-emerald-500/20", icon: Wheat, gradient: "from-emerald-600 to-green-600" },
    KRALAMOURE: { label: "Kralamoure", color: "text-pink-400", bg: "bg-pink-500/10", border: "border-pink-500/20", icon: Eye, gradient: "from-pink-600 to-rose-600" },
    OTHERS: { label: "Autres", color: "text-slate-400", bg: "bg-slate-500/10", border: "border-slate-500/20", icon: Diamond, gradient: "from-slate-600 to-zinc-600" },
};

const EVENT_IMAGES: Record<string, string> = {
    "RAID_OFFICIAL": "/assets/calendar/calendar_raid_official.png",
    EVENT_GUILD: "/assets/calendar/calendar_event_guild.png",
    SESSION_MISSIONS: "/assets/calendar/calendar_session_missions.png",
    SORTIE_FARM: "/assets/calendar/calendar_boss_farm.png",
    KRALAMOURE: "/assets/calendar/calendar_kralamour.png",
    "GUILD_MISSION": "/assets/calendar/calendar_session_missions.png", // Fallback
    "SONGES_RUN": "/assets/calendar/calendar_songes_run.png",
    "DUNGEON_FARM": "/assets/calendar/calendar_dungeon_farm.png",
    "SOCIAL": "/assets/calendar/calendar_social.png",
    "ALMANAX_BONUS": "/assets/calendar/calendar_almanax_bonus.png",
    "OTHERS": "/assets/calendar/calendar_autres.png",
};

export function EventCard({
    event,
    currentUserId,
    onRespond,
    onEdit,
    onDelete,
    canManage,
    variant = "card"
}: EventCardProps & { variant?: "card" | "list" }) {
    const startDate = event.startDate ? new Date(event.startDate) : null;
    const endDate = event.endDate ? new Date(event.endDate) : (startDate || new Date());
    
    if (!startDate || isNaN(startDate.getTime())) return null;
    const validEndDate = (endDate && !isNaN(new Date(endDate).getTime())) ? new Date(endDate) : startDate;

    const theme = TYPE_THEMES[event.type] || TYPE_THEMES.SESSION_MISSIONS;
    const Icon = theme.icon;

    const myAttendance = event.participants?.find((a: any) => a.userId === currentUserId);
    const attendeeCount = event.participants?.length || 0;

    // Extract Metamob creator for Kralamoure events
    const isKralamoure = event.type === "KRALAMOURE";
    const eventMetadata = (event as any).metadata as any;
    const displayCreatorName = isKralamoure && eventMetadata?.metamobCreator
        ? eventMetadata.metamobCreator
        : event.creator?.name || "Inconnu";

    // For Kralamoure events, use Metamob participants from metadata
    // For other events, filter by REGISTERED status
    const metamobParticipants = isKralamoure && eventMetadata?.metamobParticipants
        ? eventMetadata.metamobParticipants
        : [];

    const attendeesGoing = isKralamoure
        ? metamobParticipants
        : (event.participants?.filter((a: any) => a.status === "REGISTERED") || []);

    // Override attendee count for Kralamoure events using metadata count if available
    const displayAttendeeCount = isKralamoure 
        ? (eventMetadata?.metamobParticipantsCount || attendeesGoing.length) 
        : (event.participants?.length || 0);

    // View: List (Horizontal Row)
    if (variant === "list") {
        return (
            <div className="group relative flex items-center gap-4 rounded-xl border border-zinc-800 bg-zinc-900/40 p-3 transition-all hover:bg-zinc-900/60 hover:border-zinc-700 hover:shadow-lg hover:shadow-black/20">
                {/* Left Accent Bar */}
                <div className={cn("absolute left-0 top-3 bottom-3 w-1 rounded-r-full opacity-60 group-hover:opacity-100 transition-opacity", theme.bg.replace("/10", "/80"))} />

                {/* Date Box */}
                <div className="flex h-14 w-14 shrink-0 flex-col items-center justify-center rounded-lg border border-zinc-800 bg-zinc-950/50 ml-2">
                    <span className="text-[10px] font-medium uppercase text-zinc-500">{format(startDate, "MMM", { locale: fr })}</span>
                    <span className="text-xl font-bold text-zinc-200">{format(startDate, "dd")}</span>
                </div>

                {/* Info Main */}
                <div className="mr-auto min-w-0 flex-1 space-y-1">
                    <div className="flex items-center gap-2">
                        <Badge variant="outline" className={cn("h-5 px-1.5 text-[10px] font-medium border-0", theme.bg, theme.color)}>
                            <Icon className="mr-1 h-3 w-3" />
                            {theme.label}
                        </Badge>
                        <div className="flex items-center gap-1 text-xs text-zinc-500">
                            <Clock className="h-3 w-3" />
                            <span>{format(startDate, "HH:mm")} - {format(validEndDate, "HH:mm")}</span>
                        </div>
                    </div>
                    <h3 className="text-base font-bold text-zinc-100 group-hover:text-amber-400 transition-colors line-clamp-2 leading-tight">
                        {event.title}
                    </h3>
                    <div className="flex items-center gap-4 text-xs text-zinc-400">
                        <div className="flex items-center gap-1.5">
                            <Users className="h-3.5 w-3.5 text-zinc-500" />
                            <span>{attendeeCount}{event.maxParticipants ? ` / ${event.maxParticipants}` : ""} participants</span>
                        </div>
                        {event.location && (
                            <div className="flex items-center gap-1.5 truncate max-w-[200px]">
                                <MapPin className="h-3.5 w-3.5 text-zinc-500" />
                                <span className="truncate">{event.location}</span>
                            </div>
                        )}
                    </div>
                </div>

                {/* Attendees Avatars (Hidden on very small screens) */}
                <div className="hidden md:flex items-center -space-x-2 mr-4">
                    {event.attendees?.slice(0, 4).map((a: any) => (
                        <div key={a.id} className="h-8 w-8 rounded-full border-2 border-zinc-900 bg-zinc-800 overflow-hidden" title={a.user.name}>
                            {a.user.image ? (
                                <img src={a.user.image} alt={a.user.name} className="h-full w-full object-cover" />
                            ) : (
                                <div className="h-full w-full flex items-center justify-center text-[10px] text-zinc-400">{a.user.name?.[0]}</div>
                            )}
                        </div>
                    ))}
                    {attendeeCount > 4 && (
                        <div className="h-8 w-8 rounded-full border-2 border-zinc-900 bg-zinc-800 flex items-center justify-center text-[10px] font-bold text-zinc-400">
                            +{attendeeCount - 4}
                        </div>
                    )}
                </div>

                {/* Actions */}
                <div className="flex items-center gap-1">
                    {/* Can manage actions would go here (hidden in list usually, handled by parent) */}
                    <div className={cn(
                        "h-2 w-2 rounded-full",
                        myAttendance?.status === "GOING" ? "bg-green-500" :
                            myAttendance?.status === "MAYBE" ? "bg-amber-500" : "bg-zinc-800"
                    )} title={myAttendance?.status ? "Inscrit" : "Non inscrit"} />
                </div>
            </div>
        );
    }

    // View: Card (Vertical) - Modernized

    return (
        <Card className="h-full flex flex-col group relative overflow-hidden transition-all duration-300 hover:-translate-y-1 hover:shadow-xl border-zinc-800/50 bg-zinc-900/40 hover:bg-zinc-900/60 hover:border-zinc-700/50">
            {/* Top Image Background */}
            <div className="absolute top-0 left-0 right-0 h-32 overflow-hidden opacity-40 mask-image-gradient">
                <div className="absolute inset-0 bg-gradient-to-b from-transparent to-zinc-900/90 z-10" />
                <img
                    src={EVENT_IMAGES[event.type] || EVENT_IMAGES["EVENT_GUILD"]}
                    alt="Event type"
                    className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500 transform group-hover:scale-105"
                />
            </div>

            {/* Top Accent Line */}
            <div className={cn("h-1.5 w-full bg-gradient-to-r opacity-90 relative z-20", theme.gradient)} />

            <CardHeader className="p-5 flex-none space-y-4 pb-2">
                <div className="flex justify-between items-start gap-4">
                    <div className="flex items-center gap-2">
                        <Badge variant="outline" className={cn("rounded-md px-2.5 py-1 text-sm font-semibold border-opacity-50 transition-colors", theme.bg, theme.color, theme.border)}>
                            <Icon className="w-4 h-4 mr-2" />
                            {theme.label}
                        </Badge>

                        {/* Completed Event Badge */}
                        {event.status === "COMPLETED" && (
                            <Badge className="bg-zinc-700/50 text-zinc-300 border-zinc-600 px-2 py-0.5 text-xs font-semibold uppercase tracking-wider">
                                Terminé
                            </Badge>
                        )}
                    </div>

                    {/* Attendance Status Indicator */}
                    {myAttendance && (
                        <TooltipProvider>
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <div className={cn(
                                        "h-3 w-3 rounded-full ring-2 ring-zinc-950 shadow-lg",
                                        myAttendance.status === "REGISTERED" && "bg-green-500 shadow-green-500/50",
                                        myAttendance.status === "MAYBE" && "bg-amber-500 shadow-amber-500/50",
                                        myAttendance.status === "DECLINED" && "bg-red-500 shadow-red-500/50"
                                    )} />
                                </TooltipTrigger>
                                <TooltipContent className="bg-zinc-950 border-zinc-800 text-sm">
                                    <p>{myAttendance.status === "REGISTERED" ? "Vous participez" : myAttendance.status === "MAYBE" ? "Peut-être" : "Vous ne venez pas"}</p>
                                </TooltipContent>
                            </Tooltip>
                        </TooltipProvider>
                    )}
                </div>

                <div className="space-y-1">
                    <CardTitle className="text-xl font-bold text-zinc-100 leading-tight group-hover:text-white transition-colors line-clamp-2 min-h-[1.75rem] break-words">
                        {event.title}
                    </CardTitle>
                </div>
            </CardHeader>

            <CardContent className="p-5 pt-2 flex-1 space-y-5">
                {/* Info Grid */}
                <div className="space-y-3">
                    <div className="flex items-center text-base text-zinc-400 group-hover:text-zinc-300 transition-colors">
                        <Calendar className="w-5 h-5 mr-3 text-zinc-500 shrink-0" />
                        <span className="capitalize font-medium">
                            {format(startDate, "EEEE d MMMM", { locale: fr })}
                        </span>
                    </div>
                    <div className="flex items-center text-base text-zinc-400 group-hover:text-zinc-300 transition-colors">
                        <Clock className="w-5 h-5 mr-3 text-zinc-500 shrink-0" />
                        <span>
                            {format(startDate, "HH:mm")} - {format(validEndDate, "HH:mm")}
                        </span>
                    </div>
                    {event.location && (
                        <div className="flex items-center text-base text-zinc-400 group-hover:text-zinc-300 transition-colors">
                            <MapPin className="w-5 h-5 mr-3 text-zinc-500 shrink-0" />
                            <span className="truncate">{event.location}</span>
                        </div>
                    )}
                </div>

                <Separator className="bg-zinc-800/50" />

                {/* Creator */}
                {event.creator && (
                    <div className="flex items-center gap-3">
                        <Avatar className="h-8 w-8 ring-1 ring-zinc-800">
                            <AvatarImage src={event.creator.image} />
                            <AvatarFallback className="text-xs bg-zinc-800 text-zinc-400">
                                {event.creator.name?.[0]?.toUpperCase() || "?"}
                            </AvatarFallback>
                        </Avatar>
                        <div className="flex flex-col">
                            <span className="text-[11px] text-zinc-500 uppercase tracking-wider font-semibold">Organisé par</span>
                            <span className={cn("text-sm font-medium transition-colors", theme.color)}>{displayCreatorName}</span>
                        </div>
                    </div>
                )}
            </CardContent>

            <CardFooter className="p-5 pt-0 mt-auto">
                <div className="w-full flex flex-col gap-2 p-3 rounded-lg bg-zinc-950/30 border border-zinc-800/30 transition-colors hover:bg-zinc-950/50">
                    <div className="flex items-center justify-between mb-1">
                        <span className="text-[10px] font-semibold text-zinc-500 uppercase tracking-wider">Participants</span>
                        <div className="flex items-center text-xs font-medium text-zinc-500">
                            <Users className="w-3 h-3 mr-1.5" />
                            {displayAttendeeCount}
                            {event.maxParticipants && <span className="mx-0.5 opacity-50">/</span>}
                            {event.maxParticipants && <span>{event.maxParticipants}</span>}
                        </div>
                    </div>

                    <div className="flex flex-col gap-2">
                        {attendeesGoing.length > 0 ? (
                            attendeesGoing.slice(0, 3).map((a: any, idx: number) => {
                                // For Kralamoure events, participants are objects { username, character_count } or strings
                                // For other events, participants have user objects
                                const participantName = isKralamoure
                                    ? (typeof a === 'string' ? a : a.username || a.name || 'Inconnu')
                                    : (a.user?.profiles?.[0]?.discordNickname || a.user?.name || 'Inconnu');
                                const participantInitial = participantName?.[0]?.toUpperCase() || '?';

                                return (
                                    <div key={isKralamoure ? `${idx}-${participantName}` : a.id} className="flex items-center gap-2.5">
                                        <Avatar className="h-6 w-6 border border-zinc-700/50 shadow-sm relative z-0">
                                            {!isKralamoure && a.user?.image && <AvatarImage src={a.user.image} />}
                                            <AvatarFallback className="text-[9px] bg-zinc-800 text-zinc-400">
                                                {participantInitial}
                                            </AvatarFallback>
                                        </Avatar>
                                        <span className="text-sm text-zinc-300 font-medium truncate">
                                            {participantName}
                                        </span>
                                    </div>
                                );
                            })
                        ) : (
                            <span className="text-sm text-zinc-600 italic">Aucun participant</span>
                        )}

                        {attendeesGoing.length > 3 && (
                            <div className="pl-9 text-xs text-zinc-500 font-medium">
                                +{attendeesGoing.length - 3} autres...
                            </div>
                        )}
                    </div>
                </div>
            </CardFooter>
        </Card>
    );
}

"use client";

/**
 * EventDetailModal V3 - 4 Types + Native ClassIcon
 */

import { useState, useEffect } from "react";
import { format } from "date-fns";
import { fr } from "date-fns/locale";
import Image from "next/image";
import Link from "next/link";
import {
    Calendar,
    Clock,
    Users,
    User,
    Crown,
    Trash2,
    Edit,
    Check,
    X,
    Loader2,
    Swords,
    PartyPopper,
    Target,
    Wheat,
    Bell,
    Share2,
    ChevronDown,
    AtSign,
    ExternalLink,
    Eye,
    Globe,
    Lock,
    Shield,
    Trophy,
    Star,
    Coins,
    AlertTriangle,
} from "lucide-react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogClose,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Separator } from "@/components/ui/separator";
import {
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { ClassIcon, getClassColor } from "@/components/shared/class-icon";
import { RegistrationModal } from "./registration-modal";
import { CalendarDiscordDialog } from "./calendar-discord-dialog";
import { getMissionsByIds } from "@/server/actions/mission-actions";
import { kickParticipant } from "@/server/actions/calendar-actions";
import { Skull, Zap, Clock as ClockIcon, Infinity as InfinityIcon, Sparkles as SparklesIcon } from "lucide-react";

// ============================================
// 4 EVENT TYPES
// ============================================

interface TypeConfig {
    label: string;
    icon: React.ElementType;
    color: string;
    bgColor: string;
    gradient: string;
}

const TYPE_CONFIG: Record<string, TypeConfig> = {
    RAID_OFFICIAL: {
        label: "Raid 3.6",
        icon: Swords,
        color: "text-red-400",
        bgColor: "bg-red-500/10 border-red-500/30",
        gradient: "from-red-600 to-rose-600"
    },
    EVENT_GUILD: {
        label: "Event Guilde",
        icon: PartyPopper,
        color: "text-purple-400",
        bgColor: "bg-purple-500/10 border-purple-500/30",
        gradient: "from-purple-600 to-fuchsia-600"
    },
    SESSION_MISSIONS: {
        label: "Missions Guilde",
        icon: Target,
        color: "text-amber-400",
        bgColor: "bg-amber-500/10 border-amber-500/30",
        gradient: "from-amber-600 to-orange-600"
    },
    SORTIE_FARM: {
        label: "Sortie Farm",
        icon: Wheat,
        color: "text-emerald-400",
        bgColor: "bg-emerald-500/10 border-emerald-500/30",
        gradient: "from-emerald-600 to-green-600"
    },
    KRALAMOURE: {
        label: "Kralamoure",
        icon: Eye,
        color: "text-pink-400",
        bgColor: "bg-pink-500/10 border-pink-500/30",
        gradient: "from-pink-600 to-rose-600"
    },
};

const STATUS_CONFIG: Record<string, { label: string; color: string; bg: string }> = {
    DRAFT: { label: "Brouillon", color: "text-zinc-400", bg: "bg-zinc-600" },
    PUBLISHED: { label: "Ouvert", color: "text-green-400", bg: "bg-green-600" },
    COMPLETED: { label: "Terminé", color: "text-blue-400", bg: "bg-blue-600" },
    CANCELLED: { label: "Annulé", color: "text-red-400", bg: "bg-red-600" }
};

const MISSION_CATEGORY_CONFIG: Record<string, { icon: any; color: string; fallbackImage: string; label: string }> = {
    DONJON: {
        icon: Swords,
        color: "text-rose-400",
        fallbackImage: "/assets/missions/donjon.png",
        label: "Donjon"
    },
    REGULATION: {
        icon: Skull,
        color: "text-emerald-400",
        fallbackImage: "/assets/missions/regulation.png",
        label: "Régulation"
    },
    ANOMALIE: {
        icon: Zap,
        color: "text-fuchsia-400",
        fallbackImage: "/assets/missions/ano1.png",
        label: "Anomalie"
    },
    SONGES: {
        icon: InfinityIcon,
        color: "text-cyan-400",
        fallbackImage: "/assets/missions/songes.png",
        label: "Songes"
    },
    EXPEDITION: {
        icon: Clock,
        color: "text-amber-400",
        fallbackImage: "/assets/missions/expedition.png",
        label: "Expédition"
    },
    EVENT: {
        icon: SparklesIcon,
        color: "text-yellow-300",
        fallbackImage: "/assets/missions/event.png",
        label: "Événement"
    },
};

// ============================================
// INTERFACES
// ============================================

interface Participant {
    id: string;
    status: string;
    position: number;
    classe?: string | null;
    comment?: string | null;
    hasParticipatedThisWeek?: boolean;
    user: {
        id: string;
        name: string | null;
        image: string | null;
        profiles?: { discordNickname: string | null }[];
    };
}

interface EventDetail {
    id: string;
    title: string;
    description?: string | null;
    type: string;
    status: string;
    startDate: Date | string;
    endDate: Date | string;
    location?: string | null;
    maxParticipants?: number | null;
    creator: {
        id: string;
        name: string | null;
        image: string | null;
    };
    participants: Participant[];
    discordMessageId?: string | null;
}

interface DiscordRole {
    id: string;
    name: string;
    color?: number;
}

interface EventDetailModalProps {
    event: EventDetail | null;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    currentUserId: string;
    guildId: string;
    canManage?: boolean;
    isAdmin?: boolean;
    everyoneAllowed?: boolean;
    discordRoles?: DiscordRole[];
    onRegister?: (data: { classe?: string; comment?: string }) => Promise<void>;
    onUnregister?: () => Promise<void>;
    onEdit?: () => void;
    onDelete?: () => Promise<void>;
    onCancel?: () => Promise<void>;
    onPublish?: () => Promise<void>;
    onComplete?: () => Promise<void>;
    onUndoComplete?: () => Promise<void>;
    onSendReminder?: (roleId?: string) => Promise<{ success: boolean; sentCount?: number; discordSent?: boolean; error?: string }>;
    onShareDiscord?: (roleId?: string) => Promise<{ success: boolean; error?: string }>;
    hasMetamobKey?: boolean;
    isDiscordConfigured?: boolean;
    /** Kamas eligibility for RAID_OFFICIAL events. Null = loading or not a raid. */
    raidEligibility?: { isEligible: boolean; totalDonated: number } | null;
}

// ============================================
// COMPONENT
// ============================================

export function EventDetailModal({
    event,
    open,
    onOpenChange,
    currentUserId,
    guildId,
    canManage = false,
    isAdmin = false,
    everyoneAllowed = false,
    discordRoles = [],
    onRegister,
    onUnregister,
    onEdit,
    onDelete,
    onCancel,
    onPublish,
    onComplete,
    onUndoComplete,
    onSendReminder,
    onShareDiscord,
    hasMetamobKey = false,
    isDiscordConfigured = false,
    raidEligibility = null,
}: EventDetailModalProps) {
    const [isLoading, setIsLoading] = useState(false);
    const [showRegistration, setShowRegistration] = useState(false);
    // Discord dialog state
    const [discordDialogOpen, setDiscordDialogOpen] = useState(false);
    const [discordDialogMode, setDiscordDialogMode] = useState<"REMINDER" | "SHARE">("SHARE");

    // Delete confirmation state
    const [isDeleteConfirming, setIsDeleteConfirming] = useState(false);
    const [selectedMissions, setSelectedMissions] = useState<any[]>([]);
    const [loadingMissions, setLoadingMissions] = useState(false);
    // Raid completion state
    const [showRaidCompletion, setShowRaidCompletion] = useState(false);
    const [raidScore, setRaidScore] = useState("");
    const [presentParticipants, setPresentParticipants] = useState<Set<string>>(new Set());
    const [isCompletingRaid, setIsCompletingRaid] = useState(false);
    const [confirmRaidComplete, setConfirmRaidComplete] = useState(false);

    const eventMetadata = (event as any)?.metadata as any;
    const missionIds = eventMetadata?.missionIds as string[] | undefined;
    // Raid metadata
    const isRaid = event?.type === "RAID_OFFICIAL";
    const raidMeta = isRaid ? eventMetadata : null;

    // Fetch missions if needed
    useEffect(() => {
        if (event?.type === "SESSION_MISSIONS" && missionIds && missionIds.length > 0) {
            setLoadingMissions(true);
            getMissionsByIds(missionIds).then(missions => {
                setSelectedMissions(missions);
                setLoadingMissions(false);
            });
        }
    }, [event?.type, missionIds]);

    if (!event) return null;

    // Init present participants when entering completion mode
    const initRaidCompletion = () => {
        const registered = event.participants.filter(p => p.status === "REGISTERED").map(p => p.user.id);
        setPresentParticipants(new Set(registered));
        setRaidScore("");
        setConfirmRaidComplete(false);
        setShowRaidCompletion(true);
    };

    const typeConfig = TYPE_CONFIG[event.type] || TYPE_CONFIG.EVENT_GUILD;
    const statusConfig = STATUS_CONFIG[event.status] || STATUS_CONFIG.DRAFT;

    const registeredCount = event.participants.filter(p => p.status === "REGISTERED").length;
    const reserveCount = event.participants.filter(p => p.status === "RESERVE").length;
    const isUserRegistered = event.participants.some(p => p.user.id === currentUserId && p.status !== "DECLINED");
    const userParticipant = event.participants.find(p => p.user.id === currentUserId);

    // Distinguish between direct Metamob events (krala-{id}) and imported events
    const isDirectKralamoure = event.id.startsWith("krala-");
    const isImportedKralamoure = event.type === "KRALAMOURE" && !isDirectKralamoure;
    const isExternal = isDirectKralamoure; // Only direct Kralamoure events are truly external

    const isOpen = event.status === "PUBLISHED";
    const isFull = event.maxParticipants ? registeredCount >= event.maxParticipants : false;
    const isCreator = event.creator.id === currentUserId;
    const isRegistered = isUserRegistered;
    const canRegister = isOpen && !isRegistered && !isExternal;

    // Extract Metamob creator from metadata or description for Kralamoure events
    const metamobCreator = (isDirectKralamoure || isImportedKralamoure)
        ? (eventMetadata?.metamobCreator || event.creator.name)
        : null;

    // SaaS 2026: Live count calculation
    const isKrala = isDirectKralamoure || isImportedKralamoure;
    const cachedCount = isKrala ? (eventMetadata?.metamobParticipantsCount || 0) : 0;
    const displayCount = registeredCount > 0 ? registeredCount : cachedCount;

    const handleAction = async (action: () => Promise<void>) => {
        setIsLoading(true);
        try {
            await action();
        } catch (error) {
            toast.error("Une erreur est survenue");
        } finally {
            setIsLoading(false);
        }
    };

    const handleRegistration = async (data: { classe?: string; comment?: string }) => {
        if (onRegister) {
            await onRegister(data);
        }
    };

    const handleDelete = async () => {
        if (!onDelete) return;

        setIsLoading(true);
        try {
            await onDelete();
            onOpenChange(false);
            toast.success("Événement supprimé");
        } catch (error) {
            toast.error("Erreur lors de la suppression");
        } finally {
            setIsLoading(false);
        }
    };

    const handleCancel = async () => {
        if (!onCancel) return;

        setIsLoading(true);
        try {
            await onCancel();
            onOpenChange(false);
            toast.success("Événement annulé");
        } catch (error) {
            toast.error("Erreur lors de l'annulation");
        } finally {
            setIsLoading(false);
        }
    };



    const TypeIcon = typeConfig.icon;

    return (
        <>
            <Dialog open={open} onOpenChange={onOpenChange}>
                <DialogContent
                    draggable
                    className="w-[95vw] sm:max-w-2xl bg-zinc-900/98 backdrop-blur-xl border border-white/10 ring-1 ring-orange-500/25 p-0 overflow-hidden max-h-[90vh] flex flex-col shadow-[0_0_50px_rgba(249,115,22,0.2)] fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2"
                >
                    {/* Header */}
                    <div className={cn("relative px-8 pt-12 pb-10 border-b border-zinc-800/50 overflow-hidden", typeConfig.bgColor)}>
                        <div className={cn("absolute inset-0 opacity-40 bg-gradient-to-br z-0", typeConfig.gradient)} />
                        
                        {/* Decorative Kralamoure Insert (Top Right) */}
                        {event.type === "KRALAMOURE" && (
                            <div className="absolute right-0 top-0 w-32 h-full opacity-60 pointer-events-none overflow-hidden select-none">
                                <div className="absolute top-1/2 -translate-y-1/2 right-4 w-20 h-20 rounded-2xl border border-white/20 overflow-hidden rotate-12 shadow-2xl backdrop-blur-md bg-white/5 p-1">
                                    <Image 
                                        src="/game-data/dungeons/antre-du-kralamoure-g-ant.webp" 
                                        alt="Kralamoure" 
                                        fill
                                        className="object-cover rounded-xl"
                                    />
                                </div>
                            </div>
                        )}

                        <div className="relative flex justify-between items-start z-10 w-full pr-8">
                            <div className="flex gap-5">
                                <div className={cn(
                                    "p-3 rounded-2xl shadow-inner shrink-0",
                                    "bg-black/20 text-white backdrop-blur-sm border border-white/10"
                                )}>
                                    <TypeIcon className="w-6 h-6" />
                                </div>

                                <div className="space-y-2">
                                    <div className="flex items-center gap-2">
                                        <Badge variant="outline" className={cn("text-[10px] font-black uppercase tracking-wider", typeConfig.color, "border-current/30 bg-current/5 px-2 py-0")}>
                                            {typeConfig.label}
                                        </Badge>
                                        <Badge className={cn("text-[10px] font-black uppercase tracking-wider px-2 py-0", statusConfig.bg)}>
                                            {statusConfig.label}
                                        </Badge>
                                    </div>
                                    <DialogHeader>
                                        <DialogTitle className={cn(
                                            "font-black tracking-tight text-white uppercase italic leading-tight break-words",
                                            event.title.length > 40 ? "text-lg sm:text-xl" : "text-xl sm:text-2xl"
                                        )}>
                                            {event.title}
                                        </DialogTitle>
                                    </DialogHeader>
                                </div>
                            </div>

                            {/* Move Complete Button Here */}
                            {canManage && (
                                <div className="flex items-center gap-2 ml-4">
                                    {/* Edit button — only creator or admin, disabled for Kralamoure */}
                                    {onEdit && event.type !== "KRALAMOURE" && (isCreator || isAdmin) && (
                                        <Button
                                            size="sm"
                                            variant="ghost"
                                            onClick={onEdit}
                                            className="text-zinc-400 hover:text-white hover:bg-white/10"
                                        >
                                            <Edit className="h-4 w-4 mr-1.5" />
                                            Éditer
                                        </Button>
                                    )}

                                    {/* Cancel button — only creator or admin (soft delete → CANCELLED) */}
                                    {event.status === "PUBLISHED" && onCancel && (isCreator || isAdmin) && (
                                        <Button
                                            size="sm"
                                            variant={isDeleteConfirming ? "destructive" : "ghost"}
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                if (isDeleteConfirming) {
                                                    handleCancel();
                                                } else {
                                                    setIsDeleteConfirming(true);
                                                    setTimeout(() => setIsDeleteConfirming(false), 3000);
                                                }
                                            }}
                                            disabled={isLoading}
                                            className={cn(
                                                "transition-all",
                                                isDeleteConfirming
                                                    ? "bg-red-600 hover:bg-red-700 text-white"
                                                    : "text-zinc-400 hover:text-red-400 hover:bg-red-950/20"
                                            )}
                                        >
                                            <Trash2 className="h-4 w-4 mr-1.5" />
                                            {isDeleteConfirming ? "Confirmer" : "Annuler"}
                                        </Button>
                                    )}

                                    {/* Hard delete button — only for admin on CANCELLED events */}
                                    {event.status === "CANCELLED" && onDelete && (isCreator || isAdmin) && (
                                        <Button
                                            size="sm"
                                            variant={isDeleteConfirming ? "destructive" : "ghost"}
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                if (isDeleteConfirming) {
                                                    handleDelete();
                                                } else {
                                                    setIsDeleteConfirming(true);
                                                    setTimeout(() => setIsDeleteConfirming(false), 3000);
                                                }
                                            }}
                                            disabled={isLoading}
                                            className={cn(
                                                "transition-all",
                                                isDeleteConfirming
                                                    ? "bg-red-600 hover:bg-red-700 text-white"
                                                    : "text-zinc-400 hover:text-red-400 hover:bg-red-950/20"
                                            )}
                                        >
                                            <Trash2 className="h-4 w-4 mr-1.5" />
                                            {isDeleteConfirming ? "Confirmer" : "Supprimer définitivement"}
                                        </Button>
                                    )}

                                    {/* Complete button — raids get a special flow */}
                                    {event.status === "PUBLISHED" && onComplete && (
                                        isRaid ? (
                                            <Button
                                                size="sm"
                                                onClick={initRaidCompletion}
                                                disabled={isLoading}
                                                className="bg-red-600/80 hover:bg-red-500 text-white shadow-sm border border-red-500/50"
                                            >
                                                <Trophy className="h-4 w-4 mr-1.5" />
                                                Clôturer le Raid
                                            </Button>
                                        ) : (
                                            <Button
                                                size="sm"
                                                onClick={() => handleAction(onComplete)}
                                                disabled={isLoading}
                                                className="bg-blue-600/80 hover:bg-blue-500 text-white shadow-sm border border-blue-500/50"
                                            >
                                                <Check className="h-4 w-4 mr-1.5" />
                                                Terminer l'event
                                            </Button>
                                        )
                                    )}
                                    {event.status === "COMPLETED" && (
                                        <div className="flex items-center gap-2">
                                            {isRaid && onUndoComplete && (isCreator || canManage) && (
                                                <Button
                                                    size="sm"
                                                    variant="ghost"
                                                    onClick={() => handleAction(onUndoComplete)}
                                                    disabled={isLoading}
                                                    className="text-emerald-400 hover:text-emerald-300 hover:bg-emerald-500/10"
                                                >
                                                    <span className="mr-1.5">↩</span>
                                                    Annuler la clôture
                                                </Button>
                                            )}
                                            <Badge variant="secondary" className="bg-zinc-950/50 text-zinc-400 border-zinc-700 px-3 py-1.5 text-xs font-semibold uppercase tracking-wider">
                                                {isRaid ? "Raid terminé" : "Event terminé"}
                                            </Badge>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>

                    <ScrollArea className="flex-1 overflow-y-auto">
                        <div className="p-6 space-y-5">
                            {canManage && !isDiscordConfigured && !isExternal && (
                                <div className="p-3 rounded-lg bg-amber-500/10 border border-amber-500/20 flex items-start gap-3">
                                    <Bell className="h-5 w-5 text-amber-500 shrink-0 mt-0.5" />
                                    <div className="space-y-1">
                                        <p className="text-xs font-bold text-amber-200 uppercase tracking-wide">Discord non configuré</p>
                                        <p className="text-[10px] text-amber-400/80 leading-relaxed">
                                            Le salon Discord pour les événements n'est pas défini. Les notifications et la publication automatique sont désactivées.
                                        </p>
                                    </div>
                                </div>
                            )}

                            <div className="grid grid-cols-2 gap-4">
                                <InfoCard
                                    icon={<Calendar className="h-4 w-4 text-amber-500" />}
                                    label="Date"
                                    value={format(new Date(event.startDate), "EEEE d MMMM", { locale: fr })}
                                />
                                <InfoCard
                                    icon={<Clock className="h-4 w-4 text-blue-400" />}
                                    label="Horaires"
                                    value={`${format(new Date(event.startDate), "HH:mm")} - ${format(new Date(event.endDate), "HH:mm")}`}
                                />
                                <InfoCard
                                    icon={<Users className="h-4 w-4 text-pink-400" />}
                                    label="Participants"
                                    value={
                                        <div className="flex items-center gap-2">
                                            <span className="font-black text-lg">{displayCount}</span>
                                            {event.maxParticipants && <span className="text-zinc-500 text-xs font-bold">/ {event.maxParticipants}</span>}
                                            {reserveCount > 0 && (
                                                <Badge variant="outline" className="bg-amber-500/10 text-amber-500 border-amber-500/30 text-[10px] font-black">
                                                    +{reserveCount} WAITING
                                                </Badge>
                                            )}
                                        </div>
                                    }
                                />
                                <InfoCard
                                    icon={<Crown className="h-4 w-4 text-yellow-500" />}
                                    label="Organisateur"
                                    value={
                                        (isDirectKralamoure || isImportedKralamoure) && metamobCreator ? (
                                            <span className="truncate font-black italic uppercase text-zinc-300 tracking-tight" title={metamobCreator}>
                                                {metamobCreator}
                                            </span>
                                        ) : event.creator ? (
                                            <div className="flex items-center gap-2">
                                                <Avatar className="h-5 w-5 border border-zinc-700">
                                                    <AvatarImage src={event.creator.image || undefined} />
                                                    <AvatarFallback className="text-[10px] bg-zinc-800">
                                                        {event.creator.name?.charAt(0) || "?"}
                                                    </AvatarFallback>
                                                </Avatar>
                                                <span className="truncate font-bold text-zinc-300" title={event.creator.name || "Inconnu"}>
                                                    {event.creator.name || "Inconnu"}
                                                </span>
                                            </div>
                                        ) : (
                                            <span className="text-zinc-500">Inconnu</span>
                                        )
                                    }
                                />
                            </div>



                            {/* Description */}
                            {event.description && (
                                <div className="p-3 rounded-lg bg-zinc-800/30 border border-zinc-700/30">
                                    <p className="text-sm text-zinc-300 whitespace-pre-wrap">{event.description}</p>
                                </div>
                            )}

                            {/* ========== RAID INFO PANEL ========== */}
                            {isRaid && raidMeta && (
                                <div className="space-y-3 p-4 rounded-xl border border-red-500/20 bg-red-500/[0.04] animate-in fade-in duration-300">
                                    <div className="flex items-center gap-2 mb-2">
                                        <Swords className="h-4 w-4 text-red-400" />
                                        <span className="text-xs font-black text-red-400 uppercase tracking-widest">Détails du Raid</span>
                                    </div>

                                    {/* Raid type + badges */}
                                    <div className="flex flex-wrap items-center gap-2">
                                        {raidMeta.raidLabel && (
                                            <span className="px-2.5 py-1 rounded-lg bg-red-500/10 border border-red-500/20 text-red-300 text-xs font-black uppercase tracking-wider">
                                                {raidMeta.raidLabel}
                                            </span>
                                        )}
                                        {raidMeta.openToExternal ? (
                                            <span className="flex items-center gap-1 px-2 py-1 rounded-lg bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 text-[10px] font-black uppercase tracking-wider">
                                                <Globe className="h-3 w-3" /> Ouvert aux extérieurs
                                            </span>
                                        ) : (
                                            <span className="flex items-center gap-1 px-2 py-1 rounded-lg bg-zinc-800 border border-zinc-700 text-zinc-500 text-[10px] font-black uppercase tracking-wider">
                                                <Lock className="h-3 w-3" /> Guilde uniquement
                                            </span>
                                        )}
                                    </div>

                                    {/* Captain */}
                                    {raidMeta.raidCaptain && (
                                        <div className="flex items-center gap-2 text-sm">
                                            <Crown className="h-4 w-4 text-yellow-500 shrink-0" />
                                            <span className="text-zinc-400 text-xs uppercase tracking-wider">Capitaine :</span>
                                            <span className="font-black text-yellow-300 uppercase tracking-tight">{raidMeta.raidCaptain}</span>
                                        </div>
                                    )}

                                    {/* Progress bar min/max */}
                                    {raidMeta.raidMin && raidMeta.raidMax && (
                                        <div className="space-y-1.5">
                                            <div className="flex items-center justify-between text-xs">
                                                <span className="text-zinc-500 font-bold uppercase tracking-wider">Inscrits</span>
                                                <span className={cn(
                                                    "font-black",
                                                    registeredCount >= raidMeta.raidMin ? "text-emerald-400" : "text-amber-400"
                                                )}>
                                                    {registeredCount >= raidMeta.raidMin ? "✅ RAID GO" : `⏳ ${raidMeta.raidMin - registeredCount} manquant(s)`}
                                                </span>
                                            </div>
                                            <div className="relative h-2.5 rounded-full bg-zinc-800 overflow-hidden">
                                                {/* Min threshold marker */}
                                                <div
                                                    className="absolute top-0 bottom-0 w-px bg-amber-400/50 z-10"
                                                    style={{ left: `${(raidMeta.raidMin / raidMeta.raidMax) * 100}%` }}
                                                />
                                                {/* Fill */}
                                                <div
                                                    className={cn(
                                                        "h-full rounded-full transition-all duration-700",
                                                        registeredCount >= raidMeta.raidMin
                                                            ? "bg-gradient-to-r from-emerald-600 to-emerald-400"
                                                            : "bg-gradient-to-r from-red-700 to-amber-500"
                                                    )}
                                                    style={{ width: `${Math.min(100, (registeredCount / raidMeta.raidMax) * 100)}%` }}
                                                />
                                            </div>
                                            <div className="flex justify-between text-[10px] text-zinc-600 font-bold">
                                                <span>0</span>
                                                <span className="text-amber-500/70">{raidMeta.raidMin} min</span>
                                                <span>{raidMeta.raidMax} max</span>
                                            </div>
                                            <div className="text-center">
                                                <span className="text-lg font-black text-white">{registeredCount}</span>
                                                <span className="text-zinc-500 text-xs font-bold"> / {raidMeta.raidMax} joueurs</span>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            )}

                            {/* Mission Objectives Grid */}
                            {event.type === "SESSION_MISSIONS" && (selectedMissions.length > 0 || loadingMissions) && (
                                <div className="space-y-4">
                                    <div className="flex items-center gap-2">
                                        <Target className="h-4 w-4 text-amber-500" />
                                        <h3 className="text-xs font-black text-zinc-400 uppercase italic tracking-widest">Objectifs de la session</h3>
                                    </div>

                                    {loadingMissions ? (
                                        <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                                            {[1, 2].map(i => (
                                                <div key={i} className="aspect-[16/9] rounded-xl bg-zinc-800/50 animate-pulse border border-zinc-800" />
                                            ))}
                                        </div>
                                    ) : (
                                        <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                                            {selectedMissions.map((mission) => {
                                                const config = MISSION_CATEGORY_CONFIG[mission.category] || MISSION_CATEGORY_CONFIG.EVENT;
                                                const payload = mission.payload || {};
                                                let imageUrl = payload.imageUrl || payload.image || config.fallbackImage;
                                                
                                                if (mission.category === 'SONGES') {
                                                    const diff: string = (payload.difficulty || 'Reve').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
                                                    const levelMap: Record<string, number> = { 'I': 1, 'II': 2, 'III': 3, 'IV': 4 };
                                                    const lvl = levelMap[payload.level as string] || 1;
                                                    imageUrl = `/assets/missions/${diff}${lvl}.png`;
                                                }

                                                const mTitle = mission.title || payload.dungeonName || payload.monsterName || config.label;

                                                return (
                                                    <TooltipProvider key={mission.id}>
                                                        <Tooltip>
                                                            <TooltipTrigger asChild>
                                                                <Link 
                                                                    href={`/dashboard/${guildId}/missions`}
                                                                    className="group relative aspect-[16/9] rounded-xl border border-zinc-800 overflow-hidden bg-zinc-950 shadow-lg block hover:border-amber-500/50 transition-all hover:scale-[1.02]"
                                                                >
                                                                    <Image 
                                                                        src={imageUrl} 
                                                                        alt={mTitle} 
                                                                        fill 
                                                                        className="object-contain p-2 opacity-60 group-hover:opacity-100 transition-opacity duration-500" 
                                                                        unoptimized
                                                                    />
                                                                    <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent" />
                                                                    
                                                                    {/* Category Icon */}
                                                                    <div className={cn(
                                                                        "absolute top-2 left-2 p-1 rounded bg-black/60 border border-white/10 backdrop-blur-md z-10",
                                                                        config.color
                                                                    )}>
                                                                        <config.icon className="h-2.5 w-2.5" />
                                                                    </div>

                                                                    <div className="absolute inset-x-0 bottom-0 p-2">
                                                                        <p className="text-[10px] font-black text-white uppercase tracking-tighter line-clamp-1 leading-none mb-1">
                                                                            {mTitle}
                                                                        </p>
                                                                        {payload.objectives && (
                                                                            <p className="text-[8px] font-bold text-zinc-400 uppercase tracking-widest line-clamp-1">
                                                                                {payload.objectives}
                                                                            </p>
                                                                        )}
                                                                    </div>
                                                                </Link>
                                                            </TooltipTrigger>
                                                            <TooltipContent side="bottom" className="bg-amber-500 text-zinc-950 font-black uppercase text-[10px] tracking-widest border-none">
                                                                Aller voir les missions ?
                                                            </TooltipContent>
                                                        </Tooltip>
                                                    </TooltipProvider>
                                                );
                                            })}
                                        </div>
                                    )}
                                </div>
                            )}

                            <Separator className="bg-zinc-800/50" />

                            {/* Roster */}
                            {(() => {
                                return (
                                    <div>
                                        <h3 className="text-sm font-black text-zinc-400 mb-4 flex items-center justify-between uppercase italic tracking-widest">
                                            <div className="flex items-center gap-2">
                                                <Users className="h-4 w-4 text-pink-400" />
                                                Participants{isKrala ? " Metamob" : ""}
                                            </div>
                                            <span className="px-2 py-0.5 rounded-md bg-pink-500/20 text-pink-400 text-xs font-black shadow-lg shadow-pink-500/10">
                                                {displayCount}
                                            </span>
                                        </h3>

                                        <div className="space-y-2">
                                            {/* Standard DB Participants */}
                                            {event.participants
                                                .filter(p => p.status === "REGISTERED")
                                                .sort((a, b) => a.position - b.position)
                                                .map((participant) => (
                                                    <ParticipantRow
                                                        key={participant.id}
                                                        participant={participant}
                                                        isCreator={participant.user.id === event.creator.id}
                                                        isCurrentUser={participant.user.id === currentUserId}
                                                        onUnregister={!isExternal && onUnregister ? () => handleAction(onUnregister) : undefined}
                                                        onKick={(canManage || event.creator.id === currentUserId) && participant.user.id !== event.creator.id
                                                            ? () => handleAction(async () => {
                                                                const res = await kickParticipant(guildId, event.id, participant.user.id);
                                                                if (res.success) {
                                                                    toast.success("Joueur exclu de l'événement.");
                                                                } else {
                                                                    toast.error(res.error || "Erreur lors de l'expulsion");
                                                                }
                                                            })
                                                            : undefined
                                                        }
                                                    />
                                                ))}

                                            {/* Metamob Metadata Participants Fallback */}
                                            {isKrala && event.participants.length === 0 && (eventMetadata?.metamobParticipants || []).length > 0 && (
                                                (eventMetadata.metamobParticipants as any[]).map((p, i) => (
                                                    <div key={`meta-${i}`} className="group relative flex items-center justify-between p-3 rounded-xl bg-zinc-900/40 border border-zinc-800/50 hover:bg-zinc-800/60 transition-all">
                                                        <div className="flex items-center gap-4 min-w-0">
                                                            <div className="h-8 w-8 rounded-full bg-zinc-800 border border-zinc-700 flex items-center justify-center text-[10px] font-black text-zinc-500 shrink-0 group-hover:border-pink-500/30 group-hover:text-pink-400 transition-colors">
                                                                #{i + 1}
                                                            </div>
                                                            <Avatar className="h-10 w-10 border border-zinc-800 shadow-xl group-hover:scale-110 transition-transform">
                                                                <AvatarFallback className="bg-gradient-to-br from-zinc-800 to-zinc-900 text-zinc-400 text-xs font-bold">
                                                                    {p.username?.[0] || "?"}
                                                                </AvatarFallback>
                                                            </Avatar>
                                                            <div className="flex flex-col min-w-0">
                                                                <span className="text-sm font-black text-zinc-100 truncate group-hover:text-white transition-colors uppercase italic tracking-tight">
                                                                    {(p.username || "Anonyme").replace(/\s\(\d+\)$/, "")}
                                                                </span>
                                                                <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest mt-0.5">
                                                                    {p.character_count || 1} { (p.character_count || 1) > 1 ? 'Personnages' : 'Personnage'}
                                                                </span>
                                                            </div>
                                                        </div>
                                                        <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                                                            <Badge variant="outline" className="text-[10px] font-black border-pink-500/20 text-pink-400 bg-pink-500/5">
                                                                METAMOB
                                                            </Badge>
                                                        </div>
                                                    </div>
                                                ))
                                            )}

                                            {reserveCount > 0 && (
                                                <>
                                                    <div className="text-xs text-amber-400 font-medium mt-4 mb-2 flex items-center gap-2">
                                                        <div className="h-px bg-zinc-800/50 flex-1" />
                                                        <Clock className="h-3 w-3" />
                                                        File d&apos;attente ({reserveCount})
                                                        <div className="h-px bg-zinc-800/50 flex-1" />
                                                    </div>
                                                    {event.participants
                                                        .filter(p => p.status === "RESERVE")
                                                        .sort((a, b) => a.position - b.position)
                                                        .map((participant) => (
                                                            <ParticipantRow
                                                                key={participant.id}
                                                                participant={participant}
                                                                isReserve
                                                                isCurrentUser={participant.user.id === currentUserId}
                                                                onUnregister={onUnregister ? () => handleAction(onUnregister) : undefined}
                                                                onKick={(canManage || event.creator.id === currentUserId) && participant.user.id !== event.creator.id
                                                                    ? () => handleAction(async () => {
                                                                        const res = await kickParticipant(guildId, event.id, participant.user.id);
                                                                        if (res.success) {
                                                                            toast.success("Joueur exclu de l'événement.");
                                                                        } else {
                                                                            toast.error(res.error || "Erreur lors de l'expulsion");
                                                                        }
                                                                    })
                                                                    : undefined
                                                                }
                                                            />
                                                        ))}
                                                </>
                                            )}

                                            {event.participants.length === 0 && (!isKrala || (eventMetadata?.metamobParticipants || []).length === 0) && (
                                                <div className="text-center py-12 rounded-xl border-2 border-dashed border-zinc-800/50 bg-zinc-900/20">
                                                    <User className="h-10 w-10 mx-auto mb-3 text-zinc-600 opacity-50" />
                                                    <p className="text-zinc-400 font-medium">
                                                        {isKrala 
                                                            ? "Détails des participants indisponibles" 
                                                            : "Aucun participant inscrit"
                                                        }
                                                    </p>
                                                    {isKrala && (
                                                        <p className="text-xs text-zinc-500 mt-2 px-6">
                                                            Les inscrits sur Metamob ne sont pas encore synchronisés ou nécessitent une clé API valide.
                                                        </p>
                                                    )}
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                );
                            })()}
                        </div>
                    </ScrollArea>



                    {/* Footer */}
                    <div className="px-6 py-4 bg-zinc-950/50 border-t border-zinc-800/50 space-y-3">
                        {/* User Actions */}
                        <div className="flex items-center gap-2 flex-wrap">
                            {(isDirectKralamoure || isImportedKralamoure) ? (
                                <div className="flex flex-col gap-3 w-full">
                                    <div className="flex items-center gap-2">
                                        <Button
                                            asChild
                                            className="bg-indigo-600 hover:bg-indigo-500 text-white font-bold shadow-lg shadow-indigo-500/20"
                                        >
                                            <a
                                                href="https://metamob.fr/kralove"
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="flex items-center w-full h-full px-4 py-2"
                                            >
                                                <ExternalLink className="h-4 w-4 mr-2" />
                                                S'inscrire sur Metamob
                                            </a>
                                        </Button>

                                        {!hasMetamobKey && (
                                                <Button
                                                    asChild
                                                    variant="outline"
                                                    className="border-indigo-500/30 text-indigo-400 hover:bg-indigo-500/10 hover:border-indigo-500/50"
                                                >
                                                <a href={`/dashboard/${guildId}/profile`}>
                                                    Lier mon compte Metamob
                                                </a>
                                            </Button>
                                        )}
                                    </div>
                                    {!hasMetamobKey && (
                                        <p className="text-[11px] text-zinc-500 italic">
                                            Liez votre compte pour que SigilOS puisse synchroniser votre état de jeu.
                                        </p>
                                    )}
                                </div>
                            ) : (
                                <>
                                    {canRegister && (
                                        (() => {
                                            // Kamas gate: only for RAID_OFFICIAL events
                                            const isRaidOfficial = event.type === "RAID_OFFICIAL";
                                            const isBlocked = isRaidOfficial && raidEligibility !== null && raidEligibility !== undefined && !raidEligibility.isEligible;

                                            if (isBlocked) {
                                                const donated = raidEligibility!.totalDonated.toLocaleString("fr-FR");
                                                return (
                                                    <div className="flex flex-col gap-2 w-full">
                                                        <Button
                                                            size="lg"
                                                            disabled
                                                            className="h-12 rounded-xl font-black text-sm uppercase tracking-wider transition-all duration-300 shadow-inner relative group overflow-hidden border border-zinc-700/50 bg-zinc-800/50 text-zinc-500 cursor-not-allowed px-8"
                                                        >
                                                            <Lock className="h-4 w-4 mr-2.5" />
                                                            Inscription verrouillée
                                                        </Button>
                                                        <div className="flex items-start gap-2.5 p-3 rounded-xl bg-amber-500/5 border border-amber-500/20 text-amber-400">
                                                            <Coins className="h-4 w-4 shrink-0 mt-0.5" />
                                                            <div className="text-xs leading-relaxed">
                                                                <span className="font-black uppercase tracking-wide">Don requis : 30 000 kamas</span>
                                                                <br />
                                                                <span className="text-amber-400/70">
                                                                    Tu as donné <strong>{donated}</strong> kamas cette semaine. Complète ton don pour débloquer l'accès aux raids.
                                                                </span>
                                                                <br />
                                                                <Link
                                                                    href={`/dashboard/${guildId}/missions#don-kamas`}
                                                                    className="inline-flex items-center gap-1 mt-1.5 font-black text-amber-400 hover:text-amber-300 underline underline-offset-2"
                                                                >
                                                                    <Coins className="h-3 w-3" />
                                                                    Faire mon don maintenant
                                                                    <ExternalLink className="h-3 w-3" />
                                                                </Link>
                                                            </div>
                                                        </div>
                                                    </div>
                                                );
                                            }

                                            return (
                                                <Button
                                                    size="lg"
                                                    onClick={() => setShowRegistration(true)}
                                                    disabled={isLoading}
                                                    className={cn(
                                                        "h-12 rounded-xl font-black text-sm uppercase tracking-wider transition-all duration-300 shadow-lg relative group overflow-hidden border-t border-white/10 px-8",
                                                        isFull
                                                            ? "bg-amber-600 hover:bg-amber-500 shadow-amber-600/30 text-white"
                                                            : "bg-indigo-600 hover:bg-indigo-500 shadow-indigo-600/30 text-white"
                                                    )}
                                                >
                                                    <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                                                    {isFull ? <Users className="h-4 w-4 mr-2.5" /> : <Check className="h-4 w-4 mr-2.5" />}
                                                    {isFull ? "Rejoindre la file d'attente" : "S'inscrire à l'événement"}
                                                </Button>
                                            );
                                        })()
                                    )}

                                    {isRegistered && onUnregister && (
                                        <Button
                                            size="lg"
                                            variant="outline"
                                            onClick={() => handleAction(onUnregister)}
                                            disabled={isLoading}
                                            className="h-12 rounded-xl font-bold text-sm border-zinc-700 bg-zinc-800/50 text-zinc-400 hover:bg-red-500/10 hover:text-red-400 hover:border-red-500/30 transition-all duration-300 px-6"
                                        >
                                            <X className="h-4 w-4 mr-2" />
                                            Se désinscrire
                                        </Button>
                                    )}
                                </>
                            )}
                        </div>

                        {/* Admin Actions — only Rappel Discord (creator or admin) */}
                        {canManage && !isExternal && (isCreator || isAdmin) && (
                            <div className="flex items-center justify-between gap-2 flex-wrap pt-4 mt-2 border-t border-zinc-800/30">
                                <div className="flex items-center gap-2 ml-auto">
                                    {event.status === "PUBLISHED" && onSendReminder && event.participants.length > 0 && isDiscordConfigured === true && (
                                            <Button
                                                size="sm"
                                                variant="ghost"
                                                disabled={isLoading}
                                                onClick={() => {
                                                    setDiscordDialogMode("REMINDER");
                                                    setDiscordDialogOpen(true);
                                                }}
                                                className="text-amber-400 hover:bg-amber-500/10 font-bold px-4"
                                            >
                                                <Bell className="h-4 w-4 mr-2" />
                                                Rappel Discord
                                            </Button>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>
                </DialogContent>
            </Dialog>

            {/* ========== RAID COMPLETION MODAL ========== */}
            {isRaid && showRaidCompletion && (
                <Dialog open={showRaidCompletion} onOpenChange={setShowRaidCompletion}>
                    <DialogContent className="w-[95vw] sm:max-w-lg bg-zinc-900/98 backdrop-blur-xl border border-white/10 ring-1 ring-red-500/25 p-0 overflow-hidden shadow-[0_0_50px_rgba(239,68,68,0.2)]">
                        <div className="relative p-6 border-b border-red-500/10 bg-red-500/5">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-red-500/10 border border-red-500/20 flex items-center justify-center">
                                    <Trophy className="h-5 w-5 text-red-400" />
                                </div>
                                <div>
                                    <DialogTitle className="text-white font-black uppercase tracking-tight">Clôturer le Raid</DialogTitle>
                                    <p className="text-[11px] text-zinc-500 uppercase tracking-wider">Distribution des points & score</p>
                                </div>
                            </div>
                        </div>

                        <div className="p-6 space-y-5">
                            {/* Score */}
                            <div className="space-y-1.5">
                                <label className="text-xs font-black text-zinc-400 uppercase tracking-widest flex items-center gap-1.5">
                                    <Star className="h-3.5 w-3.5 text-yellow-500" />
                                    Score du Raid
                                </label>
                                <input
                                    type="text"
                                    placeholder="Ex: 84 500 pts"
                                    value={raidScore}
                                    onChange={e => setRaidScore(e.target.value)}
                                    className="w-full h-11 px-4 rounded-xl bg-zinc-950/80 border border-zinc-700 text-zinc-100 font-black text-base placeholder:text-zinc-600 focus:outline-none focus:border-red-500/50"
                                />
                                <p className="text-[10px] text-zinc-600 italic">Score visible dans le module de raid en jeu.</p>
                            </div>

                            {/* Participants présents */}
                            <div className="space-y-2">
                                <div className="flex items-center justify-between">
                                    <label className="text-xs font-black text-zinc-400 uppercase tracking-widest flex items-center gap-1.5">
                                        <Users className="h-3.5 w-3.5 text-pink-400" />
                                        Présents au Raid
                                    </label>
                                    <span className="text-xs font-black text-zinc-500">
                                        {presentParticipants.size} / {event.participants.filter(p => p.status === "REGISTERED").length}
                                    </span>
                                </div>
                                <div className="space-y-1.5 max-h-64 overflow-y-auto pr-1">
                                    {event.participants
                                        .filter(p => p.status === "REGISTERED")
                                        .map(p => {
                                            const isPresent = presentParticipants.has(p.user.id);
                                            return (
                                                <button
                                                    key={p.id}
                                                    type="button"
                                                    onClick={() => {
                                                        setPresentParticipants(prev => {
                                                            const next = new Set(prev);
                                                            if (next.has(p.user.id)) next.delete(p.user.id);
                                                            else next.add(p.user.id);
                                                            return next;
                                                        });
                                                    }}
                                                    className={cn(
                                                        "w-full flex items-center gap-3 p-2.5 rounded-lg border transition-all text-left",
                                                        isPresent
                                                            ? "bg-emerald-500/10 border-emerald-500/30"
                                                            : "bg-zinc-900/50 border-zinc-800 opacity-50"
                                                    )}
                                                >
                                                    <div className={cn(
                                                        "w-5 h-5 rounded-md border-2 flex items-center justify-center shrink-0 transition-all",
                                                        isPresent ? "bg-emerald-500 border-emerald-400" : "border-zinc-600"
                                                    )}>
                                                        {isPresent && <Check className="h-3 w-3 text-white" />}
                                                    </div>
                                                    <Avatar className="h-7 w-7 border border-zinc-700 shrink-0">
                                                        <AvatarImage src={p.user.image || undefined} />
                                                        <AvatarFallback className="bg-zinc-800 text-[10px]">{p.user.name?.[0] || "?"}</AvatarFallback>
                                                    </Avatar>
                                                    <span className={cn(
                                                        "text-sm font-black uppercase tracking-tight",
                                                        isPresent ? "text-zinc-100" : "text-zinc-600"
                                                    )}>
                                                        {p.user.profiles?.[0]?.discordNickname || p.user.name || "Anonyme"}
                                                    </span>
                                                    {isPresent && (
                                                        <span className="ml-auto text-[10px] font-black text-emerald-400 uppercase">+50 pts</span>
                                                    )}
                                                </button>
                                            );
                                        })}
                                </div>
                            </div>

                            {/* Confirmation checkbox */}
                            <div className="flex items-start gap-3 p-3 rounded-xl border border-red-500/15 bg-red-500/5">
                                <input
                                    type="checkbox"
                                    id="confirm-raid-complete"
                                    checked={confirmRaidComplete}
                                    onChange={(e) => setConfirmRaidComplete(e.target.checked)}
                                    className="mt-0.5 h-4 w-4 shrink-0 rounded border-zinc-600 bg-zinc-800 text-red-500 focus:ring-red-500/50"
                                />
                                <label htmlFor="confirm-raid-complete" className="text-xs text-zinc-400 leading-relaxed cursor-pointer">
                                    <span className="font-bold text-red-400">J'atteste</span> avoir coordonné la clôture avec mon équipe. Les <strong>{presentParticipants.size} participant{ presentParticipants.size > 1 ? "s" : "" } présent{ presentParticipants.size > 1 ? "s" : "" }</strong> sélectionné{ presentParticipants.size > 1 ? "s" : "" } verront leurs Kamas Violets déduits.
                                </label>
                            </div>

                            {/* Actions */}
                            <div className="flex gap-3 pt-2">
                                <Button
                                    variant="ghost"
                                    className="flex-1 border border-zinc-800 text-zinc-400"
                                    onClick={() => setShowRaidCompletion(false)}
                                >
                                    Annuler
                                </Button>
                                <Button
                                    className="flex-1 bg-gradient-to-r from-red-600 to-rose-500 hover:from-red-500 hover:to-rose-400 text-white font-black shadow-lg shadow-red-500/20"
                                    disabled={isCompletingRaid || !confirmRaidComplete}
                                    onClick={async () => {
                                        if (!onComplete) return;
                                        setIsCompletingRaid(true);
                                        try {
                                            // Pass raid completion data via the existing onComplete handler
                                            // The caller (calendar-dashboard) will handle the extended data
                                            (window as any).__raidCompletionData = {
                                                score: raidScore,
                                                presentUserIds: Array.from(presentParticipants)
                                            };
                                            await onComplete();
                                            setShowRaidCompletion(false);
                                        } finally {
                                            setIsCompletingRaid(false);
                                        }
                                    }}
                                >
                                    {isCompletingRaid ? (
                                        <><Loader2 className="h-4 w-4 mr-2 animate-spin" />Clôture...</>
                                    ) : (
                                        <><Trophy className="h-4 w-4 mr-2" />Valider & Distribuer</>  
                                    )}
                                </Button>
                            </div>
                        </div>
                    </DialogContent>
                </Dialog>
            )}

            <RegistrationModal
                open={showRegistration}
                onOpenChange={setShowRegistration}
                eventTitle={event.title}
                isFull={isFull}
                onSubmit={handleRegistration}
            />

            <CalendarDiscordDialog
                isOpen={discordDialogOpen}
                onOpenChange={setDiscordDialogOpen}
                guildId={guildId}
                eventId={event.id}
                roles={discordRoles}
                everyoneAllowed={everyoneAllowed}
                mode={discordDialogMode}
                onConfirm={async (roleId) => {
                    if (discordDialogMode === "REMINDER" && onSendReminder) {
                        return await onSendReminder(roleId);
                    } else if (discordDialogMode === "SHARE" && onShareDiscord) {
                        return await onShareDiscord(roleId);
                    }
                    return { success: false, error: "Action non définie" };
                }}
            />
        </>
    );
}

