                                                    </CommandItem>
                                                    {discordRoles.map((role) => (
                                                        <CommandItem
                                                            key={role.id}
                                                            value={role.name}
                                                            onSelect={() => {
                                                                const current = field.value || [];
                                                                const next = current.includes(role.id)
