                                                                <span className="font-bold text-zinc-300 group-hover:text-white transition-colors uppercase tracking-tight">{role.name}</span>
                                                            </div>
                                                            {field.value?.includes(role.id) && <Check className="h-4 w-4 text-amber-500" />}
                                                        </CommandItem>
                                                    ))}
                                                </CommandGroup>
                                            </CommandList>
                                        </Command>
                                    </PopoverContent>
                                </Popover>
                                <FormMessage />
                            </FormItem>
                        )}
                    />
                )}

                {/* ============ SUBMIT ============ */}
                <div className="flex items-center gap-3 mt-4">
                    <Button
                        type="submit"
                        disabled={submitting || (isRaid && creatorRaidEligibility !== null && !creatorRaidEligibility.isEligible)}
                        className={cn(
                            "w-full h-12 font-bold text-base transition-all",
                            isRaid && creatorRaidEligibility !== null && !creatorRaidEligibility.isEligible
                                ? "bg-zinc-800 border border-zinc-700 text-zinc-500 cursor-not-allowed shadow-inner"
                                : "bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-400 hover:to-orange-400 shadow-lg shadow-amber-500/20 text-zinc-950"
                        )}
                    >
                        {submitting ? (
                            <>
                                <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                                Création...
                            </>
                        ) : isRaid && creatorRaidEligibility !== null && !creatorRaidEligibility.isEligible ? (
                            <>
                                <Lock className="mr-2 h-5 w-5" />
                                Création bloquée
                            </>
                        ) : (
                            <>
                                {currentConfig && <currentConfig.icon className="mr-2 h-5 w-5" />}
                                {initialData ? "Enregistrer" : "Créer l'événement"}
                            </>
                        )}
                    </Button>
                </div>
            </motion.div>
        )}
        </AnimatePresence>
    </form>
</Form>
    );
}

"use client";

import { useState, useEffect } from "react";
import { format, isToday, differenceInMinutes } from "date-fns";
import { fr } from "date-fns/locale";
import {
    Clock,
    Users,
    Swords,
    PartyPopper,
    Target,
    Wheat,
    Eye
} from "lucide-react";
import { cn } from "@/lib/utils";
import { motion, AnimatePresence } from "framer-motion";

const TYPE_CONFIG: Record<string, { label: string; icon: React.ElementType; color: string; bg: string }> = {
    RAID_OFFICIAL: {
        label: "Raid 3.6",
        icon: Swords,
        color: "text-red-400",
        bg: "bg-red-500/10 border-red-500/20"
    },
    EVENT_GUILD: {
        label: "Event Guilde",
        icon: PartyPopper,
        color: "text-purple-400",
        bg: "bg-purple-500/10 border-purple-500/20"
    },
    SESSION_MISSIONS: {
        label: "Missions",
        icon: Target,
        color: "text-amber-400",
        bg: "bg-amber-500/10 border-amber-500/20"
    },
    SORTIE_FARM: {
        label: "Farm",
        icon: Wheat,
        color: "text-emerald-400",
        bg: "bg-emerald-500/10 border-emerald-500/20"
    },
    KRALAMOURE: {
        label: "Kralamoure",
        icon: Eye,
        color: "text-pink-400",
        bg: "bg-pink-500/10 border-pink-500/20"
    }
};

interface FeaturedEventsCarouselProps {
    events: any[];
    onEventClick: (eventId: string) => void;
}

export function FeaturedEventsCarousel({ events, onEventClick }: FeaturedEventsCarouselProps) {
    const [currentIndex, setCurrentIndex] = useState(0);

    // Filter only future/today events and take next 5
    const upcoming = events
        .filter(e => new Date(e.startDate) >= new Date(new Date().setHours(0, 0, 0, 0)))
        .sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime())
        .slice(0, 5);

    useEffect(() => {
        if (upcoming.length <= 1) return;

        const interval = setInterval(() => {
            setCurrentIndex((prev) => (prev + 1) % upcoming.length);
        }, 5000);

        return () => clearInterval(interval);
    }, [upcoming.length]);

    if (upcoming.length === 0) return null;

    const event = upcoming[currentIndex];
    const config = TYPE_CONFIG[event.type] || TYPE_CONFIG.EVENT_GUILD;
    const startDate = new Date(event.startDate);

    // Participants logic
    const participantCount = event._count?.participants ||
        (event.participants ? event.participants.length : 0);
    const maxParticipants = event.maxParticipants;
    const isFull = maxParticipants && participantCount >= maxParticipants;

    return (
        <div className="flex justify-center w-full">
            <AnimatePresence mode="wait">
                <motion.button
                    key={event.id}
                    onClick={() => onEventClick(event.id)}
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                    transition={{ duration: 0.3 }}
                    className={cn(
                        "flex items-center gap-3 px-4 py-2 rounded-full border bg-zinc-900/50 backdrop-blur-md transition-all hover:bg-zinc-800/50 hover:scale-105 hover:border-zinc-700 group",
                        config.bg.replace("/10", "/20").replace("border-", "border-zinc-800/50 ")
                    )}
                >
                    {/* Status Dot */}
                    <div className={cn("h-2 w-2 rounded-full animate-pulse", config.color.replace("text-", "bg-"))} />

                    {/* Title */}
                    <span className="text-sm font-bold text-zinc-100 truncate max-w-[150px] group-hover:text-amber-400 transition-colors">
                        {event.title}
                    </span>

                    {/* Date */}
                    <span className="text-xs text-zinc-400 font-medium hidden sm:inline-block">
                        {isToday(startDate) ? "Aujourd'hui" : format(startDate, "dd MMM", { locale: fr })} {format(startDate, "HH:mm")}
                    </span>

                    {/* Participants */}
                    <span className={cn(
                        "text-xs font-medium px-2 py-0.5 rounded-full bg-zinc-950/30 border border-zinc-800 flex items-center gap-1",
                        isFull ? "text-red-400 border-red-900/30" : "text-zinc-500"
                    )}>
                        <Users className="h-3 w-3" />
                        {participantCount}{maxParticipants ? `/${maxParticipants}` : ""}
                    </span>
                </motion.button>
            </AnimatePresence>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { MissionCategory } from "@prisma/client";
import { cn } from "@/lib/utils";
import Image from "next/image";
import { Swords, Skull, Zap, Clock, Infinity as InfinityIcon, Sparkles, Check, Loader2 } from "lucide-react";
import { getMissionsForCalendar } from "@/server/actions/mission-actions";

interface MissionPickerProps {
    guildId: string;
    selectedIds: string[];
    onSelect: (ids: string[], titles: string[]) => void;
}

const CATEGORY_CONFIG: Record<string, { icon: any; color: string; bgColor: string; borderColor: string; fallbackImage: string; label: string }> = {
    DONJON: {
        icon: Swords,
        color: "text-rose-400",
        bgColor: "bg-rose-500/10",
        borderColor: "border-rose-500/20",
        fallbackImage: "/assets/missions/donjon.png",
        label: "Donjon"
    },
    REGULATION: {
        icon: Skull,
        color: "text-emerald-400",
        bgColor: "bg-emerald-500/10",
        borderColor: "border-emerald-500/20",
        fallbackImage: "/assets/missions/regulation.png",
        label: "Régulation"
    },
    ANOMALIE: {
        icon: Zap,
        color: "text-fuchsia-400",
        bgColor: "bg-fuchsia-500/10",
        borderColor: "border-fuchsia-500/20",
        fallbackImage: "/assets/missions/ano1.png",
        label: "Anomalie"
    },
    SONGES: {
        icon: InfinityIcon,
        color: "text-cyan-400",
        bgColor: "bg-cyan-500/10",
        borderColor: "border-cyan-500/20",
        fallbackImage: "/assets/missions/songes.png",
        label: "Songes"
    },
    EXPEDITION: {
        icon: Clock,
        color: "text-amber-400",
        bgColor: "bg-amber-500/10",
        borderColor: "border-amber-500/20",
        fallbackImage: "/assets/missions/expedition.png",
        label: "Expédition"
    },
    EVENT: {
        icon: Sparkles,
        color: "text-yellow-300",
        bgColor: "bg-yellow-500/10",
        borderColor: "border-yellow-500/20",
        fallbackImage: "/assets/missions/event.png",
        label: "Événement"
    },
};

export function MissionPicker({ guildId, selectedIds, onSelect }: MissionPickerProps) {
    const [missions, setMissions] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchMissions = async () => {
            setLoading(true);
            const res = await getMissionsForCalendar(guildId);
            if (res.success && res.data) {
                setMissions(res.data);
            }
            setLoading(false);
        };
        fetchMissions();
    }, [guildId]);

    const toggleSelection = (id: string, title: string) => {
        let newIds: string[];
        let newTitles: string[];

        if (selectedIds.includes(id)) {
            newIds = selectedIds.filter(i => i !== id);
            // This is a bit tricky since we don't store titles, 
            // but we can find them in the current mission list
            newTitles = missions
                .filter(m => newIds.includes(m.id))
                .map(m => m.title || (m.payload as any).dungeonName || (m.payload as any).monsterName || "Objectif");
        } else {
            newIds = [...selectedIds, id];
            newTitles = missions
                .filter(m => newIds.includes(m.id))
                .map(m => m.title || (m.payload as any).dungeonName || (m.payload as any).monsterName || "Objectif");
        }
        onSelect(newIds, newTitles);
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center p-8 bg-zinc-900/50 border border-zinc-800 rounded-xl">
                <Loader2 className="h-6 w-6 text-amber-500 animate-spin mr-3" />
                <span className="text-zinc-400 font-bold uppercase tracking-widest text-xs italic">Chargement des missions...</span>
            </div>
        );
    }

    if (missions.length === 0) {
        return (
            <div className="p-8 text-center bg-zinc-900/50 border border-dashed border-zinc-800 rounded-xl">
                <p className="text-zinc-500 text-sm font-bold italic">Aucune mission active trouvée pour cette semaine.</p>
            </div>
        );
    }

    return (
        <div className="space-y-4">
            <h4 className="text-[10px] font-black uppercase tracking-[3px] text-zinc-500 flex items-center gap-2 px-1">
                <Check className="h-3 w-3 text-emerald-500" />
                Sélectionner les objectifs ({selectedIds.length})
            </h4>
            
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
                {missions
                    .filter(m => m.category !== "DONJON") // Uniquement les vraies missions (Anomalies, Expeditions, etc.)
                    .map((mission) => {
                    const isSelected = selectedIds.includes(mission.id);
                    const config = CATEGORY_CONFIG[mission.category] || CATEGORY_CONFIG.EVENT;
                    const payload = mission.payload || {};
                    
                    // Logic to get image from payload (simplified version of MissionCard)
                    let imageUrl = payload.imageUrl || payload.image || config.fallbackImage;
                    
                    if (mission.category === 'SONGES') {
                        const diff: string = (payload.difficulty || 'Reve').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
                        const levelMap: Record<string, number> = { 'I': 1, 'II': 2, 'III': 3, 'IV': 4 };
                        const lvl = levelMap[payload.level as string] || 1;
                        imageUrl = `/assets/missions/${diff}${lvl}.png`;
                    }

                    const title = mission.title || payload.dungeonName || payload.monsterName || payload.familyName || config.label;

                    return (
                        <button
                            key={mission.id}
                            type="button"
                            onClick={() => toggleSelection(mission.id, title)}
                            className={cn(
                                "group relative aspect-[4/3] rounded-xl border-2 overflow-hidden transition-all duration-300",
                                isSelected 
                                    ? "border-emerald-500 ring-2 ring-emerald-500/20" 
                                    : "border-zinc-800 hover:border-zinc-700 bg-zinc-900/50"
                            )}
                        >
                            {/* Background image */}
                            <div className="absolute inset-0">
                                <Image 
                                    src={imageUrl} 
                                    alt={title} 
                                    fill 
                                    className={cn(
                                        "object-contain p-2 transition-transform duration-500",
                                        isSelected ? "scale-110" : "group-hover:scale-105"
                                    )} 
                                    unoptimized
                                />
                                <div className={cn(
                                    "absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent",
                                    isSelected && "bg-emerald-500/10"
                                )} />
                            </div>

                            {/* Content overlay */}
                            <div className="absolute inset-x-0 bottom-0 p-2 z-10">
                                <p className="text-[9px] font-black text-white uppercase tracking-tighter line-clamp-1 text-shadow">
                                    {title}
                                </p>
                            </div>

                            {/* Selection checkmark */}
                            {isSelected && (
                                <div className="absolute top-2 right-2 h-5 w-5 rounded-full bg-emerald-500 flex items-center justify-center shadow-lg border border-white/20 z-20">
                                    <Check className="h-3 w-3 text-white" />
                                </div>
                            )}

                            {/* Category Indicator */}
                            <div className={cn(
                                "absolute top-2 left-2 p-1 rounded bg-black/60 border border-white/10 backdrop-blur-md z-10",
                                config.color
                            )}>
                                <config.icon className="h-2.5 w-2.5" />
                            </div>
                        </button>
                    );
                })}
            </div>
        </div>
    );
}

