export function RaidHubModal({ open, onOpenChange, guildId, isAdmin }: RaidHubModalProps) {
    const [activeTab, setActiveTab] = useState<RaidTab>("jardin");
    const [config, setConfig] = useState<RaidHubConfig>({
        jardinTips: [],
        gigalodonTips: [],
        jardinDescription: "",
        gigalodonDescription: "",
    });
    const [loading, setLoading] = useState(false);
    const [saving, setSaving] = useState(false);
    const [hasChanges, setHasChanges] = useState(false);

    const loadConfig = useCallback(async () => {
        setLoading(true);
        const result = await getRaidHubConfig(guildId);
        if (result.success && result.config) {
            setConfig(result.config);
        } else {
            toast.error(result.error ?? "Erreur de chargement");
        }
        setLoading(false);
    }, [guildId]);

    useEffect(() => {
        if (open) {
            loadConfig();
            setHasChanges(false);
        }
    }, [open, loadConfig]);

    const handleSave = async () => {
        setSaving(true);
        const result = await updateRaidHubConfig(guildId, config);
        if (result.success) {
            toast.success("Hub Raid sauvegardé !");
            setHasChanges(false);
        } else {
            toast.error(result.error ?? "Erreur de sauvegarde");
        }
        setSaving(false);
    };

    const updateConfig = (updates: Partial<RaidHubConfig>) => {
        setConfig((prev) => ({ ...prev, ...updates }));
        setHasChanges(true);
    };

    const TABS: { id: RaidTab; label: string; icon: any; color: string; activeBg: string; activeBorder: string }[] = [
        {
            id: "jardin",
            label: "Sanctuaire des Jardins Éternels",
            icon: Swords,
            color: "text-red-400",
            activeBg: "bg-red-500/10",
            activeBorder: "border-red-500/40",
        },
        {
            id: "gigalodon",
            label: "Gigalodon",
            icon: Waves,
            color: "text-cyan-400",
            activeBg: "bg-cyan-500/10",
            activeBorder: "border-cyan-500/40",
        },
    ];

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-3xl max-h-[90vh] overflow-hidden flex flex-col bg-zinc-950/98 border border-white/10 ring-1 ring-red-500/20 shadow-[0_0_60px_rgba(239,68,68,0.15)] p-0">
                {/* Header */}
                <div className="relative overflow-hidden px-6 pt-6 pb-4 border-b border-zinc-800/80 shrink-0">
                    <div className="absolute inset-0 bg-gradient-to-r from-red-500/5 via-transparent to-cyan-500/5 pointer-events-none" />
                    <div className="relative flex items-start justify-between gap-4">
                        <div className="flex items-center gap-4">
                            <div className="relative">
                                <div className="absolute inset-0 bg-gradient-to-br from-red-500/20 to-cyan-500/20 rounded-xl blur-lg" />
                                <div className="relative h-12 w-12 rounded-xl bg-gradient-to-br from-red-500/10 to-cyan-500/10 flex items-center justify-center border border-white/10">
                                    <Swords className="h-6 w-6 text-red-400" />
                                </div>
                            </div>
                            <div>
                                <DialogTitle className="text-xl font-black uppercase italic tracking-tighter text-zinc-100">
                                    Hub Raid
                                </DialogTitle>
                                <DialogDescription className="text-zinc-500 font-bold text-xs mt-0.5">
                                    Guides & conseils pour les raids de guilde
                                </DialogDescription>
                            </div>
                        </div>

                        {/* Save button (admin) */}
                        {isAdmin && hasChanges && (
                            <button
                                onClick={handleSave}
                                disabled={saving}
                                className="flex items-center gap-2 px-4 py-2 rounded-xl bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-400 hover:to-orange-400 text-zinc-950 font-bold text-sm shadow-lg shadow-amber-500/25 transition-all hover:scale-105 disabled:opacity-50"
                            >
                                {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
                                Sauvegarder
                            </button>
                        )}
                    </div>

                    {/* Unsaved changes warning */}
                    {isAdmin && hasChanges && !saving && (
                        <div className="relative flex items-center gap-2 mt-3 px-3 py-2 rounded-lg bg-amber-500/10 border border-amber-500/20">
                            <AlertCircle className="h-3.5 w-3.5 text-amber-400 shrink-0" />
                            <p className="text-xs text-amber-400 font-bold">Modifications non sauvegardées</p>
                        </div>
                    )}
                </div>

                {/* Tab Switcher */}
                <div className="flex gap-2 px-6 pt-4 shrink-0">
                    {TABS.map((tab) => {
                        const Icon = tab.icon;
                        const isActive = activeTab === tab.id;
                        return (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id)}
                                className={cn(
                                    "flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-black uppercase tracking-wider border transition-all",
                                    isActive
                                        ? cn(tab.activeBg, tab.color, tab.activeBorder, "shadow-md")
                                        : "bg-zinc-900/50 text-zinc-500 border-zinc-800 hover:border-zinc-700 hover:text-zinc-300"
                                )}
                            >
                                <Icon className={cn("h-4 w-4", isActive ? tab.color : "")} />
                                {tab.label}
                                <ChevronRight className={cn(
                                    "h-3 w-3 transition-transform",
                                    isActive ? "rotate-90 opacity-100" : "opacity-0"
                                )} />
                            </button>
                        );
                    })}

                    {/* Reload */}
                    <button
                        onClick={loadConfig}
                        disabled={loading}
                        className="ml-auto p-2 rounded-lg hover:bg-zinc-800 text-zinc-600 hover:text-zinc-300 transition-all"
                        title="Rafraîchir"
                    >
                        <RefreshCw className={cn("h-4 w-4", loading && "animate-spin")} />
                    </button>
                </div>

                {/* Content Area */}
                <div className="flex-1 overflow-y-auto px-6 py-4 scrollbar-thin scrollbar-thumb-zinc-800 scrollbar-track-transparent">
                    {loading ? (
                        <div className="flex flex-col items-center justify-center py-20 space-y-4">
                            <div className="relative">
                                <div className="h-14 w-14 rounded-full bg-red-500/10 flex items-center justify-center animate-pulse">
                                    <Swords className="h-7 w-7 text-red-500/50" />
                                </div>
                                <Loader2 className="absolute -top-1 -right-1 h-5 w-5 text-red-400 animate-spin" />
                            </div>
                            <p className="text-zinc-500 text-sm">Chargement du Hub Raid...</p>
                        </div>
                    ) : activeTab === "jardin" ? (
                        <RaidTabPanel
                            raidType="jardin"
                            tips={config.jardinTips}
                            description={config.jardinDescription}
                            isAdmin={isAdmin}
                            onUpdateTips={(tips) => updateConfig({ jardinTips: tips })}
                            onUpdateDescription={(desc) => updateConfig({ jardinDescription: desc })}
                        />
                    ) : (
                        <RaidTabPanel
                            raidType="gigalodon"
                            tips={config.gigalodonTips}
                            description={config.gigalodonDescription}
                            isAdmin={isAdmin}
                            onUpdateTips={(tips) => updateConfig({ gigalodonTips: tips })}
                            onUpdateDescription={(desc) => updateConfig({ gigalodonDescription: desc })}
                        />
                    )}
                </div>

                {/* Footer */}
                {isAdmin && (
                    <div className="px-6 py-4 border-t border-zinc-800/80 shrink-0 flex items-center justify-between">
                        <p className="text-xs text-zinc-600 font-bold">
                            {isAdmin ? "Mode édition — visible par tous les membres" : "Vue lecture seule"}
                        </p>
                        {hasChanges && (
                            <button
                                onClick={handleSave}
                                disabled={saving}
                                className="flex items-center gap-2 px-4 py-2 rounded-xl bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-400 hover:to-orange-400 text-zinc-950 font-bold text-sm transition-all hover:scale-105 disabled:opacity-50"
                            >
                                {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
                                Sauvegarder les modifications
                            </button>
                        )}
                    </div>
                )}
            </DialogContent>
        </Dialog>
    );
}

"use client";

/**
 * Registration Modal - Class Selection & Signup
 * Uses existing ClassIcon from shared components
 */

import { useState } from "react";
import { Check, Loader2, User, MessageSquare } from "lucide-react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
    DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";
import { DOFUS_CLASSES } from "@/lib/dofus-assets";
import { ClassIcon, getClassColor } from "@/components/shared/class-icon";

interface RegistrationModalProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    eventTitle: string;
    isFull: boolean;
    onSubmit: (data: { classe?: string; comment?: string }) => Promise<void>;
}

export function RegistrationModal({
    open,
    onOpenChange,
    eventTitle,
    isFull,
    onSubmit,
}: RegistrationModalProps) {
    const [selectedClass, setSelectedClass] = useState<string | null>(null);
    const [comment, setComment] = useState("");
    const [submitting, setSubmitting] = useState(false);

    const handleSubmit = async () => {
        setSubmitting(true);
        try {
            await onSubmit({
                classe: selectedClass || undefined,
                comment: comment || undefined,
            });
            onOpenChange(false);
            setSelectedClass(null);
            setComment("");
        } finally {
            setSubmitting(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent draggable className="max-w-lg bg-zinc-900/95 backdrop-blur-xl border-zinc-800">
                <DialogHeader>
                    <DialogTitle className="text-xl font-bold text-zinc-100">
                        {isFull ? "Rejoindre la file d'attente" : "S'inscrire à l'événement"}
                    </DialogTitle>
                    <DialogDescription className="text-zinc-400">
                        {eventTitle}
                    </DialogDescription>
                </DialogHeader>

                <div className="space-y-6 py-4 max-h-[60vh] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-zinc-700 scrollbar-track-transparent">
                    {/* Class Selection */}
                    <div className="space-y-3">
                        <Label className="text-sm font-medium text-zinc-300 flex items-center gap-2">
                            <User className="h-4 w-4" />
                            Classe Dofus (optionnel)
                        </Label>

                        <div className="grid grid-cols-5 gap-2">
                            {DOFUS_CLASSES.map((classe) => {
                                const isSelected = selectedClass === classe.id;
                                const borderColor = isSelected ? classe.color : undefined;

                                return (
                                    <button
                                        key={classe.id}
                                        type="button"
                                        onClick={() => setSelectedClass(isSelected ? null : classe.id)}
                                        className={cn(
                                            "flex flex-col items-center gap-1 p-2 rounded-lg border-2 transition-all hover:bg-zinc-800/50",
                                            isSelected
                                                ? "ring-2 ring-offset-2 ring-offset-zinc-900"
                                                : "bg-zinc-900/50 border-zinc-800 hover:border-zinc-700"
                                        )}
                                        style={{
                                            borderColor: isSelected ? classe.color : undefined,
                                            boxShadow: isSelected ? `0 0 12px ${classe.color}40` : undefined,
                                            backgroundColor: isSelected ? `${classe.color}10` : undefined,
                                        }}
                                    >
                                        <ClassIcon classId={classe.id} size={28} />
                                        <span className={cn(
                                            "text-[10px] font-medium leading-tight",
                                            isSelected ? "text-white" : "text-zinc-500"
                                        )}>
                                            {classe.name}
                                        </span>
                                    </button>
                                );
                            })}
                        </div>

                        {selectedClass && (
                            <p className="text-xs text-zinc-500">
                                Sélection :{" "}
                                <span style={{ color: getClassColor(selectedClass) }}>
                                    {DOFUS_CLASSES.find(c => c.id === selectedClass)?.name}
                                </span>
                            </p>
                        )}
                    </div>

                    {/* Comment */}
                    <div className="space-y-2">
                        <Label className="text-sm font-medium text-zinc-300 flex items-center gap-2">
                            <MessageSquare className="h-4 w-4" />
                            Note (optionnel)
                        </Label>
                        <Input
                            placeholder="Ex: Perso principal, Multi possible..."
                            value={comment}
                            onChange={(e) => setComment(e.target.value)}
                            className="bg-zinc-900/50 border-zinc-800 text-zinc-100"
                            maxLength={100}
                        />
                    </div>

                    {/* Warning if full */}
                    {isFull && (
                        <div className="p-3 rounded-lg bg-amber-500/10 border border-amber-500/30">
                            <p className="text-sm text-amber-400">
                                ⚠️ L'événement est complet. Vous serez ajouté à la file d'attente et promu automatiquement en cas de désistement.
                            </p>
                        </div>
                    )}
                </div>

                <DialogFooter>
                    <Button
                        variant="ghost"
                        onClick={() => onOpenChange(false)}
                        disabled={submitting}
                        className="text-zinc-400"
                    >
                        Annuler
                    </Button>
                    <Button
                        onClick={handleSubmit}
                        disabled={submitting}
                        className={cn(
                            "font-bold",
                            isFull
                                ? "bg-amber-500 hover:bg-amber-400 text-zinc-950"
                                : "bg-green-600 hover:bg-green-500 text-white"
                        )}
                    >
                        {submitting ? (
                            <Loader2 className="h-4 w-4 animate-spin mr-2" />
                        ) : (
                            <Check className="h-4 w-4 mr-2" />
                        )}
                        {isFull ? "Rejoindre la file" : "Confirmer l'inscription"}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

"use client";

/**
 * UpcomingEventsWidget - Smart Events Preview
 * Shows next events with countdown and quick actions
 */

import { useState, useEffect, useMemo } from "react";
import { format, formatDistanceToNow, isPast, isFuture, isToday, differenceInHours, differenceInMinutes } from "date-fns";
import { fr } from "date-fns/locale";
import {
    Calendar,
    Clock,
    Users,
    ChevronRight,
    Bell,
    Flame,
    Swords,
    PartyPopper,
    Target,
    Wheat
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";

// ============================================
// TYPES
// ============================================

interface UpcomingEvent {
    id: string;
    title: string;
    type: string;
    status: string;
    startDate: Date | string;
    endDate: Date | string;
    maxParticipants?: number | null;
    _count?: { participants: number };
}

interface UpcomingEventsWidgetProps {
    events: UpcomingEvent[];
    onEventClick: (eventId: string) => void;
    onViewAll?: () => void;
    maxEvents?: number;
    compact?: boolean;
}

// ============================================
// TYPE CONFIG
// ============================================

const TYPE_CONFIG: Record<string, { label: string; icon: React.ElementType; color: string; bg: string }> = {
    RAID_OFFICIAL: {
        label: "Raid 3.6",
        icon: Swords,
        color: "text-red-400",
        bg: "bg-red-500/15 border-red-500/30"
    },
    EVENT_GUILD: {
        label: "Event Guilde",
        icon: PartyPopper,
        color: "text-purple-400",
        bg: "bg-purple-500/15 border-purple-500/30"
    },
    SESSION_MISSIONS: {
        label: "Missions Guilde",
        icon: Target,
        color: "text-amber-400",
        bg: "bg-amber-500/15 border-amber-500/30"
    },
    SORTIE_FARM: {
        label: "Sortie Farm",
        icon: Wheat,
        color: "text-emerald-400",
        bg: "bg-emerald-500/15 border-emerald-500/30"
    },
};

// ============================================
// COMPONENT
// ============================================

export function UpcomingEventsWidget({
    events,
    onEventClick,
    onViewAll,
    maxEvents = 3,
    compact = false
}: UpcomingEventsWidgetProps) {
    const [now, setNow] = useState(new Date());

    // Update time every minute for countdown
    useEffect(() => {
        const interval = setInterval(() => setNow(new Date()), 60000);
        return () => clearInterval(interval);
    }, []);

    // Filter and sort upcoming events
    const upcomingEvents = useMemo(() => {
        return events
            .filter(e => {
                const startDate = new Date(e.startDate);
                return isFuture(startDate) || isToday(startDate);
            })
            .sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime())
            .slice(0, maxEvents);
    }, [events, maxEvents]);

    if (upcomingEvents.length === 0) {
        return null; // Don't show widget if no events
    }

    return (
        <div className={cn(
            "rounded-xl border border-zinc-800/50 overflow-hidden",
            compact ? "bg-zinc-900/40" : "bg-gradient-to-br from-zinc-900/80 to-zinc-950/80"
        )}>
            {/* Header */}
            <div className="flex items-center justify-between px-4 py-3 border-b border-zinc-800/30 bg-zinc-900/60">
                <div className="flex items-center gap-2">
                    <div className="h-8 w-8 rounded-lg bg-amber-500/10 flex items-center justify-center">
                        <Calendar className="h-4 w-4 text-amber-400" />
                    </div>
                    <div>
                        <h3 className="text-sm font-bold text-zinc-100">À venir</h3>
                        <p className="text-xs text-zinc-500">{upcomingEvents.length} événement{upcomingEvents.length > 1 ? "s" : ""}</p>
                    </div>
                </div>
                {onViewAll && (
                    <Button
                        variant="ghost"
                        size="sm"
                        onClick={onViewAll}
                        className="h-8 px-2 text-xs text-zinc-400 hover:text-amber-400"
                    >
                        Voir tout
                        <ChevronRight className="h-3 w-3 ml-1" />
                    </Button>
                )}
            </div>

            {/* Events List */}
            <div className="divide-y divide-zinc-800/30">
                {upcomingEvents.map((event) => (
                    <EventRow
                        key={event.id}
                        event={event}
                        now={now}
                        onClick={() => onEventClick(event.id)}
                        compact={compact}
                    />
                ))}
            </div>
        </div>
    );
}

// ============================================
// EVENT ROW
// ============================================

function EventRow({
    event,
    now,
    onClick,
    compact
}: {
    event: UpcomingEvent;
    now: Date;
    onClick: () => void;
    compact?: boolean;
}) {
    const config = TYPE_CONFIG[event.type] || TYPE_CONFIG.EVENT_GUILD;
    const Icon = config.icon;
    const startDate = new Date(event.startDate);
    const hoursUntil = differenceInHours(startDate, now);
    const minutesUntil = differenceInMinutes(startDate, now) % 60;

    // Determine urgency
    const isUrgent = hoursUntil < 2;
    const isTodays = isToday(startDate);

    // Format countdown
    const countdown = useMemo(() => {
        if (hoursUntil < 1) {
            return `${minutesUntil}min`;
        } else if (hoursUntil < 24) {
            return `${hoursUntil}h${minutesUntil > 0 ? minutesUntil : ""}`;
        } else {
            return formatDistanceToNow(startDate, { addSuffix: false, locale: fr });
        }
    }, [hoursUntil, minutesUntil, startDate]);

    return (
        <button
            onClick={onClick}
            className={cn(
                "w-full flex items-center gap-3 p-3 text-left transition-all hover:bg-zinc-800/30 group",
                compact && "p-2.5"
            )}
        >
            {/* Icon */}
            <div className={cn(
                "shrink-0 h-10 w-10 rounded-lg flex items-center justify-center border",
                config.bg,
                compact && "h-8 w-8"
            )}>
                <Icon className={cn("h-5 w-5", config.color, compact && "h-4 w-4")} />
            </div>

            {/* Content */}
            <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                    <span className={cn(
                        "font-semibold text-zinc-100 truncate text-sm",
                        compact && "text-xs"
                    )}>
                        {event.title}
                    </span>
                    {isUrgent && (
                        <Flame className="h-3.5 w-3.5 text-orange-500 animate-pulse shrink-0" />
                    )}
                </div>
                <div className={cn(
                    "flex items-center gap-2 text-xs text-zinc-500 mt-0.5",
                    compact && "text-[10px]"
                )}>
                    <Clock className="h-3 w-3" />
                    {isTodays ? (
                        <span>Aujourd'hui {format(startDate, "HH:mm")}</span>
                    ) : (
                        <span>{format(startDate, "EEE d MMM, HH:mm", { locale: fr })}</span>
                    )}
                    {event._count && (
                        <>
                            <span className="text-zinc-600">•</span>
                            <Users className="h-3 w-3" />
                            <span>
                                {event._count.participants}
                                {event.maxParticipants && `/${event.maxParticipants}`}
                            </span>
                        </>
                    )}
                </div>
            </div>

            {/* Countdown Badge */}
            <Badge
                variant="outline"
                className={cn(
                    "shrink-0 font-bold text-xs",
                    isUrgent
                        ? "bg-orange-500/10 border-orange-500/30 text-orange-400"
                        : isTodays
                            ? "bg-amber-500/10 border-amber-500/30 text-amber-400"
                            : "bg-zinc-800 border-zinc-700 text-zinc-400"
                )}
            >
                {countdown}
            </Badge>

            {/* Arrow */}
            <ChevronRight className="h-4 w-4 text-zinc-600 group-hover:text-zinc-400 transition-colors shrink-0" />
        </button>
    );
}

// ============================================
// COMPACT HEADER VERSION (for global header)
// ============================================

export function UpcomingEventsBadge({
    events,
    onClick
}: {
    events: UpcomingEvent[];
    onClick: () => void;
}) {
    const now = new Date();

    // Find next event
    const nextEvent = useMemo(() => {
        return events
            .filter(e => isFuture(new Date(e.startDate)) || isToday(new Date(e.startDate)))
            .sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime())[0];
    }, [events]);

    if (!nextEvent) return null;

    const startDate = new Date(nextEvent.startDate);
    const hoursUntil = differenceInHours(startDate, now);
    const isUrgent = hoursUntil < 2;
    const config = TYPE_CONFIG[nextEvent.type] || TYPE_CONFIG.EVENT_GUILD;
    const Icon = config.icon;

    return (
        <button
            onClick={onClick}
            className={cn(
                "flex items-center gap-2 px-3 py-1.5 rounded-full border transition-all",
                isUrgent
                    ? "bg-orange-500/10 border-orange-500/30 text-orange-400 animate-pulse"
                    : "bg-zinc-900/60 border-zinc-700/50 text-zinc-400 hover:border-zinc-600"
            )}
        >
            <Icon className="h-4 w-4" />
            <span className="text-xs font-medium truncate max-w-[120px]">
                {nextEvent.title}
            </span>
            <Badge
                variant="outline"
                className={cn(
                    "h-5 text-[10px] font-bold",
                    isUrgent ? "border-orange-500/50 text-orange-300" : "border-zinc-600 text-zinc-400"
                )}
            >
                {hoursUntil < 1 ? `${Math.max(1, differenceInMinutes(startDate, now))}min` : `${hoursUntil}h`}
            </Badge>
        </button>
    );
}

"use client";

import { useState, useEffect } from "react";
