import { ChangelogCategory } from "@prisma/client";

const categoryConfig: Record<ChangelogCategory, { label: string; bg: string; text: string; border: string; icon: any }> = {
    FEATURE: { label: "Nouveauté", bg: "bg-emerald-500/10", text: "text-emerald-400", border: "border-emerald-500/30", icon: Rocket },
    BUGFIX: { label: "Correction", bg: "bg-amber-500/10", text: "text-amber-400", border: "border-amber-500/30", icon: Bug },
    SECURITY: { label: "Sécurité", bg: "bg-red-500/10", text: "text-red-400", border: "border-red-500/30", icon: Shield },
    PERFORMANCE: { label: "Performance", bg: "bg-blue-500/10", text: "text-blue-400", border: "border-blue-500/30", icon: Zap },
    DOCUMENTATION: { label: "Documentation", bg: "bg-purple-500/10", text: "text-purple-400", border: "border-purple-500/30", icon: BookOpen },
};

export function ChangelogModal() {
    const [isOpen, setIsOpen] = useState(false);
    const [changelog, setChangelog] = useState<any>(null);

    useEffect(() => {
        const checkVisibility = async () => {
            try {
                const res = await checkChangelogVisibility();
                if (res.show && res.changelog) {
                    setChangelog(res.changelog);
                    setIsOpen(true);
                }
            } catch (err) {
                console.error("Failed to check changelog visibility", err);
            }
        };
        checkVisibility();
    }, []);

    const handleClose = async () => {
        if (changelog?.id) {
            try {
                await markChangelogAsSeen(changelog.id);
            } catch (err) {
                console.error("Failed to mark changelog as seen", err);
            }
        }
        setIsOpen(false);
    };

    if (!changelog) return null;

    const cat = categoryConfig[changelog.category as ChangelogCategory] || {
        label: changelog.category || "Mise à jour",
        bg: "bg-indigo-500/10",
        text: "text-indigo-400",
        border: "border-indigo-500/30",
        icon: Sparkles,
    };
    const CatIcon = cat.icon;

    return (
        <Dialog open={isOpen} onOpenChange={(open) => !open && handleClose()}>
            <DialogContent className="max-w-2xl w-[92vw] max-h-[85vh] bg-zinc-950/95 border border-white/10 p-0 shadow-[0_0_60px_rgba(0,0,0,0.8)] focus:outline-none focus:ring-0 rounded-2xl flex flex-col overflow-hidden backdrop-blur-xl [&>button:first-of-type]:hidden">
                {/* Header Banner */}
                <div className="relative pt-6 px-6 pb-4 border-b border-white/10 shrink-0 bg-gradient-to-b from-indigo-500/10 via-purple-500/5 to-transparent">
                    {/* Background glow */}
                    <div className="absolute -top-12 -left-12 w-48 h-48 bg-indigo-500/15 rounded-full blur-3xl pointer-events-none" />

                    {/* Close Button */}
                    <button
                        onClick={handleClose}
                        className="absolute top-4 right-4 z-20 p-2 rounded-full bg-zinc-900/80 hover:bg-zinc-800 border border-white/10 text-zinc-400 hover:text-white transition-all shadow-md"
                        title="Fermer"
                    >
                        <X className="w-4 h-4" />
                    </button>

                    <div className="relative z-10 flex flex-col items-start gap-2 pr-8">
                        <div className="flex items-center gap-2 flex-wrap">
                            <span className="px-2.5 py-0.5 rounded-full bg-amber-500/15 border border-amber-500/30 text-amber-400 text-[10px] font-black uppercase tracking-widest flex items-center gap-1.5 shadow-sm">
                                <Sparkles className="w-3 h-3 text-amber-400" /> Version {changelog.version}
                            </span>
                            {changelog.category && (
                                <span className={cn("px-2.5 py-0.5 rounded-full border text-[10px] font-black uppercase tracking-widest flex items-center gap-1.5 shadow-sm", cat.bg, cat.text, cat.border)}>
                                    <CatIcon className="w-3 h-3" /> {cat.label}
                                </span>
                            )}
                        </div>

                        <DialogHeader className="text-left space-y-1">
                            <DialogTitle className="text-xl sm:text-2xl font-black text-zinc-100 tracking-tight leading-tight">
                                {changelog.title}
                            </DialogTitle>
                            <DialogDescription className="sr-only">
                                Nouveautés SigilOS {changelog.version}
                            </DialogDescription>
                        </DialogHeader>
                    </div>
                </div>

                {/* Single Scrollable Content Container (Prevents Double Scrollbars) */}
                <div className="flex-1 overflow-y-auto p-6 scrollbar-thin scrollbar-thumb-zinc-800 scrollbar-track-transparent">
                    <DocContent
                        content={changelog.content}
                        className="
                            prose-p:text-sm prose-p:leading-relaxed prose-p:text-zinc-300
                            prose-headings:text-zinc-100 prose-headings:font-black prose-headings:uppercase prose-headings:tracking-tight prose-headings:mb-3 prose-headings:mt-6
                            prose-h2:text-lg prose-h2:text-amber-400 prose-h2:border-b-0 prose-h2:pb-0
                            prose-h3:text-base prose-h3:text-indigo-400
                            prose-strong:text-amber-300 prose-strong:font-bold
                            prose-ul:list-disc prose-ul:ml-4 prose-li:text-zinc-300 prose-li:text-sm prose-li:my-1
                            prose-hr:border-white/10 prose-hr:my-4
                            [&_.callout]:my-4 [&_.callout]:p-4 [&_.callout]:rounded-xl
                            [&_img]:max-w-full [&_img]:max-h-[380px] [&_img]:w-auto [&_img]:h-auto [&_img]:object-contain [&_img]:rounded-xl [&_img]:border [&_img]:border-white/10 [&_img]:my-3 [&_img]:shadow-lg [&_img]:mx-auto
                            [&_figure]:my-4 [&_figure]:flex [&_figure]:flex-col [&_figure]:items-center
                        "
                    />
                </div>

                {/* Footer Controls */}
                <div className="px-6 py-4 bg-zinc-950 border-t border-white/10 shrink-0 flex items-center justify-between gap-3">
                    <div className="flex flex-col">
                        <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">
                            SigilOS Platform
                        </span>
                        <span className="text-[9px] font-bold text-zinc-600">
                            Build {changelog.version}
                        </span>
                    </div>

                    <Button
                        onClick={handleClose}
                        className="bg-amber-500 hover:bg-amber-400 text-zinc-950 font-black uppercase tracking-wider text-xs h-9 px-5 rounded-xl shadow-lg shadow-amber-500/20 transition-all hover:scale-105"
                    >
                        Compris
                        <ChevronRight className="w-4 h-4 ml-1" />
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { motion, AnimatePresence } from "framer-motion";
import { Check, Shield, ScrollText, BookOpen, Sparkles, Zap, ArrowRight, CheckCircle2, Infinity as InfinityIcon, Users, AlertCircle, Rocket, X } from "lucide-react";
import Link from "next/link";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { BorderBeam } from "@/components/ui/border-beam";
import { useEffect, useState } from "react";

interface OnboardingStep {
    id: string;
    title: string;
    description: string;
    href: string;
    completed: boolean;
    icon: string;
}

export function OnboardingBanner({
    guildId,
    steps,
    title = "Administration",
    subtitle = "Configuration",
    checklistLabel = "Checklist de configuration",
    guideHref,
    variant = "admin",
    dismissible = false,
    storageKey
}: {
    guildId: string,
    steps: OnboardingStep[],
    title?: string,
    subtitle?: string,
    checklistLabel?: string,
    guideHref?: string,
    variant?: "admin" | "user",
    dismissible?: boolean,
    storageKey?: string
}) {
    const [isDismissed, setIsDismissed] = useState(false);
    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setMounted(true);
        if (storageKey) {
            const dismissed = localStorage.getItem(`sigilos-dismiss-${storageKey}`);
            if (dismissed === "true") setIsDismissed(true);
        }
    }, [storageKey]);

    const handleDismiss = () => {
        setIsDismissed(true);
        if (storageKey) {
            localStorage.setItem(`sigilos-dismiss-${storageKey}`, "true");
        }
    };

    const completedSteps = steps.filter(s => s.completed).length;
    const progress = (completedSteps / steps.length) * 100;
    const isFinished = completedSteps === steps.length;

    // Automatic dismissal if everything is done — don't show the banner anymore
    useEffect(() => {
        if (mounted && isFinished) {
            handleDismiss();
        }
    }, [isFinished, mounted]);

    const iconMap = {
        shield: Shield,
        "scroll-text": ScrollText,
        "book-open": BookOpen,
        infinity: InfinityIcon,
        users: Users,
        sparkles: Sparkles,
        zap: Zap,
        rocket: Rocket
    };

    if (isDismissed || !mounted) return null;

    return (
        <div className="relative group/onboarding w-full">
            {/* Animated Glow when incomplete */}
            {!isFinished && (
                <div className={cn(
                    "absolute -inset-[2px] rounded-2xl blur-md opacity-30 animate-pulse-slow",
                    variant === "user" ? "bg-gradient-to-r from-blue-500/40 via-indigo-500/40 to-blue-500/40" : "bg-gradient-to-r from-emerald-500/40 via-teal-500/40 to-emerald-500/40"
                )} />
            )}

            <div className={cn(
                "relative glass-premium p-6 md:p-8 rounded-2xl border border-white/10 overflow-hidden transition-all duration-500 group-hover/onboarding:border-white/20",
                variant === "user" ? "ring-1 ring-blue-500/20 shadow-[0_0_30px_rgba(59,130,246,0.1)]" : "ring-1 ring-emerald-500/20 shadow-[0_0_30px_rgba(16,185,129,0.1)]",
                !isFinished ? "opacity-100" : "opacity-90"
            )}>
                {dismissible && (
                    <button
                        onClick={handleDismiss}
                        className="absolute top-4 right-4 p-2 rounded-full hover:bg-white/10 text-zinc-500 hover:text-white transition-all z-20 group/close"
                    >
                        <X className="w-4 h-4 group-hover/close:rotate-90 transition-transform" />
                    </button>
                )}
                
                {!isFinished && (
                    <BorderBeam
                        size={200}
                        duration={6}
                        colorFrom={variant === "user" ? "#3b82f6" : "#10b981"}
                        colorTo={variant === "user" ? "#60a5fa" : "#34d399"}
                    />
                )}

                <div className="relative z-10 flex flex-col lg:flex-row lg:items-center justify-between gap-8">
                    <div className="space-y-6 flex-1 max-w-2xl">
                        <div className="flex items-start gap-4">
                            <div className={cn(
                                "p-3 rounded-2xl border transition-colors",
                                !isFinished
                                    ? (variant === "user" ? "bg-blue-500/20 border-blue-500/30 text-blue-400 group-hover/onboarding:scale-110 duration-500" : "bg-emerald-500/20 border-emerald-500/30 text-emerald-400 group-hover/onboarding:scale-110 duration-500")
                                    : "bg-zinc-500/10 border-white/10 text-zinc-400"
                            )}>
                                {isFinished ? (
                                    <CheckCircle2 className="w-6 h-6" />
                                ) : (
                                    variant === "user" ? <Sparkles className="w-6 h-6 animate-pulse" /> : <Rocket className="w-6 h-6 animate-bounce-subtle" />
                                )}
                            </div>
                            <div className="space-y-1">
                                <div className="flex items-center gap-2">
                                    <span className={cn(
                                        "text-[10px] font-black uppercase tracking-[0.4em] leading-none",
                                        variant === "user" ? "text-blue-400/80" : "text-emerald-400/80"
                                    )}>
                                        {isFinished ? (variant === "user" ? "Prêt pour l'aventure" : "Succès") : (variant === "user" ? "Préparation" : "Configuration Nécessaire")}
                                    </span>
                                    {!isFinished && (
                                        <div className={cn(
                                            "flex items-center gap-1 px-1.5 py-0.5 rounded-full border",
                                            variant === "user" ? "bg-blue-500/10 border-blue-500/20" : "bg-emerald-500/10 border-emerald-500/20"
                                        )}>
                                            <span className={cn(
                                                "w-1 h-1 rounded-full animate-ping",
                                                variant === "user" ? "bg-blue-400" : "bg-emerald-400"
                                            )} />
                                            <span className={cn(
                                                "text-[8px] font-black uppercase tracking-tighter",
                                                variant === "user" ? "text-blue-400" : "text-emerald-400"
                                            )}>Priorité</span>
                                        </div>
                                    )}
                                </div>
                                <h2 className="text-2xl md:text-3xl font-black tracking-tighter text-white">
                                    {isFinished
                                        ? (variant === "user" ? "Votre profil est prêt !" : "Votre Guilde est prête !")
                                        : title}
                                </h2>
                                <p className="text-zinc-400 text-sm font-medium leading-relaxed max-w-md">
                                    {isFinished
                                        ? (variant === "user"
                                            ? "Vous avez configuré les piliers essentiels de votre identité. Profitez pleinement de SigilOS !"
                                            : "Tous les systèmes sont opérationnels. Vos membres peuvent désormais profiter pleinement du dashboard.")
                                        : (variant === "user"
                                            ? "Suivez ces quelques étapes pour préparer votre profil et faciliter votre intégration dans l'écosystème de la guilde."
                                            : "Il reste quelques étapes pour que votre guilde bénéficie de l'expérience complète de SigilOS.")}
                                </p>
                            </div>
                        </div>

                        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-6 pt-2">
                            {guideHref && !isFinished && (
                                <Button asChild variant={variant === "user" ? "sigil" : "sigil-emerald"} className="h-12 px-8">
                                    <Link href={guideHref}>
                                        {variant === "user" ? "MON PARCOURS" : "AVANCEMENT"}
                                        <ArrowRight className="ml-2 w-5 h-5 group-hover/btn:translate-x-2 transition-transform" />
                                    </Link>
                                </Button>
                            )}

                            <div className="flex-1 min-w-[200px] space-y-2">
                                <div className="flex justify-between text-[10px] font-black uppercase tracking-widest">
                                    <span className="text-zinc-500">{checklistLabel}</span>
                                    <span className={variant === "user" ? "text-blue-400" : "text-emerald-400"}>{completedSteps} / {steps.length}</span>
                                </div>
                                <div className="h-2 w-full bg-zinc-900 rounded-full overflow-hidden border border-white/5">
                                    <motion.div
                                        initial={{ width: 0 }}
                                        animate={{ width: `${progress}%` }}
                                        transition={{ duration: 1, ease: "easeOut" }}
                                        className={cn(
                                            "h-full transition-all duration-500",
                                            variant === "user" ? "bg-gradient-to-r from-blue-600 to-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.5)]" : "bg-gradient-to-r from-emerald-600 to-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.5)]"
                                        )}
                                    />
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="grid grid-cols-3 sm:flex items-center gap-4">
                        {steps.map((step, idx) => {
                            const Icon = iconMap[step.icon as keyof typeof iconMap] || Sparkles;
                            return (
                                <Link key={step.id} href={step.href} className="contents">
                                    <motion.div
                                        initial={{ opacity: 0, y: 10 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        transition={{ delay: 0.1 * idx }}
                                        className={cn(
                                            "relative p-4 rounded-2xl border transition-all hover:scale-110 active:scale-95 group/step flex flex-col items-center gap-3 min-w-[90px]",
                                            step.completed
                                                ? (variant === "user" ? "bg-blue-500/10 border-blue-500/30 text-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.1)]" : "bg-emerald-500/10 border-emerald-500/30 text-emerald-400")
                                                : "bg-white/5 border-white/10 text-zinc-500 hover:border-white/30 hover:bg-white/10"
                                        )}
                                    >
                                        <Icon className={cn("w-6 h-6", !step.completed && "grayscale opacity-50")} />
                                        <span className="text-[8px] font-black uppercase tracking-widest text-center leading-tight">{step.title}</span>

                                        {step.completed && (
                                            <div className={cn(
                                                "absolute -top-1.5 -right-1.5 rounded-full p-1 border-2 border-zinc-950 shadow-lg",
                                                variant === "user" ? "bg-blue-500" : "bg-emerald-500"
                                            )}>
                                                <Check className="w-2.5 h-2.5 text-white" />
                                            </div>
                                        )}

                                        <div className="absolute -bottom-12 left-1/2 -translate-x-1/2 bg-zinc-900 border border-white/10 p-2 rounded-lg opacity-0 group-hover/step:opacity-100 pointer-events-none transition-all z-50 whitespace-nowrap scale-90 group-hover/step:scale-100 origin-top">
                                            <p className="text-[9px] font-black uppercase tracking-widest text-white">{step.description}</p>
                                        </div>
                                    </motion.div>
                                </Link>
                            );
                        })}
                    </div>
                </div>

                <div className="absolute -bottom-10 -right-10 p-8 opacity-[0.03] pointer-events-none group-hover/onboarding:opacity-[0.07] transition-opacity duration-1000 group-hover/onboarding:rotate-0 rotate-12">
                    {variant === "user" ? <Sparkles className="w-64 h-64 text-white" /> : <Shield className="w-64 h-64 text-white" />}
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { 
    Sparkles, 
    Sword, 
    Check, 
    AlertTriangle, 
    Loader2, 
    Compass, 
    ArrowRight,
    User
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { DOFUS_CLASSES } from "@/lib/dofus-assets";
import { updateUserProfile } from "@/server/actions/profile-actions";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

import { useRouter } from "next/navigation";

interface OnboardingWizardProps {
    guildId: string;
    userName: string;
    show: boolean;
    initialStep?: number;
    initialPseudo?: string;
}

export function OnboardingWizard({ guildId, userName, show, initialStep = 1, initialPseudo = "" }: OnboardingWizardProps) {
    const router = useRouter();
    const [isOpen, setIsOpen] = useState(false);
    const [step, setStep] = useState(initialStep);
    const [pseudo, setPseudo] = useState(initialPseudo);
    const [selectedClass, setSelectedClass] = useState("");
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (show) {
            setIsOpen(true);
        }
    }, [show]);

    const handlePseudoSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);

        const trimmed = pseudo.trim();
        if (!trimmed) {
            setError("Le pseudo est obligatoire.");
            return;
        }

        if (trimmed.length < 2 || trimmed.length > 50) {
            setError("Le pseudo doit faire entre 2 et 50 caractères.");
            return;
        }

        // Simple client-side regex check matching UpdateProfileSchema regex
        const pseudoRegex = /^[a-zA-Z\u00C0-\u017F\u00DF\u00FF\u0100-\u017F\-\s\[\]]*$/;
        if (!pseudoRegex.test(trimmed)) {
            setError("Le pseudo ne doit contenir que des lettres, espaces, tirets et crochets.");
            return;
        }

        setLoading(true);
        try {
            // Validate the pseudo by trying to write it temporarily or just moving to the next step
            // We actually call updateUserProfile with just the pseudo first
            const res = await updateUserProfile({
                guildId,
                pseudoDofus: trimmed
            });

            if (res.success) {
                setStep(2);
            } else {
                setError(res.error || "Pseudo invalide ou introuvable sur le ladder officiel Ankama.");
            }
        } catch (err: any) {
            setError("Une erreur est survenue lors de la validation du pseudo.");
        } finally {
            setLoading(false);
        }
    };

    const handleClassSubmit = async () => {
        if (!selectedClass) {
            toast.error("Veuillez sélectionner une classe.");
            return;
        }

        setLoading(true);
        try {
            // Only re-submit pseudoDofus if the user typed it during this session (step 1).
            // If we started at step 2 (pseudo already valid in DB), skip it to avoid
            // re-triggering the Ankama ladder check.
            const payload: Parameters<typeof updateUserProfile>[0] = {
                guildId,
                classe: selectedClass,
                ...(pseudo.trim() !== initialPseudo ? { pseudoDofus: pseudo.trim() } : {})
            };
            const res = await updateUserProfile(payload);

            if (res.success) {
                toast.success("Profil configuré avec succès ! Bienvenue à bord.");
                setIsOpen(false);
                router.push(`/dashboard/${guildId}/profile?tour=1`);
            } else {
                toast.error(res.error || "Une erreur est survenue lors de la sauvegarde.");
            }
        } catch (err) {
            toast.error("Erreur serveur lors de la sauvegarde de la classe.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <AnimatePresence>
            {isOpen && (
                <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 md:p-6">
                    {/* Backdrop (Forced: cannot click outside) */}
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="absolute inset-0 bg-black/95 backdrop-blur-md"
                    />

                    {/* Modal Content */}
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95, y: 20 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.95, y: 20 }}
                        className="relative w-full max-w-xl glass-premium rounded-3xl border border-white/10 overflow-hidden shadow-[0_0_60px_rgba(139,92,246,0.25)] bg-zinc-950/80 backdrop-blur-2xl"
                    >
                        {/* Decorative background glows */}
                        <div className="absolute -top-24 -left-24 w-64 h-64 bg-violet-600/20 rounded-full blur-[100px]" />
                        <div className="absolute -bottom-24 -right-24 w-64 h-64 bg-indigo-500/10 rounded-full blur-[100px]" />

                        <div className="relative z-10 p-6 sm:p-10 flex flex-col items-center text-center space-y-6">
                            {/* Step indicators — 2 dots for full flow, 1 dot for class-only */}
                            <div className="flex items-center gap-3">
                                {initialStep === 1 && (
                                    <div className={cn("w-2 h-2 rounded-full transition-all duration-300", step === 1 ? "bg-violet-500 scale-125 shadow-[0_0_8px_#8b5cf6]" : "bg-white/20")} />
                                )}
                                <div className={cn("w-2 h-2 rounded-full transition-all duration-300", step === 2 ? "bg-violet-500 scale-125 shadow-[0_0_8px_#8b5cf6]" : "bg-white/20")} />
                            </div>

                            {step === 1 && (
                                <motion.div 
                                    initial={{ opacity: 0, x: -10 }}
                                    animate={{ opacity: 1, x: 0 }}
                                    className="w-full space-y-6"
                                >
                                    <div className="space-y-2">
                                        <div className="relative w-16 h-16 mx-auto mb-4 rounded-2xl bg-gradient-to-br from-violet-500 to-indigo-600 flex items-center justify-center shadow-xl">
                                            <User className="w-8 h-8 text-white" />
                                            <Sparkles className="absolute -top-1 -right-1 w-4 h-4 text-amber-400" />
                                        </div>
                                        <h2 className="text-2xl font-black text-white tracking-tight uppercase italic">
                                            Identifie ton <span className="text-violet-400">Personnage</span>
                                        </h2>
                                        <p className="text-zinc-400 text-xs font-semibold leading-relaxed max-w-sm mx-auto">
                                            Renseigne ton pseudo exact en jeu. Le site l'utilisera pour synchroniser tes succès et ton activité sur le Ladder !
                                        </p>
                                    </div>

                                    <form onSubmit={handlePseudoSubmit} className="space-y-4 text-left max-w-md mx-auto">
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500 pl-1">Pseudo Dofus Exact</label>
                                            <Input
                                                placeholder="Ex: Dark-Iop"
                                                value={pseudo}
                                                onChange={(e) => setPseudo(e.target.value)}
                                                className="bg-black/50 border-white/10 h-12 text-sm font-medium rounded-xl focus-visible:ring-violet-500/30 text-white"
                                                disabled={loading}
                                                autoFocus
                                            />
                                        </div>

                                        {error && (
                                            <div className="flex items-start gap-2.5 p-3 rounded-xl bg-rose-500/10 border border-rose-500/20 text-rose-400 text-xs font-medium">
                                                <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5" />
                                                <span>{error}</span>
                                            </div>
                                        )}

                                        <Button
                                            type="submit"
                                            className="w-full h-12 bg-violet-600 hover:bg-violet-700 font-black uppercase tracking-widest text-xs rounded-xl shadow-[0_4px_15px_rgba(139,92,246,0.3)] transition-all active:scale-95 text-white gap-2"
                                            disabled={loading}
                                        >
                                            {loading ? (
                                                <>
                                                    <Loader2 className="w-4 h-4 animate-spin" />
                                                    Validation avec le Ladder...
                                                </>
                                            ) : (
                                                <>
                                                    Continuer
                                                    <ArrowRight className="w-4 h-4" />
                                                </>
                                            )}
                                        </Button>
                                    </form>
                                </motion.div>
                            )}

                            {step === 2 && (
                                <motion.div 
                                    initial={{ opacity: 0, x: 10 }}
                                    animate={{ opacity: 1, x: 0 }}
                                    className="w-full space-y-6"
                                >
                                    <div className="space-y-2">
                                        <div className="relative w-16 h-16 mx-auto mb-4 rounded-2xl bg-gradient-to-br from-violet-500 to-indigo-600 flex items-center justify-center shadow-xl">
                                            <Sword className="w-8 h-8 text-white" />
                                        </div>
                                        <h2 className="text-2xl font-black text-white tracking-tight uppercase italic">
                                            Choisis ta <span className="text-violet-400">Classe</span>
                                        </h2>
                                        <p className="text-zinc-400 text-xs font-semibold leading-relaxed max-w-sm mx-auto">
                                            Sélectionne la classe de ton personnage principal pour compléter ton badge de guilde.
                                        </p>
                                    </div>

                                    {/* Grid of classes */}
                                    <div className="grid grid-cols-4 sm:grid-cols-6 gap-2 max-h-[240px] overflow-y-auto pr-1 scrollbar-thin scrollbar-thumb-white/10 w-full text-center">
                                        {DOFUS_CLASSES.map((cls) => {
                                            const isSelected = selectedClass === cls.id;
                                            return (
                                                <button
                                                    key={cls.id}
                                                    type="button"
                                                    onClick={() => setSelectedClass(cls.id)}
                                                    className={cn(
                                                        "flex flex-col items-center justify-center p-2 rounded-xl border transition-all relative group",
                                                        isSelected 
                                                            ? "bg-violet-500/20 border-violet-500 shadow-[0_0_12px_rgba(139,92,246,0.2)]" 
                                                            : "bg-white/[0.02] border-white/5 hover:bg-white/[0.05] hover:border-white/15"
                                                    )}
                                                >
                                                    <div className="w-10 h-10 relative flex items-center justify-center">
                                                        <img src={cls.icon} alt={cls.name} className="w-8 h-8 object-contain" />
                                                    </div>
                                                    <span className="text-[9px] font-black uppercase tracking-tight text-zinc-400 mt-1 truncate w-full group-hover:text-white transition-colors">{cls.name}</span>
                                                    {isSelected && (
                                                        <div className="absolute -top-1 -right-1 bg-violet-500 rounded-full p-0.5 shadow-md">
                                                            <Check className="w-2.5 h-2.5 text-white" />
                                                        </div>
                                                    )}
                                                </button>
                                            );
                                        })}
                                    </div>

                                    <div className="flex gap-3 max-w-md mx-auto w-full">
                                        {initialStep === 1 && (
                                            <Button
                                                type="button"
                                                variant="outline"
                                                onClick={() => setStep(1)}
                                                className="h-12 border-white/10 bg-white/5 hover:bg-white/10 text-xs font-black uppercase tracking-widest rounded-xl transition-all"
                                                disabled={loading}
                                            >
                                                Retour
                                            </Button>
                                        )}
                                        <Button
                                            type="button"
                                            onClick={handleClassSubmit}
                                            className="flex-1 h-12 bg-violet-600 hover:bg-violet-700 font-black uppercase tracking-widest text-xs rounded-xl shadow-[0_4px_15px_rgba(139,92,246,0.3)] transition-all active:scale-95 text-white gap-2"
                                            disabled={loading || !selectedClass}
                                        >
                                            {loading ? (
                                                <Loader2 className="w-4 h-4 animate-spin" />
                                            ) : (
                                                "Terminer"
                                            )}
                                        </Button>
                                    </div>
                                </motion.div>
                            )}
                        </div>

                        {/* Bottom decorative bar */}
                        <div className="absolute bottom-0 left-0 w-full h-1 bg-gradient-to-r from-violet-500 via-indigo-500 to-purple-500" />
                    </motion.div>
                </div>
            )}
        </AnimatePresence>
    );
}

"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
    Rocket,
    X,
    ArrowRight,
    Sparkles,
    Shield,
    Puzzle,
    BookOpen,
    Swords
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { markWelcomeAsSeen } from "@/server/actions/onboarding-actions";
import Link from "next/link";
import { cn } from "@/lib/utils";

interface WelcomeModalProps {
    guildId: string;
    show: boolean;
}

export function WelcomeModal({ guildId, show }: WelcomeModalProps) {
    const [isOpen, setIsOpen] = useState(false);

    useEffect(() => {
        if (show) {
            setIsOpen(true);
        }
    }, [show]);

    const handleClose = async () => {
        setIsOpen(false);
        await markWelcomeAsSeen(guildId);
    };

    return (
        <AnimatePresence>
            {isOpen && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-6">
                    {/* Backdrop — non-cliquable pour forcer l'action */}
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="absolute inset-0 bg-black/80 backdrop-blur-md"
                    />

                    {/* Modal Content */}
                    <motion.div
                        initial={{ opacity: 0, scale: 0.9, y: 20 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.9, y: 20 }}
                        className="relative w-full max-w-2xl max-h-[90vh] overflow-y-auto glass-premium rounded-2xl md:rounded-3xl border border-white/15 overflow-hidden shadow-[0_0_50px_rgba(99,102,241,0.2)]"
                    >
                        {/* Decorative background glow */}
                        <div className="absolute -top-24 -left-24 w-64 h-64 bg-emerald-500/10 rounded-full blur-[100px]" />
                        <div className="absolute -bottom-24 -right-24 w-64 h-64 bg-teal-500/10 rounded-full blur-[100px]" />

                        <div className="relative z-10 p-5 sm:p-8 md:p-12 flex flex-col items-center text-center space-y-5 md:space-y-8">
                            {/* Close Button — always visible */}
                            <button
                                onClick={handleClose}
                                className="absolute top-3 right-3 sm:top-6 sm:right-6 p-2 rounded-full bg-white/5 border border-white/10 text-zinc-400 hover:text-white hover:bg-white/10 transition-all z-20"
                            >
                                <X className="w-4 h-4 sm:w-5 sm:h-5" />
                            </button>

                            {/* Icon Header */}
                            <div className="relative pt-2">
                                <div className="absolute inset-0 bg-indigo-500 blur-2xl opacity-20 animate-pulse" />
                                <div className="relative w-14 h-14 sm:w-20 sm:h-20 rounded-[1.5rem] sm:rounded-[2rem] bg-gradient-to-br from-emerald-500 to-teal-600 flex items-center justify-center shadow-2xl">
                                    <Rocket className="w-7 h-7 sm:w-10 sm:h-10 text-white" />
                                </div>
                                <div className="absolute -top-2 -right-2 p-1.5 rounded-full bg-emerald-500 shadow-xl border-2 border-zinc-950">
                                    <Sparkles className="w-3 h-3 text-white" />
                                </div>
                            </div>

                            {/* Text Content */}
                            <div className="space-y-3">
                                <h2 className="text-2xl sm:text-3xl md:text-4xl font-black text-white tracking-tighter uppercase font-heading">
                                    Bienvenue sur <span className="text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-teal-400">SigilOS</span>
                                </h2>
                                <p className="text-zinc-400 font-medium max-w-sm sm:max-w-md mx-auto text-sm sm:text-base md:text-lg leading-relaxed">
                                    Félicitations ! Vous êtes désormais aux commandes de votre guilde sur la plateforme de gestion la plus avancée du Monde des Douze.
                                </p>
                            </div>

                            {/* Features Grid (Small) */}
                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 w-full pt-4">
                                <div className="flex flex-col items-center gap-2">
                                    <div className="p-3 rounded-xl bg-white/5 border border-white/10 text-indigo-400">
                                        <Shield className="w-5 h-5" />
                                    </div>
                                    <span className="text-[9px] font-black uppercase text-zinc-500 tracking-widest">Bot Discord</span>
                                </div>
                                <div className="flex flex-col items-center gap-2">
                                    <div className="p-3 rounded-xl bg-white/5 border border-white/10 text-purple-400">
                                        <Puzzle className="w-5 h-5" />
                                    </div>
                                    <span className="text-[9px] font-black uppercase text-zinc-500 tracking-widest">Modules</span>
                                </div>
                                <div className="flex flex-col items-center gap-2">
                                    <div className="p-3 rounded-xl bg-white/5 border border-white/10 text-emerald-400">
                                        <Swords className="w-5 h-5" />
                                    </div>
                                    <span className="text-[9px] font-black uppercase text-zinc-500 tracking-widest">Missions</span>
                                </div>
                                <div className="flex flex-col items-center gap-2">
                                    <div className="p-3 rounded-xl bg-white/5 border border-white/10 text-blue-400">
                                        <BookOpen className="w-5 h-5" />
                                    </div>
                                    <span className="text-[9px] font-black uppercase text-zinc-500 tracking-widest">Wiki</span>
                                </div>
                            </div>

                            {/* Actions */}
                            <div className="flex flex-col items-center gap-3 pt-3 w-full max-w-md">
                                <Button
                                    asChild
                                    className="w-full h-12 bg-white text-black hover:bg-zinc-200 font-black uppercase tracking-[0.15em] text-xs rounded-2xl group"
                                >
                                    <Link href={`/dashboard/${guildId}/admin/getting-started`} onClick={handleClose}>
                                        Lancer la configuration
                                        <ArrowRight className="ml-2 w-4 h-4 group-hover:translate-x-1 transition-transform" />
                                    </Link>
                                </Button>
                            </div>
                        </div>

                        {/* Bottom decorative bar */}
                        <div className="absolute bottom-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-purple-500 to-emerald-500" />
                    </motion.div>
                </div>
            )}
        </AnimatePresence>
    );
}

"use client";

import { useState, useMemo } from "react";
import { cn } from "@/lib/utils";
import { DAYS_OF_WEEK, TIME_SLOTS, type GlobalAvailability, type DayOfWeek, type TimeSlot } from "@/lib/dofus-assets";
import { format, addWeeks, startOfWeek, endOfWeek, getISOWeek, getYear } from "date-fns";
import { fr } from "date-fns/locale";
import { ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, CalendarDays, Plane, Sunrise, Sun, Moon, AlertCircle, Search, Sunset, Sparkles } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import Link from "next/link";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { startOfMonth, differenceInWeeks, addMonths, isSameMonth } from "date-fns";

const SLOT_INFO: Record<TimeSlot, { icon: any, label: string, color: string, bg: string, border: string }> = {
    matin: { icon: Sunrise, label: "Matin", color: "text-orange-500", bg: "bg-orange-500/10", border: "border-orange-500/20" },
    midi: { icon: Sun, label: "Midi", color: "text-amber-400", bg: "bg-amber-400/10", border: "border-amber-400/20" },
    soir: { icon: Sunset, label: "Soir", color: "text-violet-400", bg: "bg-violet-500/10", border: "border-violet-500/20" },
    nuit: { icon: Moon, label: "Nuit", color: "text-indigo-400", bg: "bg-indigo-500/10", border: "border-indigo-500/20" },
};

interface GuildAbsenceCalendarProps {
    members: any[];
    guildId: string;
}

// Removed TIME_SLOT_COLORS as we use SLOT_INFO now

export function GuildAbsenceCalendar({ members, guildId }: GuildAbsenceCalendarProps) {
    const [weekOffset, setWeekOffset] = useState(0);
    const [search, setSearch] = useState("");

    const currentMonday = useMemo(() => {
        const now = new Date();
        const start = startOfWeek(now, { weekStartsOn: 1 });
        return addWeeks(start, weekOffset);
    }, [weekOffset]);

    const currentWeekKey = useMemo(() => {
        const year = getYear(currentMonday);
        const week = getISOWeek(currentMonday);
        return `${year}-W${week}`;
    }, [currentMonday]);

    const weekDates = useMemo(() => {
        const dates: Record<DayOfWeek, Date> = {} as any;
        DAYS_OF_WEEK.forEach((day, idx) => {
            const date = new Date(currentMonday);
            date.setDate(currentMonday.getDate() + idx);
            dates[day] = date;
        });
        return dates;
    }, [currentMonday]);

    const isToday = (date: Date) => {
        const today = new Date();
        return today.getDate() === date.getDate() &&
            today.getMonth() === date.getMonth() &&
            today.getFullYear() === date.getFullYear();
    };

    const isVacation = (member: any, date: Date) => {
        if (!member.vacationStart || !member.vacationEnd) return false;
        const d = new Date(date); d.setHours(12, 0, 0, 0);
        const start = new Date(member.vacationStart); start.setHours(0, 0, 0, 0);
        const end = new Date(member.vacationEnd); end.setHours(23, 59, 59, 999);
        return d >= start && d <= end;
    };

    const getMemberAvailabilityForDay = (member: any, day: DayOfWeek) => {
        const availability = member.availability as GlobalAvailability | undefined;
        if (!availability) return null;
        
        // Handle both new GlobalAvailability and legacy format
        const isLegacy = Object.keys(availability).some(k => DAYS_OF_WEEK.includes(k as any));
        const template = isLegacy ? availability : (availability.template || {});
        const weekData = (!isLegacy && availability.weeks) ? availability.weeks[currentWeekKey] : null;
        
        const effectiveData = weekData || template;
        return effectiveData[day] || [];
    };

    const filteredMembers = useMemo(() => {
        const searchTerm = search.toLowerCase();
        
        // 1. Filter members first
        const matched = members.filter(m => {
            const match = 
                (m.pseudoDofus || "").toLowerCase().includes(searchTerm) ||
                (m.user?.name || "").toLowerCase().includes(searchTerm) ||
                (m.discordNickname || "").toLowerCase().includes(searchTerm);
            return match;
        });

        // 2. Precompute vacation status for the current week to avoid overhead in the sort loop
        const membersWithVacationStatus = matched.map(m => {
            const hasVacationThisWeek = DAYS_OF_WEEK.some(day => isVacation(m, weekDates[day]));
            return {
                member: m,
                hasVacationThisWeek,
                name: (m.pseudoDofus || m.discordNickname || m.user?.name || "").toLowerCase()
            };
        });

        // 3. Sort on precomputed values
        membersWithVacationStatus.sort((a, b) => {
            if (a.hasVacationThisWeek && !b.hasVacationThisWeek) return -1;
            if (!a.hasVacationThisWeek && b.hasVacationThisWeek) return 1;
            return a.name.localeCompare(b.name);
        });

        // 4. Return original objects
        return membersWithVacationStatus.map(x => x.member);
    }, [members, search, weekDates]);

    return (
        <div className="space-y-6 animate-in fade-in duration-700">
            {/* Toolbar */}
            <div className="relative overflow-hidden flex flex-col md:flex-row items-center justify-between gap-4 p-5 rounded-[2rem] bg-zinc-950/40 border border-white/5 shadow-2xl backdrop-blur-3xl group/toolbar">
                <div className="noise-overlay absolute inset-0 opacity-[0.03] pointer-events-none" />
                <div className="absolute inset-0 bg-gradient-to-br from-white/[0.02] to-transparent pointer-events-none" />
                
                <div className="relative w-full md:w-72 group/search">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground group-focus-within/search:text-indigo-400 transition-colors" />
                    <Input
                        placeholder="Chercher un membre..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        className="pl-10 bg-white/5 border-white/10 hover:border-white/20 focus-visible:ring-indigo-500/30 rounded-xl"
                    />
                </div>

                <div className="flex items-center gap-1 bg-zinc-900 p-1.5 rounded-xl border border-white/10 shadow-inner">
                    <button
                        onClick={() => setWeekOffset(prev => prev - 4)}
                        className="p-1.5 hover:bg-white/10 rounded-lg text-zinc-500 hover:text-white transition-all"
                        title="-1 Mois"
                    >
                        <ChevronsLeft className="w-4 h-4" />
                    </button>
                    <button
                        onClick={() => setWeekOffset(prev => prev - 1)}
                        className="p-1.5 hover:bg-white/10 rounded-lg text-zinc-400 hover:text-white transition-all"
                        title="-1 Semaine"
                    >
                        <ChevronLeft className="w-5 h-5" />
                    </button>
                    <Popover>
                        <PopoverTrigger asChild>
                            <div className="px-4 text-sm font-black text-zinc-200 min-w-[180px] text-center flex items-center justify-center gap-2 cursor-pointer hover:text-indigo-400 hover:scale-105 transition-all duration-300 group/week" title="Choisir un mois">
                                <CalendarDays className={cn(
                                    "w-4 h-4 transition-colors",
                                    weekOffset === 0 ? "text-indigo-400" : "text-zinc-500 group-hover:text-indigo-400"
                                )} />
                                <span className="uppercase tracking-widest italic">
                                    {weekOffset === 0 ? "Cette semaine" : format(currentMonday, "d MMM", { locale: fr }) + " - " + format(endOfWeek(currentMonday, { weekStartsOn: 1 }), "d MMM yyyy", { locale: fr })}
                                </span>
                            </div>
                        </PopoverTrigger>
                        <PopoverContent className="w-[320px] p-4 glass-premium border-white/10 shadow-2xl overflow-hidden" align="center">
                            <div className="noise-overlay absolute inset-0 opacity-[0.03] pointer-events-none" />
                            <div className="relative z-10">
                                <div className="flex items-center gap-2 mb-4">
                                    <div className="w-8 h-8 rounded-lg bg-indigo-500/10 flex items-center justify-center border border-indigo-500/20">
                                        <Sparkles className="w-4 h-4 text-indigo-400" />
                                    </div>
                                    <h4 className="text-[10px] font-black uppercase text-zinc-400 tracking-[0.2em]">Sauter vers un mois</h4>
                                </div>
                                
                                <div className="grid grid-cols-2 gap-2">
                                    {[0, 1, 2, 3, 4, 5].map((monthAdd) => {
                                        const targetMonth = addMonths(new Date(), monthAdd);
                                        const isActive = isSameMonth(targetMonth, currentMonday);
                                        
                                        return (
                                            <button
                                                key={monthAdd}
                                                onClick={() => {
                                                    const now = new Date();
                                                    const startOfTarget = startOfMonth(targetMonth);
                                                    const mondayOfTarget = startOfWeek(startOfTarget, { weekStartsOn: 1 });
                                                    const mondayOfNow = startOfWeek(now, { weekStartsOn: 1 });
                                                    const offset = differenceInWeeks(mondayOfTarget, mondayOfNow);
                                                    setWeekOffset(offset);
                                                }}
                                                className={cn(
                                                    "group/m relative flex flex-col items-center justify-center p-3 rounded-xl border transition-all duration-500 h-20 overflow-hidden",
                                                    isActive
                                                        ? "bg-indigo-500/20 border-indigo-500/40 shadow-[0_0_20px_rgba(79,70,229,0.2)]"
                                                        : "bg-white/[0.02] border-white/5 hover:bg-white/[0.05] hover:border-white/10"
                                                )}
                                            >
                                                <span className={cn(
                                                    "text-[9px] font-black uppercase tracking-widest transition-colors",
                                                    isActive ? "text-indigo-400" : "text-zinc-500 group-hover/m:text-zinc-300"
                                                )}>
                                                    {format(targetMonth, "yyyy")}
                                                </span>
                                                <span className={cn(
                                                    "text-sm font-black uppercase transition-all",
                                                    isActive ? "text-white scale-110" : "text-zinc-400 group-hover/m:text-white"
                                                )}>
                                                    {format(targetMonth, "MMMM", { locale: fr })}
                                                </span>
                                                {isActive && (
                                                    <div className="absolute -bottom-4 -right-4 w-12 h-12 bg-indigo-500/20 blur-xl rounded-full" />
                                                )}
                                            </button>
                                        );
                                    })}
                                </div>

                                <button 
                                    onClick={() => setWeekOffset(0)}
                                    className="w-full mt-4 p-2 rounded-lg border border-white/5 bg-white/[0.02] hover:bg-white/[0.05] text-[9px] font-black uppercase tracking-[0.3em] text-zinc-500 hover:text-white transition-all flex items-center justify-center gap-2"
                                >
                                    <ChevronsLeft className="w-3 h-3" />
                                    Retour au présent
                                </button>
                            </div>
                        </PopoverContent>
                    </Popover>
                    <button
                        onClick={() => setWeekOffset(prev => prev + 1)}
                        className="p-1.5 hover:bg-white/10 rounded-lg text-zinc-400 hover:text-white transition-all"
                        title="+1 Semaine"
                    >
                        <ChevronRight className="w-5 h-5" />
                    </button>
                    <button
                        onClick={() => setWeekOffset(prev => prev + 4)}
                        className="p-1.5 hover:bg-white/10 rounded-lg text-zinc-500 hover:text-white transition-all"
                        title="+1 Mois"
                    >
                        <ChevronsRight className="w-4 h-4" />
                    </button>
                </div>
            </div>

            {/* Calendar Grid */}
            <div className="relative rounded-[2.5rem] border border-white/5 bg-zinc-950/40 backdrop-blur-3xl overflow-hidden shadow-[0_40px_80px_-20px_rgba(0,0,0,0.5)] group/calendar">
                <div className="noise-overlay absolute inset-0 opacity-[0.02] pointer-events-none" />
                <div className="absolute inset-0 bg-gradient-to-b from-white/[0.01] to-transparent pointer-events-none" />
                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse min-w-[800px]">
                        <thead>
                            <tr className="border-b border-white/10 bg-white/[0.02]">
                                <th className="p-5 w-64 font-black text-zinc-500 text-[10px] uppercase tracking-[0.2em] italic">Membre</th>
                                {DAYS_OF_WEEK.map(day => {
                                    const date = weekDates[day];
                                    const today = isToday(date);
                                    return (
                                        <th key={day} className={cn(
                                            "p-4 text-center border-l border-white/5 relative overflow-hidden transition-all duration-500",
                                            today && "bg-indigo-500/[0.03]"
                                        )}>
                                            {today && (
                                                <div className="absolute top-0 left-0 w-full h-1 bg-indigo-500 shadow-[0_0_15px_rgba(79,70,229,0.5)]" />
                                            )}
                                            <div className="flex flex-col items-center relative z-10">
                                                <span className={cn(
                                                    "text-[9px] font-black uppercase tracking-[0.2em] mb-1 transition-colors duration-500", 
                                                    today ? "text-indigo-400 drop-shadow-[0_0_8px_rgba(79,70,229,0.3)]" : "text-zinc-500"
                                                )}>
                                                    {format(date, "EEEE", { locale: fr })}
                                                </span>
                                                <span className={cn(
                                                    "text-xl font-black transition-all duration-500 leading-none", 
                                                    today ? "text-white scale-110" : "text-zinc-300"
                                                )}>
                                                    {format(date, "d")}
                                                </span>
                                            </div>
                                        </th>
                                    );
                                })}
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {filteredMembers.map((member) => (
                                <tr key={member.id} className="group hover:bg-white/[0.02] transition-colors">
                                    <td className="p-4">
                                        <Link 
                                            href={`/dashboard/${guildId}/members/${encodeURIComponent(member.pseudoDofus || member.id)}`}
                                            className="flex items-center gap-4 group/member outline-none"
                                        >
                                            <div className="relative">
                                                <Avatar className="w-12 h-12 border border-white/5 shadow-2xl transition-all duration-500 group-hover/member:scale-110 group-hover/member:rotate-3 group-hover/member:border-indigo-500/30">
                                                    <AvatarImage src={member.user?.image} />
                                                    <AvatarFallback className="bg-zinc-900 text-xs font-black text-zinc-500 uppercase tracking-tighter">
                                                        {(member.pseudoDofus || member.discordNickname || member.user?.name || "?").substring(0, 2).toUpperCase()}
                                                    </AvatarFallback>
                                                </Avatar>
                                                <div className="absolute inset-0 rounded-full bg-indigo-500/0 group-hover/member:bg-indigo-500/10 blur-xl transition-all duration-500 -z-10" />
                                            </div>
                                            <div className="flex flex-col">
                                                <span className="font-black text-zinc-200 text-[13px] uppercase tracking-wider transition-colors duration-500 group-hover/member:text-indigo-400 truncate max-w-[150px]">
                                                    {member.pseudoDofus || member.discordNickname || member.user?.name}
                                                </span>
                                                <span className="text-[9px] font-black text-zinc-600 uppercase tracking-[0.2em] italic group-hover/member:text-zinc-500 transition-colors">
                                                    {member.roleName || "Membre"}
                                                </span>
                                            </div>
                                        </Link>
                                    </td>
                                    {DAYS_OF_WEEK.map(day => {
                                        const onVacation = isVacation(member, weekDates[day]);
                                        const slots = getMemberAvailabilityForDay(member, day);
                                        const hasSlots = slots && slots.length > 0;
                                        
                                        return (
                                            <td key={day} className="p-2 border-l border-white/5 align-middle">
                                                {onVacation ? (
                                                    <div className="w-full h-10 rounded-lg bg-cyan-500/10 border border-cyan-500/20 flex flex-col items-center justify-center gap-0.5" title={member.vacationReason ? `En congés : ${member.vacationReason}` : "En congés"}>
                                                        <Plane className="w-4 h-4 text-cyan-400" />
                                                        <span className="text-[9px] font-bold text-cyan-500/80 uppercase tracking-widest">Absent</span>
                                                    </div>
                                                ) : hasSlots ? (
                                                    <div className="w-full flex flex-wrap items-center justify-center gap-1.5 p-1">
                                                        {slots.map((slot: TimeSlot) => {
                                                            const Info = SLOT_INFO[slot];
                                                            const Icon = Info.icon;
                                                            return (
                                                                <div 
                                                                    key={slot}
                                                                    className={cn(
                                                                        "flex items-center justify-center w-7 h-7 rounded-md border shadow-sm transition-transform hover:scale-110",
                                                                        Info.bg, Info.border
                                                                    )}
                                                                    title={Info.label}
                                                                >
                                                                    <Icon className={cn("w-4 h-4", Info.color)} />
                                                                </div>
                                                            );
                                                        })}
                                                    </div>
                                                ) : (
                                                    <div className="w-full h-10 rounded-lg bg-zinc-900/50 border border-dashed border-white/10 flex flex-col items-center justify-center text-zinc-600 gap-1" title="Disponibilité non définie">
                                                        <AlertCircle className="w-3.5 h-3.5 opacity-50" />
                                                    </div>
                                                )}
                                            </td>
                                        );
                                    })}
                                </tr>
                            ))}
                            {filteredMembers.length === 0 && (
                                <tr>
                                    <td colSpan={8} className="p-8 text-center text-zinc-500">
                                        Aucun membre trouvé.
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Legend */}
            <div className="flex flex-wrap items-center justify-center gap-6 px-4 py-3 bg-zinc-950 border border-white/10 rounded-xl text-xs font-medium text-zinc-400 shadow-2xl">
                {TIME_SLOTS.map(slot => {
                    const Info = SLOT_INFO[slot];
                    const Icon = Info.icon;
                    return (
                        <div key={slot} className="flex items-center gap-2">
                            <div className={cn("flex items-center justify-center w-6 h-6 rounded-md border", Info.bg, Info.border)}>
                                <Icon className={cn("w-3.5 h-3.5", Info.color)} />
                            </div>
                            <span className="capitalize">{Info.label}</span>
                        </div>
                    );
                })}
                <div className="h-4 w-px bg-white/10 mx-2 hidden sm:block" />
                <div className="flex items-center gap-2 text-cyan-400">
                    <Plane className="w-4 h-4" />
                    <span>Absent</span>
                </div>
                <div className="flex items-center gap-2 text-zinc-500">
                    <AlertCircle className="w-4 h-4 opacity-50" />
                    <span>Non défini</span>
                </div>
            </div>
        </div>
    );
}

"use client";

import Link from "next/link";
import { UserProfile, User } from "@prisma/client";
import { Card, CardContent } from "@/components/ui/card";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import Image from "next/image";
import { Badge } from "@/components/ui/badge";
import { Hammer, Palmtree, Shield, ShieldCheck, Sparkles } from "lucide-react";
import { getClass, DOFUS_JOBS } from "@/lib/dofus-assets";
import { ClassIcon } from "@/components/shared/class-icon";
import { cn } from "@/lib/utils";
import { format } from "date-fns";
import { fr } from "date-fns/locale";
import { getAlignment, getOrder } from "@/lib/dofus-assets";
import {
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from "@/components/ui/tooltip";

interface ExtendedProfile extends UserProfile {
    user: User;
    displayName?: string;
    roleColor?: number;
    roleName?: string;
    isAdmin?: boolean;
    alignment: string | null;
    alignmentOrder: string | null;
    alignmentLevel: number | null;
    legendaryCrafts?: any[];
}

interface MemberCardProps {
    profile: ExtendedProfile;
    guildId: string;
}

export function MemberCard({ profile, guildId }: MemberCardProps) {
    const jobs = Array.isArray(profile.metiers) ? (profile.metiers as string[]) : [];
    const topJobs = jobs.slice(0, 3);
    const remaining = jobs.length - 3;

    const classData = getClass(profile.classe || "");

    const altPseudos = Array.isArray(profile.altPseudos) ? (profile.altPseudos as any[]) : [];
    const alignedMules = altPseudos.filter((mule: any) => 
        mule && typeof mule === 'object' && mule.pseudo && mule.alignment && mule.alignment !== "neutre" && mule.alignmentOrder
    );


    const displayName = profile.displayName || profile.pseudoDofus || profile.user.name || "Voyageur";

    // Role color border
    const roleColor = profile.roleColor && profile.roleColor > 0
        ? `#${profile.roleColor.toString(16).padStart(6, "0")}`
        : undefined;

    // Check if on vacation
    const now = new Date();
    const vacationStart = profile.vacationStart ? new Date(profile.vacationStart) : null;
    const vacationEnd = profile.vacationEnd ? new Date(profile.vacationEnd) : null;
    const isOnVacation = vacationStart && vacationStart <= now && (!vacationEnd || vacationEnd >= now);
    const isUpcoming = vacationStart && vacationStart > now;

    // Format vacation dates for tooltip
    const vacationTooltip = (isOnVacation || isUpcoming)
        ? `Absent du ${format(vacationStart!, "d MMM", { locale: fr })}${vacationEnd ? ` au ${format(vacationEnd, "d MMM", { locale: fr })}` : " (indéfini)"}`
        : "";

    // Check if online (last 2 minutes)
    const activeThreshold = 2 * 60 * 1000;
    const isOnline = profile.lastActivityAt && (new Date().getTime() - new Date(profile.lastActivityAt).getTime() < activeThreshold);

    const alignmentData = getAlignment(profile.alignment || "");
    const orderData = profile.alignment && profile.alignmentOrder ? getOrder(profile.alignment, profile.alignmentOrder) : null;

    return (
        <Link href={`/dashboard/${guildId}/members/${encodeURIComponent(profile.pseudoDofus || profile.id)}`}>
            <Card
                className={cn(
                    "group relative overflow-hidden cursor-pointer border shadow-xl transition-all duration-500 hover:-translate-y-1 hover:shadow-2xl bg-zinc-950/80 backdrop-blur-md",
                    roleColor ? "" : "border-white/5 hover:border-white/10",
                    isOnVacation && "bg-cyan-950/20 border-cyan-500/20 hover:border-cyan-500/40"
                )}
                style={roleColor ? { borderColor: `${roleColor}30`, boxShadow: `0 10px 40px -10px ${roleColor}15` } : undefined}
            >
                {/* Dynamic Background Glow & Top Banner */}
                <div 
                    className="absolute inset-0 opacity-20 group-hover:opacity-40 transition-opacity duration-500 pointer-events-none"
                    style={roleColor ? { background: `radial-gradient(circle at 50% 0%, ${roleColor}, transparent 70%)` } : { background: `radial-gradient(circle at 50% 0%, rgba(255,255,255,0.1), transparent 70%)` }}
                />
                <div 
                    className="absolute top-0 left-0 w-full h-1"
                    style={roleColor ? { backgroundColor: roleColor } : { background: "linear-gradient(90deg, #3f3f46, #71717a)" }}
                />

                <CardContent className="p-6 flex flex-col items-center gap-4 relative z-10">
                    {/* Vacation Badges */}
                    {isOnVacation && (
                        <div className="absolute top-3 right-3 z-20">
                            <TooltipProvider>
                                <Tooltip>
                                    <TooltipTrigger asChild>
                                        <Badge variant="outline" className="bg-cyan-500/10 border-cyan-500/30 text-cyan-400 gap-1.5 hover:bg-cyan-500/20 transition-colors cursor-help">
                                            <Palmtree className="w-3.5 h-3.5" />
                                            <span className="text-[10px] font-semibold uppercase tracking-wide hidden sm:inline">En vacances</span>
                                        </Badge>
                                    </TooltipTrigger>
                                    <TooltipContent side="bottom" className="glass-premium border-cyan-500/30 text-cyan-600 dark:text-cyan-300">
                                        <p className="font-bold">{vacationTooltip}</p>
                                    </TooltipContent>
                                </Tooltip>
                            </TooltipProvider>
                        </div>
                    )}
                    {isUpcoming && (
                        <div className="absolute top-3 right-3 z-20">
                            <TooltipProvider>
                                <Tooltip>
                                    <TooltipTrigger asChild>
                                        <Badge variant="outline" className="bg-orange-500/10 border-orange-500/30 text-orange-400 gap-1.5 hover:bg-orange-500/20 transition-colors cursor-help">
                                            <Palmtree className="w-3.5 h-3.5" />
                                            <span className="text-[10px] font-semibold uppercase tracking-wide hidden sm:inline">Bientôt</span>
                                        </Badge>
                                    </TooltipTrigger>
                                    <TooltipContent side="bottom" className="glass-premium border-orange-500/30 text-orange-600 dark:text-orange-300">
                                        <p className="font-bold">⏳ {vacationTooltip}</p>
                                    </TooltipContent>
                                </Tooltip>
                            </TooltipProvider>
                        </div>
                    )}

                    {/* Avatar Container */}
                    <div className="relative group/avatar mt-2">
                        <div className="absolute inset-0 rounded-full blur-md opacity-0 group-hover/avatar:opacity-50 transition-opacity duration-500"
                             style={roleColor ? { backgroundColor: roleColor } : { backgroundColor: "rgba(255,255,255,0.2)" }} />
                        
                        <Avatar
                            className="w-24 h-24 transition-all duration-500 ring-2 ring-offset-4 ring-offset-zinc-950 group-hover/avatar:scale-105"
                            style={{ "--ringColor": roleColor || "rgba(255,255,255,0.1)" } as React.CSSProperties}
                        >
                            <AvatarImage src={profile.user.image || ""} className="object-cover" />
                            <AvatarFallback className="text-2xl font-black bg-zinc-900 text-zinc-500">
                                {displayName.slice(0, 2).toUpperCase()}
                            </AvatarFallback>
                        </Avatar>
                        
                        {/* Online Status Indicator */}
                        <TooltipProvider>
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <div className={cn(
                                        "absolute bottom-1 right-1 w-5 h-5 rounded-full border-[3px] border-zinc-950 transition-all duration-300",
                                        isOnline ? "bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.8)]" : "bg-zinc-600"
                                    )} />
                                </TooltipTrigger>
                                <TooltipContent side="right" className="glass-premium border-white/10 text-xs font-bold uppercase tracking-widest">
                                    {isOnline ? "En ligne récemment" : "Hors ligne"}
                                </TooltipContent>
                            </Tooltip>
                        </TooltipProvider>

                        {/* Alignment/Order Badge */}
                        {profile.alignment && (
                            <div className="absolute -top-1.5 -left-1.5 z-20">
                                <TooltipProvider>
                                    <Tooltip>
                                        <TooltipTrigger asChild>
                                            <div className={cn(
                                                "w-11 h-11 rounded-xl border-2 bg-zinc-950/90 shadow-2xl flex items-center justify-center overflow-hidden",
                                                profile.alignment === "bontarien" ? "border-blue-500/40" : 
                                                profile.alignment === "brakmarien" ? "border-red-500/40" : 
                                                "border-white/20"
                                            )}>
                                                {orderData ? (
                                                    <Image src={orderData.icon} alt={orderData.name} width={36} height={36} className="object-contain w-full h-full p-1" />
                                                ) : (
                                                    <Shield className={cn(
                                                        "w-5 h-5",
                                                        profile.alignment === "bontarien" ? "text-blue-400" : 
                                                        profile.alignment === "brakmarien" ? "text-red-400" : 
                                                        "text-zinc-500"
                                                    )} />
                                                )}
                                            </div>
                                        </TooltipTrigger>
                                        <TooltipContent side="left" className="glass-premium border-white/10 text-[10px] font-black uppercase tracking-widest">
                                            <p>{alignmentData?.name}{orderData ? ` - ${orderData.name}` : ""}</p>
                                            {profile.alignmentLevel ? <p className="text-zinc-500">Niveau {profile.alignmentLevel}</p> : null}
                                        </TooltipContent>
                                    </Tooltip>
                                </TooltipProvider>
                            </div>
                        )}
                    </div>

                    {/* Name & Role */}
                    <div className="text-center space-y-2 w-full mt-2">
                        <div className="flex flex-col items-center justify-center gap-1.5">
                            <div className="flex items-center gap-2">
                                <h3 className="font-black text-xl truncate text-white italic uppercase tracking-tighter">
                                    {displayName}
                                </h3>
                                {profile.isAdmin && (
                                    <TooltipProvider>
                                        <Tooltip>
                                            <TooltipTrigger asChild>
                                                <ShieldCheck className="w-4 h-4 text-amber-400 drop-shadow-[0_0_8px_rgba(251,191,36,0.5)] shrink-0" />
                                            </TooltipTrigger>
                                            <TooltipContent side="top" className="glass-premium border-amber-500/30 text-amber-500 text-[10px] font-black uppercase tracking-widest">
                                                Administration SigilOS
                                            </TooltipContent>
                                        </Tooltip>
                                    </TooltipProvider>
                                )}
                                {profile.legendaryCrafts && profile.legendaryCrafts.length > 0 && (
                                    <TooltipProvider>
                                        <Tooltip>
                                            <TooltipTrigger asChild>
                                                <Sparkles className="w-4 h-4 text-purple-400 drop-shadow-[0_0_8px_rgba(168,85,247,0.6)] shrink-0 animate-pulse" />
                                            </TooltipTrigger>
                                            <TooltipContent side="top" className="glass-premium border-purple-500/30 text-purple-400 text-[10px] font-black uppercase tracking-widest">
                                                Artisan Légendaire Spécialisé
                                            </TooltipContent>
                                        </Tooltip>
                                    </TooltipProvider>
                                )}
                            </div>
                            

                        </div>
                        
                        <div className="flex items-center justify-center gap-1.5 pt-1">
                            {classData && <ClassIcon classId={classData.id} size={18} className="opacity-80" />}
                            <p className="text-xs text-zinc-400 font-medium uppercase tracking-wider">
                                {classData?.name || profile.classe || "Aventurier"}
                            </p>
                        </div>
                    </div>

                    {/* Divider */}
                    <div className="w-full h-px bg-gradient-to-r from-transparent via-white/10 to-transparent my-1" />

                    {/* Jobs */}
                    <div className={cn(
                        "flex flex-wrap items-center justify-center gap-2 min-h-[1.5rem]",
                        isOnVacation && "mb-2"
                    )}>
                        {jobs.length > 0 ? (
                            <>
                                {topJobs.map(job => {
                                    const jobData = Object.values(DOFUS_JOBS).flat().find(j => j.id === job);
                                    return (
                                        <Badge key={job} variant="secondary" className="bg-white/[0.03] hover:bg-white/[0.08] text-[9px] px-2.5 py-1 border-white/5 font-black uppercase tracking-widest text-zinc-300 transition-colors">
                                            {jobData?.icon ? (
                                                jobData.icon.startsWith("/") ? (
                                                    <Image src={jobData.icon} alt={jobData.name} width={14} height={14} className="w-3.5 h-3.5 mr-1.5 object-contain opacity-80" />
                                                ) : (
                                                    <span className="mr-1.5 opacity-80 text-[10px]">{jobData.icon}</span>
                                                )
                                            ) : (
                                                <Hammer className="w-3 h-3 mr-1.5 opacity-50" />
                                            )}
                                            {jobData?.name || job}
                                        </Badge>
                                    );
                                })}
                                {remaining > 0 && (
                                    <div className="w-6 h-6 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-[9px] font-black text-zinc-400">
                                        +{remaining}
                                    </div>
                                )}
                            </>
                        ) : (
                            <span className="text-[10px] text-zinc-600 uppercase tracking-widest font-bold">Aucun métier</span>
                        )}
                    </div>

                    {/* Aligned Mules */}
                    {alignedMules.length > 0 && (
                        <>
                            <div className="w-full h-px bg-gradient-to-r from-transparent via-white/10 to-transparent my-1" />
                            <div className="flex flex-col items-center gap-1.5 w-full">
                                <span className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">Mules alignées</span>
                                <div className="flex flex-wrap justify-center gap-1.5">
                                    {alignedMules.map((mule: any, idx: number) => {
                                        const mCls = getClass(mule.classe || "cra");
                                        const mOrder = mule.alignment && mule.alignmentOrder ? getOrder(mule.alignment, mule.alignmentOrder) : null;
                                        return (
                                            <TooltipProvider key={mule.id || idx}>
                                                <Tooltip>
                                                    <TooltipTrigger asChild>
                                                        <div className="flex items-center gap-1.5 bg-black/40 border border-white/5 rounded-md px-2 py-0.5 max-w-full">
                                                            {mCls && (
                                                                <div className="relative w-4.5 h-4.5 shrink-0">
                                                                    <Image 
                                                                        src={mCls.icon} 
                                                                        alt={mCls.name} 
                                                                        fill 
                                                                        className="object-contain" 
                                                                        unoptimized
                                                                    />
                                                                </div>
                                                            )}
                                                            <span className="text-[9px] text-zinc-300 font-bold max-w-[70px] truncate">
                                                                {mule.pseudo}
                                                            </span>
                                                            {mOrder && (
                                                                <div className="relative w-4 h-4 shrink-0 ml-0.5">
                                                                    <Image 
                                                                        src={mOrder.icon} 
                                                                        alt={mOrder.name} 
                                                                        fill 
                                                                        className="object-contain" 
                                                                        unoptimized
                                                                    />
                                                                </div>
                                                            )}
                                                        </div>
                                                    </TooltipTrigger>
                                                    <TooltipContent side="top" className="glass-premium border-white/10 text-[10px] font-black uppercase tracking-widest">
                                                        <p>{mule.pseudo} (Nv. {mule.level || 200})</p>
                                                        <p className="text-zinc-500">{mCls?.name || "Classe inconnue"} - {mOrder?.name || "Sans ordre"}</p>
                                                    </TooltipContent>
                                                </Tooltip>
                                            </TooltipProvider>
                                        );
                                    })}
                                </div>
                            </div>
                        </>
                    )}

                    {/* Absence details footer */}
                    {isOnVacation && (
                        <div className="w-full mt-2 pt-3 border-t border-cyan-500/10 flex flex-col items-center gap-1.5 animate-in slide-in-from-bottom-2 duration-500">
                            <span className="text-[9px] text-cyan-400 font-bold uppercase tracking-widest flex items-center gap-1 bg-cyan-500/10 px-2 py-0.5 rounded-full border border-cyan-500/20">
                                <Palmtree className="w-3 h-3" /> Période d'absence
                            </span>
                            <span className="text-[11px] text-zinc-300 font-black italic whitespace-nowrap">
                                {format(vacationStart!, "d MMMM", { locale: fr })}
                                {vacationEnd ? ` au ${format(vacationEnd, "d MMMM", { locale: fr })}` : " (indéfini)"}
                            </span>
                        </div>
                    )}
                </CardContent>
            </Card>
        </Link>
    );
}

"use client";

import { useState, useTransition } from "react";
import { MemberCard } from "./member-card";
import Image from "next/image";
import { Tabs, TabsContent } from "@/components/ui/tabs";
import { motion, AnimatePresence } from "framer-motion";
import { GuildAbsenceCalendar } from "./guild-absence-calendar";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList, CommandSeparator } from "@/components/ui/command";
import { DOFUS_CLASSES, DOFUS_JOBS, JOB_CATEGORIES } from "@/lib/dofus-assets";
import { ClassIcon } from "@/components/shared/class-icon";
import { Search, Filter, X, Briefcase, Swords, Check, Palmtree, Shield, Sparkles } from "lucide-react";
import { ALIGNMENTS, ORDERS } from "@/lib/dofus-assets";
import { EmptyState } from "@/components/ui/empty-state";
import { cn } from "@/lib/utils";


interface MemberDirectoryProps {
    initialMembers: any[];
    legendaryItems: any[];
    guildId: string;
}

export function MemberDirectory({ initialMembers, legendaryItems, guildId }: MemberDirectoryProps) {
    const [members] = useState(initialMembers);
    const [isPending, startTransition] = useTransition();

    // Filters State
    const [search, setSearch] = useState("");
    const [selectedClass, setSelectedClass] = useState<string | null>(null);
    const [selectedJob, setSelectedJob] = useState<string | null>(null);
    const [selectedAlignment, setSelectedAlignment] = useState<string | null>(null);
    const [selectedOrder, setSelectedOrder] = useState<string | null>(null);
    const [selectedLegendary, setSelectedLegendary] = useState<string | null>(null);
    const [filterLegendaryPet, setFilterLegendaryPet] = useState(false);
    const [isOpenClass, setIsOpenClass] = useState(false);
    const [isOpenJob, setIsOpenJob] = useState(false);
    const [isOpenAlignment, setIsOpenAlignment] = useState(false);
    const [isOpenOrder, setIsOpenOrder] = useState(false);
    const [isOpenLegendary, setIsOpenLegendary] = useState(false);

    // Filtering Logic
    const filteredMembers = members.filter(m => {
        // 1. Search (Deep Alias Search)
        const searchTerm = search.toLowerCase();
        
        // Main Pseudos - Safe check
        const mainMatch = 
            (typeof m.pseudoDofus === 'string' ? m.pseudoDofus : "").toLowerCase().includes(searchTerm) ||
            (typeof m.dofusPseudo === 'string' ? m.dofusPseudo : "").toLowerCase().includes(searchTerm) ||
            (typeof m.user?.name === 'string' ? m.user.name : "").toLowerCase().includes(searchTerm) ||
            (typeof m.discordNickname === 'string' ? m.discordNickname : "").toLowerCase().includes(searchTerm);

        // Alt Pseudos (stored as JSON array) - Safe check
        let altMatch = false;
        if (m.altPseudos && Array.isArray(m.altPseudos)) {
            altMatch = m.altPseudos.some((alt: any) => {
                if (typeof alt === 'string') {
                    return alt.toLowerCase().includes(searchTerm);
                } else if (alt && typeof alt === 'object' && typeof alt.pseudo === 'string') {
                    return alt.pseudo.toLowerCase().includes(searchTerm);
                }
                return false;
            });
        }

        if (!mainMatch && !altMatch) return false;

        // 2. Class Filter (Case insensitive check)
        if (selectedClass) {
            const targetClass = DOFUS_CLASSES.find(c => c.id === selectedClass);
            if (!targetClass) return false;

            const memberClass = typeof m.classe === 'string' ? m.classe.toLowerCase() : null;
            if (memberClass !== targetClass.name.toLowerCase() && memberClass !== targetClass.id) {
                return false;
            }
        }

        // 3. Job Filter
        if (selectedJob) {
            const jobs = Array.isArray(m.metiers) ? m.metiers : [];
            const hasJob = jobs.some((j: any) => 
                typeof j === 'string' && j.toLowerCase() === selectedJob.toLowerCase()
            );
            if (!hasJob) return false;
        }

        // 4. Alignment Filter
        if (selectedAlignment) {
            const mainAlignMatch = m.alignment === selectedAlignment;
            let muleAlignMatch = false;
            if (m.altPseudos && Array.isArray(m.altPseudos)) {
                muleAlignMatch = m.altPseudos.some((alt: any) => 
                    alt && typeof alt === 'object' && alt.alignment === selectedAlignment
                );
            }
            if (!mainAlignMatch && !muleAlignMatch) return false;
        }

        // 5. Order Filter
        if (selectedOrder) {
            const mainOrderMatch = m.alignmentOrder === selectedOrder;
            let muleOrderMatch = false;
            if (m.altPseudos && Array.isArray(m.altPseudos)) {
                muleOrderMatch = m.altPseudos.some((alt: any) => 
                    alt && typeof alt === 'object' && alt.alignmentOrder === selectedOrder
                );
            }
            if (!mainOrderMatch && !muleOrderMatch) return false;
        }

        // 6. Legendary Filter
        if (selectedLegendary) {
            const hasLegendary = Array.isArray(m.legendaryCrafts) && m.legendaryCrafts.some((lc: any) => lc.id === selectedLegendary);
            if (!hasLegendary) return false;
        }

        // 7. Legendary Pet Filter
        if (filterLegendaryPet) {
            if (!m.hasLegendaryPet) return false;
        }

        return true;
    });

    const resetFilters = () => {
        setSearch("");
        setSelectedClass(null);
        setSelectedJob(null);
        setSelectedAlignment(null);
        setSelectedOrder(null);
        setSelectedLegendary(null);
        setFilterLegendaryPet(false);
    };

    const activeFiltersCount = (selectedClass ? 1 : 0) + (selectedJob ? 1 : 0) + (selectedAlignment ? 1 : 0) + (selectedOrder ? 1 : 0) + (selectedLegendary ? 1 : 0) + (filterLegendaryPet ? 1 : 0);

    const getSelectedClassName = () => DOFUS_CLASSES.find(c => c.id === selectedClass)?.name;
    const getSelectedJobName = () => {
        for (const cat of Object.values(DOFUS_JOBS)) {
            const found = cat.find(j => j.id === selectedJob);
            if (found) return found.name;
        }
        return selectedJob;
    };
    const getSelectedLegendaryName = () => legendaryItems.find(i => i.id === selectedLegendary)?.name;

    const [activeTab, setActiveTab] = useState("roster");

    return (
        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-12">
                {/* --- Roster Card --- */}
                <button
                    onClick={() => setActiveTab("roster")}
                    className={cn(
                        "relative group flex items-center gap-6 p-8 rounded-[2.5rem] transition-all duration-700 outline-none select-none text-left overflow-hidden",
                        activeTab === "roster"
                            ? "glass-premium bg-white/[0.03] border-white/10 scale-[1.02] shadow-2xl"
                            : "bg-white/[0.04] border-white/10 hover:bg-white/[0.06] hover:border-white/20 hover:-translate-y-1"
                    )}
                >
                    <AnimatePresence>
                        {activeTab === "roster" ? (
                            <motion.div 
                                layoutId="dir-glow-roster"
                                className="absolute inset-0 rounded-[inherit] -z-10"
                                style={{ background: `radial-gradient(circle at center, rgba(79, 70, 229, 0.35), transparent 70%)` }}
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                exit={{ opacity: 0 }}
                            />
                        ) : (
                            <div 
                                className="absolute inset-0 rounded-[inherit] -z-10 opacity-5 group-hover:opacity-15 transition-opacity duration-700 bg-indigo-500"
                                style={{ background: `radial-gradient(circle at center, rgba(79, 70, 229, 0.4), transparent 80%)` }}
                            />
                        )}
                    </AnimatePresence>

                    <div className={cn(
                        "w-16 h-16 rounded-2xl flex items-center justify-center shrink-0 border transition-all duration-700 relative z-10",
                        activeTab === "roster"
                            ? "bg-indigo-500/10 border-indigo-500/30 text-indigo-400 shadow-[0_0_30px_rgba(79,70,229,0.3)]"
                            : "bg-zinc-900/50 border-white/5 text-indigo-400 opacity-40 group-hover:opacity-100 group-hover:border-white/10"
                    )}>
                        {activeTab === "roster" && (
                            <div className="absolute inset-0 blur-lg opacity-40 -z-10 bg-indigo-500" />
                        )}
                        <Swords className={cn(
                            "w-7 h-7 transition-transform duration-700",
                            activeTab === "roster" ? "scale-110 rotate-[5deg]" : "group-hover:scale-110"
                        )} />
                    </div>

                    <div className="relative z-10">
                        <p className={cn(
                            "font-black text-sm uppercase tracking-[0.3em] transition-all duration-500",
                            activeTab === "roster" ? "text-foreground drop-shadow-[0_0_12px_rgba(255,255,255,0.3)]" : "text-zinc-300 group-hover:text-white"
                        )}>
                            Effectifs de Guilde
                        </p>
                        <p className={cn(
                            "text-[11px] font-bold mt-1 tracking-wider transition-colors duration-500",
                            activeTab === "roster" ? "text-zinc-400" : "text-zinc-500 group-hover:text-zinc-400"
                        )}>
                            Artisans, combattants et membres
                        </p>
                    </div>

                    {activeTab === "roster" && (
                        <motion.div 
                            layoutId="dir-active-pill"
                            className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-1/4 h-1.5 rounded-full blur-sm bg-indigo-500"
                            transition={{ type: "spring", stiffness: 300, damping: 30 }}
                        />
                    )}
                </button>

                {/* --- Absences Card --- */}
                <button
                    onClick={() => setActiveTab("absences")}
                    className={cn(
                        "relative group flex items-center gap-6 p-8 rounded-[2.5rem] transition-all duration-700 outline-none select-none text-left overflow-hidden",
                        activeTab === "absences"
                            ? "glass-premium bg-white/[0.03] border-white/10 scale-[1.02] shadow-2xl"
                            : "bg-white/[0.04] border-white/10 hover:bg-white/[0.06] hover:border-white/20 hover:-translate-y-1"
                    )}
                >
                    <AnimatePresence>
                        {activeTab === "absences" ? (
                            <motion.div 
                                layoutId="dir-glow-absences"
                                className="absolute inset-0 rounded-[inherit] -z-10"
                                style={{ background: `radial-gradient(circle at center, rgba(8, 145, 178, 0.35), transparent 70%)` }}
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                exit={{ opacity: 0 }}
                            />
                        ) : (
                            <div 
                                className="absolute inset-0 rounded-[inherit] -z-10 opacity-5 group-hover:opacity-15 transition-opacity duration-700 bg-cyan-500"
                                style={{ background: `radial-gradient(circle at center, rgba(8, 145, 178, 0.4), transparent 80%)` }}
                            />
                        )}
                    </AnimatePresence>

                    <div className={cn(
                        "w-16 h-16 rounded-2xl flex items-center justify-center shrink-0 border transition-all duration-700 relative z-10",
                        activeTab === "absences"
                            ? "bg-cyan-500/10 border-cyan-500/30 text-cyan-400 shadow-[0_0_30px_rgba(8,145,178,0.3)]"
                            : "bg-zinc-900/50 border-white/5 text-cyan-400 opacity-40 group-hover:opacity-100 group-hover:border-white/10"
                    )}>
                        {activeTab === "absences" && (
                            <div className="absolute inset-0 blur-lg opacity-40 -z-10 bg-cyan-500" />
                        )}
                        <Palmtree className={cn(
                            "w-7 h-7 transition-transform duration-700",
                            activeTab === "absences" ? "scale-110 rotate-[5deg]" : "group-hover:scale-110"
                        )} />
                    </div>

                    <div className="relative z-10">
                        <p className={cn(
                            "font-black text-sm uppercase tracking-[0.3em] transition-all duration-500",
                            activeTab === "absences" ? "text-foreground drop-shadow-[0_0_12px_rgba(255,255,255,0.3)]" : "text-zinc-300 group-hover:text-white"
                        )}>
                            Disponibilités
                        </p>
                        <p className={cn(
                            "text-[11px] font-bold mt-1 tracking-wider transition-colors duration-500",
                            activeTab === "absences" ? "text-zinc-400" : "text-zinc-500 group-hover:text-zinc-400"
                        )}>
                            Calendrier et absences
                        </p>
                    </div>

                    {activeTab === "absences" && (
                        <motion.div 
                            layoutId="dir-active-pill"
                            className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-1/4 h-1.5 rounded-full blur-sm bg-cyan-500"
                            transition={{ type: "spring", stiffness: 300, damping: 30 }}
                        />
                    )}
                </button>
            </div>

            <TabsContent value="roster" className="mt-0 border-0 p-0 animate-in fade-in zoom-in-95 duration-500">

            {/* FILTER BAR — UI UX 2026 PREMIUM */}
            <div className="relative overflow-hidden p-2.5 rounded-2xl flex flex-col md:flex-row gap-3 shadow-2xl bg-zinc-950 group/filterbar border border-white/5 mb-6">
                <div className="noise-overlay absolute inset-0 opacity-10" />
                
                {/* Search Input — High Fidelity */}
                <div className="relative flex-1 group/search">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground group-focus-within/search:text-indigo-400 transition-colors duration-500" />
                    <Input
                        placeholder="Rechercher par pseudo, alt, discord..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        className="pl-11 bg-white/[0.02] border-white/5 hover:border-white/10 focus-visible:ring-indigo-500/30 focus-visible:border-indigo-500/50 transition-all duration-500 h-11 rounded-xl text-sm font-medium placeholder:text-zinc-600"
                    />
                    {/* Inner Focus Glint */}
                    <div className="absolute inset-px rounded-[inherit] border border-white/5 pointer-events-none group-focus-within/search:border-indigo-500/20 transition-all duration-500" />
                    
                    {search && (
                        <button
                            onClick={() => setSearch("")}
                            className="absolute right-4 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-indigo-400 transition-colors"
                        >
                            <X className="w-4 h-4" />
                        </button>
                    )}
                </div>

                <div className="flex gap-2 overflow-x-auto pb-1 md:pb-0 scrollbar-hide">
                    {/* Class Filter Popover */}
                    <Popover open={isOpenClass} onOpenChange={setIsOpenClass}>
                        <PopoverTrigger asChild>
                            <Button
                                variant="outline"
                                className={cn(
                                    "h-11 border-indigo-500/10 bg-indigo-500/5 hover:bg-indigo-500/10 hover:border-indigo-500/20 text-muted-foreground gap-2.5 px-4 font-black uppercase italic tracking-widest text-[11px] rounded-xl transition-all duration-500 shadow-xl group/btn",
                                    selectedClass && "border-indigo-500/40 bg-indigo-500/20 text-indigo-400 shadow-indigo-500/10"
                                )}
                            >
                                <Swords className={cn(
                                    "w-4 h-4 transition-all duration-500 text-indigo-400/50 group-hover/btn:text-indigo-400 group-hover/btn:scale-110", 
                                    selectedClass && "rotate-12 scale-110 text-indigo-400 opacity-100"
                                )} />
                                {selectedClass ? getSelectedClassName() : "Classe"}
                                {selectedClass && (
                                    <span
                                        role="button"
                                        tabIndex={0}
                                        className="ml-1 rounded-full hover:bg-indigo-400/20 p-0.5 transition-colors cursor-pointer"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            e.preventDefault();
                                            setSelectedClass(null);
                                        }}
                                        onKeyDown={(e) => e.key === 'Enter' && setSelectedClass(null)}
                                        aria-label="Supprimer le filtre classe"
                                    >
                                        <X className="w-3.5 h-3.5 text-indigo-400/60 hover:text-indigo-400" />
                                    </span>
                                )}
                            </Button>
                        </PopoverTrigger>
                        <PopoverContent className="w-[340px] p-0 glass-premium border-white/10 shadow-2xl" align="end">
                            <Command className="bg-transparent">
                                <CommandInput placeholder="Chercher une classe..." className="h-11 border-none bg-transparent" />
                                <CommandList className="max-h-[400px]">
                                    <CommandEmpty>Aucune classe trouvée.</CommandEmpty>
                                    <CommandGroup heading="Classes" className="text-zinc-500 font-black uppercase text-[10px] tracking-widest p-2">
                                        <div className="grid grid-cols-4 gap-2">
                                            {DOFUS_CLASSES.map((c) => (
                                                <CommandItem
                                                    key={c.id}
                                                    value={c.name}
                                                    onSelect={() => {
                                                        setSelectedClass(selectedClass === c.id ? null : c.id);
                                                        setIsOpenClass(false);
                                                    }}
                                                     className={cn(
                                                        "flex flex-col items-center justify-center p-3 rounded-xl cursor-pointer transition-all gap-1.5 border h-auto",
                                                        selectedClass === c.id
                                                            ? "bg-indigo-500/20 border-indigo-500/40 text-foreground aria-selected:bg-indigo-500/30 shadow-[0_0_15px_rgba(99,102,241,0.2)]"
                                                            : "bg-white/[0.02] border-white/5 hover:bg-white/[0.05] hover:border-white/10 text-muted-foreground hover:text-foreground aria-selected:bg-white/[0.05]"
                                                    )}
                                                >
                                                    <ClassIcon classId={c.id} size={36} className="filter drop-shadow-[0_4px_8px_rgba(0,0,0,0.5)]" />
                                                    <span className="text-[10px] font-black truncate w-full text-center uppercase tracking-tighter opacity-80">{c.name}</span>
                                                </CommandItem>
                                            ))}
                                        </div>
                                    </CommandGroup>
                                </CommandList>
                            </Command>
                        </PopoverContent>
                    </Popover>

                    {/* Job Filter Popover */}
                    <Popover open={isOpenJob} onOpenChange={setIsOpenJob}>
                        <PopoverTrigger asChild>
                            <Button
                                variant="outline"
                                className={cn(
                                    "h-11 border-amber-500/10 bg-amber-500/5 hover:bg-amber-500/10 hover:border-amber-500/20 text-muted-foreground gap-2.5 px-4 font-black uppercase italic tracking-widest text-[11px] rounded-xl transition-all duration-500 shadow-xl group/btn",
                                    selectedJob && "border-amber-500/40 bg-amber-500/20 text-amber-500 shadow-amber-500/10"
                                )}
                            >
                                <Briefcase className={cn(
                                    "w-4 h-4 transition-all duration-500 text-amber-500/50 group-hover/btn:text-amber-500 group-hover/btn:scale-110", 
                                    selectedJob && "scale-110 -rotate-6 text-amber-500 opacity-100"
                                )} />
                                {selectedJob ? getSelectedJobName() : "Métier (200)"}
                                {selectedJob && (
                                    <span
                                        role="button"
                                        tabIndex={0}
                                        className="ml-1 rounded-full hover:bg-amber-400/20 p-0.5 transition-colors cursor-pointer"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            e.preventDefault();
                                            setSelectedJob(null);
                                        }}
                                        onKeyDown={(e) => e.key === 'Enter' && setSelectedJob(null)}
                                        aria-label="Supprimer le filtre métier"
                                    >
                                        <X className="w-3.5 h-3.5 text-amber-500/60 hover:text-amber-400" />
                                    </span>
                                )}
                            </Button>
                        </PopoverTrigger>
                        <PopoverContent className="w-[340px] p-0 glass-premium border-white/10 shadow-2xl" align="end">
                            <Command className="bg-transparent">
                                <CommandInput placeholder="Chercher un métier..." className="h-11 border-none bg-transparent" />
                                <CommandList className="max-h-[400px]">
                                    <CommandEmpty>Aucun métier trouvé.</CommandEmpty>
                                    <CommandGroup className="p-0">
                                        {Object.entries(DOFUS_JOBS).map(([category, jobs]) => (
                                            <div key={category} className="mb-2">
                                                <div className="px-4 py-2 text-[10px] font-black text-zinc-500 bg-white/[0.03] border-y border-white/5 sticky top-0 z-10 backdrop-blur-md uppercase tracking-widest">
                                                    {category}
                                                </div>
                                                <div className="grid grid-cols-4 gap-2 p-3">
                                                    {jobs.map(job => (
                                                        <CommandItem
                                                            key={job.id}
                                                            value={job.name}
                                                            onSelect={() => {
                                                                setSelectedJob(selectedJob === job.id ? null : job.id);
                                                                setIsOpenJob(false);
                                                            }}
                                                            className={cn(
                                                                "flex flex-col items-center justify-center p-3 rounded-xl cursor-pointer transition-all gap-1.5 border h-auto",
                                                                selectedJob === job.id
                                                                    ? "bg-amber-500/20 border-amber-500/40 text-foreground aria-selected:bg-amber-500/30 shadow-[0_0_15px_rgba(245,158,11,0.2)]"
                                                                    : "bg-white/[0.02] border-white/5 hover:bg-white/[0.05] hover:border-white/10 text-muted-foreground hover:text-foreground aria-selected:bg-white/[0.05]"
                                                            )}
                                                        >
                                                            <div className="relative w-9 h-9 flex items-center justify-center filter drop-shadow-[0_4px_8px_rgba(0,0,0,0.5)]">
                                                                {job.icon.startsWith("/") ? (
                                                                    <Image
                                                                        src={job.icon}
                                                                        alt={job.name}
                                                                        fill
                                                                        className="object-contain"
                                                                        sizes="36px"
                                                                    />
                                                                ) : (
                                                                    <span className="text-2xl">{job.icon}</span>
                                                                )}
                                                            </div>
                                                            <span className="text-[10px] font-black truncate w-full text-center uppercase tracking-tighter opacity-80">{job.name}</span>
                                                        </CommandItem>
                                                    ))}
                                                </div>
                                            </div>
                                        ))}
                                    </CommandGroup>
                                </CommandList>
                            </Command>
                        </PopoverContent>
                    </Popover>

                    {/* Alignment Filter Popover */}
                    <Popover open={isOpenAlignment} onOpenChange={setIsOpenAlignment}>
                        <PopoverTrigger asChild>
                            <Button
                                variant="outline"
                                className={cn(
                                    "h-11 border-indigo-500/10 bg-indigo-500/5 hover:bg-indigo-500/10 hover:border-indigo-500/20 text-muted-foreground gap-2.5 px-4 font-black uppercase italic tracking-widest text-[11px] rounded-xl transition-all duration-500 shadow-xl group/btn",
                                    selectedAlignment && "border-indigo-500/40 bg-indigo-500/20 text-indigo-400 shadow-indigo-500/10"
                                )}
                            >
                                <Shield className={cn(
                                    "w-4 h-4 transition-all duration-500 text-indigo-400/50 group-hover/btn:text-indigo-400 group-hover/btn:scale-110", 
                                    selectedAlignment && "rotate-12 scale-110 text-indigo-400 opacity-100"
                                )} />
                                {selectedAlignment ? selectedAlignment : "Alignement"}
                                {selectedAlignment && (
                                    <span
                                        role="button"
                                        tabIndex={0}
                                        className="ml-1 rounded-full hover:bg-indigo-400/20 p-0.5 transition-colors cursor-pointer"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            e.preventDefault();
                                            setSelectedAlignment(null);
                                            setSelectedOrder(null);
                                        }}
                                        onKeyDown={(e) => e.key === 'Enter' && (setSelectedAlignment(null), setSelectedOrder(null))}
                                        aria-label="Supprimer le filtre alignement"
                                    >
                                        <X className="w-3.5 h-3.5 text-indigo-400/60 hover:text-indigo-400" />
                                    </span>
                                )}
                            </Button>
                        </PopoverTrigger>
                        <PopoverContent className="w-[320px] p-4 glass-premium border-white/10 shadow-2xl" align="end">
                            <div className="space-y-3">
                                <h4 className="text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em] mb-2 flex items-center gap-2">
                                    <Shield className="w-3 h-3" /> Factions
                                </h4>
                                <div className="grid grid-cols-3 gap-2">
                                    {ALIGNMENTS.map((a) => {
                                        const isSelected = selectedAlignment === a.id;
                                        return (
                                            <button
                                                key={a.id}
                                                onClick={() => {
                                                    setSelectedAlignment(isSelected ? null : a.id);
                                                    setSelectedOrder(null);
                                                    setIsOpenAlignment(false);
                                                }}
                                                className={cn(
                                                    "relative flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all duration-300",
                                                    isSelected 
                                                        ? "border-indigo-500 bg-indigo-500/10 shadow-[0_0_15px_rgba(99,102,241,0.2)]" 
                                                        : "border-white/5 bg-black/20 hover:border-white/20 hover:bg-white/5"
                                                )}
                                            >
                                                <div className="relative w-10 h-10 rounded-full overflow-hidden border border-white/10 shadow-inner">
                                                    <Image 
                                                        src={a.icon} 
                                                        alt={a.name} 
                                                        fill 
                                                        className="object-cover scale-[1.35]" 
                                                    />
                                                </div>
                                                <span className={cn(
                                                    "text-[9px] font-black uppercase tracking-widest",
                                                    isSelected ? "text-indigo-400" : "text-zinc-400"
                                                )}>
                                                    {a.name}
                                                </span>
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>
                        </PopoverContent>
                    </Popover>

                    {/* Order Filter Popover */}
                    {selectedAlignment && selectedAlignment !== "neutre" && (
                        <Popover open={isOpenOrder} onOpenChange={setIsOpenOrder}>
                            <PopoverTrigger asChild>
                                <Button
                                    variant="outline"
                                    className={cn(
                                        "h-11 border-amber-500/10 bg-amber-500/5 hover:bg-amber-500/10 hover:border-amber-500/20 text-muted-foreground gap-2.5 px-4 font-black uppercase italic tracking-widest text-[11px] rounded-xl transition-all duration-500 shadow-xl group/btn",
                                        selectedOrder && "border-amber-500/40 bg-amber-500/20 text-amber-500 shadow-amber-500/10"
                                    )}
                                >
                                    <Sparkles className={cn(
                                        "w-4 h-4 transition-all duration-500 text-amber-500/50 group-hover/btn:text-amber-500 group-hover/btn:scale-110", 
                                        selectedOrder && "scale-110 -rotate-6 text-amber-500 opacity-100"
                                    )} />
                                    {selectedOrder ? (ORDERS as any)[selectedAlignment].find((o: any) => o.id === selectedOrder)?.name || "Ordre" : "Ordre"}
                                    {selectedOrder && (
                                        <span
                                            role="button"
                                            tabIndex={0}
                                            className="ml-1 rounded-full hover:bg-amber-400/20 p-0.5 transition-colors cursor-pointer"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                e.preventDefault();
                                                setSelectedOrder(null);
                                            }}
                                            onKeyDown={(e) => e.key === 'Enter' && setSelectedOrder(null)}
                                            aria-label="Supprimer le filtre ordre"
                                        >
                                            <X className="w-3.5 h-3.5 text-amber-500/60 hover:text-amber-400" />
                                        </span>
                                    )}
                                </Button>
                            </PopoverTrigger>
                            <PopoverContent className="w-[360px] p-4 glass-premium border-white/10 shadow-2xl" align="end">
                                <div className="space-y-3">
                                    <h4 className="text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em] mb-2 flex items-center gap-2">
                                        <Sparkles className="w-3 h-3" /> Ordres ({selectedAlignment})
                                    </h4>
                                    <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                                        {(ORDERS as any)[selectedAlignment].map((o: any) => {
                                            const isSelected = selectedOrder === o.id;
                                            return (
                                                <button
                                                    key={o.id}
                                                    onClick={() => {
                                                        setSelectedOrder(isSelected ? null : o.id);
                                                        setIsOpenOrder(false);
                                                    }}
                                                    className={cn(
                                                        "relative flex flex-col items-center justify-center gap-2 p-3 rounded-xl border-2 transition-all duration-300 text-center h-24",
                                                        isSelected 
                                                            ? "border-amber-500 bg-amber-500/10 shadow-[0_0_15px_rgba(245,158,11,0.2)]" 
                                                            : "border-white/5 bg-black/20 hover:border-white/20 hover:bg-white/5"
                                                    )}
                                                >
                                                    <div className="relative w-8 h-8 rounded-lg overflow-hidden shrink-0">
                                                        <Image 
                                                            src={o.icon} 
                                                            alt={o.name} 
                                                            fill 
                                                            className="object-contain" 
                                                        />
                                                    </div>
                                                    <span className={cn(
                                                        "text-[9px] font-black uppercase leading-tight line-clamp-2 px-1",
                                                        isSelected ? "text-amber-400" : "text-zinc-400"
                                                    )}>
                                                        {o.name}
                                                    </span>
                                                </button>
                                            );
                                        })}
                                    </div>
                                </div>
                            </PopoverContent>
                        </Popover>
                    )}



                    {/* Legendary Filter Popover */}
                    <Popover open={isOpenLegendary} onOpenChange={setIsOpenLegendary}>
                        <PopoverTrigger asChild>
                            <Button
                                variant="outline"
                                className={cn(
                                    "h-11 border-purple-500/10 bg-purple-500/5 hover:bg-purple-500/10 hover:border-purple-500/20 text-muted-foreground gap-2.5 px-4 font-black uppercase italic tracking-widest text-[11px] rounded-xl transition-all duration-500 shadow-xl group/btn",
                                    selectedLegendary && "border-purple-500/40 bg-purple-500/20 text-purple-400 shadow-purple-500/10"
                                )}
                            >
                                <Sparkles className={cn(
                                    "w-4 h-4 transition-all duration-500 text-purple-400/50 group-hover/btn:text-purple-400 group-hover/btn:scale-110", 
                                    selectedLegendary && "scale-110 -rotate-6 text-purple-400 opacity-100"
                                )} />
                                {selectedLegendary ? getSelectedLegendaryName() : "Légendaire"}
                                {selectedLegendary && (
                                    <span
                                        role="button"
                                        tabIndex={0}
                                        className="ml-1 rounded-full hover:bg-purple-400/20 p-0.5 transition-colors cursor-pointer"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            e.preventDefault();
                                            setSelectedLegendary(null);
                                        }}
                                        onKeyDown={(e) => e.key === 'Enter' && setSelectedLegendary(null)}
                                        aria-label="Supprimer le filtre légendaire"
                                    >
                                        <X className="w-3.5 h-3.5 text-purple-400/60 hover:text-purple-400" />
                                    </span>
                                )}
                            </Button>
                        </PopoverTrigger>
                        <PopoverContent className="w-[300px] p-0 glass-premium border-white/10 shadow-2xl" align="end">
                            <Command className="bg-transparent">
                                <CommandInput placeholder="Chercher un objet..." className="h-11 border-none bg-transparent" />
                                <CommandList className="max-h-[300px]">
                                    <CommandEmpty>Aucun objet trouvé.</CommandEmpty>
                                    <CommandGroup heading="Objets Légendaires" className="text-zinc-500 font-black uppercase text-[10px] tracking-widest p-2">
                                        <div className="grid grid-cols-2 gap-2 p-2">
                                            {legendaryItems.map((item) => (
                                                <CommandItem
                                                    key={item.id}
                                                    value={item.name}
                                                    onSelect={() => {
                                                        setSelectedLegendary(selectedLegendary === item.id ? null : item.id);
                                                        setIsOpenLegendary(false);
                                                    }}
                                                    className={cn(
                                                        "flex flex-col items-center justify-center gap-2 p-3 rounded-xl cursor-pointer transition-all border border-transparent text-center h-28",
                                                        selectedLegendary === item.id 
                                                            ? "bg-purple-500/20 border-purple-500/40 shadow-[0_0_15px_rgba(168,85,247,0.2)] text-white" 
                                                            : "bg-white/[0.02] border-white/5 hover:bg-white/[0.05] hover:border-white/10 text-muted-foreground"
                                                    )}
                                                >
                                                    <div className="relative w-10 h-10 flex items-center justify-center bg-black/40 rounded-xl border border-white/10 overflow-hidden shadow-inner shrink-0">
                                                        {item.imageUrl ? (
                                                            <img src={item.imageUrl.startsWith("/") ? item.imageUrl : `/api/proxy-image?url=${encodeURIComponent(item.imageUrl)}`} alt={item.name} width={32} height={32} className="object-contain" />
                                                        ) : (
                                                            <Sparkles className="w-5 h-5 text-purple-500/50" />
                                                        )}
                                                    </div>
                                                    <div className="flex flex-col items-center px-1">
                                                        <span className="text-[10px] font-black uppercase leading-tight line-clamp-2 text-center">
                                                            {item.name}
                                                        </span>
                                                        <span className="text-[8px] text-zinc-500 uppercase mt-1 tracking-widest">
                                                            {item.jobRequired}
                                                        </span>
                                                    </div>
                                                    {selectedLegendary === item.id && (
                                                        <div className="absolute top-2 right-2 w-4 h-4 rounded-full bg-purple-500 flex items-center justify-center shadow-[0_0_10px_rgba(168,85,247,0.5)]">
                                                            <Check className="w-2.5 h-2.5 text-white" />
                                                        </div>
                                                    )}
                                                </CommandItem>
                                            ))}
                                        </div>
                                    </CommandGroup>
                                </CommandList>
                            </Command>
                        </PopoverContent>
                    </Popover>

                    {/* Legendary Pet Filter Button */}
                    <Button
                        variant="outline"
                        onClick={() => setFilterLegendaryPet(!filterLegendaryPet)}
                        className={cn(
                            "h-11 border-amber-400/10 bg-amber-400/5 hover:bg-amber-400/10 hover:border-amber-400/20 text-muted-foreground gap-2.5 px-4 font-black uppercase italic tracking-widest text-[11px] rounded-xl transition-all duration-500 shadow-xl group/btn shrink-0",
                            filterLegendaryPet && "border-amber-400/40 bg-amber-400/20 text-amber-300 shadow-amber-400/10"
                        )}
                    >
                        <Image
                            src="/assets/icons/croquette.png"
                            alt="Service légendaire familier"
                            width={18}
                            height={18}
                            className={cn(
                                "object-contain transition-all duration-500",
                                filterLegendaryPet
                                    ? "drop-shadow-[0_0_6px_rgba(251,191,36,0.8)] scale-110"
                                    : "grayscale opacity-50 group-hover/btn:opacity-80 group-hover/btn:grayscale-0"
                            )}
                        />
                        Service Familier ★
                        {filterLegendaryPet && (
                            <span
                                role="button"
                                tabIndex={0}
                                className="ml-1 rounded-full hover:bg-amber-300/20 p-0.5 transition-colors cursor-pointer"
                                onClick={(e) => {
                                    e.stopPropagation();
                                    e.preventDefault();
                                    setFilterLegendaryPet(false);
                                }}
                                onKeyDown={(e) => e.key === 'Enter' && setFilterLegendaryPet(false)}
                                aria-label="Supprimer le filtre familier"
                            >
                                <X className="w-3.5 h-3.5 text-amber-300/60 hover:text-amber-300" />
                            </span>
                        )}
                    </Button>

                    {/* Reset Button — High Visibility */}
                    {activeFiltersCount > 0 && (
                        <Button
                            variant="ghost"
                            size="icon"
                            onClick={resetFilters}
                            className="h-11 w-11 text-zinc-600 hover:text-rose-500 hover:bg-rose-500/5 transition-all duration-500 group/reset"
                            title="Réinitialiser les filtres"
                        >
                            <X className="w-5 h-5 transition-transform group-hover:rotate-90 group-active:scale-90" />
                        </Button>
                    )}
                </div>
            </div>

            {/* RESULT STATS */}
            <div className="flex items-center justify-between px-1 mb-6">
                <p className="text-xs font-black text-muted-foreground uppercase tracking-widest italic">
                    <span className="text-foreground">{filteredMembers.length}</span> membre{filteredMembers.length > 1 ? "s" : ""} trouvé{filteredMembers.length > 1 ? "s" : ""}
                </p>
            </div>

            {/* RESULTS GRID */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 animate-in fade-in duration-500">
                {filteredMembers.map(member => (
                    <MemberCard key={member.id} profile={member} guildId={guildId} />
                ))}
            </div>

            {/* EMPTY STATE */}
            {filteredMembers.length === 0 && (
                <div className="py-12">
                    <EmptyState
                        icon={Filter}
                        title="Aucun membre trouvé"
                        description="Essayez de modifier vos filtres ou votre recherche pour trouver un compagnon de guilde."
                        variant="premium"
                        action={{
                            label: "Réinitialiser les filtres",
                            onClick: resetFilters
                        }}
                    />
                </div>
            )}
            </TabsContent>

            <TabsContent value="absences" className="mt-0 border-0 p-0 animate-in fade-in zoom-in-95 duration-500">
                <GuildAbsenceCalendar members={members} guildId={guildId} />
            </TabsContent>
        </Tabs>
    );
}

"use client";

import { cn } from "@/lib/utils";
import { format } from "date-fns";
import { fr } from "date-fns/locale";
import { Hash, Volume2, Shield, Info, ExternalLink } from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";

interface EmbedField {
    name: string;
    value: string;
    inline?: boolean;
}

interface DiscordEmbedPreviewProps {
    title?: string;
    description?: string;
    color?: number; // Hex number
    fields?: EmbedField[];
    thumbnail?: string;
    image?: string;
    footer?: string;
    author?: {
        name: string;
        iconUrl?: string;
    };
    mentionContent?: string;
    channelName?: string;
    timestamp?: Date;
    className?: string;
}

export function DiscordEmbedPreview({
    title,
    description,
    color = 0x9333ea,
    fields = [],
    thumbnail,
    image,
    footer,
    author,
    mentionContent,
    channelName = "annonces",
    timestamp = new Date(),
    className
}: DiscordEmbedPreviewProps) {
    // Convert decimal color to hex string
    const hexColor = color ? `#${color.toString(16).padStart(6, '0')}` : "#9333ea";

    return (
        <div className={cn("flex flex-col gap-1 w-full max-w-[520px] font-sans text-[14px] leading-[1.375rem]", className)}>
            {/* Channel Info Header */}
            <div className="flex items-center gap-2 mb-2 px-1">
                <Hash className="w-4 h-4 text-zinc-500" />
                <span className="text-zinc-300 font-bold text-sm tracking-tight">{channelName}</span>
                <span className="text-[10px] text-zinc-500 font-medium uppercase tracking-wider ml-1 bg-zinc-800/50 px-1.5 py-0.5 rounded border border-white/5">Aperçu Discord</span>
            </div>

            <div className="flex gap-4 p-4 rounded-xl bg-[#313338] border border-white/5 shadow-2xl relative overflow-hidden group">
                {/* User Avatar Placeholder (SigilOS Bot) */}
                <div className="shrink-0 pt-0.5">
                    <div className="w-10 h-10 rounded-full bg-indigo-600 flex items-center justify-center border border-white/10 shadow-lg relative">
                        <img src="/assets/ui/logo-v2.png" alt="SigilOS" className="w-6 h-6 object-contain" />
                        <div className="absolute -bottom-0.5 -right-0.5 w-3.5 h-3.5 rounded-full bg-indigo-500 border-2 border-[#313338] flex items-center justify-center">
                            <Shield className="w-2 h-2 text-white" />
                        </div>
                    </div>
                </div>

                <div className="flex-1 min-w-0">
                    {/* Message Header */}
                    <div className="flex items-center gap-2 mb-1">
                        <span className="font-bold text-white hover:underline cursor-pointer">SigilOS</span>
                        <span className="bg-[#5865F2] text-white text-[10px] px-1.5 py-0.5 rounded-[3px] font-black uppercase flex items-center gap-0.5 leading-none">
                             BOT
                        </span>
                        <span className="text-[12px] text-zinc-400 font-medium">
                            {format(timestamp, "'Aujourd'hui à' HH:mm", { locale: fr })}
                        </span>
                    </div>

                    {/* Mention Content (if any) */}
                    {mentionContent && (
                        <div className="text-[#dbdee1] mb-1.5 whitespace-pre-wrap break-words">
                            {mentionContent.split(/(<@&\d+>)/g).map((part, i) => {
                                if (part.startsWith("<@&")) {
                                    return <span key={i} className="text-[#c9cdfb] bg-[#3e4171] px-0.5 rounded-[3px] font-medium hover:bg-[#5865f2] hover:text-white cursor-pointer transition-colors">@Rôle Mentionné</span>;
                                }
                                return part;
                            })}
                        </div>
                    )}

                    {/* The Embed */}
                    <div 
                        className="mt-1 flex flex-col rounded-[4px] border-l-4 bg-[#2b2d31] max-w-[432px] shadow-sm"
                        style={{ borderLeftColor: hexColor }}
                    >
                        <div className="p-3 pr-4 flex gap-3">
                            <div className="flex-1 min-w-0">
                                {/* Author */}
                                {author && (
                                    <div className="flex items-center gap-2 mb-2">
                                        {author.iconUrl && <img src={author.iconUrl} alt="" className="w-6 h-6 rounded-full" />}
                                        <span className="text-white text-[13px] font-bold hover:underline cursor-pointer">{author.name}</span>
                                    </div>
                                )}

                                {/* Title */}
                                {title && (
                                    <div className="text-white text-[16px] font-bold mb-2 hover:underline cursor-pointer leading-[1.25rem] text-[#00a8fc]">
                                        {title}
                                    </div>
                                )}

                                {/* Description */}
                                {description && (
                                    <div className="text-[#dbdee1] text-[14px] leading-[1.125rem] whitespace-pre-wrap break-words opacity-90">
                                        {description.split('\n').map((line, i) => (
                                            <p key={i} className={cn(i > 0 && "mt-1")}>{line}</p>
                                        ))}
                                    </div>
                                )}

                                {/* Fields */}
                                {fields.length > 0 && (
                                    <div className="mt-4 grid grid-cols-12 gap-y-4 gap-x-2">
                                        {fields.map((field, i) => (
                                            <div 
                                                key={i} 
                                                className={cn(
                                                    "col-span-12",
                                                    field.inline ? "sm:col-span-4" : "col-span-12"
                                                )}
                                            >
                                                <div className="text-white text-[13px] font-bold mb-1">{field.name}</div>
                                                <div className="text-[#dbdee1] text-[13px] leading-[1.125rem] whitespace-pre-wrap">{field.value}</div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>

                            {/* Thumbnail */}
                            {thumbnail && (
                                <div className="shrink-0 mt-2">
                                    <img src={thumbnail} alt="" className="w-[80px] h-[80px] rounded object-contain bg-zinc-900/50" />
                                </div>
                            )}
                        </div>

                        {/* Large Image */}
                        {image && (
                            <div className="mt-2 px-3 pb-3">
                                <img src={image} alt="" className="rounded max-h-[300px] w-full object-cover border border-white/5" />
                            </div>
                        )}

                        {/* Footer */}
                        {(footer || timestamp) && (
                            <div className="px-3 pb-3 flex items-center gap-2 text-zinc-400 text-[11px] font-medium">
                                <span>{footer || "SigilOS — Donjons & Quêtes"}</span>
                                {timestamp && (
                                    <>
                                        <span className="w-1 h-1 rounded-full bg-zinc-600" />
                                        <span>{format(timestamp, "dd/MM/yyyy", { locale: fr })}</span>
                                    </>
                                )}
                            </div>
                        )}
                    </div>

                    {/* Component Buttons (Simulated) */}
                    <div className="mt-2 flex flex-wrap gap-2">
                        <div className="px-4 py-1.5 rounded-[3px] bg-[#4e5058] text-white text-xs font-bold flex items-center gap-2 cursor-not-allowed opacity-80">
                             ⚔️ S'inscrire
                        </div>
                        <div className="px-4 py-1.5 rounded-[3px] bg-[#4e5058] text-white text-xs font-bold flex items-center gap-2 cursor-not-allowed opacity-80">
                            🚪 Se désinscrire
                        </div>
                        <div className="px-4 py-1.5 rounded-[3px] bg-[#4e5058] text-white text-xs font-bold flex items-center gap-2 cursor-not-allowed opacity-80">
                            🔗 Voir sur le site <ExternalLink className="w-3 h-3" />
                        </div>
                    </div>
                </div>
            </div>
            <p className="text-[10px] text-zinc-500 italic mt-1 ml-1 flex items-center gap-1">
                <Info className="w-3 h-3" /> Note: Cet aperçu simule l'affichage final sur Discord.
            </p>
        </div>
    );
}

"use client";

import { cn } from "@/lib/utils";
import * as React from "react";
import { toast } from "sonner";
import { sanitizeHtml } from "@/lib/security";

interface DocContentProps {
    content: string;
    className?: string;
}

export function DocContent({ content, className }: DocContentProps) {
    const contentRef = React.useRef<HTMLDivElement>(null);

    // Elite Post-Processing (Steps, Zoom, Copy, Callout Icons)
    React.useEffect(() => {
        if (!contentRef.current) return;

        // A. Headings & Anchors Logic
        const headings = contentRef.current.querySelectorAll('h2, h3');
        headings.forEach(h => {
            if (!h.id) {
                h.id = (h.textContent || "").toLowerCase().replace(/[^\w\s-]/g, '').replace(/\s+/g, '-');
            }
            if (!h.querySelector('.anchor-link')) {
                const anchor = document.createElement('a');
                anchor.href = `#${h.id}`;
                anchor.className = 'anchor-link opacity-0 group-hover:opacity-100 ml-2 text-zinc-600 hover:text-indigo-400 p-1 transition-all';
                anchor.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/></svg>';
                h.classList.add('group', 'flex', 'items-center');
                h.appendChild(anchor);
            }
        });

        // B. Callout Enrichment (Auto-Icons)
        const callouts = contentRef.current.querySelectorAll('.callout');
        const icons: Record<string, string> = {
            info: '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4"/><path d="M12 8h.01"/></svg>',
            tip: '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M15 14c.2-1 .7-1.7 1.5-2.5 1-.9 1.5-2.2 1.5-3.5A6 6 0 0 0 6 8c0 1 .2 2.2 1.5 3.5.7.7 1.3 1.5 1.5 2.5"/><path d="M9 18h6"/><path d="M10 22h4"/></svg>',
            success: '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg>',
            warning: '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><path d="M12 9v4"/><path d="M12 17h.01"/></svg>',
            danger: '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="m10.27 2.1-6.9 12c-.79 1.38.22 3.1 1.8 3.1h13.8c1.58 0 2.59-1.72 1.8-3.1l-6.9-12a2 2 0 0 0-3.6 0Z"/><path d="M12 7v4"/><path d="M12 15h.01"/></svg>',
            error: '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="m10.27 2.1-6.9 12c-.79 1.38.22 3.1 1.8 3.1h13.8c1.58 0 2.59-1.72 1.8-3.1l-6.9-12a2 2 0 0 0-3.6 0Z"/><path d="M12 7v4"/><path d="M12 15h.01"/></svg>',
            important: '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 8v4"/><path d="M12 16h.01"/></svg>',
            note: '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"/><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"/></svg>',
            abstract: '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M4 19.5v-15A2.5 2.5 0 0 1 6.5 2H20v20H6.5a2.5 2.5 0 0 1 0-5H20"/></svg>',
            caution: '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><path d="M12 9v4"/><path d="M12 17h.01"/></svg>',
            question: '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/><path d="M12 17h.01"/></svg>',
            bug: '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect width="8" height="14" x="8" y="6" rx="4"/><path d="m19 7-3 2"/><path d="m5 7 3 2"/><path d="m19 19-3-2"/><path d="m5 19 3-2"/><path d="M20 13h-4"/><path d="M4 13h4"/><path d="m10 4 1 2"/><path d="m14 4-1 2"/></svg>',
            todo: '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10z"/><path d="m9 12 2 2 4-4"/></svg>',
        };

        callouts.forEach(callout => {
            const classes = Array.from(callout.classList);
            const type = classes.find(c => c.startsWith('callout-'))?.replace('callout-', '');
            const title = callout.querySelector('strong');
            if (title && type && icons[type] && !title.querySelector('.callout-icon')) {
                const icon = document.createElement('span');
                icon.className = 'callout-icon opacity-80 shrink-0';
                icon.innerHTML = icons[type];
                title.prepend(icon);
                title.classList.add('flex', 'items-center', 'gap-2');
            }
        });

        // C. Steps Auto-Styling
        const stepLists = contentRef.current.querySelectorAll('.steps');
        stepLists.forEach(list => {
            const items = list.querySelectorAll('li');
            items.forEach((li: any, idx) => {
                if (li.querySelector('.step-number')) return;
                li.classList.add('step-item');
                const num = document.createElement('div');
                num.className = 'step-number';
                num.innerText = (idx + 1).toString();
                li.prepend(num);
            });
        });

        // D. Image Zoom
        const images = contentRef.current.querySelectorAll('img');
        images.forEach((img: any) => {
            img.classList.add('cursor-zoom-in', 'transition-transform', 'duration-300', 'hover:scale-[1.02]', 'rounded-xl', 'shadow-xl');
            img.onclick = () => {
                if (img.classList.contains('fixed')) {
                    img.className = 'cursor-zoom-in transition-transform duration-300 hover:scale-[1.02] rounded-xl shadow-xl max-w-full';
                    img.style.position = '';
                    img.style.top = '';
                    img.style.left = '';
                    img.style.width = '';
                    img.style.zIndex = '';
                    document.body.style.overflow = '';
                } else {
                    img.classList.add('fixed', 'inset-0', 'm-auto', 'z-[1000]', 'max-w-[90vw]', 'max-h-[90vh]', 'cursor-zoom-out', 'object-contain', 'p-4', 'bg-black/80', 'backdrop-blur-xl');
                    document.body.style.overflow = 'hidden';
                }
            };
        });

        // E. Code Copy
        const preBlocks = contentRef.current.querySelectorAll('pre');
        preBlocks.forEach((pre) => {
            if (pre.querySelector('.copy-button')) return;
            pre.style.position = 'relative';
            pre.classList.add('group');

            const button = document.createElement('button');
            button.className = 'copy-button absolute top-4 right-4 p-2 rounded-xl bg-white/5 border border-white/10 hover:bg-white/10 text-zinc-500 hover:text-white transition-all opacity-0 group-hover:opacity-100 focus:opacity-100 shadow-xl backdrop-blur-md';
            button.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-copy"><rect width="14" height="14" x="8" y="8" rx="2" ry="2"/><path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2"/></svg>';

            button.onclick = (e) => {
                e.preventDefault();
                const code = pre.querySelector('code')?.innerText || pre.innerText;
                navigator.clipboard.writeText(code);
                toast.success("Code copié !");
                button.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check text-emerald-400"><polyline points="20 6 9 17 4 12"/></svg>';
                setTimeout(() => {
                    button.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-copy"><rect width="14" height="14" x="8" y="8" rx="2" ry="2"/><path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2"/></svg>';
                }, 2000);
            };
            pre.appendChild(button);
        });
    }, [content]);

    if (!content) return null;

    // 🔒 SECURITY FIX: Sanitize HTML to prevent XSS attacks
    // Ref: Security Audit Report #1 - Critical XSS vulnerability
    const sanitizedContent = sanitizeHtml(content) || "";


    return (
        <div
            className={cn(
                "doc-preview-content prose prose-zinc dark:prose-invert max-w-none break-words min-w-0",
                // Headers - Modern & Gradient
                "prose-headings:font-black prose-headings:tracking-tight prose-headings:mb-6 prose-headings:mt-10",
                "prose-h1:text-4xl prose-h1:text-white prose-h1:mb-8",
                "prose-h2:text-2xl prose-h2:border-b prose-h2:border-white/10 prose-h2:pb-3 prose-h2:text-teal-400 prose-h2:tracking-wide",
                "prose-h3:text-xl prose-h3:text-amber-400 prose-h3:tracking-tight",

                // Text & Layout
                "prose-p:leading-relaxed prose-p:text-zinc-300 prose-p:mb-6 prose-p:text-[15px]",
                "prose-strong:text-white prose-strong:font-black",

                // Lists
                "prose-ul:list-disc prose-ul:ml-6 prose-ul:marker:text-teal-500",
                "prose-ol:list-decimal prose-ol:ml-6 prose-ol:marker:text-amber-500",
                "prose-li:pl-2 prose-li:my-3",

                // Links
                "prose-a:text-teal-400 prose-a:font-bold prose-a:no-underline hover:prose-a:text-teal-300 hover:prose-a:underline hover:prose-a:decoration-2 hover:prose-a:underline-offset-4 transition-all",

                // Code Blocks
                "prose-code:text-emerald-300 prose-code:bg-emerald-500/10 prose-code:px-1.5 prose-code:py-0.5 prose-code:rounded prose-code:font-mono prose-code:text-xs prose-code:before:content-none prose-code:after:content-none",
                "prose-pre:bg-[#050505] prose-pre:border prose-pre:border-white/5 prose-pre:rounded-2xl prose-pre:p-6 prose-pre:shadow-2xl",

                // Callouts / Alerts - Elite Standard (GitHub Flavor)
                "[&_.callout]:my-10 [&_.callout]:p-6 [&_.callout]:rounded-2xl [&_.callout]:border-l-[6px] [&_.callout]:bg-white/[0.03] [&_.callout]:backdrop-blur-xl [&_.callout]:shadow-2xl [&_.callout]:transition-all [&_.callout]:relative [&_.callout]:overflow-hidden",
                "[&_.callout:hover]:bg-white/[0.05] [&_.callout:hover]:scale-[1.01]",

                "[&_.callout-info]:border-blue-500 [&_.callout-info]:text-blue-100/90",
                "[&_.callout-tip]:border-emerald-500 [&_.callout-tip]:text-emerald-100/90",
                "[&_.callout-success]:border-emerald-500 [&_.callout-success]:text-emerald-100/90",
                "[&_.callout-warning]:border-amber-500 [&_.callout-warning]:text-amber-100/90",
                "[&_.callout-caution]:border-red-500 [&_.callout-caution]:text-red-100/90",
                "[&_.callout-danger]:border-red-500 [&_.callout-danger]:text-red-100/90",
                "[&_.callout-error]:border-red-500 [&_.callout-error]:text-red-100/90",
                "[&_.callout-important]:border-teal-500 [&_.callout-important]:text-teal-100/90",
                "[&_.callout-note]:border-zinc-500 [&_.callout-note]:text-zinc-200/90",
                "[&_.callout-abstract]:border-cyan-500 [&_.callout-abstract]:text-cyan-100/90",
                "[&_.callout-question]:border-indigo-500 [&_.callout-question]:text-indigo-100/90",
                "[&_.callout-bug]:border-rose-500 [&_.callout-bug]:text-rose-100/90",
                "[&_.callout-todo]:border-emerald-500 [&_.callout-todo]:text-emerald-100/90",

                "[&_.callout\ strong]:text-white [&_.callout\ strong]:font-black [&_.callout\ strong]:uppercase [&_.callout\ strong]:tracking-widest [&_.callout\ strong]:text-[10px] [&_.callout\ strong]:mb-2",

                // Steps Component (Auto-styling for tutorials)
                "[&_.steps]:relative [&_.steps]:ml-4 [&_.steps]:pl-8 [&_.steps]:border-l-2 [&_.steps]:border-white/5 [&_.steps]:space-y-12 [&_.steps]:py-4",
                "[&_.step-item]:relative",
                "[&_.step-number]:absolute [&_.step-number]:-left-[49px] [&_.step-number]:top-0 [&_.step-number]:w-8 [&_.step-number]:h-8 [&_.step-number]:bg-black [&_.step-number]:border-2 [&_.step-number]:border-teal-500 [&_.step-number]:rounded-full [&_.step-number]:flex [&_.step-number]:items-center [&_.step-number]:justify-center [&_.step-number]:text-xs [&_.step-number]:font-black [&_.step-number]:text-white [&_.step-number]:shadow-[0_0_15px_rgba(45,212,191,0.4)]",

                // Accordions / Details
                "prose-details:bg-white/[0.03] prose-details:border prose-details:border-white/5 prose-details:rounded-2xl prose-details:overflow-hidden prose-details:my-6 prose-details:transition-all",
                "prose-summary:px-6 prose-summary:py-4 prose-summary:font-bold prose-summary:cursor-pointer prose-summary:hover:bg-white/5 prose-summary:list-none prose-summary:flex prose-summary:items-center prose-summary:justify-between prose-summary:after:content-['+'] open:prose-summary:after:content-['-']",
                "[&_details[open]]:bg-white/[0.05]",
                "[&_details_>_div]:p-6 [&_details_>_div]:border-t [&_details_>_div]:border-white/5",

                // Table of Contents anchoring
                "scroll-mt-32",


                // Custom Style Overrides (Ensure colors and floats stick)
                "[&_span[style]]:!opacity-100",
                "[&_span[style*='color']]:![color:inherit]", // Preserve TipTap color styles
                "[&_img]:max-w-full [&_img]:h-auto [&_img]:object-contain", // Fix image overflow

                className
            )}
            ref={contentRef}
            // nosemgrep
            dangerouslySetInnerHTML={{ __html: sanitizedContent }}
        />
    );
}

"use client";

import { useTransition } from "react";
import { useRouter, useSearchParams, usePathname } from "next/navigation";
import { User, Users, ChevronDown, Crown } from "lucide-react";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { ClassIcon } from "@/components/shared/class-icon";
import { DofusClass } from "@/lib/songes/types";

interface CharacterQuestSelectorProps {
    mainCharacter: {
        pseudo: string;
        classe?: string | null;
    };
    mules: {
        pseudo: string;
        classe?: string | null;
        level?: number | null;
    }[];
}

export function CharacterQuestSelector({ mainCharacter, mules }: CharacterQuestSelectorProps) {
    const router = useRouter();
    const pathname = usePathname();
    const searchParams = useSearchParams();
    const [isPending, startTransition] = useTransition();

    const selectedCharacter = searchParams.get("character") || "PRINCIPAL";

    const handleSelect = (char: string) => {
        const params = new URLSearchParams(searchParams.toString());
        if (char === "PRINCIPAL") {
            params.delete("character");
        } else {
            params.set("character", char);
        }
        startTransition(() => {
            router.push(`${pathname}?${params.toString()}`);
        });
    };

    // Find class of selected character
    const selectedCharClass = selectedCharacter === "PRINCIPAL"
        ? mainCharacter.classe
        : mules.find(m => m.pseudo === selectedCharacter)?.classe;

    const currentLabel = selectedCharacter === "PRINCIPAL" 
        ? mainCharacter.pseudo
        : selectedCharacter;

    return (
        <div className="flex flex-col gap-1.5">
            <span className="text-[9px] font-black text-zinc-500 uppercase tracking-widest ml-1">
                Personnage Actif
            </span>
            <DropdownMenu>
                <DropdownMenuTrigger asChild>
                    <Button 
                        variant="outline" 
                        role="combobox"
                        aria-expanded={false}
                        className="bg-zinc-950/60 backdrop-blur-md border-white/5 hover:border-emerald-500/20 text-white justify-between min-w-[200px] transition-all rounded-xl h-10 px-3 cursor-pointer"
                        disabled={isPending}
                    >
                        <div className="flex items-center gap-2 truncate">
                            {selectedCharClass ? (
                                <ClassIcon classId={selectedCharClass as DofusClass} size={18} />
                            ) : selectedCharacter === "PRINCIPAL" ? (
                                <Crown className="w-3.5 h-3.5 text-amber-500" />
                            ) : (
                                <Users className="w-3.5 h-3.5 text-blue-400" />
                            )}
                            <span className="truncate font-bold tracking-wide text-xs">{currentLabel}</span>
                        </div>
                        <ChevronDown className={`w-3.5 h-3.5 transition-transform opacity-30 ${isPending ? 'animate-pulse' : ''}`} />
                    </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="bg-zinc-950/95 backdrop-blur-xl border-white/5 text-white min-w-[200px] rounded-xl p-1.5 shadow-2xl z-[100]">
                    <DropdownMenuItem 
                        onClick={() => handleSelect("PRINCIPAL")}
                        className={`flex items-center gap-2.5 px-2.5 py-2 rounded-lg cursor-pointer transition-colors ${selectedCharacter === "PRINCIPAL" ? "bg-white/5 text-emerald-400" : "hover:bg-white/5"}`}
                    >
                        <div className="w-7 h-7 rounded-lg bg-amber-500/10 flex items-center justify-center border border-amber-500/20">
                            {mainCharacter.classe ? (
                                <ClassIcon classId={mainCharacter.classe as DofusClass} size={16} />
                            ) : (
                                <Crown className="w-3.5 h-3.5 text-amber-500" />
                            )}
                        </div>
                        <div className="flex flex-col text-left">
                            <span className="text-xs font-bold">{mainCharacter.pseudo}</span>
                            <span className="text-[9px] text-zinc-500 font-medium uppercase tracking-widest">{mainCharacter.classe || "Principal"}</span>
                        </div>
                    </DropdownMenuItem>
                    
                    {mules.length > 0 && <div className="h-px bg-white/5 my-1" />}
                    
                    {mules.map((mule) => (
                        <DropdownMenuItem 
                            key={mule.pseudo}
                            onClick={() => handleSelect(mule.pseudo)}
                            className={`flex items-center gap-2.5 px-2.5 py-2 rounded-lg cursor-pointer transition-colors ${selectedCharacter === mule.pseudo ? "bg-white/5 text-emerald-400" : "hover:bg-white/5"}`}
                        >
                            <div className="w-7 h-7 rounded-lg bg-blue-500/10 flex items-center justify-center border border-blue-500/20">
                                {mule.classe ? (
                                    <ClassIcon classId={mule.classe as DofusClass} size={16} />
                                ) : (
                                    <Users className="w-3.5 h-3.5 text-blue-400" />
                                )}
                            </div>
                            <div className="flex flex-col text-left">
                                <span className="text-xs font-bold">{mule.pseudo}</span>
                                <span className="text-[9px] text-zinc-500 font-medium uppercase tracking-widest">
                                    Niv. {mule.level || 200} {mule.classe ? `• ${mule.classe}` : ""}
                                </span>
                            </div>
                        </DropdownMenuItem>
                    ))}
                </DropdownMenuContent>
            </DropdownMenu>
        </div>
    );
}

"use client";

import React, { useState, useTransition } from "react";
import { motion } from "framer-motion";
import { BookOpen, CalendarDays, ExternalLink, Plus, Minus, CheckCircle2, Info } from "lucide-react";
import Link from "next/link";
import { Button } from "@/components/ui/button";

// ─────────────────────────────────────────────────────────────────────────────
// Dolmanax Tracker — 365 Almanax pages declarative component
// The Dolmanax is obtained after collecting 365 Almanax pages via daily quests.
// No quest chain to track — just a simple progress declaration.
// ─────────────────────────────────────────────────────────────────────────────

const TOTAL_PAGES = 365;

interface DofusDolmanaxTrackerProps {
    guildId: string;
    /** Current saved page count for this member — from DB (can be null/0 if not set). */
    initialPages?: number;
    /** Callback to persist the value server-side */
    onSave?: (pages: number) => Promise<void>;
}

export function DofusDolmanaxTracker({ guildId, initialPages = 0, onSave }: DofusDolmanaxTrackerProps) {
    const [pages, setPages] = useState<number>(Math.min(Math.max(0, initialPages), TOTAL_PAGES));
    const [isSaving, startSave] = useTransition();
    const [saved, setSaved] = useState(false);

    const pct = Math.round((pages / TOTAL_PAGES) * 100);
    const isDone = pages >= TOTAL_PAGES;

    function adjust(delta: number) {
        setPages(p => Math.min(TOTAL_PAGES, Math.max(0, p + delta)));
        setSaved(false);
    }

    function handleSave() {
        if (!onSave) return;
        startSave(async () => {
            await onSave(pages);
            setSaved(true);
        });
    }

    return (
        <div className="space-y-6">
            {/* Header info */}
            <div className="p-5 bg-amber-500/5 border border-amber-500/15 rounded-3xl flex items-start gap-4">
                <div className="w-10 h-10 rounded-2xl bg-amber-500/10 flex items-center justify-center flex-shrink-0 mt-0.5">
                    <Info className="w-5 h-5 text-amber-400" />
                </div>
                <div className="space-y-1">
                    <div className="text-[10px] font-black text-amber-400 uppercase tracking-[0.4em]">Comment obtenir le Dolmanax</div>
                    <p className="text-[13px] text-zinc-400 leading-relaxed">
                        Le <span className="text-white font-bold italic">Dolmanax</span> s&apos;obtient après avoir récupéré{" "}
                        <span className="text-amber-400 font-black">365 pages d&apos;Almanax</span> via les quêtes journalières dans n&apos;importe quel temple.
                        Chaque jour, parle au PNJ Almanzor dans un temple de la classe pour recevoir ta page.
                    </p>
                    <Link
                        href={`/dashboard/${guildId}/almanax`}
                        className="inline-flex items-center gap-1.5 text-[10px] font-black text-amber-500 hover:text-amber-300 mt-1 transition-colors"
                    >
                        <CalendarDays className="w-3.5 h-3.5" />
                        Voir le module Almanax →
                    </Link>
                </div>
            </div>

            {/* Progress bar */}
            <div className="space-y-3">
                <div className="flex items-center justify-between">
                    <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Progression</span>
                    <span className="text-[13px] font-black text-white tabular-nums">
                        <span style={{ color: isDone ? "#10b981" : "#f59e0b" }}>{pages}</span>
                        <span className="text-zinc-600"> / {TOTAL_PAGES} pages</span>
                    </span>
                </div>
                <div className="w-full h-3 bg-white/5 rounded-full overflow-hidden">
                    <motion.div
                        className="h-full rounded-full relative"
                        style={{
                            background: isDone
                                ? "linear-gradient(90deg, #10b981, #34d399)"
                                : "linear-gradient(90deg, #f59e0b, #fbbf24)",
                            boxShadow: isDone ? "0 0 20px rgba(16,185,129,0.4)" : "0 0 20px rgba(245,158,11,0.3)",
                        }}
                        initial={{ width: 0 }}
                        animate={{ width: `${pct}%` }}
                        transition={{ duration: 0.5, ease: "easeOut" }}
                    />
                </div>
                <div className="flex items-center justify-between text-[9px] font-black uppercase tracking-widest">
                    <span className="text-zinc-700">0</span>
                    <span className={isDone ? "text-emerald-400 animate-pulse" : "text-zinc-600"}>
                        {isDone ? "✓ DOLMANAX OBTENU" : `${pct}% — ${TOTAL_PAGES - pages} jours restants`}
                    </span>
                    <span className="text-zinc-700">365</span>
                </div>
            </div>

            {/* Controls */}
            <div className="flex items-center gap-3">
                <div className="flex items-center bg-zinc-950/80 border border-white/5 rounded-2xl overflow-hidden">
                    <button
                        onClick={() => adjust(-10)}
                        className="w-10 h-10 flex items-center justify-center text-zinc-500 hover:text-white hover:bg-white/5 transition-all border-r border-white/5 text-[10px] font-black"
                    >
                        -10
                    </button>
                    <button
                        onClick={() => adjust(-1)}
                        className="w-10 h-10 flex items-center justify-center text-zinc-500 hover:text-white hover:bg-white/5 transition-all border-r border-white/5"
                    >
                        <Minus className="w-3.5 h-3.5" />
                    </button>
                    <div className="w-20 text-center">
                        <input
                            type="number"
                            min={0}
                            max={TOTAL_PAGES}
                            value={pages}
                            onChange={(e) => {
                                const v = parseInt(e.target.value, 10);
                                if (!isNaN(v)) { setPages(Math.min(TOTAL_PAGES, Math.max(0, v))); setSaved(false); }
                            }}
                            className="w-full bg-transparent text-center text-[16px] font-black text-white outline-none tabular-nums"
                        />
                    </div>
                    <button
                        onClick={() => adjust(+1)}
                        className="w-10 h-10 flex items-center justify-center text-zinc-500 hover:text-white hover:bg-white/5 transition-all border-l border-white/5"
                    >
                        <Plus className="w-3.5 h-3.5" />
                    </button>
                    <button
                        onClick={() => adjust(+10)}
                        className="w-10 h-10 flex items-center justify-center text-zinc-500 hover:text-white hover:bg-white/5 transition-all border-l border-white/5 text-[10px] font-black"
                    >
                        +10
                    </button>
                </div>

                {onSave && (
                    <Button
                        onClick={handleSave}
                        disabled={isSaving || saved}
                        className={`h-10 px-4 rounded-2xl font-black text-[11px] uppercase italic tracking-widest transition-all ${
                            saved
                                ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20"
                                : "bg-white text-black hover:bg-zinc-200 shadow-[0_0_20px_rgba(255,255,255,0.1)]"
                        }`}
                    >
                        {saved ? <><CheckCircle2 className="w-4 h-4 mr-1.5 inline" /> Sauvegardé</> : isSaving ? "..." : "Sauvegarder"}
                    </Button>
                )}
            </div>

            {/* Milestones */}
            <div className="grid grid-cols-3 gap-3">
                {[
                    { label: "Quart", target: 91, emoji: "📖" },
                    { label: "Moitié", target: 183, emoji: "📚" },
                    { label: "Final", target: 365, emoji: "🏆" },
                ].map((milestone) => {
                    const reached = pages >= milestone.target;
                    return (
                        <div key={milestone.target}
                            className={`p-3 rounded-2xl border text-center transition-all ${
                                reached ? "bg-amber-500/10 border-amber-500/25" : "bg-white/[0.02] border-white/5"
                            }`}>
                            <div className="text-xl mb-1">{milestone.emoji}</div>
                            <div className="text-[9px] font-black uppercase tracking-widest text-zinc-500">{milestone.label}</div>
                            <div className={`text-[12px] font-black ${reached ? "text-amber-400" : "text-zinc-700"}`}>
                                {milestone.target} pages
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import Image from "next/image";
import Link from "next/link";
import { Crown, Gem, Lock, Sparkles, RefreshCw } from "lucide-react";
import { DofusProgressRing } from "./DofusProgressRing";
import { DofusIcon } from "./DofusIcon";
import { toggleDofusObtained } from "@/server/actions/dofus-quest-actions";
import type { DofusItemWithProgress } from "@/server/actions/dofus-quest-actions";
import { toast } from "sonner";

interface DofusGemCardProps {
    dofus: DofusItemWithProgress;
    guildId: string;
    selectedCharacter?: string;
}

export function DofusGemCard({ dofus, guildId, selectedCharacter = "PRINCIPAL" }: DofusGemCardProps) {
    const [isObtained, setIsObtained] = useState(dofus.isObtained);
    const [isPending, startTransition] = useTransition();
    const [syncAllMules, setSyncAllMules] = useState(() => {
        if (typeof window !== "undefined") {
            return localStorage.getItem("dofus-sync-all-mules") === "true";
        }
        return false;
    });

    useEffect(() => {
        setIsObtained(dofus.isObtained);
    }, [dofus.isObtained, selectedCharacter]);

    useEffect(() => {
        const handleSyncChange = () => {
            setSyncAllMules(localStorage.getItem("dofus-sync-all-mules") === "true");
        };
        window.addEventListener("dofus-sync-all-mules-changed", handleSyncChange);
        return () => window.removeEventListener("dofus-sync-all-mules-changed", handleSyncChange);
    }, []);

    const color = dofus.color || "#6366f1";
    const hasChain = dofus.totalQuests > 0;
    const isLocked = !hasChain; // No quest data yet

    function handleToggleObtained(e: React.MouseEvent) {
        e.preventDefault();
        e.stopPropagation();
        if (isPending) return;

        const newVal = !isObtained;
        setIsObtained(newVal);
        startTransition(async () => {
            const res = await toggleDofusObtained(guildId, dofus.id, newVal, selectedCharacter, syncAllMules);
            if (res.success) {
                if (syncAllMules) {
                    toast.success(`Dofus ${newVal ? "obtenu" : "retiré"} sur tous vos personnages !`);
                } else {
                    toast.success(`Dofus ${newVal ? "obtenu" : "retiré"} pour ${selectedCharacter === "PRINCIPAL" ? "votre personnage principal" : selectedCharacter}.`);
                }
            } else {
                toast.error(res.error || "Erreur de mise à jour");
                setIsObtained(!newVal); // rollback
            }
        });
    }

    return (
        <Link
            href={`/dashboard/${guildId}/quetes-dofus/${dofus.slug}${selectedCharacter !== "PRINCIPAL" ? `?character=${selectedCharacter}` : ""}`}
            className="group relative flex flex-col rounded-2xl overflow-hidden transition-all duration-300 hover:-translate-y-1 will-change-transform"
            style={{
                background: `linear-gradient(145deg, rgba(255,255,255,0.04) 0%, rgba(255,255,255,0.02) 100%)`,
                border: `1px solid ${isObtained ? color + "66" : "rgba(255,255,255,0.08)"}`,
                boxShadow: isObtained
                    ? `0 0 20px ${color}22, 0 4px 24px rgba(0,0,0,0.4)`
                    : `0 4px 24px rgba(0,0,0,0.3)`,
            }}
        >
            {/* Glow overlay on hover */}
            <div
                className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none rounded-2xl"
                style={{
                    background: `radial-gradient(ellipse at 50% 0%, ${color}18 0%, transparent 70%)`,
                }}
            />

            {/* Tags Section */}
            <div className="absolute top-2 left-2 z-10 flex flex-wrap gap-1 max-w-[85%]">
                {/* Main Dynamic Tag (The one you edit in God Mode) */}
                {dofus.rarity && (
                    <span
                        className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-md text-[9px] font-black uppercase tracking-wider shadow-sm border"
                        style={{
                            background: `${color}15`,
                            color,
                            borderColor: `${color}30`,
                        }}
                    >
                        {dofus.rarity}
                    </span>
                )}

                {/* Functional Icons (Discrete indicators) */}
                {dofus.isPrimordial && (
                    <div className="w-5 h-5 rounded-md bg-amber-500/10 border border-amber-500/30 flex items-center justify-center text-amber-500 shadow-sm" title="Dofus Primordial">
                        <Crown className="w-3 h-3" />
                    </div>
                )}
                {dofus.isMeta && (
                    <div className="w-5 h-5 rounded-md bg-indigo-500/10 border border-indigo-500/30 flex items-center justify-center text-indigo-400 shadow-sm" title="Dofus Méta">
                        <Sparkles className="w-3 h-3" />
                    </div>
                )}
                {dofus.isSylvestreReq && (
                    <div className="w-5 h-5 rounded-md bg-emerald-500/10 border border-emerald-500/30 flex items-center justify-center text-emerald-400 shadow-sm" title="Requis pour le Sylvestre">
                        <Gem className="w-3 h-3" />
                    </div>
                )}
            </div>

            {/* Sync All Mules toggle button */}
            <button
                onClick={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    const nextVal = !syncAllMules;
                    setSyncAllMules(nextVal);
                    localStorage.setItem("dofus-sync-all-mules", String(nextVal));
                    window.dispatchEvent(new Event("dofus-sync-all-mules-changed"));
                }}
                className={`absolute top-3 right-12 z-10 w-7 h-7 rounded-full flex items-center justify-center transition-all duration-200 hover:scale-110 border ${
                    syncAllMules ? "bg-indigo-500/10 border-indigo-500/30 text-indigo-400" : "bg-white/5 border-white/10 text-zinc-500 hover:text-white"
                }`}
                style={{
                    borderColor: syncAllMules ? `${color}66` : undefined,
                    color: syncAllMules ? color : undefined,
                    boxShadow: syncAllMules ? `0 0 8px ${color}33` : undefined,
                }}
                title={syncAllMules ? "Sync multi-personnages ACTIVE (Appliquer à tous)" : "Sync multi-personnages INACTIVE (Seulement ce perso)"}
            >
                <RefreshCw className="w-3.5 h-3.5" />
            </button>

            {/* Obtained toggle button */}
            <button
                onClick={handleToggleObtained}
                disabled={isPending}
                className="absolute top-3 right-3 z-10 w-7 h-7 rounded-full flex items-center justify-center transition-all duration-200 hover:scale-110"
                style={{
                    background: isObtained ? color : "rgba(255,255,255,0.08)",
                    border: `1px solid ${isObtained ? color : "rgba(255,255,255,0.15)"}`,
                    boxShadow: isObtained ? `0 0 10px ${color}66` : "none",
                }}
                title={isObtained ? "Marquer comme non obtenu" : "Marquer comme obtenu"}
                aria-label={isObtained ? "Dofus obtenu — cliquer pour annuler" : "Marquer comme obtenu"}
            >
                {isObtained ? (
                    <span className="text-sm text-black font-bold">✓</span>
                ) : (
                    <span className="text-sm text-white/40">○</span>
                )}
            </button>

            {/* Image + Ring */}
            <div className="flex flex-col items-center pt-10 pb-4 px-4">
                <div className="relative">
                    <DofusProgressRing
                        percent={dofus.progressPercent}
                        size={90}
                        strokeWidth={5}
                        color={color}
                        isObtained={isObtained}
                        showText={false}
                    />
                    <div className="absolute inset-0 flex items-center justify-center">
                        <div className="relative flex items-center justify-center transition-all duration-500 group-hover:scale-110 will-change-transform">
                            {dofus.imageUrl ? (
                                // eslint-disable-next-line @next/next/no-img-element
                                <img
                                    src={dofus.slug === "dofoozbz" ? "/module-dofus/Dofus_dofoozbz.png" : dofus.imageUrl.replace(/^\/public/, "")}
                                    alt={dofus.nameShort}
                                    width={56}
                                    height={56}
                                    className="object-contain"
                                    style={{
                                        filter: isObtained
                                            ? `drop-shadow(0 0 8px ${color}88)`
                                            : `drop-shadow(0 0 3px ${color}22)`,
                                    }}
                                />
                            ) : dofus.nameShort ? (
                                <DofusIcon
                                    name={dofus.nameShort}
                                    size={56}
                                    color={color}
                                    isObtained={isObtained}
                                />
                            ) : (
                                <Gem className="w-8 h-8 opacity-40" style={{ color }} />
                            )}
                        </div>
                    </div>
                </div>
            </div>

            {/* Info */}
            <div className="flex flex-col px-4 pb-4 gap-1">
                <h3
                    className="text-sm font-bold text-center leading-tight"
                    style={{ color: isObtained ? color : "white" }}
                >
                    {dofus.nameShort}
                </h3>

                {hasChain ? (
                    <div className="flex items-center justify-center gap-1.5 mt-1">
                        <div
                            className="flex-1 h-1 rounded-full overflow-hidden"
                            style={{ background: "rgba(255,255,255,0.08)" }}
                        >
                            <div
                                className="h-full rounded-full transition-all duration-700"
                                style={{
                                    width: `${dofus.progressPercent}%`,
                                    background: isObtained
                                        ? `linear-gradient(90deg, ${color}, #fbbf24)`
                                        : color,
                                }}
                            />
                        </div>
                        <span className="text-[10px] tabular-nums font-black" style={{ color: dofus.progressPercent > 0 ? color : "rgba(255,255,255,0.2)" }}>
                            {dofus.progressPercent}%
                        </span>
                        <span className="text-[10px] tabular-nums text-white/20 whitespace-nowrap">
                            ({dofus.completedQuests}/{dofus.totalQuests})
                        </span>
                    </div>
                ) : (
                    <div className="flex items-center justify-center gap-1 mt-1">
                        <Lock className="w-3 h-3 text-white/25" />
                        <span className="text-[10px] text-white/25">Guide à venir</span>
                    </div>
                )}

                {dofus.levelRecommended > 0 && (
                    <p className="text-[10px] text-white/30 text-center mt-0.5">
                        Niveau {dofus.levelRecommended}+
                    </p>
                )}
            </div>

            {/* Bottom accent line */}
            <div
                className="h-0.5 w-full transition-all duration-300"
                style={{
                    background: isObtained
                        ? `linear-gradient(90deg, transparent, ${color}, transparent)`
                        : `linear-gradient(90deg, transparent, ${color}44, transparent)`,
                    opacity: isObtained ? 1 : 0.5,
                }}
            />
        </Link>
    );
}

"use client";

import React, { useMemo } from "react";
import { 
    Package, 
    ChevronDown, 
    Info,
    Sword,
    ScrollText
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { ItemInline, detectRealDungeons, filterQuestItemsFromResources, extractObjectiveText } from "./dofus-resolvers";
import { cn } from "@/lib/utils";

function ResourceNameLink({ itemId, fallbackName }: { itemId: string; fallbackName?: string }) {
    const [name, setName] = React.useState<string | null>(null);

    React.useEffect(() => {
        if (fallbackName && fallbackName !== "Ressource" && fallbackName !== "Objet") {
            setName(fallbackName);
            return;
        }
        fetch(`https://api.dofusdb.fr/items/${itemId}?lang=fr`)
            .then(res => res.ok ? res.json() : null)
            .then(d => {
                if (d?.name?.fr) setName(d.name.fr);
            })
            .catch(() => {});
    }, [itemId, fallbackName]);

    return (
        <a 
            href={`https://dofusdb.fr/fr/database/item/${itemId}`}
            target="_blank"
            rel="noopener noreferrer"
            className="text-[12px] font-black text-amber-400 italic hover:text-amber-300 transition-colors uppercase tracking-tight block truncate"
        >
            {name || fallbackName || `Ressource #${itemId}`}
        </a>
    );
}

interface DofusGlobalLogisticsProps {
    chains: any[];
    dofusColor: string;
    completedIds?: Set<string>;
}

export function DofusGlobalLogistics({ chains, dofusColor, completedIds }: DofusGlobalLogisticsProps) {
    const [isExpanded, setIsExpanded] = React.useState(false);
    const [filteredItems, setFilteredItems] = React.useState<{id: string, amount: number, name: string, img?: string}[]>([]);
    const [isLoadingItems, setIsLoadingItems] = React.useState(true);

    const logistics = useMemo(() => {
        const items = new Map<string, { id: string; amount: number; name: string; img?: string }>();
        const dungeons = new Map<string, { id?: string; name: string; bossName?: string; level?: number; img?: string; idoleName?: string }>();
        let totalQuests = 0;

        // Collect data from ALL chains (including prerequisites) for a true global summary
        (chains || []).forEach(chain => {
            (chain.entries || []).forEach((quest: any) => {
                if (completedIds && completedIds.has(String(quest.id))) return;
                totalQuests++;
                
                // Collect Items from structured data
                (quest.itemsRequired || []).forEach((req: any) => {
                    const id = String(req.id);
                    if (items.has(id)) {
                        items.get(id)!.amount += (req.amount || 1);
                        if (req.img && !items.get(id)!.img) items.get(id)!.img = req.img;
                    } else {
                        items.set(id, { id, amount: req.amount || 1, name: req.name || "Objet", img: req.img });
                    }
                });

                // Detect Items from objective text patterns (V3 support)
                const objectives = Array.isArray(quest.objectives) ? quest.objectives : [];
                objectives.forEach((obj: any) => {
                    const text = extractObjectiveText(obj);
                    const regex = /(?:(\d+)\s*(?:[xX]\s*|de\s*)?)?\{item,\s*(\d+)(?:,(\d+))?\}/g;
                    let match;
                    while ((match = regex.exec(text)) !== null) {
                        const amountStr = match[1];
                        const amount = amountStr ? parseInt(amountStr, 10) : 1;
                        const id = match[2];
                        if (items.has(id)) {
                            items.get(id)!.amount += amount;
                        } else {
                            items.set(id, { id, amount, name: "Ressource" });
                        }
                    }
                });
                
                // Read dungeonsRequired directly from compiled data (V3)
                (quest.dungeonsRequired || []).forEach((d: any) => {
                    const key = d.name || `Dungeon-${d.id}`;
                    if (!dungeons.has(key)) {
                        dungeons.set(key, {
                            id: d.bossId ? String(d.bossId) : d.id ? String(d.id) : undefined,
                            name: d.name === "Risquer un œil" ? "Risquer un œil" : d.name,
                            level: d.level,
                            bossName: d.bossName,
                            img: d.img,
                            idoleName: d.idoleName
                        });
                    }
                });
                
                // Fallback: detect dungeons from objective text patterns
                const dungeonInfos = detectRealDungeons(objectives);
                for (const dungeonInfo of dungeonInfos) {
                    if (dungeonInfo.isDungeon && dungeonInfo.dungeonName) {
                        if (!dungeons.has(dungeonInfo.dungeonName)) {
                            dungeons.set(dungeonInfo.dungeonName, { 
                                name: dungeonInfo.dungeonName,
                                id: dungeonInfo.bossId ? String(dungeonInfo.bossId) : undefined,
                                img: dungeonInfo.mapImg
                            });
                        } else if (dungeonInfo.mapImg) {
                            // Merge the image if it wasn't provided by the compiler generated block!
                            const existing = dungeons.get(dungeonInfo.dungeonName)!;
                            if (!existing.img && dungeonInfo.mapImg) {
                                existing.img = dungeonInfo.mapImg;
                            }
                            if (!existing.id && dungeonInfo.bossId) {
                                existing.id = String(dungeonInfo.bossId);
                            }
                        }
                    }
                }
            });
        });

        return {
            items: Array.from(items.values()).sort((a,b) => b.amount - a.amount),
            dungeons: Array.from(dungeons.values()).sort((a,b) => (a.level || 0) - (b.level || 0) || a.name.localeCompare(b.name)),
            totalQuests
        };
    }, [chains]);

    React.useEffect(() => {
        if (!logistics.items.length) {
            setFilteredItems([]);
            setIsLoadingItems(false);
            return;
        }

        let isMounted = true;
        setIsLoadingItems(true);

        filterQuestItemsFromResources(logistics.items)
            .then(filtered => {
                if (isMounted) {
                    setFilteredItems(filtered.length > 0 ? filtered : logistics.items);
                    setIsLoadingItems(false);
                }
            })
            .catch(() => {
                if (isMounted) {
                    setFilteredItems(logistics.items);
                    setIsLoadingItems(false);
                }
            });

        return () => { isMounted = false; };
    }, [logistics.items]);

    if (!chains || chains.length === 0) return null;

    return (
        <div className="w-full relative z-10 isolate mb-12">
            <div 
                onClick={() => setIsExpanded(!isExpanded)}
                className={cn(
                    "w-full p-6 bg-white/[0.03] border border-white/10 rounded-[2.5rem] flex flex-col sm:flex-row items-center justify-between cursor-pointer hover:bg-white/[0.05] transition-all group gap-6",
                    isExpanded && "rounded-b-none border-b-0 bg-white/[0.05]"
                )}
            >
                <div className="flex flex-col sm:flex-row items-center gap-6 sm:gap-8 w-full sm:w-auto">
                    <div className={cn(
                        "w-12 h-12 rounded-2xl flex items-center justify-center border shadow-2xl transition-transform group-hover:scale-110 shrink-0",
                        isExpanded ? "bg-white text-black border-white" : "bg-white/5 border-white/10 text-zinc-500"
                    )}>
                        <Info className="w-6 h-6" />
                    </div>
                    <div className="flex flex-col sm:flex-row items-center sm:items-start gap-4 sm:gap-12 w-full text-center sm:text-left">
                        <div>
                            <div className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.4em] mb-1">RÉCAPITULATIF GLOBAL</div>
                            <div className="text-[18px] font-black text-white italic uppercase tracking-tighter">Logistique du Dofus</div>
                        </div>
                        <div className="flex flex-wrap justify-center sm:justify-start items-center gap-4 sm:gap-8 text-[11px] font-black uppercase tracking-widest text-zinc-500">
                            <div className="flex items-center gap-2"><ScrollText className="w-4 h-4" /> {logistics.totalQuests} Quêtes</div>
                            <div className="flex items-center gap-2"><Package className="w-4 h-4" /> {isLoadingItems ? "..." : filteredItems.length} Ressources</div>
                        </div>
                    </div>
                </div>
                
                <div className={cn(
                    "w-10 h-10 rounded-xl bg-white/5 flex items-center justify-center transition-transform shrink-0",
                    isExpanded && "rotate-180 bg-white/10"
                )}>
                    <ChevronDown className="w-5 h-5 text-white/50" />
                </div>
            </div>

            <AnimatePresence>
                {isExpanded && (
                    <motion.div
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: "auto" }}
                        exit={{ opacity: 0, height: 0 }}
                        transition={{ duration: 0.3, ease: "easeInOut" }}
                        className="overflow-hidden bg-white/[0.02] border border-t-0 border-white/10 rounded-b-[2.5rem]"
                    >
                        <div className="p-8 grid grid-cols-1 lg:grid-cols-12 gap-12">
                            {/* Resources Column */}
                            <div className="lg:col-span-5 space-y-6">
                                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                                    <h4 className="text-[11px] font-black text-zinc-400 uppercase tracking-[0.4em] flex items-center gap-3">
                                        <Package className="w-4 h-4" /> Ressources à prévoir
                                    </h4>
                                    <span className="text-[10px] font-black px-3 py-1 bg-white/5 rounded-full text-zinc-500">{filteredItems.length} TYPES</span>
                                </div>

                                {isLoadingItems ? (
                                    <div className="p-8 border border-dashed border-white/10 rounded-3xl text-center text-zinc-600 italic text-[13px] flex flex-col items-center gap-2">
                                        <div className="w-4 h-4 border-2 border-zinc-600 border-t-white rounded-full animate-spin"></div>
                                        Analyse logistique en cours...
                                    </div>
                                ) : filteredItems.length > 0 ? (
                                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 xl:grid-cols-2 gap-3 max-h-[600px] overflow-y-auto pr-2 custom-scrollbar">
                                        {filteredItems.map((item) => (
                                            <div key={item.id} className="flex items-center gap-3 p-3 bg-white/[0.01] border border-white/5 rounded-2xl hover:border-white/10 hover:bg-white/[0.03] transition-all group">
                                                <div className="w-10 h-10 bg-zinc-950 rounded-xl flex items-center justify-center p-1.5 relative shrink-0 border border-white/5">
                                                    <img 
                                                        src={item.img || `https://static.dofusdb.fr/items/${item.id}.png`} 
                                                        alt="" 
                                                        className="w-full h-full object-contain group-hover:scale-110 transition-transform drop-shadow-[0_0_8px_rgba(245,158,11,0.2)]"
                                                        onError={(e) => (e.currentTarget.style.display = 'none')}
                                                    />
                                                    <div className="absolute -top-1.5 -right-1.5 bg-amber-500 text-black text-[9px] font-black px-1.5 py-0.5 rounded-md shadow-lg border border-white/10">
                                                        x{item.amount}
                                                    </div>
                                                </div>
                                                <div className="flex-1 min-w-0">
                                                    <ResourceNameLink itemId={item.id} fallbackName={item.name} />
                                                    <span className="text-[9px] font-bold text-zinc-600 uppercase tracking-widest block mt-0.5">ID: {item.id}</span>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <div className="p-8 border border-dashed border-white/10 rounded-3xl text-center text-zinc-600 italic text-[13px]">
                                        Aucune ressource spécifique listée.
                                    </div>
                                )}
                            </div>

                            {/* Dungeons Column - REFACTORED TO GRID */}
                            <div className="lg:col-span-7 space-y-6">
                                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                                    <h4 className="text-[11px] font-black text-zinc-400 uppercase tracking-[0.4em] flex items-center gap-3">
                                        <Sword className="w-4 h-4" /> Donjons Requis
                                    </h4>
                                    <span className="text-[10px] font-black px-3 py-1 bg-white/5 rounded-full text-zinc-500">{logistics.dungeons.length} BOSS</span>
                                </div>

                                {logistics.dungeons.length > 0 ? (
                                    <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-3 max-h-[600px] overflow-y-auto pr-2 custom-scrollbar content-start">
                                        {logistics.dungeons.map((d, i) => {
                                            const searchUrl = `https://www.google.com/search?q=site:dofuspourlesnoobs.com+${encodeURIComponent(d.name)}`;
                                            return (
                                                <a 
                                                    key={i} 
                                                    href={searchUrl}
                                                    target="_blank"
                                                    rel="noopener noreferrer"
                                                    className="flex flex-col gap-2 p-3 bg-rose-500/[0.02] border border-rose-500/10 rounded-2xl group hover:border-rose-500/30 hover:bg-rose-500/[0.05] transition-all relative overflow-hidden h-fit cursor-pointer"
                                                >
                                                    {/* Idol Badge */}
                                                    {d.idoleName && (
                                                        <div className="absolute top-0 right-0 px-2 py-0.5 bg-amber-500/20 border-b border-l border-amber-500/30 rounded-bl-lg text-[7px] font-black text-amber-500 uppercase tracking-widest z-10">
                                                            {d.idoleName}
                                                        </div>
                                                    )}
                                                    
                                                    <div className="flex items-center gap-3">
                                                        <div className="w-10 h-10 rounded-xl bg-black/60 border border-white/5 flex items-center justify-center p-1 shrink-0 relative overflow-hidden group-hover:scale-105 transition-transform shadow-inner">
                                                            {(d.id || d.img) ? (
                                                                <img 
                                                                    src={d.img || `https://static.dofusdb.fr/monsters/${d.id}.png`} 
                                                                    className="w-full h-full object-contain relative z-10 drop-shadow-[0_0_8px_rgba(239,68,68,0.2)]" 
                                                                    onError={(e) => (e.currentTarget.style.display = 'none')}
                                                                    alt={d.name}
                                                                />
                                                            ) : (
                                                                <span className="text-rose-500 text-base">🏰</span>
                                                            )}
                                                        </div>
                                                        <div className="flex-1 min-w-0">
                                                            <div className="text-[11px] font-black text-white italic truncate group-hover:text-rose-400 transition-colors uppercase leading-tight">
                                                                {d.name}
                                                            </div>
                                                            <div className="flex flex-wrap items-center gap-x-2 gap-y-0.5 mt-0.5 opacity-50">
                                                                {d.level && d.level > 0 && (
                                                                    <span className="text-[8px] text-zinc-500 font-bold uppercase tracking-wider whitespace-nowrap">Lvl {d.level}</span>
                                                                )}
                                                                {d.bossName && (
                                                                    <span className="text-[8px] text-zinc-600 font-bold italic truncate">— {d.bossName}</span>
                                                                )}
                                                            </div>
                                                        </div>
                                                    </div>
                                                </a>
                                            );
                                        })}
                                    </div>
                                ) : (
                                    <div className="p-8 border border-dashed border-white/10 rounded-3xl text-center text-zinc-600 italic text-[13px]">
                                        Aucun donjon requis.
                                    </div>
                                )}
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

"use client";

import Image from "next/image";
import { useState } from "react";
import { Gem } from "lucide-react";

interface DofusIconProps {
    name: string;
    size?: number;
    color?: string;
    isObtained?: boolean;
    className?: string;
}

export function DofusIcon({ 
    name, 
    size = 64, 
    color = "#6366f1", 
    isObtained = false,
    className = "" 
}: DofusIconProps) {
    const [error, setError] = useState(false);
    
    // 🛠️ ULTIMATE ROBUST FILENAME RESOLUTION
    const normalizeName = (str: string) => {
        const n = str.trim();
        
        // Specific alias mappings based on filesystem audit
        if (n === "Glaces") return "Des_Glaces";
        if (n === "Cauchemar") return "Du_Cauchemar";
        if (n === "Scintillant") return "Argente_Scintillant";
        
        if (n === "Argenté" || n === "Tacheté") return n;
        
        // Strip ALL accents for other Dofus (e.g., Ébène -> Ebene, Émeraude -> Emeraude)
        return n.normalize("NFD")
                .replace(/[\u0300-\u036f]/g, "") // Remove combining diacritics
                .replace(/\s+/g, '_');          // Spaces to underscores
    };

    const localSrc = `/module-dofus/Dofus_${normalizeName(name)}.png`;
    const fallbackSrc = "https://static.dofusdb.fr/items/19000.png";

    if (error) {
        return (
            <Image
                src={fallbackSrc}
                alt={name}
                width={size}
                height={size}
                className={`object-contain ${className}`}
                style={{
                    filter: isObtained
                        ? `drop-shadow(0 0 12px ${color}99)`
                        : `drop-shadow(0 0 6px ${color}44)`,
                }}
            />
        );
    }

    return (
        <Image
            src={localSrc}
            alt={name}
            width={size}
            height={size}
            className={`object-contain ${className}`}
            onError={() => setError(true)}
            style={{
                filter: isObtained
                    ? `drop-shadow(0 0 12px ${color}99)`
                    : `drop-shadow(0 0 6px ${color}44)`,
            }}
        />
    );
}

"use client";

import React, { useState, useEffect, useTransition } from "react";
import { motion } from "framer-motion";
import { Shield, RefreshCw, Unlink, CheckCircle2, Zap, Info, Crown } from "lucide-react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { 
    getMyOcreProgress, 
    unlinkOcreAccount,
    OcreProgressData
} from "@/server/actions/ocre-actions";

interface DofusOcreMetamobProps {
    guildId: string;
    metamobUsername: string | null;
    onLinkMetamob: (pseudo: string) => Promise<any>;
}

export function DofusOcreMetamob({ guildId, metamobUsername, onLinkMetamob }: DofusOcreMetamobProps) {
    const [username, setUsername] = useState<string | null>(metamobUsername);
    const [isPending, startTransition] = React.useTransition();

    async function handleLink(u: string) {
        const res = await onLinkMetamob(u);
        if (res.success) {
            setUsername(u);
            toast.success("Compte Metamob lié !");
        } else {
            throw new Error(res.error ?? "Erreur de liaison");
        }
    }

    async function handleUnlink() {
        if (!confirm("Voulez-vous délier votre compte Metamob ?")) return;
        startTransition(async () => {
            const res = await unlinkOcreAccount({ guildId });
            if (res.success) {
                setUsername(null);
                toast.success("Compte délié");
            }
        });
    }

    return (
        <div className="w-full">
            {username ? (
                <MetamobProgressView 
                    guildId={guildId} 
                    username={username} 
                    onUnlink={handleUnlink} 
                />
            ) : (
                <MetamobLinkPrompt onLink={handleLink} />
            )}
        </div>
    );
}

function MetamobLinkPrompt({ onLink }: { onLink: (username: string) => Promise<void> }) {
    const [username, setUsername] = useState("");
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    return (
        <div className="py-12 flex flex-col items-center text-center gap-6 max-w-sm mx-auto">
            <div className="w-16 h-16 rounded-3xl bg-amber-500/10 border border-amber-500/20 flex items-center justify-center">
                <Crown className="w-8 h-8 text-amber-400" />
            </div>
            <div>
                <h3 className="text-lg font-black text-white italic uppercase tracking-tighter">Lier ton Ocre</h3>
                <p className="text-[12px] text-zinc-500 leading-relaxed mt-1">
                    Connecte ton compte <span className="text-amber-400 font-bold">Metamob</span> pour synchroniser ta progression réelle.
                </p>
            </div>
            <form onSubmit={async (e) => {
                e.preventDefault();
                setLoading(true);
                setError(null);
                try { await onLink(username); }
                catch (err: any) { setError(err.message); }
                finally { setLoading(false); }
            }} className="w-full space-y-3">
                <input
                    type="text"
                    value={username}
                    onChange={e => setUsername(e.target.value)}
                    placeholder="Pseudo Metamob"
                    className="w-full h-11 bg-zinc-950/80 border border-white/10 rounded-2xl px-4 text-white text-sm font-bold focus:border-amber-500/40 outline-none transition-colors"
                />
                <Button disabled={loading || !username} className="w-full h-11 bg-amber-500 text-black font-black uppercase tracking-widest rounded-2xl">
                    {loading ? "Liaison..." : "Lier mon compte"}
                </Button>
                {error && <div className="text-rose-400 text-[10px] uppercase font-bold">{error}</div>}
            </form>
        </div>
    );
}

function MetamobProgressView({ guildId, username, onUnlink }: { guildId: string; username: string; onUnlink: () => void }) {
    const [data, setData] = useState<OcreProgressData | null>(null);
    const [loading, setLoading] = useState(true);

    async function refresh() {
        setLoading(true);
        const res = await getMyOcreProgress(guildId);
        if (res.success && res.data) setData(res.data);
        setLoading(false);
    }

    useEffect(() => { refresh(); }, [guildId]);

    const StatItem = ({ label, current, total, color }: { label: string; current: number; total: number; color: string }) => {
        const pct = total > 0 ? Math.min(100, Math.round((current / total) * 100)) : 0;
        return (
            <div className="space-y-2">
                <div className="flex justify-between text-[10px] font-black uppercase tracking-widest">
                    <span className="text-zinc-500">{label}</span>
                    <span className="text-white">{current} / {total}</span>
                </div>
                <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
                    <motion.div 
                        initial={{ width: 0 }} 
                        animate={{ width: `${pct}%` }} 
                        className={`h-full rounded-full transition-all duration-500 ${color}`}
                    />
                </div>
            </div>
        );
    };

    if (loading && !data) return (
        <div className="py-12 flex flex-col items-center gap-3 opacity-50">
            <RefreshCw className="w-5 h-5 animate-spin text-amber-500" />
            <span className="text-[10px] font-black uppercase tracking-widest">Metamob Sync...</span>
        </div>
    );

    return (
        <div className="p-1 space-y-8 animate-in fade-in slide-in-from-top-4 duration-700">
            <div className="flex items-center justify-between gap-4 p-4 bg-zinc-950/40 border border-white/5 rounded-3xl backdrop-blur-md">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-2xl bg-amber-500/10 border border-amber-500/20 flex items-center justify-center">
                        <Shield className="w-5 h-5 text-amber-400" />
                    </div>
                </div>
                <div className="flex-1 min-w-0">
                    <div className="text-[9px] font-black text-amber-500/60 uppercase tracking-widest">Metamob Live</div>
                    <div className="flex items-center gap-2">
                        <div className="text-sm font-black text-white italic truncate">{username}</div>
                        <a 
                            href={`/dashboard/${guildId}/quete-ocre`} 
                            className="p-1 rounded-lg bg-white/5 border border-white/10 hover:bg-white/10 transition-colors"
                        >
                            <Crown className="w-3 h-3 text-amber-400" />
                        </a>
                    </div>
                </div>
                <div className="flex items-center gap-2">
                    <Button variant="ghost" size="icon" onClick={refresh} disabled={loading} className="w-8 h-8 rounded-xl text-zinc-500 hover:text-white">
                        <RefreshCw className={`w-3.5 h-3.5 ${loading ? "animate-spin" : ""}`} />
                    </Button>
                    <Button variant="ghost" size="sm" onClick={onUnlink} className="h-8 px-3 text-[9px] font-black uppercase text-zinc-700 hover:text-rose-400 rounded-xl">
                        <Unlink className="w-3 h-3" />
                    </Button>
                </div>
            </div>

            {data && (
                <div className="grid sm:grid-cols-3 gap-6 px-2">
                    <StatItem label="Étapes Quête" current={data.questInfo.currentStep} total={34} color="bg-amber-500" />
                    <StatItem label="Gardiens" current={data.stats.bosses.gathered} total={data.stats.bosses.total} color="bg-blue-500" />
                    <StatItem label="Archimonstres" current={data.stats.archis.gathered} total={data.stats.archis.total} color="bg-emerald-500" />
                </div>
            )}

            {data && data.stats.bosses.gathered < data.stats.bosses.total && (
                <div className="space-y-4 px-2">
                    <div className="flex items-center gap-2 text-[10px] font-black text-zinc-500 uppercase tracking-widest">
                        <Zap className="w-3 h-3 text-amber-400" /> Prochaines cibles (Boss)
                    </div>
                    <div className="grid grid-cols-3 sm:grid-cols-5 gap-3">
                        {data.monsters
                            .filter(m => m.type === "boss" && m.state === "MANQUANT")
                            .slice(0, 5)
                            .map(m => (
                                <div key={m.id} className="group relative flex flex-col items-center gap-2 p-3 bg-white/[0.02] border border-white/5 rounded-2xl hover:bg-white/[0.05] transition-all">
                                    <div className="relative w-12 h-12 grayscale opacity-40 group-hover:grayscale-0 group-hover:opacity-100 transition-all">
                                        <img 
                                            src={`https://www.metamob.fr/images/monstres/${m.id}.png`} 
                                            alt={m.name} 
                                            className="w-full h-full object-contain"
                                            onError={(e) => { 
                                                (e.target as HTMLImageElement).src = `https://static.dofusdb.fr/monsters/${m.id}.png`; 
                                            }}
                                        />
                                    </div>
                                    <div className="text-[8px] font-black text-zinc-600 text-center uppercase truncate w-full">{m.name}</div>
                                </div>
                            ))
                        }
                    </div>
                </div>
            )}

            <div className="flex items-start gap-2 p-3 bg-blue-500/5 rounded-2xl border border-blue-500/10">
                <Info className="w-3.5 h-3.5 text-blue-400 shrink-0 mt-0.5" />
                <p className="text-[10px] text-zinc-600 italic leading-relaxed">
                    Données synchronisées avec Metamob. Mets à jour tes captures sur le site pour voir ta progression ici.
                </p>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useMemo, useCallback } from "react";
import { useSearchParams, useRouter, usePathname } from "next/navigation";
import { Gem, Users, Search, Sparkles, RefreshCw, CheckCircle2, BookOpen, ChevronLeft, ArrowRight, X, Navigation, Trophy, Construction, Zap, TreePine } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import Link from "next/link";
import { DofusGemCard } from "./DofusGemCard";
import { GuildDofusOverview } from "./GuildDofusOverview";
import { OptimizedGuideTab } from "./OptimizedGuideTab";
import { getMemberAllGuidesProgress } from "@/server/actions/optimized-guide-actions";
import { toast } from "sonner";
import type { DofusItemWithProgress, GuildDofusStats, MemberDofusSummary } from "@/server/actions/dofus-quest-actions";

type Tab = "menu" | "dofus" | "guide" | "guilde";

interface DofusQuestHubProps {
    dofusList: DofusItemWithProgress[];
    guildStats: { stats: GuildDofusStats[]; topMembers: MemberDofusSummary[]; totalMembers: number } | null;
    guides?: any[];
    timelineGuides?: any[];
    rushSylvestreGuide?: { isUnderConstruction?: boolean } | null;
    guildId: string;
    selectedCharacter?: string;
    userProfile?: {
        metamobPseudo: string | null;
        metamobVerified: boolean;
        metamobLastSync: string | null;
        metamobQuestSlug: string | null;
    } | null;
    selectedGuideSlug?: string | null;
    selectedGuideDetail?: any | null;
    selectedGuideUserProgress?: any[] | null;
    selectedGuideGuildProgress?: any[] | null;
}

export function DofusQuestHub({
    dofusList,
    guildStats,
    guides = [],
    timelineGuides = [],
    rushSylvestreGuide = null,
    guildId,
    selectedCharacter = "PRINCIPAL",
    userProfile,
    selectedGuideSlug,
    selectedGuideDetail,
    selectedGuideUserProgress,
    selectedGuideGuildProgress
}: DofusQuestHubProps) {
    const searchParams = useSearchParams();
    const router = useRouter();
    const pathname = usePathname();

    const [activeTab, setActiveTab] = useState<Tab>((searchParams.get("tab") as Tab) || "menu");
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState<"Tous" | "Obtenus" | "En cours" | "À faire">("Tous");
    const [selectedMember, setSelectedMember] = useState<{ profileId: string; pseudo: string; avatarUrl?: string } | null>(null);
    const [memberGuideProgress, setMemberGuideProgress] = useState<any[]>([]);
    const [isMemberLoading, setIsMemberLoading] = useState(false);

    const handleTabChange = (tab: Tab) => {
        setActiveTab(tab);
        const params = new URLSearchParams(searchParams.toString());
        if (tab === "menu") {
            params.delete("tab");
        } else {
            params.set("tab", tab);
        }
        router.push(`${pathname}?${params.toString()}`, { scroll: false });
    };

    const handleMemberClick = useCallback(async (profileId: string, pseudo: string, avatarUrl?: string) => {
        setSelectedMember({ profileId, pseudo, avatarUrl });
        setMemberGuideProgress([]);
        setIsMemberLoading(true);
        try {
            const res = await getMemberAllGuidesProgress(profileId, guildId);
            if (res.success) setMemberGuideProgress(res.guideProgress ?? []);
        } catch (e) {
            console.error("[handleMemberClick] error:", e);
        } finally {
            setIsMemberLoading(false);
        }
    }, [guildId]);

    useEffect(() => {
        const tab = searchParams.get("tab") as Tab;
        if (tab && tab !== activeTab) {
            setActiveTab(tab);
        } else if (!tab) {
            setActiveTab("menu");
        }
    }, [searchParams]);

    const normalDofusList = dofusList.filter(d => !d.isMeta);
    const totalObtained = dofusList.filter((d) => d.isObtained).length;
    const totalNormalDofus = normalDofusList.length;
    const obtainedNormalDofus = normalDofusList.filter(d => d.isObtained).length;
    const overallPercent = dofusList.length > 0
        ? Math.round(dofusList.reduce((sum, d) => sum + d.progressPercent, 0) / dofusList.length)
        : 0;

    const filtered = dofusList
        .filter((d) => {
            if (search) return d.name.toLowerCase().includes(search.toLowerCase()) || d.nameShort.toLowerCase().includes(search.toLowerCase());
            return true;
        })
        .filter((d) => {
            switch (statusFilter) {
                case "Obtenus": return d.isObtained;
                case "En cours": return !d.isObtained && d.progressPercent > 0;
                case "À faire": return !d.isObtained && d.progressPercent === 0;
                default: return true;
            }
        });

    const membersGuideProgress = useMemo(() => {
        if (!selectedGuideDetail?.milestones || !selectedGuideGuildProgress) return [];
        const totalMilestones = selectedGuideDetail.milestones.length;
        if (totalMilestones === 0) return [];

        const progressByProfile: Record<string, { profileId: string; userName: string; userAvatar?: string; completedCount: number; completedMilestoneIds: Set<string> }> = {};
        selectedGuideGuildProgress.forEach((p: any) => {
            if (!progressByProfile[p.profileId]) {
                progressByProfile[p.profileId] = { profileId: p.profileId, userName: p.userName, userAvatar: p.userAvatar, completedCount: 0, completedMilestoneIds: new Set() };
            }
            if (p.isCompleted) {
                progressByProfile[p.profileId].completedCount++;
                progressByProfile[p.profileId].completedMilestoneIds.add(p.milestoneId);
            }
        });

        return Object.values(progressByProfile).map(member => {
            const percent = Math.round((member.completedCount / totalMilestones) * 100);
            const activeMilestone = selectedGuideDetail.milestones.find((m: any) => !member.completedMilestoneIds.has(m.id));
            return { ...member, percent, activeMilestone: activeMilestone ? { id: activeMilestone.id, title: activeMilestone.title } : null };
        }).sort((a, b) => b.completedCount - a.completedCount);
    }, [selectedGuideDetail, selectedGuideGuildProgress]);

    const guideColor = useMemo(() => {
        if (!selectedGuideDetail?.slug) return "#6366f1";
        return dofusList.find(d => d.slug === selectedGuideDetail.slug)?.color || "#6366f1";
    }, [selectedGuideDetail, dofusList]);

    return (
        <div className="flex flex-col gap-8">

            {/* ── BOUTON RETOUR (hors menu) ── */}
            {activeTab !== "menu" && (
                <button
                    onClick={() => handleTabChange("menu")}
                    className="flex items-center gap-2 text-xs font-black uppercase tracking-widest text-zinc-500 hover:text-white transition-colors self-start group"
                >
                    <ChevronLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
                    Retour au menu
                </button>
            )}

            {/* ── CONTENU PAR TAB ── */}
            <div className="relative min-h-[500px]">
                <AnimatePresence mode="wait">
                    <motion.div
                        key={activeTab}
                        initial={{ opacity: 0, y: 15 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -15 }}
                        transition={{ duration: 0.35, ease: [0.23, 1, 0.32, 1] }}
                    >

                        {/* ══ VUE MENU — grille 2×2 ══ */}
                        {activeTab === "menu" && (
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">

                                {/* CARD 1 : Rush Sylvestre — toujours visible, hard-codé */}
                                <Link
                                    href={`/dashboard/${guildId}/quetes-dofus/guide/rush-sylvestre`}
                                    className="group relative flex flex-col justify-between p-6 min-h-[320px] bg-gradient-to-br from-zinc-950 via-emerald-950/15 to-zinc-950 border border-emerald-500/25 hover:border-emerald-500/50 rounded-3xl shadow-2xl transition-all duration-300 no-underline"
                                    style={{ textDecoration: 'none' }}
                                >
                                    <div className="absolute top-0 right-0 w-40 h-40 bg-emerald-500/6 blur-[60px] pointer-events-none rounded-full" />
                                    {/* Dofus Sylvestre watermark */}
                                    <div className="absolute bottom-0 right-0 w-32 h-32 pointer-events-none opacity-[0.08] group-hover:opacity-[0.14] transition-opacity">
                                        {/* eslint-disable-next-line @next/next/no-img-element */}
                                        <img src="/module-dofus/Dofus_Sylvestre.png" alt="" className="w-full h-full object-contain" />
                                    </div>
                                    {rushSylvestreGuide?.isUnderConstruction && (
                                        <div className="absolute top-3 right-3 flex items-center gap-1 px-2 py-1 rounded-full bg-amber-500/15 border border-amber-500/25 text-[9px] font-black text-amber-400 uppercase tracking-widest z-10">
                                            <Construction className="w-2.5 h-2.5" /> En construction
                                        </div>
                                    )}
                                    <div className="space-y-4">
                                        <div className="p-2 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 w-fit group-hover:scale-110 transition-transform duration-500">
                                            {/* eslint-disable-next-line @next/next/no-img-element */}
                                            <img src="/module-dofus/Dofus_Sylvestre.png" alt="Dofus Sylvestre" className="w-10 h-10 object-contain drop-shadow-[0_0_10px_rgba(16,185,129,0.6)]" />
                                        </div>
                                        <div>
                                            <div className="flex items-center gap-2 mb-1">
                                                <h3 className="text-lg font-black text-white italic uppercase tracking-wider">
                                                    Rush Sylvestre
                                                </h3>
                                                <span className="text-[8px] font-black px-1.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-400 border border-emerald-500/20 uppercase tracking-widest">NEW</span>
                                            </div>
                                            <p className="text-xs font-semibold text-zinc-400 leading-relaxed">
                                                Rush Sylvestre communautaire — suis ta progression étape par étape et coordonne-toi avec ta guilde.
                                            </p>
                                        </div>
                                    </div>
                                    <div className="space-y-3 pt-6 border-t border-white/5">
                                        <div className="flex items-center justify-between text-xs font-bold">
                                            <span className="text-zinc-500">Mode :</span>
                                            <span className="text-emerald-400 font-black italic">Collaboratif</span>
                                        </div>
                                        <div className="flex items-center gap-1 text-[10px] font-black uppercase tracking-widest text-emerald-400 pt-2">
                                            Démarrer le Rush <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-1.5 transition-transform" />
                                        </div>
                                    </div>
                                </Link>

                                {/* CARD 2 : Guides Optimisés */}
                                <motion.div
                                    whileHover={{ scale: 1.02, translateY: -4 }}
                                    onClick={() => handleTabChange("guide")}
                                    className="group relative flex flex-col justify-between p-6 min-h-[320px] bg-gradient-to-br from-zinc-950 via-indigo-950/20 to-zinc-950 border border-indigo-500/20 hover:border-indigo-500/40 rounded-3xl cursor-pointer shadow-2xl transition-all duration-300"
                                >
                                    <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/5 blur-[50px] pointer-events-none rounded-full" />
                                    {/* Ganymède watermark */}
                                    <div className="absolute bottom-4 right-4 w-24 h-24 pointer-events-none opacity-[0.07] group-hover:opacity-[0.12] transition-opacity">
                                        {/* eslint-disable-next-line @next/next/no-img-element */}
                                        <img src="/assets/icons/ganymede.webp" alt="" className="w-full h-full object-contain" />
                                    </div>
                                    <div className="space-y-4">
                                        <div className="p-2 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 w-fit group-hover:scale-110 transition-transform duration-500">
                                            {/* eslint-disable-next-line @next/next/no-img-element */}
                                            <img src="/assets/icons/ganymede.webp" alt="Ganymède" className="w-10 h-10 object-contain drop-shadow-[0_0_8px_rgba(99,102,241,0.5)]" />
                                        </div>
                                        <div>
                                            <h3 className="text-lg font-black text-white italic uppercase tracking-wider mb-1">
                                                Guides Optimisés
                                            </h3>
                                            <p className="text-xs font-semibold text-zinc-400 leading-relaxed">
                                                Suis le chemin le plus rapide rédigé par ganymède pour obtenir tes Dofus.
                                            </p>
