"use client";

import React, { useState, useEffect } from "react";
import { Navigation, ChevronRight, Check, CheckCircle2, Circle, Sparkles, Users, Calendar, MapPin, Sword, Package, Info } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { getOptimizedGuideDetail, getGuildOptimizedGuideProgress } from "@/server/actions/optimized-guide-actions";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { useSession } from "next-auth/react";

interface OptimizedGuideTabProps {
    initialGuides: any[];
    guildId: string;
}

export function OptimizedGuideTab({ initialGuides, guildId }: OptimizedGuideTabProps) {
    const { data: session } = useSession();
    const router = useRouter();
    const [selectedGuideSlug, setSelectedGuideSlug] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [guideData, setGuideData] = useState<any>(null);
    const [questsDetail, setQuestsDetail] = useState<any[]>([]);
    const [memberProgress, setMemberProgress] = useState<any[]>([]);
    const [selectedStepIndex, setSelectedStepIndex] = useState(0);

    // Filtrer le guide rush-sylvestre qui a déjà sa carte dédiée dans le hub principal
    const filteredGuides = React.useMemo(() => {
        return (initialGuides || []).filter(g => g.slug !== "rush-sylvestre");
    }, [initialGuides]);

    const [redirecting, setRedirecting] = useState(filteredGuides && filteredGuides.length === 1);

    useEffect(() => {
        if (filteredGuides && filteredGuides.length === 1) {
            router.replace(`/dashboard/${guildId}/quetes-dofus/guide/${filteredGuides[0].slug}`);
        } else {
            setRedirecting(false);
        }
    }, [filteredGuides, guildId, router]);

    const handleSelectGuide = (slug: string) => {
        router.push(`/dashboard/${guildId}/quetes-dofus/guide/${slug}`);
    };

    if (redirecting) {
        return (
            <div className="flex flex-col items-center justify-center py-24 gap-4 animate-pulse">
                <div className="w-12 h-12 rounded-full border-4 border-emerald-500/20 border-t-emerald-500 animate-spin" />
                <p className="text-sm font-bold text-zinc-400 uppercase tracking-widest">Chargement de votre feuille de route...</p>
            </div>
        );
    }

    // Helper to get quest info
    const getQuestInfo = (id: string) => questsDetail.find(q => q.id === id);

    // Determines if a step is completed for the current user
    const isStepCompleted = (step: any) => {
        const objectives = step.objectives as any[] || [];
        const questIds = step.questIds || [];
        
        // Check quests
        const allQuestIds = [...new Set([...questIds, ...objectives.filter(o => o.type === 'QUEST').map(o => o.id)])];
        if (allQuestIds.length === 0) return true;

        return allQuestIds.every(qid => {
            const q = getQuestInfo(qid);
            return q?.playerProgress?.length > 0 && q.playerProgress[0].status === "COMPLETED";
        });
    };

    if (selectedGuideSlug && guideData && guideData.steps) {
        // --- DETAIL VIEW (Legacy fallback) ---
        const totalSteps = guideData.steps?.length || 0;
        const completedSteps = guideData.steps?.filter((s: any) => isStepCompleted(s)).length || 0;
        const progressPercent = totalSteps > 0 ? (completedSteps / totalSteps) * 100 : 0;

        return (
            <div className="flex flex-col gap-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
                {/* Header / Back */}
                <div className="flex items-center justify-between">
                    <button 
                        onClick={() => setSelectedGuideSlug(null)}
                        className="flex items-center gap-2 text-zinc-500 hover:text-white transition-colors group"
                    >
                        <div className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center group-hover:bg-white/10">
                             <ChevronRight className="w-4 h-4 rotate-180" />
                        </div>
                        <span className="text-sm font-bold uppercase tracking-widest">Retour aux guides</span>
                    </button>

                    <div className="flex items-center gap-4">
                        <div className="hidden md:flex flex-col items-end">
                            <span className="text-[10px] font-black uppercase text-zinc-500 tracking-tighter">Votre progression</span>
                            <span className="text-sm font-bold text-emerald-400">{completedSteps} / {totalSteps} Étapes</span>
                        </div>
                        <div className="w-32 h-2 bg-zinc-800 rounded-full overflow-hidden">
                            <motion.div 
                                initial={{ width: 0 }}
                                animate={{ width: `${progressPercent}%` }}
                                className="h-full bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)]"
                            />
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
                    
                    {/* Left: The Roadmap (4 columns) */}
                    <div className="lg:col-span-5 space-y-6">
                        <div className="bg-zinc-900/50 border border-white/5 rounded-3xl p-6 relative overflow-hidden">
                             <div className="absolute top-0 right-0 p-8 opacity-5">
                                <Navigation className="w-32 h-32 rotate-12" />
                             </div>

                             <h2 className="text-3xl font-black text-white mb-2">{guideData.name}</h2>
                             <p className="text-zinc-500 text-sm leading-relaxed mb-8">{guideData.description || "Suivez cet itinéraire pour optimiser votre progression."}</p>

                             <div className="relative pl-8 space-y-12 pb-4">
                                {/* Vertical Line */}
                                <div className="absolute top-2 bottom-2 left-3 w-0.5 bg-zinc-800">
                                     <motion.div 
                                        initial={{ height: 0 }}
                                        animate={{ height: `${progressPercent}%` }}
                                        className="w-full bg-emerald-500"
                                     />
                                </div>

                                {guideData.steps.map((step: any, idx: number) => {
                                    const isDone = isStepCompleted(step);
                                    const active = selectedStepIndex === idx;
                                    const membersHere = memberProgress.filter(mp => mp.currentStepIndex === idx && !mp.isFinished);

                                    return (
                                        <div 
                                            key={step.id} 
                                            onClick={() => setSelectedStepIndex(idx)}
                                            className={`relative z-10 flex items-start gap-6 cursor-pointer group transition-all duration-300 ${active ? 'scale-105' : 'opacity-60 hover:opacity-100'}`}
                                        >
                                            {/* Node */}
                                            <div className={`w-6 h-6 rounded-full flex items-center justify-center transition-all duration-500 border-2 
                                                ${isDone ? 'bg-emerald-500 border-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.4)]' : 'bg-zinc-900 border-zinc-700 group-hover:border-zinc-500'}
                                                ${active && !isDone ? 'ring-4 ring-emerald-500/20 border-emerald-500' : ''}`}>
                                                {isDone ? <Check className="w-3 h-3 text-emerald-950 font-black" /> : null}
                                            </div>

                                            <div className="flex-1">
                                                <div className="flex items-center gap-2">
                                                    <span className={`text-xs font-black uppercase tracking-widest ${isDone ? 'text-emerald-500' : 'text-zinc-500'}`}>Étape {idx + 1}</span>
                                                    {membersHere.length > 0 && (
                                                        <div className="flex -space-x-2 ml-2">
                                                            {membersHere.slice(0, 3).map((mp, i) => (
                                                                <Avatar key={mp.profile.id} className="w-5 h-5 border border-zinc-900 shadow-md">
                                                                    <AvatarImage src={mp.profile.user?.image} />
                                                                    <AvatarFallback>{mp.profile.user?.name?.[0]}</AvatarFallback>
                                                                </Avatar>
                                                            ))}
                                                            {membersHere.length > 3 && (
                                                                <div className="w-5 h-5 rounded-full bg-zinc-800 text-[8px] font-bold flex items-center justify-center border border-zinc-900 text-white">+{membersHere.length - 3}</div>
                                                            )}
                                                        </div>
                                                    )}
                                                </div>
                                                <h3 className={`font-bold transition-colors ${active ? 'text-white' : 'text-zinc-300'}`}>{step.title}</h3>
                                            </div>
                                        </div>
                                    );
                                })}
                             </div>
                        </div>
                    </div>

                    {/* Right: Step Detail (7 columns) */}
                    <div className="lg:col-span-7">
                        <AnimatePresence mode="wait">
                            <motion.div 
                                key={selectedStepIndex}
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: -20 }}
                                className="bg-gradient-to-br from-zinc-900 to-black border border-white/10 rounded-[2rem] p-8 shadow-2xl relative overflow-hidden min-h-[500px]"
                            >
                                <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
                                    <Sparkles className="w-64 h-64 text-emerald-500" />
                                </div>

                                {guideData.steps[selectedStepIndex] ? (
                                    <div className="relative z-10 space-y-8">
                                        <div>
                                            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-emerald-500/10 border border-emerald-500/20 text-[10px] font-black text-emerald-400 uppercase tracking-[0.2em] mb-4">
                                                Détails de l'objectif
                                            </div>
                                            <h3 className="text-4xl font-black text-white leading-tight mb-4">{guideData.steps[selectedStepIndex].title}</h3>
                                            <p className="text-zinc-400 leading-relaxed text-lg">{guideData.steps[selectedStepIndex].description || "Terminez les objectifs suivants pour passer à l'étape suivante."}</p>
                                        </div>

                                        <div className="space-y-4">
                                            {/* Merged Objectives List */}
                                            {(() => {
                                                const step = guideData.steps[selectedStepIndex];
                                                const objectives = step.objectives as any[] || [];
                                                // Handle legacy questIds if not migrated yet
                                                const legacyQuests = (step.questIds || []).filter((id:string) => !objectives.find(o => o.id === id)).map((id:string) => ({ id, type: 'QUEST' }));
                                                const items = [...objectives, ...legacyQuests];

                                                if (items.length === 0) return (
                                                    <div className="py-12 border-2 border-dashed border-white/5 rounded-3xl flex flex-col items-center justify-center text-zinc-600 italic">
                                                        Aucun objectif spécifique pour cette étape.
                                                    </div>
                                                );

                                                return items.map((obj, i) => {
                                                    const isQuest = obj.type === 'QUEST';
                                                    const isDungeon = obj.type === 'DUNGEON';
                                                    const isResource = obj.type === 'RESOURCE';
                                                    
                                                    let name = obj.name;
                                                    let isDone = false;
                                                    let subtitle = "";
                                                    let img = obj.imageUrl;

                                                    if (isQuest) {
                                                        const info = getQuestInfo(obj.id);
                                                        name = info?.name || obj.name || "Quête inconnue";
                                                        isDone = info?.playerProgress?.[0]?.status === "COMPLETED";
                                                        subtitle = info?.chain?.dofus?.name || "Catégorie Quête";
                                                        img = img || info?.chain?.dofus?.localImageUrl || info?.chain?.dofus?.imageUrl;
                                                    } else {
                                                        // Manual completion for others for now, unless we check boss kills later
                                                        subtitle = obj.type === 'DUNGEON' ? 'Donjon' : obj.type === 'RESOURCE' ? `Ressource (${obj.quantity || 1}x)` : 'Objectif';
                                                    }

                                                    return (
                                                        <div 
                                                            key={i} 
                                                            className={`group p-5 rounded-2xl border transition-all flex items-center justify-between ${isDone ? 'bg-emerald-500/10 border-emerald-500/30' : 'bg-black/40 border-white/5 hover:border-white/20'}`}
                                                        >
                                                            <div className="flex items-center gap-4">
                                                                <div className={`w-12 h-12 rounded-xl flex items-center justify-center flex-shrink-0 border ${isDone ? 'bg-emerald-500/20 border-emerald-500/30' : 'bg-zinc-800/50 border-white/5'}`}>
                                                                    {img ? (
                                                                        <img src={img} alt="" className="w-8 h-8 object-contain" />
                                                                    ) : (
                                                                        isDungeon ? <Sword className="w-6 h-6 text-indigo-400" /> : <Package className="w-6 h-6 text-amber-400" />
                                                                    )}
                                                                </div>
                                                                <div>
                                                                    <div className={`text-[10px] uppercase font-black tracking-widest ${isDone ? 'text-emerald-500' : 'text-zinc-500'}`}>{subtitle}</div>
                                                                    <div className={`font-bold text-lg ${isDone ? 'text-emerald-400' : 'text-zinc-200'}`}>{name}</div>
                                                                </div>
                                                            </div>

                                                            <div className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${isDone ? 'bg-emerald-500 text-emerald-950' : 'bg-white/5 text-zinc-600'}`}>
                                                                {isDone ? <CheckCircle2 className="w-6 h-6" /> : <Circle className="w-6 h-6 opacity-40" />}
                                                            </div>
                                                        </div>
                                                    );
                                                });
                                            })()}
                                        </div>
                                    </div>
                                ) : (
                                    <div className="flex items-center justify-center h-full text-zinc-500">Sélectionnez une étape pour voir les détails.</div>
                                )}
                            </motion.div>
                        </AnimatePresence>
                    </div>

                </div>
            </div>
        );
    }

    // --- LIST VIEW ---
    return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
            {filteredGuides.map((guide) => (
                <div 
                    key={guide.id} 
                    onClick={() => handleSelectGuide(guide.slug)}
                    className="group relative bg-zinc-900 border border-white/5 rounded-[2.5rem] p-8 cursor-pointer hover:border-emerald-500/30 transition-all duration-500 hover:shadow-[0_20px_50px_rgba(0,0,0,0.5)] overflow-hidden"
                >
                    {/* Background Glow */}
                    <div className="absolute -top-24 -right-24 w-48 h-48 bg-emerald-500/10 blur-[80px] group-hover:bg-emerald-500/20 transition-all" />
                    
                    <div className="relative z-10 flex flex-col h-full">
                        <div className="w-14 h-14 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                             <Navigation className="w-8 h-8 text-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.5)]" />
                        </div>

                        <h3 className="text-2xl font-black text-white mb-2 group-hover:text-emerald-400 transition-colors uppercase tracking-tight">
                            {guide.name}
                        </h3>
                        <p className="text-zinc-500 text-sm line-clamp-2 mb-8 h-10">
                            {guide.description || "Un itinéraire complet et optimisé pour atteindre vos objectifs."}
                        </p>

                        <div className="mt-auto flex items-center justify-between">
                            <div className="flex items-center gap-4">
                                <div className="flex flex-col">
                                    <span className="text-[10px] font-black text-zinc-600 uppercase tracking-widest leading-none mb-1">Étapes</span>
                                    <span className="text-lg font-black text-white">{guide.steps?.length || 0}</span>
                                </div>
                                <div className="w-[1px] h-8 bg-white/5" />
                                <div className="flex flex-col">
                                    <span className="text-[10px] font-black text-zinc-600 uppercase tracking-widest leading-none mb-1">Type</span>
                                    <span className="text-lg font-black text-white">Route Opti</span>
                                </div>
                            </div>

                            <div className="w-12 h-12 rounded-full border border-white/10 flex items-center justify-center group-hover:bg-white/10 transition-all group-hover:translate-x-1">
                                <ChevronRight className="w-6 h-6 text-zinc-400" />
                            </div>
                        </div>
                    </div>
                </div>
            ))}

            {filteredGuides.length === 0 && (
                <div className="col-span-full py-20 bg-white/5 border border-dashed border-white/10 rounded-[3rem] text-center flex flex-col items-center justify-center">
                    <Navigation className="w-12 h-12 text-zinc-600 mb-4 opacity-20" />
                    <h3 className="text-xl font-bold text-white/50">Aucun guide configuré</h3>
                    <p className="text-zinc-600 text-sm max-w-xs">Les administrateurs n'ont pas encore publié de routes optimisées.</p>
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useState, useEffect } from "react";
import { 
    Target, 
    BookOpen, 
    Navigation, 
    Users, 
    Copy,
    Search,
    ShieldAlert,
    Check,
    Lock
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { ScrollArea } from "@/components/ui/scroll-area";
import { copyWithToast } from "./dofus-resolvers";
import type { MemberOnQuest } from "@/server/actions/dofus-quest-actions";
import { getOtherMembersOnQuest } from "@/server/actions/dofus-quest-actions";
import Link from "next/link";

interface QuestActionsBlockProps {
    entry: {
        id: string;
        dofusdbId?: number | null;
        name: string;
        externalRef?: string | null;
        coords?: { x: number; y: number; worldId?: number } | null;
    };
    guildId: string;
    dofusColor: string;
    initialMembers?: MemberOnQuest[];
    lock: boolean;
    done: boolean;
    onToggle: () => void;
}

export function QuestActionsBlock({
    entry,
    guildId,
    dofusColor,
    initialMembers = [],
    lock,
    done,
    onToggle
}: QuestActionsBlockProps) {
    const [members, setMembers] = useState<MemberOnQuest[]>(initialMembers);
    const [loadingMembers, setLoadingMembers] = useState(false);
    const [isModalOpen, setIsModalOpen] = useState(false);

    // Dynamic icon URL fetcher
    const dofusDbFavicon = "https://dofusdb.fr/favicon.ico";
    const noobsFavicon = "https://www.dofuspourlesnoobs.com/favicon.ico";
    const dofusbookFavicon = "https://www.dofusbook.net/favicon.ico";

    useEffect(() => {
        if (initialMembers.length > 0) {
            setMembers(initialMembers);
        } else {
            // Lazy load members if none provided initially
            setLoadingMembers(true);
            getOtherMembersOnQuest(guildId, entry.id).then((res) => {
                if (res.success && res.data) {
                    setMembers(res.data);
                }
                setLoadingMembers(false);
            });
        }
    }, [guildId, entry.id, initialMembers]);

    // Triggers the modal view
    const openGuildModal = (e: React.MouseEvent) => {
        e.stopPropagation();
        setIsModalOpen(true);
    };

    const copyTravelCoords = (e: React.MouseEvent) => {
        e.stopPropagation();
        if (entry.coords) {
            copyWithToast(`/travel ${entry.coords.x} ${entry.coords.y}`);
        }
    };

    return (
        <div className="pt-4 border-t border-white/5 space-y-4">
            <div className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.2em] italic mb-1">
                Panneau Tactique & Synergies
            </div>

            {/* 4-Column Navigation Deck */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                {/* 1. DofusDB */}
                <a
                    href={`https://dofusdb.fr/fr/database/quest/${entry.dofusdbId || entry.id}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="relative group overflow-hidden rounded-2xl border border-indigo-500/20 bg-[#0d0e15]/60 p-4 hover:border-indigo-500/40 hover:bg-[#10121d]/80 hover:shadow-[0_0_20px_rgba(99,102,241,0.15)] transition-all duration-300 flex flex-col justify-between min-h-[110px]"
                    onClick={(e) => e.stopPropagation()}
                >
                    <div className="flex justify-between items-start">
                        {/* eslint-disable-next-line @next/next/no-img-element */}
                        <img 
                            src={dofusDbFavicon} 
                            alt="DofusDB" 
                            className="w-5 h-5 object-contain rounded-md filter drop-shadow-[0_0_4px_rgba(99,102,241,0.5)] group-hover:scale-110 transition-transform" 
                            onError={(e) => { e.currentTarget.style.display = "none"; }} 
                        />
                        <span className="text-[8px] font-black uppercase tracking-wider text-indigo-400/90 bg-indigo-500/10 px-1.5 py-0.5 rounded border border-indigo-500/20">
                            Base
                        </span>
                    </div>
                    <div>
                        <h4 className="text-xs font-black text-white italic tracking-tight mt-3 group-hover:text-indigo-400 transition-colors">
                            DofusDB
                        </h4>
                        <p className="text-[9px] text-zinc-500 mt-1 line-clamp-2 leading-tight">
                            Fiche officielle, IDs & structure.
                        </p>
                    </div>
                </a>

                {/* 2. Dofus pour les Noobs */}
                <a
                    href={entry.externalRef || (() => {
                        const slug = entry.name
                            .toLowerCase()
                            .normalize("NFD")
                            .replace(/[\u0300-\u036f]/g, "")
                            .replace(/['’]/g, "")
                            .replace(/[^a-z0-9\s-]/g, "")
                            .trim()
                            .replace(/\s+/g, "-")
                            .replace(/-+/g, "-");
                        return `https://www.dofuspourlesnoobs.com/${slug}.html`;
                    })()}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="relative group overflow-hidden rounded-2xl border border-amber-500/20 bg-[#0d0e15]/60 p-4 hover:border-amber-500/40 hover:bg-[#15120e]/80 hover:shadow-[0_0_20px_rgba(245,158,11,0.15)] transition-all duration-300 flex flex-col justify-between min-h-[110px]"
                    onClick={(e) => e.stopPropagation()}
                >
                    <div className="flex justify-between items-start">
                        {/* eslint-disable-next-line @next/next/no-img-element */}
                        <img 
                            src={noobsFavicon} 
                            alt="Noobs" 
                            className="w-5 h-5 object-contain rounded-md filter drop-shadow-[0_0_4px_rgba(245,158,11,0.5)] group-hover:scale-110 transition-transform" 
                            onError={(e) => { e.currentTarget.style.display = "none"; }} 
                        />
                        <span className="text-[8px] font-black uppercase tracking-wider text-amber-400/90 bg-amber-500/10 px-1.5 py-0.5 rounded border border-amber-500/20">
                            Tuto
                        </span>
                    </div>
                    <div>
                        <h4 className="text-xs font-black text-white italic tracking-tight mt-3 group-hover:text-amber-400 transition-colors">
                            Noobs
                        </h4>
                        <p className="text-[9px] text-zinc-500 mt-1 line-clamp-2 leading-tight">
                            Tutoriel détaillé & images d'étapes.
                        </p>
                    </div>
                </a>

                {/* 3. Autopilote (Travel) */}
                <button
                    onClick={copyTravelCoords}
                    disabled={!entry.coords}
                    className="relative group overflow-hidden rounded-2xl border border-emerald-500/20 bg-[#0d0e15]/60 p-4 hover:border-emerald-500/40 hover:bg-[#0e1512]/80 hover:shadow-[0_0_20px_rgba(16,185,129,0.15)] transition-all duration-300 flex flex-col justify-between min-h-[110px] text-left disabled:opacity-30 disabled:pointer-events-none"
                >
                    <div className="flex justify-between items-start">
                        <Navigation className="w-5 h-5 text-emerald-400/80 group-hover:rotate-12 transition-transform shrink-0" />
                        <span className="text-[8px] font-black uppercase tracking-wider text-emerald-400/90 bg-emerald-500/10 px-1.5 py-0.5 rounded border border-emerald-500/20">
                            GPS
                        </span>
                    </div>
                    <div>
                        <h4 className="text-xs font-black text-white italic tracking-tight mt-3 group-hover:text-emerald-400 transition-colors">
                            Autopilote
                        </h4>
                        {entry.coords ? (
                            <div className="flex items-center gap-1 mt-1">
                                <span className="text-[8px] font-mono text-emerald-400 bg-emerald-950/60 border border-emerald-500/20 px-1.5 py-0.5 rounded">
                                    [{entry.coords.x}, {entry.coords.y}]
                                </span>
                                <Copy className="w-2.5 h-2.5 text-emerald-500/50" />
                            </div>
                        ) : (
                            <p className="text-[9px] text-zinc-600 mt-1">
                                Aucune coordonnée
                            </p>
                        )}
                    </div>
                </button>

                {/* 4. Guild Radar Card (La Tour de Contrôle avec vrai modal au clic) */}
                <button
                    onClick={openGuildModal}
                    className="relative group overflow-hidden rounded-2xl border border-rose-500/20 bg-[#0d0e15]/60 p-4 hover:border-rose-500/40 hover:bg-[#150d10]/80 hover:shadow-[0_0_20px_rgba(244,63,94,0.15)] transition-all duration-300 flex flex-col justify-between min-h-[110px] text-left"
                >
                    <div className="flex justify-between items-start">
                        <Users className="w-5 h-5 text-rose-400/80 group-hover:scale-110 transition-transform shrink-0" />
                        <span className="text-[8px] font-black uppercase tracking-wider text-rose-400/90 bg-rose-500/10 px-1.5 py-0.5 rounded border border-rose-500/20">
                            Guilde
                        </span>
                    </div>
                    <div>
                        <h4 className="text-xs font-black text-white italic tracking-tight mt-1 group-hover:text-rose-400 transition-colors">
                            Synergies
                        </h4>

                        {/* Avatars Stack or Count */}
                        <div className="mt-1 flex items-center gap-1">
                            {loadingMembers ? (
                                <div className="w-3.5 h-3.5 rounded-full border border-white/10 border-t-rose-400 animate-spin" />
                            ) : members.length === 0 ? (
                                <span className="text-[9px] text-zinc-600 font-bold uppercase tracking-wider">
                                    0 Membre
                                </span>
                            ) : (
                                <div className="flex -space-x-1.5 overflow-hidden">
                                    {members.slice(0, 3).map((m) => (
                                        <div
                                            key={m.profileId}
                                            className="w-5 h-5 rounded-full overflow-hidden border border-zinc-950 bg-zinc-800 flex-shrink-0"
                                        >
                                            {m.image ? (
                                                <img src={m.image} alt={m.pseudo} className="w-full h-full object-cover" />
                                            ) : (
                                                <span className="text-[7px] flex items-center justify-center h-full font-black text-white/50 bg-zinc-700">
                                                    {m.pseudo[0]}
                                                </span>
                                            )}
                                        </div>
                                    ))}
                                    {members.length > 3 && (
                                        <div className="w-5 h-5 rounded-full bg-zinc-900 border border-rose-500/20 flex items-center justify-center text-[7px] font-black text-rose-400">
                                            +{members.length - 3}
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>
                </button>
            </div>

            {/* Validation CTA Button */}
            <Button
                disabled={lock && !done}
                onClick={(e) => {
                    e.stopPropagation();
                    if (lock && !done) return;
                    onToggle();
                }}
                className={`w-full h-12 rounded-2xl font-black italic uppercase text-[13px] transition-all tracking-widest ${
                    done
                        ? "bg-zinc-900 border border-white/10 text-zinc-400 hover:bg-zinc-950"
                        : lock
                        ? "bg-zinc-950 text-white/10 border border-white/5 cursor-not-allowed"
                        : "bg-white text-black hover:bg-zinc-200 hover:scale-[1.01] active:scale-[0.99] shadow-[0_0_20px_rgba(255,255,255,0.15)]"
                }`}
            >
                {done ? (
                    <span className="flex items-center justify-center gap-2">
                        <Check className="w-4 h-4 text-emerald-400" /> Réinitialiser la progression
                    </span>
                ) : lock ? (
                    <span className="flex items-center justify-center gap-2">
                        <Lock className="w-4 h-4 text-zinc-700" /> Quête Verrouillée
                    </span>
                ) : (
                    "Valider l'étape de quête"
                )}
            </Button>

            {/* Beautiful Interactive Guild Progress Dialog Modal */}
            <Dialog open={isModalOpen} onOpenChange={setIsModalOpen}>
                <DialogContent className="max-w-md bg-[#090a0f] border border-white/10 rounded-[2rem] p-6 shadow-2xl overflow-hidden flex flex-col max-h-[80vh]">
                    <DialogHeader className="border-b border-white/5 pb-4 mb-4">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-xl bg-rose-500/10 border border-rose-500/20 flex items-center justify-center text-rose-400 shrink-0">
                                <Users className="w-5 h-5" />
                            </div>
                            <div className="text-left">
                                <div className="text-[9px] font-black text-rose-400 uppercase tracking-widest leading-none mb-1">
                                    Synergies de Guilde
                                </div>
                                <DialogTitle className="text-lg font-black text-white italic uppercase tracking-tight truncate max-w-[280px]">
                                    {entry.name}
                                </DialogTitle>
                            </div>
                        </div>
                    </DialogHeader>

                    <ScrollArea className="flex-1 pr-1">
                        <div className="space-y-2">
                            {loadingMembers ? (
                                <div className="py-12 flex flex-col items-center justify-center gap-3">
                                    <div className="w-6 h-6 rounded-full border-2 border-rose-500/20 border-t-rose-400 animate-spin" />
                                    <span className="text-[10px] text-zinc-500 font-bold uppercase">Chargement de la tour de contrôle...</span>
                                </div>
                            ) : members.length === 0 ? (
                                <div className="py-12 flex flex-col items-center justify-center text-center gap-2 bg-white/[0.01] border border-dashed border-white/5 rounded-2xl">
                                    <ShieldAlert className="w-8 h-8 text-zinc-700" />
                                    <p className="text-xs text-zinc-500 font-black uppercase tracking-wider">
                                        Aucun membre n'a débuté
                                    </p>
                                    <p className="text-[10px] text-zinc-600 max-w-[220px]">
                                        Soyez le premier de votre guilde à vous lancer et à guider les autres !
                                    </p>
                                </div>
                            ) : (
                                <div className="grid grid-cols-1 gap-2">
                                    {members.map((m) => {
                                        const isDone = m.status === "COMPLETED";
                                        return (
                                            <Link
                                                key={m.profileId}
                                                href={`/dashboard/${guildId}/members/${encodeURIComponent(m.pseudo)}`}
                                                className="flex items-center gap-3 p-3 rounded-2xl bg-white/[0.02] border border-white/5 hover:bg-white/[0.05] hover:border-white/10 transition-all group/member"
                                                onClick={() => setIsModalOpen(false)}
                                            >
                                                <div className="w-9 h-9 rounded-xl overflow-hidden bg-zinc-800 border border-white/10 shrink-0 relative shadow-inner">
                                                    {m.image ? (
                                                        <img src={m.image} alt={m.pseudo} className="w-full h-full object-cover" />
                                                    ) : (
                                                        <span className="text-[11px] flex items-center justify-center h-full font-black text-white/50 bg-zinc-700 uppercase">
                                                            {m.pseudo[0]}
                                                        </span>
                                                    )}
                                                </div>

                                                <div className="flex-1 min-w-0">
                                                    <p className="text-sm font-black text-white group-hover/member:text-rose-400 transition-colors truncate leading-none mb-1.5">
                                                        {m.pseudo}
                                                    </p>
                                                    <div className="flex items-center gap-1.5">
                                                        <span 
                                                            className="w-1.5 h-1.5 rounded-full" 
                                                            style={{ backgroundColor: isDone ? "#10b981" : "#f59e0b" }} 
                                                        />
                                                        <span 
                                                            className="text-[9px] font-black uppercase tracking-widest"
                                                            style={{ color: isDone ? "#10b981" : "#f59e0b" }}
                                                        >
                                                            {isDone ? "Terminée" : "En cours"}
                                                        </span>
                                                    </div>
                                                </div>
                                            </Link>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                    </ScrollArea>

                    <div className="mt-4 pt-4 border-t border-white/5 flex items-center justify-between text-[8px] font-black text-zinc-600 uppercase tracking-widest">
                        <span>SigilOS Intelligence</span>
                        <span>{members.length} joueur{members.length > 1 ? "s" : ""}</span>
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useTransition, useMemo, useCallback } from "react";
import { CheckCircle2, Circle, ChevronDown, ChevronUp, Swords, Star, Briefcase, Wand2, ListChecks, Shield, AlertCircle, MapPin, Lock, Copy, BookOpen, Users, Target, Navigation } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { toggleQuestStatus, getOtherMembersOnQuest, type MemberOnQuest } from "@/server/actions/dofus-quest-actions";
import type { DofusChainWithProgress, DofusEntryWithProgress } from "@/server/actions/dofus-quest-actions";
import { DofusQuestStatus } from "@prisma/client";
import { NpcName, ItemInline, ParsedObjective, copyWithToast, detectRealDungeons, extractObjectiveText } from "./dofus-resolvers";
import { QuestGuildStatus } from "./QuestGuildStatus";
import { QuestActionsBlock } from "./QuestActionsBlock";


// ─── Icons per quest type ────────────────────────────────────────────────────
function QuestTypeIcon({ type, className }: { type: string; className?: string }) {
    const cls = className || "w-3.5 h-3.5";
    switch (type) {
        case "DUNGEON":     return <Swords className={cls} />;
        case "ACHIEVEMENT": return <Star className={cls} />;
        case "JOB":         return <Briefcase className={cls} />;
        case "SPELL":       return <Wand2 className={cls} />;
        case "REQUIREMENT": return <AlertCircle className={cls} />;
        default:            return <ListChecks className={cls} />;
    }
}

// ─── Section type label ────────────────────────────────────────────────────────
function SectionBadge({ type }: { type: string }) {
    const map: Record<string, { label: string; color: string }> = {
        PREREQUISITE:  { label: "Prérequis",    color: "#f59e0b" },
        MAIN_CHAIN:    { label: "Les quêtes",   color: "#6366f1" },
        OPTIONAL:      { label: "Optionnel",    color: "#6b7280" },
    };
    const cfg = map[type] || { label: type, color: "#6b7280" };
    return (
        <span
            className="text-[10px] font-semibold uppercase tracking-wider px-2 py-0.5 rounded-full"
            style={{ background: `${cfg.color}22`, color: cfg.color, border: `1px solid ${cfg.color}44` }}
        >
            {cfg.label}
        </span>
    );
}

// ─── Single quest entry row ──────────────────────────────────────────────────
function QuestEntryRow({
    entry,
    guildId,
    dofusColor,
    completedIds,   // ← reactive set from the parent (includes local toggles)
    onToggle,       // ← callback to notify parent of status change
}: {
    entry: DofusEntryWithProgress;
    guildId: string;
    dofusColor: string;
    completedIds: Set<string>;
    onToggle: (id: string, newStatus: DofusQuestStatus) => void;
}) {
    // Mirror the initial status — parent drives it via completedIds
    const isCompleted = completedIds.has(entry.id);
    const [isPending, startTransition] = useTransition();
    const [showDetail, setShowDetail] = useState(false);

    const [members, setMembers] = useState<MemberOnQuest[]>([]);
    const [loadingMembers, setLoadingMembers] = useState(false);

    useEffect(() => {
        if (showDetail) {
            setLoadingMembers(true);
            getOtherMembersOnQuest(guildId, entry.id).then((res) => {
                if (res.success && res.data) {
                    setMembers(res.data);
                }
                setLoadingMembers(false);
            });
        }
    }, [showDetail, guildId, entry.id]);

    // Lock if any QUEST requirement is not yet in completedIds
    const isLocked = useMemo(() => {
        const reqs = Array.isArray(entry.requirements) ? entry.requirements : [];
        if (reqs.length === 0) return false;
        return reqs.some((req: any) => {
            if (!req || typeof req !== "object" || req.type !== "QUEST") return false;
            const rid = req.id || req.dofusdbId;
            return !completedIds.has(String(rid));
        });
    }, [entry.requirements, completedIds]);

    // V3 structured dungeons
    const structuredDungeons: { id?: string; name: string; bossName?: string; level?: number; img?: string; idoleName?: string }[] =
        useMemo(() => (entry as any).dungeonsRequired ?? [], [entry]);

    // Fallback: text-parsed dungeons
    const dungeonInfos = useMemo(() => detectRealDungeons((entry as any).objectives ?? []), [entry]);
    const hasDungeons = structuredDungeons.length > 0 || dungeonInfos.length > 0;

    function handleToggle() {
        if (isLocked && !isCompleted) return;
        const newStatus: DofusQuestStatus = isCompleted ? "NOT_STARTED" : "COMPLETED";
        
        // Auto-collapse detail on completion
        if (newStatus === "COMPLETED") setShowDetail(false);
        
        // Optimistic: notify parent immediately so completedIds updates for siblings
        onToggle(entry.id, newStatus);
        startTransition(async () => {
            const res = await toggleQuestStatus(guildId, entry.id, newStatus);
            // On failure, revert
            if (!res.success) onToggle(entry.id, isCompleted ? "COMPLETED" : "NOT_STARTED");
        });
    }

    return (
        <div
            className={`group flex flex-col rounded-2xl transition-all duration-300 border ${
                isCompleted ? "bg-[#10b98108] border-[#10b98125]" : "bg-[#ffffff03] border-white/5 hover:border-white/10"
            } ${entry.isOptional ? "opacity-60" : ""} ${isPending ? "opacity-50 pointer-events-none" : ""}`}
        >
            {/* ── Header row ── */}
            <div
                className="flex items-center gap-3 px-4 py-3 cursor-pointer select-none"
                onClick={() => setShowDetail(!showDetail)}
            >
                {/* Checkbox */}
                <button
                    disabled={isPending || (!!isLocked && !isCompleted)}
                    onClick={(e) => { e.stopPropagation(); handleToggle(); }}
                    className={`flex-shrink-0 transition-all duration-150 z-10 ${
                        isLocked && !isCompleted ? "cursor-not-allowed opacity-20 grayscale" : "hover:scale-110"
                    }`}
                >
                    {isCompleted ? (
                        <CheckCircle2 className="w-5 h-5" style={{ color: dofusColor, filter: `drop-shadow(0 0 8px ${dofusColor}44)` }} />
                    ) : isLocked ? (
                        <Lock className="w-5 h-5 text-zinc-700" />
                    ) : (
                        <Circle className="w-5 h-5 text-white/10 group-hover:text-white/30 transition-colors" />
                    )}
                </button>

                {/* Type icon */}
                <span className={`flex-shrink-0 ${isCompleted ? "" : "text-white/20"}`} style={{ color: isCompleted ? dofusColor : undefined }}>
                    <QuestTypeIcon type={entry.questType} />
                </span>

                {/* Name */}
                <div className="flex-1 min-w-0">
                    <div className="flex flex-col sm:flex-row sm:items-center gap-x-2">
                        <span className={`text-[14px] font-black italic tracking-tight transition-colors ${
                            isCompleted ? "text-white/30 line-through" : "text-white"
                        }`}>
                            {entry.name}
                        </span>
                        <div className="flex items-center gap-2">
                            {entry.zone && <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest">{entry.zone}</span>}
                            {(entry as any).level != null && <span className="text-[10px] text-zinc-600 font-medium">Lvl {(entry as any).level}</span>}
                        </div>
                    </div>
                </div>

                {/* Badges */}
                <div className="flex items-center gap-2 flex-shrink-0">
                    {hasDungeons && <span className="text-[9px] text-rose-400/80 font-black uppercase">🏰 DJ</span>}
                    {entry.isLast && (
                        <span className="text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-md" style={{ background: `${dofusColor}20`, color: dofusColor }}>
                            🎯 Final
                        </span>
                    )}
                    <div className={`text-white/10 group-hover:text-white/40 transition-all ${showDetail ? "rotate-180" : ""}`}>
                        <ChevronDown className="w-4 h-4" />
                    </div>
                </div>
            </div>

            {/* ── Expanded detail ── */}
            <AnimatePresence>
                {showDetail && (
                    <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: "auto", opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        className="overflow-hidden"
                        onClick={(e) => e.stopPropagation()}
                    >
                        <div className="px-5 pb-5 pt-2 ml-[10px] sm:ml-[42px] border-l border-white/5 space-y-4">

                            {/* V3 Structured Dungeons */}
                            {structuredDungeons.map((d, dx) => (
                                <div key={`sd-${dx}`} className="p-3 bg-rose-500/10 border border-rose-500/20 rounded-2xl flex items-center gap-3">
                                    <div className="w-12 h-12 rounded-xl bg-black/60 border border-rose-500/20 flex items-center justify-center p-1 shrink-0 overflow-hidden">
                                        {d.img ? (
                                            // eslint-disable-next-line @next/next/no-img-element
                                            <img src={d.img} alt={d.name} className="w-full h-full object-contain" onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }} />
                                        ) : d.id ? (
                                            // eslint-disable-next-line @next/next/no-img-element
                                            <img src={`https://api.dofusdb.fr/img/monsters/${d.id}.png`} alt={d.name} className="w-full h-full object-contain" onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }} />
                                        ) : (
                                            <span className="text-rose-400">🏰</span>
                                        )}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="text-[9px] font-black text-rose-400 uppercase tracking-widest mb-0.5">🏰 Donjon requis</div>
                                        <div className="text-[13px] font-black text-white italic truncate">{d.name}</div>
                                        <div className="flex items-center gap-2 mt-0.5">
                                            {d.level && d.level > 0 && <span className="text-[9px] text-zinc-500 font-bold">Lvl {d.level}</span>}
                                            {d.bossName && <span className="text-[9px] text-zinc-600 italic">— {d.bossName}</span>}
                                            {d.idoleName && <span className="text-[8px] font-black text-amber-500 bg-amber-500/10 px-1 py-0.5 rounded">{d.idoleName}</span>}
                                        </div>
                                    </div>
                                    {(d as any).dplnUrl && (
                                        <Button
                                            asChild
                                            variant="sigil"
                                            className="h-10 px-4"
                                            onClick={(e) => e.stopPropagation()}
                                        >
                                            <a href={(d as any).dplnUrl} target="_blank" rel="noopener noreferrer">
                                                <BookOpen className="w-4 h-4 mr-2" />
                                                <span className="text-[10px] font-black uppercase tracking-widest">Stratégie</span>
                                            </a>
                                        </Button>
                                    )}
                                </div>
                            ))}

                            {/* Fallback text-parsed dungeons */}
                            {structuredDungeons.length === 0 && dungeonInfos.map((di, dx) => (
                                <div key={`di-${dx}`} className="p-3 bg-rose-500/10 border border-rose-500/20 rounded-2xl flex items-center gap-3">
                                    {di.mapImg && (
                                        // eslint-disable-next-line @next/next/no-img-element
                                        <img src={di.mapImg} alt={di.dungeonName} className="w-12 h-12 object-cover rounded-xl border border-rose-500/30" onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }} />
                                    )}
                                    <div className="flex-1">
                                        <div className="text-[9px] font-black text-rose-400 uppercase tracking-widest mb-0.5">🏰 Donjon</div>
                                        <div className="text-[13px] font-black text-white italic">{di.dungeonName}</div>
                                    </div>
                                    {di.x !== undefined && (
                                        <Link href={`/dashboard/${guildId}/worldmap?x=${di.x}&y=${di.y}&zoom=4&world=${di.worldId ?? 0}`}
                                            className="h-8 w-8 rounded-xl bg-rose-500 text-black flex items-center justify-center hover:scale-110 transition-transform flex-shrink-0"
                                            onClick={(e) => e.stopPropagation()}>
                                            <MapPin className="w-4 h-4" />
                                        </Link>
                                    )}
                                </div>
                            ))}

                            {/* NPC GPS */}
                            {(entry as any).coords && (
                                <div className="p-3 bg-zinc-900/50 rounded-2xl border border-white/5 flex items-center justify-between hover:bg-zinc-900 transition-all">
                                    <div className="flex items-center gap-3 cursor-pointer group/travel"
                                        onClick={(e) => { e.stopPropagation(); copyWithToast(`/travel ${(entry as any).coords.x} ${(entry as any).coords.y}`); }}>
                                        <div className="w-8 h-8 rounded-xl bg-indigo-500/10 flex items-center justify-center text-indigo-400">
                                            <Wand2 className="w-4 h-4" />
                                        </div>
                                        <div>
                                            <div className="text-[9px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-1.5">
                                                PNJ OBJECTIF
                                                <span className="text-[8px] bg-white/5 px-1 py-0.5 rounded opacity-0 group-hover/travel:opacity-100 transition-opacity flex items-center gap-0.5">
                                                    <Copy className="w-2.5 h-2.5" /> COPIER
                                                </span>
                                            </div>
                                            <div className="text-[12px] font-bold text-white italic group-hover/travel:text-emerald-400 transition-colors">
                                                {(() => {
                                                    const objectives = Array.isArray((entry as any).objectives) ? (entry as any).objectives : [];
                                                    const objWithNpc = objectives.find((o: any) => extractObjectiveText(o).includes("{npc,"));
                                                    const match = extractObjectiveText(objWithNpc).match(/\{npc,(\d+)\}/);
                                                    return match ? <NpcName npcId={match[1]} /> : ((entry as any).npcName || "PNJ");
                                                })()} <span className="text-zinc-500 font-normal">[{(entry as any).coords.x}, {(entry as any).coords.y}]</span>
                                            </div>
                                        </div>
                                    </div>
                                    <Link
                                        href={`/dashboard/${guildId}/worldmap?x=${(entry as any).coords.x}&y=${(entry as any).coords.y}&zoom=4&world=${(entry as any).coords.worldId ?? 0}`}
                                        className="h-8 w-8 rounded-lg bg-emerald-500 text-black flex items-center justify-center hover:scale-110 transition-transform shadow-[0_0_15px_rgba(16,185,129,0.3)]"
                                        onClick={(e) => e.stopPropagation()}
                                    >
                                        <MapPin className="w-4 h-4" />
                                    </Link>
                                </div>
                            )}

                            {/* Objectives */}
                            {Array.isArray((entry as any).objectives) && (entry as any).objectives.length > 0 && (
                                <div className="space-y-2">
                                    <div className="text-[10px] font-black text-zinc-600 uppercase tracking-widest italic mb-2">Marche à suivre</div>
                                    {(entry as any).objectives.map((obj: any, i: number) => {
                                        const text = extractObjectiveText(obj);
                                        const isReturn = text.toLowerCase().includes("retour") || text.toLowerCase().includes("aller voir");
                                        return (
                                            <div key={i} className="flex gap-2 items-start py-0.5">
                                                <div className={`w-4 h-4 rounded-full flex items-center justify-center flex-shrink-0 text-[8px] font-black mt-0.5 ${isReturn ? "animate-pulse" : ""}`}
                                                    style={{ background: isReturn ? `${dofusColor}40` : "rgba(255,255,255,0.05)", color: isReturn ? "#fff" : "rgba(255,255,255,0.4)" }}>
                                                    {i + 1}
                                                </div>
                                                <div className={`text-[12.5px] font-medium leading-relaxed ${isReturn ? "text-white" : "text-zinc-400"}`}>
                                                    <ParsedObjective text={obj} guildId={guildId} zone={entry.zone ?? undefined} />
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                            <QuestActionsBlock
                                entry={entry}
                                guildId={guildId}
                                dofusColor={dofusColor}
                                initialMembers={members}
                                lock={isLocked}
                                done={isCompleted}
                                onToggle={handleToggle}
                            />
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

// ─── Chain section ─────────────────────────────────────────────────────────────
function ChainSection({
    chain,
    guildId,
    dofusColor,
    completedIds,
    onToggle,
}: {
    chain: DofusChainWithProgress;
    guildId: string;
    dofusColor: string;
    completedIds: Set<string>;
    onToggle: (id: string, newStatus: DofusQuestStatus) => void;
}) {
    const [collapsed, setCollapsed] = useState(false);
    const completedCount = (chain.entries || []).filter((e) => completedIds.has(e.id)).length;
    const total = (chain.entries || []).length;
    const allDone = completedCount === total && total > 0;

    return (
        <div className="flex flex-col gap-2">
            <button onClick={() => setCollapsed(!collapsed)} className="flex items-center gap-3 w-full text-left group">
                <SectionBadge type={chain.sectionType} />
                <span className="text-sm font-semibold text-white/80 flex-1">{chain.sectionName}</span>
                {chain.description && (
                    <span className="text-xs text-white/30 hidden sm:block truncate max-w-[180px]">{chain.description}</span>
                )}
                <span className="text-xs text-white/30 tabular-nums">{completedCount}/{total}</span>
                {allDone && <span style={{ color: dofusColor }}>✓</span>}
                {collapsed ? <ChevronDown className="w-4 h-4 text-white/30" /> : <ChevronUp className="w-4 h-4 text-white/30" />}
            </button>

            {!collapsed && (
                <div className="flex flex-col gap-1.5 ml-0 sm:ml-2">
                    {(chain.entries || []).map((entry: any) => (
                        <QuestEntryRow
                            key={entry.id}
                            entry={entry}
                            guildId={guildId}
                            dofusColor={dofusColor}
                            completedIds={completedIds}
                            onToggle={onToggle}
                        />
                    ))}
                    {total === 0 && (
                        <p className="text-sm text-white/20 text-center py-4">Aucune entrée pour cette section</p>
                    )}
                </div>
            )}
        </div>
    );
}

// ─── Main export ───────────────────────────────────────────────────────────────
interface QuestChecklistProps {
    chains: DofusChainWithProgress[];
    guildId: string;
    dofusColor: string;
    completedIds: Set<string>;
    onToggle: (id: string, newStatus: DofusQuestStatus) => void;
}

export function QuestChecklist({ chains, guildId, dofusColor, completedIds, onToggle }: QuestChecklistProps) {
    if (chains.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center py-16 gap-3">
                <ListChecks className="w-10 h-10 text-white/15" />
                <p className="text-white/30 text-sm">Guide de quêtes à venir — données en cours d&apos;intégration</p>
            </div>
        );
    }

    return (
        <div className="space-y-12">
            {(chains || []).map((chain) => (
                <div key={chain.id} className="space-y-6">
                    <ChainSection
                        chain={chain}
                        guildId={guildId}
                        dofusColor={dofusColor}
                        completedIds={completedIds}
                        onToggle={onToggle}
                    />
                </div>
            ))}
        </div>
    );
}

"use client";

import React, { useState } from "react";
import { Users } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/components/ui/button";
import { getOtherMembersOnQuest, type MemberOnQuest } from "@/server/actions/dofus-quest-actions";

interface QuestGuildStatusProps {
    guildId: string;
    questId: string;
    dofusColor: string;
    variant?: "default" | "action";
}

export function QuestGuildStatus({ guildId, questId, dofusColor, variant = "default" }: QuestGuildStatusProps) {
    const [isLoading, setIsLoading] = useState(false);
    const [members, setMembers] = useState<MemberOnQuest[]>([]);
    const [isOpen, setIsOpen] = useState(false);

    async function handleToggle() {
        if (!isOpen) {
            setIsLoading(true);
            const res = await getOtherMembersOnQuest(guildId, questId);
            if (res.success && res.data) setMembers(res.data);
            setIsLoading(false);
        }
        setIsOpen(!isOpen);
    }

    const isAction = variant === "action";

    return (
        <div className={isAction ? "w-full" : "relative"}>
            <Button
                variant={isAction ? "sigil-destructive" : "ghost"}
                onClick={(e) => { e.stopPropagation(); handleToggle(); }}
                className={isAction 
                    ? "flex flex-col items-center justify-center gap-2 h-20 w-full rounded-2xl"
                    : `flex items-center gap-1.5 px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${
                        isOpen ? "bg-white/10 text-white border-white/20" : "bg-white/5 text-zinc-500 hover:text-white border-white/5"
                    } border h-auto`
                }
            >
                <Users className={isAction ? "w-5 h-5" : "w-3 h-3 transition-colors"} style={{ color: isOpen ? dofusColor : undefined }} />
                {isAction ? (
                    <span className="flex flex-col items-center">
                        <span className="text-[10px]">{members.length > 0 ? `${members.length} Membres` : "Guilde"}</span>
                    </span>
                ) : (
                    members.length > 0 ? (
                        <span className="flex items-center gap-1">
                            <span style={{ color: dofusColor }}>{members.length}</span>
                            <span>membres</span>
                        </span>
                    ) : "Guilde"
                )}
            </Button>

            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95, y: 10 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.95, y: 10 }}
                        className="absolute left-0 bottom-full mb-2 z-50 w-56 p-2 rounded-xl bg-zinc-950 border border-white/10 shadow-2xl backdrop-blur-xl"
                    >
                        <div className="flex flex-col gap-1">
                            <p className="text-[8px] font-black text-white/30 uppercase tracking-[0.25em] px-2 mb-2">Avancement Guilde</p>
                            {isLoading ? (
                                <div className="py-6 flex justify-center">
                                    <div className="w-5 h-5 rounded-full border-2 border-white/5 border-t-white animate-spin" />
                                </div>
                            ) : members.length === 0 ? (
                                <div className="px-2 py-4 text-center">
                                    <p className="text-[10px] text-white/20 italic font-bold">Aucun membre sur cette étape</p>
                                </div>
                            ) : (
                                <div className="flex flex-col gap-1 max-h-48 overflow-y-auto pr-1 custom-scrollbar">
                                    {members.map(m => (
                                        <div key={m.profileId} className="flex items-center gap-2.5 p-2 rounded-lg bg-white/[0.03] border border-white/5 hover:bg-white/[0.06] transition-colors">
                                            <div className="w-6 h-6 rounded-md overflow-hidden bg-zinc-800 flex-shrink-0 border border-white/5 shadow-inner">
                                                {m.image ? <img src={m.image} alt={m.pseudo} className="w-full h-full object-cover" /> : <span className="text-[8px] flex items-center justify-center h-full font-black text-white/40">{m.pseudo[0]}</span>}
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                <p className="text-[10px] font-bold text-white/80 truncate leading-none mb-1">{m.pseudo}</p>
                                                <div className="flex items-center gap-1">
                                                    <div className={`w-1 h-1 rounded-full ${m.status === "COMPLETED" ? "bg-emerald-500" : "bg-amber-500"}`} />
                                                    <p className={`text-[8px] font-black uppercase tracking-tighter ${m.status === "COMPLETED" ? "text-emerald-500/70" : "text-amber-500/70"}`}>
                                                        {m.status === "COMPLETED" ? "Terminée" : "En cours"}
                                                    </p>
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                        <div className="mt-2 pt-2 border-t border-white/5">
                            <p className="text-[7px] text-white/10 font-black uppercase text-center tracking-widest">SigilOS Intelligence Unit</p>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

"use client";
import React from "react";
import { motion, AnimatePresence } from "framer-motion";
import { RotateCcw, X, AlertTriangle } from "lucide-react";

type ResetConfirmModalProps = {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  characterName: string;
  isLoading?: boolean;
};

export function ResetConfirmModal({
  isOpen,
  onClose,
  onConfirm,
  characterName,
  isLoading = false,
}: ResetConfirmModalProps) {
  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-md p-4"
          onClick={onClose}
        >
          <motion.div
            initial={{ scale: 0.95, opacity: 0, y: 20 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.95, opacity: 0, y: 20 }}
            transition={{ type: "spring", duration: 0.4 }}
            className="bg-zinc-900 border border-zinc-800 rounded-3xl p-5 max-w-sm w-full shadow-2xl"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Icon */}
            <div className="w-12 h-12 mx-auto rounded-2xl bg-red-500/15 border border-red-500/25 flex items-center justify-center mb-4">
              <AlertTriangle className="w-6 h-6 text-red-400" />
            </div>

            {/* Title */}
            <h3 className="text-center text-base font-black text-white mb-2">
              Réinitialiser la progression
            </h3>

            {/* Description */}
            <p className="text-center text-xs text-zinc-400 mb-6 leading-relaxed">
              Tu es sur le point de <strong className="text-red-400">tout remettre à zéro</strong> pour{" "}
              <strong className="text-white">{characterName}</strong>.
              <br />
              Cette action est irréversible.
            </p>

            {/* Buttons */}
            <div className="flex gap-2.5">
              <button
                onClick={onClose}
                disabled={isLoading}
                className="flex-1 px-4 py-2.5 rounded-xl bg-zinc-800 hover:bg-zinc-700 text-zinc-400 text-[10px] font-black uppercase tracking-widest transition-all disabled:opacity-50"
              >
                Annuler
              </button>
              <button
                onClick={onConfirm}
                disabled={isLoading}
                className="flex-1 flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl bg-red-500 hover:bg-red-400 text-white text-[10px] font-black uppercase tracking-widest transition-all disabled:opacity-50"
              >
                {isLoading ? (
                  <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                ) : (
                  <>
                    <RotateCcw className="w-3.5 h-3.5" />
                    Reset
                  </>
                )}
              </button>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

"use client";
import React, { useState, useEffect, useCallback, useRef, memo } from "react";
import {
  Users, Circle, Clock, Activity
} from "lucide-react";
import { getClass } from "@/lib/dofus-assets";
import {
  getRushActiveMembers,
  joinRushSession,
  leaveRushSession,
  updateRushLocation,
} from "@/server/actions/rush-actions";

// ─── Types ────────────────────────────────────────────────────────────────────

type RushMember = {
  id: string;
  profileId: string;
  pseudoDofus: string;
  dofusClass: string | null;
  milestoneId: string | null;
  locationDesc: string | null;
  status: string; // "ACTIVE" | "AFK"
  lastActivity: Date;
  joinedAt: Date;
};

type RushLivePopoverProps = {
  guildId: string;
  currentPseudo: string;
  currentClass: string | null;
  currentMilestoneId?: string | null;
  currentMilestoneTitle?: string | null;
  isOnRush: boolean;
};

// ─── Component ─────────────────────────────────────────────────────────────────

export const RushLivePopover = memo(function RushLivePopover({
  guildId,
  currentPseudo,
  currentClass,
  currentMilestoneId,
  currentMilestoneTitle,
  isOnRush,
}: RushLivePopoverProps) {
  const [members, setMembers] = useState<RushMember[]>([]);
  const joinedRef = useRef(false);

  const fetchMembers = useCallback(async () => {
    const res = await getRushActiveMembers(guildId);
    if (res.success) {
      setMembers(res.members as RushMember[]);
    }
  }, [guildId]);

  // Join automatically on mount, leave on unmount
  useEffect(() => {
    if (!currentPseudo || currentPseudo === "PRINCIPAL" || joinedRef.current) return;
    joinedRef.current = true;
    joinRushSession(guildId, currentPseudo, currentClass);
    fetchMembers();

    // Leave on tab close
    const handleBeforeUnload = () => {
      // Use sendBeacon for reliability on unload
      navigator.sendBeacon(
        `/api/rush/leave?guildId=${guildId}`
      );
    };
    window.addEventListener("beforeunload", handleBeforeUnload);
    return () => {
      window.removeEventListener("beforeunload", handleBeforeUnload);
      // Also leave on unmount (navigation away)
      leaveRushSession(guildId);
    };
  }, [guildId, currentPseudo, currentClass, fetchMembers]);

  // Fetch on mount + every 10s
  useEffect(() => {
    fetchMembers();
    const id = setInterval(fetchMembers, 10000);
    return () => clearInterval(id);
  }, [fetchMembers]);

  // Auto-update location when milestone changes
  useEffect(() => {
    if (currentMilestoneId) {
      updateRushLocation(guildId, currentMilestoneId, currentMilestoneTitle);
    }
  }, [guildId, currentMilestoneId, currentMilestoneTitle]);

  const uniqueMembers = Array.from(new Map(members.map(m => [m.profileId || m.pseudoDofus, m])).values())
    .sort((a, b) => a.pseudoDofus.localeCompare(b.pseudoDofus));
  const activeCount = uniqueMembers.filter(m => m.status === "ACTIVE").length;
  const totalCount = uniqueMembers.length;

  return (
    <div className="flex flex-col gap-2 w-full">
      {/* Header with count */}
      <div className="flex items-center gap-1.5 px-1">
        <Activity className="w-3.5 h-3.5 text-emerald-400" />
        <span className="text-[9px] font-black uppercase tracking-widest text-zinc-400">
          {totalCount > 0 ? `${totalCount} en ligne` : "En ligne"}
        </span>
        {activeCount > 0 && activeCount < totalCount && (
          <span className="text-[8px] text-zinc-600">({activeCount} actif{activeCount > 1 ? "s" : ""})</span>
        )}
      </div>

      {/* Inline member chips */}
      {totalCount > 0 ? (
        <div className="flex flex-wrap items-center gap-1">
          {uniqueMembers.slice(0, 6).map((m) => {
            const cls = m.dofusClass ? getClass(m.dofusClass) : null;
            const isActive = m.status === "ACTIVE";
            const isMe = m.pseudoDofus === currentPseudo;
            return (
              <div
                key={m.id}
                className="flex items-center gap-1 px-2 py-1 rounded-lg bg-zinc-800/50 border border-zinc-700/40 text-[8px] font-bold text-zinc-200"
                title={`${m.pseudoDofus} • ${cls?.name || "?"}${!isActive ? " • AFK" : ""}${m.locationDesc ? ` • ${m.locationDesc}` : ""}`}
              >
                <div className={`w-1.5 h-1.5 rounded-full flex-shrink-0 ${isActive ? "bg-emerald-400" : "bg-amber-400/60"}`} />
                {cls && (
                  <img src={cls.icon} alt="" className="w-3 h-3 object-contain" />
                )}
                <span className="truncate max-w-[50px]">{m.pseudoDofus}</span>
                {!isActive && (
                  <Clock className="w-2 h-2 text-amber-400/60" />
                )}
                {isMe && <span className="text-emerald-400 ml-0.5">(toi)</span>}
              </div>
            );
          })}
          {totalCount > 6 && (
            <span className="text-[8px] font-black text-zinc-500">+{totalCount - 6}</span>
          )}
        </div>
      ) : (
        <p className="text-[9px] text-zinc-600 italic px-1">Aucun membre pour l'instant</p>
      )}
    </div>
  );
});

"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { User, Users, CheckCircle, ArrowRight, ArrowLeft, Shield, Sparkles, ExternalLink } from "lucide-react";
