                      </div>
                    </div>
                  )}

                  {/* Stats Card */}
                  <div className="bg-slate-950/30 border border-white/5 rounded-xl p-3 shadow-xl">
                    <div className="flex items-center justify-between mb-2.5 border-b border-white/5 pb-1.5">
                      <span className="text-[8px] font-black text-zinc-500 uppercase tracking-widest">Stats Boss</span>
                      <div className="flex gap-0.5">
                        {bossStats?.grades?.map((_: any, i: number) => (
                          <button
                            key={i}
                            onClick={() => setSelectedGrade(i)}
                            className={`w-3.5 h-3.5 rounded text-[7px] font-black flex items-center justify-center transition-all border ${
                              selectedGrade === i
                                ? "bg-indigo-600 border-indigo-500 text-white"
                                : "bg-white/5 border-white/5 text-slate-500 hover:text-slate-300"
                            }`}
                          >
                            {i + 1}
                          </button>
                        ))}
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-1.5 text-[9px]">
                      <div className="bg-black/30 p-1.5 rounded-lg border border-white/5">
                        <span className="text-[7px] font-bold text-zinc-600 uppercase block">Vie</span>
                        <span className="text-white font-black">{bossStats?.grades[selectedGrade]?.lifePoints?.toLocaleString() || "---"}</span>
                      </div>
                      <div className="bg-black/30 p-1.5 rounded-lg border border-white/5">
                        <span className="text-[7px] font-bold text-zinc-600 uppercase block">PA | PM</span>
                        <span className="text-white font-black">{bossStats ? `${bossStats.grades[selectedGrade]?.actionPoints} | ${bossStats.grades[selectedGrade]?.movementPoints}` : "---"}</span>
                      </div>
                      <div className="bg-black/30 p-2 rounded-lg border border-white/5 col-span-2">
                        <div className="flex justify-between items-center gap-1">
                          <StatResist label="N" value={bossStats?.grades[selectedGrade]?.resists.neutral} color="bg-zinc-500/20" border="border-zinc-500/20" text="text-zinc-400" />
                          <StatResist label="T" value={bossStats?.grades[selectedGrade]?.resists.earth} color="bg-orange-500/20" border="border-orange-500/20" text="text-orange-400" />
                          <StatResist label="F" value={bossStats?.grades[selectedGrade]?.resists.fire} color="bg-red-500/20" border="border-red-500/20" text="text-red-400" />
                          <StatResist label="E" value={bossStats?.grades[selectedGrade]?.resists.water} color="bg-blue-500/20" border="border-blue-500/20" text="text-blue-400" />
                          <StatResist label="A" value={bossStats?.grades[selectedGrade]?.resists.air} color="bg-emerald-400/20" border="border-emerald-400/20" text="text-emerald-400" />
                        </div>
                      </div>
                    </div>
                  </div>

                  {onCreatePost && (
                    <Button
                      onClick={() => onCreatePost(selectedDungeon.id)}
                      className="w-full bg-indigo-600 hover:bg-indigo-500 text-white font-black py-3 rounded-lg shadow-lg shadow-indigo-950/20 transition-all hover:scale-[1.01] active:scale-95 text-[10px] uppercase tracking-wider"
                    >
                      <Users className="w-3 h-3 mr-2" />
                      Créer un groupe
                    </Button>
                  )}
                </div>
              </div>
            </div>

            {/* Directory Content */}
            {loadingDir ? (
              <div className="flex flex-col items-center justify-center py-16 text-slate-500 animate-pulse bg-slate-900/30 rounded-3xl border border-slate-800/50">
                <Search className="w-8 h-8 mb-3 opacity-50" />
                <p>Analyse des succès de la guilde...</p>
              </div>
            ) : filteredDirectory.length === 0 ? (
              <div className="bg-amber-500/10 border border-amber-500/20 rounded-2xl p-6 text-center text-amber-200/80">
                <Info className="w-8 h-8 mx-auto mb-2 opacity-60 text-amber-500" />
                <p>Ce donjon ne possède aucun succès recensé dans la base.</p>
              </div>
            ) : (
              <div className="space-y-6">
                {/* Member Search + Sort */}
                <div className="flex items-center gap-2 ml-auto">
                  <div className="relative w-64">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                    <input
                      type="text"
                      value={memberSearch}
                      onChange={(e) => setMemberSearch(e.target.value)}
                      placeholder="Chercher un membre…"
                      className="w-full bg-slate-900 border border-white/5 rounded-xl pl-10 pr-4 py-2 text-sm text-white placeholder:text-slate-500 focus:outline-none focus:ring-1 focus:ring-indigo-500/50 shadow-inner h-10 transition-all"
                    />
                  </div>
                  <button
                    onClick={() => setSortMode(m => m === "pseudo" ? "classe" : "pseudo")}
                    title={sortMode === "pseudo" ? "Trier par classe" : "Trier par pseudo"}
                    className={`flex items-center gap-1.5 px-3 h-10 rounded-xl border text-[11px] font-black uppercase tracking-wider transition-all ${
                      sortMode === "classe"
                        ? "bg-indigo-500/20 border-indigo-500/30 text-indigo-300"
                        : "bg-white/5 border-white/5 text-slate-400 hover:bg-white/10 hover:text-white"
                    }`}
                  >
                    <ArrowUpDown className="w-3.5 h-3.5" />
                    {sortMode === "classe" ? "Classe" : "Pseudo"}
                  </button>
                </div>

                {filteredDirectory.map((achv) => {
                  const isExpanded = expandedAchv === achv.achievementId;
                  const totalMembers =
                    achv.hasCompleted.length + achv.missing.length;
                  const completionRate =
                    totalMembers > 0
                      ? Math.round(
                          (achv.hasCompleted.length / totalMembers) * 100,
                        )
                      : 0;

                  return (
                    <div
                      key={achv.achievementId}
                      className={`group/card rounded-2xl transition-all duration-300 overflow-hidden border ${
                        isExpanded
                          ? "bg-slate-900/90 border-indigo-500/30 shadow-[0_0_30px_rgba(99,102,241,0.08)]"
                          : "bg-slate-900/30 border-white/5 hover:border-white/12 hover:bg-slate-900/50 hover:shadow-lg shadow-sm"
                      }`}
                    >
                      <button
                        onClick={() =>
                          setExpandedAchv(
                            isExpanded ? null : achv.achievementId,
                          )
                        }
                        className="w-full flex flex-col md:flex-row md:items-center justify-between p-4 md:p-5 gap-4 text-left focus:outline-none"
                      >
                        <div className="flex items-center gap-4 flex-1 min-w-0">
                          <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 border shadow-inner transition-all duration-300 ${
                            isExpanded
                              ? "bg-indigo-600/10 border-indigo-500/30"
                              : "bg-slate-900 border-white/5 group-hover/card:scale-105"
                          }`}>
                            {achv.iconUrl ? (
                              <img
                                src={achv.iconUrl}
                                alt=""
                                className="w-8 h-8 object-contain"
                              />
                            ) : (
                              <Trophy className="w-6 h-6 text-indigo-400" />
                            )}
                          </div>
                          <div className="min-w-0">
                            <h4 className="text-base font-extrabold text-white leading-snug tracking-tight">
                              {achv.achievementName}
                            </h4>
                            <div className="flex items-center gap-2 mt-1">
                              {completionRate === 100 ? (
                                <span className="inline-flex items-center text-[10px] font-black uppercase tracking-wider px-2 py-0.5 rounded-md bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                                  Terminé
                                </span>
                              ) : completionRate > 0 ? (
                                <span className="inline-flex items-center text-[10px] font-black uppercase tracking-wider px-2 py-0.5 rounded-md bg-indigo-500/10 text-indigo-400 border border-indigo-500/20">
                                  En Cours
                                </span>
                              ) : (
                                <span className="inline-flex items-center text-[10px] font-black uppercase tracking-wider px-2 py-0.5 rounded-md bg-slate-800 text-slate-400 border border-slate-700/50">
                                  Non Commencé
                                </span>
                              )}
                              <span className="text-xs text-slate-400">
                                {achv.hasCompleted.length} / {totalMembers} membres
                              </span>
                            </div>
                          </div>
                        </div>

                        {/* Progress Bar */}
                        <div className="flex flex-col gap-1 w-full md:w-48 shrink-0">
                          <div className="flex items-center justify-between text-[10px] font-black uppercase tracking-wider text-slate-400">
                            <span>Progression</span>
                            <span className={completionRate === 100 ? "text-emerald-400 font-extrabold" : "text-indigo-400 font-extrabold"}>{completionRate}%</span>
                          </div>
                          <div className="w-full h-2 bg-black/40 rounded-full overflow-hidden border border-white/5 shadow-inner relative">
                            <div
                              className={`h-full rounded-full transition-all duration-500 ${
                                completionRate === 100
                                  ? "bg-gradient-to-r from-emerald-500 to-teal-500 shadow-[0_0_8px_rgba(16,185,129,0.4)]"
                                  : completionRate > 0
                                  ? "bg-gradient-to-r from-indigo-500 to-violet-500 shadow-[0_0_8px_rgba(99,102,241,0.4)]"
                                  : "bg-slate-850"
                              }`}
                              style={{ width: `${completionRate}%` }}
                            />
                          </div>
                        </div>

                        <div className="flex items-center justify-between md:justify-end gap-4 shrink-0 mt-2 md:mt-0 border-t border-white/5 pt-2.5 md:pt-0 md:border-none">
                          {/* Avatars Preview */}
                          {!isExpanded && achv.missing.length > 0 && (
                            <div className="flex -space-x-2">
                              {achv.missing.slice(0, 4).map((m, i) => (
                                <div
                                  key={i}
                                  className="w-7 h-7 rounded-full border-2 border-slate-900 bg-slate-850 overflow-hidden relative shadow-md"
                                  title={`${m.name} cherche encore`}
                                >
                                  {m.imageUrl ? (
                                    <img
                                      src={m.imageUrl}
                                      alt=""
                                      className="w-full h-full object-cover"
                                    />
                                  ) : (
                                    <Users className="w-3 h-3 m-1.5 text-slate-500" />
                                  )}
                                </div>
                              ))}
                              {achv.missing.length > 4 && (
                                <div className="w-7 h-7 rounded-full border-2 border-slate-900 bg-slate-800 flex items-center justify-center text-[9px] font-bold text-slate-400 z-10 shadow-md">
                                  +{achv.missing.length - 4}
                                </div>
                              )}
                            </div>
                          )}

                          <div
                            className={`w-8 h-8 rounded-full flex items-center justify-center transition-all ${
                              isExpanded
                                ? "bg-indigo-500/20 text-indigo-300 shadow-[0_0_8px_rgba(99,102,241,0.2)]"
                                : "bg-white/5 text-slate-400 border border-white/5 hover:bg-white/10"
                            }`}
                          >
                            <ChevronDown
                              className={`w-4 h-4 transition-transform duration-300 ${isExpanded ? "rotate-180" : ""}`}
                            />
                          </div>
                        </div>
                      </button>

                      <AnimatePresence>
                        {isExpanded && (
                          <motion.div
                            initial={{ height: 0, opacity: 0 }}
                            animate={{ height: "auto", opacity: 1 }}
                            exit={{ height: 0, opacity: 0 }}
                            className="overflow-hidden border-t border-white/5"
                          >
                            <div className="p-5 md:p-8 grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8 bg-slate-950/20 shadow-inner">
                              {/* Col 1: MISSING */}
                              <div className="bg-slate-950/40 border border-rose-500/10 rounded-2xl p-5 shadow-[inset_0_1px_4px_rgba(244,63,94,0.05)]">
                                <div className="flex items-center justify-between mb-4 pb-3 border-b border-slate-800/60">
                                  <div className="flex items-center gap-2 font-bold text-sm">
                                    <div className="w-6 h-6 rounded-lg bg-rose-500/10 border border-rose-500/20 flex items-center justify-center">
                                      <Circle className="w-3.5 h-3.5 text-rose-400" />
                                    </div>
                                    <span className="text-rose-300">
                                      Cherchent encore
                                    </span>
                                  </div>
                                  <span className="text-xs font-black bg-rose-500/10 text-rose-400 px-2 py-0.5 rounded-full border border-rose-500/20">
                                    {achv.missing.length}
                                  </span>
                                </div>

                                {achv.missing.length > 0 ? (
                                  <div className="grid grid-cols-[repeat(auto-fill,minmax(140px,1fr))] gap-2 max-h-[320px] overflow-y-auto pr-2 custom-scrollbar">
                                    {achv.missing.map((member) => (
                                      <MemberPill
                                        key={member.id}
                                        member={member}
                                        variant="missing"
                                      />
                                    ))}
                                  </div>
                                ) : (
                                  <p className="text-sm text-slate-500 italic text-center py-4">
                                    Tout le monde a validé ce succès ! 🎉
                                  </p>
                                )}
                              </div>

                              {/* Col 2: HAS COMPLETED */}
                              <div className="bg-slate-950/40 border border-emerald-500/10 rounded-2xl p-5 shadow-[inset_0_1px_4px_rgba(16,185,129,0.05)]">
                                <div className="flex items-center justify-between mb-4 pb-3 border-b border-slate-800/60">
                                  <div className="flex items-center gap-2 font-bold text-sm">
                                    <div className="w-6 h-6 rounded-lg bg-emerald-500/10 border border-emerald-500/20 shadow-inner flex items-center justify-center">
                                      <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" />
                                    </div>
                                    <span className="text-emerald-300">
                                      Déjà validé
                                    </span>
                                  </div>
                                  <span className="text-xs font-black bg-emerald-500/10 text-emerald-400 px-2 py-0.5 rounded-full border border-emerald-500/20">
                                    {achv.hasCompleted.length}
                                  </span>
                                </div>

                                {achv.hasCompleted.length > 0 ? (
                                  <div className="grid grid-cols-[repeat(auto-fill,minmax(140px,1fr))] gap-2 max-h-[320px] overflow-y-auto pr-2 custom-scrollbar">
                                    {achv.hasCompleted.map((member) => (
                                      <MemberPill
                                        key={member.id}
                                        member={member}
                                        variant="completed"
                                      />
                                    ))}
                                  </div>
                                ) : (
                                  <p className="text-sm text-slate-600 italic text-center py-4">
                                    Personne n'a encore validé ce succès.
                                  </p>
                                )}
                              </div>
                            </div>
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </div>
                  );
                })}
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Drop Modal */}
      <AnimatePresence>
        {selectedDrop && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setSelectedDrop(null)}
              className="absolute inset-0 bg-black/80 backdrop-blur-sm"
            />
            <motion.div
              initial={{ opacity: 0, scale: 0.9, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.9, y: 20 }}
              className="relative w-full max-w-[320px] bg-zinc-900 border border-white/10 rounded-2xl overflow-hidden shadow-2xl"
            >
              <div className="p-6 flex flex-col items-center text-center space-y-4">
                <div className="w-20 h-20 rounded-2xl bg-black/40 border border-white/5 flex items-center justify-center p-3 shadow-inner relative overflow-hidden group">
                   <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/10 to-transparent opacity-50" />
                   <img src={selectedDrop.imageUrl} alt={selectedDrop.name} className="w-full h-full object-contain relative z-10 drop-shadow-md" />
                </div>
                
                <div>
                  <h3 className="text-lg font-black text-white leading-tight mb-1">{selectedDrop.name}</h3>
                  <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 text-[10px] font-black uppercase tracking-wider">
                    Taux de drop : {selectedDrop.percent}%
                  </div>
                </div>

                <div className="w-full grid grid-cols-2 gap-2 pt-2">
                  <button 
                    onClick={() => setSelectedDrop(null)}
                    className="px-4 py-2.5 rounded-xl border border-white/5 bg-white/5 text-slate-400 text-xs font-bold hover:bg-white/10 hover:text-white transition-all"
                  >
                    Fermer
                  </button>
                  <a 
                    href={`https://dofusdb.fr/fr/database/item/${selectedDrop.objectId}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="px-4 py-2.5 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-black flex items-center justify-center gap-2 shadow-lg shadow-indigo-900/20 transition-all active:scale-95"
                  >
                    DofusDB <ExternalLink className="w-3.5 h-3.5" />
                  </a>
                </div>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

function MemberPill({
  member,
  variant,
}: {
  member: any;
  variant: "missing" | "completed";
}) {
  const isMissing = variant === "missing";
  const cls = member.classe ? getClass(member.classe) : null;

  return (
    <div
      className={`group flex items-center justify-between p-2 rounded-xl border transition-all duration-200 ${
        isMissing
          ? "bg-slate-950/40 hover:bg-slate-900/80 border-rose-500/10 hover:border-rose-500/30 text-rose-100 shadow-[0_2px_8px_rgba(244,63,94,0.02)]"
          : "bg-emerald-950/20 hover:bg-emerald-900/30 border-emerald-500/10 hover:border-emerald-500/30 text-emerald-100 shadow-[0_2px_8px_rgba(16,185,129,0.02)]"
      }`}
    >
      <div className="flex items-center gap-2.5 min-w-0">
        <div
          className={`w-7 h-7 rounded-lg overflow-hidden shrink-0 border transition-transform duration-200 group-hover:scale-105 ${
            isMissing
              ? "border-rose-500/20 bg-rose-950/30"
              : "border-emerald-500/20 bg-emerald-950/30"
          } flex items-center justify-center`}
        >
          {member.imageUrl ? (
            <img
              src={member.imageUrl}
              alt={member.name}
              className="w-full h-full object-cover"
            />
          ) : (
            <Users className={`w-3.5 h-3.5 ${isMissing ? "text-rose-400/60" : "text-emerald-400/60"}`} />
          )}
        </div>

        <div className="flex flex-col min-w-0">
          <span className="text-xs font-bold truncate text-slate-100 leading-tight">
            {member.name}
          </span>
          {member.classe && (
            <span className="text-[10px] text-slate-400 font-medium truncate capitalize">
              {member.classe}
            </span>
          )}
        </div>
      </div>

      {cls && (
        <div className="shrink-0 pl-1.5 flex items-center">
          <img
            src={cls.icon}
            alt={member.classe}
            className={`w-5 h-5 object-contain transition-all duration-300 group-hover:scale-110 ${
              isMissing
                ? "drop-shadow-[0_0_4px_rgba(244,63,94,0.2)] opacity-80 group-hover:opacity-100"
                : "drop-shadow-[0_0_4px_rgba(16,185,129,0.2)] opacity-80 group-hover:opacity-100"
            }`}
            title={member.classe}
          />
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useCallback, useMemo, useTransition, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { io } from "socket.io-client";
import { buildWsUrl } from "@/lib/socket-utils";
import { Plus, Search, Trophy, Sword, RefreshCw, Frown, Users, AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { DjPostCard } from "./DjPostCard";
import { DjPostCreateModal } from "./DjPostCreateModal";
import { DjFiltersBar, type DjFiltersState } from "./DjFiltersBar";
import { AchievementTracker } from "./AchievementTracker";
import { DungeonDirectory } from "./DungeonDirectory";
import type { DjPostWithDetails } from "@/server/actions/dungeon-finder-actions";

const DEFAULT_FILTERS: DjFiltersState = {
    search: "",
    mode: "",
    minLevel: 1,
    maxLevel: 1000,
    showClosed: false,
    onlyWithAchievement: false,
    onlyWithSpots: false,
};

type Tab = "posts" | "tracker" | "directory";

interface DungeonFinderClientProps {
    guildId: string;
    initialPosts: DjPostWithDetails[];
    currentProfileId?: string;
    isAdmin?: boolean;
    // Server action bound at page level
    refreshPosts: () => Promise<DjPostWithDetails[]>;
    isDiscordConfigured?: boolean;
}

export function DungeonFinderClient({
    guildId,
    initialPosts,
    currentProfileId,
    isAdmin,
    refreshPosts,
    isDiscordConfigured,
}: DungeonFinderClientProps) {
    const [activeTab, setActiveTab] = useState<Tab>("posts");
    const [posts, setPosts] = useState<DjPostWithDetails[]>(initialPosts);
    const [isCreateOpen, setIsCreateOpen] = useState(false);
    const [filters, setFilters] = useState<DjFiltersState>(DEFAULT_FILTERS);
    const [isRefreshing, setIsRefreshing] = useState(false);
    const [initialDungeonId, setInitialDungeonId] = useState<string | undefined>(undefined);

    function handleCreateGroupDirect(dungeonId: string) {
        setInitialDungeonId(dungeonId);
        setIsCreateOpen(true);
    }

    async function handleRefresh() {
        setIsRefreshing(true);
        try {
            const fresh = await refreshPosts();
            setPosts(fresh);
        } catch {
            // Silently fail
        } finally {
            setIsRefreshing(false);
        }
    }

    // Real-time updates via WebSocket
    useEffect(() => {
        const socketUrl = buildWsUrl();
        const socket = io(socketUrl, {
            path: "/socket.io/",
            query: { guildId }
        });

        socket.on("connect", () => {
            console.log("[WS] 📡 Connecté pour Dungeon Finder");
        });

        socket.on("dj:finder:update", (data: any) => {
            console.log("[WS] 🔄 Update DJ reçu", data);
            handleRefresh();
        });

        return () => {
            socket.disconnect();
        };
    }, [guildId]);

    // Client-side filter
    const filteredPosts = useMemo(() => {
        const term = filters.search.toLowerCase();
        return posts.filter((p) => {
            if (!filters.showClosed && (p.status === "CLOSED" || p.status === "EXPIRED")) return false;
            if (filters.mode && p.mode !== filters.mode) return false;
            if (term) {
                const dName = p.dungeon?.name.toLowerCase() || "";
                const dBoss = p.dungeon?.bossName.toLowerCase() || "";
                const qName = p.questName?.toLowerCase() || "";
                if (!dName.includes(term) && !dBoss.includes(term) && !qName.includes(term)) return false;
            }
            if (p.dungeon) {
                if (p.dungeon.level < filters.minLevel || p.dungeon.level > filters.maxLevel) return false;
            }
            if (filters.onlyWithSpots) {
                const accepted = (p._acceptedCount ?? 0) + 1;
                if (accepted >= p.maxMembers) return false;
            }
            if (filters.onlyWithAchievement) {
                if (!p.wantedAchievementIds || p.wantedAchievementIds.length === 0) return false;
            }
            return true;
        });
    }, [posts, filters]);


    const myActivePosts = posts.filter((p) => p.profileId === currentProfileId && p.status === "OPEN");
    const canCreate = myActivePosts.length < 3;

    const TABS: { id: Tab; label: string; sub: string; icon: React.ElementType; color: "indigo" | "amber" | "emerald" }[] = [
        { id: "posts", label: "Recherche DJ", sub: "Trouver un groupe", icon: Search, color: "indigo" },
        { id: "tracker", label: "Mes Succès", sub: "Ma progression", icon: Trophy, color: "amber" },
        { id: "directory", label: "Succès Commun", sub: "La guilde", icon: Users, color: "emerald" },
    ];

    return (
        <div className="space-y-8">
            {/* Dissociated Professional Tabs */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                {TABS.map((tab) => {
                    const Icon = tab.icon;
                    const isActive = activeTab === tab.id;
                    const colorVariants = {
                        indigo: {
                            border: "border-indigo-500/50",
                            icon: "bg-indigo-500/15 border-indigo-500/30 text-indigo-400",
                            sub: "text-indigo-300",
                            glow: "bg-indigo-500",
                            shadow: "shadow-[0_0_20px_rgba(99,102,241,0.35)]",
                            inactiveIcon: "bg-indigo-500/8 border-indigo-500/15 text-indigo-400",
                            inactiveSub: "text-indigo-400/70",
                            inactiveBorder: "border-indigo-500/20"
                        },
                        amber: {
                            border: "border-amber-500/50",
                            icon: "bg-amber-500/15 border-amber-500/30 text-amber-400",
                            sub: "text-amber-300",
                            glow: "bg-amber-500",
                            shadow: "shadow-[0_0_20px_rgba(245,158,11,0.35)]",
                            inactiveIcon: "bg-amber-500/8 border-amber-500/15 text-amber-400",
                            inactiveSub: "text-amber-400/70",
                            inactiveBorder: "border-amber-500/20"
                        },
                        emerald: {
                            border: "border-emerald-500/50",
                            icon: "bg-emerald-500/15 border-emerald-500/30 text-emerald-400",
                            sub: "text-emerald-300",
                            glow: "bg-emerald-500",
                            shadow: "shadow-[0_0_20px_rgba(16,185,129,0.35)]",
                            inactiveIcon: "bg-emerald-500/8 border-emerald-500/15 text-emerald-400",
                            inactiveSub: "text-emerald-400/70",
                            inactiveBorder: "border-emerald-500/20"
                        }
                    }[tab.color];

                    return (
                        <motion.button
                            key={tab.id}
                            whileHover={{ scale: 1.02, y: -2 }}
                            whileTap={{ scale: 0.98 }}
                            onClick={() => setActiveTab(tab.id)}
                            className={cn(
                                "relative group overflow-hidden flex items-center gap-4 p-5 rounded-2xl border transition-all duration-300",
                                isActive
                                    ? cn("bg-zinc-800/90 z-10 shadow-2xl", colorVariants.border, colorVariants.shadow)
                                    : cn("bg-zinc-900/70 hover:bg-zinc-800/70", colorVariants.inactiveBorder)
                            )}
                        >
                            {/* Animated Background Glow */}
                            <AnimatePresence>
                                {isActive && (
                                    <motion.div
                                        initial={{ opacity: 0 }}
                                        animate={{ opacity: 1 }}
                                        exit={{ opacity: 0 }}
                                        className={cn(
                                            "absolute inset-0 bg-gradient-to-br opacity-[0.03] pointer-events-none",
                                            tab.color === 'indigo' ? 'from-indigo-500 to-transparent' :
                                            tab.color === 'amber' ? 'from-amber-500 to-transparent' :
                                            'from-emerald-500 to-transparent'
                                        )}
                                    />
                                )}
                            </AnimatePresence>

                            {/* Top Indicator */}
                            {isActive && (
                                <motion.div 
                                    layoutId="active-pill"
                                    className={cn(
                                        "absolute top-0 inset-x-0 h-[2px] z-20",
                                        tab.color === 'indigo' ? 'bg-indigo-500' :
                                        tab.color === 'amber' ? 'bg-amber-500' :
                                        'bg-emerald-500'
                                    )}
                                    style={{ 
                                        boxShadow: `0 0 15px ${tab.color === 'indigo' ? 'rgba(99,102,241,0.5)' : 
                                                     tab.color === 'amber' ? 'rgba(245,158,11,0.5)' : 
                                                     'rgba(16,185,129,0.5)'}` 
                                    }}
                                />
                            )}

                            {/* Icon Box */}
                            <div className={cn(
                                "w-12 h-12 rounded-xl flex items-center justify-center shrink-0 border transition-all duration-500 relative overflow-hidden",
                                isActive
                                    ? colorVariants.icon + " shadow-lg"
                                    : colorVariants.inactiveIcon + " group-hover:brightness-125"
                            )}>
                                {isActive && (
                                    <div className={cn(
                                        "absolute inset-0 opacity-20 bg-gradient-to-br",
                                        tab.color === 'indigo' ? 'from-indigo-400 to-indigo-700' :
                                        tab.color === 'amber' ? 'from-amber-400 to-amber-700' :
                                        'from-emerald-400 to-emerald-700'
                                    )} />
                                )}
                                <Icon className={cn("w-5 h-5 relative z-10", isActive ? "scale-110" : "scale-100 transition-transform duration-500 group-hover:scale-110")} />
                            </div>

                            {/* Labels */}
                            <div className="text-left relative z-10">
                                <p className={cn(
                                    "font-black text-[10px] uppercase tracking-[0.25em] transition-colors duration-500",
                                    isActive ? "text-white" : "text-zinc-300 group-hover:text-white"
                                )}>
                                    {tab.label}
                                </p>
                                <p className={cn(
                                    "text-[11px] font-bold mt-1 transition-colors duration-500",
                                    isActive ? colorVariants.sub : colorVariants.inactiveSub + " group-hover:" + colorVariants.sub
                                )}>
                                    {tab.sub}
                                </p>
                            </div>

                            {/* Corner Accent */}
                            {isActive && (
                                <div className={cn(
                                    "absolute -bottom-6 -right-6 w-20 h-20 blur-3xl rounded-full opacity-20",
                                    colorVariants.glow
                                )} />
                            )}
                        </motion.button>
                    );
                })}
            </div>

            <div>
                {/* === POSTS TAB === */}
                {activeTab === "posts" && (
                    <div className="space-y-5 animate-in fade-in slide-in-from-bottom-2 duration-300">
                        {/* Toolbar */}
                        <div className="flex flex-col xl:flex-row xl:items-start gap-4">
                            <div className="flex-1">
                                <DjFiltersBar
                                    filters={filters}
                                    onChange={setFilters}
                                    total={posts.filter((p) => p.status === "OPEN" || p.status === "FULL").length}
                                    filtered={filteredPosts.length}
                                />
                            </div>

                            <div className="flex items-center gap-2 shrink-0">
                                <Button
                                    variant="outline" size="icon"
                                    onClick={handleRefresh}
                                    disabled={isRefreshing}
                                    className="w-10 h-10 border-slate-700 text-slate-400 hover:text-white"
                                    title="Rafraîchir"
                                >
                                    <RefreshCw className={`w-4 h-4 ${isRefreshing ? "animate-spin" : ""}`} />
                                </Button>
                                <Button
                                    onClick={() => setIsCreateOpen(true)}
                                    disabled={!canCreate}
                                    title={canCreate ? "Créer un post" : "Tu as atteint la limite de 3 posts actifs"}
                                    className={`font-black h-10 gap-2 shadow-lg ${canCreate
                                        ? "bg-white hover:bg-zinc-200 text-zinc-900 shadow-white/5"
                                        : "bg-zinc-800/50 text-zinc-500 border border-white/5 cursor-not-allowed opacity-70"
                                        }`}
                                >
                                    {canCreate ? (
                                        <Plus className="w-4 h-4" />
                                    ) : (
                                        <AlertTriangle className="w-4 h-4" />
                                    )}
                                    Nouveau post
                                    {!canCreate && (
                                        <span className="ml-1 text-xs font-bold bg-amber-500/20 px-1.5 py-0.5 rounded">
                                            {myActivePosts.length}/3
                                        </span>
                                    )}
                                </Button>
                            </div>
                        </div>

                        {/* Anti-spam hint */}
                        {!canCreate && (
                            <div className="flex items-center gap-3 text-sm text-amber-400 bg-amber-500/8 border border-amber-500/20 rounded-xl px-4 py-3">
                                <AlertTriangle className="w-4 h-4 shrink-0" />
                                <span>
                                    Tu as <strong>{myActivePosts.length}/3</strong> posts actifs.{" "}
                                    <button
                                        onClick={() => setFilters({ ...DEFAULT_FILTERS, search: "" })}
                                        className="underline underline-offset-2 hover:text-amber-300 transition-colors"
                                    >
                                        Ferme ou expire un post existant
                                    </button>{" "}
                                    pour en créer un nouveau.
                                </span>
                            </div>
                        )}

                        {/* Posts grid */}
                        {filteredPosts.length === 0 ? (
                            <motion.div
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                className="flex flex-col items-center justify-center min-h-[320px] border border-dashed border-white/10 rounded-2xl bg-zinc-950/50 shadow-inner"
                            >
                                <div className="w-14 h-14 rounded-2xl bg-slate-900 border border-white/10 shadow-sm flex items-center justify-center mb-4">
                                    <Search className="w-6 h-6 text-slate-500" />
                                </div>
                                <h3 className="text-base font-bold text-slate-300 mb-1">Aucun post actif</h3>
                                <p className="text-sm text-slate-600 text-center max-w-xs">
                                    {filters.search || filters.mode
                                        ? "Modifie les filtres pour voir plus de posts."
                                        : "Sois le premier à créer un post de recherche de groupe !"}
                                </p>
                                {canCreate && (
                                    <Button
                                        className="mt-5 bg-white hover:bg-zinc-200 text-zinc-900 font-bold"
                                        onClick={() => setIsCreateOpen(true)}
                                    >
                                        <Plus className="w-4 h-4 mr-2" /> Créer un post
                                    </Button>
                                )}
                            </motion.div>
                        ) : (
                            <motion.div
                                layout
                                className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4"
                            >
                                <AnimatePresence>
                                    {filteredPosts.map((post) => (
                                        <DjPostCard
                                            key={post.id}
                                            post={post}
                                            guildId={guildId}
                                            currentProfileId={currentProfileId}
                                            isAdmin={isAdmin}
                                            onRefresh={handleRefresh}
                                            isDiscordConfigured={isDiscordConfigured}
                                        />
                                    ))}
                                </AnimatePresence>
                            </motion.div>
                        )}
                    </div>
                )}

                {/* === TRACKER TAB === */}
                {activeTab === "tracker" && (
                    <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                        <AchievementTracker guildId={guildId} />
                    </div>
                )}

                {/* === DIRECTORY TAB === */}
                {activeTab === "directory" && (
                    <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                        <DungeonDirectory guildId={guildId} onCreatePost={handleCreateGroupDirect} />
                    </div>
                )}
            </div>

            {/* Create modal */}
            <DjPostCreateModal
                guildId={guildId}
                isOpen={isCreateOpen}
                initialDungeonId={initialDungeonId}
                isDiscordConfigured={isDiscordConfigured}
                onClose={() => {
                    setIsCreateOpen(false);
                    setInitialDungeonId(undefined);
                }}
                onCreated={handleRefresh}
            />
        </div>
    );
}

"use client";

import { useEditor, EditorContent } from "@tiptap/react";
import { BubbleMenu } from "@tiptap/react/menus";
import StarterKit from "@tiptap/starter-kit";
import Link from "@tiptap/extension-link";
import Placeholder from "@tiptap/extension-placeholder";
import Typography from "@tiptap/extension-typography";
import { Color } from "@tiptap/extension-color";
import { TextStyle } from "@tiptap/extension-text-style";
import { useEffect, useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { configureSlashCommand } from "./extensions/slash-command";
import { ResizableImage } from "./extensions/resizable-image";
import { uploadImageFile } from "./utils/image-upload";
import { Callout } from "./extensions/callout";
import {
    Bold,
    Italic,
    Strikethrough,
    Code,
    List,
    ListOrdered,
    Quote,
    Heading1,
    Heading2,
    Heading3,
    Undo,
    Redo,
    Smile,
    AlignLeft,
    AlignCenter,
    AlignRight,
    Palette,
    Image as ImageIcon
} from "lucide-react";
import { Button } from "@/components/ui/button";
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from "@/components/ui/popover";
import { EmojiPicker } from "./emoji-picker";

interface AdvancedEditorProps {
    initialContent?: string;
    onChange: (content: string) => void;
    editable?: boolean;
    contentClassName?: string;
}

export function AdvancedEditor({ initialContent, onChange, editable = true, contentClassName }: AdvancedEditorProps) {
    // Force re-render on selection change to update toolbar state
    const [, forceUpdate] = useState(0);

    const editor = useEditor({
        immediatelyRender: false,
        extensions: [
            StarterKit.configure({
                heading: {
                    levels: [1, 2, 3],
                },
                // Prevent duplicate with standalone Link extension
                link: false,
            }),
            ResizableImage.configure({
                inline: true,
                allowBase64: true,
            }),
            Link.configure({
                openOnClick: false,
                HTMLAttributes: {
                    class: "text-primary underline decoration-primary/50 underline-offset-4 hover:decoration-primary transition-colors cursor-pointer",
                },
            }),
            Placeholder.configure({
                placeholder: "Tapez '/' pour les commandes ou commencez à écrire...",
            }),
            Typography,
            configureSlashCommand(),
            Callout,
            TextStyle,
            Color,
        ],
        content: initialContent,
        editable,
        editorProps: {
            attributes: {
                class: cn(
                    "prose prose-zinc dark:prose-invert max-w-none focus:outline-none min-h-[300px] px-4 py-2",
                    contentClassName
                ),
            },
            handlePaste: (view, event) => {
                const items = event.clipboardData?.items;
                if (!items) return false;

                for (const item of Array.from(items)) {
                    if (item.type.startsWith("image/")) {
                        event.preventDefault();
                        const file = item.getAsFile();
                        if (file) {
                            uploadImageFile(file).then((url) => {
                                if (url && editor) {
                                    editor.chain().focus().setImage({ src: url }).run();
                                }
                            });
                        }
                        return true;
                    }
                }
                return false;
            },
            handleDrop: (view, event) => {
                const files = event.dataTransfer?.files;
                if (!files?.length) return false;

                const imageFile = Array.from(files).find(f => f.type.startsWith("image/"));
                if (imageFile) {
                    event.preventDefault();
                    uploadImageFile(imageFile).then((url) => {
                        if (url && editor) {
                            editor.chain().focus().setImage({ src: url }).run();
                        }
                    });
                    return true;
                }
                return false;
            },
        },
        onUpdate: ({ editor }) => {
            onChange(editor.getHTML());
        },
        onSelectionUpdate: () => {
            forceUpdate(n => n + 1);
        }
    });

    if (!editor) {
        return null;
    }

    return (
        <div className="relative border border-white/10 rounded-2xl bg-zinc-950/50 flex flex-col h-full overflow-hidden shadow-2xl">
            {/* TOOLBAR (Sticky at top of editor) */}
            {editable && (
                <div className="flex items-center gap-1 p-2 border-b border-white/5 bg-zinc-900/95 backdrop-blur-md flex-wrap z-20">
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleBold().run()}
                        isActive={editor.isActive("bold")}
                        icon={Bold}
                        tooltip="Gras (Ctrl+B)"
                    />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleItalic().run()}
                        isActive={editor.isActive("italic")}
                        icon={Italic}
                        tooltip="Italique (Ctrl+I)"
                    />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleStrike().run()}
                        isActive={editor.isActive("strike")}
                        icon={Strikethrough}
                        tooltip="Barré"
                    />
                    <div className="w-px h-6 bg-white/10 mx-1" />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleHeading({ level: 1 }).run()}
                        isActive={editor.isActive("heading", { level: 1 })}
                        icon={Heading1}
                        tooltip="Titre 1"
                    />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleHeading({ level: 2 }).run()}
                        isActive={editor.isActive("heading", { level: 2 })}
                        icon={Heading2}
                        tooltip="Titre 2"
                    />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleHeading({ level: 3 }).run()}
                        isActive={editor.isActive("heading", { level: 3 })}
                        icon={Heading3}
                        tooltip="Titre 3"
                    />
                    <div className="w-px h-6 bg-white/10 mx-1" />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleBulletList().run()}
                        isActive={editor.isActive("bulletList")}
                        icon={List}
                        tooltip="Liste à puces"
                    />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleOrderedList().run()}
                        isActive={editor.isActive("orderedList")}
                        icon={ListOrdered}
                        tooltip="Liste numérotée"
                    />
                    <div className="w-px h-6 bg-white/10 mx-1" />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleBlockquote().run()}
                        isActive={editor.isActive("blockquote")}
                        icon={Quote}
                        tooltip="Citation"
                    />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().toggleCodeBlock().run()}
                        isActive={editor.isActive("codeBlock")}
                        icon={Code}
                        tooltip="Bloc de code"
                    />
                    <div className="w-px h-6 bg-white/10 mx-1" />
                    <input
                        type="color"
                        onInput={event => editor.chain().focus().setColor((event.target as HTMLInputElement).value).run()}
                        value={editor.getAttributes('textStyle').color || '#ffffff'}
                        className="w-8 h-8 rounded-lg bg-zinc-900 border border-white/10 cursor-pointer p-1 hover:bg-white/10 transition-colors"
                        title="Couleur du texte"
                    />
                    <ToolbarButton
                        onClick={() => {
                            const url = window.prompt("Entrez l'URL de l'image (ou laissez vide pour uploader):");
                            if (url) {
                                editor.chain().focus().setImage({ src: url }).run();
                                return;
                            }

                            const input = document.createElement("input");
                            input.type = "file";
                            input.accept = "image/*";
                            input.onchange = async () => {
                                if (input.files?.length) {
                                    const file = input.files[0];
                                    const uploadedUrl = await uploadImageFile(file);
                                    if (uploadedUrl) {
                                        editor.chain().focus().setImage({ src: uploadedUrl }).run();
                                    }
                                }
                            };
                            input.click();
                        }}
                        icon={ImageIcon}
                        tooltip="Insérer une image (Fichier ou URL)"
                    />
                    <EmojiPicker onSelect={(emoji) => editor.chain().focus().insertContent(emoji).run()} />
                    <div className="w-px h-6 bg-white/10 mx-1 ml-auto" />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().undo().run()}
                        disabled={!editor.can().undo()}
                        icon={Undo}
                        tooltip="Annuler"
                    />
                    <ToolbarButton
                        onClick={() => editor.chain().focus().redo().run()}
                        disabled={!editor.can().redo()}
                        icon={Redo}
                        tooltip="Rétablir"
                    />
                </div>
            )}

            {/* BUBBLE MENU (Floating on selection) */}
            {editable && editor && (
                <UnifiedBubbleMenu key="unified-editor-menu" editor={editor} />
            )}

            {/* EDITOR CONTENT (Scrollable area) */}
            <div className="flex-1 overflow-y-auto cursor-text bg-zinc-950/20" onClick={() => editor.chain().focus().run()}>
                <EditorContent editor={editor} className="min-h-full pb-32" />
            </div>

            <style jsx global>{`
                .ProseMirror p.is-editor-empty:first-child::before {
                    color: #71717a;
                    content: attr(data-placeholder);
                    float: left;
                    height: 0;
                    pointer-events: none;
                }
            `}</style>
        </div>
    );
}

function ToolbarButton({
    onClick,
    isActive,
    disabled,
    icon: Icon,
    tooltip,
    size = "default"
}: {
    onClick: () => void,
    isActive?: boolean,
    disabled?: boolean,
    icon: any,
    tooltip?: string,
    size?: "default" | "sm"
}) {
    return (
        <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={(e) => {
                onClick();
            }}
            onMouseDown={(e) => e.preventDefault()} // Prevent focus loss
            disabled={disabled}
            className={cn(
                "h-8 w-8 p-0 transition-all",
                isActive
                    ? "bg-indigo-500/20 text-indigo-400 hover:bg-indigo-500/30"
                    : "text-zinc-400 hover:bg-white/10 hover:text-zinc-100",
                size === "sm" && "h-7 w-7"
            )}
            title={tooltip}
        >
            <Icon className={cn("w-4 h-4", size === "sm" && "w-3 h-3")} />
        </Button>
    )
}

function UnifiedBubbleMenu({ editor }: { editor: any }) {
    if (!editor) return null;

    const isImage = editor.isActive("image");

    return (
        <BubbleMenu
            pluginKey="unified-menu-v3"
            editor={editor}
            className="flex items-center gap-1 overflow-hidden rounded-xl border border-white/10 bg-zinc-900/95 backdrop-blur-xl shadow-2xl p-1 animate-in fade-in zoom-in-95 duration-200"
            shouldShow={({ from, to }: any) => {
                // Determine if we should show the menu
                const isSelection = from !== to;
                const isImg = editor.isActive("image");
                return isImg || isSelection;
            }}
        >
