export const GarticLayout = ({ 
    phase, 
    children, 
    onClose, 
    spectators = [], 
    guildId = "", 
    showVoiceOverlay = true, 
    onToggleVoice 
}: { 
    phase: string; 
    children: React.ReactNode; 
    onClose?: () => void; 
    spectators?: any[]; 
    guildId?: string; 
    showVoiceOverlay?: boolean; 
