                {/* Halftone/Dots pattern */}
                <div 
                    className="absolute inset-0 opacity-[0.15]"
                    style={{ 
                        backgroundImage: 'radial-gradient(rgba(0,0,0,0.5) 2px, transparent 2px)', 
