"use client";

import React, { useState, useEffect } from "react";
import { Album } from "../../types/socket-events";
import { cn } from "@/lib/utils";
import { Download, ArrowRight, Home, Maximize2, Volume2, User } from "lucide-react";

interface RevealScreenProps {
    albums: Album[];
    revealIndex: number;
    isHost: boolean;
    onNextAlbum: () => void;
    onExit: () => void;
    players?: any[];
}

export const RevealScreen = ({ albums, revealIndex, isHost, onNextAlbum, onExit, players = [] }: RevealScreenProps) => {
    const album = albums[revealIndex];
    if (!album) return null;

    const ownerName = typeof album.owner === "string" ? album.owner : album.owner?.username || "?";
    
    // In Gartic Phone, all entries are revealed one by one. 
    // For simplicity and matching the "Album" feel, we'll show all entries in the current album.
    const entries = album.entries || [];

    const [visibleCount, setVisibleCount] = useState(0);
    const scrollRef = React.useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [visibleCount]);

    useEffect(() => {
        setVisibleCount(0);
        const timer = setTimeout(() => {
            setVisibleCount(1);
        }, 500);
        return () => clearTimeout(timer);
    }, [revealIndex]);

    useEffect(() => {
        if (visibleCount > 0 && visibleCount < entries.length) {
            const timer = setTimeout(() => {
                import("@/lib/sounds").then(({ playSoundEffect }) => playSoundEffect("ding"));
                setVisibleCount(v => v + 1);
            }, 5000);
            return () => clearTimeout(timer);
        } else if (visibleCount === entries.length && isHost) {
            const timer = setTimeout(() => {
                onNextAlbum();
            }, 5000);
            return () => clearTimeout(timer);
        }
    }, [visibleCount, entries.length, isHost, onNextAlbum]);



    return (
        <div className="w-full h-full max-w-[95vw] flex flex-col gap-4 animate-in fade-in duration-1000 py-4 relative">
            {/* Top Bar / Navigation */}
            <div className="flex items-center justify-between w-full px-2">
                <button 
                    onClick={onExit}
                    className="group flex items-center gap-4 bg-white/10 hover:bg-white/20 text-white px-8 py-4 rounded-[2rem] font-black uppercase text-sm border-b-[6px] border-black/20 transition-all active:translate-y-1 active:border-b-0 backdrop-blur-md"
                >
                    <Home size={20} className="group-hover:scale-125 transition-transform" />
                    <span>QUITTER LA GALERIE</span>
                </button>

                <div className="flex items-center gap-4">
                    <button className="w-12 h-12 flex items-center justify-center bg-white/10 hover:bg-white/20 rounded-xl text-white transition-all">
                        <Maximize2 size={20} />
                    </button>
                    <button className="w-12 h-12 flex items-center justify-center bg-white/10 hover:bg-white/20 rounded-xl text-white transition-all">
                        <Volume2 size={20} />
                    </button>
                </div>
            </div>

            {/* Main Content Area */}
            <div className="flex-1 grid grid-cols-12 gap-6 min-h-0">
                {/* Left Column: Players List */}
                <div className="col-span-12 md:col-span-4 flex flex-col gap-4">
                    <div className="text-center">
                        <h2 className="text-white text-3xl font-black uppercase italic tracking-tighter drop-shadow-lg">JOUEURS</h2>
                        <div className="h-1.5 w-16 bg-[#2ed573] mx-auto rounded-full mt-1" />
                    </div>

                    <div className="flex-1 bg-white/10 backdrop-blur-md rounded-[2.5rem] border-[4px] md:border-[6px] border-white/10 p-3 md:p-4 flex md:flex-col gap-3 overflow-x-auto md:overflow-y-auto custom-scrollbar shadow-2xl shrink-0 md:shrink">
                        {albums.map((a, idx) => {
                            const name = typeof a.owner === "string" ? a.owner : a.owner?.username || "?";
                            const isActive = idx === revealIndex;
                            return (
                                <div 
                                    key={idx}
                                    className={cn(
                                        "flex items-center gap-3 md:gap-4 p-3 md:p-4 rounded-2xl md:rounded-3xl border-b-[4px] md:border-b-[6px] transition-all shrink-0 md:shrink-0",
                                        isActive 
                                            ? "bg-[#2ed573] border-[#1e9b53] translate-x-1" 
                                            : "bg-white/90 border-[#c5b58e] opacity-80"
                                    )}
                                >
                                    <div className="w-10 h-10 md:w-12 md:h-12 rounded-full bg-white border-2 md:border-4 border-black/10 overflow-hidden shrink-0">
                                        <img src={`https://api.dicebear.com/7.x/bottts/svg?seed=${name}`} alt={name} className="w-full h-full object-cover" />
                                    </div>
                                    <span className={cn(
                                        "font-black text-sm md:text-xl uppercase italic tracking-tight truncate max-w-[100px] md:max-w-none",
                                        isActive ? "text-white" : "text-[#3d2080]"
                                    )}>
                                        {name}
                                    </span>
                                    {isActive && (
                                        <div className="ml-auto bg-white/30 rounded-full p-1 hidden md:block">
                                            <div className="w-6 h-6 bg-white rounded-full flex items-center justify-center">
                                                <span className="text-[10px]">👑</span>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                </div>

                {/* Right Column: Album Scroll */}
                <div className="col-span-12 md:col-span-8 flex flex-col gap-4">
                    <div className="text-center">
                        <h2 className="text-white text-3xl font-black uppercase italic tracking-tighter drop-shadow-lg">
                            ALBUM DE {ownerName.toUpperCase()}
                        </h2>
                        <div className="h-1.5 w-16 bg-[#2ed573] mx-auto rounded-full mt-1" />
                    </div>

                    <div className="flex-1 bg-white/10 backdrop-blur-md rounded-[2.5rem] border-[6px] border-white/10 p-6 flex flex-col gap-8 overflow-y-auto custom-scrollbar shadow-2xl relative" ref={scrollRef}>
                        {entries.slice(0, visibleCount).map((entry, idx) => {
                            const author = typeof entry.author === "string" ? entry.author : (entry.author as any)?.username || "?";
                            const isOdd = idx % 2 !== 0; // Drawing is usually odd indices if we start with text
                            const isText = entry.type === "text";

                            return (
                                <div 
                                    key={idx}
                                    className={cn(
                                        "flex gap-4 w-full animate-in slide-in-from-bottom-5 duration-500",
                                        isOdd ? "flex-row-reverse" : "flex-row"
                                    )}
                                    style={{ animationDelay: `${idx * 150}ms` }}
                                >
                                    {/* Author Avatar */}
                                    <div className="flex flex-col items-center gap-1 shrink-0">
                                        <div className="w-14 h-14 rounded-full bg-white border-4 border-[#3d2080]/20 overflow-hidden shadow-lg">
                                            <img src={`https://api.dicebear.com/7.x/bottts/svg?seed=${author}`} alt={author} className="w-full h-full object-cover" />
                                        </div>
                                        <span className="text-[10px] font-black text-white bg-black/40 px-2 py-0.5 rounded-full uppercase tracking-widest">
                                            {author}
                                        </span>
                                    </div>

                                    {/* Content Bubble - Notebook Style */}
                                    <div className={cn(
                                        "flex-1 max-w-[85%] bg-white rounded-[1.5rem] md:rounded-[2rem] p-4 md:p-6 shadow-xl border-b-[4px] md:border-b-[8px] border-black/10 flex flex-col items-center justify-center relative overflow-hidden",
                                        isText ? "min-h-0 py-4 md:min-h-[120px]" : "min-h-[150px] md:min-h-[350px]"
                                    )}>
                                        {/* Spiral decorations at the top of the "paper" */}
                                            <div className="absolute top-0 left-0 w-full flex justify-around px-12 opacity-[0.05] pointer-events-none">
                                                {Array.from({length: 8}).map((_, i) => (
                                                    <div key={i} className="w-2.5 h-8 bg-black rounded-full -mt-4 shadow-inner" />
                                                ))}
                                            </div>

                                            {isText ? (
                                                <p className="text-[#3d2080] font-black text-lg md:text-2xl lg:text-4xl text-center uppercase tracking-tight leading-tight p-2 md:p-4 relative z-10">
                                                    {entry.content}
                                                </p>
                                            ) : (
                                                    <div className="relative group/img w-full flex flex-col items-center">
                                                        <img src={entry.content} alt="Drawing" className="max-w-full max-h-[250px] md:max-h-[450px] object-contain rounded-xl relative z-10 shadow-lg" />
                                                        <div className="flex justify-center mt-4 gap-4 relative z-20">
                                                            <button 
                                                                onClick={() => {
                                                                    const link = document.createElement("a");
                                                                    link.href = entry.content;
                                                                    link.download = `sigil-phone-${ownerName.replace(/\s+/g, '-')}-${idx}.png`;
                                                                    document.body.appendChild(link);
                                                                    link.click();
                                                                    document.body.removeChild(link);
                                                                }}
                                                                className="flex items-center gap-2 px-6 py-2 bg-emerald-500 hover:bg-emerald-600 text-white font-black uppercase text-[10px] italic rounded-xl border-b-4 border-emerald-700 transition-all active:translate-y-1 active:border-b-0 shadow-lg"
                                                            >
                                                                <Download size={14} />
                                                                Télécharger PNG
                                                            </button>
                                                        </div>
                                                    </div>
                                            )}

                                            {/* Subtle line pattern for text */}
                                            {isText && (
                                                <div className="absolute inset-0 opacity-[0.03] pointer-events-none" style={{ backgroundImage: 'linear-gradient(#000 1px, transparent 1px)', backgroundSize: '100% 40px' }} />
                                            )}
                                        </div>
                                    </div>
                            );
                        })}

                        {/* End Indicator */}
                        {visibleCount === entries.length && (
                            <div className="mt-8 flex flex-col items-center gap-4 animate-in fade-in duration-500">
                                <div className="w-full h-px bg-white/20" />
                                <span className="text-white/40 font-black uppercase tracking-[0.5em] text-xs">
                                    FIN DE L'ALBUM DE {ownerName.toUpperCase()}
                                </span>
                                

                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

"use client";

import { useEffect } from "react";
import { useSession } from "next-auth/react";

/**
 * Sets (or removes) the sigil-god-bypass cookie based on the user's GOD status.
 * This cookie is read by the middleware to bypass maintenance mode.
 */
export function GodBypassCookie() {
    const { data: session } = useSession();

    useEffect(() => {
        const isGod = (session as any)?.isGod === true;
        const discordId = (session as any)?.user?.discordId;

        if (isGod && discordId) {
            // Secure cookie: SameSite=Strict, no JS access needed but we set it here
            // The middleware reads it server-side
            document.cookie = `sigil-god-bypass=${discordId}; path=/; SameSite=Strict; max-age=${7 * 24 * 60 * 60}`;
        } else {
            // Remove cookie if user is not GOD
            document.cookie = "sigil-god-bypass=; path=/; max-age=0";
        }
    }, [session]);

    return null;
}

"use client";

import { useEffect, useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Plus, Loader2 } from "lucide-react";
import { onboardGuild } from "@/server/actions/admin-actions";
import { useRouter } from "next/navigation";
import { toast } from "sonner"; // Assuming sonner or use a simple alert if not available

type GuildProps = {
    id: string;
    name: string;
    icon: string | null;
    isBotPresent?: boolean;
    clientId?: string;
};

export function GuildSetupCard({ guild, clientId }: { guild: GuildProps, clientId?: string }) {
    const [loading, setLoading] = useState(false);

    // If bot is missing, we need to invite it first
    const needsInvite = guild.isBotPresent === false;

    const handleSetup = async () => {
        if (needsInvite) {
            // Redirect to Discord OAuth2
            if (!clientId) {
                toast.error("Configuration Discord manquante (Client ID)");
                return;
            }

            // Using window.location.origin ensures we redirect back to the correct environment (localhost/beta/prod)
            const redirectUri = encodeURIComponent(`${window.location.origin}/onboarding/success`);
            const inviteUrl = `https://discord.com/oauth2/authorize?client_id=${clientId}&permissions=8&scope=bot&redirect_uri=${redirectUri}&response_type=code`;
            
            // Open in a new tab to keep the context, but we list for completion
            window.open(inviteUrl, "_blank");
            return;
        }

        setLoading(true);
        try {
            const result = await onboardGuild(guild.id);
            if (result.success) {
                // Force a hard reload to ensure state is absolutely fresh
                window.location.reload();
            } else {
                console.error(result.error);
                toast.error("Erreur lors du déploiement: " + result.error);
                setLoading(false);
            }
        } catch (e) {
            console.error(e);
            toast.error("Erreur inattendue");
            setLoading(false);
        }
    };

    // Auto-refresh when bot is authorized in the other tab
    useEffect(() => {
        const handleMessage = (event: MessageEvent) => {
            if (event.data === "sigilos-bot-invited" && event.origin === window.location.origin) {
                window.location.reload();
            }
        };

        window.addEventListener("message", handleMessage);
        return () => window.removeEventListener("message", handleMessage);
    }, []);

    return (
        <Card className="bg-black/20 border-white/5 border-dashed hover:border-white/20 transition-all cursor-default">
            <CardContent className="p-6 flex items-center justify-between gap-4">
                <div className="flex items-center gap-4 overflow-hidden">
                    <Avatar className="h-12 w-12 border-2 border-white/5 grayscale opacity-70">
                        <AvatarImage src={guild.icon || ""} alt={guild.name} />
                        <AvatarFallback className="bg-muted text-muted-foreground">
                            {guild.name.substring(0, 2).toUpperCase()}
                        </AvatarFallback>
                    </Avatar>
                    <div className="flex-1 overflow-hidden opacity-70">
                        <h3 className="font-bold truncate text-foreground">
                            {guild.name}
                        </h3>
                        <p className="text-xs text-muted-foreground">
                            {needsInvite ? "Bot absent - Invitation requise" : "Prêt pour déploiement"}
                        </p>
                    </div>
                </div>

                <Button
                    size="sm"
                    variant={needsInvite ? "secondary" : "outline"}
                    className={needsInvite
                        ? "bg-indigo-500/20 text-indigo-300 hover:bg-indigo-500/40"
                        : "border-primary/20 hover:bg-primary/10 hover:text-primary transition-colors"
                    }
                    onClick={handleSetup}
                    disabled={loading}
                >
                    {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4 mr-2" />}
                    {loading ? "..." : (needsInvite ? "Inviter le Bot" : "Déployer")}
                </Button>
            </CardContent>
        </Card>
    );
}

"use client";

import { useEffect, useState } from "react";
import { BonusStatus } from "@prisma/client";
import { Clock, Sparkles } from "lucide-react";

interface ActiveBonusTrackerProps {
    guildId: string;
}

interface BonusData {
    id: string;
    bonusType: string;
    status: BonusStatus;
    activatesAt: Date;
    expiresAt?: Date | null;
    config: {
        name: string;
        description: string;
    };
}

export function ActiveBonusTracker({ guildId }: ActiveBonusTrackerProps) {
    const [bonus, setBonus] = useState<BonusData | null>(null);
    const [timeRemaining, setTimeRemaining] = useState("");
    const [progress, setProgress] = useState(0);

    useEffect(() => {
        loadBonus();
        const interval = setInterval(loadBonus, 60000); // Update every minute
        return () => clearInterval(interval);
    }, [guildId]);

    useEffect(() => {
        if (!bonus) return;

        const updateCountdown = () => {
            const now = new Date();

            if (bonus.status === "PURCHASED") {
                const activatesAt = new Date(bonus.activatesAt);
                const totalDuration = 24 * 60 * 60 * 1000; // 24h in ms
                const timeLeft = activatesAt.getTime() - now.getTime();

                if (timeLeft <= 0) {
                    setTimeRemaining("Activation en cours...");
                    setProgress(100);
                    return;
                }

                const hours = Math.floor(timeLeft / (60 * 60 * 1000));
                const minutes = Math.floor((timeLeft % (60 * 60 * 1000)) / (60 * 1000));
                setTimeRemaining(`${hours}h ${minutes}m`);
                setProgress(((totalDuration - timeLeft) / totalDuration) * 100);
            } else if (bonus.status === "ACTIVE" && bonus.expiresAt) {
                const expiresAt = new Date(bonus.expiresAt);
                const activatedAt = new Date(new Date(bonus.expiresAt).getTime() - 2 * 60 * 60 * 1000);
                const totalDuration = 2 * 60 * 60 * 1000; // 2h in ms
                const timeLeft = expiresAt.getTime() - now.getTime();

                if (timeLeft <= 0) {
                    setTimeRemaining("Expiré");
                    setProgress(100);
                    return;
                }

                const hours = Math.floor(timeLeft / (60 * 60 * 1000));
                const minutes = Math.floor((timeLeft % (60 * 60 * 1000)) / (60 * 1000));
                setTimeRemaining(`${hours}h ${minutes}m`);
                setProgress(((totalDuration - timeLeft) / totalDuration) * 100);
            }
        };

        updateCountdown();
        const interval = setInterval(updateCountdown, 60000); // Update every minute
        return () => clearInterval(interval);
    }, [bonus]);

    const loadBonus = async () => {
        try {
            const res = await fetch(`/api/guild/${guildId}/active-bonus`);
            if (res.ok) {
                const data = await res.json();
                if (data.bonus) {
                    setBonus(data.bonus);
                } else {
                    setBonus(null);
                }
            }
        } catch (error) {
            console.error("Failed to load active bonus:", error);
        }
    };

    if (!bonus) return null;

    const isActive = bonus.status === "ACTIVE";
    const isPending = bonus.status === "PURCHASED";

    return (
        <div className="fixed bottom-0 left-0 right-0 z-40 bg-gradient-to-t from-slate-900 via-slate-900/95 to-transparent backdrop-blur-sm">
            <div className="max-w-7xl mx-auto px-4 py-3">
                <div className={`
                    rounded-lg border-2 p-4 transition-all
                    ${isActive ? "border-green-500/50 bg-green-500/5" : "border-orange-500/50 bg-orange-500/5"}
                `}>
                    <div className="flex items-center justify-between gap-4">
                        {/* Icon + Name */}
                        <div className="flex items-center gap-3">
                            {isActive ? (
                                <Sparkles className="w-6 h-6 text-green-400 animate-pulse" />
                            ) : (
                                <Clock className="w-6 h-6 text-orange-400" />
                            )}
                            <div>
                                <h3 className="font-bold text-white">{bonus.config.name}</h3>
                                <p className="text-xs text-slate-400">{bonus.config.description}</p>
                            </div>
                        </div>

                        {/* Progress + Time */}
                        <div className="flex-1 max-w-md">
                            {/* Progress Bar */}
                            <div className="relative h-3 bg-slate-800 rounded-full overflow-hidden mb-1">
                                <div
                                    className={`
                                        h-full transition-all duration-1000 rounded-full
                                        ${isActive ? "bg-gradient-to-r from-green-500 to-emerald-400" : "bg-gradient-to-r from-orange-500 to-yellow-400"}
                                    `}
                                    style={{ width: `${progress}%` }}
                                />
                            </div>

                            {/* Time Label */}
                            <div className="flex items-center justify-between text-xs">
                                <span className={isActive ? "text-green-400" : "text-orange-400"}>
                                    {isPending ? "Activation dans" : "Expire dans"}
                                </span>
                                <span className="font-mono font-bold text-white">
                                    {timeRemaining}
                                </span>
                            </div>
                        </div>

                        {/* Status Badge */}
                        <div className={`
                            px-3 py-1 rounded-full text-xs font-bold uppercase
                            ${isActive ? "bg-green-500/20 text-green-400" : "bg-orange-500/20 text-orange-400"}
                        `}>
                            {isActive ? "✨ Actif" : "⏳ En attente"}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useRef, useCallback, useEffect } from "react";
import { toast } from "sonner";
import {
    Coins, Plus, Minus, Upload, X, Loader2,
    CheckCircle2, Clock, ChevronDown, ChevronUp,
    Info, Star, HelpCircle
} from "lucide-react";
import { Button } from "@/components/ui/button";
import {
    submitKamaDonation,
    getMyWeeklyKamaStatus,
    type KamaWeeklyStatus,
} from "@/server/actions/kama-actions";
import {
    KAMA_TRANCHE, KAMA_MAX_TRANCHES, KAMA_MAX_PER_WEEK,
    REWARDS_PER_TRANCHE,
} from "@/lib/kama-constants";
import { cn } from "@/lib/utils";

interface KamaContributionWidgetProps {
    guildId: string;
    initialStatus: KamaWeeklyStatus | null;
}

export function KamaContributionWidget({ guildId, initialStatus }: KamaContributionWidgetProps) {
    const [status, setStatus] = useState<KamaWeeklyStatus | null>(initialStatus);
    const [expanded, setExpanded] = useState(false);
    const [showHelp, setShowHelp] = useState(false);
    const [tranches, setTranches] = useState(1);
    const [note, setNote] = useState("");
    const [file, setFile] = useState<File | null>(null);
    const [preview, setPreview] = useState<string | null>(null);
    const [submitting, setSubmitting] = useState(false);
    const [step, setStep] = useState<"form" | "proof">("form");
    const [shouldPulse, setShouldPulse] = useState(false);
    
    const fileRef = useRef<HTMLInputElement>(null);
    const widgetRef = useRef<HTMLDivElement>(null);

    const tranchesLeft = status?.tranchesLeft ?? KAMA_MAX_TRANCHES;
    const canContribute = (status?.canContribute ?? true) && tranchesLeft > 0;

    const refreshStatus = useCallback(async () => {
        const res = await getMyWeeklyKamaStatus(guildId);
        if (res.success && res.data) setStatus(res.data);
    }, [guildId]);

    const validateAndSetFile = async (f: File) => {
        const ALLOWED = ["image/jpeg", "image/png", "image/webp"];
        if (!ALLOWED.includes(f.type)) { toast.error("JPEG, PNG ou WebP uniquement."); return; }
        if (f.size > 10 * 1024 * 1024) { toast.error("Max 10 MB."); return; }

        setFile(f);
        if (preview) URL.revokeObjectURL(preview);
        setPreview(URL.createObjectURL(f));
    };

    useEffect(() => {
        if (step !== "proof" || !expanded) return;

        const handlePaste = (e: ClipboardEvent) => {
            if (e.clipboardData && e.clipboardData.files.length > 0) {
                const f = e.clipboardData.files[0];
                if (f.type.startsWith("image/")) {
                    e.preventDefault();
                    validateAndSetFile(f);
                    toast.info("Image collée ! 📋");
                }
            }
        };

        window.addEventListener("paste", handlePaste);
        return () => window.removeEventListener("paste", handlePaste);
    }, [step, expanded, guildId, preview]);

    // Handle hash routing to auto-expand and focus the widget
    useEffect(() => {
        const checkHash = () => {
            if (window.location.hash === "#don-kamas") {
                setExpanded(true);
                setShouldPulse(true);
                setTimeout(() => {
                    widgetRef.current?.scrollIntoView({ behavior: "smooth", block: "center" });
                }, 100);
                
                // Stop pulsing after 3 seconds
                const timer = setTimeout(() => setShouldPulse(false), 3000);
                return () => clearTimeout(timer);
            }
        };

        checkHash();
        window.addEventListener("hashchange", checkHash);
        return () => window.removeEventListener("hashchange", checkHash);
    }, []);

    const handleSubmit = async () => {
        if (!file) { toast.error("Ajoutez un screenshot de preuve."); return; }
        setSubmitting(true);
        const fd = new FormData();
        fd.append("file", file);
        const res = await submitKamaDonation({ guildId, tranches, note: note || null }, fd);
        if (res.success) {
            toast.success(`✅ Don de ${(tranches * KAMA_TRANCHE).toLocaleString("fr-FR")} kamas soumis !`);
            setTranches(1); setNote(""); setFile(null); setPreview(null); setStep("form");
            setExpanded(false);
            await refreshStatus();
        } else {
            toast.error(res.error || "Erreur lors de la soumission.");
        }
        setSubmitting(false);
    };

    const totalKamas = tranches * KAMA_TRANCHE;
    const totalRewards = {
        xp: tranches * REWARDS_PER_TRANCHE.xp,
        guildatons: tranches * REWARDS_PER_TRANCHE.guildatons,
        guild_kamas: tranches * REWARDS_PER_TRANCHE.guild_kamas,
    };

    const pendingCount = status?.weekDonations.filter(d => d.status === "PENDING").length ?? 0;
    const validatedKamas = status?.validatedThisWeek ?? 0;
    const submittedKamas = status?.submittedThisWeek ?? 0;
    const progressPct = Math.min(100, (submittedKamas / KAMA_MAX_PER_WEEK) * 100);

    return (
        <>
            {/* ── Widget principal ── */}
            <div 
                ref={widgetRef}
                className={cn(
                    "rounded-xl border overflow-hidden transition-all duration-300 shadow-lg",
                    shouldPulse 
                        ? "border-amber-500 shadow-[0_0_20px_rgba(245,158,11,0.4)] scale-[1.01] ring-1 ring-amber-500/50" 
                        : "border-amber-500/30 bg-gradient-to-b from-amber-500/[0.04] to-zinc-950/80 shadow-[0_4px_20px_rgba(245,158,11,0.05)] hover:border-amber-500/50"
                )}
            >

                {/* Header — always visible */}
                <div
                    role="button"
                    tabIndex={0}
                    onClick={() => setExpanded(e => !e)}
                    onKeyDown={e => { if (e.key === "Enter" || e.key === " ") setExpanded(prev => !prev); }}
                    className="w-full flex items-center gap-3 px-3 py-2.5 hover:bg-white/[0.02] transition-colors cursor-pointer"
                >
                    <div className="p-1.5 rounded-lg bg-amber-500/10 border border-amber-500/20 shrink-0">
                        <Coins className="w-3.5 h-3.5 text-amber-400" />
                    </div>

                    <div className="flex-1 text-left">
                        <p className="text-xs font-bold text-white">Contribution kamas</p>
                        <div className="flex items-center gap-2 mt-0.5">
                            <div className="flex items-center gap-0.5">
                                {Array.from({ length: KAMA_MAX_TRANCHES }).map((_, i) => {
                                    const tranchesDone = Math.floor(submittedKamas / KAMA_TRANCHE);
                                    const isValidated = i < Math.floor(validatedKamas / KAMA_TRANCHE);
                                    const isPending = !isValidated && i < tranchesDone;
                                    return (
                                        <div
                                            key={i}
                                            className={`w-2 h-2 rounded-full transition-all duration-300 ${isValidated ? "bg-emerald-400" : isPending ? "bg-amber-400 animate-pulse" : "bg-zinc-700"}`}
                                        />
                                    );
                                })}
                            </div>
                            <span className="text-[10px] text-zinc-500">
                                {KAMA_MAX_TRANCHES - tranchesLeft}/{KAMA_MAX_TRANCHES} tranches
                            </span>
                            {pendingCount > 0 && (
                                <span className="text-[9px] bg-amber-500/15 border border-amber-500/20 text-amber-400 px-1.5 py-0.5 rounded-full font-bold">
                                    {pendingCount} en attente
                                </span>
                            )}
                        </div>
                    </div>

                    <div className="shrink-0 flex items-center gap-1.5">
                        {!canContribute && (
                            <span className="text-[9px] bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 px-2 py-0.5 rounded-full font-bold">
                                MAX ✓
                            </span>
                        )}
                        <button
                            onClick={e => { e.stopPropagation(); setShowHelp(true); }}
                            className="p-1 rounded-md hover:bg-white/5 text-zinc-600 hover:text-zinc-400 transition-colors"
                            title="Comment ça marche ?"
                        >
                            <HelpCircle className="w-3.5 h-3.5" />
                        </button>
                        {expanded
                            ? <ChevronUp className="w-3.5 h-3.5 text-zinc-600" />
                            : <ChevronDown className="w-3.5 h-3.5 text-zinc-600" />
                        }
                    </div>
                </div>

                {/* Expanded content */}
                {expanded && (
                    <div className="border-t border-white/5 p-3 space-y-3">
                        {/* Info block */}
                        <div className="flex flex-col gap-2 bg-amber-500/[0.03] rounded-lg p-3 border border-amber-500/20">
                            <div className="flex items-start gap-2">
                                <Info className="w-3.5 h-3.5 text-amber-400 shrink-0 mt-0.5" />
                                <div className="text-[10px] text-zinc-400 space-y-0.5">
                                    <p>Max <span className="text-white font-bold">{KAMA_MAX_PER_WEEK.toLocaleString("fr-FR")} kamas</span> par semaine</p>
                                    <p>Chaque tranche de <span className="text-amber-400 font-bold">10 000k</span> → {REWARDS_PER_TRANCHE.xp} XP · {REWARDS_PER_TRANCHE.guildatons} guildatons</p>
                                </div>
                            </div>
                            <div className="pt-2 border-t border-amber-500/10 text-[9px] text-amber-300/80 leading-relaxed">
                                ⚠️ **Important :** Les dons en Kamas servent directement à financer les **Raids de guilde**. Votre participation aux dons est indispensable pour maintenir l&apos;accès à ces raids.
                            </div>
                        </div>

                        {/* Weekly progress bar */}
                        <div className="space-y-1">
                            <div className="flex justify-between text-[10px]">
                                <span className="text-zinc-500">Progression hebdo</span>
                                <span className="text-zinc-400 font-mono">
                                    {submittedKamas.toLocaleString("fr-FR")} / {KAMA_MAX_PER_WEEK.toLocaleString("fr-FR")} k
                                </span>
                            </div>
                            <div className="h-1.5 bg-zinc-800 rounded-full overflow-hidden">
                                <div
                                    className="h-full bg-gradient-to-r from-amber-600 to-amber-400 rounded-full transition-all duration-500"
                                    style={{ width: `${progressPct}%` }}
                                />
                            </div>
                        </div>

                        {canContribute ? (
                            step === "form" ? (
                                <>
                                    {/* Tranche selector */}
                                    <div className="space-y-1.5">
                                        <label className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest">
                                            Nombre de tranches
                                        </label>
                                        <div className="flex items-center gap-2">
                                            <button
                                                onClick={() => setTranches(t => Math.max(1, t - 1))}
                                                disabled={tranches <= 1}
                                                className="w-8 h-8 rounded-lg bg-zinc-800 border border-white/10 flex items-center justify-center text-zinc-400 hover:text-white hover:border-white/20 disabled:opacity-30 disabled:cursor-not-allowed transition-all"
                                            >
                                                <Minus className="w-3.5 h-3.5" />
                                            </button>
                                            <div className="flex-1 text-center">
                                                <div className="text-lg font-black text-amber-400 font-mono">{tranches}</div>
                                                <div className="text-[10px] text-zinc-500">= {totalKamas.toLocaleString("fr-FR")} kamas</div>
                                            </div>
                                            <button
                                                onClick={() => setTranches(t => Math.min(tranchesLeft, t + 1))}
                                                disabled={tranches >= tranchesLeft}
                                                className="w-8 h-8 rounded-lg bg-zinc-800 border border-white/10 flex items-center justify-center text-zinc-400 hover:text-white hover:border-white/20 disabled:opacity-30 disabled:cursor-not-allowed transition-all"
                                            >
                                                <Plus className="w-3.5 h-3.5" />
                                            </button>
                                            <button
                                                onClick={() => setTranches(tranchesLeft)}
                                                className="px-2.5 py-1.5 rounded-lg bg-zinc-800 border border-white/10 text-[10px] font-bold text-zinc-400 hover:text-white hover:border-white/20 transition-all"
                                            >
                                                MAX
                                            </button>
                                        </div>
                                    </div>

                                    {/* Rewards preview */}
                                    <div className="flex items-center gap-2 bg-zinc-900/60 rounded-lg px-3 py-2 border border-white/5">
                                        <Star className="w-3 h-3 text-amber-400 shrink-0" />
                                        <span className="text-[10px] text-zinc-400">Récompenses :</span>
                                        <div className="flex items-center gap-3 ml-auto">
                                            <span className="text-[10px] font-bold text-blue-300">+{totalRewards.xp} XP</span>
                                            <span className="text-[10px] font-bold text-amber-300">+{totalRewards.guildatons} guildatons</span>
                                            <span className="text-[10px] font-bold text-emerald-300">+{totalRewards.guild_kamas} k.g.</span>
                                        </div>
                                    </div>

                                    <Button
                                        onClick={() => setStep("proof")}
                                        className="w-full bg-amber-600 hover:bg-amber-500 text-white font-bold gap-2 h-9 text-sm"
                                    >
                                        <Upload className="w-3.5 h-3.5" />
                                        Ajouter la preuve screenshot
                                    </Button>
                                </>
                            ) : (
                                // Step 2: screenshot upload
                                <>
                                    <div className="flex items-center gap-2">
                                        <button
                                            onClick={() => setStep("form")}
                                            className="text-[10px] text-zinc-500 hover:text-zinc-300 transition-colors"
                                        >
                                            ← Retour
                                        </button>
                                        <span className="text-[10px] text-zinc-600">
                                            {totalKamas.toLocaleString("fr-FR")} kamas ({tranches} tranche{tranches > 1 ? "s" : ""})
                                        </span>
                                    </div>

                                    {preview ? (
                                        <div className="relative rounded-xl overflow-hidden border border-white/10 bg-zinc-800/50">
                                            {/* eslint-disable-next-line @next/next/no-img-element */}
                                            <img src={preview} alt="Preuve" className="w-full max-h-48 object-contain" />
                                            <button
                                                onClick={() => { setPreview(null); setFile(null); }}
                                                className="absolute top-2 right-2 p-1 rounded-full bg-zinc-900/80 border border-white/10 text-zinc-300 hover:text-red-400 transition-colors"
                                            >
                                                <X className="w-3 h-3" />
                                            </button>
                                        </div>
                                    ) : (
                                        <div
                                            className="border-2 border-dashed border-white/10 rounded-xl p-5 flex flex-col items-center gap-2 transition-all group"
                                            onDrop={e => {
                                                e.preventDefault();
                                                const f = e.dataTransfer.files[0];
                                                if (f) validateAndSetFile(f);
                                            }}
                                            onDragOver={e => e.preventDefault()}
                                        >
                                            <Upload className="w-5 h-5 text-zinc-600 group-hover:text-amber-400 transition-colors" />
                                            <div className="text-xs text-zinc-500 text-center">
                                                <p className="group-hover:text-zinc-300 transition-colors">
                                                    Glissez, collez (Ctrl+V) ou{" "}
                                                    <button
                                                        type="button"
                                                        onClick={() => fileRef.current?.click()}
                                                        className="text-amber-400 hover:text-amber-300 font-medium hover:underline focus:outline-none"
                                                    >
                                                        cliquez ici
                                                    </button>
                                                </p>
                                                <p className="text-[10px] text-zinc-600 mt-1">JPEG · PNG · WebP · max 10MB</p>
                                            </div>
                                        </div>
                                    )}
                                    <input
                                        ref={fileRef}
                                        type="file"
                                        accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp"
                                        className="hidden"
                                        onChange={e => { const f = e.target.files?.[0]; if (f) validateAndSetFile(f); }}
                                    />

                                    <Button
                                        onClick={handleSubmit}
                                        disabled={submitting || !file}
                                        className="w-full bg-amber-600 hover:bg-amber-500 disabled:opacity-50 text-white font-bold gap-2 h-9 text-sm"
                                    >
                                        {submitting
                                            ? <><Loader2 className="w-4 h-4 animate-spin" /> Envoi...</>
                                            : <><CheckCircle2 className="w-4 h-4" /> Confirmer le don</>
                                        }
                                    </Button>
                                </>
                            )
                        ) : (
                            <div className="flex flex-col items-center gap-2 py-2">
                                <div className="p-2 rounded-full bg-emerald-500/10 border border-emerald-500/20">
                                    <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                                </div>
                                <p className="text-xs font-bold text-emerald-300 text-center">Maximum hebdomadaire atteint !</p>
                                <p className="text-[10px] text-zinc-500 text-center">
                                    {submittedKamas.toLocaleString("fr-FR")} kamas contribués cette semaine.<br />
                                    Reset au prochain cycle de missions.
                                </p>
                            </div>
                        )}

                        {pendingCount > 0 && (
                            <div className="flex items-center gap-2 bg-amber-500/5 border border-amber-500/15 rounded-lg px-2.5 py-2">
                                <Clock className="w-3 h-3 text-amber-400 shrink-0" />
                                <p className="text-[10px] text-amber-300">
                                    {pendingCount} don{pendingCount > 1 ? "s" : ""} en cours de validation.
                                </p>
                            </div>
                        )}
                    </div>
                )}
            </div>

            {/* ── Modale d'aide ── */}
            {showHelp && (
                <div
                    className="fixed inset-0 z-50 bg-black/90 flex items-center justify-center p-4"
                    onClick={() => setShowHelp(false)}
                >
                    <div
                        className="bg-zinc-900 border border-amber-500/20 rounded-2xl max-w-md w-full shadow-2xl overflow-hidden"
                        onClick={e => e.stopPropagation()}
                    >
                        <div className="flex items-center gap-3 px-5 py-4 border-b border-white/5 bg-amber-500/5">
                            <div className="p-2 rounded-xl bg-amber-500/10 border border-amber-500/20">
                                <Coins className="w-4 h-4 text-amber-400" />
                            </div>
                            <div className="flex-1">
                                <p className="text-sm font-black text-white">Comment déclarer un don ?</p>
                                <p className="text-[10px] text-zinc-500">Mécanique officielle Dofus</p>
                            </div>
                            <button
                                onClick={() => setShowHelp(false)}
                                className="p-1.5 rounded-lg hover:bg-white/5 text-zinc-500 hover:text-zinc-300 transition-colors"
                            >
                                <X className="w-4 h-4" />
                            </button>
                        </div>

                        <div className="relative bg-zinc-950/80 border-b border-white/5">
                            {/* eslint-disable-next-line @next/next/no-img-element */}
                            <img
                                src="/assets/missions/don-kamas-guilde.png"
                                alt="Interface don de kamas Dofus"
                                className="w-full object-contain max-h-52"
                            />
                            <div className="absolute bottom-0 inset-x-0 bg-gradient-to-t from-zinc-950/90 to-transparent p-3">
                                <p className="text-[10px] text-amber-300 font-bold">
                                    📍 Interface du comptoir d&apos;inventaire en jeu
                                </p>
                            </div>
                        </div>

                        <div className="p-5 space-y-3">
                            {[
                                { step: "1", text: "En jeu, ouvre le coffre de guilde et fais un don de kamas (multiples de 10 000)." },
                                { step: "2", text: "Prends un screenshot du comptoir d'inventaire avec le montant visible." },
                                { step: "3", text: "Reviens ici, sélectionne le nombre de tranches et uploade le screenshot." },
                                { step: "4", text: "Un admin valide. Dès validation : XP et guildatons comptabilisés automatiquement." },
                            ].map(({ step, text }) => (
                                <div key={step} className="flex items-start gap-3">
                                    <div className="w-5 h-5 rounded-full bg-amber-500/20 border border-amber-500/30 text-amber-400 text-[10px] font-black flex items-center justify-center shrink-0 mt-0.5">
                                        {step}
                                    </div>
                                    <p className="text-xs text-zinc-400 leading-relaxed">{text}</p>
                                </div>
                            ))}

                            <div className="mt-3 p-3 bg-zinc-800/50 rounded-xl border border-white/5">
                                <p className="text-[10px] font-bold text-zinc-300 uppercase tracking-widest mb-2">Limites hebdomadaires</p>
                                <div className="grid grid-cols-2 gap-1.5 text-[10px] text-zinc-500">
                                    <span>Max par semaine :</span>
                                    <span className="text-amber-400 font-bold">{KAMA_MAX_PER_WEEK.toLocaleString("fr-FR")} kamas</span>
                                    <span>Max tranches :</span>
                                    <span className="text-amber-400 font-bold">{KAMA_MAX_TRANCHES} tranches</span>
                                    <span>Par tranche :</span>
                                    <span className="text-blue-400 font-bold">+{REWARDS_PER_TRANCHE.xp} XP · +{REWARDS_PER_TRANCHE.guildatons} guildatons</span>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </>
    );
}

'use client';

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Check, X, Search, RefreshCcw, Coins, Clock, User as UserIcon, ExternalLink, ZoomIn } from "lucide-react";
import { toast } from "sonner";
import { reviewKamaDonation } from "@/server/actions/kama-actions";
import { SubmissionCountdown } from "@/components/missions/submission-countdown";
import { KAMA_TRANCHE } from "@/lib/kama-constants";
import { cn } from "@/lib/utils";

type KamaDonationItem = {
    id: string;
    amount: number;
    note: string | null;
    proofUrl: string | null;
    status: string;
    createdAt: Date;
    weekNumber: number | null;
    yearNumber: number | null;
    profile: {
        id: string;
        pseudoDofus: string | null;
        discordNickname: string | null;
        discordRoleColor: number | null;
        user: { name: string | null; image: string | null };
    };
};

interface KamaValidationQueueProps {
    donations: KamaDonationItem[];
    guildId: string;
}

export function KamaValidationQueue({ donations: initialDonations, guildId }: KamaValidationQueueProps) {
    const router = useRouter();
    const [isPending, startTransition] = useTransition();
    const [donations, setDonations] = useState(initialDonations);
    const [processingId, setProcessingId] = useState<string | null>(null);
    const [searchTerm, setSearchTerm] = useState("");
    const [selectedImage, setSelectedImage] = useState<string | null>(null);
    const [rejectReason, setRejectReason] = useState<{ id: string; reason: string } | null>(null);

    const handleDecision = (id: string, action: "VALIDATE" | "REJECT", reason?: string) => {
        setProcessingId(id);
        startTransition(async () => {
            const result = await reviewKamaDonation({
                guildId,
                donationId: id,
                action,
                rejectedReason: reason || null,
            });
            setProcessingId(null);

            if (result.success) {
                toast.success(action === "VALIDATE" ? "✅ Don validé !" : "❌ Don refusé");
                setDonations(prev => prev.filter(d => d.id !== id));
                setRejectReason(null);
                router.refresh();
            } else {
                toast.error(result.error || "Erreur");
            }
        });
    };

    const filtered = donations.filter(d => {
        const q = searchTerm.toLowerCase();
        return (
            (d.profile.pseudoDofus || "").toLowerCase().includes(q) ||
            (d.profile.discordNickname || "").toLowerCase().includes(q) ||
            (d.profile.user.name || "").toLowerCase().includes(q)
        );
    });

    return (
        <div className="space-y-4">
            {/* Toolbar */}
            <div className="flex flex-col sm:flex-row gap-3 items-start sm:items-center justify-between bg-zinc-900/50 p-4 rounded-xl border border-white/5">
                <div className="flex items-center gap-4">
                    <div className="flex items-center gap-2 text-sm text-zinc-400 border-r border-white/10 pr-4">
                        <span className="text-white font-medium">{donations.length}</span> en attente
                    </div>
                    <Button
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8 text-zinc-400 hover:text-white"
                        onClick={() => startTransition(() => router.refresh())}
                        disabled={isPending}
                        title="Actualiser"
                    >
                        <RefreshCcw className={cn("w-4 h-4", isPending && "animate-spin")} />
                    </Button>
                </div>
                <div className="relative w-full sm:w-64">
                    <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-zinc-500" />
                    <Input
                        placeholder="Chercher un membre..."
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                        className="pl-9 h-9 bg-black/20 border-white/10"
                    />
                </div>
            </div>

            {/* Card grid */}
            {filtered.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-[40vh] text-zinc-500 border border-dashed border-zinc-800 rounded-xl bg-zinc-900/20">
                    <Check className="w-12 h-12 mb-4 opacity-20" />
                    <p>Aucun don en attente de validation.</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                    {filtered.map(don => {
                        const tranches = Math.round(don.amount / KAMA_TRANCHE);
                        const name = don.profile.pseudoDofus || don.profile.discordNickname || don.profile.user.name || "Membre";
                        const isProcessing = processingId === don.id;

                        return (
                            <div
                                key={don.id}
                                className="flex flex-col bg-[#121417] border border-white/5 rounded-2xl overflow-hidden shadow-xl hover:border-amber-500/20 transition-all duration-300"
                            >
                                {/* Header amber */}
                                <div className="flex items-center gap-3 px-4 py-2.5 bg-gradient-to-r from-amber-950/80 to-zinc-900/80 border-b border-amber-500/15">
                                    <div className="p-1.5 bg-amber-500/15 rounded-lg border border-amber-500/20">
                                        <Coins className="w-3.5 h-3.5 text-amber-400" />
                                    </div>
                                    <div className="flex-1">
                                        <p className="text-xs font-black text-white uppercase tracking-wide">
                                            Don de Kamas
                                        </p>
                                        <p className="text-[10px] text-amber-300 font-bold font-mono">
                                            {don.amount.toLocaleString("fr-FR")} kamas · {tranches} tranche{tranches > 1 ? "s" : ""}
                                        </p>
                                    </div>
                                    <SubmissionCountdown createdAt={don.createdAt} />
                                </div>

                                {/* User bar */}
                                <div className="flex items-center gap-3 px-4 py-2 bg-zinc-950/50 border-b border-zinc-800/50">
                                    <div className="w-7 h-7 rounded-full bg-zinc-800 overflow-hidden border border-white/10 shrink-0 flex items-center justify-center">
                                        {don.profile.user.image
                                            // eslint-disable-next-line @next/next/no-img-element
                                            ? <img src={don.profile.user.image} alt="" className="w-full h-full object-cover" />
                                            : <UserIcon className="w-3.5 h-3.5 text-zinc-600" />
                                        }
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <p className="text-xs font-semibold text-white truncate">{name}</p>
                                        <p className="text-[10px] text-zinc-500">
                                            S{don.weekNumber} · {new Date(don.createdAt).toLocaleDateString("fr-FR")}
                                        </p>
                                    </div>
                                    <Badge variant="secondary" className="text-[10px] h-5 px-1.5 bg-amber-500/10 text-amber-400 border-amber-500/20">
                                        {tranches}T
                                    </Badge>
                                </div>

                                {/* Proof image */}
                                {don.proofUrl ? (
                                    <div
                                        className="relative aspect-video bg-black overflow-hidden cursor-zoom-in group"
                                        onClick={() => setSelectedImage(don.proofUrl)}
                                    >
                                        {/* eslint-disable-next-line @next/next/no-img-element */}
                                        <img
                                            src={don.proofUrl}
                                            alt="Preuve"
                                            className="w-full h-full object-contain"
                                        />
                                        <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2 text-white text-xs">
                                            <ZoomIn className="w-4 h-4" />
                                            Agrandir
                                        </div>
                                    </div>
                                ) : (
                                    <div className="aspect-video bg-zinc-900/50 flex items-center justify-center text-zinc-600 text-xs">
                                        Aucune preuve jointe
                                    </div>
                                )}

                                {/* Note */}
                                {don.note && (
                                    <div className="px-4 py-2 bg-zinc-900/30 border-t border-zinc-800/50">
                                        <p className="text-[10px] text-zinc-400 italic">&ldquo;{don.note}&rdquo;</p>
                                    </div>
                                )}

                                {/* Reject reason input (shown on demand) */}
                                {rejectReason?.id === don.id && (
                                    <div className="px-4 py-3 bg-red-950/20 border-t border-red-500/20 space-y-2">
                                        <Input
                                            placeholder="Raison du refus (optionnel)..."
                                            value={rejectReason.reason}
                                            onChange={e => setRejectReason({ id: don.id, reason: e.target.value })}
                                            className="h-8 text-xs bg-black/30 border-red-500/20"
                                            autoFocus
                                        />
                                        <div className="flex gap-2">
                                            <Button
                                                size="sm"
                                                variant="outline"
                                                className="flex-1 h-7 text-xs border-zinc-700"
                                                onClick={() => setRejectReason(null)}
                                            >
                                                Annuler
                                            </Button>
                                            <Button
                                                size="sm"
                                                className="flex-1 h-7 text-xs bg-red-700 hover:bg-red-600 text-white"
                                                onClick={() => handleDecision(don.id, "REJECT", rejectReason.reason)}
                                                disabled={isProcessing}
                                            >
                                                <X className="w-3 h-3 mr-1" /> Confirmer refus
                                            </Button>
                                        </div>
                                    </div>
                                )}

                                {/* Actions */}
                                {rejectReason?.id !== don.id && (
                                    <div className="grid grid-cols-2 gap-2 p-3 bg-zinc-950/30 border-t border-zinc-800/50">
                                        <Button
                                            variant="outline"
                                            size="sm"
                                            className="border-red-900/30 hover:bg-red-950/50 hover:text-red-400 text-red-500 text-xs"
                                            onClick={() => setRejectReason({ id: don.id, reason: "" })}
                                            disabled={isProcessing}
                                        >
                                            <X className="w-3.5 h-3.5 mr-1.5" />
                                            Refuser
                                        </Button>
                                        <Button
                                            size="sm"
                                            className="bg-emerald-600 hover:bg-emerald-500 text-white text-xs"
                                            onClick={() => handleDecision(don.id, "VALIDATE")}
                                            disabled={isProcessing}
                                        >
                                            <Check className="w-3.5 h-3.5 mr-1.5" />
                                            Valider
                                        </Button>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            )}

            {/* Lightbox */}
            {selectedImage && (
                <div
                    className="fixed inset-0 z-50 bg-black/95 flex items-center justify-center p-4 cursor-zoom-out"
                    onClick={() => setSelectedImage(null)}
                >
                    {/* eslint-disable-next-line @next/next/no-img-element */}
                    <img src={selectedImage} className="max-w-full max-h-full object-contain shadow-2xl" alt="Zoom" />
                    <Button
                        variant="ghost"
                        size="icon"
                        className="absolute top-4 right-4 text-white hover:bg-white/10"
                        onClick={() => setSelectedImage(null)}
                    >
                        <X className="w-6 h-6" />
                    </Button>
                    <a
                        href={selectedImage}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="absolute top-4 right-16 text-white hover:bg-white/10 p-2 rounded-md"
                        onClick={e => e.stopPropagation()}
                    >
                        <ExternalLink className="w-5 h-5" />
                    </a>
                </div>
            )}
        </div>
    );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import Image from "next/image";
import {
    Coins, CheckCircle2, Clock, AlertCircle,
    ChevronDown, ChevronUp, Users, TrendingUp,
    Swords, Lock, Star, Trophy, Crown, Zap, Info
} from "lucide-react";
import { cn } from "@/lib/utils";
import { KAMA_TRANCHE, KAMA_MAX_PER_WEEK } from "@/lib/kama-constants";
import type { KamaWeeklyMemberSummary, KamaWeeklySummaryResult } from "@/server/actions/kama-actions";

// ──────────────────────────────────────────────────────────────────────────────
// Helpers
// ──────────────────────────────────────────────────────────────────────────────

function getRoleColor(color: number | null): string {
    if (!color || color === 0) return "#71717a";
    return `#${color.toString(16).padStart(6, "0")}`;
}

function getInitials(name: string | null): string {
    if (!name) return "?";
    return name.slice(0, 2).toUpperCase();
}

type StatusConfig = {
    label: string;
    icon: React.ReactNode;
    className: string;
    dot: string;
};

function getStatusConfig(member: KamaWeeklyMemberSummary): StatusConfig {
    if (member.status === "VALIDATED")
        return {
            label: "Validé",
            icon: <CheckCircle2 className="w-3 h-3" />,
            className: "text-emerald-400 bg-emerald-500/10 border-emerald-500/25",
            dot: "bg-emerald-400",
        };
    if (member.status === "MIXED")
        return {
            label: "Partiel",
            icon: <AlertCircle className="w-3 h-3" />,
            className: "text-amber-300 bg-amber-500/10 border-amber-500/25",
            dot: "bg-amber-400",
        };
    return {
        label: "En attente",
        icon: <Clock className="w-3 h-3" />,
        className: "text-zinc-400 bg-zinc-700/40 border-zinc-600/30",
        dot: "bg-zinc-500",
    };
}

// ──────────────────────────────────────────────────────────────────────────────
// Kamas Violet Display Component
// ──────────────────────────────────────────────────────────────────────────────

function KamasVioletIcon({ size = 16 }: { size?: number }) {
    return (
        <Image
            src="/kamas-violet.png"
            alt="🟣"
            width={size}
            height={size}
            className="inline-block"
            style={{ width: size, height: size }}
        />
    );
}

// ──────────────────────────────────────────────────────────────────────────────
// Raid Eligibility Badge
// ──────────────────────────────────────────────────────────────────────────────

function RaidEligibilityBadge({ purpleKamasBalance, requiredPurpleKamas = 30 }: { purpleKamasBalance: number; requiredPurpleKamas?: number }) {
    const isEligible = purpleKamasBalance >= requiredPurpleKamas;
    if (isEligible) {
        return (
            <span className="flex items-center gap-1.5 text-[9px] font-black bg-emerald-500/15 border border-emerald-500/25 text-emerald-400 px-2.5 py-0.5 rounded-full uppercase tracking-wide shrink-0">
                <Swords className="w-2.5 h-2.5" />
                Raid éligible
            </span>
        );
    }
    return (
        <span className="flex items-center gap-1.5 text-[9px] font-black bg-zinc-800/60 border border-zinc-700/40 text-zinc-500 px-2.5 py-0.5 rounded-full uppercase tracking-wide shrink-0">
            <Lock className="w-2.5 h-2.5" />
            Non éligible
        </span>
    );
}

// ──────────────────────────────────────────────────────────────────────────────
// Bourse Badge — shows balance in Kamas Violets with conversion info
// ──────────────────────────────────────────────────────────────────────────────

function PurpleKamasBadge({ balance }: { balance: number }) {
    return (
        <span className="flex items-center gap-1.5 text-[9px] font-black bg-violet-500/15 border border-violet-500/25 text-violet-300 px-2.5 py-0.5 rounded-full uppercase tracking-wide shrink-0">
            <KamasVioletIcon size={12} />
            Bourse: {balance}
        </span>
    );
}

// ──────────────────────────────────────────────────────────────────────────────
// Member Row
// ──────────────────────────────────────────────────────────────────────────────

function MemberRow({
    member,
    rank,
    isOfficer,
    requiredPurpleKamas = 30,
}: {
    member: KamaWeeklyMemberSummary;
    rank: number;
    isOfficer: boolean;
    requiredPurpleKamas?: number;
}) {
    const [expanded, setExpanded] = useState(false);
    const displayName = member.discordNickname || member.pseudoDofus || "Membre inconnu";
    const roleColor = getRoleColor(member.discordRoleColor);
    const statusCfg = getStatusConfig(member);
    const isMax = member.totalAmount >= KAMA_MAX_PER_WEEK;
    const purpleBalance = member.purpleKamasBalance || 0;
    const isEligible = purpleBalance >= requiredPurpleKamas;

    // Convert total donated to purple kamas equivalent
    const purpleEarned = Math.floor((member.totalAmount || 0) / 1000);

    const rankStyle =
        rank === 1 ? "bg-amber-500/20 text-amber-400 border border-amber-500/30 shadow-amber-500/20 shadow-sm" :
        rank === 2 ? "bg-zinc-400/10 text-zinc-400 border border-zinc-600/30" :
        rank === 3 ? "bg-orange-700/15 text-orange-500 border border-orange-700/25" :
        "bg-zinc-800/60 text-zinc-600 border border-zinc-700/40";

    return (
        <div className={cn(
            "rounded-2xl border transition-all duration-200 group",
            rank === 1
                ? "border-amber-500/30 bg-gradient-to-r from-amber-500/[0.04] to-transparent"
                : isEligible
                    ? "border-emerald-500/15 bg-zinc-900/40 hover:border-emerald-500/25"
                    : "border-white/[0.04] bg-zinc-900/30",
            "hover:bg-zinc-900/60 hover:shadow-lg hover:shadow-black/20 hover:-translate-y-px"
        )}>
            {/* Main row */}
            <div className="flex items-center gap-3 p-3.5 sm:p-4">

                {/* Rank badge */}
                <div className={cn(
                    "w-8 h-8 rounded-xl flex items-center justify-center text-xs font-black shrink-0",
                    rankStyle
                )}>
                    {rank <= 3 ? (
                        rank === 1 ? <Crown className="w-4 h-4" /> :
                        rank === 2 ? <Trophy className="w-3.5 h-3.5" /> :
                        <Star className="w-3.5 h-3.5" />
                    ) : rank}
                </div>

                {/* Avatar */}
                <div className="relative shrink-0">
                    {member.discordImage ? (
                        // eslint-disable-next-line @next/next/no-img-element
                        <img
                            src={member.discordImage}
                            alt={displayName}
                            className="w-10 h-10 rounded-full object-cover border-2 transition-transform group-hover:scale-105"
                            style={{ borderColor: `${roleColor}50` }}
                        />
                    ) : (
                        <div
                            className="w-10 h-10 rounded-full flex items-center justify-center text-sm font-bold border-2 transition-transform group-hover:scale-105"
                            style={{
                                backgroundColor: `${roleColor}15`,
                                borderColor: `${roleColor}50`,
                                color: roleColor,
                            }}
                        >
                            {getInitials(displayName)}
                        </div>
                    )}
                    {/* Status dot */}
                    <div className={cn(
                        "absolute -bottom-0.5 -right-0.5 w-3.5 h-3.5 rounded-full border-2 border-zinc-900",
                        statusCfg.dot
                    )} />
                </div>

                {/* Name + badges + progress */}
                <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap mb-1.5">
                        <span className="text-sm font-bold text-white truncate" style={{ color: roleColor !== "#71717a" ? roleColor : undefined }}>
                            {displayName}
                        </span>
                        <RaidEligibilityBadge purpleKamasBalance={purpleBalance} requiredPurpleKamas={requiredPurpleKamas} />
                        <PurpleKamasBadge balance={purpleBalance} />
                        {member.totalAmount > 0 && (
                            <span className="text-[9px] font-bold bg-zinc-800/80 border border-white/10 text-zinc-300 px-2.5 py-0.5 rounded-full uppercase tracking-wide shrink-0">
                                {member.totalAmount.toLocaleString("fr-FR")} k donnés
                            </span>
                        )}
                        {isMax && (
                            <span className="text-[9px] font-black bg-amber-500/15 border border-amber-500/25 text-amber-400 px-1.5 py-0.5 rounded-full uppercase tracking-wide shrink-0">
                                MAX ✓
                            </span>
                        )}
                    </div>

                    {/* Purple Kamas progress bar (toward raid eligibility) */}
                    <div className="space-y-1">
                        <div className="flex items-center gap-2">
                            <div className="flex-1 h-1.5 bg-zinc-800 rounded-full overflow-hidden relative">
                                <div
                                    className={cn(
                                        "h-full rounded-full transition-all duration-700",
                                        isEligible
                                            ? "bg-gradient-to-r from-violet-600 via-fuchsia-500 to-rose-400"
                                            : "bg-gradient-to-r from-zinc-700 to-zinc-500"
                                    )}
                                    style={{ width: `${Math.min(100, (purpleBalance / requiredPurpleKamas) * 100)}%` }}
                                />
                            </div>
                            <div className="flex items-center gap-1 shrink-0 text-[10px] text-zinc-400 font-mono">
                                <KamasVioletIcon size={10} />
                                <span>{purpleBalance}/{requiredPurpleKamas}</span>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Status pill */}
                <div className={cn(
                    "text-[9px] font-bold flex items-center gap-1 px-2.5 py-1.5 rounded-full border shrink-0 hidden sm:flex",
                    statusCfg.className
                )}>
                    {statusCfg.icon}
                    {statusCfg.label}
                </div>

                    {/* Expand toggle */}
                    {member.donations.length > 1 && (
                        <button
                            onClick={() => setExpanded(e => !e)}
                            className="shrink-0 p-1.5 rounded-lg hover:bg-white/5 text-zinc-600 hover:text-zinc-300 transition-colors"
                            title="Voir les détails"
                        >
                            {expanded ? <ChevronUp className="w-3.5 h-3.5" /> : <ChevronDown className="w-3.5 h-3.5" />}
                        </button>
                    )}
                </div>

                {/* Expanded details */}
                {expanded && (
                    <div className="border-t border-white/5 px-4 pb-4 pt-3 space-y-3 animate-in slide-in-from-top-1 duration-150">
                        {/* Individual donations breakdown */}
                        {member.donations.length > 0 && (
                            <div className="space-y-1.5">
                                <p className="text-[10px] uppercase tracking-widest text-zinc-600 font-bold">Détail des dons</p>
                                {member.donations.map((d, i) => {
                                    const dCfg = d.status === "VALIDATED"
                                        ? { label: "Validé", color: "text-emerald-400", dot: "bg-emerald-400" }
                                        : { label: "En attente", color: "text-amber-400", dot: "bg-amber-400" };
                                    return (
                                        <div key={d.id} className="flex items-center gap-2 text-xs">
                                            <div className={cn("w-1.5 h-1.5 rounded-full shrink-0", dCfg.dot)} />
                                            <span className="text-zinc-400">Don #{i + 1}</span>
                                            <span className="font-mono font-bold text-white">
                                                {d.amount.toLocaleString("fr-FR")} k
                                            </span>
                                            <span className={cn("ml-auto", dCfg.color)}>{dCfg.label}</span>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>
                )}
        </div>
    );
}

// ──────────────────────────────────────────────────────────────────────────────
// Main Component
// ──────────────────────────────────────────────────────────────────────────────

interface KamaWeeklySummaryProps {
    data: KamaWeeklySummaryResult;
    isOfficer: boolean;
    guildId?: string;
}

export function KamaWeeklySummary({ data, isOfficer, guildId }: KamaWeeklySummaryProps) {
    const requiredKamas = data.requiredPurpleKamas ?? 30;
    const validatedCount = data.members.filter(m => m.status === "VALIDATED" || m.status === "MIXED").length;
    const eligibleCount = data.members.filter(m => m.purpleKamasBalance >= requiredKamas).length;
    const maxCount = data.members.filter(m => m.totalAmount >= KAMA_MAX_PER_WEEK).length;
    const totalCollected = data.totalValidated + data.totalPending;
