            {/* LEFT: Mobile Trigger & Breadcrumbs */}
            <div className="flex items-center gap-6 shrink-0">

                {/* Mobile Sidebar Trigger */}
                <Sheet>
                    <SheetTrigger asChild>
                        <Button variant="ghost" size="icon" className="lg:hidden -ml-2 text-muted-foreground hover:text-foreground hover:bg-muted rounded-xl">
                            <Menu className="h-5 w-5" />
                        </Button>
                    </SheetTrigger>
                    <SheetContent side="left" className="p-0 w-[260px] border-r border-border bg-zinc-950 shadow-[20px_0_40px_rgba(0,0,0,0.5)]">
