                                    {elixir === 'mineur' ? "[Élixir uchronique mineur]" : elixir === 'ameliore' ? "[Élixir uchronique amélioré]" : "[Élixir uchronique majeur]"}
                                </span> <span className="text-fuchsia-300 font-bold">(tous niveaux)</span></>
