'use client'

import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Star, Users, User as UserIcon, Loader2 } from "lucide-react";
import { MissionInterest, UserProfile, User } from "@prisma/client";
import { cn } from "@/lib/utils";
import { useTransition } from "react";
import { useRouter } from "next/navigation";
import { toggleMissionInterest } from "@/server/actions/mission-actions";
import { toast } from "sonner";

// --- Props ---

interface InterestModalProps {
    isOpen: boolean;
    onClose: () => void;
    missionTitle: string;
    missionId: string;
    interests: (MissionInterest & {
        profile: UserProfile & {
            user: User | null
        }
    })[];
    currentUserId: string;
}

// --- Component ---

export function InterestModal({
    isOpen,
    onClose,
    missionTitle,
    missionId,
    interests,
    currentUserId
}: InterestModalProps) {
    const [isPending, startTransition] = useTransition();
    const router = useRouter();

    const isCurrentUserInterested = interests.some(i => i.profile.userId === currentUserId);

    const handleToggleInterest = () => {
        startTransition(async () => {
            const result = await toggleMissionInterest(missionId);
            if (result.success) {
                toast.success(isCurrentUserInterested ? "Intérêt retiré" : "Intérêt ajouté !");
                router.refresh(); // Force refresh to update the interest list
            } else {
                toast.error(result.error || "Erreur");
            }
        });
    };

    return (
        <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
            <DialogContent className="bg-slate-900 border-slate-700 text-white sm:max-w-md">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2 text-lg">
                        <Users className="w-5 h-5 text-indigo-400" />
                        Intéressés
                    </DialogTitle>
                    <p className="text-sm text-slate-400 mt-1">
                        {missionTitle}
                    </p>
                </DialogHeader>

                <div className="py-4">
                    {interests.length === 0 ? (
                        <div className="text-center py-8 text-slate-500">
                            <Users className="w-10 h-10 mx-auto mb-2 opacity-30" />
                            <p className="text-sm">Personne n'est intéressé pour le moment.</p>
                            <p className="text-xs mt-1">Sois le premier !</p>
                        </div>
                    ) : (
                        <ScrollArea className="max-h-64">
                            <div className="space-y-2 pr-4">
                                {interests.map((interest) => (
                                    <div
                                        key={interest.id}
                                        className={cn(
                                            "flex items-center gap-3 p-3 rounded-lg border transition-colors",
                                            interest.profile.userId === currentUserId
                                                ? "bg-indigo-500/10 border-indigo-500/30"
                                                : "bg-slate-800/50 border-slate-700/50"
                                        )}
                                    >
                                        {/* Avatar Placeholder */}
                                        <div className="w-10 h-10 rounded-full bg-slate-700 flex items-center justify-center border border-slate-600 overflow-hidden">
                                            {interest.profile.user?.image ? (
                                                <img
                                                    src={interest.profile.user.image}
                                                    alt={interest.profile.user.name || "User"}
                                                    className="w-full h-full object-cover"
                                                />
                                            ) : (
                                                <UserIcon className="w-5 h-5 text-slate-400" />
                                            )}
                                        </div>

                                        {/* User Info */}
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-center gap-2">
                                                <span className="font-medium text-white truncate">
                                                    {interest.profile.discordNickname || interest.profile.user?.name || interest.profile.pseudoDofus || "Agent Anonyme"}
                                                </span>
                                                {interest.profile.userId === currentUserId && (
                                                    <span className="text-[10px] bg-indigo-500/20 text-indigo-300 px-1.5 py-0.5 rounded">
                                                        Toi
                                                    </span>
                                                )}
                                            </div>
                                            <div className="text-xs text-slate-500">
                                                {interest.profile.classe || "Classe inconnue"}
                                            </div>
                                        </div>

                                        {/* Star indicator */}
                                        <Star className="w-4 h-4 text-indigo-400 fill-indigo-400" />
                                    </div>
                                ))}
                            </div>
                        </ScrollArea>
                    )}
                </div>

                {/* Action buttons */}
                <div className="flex gap-2 pt-2 border-t border-slate-800">
                    <Button
                        variant="ghost"
                        className="flex-1 text-slate-400 hover:text-white"
                        onClick={onClose}
                    >
                        Fermer
                    </Button>
                    <Button
                        className={cn(
                            "flex-1 gap-2 transition-all",
                            isCurrentUserInterested
                                ? "bg-red-500/20 text-red-300 hover:bg-red-500/30 border border-red-500/30"
                                : "bg-indigo-600 hover:bg-indigo-500 text-white"
                        )}
                        onClick={handleToggleInterest}
                        disabled={isPending}
                    >
                        {isPending ? (
                            <Loader2 className="w-4 h-4 animate-spin" />
                        ) : (
                            <Star className={cn(
                                "w-4 h-4",
                                isCurrentUserInterested ? "" : "fill-white"
                            )} />
                        )}
                        {isCurrentUserInterested ? "Retirer" : "Je suis intéressé"}
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import * as React from "react";
import { Check, ChevronsUpDown, Search, User, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
    Command,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandItem,
    CommandList,
} from "@/components/ui/command";
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from "@/components/ui/popover";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { searchGuildMembers } from "@/server/actions/user-actions";

// Simple debounce hook implementation if not available
function useDebounceValue<T>(value: T, delay: number): T {
    const [debouncedValue, setDebouncedValue] = React.useState<T>(value);
    React.useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedValue(value);
        }, delay);
        return () => {
            clearTimeout(handler);
        };
    }, [value, delay]);
    return debouncedValue;
}

interface Member {
    id: string; // UserProfile ID
    name: string;
    subtitle?: string;
    image?: string | null;
}

interface MemberSelectorProps {
    guildId: string;
    selectedIds: string[];
    onSelect: (ids: string[]) => void;
    maxSelection?: number;
}

export function MemberSelector({ guildId, selectedIds, onSelect, maxSelection = 7 }: MemberSelectorProps) {
    const [open, setOpen] = React.useState(false);
    const [query, setQuery] = React.useState("");
    const [options, setOptions] = React.useState<Member[]>([]);
    const [loading, setLoading] = React.useState(false);
    const [selectedMembers, setSelectedMembers] = React.useState<Member[]>([]); // Cache selected member objects

    const debouncedQuery = useDebounceValue(query, 300);

    // Fetch members on query change
    React.useEffect(() => {
        if (!debouncedQuery || debouncedQuery.length < 2) {
            setOptions([]);
            return;
        }

        let active = true;
        setLoading(true);

        searchGuildMembers(guildId, debouncedQuery).then((res) => {
            if (active && res.success && res.data) {
                setOptions(res.data);
            }
            if (active) setLoading(false);
        });

        return () => { active = false; };
    }, [debouncedQuery, guildId]);

    const handleSelect = (member: Member) => {
        if (selectedIds.includes(member.id)) {
            onSelect(selectedIds.filter(id => id !== member.id));
            setSelectedMembers(prev => prev.filter(m => m.id !== member.id));
        } else {
            if (selectedIds.length >= maxSelection) return;
            onSelect([...selectedIds, member.id]);
            setSelectedMembers(prev => [...prev, member]);
        }
    };

    const handleRemove = (id: string) => {
        onSelect(selectedIds.filter(sid => sid !== id));
        setSelectedMembers(prev => prev.filter(m => m.id !== id));
    };

    return (
        <div className="space-y-3">
            <Popover open={open} onOpenChange={setOpen}>
                <PopoverTrigger asChild>
                    <Button
                        variant="outline"
                        role="combobox"
                        aria-expanded={open}
                        className="w-full justify-between bg-zinc-900/50 border-white/10 text-zinc-300 hover:bg-zinc-900 hover:text-white"
                        disabled={selectedIds.length >= maxSelection}
                    >
                        <span className="flex items-center gap-2">
                            <Search className="w-4 h-4 opacity-50" />
                            {selectedIds.length >= maxSelection
                                ? "Limite atteinte"
                                : "Rechercher des membres..."}
                        </span>
                        <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                    </Button>
                </PopoverTrigger>
                <PopoverContent className="w-[300px] p-0 bg-zinc-900 border-zinc-800 text-white" align="start">
                    <Command shouldFilter={false}>
                        <CommandInput
                            placeholder="Pseudo Dofus ou Discord..."
                            value={query}
                            onValueChange={setQuery}
                            className="bg-transparent border-none focus:ring-0"
                        />
                        <CommandList>
                            {loading && <div className="p-4 text-center text-xs text-zinc-500"><LoaderSpin /> Recherche...</div>}
                            {!loading && options.length === 0 && query.length >= 2 && (
                                <CommandEmpty>Aucun membre trouvé.</CommandEmpty>
                            )}
                            {!loading && query.length < 2 && (
                                <div className="p-4 text-center text-xs text-zinc-500">Tapez 2 lettres pour chercher</div>
                            )}

                            <CommandGroup>
                                {options.map((member) => {
                                    const isSelected = selectedIds.includes(member.id);
                                    return (
                                        <CommandItem
                                            key={member.id}
                                            value={member.id}
                                            onSelect={() => handleSelect(member)}
                                            className="flex items-center gap-2 cursor-pointer hover:bg-zinc-800 aria-selected:bg-zinc-800"
                                        >
                                            <div className="relative">
                                                <Avatar className="h-8 w-8 border border-white/10">
                                                    <AvatarImage src={member.image || undefined} />
                                                    <AvatarFallback className="bg-zinc-800 text-xs">
                                                        {member.name.substring(0, 2).toUpperCase()}
                                                    </AvatarFallback>
                                                </Avatar>
                                                {isSelected && (
                                                    <div className="absolute -top-1 -right-1 bg-emerald-500 rounded-full p-0.5 border border-black">
                                                        <Check className="w-2 h-2 text-black font-bold" />
                                                    </div>
                                                )}
                                            </div>
                                            <div className="flex flex-col">
                                                <span className="text-sm font-medium text-white">{member.name}</span>
                                                {member.subtitle && (
                                                    <span className="text-xs text-zinc-500">{member.subtitle}</span>
                                                )}
                                            </div>
                                        </CommandItem>
                                    );
                                })}
                            </CommandGroup>
                        </CommandList>
                    </Command>
                </PopoverContent>
            </Popover>

            {/* Selected Members Tags */}
            {selectedIds.length > 0 && (
                <div className="flex flex-wrap gap-2">
                    {selectedMembers.map((member) => (
                        <div
                            key={member.id}
                            className="flex items-center gap-2 pl-1 pr-2 py-1 bg-zinc-800 hover:bg-zinc-700 border border-white/10 rounded-full transition-colors group"
                        >
                            <Avatar className="h-6 w-6 border border-white/10">
                                <AvatarImage src={member.image || undefined} />
                                <AvatarFallback className="bg-zinc-700 text-[9px]">
                                    {member.name.substring(0, 2).toUpperCase()}
                                </AvatarFallback>
                            </Avatar>
                            <span className="text-xs font-medium text-zinc-200">{member.name}</span>
                            <button
                                onClick={() => handleRemove(member.id)}
                                className="ml-1 p-0.5 rounded-full hover:bg-red-500/20 hover:text-red-400 text-zinc-500 transition-colors"
                            >
                                <X className="w-3 h-3" />
                            </button>
                        </div>
                    ))}
                </div>
            )}

            <div className="text-[10px] text-zinc-500">
                {selectedIds.length} / {maxSelection} participants sélectionnés
            </div>
        </div>
    );
}

function LoaderSpin() {
    return (
        <svg
            className="animate-spin h-4 w-4 text-zinc-400 mx-auto"
            xmlns="http://www.w3.org/2000/svg"
            fill="none"
            viewBox="0 0 24 24"
        >
            <circle
                className="opacity-25"
                cx="12"
                cy="12"
                r="10"
                stroke="currentColor"
                strokeWidth="4"
            ></circle>
            <path
                className="opacity-75"
                fill="currentColor"
                d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
            ></path>
        </svg>
    );
}

