}

const STATUS_FILTERS: { label: string; value: 'ALL' | 'PENDING' | 'VALIDATED'; icon?: React.ComponentType<{ className?: string }> }[] = [
    { label: "Tout", value: "ALL" },
    { label: "En attente", value: "PENDING", icon: Hourglass },
    { label: "Validé", value: "VALIDATED", icon: CheckCircle2 },
];

// Classic categories only (non-EVENT)
const CATEGORY_FILTERS: { label: string; value: MissionCategory; icon?: React.ComponentType<{ className?: string }> }[] = [
    { label: "Donjon", value: "DONJON", icon: Swords },
    { label: "Régulation", value: "REGULATION", icon: Skull },
    { label: "Anomalie", value: "ANOMALIE", icon: Zap },
    { label: "Songes", value: "SONGES", icon: InfinityIcon },
    { label: "Expédition", value: "EXPEDITION", icon: Clock },
];

// Pool type for Dofus 3.5 split
type MissionPool = 'CLASSIQUES' | 'SPECIALES';


export function MissionBoard({ missions, currentUserId, guildId, isRestricted, availableAt, vitrineMode = false }: MissionBoardProps) {
    const router = useRouter();
    const [selectedCategory, setSelectedCategory] = useState<MissionCategory | 'ALL' | 'PENDING' | 'VALIDATED'>('ALL');
    const [missionPool, setMissionPool] = useState<MissionPool>('CLASSIQUES');
    const [showFilters, setShowFilters] = useState(false);
    const [isPending, startTransition] = useTransition();

    // Interest Modal State
    const [selectedMissionId, setSelectedMissionId] = useState<string | null>(null);

    // Split missions between classic and event pools
    const classicMissions = missions.filter(m => m.category !== 'EVENT');
    const specialMissions = missions.filter(m => m.category === 'EVENT');
    const activeMissions = missionPool === 'CLASSIQUES' ? classicMissions : specialMissions;

    // Filter Logic within active pool
    const filteredMissions = activeMissions.filter(m => {
        if (selectedCategory === 'ALL') return true;
        if (selectedCategory === 'PENDING') return m.submissions?.[0]?.status === 'PENDING';
        if (selectedCategory === 'VALIDATED') return m.submissions?.[0]?.status === 'VALIDATED';
        return m.category === selectedCategory;
    });

    // Count active category filters (ignoring ALL/PENDING/VALIDATED)
    const activeCategoryCount = CATEGORY_FILTERS.some(f => f.value === selectedCategory) ? 1 : 0;

    // Find selected mission for modal
    const selectedMission = selectedMissionId
        ? missions.find(m => m.id === selectedMissionId)
        : null;

    const handleInterestClick = (missionId: string) => {
        setSelectedMissionId(missionId);
    };

    const handleCloseModal = () => {
        setSelectedMissionId(null);
    };

    const handlePoolChange = (pool: MissionPool) => {
        setMissionPool(pool);
        setSelectedCategory('ALL'); // Reset category filter when switching pools
    };

    // Category Styling Map
    const CATEGORY_STYLES: Record<MissionCategory, { bg: string; border: string; text: string; icon: string; shadow: string }> = {
        DONJON: { bg: "bg-indigo-500/10", border: "border-indigo-500/20", text: "text-indigo-400", icon: "text-indigo-400", shadow: "shadow-indigo-500/10" },
        REGULATION: { bg: "bg-rose-500/10", border: "border-rose-500/20", text: "text-rose-400", icon: "text-rose-400", shadow: "shadow-rose-500/10" },
        ANOMALIE: { bg: "bg-fuchsia-500/10", border: "border-fuchsia-500/20", text: "text-fuchsia-400", icon: "text-fuchsia-400", shadow: "shadow-fuchsia-500/10" },
        SONGES: { bg: "bg-cyan-500/10", border: "border-cyan-500/20", text: "text-cyan-400", icon: "text-cyan-400", shadow: "shadow-cyan-500/10" },
        EXPEDITION: { bg: "bg-amber-500/10", border: "border-amber-500/20", text: "text-amber-400", icon: "text-amber-400", shadow: "shadow-amber-500/10" },
        EVENT: { bg: "bg-yellow-500/10", border: "border-yellow-500/20", text: "text-yellow-400", icon: "text-yellow-400", shadow: "shadow-yellow-500/10" },
    };

    return (
        <div className="space-y-6">
            {isRestricted && availableAt && (
                <ResidencyCountdown availableAt={availableAt} className="mb-6" />
            )}
            {/* 🛠️ Simplified Toolbar */}
            <div className="flex flex-col gap-4 bg-zinc-900/40 p-3 rounded-2xl border border-white/5 backdrop-blur-sm">

                {/* PRIMARY ACTIONS ROW */}
                <div className="flex flex-wrap items-center justify-between gap-3">

                    {/* Left: Pool & Status Logic Combined */}
                    <div className="flex items-center gap-2 overflow-x-auto pb-1 sm:pb-0 scrollbar-hide">
                        {/* Pool Toggle */}
                        <div className="flex items-center gap-1 p-1 bg-black/40 border border-white/5 rounded-full shrink-0">
                            {(['CLASSIQUES', 'SPECIALES'] as MissionPool[]).map(pool => {
                                const isActive = missionPool === pool;
                                return (
                                    <button
                                        key={pool}
                                        onClick={() => handlePoolChange(pool)}
                                        className={cn(
                                            "flex items-center gap-2 px-4 py-1.5 text-[10px] font-black rounded-full transition-all uppercase tracking-widest",
                                            isActive
                                                ? pool === 'CLASSIQUES'
                                                    ? "bg-indigo-500 text-white shadow-lg"
                                                    : "bg-yellow-500 text-black shadow-lg"
                                                : "text-zinc-500 hover:text-white"
                                        )}
                                    >
                                        {pool === 'CLASSIQUES' ? '⚔️' : '✨'} {pool}
                                    </button>
                                );
                            })}
                        </div>

                        {!vitrineMode && (
                            <>
                                <div className="h-4 w-px bg-white/10 mx-1" />

                                {/* Status Toggle */}
                                <div className="flex items-center gap-1 p-1 bg-black/40 border border-white/5 rounded-full shrink-0">
                                    {STATUS_FILTERS.map(f => {
                                        const isActive = selectedCategory === f.value;
                                        return (
                                            <button
                                                key={f.value}
                                                onClick={() => setSelectedCategory(f.value)}
                                                className={cn(
                                                    "px-3 py-1.5 text-[10px] font-bold rounded-full transition-all uppercase tracking-wider",
                                                    isActive ? "bg-zinc-100 text-zinc-950 shadow-md" : "text-zinc-500 hover:text-white"
                                                )}
                                            >
                                                {f.label}
                                            </button>
                                        )
                                    })}
                                </div>
                            </>
                        )}
                    </div>

                    {/* Right: Filters & Tools */}
                    <div className="flex items-center gap-2 ml-auto">
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => setShowFilters(!showFilters)}
                            className={cn(
                                "h-9 rounded-full px-4 text-[10px] font-black uppercase tracking-widest transition-all",
                                (showFilters || activeCategoryCount > 0)
                                    ? "bg-white/10 text-white border-white/20"
                                    : "bg-transparent text-zinc-400 border-white/5"
                            )}
                        >
                            <Filter className={cn("w-3.5 h-3.5 mr-2", activeCategoryCount > 0 && "text-emerald-400 animate-pulse")} />
                            Catégories
                            {activeCategoryCount > 0 && (
                                <span className="ml-2 w-4 h-4 rounded-full bg-emerald-500 text-black text-[9px] flex items-center justify-center">
                                    {activeCategoryCount}
                                </span>
                            )}
                        </Button>

                        <Button
                            variant="ghost"
                            size="icon"
                            className="h-9 w-9 text-zinc-500 hover:text-white hover:bg-white/5 rounded-full"
                            onClick={() => startTransition(() => router.refresh())}
                            disabled={isPending}
                        >
                            <RefreshCcw className={cn("w-3.5 h-3.5", isPending && "animate-spin")} />
                        </Button>
                    </div>
                </div>

                {/* SECONDARY: Category Filters (Collapsible) */}
                {showFilters && missionPool === 'CLASSIQUES' && (
                    <div className="pt-2 border-t border-white/5 animate-in slide-in-from-top-2 duration-300">
                        <div className="flex flex-wrap gap-2">
                            {CATEGORY_FILTERS.map(f => {
                                const IconComponent = f.icon;
                                const isActive = selectedCategory === f.value;
                                const style = CATEGORY_STYLES[f.value as MissionCategory];

                                return (
                                    <button
                                        key={f.value}
                                        onClick={() => setSelectedCategory(isActive ? 'ALL' : f.value)}
                                        className={cn(
                                            "group flex items-center gap-2 px-3 py-1.5 text-[10px] font-bold rounded-lg border transition-all",
                                            isActive
                                                ? cn(style.bg, style.border, style.text, "ring-1 ring-white/10")
                                                : "bg-white/5 border-white/10 text-zinc-400 hover:bg-white/10 hover:border-white/20 hover:text-white"
                                        )}
                                    >
                                        {IconComponent && <IconComponent className="w-3 h-3" />}
                                        {f.label}
                                    </button>
                                )
                            })}
                        </div>
                    </div>
                )}
            </div>


            {/* Grid */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {filteredMissions.map((mission) => (
                    <div key={mission.id} className="h-full">
                        <MissionCard
                            mission={mission}
                            currentUserId={currentUserId}
                            guildId={guildId}
                            onInterestClick={handleInterestClick}
                            isRestricted={isRestricted}
                            linkedEvent={(mission as any).linkedEvent}
                            vitrineMode={vitrineMode}
                        />
                    </div>
                ))}

                {filteredMissions.length === 0 ? (
                    <div className="col-span-full py-12">
                        <EmptyState
                            icon={SearchX}
                            title="Aucune mission trouvée"
                            description="Ajustez vos filtres ou revenez plus tard pour voir les nouveaux défis."
                            variant="glow"
                        />
                    </div>
                ) : null}
            </div>

            {/* Interest Modal */}
            {selectedMission && (
                <InterestModal
                    isOpen={!!selectedMissionId}
                    onClose={handleCloseModal}
                    missionTitle={selectedMission.title || "Mission"}
                    missionId={selectedMission.id}
                    interests={selectedMission.interests}
                    currentUserId={currentUserId}
                />
            )}
        </div>
    );
}

'use client'

import { Card, CardContent, CardFooter, CardHeader } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
    Swords,
    Skull,
    Zap,
    Clock,
    MapPin,
    Sparkles,
    Infinity as InfinityIcon,
    Star,
    Upload,
    Users,
    Search,
    ExternalLink,
    AlertTriangle,
    CheckCircle2,
    Hourglass,
    XCircle,
    Loader2,
    ShieldCheck,
    Trophy,
    Calendar as CalendarIcon
} from "lucide-react";
import { Mission, MissionCategory, MissionInterest, UserProfile, User, Submission, SubmissionStatus } from "@prisma/client";
import { cn } from "@/lib/utils";
import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { toggleMissionInterest, cancelMissionSubmission, getMissionValidators } from "@/server/actions/mission-actions";
import { toast } from "sonner";
import Image from "next/image";
import Link from "next/link";
import { ProofUploadDialog } from "./proof-upload-dialog";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";

// --- Props ---

interface MissionCardProps {
    mission: Mission & {
        interests: (MissionInterest & {
            profile: UserProfile & {
                user: User | null
            }
        })[];
        submissions?: Submission[]; // User's submissions for this mission
    };
    currentUserId: string;
    guildId: string; // Discord Guild ID for upload
    onInterestClick?: (missionId: string) => void; // For modal trigger
    isRestricted?: boolean;
    linkedEvent?: { id: string, title: string, startDate: Date } | null;
    vitrineMode?: boolean;
}

// --- Category Config ---

const CATEGORY_CONFIG: Record<MissionCategory, {
    icon: any;
    color: string;
    bgColor: string;
    borderColor: string;
    headerGradient: string;
    bannerImage: string;
    fallbackImage?: string;
    glowColor: string;
    label: string;
    ringColor: string; // CSS color for animated ring
}> = {
    DONJON: {
        icon: Swords,
        color: "text-rose-400",
        bgColor: "bg-rose-950/40",
        borderColor: "border-rose-500/40",
        headerGradient: "from-[#a11a21]/90 via-[#d32f2f]/80 to-[#6b0f14]/90",
        bannerImage: "/banners/donjon.png",
        fallbackImage: "/assets/missions/donjon.png",
        glowColor: "rgba(244, 63, 94, 0.4)",
        ringColor: "#f43f5e",
        label: "Donjon"
    },
    REGULATION: {
        icon: Skull,
        color: "text-emerald-400",
        bgColor: "bg-emerald-950/40",
        borderColor: "border-emerald-500/40",
        headerGradient: "from-[#4b6b1a]/90 via-[#7cb342]/80 to-[#2d4010]/90",
        bannerImage: "/banners/regulation.png",
        fallbackImage: "/assets/missions/regulation.png",
        glowColor: "rgba(52, 211, 153, 0.4)",
        ringColor: "#10b981",
        label: "Régulation"
    },
    ANOMALIE: {
        icon: Zap,
        color: "text-fuchsia-400",
        bgColor: "bg-fuchsia-950/40",
        borderColor: "border-fuchsia-500/40",
        headerGradient: "from-[#7d1a6b]/90 via-[#ab47bc]/80 to-[#4d1040]/90",
        bannerImage: "/banners/anomalie.png",
        fallbackImage: "/assets/missions/ano1.png",
        glowColor: "rgba(217, 70, 239, 0.4)",
        ringColor: "#d946ef",
        label: "Anomalie"
    },
    SONGES: {
        icon: InfinityIcon,
        color: "text-cyan-400",
        bgColor: "bg-cyan-950/40",
        borderColor: "border-cyan-500/40",
        headerGradient: "from-[#1a6b7d]/90 via-[#26c6da]/80 to-[#10404d]/90",
        bannerImage: "/banners/songes.png",
        fallbackImage: "/assets/missions/songes.png",
        glowColor: "rgba(34, 211, 238, 0.4)",
        ringColor: "#22d3ee",
        label: "Songes"
    },
    EXPEDITION: {
        icon: Clock,
        color: "text-amber-400",
        bgColor: "bg-amber-950/40",
        borderColor: "border-amber-500/40",
        headerGradient: "from-[#7d5b1a]/90 via-[#ffa000]/80 to-[#4d3810]/90",
        bannerImage: "/banners/expedition.png",
        fallbackImage: "/assets/missions/expedition.png",
        glowColor: "rgba(251, 191, 36, 0.4)",
        ringColor: "#fbbf24",
        label: "Expédition"
    },
    EVENT: {
        icon: Sparkles,
        color: "text-yellow-300",
        bgColor: "bg-yellow-950/40",
        borderColor: "border-yellow-500/40",
        headerGradient: "from-[#7d6b1a]/90 via-[#fbc02d]/80 to-[#4d4010]/90",
        bannerImage: "/banners/event.png",
        fallbackImage: "/assets/missions/event.png",
        glowColor: "rgba(253, 224, 71, 0.4)",
        ringColor: "#fde047",
        label: "Événement"
    },
};

// --- Component ---

export function MissionCard({ mission, currentUserId, guildId, onInterestClick, isRestricted, linkedEvent, vitrineMode = false }: MissionCardProps) {
    const [isPending, startTransition] = useTransition();
    const [showUploadDialog, setShowUploadDialog] = useState(false);
    const [showValidators, setShowValidators] = useState(false);
    const [isLoadingValidators, setIsLoadingValidators] = useState(false);
    const [validatorsList, setValidatorsList] = useState<any[]>([]);
    const router = useRouter();

    const isInterested = mission.interests.some(i => i.profile.userId === currentUserId);
    const interestCount = mission.interests.length;

    const config = CATEGORY_CONFIG[mission.category];
    const Icon = config.icon;
    const payload = mission.payload as any;

    // Extract image URL from payload — SONGES gets per-difficulty/level image, épreuves get custom image
    const getSongesImage = () => {
        if (mission.category !== 'SONGES') return null;
        if (payload.epreuve) {
            return `/assets/missions/epreuves-songes/${payload.epreuve}.png`;
        }
        const diff: string = (payload.difficulty || 'Reve').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        const levelMap: Record<string, number> = { 'I': 1, 'II': 2, 'III': 3, 'IV': 4 };
        const lvl = levelMap[payload.level as string] || 1;
        return `/assets/missions/${diff}${lvl}.png`;
    };

    const getAnomalieImage = () => {
        if (mission.category !== 'ANOMALIE') return null;
        switch (payload.type) {
            case 'BOSS': return "/assets/missions/ano1.png";
            case 'FRAGMENTS': return "/assets/missions/fragment.png";
            case 'STABILISATION': return "/assets/missions/3-gardiens.png";
            default: return "/assets/missions/anomalie.png";
        }
    };

    const getEventImage = () => {
        if (mission.category !== 'EVENT') return null;
        if (payload.eventType === 'FRAGMENTS_ANOMALIE') {
            return "/assets/missions/fragment.png";
        }
        return payload.imageUrl || null;
    };

    const imageUrl = mission.category === 'SONGES'
        ? getSongesImage()
        : mission.category === 'ANOMALIE'
        ? getAnomalieImage()
        : mission.category === 'EVENT'
        ? getEventImage()
        : (payload.imageUrl || payload.image || (config as any).fallbackImage || null);

    // Check user's submission status for this mission
    const userSubmission = mission.submissions?.[0];
    const isValidated = userSubmission?.status === "VALIDATED";
    const isPendingValidation = userSubmission?.status === "PENDING";
    const isRejected = userSubmission?.status === "REJECTED";

    // Get level from payload
    const displayLevel = payload.level || getDefaultLevel((mission as any).rank || 1);

    // ------------------------------------------------------------------
    // EMPTY STATE
    // ------------------------------------------------------------------
    const isEmpty = !mission.title && (
        (mission.category === 'DONJON' && !payload.dungeonName) ||
        (mission.category === 'REGULATION' && !payload.monsterName && !payload.familyName) ||
        (mission.category === 'ANOMALIE' && !payload.levelRange && !payload.type) ||
        (mission.category === 'SONGES' && !payload.difficulty && !payload.epreuve) ||
        (mission.category === 'EXPEDITION' && !payload.dungeonName) ||
        (mission.category === 'EVENT' && !payload.description && payload.eventType !== 'FRAGMENTS_ANOMALIE')
    );

    if (isEmpty) {
        return (
            <Card className="flex flex-col h-[180px] bg-zinc-950/50 border border-zinc-800/60 border-dashed items-center justify-center p-6 text-center space-y-4 hover:bg-zinc-900/50 transition-colors group">
                <div className="w-12 h-12 rounded-xl bg-zinc-900/50 border border-zinc-800 flex items-center justify-center group-hover:scale-110 transition-transform duration-500 shadow-inner">
                    <Icon className="w-6 h-6 text-zinc-600 group-hover:text-zinc-400 transition-colors" />
                </div>
                <div className="space-y-1 cursor-default">
                    <h3 className="font-semibold text-zinc-400 text-sm tracking-wide">Mission Mystère</h3>
                    <p className="text-[10px] text-zinc-600 font-medium">Dévoilée prochainement</p>
                </div>
            </Card>
        );
    }

    const handleCancel = async () => {
        if (!confirm("Voulez-vous vraiment annuler cette soumission ?")) return;

        startTransition(async () => {
            const result = await cancelMissionSubmission(mission.id);
            if (result.success) {
                toast.success("Soumission annulée.");
                router.refresh();
            } else {
                toast.error(result.error || "Erreur lors de l'annulation");
            }
        });
    };

    const handleToggleInterest = () => {
        startTransition(async () => {
            const result = await toggleMissionInterest(mission.id);
            if (result.success) {
                toast.success(isInterested ? "Intérêt retiré" : "Intérêt ajouté !");
                router.refresh();
            } else {
                toast.error(result.error || "Erreur");
            }
        });
    };

    const handleInterestBadgeClick = (e: React.MouseEvent) => {
        e.stopPropagation();
        if (onInterestClick) {
            onInterestClick(mission.id);
        }
    };

    const handleShowValidators = async () => {
        setShowValidators(true);
        setIsLoadingValidators(true);
        try {
            const res = await getMissionValidators(guildId, mission.id);
            if (res.success && res.data) {
                setValidatorsList(res.data);
            }
        } catch {
            toast.error("Erreur chargement validateurs");
        } finally {
            setIsLoadingValidators(false);
        }
    };

    return (
        <div
            className="mission-card-ring"
            style={{ '--ring-color': config.ringColor } as React.CSSProperties}
        >
            <Card className={cn(
                "flex flex-col relative overflow-hidden transition-all duration-500 group border-white/5 bg-[#121417] shadow-2xl",
                "hover:border-white/10 hover:shadow-[0_0_30px_rgba(0,0,0,0.5)]",
                !vitrineMode && isValidated && "ring-1 ring-emerald-500/40",
                !vitrineMode && isRejected && "ring-1 ring-red-500/40",
                !vitrineMode && isPendingValidation && "ring-1 ring-yellow-500/40"
            )}>
                {/* ----------------- HEADER BAR (Full Width) ----------------- */}
                <div className={cn(
                    "relative z-20 flex items-center gap-4 px-4 py-2.5 shadow-inner border-b border-white/5",
                    "overflow-hidden transition-all duration-500"
                )}>
                    {/* AI BACKGROUND BANNER */}
                    <div className="absolute inset-0 z-0">
                        <Image
                            src={config.bannerImage}
                            alt="Banner"
                            fill
                            className="object-cover opacity-60 mix-blend-luminosity grayscale-[0.2]"
                            unoptimized={true}
                        />
                        <div className={cn(
                            "absolute inset-0 bg-gradient-to-r mix-blend-multiply opacity-90",
                            config.headerGradient
                        )} />
                    </div>

                    {/* Noise texture overlay */}
                    <div className="absolute inset-0 opacity-[0.12] mix-blend-overlay pointer-events-none bg-[url(/noise.svg)] bg-repeat z-10" />

                    {/* Visual indicator (Lueur) */}
                    <div className="absolute inset-x-0 bottom-0 h-[1px] bg-white/20 blur-[1px] z-10" />

                    <div className="relative shrink-0 z-10">
                        <div className="absolute inset-0 bg-white/20 blur-[8px] rounded-full scale-75 opacity-0 group-hover:opacity-100 transition-opacity" />
                        <div className="w-8 h-8 rounded-lg flex items-center justify-center bg-black/40 backdrop-blur-md border border-white/10 shadow-lg relative transition-transform group-hover:scale-105">
                            <Icon className={cn("w-4 h-4", config.color.replace('text-', 'text-white'))} />
                        </div>
                    </div>

                    <div className="flex-1 min-w-0 relative z-10">
                        <h3 className="font-black text-sm sm:text-base text-white truncate drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)] tracking-tight uppercase">
                            {mission.title || getAutoTitle(mission.category, payload)}
                        </h3>
                    </div>

                    {/* Status Badges Pin to Right */}
                    <div className="ml-auto flex gap-2 relative z-10">
                        {!vitrineMode && isValidated && (
                            <div className="flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-emerald-500/90 text-white font-black text-[9px] shadow-lg border border-white/10">
                                <CheckCircle2 className="w-3 h-3" /> <span className="hidden sm:inline">VALIDÉ</span>
                            </div>
                        )}
                        {!vitrineMode && isPendingValidation && (
                            <div className="flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-yellow-500/90 text-black font-black text-[9px] shadow-lg border border-white/10 animate-pulse">
                                <Hourglass className="w-3 h-3" /> <span className="hidden sm:inline">ATTENTE</span>
                            </div>
                        )}
                        {!vitrineMode && isRejected && (
                            <div className="flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-red-500/90 text-white font-black text-[9px] shadow-lg border border-white/10">
                                <XCircle className="w-3 h-3" /> <span className="hidden sm:inline">REFUSÉ</span>
                            </div>
                        )}
                    </div>
