                                        </div>
                                    ))}
                                </div>
                            )}
                        </ScrollArea>
                    </DialogContent>
                </Dialog>
            </Card>
        </div>
    );
}

// --- Helpers ---

function getDefaultLevel(tier: number): number {
    switch (tier) {
        case 1: return 50;
        case 2: return 100;
        case 3: return 150;
        case 4: return 190;
        case 5: return 200;
        default: return 200;
    }
}

function getAutoTitle(category: MissionCategory, payload: any): string {
    switch (category) {
        case "DONJON": return payload.dungeonName || "Donjon Mystérieux";
        case "REGULATION": return (payload.monsterName || payload.familyName) ? `Régulation des ${payload.monsterName || payload.familyName}` : "Régulation";
        case "ANOMALIE": return payload.type === 'BOSS' ? `Gardien d'anomalie ${payload.levelRange || '200'}` : payload.type === 'FRAGMENTS' ? `Collecte Fragments` : payload.type === 'STABILISATION' ? `Stabilisation Gardiens` : "Au cœur de l'anomalie";
        case "SONGES": return payload.epreuve ? `Réaliser l'épreuve de Songe ${payload.epreuve}` : (payload.difficulty && payload.level ? `Plongée en ${payload.difficulty} ${payload.level}` : "Songes Infinis");
        case "EXPEDITION": return payload.dungeonName ? `Expédition de ${payload.dungeonName}` : "Expédition";
        case "EVENT":
            if (payload.eventType === 'FRAGMENTS_ANOMALIE') return payload.title || "Fragments d'anomalie";
            return payload.title || "Événement Spécial";
        default: return "Mission";
    }
}

function generateDescription(category: MissionCategory, payload: any): React.ReactNode {
    switch (category) {
        case "DONJON":
            return (
                <>Vaincre <span className="text-rose-400 font-medium">{payload.bossName || "le Boss"}</span> dans son donjon</>
            );
        case "REGULATION":
            const targetName = payload.monsterName || payload.familyName || "monstres";
            return (
                <>Vaincre <span className="text-emerald-400 font-medium">50 {targetName}</span> sur leur territoire</>
            );
        case "ANOMALIE":
            const range = payload.levelRange || "200";
            if (payload.type === 'BOSS') {
                return (
                    <>Vaincre un <span className="text-fuchsia-400 font-bold">gardien d'anomalie</span> de niveau <span className="text-fuchsia-400 font-bold">{range}</span> sous l'effet d'un <span className="text-fuchsia-400 font-bold">Elixir uchronique</span></>
                );
            }
            if (payload.type === 'GARDIENS') {
                return (
                    <>Vaincre <span className="text-fuchsia-400 font-bold">3 gardiens d'anomalie</span> de niveau <span className="text-fuchsia-400 font-bold">{range}</span> sous l'effet d'un <span className="text-fuchsia-400 font-bold">Elixir uchronique</span></>
                );
            }
            if (payload.type === 'COLLECTE') {
                const frag = payload.fragmentLevel || 1;
                return (
                    <>Collecter des <span className="text-fuchsia-400 font-bold">Fragments d'anomalie {frag}</span></>
                );
            }
            if (payload.type === 'FRAGMENTS') {
                return (
                    <>Obtenir <span className="text-fuchsia-400 font-bold">20 Fragments d'anomalie</span> dans une anomalie (tous niveaux)</>
                );
            }
            if (payload.type === 'STABILISATION') {
                const elixir = payload.elixir || 'majeur';
                if (elixir === 'aucun') {
                    return (
                        <>Vaincre <span className="text-fuchsia-400 font-bold">3 Gardiens des anomalies</span> (tous niveaux)</>
                    );
                }
                const labelMap: Record<string, string> = {
                    mineur: "Élixir uchronique mineur",
                    ameliore: "Élixir uchronique amélioré",
                    majeur: "Élixir uchronique majeur"
                };
                const elixirLabel = labelMap[elixir as keyof typeof labelMap] || labelMap.majeur;
                return (
                    <>Vaincre <span className="text-fuchsia-400 font-bold">3 Gardiens des anomalies</span> sous l'effet d'un <span className="text-fuchsia-400 font-bold">[{elixirLabel}]</span> (tous niveaux)</>
                );
            }
            return (
                <>Vaincre <span className="text-fuchsia-400 font-bold">50 monstres</span> dans une zone de niveau <span className="text-fuchsia-400 font-bold">{range}</span> sous l'effet d'un <span className="text-fuchsia-400 font-bold">Elixir uchronique</span></>
            );
        case "SONGES":
            if (payload.epreuve) {
                return (
                    <>Terminer l'épreuve de Songe <span className="text-cyan-400 font-bold">{payload.epreuve}</span></>
                );
            }
            const palierNames: Record<number, string> = {
                1: "Pensées oniriques",
                2: "Balades fantastiques",
                3: "Espaces imaginaires",
                4: "Concepts brumeux",
                5: "Abstractions chimériques"
            };
            const palierName = palierNames[payload.tier] || palierNames[2];
            return (
                <>Démarrer un songe en <span className="text-cyan-400 font-medium">{payload.difficulty || "Paradoxe"} {payload.level || "I"}</span> et terminer le Palier {payload.tier || 2} : les <span className="text-cyan-400">{palierName}</span></>
            );
        case "EXPEDITION":
            const modeText = payload.mode && payload.mode !== 'aucun' ? ` de ${payload.mode}` : '';
            return (
                <>Vaincre <span className="text-amber-400 font-medium">{payload.bossName || "le Boss"}</span> dans son expédition{modeText}</>
            );
        case "EVENT":
            if (payload.eventType === 'FRAGMENTS_ANOMALIE') {
                return (
                    <>Obtenir <span className="text-fuchsia-400 font-bold">20 Fragments d'anomalie</span> dans une anomalie (tous niveaux)</>
                );
            }
            if (payload.eventType === 'OBJECTIF' || payload.description) {
                return <>{payload.description || "Participer à l'événement."}</>;
            }
            if (payload.eventType === 'MONSTRE_SPECIAL' && payload.monsterName) {
                return (
                    <>Vaincre <span className="text-purple-400 font-bold">{payload.targetCount || 50} {payload.monsterName}</span></>
                );
            }
            if (payload.eventType === 'DONJON' && payload.bossName) {
                return (
                    <>Vaincre <span className="text-rose-400 font-medium">{payload.bossName}</span> dans son donjon</>
                );
            }
            if (payload.eventType === 'REGULATION' && (payload.familyName || payload.zoneName)) {
                const target = payload.familyName || "monstres";
                return (
                    <>Vaincre <span className="text-amber-400 font-medium">50 {target}</span> sur leur territoire</>
                );
            }
            return <>{payload.description || "Participer à l'événement."}</>;
        default:
            return "Compléter l'objectif demandé.";
    }
}

'use client'

import { useState, useEffect, useCallback } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardFooter } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from "@/components/ui/dialog";
import { createWeekMissions, resetMission, resetWeek, getWeekMissions, updateWeekTier } from "@/server/actions/mission-actions";
import { getDofusConfig, updateGuildHallConfig } from "@/server/actions/admin-actions";
import { toast } from "sonner";
import { Save, Trash2, Edit2, RotateCcw, Check, Loader2, AlertTriangle, Send, Swords, Sparkles, Home, ChevronDown, MapPin, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { CATEGORY_CONFIG, MISSION_CATEGORIES, type MissionCategoryType } from "@/lib/mission-config";
import { getDofusWeek } from "@/lib/date-utils";
import { useRouter } from "next/navigation";
import { BonusMenuButton } from "@/components/admin/BonusMenuButton";
import { MissionPublishFlowDialog } from "./mission-publish-flow-dialog";
import { GuidePulse } from "@/components/dashboard/guide-pulse";
import { DOFUS_WORLDS } from "@/lib/dofus-assets";
import {
    DungeonForm,
    RegulationForm,
    AnomalieForm,
    SongesForm,
    SongesEpreuveForm,
    ExpeditionForm,
    EventForm
} from "./category-forms";

// --- Types ---

type DraftMission = {
    slotIndex: number; // 0-11
    category: MissionCategoryType;
    rank: number;
    title: string;
    xpReward: number;
    guildatonsReward: number;
    payload: Record<string, any>;
};

const DEFAULT_mission_TEMPLATE = (index: number): DraftMission => ({
    slotIndex: index,
    category: index >= 12 ? "EVENT" : "DONJON", // Slots 12-17 are for SPECIALES (EVENT)
    rank: 1,
    title: "",
    xpReward: 300,
    guildatonsReward: 50,
    payload: index >= 12 ? { eventType: 'REGULATION' } : { boss: "" }
});

type MissionPool = 'CLASSIQUES' | 'SPECIALES';

// --- Component ---

export function MissionEditor({ guildId, isDiscordConfigured }: { guildId: string; isDiscordConfigured?: boolean }) {
    const router = useRouter();
    const { week: weekNumber, year } = getDofusWeek();

    const [missions, setMissions] = useState<DraftMission[]>(
        Array.from({ length: 18 }).map((_, i) => DEFAULT_mission_TEMPLATE(i))
    );

    const [missionPool, setMissionPool] = useState<MissionPool>('CLASSIQUES');
    const [globalTier, setGlobalTier] = useState<number>(3);
    const [guildDefaultTier, setGuildDefaultTier] = useState<number>(3);
    const [editingSlot, setEditingSlot] = useState<number | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [isResetting, setIsResetting] = useState(false);
    const [confirmPublishOpen, setConfirmPublishOpen] = useState(false);

    // Guild Hall Config state
    const [hallPanelOpen, setHallPanelOpen] = useState(false);
    const [hallPosX, setHallPosX] = useState<number | null>(null);
    const [hallPosY, setHallPosY] = useState<number | null>(null);
    const [hallWorldId, setHallWorldId] = useState<number>(1);
    const [isSavingHall, setIsSavingHall] = useState(false);

    // Slots for current pool
    const poolMissions = missionPool === 'CLASSIQUES'
        ? missions.slice(0, 12)  // slots 0-11
        : missions.slice(12, 18); // slots 12-17

    // Fetch Data on Week Change
    const fetchData = useCallback(async () => {
        setIsLoading(true);
        try {
            // Load guild default tier (for fallback when no missions exist yet)
            const configRes = await getDofusConfig(guildId);
            const guildTier = configRes.success && configRes.data?.missionTier ? configRes.data.missionTier : 3;
            setGuildDefaultTier(guildTier);

            // Load guild hall config
            if (configRes.success && configRes.data) {
                setHallPosX(configRes.data.guildHallPosX ?? null);
                setHallPosY(configRes.data.guildHallPosY ?? null);
                setHallWorldId(configRes.data.guildHallWorldId ?? 1);
            }

            const res = await getWeekMissions(guildId, weekNumber, year);
            if (res.success && res.data) {
                const fetched = res.data;
                // Build 18 slots: 0-11 classic, 12-17 special
                const newMissions = Array.from({ length: 18 }).map((_, i) => {
                    const existing = fetched.find((m: any) => m.slotIndex === i);
                    if (existing) {
                        return {
                            slotIndex: i,
                            category: existing.category,
                            rank: existing.rank || 1,
                            title: existing.title || "",
                            xpReward: existing.xpReward || 0,
                            guildatonsReward: existing.guildatonsReward || 0,
                            payload: existing.payload || {}
                        };
                    }
                    return DEFAULT_mission_TEMPLATE(i);
                });
                setMissions(newMissions);

                // Use the tier from existing missions if available, else fall back to guild default
                const foundTier = (fetched as any[]).find((m: any) => m.tier)?.tier;
                setGlobalTier(foundTier || guildTier);
            } else {
                // No missions yet this week — use guild default
                setGlobalTier(guildTier);
            }
        } catch (e: unknown) {
            toast.error("Erreur de chargement");
        } finally {
            setIsLoading(false);
        }
    }, [guildId, weekNumber, year]);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    const handleSaveSingle = async (slot: number) => {
        const mission = missions[slot];
        
        // Local uniqueness check
        const currentSig = `${mission.category}-${globalTier}-${mission.rank}-${mission.title}-${JSON.stringify(mission.payload)}`;
        const isDuplicate = missions.some((m, idx) => {
            if (idx === slot || !m.title) return false;
            const sig = `${m.category}-${globalTier}-${m.rank}-${m.title}-${JSON.stringify(m.payload)}`;
            return sig === currentSig;
        });

        if (isDuplicate) {
            toast.error(`Doublon détecté : La mission "${mission.title}" est déjà configurée dans un autre slot.`);
            return;
        }

        const promise = createWeekMissions({
            guildId,
            weekNumber,
            year,
            missions: [{ ...mission, tier: globalTier }],
            updateGuildTier: missionPool === 'CLASSIQUES' ? globalTier : undefined
        });

        toast.promise(promise, {
            loading: 'Sauvegarde...',
            success: 'Mission sauvegardée !',
            error: 'Erreur sauvegarde'
        });

        const res = await promise;
        if (res.success) {
            fetchData();
        }
    };

    const handleResetSingle = async (slot: number) => {
        if (!confirm("Effacer cette mission ?")) return;

        const res = await resetMission(guildId, weekNumber, year, slot);
        if (res.success) {
            updateMission(slot, DEFAULT_mission_TEMPLATE(slot));
            toast.success("Mission effacée");
        } else {
            toast.error("Erreur effacement");
        }
    };

    const handleGlobalPublish = async () => {
        // Uniqueness check (Frontend safety)
        const seen = new Set<string>();
        const duplicates = [];
        for (const m of poolMissions) {
            if (!m.title) continue;
            const sig = `${m.category}-${globalTier}-${m.rank}-${m.title}-${JSON.stringify(m.payload)}`;
            if (seen.has(sig)) duplicates.push(m.title);
            seen.add(sig);
        }

        if (duplicates.length > 0) {
            toast.error(`Doublon détecté : "${duplicates[0]}". Chaque mission doit être unique.`);
            return { success: false, error: "Duplicate missions" };
        }

        setIsSaving(true);
        // Only publish missions from the current pool
        const res = await createWeekMissions({
            guildId,
            weekNumber,
            year,
            missions: poolMissions.filter(m => m.title).map(m => ({ ...m, tier: globalTier })),
            updateGuildTier: missionPool === 'CLASSIQUES' ? globalTier : undefined,
            notifyMembers: true
        });
        setIsSaving(false);

        if (res.success) {
            toast.success(missionPool === 'CLASSIQUES' ? "Missions classiques sauvegardées !" : "Missions spéciales sauvegardées !");
            fetchData();
            return { success: true };
        } else {
            toast.error(res.error || "Erreur globale");
            return { success: false, error: res.error };
        }
    };

    const handleResetWeek = async () => {
        if (!confirm("⚠️ ATTENTION: Voulez-vous vraiment TOUT EFFACER pour cette semaine ? Cette action est irréversible.")) return;

        setIsResetting(true);
        try {
            const res = await resetWeek(guildId, weekNumber, year);
            if (res.success) {
                setMissions(Array.from({ length: 18 }).map((_, i) => DEFAULT_mission_TEMPLATE(i)));
                toast.success("Semaine réinitialisée avec succès");
            } else {
                toast.error(res.error || "Erreur lors de la réinitialisation");
            }
        } catch (error) {
            toast.error("Erreur réseau ou serveur");
        } finally {
            setIsResetting(false);
        }
    };

    const updateMission = (slot: number, updates: Partial<DraftMission>) => {
        setMissions(prev => prev.map(m => m.slotIndex === slot ? { ...m, ...updates } : m));
    };

    /** Returns an error string if the mission is incomplete, null if valid */
    const validateMission = (m: DraftMission): string | null => {
        if (!m.title?.trim()) {
            switch (m.category) {
                case 'DONJON': return "Sélectionnez un donjon.";
                case 'EXPEDITION': return "Sélectionnez un donjon pour l’expédition.";
                case 'REGULATION': return "Sélectionnez une zone ou une famille de monstres.";
                case 'ANOMALIE': return "Configurez l’anomalie (zone requise).";
                case 'SONGES': return "Configurez les songes.";
                case 'EVENT': return "Renseignez le titre et le type de mission événement.";
                default: return "Champs requis manquants.";
            }
        }
        // Extra field checks per category
        if (m.category === 'DONJON' && !m.payload?.dungeonId)
            return "Sélectionnez un donjon dans la liste.";
        if (m.category === 'EXPEDITION' && !m.payload?.dungeonId)
            return "Sélectionnez un donjon pour l’expédition.";
        if (m.category === 'REGULATION' && !m.payload?.familyId && !m.payload?.zoneId)
            return "Sélectionnez au moins une zone ou une famille.";
        if (m.category === 'EVENT' && m.payload?.eventType === 'OBJECTIF' && !m.payload?.description?.trim())
            return "Rédigez l'objectif de la mission.";
        return null;
    };

    const handleSaveFromDialog = (slot: number) => {
        const mission = missions[slot];
        const error = validateMission(mission);
        if (error) {
            toast.error(error, { description: "Complétez tous les champs avant d’enregistrer." });
            return;
        }
        handleSaveSingle(slot);
        setEditingSlot(null);
    };

    const currentMission = editingSlot !== null ? missions[editingSlot] : null;

    const handleGlobalTierChange = async (e: React.ChangeEvent<HTMLSelectElement>) => {
        const newTier = parseInt(e.target.value);
        setGlobalTier(newTier);

        setIsLoading(true);
        const res = await updateWeekTier(guildId, weekNumber, year, newTier);
        setIsLoading(false);

        if (res.success) {
            toast.success(`Palier hebdomadaire mis à jour : Palier ${newTier}`);
            router.refresh();
        } else {
            toast.error(res.error || "Erreur lors de la mise à jour du palier.");
        }
    };

    return (
        <div className="space-y-6">
            {!isDiscordConfigured && (
                <div className="bg-amber-500/10 border border-amber-500/20 rounded-xl p-4 flex items-start gap-4 shadow-lg backdrop-blur-sm">
                    <div className="p-2 bg-amber-500/20 rounded-lg text-amber-500">
                        <AlertTriangle className="w-5 h-5" />
                    </div>
                    <div className="flex-1">
                        <h4 className="text-sm font-black text-amber-500 uppercase tracking-widest mb-1">Configuration Discord Absente</h4>
                        <p className="text-xs text-amber-200/70 leading-relaxed font-medium">
                            Le salon de notification des missions n&apos;est pas configuré dans les paramètres de la guilde.
                            <span className="text-amber-400 font-bold ml-1 italic text-[10px] sm:text-xs">
                                Le bouton d&apos;Annonce Discord est masqué pour éviter les pings invalides.
                            </span>
                        </p>
                    </div>
                </div>
            )}

            {/* Toolbar */}
            <div className="flex flex-col md:flex-row items-center justify-between bg-zinc-900 border border-zinc-800 p-4 rounded-xl gap-4">
                <div className="flex flex-wrap items-center gap-4">
                    <div className="flex items-center gap-2">
                        <span className="text-sm text-zinc-400">Semaine</span>
                        <span className="h-9 px-3 flex items-center bg-zinc-950 border border-zinc-800 rounded text-sm text-white font-mono font-bold">
                            {weekNumber}
                        </span>
                    </div>
                    <div className="flex items-center gap-2">
                        <span className="text-sm text-zinc-400">Année</span>
                        <span className="h-9 px-3 flex items-center bg-zinc-950 border border-zinc-800 rounded text-sm text-white font-mono">
                            {year}
                        </span>
                    </div>

                    <div className="w-px h-8 bg-zinc-800 mx-2 hidden sm:block"></div>

                    <div className="flex items-center gap-2">
                        <label className="text-sm text-zinc-400 font-medium">Palier semaine</label>
                        <select
                            className="h-9 w-32 rounded-md border border-zinc-800 bg-zinc-950 px-2 py-1 text-sm text-white focus:ring-2 focus:ring-indigo-500/50 outline-none disabled:opacity-50"
                            value={globalTier}
                            onChange={handleGlobalTierChange}
                            disabled={isLoading}
                        >
                            {[1, 2, 3, 4, 5].map(t => (
                                <option key={t} value={t}>Palier {t}</option>
                            ))}
                        </select>
                        {globalTier !== guildDefaultTier && (
                            <span className="text-[10px] text-zinc-600 italic">Défaut guilde : {guildDefaultTier}</span>
                        )}
                        <GuidePulse description="Définit le nombre total de points requis par la guilde cette semaine pour débloquer les récompenses." />
                    </div>

                    {isLoading && <Loader2 className="w-4 h-4 animate-spin text-zinc-500" />}
                </div>

                <div className="flex items-center gap-2 p-1 bg-black/40 border border-white/5 rounded-xl shadow-inner backdrop-blur-md">
                    <BonusMenuButton guildId={guildId} />
                    
                    <div className="w-px h-6 bg-white/10 mx-1" />

                    {/* Guild Hall Config Button */}
                    <button
                        type="button"
                        onClick={() => setHallPanelOpen(v => !v)}
                        className={cn(
                            "h-9 px-3 flex items-center gap-1.5 rounded-lg text-xs font-bold transition-all",
                            hallPanelOpen
                                ? "bg-cyan-500/20 text-cyan-300 border border-cyan-500/30"
                                : "text-zinc-400 hover:text-cyan-400 hover:bg-cyan-500/10"
                        )}
                    >
                        <Home className="w-3.5 h-3.5" />
                        <span className="hidden sm:inline">Hall</span>
                        {(hallPosX !== null && hallPosY !== null) && (
                            <span className="w-1.5 h-1.5 rounded-full bg-cyan-400 animate-pulse" />
                        )}
                    </button>

                    <div className="w-px h-6 bg-white/10 mx-1" />

                    <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        className="h-9 px-3 text-zinc-400 hover:text-rose-400 hover:bg-rose-500/10"
                        onClick={handleResetWeek}
                        disabled={isResetting || isLoading}
                    >
                        {isResetting ? (
                            <Loader2 className="w-4 h-4 animate-spin" />
                        ) : (
                            <Trash2 className="w-4 h-4 mr-2" />
                        )}
                        <span className="hidden sm:inline">Reset Semaine</span>
                    </Button>

                    <div className="w-px h-6 bg-white/10 mx-1" />

                    <Button 
                        onClick={() => setConfirmPublishOpen(true)} 
                        variant="sigil" 
                        className="h-9 px-6 shadow-lg shadow-indigo-500/20" 
                        size="sm"
                        disabled={isLoading}
                    >
                        <Save className="w-4 h-4 mr-2" />
                        TOUT PUBLIER
                    </Button>
                </div>
            </div>

            {/* Guild Hall Config Panel */}
            {hallPanelOpen && (
                <div className="border border-cyan-500/20 bg-cyan-500/5 backdrop-blur-md rounded-2xl p-5 space-y-4 animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                            <div className="p-1.5 rounded-lg bg-cyan-500/10 border border-cyan-500/20">
                                <Home className="w-4 h-4 text-cyan-400" />
                            </div>
                            <div>
                                <p className="text-sm font-black text-white">Hall de Guilde</p>
                                <p className="text-[10px] text-zinc-500">Position du point de ralliement visible par tous les membres.</p>
                            </div>
                        </div>
                        <button onClick={() => setHallPanelOpen(false)} className="p-1.5 rounded-lg text-zinc-600 hover:text-zinc-300 hover:bg-white/5 transition-all">
                            <X className="w-4 h-4" />
                        </button>
                    </div>

                    <div className="grid grid-cols-3 gap-3">
                        <div>
                            <label className="text-[10px] font-black text-cyan-400 uppercase tracking-wider block mb-1">Position X</label>
                            <input
                                type="number"
                                value={hallPosX ?? ""}
                                onChange={(e) => setHallPosX(e.target.value ? Number(e.target.value) : null)}
                                placeholder="Ex: -3"
                                className="w-full bg-zinc-950/60 border border-white/10 hover:border-cyan-500/30 focus:border-cyan-500 rounded-xl px-3 py-2 text-sm font-bold text-white text-center outline-none transition-all"
                            />
                        </div>
                        <div>
                            <label className="text-[10px] font-black text-cyan-400 uppercase tracking-wider block mb-1">Position Y</label>
                            <input
                                type="number"
                                value={hallPosY ?? ""}
                                onChange={(e) => setHallPosY(e.target.value ? Number(e.target.value) : null)}
                                placeholder="Ex: -56"
                                className="w-full bg-zinc-950/60 border border-white/10 hover:border-cyan-500/30 focus:border-cyan-500 rounded-xl px-3 py-2 text-sm font-bold text-white text-center outline-none transition-all"
                            />
                        </div>
                        <div>
                            <label className="text-[10px] font-black text-cyan-400 uppercase tracking-wider block mb-1">Monde</label>
                            <div className="relative">
                                <select
                                    value={hallWorldId}
                                    onChange={(e) => setHallWorldId(Number(e.target.value))}
                                    className="w-full bg-zinc-950/60 border border-white/10 hover:border-cyan-500/30 focus:border-cyan-500 rounded-xl pl-3 pr-7 py-2 text-[11px] font-bold text-white outline-none appearance-none transition-all cursor-pointer"
                                >
                                    {DOFUS_WORLDS.map(w => (
                                        <option key={w.id} value={w.id} className="bg-zinc-950 text-white text-xs">{w.name}</option>
                                    ))}
                                </select>
                                <ChevronDown className="absolute right-2 top-1/2 -translate-y-1/2 w-3 h-3 text-zinc-500 pointer-events-none" />
                            </div>
                        </div>
                    </div>

                    {hallPosX !== null && hallPosY !== null && (
                        <p className="text-[10px] text-cyan-400/70 font-mono text-center">
                            /travel {hallPosX} {hallPosY}
                        </p>
                    )}

                    <div className="flex justify-end">
                        <Button
                            size="sm"
                            disabled={isSavingHall}
                            onClick={async () => {
                                setIsSavingHall(true);
                                const res = await updateGuildHallConfig(guildId, {
                                    posX: hallPosX,
                                    posY: hallPosY,
                                    worldId: hallWorldId
                                });
                                setIsSavingHall(false);
                                if (res.success) {
                                    toast.success("Hall de Guilde configuré !");
                                    setHallPanelOpen(false);
                                } else {
                                    toast.error(res.error || "Erreur");
                                }
                            }}
                            className="px-6 bg-cyan-600 hover:bg-cyan-500 text-white font-bold rounded-xl transition-all shadow-lg shadow-cyan-500/20"
                        >
                            {isSavingHall ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                            Sauvegarder
                        </Button>
                    </div>
                </div>
            )}

            {/* Pool Toggle — Dofus 3.5 Classiques / Spéciales */}
            <div className="flex items-center gap-3 flex-wrap w-full">
                <div className="flex items-center gap-1 p-1 bg-black/60 backdrop-blur-md border border-white/10 rounded-2xl sm:rounded-full shadow-lg flex-wrap sm:flex-nowrap w-full sm:w-auto">
                    {(['CLASSIQUES', 'SPECIALES'] as MissionPool[]).map(pool => {
                        const isActive = missionPool === pool;
                        const count = pool === 'CLASSIQUES' ? missions.slice(0, 12).filter(m => m.title).length : missions.slice(12, 18).filter(m => m.title).length;
                        const total = pool === 'CLASSIQUES' ? 12 : 6;
                        return (
                            <button
                                key={pool}
                                onClick={() => setMissionPool(pool)}
                                className={cn(
                                    "flex-1 sm:flex-none relative flex items-center justify-center gap-1.5 sm:gap-2 px-2 py-2 sm:px-5 text-[10px] sm:text-xs font-black rounded-full transition-all duration-300 uppercase tracking-widest min-w-0",
                                    isActive
                                        ? pool === 'CLASSIQUES'
                                            ? "bg-indigo-500 text-white shadow-[0_0_20px_rgba(99,102,241,0.4)]"
                                            : "bg-yellow-500 text-black shadow-[0_0_20px_rgba(234,179,8,0.5)]"
                                        : "text-zinc-400 hover:text-white hover:bg-white/10"
                                )}
                            >
                                {pool === 'CLASSIQUES' ? <Swords className="w-3.5 h-3.5" /> : <Sparkles className="w-3.5 h-3.5" />}
                                {pool}
                                <span className={cn(
                                    "text-[9px] font-black px-1.5 py-0.5 rounded-full min-w-[18px] text-center",
                                    isActive
                                        ? pool === 'CLASSIQUES' ? "bg-white/20 text-white" : "bg-black/20 text-black"
                                        : "bg-zinc-700 text-zinc-300"
                                )}>
                                    {count}/{total}
                                </span>
                            </button>
                        );
                    })}
                </div>
                {missionPool === 'SPECIALES' && (
                    <span className="text-[10px] text-yellow-400/70 font-medium hidden sm:flex items-center gap-1">
                        <Sparkles className="w-3 h-3" /> Missions spéciales — jusqu'à 6 missions (Dofus 3.5)
                    </span>
                )}
                {isLoading && <Loader2 className="w-4 h-4 animate-spin text-zinc-500" />}
            </div>

            {/* Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                {poolMissions.map((mission) => {
                    const isEmpty = !mission.title;
                    const config = CATEGORY_CONFIG[mission.category] || CATEGORY_CONFIG.DONJON;
                    const borderColor = isEmpty ? "border-zinc-800" : config.borderColor;
                    const glowColor = isEmpty ? "rgba(255,255,255,0.1)" : config.glowColor;
                    const badgeStyle = isEmpty ? "" : `${config.color} ${config.borderColor} ${config.bgColor}`;

                    const getPayloadPreview = (category: MissionCategoryType, payload: Record<string, any>): React.ReactNode => {
                        if (!payload || Object.keys(payload).length === 0) return null;
                        switch (category) {
                            case 'DONJON': {
                                const name = payload.dungeonName;
                                const boss = payload.bossName;
                                return name ? (
                                    <span className="text-violet-300 font-medium">
                                        {name}{boss ? <span className="text-zinc-500 font-normal"> · {boss}</span> : null}
                                    </span>
                                ) : null;
                            }
                            case 'ANOMALIE': {
                                const typeLabel = payload.type === 'BOSS' ? '🐉 Gardien' : payload.type === 'ZONE' ? '⚔️ Zone' : payload.type;
                                const level = payload.levelRange ? `Niv. ${payload.levelRange}` : null;
                                return <span className="text-fuchsia-300">{[typeLabel, level].filter(Boolean).join(' · ')}</span>;
                            }
                            case 'REGULATION': {
                                const zone = payload.zoneName;
                                const monster = payload.monsterName || payload.familyName;
                                return <span className="text-amber-300">{[zone, monster].filter(Boolean).join(' · ')}</span>;
                            }
                            case 'SONGES': {
                                const diff = payload.difficulty;
                                const lvl = payload.level ? `Niv. ${payload.level}` : null;
                                return <span className="text-cyan-300">{[diff, lvl].filter(Boolean).join(' ')}</span>;
                            }
                            case 'EXPEDITION': {
                                const name = payload.dungeonName;
                                const modeLabels: Record<string, string> = { bravoure: 'Bravoure', audace: 'Audace', aucun: 'Sans modif.' };
                                const mode = payload.mode ? modeLabels[payload.mode] || payload.mode : null;
                                return <span className="text-emerald-300">{[name, mode].filter(Boolean).join(' · ')}</span>;
                            }
                            case 'EVENT': {
                                if (payload.eventType === 'FRAGMENTS_ANOMALIE') {
                                    return <span className="text-fuchsia-300 font-medium">⚡ 20 Fragments d'anomalie</span>;
                                }
                                if (payload.eventType === 'OBJECTIF') {
                                    return payload.description ? <span className="text-cyan-300 truncate font-medium">📜 {payload.description}</span> : null;
                                }
                                return payload.description ? <span className="text-rose-300 truncate">{payload.description}</span> : null;
                            }
                            default: {
                                const first = Object.values(payload).find(v => v && typeof v === 'string');
                                return first ? <span className="text-zinc-400">{String(first)}</span> : null;
                            }
                        }
                    };
                    const payloadPreview = mission.title ? getPayloadPreview(mission.category, mission.payload) : null;

                    return (
                        <Card
                            key={mission.slotIndex}
                            className={cn(
                                "relative group transition-all duration-300 flex flex-col h-full",
                                "bg-zinc-900 shadow-xl",
                                isEmpty
                                    ? "bg-zinc-950/50 border-zinc-800/60 border-dashed hover:bg-zinc-900/80"
                                    : cn("border hover:shadow-[0_0_25px_-5px_var(--glow-color)]", borderColor)
                            )}
                            style={{ "--glow-color": glowColor } as React.CSSProperties}
                        >
                            <CardHeader className="p-4 flex flex-row items-center justify-between pb-2 space-y-0 relative z-10">
                                <div className="flex items-center gap-2">
                                    <span className={cn(
                                        "text-[10px] font-black px-1.5 py-0.5 rounded transition-colors",
                                        isEmpty ? "bg-zinc-800 text-zinc-500" : "bg-white/10 text-white border border-white/10"
                                    )}>
                                        #{mission.slotIndex + 1}
                                    </span>
                                    <Badge variant="outline" className={cn("text-[10px] h-5 px-1.5 transition-colors uppercase tracking-tight", badgeStyle)}>
                                        {mission.category}
                                    </Badge>
                                </div>
                                <div className="flex items-center gap-1 opacity-100 sm:opacity-0 group-hover:opacity-100 transition-opacity">
                                    <Button
                                        size="icon"
                                        variant="ghost"
                                        className="h-6 w-6 hover:bg-white/10"
                                        title={validateMission(mission) ?? "Sauvegarder"}
                                        onClick={() => {
                                            const err = validateMission(mission);
                                            if (err) {
                                                toast.error(err, { description: "Ouvrez le slot pour compléter les champs requis." });
                                                return;
                                            }
                                            handleSaveSingle(mission.slotIndex);
                                        }}
                                    >
                                        <Save className="w-3.5 h-3.5 text-indigo-400" />
                                    </Button>
                                    <Button size="icon" variant="ghost" className="h-6 w-6 hover:bg-white/10" onClick={() => handleResetSingle(mission.slotIndex)} title="Effacer">
                                        <Trash2 className="w-3.5 h-3.5 text-red-400" />
                                    </Button>
                                </div>
                            </CardHeader>

                            <CardContent className="p-4 pt-1 cursor-pointer flex-grow relative z-10" onClick={() => setEditingSlot(mission.slotIndex)}>
                                <div className="h-full flex flex-col">
                                    {isEmpty ? (
                                        <div className="flex flex-col items-center justify-center h-20 gap-2.5">
                                            <div className="w-10 h-10 rounded-xl bg-zinc-900/50 border border-zinc-800 flex items-center justify-center group-hover:scale-110 transition-transform duration-300 shadow-inner">
                                                <Edit2 className="w-4 h-4 text-zinc-500 group-hover:text-zinc-300 transition-colors" />
                                            </div>
                                            <span className="text-[10px] font-black uppercase tracking-widest text-zinc-500 group-hover:text-zinc-200 transition-colors">Configurer</span>
                                        </div>
                                    ) : (
                                        <>
                                            <h4 className="text-base font-bold text-white truncate leading-tight transition-all">
                                                {mission.title}
                                            </h4>
                                            <div className="flex items-center gap-2 text-xs text-zinc-400 mt-1 mb-2">
                                                <Badge variant="secondary" className="text-[10px] h-5 px-1.5 bg-zinc-800 hover:bg-zinc-700 text-zinc-300">
                                                    Rang {mission.rank}
                                                </Badge>
                                                <span className="w-0.5 h-3 bg-zinc-800" />
                                                <span className="text-indigo-400 font-bold">{mission.xpReward} XP</span>
                                            </div>

                                            {payloadPreview && (
                                                <div className="mt-auto flex items-center gap-1.5 text-[11px] px-2 py-1 bg-black/30 rounded border border-white/5 group-hover:border-white/10 transition-colors">
                                                    {payloadPreview}
                                                </div>
                                            )}
                                        </>
                                    )}
                                </div>
                            </CardContent>
                        </Card>
                    );
                })}
            </div>

            {/* Editing Dialog */}
            <Dialog open={editingSlot !== null} onOpenChange={(open) => !open && setEditingSlot(null)}>
                <DialogContent className="bg-zinc-900 border-zinc-800 text-white sm:max-w-lg shadow-2xl max-h-[90vh] flex flex-col">
                    <DialogHeader className="shrink-0">
                        <DialogTitle className="text-xl font-black flex items-center gap-2">
                            {editingSlot !== null && editingSlot >= 12
                                ? <><Sparkles className="w-4 h-4 text-yellow-400" /> Éditer Slot Spécial #{editingSlot - 11}</>
                                : <>Éditer Slot #{editingSlot !== null ? editingSlot + 1 : ''}</>}
                        </DialogTitle>
                    </DialogHeader>

                    {currentMission && (
                        <div className="overflow-y-auto pr-1 flex-1 py-2 space-y-4">
                            <div className="grid grid-cols-2 gap-3">
                                <div className="space-y-2">
                                    <label className="text-xs font-black uppercase tracking-widest text-zinc-500">Catégorie</label>
                                    {missionPool === 'SPECIALES' ? (
                                        // Special pool: locked to EVENT
                                        <div className="h-9 w-full rounded-md border border-yellow-500/30 bg-yellow-500/10 px-3 flex items-center gap-2 text-sm text-yellow-300 font-bold">
                                            <Sparkles className="w-3.5 h-3.5" /> Événement
                                        </div>
                                    ) : (
                                        // Classic pool: all categories except EVENT
                                        <select
                                            className="h-9 w-full rounded-md border border-zinc-800 bg-zinc-950 px-2 py-1 text-sm text-white outline-none focus:ring-2 focus:ring-indigo-500/50"
                                            value={currentMission.category}
                                            onChange={(e) => updateMission(currentMission.slotIndex, {
                                                category: e.target.value as MissionCategoryType,
                                                title: "",
                                                payload: {}
                                            })}
                                        >
                                            {MISSION_CATEGORIES.filter(c => c !== 'EVENT').map(c => (
                                                <option key={c} value={c}>{CATEGORY_CONFIG[c].label}</option>
                                            ))}
                                        </select>
                                    )}
                                </div>

                                <div className="space-y-2">
                                    <label className="text-xs font-black uppercase tracking-widest text-zinc-500">Rang (Difficulté)</label>
                                    <select
                                        className="h-9 w-full rounded-md border border-zinc-800 bg-zinc-950 px-2 py-1 text-sm text-white outline-none focus:ring-2 focus:ring-indigo-500/50"
                                        value={currentMission.rank}
                                        onChange={(e) => updateMission(currentMission.slotIndex, { rank: parseInt(e.target.value) })}
                                    >
                                        {[1, 2, 3, 4, 5].map(r => (
                                            <option key={r} value={r}>Rang {r}</option>
                                        ))}
                                    </select>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="text-xs font-black uppercase tracking-widest text-zinc-500">XP Guilde</label>
                                    <input
                                        type="number"
                                        className="h-9 w-full rounded-md border border-zinc-800 bg-zinc-950 px-3 py-1 text-sm text-white outline-none focus:ring-2 focus:ring-indigo-500/50"
                                        value={currentMission.xpReward}
                                        onChange={(e) => updateMission(currentMission.slotIndex, { xpReward: parseInt(e.target.value) || 0 })}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-xs font-black uppercase tracking-widest text-zinc-500">Guildatons</label>
                                    <input
                                        type="number"
                                        className="h-9 w-full rounded-md border border-zinc-800 bg-zinc-950 px-3 py-1 text-sm text-white outline-none focus:ring-2 focus:ring-indigo-500/50"
                                        value={currentMission.guildatonsReward}
                                        onChange={(e) => updateMission(currentMission.slotIndex, { guildatonsReward: parseInt(e.target.value) || 0 })}
                                    />
                                </div>
                            </div>

                            <div className="pt-3 border-t border-zinc-800">
                                {currentMission.category === 'DONJON' && (
                                    <DungeonForm
                                        payload={currentMission.payload}
                                        onPayloadChange={(payload) => updateMission(currentMission.slotIndex, { payload })}
                                        onTitleChange={(title) => updateMission(currentMission.slotIndex, { title })}
                                        onRankChange={(rank) => updateMission(currentMission.slotIndex, { rank })}
                                    />
                                )}
                                {currentMission.category === 'REGULATION' && (
                                    <RegulationForm
                                        payload={currentMission.payload}
                                        onPayloadChange={(payload) => updateMission(currentMission.slotIndex, { payload })}
                                        onTitleChange={(title) => updateMission(currentMission.slotIndex, { title })}
                                        onRankChange={(rank) => updateMission(currentMission.slotIndex, { rank })}
                                    />
                                )}
                                {currentMission.category === 'ANOMALIE' && (
                                    <AnomalieForm
                                        payload={currentMission.payload}
                                        onPayloadChange={(payload) => updateMission(currentMission.slotIndex, { payload })}
                                        onTitleChange={(title) => updateMission(currentMission.slotIndex, { title })}
                                        onRankChange={(rank) => updateMission(currentMission.slotIndex, { rank })}
                                    />
                                )}
                                {currentMission.category === 'SONGES' && (
                                    <>
                                        <div className="flex items-center gap-2 mb-4 bg-zinc-800/30 rounded-xl p-1">
                                            <button
                                                type="button"
                                                onClick={() => updateMission(currentMission.slotIndex, { 
                                                    payload: { difficulty: 'Paradoxe', level: 'I', tier: 2 },
                                                    title: ''
                                                })}
                                                className={cn(
                                                    "flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all",
                                                    !currentMission.payload?.epreuve
                                                        ? "bg-cyan-500/20 text-cyan-300 border border-cyan-500/30"
                                                        : "text-zinc-500 hover:text-zinc-300"
                                                )}
                                            >
                                                Songes Classiques
                                            </button>
                                            <button
                                                type="button"
                                                onClick={() => updateMission(currentMission.slotIndex, { 
                                                    payload: { epreuve: 'Fonsocac' },
                                                    title: ''
                                                })}
                                                className={cn(
                                                    "flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all",
                                                    currentMission.payload?.epreuve
                                                        ? "bg-cyan-500/20 text-cyan-300 border border-cyan-500/30"
                                                        : "text-zinc-500 hover:text-zinc-300"
                                                )}
                                            >
                                                Épreuve Songe
                                            </button>
                                        </div>
                                        {currentMission.payload?.epreuve ? (
                                            <SongesEpreuveForm
                                                payload={currentMission.payload}
                                                onPayloadChange={(payload) => updateMission(currentMission.slotIndex, { payload })}
                                                onTitleChange={(title) => updateMission(currentMission.slotIndex, { title })}
                                            />
                                        ) : (
                                            <SongesForm
                                                payload={currentMission.payload}
                                                onPayloadChange={(payload) => updateMission(currentMission.slotIndex, { payload })}
                                                onTitleChange={(title) => updateMission(currentMission.slotIndex, { title })}
                                                onRankChange={(rank) => updateMission(currentMission.slotIndex, { rank })}
                                            />
                                        )}
                                    </>
                                )}
                                {currentMission.category === 'EXPEDITION' && (
                                    <ExpeditionForm
                                        payload={currentMission.payload}
                                        onPayloadChange={(payload) => updateMission(currentMission.slotIndex, { payload })}
                                        onTitleChange={(title) => updateMission(currentMission.slotIndex, { title })}
                                        onRankChange={(rank) => updateMission(currentMission.slotIndex, { rank })}
                                    />
                                )}
                                {currentMission.category === 'EVENT' && (
                                    <EventForm
                                        payload={currentMission.payload}
                                        onPayloadChange={(payload) => updateMission(currentMission.slotIndex, { payload })}
                                        onTitleChange={(title) => updateMission(currentMission.slotIndex, { title })}
                                    />
                                )}
                            </div>
                        </div>
                    )}
                    <DialogFooter className="shrink-0 gap-2 flex-col sm:flex-row items-center pt-3 border-t border-zinc-800">
                        {currentMission && (() => {
                            const err = validateMission(currentMission);
                            return err ? (
                                <p className="flex-1 text-xs text-rose-400 font-medium flex items-center gap-1.5 mr-auto">
                                    <span className="inline-block w-1.5 h-1.5 rounded-full bg-rose-500 shrink-0" />
                                    {err}
                                </p>
                            ) : null;
                        })()}
                        <Button variant="ghost" onClick={() => setEditingSlot(null)} className="text-zinc-400 hover:text-white">Annuler</Button>
                        <Button
                            onClick={() => currentMission && handleSaveFromDialog(currentMission.slotIndex)}
                            disabled={!!currentMission && !!validateMission(currentMission)}
                            variant="sigil"
                            className="h-10 px-8"
                        >
                            Enregistrer
                        </Button>
                    </DialogFooter>

                </DialogContent>
            </Dialog>

            <MissionPublishFlowDialog
                isOpen={confirmPublishOpen}
                onOpenChange={setConfirmPublishOpen}
                guildId={guildId}
                missionPool={missionPool}
                missionsCount={poolMissions.filter(m => m.title).length}
                onConfirm={handleGlobalPublish}
                isDiscordConfigured={isDiscordConfigured}
            />
        </div >
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
    DialogFooter
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { 
    Loader2, 
    Send, 
    Share2, 
    BellOff, 
    AtSign, 
    Check, 
    AlertTriangle, 
    ChevronRight, 
    ChevronLeft,
    Rocket,
    Save
} from "lucide-react";
import { getDiscordRolesAction } from "@/server/actions/user-actions";
import { publishMissionsToDiscord } from "@/server/actions/mission-actions";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

interface MissionPublishFlowDialogProps {
    isOpen: boolean;
    onOpenChange: (open: boolean) => void;
    guildId: string;
    missionPool: 'CLASSIQUES' | 'SPECIALES';
    missionsCount: number;
    onConfirm: () => Promise<{ success: boolean; error?: string }>;
    isDiscordConfigured?: boolean;
}

type Step = "CONFIRM" | "DISCORD_PING";
type PingType = "EVERYONE" | "ROLE" | "NONE";

export function MissionPublishFlowDialog({
    isOpen,
    onOpenChange,
    guildId,
    missionPool,
    missionsCount,
    onConfirm,
    isDiscordConfigured = true
}: MissionPublishFlowDialogProps) {
    const [step, setStep] = useState<Step>("CONFIRM");
    const [pingType, setPingType] = useState<PingType>("NONE");
    const [selectedRoleId, setSelectedRoleId] = useState<string | null>(null);
    const [roles, setRoles] = useState<{ id: string; name: string; color: number }[]>([]);
    const [isLoadingRoles, setIsLoadingRoles] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [isPublishingDiscord, setIsPublishingDiscord] = useState(false);

    useEffect(() => {
        if (isOpen) {
            setStep("CONFIRM");
            setIsLoadingRoles(true);
            getDiscordRolesAction(guildId, { ignoreWhitelist: true }).then(res => {
                if (res.success && res.roles) setRoles(res.roles);
                setIsLoadingRoles(false);
            });
        }
    }, [isOpen, guildId]);

    const isPoolComplete = missionPool === 'CLASSIQUES' ? missionsCount === 12 : missionsCount >= 1;

    const handleSaveAndNext = async () => {
        if (!isPoolComplete) return;
        setIsSaving(true);
        const res = await onConfirm();
        setIsSaving(false);
        
        if (res.success) {
            if (!isDiscordConfigured) {
                toast.success("Publication terminée !");
                onOpenChange(false);
            } else {
                setStep("DISCORD_PING");
            }
        }
    };

    const handleFinalize = async (skipDiscord = false) => {
        if (skipDiscord) {
            toast.success("Publication terminée !");
            onOpenChange(false);
            return;
        }

        setIsPublishingDiscord(true);
        const res = await publishMissionsToDiscord(guildId, pingType, selectedRoleId);
        setIsPublishingDiscord(false);
        
        if (res.success) {
            toast.success("Publication terminée et annonce Discord envoyée !");
            onOpenChange(false);
        } else {
            toast.error(res.error || "Missions sauvegardées mais erreur d'annonce Discord.");
        }
    };

    return (
        <Dialog open={isOpen} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-md bg-zinc-950 border-white/10 shadow-2xl rounded-3xl p-0 overflow-hidden outline-none">
                
                {/* STEP INDICATOR */}
                <div className="flex h-1 bg-white/5">
                    <div className={cn("h-full bg-indigo-500 transition-all duration-500", step === "CONFIRM" ? "w-1/2" : "w-full")} />
                </div>

                {/* CONTENT AREA */}
                <div className="p-6">
                    {step === "CONFIRM" ? (
                        <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
                            <DialogHeader>
                                <DialogTitle className="text-xl font-black text-white flex items-center gap-3">
                                    <div className="p-2 bg-amber-500/20 rounded-xl text-amber-500">
                                        <Save className="w-5 h-5" />
                                    </div>
                                    Publication Dashboard
                                </DialogTitle>
                                <DialogDescription className="text-zinc-500 text-sm mt-2">
                                    Vous allez mettre à jour les missions {missionPool === 'CLASSIQUES' ? 'Classiques' : 'Spéciales'} sur le site.
                                </DialogDescription>
                            </DialogHeader>

                            <div className="bg-zinc-900/50 border border-white/5 rounded-2xl p-4 space-y-3">
                                <div className="flex items-center justify-between text-xs">
                                    <span className="text-zinc-400 font-bold">Pool de missions</span>
                                    <span className={cn(
                                        "font-black uppercase tracking-widest px-2 py-1 rounded text-[10px]",
                                        missionPool === 'CLASSIQUES' ? "bg-indigo-500/20 text-indigo-400" : "bg-yellow-500/20 text-yellow-500"
                                    )}>
                                        {missionPool}
                                    </span>
                                </div>
                                <div className="flex items-center justify-between text-xs border-t border-white/5 pt-3">
                                    <span className="text-zinc-400 font-bold">État de configuration</span>
                                    <div className="flex items-center gap-2">
                                        <span className={cn(
                                            "font-mono font-black text-sm",
                                            isPoolComplete ? "text-emerald-400" : "text-rose-500"
                                        )}>
                                            {missionsCount} / {missionPool === 'CLASSIQUES' ? 12 : 6}
                                        </span>
                                        {isPoolComplete ? <Check className="w-4 h-4 text-emerald-500" /> : <AlertTriangle className="w-4 h-4 text-rose-500" />}
                                    </div>
                                </div>
                                
                                {!isPoolComplete && (
                                    <div className="bg-rose-500/10 border border-rose-500/20 rounded-xl p-3 flex items-start gap-2 text-[10px] text-rose-400 font-bold leading-tight">
                                        <AlertTriangle className="w-3.5 h-3.5 shrink-0" />
                                        {missionPool === 'CLASSIQUES' 
                                            ? "ERREUR : Les 12 missions classiques doivent être configurées pour permettre la publication hebdomadaire." 
                                            : "ERREUR : Configurez au moins une mission spéciale avant de publier."}
                                    </div>
                                )}
                            </div>

                            <div className="flex flex-col gap-2">
                                <Button 
                                    onClick={handleSaveAndNext} 
                                    disabled={isSaving || !isPoolComplete}
                                    className={cn(
                                        "h-12 font-black rounded-2xl shadow-xl transition-all",
                                        isPoolComplete 
                                            ? "bg-white text-black hover:bg-zinc-200 shadow-white/5" 
                                            : "bg-zinc-900 text-zinc-700 cursor-not-allowed grayscale"
                                    )}
                                >
                                    {isSaving ? <Loader2 className="w-5 h-5 animate-spin" /> : "PUBLIER & CONTINUER"}
                                    {!isSaving && <ChevronRight className="w-5 h-5 ml-2" />}
                                </Button>
                                <Button variant="ghost" onClick={() => onOpenChange(false)} className="text-zinc-500 hover:text-white h-10 font-bold">
                                    Annuler
                                </Button>
                            </div>
                        </div>
                    ) : (
                        <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
                            <DialogHeader>
                                <DialogTitle className="text-xl font-black text-white flex items-center gap-3">
                                    <div className="p-2 bg-indigo-500/20 rounded-xl text-indigo-400">
                                        <Send className="w-5 h-5" />
                                    </div>
                                    Annonce Discord
                                </DialogTitle>
                                <DialogDescription className="text-zinc-500 text-sm mt-2">
                                    Missions sauvegardées avec succès ! Souhaitez-vous notifier la guilde ?
                                </DialogDescription>
                            </DialogHeader>

                            <div className="grid grid-cols-2 gap-3">
                                <button
                                    onClick={() => { setPingType("NONE"); setSelectedRoleId(null); }}
                                    className={cn(
                                        "flex flex-col items-center gap-2 p-4 rounded-2xl border transition-all text-center group",
                                        pingType === "NONE"
                                            ? "bg-indigo-500/10 border-indigo-500/40 text-indigo-300"
                                            : "bg-zinc-900 border-white/5 text-zinc-500 hover:border-white/10"
                                    )}
                                >
                                    <BellOff className={cn("w-5 h-5", pingType === "NONE" ? "text-indigo-400" : "text-zinc-600 group-hover:text-zinc-400")} />
                                    <span className="text-xs font-black uppercase tracking-widest">Sans Ping</span>
                                </button>
                                <button
                                    onClick={() => { setPingType("EVERYONE"); setSelectedRoleId(null); }}
                                    className={cn(
                                        "flex flex-col items-center gap-2 p-4 rounded-2xl border transition-all text-center group",
                                        pingType === "EVERYONE"
                                            ? "bg-rose-500/10 border-rose-500/40 text-rose-300"
                                            : "bg-zinc-900 border-white/5 text-zinc-500 hover:border-white/10"
                                    )}
                                >
                                    <AtSign className={cn("w-5 h-5", pingType === "EVERYONE" ? "text-rose-400" : "text-zinc-600 group-hover:text-zinc-400")} />
                                    <span className="text-xs font-black uppercase tracking-widest">@everyone</span>
                                </button>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500 ml-1">Ping un rôle spécifique</label>
                                <div className="bg-zinc-900 border border-white/5 rounded-2xl overflow-hidden max-h-40 overflow-y-auto custom-scrollbar shadow-inner">
                                    {isLoadingRoles ? (
                                        <div className="flex items-center justify-center py-8 gap-2 text-zinc-600">
                                            <Loader2 className="w-4 h-4 animate-spin" />
                                        </div>
                                    ) : roles.length === 0 ? (
                                        <div className="py-8 text-center text-xs text-zinc-600 italic">Aucun rôle trouvé</div>
                                    ) : (
                                        <div className="p-2 space-y-1">
                                            {roles.map(role => {
                                                const isSelected = selectedRoleId === role.id;
                                                const hex = role.color ? `#${role.color.toString(16).padStart(6, "0")}` : "#71717a";
                                                return (
                                                    <button
                                                        key={role.id}
                                                        onClick={() => { setPingType("ROLE"); setSelectedRoleId(role.id); }}
                                                        className={cn(
                                                            "w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-left transition-all",
                                                            isSelected ? "bg-indigo-500 text-white shadow-lg shadow-indigo-500/20" : "text-zinc-400 hover:bg-white/5"
                                                        )}
                                                    >
                                                        <div className="w-2.5 h-2.5 rounded-full shadow-sm" style={{ backgroundColor: hex }} />
                                                        <span className="text-sm font-bold flex-1 truncate">@{role.name}</span>
                                                        {isSelected && <Check className="w-4 h-4" />}
                                                    </button>
                                                );
                                            })}
                                        </div>
                                    )}
                                </div>
                            </div>

                            <div className="flex flex-col gap-2 pt-2">
                                <Button 
                                    onClick={() => handleFinalize(false)} 
                                    disabled={isPublishingDiscord}
                                    className="bg-indigo-600 hover:bg-indigo-500 text-white h-12 font-black rounded-2xl shadow-xl shadow-indigo-500/20"
                                >
                                    {isPublishingDiscord ? <Loader2 className="w-5 h-5 animate-spin mr-2" /> : <Rocket className="w-5 h-5 mr-2" />}
                                    FINALISER & ENVOYER
                                </Button>
                                <button 
                                    onClick={() => handleFinalize(true)}
                                    className="h-10 text-xs font-bold text-zinc-600 hover:text-rose-400 transition-colors uppercase tracking-wider"
                                >
                                    Ignorer l'annonce Discord
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useEffect, useState } from "react";
import { Coins, Info, HelpCircle, TrendingUp } from "lucide-react";
import { GUILDATONS_MAX_PER_WEEK } from "@/lib/kama-constants";
import { cn } from "@/lib/utils";
import { 
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from "@/components/ui/tooltip";

interface PersonalGuildatonWidgetProps {
    guildatons: number; // Current weekly total
}

export function PersonalGuildatonWidget({ guildatons }: PersonalGuildatonWidgetProps) {
    const [progress, setProgress] = useState(0);
    const max = GUILDATONS_MAX_PER_WEEK;
    const percentage = Math.min(100, (guildatons / max) * 100);

    useEffect(() => {
        const timer = setTimeout(() => setProgress(percentage), 500);
        return () => clearTimeout(timer);
    }, [percentage]);

    const isMaxed = guildatons >= max;

    return (
        <div className="relative group overflow-hidden rounded-2xl bg-zinc-950/40 border border-white/5 p-5 transition-all duration-300 hover:border-amber-500/20">
            {/* Background Glow */}
            <div className={cn(
                "absolute -right-4 -top-4 w-24 h-24 rounded-full blur-3xl transition-opacity duration-500 pointer-events-none opacity-20",
                isMaxed ? "bg-emerald-500" : "bg-amber-500"
            )} />

            <div className="relative z-10 flex flex-col gap-4">
                {/* Header */}
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className={cn(
                            "p-2 rounded-xl border flex items-center justify-center transition-transform group-hover:scale-110",
                            isMaxed 
                                ? "bg-emerald-500/10 border-emerald-500/20 text-emerald-400" 
                                : "bg-amber-500/10 border-amber-500/20 text-amber-400"
                        )}>
                            <Coins className="w-5 h-5" />
                        </div>
                        <div>
                            <p className="text-[10px] font-black text-muted-foreground uppercase tracking-[0.2em] italic">Mes Guildatons</p>
                            <h4 className="text-sm font-black text-foreground uppercase tracking-tight">Objectif Hebdo</h4>
                        </div>
                    </div>

                    <TooltipProvider>
                        <Tooltip>
                            <TooltipTrigger asChild>
                                <button className="text-muted-foreground hover:text-foreground transition-colors">
                                    <HelpCircle className="w-4 h-4" />
                                </button>
                            </TooltipTrigger>
                            <TooltipContent className="glass-premium border-white/10 text-[10px] font-bold max-w-[200px]">
                                Gagnez des Guildatons en validant des missions ou en donnant des kamas. Limite de {max} par semaine.
                            </TooltipContent>
                        </Tooltip>
                    </TooltipProvider>
                </div>

                {/* Progress Stats */}
                <div className="flex items-end justify-between">
                    <div className="flex items-baseline gap-1.5">
                        <span className={cn(
                            "text-3xl font-black tracking-tighter tabular-nums",
                            isMaxed ? "text-emerald-400" : "text-amber-400"
                        )}>
                            {guildatons}
                        </span>
                        <span className="text-sm font-black text-muted-foreground italic">/ {max}</span>
                    </div>
                    
                    {isMaxed ? (
                        <div className="flex items-center gap-1.5 px-2 py-1 rounded-full bg-emerald-500/10 border border-emerald-500/20">
                            <TrendingUp className="w-3 h-3 text-emerald-400" />
                            <span className="text-[9px] font-black text-emerald-400 uppercase tracking-widest">Maximum Atteint</span>
                        </div>
                    ) : (
                        <span className="text-[10px] font-black text-muted-foreground uppercase tracking-widest italic">
                            {max - guildatons} restants
                        </span>
                    )}
                </div>

                {/* Progress Bar */}
                <div className="space-y-1.5">
                    <div className="h-2 w-full bg-white/5 rounded-full overflow-hidden border border-white/5">
                        <div 
                            className={cn(
                                "h-full transition-all duration-1000 ease-out relative",
                                isMaxed 
                                    ? "bg-gradient-to-r from-emerald-600 to-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.4)]" 
                                    : "bg-gradient-to-r from-amber-600 to-amber-400 shadow-[0_0_15px_rgba(245,158,11,0.4)]"
                            )}
                            style={{ width: `${progress}%` }}
                        >
                            <div className="absolute inset-0 bg-white/20 animate-pulse" />
                        </div>
                    </div>
                    <div className="flex justify-between items-center text-[9px] font-black uppercase tracking-widest text-muted-foreground/60 italic">
                        <span>Début</span>
                        <span>{percentage.toFixed(0)}%</span>
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client'

import { useState, useRef, useTransition, useEffect } from "react";

import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
    DialogFooter
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
    Upload,
    X,
    CheckCircle2,
    Loader2,
    ImageIcon,
    Sparkles,
    AlertTriangle,
    XCircle,
    Check,
    Eye,
    Clock,
    Users
} from "lucide-react";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { submitMissionProof, cancelMissionSubmission } from "@/server/actions/mission-actions";
import { reportSecurityIncident } from "@/server/actions/audit-actions";
import { useRouter } from "next/navigation";
import Image from "next/image";
import { Progress } from "@/components/ui/progress";
import { type MissionCategory, type MissionPayload } from "@/types/missions";



import { analyzeImageSafety } from "@/lib/safety-client";
import { MemberSelector } from "./member-selector"; // Import MemberSelector
import { Honeypot } from "@/components/shared/honeypot";

interface ProofUploadDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    missionId: string;
    missionTitle: string;
    guildId: string;
    category: MissionCategory;
    payload: MissionPayload;
}

type UploadState = "idle" | "analyzing" | "uploading" | "success" | "error";

export function ProofUploadDialog({
    open,
    onOpenChange,
    missionId,
    missionTitle,
    guildId,
    category,
    payload
}: ProofUploadDialogProps) {
    const [file, setFile] = useState<File | null>(null);
    const [preview, setPreview] = useState<string | null>(null);
    const [state, setState] = useState<UploadState>("idle");
    const [ocrResult, setOcrResult] = useState<any | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [isCheckingSafety, setIsCheckingSafety] = useState(false);
    const [helperIds, setHelperIds] = useState<string[]>([]); // State for helpers

    const fileInputRef = useRef<HTMLInputElement>(null);
    const router = useRouter();
    const [isPending, startTransition] = useTransition();



    const resetState = () => {
        if (preview) URL.revokeObjectURL(preview);
        setFile(null);
        setPreview(null);
        setState("idle");
        setError(null);
        setHelperIds([]); // Reset helpers
    };


    const handleClose = () => {
        resetState();
        onOpenChange(false);
    };

    // --- Refactored File Handler (Shared between Input, Drop, and Paste) ---
    const validateAndSetFile = async (selectedFile: File) => {
        // Client-side validation
        const validTypes = ["image/png", "image/jpeg", "image/webp", "image/gif"];
        if (!validTypes.includes(selectedFile.type)) {
            toast.error("Format non supporté. Utilisez PNG, JPEG, WebP ou GIF.");
            return;
        }

        const maxSize = 10 * 1024 * 1024; // 10MB
        if (selectedFile.size > maxSize) {
            toast.error("Fichier trop volumineux (max 10MB)");
            return;
        }

        if (preview) URL.revokeObjectURL(preview);

        // --- Added: NSFW/Safety Check ---
        setIsCheckingSafety(true);
        try {
            const safety = await analyzeImageSafety(selectedFile);
            if (!safety.isSafe) {
                toast.error("INFRACTION DÉTECTÉE : Contenu inapproprié.", {
                    description: "Ce type de contenu est strictement interdit sur la plateforme. L'incident a été enregistré.",
                    duration: 8000,
                    style: {
                        borderColor: '#ef4444',
                        backgroundColor: '#450a0a',
                        color: '#fca5a5'
                    }
                });

                // Logging the incident
                reportSecurityIncident(
                    guildId,
                    "NSFW_ATTEMPT",
                    `Tentative d'upload NSFW par l'utilisateur (Fichier: ${selectedFile.name})`,
                    {
                        category: category || "Unknown",
                        reason: safety.reason,
                        fileName: selectedFile.name,
                        fileSize: selectedFile.size,
                        missionTitle: missionTitle,
                        scores: safety.predictions
                    }
                ).catch((err: Error) => console.error("Failed to log incident", err));

                resetState();
                onOpenChange(false);
                return;
            }
        } finally {
            setIsCheckingSafety(false);
        }

        setFile(selectedFile);
        setPreview(URL.createObjectURL(selectedFile));
        setError(null);
        setOcrResult(null);
    };

    const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = e.target.files?.[0];
        if (selectedFile) {
            validateAndSetFile(selectedFile);
        }
    };

    // --- Clipboard Paste Support ---
    // eslint-disable-next-line react-hooks/rules-of-hooks

    // eslint-disable-next-line react-hooks/rules-of-hooks
    useEffect(() => {
        if (!open) return;

        const handlePaste = (e: ClipboardEvent) => {
            if (e.clipboardData && e.clipboardData.files.length > 0) {
                const file = e.clipboardData.files[0];
                if (file.type.startsWith("image/")) {
                    e.preventDefault();
                    validateAndSetFile(file);
                    toast.info("Image collée depuis le presse-papier ! 📋");
                }
            }
        };

        window.addEventListener("paste", handlePaste);
        return () => window.removeEventListener("paste", handlePaste);
    }, [open]);


    const handleUpload = async () => {
        if (!file) return;

        setState("analyzing");
        setError(null);

        try {
            // Convert to Base64 AND Compress
            setState("analyzing"); // Re-using analyzing state for compression

            // Dynamic import to avoid SSR issues if any
            const { compressImage } = await import("@/lib/image-compression");

            // Compress: Max 1920x1080, 80% quality
            const compressedDataUrl = await compressImage(file, {
                maxWidth: 1920,
                maxHeight: 1080,
                quality: 0.8
            });

            // 1. Submit to server action (which handles OCR + Storage)
            setState("uploading");
            
            // 🍯 Honeypot check
            const hpValue = (document.getElementById("hp_ignore_field") as HTMLInputElement)?.value;
            
            const result = await submitMissionProof(missionId, compressedDataUrl, helperIds, hpValue); // Pass helperIds + Honeypot

            if (!result.success) {
                throw new Error(result.error || "Échec de la soumission");
            }

            toast.success("Preuve soumise ! En attente de validation par un modérateur.");

            startTransition(() => {
                router.refresh();
            });

            setState("success");


        } catch (err) {
            setState("error");
            const message = err instanceof Error ? err.message : "Erreur inattendue";
            setError(message);
            toast.error(message);
        }
    };


    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        const droppedFile = e.dataTransfer.files[0];
        if (droppedFile) {
            const dataTransfer = new DataTransfer();
            dataTransfer.items.add(droppedFile);

            if (fileInputRef.current) {
                fileInputRef.current.files = dataTransfer.files;
                validateAndSetFile(droppedFile); // Use the new function
            }
        }
    };

    const isProcessing = state === "analyzing" || state === "uploading";


    return (
        <Dialog open={open} onOpenChange={handleClose}>
            <DialogContent className="sm:max-w-lg bg-slate-950 border-slate-800">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2">
                        <Upload className="w-5 h-5 text-indigo-400" />
                        Soumettre une preuve
                    </DialogTitle>
                    <DialogDescription className="text-slate-400">
                        {missionTitle}
                    </DialogDescription>
                </DialogHeader>

                <div className="space-y-4">
                    <Honeypot />
                    {/* ═══════════════════════════════════════ */}
                    {/* CONTRIBUTOR SECTION — Always visible in idle/preview */}
                    {/* ═══════════════════════════════════════ */}
                    {(state === "idle") && (
                        <div className="relative rounded-xl border border-amber-500/40 bg-gradient-to-br from-amber-950/40 via-amber-900/20 to-zinc-900/60 p-4 space-y-3 shadow-[0_0_20px_-5px_rgba(245,158,11,0.3)]">
                            {/* Glow accent */}
                            <div className="absolute -top-px left-6 right-6 h-px bg-gradient-to-r from-transparent via-amber-400/60 to-transparent" />

                            <div className="flex items-start gap-3">
                                <div className="mt-0.5 p-2 rounded-lg bg-amber-500/20 border border-amber-500/30 shrink-0">
                                    <Users className="w-5 h-5 text-amber-400" />
                                </div>
                                <div className="flex-1 min-w-0 space-y-1">
                                    <div className="flex items-center gap-2">
                                        <h3 className="text-sm font-black text-amber-300 uppercase tracking-wider">Contributeurs</h3>
                                        <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-500/20 text-amber-400 border border-amber-500/30">OPTIONNEL</span>
                                    </div>
                                    <p className="text-xs text-amber-200/80 leading-relaxed">
                                        Ils vous ont aidé ? Sélectionnez-les — ils recevront{" "}
                                        <span className="font-black text-amber-300">des points de contribution</span>{" "}
                                        dès validation de votre preuve !
                                    </p>
                                </div>
                            </div>

                            <MemberSelector
                                guildId={guildId}
                                selectedIds={helperIds}
                                onSelect={setHelperIds}
                                maxSelection={7}
                            />
                        </div>
                    )}

                    {/* Drop Zone */}
                    {!preview && state === "idle" && (
                        <div
                            className={cn(
                                "relative border-2 border-dashed border-slate-700 rounded-lg p-8 text-center transition-colors",
                                isCheckingSafety ? "opacity-50 cursor-wait" : "hover:border-indigo-500/50 hover:bg-indigo-500/5"
                            )}
                            onDrop={handleDrop}
                            onDragOver={(e) => e.preventDefault()}
                        >
                            <ImageIcon className="w-12 h-12 mx-auto text-slate-600 mb-4" />
                            <p className="text-sm text-slate-400 mb-2">
                                Glissez votre screenshot ici, coller (CTRL+V) ou{" "}
                                <button
                                    type="button"
                                    onClick={() => !isCheckingSafety && fileInputRef.current?.click()}
                                    className="text-indigo-400 hover:text-indigo-300 font-medium hover:underline focus:outline-none"
                                >
                                    cliquez pour sélectionner
                                </button>
                            </p>
                            <p className="text-xs text-slate-500">
                                PNG, JPEG, WebP ou GIF • Max 10MB
                            </p>
                            <input
                                ref={fileInputRef}
                                type="file"
                                accept="image/png,image/jpeg,image/webp,image/gif"
                                className="hidden"
                                onChange={handleFileSelect}
                                disabled={isCheckingSafety}
                            />
                            {isCheckingSafety && (
                                <div className="absolute inset-0 bg-slate-950/80 flex flex-col items-center justify-center gap-3 z-10 rounded-lg">
                                    <Loader2 className="w-8 h-8 animate-spin text-indigo-400" />
                                    <p className="text-sm text-slate-300">Vérification de sécurité...</p>
                                </div>
                            )}
                        </div>
                    )}

                    {/* Preview */}
                    {preview && (
                        <div className="relative rounded-lg overflow-hidden border border-slate-800 bg-black">
                            <Image
                                src={preview}
                                alt="Preview"
                                width={500}
                                height={300}
                                className="w-full h-auto max-h-64 object-contain"
                                unoptimized
                            />
                            {state === "idle" && (
                                <button
                                    onClick={resetState}
                                    className="absolute top-2 right-2 p-1.5 bg-red-500/80 rounded-full hover:bg-red-500 transition-colors"
                                >
                                    <X className="w-4 h-4 text-white" />
                                </button>
                            )}

                            {/* Analyzing overlay with progress */}
                            {state === "analyzing" && (
                                <div className="absolute inset-0 bg-black/80 flex flex-col items-center justify-center gap-3">
                                    <Eye className="w-8 h-8 text-indigo-400 animate-pulse" />
                                    <p className="text-xs text-slate-500">Processing...</p>

                                </div>
                            )}

                            {/* Uploading overlay */}
                            {state === "uploading" && (
                                <div className="absolute inset-0 bg-black/70 flex items-center justify-center">
                                    <div className="text-center">
                                        <Loader2 className="w-8 h-8 animate-spin text-indigo-400 mx-auto mb-2" />
                                        <p className="text-sm text-slate-300">Upload en cours...</p>
                                    </div>
                                </div>
                            )}

                            {/* Success overlay */}
                            {state === "success" && (
                                <div className="absolute inset-0 bg-black/70 flex items-center justify-center">
                                    <div className="text-center">
                                        <Clock className="w-12 h-12 text-amber-400 mx-auto mb-2" />
                                        <p className="text-sm text-amber-300 font-medium">Envoyée à la modération</p>
                                    </div>
                                </div>
                            )}
                        </div>
                    )}


                    {/* Error State */}
                    {error && (
                        <div className="bg-red-500/10 text-red-400 text-sm p-3 rounded-lg border border-red-500/20 flex items-center gap-2">
                            <XCircle className="w-4 h-4 shrink-0" />
                            {error}
                        </div>
                    )}
                </div>

                <DialogFooter className="gap-2">
                    {state === "success" ? (
                        <>
                            <Button variant="ghost" onClick={handleClose}>
                                Fermer
                            </Button>
                            {/* Allow cancelling for simple UX even if validated - user might have made mistake */}
                            <Button
                                variant="sigil-destructive"
                                disabled={isPending}
                                onClick={() => {
                                    startTransition(async () => {
                                        try {
                                            const result = await cancelMissionSubmission(missionId);
                                            if (result.success) {
                                                toast.success("Soumission annulée.");
                                                handleClose();
                                                router.refresh();
                                            } else {
                                                toast.error(result.error || "Erreur lors de l'annulation");
                                            }
                                        } catch (e) {
                                            toast.error("Erreur inattendue");
                                        }
                                    });
                                }}
                            >
                                {isPending ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <XCircle className="w-4 h-4 mr-2" />}
                                Annuler la soumission
                            </Button>
                        </>
                    ) : (
                        <>
                            <Button variant="ghost" onClick={handleClose} disabled={isProcessing}>
                                Annuler
                            </Button>
                            <Button
                                onClick={handleUpload}
                                disabled={!file || isProcessing}
                                variant="sigil-emerald"
                                className="h-10 px-6"
                            >
                                {state === "analyzing" ? (
                                    <>
                                        <Eye className="w-4 h-4 mr-2 animate-pulse" />
                                        Analyse...
                                    </>

                                ) : state === "uploading" ? (
                                    <>
                                        <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                        Upload...
                                    </>
                                ) : (
                                    <>
                                        <Upload className="w-4 h-4 mr-2" />
                                        Soumettre
                                    </>
                                )}
                            </Button>
                        </>
                    )}
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useEffect, useState } from "react";
import { Timer, Clock } from "lucide-react";
import { cn } from "@/lib/utils";

function getTimeUntilReset() {
    const now = new Date();

    // Create date for the next reset (Tuesday 07:00)
    const reset = new Date(now);

    const day = now.getDay(); // 0 is Sunday, 1 is Monday, 2 is Tuesday
    // (targetDay + 7 - currentDay) % 7. Tuesday is 2.
    let daysUntilTuesday = (2 + 7 - day) % 7;

    // If today is Tuesday and it's already past 7am, next reset is next week
    if (day === 2 && now.getHours() >= 7) {
        daysUntilTuesday = 7;
    }

    reset.setDate(now.getDate() + daysUntilTuesday);
    reset.setHours(7, 0, 0, 0);

    const diff = reset.getTime() - now.getTime();

    // Convert to days, hours, minutes, seconds
    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((diff % (1000 * 60)) / 1000);

    return { days, hours, minutes, seconds };
}

export function ResetCountdown() {
    const [timeLeft, setTimeLeft] = useState(getTimeUntilReset());
    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setMounted(true);
        const timer = setInterval(() => {
            setTimeLeft(getTimeUntilReset());
        }, 1000);

        return () => clearInterval(timer);
    }, []);

    // Prevent hydration mismatch
    if (!mounted) return null;

    return (
        <div className="flex items-center gap-4 bg-indigo-950/20 px-3 py-1.5 rounded-full border border-indigo-500/10 group hover:bg-indigo-950/40 transition-colors">
            <div className="flex items-center gap-2 text-[10px] font-semibold text-indigo-300 uppercase tracking-widest">
                <Timer className="w-3.5 h-3.5" />
                <span className="hidden sm:inline">Prochain Reset</span>
            </div>

            <div className="flex items-baseline gap-1.5 font-mono text-slate-200 text-xs">
                <span className="font-bold">{timeLeft.days}j</span>
                <span className="opacity-60">{timeLeft.hours.toString().padStart(2, '0')}h</span>
                <span className="opacity-60">{timeLeft.minutes.toString().padStart(2, '0')}m</span>
                <span className="text-indigo-400 font-bold w-[18px] text-center animate-pulse">
                    {timeLeft.seconds.toString().padStart(2, '0')}s
                </span>
            </div>
        </div>
    );
}

