export function FeedBell({ guildId, className }: { guildId: string, className?: string }) {
    const [feed, setFeed] = useState<ExtractedContent[]>([]);
    const [unreadCount, setUnreadCount] = useState(0);
    const [isOpen, setIsOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);

    const fetchFeed = async (force = false) => {
        setIsLoading(true);
        const res = await getAggregatedFeed(guildId, force);
        if (res.success && res.data) {
            setFeed(res.data as any);
            // If the popover is currently open, we consider everything seen
            if (!isOpen) {
                setUnreadCount(res.unreadCount || 0);
            } else {
                setUnreadCount(0);
            }
        }
        setIsLoading(false);
    };

    useEffect(() => {
        fetchFeed();
        // Since it's a "Lazy Pull" system, polling too often is fine, 
        // the server won't hammer external APIs unless cache expires.
        const interval = setInterval(fetchFeed, 60000 * 5); // check every 5 mins
        return () => clearInterval(interval);
    }, [guildId]);

    const handleOpenChange = async (open: boolean) => {
        setIsOpen(open);
        if (open && unreadCount > 0) {
            // Mark as read when opening the popover
            await markFeedAsRead(guildId);
            setUnreadCount(0);
        }
    };

    const getIcon = (type: string) => {
        switch (type) {
            case "YOUTUBE": return <CirclePlay className="w-4 h-4 text-red-500" />;
            case "TWITCH": return <Tv className="w-4 h-4 text-purple-500" />;
            case "NEWS": return <Rss className="w-4 h-4 text-emerald-500" />;
            default: return <Rss className="w-4 h-4 text-zinc-500" />;
        }
    };

    return (
        <Popover open={isOpen} onOpenChange={handleOpenChange}>
            <PopoverTrigger asChild>
                <Button variant="ghost" size="icon" className={cn("relative text-zinc-400 hover:text-white transition-colors", className)}>
                    <Rss className="h-5 w-5" />
                    {unreadCount > 0 && (
                        <span className="absolute top-1 right-1 flex h-4 w-4 items-center justify-center rounded-full bg-emerald-500 text-[10px] font-black text-white ring-2 ring-zinc-950 animate-in zoom-in duration-300 shadow-[0_0_10px_rgba(16,185,129,0.5)]">
                            {unreadCount > 9 ? "9+" : unreadCount}
                        </span>
                    )}
                    <span className="sr-only">Nouveautés Communauté</span>
                </Button>
            </PopoverTrigger>
            <PopoverContent className="w-80 p-0 overflow-hidden rounded-2xl border-white/10 bg-[#0d0f11]/95 backdrop-blur-3xl shadow-[0_30px_60px_rgba(0,0,0,0.7)]" align="end">
                <div className="flex items-center justify-between px-4 py-3 border-b border-white/5 bg-gradient-to-r from-emerald-500/10 to-transparent">
                    <div className="flex items-center gap-2">
                        <Rss className="h-4 w-4 text-emerald-500" />
                        <h4 className="font-bold text-xs uppercase tracking-widest text-white">Créateurs & Dofus</h4>
                    </div>
                    <Button
                        variant="ghost"
                        size="sm"
                        className="h-7 px-2 text-[8px] font-black uppercase tracking-widest text-zinc-500 hover:text-emerald-400 hover:bg-emerald-500/10 gap-1.5 transition-all"
                        onClick={async (e) => { 
                            e.stopPropagation(); 
                            await fetchFeed(true); 
                            // After a manual refresh while looking at it, mark all as read again 
                            // to ensure the badge doesn't pop back up due to fresh timestamps
                            await markFeedAsRead(guildId);
                            setUnreadCount(0);
                        }}
                        disabled={isLoading}
                    >
                        <RefreshCw className={cn("h-3 w-3", isLoading && "animate-spin")} />
                        RAFRAÎCHIR
                    </Button>
                </div>

                <ScrollArea className="h-[350px]">
                    {isLoading && feed.length === 0 ? (
                        <div className="p-12 text-center text-xs text-zinc-500 flex flex-col items-center gap-4">
                            <span className="animate-pulse">Analyse des flux...</span>
                        </div>
                    ) : feed.length === 0 ? (
                        <div className="flex flex-col items-center justify-center h-[300px] text-zinc-500 gap-4">
                            <div className="w-12 h-12 rounded-full bg-white/5 flex items-center justify-center">
                                <Rss className="h-6 w-6 opacity-20" />
                            </div>
                            <p className="text-xs font-medium uppercase tracking-widest">Aucune nouveauté</p>
                        </div>
                    ) : (
                        <div className="grid divide-y divide-white/5">
                            {feed.map((n, i) => (
                                <a
                                    key={i}
                                    href={n.url}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="p-4 hover:bg-white/[0.03] transition-colors flex items-start gap-3 group"
                                >
                                    <div className="mt-1 h-8 w-8 rounded bg-black/50 border border-white/10 flex items-center justify-center overflow-hidden shrink-0 relative">
                                        {n.thumbnail ? (
                                            <img
                                                src={n.thumbnail}
                                                alt={n.creatorId}
                                                referrerPolicy="no-referrer"
                                                className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity"
                                            />
                                        ) : (
                                            getIcon(n.type)
                                        )}
                                        <div className="absolute inset-0 ring-1 ring-inset ring-black/50 pointer-events-none" />
                                    </div>
                                    <div className="space-y-1 overflow-hidden">
                                        <div className="flex items-center gap-1.5">
                                            {getIcon(n.type)}
                                            <span className="text-[10px] uppercase font-black tracking-widest text-zinc-400 group-hover:text-zinc-300 transition-colors">
                                                {n.creatorId}
                                            </span>
                                        </div>
                                        <p className="text-sm font-bold text-zinc-100 leading-tight group-hover:text-white transition-colors">{n.title}</p>
                                        <p className="text-[10px] text-zinc-600 font-mono pt-1">
                                            {new Date(n.published).toLocaleDateString()} à {new Date(n.published).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                        </p>
                                    </div>
                                    <ExternalLink className="w-3 h-3 text-white/20 group-hover:text-white/60 transition-colors shrink-0 mt-1 opacity-0 group-hover:opacity-100" />
                                </a>
                            ))}
                        </div>
                    )}
                </ScrollArea>
                <div className="p-2 border-t border-white/5 bg-white/5">
                    <Button variant="ghost" size="sm" className="w-full text-[10px] font-black uppercase tracking-widest h-10 hover:bg-white/5 hover:text-white transition-all" asChild>
                        <Link href={`/dashboard/${guildId}/ressources`}>
                            Ouvrir le module Ressources
                        </Link>
                    </Button>
                </div>
            </PopoverContent>
        </Popover>
    );
}

"use client";

import { useEffect, useState } from "react";
import { Tv, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { getLiveStreamers } from "@/server/actions/feed-actions";
import { Button } from "@/components/ui/button";

interface LiveStreamer {
    creatorId: string;
    url: string;
    title: string;
}

export function LiveStreamBadge({ guildId }: { guildId: string }) {
    const [liveStreamers, setLiveStreamers] = useState<LiveStreamer[]>([]);
    const [isHidden, setIsHidden] = useState(true); // Default to true while loading
    const [isDismissed, setIsDismissed] = useState(false);

    useEffect(() => {
        // Check if dismissed in last 4 hours
        const lastDismiss = localStorage.getItem(`live-badge-dismissed-${guildId}`);
        if (lastDismiss) {
            const dimissTime = parseInt(lastDismiss, 10);
            if (Date.now() - dimissTime < 1000 * 60 * 60 * 4) {
                setIsDismissed(true);
                return;
            }
        }

        const fetchLive = async () => {
            const res = await getLiveStreamers(guildId);
            if (res.success && res.data && res.data.length > 0) {
                setLiveStreamers(res.data);
                setIsHidden(false);
            } else {
                setIsHidden(true);
            }
        };

        fetchLive();
        const interval = setInterval(fetchLive, 1000 * 60 * 5); // 5 mins
        return () => clearInterval(interval);
    }, [guildId]);

    const handleDismiss = (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        localStorage.setItem(`live-badge-dismissed-${guildId}`, Date.now().toString());
        setIsDismissed(true);
    };

    if (isHidden || isDismissed || liveStreamers.length === 0) return null;

    const count = liveStreamers.length;
    const first = liveStreamers[0];
    const text = count === 1 ? `${first.creatorId} est en LIVE` : `${count} Créateurs en LIVE`;

    return (
        <div className="relative group/badge">
            <a
                href={`/dashboard/${guildId}/ressources?tab=creators`}
                className={cn(
                    "flex h-8 items-center gap-2.5 px-3 rounded-full bg-red-600/10 border border-red-500/20 hover:bg-red-600/20 transition-all duration-300 group shadow-lg shadow-red-500/20 shrink-0",
                    "animate-in fade-in slide-in-from-top-2 duration-700"
                )}
            >
                {/* Status Dot */}
                <span className="relative flex h-2 w-2">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-2 w-2 bg-red-500"></span>
                </span>

                <Tv className="w-3 h-3 text-red-500" />

                <span className="text-[10px] font-black uppercase tracking-widest text-foreground leading-none whitespace-nowrap italic">
                    {text}
                </span>

                {/* Dismiss Button */}
                <button
                    onClick={handleDismiss}
                    className="ml-1 p-0.5 rounded-full hover:bg-black/20 text-foreground/20 hover:text-foreground transition-all opacity-0 group-hover:opacity-100"
                    title="Cacher pour 4h"
                >
                    <X className="w-2.5 h-2.5" />
                </button>
            </a>
        </div>
    );
}

"use client";

import { useEffect, useState, useRef } from "react";
import { Bell, Check, Info, X, Loader2 } from "lucide-react";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from "@/components/ui/popover";
import { ScrollArea } from "@/components/ui/scroll-area";
import { cn } from "@/lib/utils";
import { getUnreadNotifications, markAllAsRead, markAsRead, type Notification } from "@/server/actions/notification-actions";
import { useRouter } from "next/navigation";
import { toast } from "sonner";

export function NotificationBell({ userId, guildId, mode = "popover", className }: { userId: string, guildId: string, mode?: "popover" | "simple", className?: string }) {
    const [notifications, setNotifications] = useState<Notification[]>([]);
    const [isOpen, setIsOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const router = useRouter();
    const lastCheckedRef = useRef<Date>(new Date());

    const fetchNotifications = async (isPolling = false) => {
        const res = await getUnreadNotifications();
        if (res.success && res.data) {
            const fresh = res.data;
            setNotifications(fresh);

            if (isPolling) {
                const newNotifs = fresh.filter(n => new Date(n.createdAt) > lastCheckedRef.current);
                newNotifs.forEach(n => {
                    // Freshness check: Only toast if created within last 60 seconds
                    // Prevents spamming old unread notifications on remount/ref reset
                    const diff = new Date().getTime() - new Date(n.createdAt).getTime();
                    if (diff < 60000) {
                        const icon = n.type === 'MISSION_VALIDATED' ? <Check className="w-4 h-4 text-green-500" /> :
                            n.type === 'MISSION_REJECTED' ? <X className="w-4 h-4 text-red-500" /> :
                                <Info className="w-4 h-4 text-blue-500" />;

                        toast(n.title, {
                            description: n.message,
                            icon: icon,
                            duration: 5000,
                        });
                    }
                });

                if (newNotifs.length > 0) {
                    const maxDate = newNotifs.reduce((acc, curr) => {
                        const d = new Date(curr.createdAt);
                        return d > acc ? d : acc;
                    }, lastCheckedRef.current);
                    lastCheckedRef.current = maxDate;
                }
            } else {
                if (fresh.length > 0) {
                    const maxDate = fresh.reduce((acc, curr) => {
                        const d = new Date(curr.createdAt);
                        return d > acc ? d : acc;
                    }, new Date(0));
                    if (maxDate > lastCheckedRef.current) {
                        lastCheckedRef.current = maxDate;
                    }
                }
            }
        }
        setIsLoading(false);
    };

    useEffect(() => {
        fetchNotifications(false);
        const interval = setInterval(() => fetchNotifications(true), 10000);
        return () => clearInterval(interval);
    }, []);

    const unreadCount = notifications.length;

    if (mode === "simple") {
        return (
            <div className={cn("relative flex items-center justify-center w-full h-full", className)}>
                <Bell className="h-5 w-5" />
                {unreadCount > 0 && (
                    <span className="absolute top-1 right-1 flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-[10px] font-black text-white ring-2 ring-zinc-950 animate-in zoom-in duration-300">
                        {unreadCount > 9 ? "9+" : unreadCount}
                    </span>
                )}
                <span className="sr-only">Notifications</span>
            </div>
        );
    }

    const handleMarkAllRead = async () => {
        await markAllAsRead();
        setNotifications([]);
        toast.success("Toutes les notifications marquées comme lues");
    };

    const handleNotificationClick = async (n: Notification) => {
        if (!n.read) {
            await markAsRead(n.id);
            setNotifications(prev => prev.filter(item => item.id !== n.id));
        }
        if (n.link) {
            router.push(n.link);
            setIsOpen(false);
        }
    };

    return (
        <Popover open={isOpen} onOpenChange={setIsOpen}>
            <PopoverTrigger asChild>
                <Button variant="ghost" size="icon" className={cn("relative text-zinc-400 hover:text-white transition-colors", className)}>
                    <Bell className="h-5 w-5" />
                    {unreadCount > 0 && (
                        <span className="absolute top-1 right-1 flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-[10px] font-black text-white ring-2 ring-zinc-950 animate-in zoom-in duration-300">
                            {unreadCount > 9 ? "9+" : unreadCount}
                        </span>
                    )}
                    <span className="sr-only">Notifications</span>
                </Button>
            </PopoverTrigger>
            <PopoverContent className="w-80 p-0 overflow-hidden rounded-2xl border-white/10 bg-[#0d0f11]/95 backdrop-blur-3xl shadow-[0_30px_60px_rgba(0,0,0,0.7)]" align="end">
                <div className="flex items-center justify-between px-4 py-3 border-b border-white/5 bg-white/5">
                    <h4 className="font-bold text-xs uppercase tracking-widest text-white">Notifications</h4>
                    {unreadCount > 0 && (
                        <Button variant="ghost" size="sm" className="h-auto px-2 py-1 text-[10px] font-black uppercase tracking-tighter text-zinc-500 hover:text-primary transition-colors" onClick={handleMarkAllRead}>
                            Tout lu
                            <Check className="ml-1 h-3 w-3" />
                        </Button>
                    )}
                </div>
                <ScrollArea className="h-[350px]">
                    {isLoading ? (
                        <div className="p-12 text-center text-xs text-zinc-500 flex flex-col items-center gap-4">
                            <Loader2 className="w-5 h-5 animate-spin text-zinc-700" />
                            Chargement...
                        </div>
                    ) : notifications.length === 0 ? (
                        <div className="flex flex-col items-center justify-center h-[300px] text-zinc-500 gap-4">
                            <div className="w-12 h-12 rounded-full bg-white/5 flex items-center justify-center">
                                <Bell className="h-6 w-6 opacity-20" />
                            </div>
                            <p className="text-xs font-medium uppercase tracking-widest">Aucune notification</p>
                        </div>
                    ) : (
                        <div className="grid divide-y divide-white/5">
                            {notifications.map((n) => (
                                <div
                                    key={n.id}
                                    className="p-4 hover:bg-muted/50 cursor-pointer transition-colors flex items-start gap-3"
                                    onClick={() => handleNotificationClick(n)}
                                >
                                    <div className={cn(
                                        "h-2 w-2 mt-1.5 rounded-full flex-shrink-0",
                                        n.type === 'MISSION_VALIDATED' ? "bg-green-500" :
                                            n.type === 'MISSION_REJECTED' ? "bg-red-500" : "bg-blue-500"
                                    )} />
                                    <div className="space-y-1 overflow-hidden">
                                        <p className="text-sm font-bold text-zinc-100 leading-tight group-hover:text-white transition-colors">{n.title}</p>
                                        <p className="text-xs text-zinc-400 line-clamp-2 leading-relaxed">{n.message}</p>
                                        <p className="text-[10px] text-zinc-600 font-mono pt-1">
                                            {new Date(n.createdAt).toLocaleDateString()} at {new Date(n.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                        </p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </ScrollArea>
                <div className="p-2 border-t border-white/5 bg-white/5">
                    <Button variant="ghost" size="sm" className="w-full text-[10px] font-black uppercase tracking-widest h-10 hover:bg-white/5 hover:text-white transition-all" asChild>
                        <Link href={`/dashboard/${guildId}/notifications`}>
                            Voir toutes les notifications
                        </Link>
                    </Button>
                </div>
            </PopoverContent>
        </Popover>
    );
}

"use client";

// =============================================================================
// KRALAMOURE WIDGET - Community Kralamoure events display
// =============================================================================
// Shows upcoming community-organized Kralamoure events from Metamob

import { useState, useEffect, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from "@/components/ui/tooltip";
import {
    Calendar,
    RefreshCw,
    Skull,
    Timer,
    Users,
    MessageSquare,
    Sparkles,
} from "lucide-react";
import { formatDistanceToNow, format, isWithinInterval, addMinutes } from "date-fns";
import { fr } from "date-fns/locale";
import { cn } from "@/lib/utils";
import { getGuildKralamoureEvents } from "@/server/actions/ocre-actions";
import type { KralamoureEvent } from "@/lib/metamob-client";

import { importKralaEvent, getImportedKralamoureIds } from "@/server/actions/calendar-actions";
import { toast } from "sonner";
import { CalendarPlus, CalendarCheck } from "lucide-react";

interface KralamoureWidgetProps {
    guildId: string;
    maxEvents?: number;
    canManageCalendar?: boolean;
}

export function KralamoureWidget({ guildId, maxEvents = 3, canManageCalendar = false }: KralamoureWidgetProps) {
    const [events, setEvents] = useState<KralamoureEvent[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [importedIds, setImportedIds] = useState<number[]>([]);

    const loadEvents = useCallback(async () => {
        setLoading(true);
        setError(null);
        const result = await getGuildKralamoureEvents(guildId);
        if (result.success && result.data) {
            // Filter to upcoming events only
            const now = new Date();
            const upcoming = result.data
                .filter((e) => new Date(e.event_datetime) > now)
                .slice(0, maxEvents);
            setEvents(upcoming);

            // Load imported IDs
            const importedResult = await getImportedKralamoureIds(guildId);
            if (importedResult.success) {
                setImportedIds(importedResult.ids);
            }
        } else {
            setError(result.error || "Erreur de chargement");
        }
        setLoading(false);
    }, [guildId, maxEvents]);

    useEffect(() => {
        loadEvents();
        // Refresh every 5 minutes
        const interval = setInterval(loadEvents, 5 * 60 * 1000);
        return () => clearInterval(interval);
    }, [loadEvents]);

    return (
        <Card className="relative overflow-hidden bg-gradient-to-br from-pink-500/10 via-card/50 to-card/30 backdrop-blur-xl border-pink-500/20">
            {/* Glow effect */}
            <div className="absolute inset-0 bg-gradient-to-br from-pink-500/5 to-transparent pointer-events-none" />

            <CardHeader className="relative z-10 flex flex-row items-center justify-between space-y-0 pb-3 px-5 pt-5">
                <CardTitle className="text-base font-black flex items-center gap-2 text-white">
                    <Skull className="h-5 w-5 text-pink-500 fill-pink-500/10" />
                    Kralamoure
                </CardTitle>
                <Button
                    variant="ghost"
                    size="icon"
                    className="h-9 w-9 rounded-xl bg-white/5 border border-white/5 hover:bg-white/10 hover:border-white/10 transition-all group"
                    onClick={loadEvents}
                    disabled={loading}
                >
                    <RefreshCw
                        className={cn("h-4 w-4 text-muted-foreground group-hover:text-white transition-colors", loading && "animate-spin")}
                    />
                </Button>
            </CardHeader>

            <CardContent className="relative z-10 space-y-3">
                {loading && events.length === 0 ? (
                    <div className="space-y-3">
                        {[...Array(2)].map((_, i) => (
                            <div key={i} className="h-16 w-full bg-white/5 animate-pulse rounded-lg" />
                        ))}
                    </div>
                ) : error ? (
                    <div className="text-center py-4 text-sm text-muted-foreground">
                        <Skull className="h-8 w-8 mx-auto mb-2 opacity-30" />
                        {error}
                    </div>
                ) : events.length === 0 ? (
                    <div className="text-center py-4 text-sm text-muted-foreground">
                        <Calendar className="h-8 w-8 mx-auto mb-2 opacity-30" />
                        Aucun événement à venir
                    </div>
                ) : (
                    <AnimatePresence mode="popLayout">
                        {events.map((event, index) => (
                            <KralamoureEventCard
                                key={event.id}
                                event={event}
                                index={index}
                                canManageCalendar={canManageCalendar}
                                guildId={guildId}
                                isImported={importedIds.includes(event.id)}
                                onImportSuccess={loadEvents}
                            />
                        ))}
                    </AnimatePresence>
                )}
            </CardContent>
        </Card>
    );
}

// -----------------------------------------------------------------------------
// Event Card Sub-component
// -----------------------------------------------------------------------------

interface KralamoureEventCardProps {
    event: KralamoureEvent;
    index: number;
    canManageCalendar: boolean;
    guildId: string;
    isImported: boolean;
    onImportSuccess: () => void;
}

function KralamoureEventCard({ event, index, canManageCalendar, guildId, isImported, onImportSuccess }: KralamoureEventCardProps) {
    const eventTime = new Date(event.event_datetime);
    const now = new Date();
    const [isImporting, setIsImporting] = useState(false);

    // Check if event is happening soon (within 15 minutes)
    const isUpcoming = isWithinInterval(eventTime, {
        start: now,
        end: addMinutes(now, 15),
    });

    // Check if event is happening very soon (within 5 minutes)
    const isImminent = isWithinInterval(eventTime, {
        start: now,
        end: addMinutes(now, 5),
    });

    const handleImport = async () => {
        setIsImporting(true);
        const result = await importKralaEvent(guildId, {
            ...event,
            description: event.description || ""
        });
        if (result.success) {
            toast.success("Événement importé dans le calendrier !");
            onImportSuccess(); // Refresh to update imported status
        } else {
            toast.error(result.error || "Erreur lors de l'import");
        }
        setIsImporting(false);
    };

    return (
        <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
            transition={{ delay: index * 0.1 }}
            className={cn(
                "relative p-4 rounded-xl border transition-all duration-300 overflow-hidden",
                "bg-zinc-900/40 backdrop-blur-md",
                isImminent
                    ? "border-red-500/50 shadow-[0_0_15px_-5px_rgba(239,68,68,0.5)]"
                    : isUpcoming
                        ? "border-amber-500/40"
                        : "border-white/5 hover:border-white/10"
            )}
        >
            {/* Background Gradient */}
            <div className="absolute inset-0 bg-gradient-to-br from-white/[0.02] to-transparent pointer-events-none" />

            {/* Top Row: Title & Badge */}
            <div className="relative z-10 flex items-start justify-between mb-3">
                <div className="space-y-0.5">
                    <div className="flex items-center gap-2">
                        <h4 className="font-black text-sm text-white tracking-tight">
                            CHASSE KRALAMOURE
                        </h4>
                        {isUpcoming && <Sparkles className="h-3 w-3 text-amber-400 animate-pulse" />}
                    </div>
                    <p className="text-[10px] font-black text-pink-500 uppercase tracking-[0.1em]">
                        {event.server.name}
                    </p>
                </div>

                {isImported && (
                    <Badge className="bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded-md">
                        <CalendarCheck className="h-3 w-3 mr-1" />
                        Importé
                    </Badge>
                )}
            </div>

            {/* Middle Row: Content & Time */}
            <div className="relative z-10 flex items-end justify-between gap-4">
                <div className="space-y-2 flex-1">
                    <div className="flex items-center gap-3 text-[10px] font-bold text-zinc-500">
                        <span className="flex items-center gap-1">
                            <Users className="h-3 w-3" />
                            {event.participants_count}
                        </span>
                        {(event.messages_count ?? 0) > 0 && (
                            <span className="flex items-center gap-1">
                                <MessageSquare className="h-3 w-3" />
                                {event.messages_count}
                            </span>
                        )}
                        <span className="opacity-40">par {event.creator}</span>
                    </div>

                    {event.description && (
                        <p className="text-[10px] text-zinc-400/70 italic line-clamp-1 border-l-2 border-white/5 pl-2">
                            {event.description}
                        </p>
                    )}
                </div>

                <div className="text-right shrink-0">
                    <p className={cn(
                        "text-[9px] font-black uppercase tracking-wider mb-0.5",
                        isImminent ? "text-red-400" : isUpcoming ? "text-amber-400" : "text-zinc-500"
                    )}>
                        {formatDistanceToNow(eventTime, { locale: fr, addSuffix: true })}
                    </p>
                    <div className="flex items-center gap-3">
                        <span className="text-xl font-black text-white tabular-nums leading-none">
                            {format(eventTime, "HH:mm", { locale: fr })}
                        </span>
                        
                        {canManageCalendar && !isImported && (
                            <Button
                                variant="outline"
                                size="icon"
                                className="h-8 w-8 rounded-lg bg-white/5 border-white/10 hover:bg-pink-500 hover:text-white hover:border-pink-500 transition-all"
                                onClick={handleImport}
                                disabled={isImporting}
                            >
                                {isImporting ? (
                                    <RefreshCw className="h-3 w-3 animate-spin" />
                                ) : (
                                    <CalendarPlus className="h-4 w-4" />
                                )}
                            </Button>
                        )}
                    </div>
                </div>
            </div>
        </motion.div>
    );
}

"use client";

// =============================================================================
// OCRE DASHBOARD - Main quest progress dashboard with pagination
// =============================================================================

import { useState, useMemo, useEffect, useCallback } from "react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
} from "@/components/ui/dialog";
import {
    AlertTriangle,
    Package,
    Gift,
    Bug,
    ChevronLeft,
    ChevronRight,
    ArrowRightLeft,
    Loader2,
    Sparkles,
    Check,
    User,
    CheckCircle2,
    Plus,
    Minus,
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import Link from "next/link";
import { toast } from "sonner";

import { Progress } from "@/components/ui/progress";
// import { ProgressRing } from "./progress-ring"; // Removed as we use bars now
import { OcreStatCard, StatsGrid } from "./ocre-stats";
import { OcreMonsterCard } from "./ocre-monster-card";
import { OcreFilterBar, type OcreFilters, type MonsterType, type SortOption } from "./ocre-filter-bar";
import { OcreExchangeModal } from "./ocre-exchange-modal";
import { OcreTradeInbox } from "./ocre-trade-inbox";
import { OcreSettingsModal } from "./ocre-settings-modal";
import { OcreGuildDirectory } from "./ocre-guild-directory";

import {
    forceRefreshOcre,
    getGuildExchangeMap,
    findMonsterOwnersAction,
    type OcreProgressData,
    type ExchangePartner,
} from "@/server/actions/ocre-actions";
import type { OcreMonster } from "@/lib/metamob-client";

// Constants
const ITEMS_PER_PAGE = 48;

interface OcreDashboardProps {
    data: OcreProgressData;
    guildId: string;
    hasOcreChannel?: boolean;
}

export function OcreDashboard({ data, guildId, hasOcreChannel }: OcreDashboardProps) {
    // Filter state
    const [filters, setFilters] = useState<OcreFilters>({
        searchQuery: "",
        selectedType: "all",
        selectedStep: "all",
        selectedZone: "all",
        minQuantity: 0,
        sortBy: "step-asc",
    });

    // Other state
    const [exchangeMap, setExchangeMap] = useState<Record<number, number>>({});
    const [exchangeMapLoading, setExchangeMapLoading] = useState(true);
    const [currentPage, setCurrentPage] = useState(1);

    // Selection Mode
    const [isSelectionMode, setIsSelectionMode] = useState(false);
    const [selectedMonsterIds, setSelectedMonsterIds] = useState<Set<number>>(new Set());
    const [isBulkUpdating, setIsBulkUpdating] = useState(false);

    const toggleMonsterSelection = useCallback((id: number) => {
        setSelectedMonsterIds(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    }, []);

    const handleBulkUpdate = async (type: 'inc' | 'dec' | 'set', value?: number) => {
        if (selectedMonsterIds.size === 0) return;
        setIsBulkUpdating(true);
        try {
            const updates = Array.from(selectedMonsterIds).map(id => {
                const m = data.monsters.find(x => x.id === id);
                let newQty = m?.owned || 0;
                if (type === 'inc') newQty += 1;
                else if (type === 'dec') newQty = Math.max(0, newQty - 1);
                else if (type === 'set' && value !== undefined) newQty = value;
                return { monster_id: id, quantity: newQty };
            });

            const { bulkUpdateMonsterQuantitiesAction } = await import("@/server/actions/ocre-actions");
            const res = await bulkUpdateMonsterQuantitiesAction({ guildId, monsters: updates });
            if (res.success) {
                toast.success(`${selectedMonsterIds.size} monstres mis à jour !`);
                setIsSelectionMode(false);
                setSelectedMonsterIds(new Set());
                window.location.reload();
            } else {
                toast.error(res.error || "Erreur lors de la mise à jour groupée");
            }
        } catch {
            toast.error("Erreur réseau");
        } finally {
            setIsBulkUpdating(false);
        }
    };

    // Load exchange map on mount
    const loadExchangeMap = useCallback(async () => {
        setExchangeMapLoading(true);
        const result = await getGuildExchangeMap(guildId);
        if (result.success && result.data) {
            setExchangeMap(result.data.availableExchanges);
        }
        setExchangeMapLoading(false);
    }, [guildId]);

    // Extract unique steps and zones from monsters
    const { steps, zones } = useMemo(() => {
        const uniqueSteps = new Set<number>();
        const uniqueZones = new Set<string>();

        data.monsters.forEach((m) => {
            if (m.step) uniqueSteps.add(m.step);
            if (m.zone) uniqueZones.add(m.zone);
        });

        return {
            steps: Array.from(uniqueSteps).sort((a, b) => a - b),
            zones: Array.from(uniqueZones).sort((a, b) => a.localeCompare(b, "fr")),
        };
    }, [data.monsters]);

    // Categorize monsters
    const { manquants, possedes, doublons } = useMemo(() => {
        return {
            manquants: data.monsters.filter((m) => m.state === "MANQUANT"),
            possedes: data.monsters.filter((m) => m.state !== "MANQUANT"), // Includes Doublons
            doublons: data.monsters.filter((m) => m.state === "DOUBLON"),
        };
    }, [data.monsters]);

    // Sort function
    const sortMonsters = useCallback((monsters: OcreMonster[]): OcreMonster[] => {
        return [...monsters].sort((a, b) => {
            switch (filters.sortBy) {
                case "name-asc":
                    return a.name.localeCompare(b.name, "fr");
                case "name-desc":
                    return b.name.localeCompare(a.name, "fr");
                case "step-asc":
                    return (a.step ?? 999) - (b.step ?? 999);
                case "step-desc":
                    return (b.step ?? 0) - (a.step ?? 0);
                default:
                    return 0;
            }
        });
    }, [filters.sortBy]);

    // Filter function
    const filterMonsters = useCallback((monsters: OcreMonster[]) => {
        let filtered = monsters;

        // Filter by type
        if (filters.selectedType !== "all") {
            filtered = filtered.filter((m) => m.type === filters.selectedType);
        }

        // Filter by step
        if (filters.selectedStep !== "all") {
            const stepNum = parseInt(filters.selectedStep, 10);
            filtered = filtered.filter((m) => m.step === stepNum);
        }

        // Filter by zone
        if (filters.selectedZone !== "all") {
            filtered = filtered.filter((m) => m.zone === filters.selectedZone);
        }

        // Filter by min quantity
        if (filters.minQuantity > 0) {
            filtered = filtered.filter((m) => (m.owned || 0) >= filters.minQuantity);
        }

        // Filter by search query
        if (filters.searchQuery.trim()) {
            const query = filters.searchQuery.toLowerCase();
            filtered = filtered.filter((m) =>
                m.name.toLowerCase().includes(query) ||
                (m.zone && m.zone.toLowerCase().includes(query))
            );
        }

        // Apply sorting
        filtered = sortMonsters(filtered);

        return filtered;
    }, [filters, sortMonsters]);

    // Filtered and sorted lists
    // Note: filterMonsters is already a useCallback — no extra useMemo needed.
    // The React Compiler handles memoization automatically.
    const filteredManquants = filterMonsters(manquants);
    const filteredPossedes = filterMonsters(possedes);
    const filteredDoublons = filterMonsters(doublons);

    // Reset page when filters change
    useEffect(() => {
        setCurrentPage(1);
    }, [filters]);



    // Find exchange partners for a specific monster
    const handleFindExchanges = async (_monsterId: number): Promise<ExchangePartner[]> => {
        const result = await findMonsterOwnersAction({ guildId, monsterId: _monsterId });
        if (result.success && result.data) {
            return result.data;
        }
        return [];
    };

    // Progress Calculation Helpers
    const getProgressColor = (current: number, total: number) => {
        if (current === total) return "bg-emerald-500";
        if (current > total * 0.7) return "bg-emerald-400";
        if (current > total * 0.3) return "bg-amber-400";
        return "bg-red-400";
    };

    const renderProgressBar = (label: string, category: { total: number; gathered: number }) => {
        if (!category) return null;
        const total = category.total || 1; // Avoid div by zero
        const percent = Math.min(100, Math.round((category.gathered / total) * 100));
        return (
            <div className="space-y-1">
                <div className="flex items-center justify-between text-xs">
                    <span className="font-medium text-muted-foreground">{label}</span>
                    <span className="text-muted-foreground">
                        <span className={category.gathered === total ? "text-emerald-500 font-bold" : "text-foreground"}>
                            {category.gathered}
                        </span>
                        /{total}
                    </span>
                </div>
                <Progress value={percent} className="h-1.5" indicatorClassName={getProgressColor(category.gathered, total)} />
            </div>
        );
    };

    return (
        <div className="space-y-6">
            {/* Header with Progress (Metamob Style) */}
            <div className="relative overflow-hidden p-6 rounded-2xl bg-card border border-border shadow-xl">
                {/* Background Decoration */}
                <div className="absolute top-0 right-0 w-64 h-64 bg-amber-500/5 blur-3xl -mr-32 -mt-32 pointer-events-none" />

                <div className="relative z-10 flex flex-col md:flex-row gap-8">
                    {/* Left Side: Character & Quest Info */}
                    <div className="flex-1 space-y-4">
                        <div className="flex flex-col gap-1">
                            <h2 className="text-xl font-bold text-foreground flex items-center gap-2">
                                <Sparkles className="h-5 w-5 text-amber-500 fill-amber-500/20" />
                                Quête de l&apos;Éternelle Moisson
                            </h2>
                            <div className="flex items-center gap-2 text-muted-foreground text-sm">
                                <a
                                    href={`https://www.metamob.fr/profile/${data.questInfo.characterName}`}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="font-semibold text-foreground hover:text-amber-500 transition-colors flex items-center gap-1 group/link"
                                >
                                    {data.questInfo.characterName}
                                    <ArrowRightLeft className="h-3 w-3 opacity-0 group-hover/link:opacity-100 transition-all -rotate-45" />
                                </a>
                                <span className="opacity-40">•</span>
                                <span>{data.questInfo.serverName}</span>
                                <Badge variant="outline" className="ml-2 border-amber-500/30 text-amber-500 text-[10px] h-5 px-1.5">
                                    Unity
                                </Badge>
                            </div>
                        </div>

                        <div className="flex flex-wrap items-center gap-3">
                            <div className="flex flex-col bg-background/50 border border-border px-3 py-2 rounded-xl min-w-[100px]">
                                <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-bold">Étape Actuelle</span>
                                <span className="text-lg font-bold text-amber-500">{data.questInfo.currentStep}<span className="text-muted-foreground/30 text-xs ml-1">/ {data.questInfo.totalSteps}</span></span>
                            </div>
                            <div className="flex flex-col bg-background/50 border border-border px-3 py-2 rounded-xl min-w-[100px]">
                                <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-bold">Progression</span>
                                <span className="text-lg font-bold text-emerald-500">{data.stats.progressPercent}%</span>
                            </div>
                        </div>
                    </div>

                    {/* Right Side: Progress Bars */}
                    <div className="w-full md:w-[350px] space-y-4 bg-background/30 p-5 rounded-3xl border border-border/50 shadow-inner">
                        {renderProgressBar("Gardiens", data.stats.bosses)}
                        {renderProgressBar("Archimonstres", data.stats.archis)}
                    </div>
                </div>

            </div>

            {/* Main Navigation Sub-menu */}
            <Tabs defaultValue="progression" className="w-full space-y-8">
                <TabsList className="flex items-center justify-start h-auto p-1.5 bg-zinc-900/50 border border-white/5 rounded-2xl w-full gap-3 overflow-x-auto no-scrollbar shrink-0">
                    <TabsTrigger
                        value="progression"
                        className="flex-1 py-3 px-6 rounded-xl data-[state=active]:bg-zinc-800 data-[state=active]:text-amber-500 data-[state=active]:shadow-lg hover:bg-white/5 transition-all font-bold uppercase tracking-widest text-xs border border-transparent data-[state=active]:border-amber-500/20"
                    >
                        Progression
                    </TabsTrigger>
                    <TabsTrigger
                        value="monstres"
                        className="flex-1 py-3 px-6 rounded-xl data-[state=active]:bg-zinc-800 data-[state=active]:text-amber-500 data-[state=active]:shadow-lg hover:bg-white/5 transition-all font-bold uppercase tracking-widest text-xs border border-transparent data-[state=active]:border-amber-500/20"
                    >
                        Bestiaire
                    </TabsTrigger>
                    <TabsTrigger
                        value="echanges"
                        className="flex-1 py-3 px-6 rounded-xl data-[state=active]:bg-zinc-800 data-[state=active]:text-amber-500 data-[state=active]:shadow-lg hover:bg-white/5 transition-all font-bold uppercase tracking-widest text-xs border border-transparent data-[state=active]:border-amber-500/20"
                    >
                        Échanges
                    </TabsTrigger>
                    <TabsTrigger
                        value="membres"
                        className="flex-1 py-3 px-6 rounded-xl data-[state=active]:bg-zinc-800 data-[state=active]:text-amber-500 data-[state=active]:shadow-lg hover:bg-white/5 transition-all font-bold uppercase tracking-widest text-xs border border-transparent data-[state=active]:border-amber-500/20"
                    >
                        Membres
                    </TabsTrigger>
                </TabsList>

                {/* Tab: Summary & Global Stats */}
                <TabsContent value="progression" className="space-y-8 outline-none mt-0">
                    <div className="grid gap-6">
                        <h3 className="text-sm font-bold uppercase tracking-widest text-muted-foreground/50">Vue d&apos;ensemble</h3>
                        <StatsGrid>
                            <OcreStatCard
                                label="Total Éléments"
                                value={data.stats.total}
                                icon={Bug}
                                color="purple"
                                delay={0}
                            />
                            <OcreStatCard
                                label="Acquis / Validés"
                                value={data.stats.acquired}
                                icon={CheckCircle2}
                                color="green"
                                delay={0.1}
                            />
                            <OcreStatCard
                                label="Reste à trouver"
                                value={data.stats.remaining}
                                icon={AlertTriangle}
                                color="red"
                                delay={0.2}
                            />
                            <OcreStatCard
                                label="Doublons"
                                value={data.stats.doublons}
                                icon={Gift}
                                color="amber"
                                delay={0.3}
                            />
                        </StatsGrid>
                    </div>

                    <div className="p-8 rounded-3xl border border-dashed border-border flex flex-col items-center justify-center text-center space-y-4">
                        <div className="h-12 w-12 rounded-2xl bg-amber-500/10 flex items-center justify-center">
                            <Sparkles className="h-6 w-6 text-amber-500" />
                        </div>
                        <div className="max-w-xs">
                            <h4 className="font-bold text-foreground">Astuce Ocre</h4>
                            <p className="text-sm text-muted-foreground mt-1">
                                Utilisez la synchronisation Metamob pour mettre à jour vos captures automatiquement et trouver des partenaires d&apos;échange dans la guilde.
                            </p>
                        </div>
                    </div>
                </TabsContent>

                {/* Tab: Monsters & Search */}
                <TabsContent value="monstres" className="space-y-6 outline-none mt-0">
                    {/* Filter Bar */}
                    <OcreFilterBar
                        filters={filters}
                        onFiltersChange={setFilters}
                        steps={steps}
                        zones={zones}
                        guildId={guildId}
                        showMarketplace={false}
                        hasOcreChannel={hasOcreChannel}
                        selectionMode={isSelectionMode}
                        onSelectionModeToggle={() => {
                            setIsSelectionMode(!isSelectionMode);
                            setSelectedMonsterIds(new Set());
                        }}
                    />

                    {/* Secondary Tabs (Grid) */}
                    <Tabs defaultValue="manquants" className="w-full">
                        <div className="overflow-x-auto no-scrollbar pb-1">
                            <TabsList className="inline-flex w-auto bg-zinc-900/50 backdrop-blur-sm border border-white/5 p-1.5 rounded-2xl min-w-full sm:min-w-0 gap-2">
                                <TabsTrigger value="manquants" className="gap-3 rounded-xl py-3 px-6 data-[state=active]:bg-zinc-800 data-[state=active]:text-red-400 data-[state=active]:shadow-lg border border-transparent data-[state=active]:border-red-500/20 hover:bg-white/5 transition-all font-bold tracking-tight">
                                    <span className="hidden sm:inline">Manquants</span>
                                    <Badge variant="secondary" className="h-5 px-1.5 text-[10px] bg-red-500/10 text-red-500 border-none font-black">
                                        {filteredManquants.length}
                                    </Badge>
                                </TabsTrigger>
                                <TabsTrigger value="possedes" className="gap-3 rounded-xl py-3 px-6 data-[state=active]:bg-zinc-800 data-[state=active]:text-emerald-400 data-[state=active]:shadow-lg border border-transparent data-[state=active]:border-emerald-500/20 hover:bg-white/5 transition-all font-bold tracking-tight">
                                    <span className="hidden sm:inline">Possédés</span>
                                    <Badge variant="secondary" className="h-5 px-1.5 text-[10px] bg-emerald-500/10 text-emerald-500 border-none font-black">
                                        {filteredPossedes.length}
                                    </Badge>
                                </TabsTrigger>
                                <TabsTrigger value="doublons" className="gap-3 rounded-xl py-3 px-6 data-[state=active]:bg-zinc-800 data-[state=active]:text-amber-400 data-[state=active]:shadow-lg border border-transparent data-[state=active]:border-amber-500/20 hover:bg-white/5 transition-all font-bold tracking-tight">
                                    <span className="hidden sm:inline">Doublons</span>
                                    <Badge variant="secondary" className="h-5 px-1.5 text-[10px] bg-amber-500/10 text-amber-500 border-none font-black">
                                        {filteredDoublons.length}
                                    </Badge>
                                </TabsTrigger>
                            </TabsList>
                        </div>

                        <TabsContent value="manquants" className="mt-6 outline-none">
                            <MonsterGrid
                                monsters={filteredManquants}
                                guildId={guildId}
                                exchangeMap={exchangeMap}
                                emptyMessage={
                                    filters.searchQuery || filters.selectedType !== "all" || filters.selectedStep !== "all"
                                        ? "Aucun monstre ne correspond aux filtres"
                                        : "Félicitations ! Vous avez tous les monstres ! 🎉"
                                }
                                currentPage={currentPage}
                                onPageChange={setCurrentPage}
                                onFindExchanges={handleFindExchanges}
                                isSelectionMode={isSelectionMode}
                                selectedIds={selectedMonsterIds}
                                onToggleSelection={toggleMonsterSelection}
                            />
                        </TabsContent>

                        <TabsContent value="possedes" className="mt-6 outline-none">
                            <MonsterGrid
                                monsters={filteredPossedes}
                                guildId={guildId}
                                exchangeMap={{}}
                                emptyMessage={
                                    filters.searchQuery || filters.selectedType !== "all" || filters.selectedStep !== "all"
                                        ? "Aucun monstre ne correspond aux filtres"
                                        : "Vous n'avez encore aucun monstre possédé"
                                }
                                currentPage={currentPage}
                                onPageChange={setCurrentPage}
                                isSelectionMode={isSelectionMode}
                                selectedIds={selectedMonsterIds}
                                onToggleSelection={toggleMonsterSelection}
                            />
                        </TabsContent>

                        <TabsContent value="doublons" className="mt-6 outline-none">
                            <MonsterGrid
                                monsters={filteredDoublons}
                                guildId={guildId}
                                exchangeMap={{}}
                                emptyMessage={
                                    filters.searchQuery || filters.selectedType !== "all" || filters.selectedStep !== "all"
                                        ? "Aucun doublon ne correspond aux filtres"
                                        : "Vous n'avez pas de doublons à proposer"
                                }
                                showExchangeButton={false}
                                currentPage={currentPage}
                                onPageChange={setCurrentPage}
                                isSelectionMode={isSelectionMode}
                                selectedIds={selectedMonsterIds}
                                onToggleSelection={toggleMonsterSelection}
                            />
                        </TabsContent>
                    </Tabs>
                </TabsContent>

                {/* Tab: Exchange Hub */}
                <TabsContent value="echanges" className="outline-none mt-0 space-y-8">
                    {/* Active Trade Requests Section */}
                    <OcreTradeInbox guildId={guildId} />

                    {/* Discovery Section (Placeholder styled as discovery) */}
                    <div className="flex flex-col items-center justify-center py-12 text-center space-y-6 bg-background/30 rounded-3xl border border-dashed border-border">
                        <div className="h-16 w-16 rounded-full bg-emerald-500/10 flex items-center justify-center border border-emerald-500/20">
                            <Sparkles className="h-8 w-8 text-emerald-500" />
                        </div>
                        <div className="max-w-sm space-y-2">
                            <h3 className="text-lg font-bold uppercase tracking-wider">Trouver de nouveaux partenaires</h3>
                            <p className="text-muted-foreground text-xs leading-relaxed">
                                Analysez les doublons des membres de la guilde pour trouver les archimonstres qui vous manquent.
                            </p>
                        </div>
                        <OcreExchangeModal
                            guildId={guildId}
                            hasOcreChannel={hasOcreChannel}
                            trigger={
                                <Button size="lg" className="bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl h-11 px-8 font-bold shadow-lg shadow-emerald-500/20 transition-all hover:scale-[1.02] text-xs">
                                    Lancer la recherche de doublons
                                </Button>
                            }
                        />
                    </div>
                </TabsContent>

                {/* Tab: Guild Directory (Membres) */}
                <TabsContent value="membres" className="outline-none mt-0 space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                    <OcreGuildDirectory guildId={guildId} />
                </TabsContent>
            </Tabs>

            {/* Floating Bulk Action Bar */}
            <AnimatePresence>
                {isSelectionMode && selectedMonsterIds.size > 0 && (
                    <motion.div
                        initial={{ y: 100, opacity: 0 }}
                        animate={{ y: 0, opacity: 1 }}
                        exit={{ y: 100, opacity: 0 }}
                        className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[100] w-[90vw] max-w-2xl"
                    >
                        <div className="bg-zinc-900/90 backdrop-blur-2xl border border-amber-500/30 rounded-3xl p-4 shadow-[0_20px_50px_rgba(0,0,0,0.5)] flex items-center justify-between gap-4">
                            <div className="flex items-center gap-4 pl-2">
                                <div className="h-10 w-10 rounded-2xl bg-amber-500/10 flex items-center justify-center border border-amber-500/20">
                                    <Badge className="bg-amber-500 text-white font-black">{selectedMonsterIds.size}</Badge>
                                </div>
                                <div className="flex flex-col">
                                    <span className="text-xs font-bold text-white uppercase tracking-wider">Monstres sélectionnés</span>
                                    <span className="text-[10px] text-muted-foreground italic">Actions groupées Metamob</span>
                                </div>
                            </div>

                            <div className="flex items-center gap-2">
                                <Button
                                    size="sm"
                                    variant="outline"
                                    className="h-10 rounded-xl bg-background/50 hover:bg-emerald-500/10 hover:text-emerald-500 font-bold border-white/5"
                                    onClick={() => handleBulkUpdate('inc')}
                                    disabled={isBulkUpdating}
                                >
                                    {isBulkUpdating ? <Loader2 className="h-4 w-4 animate-spin" /> : <Plus className="h-4 w-4 mr-2" />}
                                    +1
                                </Button>
                                <Button
                                    size="sm"
                                    variant="outline"
                                    className="h-10 rounded-xl bg-background/50 hover:bg-red-500/10 hover:text-red-500 font-bold border-white/5"
                                    onClick={() => handleBulkUpdate('dec')}
                                    disabled={isBulkUpdating}
                                >
                                    <Minus className="h-4 w-4 mr-2" />
                                    -1
                                </Button>
                                <div className="w-px h-8 bg-white/10 mx-1" />
                                <Button
                                    size="sm"
                                    className="h-10 px-6 rounded-xl bg-amber-500 hover:bg-amber-400 text-white font-bold transition-all active:scale-95"
                                    onClick={() => handleBulkUpdate('set', 1)}
                                    disabled={isBulkUpdating}
                                >
                                    Possédé (1)
                                </Button>
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}


// -----------------------------------------------------------------------------
// Monster Grid Sub-component with Pagination
// -----------------------------------------------------------------------------

interface MonsterGridProps {
    monsters: OcreMonster[];
    guildId: string;
    exchangeMap: Record<number, number>;
    emptyMessage: string;
    showExchangeButton?: boolean;
    currentPage: number;
    onPageChange: (page: number) => void;
    onFindExchanges?: (monsterId: number) => Promise<ExchangePartner[]>;
    isSelectionMode?: boolean;
    selectedIds?: Set<number>;
    onToggleSelection?: (id: number) => void;
}

function MonsterGrid({
    monsters,
    guildId,
    exchangeMap,
    emptyMessage,
    showExchangeButton = true,
    currentPage,
    onPageChange,
    onFindExchanges,
    isSelectionMode = false,
    selectedIds = new Set(),
    onToggleSelection,
}: MonsterGridProps) {
    const totalPages = Math.ceil(monsters.length / ITEMS_PER_PAGE);
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    const paginatedMonsters = monsters.slice(startIndex, startIndex + ITEMS_PER_PAGE);

    if (monsters.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center py-16 text-center">
                <Bug className="h-16 w-16 text-muted-foreground/20 mb-4" />
                <p className="text-muted-foreground">{emptyMessage}</p>
            </div>
        );
    }

    return (
        <div className="space-y-4">
            {/* Pagination Info */}
            <div className="flex items-center justify-between text-sm text-muted-foreground">
                <span>
                    {startIndex + 1}-{Math.min(startIndex + ITEMS_PER_PAGE, monsters.length)} sur {monsters.length} monstres
                </span>
                {totalPages > 1 && (
                    <div className="flex items-center gap-2">
                        <Button
                            variant="outline"
                            size="icon"
                            className="h-8 w-8"
                            onClick={() => onPageChange(currentPage - 1)}
                            disabled={currentPage === 1}
                        >
                            <ChevronLeft className="h-4 w-4" />
                        </Button>
                        <span className="min-w-[80px] text-center">
                            Page {currentPage} / {totalPages}
                        </span>
                        <Button
                            variant="outline"
                            size="icon"
                            className="h-8 w-8"
                            onClick={() => onPageChange(currentPage + 1)}
                            disabled={currentPage === totalPages}
                        >
                            <ChevronRight className="h-4 w-4" />
                        </Button>
                    </div>
                )}
            </div>

            {/* Monster Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                {paginatedMonsters.map((monster) => (
                    <OcreMonsterCard
                        key={monster.id}
                        monster={monster}
                        guildId={guildId}
                        availableExchanges={exchangeMap[monster.id] || 0}
                        showExchangeButton={showExchangeButton}
                        onFindExchanges={onFindExchanges ? () => onFindExchanges(monster.id) : undefined}
                        isSelected={selectedIds.has(monster.id)}
                        isSelectionMode={isSelectionMode}
                        onToggleSelection={onToggleSelection}
                    />
                ))}
            </div>

            {/* Bottom Pagination */}
            {totalPages > 1 && (
                <div className="flex justify-center gap-2 pt-4">
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={() => onPageChange(currentPage - 1)}
                        disabled={currentPage === 1}
                    >
                        <ChevronLeft className="h-4 w-4 mr-1" />
                        Précédent
                    </Button>
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={() => onPageChange(currentPage + 1)}
                        disabled={currentPage === totalPages}
                    >
                        Suivant
                        <ChevronRight className="h-4 w-4 ml-1" />
                    </Button>
                </div>
            )}
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
    DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import {
    Loader2,
    RefreshCw,
    Sparkles,
    Copy,
    Check,
    PackageOpen,
    Handshake,
    Bell,
    Search,
    Users
} from "lucide-react";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import Link from "next/link";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { findOcreExchangePartners, getOcreExchangeJobStatus, createTradeRequest, type ExchangePartner } from "@/server/actions/ocre-actions";

interface OcreExchangeModalProps {
    guildId: string;
    hasOcreChannel?: boolean;
    trigger?: React.ReactNode;
}

export function OcreExchangeModal({ guildId, hasOcreChannel, trigger }: OcreExchangeModalProps) {
    const [isOpen, setIsOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [progress, setProgress] = useState(0);
    const [partners, setPartners] = useState<ExchangePartner[]>([]);
    const [copiedUser, setCopiedUser] = useState<string | null>(null);
    const [monsterSearch, setMonsterSearch] = useState("");
    const [memberSearch, setMemberSearch] = useState("");

    // Trade Request State
    const [tradeRequest, setTradeRequest] = useState<{ targetProfileId: string; monsterId: number; targetName: string; monsterName: string; monsterImage?: string } | null>(null);
    const [tradeMessage, setTradeMessage] = useState("");
    const [sendDiscordPing, setSendDiscordPing] = useState(hasOcreChannel ?? false);
    const [isSubmittingTrade, setIsSubmittingTrade] = useState(false);
    const [targetChannelName, setTargetChannelName] = useState<string>("commerce");

    useEffect(() => {
        if (hasOcreChannel && guildId) {
            import("@/server/actions/ocre-actions").then(m => {
                m.getOcrePublicConfig(guildId).then(res => {
                    if (res.success && res.data?.ocreNotifyChannelId) {
                        import("@/server/actions/discord-actions").then(d => {
                            d.getDiscordChannelInfo(guildId, res.data!.ocreNotifyChannelId!).then(chanRes => {
                                if (chanRes.success && chanRes.data) {
                                    setTargetChannelName(chanRes.data.name);
                                }
                            });
                        });
                    }
                });
            });
        }
    }, [hasOcreChannel, guildId]);

    const fetchExchanges = async () => {
        setLoading(true);
        setProgress(0);
        try {
            const result = await findOcreExchangePartners({ guildId });
            if (result.success && result.data?.jobId) {
                const jobId = result.data.jobId;

                const pollInterval = setInterval(async () => {
                    try {
                        const statusResult = await getOcreExchangeJobStatus(jobId);
                        if (statusResult.success && statusResult.data) {
                            const { state, progress: jobProgress, result: jobResult } = statusResult.data;

                            if (typeof jobProgress === 'number') {
                                setProgress(jobProgress);
                            }

                            if (state === "completed" && jobResult) {
                                clearInterval(pollInterval);
                                const sorted = [...jobResult].sort((a, b) => b.matchScore - a.matchScore);
                                setPartners(sorted);
                                setLoading(false);
                            } else if (state === "failed") {
                                clearInterval(pollInterval);
                                toast.error(statusResult.error || "Le calcul a échoué");
                                setLoading(false);
                            }
                        } else {
                            clearInterval(pollInterval);
                            toast.error(statusResult.error || "Erreur lors du traitement asynchrone");
                            setLoading(false);
                        }
                    } catch (e) {
                        // Ignore occasional network errors during polling
                    }
                }, 1500);
            } else {
                toast.error(result.error || "Impossible d'initier la recherche");
                setLoading(false);
            }
        } catch (error) {
            toast.error("Erreur de connexion");
            setLoading(false);
        }
    };

    useEffect(() => {
        if (isOpen) {
            fetchExchanges();
        }
    }, [isOpen]); // eslint-disable-line react-hooks/exhaustive-deps

    const handleCopyMP = (partnerName: string, monsterName: string) => {
        const message = `/w ${partnerName} Salut ! Tu aurais ${monsterName} en doublon à échanger ? :)`;
        navigator.clipboard.writeText(message);
        setCopiedUser(partnerName);
        toast.success("Message copié !");
        setTimeout(() => setCopiedUser(null), 2000);
    };

    const submitTradeRequest = async () => {
        if (!tradeRequest) return;
        setIsSubmittingTrade(true);
        try {
            const res = await createTradeRequest({
                guildId,
                targetProfileId: tradeRequest.targetProfileId,
                monsterId: tradeRequest.monsterId,
                monsterName: tradeRequest.monsterName,
                monsterImage: tradeRequest.monsterImage,
                message: tradeMessage,
                sendDiscordPing
            });
            if (res.success) {
                toast.success("Demande d'échange envoyée !");
                setTradeRequest(null);
                setTradeMessage("");
            } else {
                toast.error(res.error || "Erreur lors de l'envoi");
            }
        } catch (e) {
            toast.error("Erreur de connexion");
        } finally {
            setIsSubmittingTrade(false);
        }
    };

    // Aggregate by monster
    const monstersMap = new Map<number, {
        id: number;
        name: string;
        imageUrl?: string;
        coversNeed: boolean;
        providers: {
            name: string;
            count: number;
            avatar?: string;
            profileId: string;
            metamobName: string;
        }[]
    }>();
    let neededCount = 0;

    partners.forEach(partner => {
        partner.monstersTheyHave.forEach(monster => {
            // Apply search query filter if typed
            if (monsterSearch.trim()) {
                const q = monsterSearch.toLowerCase().trim();
                if (!monster.name.toLowerCase().includes(q)) {
                    return;
                }
            }

            if (!monstersMap.has(monster.id)) {
                monstersMap.set(monster.id, {
                    id: monster.id,
                    name: monster.name,
                    imageUrl: monster.imageUrl,
                    coversNeed: monster.coversNeed,
                    providers: []
                });
            }
            monstersMap.get(monster.id)?.providers.push({
                name: partner.characterName,
                count: monster.available,
                avatar: partner.discordAvatar,
                profileId: partner.profileId,
                metamobName: partner.username
            });
            if (monster.coversNeed) neededCount++;
        });
    });

    const monstersList = Array.from(monstersMap.values()).sort((a, b) => {
        // Sort by Needed first, then Name
        if (a.coversNeed && !b.coversNeed) return -1;
        if (!a.coversNeed && b.coversNeed) return 1;
        return a.name.localeCompare(b.name);
    });

    const totalMatches = partners.reduce((acc, p) => acc + p.monstersTheyHave.length, 0);

    return (
        <Dialog open={isOpen} onOpenChange={setIsOpen}>
            <DialogTrigger asChild>
                {trigger || (
                    <Button variant="outline" className="gap-2">
                        <Sparkles className="h-4 w-4 text-emerald-500" />
                        Trouver des échanges
                    </Button>
                )}
            </DialogTrigger>
            <DialogContent className="w-[95vw] sm:max-w-4xl h-[90vh] sm:h-[85vh] !flex flex-col bg-black/95 border-white/10 p-0 gap-0 overflow-hidden">
                <DialogHeader className="p-6 border-b border-white/10 flex-shrink-0">
                    <div className="flex items-center justify-between mr-8">
                        <div>
                            <DialogTitle className="text-xl font-bold flex items-center gap-2">
                                <Sparkles className="h-5 w-5 text-emerald-400" />
                                Place de Marché
                            </DialogTitle>
                            <DialogDescription className="text-zinc-400 mt-1">
                                {totalMatches > 0
                                    ? `${totalMatches} archimontres dispo dans la guilde (dont ${monstersList.filter(m => m.coversNeed).length} que vous recherchez)`
                                    : "Recherche de correspondances dans la guilde..."}
                            </DialogDescription>
                        </div>
                        <Button
                            variant="ghost"
                            size="icon"
                            onClick={fetchExchanges}
                            disabled={loading}
                            className="shrink-0"
                        >
                            <RefreshCw className={cn("h-4 w-4", loading && "animate-spin")} />
                        </Button>
                    </div>
                </DialogHeader>

                <div className="flex-1 overflow-hidden flex flex-col min-h-0">
                    {loading && partners.length === 0 ? (
                        <div className="h-[400px] flex flex-col items-center justify-center gap-6 text-muted-foreground w-full max-w-sm mx-auto px-6">
                            <div className="relative">
                                <div className="absolute -inset-4 bg-emerald-500/20 blur-xl rounded-full" />
                                <Loader2 className="h-10 w-10 animate-spin text-emerald-500 relative z-10" />
                            </div>
                            <div className="w-full space-y-2 text-center">
                                <p className="text-zinc-300 font-medium">Analyse méticuleuse des doublons de la guilde...</p>
                                <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
                                    <div
                                        className="h-full bg-emerald-500 transition-all duration-500 ease-out"
                                        style={{ width: `${progress}%` }}
                                    />
                                </div>
                                <p className="text-xs opacity-50">{progress}%</p>
                            </div>
                        </div>
                    ) : partners.length === 0 ? (
                        <div className="h-[400px] flex flex-col items-center justify-center gap-4 text-muted-foreground p-8 text-center">
                            <PackageOpen className="h-12 w-12 opacity-20" />
                            <p>Aucun échange trouvé pour le moment.</p>
                            <p className="text-sm opacity-60">
                                Assurez-vous que vos guildeux ont mis à jour leur Metamob !
                            </p>
                        </div>
                    ) : (
                        <Tabs defaultValue="monsters" className="h-full flex flex-col flex-1 min-h-0">
                            <div className="px-4 sm:px-6 pt-4 flex flex-col gap-3 flex-shrink-0">
                                {/* Tabs + Search row */}
                                <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2 sm:gap-3">
                                    <TabsList className="grid w-full grid-cols-2 bg-zinc-950/80 border border-white/5 p-1 rounded-xl shrink-0 sm:w-auto">
                                        <TabsTrigger 
                                            value="monsters" 
                                            className="rounded-lg font-black py-2 text-[10px] uppercase tracking-wider gap-1.5 transition-all duration-205 data-[state=active]:bg-emerald-500 data-[state=active]:text-black text-zinc-400"
                                        >
                                            <PackageOpen className="h-3.5 w-3.5 shrink-0" />
                                            <span>Par Monstre ({monstersList.length})</span>
                                        </TabsTrigger>
                                        <TabsTrigger 
                                            value="members" 
                                            className="rounded-lg font-black py-2 text-[10px] uppercase tracking-wider gap-1.5 transition-all duration-205 data-[state=active]:bg-emerald-500 data-[state=active]:text-black text-zinc-400"
                                        >
                                            <Users className="h-3.5 w-3.5 shrink-0" />
                                            <span>Par Membre ({partners.filter(p => p.monstersTheyHave.some(m => !monsterSearch.trim() || m.name.toLowerCase().includes(monsterSearch.toLowerCase().trim()))).length})</span>
                                        </TabsTrigger>
                                    </TabsList>
                                    <div className="relative w-full group">
                                        <div className="absolute inset-y-0 left-3 flex items-center pointer-events-none">
                                            <Search className="h-3.5 w-3.5 text-zinc-500 group-focus-within:text-emerald-400 transition-colors" />
                                        </div>
                                        <Input
                                            value={monsterSearch}
                                            onChange={(e) => setMonsterSearch(e.target.value)}
                                            placeholder="RECHERCHER..."
                                            className="pl-9 bg-zinc-900/50 border-white/10 h-9 text-[10px] font-black uppercase tracking-[0.1em] placeholder:text-zinc-600 focus:border-emerald-500/40 focus:ring-emerald-500/10 transition-all rounded-xl"
                                        />
                                    </div>
                                </div>

                                {/* Legend row */}
                                <div className="flex items-center gap-3 text-xs bg-zinc-900/50 backdrop-blur-md border border-white/5 rounded-xl px-3 py-2 self-start">
                                    <div className="flex items-center gap-1.5">
                                        <span className="relative flex h-2 w-2 shrink-0">
                                            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                                            <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
                                        </span>
                                        <span className="font-bold text-emerald-400 text-[11px]">Recherché</span>
                                        <span className="text-[10px] text-zinc-500 hidden xs:inline">(vous manque)</span>
                                    </div>
                                    <div className="w-px h-3 bg-white/10 shrink-0" />
                                    <div className="flex items-center gap-1.5">
                                        <span className="h-2 w-2 rounded-full bg-zinc-700 shrink-0" />
                                        <span className="font-bold text-zinc-400 text-[11px]">Possédé</span>
                                        <span className="text-[10px] text-zinc-500 hidden xs:inline">(déjà acquis)</span>
                                    </div>
                                </div>
                            </div>

                            <TabsContent value="monsters" className="mt-4 focus-visible:outline-none flex-1 overflow-hidden flex flex-col min-h-0">
                                <div className="flex-1 overflow-y-auto px-6 pb-6 min-h-0">
                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                        {monstersList.map((monster) => (
                                            <div
                                                key={monster.name}
                                                className={cn(
                                                    "border transition-all duration-200 rounded-xl p-3",
                                                    monster.coversNeed 
                                                        ? "bg-emerald-500/5 border-emerald-500/20 shadow-md shadow-emerald-950/10 hover:border-emerald-500/40" 
                                                        : "bg-zinc-900/20 border-zinc-800/60 hover:border-zinc-700/60 opacity-75 hover:opacity-100"
                                                )}
                                            >
                                                <div className="flex items-start justify-between mb-2">
                                                    <div className="flex items-center gap-3">
                                                        {monster.imageUrl && (
                                                            <img
                                                                src={monster.imageUrl}
                                                                alt={monster.name}
                                                                className="w-8 h-8 object-contain shrink-0"
                                                            />
                                                        )}
                                                        <div className="flex flex-col">
                                                            <h4 className={cn("font-bold text-sm flex items-center gap-1.5", monster.coversNeed ? "text-emerald-300" : "text-zinc-400")}>
                                                                {monster.name}
                                                                {monster.coversNeed && (
                                                                    <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse shrink-0" />
                                                                )}
                                                            </h4>
                                                            {monster.coversNeed && (
                                                                <span className="text-[9px] text-emerald-500 font-bold uppercase tracking-wider">Recherché (vous manque)</span>
                                                            )}
                                                        </div>
                                                    </div>
                                                    <Badge variant="outline" className="text-[10px] border-white/10 bg-black/20 text-zinc-400 font-bold">
                                                        x{monster.providers.length}
                                                    </Badge>
                                                </div>
                                                <div className="space-y-1.5 mt-2">
                                                    {monster.providers.map((provider) => (
                                                        <div key={provider.name} className="flex items-center justify-between text-xs bg-zinc-950/80 border border-white/5 p-1.5 rounded-lg">
                                                            <div className="flex items-center gap-2">
                                                                <Link href={`/dashboard/${guildId}/members/${provider.profileId}`} target="_blank" rel="noopener noreferrer">
                                                                    <Avatar className="h-5 w-5 border border-white/10 cursor-pointer hover:border-amber-500/50 transition-colors">
                                                                        <AvatarImage src={provider.avatar} />
                                                                        <AvatarFallback className="text-[8px] bg-zinc-800 text-zinc-400 font-bold">
                                                                            {provider.name.substring(0, 2).toUpperCase()}
                                                                        </AvatarFallback>
                                                                    </Avatar>
                                                                </Link>
                                                                <div className="flex flex-col">
                                                                    <Link
                                                                        href={`/dashboard/${guildId}/members/${provider.profileId}`}
                                                                        target="_blank"
                                                                        rel="noopener noreferrer"
                                                                        className="text-zinc-300 hover:text-amber-400 font-semibold transition-colors cursor-pointer"
                                                                    >
                                                                        {provider.name} <span className="text-zinc-500 text-[10px] ml-1 font-normal">(x{provider.count})</span>
                                                                    </Link>
                                                                </div>
                                                            </div>
                                                            <div className="flex items-center gap-1">
                                                                <Button
                                                                    variant="ghost"
                                                                    size="sm"
                                                                    className="h-6 w-6 p-0 hover:text-emerald-400"
                                                                    title="Envoyer une demande d'échange SigilOS"
                                                                    onClick={() => setTradeRequest({
                                                                        targetProfileId: provider.profileId,
                                                                        monsterId: monster.id,
                                                                        targetName: provider.name,
                                                                        monsterName: monster.name,
                                                                        monsterImage: monster.imageUrl,
                                                                    })}
                                                                >
                                                                    <Handshake className="h-3.5 w-3.5" />
                                                                </Button>
                                                                <Button
                                                                    variant="ghost"
                                                                    size="sm"
                                                                    className="h-6 w-6 p-0 hover:text-emerald-400"
                                                                    title="Copier le MP Discord"
                                                                    onClick={() => handleCopyMP(provider.metamobName, monster.name)}
                                                                >
                                                                    {copiedUser === provider.metamobName ? (
                                                                        <Check className="h-3.5 w-3.5 text-emerald-500" />
                                                                    ) : (
                                                                        <Copy className="h-3.5 w-3.5" />
                                                                    )}
                                                                </Button>
                                                            </div>
                                                        </div>
                                                    ))}
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </TabsContent>

                            <TabsContent value="members" className="mt-4 focus-visible:outline-none flex-1 overflow-hidden flex flex-col min-h-0">
                                <div className="flex-1 overflow-y-auto px-6 pb-6 min-h-0">
                                    <div className="space-y-4">
                                        {partners
                                            .map(partner => ({
                                                ...partner,
                                                monstersTheyHave: partner.monstersTheyHave.filter(m => 
                                                    !monsterSearch.trim() || m.name.toLowerCase().includes(monsterSearch.toLowerCase().trim())
                                                )
                                            }))
                                            .filter(partner => partner.monstersTheyHave.length > 0)
                                            .map((partner) => (
                                                <div
                                                    key={partner.username}
                                                    className="bg-zinc-900/40 border border-white/5 rounded-xl p-4"
                                                >
                                                    <div className="flex items-center justify-between mb-4">
                                                        <div className="flex items-center gap-3">
                                                            <Link href={`/dashboard/${guildId}/members/${partner.profileId}`} target="_blank" rel="noopener noreferrer">
                                                                <Avatar className="h-10 w-10 border border-white/10 cursor-pointer hover:border-amber-500/50 transition-colors">
                                                                    <AvatarImage src={partner.discordAvatar} />
                                                                    <AvatarFallback className="bg-emerald-900/50 text-emerald-200 font-bold">
                                                                        {partner.characterName[0].toUpperCase()}
                                                                    </AvatarFallback>
                                                                </Avatar>
                                                            </Link>
                                                            <div>
                                                                <Link
                                                                    href={`/dashboard/${guildId}/members/${partner.profileId}`}
                                                                    target="_blank"
                                                                    rel="noopener noreferrer"
                                                                    className="font-bold text-sm text-zinc-100 hover:text-amber-400 hover:underline cursor-pointer transition-colors"
                                                                >
                                                                    {partner.characterName}
                                                                </Link>
                                                                <div className="flex items-center gap-2">
                                                                    <p className="text-xs text-zinc-500">
                                                                        propose {partner.monstersTheyHave.length} monstres
                                                                    </p>
                                                                    <span className="text-[10px] bg-zinc-800 text-zinc-400 px-1.5 rounded font-semibold">
                                                                        {partner.username}
                                                                    </span>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </div>

                                                    <div className="grid grid-cols-1 xs:grid-cols-2 sm:grid-cols-3 gap-2">
                                                        {partner.monstersTheyHave.map((monster) => (
                                                            <div
                                                                key={monster.id}
                                                                className={cn(
                                                                    "flex items-center justify-between text-xs p-2 rounded-lg border group cursor-pointer transition-all duration-200",
                                                                    monster.coversNeed
                                                                        ? "bg-emerald-500/10 border-emerald-500/30 text-emerald-300 shadow-md shadow-emerald-950/20 hover:border-emerald-500/50"
                                                                        : "bg-zinc-900/30 border-zinc-800/80 text-zinc-500 opacity-60 hover:opacity-100 hover:border-zinc-700"
                                                                )}
                                                                onClick={() => handleCopyMP(partner.characterName, monster.name)}
                                                            >
                                                                <div className="flex items-center gap-2 truncate flex-1 min-w-0">
                                                                    {monster.imageUrl && (
                                                                        <img
                                                                            src={monster.imageUrl}
                                                                            alt={monster.name}
                                                                            className="w-6 h-6 object-contain shrink-0"
                                                                        />
                                                                    )}
                                                                    <span className={cn("truncate transition-colors", monster.coversNeed ? "text-emerald-300 font-bold" : "text-zinc-500")}>
                                                                        {monster.name}
                                                                    </span>
                                                                    {monster.coversNeed && (
                                                                        <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse shrink-0 ml-auto" />
                                                                    )}
                                                                </div>
                                                                <div className="flex gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity ml-2 shrink-0">
                                                                    <Button
                                                                        variant="ghost"
                                                                        size="sm"
                                                                        className="h-6 w-6 p-0 hover:text-emerald-400"
                                                                        title="Envoyer une demande d'échange SigilOS"
                                                                        onClick={(e) => {
                                                                            e.stopPropagation();
                                                                            setTradeRequest({
                                                                                targetProfileId: partner.profileId,
                                                                                monsterId: monster.id,
                                                                                targetName: partner.characterName,
                                                                                monsterName: monster.name,
                                                                                monsterImage: monster.imageUrl,
                                                                            });
                                                                        }}
                                                                    >
                                                                        <Handshake className="h-3.5 w-3.5 text-zinc-400 hover:text-emerald-400" />
                                                                    </Button>
                                                                    <Button
                                                                        variant="ghost"
                                                                        size="sm"
                                                                        className="h-6 w-6 p-0 hover:text-emerald-400"
                                                                        title="Copier le MP Discord"
                                                                        onClick={(e) => {
                                                                            e.stopPropagation();
                                                                            handleCopyMP(partner.characterName, monster.name);
                                                                        }}
                                                                    >
                                                                        {copiedUser === partner.characterName ? (
                                                                            <Check className="h-3.5 w-3.5 text-emerald-500" />
                                                                        ) : (
                                                                            <Copy className="h-3.5 w-3.5 text-zinc-400 hover:text-emerald-400" />
                                                                        )}
                                                                    </Button>
                                                                </div>
                                                            </div>
                                                        ))}
                                                    </div>
                                                </div>
                                            ))}
                                    </div>
                                </div>
                            </TabsContent>
                        </Tabs>
                    )}
                </div>
            </DialogContent>

            {/* Sub-Dialog for Trade Message */}
            {
                tradeRequest && (
                    <Dialog open={!!tradeRequest} onOpenChange={(open) => !open && setTradeRequest(null)}>
                        <DialogContent className="bg-zinc-950 border-white/10 sm:max-w-md">
                            <DialogHeader>
                                <DialogTitle className="flex items-center gap-2">
                                    <Handshake className="h-5 w-5 text-emerald-500" />
                                    Demander un échange
                                </DialogTitle>
                                <DialogDescription>
                                    Proposer un échange à <strong className="text-emerald-400">{tradeRequest.targetName}</strong> pour <strong className="text-emerald-400">{tradeRequest.monsterName}</strong>.
                                </DialogDescription>
                            </DialogHeader>

                            {!hasOcreChannel && (
                                <div className="mt-2 px-3 py-2 bg-amber-500/10 border border-amber-500/20 rounded-lg flex items-start gap-2.5">
                                    <Bell className="w-4 h-4 text-amber-500 shrink-0 mt-0.5" />
                                    <div className="text-[10px] text-amber-200/80 leading-relaxed font-medium">
                                        <span className="text-amber-500 font-bold block mb-0.5">Configuration Discord absente</span>
                                        Demandez à un officier de configurer le salon Ocre pour activer les notifications Discord.
                                    </div>
                                </div>
                            )}

                            <div className="space-y-4 py-2">
                                <Textarea
                                    placeholder="Message optionnel (ex: Dispo ce soir 20h zaap astrub ? J'ai un Piou Vert en échange)"
                                    value={tradeMessage}
                                    onChange={(e) => setTradeMessage(e.target.value)}
                                    className="bg-black/50 border-white/10 resize-none h-24 text-sm"
                                    maxLength={500}
                                />
                                <div className="flex flex-row items-center justify-between rounded-lg border border-white/5 bg-black/40 p-3">
                                    <div className="space-y-0.5">
                                        <Label className="text-sm font-medium flex items-center gap-2 text-zinc-300">
                                            <Bell className="h-4 w-4 text-emerald-400" />
                                            Mentionner sur Discord
                                        </Label>
                                        <p className="text-xs text-zinc-500">
                                            {hasOcreChannel
                                                ? "Envoie l'annonce sur le serveur."
                                                : "Configuration manquante. Demandez à un officier de configurer le salon Ocre."}
                                        </p>
                                        {hasOcreChannel && sendDiscordPing && (
                                            <div className="flex items-center gap-1 mt-2 animate-in fade-in">
                                                <span className="text-[10px] text-emerald-400/90 font-bold uppercase tracking-widest">
                                                    Sera posté dans #{targetChannelName}
                                                </span>
                                            </div>
                                        )}
                                    </div>
                                    <Switch
                                        checked={sendDiscordPing}
                                        onCheckedChange={setSendDiscordPing}
                                        disabled={!hasOcreChannel}
                                    />
                                </div>
                            </div>
                            <DialogFooter>
                                <Button variant="ghost" onClick={() => setTradeRequest(null)} disabled={isSubmittingTrade}>
                                    Annuler
                                </Button>
                                <Button onClick={submitTradeRequest} disabled={isSubmittingTrade} className="bg-emerald-600 hover:bg-emerald-500 text-white">
                                    {isSubmittingTrade ? <Loader2 className="animate-spin h-4 w-4 mr-2" /> : null}
                                    Envoyer la demande
                                </Button>
                            </DialogFooter>
                        </DialogContent>
                    </Dialog>
                )
            }
        </Dialog >
    );
}

"use client";

import { useState, useEffect } from "react";
import { useDebounce } from "@/hooks/use-debounce";

// =============================================================================
// OCRE FILTER BAR - Modern, readable filters with premium glassmorphism
// =============================================================================

import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
    Search,
    X,
    Swords,
    Skull,
    Crown,
    Footprints,
    Sparkles,
    ArrowUpDown,
    ChevronDown,
    Check,
} from "lucide-react";
import { OcreExchangeModal } from "./ocre-exchange-modal";
import { cn } from "@/lib/utils";

// =============================================================================
// TYPES
// =============================================================================

export type MonsterType = "all" | "boss" | "archimonstre";
export type SortOption = "name-asc" | "name-desc" | "step-asc" | "step-desc";

export interface OcreFilters {
    searchQuery: string;
    selectedType: MonsterType;
    selectedStep: string;
    selectedZone: string;
    minQuantity: number;
    sortBy: SortOption;
}

interface OcreFilterBarProps {
    filters: OcreFilters;
    onFiltersChange: (filters: OcreFilters) => void;
    steps: number[];
    zones: string[];
    guildId: string;
    showMarketplace?: boolean;
    hasOcreChannel?: boolean;
    selectionMode?: boolean;
    onSelectionModeToggle?: () => void;
}

// =============================================================================
// CONFIG
// =============================================================================

const MONSTER_TYPES: Array<{ id: MonsterType; label: string; icon: typeof Swords; shortLabel: string }> = [
    { id: "all", label: "Tous types", shortLabel: "Tous", icon: Swords },
    { id: "boss", label: "Boss", shortLabel: "Boss", icon: Skull },
    { id: "archimonstre", label: "Archimonstres", shortLabel: "Archis", icon: Crown },
];

const SORT_OPTIONS: Array<{ id: SortOption; label: string }> = [
    { id: "step-asc", label: "Étape croissante" },
    { id: "step-desc", label: "Étape décroissante" },
    { id: "name-asc", label: "Nom A → Z" },
    { id: "name-desc", label: "Nom Z → A" },
];

const QUANTITY_OPTIONS: Array<{ value: number; label: string }> = [
    { value: 0, label: "Toute quantité" },
    { value: 1, label: "1+ (Possédés)" },
    { value: 2, label: "2+ (Doublons)" },
    { value: 3, label: "3+ (Triples)" },
    { value: 4, label: "4+ (Quadruples)" },
];

// =============================================================================
// COMPONENT
// =============================================================================

export function OcreFilterBar({
    filters,
    onFiltersChange,
    steps,
    zones,
    guildId,
    showMarketplace = true,
    hasOcreChannel,
    selectionMode,
    onSelectionModeToggle,
}: OcreFilterBarProps) {
    const updateFilter = <K extends keyof OcreFilters>(key: K, value: OcreFilters[K]) => {
        onFiltersChange({ ...filters, [key]: value });
    };

    const hasActiveFilters =
        filters.searchQuery.trim() !== "" ||
        filters.selectedType !== "all" ||
        filters.selectedStep !== "all" ||
        filters.selectedZone !== "all" ||
        filters.minQuantity > 0 ||
        filters.sortBy !== "step-asc";

    const [localSearch, setLocalSearch] = useState(filters.searchQuery);
    const debouncedSearch = useDebounce(localSearch, 300);

    useEffect(() => {
        if (debouncedSearch !== filters.searchQuery) {
            updateFilter("searchQuery", debouncedSearch);
        }
    }, [debouncedSearch]);

    // Sync local search when filters are reset
    useEffect(() => {
        setLocalSearch(filters.searchQuery);
    }, [filters.searchQuery]);

    const clearFilters = () => {
        onFiltersChange({
            searchQuery: "",
            selectedType: "all",
            selectedStep: "all",
            selectedZone: "all",
            minQuantity: 0,
            sortBy: "step-asc",
        });
    };

    const currentSort = SORT_OPTIONS.find(s => s.id === filters.sortBy);
    const currentQty = QUANTITY_OPTIONS.find(q => q.value === filters.minQuantity);

    return (
        <div className="bg-[#12181a]/80 backdrop-blur-xl border border-white/[0.06] rounded-3xl p-5 md:p-6 space-y-5 shadow-[0_12px_40px_rgba(0,0,0,0.3)]">
            {/* Search & Primary Actions Row */}
            <div className="flex flex-col md:flex-row items-stretch md:items-center gap-4">
                {/* Search Input */}
                <div className="relative flex-1 group">
                    <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-zinc-500 group-focus-within:text-amber-500 transition-colors duration-200" />
                    <Input
                        placeholder="Rechercher un monstre..."
                        value={localSearch}
                        onChange={(e) => setLocalSearch(e.target.value)}
                        className="pl-10 h-11 text-sm bg-[#161e20]/70 focus:bg-[#1a2426]/90 border border-white/[0.07] focus:border-amber-500/50 focus:ring-4 focus:ring-amber-500/10 rounded-2xl transition-all duration-300 placeholder:text-zinc-600 text-zinc-200 shadow-inner"
                    />
                    {localSearch && (
                        <button
                            onClick={() => setLocalSearch("")}
                            className="absolute right-3.5 top-1/2 -translate-y-1/2 text-zinc-500 hover:text-zinc-300 transition-colors"
                        >
                            <X className="h-3.5 w-3.5" />
                        </button>
                    )}
                </div>

                {/* Action Buttons */}
                <div className="flex flex-wrap items-center gap-3 shrink-0">
                    {hasActiveFilters && (
                        <Button
                            variant="ghost"
                            size="sm"
                            onClick={clearFilters}
                            className="h-11 px-4 text-xs text-zinc-400 hover:text-white font-bold rounded-2xl hover:bg-white/5 transition-all duration-200 border border-transparent hover:border-white/5"
                        >
                            Réinitialiser
                        </Button>
                    )}

                    <Button
                        variant="outline"
                        size="sm"
                        onClick={onSelectionModeToggle}
                        className={cn(
                            "h-11 px-5 rounded-2xl text-xs font-bold gap-2 transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] border",
                            selectionMode
                                ? "bg-amber-500 text-white border-amber-500 shadow-lg shadow-amber-500/25"
                                : "bg-[#161e20]/60 text-zinc-300 border-white/[0.07] hover:bg-[#202a2c] hover:border-white/10"
                        )}
                    >
                        <Check className="h-4 w-4" />
                        <span>{selectionMode ? "Quitter" : "Sélectionner"}</span>
                    </Button>

                    {showMarketplace && (
                        <OcreExchangeModal
                            guildId={guildId}
                            hasOcreChannel={hasOcreChannel}
                            trigger={
                                <Button
                                    size="sm"
                                    className="h-11 px-5 bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 text-white border-0 shadow-lg shadow-emerald-950/50 rounded-2xl font-bold gap-2 transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] text-xs"
                                >
                                    <Sparkles className="h-4 w-4 fill-white/25" />
                                    <span>Échanges</span>
                                </Button>
                            }
                        />
                    )}
                </div>
            </div>

            {/* Divider */}
            <div className="border-t border-white/[0.04]" />

            {/* Filter Dropdowns Row */}
            <div className="flex flex-wrap items-center gap-3">
                {/* Type Dropdown */}
                <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                        <Button
                            variant="outline"
                            className={cn(
                                "h-10 px-4 text-xs font-semibold rounded-2xl gap-2 border transition-all duration-200 hover:scale-[1.02] active:scale-[0.98]",
                                filters.selectedType !== "all"
                                    ? "border-amber-500/40 bg-amber-500/10 text-amber-400 shadow-[0_0_16px_rgba(245,158,11,0.12)]"
                                    : "border-white/[0.07] bg-[#161e20]/60 text-zinc-300 hover:bg-[#202a2d] hover:border-white/10"
                            )}
                        >
                            {filters.selectedType === "all" ? (
                                <><Swords className="h-3.5 w-3.5" />Tous types</>
                            ) : filters.selectedType === "boss" ? (
                                <><Skull className="h-3.5 w-3.5 text-red-400" />Boss</>
                            ) : (
                                <><Crown className="h-3.5 w-3.5 text-amber-500" />Archimonstres</>
                            )}
                            <ChevronDown className="h-3 w-3 opacity-60" />
                        </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="start" className="bg-[#13191b] border border-white/10 shadow-[0_20px_50px_rgba(0,0,0,0.5)] rounded-2xl p-1.5 z-[100] min-w-[160px]">
                        {MONSTER_TYPES.map((type) => {
                            const Icon = type.icon;
                            return (
                                <DropdownMenuItem
                                    key={type.id}
                                    onClick={() => updateFilter("selectedType", type.id)}
                                    className="text-xs py-2.5 px-3.5 gap-2.5 rounded-xl cursor-pointer hover:bg-white/5 text-zinc-300 hover:text-white transition-colors"
                                >
                                    <Icon className="h-3.5 w-3.5" />
                                    {type.label}
                                    {filters.selectedType === type.id && <Check className="h-3 w-3 ml-auto text-amber-500" />}
                                </DropdownMenuItem>
                            );
                        })}
                    </DropdownMenuContent>
                </DropdownMenu>

                {/* Step Dropdown */}
                <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                        <Button
                            variant="outline"
                            className={cn(
                                "h-10 px-4 text-xs font-semibold rounded-2xl gap-2 border transition-all duration-200 hover:scale-[1.02] active:scale-[0.98]",
                                filters.selectedStep !== "all"
                                    ? "border-amber-500/40 bg-amber-500/10 text-amber-400 shadow-[0_0_16px_rgba(245,158,11,0.12)]"
                                    : "border-white/[0.07] bg-[#161e20]/60 text-zinc-300 hover:bg-[#202a2d] hover:border-white/10"
                            )}
                        >
                            <Footprints className="h-3.5 w-3.5" />
                            {filters.selectedStep === "all" ? "Toutes étapes" : `Étape ${filters.selectedStep}`}
                            <ChevronDown className="h-3 w-3 opacity-60" />
                        </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="start" className="max-h-[260px] overflow-y-auto bg-[#13191b] border border-white/10 shadow-[0_20px_50px_rgba(0,0,0,0.5)] rounded-2xl p-1.5 z-[100] min-w-[160px]">
                        <DropdownMenuItem
                            onClick={() => updateFilter("selectedStep", "all")}
                            className="text-xs py-2.5 px-3.5 rounded-xl cursor-pointer hover:bg-white/5 text-zinc-300 hover:text-white transition-colors"
                        >
                            Toutes étapes
                            {filters.selectedStep === "all" && <Check className="h-3 w-3 ml-auto text-amber-500" />}
                        </DropdownMenuItem>
                        {steps.map((step) => (
                            <DropdownMenuItem
                                key={step}
                                onClick={() => updateFilter("selectedStep", step.toString())}
                                className="text-xs py-2.5 px-3.5 rounded-xl cursor-pointer hover:bg-white/5 text-zinc-300 hover:text-white transition-colors"
                            >
                                Étape {step}
                                {filters.selectedStep === step.toString() && <Check className="h-3 w-3 ml-auto text-amber-500" />}
                            </DropdownMenuItem>
                        ))}
                    </DropdownMenuContent>
                </DropdownMenu>

                {/* Sort Dropdown */}
                <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                        <Button
                            variant="outline"
                            className={cn(
                                "h-10 px-4 text-xs font-semibold rounded-2xl gap-2 border transition-all duration-200 hover:scale-[1.02] active:scale-[0.98]",
                                filters.sortBy !== "step-asc"
                                    ? "border-blue-500/40 bg-blue-500/10 text-blue-400 shadow-[0_0_16px_rgba(59,130,246,0.12)]"
                                    : "border-white/[0.07] bg-[#161e20]/60 text-zinc-300 hover:bg-[#202a2d] hover:border-white/10"
                            )}
                        >
                            <ArrowUpDown className="h-3.5 w-3.5" />
                            {currentSort?.label || "Tri"}
                            <ChevronDown className="h-3 w-3 opacity-60" />
                        </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="start" className="bg-[#13191b] border border-white/10 shadow-[0_20px_50px_rgba(0,0,0,0.5)] rounded-2xl p-1.5 z-[100] min-w-[185px]">
                        {SORT_OPTIONS.map((sort) => (
                            <DropdownMenuItem
                                key={sort.id}
                                onClick={() => updateFilter("sortBy", sort.id)}
                                className="text-xs py-2.5 px-3.5 rounded-xl cursor-pointer hover:bg-white/5 text-zinc-300 hover:text-white transition-colors"
                            >
                                {sort.label}
                                {filters.sortBy === sort.id && <Check className="h-3 w-3 ml-auto text-blue-400" />}
                            </DropdownMenuItem>
                        ))}
                    </DropdownMenuContent>
                </DropdownMenu>

                {/* Zone Dropdown (only if zones exist) */}
                {zones.length > 0 && (
                    <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                            <Button
                                variant="outline"
                                className={cn(
                                    "h-10 px-4 text-xs font-semibold rounded-2xl gap-2 border max-w-[180px] transition-all duration-200 hover:scale-[1.02] active:scale-[0.98]",
                                    filters.selectedZone !== "all"
                                        ? "border-emerald-500/40 bg-emerald-500/10 text-emerald-400 shadow-[0_0_16px_rgba(16,185,129,0.12)]"
                                        : "border-white/[0.07] bg-[#161e20]/60 text-zinc-300 hover:bg-[#202a2d] hover:border-white/10"
                                )}
                            >
                                <span className="truncate">
                                    {filters.selectedZone === "all" ? "Toutes zones" : filters.selectedZone}
                                </span>
                                <ChevronDown className="h-3 w-3 opacity-60 shrink-0" />
                            </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="start" className="max-h-[260px] overflow-y-auto bg-[#13191b] border border-white/10 shadow-[0_20px_50px_rgba(0,0,0,0.5)] rounded-2xl p-1.5 z-[100] min-w-[200px]">
                            <DropdownMenuItem
                                onClick={() => updateFilter("selectedZone", "all")}
                                className="text-xs py-2.5 px-3.5 rounded-xl cursor-pointer hover:bg-white/5 text-zinc-300 hover:text-white transition-colors"
                            >
                                Toutes zones
                                {filters.selectedZone === "all" && <Check className="h-3 w-3 ml-auto text-emerald-500" />}
                            </DropdownMenuItem>
                            {zones.map((zone) => (
                                <DropdownMenuItem
                                    key={zone}
                                    onClick={() => updateFilter("selectedZone", zone)}
                                    className="text-xs py-2.5 px-3.5 rounded-xl cursor-pointer hover:bg-white/5 text-zinc-300 hover:text-white transition-colors"
                                >
                                    <span className="truncate flex-1">{zone}</span>
                                    {filters.selectedZone === zone && <Check className="h-3 w-3 ml-auto text-emerald-500 shrink-0" />}
                                </DropdownMenuItem>
                            ))}
                        </DropdownMenuContent>
                    </DropdownMenu>
                )}

                {/* Quantity Dropdown */}
                <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                        <Button
                            variant="outline"
                            className={cn(
                                "h-10 px-4 text-xs font-semibold rounded-2xl gap-2 border transition-all duration-200 hover:scale-[1.02] active:scale-[0.98]",
                                filters.minQuantity > 0
                                    ? "border-purple-500/40 bg-purple-500/10 text-purple-400 shadow-[0_0_16px_rgba(168,85,247,0.12)]"
                                    : "border-white/[0.07] bg-[#161e20]/60 text-zinc-300 hover:bg-[#202a2d] hover:border-white/10"
                            )}
                        >
                            <Crown className="h-3.5 w-3.5" />
                            {currentQty?.label || "Quantité"}
                            <ChevronDown className="h-3 w-3 opacity-60" />
                        </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="start" className="bg-[#13191b] border border-white/10 shadow-[0_20px_50px_rgba(0,0,0,0.5)] rounded-2xl p-1.5 z-[100] min-w-[180px]">
                        {QUANTITY_OPTIONS.map((q) => (
                            <DropdownMenuItem
                                key={q.value}
                                onClick={() => updateFilter("minQuantity", q.value)}
                                className="text-xs py-2.5 px-3.5 rounded-xl cursor-pointer hover:bg-white/5 text-zinc-300 hover:text-white transition-colors"
                            >
                                {q.label}
                                {filters.minQuantity === q.value && <Check className="h-3 w-3 ml-auto text-purple-400" />}
                            </DropdownMenuItem>
                        ))}
                    </DropdownMenuContent>
                </DropdownMenu>

                {/* Active filters summary badge */}
                {hasActiveFilters && (
                    <Badge className="h-6 px-2.5 text-[10px] font-black bg-amber-500/10 text-amber-400 border border-amber-500/20 rounded-xl">
                        Filtres actifs
                    </Badge>
                )}
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useTransition } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { 
    Search, 
    Users, 
    CheckCircle2, 
    XCircle, 
    AlertCircle, 
    Clock, 
    Shield, 
    ArrowRight, 
    RefreshCw,
    ExternalLink
} from "lucide-react";
import { getGuildMetamobDirectory, type MetamobDirectoryMember } from "@/server/actions/ocre-actions";
import { formatDistanceToNow } from "date-fns";
import { fr } from "date-fns/locale";
import { toast } from "sonner";
import Image from "next/image";

interface OcreGuildDirectoryProps {
    guildId: string;
}

export function OcreGuildDirectory({ guildId }: OcreGuildDirectoryProps) {
    const [members, setMembers] = useState<MetamobDirectoryMember[]>([]);
    const [filteredMembers, setFilteredMembers] = useState<MetamobDirectoryMember[]>([]);
    const [searchQuery, setSearchQuery] = useState("");
    const [statusFilter, setStatusFilter] = useState<"all" | "linked" | "unlinked">("all");
    const [loading, setLoading] = useState(true);
    const [isPending, startTransition] = useTransition();

    const fetchDirectory = async () => {
        setLoading(true);
        const res = await getGuildMetamobDirectory(guildId);
        if (res.success && res.data) {
            setMembers(res.data);
            setFilteredMembers(res.data);
        } else {
            toast.error(res.error || "Impossible de charger l'annuaire");
        }
        setLoading(false);
    };

    useEffect(() => {
        fetchDirectory();
    }, [guildId]);

    // Filter logic
    useEffect(() => {
        let result = members;

        // Search query
        if (searchQuery.trim()) {
            const query = searchQuery.toLowerCase().trim();
            result = result.filter(m => 
                (m.user.name && m.user.name.toLowerCase().includes(query)) ||
                (m.pseudoDofus && m.pseudoDofus.toLowerCase().includes(query)) ||
                (m.metamobPseudo && m.metamobPseudo.toLowerCase().includes(query))
            );
        }

        // Status filter
        if (statusFilter === "linked") {
            result = result.filter(m => m.metamobVerified && m.metamobPseudo);
        } else if (statusFilter === "unlinked") {
            result = result.filter(m => !m.metamobVerified || !m.metamobPseudo);
        }

        setFilteredMembers(result);
    }, [searchQuery, statusFilter, members]);

    const getProgressColor = (percent?: number) => {
        if (!percent) return "bg-zinc-600";
        if (percent === 100) return "bg-emerald-500";
        if (percent > 70) return "bg-emerald-400";
        if (percent > 30) return "bg-amber-400";
        return "bg-red-400";
    };

    return (
        <div className="space-y-6">
            {/* Header controls */}
            <div className="flex flex-col md:flex-row gap-4 justify-between items-stretch md:items-center">
                {/* Search */}
                <div className="relative flex-1">
                    <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                    <Input
                        placeholder="Rechercher un membre, pseudo Dofus ou Metamob..."
                        className="pl-10 h-11 bg-zinc-900/50 border-white/5 rounded-2xl text-xs placeholder:text-zinc-500 focus-visible:ring-amber-500/30 transition-all"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>

                {/* Filter buttons */}
                <div className="flex items-center gap-1.5 p-1 bg-zinc-900/50 border border-white/5 rounded-2xl shrink-0">
                    <Button
                        size="sm"
                        variant="ghost"
                        className={`h-9 px-4 rounded-xl text-xs font-bold transition-all ${
                            statusFilter === "all"
                                ? "bg-zinc-800 text-amber-500 border border-amber-500/10 shadow-lg"
                                : "text-muted-foreground hover:text-foreground"
                        }`}
                        onClick={() => setStatusFilter("all")}
                    >
                        Tous ({members.length})
                    </Button>
                    <Button
                        size="sm"
                        variant="ghost"
                        className={`h-9 px-4 rounded-xl text-xs font-bold transition-all ${
                            statusFilter === "linked"
                                ? "bg-zinc-800 text-emerald-400 border border-emerald-500/10 shadow-lg"
                                : "text-muted-foreground hover:text-foreground"
                        }`}
                        onClick={() => setStatusFilter("linked")}
                    >
                        Liés ({members.filter(m => m.metamobVerified).length})
                    </Button>
                    <Button
                        size="sm"
                        variant="ghost"
                        className={`h-9 px-4 rounded-xl text-xs font-bold transition-all ${
                            statusFilter === "unlinked"
                                ? "bg-zinc-800 text-red-400 border border-red-500/10 shadow-lg"
                                : "text-muted-foreground hover:text-foreground"
                        }`}
                        onClick={() => statusFilter !== "unlinked" ? setStatusFilter("unlinked") : setStatusFilter("all")}
                    >
                        Non liés ({members.filter(m => !m.metamobVerified).length})
                    </Button>

                    <Button
                        size="icon"
                        variant="ghost"
                        className="h-9 w-9 rounded-xl hover:bg-zinc-800 text-muted-foreground hover:text-foreground"
                        onClick={fetchDirectory}
                        disabled={loading}
                    >
                        <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin text-amber-500" : ""}`} />
                    </Button>
                </div>
            </div>

            {/* Grid of members */}
            {loading ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {[1, 2, 3, 4, 5, 6].map(i => (
                        <Card key={i} className="bg-card/20 border-white/5 h-44 animate-pulse">
                            <CardContent className="p-5 flex gap-4">
                                <div className="h-12 w-12 rounded-2xl bg-zinc-800" />
                                <div className="flex-1 space-y-2 mt-1">
                                    <div className="h-4 bg-zinc-800 rounded w-2/3" />
                                    <div className="h-3 bg-zinc-800 rounded w-1/2" />
                                </div>
                            </CardContent>
                        </Card>
                    ))}
                </div>
            ) : filteredMembers.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-16 text-center bg-zinc-900/20 rounded-3xl border border-dashed border-white/5">
                    <Users className="h-16 w-16 text-muted-foreground/10 mb-4" />
                    <h3 className="text-sm font-bold uppercase tracking-wider text-muted-foreground/60">Aucun membre trouvé</h3>
                    <p className="text-xs text-muted-foreground/40 mt-1 max-w-xs leading-relaxed">
                        Ajustez vos filtres ou vérifiez l&apos;orthographe de votre recherche.
                    </p>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {filteredMembers.map((member) => {
                        const isLinked = member.metamobVerified && member.metamobPseudo;
                        const hasSnapshot = member.progressPercent !== undefined;

                        return (
                            <Card 
                                key={member.id} 
                                className={`relative group overflow-hidden bg-card/20 backdrop-blur-md border border-white/5 hover:border-white/10 hover:bg-card/30 transition-all duration-300 ${
                                    isLinked ? "hover:shadow-[0_0_30px_rgba(245,158,11,0.03)]" : "opacity-80 hover:opacity-100"
                                }`}
                            >
                                <CardContent className="p-5 flex flex-col justify-between h-full min-h-[170px] gap-4">
                                    <div className="flex gap-4 items-start">
                                        {/* Avatar */}
                                        <div className="relative h-12 w-12 rounded-2xl overflow-hidden border border-white/5 shrink-0 bg-zinc-950/50 flex items-center justify-center group-hover:scale-105 transition-transform">
                                            {member.user.image ? (
                                                <Image 
                                                    src={member.user.image} 
                                                    alt={member.user.name || "Avatar"} 
                                                    fill 
                                                    sizes="48px"
                                                    className="object-cover" 
                                                />
                                            ) : (
                                                <Users className="h-5 w-5 text-zinc-600" />
                                            )}
                                        </div>

                                        {/* Identity */}
                                        <div className="flex-1 min-w-0 space-y-1">
                                            <div className="flex items-center gap-1.5 justify-between">
                                                <span className="font-bold text-sm text-foreground truncate block leading-tight">
                                                    {member.user.name || "Dofusien"}
                                                </span>
                                                {isLinked ? (
                                                    <Badge className="bg-emerald-500/10 text-emerald-400 border-none px-2 py-0.5 text-[9px] font-black tracking-wider uppercase shrink-0">
                                                        Lié
                                                    </Badge>
                                                ) : (
                                                    <Badge className="bg-red-500/10 text-red-400 border-none px-2 py-0.5 text-[9px] font-black tracking-wider uppercase shrink-0">
                                                        Non lié
                                                    </Badge>
                                                )}
                                            </div>

                                            <div className="flex flex-col gap-0.5 text-[11px] text-muted-foreground">
                                                {member.pseudoDofus && (
                                                    <span className="truncate">
                                                        Dofus : <span className="text-zinc-300 font-semibold">{member.pseudoDofus}</span>
                                                    </span>
                                                )}
                                                {isLinked && member.metamobPseudo && (
                                                    <span className="truncate flex items-center gap-1">
                                                        Metamob : 
                                                        <a 
                                                            href={`https://www.metamob.fr/profile/${encodeURIComponent(member.metamobPseudo)}`} 
                                                            target="_blank" 
                                                            rel="noopener noreferrer"
                                                            className="text-amber-500 hover:text-amber-400 font-bold hover:underline transition-colors flex items-center gap-0.5"
                                                        >
                                                            {member.metamobPseudo}
                                                            <ExternalLink className="h-2.5 w-2.5 inline" />
                                                        </a>
                                                    </span>
                                                )}
                                            </div>
                                        </div>
                                    </div>

                                    {/* Stats & Progress */}
                                    {isLinked ? (
                                        <div className="space-y-2 pt-2 border-t border-white/5">
                                            {hasSnapshot ? (
                                                <>
                                                    <div className="flex items-center justify-between text-[11px]">
                                                        <span className="text-muted-foreground">
                                                            {member.serverName || "Serveur"}
                                                            <span className="opacity-30 mx-1.5">•</span>
                                                            Étape {member.currentStep ?? 0}
                                                        </span>
                                                        <span className="font-extrabold text-foreground">
                                                            {member.progressPercent}%
                                                        </span>
                                                    </div>
                                                    <div className="relative">
                                                        <Progress 
                                                            value={member.progressPercent ?? 0} 
                                                            className="h-1.5" 
                                                            indicatorClassName={getProgressColor(member.progressPercent)}
                                                        />
                                                    </div>
                                                    {member.metamobLastSync && (
                                                        <div className="flex items-center gap-1 text-[9px] text-zinc-500 italic mt-1 justify-end">
                                                            <Clock className="h-2.5 w-2.5" />
                                                            Sync {formatDistanceToNow(new Date(member.metamobLastSync), { addSuffix: true, locale: fr })}
                                                        </div>
                                                    )}
                                                </>
                                            ) : (
                                                <div className="flex items-center gap-2 p-2.5 bg-amber-500/5 border border-amber-500/10 rounded-xl">
                                                    <AlertCircle className="h-4 w-4 text-amber-500 shrink-0" />
                                                    <span className="text-[10px] text-amber-400 font-semibold leading-normal">
                                                        Compte lié mais aucune synchronisation effectuée.
                                                    </span>
                                                </div>
                                            )}
                                        </div>
                                    ) : (
                                        <div className="flex items-center justify-center p-4 bg-zinc-950/40 rounded-xl border border-white/5 text-center mt-2">
                                            <span className="text-[10px] text-zinc-500 italic leading-normal">
                                                Ce membre n&apos;a pas configuré son compte Metamob. Les échanges automatiques ne sont pas disponibles.
                                            </span>
                                        </div>
                                    )}
                                </CardContent>

                                {/* Aesthetic border glow on hover */}
                                <div className="absolute inset-0 bg-gradient-to-r from-amber-500/0 via-amber-500/5 to-amber-500/0 opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none -z-10" />
                            </Card>
                        );
                    })}
                </div>
            )}
        </div>
    );
}

"use client";

import { useState } from "react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Settings2, Save, Loader2, Info, ArrowRightLeft, ShieldCheck } from "lucide-react";
import { toast } from "sonner";
import { updateOcreSettingsAction } from "@/server/actions/ocre-actions";
import type { OcreProgressData } from "@/server/actions/ocre-actions";

interface OcreSettingsModalProps {
    data: OcreProgressData;
    guildId: string;
    trigger?: React.ReactNode;
}

export function OcreSettingsModal({ data, guildId, trigger }: OcreSettingsModalProps) {
    const [open, setOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(false);

    // Form state
    const [settings, setSettings] = useState({
        parallel_quests: data.questInfo.parallelQuests || 1,
        trade_mode: data.questInfo.trade_mode ?? 1, // 0: Manual, 1: Automatic
        trade_offer_threshold: data.questInfo.trade_offer_threshold ?? 0,
        trade_want_threshold: data.questInfo.trade_want_threshold ?? 0,
        show_trades: data.questInfo.show_trades ?? true,
    });

    const handleSave = async () => {
        setIsLoading(true);
        try {
            const result = await updateOcreSettingsAction({
                guildId,
                settings: {
                    ...settings,
                    // Ensure numbers are numbers
                    parallel_quests: Number(settings.parallel_quests),
                    trade_offer_threshold: settings.trade_offer_threshold === null ? null : Number(settings.trade_offer_threshold),
                    trade_want_threshold: settings.trade_want_threshold === null ? null : Number(settings.trade_want_threshold),
                }
            });

            if (result.success) {
                toast.success("Paramètres mis à jour avec succès !");
                setOpen(false);
                // Force reload to update stats (especially if parallel_quests changed)
                window.location.reload();
            } else {
                toast.error(result.error || "Une erreur est survenue");
            }
        } catch (error) {
            toast.error("Erreur lors de la sauvegarde");
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <>
            {trigger ? (
                <div onClick={() => setOpen(true)}>{trigger}</div>
            ) : (
                <Button
                    variant="outline"
                    size="sm"
                    className="h-10 px-4 rounded-xl border-dashed border-border hover:border-amber-500/50 hover:bg-amber-500/5 transition-all group"
                    onClick={() => setOpen(true)}
                >
                    <Settings2 className="h-4 w-4 mr-2 text-muted-foreground group-hover:text-amber-500 transition-colors" />
                    <span className="text-xs font-semibold">Réglages Expert</span>
                </Button>
            )}

            <Dialog open={open} onOpenChange={setOpen}>
                <DialogContent className="max-w-lg overflow-hidden p-0 rounded-3xl border-border bg-zinc-950/98 backdrop-blur-2xl shadow-[0_0_80px_rgba(0,0,0,0.8)] border-white/10">
                    <div className="relative p-8 bg-gradient-to-br from-amber-500/10 via-transparent to-transparent border-b border-white/5">
                        <DialogHeader>
                            <div className="flex items-center gap-3 mb-2">
                                <div className="h-10 w-10 rounded-2xl bg-amber-500/10 flex items-center justify-center border border-amber-500/20">
                                    <Settings2 className="h-5 w-5 text-amber-500" />
                                </div>
                                <div>
                                    <DialogTitle className="text-xl font-bold">Réglages Metamob</DialogTitle>
                                    <DialogDescription className="text-xs">
                                        Configurez comment SigilOS et Metamob gèrent vos échanges.
                                    </DialogDescription>
                                </div>
                            </div>
                        </DialogHeader>
                    </div>

                    <div className="p-6 space-y-6 max-h-[60vh] overflow-y-auto no-scrollbar">
                        {/* Section: Base Info */}
                        <div className="space-y-4">
                            <h4 className="text-[10px] uppercase tracking-widest font-black text-muted-foreground/50 flex items-center gap-2">
                                <Info className="h-3 w-3" />
                                Configuration Générale
                            </h4>
                            
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <Label htmlFor="parallel_quests" className="text-xs font-bold">Quêtes en parallèle</Label>
                                    <Select 
                                        value={settings.parallel_quests.toString()} 
                                        onValueChange={(v) => setSettings(s => ({ ...s, parallel_quests: parseInt(v) }))}
                                    >
                                        <SelectTrigger id="parallel_quests" className="h-10 rounded-xl bg-background/50 border-border">
                                            <SelectValue placeholder="Nombre de quêtes" />
                                        </SelectTrigger>
                                        <SelectContent>
                                            {[1, 2, 3, 4, 5, 10].map(n => (
                                                <SelectItem key={n} value={n.toString()}>{n}</SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                    <p className="text-[10px] text-muted-foreground leading-tight">
                                        Nombre de Dofus Ocre que vous faites en même temps (détermine vos doublons).
                                    </p>
                                </div>

                                <div className="space-y-2">
                                    <Label htmlFor="trade_mode" className="text-xs font-bold">Mode d&apos;échange</Label>
                                    <Select 
                                        value={settings.trade_mode.toString()} 
                                        onValueChange={(v) => setSettings(s => ({ ...s, trade_mode: parseInt(v) }))}
                                    >
                                        <SelectTrigger id="trade_mode" className="h-10 rounded-xl bg-background/50 border-border">
                                            <SelectValue placeholder="Mode" />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="1">Automatique</SelectItem>
                                            <SelectItem value="0">Manuel</SelectItem>
                                        </SelectContent>
                                    </Select>
                                    <p className="text-[10px] text-muted-foreground leading-tight">
                                        <b>Auto</b> : Metamob calcule vos offres/recherches selon vos quantités.
                                    </p>
                                </div>
                            </div>
                        </div>

                        {/* Section: Thresholds */}
                        <div className="space-y-4">
                            <h4 className="text-[10px] uppercase tracking-widest font-black text-muted-foreground/50 flex items-center gap-2">
                                <ArrowRightLeft className="h-3 w-3" />
                                Seuils de calcul automatique
                            </h4>

                            <div className="p-4 rounded-2xl bg-zinc-900/50 border border-white/5 space-y-4">
                                <div className="flex items-center justify-between">
                                    <div className="space-y-0.5">
                                        <Label className="text-xs font-bold">Seuil d&apos;offre</Label>
                                        <p className="text-[10px] text-muted-foreground">Quantité à partir de laquelle vous proposez en échange.</p>
                                    </div>
                                    <Input 
                                        type="number" 
                                        className="w-20 h-9 rounded-lg text-center font-bold"
                                        value={settings.trade_offer_threshold ?? 0}
                                        onChange={(e) => setSettings(s => ({ ...s, trade_offer_threshold: parseInt(e.target.value) || 0 }))}
                                    />
                                </div>

                                <div className="flex items-center justify-between">
                                    <div className="space-y-0.5">
                                        <Label className="text-xs font-bold">Seuil de recherche</Label>
                                        <p className="text-[10px] text-muted-foreground">Quantité en dessous de laquelle vous recherchez le monstre.</p>
                                    </div>
                                    <Input 
                                        type="number" 
                                        className="w-20 h-9 rounded-lg text-center font-bold"
                                        value={settings.trade_want_threshold ?? 0}
                                        onChange={(e) => setSettings(s => ({ ...s, trade_want_threshold: parseInt(e.target.value) || 0 }))}
                                    />
                                </div>
                            </div>
                        </div>

                        {/* Section: Visibility */}
                        <div className="space-y-4">
                            <h4 className="text-[10px] uppercase tracking-widest font-black text-muted-foreground/50 flex items-center gap-2">
                                <ShieldCheck className="h-3 w-3" />
                                Visibilité & Vie Privée
                            </h4>

                            <div className="flex items-center justify-between p-4 rounded-2xl bg-zinc-900/50 border border-white/5">
                                <div className="space-y-0.5">
                                    <Label className="text-xs font-bold">Afficher mes échanges sur Metamob</Label>
                                    <p className="text-[10px] text-muted-foreground">Si désactivé, vous n&apos;apparaîtrez pas dans les recherches publiques.</p>
                                </div>
                                <Switch 
                                    checked={settings.show_trades}
                                    onCheckedChange={(v) => setSettings(s => ({ ...s, show_trades: v }))}
                                />
                            </div>
                        </div>
                    </div>

                    <div className="p-6 bg-zinc-900/80 border-t border-white/10 flex items-center justify-between gap-4">
                        <Button
                            variant="ghost"
                            size="sm"
                            className="rounded-xl text-xs text-muted-foreground hover:text-foreground"
                            onClick={() => setOpen(false)}
                            disabled={isLoading}
                        >
                            Annuler
                        </Button>
                        <Button
                            size="sm"
                            className="rounded-xl px-6 h-10 font-bold gap-2 bg-amber-500 hover:bg-amber-400 text-white shadow-lg shadow-amber-500/20 transition-all active:scale-95"
                            onClick={handleSave}
                            disabled={isLoading}
                        >
                            {isLoading ? (
                                <Loader2 className="h-4 w-4 animate-spin" />
                            ) : (
                                <Save className="h-4 w-4" />
                            )}
                            Sauvegarder
                        </Button>
                    </div>
                </DialogContent>
            </Dialog>
        </>
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { RefreshCw } from "lucide-react";
import { cn } from "@/lib/utils";
import { forceRefreshOcre } from "@/server/actions/ocre-actions";
import { toast } from "sonner";

interface OcreSyncButtonProps {
    guildId: string;
    lastSync?: Date | null;
}

export function OcreSyncButton({ guildId, lastSync }: OcreSyncButtonProps) {
    const [isRefreshing, setIsRefreshing] = useState(false);

    const handleRefresh = async () => {
        setIsRefreshing(true);
        try {
            const result = await forceRefreshOcre(guildId);
            if (result.success) {
                if (result.data?.questUpdated) {
                    toast.success("🎉 Nouvelle quête détectée et mise à jour !");
                } else {
                    toast.success("Synchronisation forcée réussie !");
                }
                // Small delay before reload for toast visibility
                setTimeout(() => window.location.reload(), 1000);
            } else {
                toast.error(result.error || "Erreur lors du rafraîchissement");
                setIsRefreshing(false);
            }
        } catch (error) {
            toast.error("Erreur serveur lors de la synchronisation");
            setIsRefreshing(false);
        }
    };

    return (
        <div className="flex items-center gap-4">
            {lastSync && (
                <div className="hidden md:flex flex-col items-end opacity-50 hover:opacity-100 transition-opacity">
                    <span className="text-[9px] font-black uppercase tracking-[0.2em] text-muted-foreground leading-none mb-1.5">Dernière MAJ</span>
                    <span className="text-[11px] font-bold text-white tabular-nums leading-none">
                        {new Date(lastSync).toLocaleString("fr-FR", {
                            day: "2-digit",
                            month: "2-digit",
                            hour: "2-digit",
                            minute: "2-digit"
                        })}
                    </span>
                </div>
            )}
            
            <Button
                onClick={handleRefresh}
                disabled={isRefreshing}
                variant="outline"
                className="h-12 px-6 border-white/5 bg-zinc-900/40 backdrop-blur-md rounded-xl font-bold flex items-center gap-2 hover:bg-zinc-800 transition-all hover:border-amber-500/30 shadow-lg group shrink-0"
            >
                <RefreshCw className={cn("h-5 w-5", isRefreshing ? "animate-spin text-amber-500" : "group-hover:text-amber-500 transition-colors")} />
                <span className="hidden sm:inline">
                    {isRefreshing ? "Synchronisation..." : "Synchroniser mon profil"}
                </span>
                <span className="sm:hidden">
                    {isRefreshing ? "..." : "Synchro"}
                </span>
            </Button>
        </div>
    );
}

"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import { getPendingTradeRequests, acceptTradeRequest, rejectTradeRequest, cancelTradeRequest } from "@/server/actions/ocre-actions";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Loader2, Inbox, Send, Check, X, Handshake, RefreshCw, Clock } from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { formatDistanceToNow } from "date-fns";
import { fr } from "date-fns/locale";

import { io } from "socket.io-client";
import { buildWsUrl } from "@/lib/socket-utils";
import { useSession } from "next-auth/react";
import { useRouter } from "next/navigation";

const POLL_INTERVAL_MS = 60_000; // Increased to 60s as we now have real-time sockets

export function OcreTradeInbox({ guildId }: { guildId: string }) {
    const { data: session } = useSession();
    const router = useRouter();
    const [incoming, setIncoming] = useState<any[]>([]);
    const [outgoing, setOutgoing] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [actionLoading, setActionLoading] = useState<string | null>(null);
    const [lastRefresh, setLastRefresh] = useState<Date>(new Date());
    const [isConnected, setIsConnected] = useState(false);
    const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);
    const socketRef = useRef<any>(null);

    const fetchData = useCallback(async (silent = false) => {
        if (!silent) setLoading(true);
        try {
            const res = await getPendingTradeRequests(guildId);
            if (res.success && res.data) {
                setIncoming(res.data.incoming);
                setOutgoing(res.data.outgoing);
                setLastRefresh(new Date());
            }
        } finally {
            if (!silent) setLoading(false);
        }
    }, [guildId]);

    // WebSocket + Polling
    useEffect(() => {
        fetchData(false);
        
        // Polling fallback
        pollRef.current = setInterval(() => fetchData(true), POLL_INTERVAL_MS);

        // Real-time Socket
        const socketUrl = buildWsUrl();
        const socket = io(socketUrl, {
            path: "/socket.io/",
            query: { guildId }
        });
        socketRef.current = socket;

        socket.on("connect", () => {
            console.log("[WS] 📡 Connecté pour l'Inbox Trade");
            setIsConnected(true);
        });
        
        socket.on("disconnect", () => {
            console.log("[WS] 🔴 Déconnecté de l'Inbox Trade");
            setIsConnected(false);
        });
        
        socket.on("ocre:trade:update", (data) => {
            console.log("[WS] 🔄 Update trade reçu:", data);
            fetchData(true);
        });

        return () => {
            if (pollRef.current) clearInterval(pollRef.current);
            if (socketRef.current) socketRef.current.disconnect();
        };
    }, [fetchData, guildId]);

    const handleAction = async (requestId: string, action: 'accept' | 'reject' | 'cancel') => {
        setActionLoading(requestId);
        try {
            let res;
            if (action === 'accept') res = await acceptTradeRequest({ guildId, requestId });
            else if (action === 'reject') res = await rejectTradeRequest({ guildId, requestId });
            else res = await cancelTradeRequest({ guildId, requestId });

            if (res.success) {
                toast.success(
                    action === 'accept' ? '🤝 Échange accepté ! Les compteurs Metamob sont mis à jour.' :
                        action === 'reject' ? '❌ Demande refusée.' :
                            '↩️ Demande annulée.'
                );
                await fetchData(true);
                router.refresh(); // Update the main dashboard data
            } else {
                toast.error(res.error || "Erreur réseau");
                if (res.error === "Demande déjà traitée" || res.error?.includes("introuvable")) {
                    await fetchData(true);
                }
            }
        } catch {
            toast.error("Erreur serveur");
        } finally {
            setActionLoading(null);
        }
    };

    if (loading) {
        return (
            <div className="flex flex-col items-center justify-center py-12 space-y-4">
                <div className="relative">
                    <Loader2 className="h-8 w-8 animate-spin text-emerald-500 opacity-20" />
                    <Loader2 className="h-8 w-8 animate-spin text-emerald-400 absolute top-0 left-0 [animation-delay:-0.5s]" />
                </div>
                <p className="text-xs font-bold text-zinc-500 uppercase tracking-widest animate-pulse">Chargement de votre inbox...</p>
            </div>
        );
    }

    if (incoming.length === 0 && outgoing.length === 0) {
        return (
            <div className="p-10 rounded-3xl border border-white/5 bg-zinc-900/10 flex flex-col items-center justify-center text-center space-y-4">
                <div className="h-12 w-12 rounded-2xl bg-zinc-800/50 flex items-center justify-center border border-white/5">
                    <Inbox className="h-6 w-6 text-zinc-600" />
                </div>
                <div className="max-w-xs">
                    <h4 className="font-bold text-zinc-400 text-sm">Aucun échange en cours</h4>
                    <p className="text-[11px] text-zinc-600 mt-1">
                        Utilisez la recherche de doublons ci-dessous pour trouver des partenaires et proposer des échanges.
