"use client";

import { useState } from "react";
import { ShieldAlert, BookOpen, ExternalLink, Check, ChevronRight, ChevronLeft, Plus, Loader2, Search, X } from "lucide-react";
import NextImage from "next/image";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { DO_TAGS } from "@/lib/dofus-tags";
import type { DofusBookLink } from "./builds-card";

// ─── Types ─────────────────────────────────────────────────────────────────

type BuildSource = "dofusbook" | null;

interface AddBuildModalProps {
    guildId: string;
    links: DofusBookLink[];
    onSave: (links: DofusBookLink[]) => void;
    targetUserId?: string;
    trigger?: React.ReactNode;
}

// ─── Constants ─────────────────────────────────────────────────────────────

const DOFUS_CLASSES = [
    { id: 1, name: "Féca" }, { id: 2, name: "Osamodas" }, { id: 3, name: "Enutrof" },
    { id: 4, name: "Sram" }, { id: 5, name: "Xélor" }, { id: 6, name: "Écaflip" },
    { id: 7, name: "Éniripsa" }, { id: 8, name: "Iop" }, { id: 9, name: "Crâ" },
    { id: 10, name: "Sadida" }, { id: 11, name: "Sacrieur" }, { id: 12, name: "Pandawa" },
    { id: 13, name: "Roublard" }, { id: 14, name: "Zobal" }, { id: 15, name: "Steamer" },
    { id: 16, name: "Éliotrope" }, { id: 17, name: "Huppermage" }, { id: 18, name: "Ouginak" },
    { id: 19, name: "Forgelance" }
];

const CLASS_COLORS: Record<number, string> = {
    1: "#8b5cf6", 2: "#f59e0b", 3: "#10b981", 4: "#6366f1", 5: "#3b82f6",
    6: "#ef4444", 7: "#ec4899", 8: "#f97316", 9: "#84cc16", 10: "#059669",
    11: "#dc2626", 12: "#4ade80", 13: "#7c3aed", 14: "#1e40af", 15: "#0ea5e9",
    16: "#2563eb", 17: "#9333ea", 18: "#ea580c", 19: "#06b6d4"
};

const TAG_CATEGORIES = [
    {
        name: "Éléments",
        ids: ["eau", "feu", "terre", "air", "multi", "terrefeu", "terreeau", "terreair", "feueau", "feuair", "eauair", "multinocrit"]
    },
    {
        name: "Stats & Rôles",
        ids: ["tank", "dopou", "pp", "ini", "retpm", "retpa", "sagesse", "docrit", "soin"]
    },
    {
        name: "Usage",
        ids: ["songes", "leveling"]
    }
];

type NonNullableBuildSource = "dofusbook";

const URL_VALIDATORS: Record<NonNullableBuildSource, { pattern: RegExp; placeholder: string; hint: string }> = {
    dofusbook: {
        pattern: /^https:\/\/(www\.)?(d-bk\.net|dofusbook\.net)\/(fr|en|es|pt|de)\/(?:private\/)?[a-zA-Z0-9-_\/]+$/,
        placeholder: "https://d-bk.net/fr/d/...",
        hint: "Lien d-bk.net ou dofusbook.net (https requis)"
    }
};

// ─── Step indicators ────────────────────────────────────────────────────────

const STEPS = [
    { label: "Nom", icon: "✏️" },
    { label: "Lien stuff", icon: "🔗" },
    { label: "Tags", icon: "🏷️" },
    { label: "Classe", icon: "⚔️" },
];

// ─── Main Component ─────────────────────────────────────────────────────────

export function AddBuildModal({ guildId, links, onSave, targetUserId, trigger }: AddBuildModalProps) {
    const [isOpen, setIsOpen] = useState(false);
    const [step, setStep] = useState(0);
    const [isSubmitting, setIsSubmitting] = useState(false);

    // Form state
    const [name, setName] = useState("");
    const [source, setSource] = useState<BuildSource>("dofusbook");
    const [url, setUrl] = useState("");
    const [tags, setTags] = useState<string[]>([]);
    const [classId, setClassId] = useState<number | null>(null);
    const [hoveredClassId, setHoveredClassId] = useState<number | null>(null);
    
    // Search states
    const [tagSearch, setTagSearch] = useState("");
    const [classSearch, setClassSearch] = useState("");

    const reset = () => {
        setStep(0);
        setName("");
        setSource("dofusbook");
        setUrl("");
        setTags([]);
        setClassId(null);
        setTagSearch("");
        setClassSearch("");
    };

    const handleClose = (open: boolean) => {
        if (!open) reset();
        setIsOpen(open);
    };

    // Validation per step
    const isStep0Valid = name.trim().length >= 1;
    const isStep1Valid = source !== null && url.trim().length > 0 && (source ? URL_VALIDATORS[source].pattern.test(url.trim()) : false);
    const canProceed = [isStep0Valid, isStep1Valid, true, true][step];

    const handleSubmit = async () => {
        if (!isStep1Valid || !source) return;
        setIsSubmitting(true);

        const { updateDofusBookLinks } = await import("@/server/actions/profile-actions");

        const newLink: DofusBookLink = {
            id: crypto.randomUUID(),
            name: name.trim(),
            url: url.trim(),
            tags,
            classId: classId || undefined,
            previewData: null,
        };

        const updatedLinks = [...links, newLink];

        try {
            const result = await updateDofusBookLinks({ guildId, links: updatedLinks, targetUserId });
            if (result.success) {
                onSave(updatedLinks);
                setIsOpen(false);
                reset();
                toast.success("Build ajouté avec succès !");
            } else {
                toast.error(result.error || "Erreur lors de l'ajout");
            }
        } catch {
            toast.error("Erreur serveur");
        } finally {
            setIsSubmitting(false);
        }
    };

    const urlValidator = source ? URL_VALIDATORS[source] : null;
    const urlIsValid = urlValidator && url.trim().length > 0 ? urlValidator.pattern.test(url.trim()) : null;

    return (
        <Dialog open={isOpen} onOpenChange={handleClose}>
            <DialogTrigger asChild>
                {trigger ?? (
                    <Button variant="sigil-emerald" size="sm" className="gap-2 h-9 px-4">
                        <Plus className="w-4 h-4" />
                        <span className="hidden sm:inline">Ajouter un Build</span>
                    </Button>
                )}
            </DialogTrigger>

            <DialogContent className="bg-zinc-950 border-zinc-800/60 text-zinc-200 sm:max-w-lg p-0 gap-0 overflow-hidden">
                {/* Header */}
                <DialogHeader className="p-6 pb-4 border-b border-white/5">
                    <DialogTitle className="text-lg font-black uppercase tracking-tight">
                        Importer un Build
                    </DialogTitle>

                    {/* Step progress bar */}
                    <div className="flex items-center gap-1.5 mt-3">
                        {STEPS.map((s, i) => (
                            <div key={i} className="flex items-center gap-1.5 flex-1">
                                <div className={cn(
                                    "flex items-center justify-center w-6 h-6 rounded-full text-[10px] font-black transition-all duration-300 border shrink-0",
                                    i < step
                                        ? "bg-emerald-500 border-emerald-400 text-white"
                                        : i === step
                                            ? "bg-zinc-800 border-white/30 text-white"
                                            : "bg-zinc-900 border-white/5 text-zinc-600"
                                )}>
                                    {i < step ? <Check className="w-3 h-3" /> : i + 1}
                                </div>
                                <span className={cn(
                                    "text-[10px] font-bold uppercase tracking-wider hidden sm:inline transition-colors",
                                    i === step ? "text-white" : "text-zinc-600"
                                )}>
                                    {s.label}
                                </span>
                                {i < STEPS.length - 1 && (
                                    <div className={cn(
                                        "flex-1 h-px transition-all duration-500",
                                        i < step ? "bg-emerald-500/50" : "bg-white/5"
                                    )} />
                                )}
                            </div>
                        ))}
                    </div>
                </DialogHeader>

                {/* Steps content */}
                <div className="p-6 min-h-[280px] flex flex-col">

                    {/* ── Step 0: Nom ───────────────────────────────────── */}
                    {step === 0 && (
                        <div className="flex flex-col gap-4 animate-in fade-in slide-in-from-right-4 duration-300 flex-1">
                            <div>
                                <Label htmlFor="build-name" className="text-xs font-black uppercase tracking-widest text-zinc-400 mb-2 block">
                                    Nom du build <span className="text-zinc-600 font-normal">(max 30 caractères)</span>
                                </Label>
                                <Input
                                    id="build-name"
                                    autoFocus
                                    placeholder="Ex: Cra Terre 200, Iop Full Sagesse..."
                                    maxLength={30}
                                    value={name}
                                    onChange={(e) => setName(e.target.value)}
                                    onKeyDown={(e) => e.key === "Enter" && isStep0Valid && setStep(1)}
                                    className="bg-zinc-900 border-white/10 text-white placeholder:text-zinc-600 h-12 text-base focus:border-emerald-500/50 focus:ring-emerald-500/20 transition-all"
                                />
                                <div className="flex justify-end mt-1.5">
                                    <span className={cn(
                                        "text-[10px] font-bold tabular-nums transition-colors",
                                        name.length >= 28 ? "text-amber-400" : "text-zinc-600"
                                    )}>
                                        {name.length}/30
                                    </span>
                                </div>
                            </div>

                            <div className="mt-auto p-4 bg-zinc-900/50 rounded-2xl border border-white/5 text-xs text-zinc-500 leading-relaxed">
                                <span className="text-zinc-400 font-bold">Conseil :</span> Donne un nom court et descriptif comme{" "}
                                <span className="text-zinc-300 font-bold">Cra Eau PvM</span> ou{" "}
                                <span className="text-zinc-300 font-bold">Iop Terre Songes</span> pour que les autres membres s'y retrouvent facilement.
                            </div>
                        </div>
                    )}

                    {/* ── Step 1: Lien stuff ─────────────────────────────── */}
                    {step === 1 && (
                        <div className="flex flex-col gap-5 animate-in fade-in slide-in-from-right-4 duration-300 flex-1">
                            <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                                <Label htmlFor="build-url" className="text-xs font-black uppercase tracking-widest text-zinc-400 mb-2 block">
                                    Lien de partage DofusBook
                                </Label>
                                <div className="relative">
                                    <Input
                                        id="build-url"
                                        autoFocus
                                        placeholder={urlValidator?.placeholder}
                                        value={url}
                                        onChange={(e) => setUrl(e.target.value)}
                                        className={cn(
                                            "bg-zinc-900 border-white/10 text-white placeholder:text-zinc-600 h-11 font-mono text-xs pr-10 transition-all",
                                            url.trim().length > 0 && urlIsValid === true && "border-emerald-500/50",
                                            url.trim().length > 0 && urlIsValid === false && "border-red-500/50"
                                        )}
                                    />
                                    {url.trim().length > 0 && (
                                        <div className={cn(
                                            "absolute right-3 top-1/2 -translate-y-1/2 w-5 h-5 rounded-full flex items-center justify-center",
                                            urlIsValid ? "bg-emerald-500" : "bg-red-500/80"
                                        )}>
                                            {urlIsValid
                                                ? <Check className="w-3 h-3 text-white" />
                                                : <span className="text-white text-xs font-black">!</span>
                                            }
                                        </div>
                                    )}
                                </div>
                                <p className={cn(
                                    "text-[10px] mt-1.5 flex items-center gap-1 transition-colors",
                                    url.trim().length > 0 && urlIsValid === false ? "text-red-400" : "text-zinc-500"
                                )}>
                                    <ShieldAlert className="w-3 h-3 shrink-0" />
                                    {url.trim().length > 0 && urlIsValid === false
                                        ? "Format de lien invalide (DofusBook attendu : d-bk.net ou dofusbook.net)."
                                        : urlValidator?.hint
                                    }
                                </p>
                            </div>
                        </div>
                    )}

                    {/* ── Step 2: Tags ──────────────────────────────────── */}
                    {step === 2 && (
                        <div className="flex flex-col gap-3 animate-in fade-in slide-in-from-right-4 duration-300 flex-1">
                            <div className="flex items-center justify-between">
                                <Label className="text-xs font-black uppercase tracking-widest text-zinc-400">
                                    Tags <span className="text-zinc-600 font-normal">(optionnel, max 3)</span>
                                </Label>
                                {tags.length > 0 && (
                                    <button
                                        type="button"
                                        onClick={() => setTags([])}
                                        className="text-[10px] text-zinc-500 hover:text-red-400 transition-colors font-bold"
                                    >
                                        Effacer tout
                                    </button>
                                )}
                            </div>

                            <div className="relative mb-1">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500" />
                                <Input
                                    placeholder="Rechercher un tag (ex: Eau, Soin...)"
                                    value={tagSearch}
                                    onChange={(e) => setTagSearch(e.target.value)}
                                    className="pl-9 pr-8 bg-zinc-900/50 border-white/10 text-white placeholder:text-zinc-500 h-9 text-xs rounded-lg focus:border-emerald-500/50 focus:ring-emerald-500/20"
                                />
                                {tagSearch && (
                                    <button
                                        onClick={() => setTagSearch("")}
                                        className="absolute right-2.5 top-1/2 -translate-y-1/2 text-zinc-500 hover:text-white transition-colors"
                                    >
                                        <X className="w-3.5 h-3.5" />
                                    </button>
                                )}
                            </div>

                            <div className="space-y-3 overflow-y-auto max-h-[190px] pr-2 custom-scrollbar">
                                {TAG_CATEGORIES.map((cat) => {
                                    const filteredIds = cat.ids.filter(tagId => {
                                        const tag = DO_TAGS.find(t => t.id === tagId);
                                        return tag && tag.label.toLowerCase().includes(tagSearch.toLowerCase());
                                    });

                                    if (filteredIds.length === 0) return null;

                                    return (
                                        <div key={cat.name}>
                                            <h4 className="text-[9px] font-black uppercase tracking-[0.2em] text-zinc-600 mb-2">{cat.name}</h4>
                                            <div className="flex flex-wrap gap-1.5">
                                                {filteredIds.map(tagId => {
                                                    const tag = DO_TAGS.find(t => t.id === tagId)!;
                                                    if (!tag) return null;
                                                    const isSelected = tags.includes(tag.id);
                                                    const isDisabled = !isSelected && tags.length >= 3;
                                                    return (
                                                        <button
                                                            key={tag.id}
                                                            type="button"
                                                            disabled={isDisabled}
                                                            onClick={() => {
                                                                if (isSelected) {
                                                                    setTags(prev => prev.filter(t => t !== tag.id));
                                                                } else if (tags.length < 3) {
                                                                    setTags(prev => [...prev, tag.id]);
                                                                }
                                                            }}
                                                            className={cn(
                                                                "px-2.5 py-1 text-[11px] rounded-lg transition-all border font-semibold select-none flex items-center gap-1.5",
                                                                isSelected
                                                                    ? `${tag.className} shadow-md opacity-100 ring-2 ring-emerald-500/40 shadow-emerald-500/10`
                                                                    : isDisabled
                                                                        ? "bg-transparent border-white/5 text-zinc-700 opacity-30 cursor-not-allowed"
                                                                        : `${tag.className} opacity-75 saturate-75 hover:opacity-100 hover:saturate-100`
                                                            )}
                                                        >
                                                            {tag.label}
                                                            {isSelected && <Check className="w-2.5 h-2.5 ml-0.5 shrink-0" />}
                                                        </button>
                                                    );
                                                })}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>

                            {/* Selected summary */}
                            {tags.length > 0 ? (
                                <div className="mt-auto flex items-center gap-2 p-2.5 bg-zinc-900/50 rounded-xl border border-white/5">
                                    <span className="text-[10px] text-zinc-500 font-bold shrink-0">Sélectionnés :</span>
                                    <div className="flex gap-1.5 flex-wrap">
                                        {tags.map(tid => {
                                            const tag = DO_TAGS.find(t => t.id === tid);
                                            return tag ? (
                                                <span key={tid} className={cn("px-2 py-0.5 text-[10px] rounded-md border font-semibold", tag.className)}>
                                                    {tag.label}
                                                </span>
                                            ) : null;
                                        })}
                                    </div>
                                </div>
                            ) : (
                                <div className="mt-auto p-2.5 bg-zinc-900/30 rounded-xl border border-dashed border-white/5 text-center">
                                    <span className="text-[10px] text-zinc-600 italic">Étape optionnelle — passe directement à Suivant si tu le souhaites</span>
                                </div>
                            )}
                        </div>
                    )}

                    {/* ── Step 3: Classe ────────────────────────────────── */}
                    {step === 3 && (
                        <div className="flex flex-col gap-4 animate-in fade-in slide-in-from-right-4 duration-300 flex-1">
                            <div>
                                <Label className="text-xs font-black uppercase tracking-widest text-zinc-400 mb-1 block">
                                    Classe du personnage <span className="text-zinc-600 font-normal">(recommandé)</span>
                                </Label>
                                <p className="text-[10px] text-zinc-600 mb-3">
                                    Sélectionnez la classe pour une belle preview, même si DofusBook est lent.
                                </p>

                                <div className="relative mb-3">
                                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500" />
                                    <Input
                                        placeholder="Rechercher une classe..."
                                        value={classSearch}
                                        onChange={(e) => setClassSearch(e.target.value)}
                                        className="pl-9 pr-8 bg-zinc-900/50 border-white/10 text-white placeholder:text-zinc-500 h-9 text-xs rounded-lg focus:border-emerald-500/50 focus:ring-emerald-500/20"
                                    />
                                    {classSearch && (
                                        <button
                                            onClick={() => setClassSearch("")}
                                            className="absolute right-2.5 top-1/2 -translate-y-1/2 text-zinc-500 hover:text-white transition-colors"
                                        >
                                            <X className="w-3.5 h-3.5" />
                                        </button>
                                    )}
                                </div>

                                <div className="grid grid-cols-5 sm:grid-cols-7 gap-2 overflow-y-auto max-h-[160px] custom-scrollbar pr-1">
                                    {DOFUS_CLASSES.filter(c => c.name.toLowerCase().includes(classSearch.toLowerCase())).map((cls) => {
                                        const isSelected = classId === cls.id;
                                        return (
                                            <button
                                                key={cls.id}
                                                type="button"
                                                onClick={() => setClassId(isSelected ? null : cls.id)}
                                                onMouseEnter={() => setHoveredClassId(cls.id)}
                                                onMouseLeave={() => setHoveredClassId(null)}
                                                className={cn(
                                                    "relative aspect-square rounded-xl border transition-all duration-300 flex items-center justify-center overflow-hidden group bg-zinc-900/30",
                                                    isSelected
                                                        ? "scale-110 border-emerald-500 bg-emerald-500/10 shadow-[0_0_15px_-3px_rgba(16,185,129,0.3)] z-20"
                                                        : "border-white/5 hover:border-white/20 hover:bg-zinc-900/60 z-10"
                                                )}
                                            >
                                                <div className={cn(
                                                    "relative w-8 h-8 transition-all duration-300 z-10",
                                                    isSelected
                                                        ? "scale-110 drop-shadow-[0_0_8px_rgba(16,185,129,0.4)] opacity-100"
                                                        : "opacity-70 group-hover:opacity-100 group-hover:scale-110"
                                                )}>
                                                    <NextImage
                                                        src={`/assets/dofus/classes/${cls.id === 19 ? 20 : cls.id}.png`}
                                                        alt={cls.name}
                                                        fill
                                                        className="object-contain"
                                                    />
                                                </div>
                                            </button>
                                        );
                                    })}
                                </div>

                                {/* Class name tooltip */}
                                <div className="flex items-center justify-center h-8 mt-2">
                                    {(hoveredClassId || classId) ? (
                                        <span className="text-xs font-bold px-3 py-1.5 bg-white/10 rounded-full text-white tracking-wide shadow-inner animate-in fade-in zoom-in duration-150">
                                            {DOFUS_CLASSES.find(c => c.id === (hoveredClassId || classId))?.name}
                                        </span>
                                    ) : (
                                        <span className="text-[10px] font-medium text-zinc-600 italic">
                                            Survolez pour voir le nom de la classe
                                        </span>
                                    )}
                                </div>
                            </div>
                        </div>
                    )}
                </div>

                {/* Footer navigation */}
                <div className="flex items-center justify-between px-6 pb-6 pt-4 border-t border-white/5 gap-3">
                    {/* Back button */}
                    <Button
                        variant="ghost"
                        onClick={() => step > 0 ? setStep(s => s - 1) : handleClose(false)}
                        disabled={isSubmitting}
                        className="text-zinc-500 hover:text-white hover:bg-white/5"
                    >
                        <ChevronLeft className="w-4 h-4 mr-1" />
                        {step === 0 ? "Annuler" : "Retour"}
                    </Button>

                    {/* Progress dots */}
                    <div className="flex gap-1.5">
                        {STEPS.map((_, i) => (
                            <div key={i} className={cn(
                                "h-1.5 rounded-full transition-all duration-300",
                                i === step ? "w-6 bg-emerald-500" : i < step ? "w-2 bg-emerald-500/40" : "w-2 bg-zinc-800"
                            )} />
                        ))}
                    </div>

                    {/* Next / Submit button */}
                    {step < STEPS.length - 1 ? (
                        <Button
                            onClick={() => setStep(s => s + 1)}
                            disabled={!canProceed}
                            variant="sigil-emerald"
                            className="gap-2"
                        >
                            Suivant
                            <ChevronRight className="w-4 h-4" />
                        </Button>
                    ) : (
                        <Button
                            onClick={handleSubmit}
                            disabled={isSubmitting}
                            variant="sigil-emerald"
                            className="gap-2 min-w-[130px]"
                        >
                            {isSubmitting ? (
                                <><Loader2 className="w-4 h-4 animate-spin" /> Ajout...</>
                            ) : (
                                <><Check className="w-4 h-4" /> Confirmer</>
                            )}
                        </Button>
                    )}
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Pencil, Shield, Check, Info, Sparkles } from "lucide-react";
import { ALIGNMENTS, ORDERS, getAlignment, getOrder } from "@/lib/dofus-assets";
import { cn } from "@/lib/utils";
import Image from "next/image";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogClose, DialogDescription } from "@/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Slider } from "@/components/ui/slider";

interface AlignmentSectionProps {
    alignment?: string | null;
    alignmentOrder?: string | null;
    alignmentLevel?: number | null;
    onSave?: (data: { alignment: string | null; alignmentOrder: string | null; alignmentLevel: number }) => void;
    readOnly?: boolean;
}

export function AlignmentSection({
    alignment,
    alignmentOrder,
    alignmentLevel = 0,
    onSave,
    readOnly = false,
}: AlignmentSectionProps) {
    const [isOpen, setIsOpen] = useState(false);
    const [selectedAlignment, setSelectedAlignment] = useState<string | null>(alignment || "neutre");
    const [selectedOrder, setSelectedOrder] = useState<string | null>(alignmentOrder || null);
    const [localLevel, setLocalLevel] = useState<number>(alignmentLevel || 0);

    const currentAlignment = getAlignment(alignment || "neutre");
    const currentOrder = alignment && alignmentOrder ? getOrder(alignment, alignmentOrder) : null;

    const handleSave = () => {
        onSave?.({
            alignment: selectedAlignment,
            alignmentOrder: selectedOrder,
            alignmentLevel: localLevel,
        });
        setIsOpen(false);
    };

    const handleOpen = () => {
        setSelectedAlignment(alignment || "neutre");
        setSelectedOrder(alignmentOrder || null);
        setLocalLevel(alignmentLevel || 0);
    };

    // Calculate the title based on the level
    const getLevelTitle = (align: string, orderId: string, level: number) => {
        const order = getOrder(align, orderId);
        if (!order) return "";
        
        const levels = [20, 40, 60, 80, 100];
        const currentMilestone = levels.reverse().find(l => level >= l);
        return currentMilestone ? order.levels[currentMilestone] : "Apprenti";
    };

    return (
        <div className="p-4 bg-zinc-900/40 backdrop-blur-md rounded-xl border border-white/10 transition-all hover:border-white/20 group">
            <Dialog open={isOpen} onOpenChange={setIsOpen}>
                <div className="flex items-center justify-between mb-4">
                    <h3 className="text-base font-semibold text-zinc-200 flex items-center gap-2">
                        <Shield className="w-4 h-4 text-indigo-400" />
                        Alignement & Ordre
                    </h3>
                    {!readOnly && (
                        <DialogTrigger asChild>
                            <Button 
                                variant="ghost" 
                                size="icon" 
                                className="h-8 w-8 text-zinc-400 hover:text-indigo-400 hover:bg-indigo-500/10 border border-transparent hover:border-indigo-500/20 transition-all duration-300"
                                onClick={handleOpen}
                            >
                                <Pencil className="w-4 h-4" strokeWidth={2.5} />
                            </Button>
                        </DialogTrigger>
                    )}
                </div>

                <div className="relative overflow-hidden rounded-lg border border-white/5 bg-gradient-to-br from-zinc-900 to-black p-4 mb-1 transition-colors group-hover:border-white/10">
                    <div className="flex items-center gap-4">
                        <div className={cn(
                            "relative flex items-center justify-center w-16 h-16 rounded-xl border shadow-lg shrink-0 overflow-hidden",
                            alignment === "bontarien" ? "border-blue-500/30 bg-blue-500/10" : 
                            alignment === "brakmarien" ? "border-red-500/30 bg-red-500/10" : 
                            "border-white/10 bg-zinc-950"
                        )}>
                            {currentOrder ? (
                                <Image 
                                    src={currentOrder.icon} 
                                    alt={currentOrder.name} 
                                    fill 
                                    className="object-cover p-2"
                                />
                            ) : currentAlignment ? (
                                <Image 
                                    src={currentAlignment.icon} 
                                    alt={currentAlignment.name} 
                                    fill 
                                    className="object-cover scale-[1.35]"
                                />
                            ) : (
                                <Shield className="w-8 h-8 text-zinc-600" />
                            )}
                        </div>

                        <div className="flex-1 space-y-1">
                            <div className="flex items-center gap-2">
                                <Badge 
                                    className={cn(
                                        "text-[10px] uppercase font-black tracking-widest",
                                        alignment === "bontarien" ? "bg-blue-500/20 text-blue-400 border-blue-500/30" : 
                                        alignment === "brakmarien" ? "bg-red-500/20 text-red-400 border-red-500/30" : 
                                        "bg-zinc-800 text-zinc-400 border-white/5"
                                    )}
                                >
                                    {currentAlignment?.name || "Neutre"}
                                </Badge>
                                {alignmentLevel !== null && alignmentLevel > 0 && (
                                    <span className="text-[10px] font-bold text-zinc-500">
                                        Niveau {alignmentLevel}
                                    </span>
                                )}
                            </div>

                            <h4 className="text-lg font-black text-white italic tracking-tight uppercase">
                                {currentOrder ? currentOrder.name : "Aucun ordre"}
                            </h4>

                            {alignment && alignmentOrder && (
                                <p className="text-xs font-bold text-indigo-400/80 uppercase tracking-widest">
                                    {getLevelTitle(alignment, alignmentOrder, alignmentLevel || 0)}
                                </p>
                            )}
                        </div>
                    </div>
                </div>

                <DialogContent className="max-w-4xl w-[95vw] h-[90vh] flex flex-col p-0 gap-0 bg-zinc-950 border-zinc-800 rounded-3xl overflow-hidden shadow-2xl">
                    <DialogHeader className="p-8 pb-4 border-b border-white/5 shrink-0">
                        <DialogTitle className="text-2xl font-black italic uppercase tracking-tighter">Alignement & Ordres</DialogTitle>
                        <DialogDescription className="text-base text-zinc-400">Choisissez votre camp et votre spécialisation.</DialogDescription>
                    </DialogHeader>

                    <div className="flex-1 overflow-y-auto p-8 space-y-8 scrollbar-thin">
                        {/* Alignment Selection */}
                        <section className="space-y-4">
                            <h4 className="text-xs font-black text-zinc-500 uppercase tracking-[0.2em] flex items-center gap-2">
                                <Shield className="w-4 h-4" /> 1. Choisir l'Alignement
                            </h4>
                            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                {ALIGNMENTS.map(align => (
                                    <button
                                        key={align.id}
                                        onClick={() => {
                                            setSelectedAlignment(align.id);
                                            if (align.id === "neutre") setSelectedOrder(null);
                                        }}
                                        className={cn(
                                            "relative group flex flex-col items-center gap-4 p-6 rounded-2xl border-2 transition-all duration-500 overflow-hidden",
                                            selectedAlignment === align.id
                                                ? "border-indigo-500/50 bg-indigo-500/10"
                                                : "border-white/5 bg-zinc-900/40 hover:bg-zinc-900/60 hover:border-white/10"
                                        )}
                                    >
                                        <div className={cn(
                                            "relative w-16 h-16 rounded-full flex items-center justify-center border shadow-2xl transition-transform duration-500 group-hover:scale-110 overflow-hidden",
                                            align.id === "bontarien" ? "bg-blue-500/20 border-blue-500/30" :
                                            align.id === "brakmarien" ? "bg-red-500/20 border-red-500/30" :
                                            "bg-zinc-800 border-white/10"
                                        )}>
                                            <Image 
                                                src={align.icon} 
                                                alt={align.name} 
                                                fill 
                                                className="object-cover scale-[1.35] group-hover:scale-[1.45] transition-transform duration-500" 
                                            />
                                        </div>
                                        <span className={cn(
                                            "font-black uppercase tracking-widest text-sm italic",
                                            selectedAlignment === align.id ? "text-white" : "text-zinc-500"
                                        )}>
                                            {align.name}
                                        </span>

                                        {selectedAlignment === align.id && (
                                            <div className="absolute top-3 right-3 w-6 h-6 rounded-full bg-indigo-500 flex items-center justify-center shadow-[0_0_15px_rgba(99,102,241,0.5)]">
                                                <Check className="w-4 h-4 text-white" />
                                            </div>
                                        )}
                                    </button>
                                ))}
                            </div>
                        </section>

                        {selectedAlignment && selectedAlignment !== "neutre" && (
                            <>
                                {/* Order Selection (Moved before level for better flow) */}
                                <section className="space-y-4">
                                    <h4 className="text-xs font-black text-zinc-500 uppercase tracking-[0.2em] flex items-center gap-2">
                                        <Sparkles className="w-4 h-4" /> 2. Choisir l'Ordre
                                    </h4>
                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                        {(ORDERS as any)[selectedAlignment].map((order: any) => {
                                            const isSelected = selectedOrder === order.id;
                                            return (
                                                <button
                                                    key={order.id}
                                                    onClick={() => setSelectedOrder(order.id)}
                                                    className={cn(
                                                        "relative group flex flex-col items-center gap-4 p-6 rounded-2xl border-2 transition-all duration-500 h-full",
                                                        isSelected
                                                            ? "border-amber-500/50 bg-amber-500/10"
                                                            : "border-white/5 bg-zinc-900/40 hover:bg-zinc-900/60 hover:border-white/10"
                                                    )}
                                                >
                                                    <div className="relative w-20 h-20 bg-zinc-950 border border-white/10 rounded-xl overflow-hidden shadow-2xl transition-transform duration-500 group-hover:scale-105">
                                                        <Image 
                                                            src={order.icon} 
                                                            alt={order.name} 
                                                            fill 
                                                            className="object-cover p-3"
                                                        />
                                                    </div>
                                                    <div className="text-center space-y-1">
                                                        <span className={cn(
                                                            "font-black uppercase tracking-tighter text-sm block leading-tight",
                                                            isSelected ? "text-white" : "text-zinc-400"
                                                        )}>
                                                            {order.name}
                                                        </span>
                                                    </div>

                                                    {isSelected && (
                                                        <div className="absolute top-3 right-3 w-6 h-6 rounded-full bg-amber-500 flex items-center justify-center shadow-[0_0_15px_rgba(245,158,11,0.5)]">
                                                            <Check className="w-4 h-4 text-white" />
                                                        </div>
                                                    )}
                                                </button>
                                            );
                                        })}
                                    </div>
                                </section>

                                {/* Level/Tranche Selection */}
                                {selectedOrder && (
                                    <section className="space-y-4 bg-zinc-900/30 p-6 rounded-2xl border border-white/5">
                                        <div className="flex items-center justify-between mb-2">
                                            <h4 className="text-xs font-black text-zinc-500 uppercase tracking-[0.2em] flex items-center gap-2">
                                                <Info className="w-4 h-4" /> 3. Niveau d'Alignement (Tranche)
                                            </h4>
                                        </div>
                                        <div className="grid grid-cols-1 md:grid-cols-5 gap-3">
                                            {[20, 40, 60, 80, 100].map(level => {
                                                const isSelected = localLevel >= level && localLevel < (level + 20); // If they picked exactly 100, etc. Actually let's strictly use the exact levels.
                                                // Better yet, just match exactly:
                                                const isExactSelected = localLevel === level;
                                                return (
                                                    <button
                                                        key={level}
                                                        onClick={() => setLocalLevel(level)}
                                                        className={cn(
                                                            "relative flex flex-col items-center justify-center p-4 rounded-xl border-2 transition-all duration-300 text-center gap-2",
                                                            isExactSelected
                                                                ? "border-amber-500 bg-amber-500/20 shadow-[0_0_15px_rgba(245,158,11,0.2)]"
                                                                : "border-white/5 bg-zinc-950/50 hover:border-white/20 hover:bg-zinc-900"
                                                        )}
                                                    >
                                                        <span className={cn(
                                                            "text-lg font-black italic",
                                                            isExactSelected ? "text-amber-400" : "text-zinc-500"
                                                        )}>
                                                            Niv {level}
                                                        </span>
                                                        <span className={cn(
                                                            "text-[10px] uppercase font-bold leading-tight",
                                                            isExactSelected ? "text-white" : "text-zinc-600"
                                                        )}>
                                                            {getLevelTitle(selectedAlignment, selectedOrder, level)}
                                                        </span>
                                                        {isExactSelected && (
                                                            <div className="absolute -top-2 -right-2 w-5 h-5 rounded-full bg-amber-500 flex items-center justify-center">
                                                                <Check className="w-3 h-3 text-white" />
                                                            </div>
                                                        )}
                                                    </button>
                                                )
                                            })}
                                        </div>
                                    </section>
                                )}

                            </>
                        )}
                    </div>

                    <div className="p-6 border-t border-white/5 bg-zinc-900/40 flex justify-end gap-3 shrink-0">
                        <DialogClose asChild>
                            <Button variant="ghost" className="text-zinc-400 hover:text-white">
                                Annuler
                            </Button>
                        </DialogClose>
                        <Button 
                            onClick={handleSave} 
                            variant="sigil"
                            size="xl"
                        >
                            Enregistrer mon Ordre
                        </Button>
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { Users, Plus, X, Save, Edit2, AlertCircle, Copy, Shield, Trash2, Check, Sparkles, Info } from "lucide-react";
import { toast } from "sonner";
import { DOFUS_CLASSES, getClass, ALIGNMENTS, ORDERS, getAlignment, getOrder } from "@/lib/dofus-assets";
import NextImage from "next/image";

export type Mule = {
    id?: string;
    pseudo: string;
    classe?: string;
    level?: number;
    alignment?: string | null;
    alignmentOrder?: string | null;
};

interface AltPseudosProps {
    altPseudos?: any[];
    onSave?: (pseudos: Mule[]) => Promise<any>;
    readOnly?: boolean;
    maxPseudos?: number;
}

export function AltPseudos({
    altPseudos = [],
    onSave,
    readOnly = false,
    maxPseudos = 10,
}: AltPseudosProps) {
    const [isEditing, setIsEditing] = useState(false);
    const [localPseudos, setLocalPseudos] = useState<Mule[]>([]);

    // Form inputs state
    const [newPseudo, setNewPseudo] = useState("");
    const [newClass, setNewClass] = useState<string>("cra");
    const [newLevel, setNewLevel] = useState<string>("200");
    const [newAlignment, setNewAlignment] = useState<string>("neutre");
    const [newOrder, setNewOrder] = useState<string | null>(null);

    // Edit tracking state
    const [editingMuleId, setEditingMuleId] = useState<string | null>(null);
    const [isSubmitting, setIsSubmitting] = useState(false);

    // Reference to form element to scroll to it nicely on edit trigger
    const formRef = useRef<HTMLDivElement>(null);

    // Sync and normalize local state when props change
    useEffect(() => {
        const normalized = altPseudos.map(p => {
            if (typeof p === "string") {
                return { id: crypto.randomUUID(), pseudo: p, classe: "cra", level: 200, alignment: "neutre", alignmentOrder: null };
            }
            return {
                id: p.id || crypto.randomUUID(),
                pseudo: p.pseudo || "Inconnu",
                classe: p.classe || "cra",
                level: p.level !== undefined ? p.level : 200,
                alignment: p.alignment || "neutre",
                alignmentOrder: p.alignmentOrder || null
            };
        });
        setLocalPseudos(normalized);
    }, [altPseudos]);

    const formatPseudo = (value: string) => {
        const cleaned = value.replace(/[^a-zA-Z\u00C0-\u017F\u00DF\u00FF\u0100-\u017F-]/g, "");
        if (!cleaned) return "";
        
        return cleaned
            .split("-")
            .map(part => {
                if (part.length === 0) return part;
                return part.charAt(0).toUpperCase() + part.slice(1).toLowerCase();
            })
            .join("-");
    };

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setNewPseudo(formatPseudo(e.target.value));
    };

    const validatePseudo = (pseudo: string): { valid: boolean; error?: string } => {
        if (pseudo.length < 3) return { valid: false, error: "Minimum 3 caractères" };
        if (pseudo.length > 20) return { valid: false, error: "Maximum 20 caractères" };
        return { valid: true };
    };

    // Load mule data into the form for direct modification
    const handleStartEditMule = (mule: Mule) => {
        setEditingMuleId(mule.id || null);
        setNewPseudo(mule.pseudo);
        setNewClass(mule.classe || "cra");
        setNewLevel(mule.level?.toString() || "200");
        setNewAlignment(mule.alignment || "neutre");
        setNewOrder(mule.alignmentOrder || null);

        // Smooth scroll to form
        setTimeout(() => {
            formRef.current?.scrollIntoView({ behavior: "smooth", block: "center" });
        }, 80);

        toast.info(`Modification de ${mule.pseudo} chargée dans le formulaire ci-dessous`);
    };

    // Reset/Cancel form inputs back to default "Add" mode
    const handleCancelFormEdit = () => {
        setEditingMuleId(null);
        setNewPseudo("");
        setNewClass("cra");
        setNewLevel("200");
        setNewAlignment("neutre");
        setNewOrder(null);
    };

    const handleAddOrUpdatePseudo = () => {
        const trimmed = newPseudo.trim();
        if (!trimmed) return;

        const validation = validatePseudo(trimmed);
        if (!validation.valid) {
            toast.error(validation.error);
            return;
        }

        let lvl = parseInt(newLevel, 10);
        if (isNaN(lvl) || lvl < 0 || lvl > 200) lvl = 200;

        if (editingMuleId) {
            // Update existing mule
            setLocalPseudos(prev => prev.map(p => {
                if (p.id === editingMuleId) {
                    return {
                        ...p,
                        pseudo: trimmed,
                        classe: newClass,
                        level: lvl,
                        alignment: newAlignment,
                        alignmentOrder: newAlignment === "neutre" ? null : newOrder
                    };
                }
                return p;
            }));
            toast.success(`Personnage ${trimmed} mis à jour localement`);
            handleCancelFormEdit();
        } else {
            // Add new mule
            if (localPseudos.length >= maxPseudos) {
                toast.error(`Maximum ${maxPseudos} personnages`);
                return;
            }

            if (localPseudos.some(p => p.pseudo.toLowerCase() === trimmed.toLowerCase())) {
                toast.error("Ce pseudo est déjà ajouté");
                return;
            }

            setLocalPseudos(prev => [...prev, { 
                id: crypto.randomUUID(), 
                pseudo: trimmed, 
                classe: newClass, 
                level: lvl,
                alignment: newAlignment,
                alignmentOrder: newAlignment === "neutre" ? null : newOrder
            }]);
            toast.success(`Personnage ${trimmed} ajouté localement`);
            handleCancelFormEdit();
        }
    };

    const handleRemovePseudo = (idToRemove: string) => {
        setLocalPseudos(prev => prev.filter(p => p.id !== idToRemove));
        if (editingMuleId === idToRemove) {
            handleCancelFormEdit();
        }
    };

    const handleSave = async () => {
        setIsSubmitting(true);
        try {
            const finalPseudos = [...localPseudos];

            // If there's content left in the input, auto-commit it first if valid
            const trimmed = newPseudo.trim();
            if (trimmed && !editingMuleId) {
                const validation = validatePseudo(trimmed);
                if (validation.valid && !localPseudos.some(p => p.pseudo.toLowerCase() === trimmed.toLowerCase()) && localPseudos.length < maxPseudos) {
                    let lvl = parseInt(newLevel, 10);
                    if (isNaN(lvl) || lvl < 0 || lvl > 200) lvl = 200;
                    finalPseudos.push({ 
                        id: crypto.randomUUID(), 
                        pseudo: trimmed, 
                        classe: newClass, 
                        level: lvl,
                        alignment: newAlignment,
                        alignmentOrder: newAlignment === "neutre" ? null : newOrder
                    });
                    setLocalPseudos(finalPseudos);
                    handleCancelFormEdit();
                } else if (!validation.valid) {
                    toast.error(validation.error);
                    setIsSubmitting(false);
                    return;
                }
            }

            if (onSave) {
                await onSave(finalPseudos);
            }
            setIsEditing(false);
            toast.success("Mules sauvegardées avec succès");
        } catch (error) {
            console.error("Save alt pseudos error:", error);
            toast.error("Erreur lors de la sauvegarde");
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleCancel = () => {
        const normalized = altPseudos.map(p => {
            if (typeof p === "string") return { id: crypto.randomUUID(), pseudo: p, classe: "cra", level: 200, alignment: "neutre", alignmentOrder: null };
            return {
                id: p.id || crypto.randomUUID(),
                pseudo: p.pseudo || "Inconnu",
                classe: p.classe || "cra",
                level: p.level !== undefined ? p.level : 200,
                alignment: p.alignment || "neutre",
                alignmentOrder: p.alignmentOrder || null
            };
        });
        setLocalPseudos(normalized);
        setIsEditing(false);
        handleCancelFormEdit();
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === "Enter") {
            e.preventDefault();
            handleAddOrUpdatePseudo();
        }
    };

    return (
        <Card className="bg-zinc-900/40 backdrop-blur-md border-white/10 relative overflow-hidden group h-full flex flex-col">
            <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/5 rounded-full blur-3xl pointer-events-none -mr-8 -mt-8 opacity-0 group-hover:opacity-100 transition-opacity" />

            <CardHeader className="p-6 pb-4">
                <div className="flex items-center justify-between">
                    <CardTitle className="text-base font-semibold text-zinc-200 flex items-center gap-2">
                        <Users className="w-5 h-5 text-indigo-400" />
                        Mes Mules
                        {!readOnly && (
                            <span className="text-xs text-zinc-500 bg-zinc-950/50 border border-white/5 px-2 py-0.5 rounded shadow-sm font-bold">
                                {localPseudos.length}/{maxPseudos}
                            </span>
                        )}
                    </CardTitle>
                    {!readOnly && (
                        <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => isEditing ? handleCancel() : setIsEditing(true)}
                            className={cn(
                                "h-8 px-3 text-[10px] font-black uppercase tracking-widest transition-all border shadow-lg rounded-xl",
                                isEditing
                                    ? "bg-zinc-800 text-zinc-200 border-white/10 hover:bg-zinc-700"
                                    : "bg-indigo-500/5 text-indigo-400 border-indigo-500/20 hover:bg-indigo-500 hover:text-white"
                            )}
                        >
                            {isEditing ? <X className="w-3 h-3 mr-2" /> : <Edit2 className="w-3 h-3 mr-2" strokeWidth={2.5} />}
                            {isEditing ? "Annuler" : "Gérer les Mules"}
                        </Button>
                    )}
                </div>
            </CardHeader>
            <CardContent className="p-6 pt-2 space-y-6 relative flex-1">
                {localPseudos.length > 0 ? (
                    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4">
                        {localPseudos.map((mule) => {
                            const cls = getClass(mule.classe || "cra") || DOFUS_CLASSES[0];
                            const alignData = mule.alignment ? getAlignment(mule.alignment) : null;
                            const orderData = mule.alignment && mule.alignmentOrder ? getOrder(mule.alignment, mule.alignmentOrder) : null;

                            return (
                                <div
                                    key={mule.id}
                                    className={cn(
                                        "relative flex flex-col justify-between p-4 rounded-2xl bg-zinc-950/40 border transition-all group/item overflow-hidden",
                                        editingMuleId === mule.id 
                                            ? "border-indigo-500/40 bg-indigo-950/10 shadow-[0_0_20px_rgba(99,102,241,0.15)]"
                                            : "border-white/5 hover:border-white/10"
                                    )}
                                >
                                    <div
                                        className="absolute -top-10 -right-10 w-32 h-32 rounded-full blur-3xl pointer-events-none opacity-20"
                                        style={{ backgroundColor: cls.color }}
                                    />

                                    <div className="flex items-start justify-between z-10 w-full overflow-hidden gap-2">
                                        <div className="flex items-center gap-3 w-full min-w-0">
                                            <div className="w-11 h-11 rounded-[10px] bg-black/40 border border-[currentColor]/20 flex items-center justify-center overflow-hidden shrink-0 shadow-inner" style={{ color: cls.color }}>
                                                <NextImage
                                                    src={cls.icon}
                                                    alt={cls.name}
                                                    width={32}
                                                    height={32}
                                                    className="object-contain scale-[1.15]"
                                                    unoptimized
                                                />
                                            </div>
                                            <div className="flex flex-col min-w-0 w-full overflow-hidden">
                                                <span className="font-semibold text-zinc-100 truncate w-full" title={mule.pseudo}>
                                                    {mule.pseudo}
                                                </span>
                                                <span className="text-[10px] text-zinc-400 uppercase tracking-wider font-medium flex items-center gap-1 mt-0.5" style={{ color: cls.color }}>
                                                    Nv. {mule.level !== undefined ? mule.level : 200}
                                                </span>

                                                {/* Alignment & Order Indicator */}
                                                <div className="flex flex-wrap gap-1 mt-1.5">
                                                    {alignData && alignData.id !== "neutre" && (
                                                        <div className={cn(
                                                            "flex items-center gap-1.5 bg-black/50 border rounded-md px-2 py-0.5 max-w-full",
                                                            alignData.id === "bontarien" ? "border-blue-500/20" : "border-red-500/20"
                                                        )}>
                                                            <div className="relative w-5 h-5 shrink-0 rounded-full overflow-hidden border border-white/10">
                                                                <NextImage src={alignData.icon} alt={alignData.name} fill className="object-cover scale-[1.2]" unoptimized />
                                                            </div>
                                                            <span className={cn(
                                                                "text-[9px] font-bold truncate uppercase tracking-widest",
                                                                alignData.id === "bontarien" ? "text-blue-400" : "text-red-400"
                                                            )}>
                                                                {alignData.name}
                                                            </span>
                                                        </div>
                                                    )}
                                                    {orderData && (
                                                        <div className="flex items-center gap-1.5 bg-black/50 border border-amber-500/20 rounded-md px-2 py-0.5 max-w-full">
                                                            <div className="relative w-5 h-5 shrink-0 bg-black/40 rounded-md border border-white/5 p-0.5 flex items-center justify-center">
                                                                <NextImage 
                                                                    src={orderData.icon} 
                                                                    alt={orderData.name} 
                                                                    fill 
                                                                    className="object-contain"
                                                                    unoptimized
                                                                />
                                                            </div>
                                                            <span className="text-[9px] font-bold text-amber-400 truncate uppercase tracking-widest" title={orderData.name}>
                                                                {orderData.name.replace("Ordre de l'", "").replace("Ordre du ", "")}
                                                            </span>
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        </div>

                                        <div className="flex flex-col gap-1.5 items-end shrink-0">
                                            <Button
                                                variant="ghost"
                                                size="icon"
                                                onClick={() => {
                                                    navigator.clipboard.writeText(`/w ${mule.pseudo} `);
                                                    toast.success("Commande copiée !", { description: `/w ${mule.pseudo}` });
                                                }}
                                                className="h-7 w-7 text-zinc-400 hover:text-white hover:bg-white/10 transition-all bg-black/20 rounded-md"
                                                title="Copier /w"
                                            >
                                                <Copy className="w-3.5 h-3.5" />
                                            </Button>

                                            {isEditing && (
                                                <>
                                                    <Button
                                                        variant="ghost"
                                                        size="icon"
                                                        onClick={() => handleStartEditMule(mule)}
                                                        className={cn(
                                                            "h-7 w-7 transition-all bg-black/20 rounded-md border",
                                                            editingMuleId === mule.id
                                                                ? "border-indigo-500 text-indigo-400 bg-indigo-500/10"
                                                                : "border-white/5 text-zinc-400 hover:text-white hover:bg-white/10"
                                                        )}
                                                        title="Modifier les détails / alignement"
                                                    >
                                                        <Edit2 className="w-3.5 h-3.5" />
                                                    </Button>
                                                    <button
                                                        onClick={() => handleRemovePseudo(mule.id!)}
                                                        className="h-7 w-7 flex items-center justify-center text-red-500 hover:text-white hover:bg-red-500/80 rounded-md transition-all bg-red-500/10"
                                                        title="Supprimer"
                                                    >
                                                        <Trash2 className="w-3.5 h-3.5" />
                                                    </button>
                                                </>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                ) : (
                    <div className="text-sm text-zinc-500 italic py-12 border border-dashed border-white/5 rounded-2xl flex flex-col items-center justify-center bg-zinc-950/20 gap-3">
                        <Users className="w-8 h-8 text-zinc-700" />
                        Aucune mule enregistrée
                    </div>
                )}

                {/* Edit Mode Panel (Addition & Modification Form) */}
                {isEditing && (
                    <div ref={formRef} className="p-4 sm:p-5 bg-zinc-950/60 border border-white/10 rounded-2xl animate-in fade-in duration-200 space-y-5">
                        <div className="flex items-center justify-between">
                            <h4 className="text-sm font-bold text-zinc-200 flex items-center gap-2 uppercase tracking-wide">
                                {editingMuleId ? (
                                    <>
                                        <Edit2 className="w-4 h-4 text-indigo-400" />
                                        Modifier le personnage : <span className="text-indigo-400 italic font-black">{newPseudo}</span>
                                    </>
                                ) : (
                                    <>
                                        <Plus className="w-4 h-4 text-emerald-400" />
                                        Ajouter un personnage
                                    </>
                                )}
                            </h4>
                            {editingMuleId && (
                                <Button 
                                    variant="ghost" 
                                    size="sm" 
                                    onClick={handleCancelFormEdit}
                                    className="h-6 px-2 text-[9px] font-black uppercase tracking-widest text-zinc-400 hover:text-white hover:bg-white/5 rounded-md"
                                >
                                    Mode Ajout
                                </Button>
                            )}
                        </div>

                        {localPseudos.length < maxPseudos || editingMuleId ? (
                            <div className="flex flex-col gap-5">
                                {/* 1. Class Selection Grid */}
                                <div className="grid gap-2 w-full">
                                    <label className="text-[11px] text-zinc-400 font-black uppercase tracking-wider ml-1">Sélectionner une classe</label>
                                    <div className="flex bg-zinc-950/40 p-2 rounded-xl border border-white/5 overflow-x-auto gap-2 custom-scrollbar pb-3 snap-x">
                                        {DOFUS_CLASSES.map((cls) => (
                                            <button
                                                key={cls.id}
                                                type="button"
                                                onClick={() => setNewClass(cls.id)}
                                                className={cn(
                                                    "h-12 w-12 rounded-xl shrink-0 flex items-center justify-center transition-all border snap-center",
                                                    newClass === cls.id
                                                        ? "bg-zinc-800/80 border-white/20 scale-105 z-10"
                                                        : "bg-black/20 border-white/5 opacity-50 hover:opacity-100 hover:bg-zinc-800/50"
                                                )}
                                                style={{
                                                    boxShadow: newClass === cls.id ? `0 0 15px ${cls.color}30, inset 0 0 0 1px ${cls.color}50` : 'none'
                                                }}
                                                title={cls.name}
                                            >
                                                <NextImage
                                                    src={cls.icon}
                                                    alt={cls.name}
                                                    width={28}
                                                    height={28}
                                                    className="object-contain drop-shadow-md animate-in fade-in"
                                                    unoptimized
                                                />
                                            </button>
                                        ))}
                                    </div>
                                </div>

                                {/* 2. Pseudo & Level Fields */}
                                <div className="flex flex-col sm:flex-row gap-4 items-end">
                                    <div className="grid gap-1.5 flex-[2] w-full relative">
                                        <label className="text-[11px] text-zinc-400 font-black uppercase tracking-wider ml-1">Pseudo</label>
                                        <Input
                                            value={newPseudo}
                                            onChange={handleInputChange}
                                            onKeyDown={handleKeyDown}
                                            placeholder="Ex: Darksasuke"
                                            className="bg-zinc-900/80 border-white/10 h-10 pl-10 focus-visible:ring-indigo-500/50 font-medium"
                                            maxLength={20}
                                        />
                                        <div className="absolute left-3 top-[32px] text-zinc-500 text-sm font-mono pointer-events-none">
                                            /w
                                        </div>
                                    </div>

                                    <div className="grid gap-1.5 w-full sm:w-28">
                                        <label className="text-[11px] text-zinc-400 font-black uppercase tracking-wider ml-1">Niveau</label>
                                        <Input
                                            type="number"
                                            min={0}
                                            max={200}
                                            value={newLevel}
                                            onChange={(e) => {
                                                const val = e.target.value;
                                                if (val === "") { setNewLevel(""); return; }
                                                const num = parseInt(val, 10);
                                                if (!isNaN(num)) {
                                                    if (num > 200) setNewLevel("200");
                                                    else if (num < 0) setNewLevel("0");
                                                    else setNewLevel(num.toString());
                                                }
                                            }}
                                            onKeyDown={handleKeyDown}
                                            placeholder="200"
                                            className="bg-zinc-900/80 border-white/10 h-10 focus-visible:ring-indigo-500/50 font-mono text-center font-bold"
                                        />
                                    </div>
                                </div>

                                {/* 3. Optional Alignment & Order Selection */}
                                <div className="grid gap-4 bg-zinc-950/45 p-4 rounded-xl border border-white/5">
                                    <div className="flex flex-col gap-2">
                                        <div className="flex items-center gap-1.5">
                                            <Shield className="w-3.5 h-3.5 text-indigo-400" />
                                            <label className="text-[11px] text-zinc-300 font-black uppercase tracking-wider">Alignement (Optionnel)</label>
                                        </div>
                                        
                                        <div className="flex flex-wrap gap-2">
                                            {ALIGNMENTS.map((align) => {
                                                const isSel = newAlignment === align.id;
                                                return (
                                                    <button
                                                        key={align.id}
                                                        type="button"
                                                        onClick={() => {
                                                            setNewAlignment(align.id);
                                                            if (align.id === "neutre") {
                                                                setNewOrder(null);
                                                            } else {
                                                                const available = (ORDERS as any)[align.id];
                                                                if (available && available.length > 0) {
                                                                    setNewOrder(available[0].id);
                                                                }
                                                            }
                                                        }}
                                                        className={cn(
                                                            "h-12 px-4 rounded-xl flex items-center gap-3 transition-all border text-xs font-bold uppercase tracking-wider relative overflow-hidden",
                                                            isSel 
                                                                ? align.id === "bontarien" ? "bg-blue-500/10 border-blue-500/40 text-blue-400 font-black shadow-[0_0_12px_rgba(59,130,246,0.15)]" :
                                                                  align.id === "brakmarien" ? "bg-red-500/10 border-red-500/40 text-red-400 font-black shadow-[0_0_12px_rgba(239,68,68,0.15)]" :
                                                                  "bg-zinc-800 border-white/20 text-white shadow-[0_0_12px_rgba(255,255,255,0.05)]"
                                                                : "bg-black/20 border-white/5 text-zinc-500 hover:text-zinc-300"
                                                        )}
                                                    >
                                                        <div className="relative w-7 h-7 rounded-full overflow-hidden shrink-0 border border-white/10 shadow-md">
                                                            <NextImage src={align.icon} alt={align.name} fill className="object-cover scale-[1.25]" unoptimized />
                                                        </div>
                                                        {align.name}
                                                    </button>
                                                );
                                            })}
                                        </div>
                                    </div>

                                    {/* Dependent Order Specialization List */}
                                    {newAlignment !== "neutre" && (
                                        <div className="flex flex-col gap-2 pt-2 border-t border-white/5 animate-in fade-in slide-in-from-top-2 duration-300">
                                            <div className="flex items-center gap-1.5">
                                                <Sparkles className="w-3.5 h-3.5 text-amber-400" />
                                                <label className="text-[11px] text-zinc-300 font-black uppercase tracking-wider">Ordre / Spécialisation</label>
                                            </div>
                                            
                                            <div className="grid grid-cols-1 sm:grid-cols-3 gap-2.5">
                                                {(ORDERS as any)[newAlignment].map((order: any) => {
                                                    const isSel = newOrder === order.id;
                                                    return (
                                                        <button
                                                            key={order.id}
                                                            type="button"
                                                            onClick={() => setNewOrder(order.id)}
                                                            className={cn(
                                                                "h-14 px-4 rounded-xl flex items-center gap-3 transition-all border text-left text-[11px] font-black uppercase tracking-widest relative overflow-hidden",
                                                                isSel
                                                                    ? "bg-amber-500/10 border-amber-500/40 text-amber-400 shadow-[0_0_12px_rgba(245,158,11,0.15)]"
                                                                    : "bg-black/20 border-white/5 text-zinc-500 hover:text-zinc-300"
                                                            )}
                                                        >
                                                            <div className="relative w-9 h-9 shrink-0 bg-black/60 rounded-lg border border-white/10 flex items-center justify-center p-1 overflow-hidden shadow-inner">
                                                                <NextImage src={order.icon} alt={order.name} fill className="object-contain p-0.5" unoptimized />
                                                            </div>
                                                            <span className="truncate max-w-[140px]" title={order.name}>
                                                                {order.name.replace("Ordre de l'", "").replace("Ordre du ", "")}
                                                            </span>
                                                        </button>
                                                    );
                                                })}
                                            </div>
                                        </div>
                                    )}
                                </div>

                                {/* Form Submission Action Row */}
                                <div className="flex gap-2 justify-end pt-2">
                                    <Button
                                        variant="sigil-emerald"
                                        onClick={handleAddOrUpdatePseudo}
                                        disabled={!newPseudo.trim()}
                                        className="h-10 px-6 w-full sm:w-auto font-black uppercase tracking-widest text-[10px]"
                                    >
                                        {editingMuleId ? (
                                            <>
                                                <Check className="w-4 h-4 mr-2" /> Valider les Modifs
                                            </>
                                        ) : (
                                            <>
                                                <Plus className="w-4 h-4 mr-2" /> Ajouter
                                            </>
                                        )}
                                    </Button>
                                </div>
                            </div>
                        ) : (
                            <p className="text-xs text-amber-500/90 flex items-center gap-2 bg-amber-500/10 p-3 rounded-lg border border-amber-500/20">
                                <AlertCircle className="w-4 h-4" />
                                Limite de {maxPseudos} personnages atteinte.
                            </p>
                        )}

                        <div className="flex justify-end pt-4 mt-5 border-t border-white/5">
                            <Button
                                onClick={handleSave}
                                disabled={isSubmitting}
                                variant="sigil"
                                className="h-10 px-8 w-full sm:w-auto"
                            >
                                {isSubmitting ? (
                                    <Save className="w-4 h-4 mr-2 animate-spin" />
                                ) : (
                                    <Save className="w-4 h-4 mr-2" />
                                )}
                                {isSubmitting ? "Enregistrement..." : "Enregistrer les Mules"}
                            </Button>
                        </div>
                    </div>
                )}
            </CardContent>
        </Card>
    );
}

"use client";

import { useEffect, useState } from "react";
import Image from "next/image";
import Link from "next/link";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Loader2, Gift, Copy, Check, Bug, ExternalLink } from "lucide-react";
import { getProfileMatchingArchis, type ProfileMatchData } from "@/server/actions/ocre-actions";
import { toast } from "sonner";

interface ArchiMatchingWidgetProps {
    guildId: string;
    profileId: string;
    ownerDisplayName: string;
}

export function ArchiMatchingWidget({
    guildId,
    profileId,
    ownerDisplayName
}: ArchiMatchingWidgetProps) {
    const [matchData, setMatchData] = useState<ProfileMatchData | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [copiedMsg, setCopiedMsg] = useState(false);

    const loadMatches = async () => {
        setLoading(true);
        setError(null);
        const result = await getProfileMatchingArchis({ guildId, targetProfileId: profileId });

        if (result.success) {
            setMatchData(result.data ?? null);
        } else {
            setError(result.error || "Erreur lors du chargement");
        }
        setLoading(false);
    };

    useEffect(() => {
        loadMatches();
    }, [guildId, profileId]);

    const handleCopyMP = () => {
        if (!matchData || matchData.matches.length === 0) return;

        const monsterNames = matchData.matches.slice(0, 3).map(m => m.nom).join(", ");
        const extra = matchData.matches.length > 3 ? ` et ${matchData.matches.length - 3} autres` : "";
        const message = `/w ${ownerDisplayName} Salut ! Tu aurais un de ces archis à échanger ? ${monsterNames}${extra} :)`;

        navigator.clipboard.writeText(message);
        setCopiedMsg(true);
        toast.success("Message copié !");
        setTimeout(() => setCopiedMsg(false), 2000);
    };

    // Don't render anything if no data or viewer doesn't have Metamob linked
    if (!loading && !matchData) {
        return null;
    }

    // Don't render if no matches
    if (!loading && matchData && matchData.matches.length === 0) {
        return null;
    }

    return (
        <Card className="border-primary/30 bg-gradient-to-br from-primary/5 to-transparent">
            <CardHeader className="pb-3">
                <CardTitle className="flex items-center gap-2 text-base">
                    <Gift className="h-5 w-5 text-primary" />
                    Échanges possibles
                </CardTitle>
            </CardHeader>
            <CardContent>
                {loading ? (
                    <div className="flex items-center justify-center py-6">
                        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
                    </div>
                ) : error ? (
                    <p className="text-sm text-muted-foreground text-center py-4">{error}</p>
                ) : matchData && matchData.matches.length > 0 ? (
                    <div className="space-y-3">
                        <p className="text-sm text-muted-foreground">
                            <span className="font-medium text-foreground">{ownerDisplayName}</span> a{" "}
                            <span className="text-primary font-semibold">{matchData.matches.length}</span>{" "}
                            archi{matchData.matches.length > 1 ? "s" : ""} que vous recherchez :
                        </p>

                        <ScrollArea className="h-[160px]">
                            <div className="grid grid-cols-2 gap-2 pr-2">
                                {matchData.matches.map((match) => (
                                    <div
                                        key={match.id}
                                        className="flex items-center gap-2 p-2 rounded-lg bg-card/50 border border-border/50"
                                    >
                                        {match.imageUrl && (
                                            <div className="relative w-8 h-8 shrink-0 rounded overflow-hidden bg-black/20">
                                                <Image
                                                    src={match.imageUrl}
                                                    alt={match.nom}
                                                    fill
                                                    className="object-contain"
                                                    sizes="32px"
                                                />
                                            </div>
                                        )}
                                        <div className="flex-1 min-w-0">
                                            <p className="text-xs font-medium truncate">{match.nom}</p>
                                            <p className="text-[10px] text-muted-foreground truncate">
                                                {match.zone}
                                            </p>
                                        </div>
                                        <Badge
                                            variant="outline"
                                            className="shrink-0 text-[10px] px-1.5 bg-amber-500/10 text-amber-500 border-amber-500/30"
                                        >
                                            x{match.ownerQuantite}
                                        </Badge>
                                    </div>
                                ))}
                            </div>
                        </ScrollArea>

                        <div className="flex gap-2 pt-2 border-t border-border/30">
                            <Button
                                variant="outline"
                                size="sm"
                                className="flex-1 gap-2"
                                onClick={handleCopyMP}
                            >
                                {copiedMsg ? (
                                    <Check className="h-4 w-4 text-emerald-500" />
                                ) : (
                                    <Copy className="h-4 w-4" />
                                )}
                                Copier MP
                            </Button>
                            <Button
                                variant="default"
                                size="sm"
                                className="flex-1 gap-2"
                                asChild
                            >
                                <Link href={`/dashboard/${guildId}/archimonstres`}>
                                    <Bug className="h-4 w-4" />
                                    Bourse
                                </Link>
                            </Button>
                        </div>
                    </div>
                ) : null}
            </CardContent>
        </Card>
    );
}

"use client";

import { useState, useCallback, useMemo, useEffect } from "react";
import { cn } from "@/lib/utils";
import { DAYS_OF_WEEK, TIME_SLOTS, type AvailabilityMap, type DayOfWeek, type TimeSlot, type GlobalAvailability } from "@/lib/dofus-assets";
import { useDebouncedCallback } from "use-debounce";
import { Clock, Sunrise, Sun, Moon, ChevronLeft, ChevronRight, CalendarDays, Plane } from "lucide-react";
import { format, addWeeks, startOfWeek, endOfWeek, isWithinInterval, getISOWeek, getYear } from "date-fns";
import { fr } from "date-fns/locale";

interface AvailabilityHeatmapProps {
    availability?: GlobalAvailability | AvailabilityMap; // Accept both for compatibility
    onSave?: (availability: GlobalAvailability) => void;
    readOnly?: boolean;
    vacationStart?: Date | null;
    vacationEnd?: Date | null;
}

const TIME_SLOT_LABELS: Record<TimeSlot, string> = {
    matin: "Matin",
    midi: "Après-midi",
    soir: "Soir",
    nuit: "Nuit"
};

const TIME_SLOT_HOURS: Record<TimeSlot, string> = {
    matin: "6h - 12h",
    midi: "12h - 18h",
    soir: "18h - 00h",
    nuit: "00h - 6h"
};

const TIME_SLOT_ICONS: Record<TimeSlot, React.ReactNode> = {
    matin: <Sunrise className="w-4 h-4" />,
    midi: <Sun className="w-4 h-4" />,
    soir: <Moon className="w-4 h-4" />,
    nuit: <Moon className="w-4 h-4 text-indigo-400" />
};

const TIME_SLOT_COLORS: Record<TimeSlot, { bg: string; border: string; glow: string; text: string }> = {
    matin: {
        bg: "bg-orange-500/20",
        border: "border-orange-500/50",
        glow: "shadow-[0_0_10px_rgba(249,115,22,0.3)]",
        text: "text-orange-400",
    },
    midi: {
        bg: "bg-amber-400/20",
        border: "border-amber-400/50",
        glow: "shadow-[0_0_10px_rgba(251,191,36,0.3)]",
        text: "text-amber-400",
    },
    soir: {
        bg: "bg-violet-500/20",
        border: "border-violet-500/50",
        glow: "shadow-[0_0_10px_rgba(139,92,246,0.3)]",
        text: "text-violet-400",
    },
    nuit: {
        bg: "bg-indigo-500/20",
        border: "border-indigo-500/50",
        glow: "shadow-[0_0_10px_rgba(99,102,241,0.3)]",
        text: "text-indigo-400",
    },
};

const DAY_LABELS: Record<DayOfWeek, string> = {
    lundi: "Lun",
    mardi: "Mar",
    mercredi: "Mer",
    jeudi: "Jeu",
    vendredi: "Ven",
    samedi: "Sam",
    dimanche: "Dim",
};

export function AvailabilityHeatmap({
    availability = {},
    onSave,
    readOnly = false,
    vacationStart,
    vacationEnd
}: AvailabilityHeatmapProps) {
    // -------------------------------------------------------------------------
    // STATE: MIGRATION & DATA
    // -------------------------------------------------------------------------

    // Normalize input data to GlobalAvailability structure
    const initialData: GlobalAvailability = useMemo(() => {
        // Check if it's legacy data (simple map)
        const isLegacy = Object.keys(availability).some(k => DAYS_OF_WEEK.includes(k as any));

        if (isLegacy) {
            return {
                template: availability as AvailabilityMap,
                weeks: {}
            };
        }

        return (availability as GlobalAvailability).template ? (availability as GlobalAvailability) : { template: {}, weeks: {} };
    }, [availability]);

    const [globalData, setGlobalData] = useState<GlobalAvailability>(initialData);

    // Week Navigation State (0 = current week)
    const [weekOffset, setWeekOffset] = useState(0);
    const [hoveredSlot, setHoveredSlot] = useState<{ day: DayOfWeek, slot: TimeSlot } | null>(null);

    // -------------------------------------------------------------------------
    // HELPERS: DATE & KEYS
    // -------------------------------------------------------------------------

    // Get current view's reference date (Monday of the selected week)
    const currentMonday = useMemo(() => {
        const now = new Date();
        const start = startOfWeek(now, { weekStartsOn: 1 }); // Monday
        return addWeeks(start, weekOffset);
    }, [weekOffset]);

    // Generate Key for current week: "YYYY-W#"
    const currentWeekKey = useMemo(() => {
        const year = getYear(currentMonday);
        const week = getISOWeek(currentMonday);
        return `${year}-W${week}`;
    }, [currentMonday]);

    // Get actual dates for headers
    const weekDates = useMemo(() => {
        const dates: Record<DayOfWeek, Date> = {} as any;
        DAYS_OF_WEEK.forEach((day, idx) => {
            const date = new Date(currentMonday);
            date.setDate(currentMonday.getDate() + idx);
            dates[day] = date;
        });
        return dates;
    }, [currentMonday]);

    // -------------------------------------------------------------------------
    // LOGIC: GET & SET SLOTS
    // -------------------------------------------------------------------------

    // Get effective availability for current view
    // Priority: Specific Week > Template > Empty
    const currentWeekData = useMemo(() => {
        return globalData.weeks?.[currentWeekKey] || globalData.template || {};
    }, [globalData, currentWeekKey]);

    const isSlotActive = useCallback((day: DayOfWeek, slot: TimeSlot) => {
        return currentWeekData[day]?.includes(slot) ?? false;
    }, [currentWeekData]);

    const isVacation = useCallback((day: DayOfWeek) => {
        if (!vacationStart || !vacationEnd) return false;
        const date = weekDates[day];
        // Normalize time for comparison
        const d = new Date(date); d.setHours(12, 0, 0, 0);
        const start = new Date(vacationStart); start.setHours(0, 0, 0, 0);
        const end = new Date(vacationEnd); end.setHours(23, 59, 59, 999);
        return d >= start && d <= end;
    }, [weekDates, vacationStart, vacationEnd]);

    const debouncedSave = useDebouncedCallback((data: GlobalAvailability) => {
        onSave?.(data);
    }, 1000);

    const toggleSlot = (day: DayOfWeek, slot: TimeSlot) => {
        if (readOnly) return;
        if (isVacation(day)) return;
        if (isPast(day)) return; // Prevent editing past dates

        setGlobalData(prev => {
            // ... (rest of logic same as before, just ensuring we don't break indentation, but since I'm replacing the whole function start, I need to be careful. Actually, I will just replace the specific lines in the loop and the toggle function, but this tool requires contiguous blocks. I'll split into two edits for safety or replace the whole block if confident.)
            // Wait, I can't replace `toggleSlot` AND the render loop in one contiguous block easily without including a huge chunk.
            // I will replace `toggleSlot` first.
            const existingWeekData = prev.weeks?.[currentWeekKey];
            const baseData = existingWeekData || prev.template || {};

            const currentSlots = baseData[day] || [];
            const newSlots = currentSlots.includes(slot)
                ? currentSlots.filter(s => s !== slot)
                : [...currentSlots, slot];

            const newWeekData = {
                ...baseData,
                [day]: newSlots
            };

            const newData = {
                ...prev,
                weeks: {
                    ...(prev.weeks || {}),
                    [currentWeekKey]: newWeekData
                }
            };

            debouncedSave(newData);
            return newData;
        });
    };

    // -------------------------------------------------------------------------
    // UI RENDER
    // -------------------------------------------------------------------------

    const isToday = (day: DayOfWeek) => {
        const today = new Date();
        const date = weekDates[day];
        return today.getDate() === date.getDate() &&
            today.getMonth() === date.getMonth() &&
            today.getFullYear() === date.getFullYear();
    };

    const isPast = (day: DayOfWeek) => {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const date = new Date(weekDates[day]);
        date.setHours(0, 0, 0, 0);
        return date < today;
    };

    return (
        <div className="p-6 bg-black/20 backdrop-blur-md rounded-2xl border border-white/10 h-full flex flex-col relative overflow-hidden">

            {/* Header Controls */}
            <div className="flex flex-col sm:flex-row items-center justify-between mb-6 gap-4">
                <div className="flex items-center gap-2">
                    <Clock className="w-5 h-5 text-zinc-400" />
                    <div>
                        <h3 className="text-sm font-medium text-zinc-300">Disponibilités</h3>
                        <p className="text-xs text-zinc-500">
                            Semaine {getISOWeek(currentMonday)} • Année {getYear(currentMonday)}
                        </p>
                    </div>
                </div>

                <div className="flex items-center gap-2 bg-zinc-950/50 p-1 rounded-lg border border-white/5">
                    <button
                        onClick={() => setWeekOffset(prev => prev - 1)}
                        className="p-1.5 hover:bg-white/5 rounded-md text-zinc-400 hover:text-white transition-colors"
                    >
                        <ChevronLeft className="w-4 h-4" />
                    </button>
                    <div className="px-2 text-xs font-medium text-zinc-300 min-w-[140px] text-center flex items-center justify-center gap-2">
                        <CalendarDays className="w-3.5 h-3.5 opacity-70" />
                        {weekOffset === 0 ? "Cette semaine" : format(currentMonday, "d MMMM", { locale: fr }) + " - " + format(endOfWeek(currentMonday, { weekStartsOn: 1 }), "d MMMM", { locale: fr })}
                    </div>
                    <button
                        onClick={() => setWeekOffset(prev => prev + 1)}
                        className="p-1.5 hover:bg-white/5 rounded-md text-zinc-400 hover:text-white transition-colors"
                    >
                        <ChevronRight className="w-4 h-4" />
                    </button>
                </div>
            </div>

            {/* Heatmap Grid */}
            <div className="flex-1 overflow-x-auto min-h-[220px] flex items-center justify-center">
                <div className="relative">
                    <table className="w-full border-separate border-spacing-1.5 ">
                        <thead>
                            <tr>
                                <th className="w-24"></th>
                                {DAYS_OF_WEEK.map(day => {
                                    const date = weekDates[day];
                                    const isVacationDay = isVacation(day);

                                    return (
                                        <th key={day} className="text-center w-14 pb-2 relative group">
                                            <div className={cn(
                                                "flex flex-col items-center gap-1 py-1 px-2 rounded-lg transition-colors border",
                                                isToday(day)
                                                    ? "bg-primary/10 border-primary/30"
                                                    : "border-transparent",
                                                isVacationDay && "opacity-50 grayscale"
                                            )}>
                                                <span className={cn(
                                                    "text-xs font-semibold uppercase tracking-wider",
                                                    isToday(day) ? "text-primary" : "text-zinc-500"
                                                )}>
                                                    {DAY_LABELS[day]}
                                                </span>
                                                <span className={cn(
                                                    "text-lg font-bold",
                                                    isToday(day) ? "text-primary" : "text-zinc-600"
                                                )}>
                                                    {date.getDate()}
                                                </span>
                                            </div>

                                            {/* Vacation Indicator Badge */}
                                            {isVacationDay && (
                                                <div className="absolute -top-3 left-1/2 -translate-x-1/2 bg-cyan-500/90 text-[9px] text-zinc-950 font-bold px-1.5 py-0.5 rounded-full z-10 flex items-center gap-1 shadow-lg">
                                                    <Plane className="w-2.5 h-2.5" />
                                                </div>
                                            )}
                                        </th>
                                    );
                                })}
                            </tr>
                        </thead>
                        <tbody>
                            {TIME_SLOTS.map(slot => {
                                const colors = TIME_SLOT_COLORS[slot];
                                return (
                                    <tr key={slot}>
                                        <td className="py-1 pr-3">
                                            <div className="flex items-center gap-2">
                                                <span className={cn("shrink-0", colors.text)}>
                                                    {TIME_SLOT_ICONS[slot]}
                                                </span>
                                                <div className="flex flex-col">
                                                    <span className="text-xs font-medium text-zinc-400">
                                                        {TIME_SLOT_LABELS[slot]}
                                                    </span>
                                                    <span className="text-[10px] text-zinc-600">
                                                        {TIME_SLOT_HOURS[slot]}
                                                    </span>
                                                </div>
                                            </div>
                                        </td>
                                        {DAYS_OF_WEEK.map(day => {
                                            const isActive = isSlotActive(day, slot);
                                            const isVacationDay = isVacation(day);
                                            const isPastDay = isPast(day);
                                            const isHovered = hoveredSlot?.day === day && hoveredSlot?.slot === slot;

                                            return (
                                                <td key={`${day}-${slot}`} className="p-0 relative">
                                                    <button
                                                        onClick={() => toggleSlot(day, slot)}
                                                        onMouseEnter={() => !readOnly && setHoveredSlot({ day, slot })}
                                                        onMouseLeave={() => !readOnly && setHoveredSlot(null)}
                                                        disabled={readOnly || isVacationDay || isPastDay}
                                                        className={cn(
                                                            "w-14 h-11 rounded-lg transition-all duration-200 border transform relative overflow-hidden",
                                                            // Normal State (Active Future)
                                                            !isVacationDay && !isPastDay && isActive
                                                                ? cn(colors.bg, colors.border, "shadow-sm")
                                                                : "bg-white/10 border-white/5",

                                                            // Hover States (Active Future)
                                                            !readOnly && !isVacationDay && !isPastDay && isHovered && !isActive && "scale-105 bg-white/20 border-white/20",
                                                            !readOnly && !isVacationDay && !isPastDay && isHovered && isActive && cn("scale-105", colors.bg, colors.border),

                                                            // Past State
                                                            isPastDay && "cursor-not-allowed opacity-30 grayscale brightness-50 border-transparent",

                                                            // Vacation State (High Contrast Fix)
                                                            isVacationDay && !isPastDay && "cursor-not-allowed opacity-70 bg-red-900/10 border-red-500/20 grayscale-0",
                                                            readOnly && "cursor-default"
                                                        )}
                                                    >
                                                        {/* Active Dot */}
                                                        <div className={cn(
                                                            "w-full h-full flex items-center justify-center transition-all",
                                                            isActive && !isVacationDay ? "opacity-100" : "opacity-0"
                                                        )}>
                                                            <div className={cn(
                                                                "w-2.5 h-2.5 rounded-full shadow-sm",
                                                                slot === "matin" && "bg-orange-400",
                                                                slot === "midi" && "bg-amber-400",
                                                                slot === "soir" && "bg-violet-400",
                                                                slot === "nuit" && "bg-indigo-400"
                                                            )} />
                                                        </div>

                                                        {/* Vacation Strikethrough (Brighter Red) */}
                                                        {isVacationDay && (
                                                            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                                                                <div className="w-[140%] h-[2px] bg-red-500/60 rotate-45 transform shadow-[0_0_4px_rgba(239,68,68,0.4)]" />
                                                            </div>
                                                        )}
                                                    </button>
                                                </td>
                                            );
                                        })}
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Minimal Legend */}
            <div className="flex items-center justify-center gap-4 mt-6 pt-4 border-t border-white/5 text-[10px] text-zinc-500">
                <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded-full bg-orange-400" /> Matin</div>
                <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded-full bg-amber-400" /> Midi</div>
                <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded-full bg-violet-400" /> Soir</div>
                <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded-full bg-indigo-400" /> Nuit</div>
                <div className="flex items-center gap-1.5 ml-4 text-cyan-500/50"><Plane className="w-3 h-3" /> Absent (Congés)</div>
            </div>
        </div>
    );
}

