'use client'

import { useState, useEffect } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { getMemberDreamRuns } from "@/server/actions/songes/dream-run-actions";
import { Loader2, History, Trophy, Skull, Ban } from "lucide-react";
import { format } from "date-fns";
import { fr } from "date-fns/locale";
import { cn } from "@/lib/utils";
import Image from "next/image";

export function DreamRunHistory({ guildId, userId }: { guildId: string, userId?: string }) {
    const [runs, setRuns] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        async function fetchHistory() {
            const res = await getMemberDreamRuns(guildId, userId);
            if (res.success && res.runs) {
                setRuns(res.runs);
            }
            setIsLoading(false);
        }
        fetchHistory();
    }, [guildId, userId]);

    if (isLoading) {
        return (
            <div className="flex items-center justify-center p-8">
                <Loader2 className="w-6 h-6 animate-spin text-zinc-500" />
            </div>
        );
    }

    if (runs.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center p-8 text-center space-y-3 bg-zinc-900/50 rounded-xl border border-dashed border-zinc-800">
                <History className="w-8 h-8 text-zinc-700" />
                <p className="text-sm text-zinc-500 font-medium">Aucun historique de Songes pour le moment.</p>
            </div>
        );
    }

    return (
        <div className="space-y-4">
            {runs.map((run) => {
                const difficultyColor = run.difficulty.startsWith('CAUCHEMAR') ? "text-red-400" :
                    run.difficulty.startsWith('PARADOXE') ? "text-amber-400" :
                        "text-cyan-400";

                return (
                    <Card key={run.id} className="bg-zinc-900/40 border-zinc-800 hover:border-zinc-700 transition-all group overflow-hidden">
                        <CardContent className="p-4 flex flex-col sm:flex-row items-center justify-between gap-4">
                            <div className="flex items-center gap-4 w-full">
                                <div className={cn(
                                    "w-10 h-10 rounded-lg flex items-center justify-center shrink-0 border shadow-inner",
                                    run.status === 'COMPLETED' ? "bg-emerald-500/10 border-emerald-500/30 text-emerald-400" :
                                        run.status === 'FAILED' ? "bg-red-500/10 border-red-500/30 text-red-400" :
                                            "bg-zinc-500/10 border-zinc-500/30 text-zinc-400"
                                )}>
                                    {run.status === 'COMPLETED' ? <Trophy className="w-5 h-5" /> :
                                        run.status === 'FAILED' ? <Skull className="w-5 h-5" /> :
                                            <Ban className="w-5 h-5" />}
                                </div>

                                <div className="min-w-0 flex-grow">
                                    <div className="flex flex-wrap items-center gap-2">
                                        <h4 className={cn("font-bold truncate", difficultyColor)}>
                                            {run.difficulty.replace('_', ' ')}
                                        </h4>
                                        <Badge variant="outline" className="text-[10px] uppercase font-black tracking-tight bg-zinc-900/50">
                                            {run._count.floors} ÉTAGES
                                        </Badge>
                                        <Badge variant="secondary" className={cn(
                                            "text-[9px] h-4 px-1.5 font-bold",
                                            run.status === 'COMPLETED' ? "bg-emerald-500/20 text-emerald-300" :
                                                run.status === 'FAILED' ? "bg-red-500/20 text-red-300" :
                                                    "bg-zinc-800 text-zinc-400"
                                        )}>
                                            {run.status === 'COMPLETED' ? 'SUCCÈS' : run.status === 'FAILED' ? 'ÉCHEC' : 'ABANDON'}
                                        </Badge>
                                    </div>
                                    <div className="text-[11px] font-medium text-zinc-500 mt-0.5">
                                        {run.completedAt ? format(new Date(run.completedAt), "d MMM yyyy 'à' HH:mm", { locale: fr }) : 'Date inconnue'}
                                    </div>
                                </div>
                            </div>

                            <div className="flex items-center gap-6 w-full sm:w-auto justify-between sm:justify-end">
                                <div className="flex -space-x-2 overflow-hidden">
                                    {run.members.map((member: any) => {
                                        const profile = member.user?.profiles?.[0];
                                        const pseudo = profile?.pseudoDofus || member.user?.name || "?";
                                        const classe = profile?.classe;

                                        return (
                                            <div
                                                key={member.id}
                                                className="relative inline-block h-8 w-8 rounded-full ring-2 ring-zinc-900 bg-zinc-800 flex items-center justify-center overflow-hidden hover:z-10 transition-all border border-white/5"
                                                title={`${pseudo} (${classe || "Inconnue"})`}
                                            >
                                                {member.user?.image ? (
                                                    <Image src={member.user.image} alt={pseudo} fill className="object-cover opacity-60 group-hover:opacity-100 transition-opacity" />
                                                ) : (
                                                    <div className="text-[10px] font-bold text-zinc-600 uppercase">{pseudo.slice(0, 2)}</div>
                                                )}
                                                <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent pointer-events-none" />
                                                <div className="absolute bottom-0 inset-x-0 h-0.5 bg-indigo-500 opacity-0 group-hover:opacity-100" />
                                            </div>
                                        );
                                    })}
                                </div>

                                <div className="text-right shrink-0">
                                    <div className="text-sm font-black text-rose-500 leading-none">
                                        {run.pointsReve || 0} PR
                                    </div>
                                    <div className="text-[10px] font-bold text-zinc-600 uppercase tracking-tighter mt-1">
                                        SCORE FINAL
                                    </div>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                );
            })}
        </div>
    );
}

"use client";

import { useState } from "react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Crown, Palmtree, Award, Medal, Star, ShieldCheck, Sparkles, UserCircle, Link2, Check } from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { fr } from "date-fns/locale";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import type { ContributorTier } from "@/server/actions/profile-actions";

// Tier configuration
const TIER_CONFIG = {
    LEGENDE: {
        label: "Légende",
        icon: Crown,
        bgColor: "bg-amber-500/15",
        textColor: "text-amber-400",
        borderColor: "border-amber-500/30",
        hoverColor: "hover:bg-amber-500/20",
        iconFill: "fill-amber-500/20",
    },
    CHAMPION: {
        label: "Champion",
        icon: Award,
        bgColor: "bg-slate-400/15",
        textColor: "text-slate-300",
        borderColor: "border-slate-400/30",
        hoverColor: "hover:bg-slate-400/20",
        iconFill: "fill-slate-400/20",
    },
    PILIER: {
        label: "Pilier",
        icon: Medal,
        bgColor: "bg-orange-600/15",
        textColor: "text-orange-400",
        borderColor: "border-orange-600/30",
        hoverColor: "hover:bg-orange-600/20",
        iconFill: "fill-orange-600/20",
    },
} as const;

interface HeroHeaderProps {
    avatarUrl?: string | null;
    displayName: string;
    roleColor?: number;
    contributorTier?: ContributorTier | null;
    rank?: number;
    isOnVacation?: boolean;
    isUpcomingVacation?: boolean;
    vacationStart?: Date | null;
    vacationEnd?: Date | null;
    joinedAt?: string | Date | null;
    isAdmin?: boolean;
    canViewMissions?: boolean;
    canViewLadder?: boolean;
    guildName?: string;
    sigilRoles?: any[];
    discordRoleName?: string;
    discordRoleColor?: number;
    welcomeBadgeName?: string | null;
    /** Le slug de partage (pseudoDofus encodé ou profileId en fallback) */
    shareSlug?: string | null;
    /** L'ID de la guilde — nécessaire pour construire le lien de partage */
    guildId?: string | null;
    /** Si true, on est en lecture seule (profil d'un autre membre) : on masque le bouton Partager */
    readOnly?: boolean;
}

export function HeroHeader({
    avatarUrl,
    displayName,
    roleColor = 0,
    contributorTier = null,
    rank,
    isOnVacation = false,
    isUpcomingVacation = false,
    vacationStart,
    vacationEnd,
    joinedAt,
    isAdmin = false,
    canViewMissions = true,
    canViewLadder = true,
    guildName = "Guilde",
    sigilRoles = [],
    discordRoleName,
    discordRoleColor,
    welcomeBadgeName,
    shareSlug,
    guildId,
    readOnly = false,
}: HeroHeaderProps) {
    const [copied, setCopied] = useState(false);

    const handleShare = async () => {
        if (!shareSlug || !guildId) return;
        const url = `${window.location.origin}/dashboard/${guildId}/members/${shareSlug}`;
        try {
            await navigator.clipboard.writeText(url);
            setCopied(true);
            toast.success("Lien copié !", {
                description: "Partage ce lien avec les membres de ta guilde.",
                duration: 3000,
            });
            setTimeout(() => setCopied(false), 2500);
        } catch {
            toast.error("Impossible de copier le lien.");
        }
    };

    const roleHexColor = roleColor > 0
        ? `#${roleColor.toString(16).padStart(6, "0")}`
        : "#8b5cf6"; // Default purple

    const tierConfig = contributorTier ? TIER_CONFIG[contributorTier] : null;
    const TierIcon = tierConfig?.icon || Star;

    return (
        <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-gradient-to-br from-zinc-900/90 to-zinc-950/90 backdrop-blur-xl">
            {/* Background Gradient */}
            <div
                className="absolute inset-0 opacity-30"
                style={{
                    background: `linear-gradient(135deg, ${roleHexColor}15 0%, transparent 50%, ${roleHexColor}10 100%)`
                }}
            />

            {/* Content */}
            <div className="relative z-10 p-6 md:p-8">
                {/* Share Button — only on own profile */}
                {!readOnly && shareSlug && guildId && (
                    <div className="absolute top-4 right-4 z-20">
                        <Button
                            id="profile-share-btn"
                            size="sm"
                            onClick={handleShare}
                            className={cn(
                                "gap-2 transition-all duration-500 group overflow-hidden relative border shadow-lg",
                                copied 
                                    ? "bg-emerald-500/20 border-emerald-500/50 text-emerald-400 shadow-[0_0_30px_rgba(16,185,129,0.2)] hover:bg-emerald-500/30"
                                    : "bg-indigo-600/20 border-indigo-500/30 text-indigo-300 hover:bg-indigo-600/40 hover:border-indigo-400/50 hover:text-indigo-200 shadow-[0_0_20px_rgba(79,70,229,0.15)] hover:shadow-[0_0_30px_rgba(79,70,229,0.3)]"
                            )}
                        >
                            {/* Hover Glow Effect inside button */}
                            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent opacity-0 group-hover:opacity-100 group-hover:translate-x-full transition-all duration-1000 -skew-x-12" />

                            {copied ? (
