                                {displayName}
                            </h1>
                        </div>

                        {/* Status Badges */}
                        <div className="flex flex-wrap gap-2 justify-center md:justify-start mb-4">
                            {isAdmin && (
                                <Badge className="bg-purple-500/15 text-purple-300 border-purple-500/30 hover:bg-purple-500/20 font-black uppercase tracking-[0.1em] text-[10px] py-1">
                                    <ShieldCheck className="w-3.5 h-3.5 mr-1.5" />
                                    Administration
                                </Badge>
                            )}
                            {tierConfig && (
                                <Badge className={cn(tierConfig.bgColor, tierConfig.textColor, tierConfig.borderColor, tierConfig.hoverColor)}>
                                    <TierIcon className="w-3 h-3 mr-1" />
                                    {tierConfig.label}
                                    {rank && <span className="ml-1 opacity-70">#{rank}</span>}
                                </Badge>
                            )}
                            {isOnVacation && (
                                <Badge className="bg-cyan-500/15 text-cyan-400 border-cyan-500/30 hover:bg-cyan-500/20">
                                    <Palmtree className="w-3 h-3 mr-1" />
                                    En Congés
                                </Badge>
                            )}
                            {isUpcomingVacation && vacationStart && (
                                <Badge variant="outline" className="bg-orange-500/10 text-orange-400 border-orange-500/30 hover:bg-orange-500/20">
                                    <Palmtree className="w-3 h-3 mr-1" />
                                    Absence : {vacationStart.toLocaleDateString("fr-FR", { day: 'numeric', month: 'short' })}
                                </Badge>
                            )}
                            {joinedAt && (
                                <Badge variant="outline" className="bg-white/5 text-zinc-400 border-white/10">
                                    Membre depuis {new Date(joinedAt).toLocaleDateString("fr-FR", { month: 'long', year: 'numeric' })}
                                </Badge>
                            )}

                            {sigilRoles.filter(g => g.role?.slug !== "probation").map((grant: any) => (
                                <Badge
                                    key={grant.id}
                                    className="bg-amber-500/15 text-amber-300 border-amber-500/30 hover:bg-amber-500/20 font-black uppercase tracking-[0.1em] text-[10px] py-1 gap-1.5"
                                >
                                    <Sparkles className="w-3 h-3" />
                                    {grant.label}
                                    {grant.expiresAt && (
                                        <span className="opacity-50 text-[9px] font-medium lowercase italic">
                                            expire {formatDistanceToNow(new Date(grant.expiresAt), { addSuffix: true, locale: fr })}
                                        </span>
                                    )}
                                </Badge>
                            ))}

                            {/* Specific NEW/PROBATION Badge - High Visibility */}
                            {welcomeBadgeName && sigilRoles.filter(g => g.role?.slug === "probation").map((grant: any) => (
                                <Badge
                                    key={grant.id}
                                    className="bg-indigo-500/30 text-indigo-300 border-indigo-500/40 hover:bg-indigo-500/40 font-black uppercase tracking-[0.1em] text-[11px] py-1 gap-2 shadow-[0_0_20px_rgba(99,102,241,0.2)]"
                                >
                                    <Sparkles className="w-3.5 h-3.5 fill-indigo-400/20" />
                                    {welcomeBadgeName}
                                    {grant.expiresAt && (
                                        <span className="opacity-60 text-[9px] font-medium lowercase italic border-l border-indigo-500/30 pl-2">
                                            expire {formatDistanceToNow(new Date(grant.expiresAt), { addSuffix: true, locale: fr })}
                                        </span>
                                    )}
                                </Badge>
                            ))}

                            {discordRoleName && (
                                <Badge
                                    variant="outline"
                                    className="font-bold uppercase tracking-[0.1em] text-[10px] py-1 border-white/10 bg-white/5"
                                    style={{
                                        color: discordRoleColor && discordRoleColor > 0
                                            ? `#${discordRoleColor.toString(16).padStart(6, "0")}`
                                            : "#94a3b8"
                                    }}
                                >
                                    <UserCircle className="w-3.5 h-3.5 mr-1.5" />
                                    {discordRoleName}
                                </Badge>
                            )}
                        </div>

                        {/* Stats Grid Removed - Redundant with Stats Tab */}
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Crown, Palmtree } from "lucide-react";
import { cn } from "@/lib/utils";

interface IdentityCardProps {
    avatarUrl?: string | null;
    displayName: string;
    roleColor?: number;
    isTopContributor?: boolean;
    isOnVacation?: boolean;
    joinedAt?: Date | null;
}

export function IdentityCard({
    avatarUrl,
    displayName,
    roleColor = 0,
    isTopContributor = false,
    isOnVacation = false,
    joinedAt,
}: IdentityCardProps) {
    const borderColor = roleColor > 0
        ? `#${roleColor.toString(16).padStart(6, "0")}`
        : undefined;

    return (
        <div className="relative overflow-hidden p-6 bg-zinc-900/60 rounded-2xl border border-white/5 h-full flex flex-col items-center justify-between group">

            {/* Background Gradient Effect */}
            <div
                className="absolute inset-x-0 -top-24 h-48 bg-gradient-to-b from-primary/10 to-transparent blur-3xl opacity-50 pointer-events-none group-hover:opacity-75 transition-opacity duration-700"
                style={borderColor ? { background: `linear-gradient(to bottom, ${borderColor}20, transparent)` } : undefined}
            />

            <div className="flex flex-col items-center w-full z-10">
                {/* Avatar with Role Border and Badges */}
                <div className="relative mb-4 ring-offset-[3px] ring-offset-zinc-950/0 rounded-full transition-all duration-500 hover:scale-105">
                    {/* Glow behind Avatar */}
                    <div
                        className="absolute inset-0 rounded-full blur-[20px] opacity-20 transition-opacity duration-500 group-hover:opacity-40"
                        style={{ backgroundColor: borderColor || "#ffffff" }}
                    />

                    <Avatar
                        className="w-28 h-28 border-[3px] shadow-2xl relative z-10"
                        style={{ borderColor: borderColor || "rgba(255,255,255,0.1)" }}
                    >
                        <AvatarImage src={avatarUrl || ""} alt={displayName} className="object-cover" />
                        <AvatarFallback className="text-4xl font-bold bg-zinc-900 text-zinc-300">
                            {displayName?.[0]?.toUpperCase() ?? "?"}
                        </AvatarFallback>
                    </Avatar>

                    {/* Top Contributor Crown Badge */}
                    {isTopContributor && (
                        <div className="absolute -top-1 -right-1 z-20 p-1.5 bg-zinc-900 rounded-full border border-amber-500/30 shadow-lg shadow-amber-500/20" title="Top Contributeur">
                            <Crown className="w-5 h-5 text-amber-500 fill-amber-500/20" />
                        </div>
                    )}

                    {/* Vacation Badge */}
                    {isOnVacation && (
                        <div className="absolute -bottom-1 -right-1 z-20 p-1.5 bg-zinc-900 rounded-full border border-cyan-500/30 shadow-lg shadow-cyan-500/20" title="En Vacances">
                            <Palmtree className="w-5 h-5 text-cyan-400 fill-cyan-400/20" />
                        </div>
                    )}
                </div>

                {/* Name */}
                <h2 className="text-2xl font-bold text-white tracking-tight text-center mb-1">
                    {displayName}
                </h2>

                {roleColor > 0 && (
                    <div className="h-1 w-12 rounded-full mb-4 opacity-50" style={{ backgroundColor: borderColor }} />
                )}

                {/* Badges Row - Only if badges exist */}
                {(isTopContributor || isOnVacation) && (
                    <div className="flex flex-wrap gap-2 justify-center mb-2">
                        {isTopContributor && (
                            <Badge variant="secondary" className="bg-amber-500/10 text-amber-500 hover:bg-amber-500/20 border-amber-500/20">
                                Top Contributeur
                            </Badge>
                        )}
                        {isOnVacation && (
                            <Badge variant="secondary" className="bg-cyan-500/10 text-cyan-400 hover:bg-cyan-500/20 border-cyan-500/20">
                                En Congés
                            </Badge>
                        )}
                    </div>
                )}
            </div>

            {/* Footer: Member Since */}
            {joinedAt && (
                <div className="w-full mt-6 pt-6 border-t border-white/5 flex flex-col items-center gap-1 z-10">
                    <p className="text-xs font-medium text-zinc-500 uppercase tracking-widest">
                        Membre depuis
                    </p>
                    <p className="text-zinc-300 font-medium">
                        {new Date(joinedAt).toLocaleDateString("fr-FR", { day: 'numeric', month: 'long', year: 'numeric' })}
                    </p>
                </div>
            )}

            {!joinedAt && (
                <div className="flex-1" /> // Spacer if no date
            )}
        </div>
    );
}

"use client";

import { useState } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Save, Loader2, Info, MessageSquare, Sparkles, Smile } from "lucide-react";
import { toast } from "sonner";
import { saveMemberIntroduction } from "@/server/actions/onboarding-admin-actions";
import { EmojiPicker } from "../editor/emoji-picker";
import { cn } from "@/lib/utils";

interface IntroductionCardProps {
    introduction?: string;
    onSave: (text: string) => void;
    readOnly?: boolean;
    guildId: string;
    displayName: string;
    targetUserId?: string;
}

export function IntroductionCard({
    introduction = "",
    onSave,
    readOnly = false,
    guildId,
    displayName,
    targetUserId
}: IntroductionCardProps) {
    const [text, setText] = useState(introduction);
    const [isEditing, setIsEditing] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const MAX_CHARS = 5000;

    const handleEmojiSelect = (emoji: string) => {
        setText(prev => prev + emoji);
    };

    const handleSave = async () => {
        setIsSaving(true);
        try {
            const res = await saveMemberIntroduction(guildId, text, targetUserId);
            if (res.success) {
                onSave(text);
                setIsEditing(false);
                toast.success("Présentation enregistrée !");
            } else {
                toast.error(res.error || "Une erreur est survenue");
            }
        } catch (e) {
            toast.error("Erreur de communication");
        } finally {
            setIsSaving(false);
        }
    };

    if (!isEditing && !readOnly && !introduction) {
        return (
            <Card className="p-12 bg-zinc-900/40 border-white/5 flex flex-col items-center justify-center text-center space-y-6 relative overflow-hidden group">
                <div className="absolute inset-0 bg-gradient-to-br from-emerald-500/5 to-transparent pointer-events-none" />
                <div className="w-16 h-16 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center group-hover:scale-110 transition-transform duration-500">
                    <Sparkles className="w-8 h-8 text-emerald-400" />
                </div>
                <div className="space-y-2 max-w-sm">
                    <h3 className="text-xl font-black text-white">Parle-nous de toi !</h3>
                    <p className="text-sm text-zinc-500">
                        Ajoute une présentation pour que les autres membres de la guilde apprennent à te connaître.
                    </p>
                </div>
                <Button
                    onClick={() => setIsEditing(true)}
                    variant="sigil-emerald"
                    size="xl"
                >
                    Commencer ma présentation
                </Button>
            </Card>
        );
    }

    return (
        <Card className="bg-zinc-950/20 backdrop-blur-sm border-white/5 space-y-4 relative overflow-hidden group hover:border-white/10 transition-all rounded-3xl">
            <div className="absolute inset-0 bg-gradient-to-br from-emerald-500/5 via-transparent to-transparent pointer-events-none" />

            <div className="p-5 space-y-4">
                <div className="flex items-center justify-between relative">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center">
                            <MessageSquare className="w-5 h-5 text-emerald-400" />
                        </div>
                        <div>
                            <h3 className="text-sm font-bold text-white tracking-tight">Ma Présentation</h3>
                            <p className="text-[10px] text-zinc-500 uppercase tracking-widest font-black opacity-60">Bio de {displayName}</p>
                        </div>
                    </div>
                    {!readOnly && !isEditing && (
                        <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => setIsEditing(true)}
                            className="text-[10px] font-black uppercase tracking-widest text-zinc-400 hover:text-white h-7 px-3 rounded-lg"
                        >
                            Modifier
                        </Button>
                    )}
                </div>

                <div className="relative">
                    {isEditing ? (
                        <div className="space-y-3 animate-in fade-in zoom-in-95 duration-200">
                            <div className="relative rounded-2xl border border-white/10 bg-black/40 overflow-hidden focus-within:border-emerald-500/30 transition-all">
                                <div className="flex items-center justify-between px-3 py-2 border-b border-white/5 bg-white/5">
                                    <div className="flex items-center gap-1">
                                        <EmojiPicker onSelect={handleEmojiSelect} />
                                        <span className="text-[10px] font-bold text-zinc-500 uppercase ml-2">Apparence & Bio</span>
                                    </div>
                                    <div className={cn(
                                        "text-[10px] font-black tabular-nums transition-colors px-2 py-1 rounded",
                                        text.length > MAX_CHARS ? "text-rose-500 bg-rose-500/10" : "text-zinc-500 bg-black/20"
                                    )}>
                                        {text.length} / {MAX_CHARS}
                                    </div>
                                </div>
                                <Textarea
                                    value={text}
                                    onChange={(e) => setText(e.target.value)}
                                    placeholder="Partage ton histoire, tes objectifs ou tes passions..."
                                    className="bg-transparent border-none min-h-[160px] max-h-[400px] resize-y p-4 focus-visible:ring-0 text-[13px] leading-relaxed placeholder:text-zinc-700"
                                />
                            </div>

                            <div className="flex items-center justify-between pt-1">
                                <p className="text-[10px] text-zinc-500 italic flex items-center gap-1.5 opacity-60">
                                    <Info className="w-3 h-3 text-emerald-500/50" />
                                    Visible par toute la guilde. Markdown supporté.
                                </p>
                                <div className="flex gap-2">
                                    <Button
                                        variant="ghost"
                                        size="sm"
                                        onClick={() => {
                                            setText(introduction || "");
                                            setIsEditing(false);
                                        }}
                                        disabled={isSaving}
                                        className="text-[11px] font-bold text-zinc-400 hover:text-white"
                                    >
                                        Annuler
                                    </Button>
                                    <Button
                                        onClick={handleSave}
                                        disabled={isSaving || text.length > MAX_CHARS}
                                        variant="sigil-emerald"
                                        className="h-9 px-5"
                                    >
                                        {isSaving ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Save className="w-3.5 h-3.5" />}
                                        Enregistrer
                                    </Button>
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="p-6 rounded-2xl bg-black/40 border border-white/5 text-zinc-300 text-sm leading-relaxed whitespace-pre-wrap min-h-[80px] group-hover:bg-black/60 transition-colors">
                            {introduction ? (
                                <div className="text-[13px] text-zinc-300/90 tracking-wide font-medium italic">
                                    "{introduction}"
                                </div>
                            ) : (
                                <span className="text-zinc-600 italic text-xs">Aucune présentation enregistrée.</span>
                            )}
                        </div>
                    )}
                </div>
            </div>

            {/* Corner Accent */}
            <div className="absolute top-0 right-0 p-3 opacity-[0.03] pointer-events-none group-hover:opacity-[0.06] transition-opacity">
                <Sparkles className="w-20 h-20 text-white" />
            </div>
        </Card>
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogClose, DialogDescription } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import Image from "next/image";
import { Pencil, Check, X, Hammer, Info } from "lucide-react";
import { DOFUS_JOBS, getForgemagieStatus, type ForgemagieStatusId, hasAnyForgemagie } from "@/lib/dofus-assets";
import { cn } from "@/lib/utils";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

interface JobsGridProps {
    jobs?: string[];
    forgemagieStatus?: ForgemagieStatusId;
    fmPriceClassic?: number | null;
    fmPriceTrans?: number | null;
    fmPriceExo?: number | null;
    onSaveJobs?: (jobs: string[]) => void;
    onSaveForgemagieStatus?: (status: ForgemagieStatusId) => void;
    onSaveForgemagiePrices?: (prices: { classic: number | null, trans: number | null, exo: number | null }) => void;
    readOnly?: boolean;
}

export function JobsGrid({
    jobs = [],
    forgemagieStatus = "UNAVAILABLE",
    fmPriceClassic = null,
    fmPriceTrans = null,
    fmPriceExo = null,
    onSaveJobs,
    onSaveForgemagieStatus,
    onSaveForgemagiePrices,
    readOnly = false,
}: JobsGridProps) {
    const [isOpen, setIsOpen] = useState(false);
    const [selectedJobs, setSelectedJobs] = useState<string[]>(jobs);

    const [prices, setPrices] = useState({
        classic: fmPriceClassic,
        trans: fmPriceTrans,
        exo: fmPriceExo
    });

    const userHasFMJobs = hasAnyForgemagie(jobs);

    const toggleJob = (jobId: string) => {
        if (selectedJobs.includes(jobId)) {
            setSelectedJobs(prev => prev.filter(j => j !== jobId));
        } else {
            setSelectedJobs(prev => [...prev, jobId]);
        }
    };

    const handleSave = () => {
        onSaveJobs?.(selectedJobs);
        setIsOpen(false);
    };

    const handleOpen = () => {
        setSelectedJobs(jobs);
    };

    const formatKamas = (value: number | null | undefined) => {
        if (value === null || value === undefined) return "Non défini";
        if (value === 0) return "Gratuit";
        return new Intl.NumberFormat('fr-FR').format(value) + " k";
    };

    const handlePriceChange = (type: 'classic' | 'trans' | 'exo', value: string) => {
        const num = value === "" ? null : parseInt(value);
        if (num !== null && (isNaN(num) || num < 0)) return;
        setPrices(prev => ({ ...prev, [type]: num }));
    };

    const handleSavePrices = () => {
        onSaveForgemagiePrices?.(prices);
    };

    const allJobs = Object.values(DOFUS_JOBS).flat();
    const activeJobsData = allJobs.filter(j => jobs.includes(j.id));

    return (
        <div className="p-6 bg-zinc-900/40 backdrop-blur-md rounded-2xl border border-white/10 transition-all hover:border-white/20 group h-full flex flex-col">
            <div className="flex items-center justify-between mb-6">
                <h3 className="text-base font-semibold text-zinc-200">Maîtrise artisanale</h3>
                {!readOnly && (
                    <Dialog open={isOpen} onOpenChange={setIsOpen}>
                        <DialogTrigger asChild>
                            <Button 
                                variant="ghost" 
                                size="icon" 
                                className="h-8 w-8 text-zinc-400 hover:text-amber-400 hover:bg-amber-500/10 border border-transparent hover:border-amber-500/20 transition-all duration-300" 
                                onClick={handleOpen}
                            >
                                <Pencil className="w-4 h-4" strokeWidth={2.5} />
                            </Button>
                        </DialogTrigger>
                        <DialogContent className="max-w-4xl max-h-[90vh] flex flex-col p-0 gap-0 bg-zinc-950 border-zinc-800">
                            <DialogHeader className="p-6 pb-2 border-b border-white/5">
                                <DialogTitle className="text-xl">Gérer vos métiers (Niveau 200)</DialogTitle>
                                <DialogDescription>Sélectionnez les métiers que vous maîtrisez au niveau maximum.</DialogDescription>
                            </DialogHeader>
                            <div className="flex-1 overflow-hidden p-6">
                                <Tabs defaultValue="Récolte" className="h-full flex flex-col">
                                    <TabsList className="grid w-full grid-cols-4 mb-6 bg-zinc-900 border border-zinc-800 p-1 h-12 rounded-xl">
                                        <TabsTrigger 
                                            value="Récolte"
                                            className="text-xs font-extrabold uppercase tracking-wider h-full rounded-lg transition-all text-zinc-400 hover:text-white hover:bg-zinc-800/50 data-[state=active]:bg-amber-500 data-[state=active]:text-zinc-950 data-[state=active]:font-black data-[state=active]:shadow-[0_0_20px_rgba(245,158,11,0.4)]"
                                        >
                                            Récolte
                                        </TabsTrigger>
                                        <TabsTrigger 
                                            value="Artisanat"
