"use client";

import { useState, useEffect } from "react";
import { getLegendaryCraftingData, syncLegendaryCrafts } from "@/server/actions/legendary-actions";
import { Card } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { toast } from "sonner";
import { Sparkles, Hammer, Info, Lock } from "lucide-react";
import { cn } from "@/lib/utils";
import Image from "next/image";

interface LegendaryCraftingProps {
    guildId: string;
    profileId: string;
    metiers: string[];
    readOnly?: boolean;
}

export function LegendaryCrafting({ guildId, profileId, readOnly = false }: LegendaryCraftingProps) {
    const [loading, setLoading] = useState(true);
    const [items, setItems] = useState<any[]>([]);
    const [jobsAt200, setJobsAt200] = useState<string[]>([]);
    const [hasPrerequisites, setHasPrerequisites] = useState(false);

    useEffect(() => {
        fetchData();
    }, [guildId, profileId]);

    const fetchData = async () => {
        setLoading(true);
        const res = await getLegendaryCraftingData(guildId, profileId);
        if (res.success && res.data) {
            setItems(res.data.items);
            setJobsAt200(res.data.jobsAt200);
            setHasPrerequisites(!!res.data.hasLegendaryPrerequisites);
        }
        setLoading(false);
    };

    const handlePrerequisitesToggle = async (enabled: boolean) => {
        if (readOnly) return;

        setHasPrerequisites(enabled);
        
        // Optimistic update
        setItems(prev => prev.map(item => ({
            ...item,
            canCraft: enabled && item.isEligible
        })));

        const res = await syncLegendaryCrafts(guildId, enabled);
        if (!res.success) {
            toast.error(res.error || "Erreur lors de la mise à jour");
            // Rollback
            setHasPrerequisites(!enabled);
            setItems(prev => prev.map(item => ({
                ...item,
                canCraft: !enabled && item.isEligible
            })));
        } else {
            toast.success(enabled ? "Prérequis confirmés" : "Prérequis retirés");
        }
    };

    const displayItems = items.filter(item => item.isEligible);

    // Group items by jobRequired
    const groupedItems = displayItems.reduce((acc, item) => {
        const job = item.jobRequired;
        if (!acc[job]) acc[job] = [];
        acc[job].push(item);
        return acc;
    }, {} as Record<string, any[]>);

    if (loading) {
        return (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {[1, 2, 3, 4].map(i => (
                    <Skeleton key={i} className="h-32 w-full rounded-2xl bg-white/5" />
                ))}
            </div>
        );
    }

    return (
        <div className="space-y-8">
            <div className="flex flex-col gap-2">
                <div className="flex items-center gap-2 text-xl font-black uppercase tracking-tighter text-white">
                    <Sparkles className="w-6 h-6 text-purple-400" />
                    Craft Légendaire
                </div>
                <p className="text-zinc-400 text-sm">
                    Déclarez les objets légendaires que vous êtes capable de fabriquer. 
                    Vous devez être **niveau 200** dans le métier correspondant et posséder les **6 Dofus primordiaux**.
                </p>
                
                <div className="mt-2 p-3 rounded-xl bg-purple-500/10 border border-purple-500/20 text-purple-200/80 text-xs flex items-center gap-3">
                    <Info className="w-4 h-4 text-purple-400 shrink-0" />
                    <p>
                        Une fois vos prérequis confirmés, les membres pourront voir vos capacités depuis l'annuaire et vous taguer sur Discord pour des commandes.
                    </p>
                </div>
            </div>

            {jobsAt200.length === 0 && !readOnly && (
                <Card className="p-6 bg-amber-500/10 border-amber-500/20 rounded-2xl flex items-start gap-4">
                    <Info className="w-6 h-6 text-amber-500 shrink-0 mt-1" />
                    <div>
                        <h4 className="text-amber-500 font-bold uppercase text-sm tracking-widest">Aucun métier 200</h4>
                        <p className="text-amber-200/70 text-xs mt-1">
                            Vous n'avez déclaré aucun métier de niveau 200 dans votre profil. 
                            Seuls les artisans de niveau maximum peuvent fabriquer des objets légendaires.
                        </p>
                    </div>
                </Card>
            )}

            {jobsAt200.length > 0 && !readOnly && (
                <Card className="p-6 bg-zinc-900/40 border-white/5 rounded-2xl">
                    <div className="flex items-center justify-between gap-4">
                        <div className="flex-1">
                            <h4 className="text-white font-bold uppercase tracking-widest text-sm flex items-center gap-2">
                                Prérequis <a href="https://www.dofuspourlesnoobs.com/objets-legendaires.html" target="_blank" rel="noopener noreferrer" className="text-purple-400 hover:text-purple-300" title="Voir les prérequis sur Dofus pour les Noobs"><Info className="w-4 h-4" /></a>
                            </h4>
                            <p className="text-zinc-400 text-sm mt-1">
                                Cochez cette case pour confirmer que vous avez terminé les séries de quêtes nécessaires pour fabriquer des objets légendaires (Dofus primordiaux, etc.).
                            </p>
                        </div>
                        <Switch 
                            checked={hasPrerequisites}
                            onCheckedChange={handlePrerequisitesToggle}
                            className="data-[state=checked]:bg-purple-500"
                        />
                    </div>
                </Card>
            )}

            {(!readOnly && !hasPrerequisites && jobsAt200.length > 0) ? (
                <div className="p-12 text-center text-zinc-500 border border-dashed border-white/10 rounded-2xl bg-zinc-900/20">
                    Veuillez confirmer vos prérequis ci-dessus pour déclarer vos objets légendaires.
                </div>
            ) : (
                <div className="space-y-8">
                    {Object.entries(groupedItems).map(([job, jobItems]: [string, any]) => (
                        <div key={job} className="space-y-4">
                            <h4 className="text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em] flex items-center gap-2 px-1">
                                <Hammer className="w-3 h-3" /> {job}
                            </h4>
                            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                                {jobItems.map((item: any) => (
                                    <Card 
                                        key={item.id}
                                        className={cn(
                                            "group relative overflow-hidden p-4 transition-all duration-300 rounded-2xl border-white/5 bg-zinc-900/40 backdrop-blur-md",
                                            item.canCraft ? "border-purple-500/30 bg-purple-500/5 shadow-[0_0_20px_rgba(168,85,247,0.1)]" : "hover:border-white/10"
                                        )}
                                    >
                                        <div className="flex items-center gap-4">
                                            <div className="relative w-16 h-16 shrink-0 rounded-xl overflow-hidden bg-black/40 border border-white/10 flex items-center justify-center p-2">
                                                {item.imageUrl ? (
                                                     <img 
                                                         src={item.imageUrl.startsWith("/") ? item.imageUrl : `/api/proxy-image?url=${encodeURIComponent(item.imageUrl)}`} 
                                                         alt={item.name} 
                                                         width={48} 
                                                         height={48}
                                                         className="object-contain group-hover:scale-110 transition-transform duration-500"
                                                     />
                                                ) : (
                                                    <Sparkles className="w-8 h-8 text-zinc-700" />
                                                )}
                                            </div>

                                            <div className="flex-1 min-w-0">
                                                <h4 className="text-white font-bold text-sm truncate uppercase tracking-tight leading-none">
                                                    {item.name}
                                                </h4>
                                                <div className="flex items-center gap-2 mt-1">
                                                    <Badge variant="outline" className="bg-white/5 text-[10px] uppercase border-none text-zinc-400">
                                                        {item.category}
                                                    </Badge>
                                                </div>
                                            </div>
                                        </div>

                                        {/* Status Indicator */}
                                        {item.canCraft && (
                                            <div className="absolute top-0 right-0 p-1.5 bg-purple-500 rounded-bl-xl shadow-lg animate-in zoom-in duration-300">
                                                <Sparkles className="w-3 h-3 text-white" />
                                            </div>
                                        )}
                                    </Card>
                                ))}
                            </div>
                        </div>
                    ))}
                    
                    {displayItems.length === 0 && jobsAt200.length > 0 && (
                        <div className="p-12 text-center text-zinc-500 border border-dashed border-white/10 rounded-2xl bg-zinc-900/20">
                            Aucun objet légendaire correspondant à vos métiers n'a été trouvé.
                        </div>
                    )}
                </div>
            )}
        </div>
    );
}

"use client";

import { useState } from "react";
import { BarChart3, Star, Coins, CheckCircle2, Target, Moon, CalendarDays, HandHeart, Trophy, Activity } from "lucide-react";
import StatCard from "@/app/dashboard/[guildId]/stats/_components/stat-card";
import ActivityChart from "@/app/dashboard/[guildId]/stats/_components/activity-chart";
import { ResponsiveContainer, PieChart, Pie, Cell, Tooltip } from "recharts";
import { cn } from "@/lib/utils";

interface MemberStatsProps {
    stats: {
        xp: number;
        weeklyXp: number;
        guildatons: number;
        missionsValidated: number;
        weeklyMissions: number;
        rank?: number;
        weeklyActivity: { week: string; submissions: number; validated: number }[];
        missionsByCategory: { category: string; count: number; validated: number }[];
        totalGuildMissions: number;
        discordStats?: {
            weekly: { messages: number; voice: number };
            monthly: { messages: number; voice: number };
            total: { messages: number; voice: number };
        };
    };
}

const CATEGORY_LABELS: Record<string, string> = {
    DONJON: "Donjon",
    REGULATION: "Régulation",
    ANOMALIE: "Anomalie",
    SONGES: "Songes",
    EXPEDITION: "Expédition",
    EVENT: "Événement",
};

const COLORS = ["#8b5cf6", "#14b8a6", "#f59e0b", "#ef4444", "#06b6d4", "#ec4899"];

export function MemberStats({ stats }: MemberStatsProps) {
    const [discordPeriod, setDiscordPeriod] = useState<"weekly" | "monthly" | "total">("weekly");

    const pieData = stats.missionsByCategory.map(c => ({
        name: CATEGORY_LABELS[c.category] || c.category,
        value: c.count,
    }));

    const validationRate = stats.missionsByCategory.reduce((acc, curr) => acc + curr.count, 0) > 0
        ? Math.round((stats.missionsValidated / stats.missionsByCategory.reduce((acc, curr) => acc + curr.count, 0)) * 100)
        : 0;

    const currentDiscordStats = stats.discordStats?.[discordPeriod] || { messages: 0, voice: 0 };
    const voiceHours = Math.floor(currentDiscordStats.voice / 60);
    const voiceMinutes = currentDiscordStats.voice % 60;

    const participationRate = stats.totalGuildMissions > 0 
        ? Math.round((stats.missionsValidated / stats.totalGuildMissions) * 100) 
        : 0;

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700 pb-12">
            {/* KPI Cards */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <StatCard icon={Star} label="XP Total" value={stats.xp.toLocaleString()} accent="violet" />
                <StatCard icon={Trophy} label="Rang XP" value={stats.rank ? `#${stats.rank}` : "---"} accent="teal" />
                <StatCard icon={Target} label="Missions (Total)" value={stats.missionsValidated} accent="emerald" />
                <StatCard icon={HandHeart} label="Taux réussite" value={`${validationRate}%`} accent="rose" />
            </div>

            {/* Discord Activity Card */}
            <div className="rounded-[2.5rem] border border-white/5 bg-gradient-to-br from-indigo-500/5 via-transparent to-transparent backdrop-blur-xl p-8 relative overflow-hidden group">
                <div className="absolute top-0 right-0 w-96 h-96 bg-indigo-500/5 rounded-full blur-[120px] pointer-events-none" />
                
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-10">
                    <div>
                        <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-500 flex items-center gap-3 italic">
                            <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 shadow-[0_0_10px_rgba(99,102,241,0.5)]" />
                            Engagement Discord
                        </h3>
                        <p className="text-zinc-400 text-xs mt-2 font-medium">Votre activité sur le serveur Discord de la guilde.</p>
                    </div>

                    <div className="flex p-1 bg-zinc-900/50 rounded-2xl border border-white/5 self-start">
                        {(["weekly", "monthly", "total"] as const).map((period) => (
                            <button
                                key={period}
                                onClick={() => setDiscordPeriod(period)}
                                className={cn(
                                    "px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all",
                                    discordPeriod === period 
                                        ? "bg-indigo-500 text-white shadow-lg shadow-indigo-500/20" 
                                        : "text-zinc-500 hover:text-zinc-300"
                                )}
                            >
                                {period === "weekly" ? "Semaine" : period === "monthly" ? "Mois" : "Global"}
                            </button>
                        ))}
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div className="bg-white/[0.03] rounded-3xl p-6 border border-white/5 flex items-center gap-6 group/stat">
                        <div className="p-4 rounded-2xl bg-indigo-500/10 text-indigo-400 group-hover/stat:scale-110 transition-transform">
                            <Activity className="w-6 h-6" />
                        </div>
                        <div>
                            <div className="text-2xl font-black text-white tabular-nums tracking-tighter italic">
                                {currentDiscordStats.messages.toLocaleString()}
                            </div>
                            <div className="text-[9px] font-black uppercase text-zinc-500 tracking-widest mt-1">Messages Envoyés</div>
                        </div>
                    </div>

                    <div className="bg-white/[0.03] rounded-3xl p-6 border border-white/5 flex items-center gap-6 group/stat">
                        <div className="p-4 rounded-2xl bg-cyan-500/10 text-cyan-400 group-hover/stat:scale-110 transition-transform">
                            <Moon className="w-6 h-6" />
                        </div>
                        <div>
                            <div className="text-2xl font-black text-white tabular-nums tracking-tighter italic">
                                {voiceHours}h {voiceMinutes}m
                            </div>
                            <div className="text-[9px] font-black uppercase text-zinc-500 tracking-widest mt-1">Temps en Vocal</div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <StatCard icon={Star} label="XP Semaine" value={`+${stats.weeklyXp.toLocaleString()}`} accent="violet" />
                <StatCard icon={Target} label="Missions Semaine" value={stats.weeklyMissions} accent="emerald" />
                <StatCard icon={Coins} label="Guildatons" value={stats.guildatons} accent="amber" />
                <StatCard icon={CalendarDays} label="Participation" value={`${participationRate}%`} accent="sky" />
            </div>

            {/* Charts Section */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Activity Trend */}
                <div className="lg:col-span-2 rounded-[2rem] border border-white/5 bg-black/40 backdrop-blur-xl p-8 relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-violet-500/5 rounded-full blur-[100px] pointer-events-none transition-all group-hover:bg-violet-500/10" />
                    <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-500 mb-8 flex items-center gap-3 italic">
                        <div className="w-1.5 h-1.5 rounded-full bg-violet-500 shadow-[0_0_10px_rgba(139,92,246,0.5)]" />
                        Courbe d'Activité Personnelle
                    </h3>
                    <div className="mt-4">
                        <ActivityChart data={stats.weeklyActivity} />
                    </div>
                </div>

                {/* Categories Breakdown */}
                <div className="rounded-[2rem] border border-white/5 bg-black/40 backdrop-blur-xl p-8 relative overflow-hidden group flex flex-col">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-500/5 rounded-full blur-[100px] pointer-events-none transition-all group-hover:bg-emerald-500/10" />
                    <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-500 mb-8 flex items-center gap-3 italic">
                        <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)]" />
                        Répartition des Missions
                    </h3>
                    
                    {pieData.length === 0 ? (
                        <div className="flex-1 flex items-center justify-center text-zinc-600 text-[10px] uppercase font-bold italic tracking-widest bg-white/[0.02] rounded-3xl border border-dashed border-white/5 mt-4 min-h-[200px]">
                            Aucune mission validée
                        </div>
                    ) : (
                        <>
                            <div className="h-[220px] relative mt-4">
                                <ResponsiveContainer width="100%" height="100%" minWidth={0}>
                                    <PieChart>
                                        <Pie
                                            data={pieData}
                                            cx="50%"
                                            cy="50%"
                                            innerRadius={65}
                                            outerRadius={90}
                                            paddingAngle={8}
                                            dataKey="value"
                                            stroke="none"
                                            animationDuration={1500}
                                        >
                                            {pieData.map((_, i) => (
                                                <Cell key={i} fill={COLORS[i % COLORS.length]} className="focus:outline-none" />
                                            ))}
                                        </Pie>
                                        <Tooltip 
                                            contentStyle={{ 
                                                backgroundColor: 'rgba(9,9,11,0.95)', 
                                                border: '1px solid rgba(255,255,255,0.1)',
                                                borderRadius: '12px',
                                                fontSize: '11px',
                                                fontWeight: 'bold',
                                                textTransform: 'uppercase'
                                            }}
                                        />
                                    </PieChart>
                                </ResponsiveContainer>
                                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex flex-col items-center">
                                    <span className="text-3xl font-black text-white italic leading-none tracking-tighter">
                                        {pieData.reduce((acc, curr) => acc + curr.value, 0)}
                                    </span>
                                    <span className="text-[9px] text-zinc-600 uppercase font-black tracking-widest mt-1">Total</span>
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8">
                                {pieData.map((entry, i) => (
                                    <div key={entry.name} className="flex items-center gap-2">
                                        <div className="w-1.5 h-1.5 rounded-full shadow-[0_0_8px_rgba(0,0,0,0.5)]" style={{ backgroundColor: COLORS[i % COLORS.length] }} />
                                        <span className="text-[10px] font-black text-zinc-400 uppercase italic truncate">{entry.name}</span>
                                        <span className="text-[10px] font-black text-white ml-auto">{entry.value}</span>
                                    </div>
                                ))}
                            </div>
                        </>
                    )}
                </div>
            </div>

            {/* Bottom Note */}
            <div className="flex items-center justify-center gap-3 py-6 border-t border-white/5 opacity-50">
                <BarChart3 className="w-4 h-4 text-zinc-600" />
                <p className="text-[9px] font-black uppercase tracking-[0.2em] text-zinc-600 italic">
                    Données certifiées • Synchronisation temps-réel via Robot SigilOS
                </p>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Card, CardContent } from "@/components/ui/card";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter, DialogDescription } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { CheckCircle2, ExternalLink, Loader2, RefreshCw, Unlink, Link2, Crown, ArrowRightLeft, ShieldCheck, AlertCircle, Settings, MoreVertical } from "lucide-react";
import { linkOcreAccount, unlinkOcreAccount, forceRefreshOcre, getAvailableOcreQuests, switchOcreQuest, type OcreProgressData } from "@/server/actions/ocre-actions";
import { toast } from "sonner";
import Link from "next/link";
import Image from "next/image";
import { formatDistanceToNow } from "date-fns";
import { fr } from "date-fns/locale";
import { cn } from "@/lib/utils";
import type { UserQuest } from "@/lib/metamob-client";
import { OcreSettingsModal } from "../ocre/ocre-settings-modal";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

interface MetamobLinkProps {
    guildId: string;
    metamobPseudo?: string | null;
    metamobVerified?: boolean;
    metamobLastSync?: Date | null;
    readOnly?: boolean;
    isAdmin?: boolean;
    targetUserId?: string;
    progressData?: OcreProgressData;
}

export function MetamobLink({
    guildId,
    metamobPseudo,
    metamobVerified,
    metamobLastSync,
    readOnly = false,
    isAdmin = false,
    targetUserId,
    progressData,
}: MetamobLinkProps) {
    const [isLinked, setIsLinked] = useState(Boolean(metamobPseudo && metamobVerified));
    const [currentPseudo, setCurrentPseudo] = useState(metamobPseudo || "");
    const [inputPseudo, setInputPseudo] = useState("");
    const [inputApiKey, setInputApiKey] = useState("");
    const [isLinking, setIsLinking] = useState(false);
    const [isUnlinking, setIsUnlinking] = useState(false);
    const [isRefreshing, setIsRefreshing] = useState(false);
    const [showLinkDialog, setShowLinkDialog] = useState(false);

    const [showUnlinkDialog, setShowUnlinkDialog] = useState(false);
    const [linkError, setLinkError] = useState<string | null>(null);
    const [forceLink, setForceLink] = useState(false);
    const [linkStep, setLinkStep] = useState(1);

    // Multi-Quest Support
    const [showSwitchDialog, setShowSwitchDialog] = useState(false);
    const [isSwitching, setIsSwitching] = useState(false);
    const [availableQuests, setAvailableQuests] = useState<UserQuest[]>([]);
    const [questsLoading, setQuestsLoading] = useState(false);

    const handleLink = async (force: boolean = false) => {
        if (!inputPseudo.trim()) {
            setLinkError("Veuillez entrer un pseudo");
            return;
        }

        setIsLinking(true);
        setLinkError(null);
        setForceLink(false);

        const result = await linkOcreAccount({
            guildId,
            pseudo: inputPseudo.trim(),
            apiKey: inputApiKey.trim() || undefined,
            force,
            targetUserId,
        });

        if (result.success && result.data) {
            setIsLinked(true);
            setCurrentPseudo(result.data.pseudo);
            setShowLinkDialog(false);
            setInputPseudo("");
            setInputApiKey("");
            setForceLink(false);
            const serverInfo = result.data.serverName ? ` (${result.data.serverName})` : "";
            toast.success(`Compte Metamob "${result.data.pseudo}" lié${serverInfo} !`);
        } else {
            setLinkError(result.error || "Erreur lors de la liaison du compte");
            // Detect if it's an ownership error and user is admin
            if (result.error?.includes("déjà lié") && isAdmin) {
                setForceLink(true);
            }
        }

        setIsLinking(false);
    };

    const handleUnlink = async () => {
        setIsUnlinking(true);

        const result = await unlinkOcreAccount({ guildId, targetUserId });

        if (result.success) {
            setIsLinked(false);
            setCurrentPseudo("");
            setShowUnlinkDialog(false);
            toast.success("Compte Metamob délié");
        } else {
            toast.error(result.error || "Erreur lors de la suppression");
        }

        setIsUnlinking(false);
    };

    const handleRefresh = async () => {
        setIsRefreshing(true);

        const result = await forceRefreshOcre(guildId, targetUserId);

        if (result.success) {
            toast.success("Données Metamob actualisées");
        } else {
            toast.error(result.error || "Erreur lors du rafraîchissement");
        }

        setIsRefreshing(false);
    };

    const handleOpenSwitch = async () => {
        setQuestsLoading(true);
        setShowSwitchDialog(true);
        const result = await getAvailableOcreQuests(guildId, targetUserId);
        if (result.success && result.data) {
            setAvailableQuests(result.data.sort((a, b) => b.quest_template.id - a.quest_template.id)); // Unity first? Or by date?
        } else {
            toast.error("Impossible de charger les quêtes");
            setShowSwitchDialog(false);
        }
        setQuestsLoading(false);
    };

    const handleSwitch = async (questSlug: string) => {
        setIsSwitching(true);
        const result = await switchOcreQuest(guildId, questSlug, targetUserId);
        if (result.success) {
            toast.success("Quête active mise à jour !");
            setShowSwitchDialog(false);
            // Refresh page to show new data? Client side navigation sufficient?
        } else {
            toast.error(result.error || "Impossible de changer de quête");
        }
        setIsSwitching(false);
    };

    return (
        <div className="p-4 bg-zinc-900/40 backdrop-blur-md rounded-xl border border-white/10 transition-all hover:border-white/20 group">
            <div className="flex items-center justify-between mb-4">
                <h3 className="text-base font-semibold text-zinc-200 flex items-center gap-2">
                    <div className="relative w-4 h-4 opacity-80">
                        <Image src="/assets/icons/ocre.png" alt="Ocre" fill sizes="16px" className="object-contain" />
                    </div>
                    Registre Metamob
                </h3>
                {!readOnly && (
                    <div className="flex items-center gap-2">
                        {isLinked ? (
                            <DropdownMenu>
                                <DropdownMenuTrigger asChild>
                                    <Button variant="ghost" size="icon" className="h-8 w-8 text-zinc-400 hover:text-amber-400 hover:bg-amber-500/10 border border-transparent hover:border-amber-500/20">
                                        <Settings className="w-4 h-4" />
                                    </Button>
                                </DropdownMenuTrigger>
                                <DropdownMenuContent align="end" className="w-56 bg-zinc-950 border-white/10">
                                    <DropdownMenuLabel className="text-zinc-200 font-bold uppercase tracking-widest text-[10px]">Mon compte Metamob</DropdownMenuLabel>
                                    <DropdownMenuSeparator className="bg-white/5" />
                                    <DropdownMenuItem asChild>
                                        <a href={`https://www.metamob.fr/profile/${encodeURIComponent(currentPseudo)}`} target="_blank" rel="noopener noreferrer" className="cursor-pointer text-zinc-300">
                                            <ExternalLink className="h-4 w-4 mr-2" />
                                            Voir sur Metamob.fr
                                        </a>
                                    </DropdownMenuItem>
                                    <DropdownMenuSeparator className="bg-white/5" />
                                    <DropdownMenuItem onClick={handleRefresh} disabled={isRefreshing} className="cursor-pointer text-zinc-300">
                                        <RefreshCw className={cn("h-4 w-4 mr-2", isRefreshing ? "animate-spin" : "")} />
                                        Forcer la synchro
                                    </DropdownMenuItem>
                                    <DropdownMenuItem onClick={handleOpenSwitch} className="cursor-pointer text-zinc-300">
                                        <ArrowRightLeft className="h-4 w-4 mr-2" />
                                        Changer de quête
                                    </DropdownMenuItem>
                                    {progressData && (
                                        <OcreSettingsModal
                                            data={progressData}
                                            guildId={guildId}
                                            trigger={
                                                <DropdownMenuItem 
                                                    onSelect={(e) => e.preventDefault()}
                                                    className="cursor-pointer text-zinc-300"
                                                >
                                                    <Settings className="h-4 w-4 mr-2" />
                                                    Réglages Expert
                                                </DropdownMenuItem>
                                            }
                                        />
                                    )}
                                    <DropdownMenuSeparator className="bg-white/5" />
                                    <DropdownMenuItem onClick={() => setShowUnlinkDialog(true)} className="text-rose-400 focus:text-rose-400 focus:bg-rose-950/30 cursor-pointer">
                                        <Unlink className="h-4 w-4 mr-2" />
                                        Délier le compte
                                    </DropdownMenuItem>
                                </DropdownMenuContent>
                            </DropdownMenu>
                        ) : (
                            <Button 
                                variant="ghost" 
                                size="sm" 
                                className="h-8 px-3 text-xs font-bold text-zinc-400 hover:text-amber-400 hover:bg-amber-500/10 border border-transparent hover:border-amber-500/20"
                                onClick={() => setShowLinkDialog(true)}
                            >
                                <Link2 className="w-3.5 h-3.5 mr-2" />
                                Lier mon compte
                            </Button>
                        )}
                    </div>
                )}
            </div>

            <div className="relative overflow-hidden rounded-lg border border-white/5 bg-gradient-to-br from-zinc-900 to-black p-4">
                <div className="relative flex items-center gap-4">
                    <div className="relative flex items-center justify-center w-14 h-14 rounded-xl bg-zinc-950 border border-white/10 shadow-lg shrink-0">
                        <div className={cn("relative h-8 w-8 transition-all", !isLinked && "opacity-40 grayscale")}>
                            <Image src="/assets/icons/ocre.png" alt="Dofus Ocre" fill sizes="32px" className="object-contain drop-shadow-[0_0_8px_rgba(245,158,11,0.5)]" />
                        </div>
                        {isLinked && <div className="absolute -bottom-1 -right-1 bg-zinc-950 rounded-full border border-zinc-900 p-0.5"><CheckCircle2 className="w-3.5 h-3.5 text-emerald-500" /></div>}
                    </div>
                    <div className="flex-1 space-y-1.5">
                        <div className="flex items-baseline gap-2">
                            <span className="text-xs font-bold text-zinc-500 uppercase tracking-widest shrink-0">Pseudo</span>
                            <span className="text-lg font-black text-amber-500 italic tracking-tight">{isLinked ? currentPseudo : "Non relié"}</span>
                        </div>
                        <div className="flex items-baseline gap-2">
                            <span className="text-xs font-bold text-zinc-500 uppercase tracking-widest shrink-0">Statut</span>
                            {isLinked ? (
                                <span className="text-sm font-black text-white">{metamobLastSync ? `Synchronisé ${formatDistanceToNow(new Date(metamobLastSync), { addSuffix: true, locale: fr })}` : "En attente"}</span>
                            ) : (
                                <span className="text-[10px] font-bold text-zinc-500 uppercase italic">Liaison requise</span>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            <Dialog open={showSwitchDialog} onOpenChange={setShowSwitchDialog}>
                <DialogContent className="max-w-md bg-zinc-950 border-white/10">
                    <DialogHeader>
                        <DialogTitle className="text-zinc-100">Choisir la quête active</DialogTitle>
                        <DialogDescription className="text-zinc-400">Sélectionnez la quête Ocre que vous souhaitez suivre sur SigilOS.</DialogDescription>
                    </DialogHeader>
                    <div className="space-y-3 py-2 max-h-[60vh] overflow-y-auto pr-2">
                        {questsLoading ? (
                            <div className="flex justify-center py-8"><Loader2 className="h-8 w-8 text-amber-500 animate-spin" /></div>
                        ) : availableQuests.length === 0 ? (
                            <div className="text-center py-6 text-muted-foreground">Aucune quête Ocre trouvée.</div>
                        ) : (
                            availableQuests.map((quest) => (
                                <div key={quest.slug} onClick={() => handleSwitch(quest.slug)} className="flex items-center justify-between p-3 rounded-xl border border-white/5 bg-white/5 hover:bg-white/10 cursor-pointer">
                                    <div className="flex flex-col gap-1">
                                        <div className="flex items-center gap-2">
                                            <span className="font-medium text-zinc-200">{quest.server.name}</span>
                                            <Badge variant="secondary" className="text-[10px] h-5 bg-black/20 border-white/5">{quest.quest_template.id === 1 ? "Unity" : "Rétro"}</Badge>
                                        </div>
                                        <div className="flex items-center gap-2 text-xs text-zinc-500"><UserCircle className="h-3.5 w-3.5" /><span>{quest.character_name}</span></div>
                                    </div>
                                    <Badge className="bg-amber-500/10 text-amber-500 border-amber-500/20">Étape {quest.current_step}</Badge>
                                </div>
                            ))
                        )}
                    </div>
                </DialogContent>
            </Dialog>

            <Dialog open={showUnlinkDialog} onOpenChange={setShowUnlinkDialog}>
                <DialogContent className="sm:max-w-md bg-zinc-950 border-white/10">
                    <DialogHeader>
                        <DialogTitle className="text-zinc-100">Délier le compte Metamob ?</DialogTitle>
                        <DialogDescription className="text-zinc-400">Vous ne pourrez plus accéder à la Quête Ocre via SigilOS.</DialogDescription>
                    </DialogHeader>
                    <DialogFooter>
                        <Button variant="ghost" onClick={() => setShowUnlinkDialog(false)} className="text-zinc-400">Annuler</Button>
                        <Button variant="destructive" onClick={handleUnlink} disabled={isUnlinking}>{isUnlinking && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}Délier</Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
 
            <Dialog open={showLinkDialog} onOpenChange={(open) => {
                setShowLinkDialog(open);
                if (!open) { setLinkError(null); setInputPseudo(""); setInputApiKey(""); setForceLink(false); setLinkStep(1); }
            }}>
                <DialogContent className="sm:max-w-2xl bg-zinc-950 border-white/10 shadow-2xl p-0 gap-0">
                    <DialogHeader className="p-8 border-b border-white/5">
                        <DialogTitle className="text-2xl font-black text-white flex items-center gap-3"><Link2 className="h-6 w-6 text-amber-500" />Lier votre compte Metamob</DialogTitle>
                    </DialogHeader>
                    <div className="p-8 space-y-6">
                        <div className="flex items-center gap-4">
                            <div className={cn("px-4 py-2 rounded-xl text-xs font-black uppercase", linkStep === 1 ? "bg-amber-500/20 text-amber-400" : "bg-emerald-500/20 text-emerald-400")}>1. Pseudo</div>
                            <div className="flex-1 h-0.5 bg-zinc-800" />
                            <div className={cn("px-4 py-2 rounded-xl text-xs font-black uppercase", linkStep === 2 ? "bg-amber-500/20 text-amber-400" : "bg-zinc-900 text-zinc-600")}>2. Clé API</div>
                        </div>
                        {linkStep === 1 ? (
                            <div className="space-y-4">
                                <label className="text-sm font-bold text-zinc-200">Pseudo Metamob</label>
                                <Input placeholder="Ex: MonPseudo" value={inputPseudo} onChange={(e) => setInputPseudo(e.target.value)} className="h-12 bg-zinc-900/50 border-zinc-800" />
                            </div>
                        ) : (
                            <div className="space-y-4">
                                <div className="flex items-center justify-between">
                                    <label className="text-sm font-bold text-zinc-200">Clé API V2</label>
                                    <a 
                                        href="https://www.metamob.fr/settings#api" 
                                        target="_blank" 
                                        rel="noopener noreferrer" 
                                        className="text-xs text-amber-500 hover:text-amber-400 font-semibold flex items-center gap-1 transition-colors"
                                    >
                                        Où trouver ma clé API ? <ExternalLink className="h-3 w-3" />
                                    </a>
                                </div>
                                <Input type="password" placeholder="64 caractères..." value={inputApiKey} onChange={(e) => setInputApiKey(e.target.value)} className="h-12 bg-zinc-900/50 border-zinc-800" />
                                <p className="text-xs text-zinc-500 leading-relaxed">
                                    Votre clé API est requise pour synchroniser automatiquement vos archimonstres et vos quêtes. Elle est disponible dans l'onglet <strong>API</strong> des paramètres de votre compte Metamob.fr.
                                </p>
                            </div>
                        )}
                        {linkError && <div className="p-4 rounded-xl bg-red-500/10 text-red-400 border border-red-500/20 text-sm font-bold">{linkError}</div>}
                    </div>
                    <DialogFooter className="p-8 border-t border-white/5 flex gap-3">
                        {linkStep === 1 ? (
                            <Button onClick={() => setLinkStep(2)} disabled={!inputPseudo.trim()} className="w-full bg-amber-600 font-bold">Suivant</Button>
                        ) : (
                            <>
                                <Button variant="ghost" onClick={() => setLinkStep(1)}>Retour</Button>
                                <Button onClick={() => handleLink(false)} disabled={isLinking} className="bg-emerald-600 font-bold">{isLinking ? <Loader2 className="animate-spin" /> : "Lier le compte"}</Button>
                            </>
                        )}
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}

function UserCircle({ className }: { className?: string }) {
    return (
        <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            className={className}
        >
            <circle cx="12" cy="12" r="10" />
            <circle cx="12" cy="10" r="3" />
            <path d="M7 20.662V19a2 2 0 0 1 2-2h6a2 2 0 0 1 2 2v1.662" />
        </svg>
    );
}

"use client";

import { useState, useEffect } from "react";
import { useSearchParams } from "next/navigation";
import { HeroHeader } from "./hero-header";
import { ClassDisplay } from "./class-display";
import { JobsGrid } from "./jobs-grid";
import { AvailabilityHeatmap } from "./availability-heatmap";
import { VacationMode } from "./vacation-mode";
import { MetamobLink } from "./metamob-link";
import { AltPseudos } from "./alt-pseudos";
import { BuildsCard } from "./builds-card";
import { SuccessSync } from "./success-sync";
import { UserSettings } from "./user-settings";
import { IntroductionCard } from "./introduction-card";
import { SkinLibrary } from "./skin-library";
import { AlignmentSection } from "./alignment-section";
import { LegendaryCrafting } from "./legendary-crafting";
import { LegendaryPetToggle } from "./legendary-pet-toggle";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { updateUserProfile, updateAvailability, updateVacationMode, updateForgemagieStatus, updateAltPseudos } from "@/server/actions/profile-actions";
import type { ContributorTier } from "@/server/actions/profile-actions";
import { toast } from "sonner";
import { UserCircle, LayoutDashboard, Shield, Sparkles, Users, Calendar, Trophy, Settings, Hammer } from "lucide-react";
import { ProfileReminderBanner } from "./profile-reminder-banner";
import { cn } from "@/lib/utils";
import { motion } from "framer-motion";
import type { AvailabilityMap, ForgemagieStatusId, GlobalAvailability } from "@/lib/dofus-assets";
import { useTour } from "@/components/tour/tour-provider";

interface ProfileBentoGridProps {
    profile: {
        id: string;
        userId?: string;
        pseudoDofus?: string | null;
        classe?: string | null;
        classeSecondaires?: string[] | null;
        metiers?: string[] | null;
        forgemagieStatus?: string | null;
        fmPriceClassic?: number | null;
        fmPriceTrans?: number | null;
        fmPriceExo?: number | null;
        availability?: GlobalAvailability | AvailabilityMap | null;
        vacationStart?: Date | null;
        vacationEnd?: Date | null;
        vacationNotify?: boolean;
        vacationReason?: string | null;
        metamobPseudo?: string | null;
        metamobVerified?: boolean;
        metamobLastSync?: Date | null;
        altPseudos?: string[] | null;
        dofusBookLinks?: { id: string; url: string; name: string }[] | null;
        successPoints?: number | null;
        lastLadderUpdate?: Date | null;
        notificationPrefs?: {
            missions?: boolean;
            songes?: boolean;
            events?: boolean;
            ladder?: boolean;
            polls?: boolean;
            admin_validations?: boolean;
        } | null;
        roleGrants?: any[];
        introduction?: string | null;
        showPresence?: boolean;
        skins?: any[];
        alignment?: string | null;
        alignmentOrder?: string | null;
        alignmentLevel?: number | null;
        hasLegendaryPet?: boolean | null;
    };
    user: {
        name?: string | null;
        image?: string | null;
    };
    stats: {
        xp: number;
        weeklyXp: number;
        guildatons: number;
        missionsValidated: number;
        weeklyMissions: number;
        joinedAt: string | Date | null;
        lastActivity: { description: string; date: string | Date } | null;
        isTopContributor: boolean;
        contributorTier?: ContributorTier;
        rank?: number;
        weeklyActivity: { week: string; submissions: number; validated: number }[];
        missionsByCategory: { category: string; count: number; validated: number }[];
        totalGuildMissions: number;
        discordStats?: {
            weekly: { messages: number; voice: number };
            monthly: { messages: number; voice: number };
            total: { messages: number; voice: number };
        };
    };
    guildId: string;
    discordNickname?: string | null;
    readOnly?: boolean;
    isAdmin?: boolean;
    permissions?: {
        canViewOcre?: boolean;
        canViewSonges?: boolean;
        canViewLadder?: boolean;
        canSyncLadder?: boolean;
        canManualSyncLadder?: boolean;
        canViewMissions?: boolean;
    };
    guildName?: string;
    dofusServerId?: string | null;
    roleName?: string;
    roleColor?: number;
    welcomeBadgeName?: string | null;
    isSuperAdmin?: boolean;
    hasAbsenceChannel?: boolean;
}

export function ProfileBentoGrid({
    profile,
    user,
    stats,
    guildId,
    discordNickname,
    readOnly = false,
    isAdmin = false,
    permissions = {},
    guildName,
    dofusServerId,
    roleName = "Membre",
    roleColor = 0,
    welcomeBadgeName,
    isSuperAdmin = false,
    hasAbsenceChannel = false,
}: ProfileBentoGridProps) {
    const [localProfile, setLocalProfile] = useState(profile);
    const searchParams = useSearchParams();
    const initialTab = searchParams.get("tab") || "overview";
    const [activeTab, setActiveTab] = useState(initialTab);

    const { tourPhase, currentStep } = useTour();

    // Synchronize activeTab with onboarding tour phase & step
    useEffect(() => {
        if (tourPhase === "profile") {
            if (currentStep === 3) setActiveTab("metiers");
            else if (currentStep === 4) setActiveTab("planning");
            else if (currentStep === 5) setActiveTab("combat");
            else if (currentStep === 6) setActiveTab("intro");
            else if (currentStep === 7) setActiveTab("settings");
            else if (currentStep === 1 || currentStep === 2) setActiveTab("overview");
        }
    }, [currentStep, tourPhase]);

    // Default permissions to true if not provided (internal consistency)
    const { 
        canViewOcre = true, 
        canViewSonges = true, 
        canViewLadder = true, 
        canViewMissions = true,
        canSyncLadder = false,
        canManualSyncLadder = true
    } = permissions;

    // Sync state if URL param changes (optional but good for UX)
    useEffect(() => {
        const tab = searchParams.get("tab");
        if (tab) setActiveTab(tab);
    }, [searchParams]);

    const [visitedTabs, setVisitedTabs] = useState<Set<string>>(new Set([initialTab]));

    useEffect(() => {
        setVisitedTabs(prev => {
            if (prev.has(activeTab)) return prev;
            return new Set(prev).add(activeTab);
        });
    }, [activeTab]);

    const displayName = discordNickname || profile.pseudoDofus || user.name || "Voyageur";

    // Compute empty section flags for readOnly mode (hide tabs/sections that have no data)
    const isEmpty: Record<string, boolean> = {
        combat: readOnly && (!localProfile.dofusBookLinks || localProfile.dofusBookLinks.length === 0),
        skins: readOnly && (!localProfile.skins || localProfile.skins.length === 0),
        mules: readOnly && (!localProfile.altPseudos || localProfile.altPseudos.length === 0),
        achievements: readOnly && !localProfile.successPoints,
        metiers: readOnly && (!localProfile.metiers || localProfile.metiers.length === 0),
        artisanat: readOnly && (!localProfile.metiers || localProfile.metiers.length === 0) && !localProfile.hasLegendaryPet,
        planning: readOnly && (
            (!localProfile.availability || Object.keys(localProfile.availability).length === 0) &&
            !localProfile.vacationStart &&
            !localProfile.vacationEnd
        ),
        metamob: readOnly && !localProfile.metamobPseudo,
        alignment: readOnly && (!localProfile.alignment || localProfile.alignment === "neutre") && !localProfile.alignmentOrder,
    };

    const now = new Date();
    const startDate = localProfile.vacationStart ? new Date(localProfile.vacationStart) : null;
    const endDate = localProfile.vacationEnd ? new Date(localProfile.vacationEnd) : null;

    const isUpcoming = Boolean(startDate && startDate > now);
    const isOnVacation = Boolean(startDate && startDate <= now && (!endDate || endDate >= now));

    // canEdit logic: Normal users can only edit if NOT readOnly. 
    // SuperAdmins can ALWAYS edit (God Mode).
    const canEdit = !readOnly || isSuperAdmin;
    const targetUserId = isSuperAdmin ? profile.userId : undefined;

    // Handlers
    const handleClassSave = async (mainClass: string, pseudo: string) => {
        setLocalProfile(prev => ({
            ...prev,
            classe: mainClass,
            pseudoDofus: pseudo
        }));

        const res = await updateUserProfile({
            guildId,
            classe: mainClass,
            // classeSecondaires: [], // Reset/Clear secondary classes
            pseudoDofus: pseudo,
            targetUserId
        });

        if (res.success) {
            toast.success("Profil mis à jour");
        } else {
            toast.error(res.error || "Erreur");
        }
    };

    const handleJobsSave = async (jobs: string[]) => {
        setLocalProfile(prev => ({ ...prev, metiers: jobs }));
        const res = await updateUserProfile({
            guildId,
            metiers: jobs,
            targetUserId
        });
        if (res.success) {
            toast.success("Métiers mis à jour");
        } else {
            toast.error(res.error || "Erreur");
        }
    };

    const handleForgemagieStatusSave = async (status: ForgemagieStatusId) => {
        setLocalProfile(prev => ({ ...prev, forgemagieStatus: status }));
        const res = await updateForgemagieStatus({ guildId, status, targetUserId });
        if (res.success) {
            toast.success("Statut Forgemagie mis à jour");
        } else {
            toast.error(res.error || "Erreur");
        }
    };

    const handleForgemagiePricesSave = async (prices: { classic: number | null, trans: number | null, exo: number | null }) => {
        setLocalProfile(prev => ({
            ...prev,
            fmPriceClassic: prices.classic,
            fmPriceTrans: prices.trans,
            fmPriceExo: prices.exo
        }));

        const res = await updateUserProfile({
            guildId,
            fmPriceClassic: prices.classic,
            fmPriceTrans: prices.trans,
            fmPriceExo: prices.exo,
            targetUserId
        });

        if (res.success) {
            toast.success("Tarifs Forgemagie mis à jour");
        } else {
            toast.error(res.error || "Erreur");
        }
    };

    const handleAvailabilitySave = async (availability: GlobalAvailability) => {
        setLocalProfile(prev => ({ ...prev, availability: availability as any }));
        const res = await updateAvailability({ guildId, availability, targetUserId });
        if (res.success) {
            toast.success("Disponibilités mises à jour");
        } else {
            toast.error(res.error || "Erreur");
        }
    };

    const handleVacationSave = async (data: { start: Date | null; end: Date | null; notify: boolean; noEndDate: boolean; reason: string | null }) => {
        setLocalProfile(prev => ({
            ...prev,
            vacationStart: data.start,
            vacationEnd: data.noEndDate ? null : data.end,
            vacationNotify: data.notify,
            vacationReason: data.reason,
        }));
        const res = await updateVacationMode({
            guildId,
            vacationStart: data.start?.toISOString() ?? null,
            vacationEnd: data.noEndDate ? null : (data.end?.toISOString() ?? null),
            vacationNotify: data.notify,
            vacationReason: data.reason ?? null,
            targetUserId
        });
        if (res.success) {
            toast.success("Mode vacances mis à jour");
        } else {
            toast.error(res.error || "Erreur");
        }
    };

    const handleAltPseudosSave = async (altPseudos: any[]) => {
        const res = await updateAltPseudos({ guildId, altPseudos, targetUserId });
        if (res.success) {
            setLocalProfile(prev => ({ ...prev, altPseudos }));
        } else {
            toast.error(res.error || "Erreur lors de la sauvegarde");
            throw new Error(res.error); // Allow component to handle error
        }
    };

    const handlePresenceToggle = async (enabled: boolean) => {
        setLocalProfile(prev => ({ ...prev, showPresence: enabled }));
        const res = await updateUserProfile({ guildId, showPresence: enabled, targetUserId });
        if (res.success) {
            toast.success(enabled ? "Visibilité de l'activité activée" : "Visibilité de l'activité désactivée");
        } else {
            toast.error(res.error || "Erreur");
        }
    };

    const handleAlignmentSave = async (data: { alignment: string | null; alignmentOrder: string | null; alignmentLevel: number }) => {
        setLocalProfile(prev => ({
            ...prev,
            alignment: data.alignment,
            alignmentOrder: data.alignmentOrder,
            alignmentLevel: data.alignmentLevel
        }));

        const res = await updateUserProfile({
            guildId,
            alignment: data.alignment,
            alignmentOrder: data.alignmentOrder,
            alignmentLevel: data.alignmentLevel,
            targetUserId
        });

        if (res.success) {
            toast.success("Alignement mis à jour");
        } else {
            toast.error(res.error || "Erreur lors de la sauvegarde");
        }
    };

    const handleNotificationPrefsSave = (prefs: any) => {
        setLocalProfile(prev => ({
            ...prev,
            notificationPrefs: {
                ...(prev.notificationPrefs || {}),
                ...prefs
            }
        }));
    };

    return (
        <div className="flex flex-col gap-6">
            {/* Monthly Profile Reminder — only for profile owner */}
            {!readOnly && (
                <ProfileReminderBanner guildId={guildId} />
            )}

            {/* Hero Header (Glass) */}
            <div data-tour="profile-header" className="rounded-3xl overflow-hidden border border-white/10 shadow-2xl bg-black/40 backdrop-blur-md">
                <HeroHeader
                    avatarUrl={user.image}
                    displayName={displayName}
                    roleColor={roleColor}
                    contributorTier={stats.contributorTier}
                    rank={stats.rank}
                    isOnVacation={isOnVacation}
                    isUpcomingVacation={isUpcoming}
                    vacationStart={startDate}
                    vacationEnd={endDate}
                    joinedAt={stats.joinedAt}
                    canViewMissions={permissions.canViewMissions}
                    canViewLadder={canViewLadder}
                    guildName={guildName}
                    sigilRoles={localProfile.roleGrants || []}
                    discordRoleName={roleName}
                    discordRoleColor={roleColor}
                    welcomeBadgeName={welcomeBadgeName}
                    shareSlug={encodeURIComponent(localProfile.pseudoDofus || profile.id)}
                    guildId={guildId}
                    readOnly={readOnly}
                />
            </div>

            {/* Sigma 2026 Adaptive Layout */}
            <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
                <div className="grid lg:grid-cols-[280px_1fr] grid-cols-1 gap-8 items-start">
                
                {/* Sidebar Navigation (Sticky on Desktop, Scrollable on Mobile) */}
                <aside className="lg:sticky lg:top-24 z-20 min-w-0 w-full">
                    <TabsList className="bg-transparent flex lg:flex-col flex-row flex-nowrap overflow-x-auto lg:overflow-visible gap-2 p-1 h-auto justify-start border-none w-full scrollbar-width-none [&::-webkit-scrollbar]:hidden">
                        {(() => {
                            const TABS_GROUPS = [
                                {
                                    name: "Identité",
                                    tabs: [
                                        { id: "overview", label: "Général", icon: UserCircle, activeColor: "text-emerald-400", bgActive: "bg-emerald-500/10", indicator: "bg-emerald-500 shadow-emerald-500/50" },
                                        { id: "intro", label: "Présentation", icon: LayoutDashboard, activeColor: "text-sky-400", bgActive: "bg-sky-500/10", indicator: "bg-sky-500 shadow-sky-500/50" },
                                    ]
                                },
                                {
                                    name: "Jeu & Progression",
                                    tabs: [
                                        { id: "combat", label: "Stuffs", icon: Shield, activeColor: "text-rose-400", bgActive: "bg-rose-500/10", indicator: "bg-rose-500 shadow-rose-500/50" },
                                        { id: "skins", label: "Skins", icon: Sparkles, activeColor: "text-pink-400", bgActive: "bg-pink-500/10", indicator: "bg-pink-500 shadow-pink-500/50" },
                                        { id: "mules", icon: Users, label: "Mules", activeColor: "text-indigo-400", bgActive: "bg-indigo-500/10", indicator: "bg-indigo-500 shadow-indigo-500/50" },
                                        { id: "achievements", label: "Succès", icon: Trophy, activeColor: "text-amber-400", bgActive: "bg-amber-500/10", indicator: "bg-amber-500 shadow-amber-500/50" },
                                    ].filter(t => !isEmpty[t.id]),
                                },
                                {
                                    name: "Artisanat",
                                    tabs: [
                                        { id: "metiers", label: "Métiers", icon: Hammer, activeColor: "text-orange-400", bgActive: "bg-orange-500/10", indicator: "bg-orange-500 shadow-orange-500/50" },
                                        { id: "artisanat", label: "Légendaire", icon: Sparkles, activeColor: "text-fuchsia-400", bgActive: "bg-fuchsia-500/10", indicator: "bg-fuchsia-500 shadow-fuchsia-500/50" },
                                    ].filter(t => !isEmpty[t.id]),
                                },
                                {
                                    name: "Activité",
                                    tabs: [
                                        { id: "planning", label: "Planning", icon: Calendar, activeColor: "text-cyan-400", bgActive: "bg-cyan-500/10", indicator: "bg-cyan-500 shadow-cyan-500/50" },
                                    ].filter(t => !isEmpty[t.id]),
                                },
                                ...(canEdit ? [{
                                    name: "Administration",
                                    tabs: [
                                        { id: "settings", label: "Réglages", icon: Settings, activeColor: "text-zinc-200", bgActive: "bg-white/10", indicator: "bg-white shadow-white/50" }
                                    ]
                                }] : [])
                            ];

                            return TABS_GROUPS.map((group, gIdx) => (
                                <div key={group.name} className={cn("flex flex-col gap-1 w-full", gIdx > 0 && "mt-4 lg:mt-6")}>
                                    <h4 className="hidden lg:block text-[10px] font-black uppercase tracking-widest text-zinc-600 mb-2 px-4">
                                        {group.name}
                                    </h4>
                                    {group.tabs.map((tab) => (
                                        <TabsTrigger
                                            key={tab.id}
                                            value={tab.id}
                                            data-tour={`profile-tab-${tab.id}`}
                                            className={cn(
                                                "relative flex items-center justify-start gap-3 min-w-[max-content] lg:w-full px-4 py-3 rounded-2xl transition-all duration-300 group shrink-0 overflow-hidden",
                                                "bg-zinc-900/40 backdrop-blur-md border border-white/5",
                                                "data-[state=active]:border-white/10 data-[state=active]:shadow-lg",
                                                activeTab === tab.id ? tab.bgActive : "hover:bg-white/[0.07] hover:border-white/10 active:scale-[0.98]"
                                            )}
                                        >
                                            {/* Hover Glow (Pre-click highlight) */}
                                            <div className="absolute inset-x-0 bottom-0 h-0.5 bg-gradient-to-r from-transparent via-white/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />

                                            <div className={cn(
                                                "p-2 rounded-xl transition-all duration-500 z-10",
                                                "bg-zinc-800/50 group-data-[state=active]:scale-110 group-data-[state=active]:translate-x-1 group-data-[state=active]:bg-zinc-950/50",
                                                activeTab === tab.id ? `${tab.activeColor} shadow-[0_0_15px_rgba(0,0,0,0.3)]` : "text-zinc-500 group-hover:text-zinc-300"
                                            )}>
                                                <tab.icon className="w-4 h-4" />
                                            </div>
                                            
                                            <span className={cn(
                                                "text-sm font-black uppercase tracking-widest transition-all duration-300 z-10",
                                                activeTab === tab.id ? "text-white translate-x-1" : "text-zinc-400 group-hover:text-zinc-200 group-hover:translate-x-0.5"
                                            )}>
                                                {tab.label}
                                            </span>

                                            {/* Neon Indicator */}
                                            {activeTab === tab.id && (
                                                <div className={cn(
                                                    "absolute left-0 w-1 h-6 rounded-full z-10 shadow-[0_0_10px_rgba(0,0,0,0.5)]",
                                                    tab.indicator
                                                )} />
                                            )}
                                        </TabsTrigger>
                                    ))}
                                </div>
                            ));
                        })()}
                    </TabsList>
                </aside>

                {/* Main Content Area */}
                <div className="min-w-0 space-y-8">

                {/* OVERVIEW TAB */}
                <TabsContent value="overview" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    <div className="flex flex-col gap-6">
                        {/* Classes */}
                        <div data-tour="profile-class">
                            <ClassDisplay
                                pseudoDofus={localProfile.pseudoDofus}
                                mainClass={localProfile.classe}
                                onSave={handleClassSave}
                                readOnly={!canEdit}
                                guildId={guildId}
                            />
                        </div>

                        {/* Metamob */}
                        {canViewOcre && !isEmpty.metamob && (
                            <MetamobLink
                                guildId={guildId}
                                metamobPseudo={profile.metamobPseudo}
                                metamobVerified={profile.metamobVerified}
                                metamobLastSync={profile.metamobLastSync}
                                readOnly={!canEdit}
                                isAdmin={isAdmin}
                                targetUserId={targetUserId}
                            />
                        )}

                        {/* Alignment & Order */}
                        {!isEmpty.alignment && (
                            <AlignmentSection
                                alignment={localProfile.alignment}
                                alignmentOrder={localProfile.alignmentOrder}
                                alignmentLevel={localProfile.alignmentLevel}
                                onSave={handleAlignmentSave}
                                readOnly={!canEdit}
                            />
                        )}
                    </div>
                </TabsContent>

                {/* INTRODUCTION TAB */}
                <TabsContent value="intro" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {visitedTabs.has("intro") && (
                        <IntroductionCard
                            introduction={localProfile.introduction || ""}
                            onSave={(text: string) => setLocalProfile(prev => ({ ...prev, introduction: text }))}
                            readOnly={!canEdit}
                            guildId={guildId}
                            displayName={displayName}
                            targetUserId={targetUserId}
                        />
                    )}
                </TabsContent>

                {/* COMBAT TAB (Stuffs) */}
                <TabsContent value="combat" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {visitedTabs.has("combat") && (
                        <div className="w-full">
                            <BuildsCard
                                links={localProfile.dofusBookLinks as any || []}
                                onSave={(links) => setLocalProfile(prev => ({ ...prev, dofusBookLinks: links }))}
                                readOnly={!canEdit}
                                guildId={guildId}
                                targetUserId={targetUserId}
                            />
                        </div>
                    )}
                </TabsContent>

                {/* SKINS TAB */}
                <TabsContent value="skins" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {visitedTabs.has("skins") && (
                        <div className="w-full">
                            <SkinLibrary 
                                initialSkins={localProfile.skins || []}
                                guildId={guildId}
                                readOnly={!canEdit}
                                profileId={localProfile.id}
                            />
                        </div>
                    )}
                </TabsContent>

                {/* MULES TAB */}
                <TabsContent value="mules" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {visitedTabs.has("mules") && (
                        <div className="w-full">
                            <AltPseudos
                                altPseudos={localProfile.altPseudos as any || []}
                                onSave={handleAltPseudosSave}
                                readOnly={!canEdit}
                            />
                        </div>
                    )}
                </TabsContent>

                {/* PLANNING TAB */}
                <TabsContent value="planning" className="animate-in fade-in slide-in-from-bottom-4 duration-500 flex flex-col gap-6">
                    {visitedTabs.has("planning") && (
                        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                            <div className="lg:col-span-2">
                                <AvailabilityHeatmap
                                    availability={localProfile.availability || {}}
                                    onSave={handleAvailabilitySave}
                                    readOnly={!canEdit}
                                    vacationStart={localProfile.vacationStart}
                                    vacationEnd={localProfile.vacationEnd}
                                />
                            </div>
                            <div>
                                <VacationMode
                                    vacationStart={localProfile.vacationStart}
                                    vacationEnd={localProfile.vacationEnd}
                                    vacationNotify={localProfile.vacationNotify}
                                    vacationReason={localProfile.vacationReason}
                                    onSave={handleVacationSave}
                                    readOnly={!canEdit}
                                    guildId={guildId}
                                    pseudo={displayName}
                                    profileId={profile.id}
                                    hasAbsenceChannel={hasAbsenceChannel}
                                />
                            </div>
                        </div>
                    )}
                </TabsContent>

                {/* ACHIEVEMENTS TAB */}
                <TabsContent value="achievements" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {visitedTabs.has("achievements") && (
                        <SuccessSync
                            pseudoDofus={localProfile.pseudoDofus}
                            guildId={guildId}
                            dofusServerId={dofusServerId}
                            successPoints={localProfile.successPoints}
                            lastUpdate={localProfile.lastLadderUpdate}
                            readOnly={!canEdit}
                            onTabChange={setActiveTab}
                            onSuccess={(points) => {
                                setLocalProfile(prev => ({
                                    ...prev,
                                    successPoints: points,
                                    lastLadderUpdate: new Date()
                                }));
                            }}
                            canSyncLadder={canSyncLadder}
                        />
                    )}
                </TabsContent>

                 {/* MÉTIERS TAB */}
                 <TabsContent value="metiers" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                     {visitedTabs.has("metiers") && (
                         <JobsGrid
                             jobs={localProfile.metiers || []}
                             forgemagieStatus={(localProfile.forgemagieStatus as ForgemagieStatusId) || "UNAVAILABLE"}
                             fmPriceClassic={localProfile.fmPriceClassic}
                             fmPriceTrans={localProfile.fmPriceTrans}
                             fmPriceExo={localProfile.fmPriceExo}
                             onSaveJobs={handleJobsSave}
                             onSaveForgemagieStatus={handleForgemagieStatusSave}
                             onSaveForgemagiePrices={handleForgemagiePricesSave}
                             readOnly={!canEdit}
                         />
                     )}
                 </TabsContent>

                 {/* ARTISANAT TAB */}
                 <TabsContent value="artisanat" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                     {visitedTabs.has("artisanat") && (
                         <div className="space-y-12">
                             <LegendaryCrafting 
                                 guildId={guildId}
                                 profileId={localProfile.id}
                                 metiers={localProfile.metiers || []}
                                 readOnly={!canEdit}
                             />
                             <div className="border-t border-white/5 pt-8">
                                 <LegendaryPetToggle
                                     guildId={guildId}
                                     initialValue={localProfile.hasLegendaryPet ?? false}
                                     readOnly={!canEdit}
                                 />
                             </div>
                         </div>
                     )}
                 </TabsContent>



                {/* SETTINGS TAB */}
                {canEdit && (
                    <TabsContent value="settings" className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                        {visitedTabs.has("settings") && (
                            <UserSettings
                                guildId={guildId}
                                guildName={guildName || "la guilde"}
                                profileId={profile.id}
                                notificationPrefs={localProfile.notificationPrefs as any}
                                onNotificationPrefsSave={handleNotificationPrefsSave}
                                showPresence={localProfile.showPresence ?? true}
                                onPresenceToggle={handlePresenceToggle}
                                isAdmin={isAdmin}
                                targetUserId={targetUserId}
                            />
                        )}
                    </TabsContent>
                )}
                </div>
            </div>
            </Tabs>
        </div>
    );
}

"use client";

import { useState, useTransition } from "react";
import { UserProfile } from "@prisma/client";
import { updateUserProfile, verifyDofusPseudo } from "@/server/actions/profile-actions";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { MultiSelect } from "@/components/ui/multi-select";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { toast } from "sonner";
import { DOFUS_CLASSES, DOFUS_JOBS } from "@/lib/dofus-data";
import { Loader2, Save, User as UserIcon, Search, UserCheck, AlertTriangle } from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { formatDofusPseudo, cn } from "@/lib/utils";

interface ExtendedProfile extends UserProfile {
    user: { name: string | null; image: string | null };
    xp: number;
    guildatons: number;
}

interface ProfileEditorProps {
    profile: any; // Bypass stale type
    guildId: string;
}

export function ProfileEditor({ profile: rawProfile, guildId }: ProfileEditorProps) {
    const profile = rawProfile as ExtendedProfile;
    const [isPending, startTransition] = useTransition();

    const [pseudo, setPseudo] = useState(profile.pseudoDofus || "");
    const [classe, setClasse] = useState(profile.classe || "");
    const [isVerifying, setIsVerifying] = useState(false);
    const [verifyStatus, setVerifyStatus] = useState<"idle" | "success" | "error">("idle");
    // Helper to safely parse JSONB
    const initialJobs = Array.isArray(profile.metiers) ? (profile.metiers as string[]) : [];
    const [jobs, setJobs] = useState<string[]>(initialJobs);

    const handleVerify = async () => {
        if (!pseudo || pseudo.length < 2) return;
        setIsVerifying(true);
        setVerifyStatus("idle");
        try {
            const res = await verifyDofusPseudo(pseudo, guildId);
            if (res.success) {
                setVerifyStatus("success");
                toast.success("Pseudo trouvé sur le ladder !");
            } else {
                setVerifyStatus("error");
                toast.error(res.error || "Pseudo introuvable");
            }
        } catch (e) {
            setVerifyStatus("error");
        } finally {
            setIsVerifying(false);
        }
    };

    const handleSave = () => {
        if (!pseudo) {
            toast.error("Le pseudo est obligatoire");
            return;
        }

        // Si le pseudo a changé par rapport à l'original et n'est pas vérifié
        if (pseudo !== (profile.pseudoDofus || "") && verifyStatus !== "success") {
            toast.error("Veuillez vérifier la validité de votre pseudo avant d'enregistrer.");
            return;
        }

        startTransition(async () => {
            const result = await updateUserProfile({
                guildId,
                pseudoDofus: pseudo,
                classe: classe || undefined,
                metiers: jobs
            });

            if (result.success) {
                toast.success("Profil mis à jour avec succès");
            } else {
                toast.error(result.error || "Erreur lors de la mise à jour");
            }
        });
    };

    const jobOptions = DOFUS_JOBS.map(job => ({ label: job, value: job }));

    return (
        <div className="grid gap-6 md:grid-cols-2">

            {/* ID CARD */}
            <Card className="bg-black/40 border-white/10 backdrop-blur-sm h-fit">
                <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                        <UserIcon className="w-5 h-5 text-primary" />
                        Identité Visuelle
                    </CardTitle>
                    <CardDescription>
                        Aperçu de votre carte de membre dans l'annuaire.
                    </CardDescription>
                </CardHeader>
                <CardContent className="flex flex-col items-center justify-center py-6 gap-4">
                    <div className="relative group">
                        <Avatar className="w-32 h-32 border-4 border-white/10 shadow-xl group-hover:border-primary transition-colors">
                            <AvatarImage src={profile.user.image || ""} />
                            <AvatarFallback className="text-4xl bg-zinc-800 text-zinc-400">
                                {profile.user.name?.[0]?.toUpperCase() || "?"}
                            </AvatarFallback>
                        </Avatar>
                        {/* Placeholder for future avatar upload */}
                    </div>

                    <div className="text-center space-y-1">
                        <h3 className="text-2xl font-bold text-white tracking-tight">
                            {pseudo || profile.user.name || "Inconnu"}
                        </h3>
                        <p className="text-primary font-medium">{classe || "Classe inconnue"}</p>

                        {/* Stats Badges */}
                        <div className="flex items-center justify-center gap-3 mt-4 text-xs font-mono">
                            <div className="px-3 py-1 rounded-full bg-indigo-500/20 text-indigo-300 border border-indigo-500/30">
                                ✨ {profile.xp} XP
                            </div>
                            <div className="px-3 py-1 rounded-full bg-amber-500/20 text-amber-300 border border-amber-500/30">
                                🪙 {profile.guildatons} G
                            </div>
                        </div>
                    </div>
                </CardContent>
            </Card>

            {/* FORM */}
            <Card className="bg-zinc-900/50 border-white/10">
                <CardHeader>
                    <CardTitle>Configuration du Profil</CardTitle>
                    <CardDescription>
                        Ces informations permettent aux autres membres de vous trouver.
                    </CardDescription>
                </CardHeader>
                <CardContent className="space-y-6">

                    <div className="space-y-2">
                        <Label>Pseudo en jeu (Obligatoire)</Label>
                        <div className="flex gap-2">
                            <div className="relative flex-1 group/input">
                                <Input
                                    value={pseudo}
                                    onChange={(e) => {
                                        setPseudo(formatDofusPseudo(e.target.value));
                                        setVerifyStatus("idle");
                                    }}
                                    placeholder="Ex: Dark-Sasuké"
                                    className={cn(
                                        "bg-zinc-950/50 border-white/10 focus:border-primary/50 transition-all",
                                        verifyStatus === "success" && "border-emerald-500/50 pr-10",
                                        verifyStatus === "error" && "border-rose-500/50 pr-10"
                                    )}
                                />
                                {verifyStatus === "success" && (
                                    <div className="absolute right-3 top-1/2 -translate-y-1/2 text-emerald-500">
                                        <UserCheck className="w-4 h-4" />
                                    </div>
                                )}
                                {verifyStatus === "error" && (
                                    <div className="absolute right-3 top-1/2 -translate-y-1/2 text-rose-500">
                                        <AlertTriangle className="w-4 h-4" />
                                    </div>
                                )}
                            </div>
                            <Button 
                                variant="outline" 
                                size="icon"
                                onClick={handleVerify}
                                disabled={isVerifying || !pseudo || pseudo.length < 2}
                                className={cn(
                                    "shrink-0 bg-black/20 border-white/10 hover:border-white/20",
                                    verifyStatus === "success" && "text-emerald-500 border-emerald-500/20 bg-emerald-500/5"
                                )}
                            >
                                {isVerifying ? <Loader2 className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4" />}
                            </Button>
                        </div>
                        <p className="text-[10px] leading-relaxed text-muted-foreground ml-1 mt-1">
                            {verifyStatus === "success" ? (
                                <span className="text-emerald-400 font-medium">✅ Pseudo validé sur le ladder officiel.</span>
                            ) : (
                                <>
                                    Le pseudo doit être <strong className="text-white">EXACT</strong> (Majuscules, tirets, etc.) pour que la synchronisation automatique fonctionne.
                                </>
                            )}
                        </p>
                    </div>

                    <div className="space-y-2">
                        <Label>Classe</Label>
                        <Select value={classe} onValueChange={setClasse}>
                            <SelectTrigger className="bg-zinc-950/50 border-white/10">
                                <SelectValue placeholder="Sélectionner une classe" />
                            </SelectTrigger>
                            <SelectContent>
                                {DOFUS_CLASSES.map((c) => (
                                    <SelectItem key={c} value={c}>
                                        {c}
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>

                    <div className="space-y-2">
                        <Label>Métiers (Niveau 200)</Label>
                        <MultiSelect
                            options={jobOptions}
                            selected={jobs}
                            onChange={setJobs}
                            placeholder="Sélectionner vos métiers"
                        />
                        <p className="text-xs text-muted-foreground">
                            Sélectionnez uniquement vos métiers maîtrisés.
                        </p>
                    </div>

                </CardContent>
                <CardFooter className="flex justify-between border-t border-white/5 pt-6">
                    <Button variant="ghost" onClick={() => setPseudo(profile.pseudoDofus || "")}>
                        Annuler
                    </Button>
                    <Button onClick={handleSave} disabled={isPending} className="min-w-[140px]">
                        {isPending ? (
                            <>
                                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                Sauvegarde...
                            </>
                        ) : (
                            <>
                                <Save className="w-4 h-4 mr-2" />
                                Enregistrer
                            </>
                        )}
                    </Button>
                </CardFooter>
            </Card>
        </div>
    );
}

"use client";

import { useState, useEffect, useMemo } from "react";
import { 
    Sparkles, 
    Plus, 
    Trash2, 
    ExternalLink, 
    Eye, 
    LayoutGrid, 
    Info, 
    Loader2, 
    Copy, 
    RefreshCw, 
    HelpCircle, 
    Globe, 
    Search, 
    X, 
    Megaphone, 
    Send, 
    Pencil,
    Mars,
    Venus
} from "lucide-react";
import { ClassFilter, GenderFilter } from "@/components/gallery/gallery-filters";
import { DOFUS_CLASSES } from "@/lib/dofus-assets";
import NextImage from "next/image";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { addUserSkin, deleteUserSkin, getSkinPreview, type SkinData, updateUserSkin } from "@/server/actions/skin-actions";
import { shareGalleryItemOnDiscord } from "@/server/actions/gallery-actions";

interface Skin {
    id: string;
    name: string;
    url: string;
    provider: string;
    thumbnailUrl: string | null;
    equipment?: any;
    colors?: any;
    metadata?: any;
    createdAt: Date | string;
}

interface SkinLibraryProps {
    initialSkins: Skin[];
    guildId: string;
    readOnly?: boolean;
    profileId: string;
}

export function SkinLibrary({ initialSkins, guildId, readOnly = false, profileId }: SkinLibraryProps) {
    const [skins, setSkins] = useState<Skin[]>(initialSkins);
    const [isAddOpen, setIsAddOpen] = useState(false);
    const [newSkinUrl, setNewSkinUrl] = useState("");
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [selectedSkin, setSelectedSkin] = useState<Skin | null>(null);
    const [previewData, setPreviewData] = useState<SkinData | null>(null);
    const [isPreviewLoading, setIsPreviewLoading] = useState(false);

    const [isEditOpen, setIsEditOpen] = useState(false);
    const [skinToEdit, setSkinToEdit] = useState<Skin | null>(null);
    const [editedName, setEditedName] = useState("");
    const [editedUrl, setEditedUrl] = useState("");

    // Filter State
    const [searchQuery, setSearchQuery] = useState("");
    const [selectedClass, setSelectedClass] = useState<string | null>(null);
    const [selectedGender, setSelectedGender] = useState<string | null>(null);

    // Client-side filtering logic
    const filteredSkins = useMemo(() => {
        const normalize = (s: string) => s ? s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim() : "";

        return skins.filter(skin => {
            // 1. Search filter
            if (searchQuery) {
                const q = searchQuery.toLowerCase();
                const matchesTitle = skin.name.toLowerCase().includes(q);
                const matchesAuthor = skin.metadata?.author?.toLowerCase().includes(q);
                if (!matchesTitle && !matchesAuthor) return false;
            }

            // 2. Class filter
            if (selectedClass) {
                // Handle both numerical (Dofus IDs) and string class names
                const skinClass = skin.metadata?.class;
                if (!skinClass) return false;
                
                // Mapping is done by name for now as metadata.class stores names
                const targetClass = DOFUS_CLASSES.find((c: any) => {
                    const match = c.icon.match(/classes\/(\d+)\.png/);
                    return match && match[1] === selectedClass;
                });
                
                if (!targetClass) return false;
                
                const matchesId = skinClass === selectedClass;
                const matchesName = normalize(skinClass).includes(normalize(targetClass.name));
                
                if (!matchesId && !matchesName) return false;
            }

            // 3. Gender filter
            if (selectedGender) {
                const skinGender = skin.metadata?.gender; // Normalized to M/F by scraper now, but handle legacy
                if (!skinGender) return false;
                
                const mValues = ["M", "Homme", "♂", "Mâle", "Male"];
                const fValues = ["F", "Femme", "♀", "Femelle"];
                const valuesToMatch = selectedGender === "M" ? mValues : fValues;
                
                const normalizedSearch = valuesToMatch.map(v => normalize(v));
                if (!normalizedSearch.includes(normalize(skinGender))) return false;
            }

            return true;
        });
    }, [skins, searchQuery, selectedClass, selectedGender]);


    // Live Preview Effect
    useEffect(() => {
        if (!newSkinUrl.trim() || newSkinUrl.length < 15) {
            setPreviewData(null);
            return;
        }

        const timer = setTimeout(async () => {
            const isSupported = newSkinUrl.includes("barbofus.com") || 
                              newSkinUrl.includes("dofusskinmanga.com");
            
            if (!isSupported) return;

            setIsPreviewLoading(true);
            try {
                const res = await getSkinPreview(newSkinUrl.trim());
                if (res.success && res.data) {
                    setPreviewData(res.data);
                }
            } finally {
                setIsPreviewLoading(false);
            }
        }, 800);

        return () => clearTimeout(timer);
    }, [newSkinUrl]);

    const handleAddSkin = async () => {
        if (!newSkinUrl.trim()) {
            toast.error("Veuillez entrer une URL");
            return;
        }

        setIsSubmitting(true);
        try {
            const res = await addUserSkin({ guildId, url: newSkinUrl.trim() });
            if (res.success && res.data) {
                toast.success("Skin ajouté à votre bibliothèque !");
                setIsAddOpen(false);
                setNewSkinUrl("");
                setSkins(prev => [res.data, ...prev]);
            } else {
                toast.error(res.error || "Une erreur est survenue");
            }
        } catch (error) {
            toast.error("Erreur serveur");
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleCopyLink = (url: string) => {
        navigator.clipboard.writeText(url);
        toast.success("Lien copié !");
    };

    const handleRefreshMetadata = async (skinId: string, url: string) => {
        setIsSubmitting(true);
        toast.info("Mise à jour des données...");
        try {
            const res = await addUserSkin({ guildId, url: url.trim(), existingSkinId: skinId });
            if (res.success && res.data) {
                setSkins(prev => prev.map(s => s.id === skinId ? res.data : s));
                toast.success("Données actualisées !");
            } else {
                toast.error(res.error || "Erreur lors de la mise à jour");
            }
        } catch (error) {
            toast.error("Erreur serveur");
        } finally {
            setIsSubmitting(false);
        }
    };

    const [isDeleteOpen, setIsDeleteOpen] = useState(false);
    const [skinToDelete, setSkinToDelete] = useState<string | null>(null);

    const handleDeleteSkin = async () => {
        if (readOnly || !skinToDelete) return;
        
        setIsSubmitting(true);
        try {
            const res = await deleteUserSkin(guildId, skinToDelete);
            if (res.success) {
                setSkins(prev => prev.filter(s => s.id !== skinToDelete));
                toast.success("Skin supprimé avec succès");
                setIsDeleteOpen(false);
                setSkinToDelete(null);
            } else {
                toast.error(res.error || "Erreur lors de la suppression");
            }
        } catch (error) {
            toast.error("Erreur serveur");
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleUpdateSkin = async () => {
        if (!skinToEdit || !editedName.trim()) return;

        setIsSubmitting(true);
        try {
            const res = await updateUserSkin(guildId, skinToEdit.id, { 
                name: editedName.trim(),
                url: editedUrl.trim() 
            });
            if (res.success && res.data) {
                // If URL changed, we use the full returned object in case metadata changed
                setSkins(prev => prev.map(s => s.id === skinToEdit.id ? res.data : s));
                toast.success("Skin mis à jour avec succès !");
                setIsEditOpen(false);
                setSkinToEdit(null);
            } else {
                toast.error(res.error || "Erreur lors de la modification");
            }
        } catch (error) {
            toast.error("Erreur serveur");
        } finally {
            setIsSubmitting(false);
        }
    };


    const getProviderIcon = (provider: string) => {
        switch (provider) {
            case "BARBOFUS": return "/assets/ui/icons/barbofus.png";
            case "DOFUSSKINMANGA": return "/assets/ui/icons/dofusskinmanga.png"; 
            default: return null;
        }
    };

    return (
        <div className="flex flex-col gap-6">
            {/* Header / Actions */}
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-zinc-900/40 backdrop-blur-md p-6 rounded-3xl border border-white/10">
                <div className="flex items-center gap-3">
                    <div className="p-3 bg-pink-500/10 rounded-2xl border border-pink-500/20">
                        <Sparkles className="w-6 h-6 text-pink-400" />
                    </div>
                    <div>
                        <div className="flex items-center gap-4">
                            <h3 className="text-xl font-bold text-white">Ma Garde-Robe</h3>
                            <Popover>
                                <PopoverTrigger asChild>
                                    <Button variant="outline" size="sm" className="h-8 rounded-xl border-pink-500/30 bg-pink-500/5 text-pink-400 hover:bg-pink-500 hover:text-white transition-all gap-2 text-[10px] font-black uppercase tracking-widest shadow-lg shadow-pink-500/10">
                                        <HelpCircle className="w-3.5 h-3.5" />
                                        Comment ça marche ?
                                    </Button>
                                </PopoverTrigger>
                                <PopoverContent className="w-80 bg-zinc-950 border-white/10 p-0 rounded-[2rem] shadow-2xl overflow-hidden border-2 border-pink-500/20">
                                    <div className="bg-gradient-to-r from-pink-500/20 to-purple-500/20 p-5 border-b border-white/5">
                                        <h4 className="font-black text-xs uppercase tracking-widest text-white flex items-center gap-2">
                                            <Sparkles className="w-4 h-4 text-pink-400" />
                                            Guide Mode & Skins
                                        </h4>
                                    </div>
                                    <div className="p-6 space-y-8">
                                        <div className="space-y-4">
                                            <p className="text-[10px] text-zinc-500 font-black uppercase tracking-[0.2em]">1. Choisir un site</p>
                                            <div className="grid grid-cols-1 gap-3">
                                                <a 
                                                    href="https://barbofus.com" 
                                                    target="_blank" 
                                                    rel="noopener noreferrer"
                                                    className="flex items-center justify-between p-4 bg-white/5 hover:bg-pink-500/10 rounded-2xl border border-white/5 hover:border-pink-500/30 transition-all group"
                                                >
                                                    <div className="flex items-center gap-4">
                                                        <div className="w-10 h-10 rounded-xl bg-pink-500/10 flex items-center justify-center border border-pink-500/20 shadow-inner overflow-hidden">
