                                </div>
                            </div>
                        </div>
                        {item.reward_kamas && (
                            <div className="ml-auto text-right">
                                <div className="text-[9px] text-zinc-500 uppercase tracking-widest font-bold">Récompense</div>
                                <div className="font-black text-lg" style={{ color }}>{formatKamas(item.reward_kamas)}</div>
                            </div>
                        )}
