                            <input value={emoji} onChange={e => setEmoji(e.target.value)} type="text" placeholder="🔗" className="text-center w-full bg-white/5 border border-white/10 rounded-xl px-2 py-3 text-white focus:outline-none focus:border-emerald-500/50 transition-colors" />
                        </div>
                        <div className="col-span-3">
                            <label className="text-[10px] uppercase font-black tracking-widest text-zinc-500 mb-1.5 block">Titre</label>
                            <input value={title} onChange={e => setTitle(e.target.value)} type="text" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-emerald-500/50 transition-colors" />
                        </div>
                    </div>
                    <div>
                        <label className="text-[10px] uppercase font-black tracking-widest text-zinc-500 mb-1.5 block">URL</label>
                        <input value={url} onChange={e => setUrl(e.target.value)} type="text" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-xs focus:outline-none focus:border-emerald-500/50 transition-colors" />
                    </div>
                    <div>
                        <label className="text-[10px] uppercase font-black tracking-widest text-zinc-500 mb-1.5 block">Description</label>
                        <textarea value={desc} onChange={e => setDesc(e.target.value)} rows={2} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white text-xs focus:outline-none focus:border-emerald-500/50 transition-colors resize-none" />
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                        <div>
                            <label className="text-[10px] uppercase font-black tracking-widest text-zinc-500 mb-1.5 block">Ordre</label>
                            <input value={order} onChange={e => setOrder(parseInt(e.target.value))} type="number" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-emerald-500/50 transition-colors" />
                        </div>
                        <div className="flex items-center h-full pt-6">
                            <label className="flex items-center gap-3 cursor-pointer group/check">
                                <div className={cn(
                                    "w-6 h-6 rounded border transition-all flex items-center justify-center",
                                    isOfficial ? "bg-red-500 border-red-500" : "bg-white/5 border-white/10"
                                )}>
                                    {isOfficial && <Save className="h-3 w-3 text-white" />}
                                </div>
                                <input type="checkbox" checked={isOfficial} onChange={e => setIsOfficial(e.target.checked)} className="hidden" />
                                <span className="text-[10px] uppercase font-black tracking-widest text-zinc-400 group-hover/check:text-white transition-colors">Officiel ?</span>
                            </label>
                        </div>
                    </div>
                </div>

                <div className="flex items-center gap-3 mt-8">
                    {link && (
                        <button onClick={handleDelete} className="flex items-center justify-center gap-2 p-3 bg-red-500/10 hover:bg-red-500/20 text-red-500 border border-red-500/20 rounded-xl transition-all">
                            <Trash2 className="h-5 w-5" />
                        </button>
                    )}
                    <button
                        onClick={handleSave}
                        disabled={isPending}
                        className="flex-1 flex items-center justify-center gap-2 px-6 py-4 bg-emerald-500 hover:bg-emerald-600 disabled:opacity-50 text-white rounded-xl text-sm font-black uppercase tracking-widest transition-all shadow-lg shadow-emerald-500/20"
                    >
                        {isPending ? <Loader2 className="h-4 w-4 animate-spin text-white" /> : <Save className="h-4 w-4" />}
                        {link ? "Mettre à jour" : "Ajouter"}
                    </button>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Mic, MicOff, VolumeX, GripVertical, ExternalLink, X } from 'lucide-react';
import { cn } from "@/lib/utils";
import { VoiceUser } from "@/hooks/use-discord-voice";

interface DiscordVoiceOverlayProps {
    users: VoiceUser[];
    guildId: string;
    className?: string;
    gamePlayerIds?: string[];
    currentUserId?: string | null;
}

export const DiscordVoiceOverlay: React.FC<DiscordVoiceOverlayProps> = ({ 
    users, 
    guildId,
    className,
    gamePlayerIds = [],
    currentUserId
}) => {
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [isLoaded, setIsLoaded] = useState(false);
    const [confirmUserId, setConfirmUserId] = useState<string | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const dragStart = useRef<{ x: number; y: number } | null>(null);
    const overlayRef = useRef<HTMLDivElement>(null);

    // Filtered users: game participants + always show self
    const filteredUsers = users.filter(u => 
        gamePlayerIds.includes(u.userId) || u.userId === currentUserId
    );

    // Load saved position
    useEffect(() => {
        const saved = localStorage.getItem(`sigil_voice_pos_${guildId}`);
        if (saved) {
            try { setPosition(JSON.parse(saved)); } catch {}
        }
        setIsLoaded(true);
    }, [guildId]);

    // Close confirmation on outside click
    useEffect(() => {
        if (!confirmUserId) return;
        const handler = (e: MouseEvent) => {
            if (overlayRef.current && !overlayRef.current.contains(e.target as Node)) {
                setConfirmUserId(null);
            }
        };
        document.addEventListener('mousedown', handler);
        return () => document.removeEventListener('mousedown', handler);
    }, [confirmUserId]);

    // Manual drag via mousedown/mousemove/mouseup on the handle
    const handleMouseDown = (e: React.MouseEvent) => {
        e.preventDefault();
        dragStart.current = { x: e.clientX - position.x, y: e.clientY - position.y };
        setIsDragging(true);
    };

    useEffect(() => {
        if (!isDragging) return;
        const onMove = (e: MouseEvent) => {
            if (!dragStart.current) return;
            setPosition({ x: e.clientX - dragStart.current.x, y: e.clientY - dragStart.current.y });
        };
        const onUp = (e: MouseEvent) => {
            if (!dragStart.current) return;
            const newPos = { x: e.clientX - dragStart.current.x, y: e.clientY - dragStart.current.y };
            setPosition(newPos);
            localStorage.setItem(`sigil_voice_pos_${guildId}`, JSON.stringify(newPos));
            dragStart.current = null;
            setIsDragging(false);
        };
        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', onUp);
        return () => { window.removeEventListener('mousemove', onMove); window.removeEventListener('mouseup', onUp); };
    }, [isDragging, guildId]);

    if (filteredUsers.length === 0 || !isLoaded) return null;

    const handleUserClick = (user: VoiceUser) => {
        if (confirmUserId === user.userId) {
            // Second click = confirm open Discord
            window.open(`https://discord.com/channels/${guildId}/${user.channelId}`, '_blank');
            setConfirmUserId(null);
        } else {
            setConfirmUserId(user.userId);
        }
    };

    return (
        <div
            ref={overlayRef}
            className={cn("fixed top-24 right-6 z-[200] flex flex-col items-end gap-2", className)}
            style={{ transform: `translate(${position.x}px, ${position.y}px)` }}
        >
            {/* Drag Handle */}
            <div
                onMouseDown={handleMouseDown}
                className={cn(
                    "flex items-center gap-2 px-3 py-1 bg-black/70 backdrop-blur-md rounded-full border border-white/10 mb-1 cursor-move select-none group transition-all hover:border-indigo-500/50",
                    isDragging && "border-indigo-500/70 scale-[1.02]"
                )}
            >
                <GripVertical size={10} className="text-white/30 group-hover:text-indigo-400 transition-colors" />
                <span className="text-[10px] font-black uppercase tracking-widest text-white/40 italic">Voice Overlay</span>
                <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
            </div>

            <AnimatePresence mode="popLayout">
                {filteredUsers.map((user) => {
                    const isInGame = gamePlayerIds.includes(user.userId);
                    const isMe = user.userId === currentUserId;
                    const isTalkingActive = user.isSpeaking && !user.isMute && !user.isDeaf;
                    const isConfirming = confirmUserId === user.userId;

                    return (
                        <motion.div
                            key={user.userId}
                            layout
                            initial={{ opacity: 0, x: 20, scale: 0.85 }}
                            animate={{ opacity: 1, x: 0, scale: 1 }}
                            exit={{ opacity: 0, x: 10, scale: 0.9 }}
                            className="relative"
                        >
                            {/* Confirmation mini-panel */}
                            <AnimatePresence>
                                {isConfirming && (
                                    <motion.div
                                        initial={{ opacity: 0, y: -8, scale: 0.9 }}
                                        animate={{ opacity: 1, y: 0, scale: 1 }}
                                        exit={{ opacity: 0, y: -8, scale: 0.9 }}
                                        className="absolute right-full mr-3 top-1/2 -translate-y-1/2 flex items-center gap-2 px-3 py-2 bg-black/90 backdrop-blur-xl border border-white/20 rounded-2xl shadow-2xl z-50 whitespace-nowrap"
                                    >
                                        <span className="text-[10px] font-black text-white/70 uppercase tracking-widest italic">Ouvrir Discord ?</span>
                                        <button
                                            onClick={() => { window.open(`https://discord.com/channels/${guildId}/${user.channelId}`, '_blank'); setConfirmUserId(null); }}
                                            className="px-2 py-1 rounded-lg bg-indigo-500 hover:bg-indigo-400 text-white text-[9px] font-black uppercase tracking-widest transition-all"
                                        >
                                            Oui
                                        </button>
                                        <button
                                            onClick={() => setConfirmUserId(null)}
                                            className="p-1 rounded-lg bg-white/10 hover:bg-white/20 text-white/60 transition-all"
                                        >
                                            <X size={10} />
                                        </button>
                                    </motion.div>
                                )}
                            </AnimatePresence>

                            {/* User Card */}
                            <div
                                onClick={() => handleUserClick(user)}
                                className={cn(
                                    "flex items-center gap-3 p-1.5 pr-4 rounded-2xl border transition-all duration-200 cursor-pointer relative overflow-hidden select-none",
                                    // Speaking = bright green card
                                    isTalkingActive
                                        ? "bg-emerald-500/20 border-emerald-400/60 shadow-[0_0_20px_rgba(16,185,129,0.4)]"
                                        : isInGame || isMe
                                            ? "bg-indigo-500/10 border-indigo-500/30 hover:border-indigo-400/50"
                                            : "bg-black/60 border-white/10 backdrop-blur-xl hover:border-white/20"
                                )}
                            >
                                {/* Speaking background pulse */}
                                <AnimatePresence>
                                    {isTalkingActive && (
                                        <motion.div
                                            key="speak-bg"
                                            initial={{ opacity: 0 }}
                                            animate={{ opacity: [0.15, 0.35, 0.15] }}
                                            exit={{ opacity: 0 }}
                                            transition={{ repeat: Infinity, duration: 0.8 }}
                                            className="absolute inset-0 bg-emerald-500 pointer-events-none"
                                        />
                                    )}
                                </AnimatePresence>

                                {/* Avatar */}
                                <div className="relative z-10 flex-shrink-0">
                                    <div className={cn(
                                        "w-8 h-8 rounded-xl overflow-hidden border-2 transition-all duration-200",
                                        isTalkingActive
                                            ? "border-emerald-400 shadow-[0_0_12px_rgba(16,185,129,0.8)] scale-110"
                                            : isInGame || isMe ? "border-indigo-500/50" : "border-white/10"
                                    )}>
                                        <img src={user.avatar || ""} alt={user.userName} className="w-full h-full object-cover" />
                                    </div>

                                    {/* Mic/Deaf icons */}
                                    <div className="absolute -bottom-1 -right-1 z-20">
                                        {user.isDeaf ? (
                                            <div className="p-0.5 bg-red-500 rounded-md border border-black shadow-lg">
                                                <VolumeX size={8} className="text-white" />
                                            </div>
                                        ) : user.isMute ? (
                                            <div className="p-0.5 bg-zinc-700 rounded-md border border-black shadow-lg">
                                                <MicOff size={8} className="text-white" />
                                            </div>
                                        ) : isTalkingActive ? (
                                            <motion.div
                                                initial={{ scale: 0 }}
                                                animate={{ scale: [1, 1.2, 1] }}
                                                transition={{ repeat: Infinity, duration: 0.5 }}
                                                className="p-0.5 bg-emerald-500 rounded-md border border-black shadow-[0_0_8px_rgba(16,185,129,0.9)]"
                                            >
                                                <Mic size={8} className="text-white" />
                                            </motion.div>
                                        ) : null}
                                    </div>
                                </div>

                                {/* Name + Channel */}
                                <div className="flex flex-col relative z-10 min-w-0">
                                    <div className="flex items-center gap-1.5">
                                        <span className={cn(
                                            "text-xs font-black italic uppercase tracking-tight transition-colors truncate max-w-[100px]",
                                            isTalkingActive ? "text-emerald-300" : isInGame || isMe ? "text-indigo-300" : "text-white/80"
                                        )}>
                                            {user.userName}{isMe && " (Moi)"}
                                        </span>
                                        {(isInGame || isMe) && !isTalkingActive && (
                                            <div className="w-1 h-1 rounded-full bg-indigo-500 flex-shrink-0" />
                                        )}
                                    </div>
                                    <span className="text-[8px] font-bold text-white/30 truncate max-w-[80px]">
                                        # {user.channelName}
                                    </span>
                                </div>

                                {/* Discord link hint */}
                                <ExternalLink size={10} className={cn(
                                    "ml-auto flex-shrink-0 transition-colors relative z-10",
                                    isConfirming ? "text-indigo-400" : "text-white/10 group-hover:text-white/30"
                                )} />
                            </div>
                        </motion.div>
                    );
                })}
            </AnimatePresence>
        </div>
    );
};

"use client";

import React, { useState, useEffect, useRef, useCallback } from "react";
import { io, Socket } from "socket.io-client";
import { buildWsUrl } from "@/lib/socket-utils";
import { Eye, Users, Gamepad2, X, Loader2, Sparkles, Trophy, Play, Activity, Terminal } from "lucide-react";
import { cn } from "@/lib/utils";
import { useParams, useRouter } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";

interface LiveRoom {
    id?: string;
    roomId?: string;
    hostName?: string;
    playerCount: number;
    maxPlayers: number;
    gameType: 'guesser' | 'draw' | 'phone';
}

interface GamesLiveWidgetProps {
    isOpen: boolean;
    onOpenChange: (open: boolean) => void;
    onRoomCountChange?: (count: number) => void;
    guildId?: string;
}

export function GamesLiveWidget({ isOpen, onOpenChange, onRoomCountChange, guildId: propGuildId }: GamesLiveWidgetProps) {
    const params = useParams();
    const guildId = propGuildId || params.guildId as string;
    const router = useRouter();
    const [rooms, setRooms] = useState<LiveRoom[]>([]);
    const [socket, setSocket] = useState<Socket | null>(null);

    const getWsUrl = useCallback((): string => {
        return buildWsUrl();
    }, []);

    useEffect(() => {
        if (!guildId) return;

        const s = io(getWsUrl(), {
            path: "/socket.io/",
            transports: ["websocket", "polling"],
            reconnectionAttempts: 5,
            query: { guildId }
        });

        const refreshRooms = () => {
            s.emit("geoguesser:room:list");
            s.emit("skribbl:room:list");
            s.emit("gartic:room:list");
        };

        s.on("connect", refreshRooms);

        const handleRoomUpdate = (type: 'guesser' | 'draw' | 'phone') => (data: any[]) => {
            setRooms(prev => {
                const other = prev.filter(r => r.gameType !== type);
                const next = (data || []).map(r => ({ ...r, gameType: type }));
                const updated = [...other, ...next];
                return updated;
            });
        };

        s.on("geoguesser:room:list", handleRoomUpdate('guesser'));
        s.on("skribbl:room:list", handleRoomUpdate('draw'));
        s.on("gartic:room:list", handleRoomUpdate('phone'));

        setSocket(s);
        const timer = setInterval(refreshRooms, 5000);

        return () => {
            s.disconnect();
            clearInterval(timer);
        };
    }, [guildId, getWsUrl]);

    useEffect(() => {
        onRoomCountChange?.(rooms.length);
    }, [rooms.length, onRoomCountChange]);

    const handleSpectate = (room: LiveRoom) => {
        const rid = room.id || room.roomId;
        if (!rid) return;

        onOpenChange(false);

        if (room.gameType === 'guesser') {
             router.push(`/dashboard/${guildId}/mini-jeux?spectateRoom=${rid}`);
        } else if (room.gameType === 'draw') {
             router.push(`/dashboard/${guildId}/mini-jeux/skribbl?room=${rid}&spectate=true`);
        } else if (room.gameType === 'phone') {
             router.push(`/dashboard/${guildId}/mini-jeux/gartic?room=${rid}&spectate=true`);
        }
    };

    return (
        <AnimatePresence>
            {isOpen && (
                <div className="fixed top-[76px] right-24 z-[100] animate-in fade-in slide-in-from-top-2 duration-300">
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95, y: -10 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.95, y: -10 }}
                        className="w-80 bg-zinc-900/95 backdrop-blur-3xl border border-white/10 rounded-2xl shadow-[0_30px_60px_rgba(0,0,0,0.6)] overflow-hidden flex flex-col ring-1 ring-white/10"
                    >
                        {/* Header */}
                        <div className="p-4 border-b border-white/5 bg-white/5 flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className="p-1.5 bg-emerald-500/20 rounded-lg">
                                    <Activity className="w-3.5 h-3.5 text-emerald-400 animate-pulse" />
                                </div>
                                <div>
                                    <h3 className="text-white font-black text-[10px] uppercase italic tracking-widest">Parties en cours</h3>
                                </div>
                            </div>
                            <button 
                                onClick={() => onOpenChange(false)}
                                className="p-1.5 hover:bg-white/10 rounded-lg text-white/20 hover:text-white transition-all"
                            >
                                <X size={16} />
                            </button>
                        </div>

                        {/* List */}
                        <div className="p-3 max-h-[350px] overflow-y-auto custom-scrollbar flex flex-col gap-2">
                            {rooms.length === 0 ? (
                                <div className="py-8 flex flex-col items-center justify-center gap-3 text-white/10 italic">
                                    <Gamepad2 size={32} strokeWidth={1} />
                                    <span className="text-[9px] font-black uppercase tracking-widest text-center px-4">Aucune partie trouvée...</span>
                                </div>
                            ) : (
                                rooms.map((room, idx) => (
                                    <div 
                                        key={`${room.gameType}-${room.id || room.roomId || idx}`}
                                        className="bg-white/5 border border-white/5 rounded-xl p-3 flex items-center justify-between hover:bg-white/10 hover:border-white/10 transition-all"
                                    >
                                        <div className="flex flex-col gap-0.5 min-w-0 pr-2">
                                            <div className="flex items-center gap-1.5">
                                                <span className={cn(
                                                    "px-1 py-0.5 rounded-[4px] text-[7px] font-black uppercase italic",
                                                    room.gameType === 'guesser' ? "bg-emerald-500/20 text-emerald-400" :
                                                    room.gameType === 'draw' ? "bg-blue-500/20 text-blue-400" :
                                                    "bg-amber-500/20 text-amber-400"
                                                )}>
                                                    {room.gameType === 'guesser' ? 'Guesser' : room.gameType === 'draw' ? 'Draw' : 'Phone'}
                                                </span>
                                                <span className="text-white/40 text-[9px] font-black italic">{room.playerCount}/{room.maxPlayers}</span>
                                            </div>
                                            <span className="text-white font-black text-[10px] uppercase italic truncate">
                                                {room.hostName || (room.id || room.roomId || "").slice(0, 8)}
                                            </span>
                                        </div>

                                        <button 
                                            onClick={() => handleSpectate(room)}
                                            className="px-3 py-1.5 bg-white/10 hover:bg-white text-white hover:text-black rounded-lg transition-all font-black uppercase italic text-[8px] active:scale-95 flex items-center gap-1.5"
                                        >
                                            <Eye size={10} />
                                            Live
                                        </button>
                                    </div>
                                ))
                            )}
                        </div>

                        {/* Footer Link */}
                        <button 
                            onClick={() => { router.push(`/dashboard/${guildId}/mini-jeux`); onOpenChange(false); }}
                            className="p-3 bg-white/5 text-center text-white/40 hover:text-white text-[9px] font-black uppercase italic tracking-widest transition-all hover:bg-white/10 flex items-center justify-center gap-2"
                        >
                            Arcade
                            <Play size={8} />
                        </button>
                    </motion.div>
                </div>
            )}
        </AnimatePresence>
    );
}

"use client";

import React, { useState } from "react";
import { Share2, Check, Copy } from "lucide-react";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { motion, AnimatePresence } from "framer-motion";

interface ShareRoomButtonProps {
    roomId: string;
    className?: string;
}

export function ShareRoomButton({ roomId, className }: ShareRoomButtonProps) {
    const [copied, setCopied] = useState(false);

    const handleShare = async () => {
        const url = new URL(window.location.href);
        url.searchParams.set("room", roomId);
        const fullUrl = url.toString();

        // Avoid native share sheet on desktop (it's annoying for copy-link intent)
        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);

        try {
            if (isMobile && navigator.share) {
                await navigator.share({
                    title: "Rejoins-moi sur SigilOS !",
                    text: `J'ai ouvert une salle (${roomId}). Viens jouer !`,
                    url: fullUrl,
                });
            } else {
                await navigator.clipboard.writeText(fullUrl);
                setCopied(true);
                toast.success("Lien copié dans le presse-papier !");
                setTimeout(() => setCopied(false), 2000);
            }
        } catch (err) {
            console.error("Erreur de partage:", err);
            // Fallback to clipboard if share cancelled or failed
            try {
                await navigator.clipboard.writeText(fullUrl);
                setCopied(true);
                toast.success("Lien copié !");
                setTimeout(() => setCopied(false), 2000);
            } catch (clipErr) {
                console.error("Clipboard fallback failed:", clipErr);
            }
        }
    };

    return (
        <button
            onClick={handleShare}
            className={cn(
                "group relative flex items-center gap-3 px-6 py-3 rounded-2xl bg-black/40 backdrop-blur-xl border border-white/10 hover:border-indigo-500/50 hover:bg-black/60 transition-all active:scale-95",
                className
            )}
        >
            <div className="flex flex-col items-start leading-none pointer-events-none">
                <span className="text-[8px] font-black text-white/20 uppercase tracking-[0.3em] italic mb-1">Partager</span>
                <span className="text-sm font-black text-white italic tracking-tighter uppercase">{roomId}</span>
            </div>
            
            <div className="w-10 h-10 rounded-xl bg-white/5 flex items-center justify-center group-hover:bg-indigo-500 group-hover:text-white transition-all">
                <AnimatePresence mode="wait">
                    {copied ? (
                        <motion.div
                            key="check"
                            initial={{ scale: 0.5, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            exit={{ scale: 0.5, opacity: 0 }}
                        >
                            <Check size={18} />
                        </motion.div>
                    ) : (
                        <motion.div
                            key="share"
                            initial={{ scale: 0.5, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            exit={{ scale: 0.5, opacity: 0 }}
                        >
                            <Share2 size={18} className="group-hover:rotate-12 transition-transform" />
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>

            {/* Premium Shine Effect */}
            <div className="absolute inset-0 rounded-2xl overflow-hidden pointer-events-none">
                <div className="absolute top-[-100%] left-[-100%] w-[300%] h-[300%] bg-gradient-to-br from-white/0 via-white/[0.05] to-white/0 rotate-45 animate-shine opacity-0 group-hover:opacity-100 transition-opacity" />
            </div>

            <style jsx>{`
                @keyframes shine {
                    0% { transform: translate(-100%, -100%) rotate(45deg); }
                    100% { transform: translate(100%, 100%) rotate(45deg); }
                }
                .animate-shine {
                    animation: shine 1.5s infinite;
                }
            `}</style>
        </button>
    );
}

import React, { useEffect, useRef, useState } from "react";
import { Socket } from "socket.io-client";
import { Eraser, Trash2, Undo, Loader2, PenLine, PaintBucket } from "lucide-react";
import { cn } from "@/lib/utils";

interface CanvasPanelProps {
    socket: Socket;
    gameState: any;
    isDrawer: boolean;
    isSpectator?: boolean;
}

export default function CanvasPanel({ socket, gameState, isDrawer, isSpectator }: CanvasPanelProps) {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const [isDrawing, setIsDrawing] = useState(false);
    const [color, setColor] = useState("#000000");
    const [lineWidth, setLineWidth] = useState(5);
    const [tool, setTool] = useState<"pen" | "fill">("pen");
    const [lastPos, setLastPos] = useState<{ x: number, y: number, normX: number, normY: number } | null>(null);
    const currentStroke = useRef<any[]>([]);
    const currentPathId = useRef<string | null>(null);

    const colors = [
        "#ffffff", "#dcdcdc", "#ff0000", "#ff8c00", "#ffff00", "#008000", "#0000ff", "#4b0082", "#ee82ee", "#8b4513",
        "#000000", "#808080", "#800000", "#a52a2a", "#ffa500", "#006400", "#40e0d0", "#000080", "#800080", "#ffc0cb"
    ];

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        const setCanvasSize = () => {
            const w = container.clientWidth;
            const h = container.clientHeight;
            if (w > 0 && h > 0 && (canvas.width !== w || canvas.height !== h)) {
                canvas.width = w;
                canvas.height = h;
                // Redraw after resize
                if (gameState.canvasData && Array.isArray(gameState.canvasData)) {
                    redrawCanvas(gameState.canvasData);
                }
            }
        };
        const ro = new ResizeObserver(setCanvasSize);
        ro.observe(container);

        const ctx = canvas.getContext("2d");
        if (!ctx) return;
        ctx.lineCap = "round";
        ctx.lineJoin = "round";

        const drawSegment = (x0: number, y0: number, x1: number, y1: number, col: string, lw: number) => {
            ctx.beginPath();
            ctx.moveTo(x0, y0);
            ctx.lineTo(x1, y1);
            ctx.strokeStyle = col;
            ctx.lineWidth = lw;
            ctx.stroke();
            ctx.closePath();
        };

        const hexToRgb = (hex: string) => {
            const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
            return result ? [parseInt(result[1], 16), parseInt(result[2], 16), parseInt(result[3], 16), 255] : [0,0,0,255];
        };

        const performFloodFill = (cx: number, cy: number, fillColor: string) => {
            const canvasData = ctx.getImageData(0, 0, canvas.width, canvas.height);
            const data = canvasData.data;
            const targetColorArr = hexToRgb(fillColor);
            
            const getPixelIdx = (px: number, py: number) => (py * canvas.width + px) * 4;
            
            const startIdx = getPixelIdx(cx, cy);
            const startR = data[startIdx];
            const startG = data[startIdx+1];
            const startB = data[startIdx+2];
            const startA = data[startIdx+3];

            if (startR === targetColorArr[0] && startG === targetColorArr[1] && startB === targetColorArr[2]) return;

            const matchStartColor = (idx: number) => {
                return data[idx] === startR && data[idx+1] === startG && data[idx+2] === startB && data[idx+3] === startA;
            };

            const stack = [[cx, cy]];
            while (stack.length) {
                const [x, y] = stack.pop()!;
                if (x < 0 || y < 0 || x >= canvas.width || y >= canvas.height) continue;
                const i = getPixelIdx(x, y);
                if (!matchStartColor(i)) continue;

                data[i] = targetColorArr[0];
                data[i+1] = targetColorArr[1];
                data[i+2] = targetColorArr[2];
                data[i+3] = targetColorArr[3];

                stack.push([x+1, y], [x-1, y], [x, y+1], [x, y-1]);
            }
            ctx.putImageData(canvasData, 0, 0);
        };

        socket.on("skribbl:draw:stroke", (dataList: any[]) => {
            if (!Array.isArray(dataList)) dataList = [dataList];
            dataList.forEach(data => {
                if (data.type === "fill") {
                    const cx = Math.floor(data.normX * canvas.width);
                    const cy = Math.floor(data.normY * canvas.height);
                    performFloodFill(cx, cy, data.color);
                } else {
                    const x0 = data.x0 * canvas.width;
                    const y0 = data.y0 * canvas.height;
                    const x1 = data.x1 * canvas.width;
                    const y1 = data.y1 * canvas.height;
                    drawSegment(x0, y0, x1, y1, data.color, data.lineWidth || 5);
                }
            });
        });

        socket.on("skribbl:draw:clear", () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
        });

        // ── Move redrawCanvas UP so setCanvasSize can use it ──
        const redrawCanvas = (actions: any[]) => {
            if (!canvas) return;
            const ctx2 = canvas.getContext("2d");
            if (!ctx2) return;
            ctx2.clearRect(0, 0, canvas.width, canvas.height);
            actions.forEach((dataList: any) => {
                const arr = Array.isArray(dataList) ? dataList : [dataList];
                arr.forEach((data: any) => {
                    if (data.type === "fill") {
                        const cx = Math.floor((data.normX as number) * canvas.width);
                        const cy = Math.floor((data.normY as number) * canvas.height);
                        performFloodFill(cx, cy, data.color);
                    } else {
                        const x0 = (data.x0 as number) * canvas.width;
                        const y0 = (data.y0 as number) * canvas.height;
                        const x1 = (data.x1 as number) * canvas.width;
                        const y1 = (data.y1 as number) * canvas.height;
                        drawSegment(x0, y0, x1, y1, data.color, data.lineWidth || 5);
                    }
                });
            });
        };

        setCanvasSize(); // Initial call

        // Redraw on mount or when gameState changes
        if (gameState.canvasData && Array.isArray(gameState.canvasData)) {
            redrawCanvas(gameState.canvasData);
        }

        socket.on("skribbl:canvas:restore", ({ actions }) => {
            redrawCanvas(actions);
        });

        socket.on("skribbl:draw:undo", () => {
            // Server handles undo and emits skribbl:canvas:restore
        });

        socket.on("skribbl:draw:undo", () => {
            // Do not force a rejoin, the server will send a skribbl:canvas:restore event.
        });

        const sendBatch = setInterval(() => {
            if (currentStroke.current.length > 0) {
                socket.emit("skribbl:draw:stroke", currentStroke.current);
                currentStroke.current = [];
            }
        }, 50);

        return () => {
            clearInterval(sendBatch);
            ro.disconnect();
            socket.off("skribbl:draw:stroke");
            socket.off("skribbl:draw:clear");
            socket.off("skribbl:canvas:restore");
            socket.off("skribbl:draw:undo");
        };
    }, [socket, gameState.id]);

    const getMouseCoords = (e: React.MouseEvent | React.TouchEvent | MouseEvent | TouchEvent) => {
        if (!canvasRef.current) return { x: 0, y: 0, normX: 0, normY: 0 };
        const rect = canvasRef.current.getBoundingClientRect();
        let clientX = 0, clientY = 0;

        if ('touches' in e) {
            clientX = e.touches[0].clientX;
            clientY = e.touches[0].clientY;
        } else {
            clientX = (e as React.MouseEvent).clientX;
            clientY = (e as React.MouseEvent).clientY;
        }

        return {
            x: (clientX as number) - rect.left,
            y: (clientY as number) - rect.top,
            normY: ((clientY as number) - rect.top) / rect.height,
            normX: ((clientX as number) - rect.left) / rect.width
        };
    };

    const hexToRgbFast = (hex: string) => {
        const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
        return result ? [parseInt(result[1], 16), parseInt(result[2], 16), parseInt(result[3], 16), 255] : [0,0,0,255];
    };

    const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
        if (!isDrawer) return;
        const { x, y, normX, normY } = getMouseCoords(e);
        
        if (tool === "fill") {
            currentStroke.current.push({
                type: "fill",
                normX, normY, color, pathId: Math.random().toString(36).substring(7)
            });
            const canvas = canvasRef.current;
            const ctx = canvas?.getContext("2d");
            if (canvas && ctx) {
                const canvasData = ctx.getImageData(0, 0, canvas.width, canvas.height);
                const data = canvasData.data;
                const targetColorArr = hexToRgbFast(color);
                const cx = Math.floor(x);
                const cy = Math.floor(y);
                const getPixelIdx = (px: number, py: number) => (py * canvas.width + px) * 4;
                const startIdx = getPixelIdx(cx, cy);
                const startR = data[startIdx];
                const startG = data[startIdx+1];
                const startB = data[startIdx+2];
                const startA = data[startIdx+3];

                if (!(startR === targetColorArr[0] && startG === targetColorArr[1] && startB === targetColorArr[2])) {
                    const matchStartColor = (idx: number) => 
                        data[idx] === startR && data[idx+1] === startG && data[idx+2] === startB && data[idx+3] === startA;

                    const stack = [[cx, cy]];
                    while (stack.length) {
                        const [px, py] = stack.pop()!;
                        if (px < 0 || py < 0 || px >= canvas.width || py >= canvas.height) continue;
                        const i = getPixelIdx(px, py);
                        if (!matchStartColor(i)) continue;

                        data[i] = targetColorArr[0];
                        data[i+1] = targetColorArr[1];
                        data[i+2] = targetColorArr[2];
                        data[i+3] = targetColorArr[3];

                        stack.push([px+1, py], [px-1, py], [px, py+1], [px, py-1]);
                    }
                    ctx.putImageData(canvasData, 0, 0);
                }
            }
            return;
        }

        setIsDrawing(true);
        currentPathId.current = Math.random().toString(36).substring(7);
        setLastPos({ x, y, normX, normY });
    };

    const draw = (e: React.MouseEvent | React.TouchEvent) => {
        if (!isDrawing || !isDrawer || tool !== "pen" || !lastPos || !canvasRef.current) return;
        const { x, y, normX, normY } = getMouseCoords(e);
        const canvas = canvasRef.current;
        const ctx = canvas.getContext("2d");
        if (ctx && lastPos) {
            ctx.beginPath();
            ctx.moveTo(lastPos.x, lastPos.y); 
            ctx.lineTo(x, y);
            ctx.strokeStyle = color;
            ctx.lineWidth = lineWidth;
            ctx.stroke();
            ctx.closePath();
            currentStroke.current.push({
                type: "pen",
                x0: lastPos.normX, y0: lastPos.normY,
                x1: normX, y1: normY,
                color, lineWidth,
                pathId: currentPathId.current
            });
        }
        setLastPos({ x, y, normX, normY });
    };

    const stopDrawing = () => {
        setIsDrawing(false);
        setLastPos(null);
        currentPathId.current = null;
    };

    const clearCanvas = () => {
        if (!isDrawer) return;
        const ctx = canvasRef.current?.getContext("2d");
        if (ctx && canvasRef.current) {
            ctx.clearRect(0, 0, canvasRef.current.width, canvasRef.current.height);
        }
        socket.emit("skribbl:draw:clear");
    };

    const undoLast = () => {
        if (!isDrawer) return;
        socket.emit("skribbl:draw:undo");
    };

    return (
        <div className="flex-1 w-full min-h-0 flex flex-col bg-transparent relative gap-3 overflow-hidden">
            <div className="flex-1 bg-white rounded-[2rem] md:rounded-[2.5rem] shadow-2xl relative overflow-hidden border-b-[8px] md:border-b-[14px] border-black/10 min-h-0">
                 <div className="absolute top-0 left-0 w-full flex justify-around px-8 md:px-24 opacity-10 pointer-events-none z-0">
                    {Array.from({length: 15}).map((_, i) => (
                        <div key={i} className="w-2.5 md:w-3.5 h-8 md:h-12 bg-black rounded-full -mt-4 md:-mt-6 shadow-inner" />
                    ))}
                </div>

                <div ref={containerRef} className="absolute inset-0 cursor-crosshair">
                    <canvas
                        ref={canvasRef}
                        className="block w-full h-full cursor-crosshair touch-none"
                        onMouseDown={startDrawing}
                        onMouseMove={draw}
                        onMouseUp={stopDrawing}
                        onMouseOut={stopDrawing}
                        onTouchStart={startDrawing}
                        onTouchMove={draw}
                        onTouchEnd={stopDrawing}
                    />
                </div>
            </div>

            {isDrawer && (
                <div className="bg-white/95 backdrop-blur-md rounded-2xl md:rounded-[2.5rem] px-4 md:px-6 py-3 md:py-4 flex flex-col lg:flex-row items-center justify-center lg:justify-between shrink-0 shadow-2xl border-b-[6px] md:border-b-[8px] border-black/10 z-20 gap-3 md:gap-4">
                    <div className="flex items-center gap-2 md:gap-3 shrink-0">
                        <div className="bg-slate-100 p-2 md:p-3 rounded-xl md:rounded-[1.5rem] border-b-2 border-black/5">
                            <div className="grid grid-cols-5 md:grid-cols-10 gap-1 md:gap-1.5">
                                {colors.map(c => (
                                    <button
                                        key={c}
                                        onClick={() => setColor(c)}
                                        className={cn(
                                            "w-5 h-5 md:w-6 md:h-6 rounded-md border transition-all hover:scale-125 active:scale-95",
                                            color === c ? "ring-2 ring-[#5d3fd3]/30 scale-125 border-white shadow-lg" : "border-black/5"
                                        )}
                                        style={{ backgroundColor: c }}
                                    />
                                ))}
                            </div>
                        </div>
                    </div>

                    <div className="flex items-center gap-4 md:gap-6 flex-wrap justify-center">
                        <div className="flex items-center gap-3 md:gap-4 bg-slate-100/50 px-4 md:px-6 py-2 md:py-3 rounded-[1rem] md:rounded-[1.5rem]">
                            {[4, 10, 20, 40].map(w => (
                                <button key={w} onClick={() => setLineWidth(w)} className="relative group transition-transform active:scale-90">
                                    <div className={cn(
                                        "rounded-full transition-all duration-300",
                                        lineWidth === w ? "bg-[#5d3fd3] ring-2 md:ring-4 ring-[#5d3fd3]/20 shadow-xl scale-125" : "bg-slate-400"
                                    )} style={{ width: Math.max(5, w/2.5), height: Math.max(5, w/2.5) }} />
                                </button>
                            ))}
                        </div>

                        <div className="flex gap-2">
                            {[
                                { id: "pen", icon: <PenLine className="w-4 h-4 md:w-5 md:h-5" /> },
                                { id: "fill", icon: <PaintBucket className="w-4 h-4 md:w-5 md:h-5" /> }
                            ].map(t => (
                                <button key={t.id} onClick={() => setTool(t.id as any)} className={cn(
                                    "w-10 h-10 md:w-12 md:h-12 rounded-lg md:rounded-xl flex items-center justify-center transition-all border-b-[4px] shadow-lg",
                                    tool === t.id ? "bg-[#5d3fd3] text-white border-[#3d2080] scale-105" : "bg-slate-100 text-slate-500 border-slate-300 hover:bg-white"
                                )}>
                                    {t.icon}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="flex items-center gap-2 pl-2 md:pl-4 lg:border-l-2 border-slate-200">
                        <button onClick={undoLast} className="w-10 h-10 md:w-12 md:h-12 rounded-lg md:rounded-xl bg-amber-500 hover:bg-amber-400 text-white flex items-center justify-center border-b-[4px] border-amber-700 active:translate-y-1 active:border-b-0 transition-all shadow-lg group">
                            <Undo className="w-5 h-5 md:w-6 md:h-6 group-hover:-rotate-45 transition-transform" />
                        </button>
                        <button onClick={clearCanvas} className="px-3 md:px-6 h-10 md:h-12 rounded-lg md:rounded-xl bg-red-500 hover:bg-red-400 text-white flex items-center gap-2 border-b-[4px] border-red-700 active:translate-y-1 active:border-b-0 transition-all shadow-lg font-black uppercase italic tracking-tighter text-[10px] md:text-xs text-nowrap">
                            <Trash2 className="w-4 h-4 md:w-5 md:h-5" />
                            <span className="hidden xs:inline">Effacer</span>
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

import React, { useEffect, useRef, useState } from "react";
import { Socket } from "socket.io-client";
import { Send } from "lucide-react";

interface ChatPanelProps {
    socket: Socket;
    messages: any[];
    gameState: any;
    isDrawer: boolean;
    isSpectator?: boolean;
}

export default function ChatPanel({ socket, messages, gameState, isDrawer, isSpectator }: ChatPanelProps) {
    const [input, setInput] = useState("");
    const endRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        endRef.current?.scrollIntoView({ behavior: "smooth" });
    }, [messages]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!input.trim() || isSpectator) return;
        socket.emit("skribbl:chat:guess", { text: input });
        setInput("");
    };

    const getPlaceholder = () => {
        if (isSpectator) return "MODE SPECTATEUR...";
        if (isDrawer) return "VOUS DESSINEZ...";
        return "REPONSE...";
    };

    return (
        <div className="flex flex-col h-full bg-white relative overflow-hidden">
            {/* Chat Header */}
            <div className="px-4 md:px-6 py-2.5 md:py-4 border-b border-slate-100 bg-slate-50/50 flex items-center justify-between shrink-0">
                <span className="text-[8px] md:text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] italic">COMMUNICATIONS</span>
                <div className="flex items-center gap-1.5 bg-[#5d3fd3]/10 px-2 py-0.5 md:py-1 rounded-lg">
                    <span className="w-1 md:w-1.5 h-1 md:h-1.5 bg-[#5d3fd3] rounded-full animate-pulse" />
                    <span className="text-[6px] md:text-[8px] font-black text-[#5d3fd3] uppercase italic">LIVE</span>
                </div>
            </div>

            <div className="flex-grow overflow-y-auto p-2 md:p-4 space-y-2 md:space-y-3 custom-scrollbar">
                {messages.map((msg, i) => {
                    if (msg.type === "system") {
                         return (
                            <div key={i} className="flex justify-center my-1 md:my-2">
                                <div className="bg-slate-100 px-3 md:px-4 py-1 rounded-full border border-slate-200">
                                    <span className="text-[8px] md:text-[10px] font-black text-slate-500 uppercase italic tracking-tighter">
                                        {msg.text}
                                    </span>
                                </div>
                            </div>
                         );
                    }

                    if (msg.type === "success") {
                        return (
                            <div key={i} className="flex flex-col items-center gap-1 my-2 md:my-4 animate-in zoom-in-95 duration-300">
                                <div className="bg-emerald-500 text-white px-4 md:px-6 py-1.5 md:py-2.5 rounded-xl md:rounded-[1.5rem] shadow-xl shadow-emerald-500/20 border-b-2 md:border-b-4 border-emerald-700">
                                    <span className="font-black text-[10px] md:text-xs uppercase italic tracking-tighter text-center">{msg.text}</span>
                                </div>
                            </div>
                        );
                    }

                    if (msg.type === "warning") {
                        return (
                            <div key={i} className="flex justify-center my-1 md:my-2">
                                <div className="bg-amber-100 px-3 md:px-4 py-1 rounded-full border border-amber-200">
                                    <span className="text-[8px] md:text-[10px] font-black text-amber-700 uppercase italic tracking-tighter">
                                        {msg.text}
                                    </span>
                                </div>
                            </div>
                        );
                    }

                    if (!msg.type && gameState.state === "DRAWING" && !isSpectator && !isDrawer) {
                        return null; // Hide guesses during DRAWING phase
                    }

                    return (
                        <div key={i} className="flex flex-col gap-0.5 md:gap-1 items-start group">
                            <span className="text-[8px] md:text-[9px] font-black text-slate-400 uppercase tracking-widest italic ml-1.5 md:ml-3">
                                {msg.sender}
                            </span>
                            <div className="bg-slate-50 border border-slate-200 px-3 md:px-5 py-2 md:py-3 rounded-lg md:rounded-[1.5rem] rounded-tl-none shadow-sm group-hover:bg-white group-hover:shadow-md transition-all">
                                <span className="text-xs md:text-sm font-bold text-slate-800 leading-relaxed break-words">
                                    {msg.text}
                                </span>
                            </div>
                        </div>
                    );
                })}
                <div ref={endRef} />
            </div>

            <div className="p-2 md:p-4 bg-slate-50/80 backdrop-blur-md border-t border-slate-100 shrink-0">
                <form onSubmit={handleSubmit} className="relative group">
                    <input
                        type="text"
                        value={input}
                        onChange={e => setInput(e.target.value)}
                        placeholder={getPlaceholder()}
                        disabled={isDrawer || isSpectator}
                        className="w-full bg-white border-2 border-slate-200 rounded-xl md:rounded-[1.5rem] px-4 md:px-6 py-3 md:py-4 text-[10px] md:text-xs font-black text-slate-800 uppercase italic tracking-tighter focus:outline-none focus:border-[#5d3fd3] focus:ring-4 focus:ring-[#5d3fd3]/10 disabled:opacity-50 disabled:bg-slate-100 transition-all shadow-lg placeholder:text-slate-300"
                        autoComplete="off"
                        maxLength={100}
                    />
                    {!isDrawer && !isSpectator && (
                        <button 
                            type="submit"
                            className="absolute right-1.5 top-1/2 -translate-y-1/2 w-8 h-8 md:w-10 md:h-10 bg-[#5d3fd3] text-white rounded-lg md:rounded-2xl flex items-center justify-center shadow-lg hover:scale-110 active:scale-95 transition-transform"
                        >
                            <Send className="w-3.5 h-3.5 md:w-4 md:h-4" strokeWidth={3} />
                        </button>
                    )}
                </form>
            </div>
        </div>
    );
}

