                                                                <span className="text-[10px] font-black text-white/20 bg-white/5 px-2 py-0.5 rounded-lg">
                                                                    {achv.hasCompleted.length}
                                                                </span>
                                                            </div>
                                                            <div className="grid grid-cols-1 gap-2 max-h-[200px] overflow-y-auto custom-scrollbar pr-2">
                                                                {achv.hasCompleted.length > 0 ? achv.hasCompleted.map((member) => (
                                                                    <MemberPill key={member.id} member={member} />
                                                                )) : (
                                                                    <p className="text-[10px] text-white/10 italic py-2">Aucun succès validé.</p>
                                                                )}
                                                            </div>
                                                        </div>
                                                    </div>
                                                </motion.div>
                                            )}
                                        </AnimatePresence>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </div>

                {/* Footer / Actions */}
                <div className="p-6 bg-white/[0.02] border-t border-white/5 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-full bg-amber-500/10 border border-amber-500/20 flex items-center justify-center text-amber-500">
                             <Users size={14} />
                        </div>
                        <p className="text-[10px] text-white/30 font-bold uppercase tracking-widest leading-tight">
                            Consultez les membres de guilde<br/>pour organiser vos groupes
                        </p>
                    </div>
                    <a 
                        href={`/dashboard/${guildId}/donjons-et-quetes`}
                        className="px-6 py-3 rounded-2xl bg-amber-600 text-white font-black text-[10px] uppercase italic shadow-lg shadow-amber-600/20 hover:bg-amber-500 hover:-translate-y-0.5 transition-all flex items-center gap-2"
                    >
                        Créer un groupe <ChevronRight size={14} />
                    </a>
                </div>
            </DialogContent>
        </Dialog>
    );
}

function MemberPill({ member, isMissing }: { member: any, isMissing?: boolean }) {
    const classInfo = member.classe ? getClass(member.classe) : null;
    
    return (
        <div className={`flex items-center gap-3 p-2 rounded-xl border transition-all ${isMissing ? "bg-white/[0.03] border-white/5 hover:border-white/10" : "bg-emerald-500/5 border-emerald-500/10 opacity-60"}`}>
            <div className="w-6 h-6 rounded-lg bg-black/40 border border-white/10 overflow-hidden flex items-center justify-center shrink-0">
                {member.imageUrl ? (
                    <img src={member.imageUrl} alt="" className="w-full h-full object-cover" />
                ) : (
                    <Users size={12} className="text-white/20" />
                )}
            </div>
            <span className="text-[11px] font-bold text-white/70 truncate flex-1 uppercase tracking-tighter">
                {member.name}
            </span>
            {classInfo && (
                <div className="w-4 h-4 rounded overflow-hidden opacity-50 shadow-inner">
                    <img src={classInfo.icon} alt={member.classe} className="w-full h-full object-contain" />
                </div>
            )}
        </div>
    );
}

'use client';

import React from 'react';
import { Clock, Trophy, Flag, Mic } from 'lucide-react';
import { cn } from '@/lib/utils';

interface GeoguesserHUDProps {
    round: number;
    maxRounds: number;
    timeLeft: number;
    score: number;
    gamePhase: 'playing' | 'result' | 'summary';
    spectators?: any[];
    voiceUsers?: any[];
    onReportMap?: () => void;
}

export default function GeoguesserHUD({ round, maxRounds, timeLeft, score, gamePhase, spectators = [], voiceUsers = [], onReportMap }: GeoguesserHUDProps) {
    const voiceUserIds = voiceUsers.map(u => u.userId);
    return (
        <div className="flex items-center justify-center gap-2 sm:gap-4 animate-in slide-in-from-top-10 duration-700 pointer-events-auto">
            {/* Spectators - Floating on the left */}
            {spectators.length > 0 && (
                <div className="hidden lg:flex items-center gap-3 px-4 py-2 bg-slate-900 border border-white/5 rounded-2xl mr-2">
                    <div className="flex -space-x-2">
                        {spectators.slice(0, 3).map(s => (
                             <div key={s.userId || s.id} className="w-6 h-6 rounded-lg border border-black p-0.5 bg-zinc-900 overflow-hidden grayscale opacity-60 hover:grayscale-0 hover:opacity-100 transition-all cursor-help relative" title={s.userName}>
                                 <img src={s.userAvatar || `https://api.dicebear.com/7.x/bottts/svg?seed=${s.userName}`} className="w-full h-full object-cover rounded-md" alt="" />
                                 {voiceUserIds.includes(s.userId) && (
                                     <div className="absolute -top-0.5 -right-0.5 z-10 p-0.5 bg-emerald-500 rounded border border-zinc-950 shadow-sm">
                                         <Mic size={6} className="text-white fill-white/20" />
                                     </div>
                                 )}
                             </div>
                        ))}
                        {spectators.length > 3 && (
                            <div className="w-6 h-6 rounded-lg bg-zinc-800 border border-white/5 flex items-center justify-center text-[8px] font-black text-white/40">
                                +{spectators.length - 3}
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* Round Indicator */}
            <div className="flex flex-col items-center justify-center px-4 py-2 sm:px-6 bg-[#1a1c23]/90 backdrop-blur-xl border border-white/10 rounded-xl sm:rounded-2xl shadow-[0_10px_30px_rgba(0,0,0,0.5)] ring-1 ring-white/5">
                <span className="text-[8px] sm:text-[9px] text-white/30 font-black uppercase tracking-[0.2em] mb-0.5 italic">Round</span>
                <span className="text-white font-black text-lg sm:text-xl italic tracking-tighter leading-none">
                    {round}<span className="text-white/20">/{maxRounds}</span>
                </span>
            </div>

            {/* Timer */}
            <div className={cn(
                "group flex flex-col items-center justify-center px-6 py-2 sm:px-10 sm:py-4 bg-[#1a1c23] border-2 transition-all duration-500 rounded-2xl sm:rounded-[2.5rem] shadow-[0_20px_50px_rgba(0,0,0,0.8)] ring-1 ring-white/10",
                timeLeft <= 10 ? "border-red-500/60 ring-red-500/20" : "border-[#a78bfa]/30 ring-purple-500/20"
            )}>
                <span className="text-[8px] sm:text-[9px] text-white/30 font-black uppercase tracking-[0.2em] mb-0.5 italic">Temps restant</span>
                <div className="flex items-center gap-2 sm:gap-3">
                    <Clock size={16} className={cn(
                        "sm:w-5 sm:h-5 transition-transform duration-500",
                        timeLeft <= 10 ? "text-red-500 animate-pulse scale-110" : "text-[#a78bfa]"
                    )} />
                    <span className={cn(
                        "text-xl sm:text-3xl font-black italic tracking-tighter leading-none transition-colors",
                        timeLeft <= 10 ? "text-red-500" : "text-white"
                    )}>
                        {timeLeft}s
                    </span>
                </div>
            </div>

            {/* Score */}
            <div className="flex flex-col items-center justify-center px-4 py-2 sm:px-6 bg-[#1a1c23]/90 backdrop-blur-xl border border-white/10 rounded-xl sm:rounded-2xl shadow-[0_10px_30px_rgba(0,0,0,0.5)] ring-1 ring-white/5">
                <span className="text-[8px] sm:text-[9px] text-white/30 font-black uppercase tracking-[0.2em] mb-0.5 italic">Score</span>
                <div className="flex items-center gap-1 sm:gap-2">
                    <Trophy size={14} className="text-amber-400 sm:w-4 sm:h-4 drop-shadow-[0_0_8px_rgba(251,191,36,0.4)]" />
                    <span className="text-white font-black text-lg sm:text-xl italic tracking-tighter leading-none">{score}</span>
                </div>
            </div>

            {/* Report Button removed from playing phase per user request. Available in result phase only. */}
        </div>
    );
}

'use client';

import React, { useState, useRef } from 'react';
import { motion, AnimatePresence, useDragControls } from 'framer-motion';
import { X, Maximize2, Minimize2, MapPin, RefreshCw, Swords, Plus, Minus, Layers } from 'lucide-react';
import { cn } from '@/lib/utils';



interface MapDetailsPanelProps {
    position: { x: number; y: number; displayX: number; displayY: number; mapId?: number };
    allLayers?: any[];
    subAreaName?: string;
    guildId: string;
    onClose: () => void;
    onOpenZoneDetails?: () => void;
    onSelectMap?: (map: any) => void;
}

export default function MapDetailsPanel({ 
    position, 
    allLayers = [], 
    subAreaName, 
    guildId, 
    onClose, 
    onOpenZoneDetails,
    onSelectMap
}: MapDetailsPanelProps) {
    const [isMaximized, setIsMaximized] = useState(false);
    const [zoom, setZoom] = useState(1);
    const [pan, setPan] = useState({ x: 0, y: 0 });
    const containerRef = useRef<HTMLDivElement>(null);
    const dragControls = useDragControls();



    // HD Map URL
    const hdMapUrl = position.mapId ? `/game-data/hd_maps/${position.mapId}.webp` : null;

    const handleZoomIn = () => setZoom(prev => Math.min(prev + 0.5, 4));
    const handleZoomOut = () => {
        setZoom(prev => {
            const next = Math.max(prev - 0.5, 1);
            if (next === 1) setPan({ x: 0, y: 0 });
            return next;
        });
    };
    const handleReset = () => {
        setZoom(1);
        setPan({ x: 0, y: 0 });
    };

    const handleWheel = (e: React.WheelEvent) => {
        if (e.deltaY < 0) handleZoomIn();
        else handleZoomOut();
    };

    return (
        <AnimatePresence>
            {/* Backdrop for maximized mode */}
            {isMaximized && (
                <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    onClick={onClose}
                    className="fixed inset-0 bg-black/80 backdrop-blur-sm z-[4999]"
                />
            )}

            <motion.div
                initial={{ 
                    opacity: 0, 
                    scale: 0.9, 
                    x: isMaximized ? '-50%' : 20, 
                    y: isMaximized ? '-50%' : 0,
                    left: isMaximized ? '50%' : 'auto',
                    right: isMaximized ? 'auto' : '2rem',
                    top: isMaximized ? '50%' : 'auto',
                    bottom: isMaximized ? 'auto' : '2rem',
                }}
                animate={{
                    opacity: 1,
                    scale: 1,
                    width: isMaximized ? 'min(1400px, 95vw)' : 'min(440px, 95vw)',
                    height: isMaximized ? 'min(900px, 90vh)' : 'min(500px, calc(100vh - 100px))',
                    left: isMaximized ? '50%' : 'auto',
                    top: isMaximized ? '50%' : 'auto',
                    x: isMaximized ? '-50%' : 0,
                    y: isMaximized ? '-50%' : 0,
                    right: isMaximized ? 'auto' : '2rem', 
                    bottom: isMaximized ? 'auto' : '2rem',
                    borderRadius: isMaximized ? '2.5rem' : '2rem',
                }}
                transition={{
                    type: 'spring',
                    damping: 25,
                    stiffness: 200,
                    mass: 0.8
                }}
                exit={{ opacity: 0, scale: 0.9 }}
                drag
                dragControls={dragControls}
                dragListener={false}
                dragMomentum={false}
                className={cn(
                    "overflow-hidden bg-[#020408]/95 backdrop-blur-3xl border border-white/10 shadow-[0_50px_100px_rgba(0,0,0,0.9)] flex flex-col",
                    isMaximized ? "fixed z-[5000] border-white/20" : "absolute z-[1000]"
                )}
            >
                {/* ─── HEADER ─── */}
                <div 
                    onPointerDown={(e) => dragControls.start(e)}
                    className={cn(
                        "flex border-b border-white/5 shrink-0 transition-all cursor-grab active:cursor-grabbing select-none relative z-[100]",
                        isMaximized ? "items-center bg-white/5 px-10 py-6 gap-6" : "flex-col bg-white/5 p-4 gap-4"
                    )}
                >
                    <div className="flex items-center justify-between w-full min-w-0 gap-4">
                        <div className="flex items-center gap-3 min-w-0">
                            <div className={cn(
                                "rounded-2xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-500 shadow-inner shrink-0 transition-all",
                                isMaximized ? "w-12 h-12" : "w-10 h-10"
                            )}>
                                <MapPin size={isMaximized ? 24 : 20} />
                            </div>
                            <div className="min-w-0 pr-2">
                                <h3 className="text-[9px] font-black uppercase tracking-[0.4em] text-white/30 mb-1 truncate">Renseignement Satellite</h3>
                                <h2 className={cn(
                                    "font-black text-white uppercase italic tracking-tighter leading-tight truncate transition-all",
                                    isMaximized ? "text-xl" : "text-sm"
                                )}>
                                    {subAreaName || "Zone Inconnue"}
                                </h2>
                            </div>
                            {isMaximized && (
                                <div className="ml-4 px-3 py-1.5 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center gap-2 shrink-0">
                                    <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                                    <span className="text-[10px] font-black text-emerald-400 italic tracking-widest">
                                        [ {position.x}, {position.y} ]
                                    </span>
                                </div>
                            )}
                        </div>

                        {/* Top-Right Area */}
                        <div className="flex items-center gap-4 shrink-0">


                            {/* Layer Switcher (Visible on the same line ONLY if maximized) */}
                            {isMaximized && allLayers.length > 1 && (
                                <div 
                                    className="flex items-center gap-1.5 p-1.5 rounded-2xl bg-black/40 border border-white/10" 
                                    onPointerDown={(e) => e.stopPropagation()}
                                >
                                    {allLayers.sort((a, b) => (a.altitude || 0) - (b.altitude || 0)).map((layer) => {
                                        const isActive = position.mapId === layer.id;
                                        const label = (layer.altitude ?? 0) === 0 ? "Sol" : (layer.altitude ?? 0) === 1 ? "Air" : `Z${layer.altitude}`;
                                        return (
                                            <button
                                                key={layer.id}
                                                onClick={(e) => { e.stopPropagation(); onSelectMap?.(layer); }}
                                                className={cn(
                                                    "h-8 px-4 rounded-xl flex items-center justify-center transition-all border text-[10px] font-black uppercase italic cursor-pointer whitespace-nowrap",
                                                    isActive 
                                                        ? 'bg-emerald-500 border-emerald-400 text-white shadow-lg' 
                                                        : 'bg-transparent text-white/40 border-transparent hover:bg-white/10 hover:text-white'
                                                )}
                                            >
                                                {label}
                                            </button>
                                        );
                                    })}
                                </div>
                            )}

                            <div className={cn("flex items-center gap-2", isMaximized && "border-l border-white/5 pl-4")}>
                                <button
                                    onPointerDown={e => e.stopPropagation()}
                                    onClick={() => {
                                        setIsMaximized(!isMaximized);
                                        handleReset();
                                    }}
                                    className="p-2.5 rounded-xl bg-white/5 hover:bg-white/10 border border-white/10 text-white/50 transition-all hover:scale-105 active:scale-95 shadow-xl"
                                >
                                    {isMaximized ? <Minimize2 size={16} /> : <Maximize2 size={16} />}
                                </button>
                                <button
                                    onPointerDown={e => e.stopPropagation()}
                                    onClick={onClose}
                                    className="p-2.5 rounded-xl bg-rose-500 text-white shadow-lg shadow-rose-500/20 hover:scale-105 active:scale-95 transition-all"
                                >
                                    <X size={16} />
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Bottom Area: Layer Switcher (small mode) */}
                    {!isMaximized && allLayers.length > 1 && (
                        <div className="flex items-center gap-2 w-full overflow-x-auto no-scrollbar" onPointerDown={e => e.stopPropagation()}>
                            {/* Layer Switcher */}
                            <div className="flex items-center gap-1 p-1 rounded-2xl bg-black/40 border border-white/10 overflow-x-auto no-scrollbar">
                                {allLayers.sort((a, b) => (a.altitude || 0) - (b.altitude || 0)).map((layer) => {
                                    const isActive = position.mapId === layer.id;
                                    const label = (layer.altitude ?? 0) === 0 ? "Sol" : (layer.altitude ?? 0) === 1 ? "Air" : `Z${layer.altitude}`;
                                    return (
                                        <button
                                            key={layer.id}
                                            onClick={(e) => { e.stopPropagation(); onSelectMap?.(layer); }}
                                            className={cn(
                                                "h-7 px-3 rounded-lg flex items-center justify-center transition-all border text-[9px] font-black uppercase italic cursor-pointer whitespace-nowrap",
                                                isActive 
                                                    ? 'bg-emerald-500 border-emerald-400 text-white shadow-lg' 
                                                    : 'bg-transparent text-white/40 border-transparent hover:bg-white/10 hover:text-white'
                                            )}
                                        >
                                            {label}
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                    )}
                </div>

                {/* ─── MAP VIEWPORT (THE CONTENT) ─── */}
                <div className="flex-1 relative bg-[#020408] overflow-hidden min-h-[300px] z-10">
                        <div
                            className="absolute inset-0 cursor-move"
                            ref={containerRef}
                            onWheel={isMaximized ? handleWheel : undefined}
                        >
                            {hdMapUrl ? (
                                <motion.div
                                    animate={{ scale: zoom, x: pan.x, y: pan.y }}
                                    transition={{ type: 'spring', damping: 25, stiffness: 200 }}
                                    drag={zoom > 1}
                                    onDragEnd={(e, info) => setPan(prev => ({ x: prev.x + info.offset.x, y: prev.y + info.offset.y }))}
                                    className="w-full h-full flex items-center justify-center"
                                >
                                    <img
                                        src={hdMapUrl}
                                        alt="HD Preview"
                                        className={cn(
                                            "max-w-full max-h-full object-contain pointer-events-none transition-all duration-700",
                                            isMaximized && "shadow-2xl ring-1 ring-white/5"
                                        )}
                                        onError={(e) => {
                                            (e.target as HTMLImageElement).src = '/game-data/tiles/w1/1/1.webp';
                                        }}
                                    />
                                </motion.div>
                            ) : (
                                <div className="w-full h-full flex flex-col items-center justify-center gap-4 opacity-20">
                                    <Swords size={48} className="text-white" />
                                    <span className="text-white font-black uppercase text-[10px] italic tracking-widest text-center leading-loose">
                                        Visualisation Satellite<br/>indisponible
                                    </span>
                                </div>
                            )}
                        </div>

                        {/* Gradient shadow for bottom readability */}
                        <div className="absolute inset-x-0 bottom-0 h-40 bg-gradient-to-t from-slate-950 to-transparent pointer-events-none z-[20]" />

                        {/* Left Toolbar (Zoom) */}
                        {hdMapUrl && (
                            <div className="absolute left-6 top-1/2 -translate-y-1/2 flex flex-col gap-3 z-[30]">
                                <button 
                                    onPointerDown={(e) => e.stopPropagation()}
                                    onClick={(e) => { e.stopPropagation(); handleZoomIn(); }}
                                    className="w-12 h-12 rounded-2xl bg-slate-950 border border-white/20 text-white flex items-center justify-center shadow-2xl hover:scale-110 active:scale-90 transition-all cursor-pointer"
                                >
                                    <Plus size={20} />
                                </button>
                                <button 
                                    onPointerDown={(e) => e.stopPropagation()}
                                    onClick={(e) => { e.stopPropagation(); handleZoomOut(); }}
                                    className="w-12 h-12 rounded-2xl bg-slate-950 border border-white/20 text-white flex items-center justify-center shadow-2xl hover:scale-110 active:scale-90 transition-all cursor-pointer"
                                >
                                    <Minus size={20} />
                                </button>
                            </div>
                        )}
                </div>

                {/* ─── OVERLAYS DESKTOP / TOP-LEVEL (Outside Main Content for perfect Z-index) ─── */}
                


                {/* Bottom Action Area (Always visible, highest Z) */}
                <div className={cn(
                    "absolute left-8 right-8 flex items-center justify-between pointer-events-none z-[2000] transition-all",
                    isMaximized ? "bottom-12" : "bottom-14"
                )}>
                    <div className="flex items-center gap-3 pointer-events-auto">
                        <div className="px-5 py-3 rounded-2xl bg-black border border-white/20 text-emerald-400 font-mono text-sm font-black shadow-[0_20px_50px_rgba(0,0,0,0.5)] flex items-center gap-3">
                            <div className="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_15px_#10b981]" />
                            <span className="tracking-tight">[{position.displayX}, {position.displayY}]</span>
                        </div>
                        
                        <button 
                            onPointerDown={(e) => e.stopPropagation()}
                            onClick={(e) => {
                                e.preventDefault();
                                e.stopPropagation();
                                onOpenZoneDetails?.();
                            }}
                            className="px-10 py-3 rounded-2xl bg-amber-500 text-black font-black text-xs uppercase italic shadow-[0_20px_50px_rgba(245,158,11,0.3)] hover:scale-105 active:scale-95 transition-all flex items-center gap-2 cursor-pointer relative z-10"
                        >
                            <Layers size={16} /> 
                            Analyser
                        </button>
                    </div>

                    {zoom > 1 && (
                        <button 
                            onPointerDown={(e) => e.stopPropagation()}
                            onClick={(e) => { e.stopPropagation(); handleReset(); }}
                            className="pointer-events-auto w-12 h-12 rounded-2xl bg-white/10 backdrop-blur-xl border border-white/20 text-white flex items-center justify-center shadow-2xl transition-all cursor-pointer hover:bg-white/20"
                        >
                            <RefreshCw size={18} />
                        </button>
                    )}
                </div>

                {/* ─── FOOTER ─── */}
                {!isMaximized && (
                    <div className="h-10 px-8 bg-black/80 border-t border-white/5 flex items-center shrink-0">
                        <div className="flex items-center gap-4 opacity-20">
                            <div className="flex items-center gap-2">
                                <div className="w-1 h-1 rounded-full bg-white" />
                                <span className="text-[7px] font-black uppercase tracking-[0.3em]">Live Feed</span>
                            </div>
                        </div>
                    </div>
                )}
            </motion.div>
        </AnimatePresence>
    );
}

'use client';

