interface LeafletMapCoreProps {
    activeWorld: any | null; // Assuming WorldInfo is a type, using 'any' for simplicity if not defined elsewhere
    selectedWorldId: number;
    activeMaps: any[];
    mapsByCoords: Map<string, any>;
    subAreasById: Map<number, any>;
    dungeonsByMapId: Map<number, any[]>;
    groupedDungeons: any[];
    showDebugGrid: boolean;
    selectedPosition: any;
    setSelectedPosition: (pos: any) => void;
    setSelectedDungeon: (dungeons: any[] | null) => void;
    triggerCenterPosition?: { x: number, y: number } | null;
    triggerWorldId?: number;
    isMiniMap?: boolean;
    guessResult?: { target: any, guess: any } | null;
    mapsBySubAreaId?: Map<number, any[]>;
    minimapZoomLevel?: number;
    minimapRecenterTrigger?: number;
    participants?: any[];
    currentUserId?: string;
    isSpectator?: boolean;
    hideUI?: boolean;
    interactive?: boolean;
    autoCopyTravel?: boolean;
    onHoverMap?: (pos: { x: number, y: number, found: boolean } | null) => void;
    highlightSubareaIds?: number[];
    minZoom?: number;
}
export default function LeafletMapCore(props: LeafletMapCoreProps) {
    const [hoveredCoords, setHoveredCoords] = React.useState<{ x: number, y: number, found?: boolean } | null>(null);

    const {
        activeWorld, selectedWorldId, activeMaps, mapsByCoords, subAreasById,
        dungeonsByMapId, groupedDungeons, showDebugGrid, selectedPosition,
        mapsBySubAreaId, setSelectedPosition, setSelectedDungeon, triggerCenterPosition,
        triggerWorldId, isMiniMap, guessResult, minimapZoomLevel, minimapRecenterTrigger,
        participants, currentUserId, isSpectator, hideUI, interactive = true, 
        autoCopyTravel = false, onHoverMap, highlightSubareaIds
    } = props;

    const correctedActiveWorld = useMemo(() => {
        if (!activeWorld) return null;
        // Calibration précise du Monde des Douze (id=1) :
        // Le dataset DofusDB calcule mapWidth/mapHeight sur base d'un canevas 10000x8000
        // Mais comme nous affichons des tuiles à 256px (40x32 tiles),
        // Le canevas final est étiré par un facteur de (256/250) = 1.024
        // Il FAUT appliquer ce facteur multiplicatif brut sur TOUTES les constantes de base :
        if (activeWorld.id === 1) {
            return {
                ...activeWorld,
                origineX: activeWorld.origineX * 1.024,
                origineY: activeWorld.origineY * 1.024,
                mapWidth: activeWorld.mapWidth * 1.024,
                mapHeight: activeWorld.mapHeight * 1.024,
                totalWidth: activeWorld.totalWidth * 1.024,
                totalHeight: Math.ceil(activeWorld.totalHeight * 1.024)
            };
        }
        return activeWorld;
    }, [activeWorld]);

    if (!correctedActiveWorld) return null;

    if (typeof window !== 'undefined') {
        (window as any)._activeWorld_for_crs = correctedActiveWorld;
    }

    // Dimension des tuiles du monde en cours pour combler parfaitement les trous
    const tileSize = selectedWorldId === 1 ? 256 : 250;

    // Calculate initial center: quest target if exists, else world center
    const initialCenter = useMemo(() => {
        if (triggerCenterPosition && correctedActiveWorld) {
            const lat = -(correctedActiveWorld.origineY + triggerCenterPosition.y * correctedActiveWorld.mapHeight + correctedActiveWorld.mapHeight / 2);
            const lng = correctedActiveWorld.origineX + triggerCenterPosition.x * correctedActiveWorld.mapWidth + correctedActiveWorld.mapWidth / 2;
            return [lat, lng] as [number, number];
        }
        return [-correctedActiveWorld.totalHeight / 2, correctedActiveWorld.totalWidth / 2] as [number, number];
    }, [triggerCenterPosition, correctedActiveWorld]);

    const initialZoom = useMemo(() => {
        if (triggerCenterPosition) return 0; // Standard for quest focus
        return isMiniMap ? -3 : 0;
    }, [triggerCenterPosition, isMiniMap]);

    return (
        <div className="w-full h-full cursor-crosshair relative map-core-wrapper">
            {/* L'UI de la zone survolée est mise à jour manuellement pour des raisons de perfs absolues sans re-render */}
            {!isMiniMap && !hideUI && (
                <div 
                    id="sigil-map-hover-hud"
                    style={{ display: 'none' }}
                    className="absolute bottom-8 left-1/2 -translate-x-[50%] z-[1000] bg-[#2d3139] shadow-[0_8px_32px_rgba(0,0,0,0.6)] rounded-lg pointer-events-auto transition-all duration-200 flex items-center border border-white/10 overflow-visible px-6 py-4 group"
                >
                    {/* Tooltip visible on group hover */}
                    <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-3 bg-[#1a1b1e] text-white text-[11px] font-bold px-4 py-2 rounded shadow-2xl opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap border border-white/5 pointer-events-none">
                        Copier la commande d'auto-pilotage
                        <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-[#1a1b1e]"></div>
                    </div>

                    <div className="flex flex-col justify-center min-w-[200px]">
                        <span id="sigil-map-hover-zone" className="text-white font-black text-xl uppercase tracking-tight leading-none group-hover:text-emerald-400 transition-colors"></span>
                        <div className="flex items-center gap-3 mt-2">
                            <span id="sigil-map-hover-world" className="text-white/30 font-bold text-[10px] uppercase tracking-[0.2em]"></span>
                            <span className="w-1 h-1 rounded-full bg-white/10" />
                            <div className="flex items-center gap-1 bg-black/20 px-2 py-0.5 rounded border border-white/5">
                                <Rocket size={10} className="text-emerald-500" />
                                <span id="sigil-map-hover-coords" className="text-emerald-400 font-black text-[13px] tracking-tight"></span>
                            </div>
                        </div>
                    </div>

                    {/* Rocket Copy Button */}
                    <div className="ml-8 w-12 h-12 bg-emerald-500 rounded-xl flex items-center justify-center shadow-[0_10px_20px_rgba(16,185,129,0.3)] hover:bg-emerald-400 hover:shadow-[0_15px_30px_rgba(16,185,129,0.4)] transition-all cursor-pointer group/btn active:scale-90" onClick={() => {
                        const coords = document.getElementById('sigil-map-hover-coords')?.innerText;
                        if (coords) {
                            const match = coords.match(/\[(.*),(.*)\]/);
                            if (match) {
                                const cmd = `/travel ${match[1].trim()} ${match[2].trim()}`;
                                navigator.clipboard.writeText(cmd);
                                toast.success("Commande copiée !", {
                                    description: cmd,
                                    icon: <Rocket className="w-4 h-4 text-emerald-400" />
                                });
                            }
                        }
                    }}>
                        <Rocket size={22} className="text-emerald-950 group-hover:scale-110 transition-transform" />
                    </div>
                </div>
            )}
            <style>{`
                /* ── Fix jointures de tuiles ABSOLU ──
                   Force la taille exacte des tuiles du monde ciblé + 1 pixel
                   pour un recouvrement garanti qui annule les lignes blanches */
                .leaflet-tile {
                    width: ${tileSize}px !important;
                    height: ${tileSize}px !important;
                    -webkit-backface-visibility: hidden;
                    backface-visibility: hidden;
                    image-rendering: auto;
                    /* Supprime les bordures noires/vides entre les images */
                    outline: none !important;
                    border: none !important;
                    box-shadow: none !important;
                }
                .leaflet-container {
                    background: #080b12 !important;
                    will-change: transform;
                }
                .leaflet-tile-pane {
                    will-change: transform;
                }
                .custom-leaflet-tooltip {
                    background: #111822 !important;
                    border: 1px solid rgba(255, 255, 255, 0.05) !important;
                    color: white !important;
                    font-family: inherit;
                    font-size: 12px;
                    border-radius: 8px;
                    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.5);
                    padding: 6px 12px;
                    white-space: nowrap;
                    pointer-events: none;
                }
                .leaflet-tooltip-left::before, .leaflet-tooltip-right::before { display: none; }
                .dungeon-icon-marker { background: none; border: none; }
                .sigil-grid-canvas { pointer-events: none; }
                
                /* ── GPS Pulse Animation ── */
                @keyframes gps-ping {
                    0% { transform: scale(1); opacity: 0.8; }
                    100% { transform: scale(2.5); opacity: 0; }
                }
                .gps-pulse-outer {
                    animation: gps-ping 2s cubic-bezier(0, 0, 0.2, 1) infinite;
                }
                .gps-pulse-marker {
                    background: none !important;
                    border: none !important;
                }
                
                /* Animation zoom fluide */
                .leaflet-zoom-animated {
                    transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
                }
            `}</style>

            <MapContainer
                key={`${selectedWorldId}-${isMiniMap}-${triggerCenterPosition?.x}-${triggerCenterPosition?.y}`}
                crs={sigilCRS}
                center={initialCenter}
                zoom={initialZoom}
                style={{ height: '100%', width: '100%', outline: 'none' }}
                zoomControl={false}
                attributionControl={false}
                minZoom={isMiniMap ? -6 : Math.max(selectedWorldId !== 1 ? -3 : -4, -(correctedActiveWorld.zoom?.length || 1) - 1)}
                maxZoom={3}
                maxBoundsViscosity={0.8}
                zoomSnap={0.1}
                zoomDelta={1}
                preferCanvas={true}
                dragging={interactive}
                touchZoom={interactive}
                doubleClickZoom={interactive}
                scrollWheelZoom={interactive}
                boxZoom={interactive}
                keyboard={interactive}
            >
                <MapViewHandler
                    isMiniMap={isMiniMap}
                    guessResult={guessResult}
                    activeWorld={correctedActiveWorld}
                    minimapZoomLevel={minimapZoomLevel}
                    minimapRecenterTrigger={minimapRecenterTrigger}
                    participants={participants}
                />
                {/* 1. Tuiles */}
                <SigilTilesLayer activeWorld={correctedActiveWorld} selectedWorldId={selectedWorldId} />

                {/* 2. Grille DofusDB canvas (contour par position), contrôlée par showDebugGrid */}
                <MapGridOverlay
                    activeWorld={correctedActiveWorld}
                    mapsByCoords={mapsByCoords}
                    mapsBySubAreaId={mapsBySubAreaId}
                    subAreasById={subAreasById}
                    showDebugGrid={showDebugGrid}
                    isMiniMap={isMiniMap}
                    guessResult={guessResult}
                    selectedPosition={selectedPosition}
                    participants={participants}
                    currentUserId={currentUserId}
                    highlightSubareaIds={highlightSubareaIds}
                />

                {/* 4. Interactions */}
                <MapInteractionHandler
                    activeWorld={correctedActiveWorld}
                    selectedWorldId={selectedWorldId}
                    mapsByCoords={mapsByCoords}
                    subAreasById={subAreasById}
                    dungeonsByMapId={dungeonsByMapId}
                    setSelectedPosition={setSelectedPosition}
                    isMiniMap={isMiniMap}
                    isSpectator={isSpectator}
                    hideUI={hideUI}
                    interactive={interactive}
                    autoCopyTravel={autoCopyTravel}
                    onHoverMap={setHoveredCoords}
                />

                {/* 5. GPS Narrative Pulse (Highlight for quests) */}
                <MapNarrativeGPS 
                    activeWorld={correctedActiveWorld} 
                    triggerCoords={triggerCenterPosition} 
                    triggerWorldId={triggerWorldId}
                    currentWorldId={selectedWorldId}
                />

                {/* 5. Highlight overlay (click selection) */}

                {/* 6. Dungeon markers (Uniquement si pas mini-map) */}
                {!isMiniMap && groupedDungeons && groupedDungeons.map((group: any) => {
                    const px = correctedActiveWorld.origineX + group.mapNode.x * correctedActiveWorld.mapWidth + correctedActiveWorld.mapWidth / 2;
                    const py = correctedActiveWorld.origineY + group.mapNode.y * correctedActiveWorld.mapHeight + correctedActiveWorld.mapHeight / 2;
                    const dCount = group.dungeons.length;

                    const iconHtml = `
                    <div class="w-7 h-7 rounded-full bg-slate-900/90 border-2 border-amber-500/80 shadow-[0_0_12px_rgba(245,158,11,0.4)] flex items-center justify-center text-amber-400 group-hover:scale-125 group-hover:border-amber-400 transition-all duration-200 relative">
                        <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 20v-9H2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2Z"/><path d="M18 11V4H6v7"/><path d="M15 22v-4a3 3 0 0 0-3-3v0a3 3 0 0 0-3 3v4"/><path d="M22 11V9"/><path d="M2 11V9"/><path d="M6 4V2"/><path d="M18 4V2"/><path d="M10 4V2"/><path d="M14 4V2"/></svg>
                        ${dCount > 1 ? `<div class="absolute -top-2 -right-2 bg-amber-500 text-black text-[9px] font-bold w-4 h-4 rounded-full flex items-center justify-center border border-slate-900">${dCount}</div>` : ''}
                    </div>`;

                    return (
                        <Marker
                            key={`d-${group.mapId}`}
                            position={[-py, px]}
                            icon={new L.DivIcon({
                                html: iconHtml,
                                className: 'dungeon-icon-marker',
                                iconSize: [28, 28],
                                iconAnchor: [14, 14]
                            })}
                            eventHandlers={{ click: (e) => { e.originalEvent.stopPropagation(); setSelectedDungeon(group.dungeons); } }}
                        >
                            <Tooltip direction="top" offset={[0, -10]} opacity={1}>
                                <div className="text-amber-500 font-bold text-xs">
                                    {dCount > 1
                                        ? `${dCount} Donjons`
                                        : (typeof group.dungeons[0].name === 'string'
                                            ? group.dungeons[0].name
                                            : group.dungeons[0].name?.fr || 'Donjon')}
                                </div>
                            </Tooltip>
                        </Marker>
                    );
                })}

                <ExternalController 
                    triggerCenterPosition={triggerCenterPosition} 
                    activeWorld={correctedActiveWorld} 
                    minimapRecenterTrigger={minimapRecenterTrigger} 
                />
                
                {/* 7. Contrôles de zoom premium */}
                {interactive && !isMiniMap && <ZoomControls />}
            </MapContainer>

            {/* Real-time Coordinate HUD */}
            <AnimatePresence>
                {hoveredCoords && (
                    <motion.div 
                        initial={{ opacity: 0, y: 10, scale: 0.9 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: 10, scale: 0.9 }}
                        className="absolute bottom-6 left-6 z-[1000] px-4 py-2 bg-slate-900/80 backdrop-blur-md border border-white/10 rounded-xl shadow-2xl flex items-center gap-3 pointer-events-none"
                    >
                        <div className={`w-2 h-2 rounded-full ${hoveredCoords.found ? 'bg-emerald-500 shadow-[0_0_10px_#10b981]' : 'bg-white/10'}`} />
                        <span className="text-[10px] font-black text-white/40 uppercase tracking-widest italic">Position</span>
                        <span className="text-white font-black text-sm italic tracking-tighter">[{hoveredCoords.x}, {hoveredCoords.y}]</span>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import dynamic from "next/dynamic";
import { Loader2 } from "lucide-react";

// Dynamically import InteractiveMap to avoid SSR issues with Leaflet interacting with `window`
const MapWithNoSSR = dynamic<any>(
    () => import('./interactive-map-v2'),
    {
        ssr: false,
        loading: () => (
            <div className="w-full h-full flex items-center justify-center bg-[#111] rounded-xl border border-white/10">
                <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
            </div>
        )
    }
);
export function MapViewer({ 
    initialLadder, 
    initialTab, 
    gameStatuses,
    initialX,
    initialY,
    initialZoom,
    initialWorldId,
    hideUI,
    userName,
    userAvatar,
    isAdmin
}: { 
    initialLadder?: any[], 
    initialTab?: 'map' | 'games', 
    gameStatuses?: any[],
    initialX?: number,
    initialY?: number,
    initialZoom?: number,
    initialWorldId?: number,
    hideUI?: boolean,
    userName?: string,
    userAvatar?: string,
    isAdmin?: boolean
}) {
    const [data, setData] = useState<any>(null);
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function fetchMapData() {
            try {
                const [resMap, resWorlds] = await Promise.all([
                    fetch('/game-data/worldmap.json'),
                    fetch('/game-data/worlds.json')
                ]);

                if (!resMap.ok || !resWorlds.ok) throw new Error("Could not load map data");

                const mapData = await resMap.json();
                const worldsData = await resWorlds.json();

                setData({
                    ...mapData,
                    worlds: worldsData
                });
            } catch (err: any) {
                setError(err.message || "Failed to load map data");
            } finally {
                setLoading(false);
            }
        }
        fetchMapData();
    }, []);

    if (error) {
        return (
            <div className="p-4 bg-red-500/10 border border-red-500/50 rounded-lg text-red-500 text-sm">
                Erreur de chargement de la carte : {error}
            </div>
        );
    }

    if (loading || !data) {
        return (
            <div className="w-full h-[70vh] flex flex-col items-center justify-center bg-[#111] rounded-xl border border-white/10">
                <Loader2 className="h-8 w-8 animate-spin text-teal-500 mb-4" />
                <p className="text-zinc-400 text-sm font-bold uppercase tracking-widest italic opacity-50">Synchronisation du Monde...</p>
            </div>
        );
    }

    return (
        <MapWithNoSSR 
            worldMap={data} 
            initialLadder={initialLadder} 
            initialTab={initialTab} 
            gameStatuses={gameStatuses} 
            initialX={initialX}
            initialY={initialY}
            initialZoom={initialZoom}
            initialWorldId={initialWorldId}
            hideUI={hideUI}
            userName={userName}
            userAvatar={userAvatar}
            isAdmin={isAdmin}
        />
    );
}

import { useEffect, useState } from "react";
// @ts-ignore
import { useSocket } from "@/hooks/use-socket"; // Assuming this exists, if not I will adapt

export interface VoiceUser {
    userId: string;
    userName: string;
    avatar: string | null;
    channelId: string;
    channelName: string;
    isMute: boolean;
    isDeaf: boolean;
    isSpeaking?: boolean;
}

export function useDiscordVoice(guildId: string | undefined, socket: any) {
    const [voiceUsers, setVoiceUsers] = useState<VoiceUser[]>([]);

    useEffect(() => {
        if (!socket || !guildId || guildId === "undefined") return;

        // Listener for voice updates
        const handleUpdate = (data: { guildId: string; users: VoiceUser[] }) => {
            if (data.guildId === guildId) {
                setVoiceUsers(data.users);
            }
        };

        socket.on("discord:voice:update", handleUpdate);
        
        // Request immediate sync now that listener is ready
        socket.emit("discord:voice:request", { guildId });

        // Optional: request initial state? 
        // For now we wait for the next push or assume the server pushes regularly.
        
        return () => {
            socket.off("discord:voice:update", handleUpdate);
        };
    }, [socket, guildId]);

    return { voiceUsers };
}

