// ─── DOFUS POUR LES NOOBS HOMEPAGE SCRAPER ────────────────────────
export async function fetchDPLNNews(): Promise<ExtractedContent[]> {
    try {
        const baseUrl = 'https://www.dofuspourlesnoobs.com';
        const html = await fetchWithProxyFallback(baseUrl);

        if (!html) throw new Error(`Could not fetch DPLN (Direct & Proxy failed)`);


        const items: ExtractedContent[] = [];
        const now = new Date();

        // 1. New Approach: Find article sliders/images which wrap image + text in a single <a> tag
        const aRegex = /<a\s+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi;
        let aMatch;
        let count = 0;

        while ((aMatch = aRegex.exec(html)) !== null && count < 8) {
            const path = aMatch[1];
            const innerHtml = aMatch[2];

            // Ignore standard navigation/social
            if (path.startsWith('http') && !path.includes('dofuspourlesnoobs')) continue;
            if (path === '/' || path.includes('#') || path.includes('mailto')) continue;

            // Check for image inside the link
            const imgMatch = innerHtml.match(/<img[^>]+src="([^"]+)"/i);
            if (!imgMatch) continue;

            const imgUrl = imgMatch[1];
            // Ignore generic UI icons
            if (imgUrl.includes('logo') || imgUrl.includes('spacer') || imgUrl.includes('icon')) continue;

            // Extract text from HTML, removing all tags
            let fullText = innerHtml.replace(/<[^>]+>/g, '').trim();
            if (!fullText) {
                const altMatch = innerHtml.match(/<img[^>]+alt="([^"]+)"/i);
                if (altMatch) fullText = altMatch[1];
            }

            if (fullText && fullText.length > 5 && imgUrl) {
                let url = path;
                if (url.startsWith('/')) url = baseUrl + url;

                let thumbnail = imgUrl;
                if (thumbnail.startsWith('/')) thumbnail = baseUrl + thumbnail;

                // Avoid duplicates
                if (!items.find(i => i.url === url)) {
                    // Split title from potential description block
                    const textParts = fullText.split('\n').map(p => p.trim()).filter(Boolean);
                    const title = textParts[0];
                    const description = textParts.slice(1).join(' ') || undefined;

                    items.push({
                        type: "NEWS" as const,
                        creatorId: "DPLN",
                        title,
                        url,
                        thumbnail,
                        description,
                        published: new Date(now.getTime() - count * 60000)
                    });
                    count++;
                }
            }
        }

        // 2. Fallback: Standard Weebly lists (for when sliders break entirely)
        if (items.length === 0) {
            const listRegex = /<li><a\s+href="([^"]+)"[^>]*>(.*?)<\/a><\/li>/g;
            let listMatch;
            while ((listMatch = listRegex.exec(html)) !== null && count < 10) {
                let url = listMatch[1];
                if (url.startsWith('/')) url = baseUrl + url;
                const title = listMatch[2].replace(/<[^>]+>/g, '').trim();

                if (title && !title.includes('Mise à jour')) {
                    items.push({
                        type: "NEWS" as const,
                        creatorId: "DPLN",
                        title,
                        url,
                        thumbnail: null,
                        published: new Date(now.getTime() - count * 60000)
                    });
                    count++;
                }
            }
        }

        return items;
    } catch (e) {
        console.error("Failed to scrape DPLN homepage", e);
        return [];
    }
}

// ─── TWITCH API ──────────────────────────────────────────────────
export async function fetchTwitchLiveStreams(twitchUsernames: string[]): Promise<ExtractedContent[]> {
    const clientId = process.env.TWITCH_CLIENT_ID;
    const clientSecret = process.env.TWITCH_CLIENT_SECRET;

    if (!clientId || !clientSecret || twitchUsernames.length === 0) {
        return []; // Missing keys or users
    }

    try {
        // 1. Get Access Token
        const tokenRes = await fetch(`https://id.twitch.tv/oauth2/token?client_id=${clientId}&client_secret=${clientSecret}&grant_type=client_credentials`, {
            method: 'POST'
        });
        const tokenData = await tokenRes.json();
        const accessToken = tokenData.access_token;
        if (!accessToken) return [];

        // 2. Fetch Streams
        const userQuery = twitchUsernames.map(u => `user_login=${u.toLowerCase()}`).join('&');
        const streamsRes = await fetch(`https://api.twitch.tv/helix/streams?${userQuery}`, {
            headers: {
                'Client-Id': clientId,
                'Authorization': `Bearer ${accessToken}`
            }
        });
        const streamsData = await streamsRes.json();

        const liveStreams: ExtractedContent[] = (streamsData.data || []).map((stream: any) => ({
            type: "TWITCH",
            creatorId: stream.user_name,
            title: stream.title,
            url: `https://www.twitch.tv/${stream.user_login}`,
            thumbnail: stream.thumbnail_url.replace('{width}', '320').replace('{height}', '180'),
            published: new Date(stream.started_at)
        }));

        return liveStreams;

    } catch (e) {
        console.error("Failed to fetch Twitch streams", e);
        return [];
    }
}

// ─── YOUTUBE API ─────────────────────────────────────────────────
export async function fetchYouTubeLatestVideos(youtubeHandles: string[]): Promise<ExtractedContent[]> {
    const apiKey = process.env.YOUTUBE_API_KEY;
    if (!apiKey || youtubeHandles.length === 0) return [];

    try {
        // Unfortunately YouTube API v3 search has a high quota cost (100 units). 
        // A smarter way for minimal quota is fetching the channel's uploads playlist 
        // OR using the undocumented RSS feed but it doesn't support handles directly easily.
        // We will use standard Search API for this example, limiting queries.

        const videos: ExtractedContent[] = [];

        for (const handle of youtubeHandles) {
            // Find channel by @handle
            const searchRes = await fetch(`https://youtube.googleapis.com/youtube/v3/search?part=snippet&q=${handle}&type=channel&key=${apiKey}`);
            const searchData = await searchRes.json();
            const channelId = searchData.items?.[0]?.snippet?.channelId;

            if (!channelId) continue;

            // Fetch latest video
            const vidRes = await fetch(`https://youtube.googleapis.com/youtube/v3/search?part=snippet&channelId=${channelId}&maxResults=1&order=date&type=video&key=${apiKey}`);
            const vidData = await vidRes.json();
            const video = vidData.items?.[0];

            if (video) {
                videos.push({
                    type: "YOUTUBE",
                    creatorId: handle.replace('@', ''),
                    title: video.snippet.title,
                    url: `https://www.youtube.com/watch?v=${video.id.videoId}`,
                    thumbnail: video.snippet.thumbnails?.medium?.url || null,
                    published: new Date(video.snippet.publishedAt)
                });
            }
        }

        return videos;

    } catch (e) {
        console.error("Failed to fetch YouTube videos", e);
        return [];
    }
}

import fs from "fs";
import path from "path";

/**
 * Script pour générer des mots Dofus pour Skribbl
 * Focus: Monstres, Dofus, Ressources, Items (stuff de panoplie)
 * Exclut: Panoplies complètes, Archimonstres, Donjons, Quêtes, Succès
 * Inclut: URLs d'icônes pour les indices visuels
 */

async function fetchFromDofusDB(endpoint: string, maxEntries: number = 2000) {
  let allData: any[] = [];
  const limit = 50;
  
  console.log(`📡 Récupération de ${endpoint} (jusqu'à ${maxEntries})...`);

  for (let skip = 0; skip < maxEntries; skip += limit) {
    const url = `https://api.dofusdb.fr/${endpoint}?lang=fr&$limit=${limit}&$skip=${skip}`;
    try {
      const res = await fetch(url);
      if (!res.ok) break;
      const json = await res.json() as { data: any[] };
      const batchSize = json.data?.length || 0;
      if (!json.data || batchSize === 0) break;
      allData = [...allData, ...json.data];
      
      if (skip % 1000 === 0 && skip > 0) {
        console.log(`  > ${skip} éléments récupérés...`);
      }
      
      if (batchSize < limit) break;
    } catch (error) {
      break;
    }
  }
  return allData;
}

function classifyWord(name: string, level: number = 1): "facile" | "moyen" | "difficile" {
  const length = name.length;
  // Facile: Niveaux < 60, noms courts (< 12)
  if (level < 60 && length < 12) return "facile";
  // Moyen: Niveaux < 180, noms moyens (< 20)
  if (level < 180 && length < 20) return "moyen";
  // Difficile: Le reste
  return "difficile";
}

async function generateWords() {
  console.log("🚀 Lancement de la génération massive (DofusDB Explorer)...");
  
  // Les monstres sont moins nombreux que les items (environ 3000-4000 réels)
  const monsters = await fetchFromDofusDB("monsters", 5000);
  // Les items sont extrêmement nombreux (plus de 25000)
  const items = await fetchFromDofusDB("items", 25000);

  const words = {
    facile: new Map<string, any>(),
    moyen: new Map<string, any>(),
    difficile: new Map<string, any>()
  };

  // 1. Monstres
  monsters.forEach(m => {
    const name = m.name?.fr;
    // On ignore les noms trop courts (<2), trop longs (>25) ou techniques
    if (!name || name.includes("Archimonstre") || name.length < 2 || name.length > 25) return;
    const lowerName = name.toLowerCase();
    
    // Filtres d'exclusion
    if (lowerName.includes("donjon") || lowerName.includes("quête") || lowerName.includes("succès") || lowerName.includes("pnj") || lowerName.includes("test")) return;
    if (name.startsWith("Panoplie")) return;

    const iconUrl = m.img || (m.ankamaId ? `https://static.dofusdb.fr/monsters/${m.ankamaId}.png` : null);
    if (!iconUrl || iconUrl.includes("undefined")) return;

    const difficulty = classifyWord(name, m.level);
    words[difficulty].set(name, { word: name, iconUrl });
  });

  // 2. Items & Dofus & Ressources
  items.forEach(i => {
    const name = i.name?.fr;
    if (!name || name.length < 3 || name.length > 25) return;
    
    // Filtrage thématique strict
    const lowerName = name.toLowerCase();
    if (name.startsWith("(") || name.includes("Test") || lowerName.includes("quête") || lowerName.includes("succès") || lowerName.includes("pnj") || lowerName.includes("[")) return;
    if (name.startsWith("Panoplie")) return;

    const iconUrl = i.img || (i.ankamaId ? `https://static.dofusdb.fr/items/${i.ankamaId}.png` : null);
    if (!iconUrl || iconUrl.includes("/0.png") || iconUrl.includes("undefined")) return;

    // Priorité Dofus (toujours en difficile ou moyen si petit)
    if (lowerName.includes("dofus")) {
        words.difficile.set(name, { word: name, iconUrl });
        return;
    }

    const difficulty = classifyWord(name, i.level);
    words[difficulty].set(name, { word: name, iconUrl });
  });

  // Export & Stats
  const result = {
    facile: Array.from(words.facile.values()).sort((a, b) => a.word.localeCompare(b.word)),
    moyen: Array.from(words.moyen.values()).sort((a, b) => a.word.localeCompare(b.word)),
    difficile: Array.from(words.difficile.values()).sort((a, b) => a.word.localeCompare(b.word))
  };

  const total = result.facile.length + result.moyen.length + result.difficile.length;
