// VALIDATION HELPERS
// =============================================================================

/**
 * Check if the OCR result meets auto-validation criteria
 */
export function shouldAutoValidate(result: OcrResult, context?: 'mission' | 'achievement' | 'ladder'): {
    autoValidate: boolean;
    reason: string;
} {
    // Content moderation check first
    if (!result.moderation.isAppropriate) {
        return {
            autoValidate: false,
            reason: `Contenu inapproprié détecté: ${result.moderation.reason || 'Non spécifié'}`
        };
    }

    // Check if OCR succeeded
    if (!result.success) {
        return { autoValidate: false, reason: 'Échec de l\'analyse de l\'image' };
    }

    // Check confidence threshold
    if (result.confidence < AUTO_VALIDATE_THRESHOLD) {
        return {
            autoValidate: false,
            reason: `Score de confiance insuffisant (${result.confidence}% < ${AUTO_VALIDATE_THRESHOLD}%)`
        };
    }

    // For achievements/ladder: a valid score + sufficient confidence is enough.
    // isVictory keywords are mission-specific ("terminé", "validé"...) and don't apply here.
    if (context === 'achievement' || context === 'ladder') {
        return {
            autoValidate: true,
            reason: `Auto-validé avec ${result.confidence}% de confiance (succès)`
        };
    }

    // For missions: also require explicit victory indicators
    if (!result.isVictory) {
        return {
            autoValidate: false,
            reason: 'Aucun indicateur de victoire détecté'
        };
    }

    return {
        autoValidate: true,
        reason: `Auto-validé avec ${result.confidence}% de confiance`
    };
}

export function getAutoValidateThreshold(): number {
    return AUTO_VALIDATE_THRESHOLD;
}

/**
 * Optimize image for Ollama (Resize & Compress)
 * - Resize to max 1024x1024 (Moondream works well with this resolution)
 * - Convert to JPEG (smaller payload than PNG/WebP)
 * - Remove metadata
 */
async function optimizeImage(base64Image: string): Promise<string> {
    try {
        // Remove data URL prefix if present
        const base64Data = base64Image.replace(/^data:image\/\w+;base64,/, '');
        const buffer = Buffer.from(base64Data, 'base64');

        const originalSize = buffer.length;

        // Process with sharp
        const optimizedBuffer = await sharp(buffer)
            .resize({
                width: 1024,
                height: 1024,
                fit: 'inside', // Maintain aspect ratio
                withoutEnlargement: true // Don't upscale small images
            })
            .jpeg({
                quality: 80, // Good balance of quality/size
                mozjpeg: true // Better compression
            })
            .toBuffer();

        const newSize = optimizedBuffer.length;
        const reduction = Math.round((1 - newSize / originalSize) * 100);


        return optimizedBuffer.toString('base64');
    } catch (error: unknown) {
        logger.warn('[LLM-OCR] Image optimization failed, using original', { error });
        return base64Image; // Fallback to original if sharp fails
    }
}

/**
 * Structured Logger Abstraction
 * Production-safe logging with automatic redaction and structured output
 */

type LogLevel = 'debug' | 'info' | 'warn' | 'error';

interface LogContext {
    [key: string]: any;
}

/**
 * Structured logger with environment-aware output
 * - Development: Pretty console output
 * - Production: Structured JSON (ready for log aggregation)
 */
class Logger {
    private isDevelopment = process.env.NODE_ENV === 'development';
    private sensitiveKeys = ['password', 'token', 'secret', 'authorization', 'cookie', 'apiKey'];

    /**
     * Redact sensitive information from log context
     */
    private redact(context: LogContext): LogContext {
        const redacted: LogContext = {};

        for (const [key, value] of Object.entries(context)) {
            const lowerKey = key.toLowerCase();
            const isSensitive = this.sensitiveKeys.some(k => lowerKey.includes(k));

            if (isSensitive) {
                redacted[key] = '[REDACTED]';
            } else if (typeof value === 'object' && value !== null) {
                redacted[key] = this.redact(value);
            } else {
                redacted[key] = value;
            }
        }

        return redacted;
    }

    /**
     * Format log message with context
     */
    private format(level: LogLevel, message: string, context?: LogContext): string {
        const timestamp = new Date().toISOString();

        if (this.isDevelopment) {
            // Pretty format for development
            const emoji = {
                debug: '🐛',
                info: 'ℹ️',
                warn: '⚠️',
                error: '❌'
            }[level];

            return context
                ? `${emoji} [${level.toUpperCase()}] ${message} ${JSON.stringify(this.redact(context), null, 2)}`
                : `${emoji} [${level.toUpperCase()}] ${message}`;
        } else {
            // Structured JSON for production (ready for log aggregation like Datadog, Splunk, etc.)
            return JSON.stringify({
                timestamp,
                level,
                message,
                ...(context ? { context: this.redact(context) } : {})
            });
        }
    }

    /**
     * Debug log (development only)
     */
    debug(message: string, context?: LogContext): void {
        if (this.isDevelopment) {
            console.log(this.format('debug', message, context));
        }
    }

    /**
     * Info log (always logged)
     */
    info(message: string, context?: LogContext): void {
        console.log(this.format('info', message, context));
    }

    /**
     * Warning log (always logged)
     */
    warn(message: string, context?: LogContext): void {
        console.warn(this.format('warn', message, context));
    }

    /**
     * Error log (always logged)
     */
    error(message: string, context?: LogContext): void {
        console.error(this.format('error', message, context));
    }
}

// Export singleton instance
export const logger = new Logger();

/**
 * mergeCellEdges
 * Merges adjacent grid cells into one or more polygons (boundary paths).
 * Useful for "pixel-perfect" map zone rendering.
 */
export function mergeCellEdges(cells: { x: number, y: number }[]): { x: number, y: number }[][] {
    if (!cells || cells.length === 0) return [];

    // 1. Map edges to their occurence count
    // Edge key format: "x1,y1|x2,y2" where points are sorted to ensure uniqueness
    const edgeCount = new Map<string, number>();
    const edges: [number, number, number, number][] = [];

    const getEdgeKey = (x1: number, y1: number, x2: number, y2: number) => {
        if (x1 < x2 || (x1 === x2 && y1 < y2)) {
            return `${x1},${y1}|${x2},${y2}`;
        }
        return `${x2},${y2}|${x1},${y1}`;
    };

    for (const cell of cells) {
        const { x, y } = cell;
        const cellEdges = [
            [x, y, x + 1, y],         // Top
            [x + 1, y, x + 1, y + 1], // Right
            [x + 1, y + 1, x, y + 1], // Bottom
            [x, y + 1, x, y]          // Left
        ];

        for (const [x1, y1, x2, y2] of cellEdges) {
            const key = getEdgeKey(x1, y1, x2, y2);
            edgeCount.set(key, (edgeCount.get(key) || 0) + 1);
        }
    }

    // 2. Keep only unique edges (the boundary)
    const boundaryEdges: [number, number, number, number][] = [];
    edgeCount.forEach((count, key) => {
        if (count === 1) {
            const [p1, p2] = key.split('|');
            const [x1, y1] = p1.split(',').map(Number);
            const [x2, y2] = p2.split(',').map(Number);
            boundaryEdges.push([x1, y1, x2, y2]);
        }
    });

    if (boundaryEdges.length === 0) return [];

    // 3. Chain edges into polygons
    const polygons: { x: number, y: number }[][] = [];
    while (boundaryEdges.length > 0) {
        const polygon: { x: number, y: number }[] = [];
        const currentEdge = boundaryEdges.shift()!;
        const [startX, startY] = [currentEdge[0], currentEdge[1]];
        let [endX, endY] = [currentEdge[2], currentEdge[3]];
        polygon.push({ x: startX, y: startY });
        polygon.push({ x: endX, y: endY });

        let found = true;
        while (found) {
            found = false;
            for (let i = 0; i < boundaryEdges.length; i++) {
                const [x1, y1, x2, y2] = boundaryEdges[i];
                if (x1 === endX && y1 === endY) {
                    endX = x2; endY = y2;
                    polygon.push({ x: endX, y: endY });
                    boundaryEdges.splice(i, 1);
                    found = true;
                    break;
                } else if (x2 === endX && y2 === endY) {
                    endX = x1; endY = y1;
                    polygon.push({ x: endX, y: endY });
                    boundaryEdges.splice(i, 1);
                    found = true;
                    break;
                }
            }
            // Check if we closed the loop
            if (endX === startX && endY === startY) break;
        }
        polygons.push(polygon);
    }

    return polygons;
}

