'use server';

import { db } from "@/lib/prisma";
import { auth } from "@/auth";
import { getUserContext } from "./user-actions";
import { revalidatePath } from "next/cache";

export async function submitBombScore(
    guildId: string,
    userId: string,
    score: number
) {
    // Note: Since this can be called from the WebSocket server directly (which might not have a session in context),
    // we bypass auth check ONLY if the caller is the internal WebSocket server, but standard security applies.
    // If it's a client calling it via Server Action, we authenticate:
    const session = await auth();
    
    // Allow internal calls (from WS server where session is not set in the async local storage of Next.js)
    const activeUserId = session?.user?.id || userId;
    if (!activeUserId) return { success: false, error: "Non autorisé" };

    const ctx = await getUserContext(guildId);
    if (!ctx.isMember) return { success: false, error: "Non membre" };

    try {
        // Update aggregate rank
        const rank = await db.bombRank.upsert({
            where: {
                guildId_userId: {
                    guildId,
                    userId: activeUserId
                }
            },
            create: {
                guildId,
                userId: activeUserId,
                userName: ctx.name || "Inconnu",
                userAvatar: ctx.image,
                bestScore: score,
                totalPoints: score,
                gamesPlayed: 1
            },
            update: {
                totalPoints: { increment: score },
                gamesPlayed: { increment: 1 },
                userName: ctx.name || "Inconnu",
                userAvatar: ctx.image,
            }
        });

        // Re-check best score to ensure we don't overwrite with lower
        if (score > rank.bestScore) {
            await db.bombRank.update({
                where: { id: rank.id },
                data: { bestScore: score }
            });
        }

        // Save individual score
        await db.bombScore.create({
            data: {
                guildId,
                userId: activeUserId,
                userName: ctx.name || "Inconnu",
                userAvatar: ctx.image,
                score
            }
        });

        revalidatePath(`/dashboard/${guildId}/mini-jeux`);
        return { success: true };
    } catch (error) {
        console.error("Failed to submit bomb score:", error);
        return { success: false, error: "Erreur de base de données" };
    }
}

export async function getBombLadder(guildId: string, type: 'all_time' | 'month' = 'all_time') {
    try {
        if (type === 'all_time') {
            const ranks = await db.bombRank.findMany({
                where: { guildId },
                orderBy: { bestScore: 'desc' },
                take: 10
            });
            return ranks.map(r => ({
                userId: r.userId,
                userName: r.userName,
                userAvatar: r.userAvatar,
                bestScore: r.bestScore
            }));
        }

        const startOfMonth = new Date();
        startOfMonth.setDate(1);
        startOfMonth.setHours(0, 0, 0, 0);

        const monthlyScores = await db.bombScore.groupBy({
            by: ['userId', 'userName', 'userAvatar'],
            where: {
                guildId,
                createdAt: { gte: startOfMonth }
            },
            _max: {
                score: true
            },
            orderBy: {
                _max: {
                    score: 'desc'
                }
            },
            take: 10
        });

        return monthlyScores.map((s: any) => ({
            userId: s.userId,
            userName: s.userName,
            userAvatar: s.userAvatar,
            bestScore: s._max?.score || 0
        }));
    } catch (error) {
        console.error("Failed to fetch bomb ladder:", error);
        return [];
    }
}

"use server";

import { auth } from "@/auth";
import { db } from "@/lib/prisma";
import { revalidatePath } from "next/cache";
import { BonusType, BonusStatus, MentionType, GuildBonus } from "@prisma/client";
import { getUserContext } from "./user-actions";
import { z } from "zod";
import { createAuditLog } from "./audit-actions";

// --- Types ---

type ActionResponse<T = void> = {
    success: boolean;
    error?: string;
    data?: T;
};

// --- Input Validation Schemas ---

const purchaseBonusSchema = z.object({
    guildId: z.string().min(1, "guildId requis"),
    bonusType: z.nativeEnum(BonusType),
    channelId: z.string().regex(/^\d{17,20}$/, "ID Discord invalide").optional(),
    mentionType: z.nativeEnum(MentionType).default(MentionType.NONE),
    roleId: z.string().regex(/^\d{17,20}$/, "ID rôle invalide").optional(),
});

const cancelBonusSchema = z.object({
    bonusId: z.string().min(1, "bonusId requis"),
    guildId: z.string().min(1, "guildId requis"),
});

// Bonus configuration
const BONUS_CONFIG: Record<BonusType, { name: string; description: string; cost: number; duration: number }> = {
    FORTUNE: {
        name: "Oracle de Fortune",
        description: "+50% chances de loot sur les monstres",
        cost: 20,
        duration: 2 * 60 * 60 * 1000, // 2h in ms
    },
    GLADIATOR: {
        name: "Oracle de Gladiateur",
        description: "+50% gains en Kolizéum",
        cost: 20,
        duration: 2 * 60 * 60 * 1000,
    },
    HARVESTER: {
        name: "Oracle de Récolteur",
        description: "Possibilité d'obtenir des Rékloots en récolte",
        cost: 50,
        duration: 2 * 60 * 60 * 1000,
    },
    WISDOM: {
        name: "Oracle de Savoir",
        description: "+50% d'expérience sur toutes les missions",
        cost: 20,
        duration: 2 * 60 * 60 * 1000,
    },
    DIVINE: {
        name: "Oracle Divin",
        description: "Déclenche l'événement Moissonneuse Batteuse",
        cost: 200,
        duration: 2 * 60 * 60 * 1000,
    },
};

// Local images for each bonus type (served from /public/bonus_guilde/)
const BONUS_IMAGES: Record<BonusType, string> = {
    FORTUNE: "/bonus_guilde/oracle_de_fortune.png",
    GLADIATOR: "/bonus_guilde/oracle_de_gladiateur.png",
    HARVESTER: "/bonus_guilde/oracle_de_recolteur.png",
    WISDOM: "/bonus_guilde/oracle_de_savoir.png",
    DIVINE: "/bonus_guilde/oracle_divin.png",
};

// --- Helper Functions ---

/**
 * Require authenticated user, return userId
 */
async function requireAuth(): Promise<string> {
    const session = await auth();
    if (!session?.user?.id) {
        throw new Error("Non authentifié");
    }
    return session.user.id;
}

/**
 * Require authenticated member of the guild
 */
async function requireMember(guildId: string) {
    await requireAuth();
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated || !ctx.isMember) {
        throw new Error("Non autorisé");
    }
    return ctx;
}

/**
 * Require authenticated admin of the guild
 */
async function requireAdmin(guildId: string) {
    const ctx = await requireMember(guildId);
    if (!ctx.isAdmin) {
        throw new Error("Permissions insuffisantes - Admin requis");
    }
    return ctx;
}

/**
 * Require authenticated user with bonus manage permission
 */
async function requireBonusManage(guildId: string) {
    const ctx = await requireMember(guildId);
    if (!ctx.canManageBonus) {
        throw new Error("Permissions insuffisantes - Gestion des bonus requise");
    }
    return ctx;
}

// --- Public Functions ---

/**
 * Get Discord roles for a guild (for dropdown)
 */
export async function getGuildRoles(guildId: string): Promise<ActionResponse<Array<{ id: string; name: string; color: number; position: number }>>> {
    try {
        await requireMember(guildId);

        const { fetchGuildRoles } = await import("@/server/discord");
        const roles = await fetchGuildRoles(guildId, { excludeManaged: true });

        const filteredRoles = roles
            .filter((r: { name: string }) => r.name !== "@everyone")
            .map((r: { id: string; name: string; color: number; position: number }) => ({
                id: r.id,
                name: r.name,
                color: r.color,
                position: r.position,
            }));

        return { success: true, data: filteredRoles };
    } catch (error) {
        return { success: false, error: (error as Error).message, data: [] };
    }
}

/**
 * Get all bonuses for a guild
 */
export async function getGuildBonuses(
    guildId: string
): Promise<ActionResponse<any[]>> {
    try {
        // Security: verify membership before data access
        await requireMember(guildId);

        const bonuses = await db.guildBonus.findMany({
            where: { guildId },
            orderBy: { createdAt: "desc" },
        });

        const enriched = bonuses.map((bonus) => ({
            ...bonus,
            config: BONUS_CONFIG[bonus.bonusType],
        }));

        return { success: true, data: enriched };
    } catch (error) {
        return { success: false, error: (error as Error).message };
    }
}

/**
 * Get the currently active or pending bonus for a guild
 * Automatically activates/expires bonuses based on time
 */
export async function getActiveBonuses(
    guildId: string
): Promise<ActionResponse<Array<GuildBonus & { config: { name: string; description: string; cost: number; duration: number }; purchaserName: string }>>> {
    try {
        // Security: verify membership before data access
        await requireMember(guildId);

        // Get internal guild ID (CUID)
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true },
        });

        if (!guildConfig) {
            return { success: false, error: "Guilde introuvable" };
        }

        const bonuses = await db.guildBonus.findMany({
            where: {
                guildId: guildConfig.id,
                status: {
                    in: [BonusStatus.PURCHASED, BonusStatus.ACTIVE],
                },
            },
            orderBy: { createdAt: "desc" },
        });

        if (bonuses.length === 0) {
            return { success: true, data: [] };
        }

        const now = new Date();
        const results: Array<GuildBonus & { config: { name: string; description: string; cost: number; duration: number }; purchaserName: string }> = [];

        for (const bonus of bonuses) {
            let current = bonus;

            // Auto-expire if 24h has passed without being activated
            if (current.status === BonusStatus.PURCHASED && now >= current.activatesAt) {
                current = await db.guildBonus.update({
                    where: { id: current.id },
                    data: {
                        status: BonusStatus.EXPIRED,
                    },
                });
                continue; // Skip expired bonus
            }

            // Auto-expire if duration has passed
            if (current.status === BonusStatus.ACTIVE && current.expiresAt && now >= current.expiresAt) {
                await db.guildBonus.update({
                    where: { id: current.id },
                    data: { status: BonusStatus.EXPIRED },
                });
                continue; // Skip expired bonus
            }

            // Fetch purchaser data separately
            let purchaserName = "Inconnu";
            if (current.purchasedBy) {
                const purchaser = await db.userProfile.findUnique({
                    where: { id: current.purchasedBy },
                    select: { dofusPseudo: true, discordNickname: true },
                });
                purchaserName = purchaser?.dofusPseudo || purchaser?.discordNickname || "Inconnu";
            }

            results.push({
                ...current,
                config: BONUS_CONFIG[current.bonusType],
                purchaserName,
            });
        }

        if (results.length !== bonuses.length) {
            revalidatePath(`/admin/bonus`);
            revalidatePath(`/[guildSlug]/missions`);
        }

        return { success: true, data: results };
    } catch (error) {
        return { success: false, error: (error as Error).message };
    }
}

/** @deprecated Use getActiveBonuses instead */
export async function getActiveBonus(
    guildId: string
): Promise<ActionResponse<(GuildBonus & { config: { name: string; description: string; cost: number; duration: number }; purchaserName: string }) | null>> {
    const result = await getActiveBonuses(guildId);
    if (!result.success) return { success: false, error: result.error };
    return { success: true, data: result.data?.[0] || null };
}

/**
 * Purchase a new guild bonus
 */
export async function purchaseBonus(
    guildId: string,
    bonusType: BonusType,
    channelId?: string,
    mentionType: MentionType = MentionType.NONE,
    roleId?: string
): Promise<ActionResponse<any>> {
    try {
        // Validate input
        const validated = purchaseBonusSchema.parse({
            guildId,
            bonusType,
            channelId: channelId || undefined,
            mentionType,
            roleId: roleId || undefined,
        });

        // Security: require bonus manage permission
        const userId = await requireAuth();
        await requireBonusManage(validated.guildId);

        const config = BONUS_CONFIG[validated.bonusType];

        // Get guild config FIRST (needed for all subsequent queries)
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: validated.guildId },
            select: { id: true, bonusNotifyChannelId: true },
        });

        if (!guildConfig) {
            return { success: false, error: "Guilde introuvable" };
        }

        // Check if the SAME bonus type is already active or pending
        const existingBonus = await db.guildBonus.findFirst({
            where: {
                guildId: guildConfig.id, // ✅ Use internal CUID
                bonusType: validated.bonusType, // ✅ Only block same type
                status: {
                    in: [BonusStatus.PURCHASED, BonusStatus.ACTIVE],
                },
            },
        });

        if (existingBonus) {
            return {
                success: false,
                error: `Un bonus ${config.name} est déjà actif ou en attente`,
            };
        }

        // guildConfig already fetched above

        // Get user profile ID (UserProfile.id, not User.id)
        const userProfile = await db.userProfile.findFirst({
            where: {
                userId: userId,
                guildId: guildConfig.id,
            },
            select: { id: true },
        });

        if (!userProfile) {
            return { success: false, error: "Profil utilisateur introuvable" };
        }

        // Fall back to stored channel from settings if none provided
        const notificationChannelId = validated.channelId ?? guildConfig.bonusNotifyChannelId ?? undefined;

        // Calculate activation time (24h from now)
        const now = new Date();
        const activatesAt = new Date(now.getTime() + 24 * 60 * 60 * 1000);

        // Create bonus record (use internal guildId CUID, not discordGuildId)
        const bonus = await db.guildBonus.create({
            data: {
                guildId: guildConfig.id, // ✅ Use GuildConfig.id (CUID), not discordGuildId
                bonusType: validated.bonusType,
                cost: config.cost,
                purchasedBy: userProfile.id, // ✅ Use UserProfile.id, not User.id
                activatesAt,
                notificationChannelId,
                mentionType: validated.mentionType,
                mentionRoleId: validated.roleId,
            },
        });

        revalidatePath(`/admin/bonus`);
        revalidatePath(`/[guildSlug]/missions`);

        // Audit log
        const session = await auth();
        await createAuditLog({
            guildId: validated.guildId,
            actorUserId: userId,
            actorName: session?.user?.name || "Membre",
            action: "BONUS_PURCHASED" as any,
            targetType: "GUILD" as any,
            targetId: bonus.id,
            metadata: {
                bonusType: validated.bonusType,
                bonusName: config.name,
                cost: config.cost,
                activatesAt: bonus.activatesAt
            }
        });

        // 🟢 SEND DISCORD NOTIFICATION
        if (notificationChannelId) {
            const { sendChannelMessage } = await import("@/server/discord");

            let mentionText = "";
            if (validated.mentionType === MentionType.EVERYONE) mentionText = "Bonjour @everyone !";
            else if (validated.mentionType === MentionType.ROLE && validated.roleId) mentionText = `Bonjour <@&${validated.roleId}> !`;

            const discordTimestamp = Math.floor(activatesAt.getTime() / 1000);

            const baseUrl = process.env.NEXT_PUBLIC_APP_URL || process.env.NEXTAUTH_URL || "https://sigilos.fr";
            const dashboardUrl = `${baseUrl}/dashboard/${validated.guildId}`;
            const bonusImagePath = BONUS_IMAGES[validated.bonusType];
            const bonusThumbnailUrl = bonusImagePath
                ? `${baseUrl}${bonusImagePath}`
                : undefined;

            await sendChannelMessage(notificationChannelId, mentionText, {
                embedTitle: "💎 Bonus de Guilde disponible : " + config.name,
                embedColor: 0x9333ea,
                embedDescription: `Un nouveau bonus a été acheté par **${session?.user?.name || "un membre"}**.\n\n**Comment l'activer ?**\nN'importe quel membre peut l'activer en jeu ! Vous avez **24h** pour le faire dans l'onglet **"Obtenu"** du menu des bonus de guilde.`,
                fields: [
                    { name: "✨ Effet du bonus", value: config.description, inline: true },
                    { name: "⏳ Disponibilité restante", value: `<t:${discordTimestamp}:R>`, inline: false },
                    { name: "\u200b", value: "*Pas encore sur le Dashboard ? Rejoins-le sur **beta.sigilos.fr** !*", inline: false }
                ],
                embedFooter: "SigilOS • Pas encore sur le Dashboard ? → beta.sigilos.fr",
                embedThumbnail: bonusThumbnailUrl,
                mentionContent: mentionText
            });
        }

        return {
            success: true,
            data: {
                ...bonus,
                config,
            },
        };
    } catch (error) {
        // Return Zod validation errors cleanly
        if ((error as any).name === "ZodError") {
            const firstError = (error as any).errors?.[0]?.message || "Données invalides";
            return { success: false, error: firstError };
        }
        return { success: false, error: (error as Error).message };
    }
}

/**
 * Cancel a pending bonus (before activation)
 */
export async function cancelBonus(
    bonusId: string,
    guildId: string
): Promise<ActionResponse> {
    try {
        // Validate input
        const validated = cancelBonusSchema.parse({ bonusId, guildId });

        // Security: require bonus manage permission
        await requireBonusManage(validated.guildId);

        // Resolve discordGuildId → internal CUID
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: validated.guildId },
            select: { id: true },
        });

        if (!guildConfig) {
            return { success: false, error: "Guilde introuvable" };
        }

        const bonus = await db.guildBonus.findUnique({
            where: { id: validated.bonusId },
        });

        if (!bonus) {
            return { success: false, error: "Bonus introuvable" };
        }

        // Security: guild isolation check (compare CUIDs)
        if (bonus.guildId !== guildConfig.id) {
            return { success: false, error: "Ce bonus n'appartient pas à votre guilde" };
        }

        if (bonus.status !== BonusStatus.PURCHASED) {
            return { success: false, error: "Seuls les bonus en attente peuvent être annulés" };
        }

        await db.guildBonus.delete({
            where: { id: validated.bonusId },
        });

        revalidatePath(`/admin/bonus`);
        revalidatePath(`/[guildSlug]/missions`);

        // Audit log
        const session = await auth();
        await createAuditLog({
            guildId: validated.guildId,
            actorUserId: session?.user?.id || "unknown",
            actorName: session?.user?.name || "Membre",
            action: "BONUS_CANCELLED" as any,
            targetType: "GUILD" as any,
            targetId: validated.bonusId,
            metadata: { bonusType: bonus.bonusType }
        });

        return { success: true };
    } catch (error) {
        if ((error as any).name === "ZodError") {
            const firstError = (error as any).errors?.[0]?.message || "Données invalides";
            return { success: false, error: firstError };
        }
        return { success: false, error: (error as Error).message };
    }
}

/**
 * Expire a bonus (internal use / cron only)
 * NOT exposed to client — requires bonusId known only server-side
 */
export async function expireBonus(bonusId: string): Promise<ActionResponse> {
    try {
        if (!bonusId || typeof bonusId !== "string") {
            return { success: false, error: "bonusId invalide" };
        }

        const bonus = await db.guildBonus.findUnique({
            where: { id: bonusId },
        });

        if (!bonus) {
            return { success: false, error: "Bonus introuvable" };
        }

        if (bonus.status !== BonusStatus.ACTIVE) {
            return { success: false, error: "Le bonus n'est pas actif" };
        }

        const now = new Date();
        if (!bonus.expiresAt || now < bonus.expiresAt) {
            return { success: false, error: "Le bonus n'est pas encore expiré" };
        }

        await db.guildBonus.update({
            where: { id: bonusId },
            data: { status: BonusStatus.EXPIRED },
        });

        revalidatePath(`/admin/bonus`);
        revalidatePath(`/[guildSlug]/missions`);

        return { success: true };
    } catch (error) {
        return { success: false, error: (error as Error).message };
    }
}

/**
 * Check if a specific bonus type is currently active for a guild
 * Server-only utility — no need for user-facing auth since this is
 * called from other server actions that already have their own auth
 */
export async function isBonusActive(
    guildId: string,
    bonusType: BonusType
): Promise<boolean> {
    try {
        const bonus = await db.guildBonus.findFirst({
            where: {
                guildId,
                bonusType,
                status: BonusStatus.ACTIVE,
                expiresAt: {
                    gte: new Date(),
                },
            },
        });

        return !!bonus;
    } catch {
        return false;
    }
}

/**
 * Get the XP multiplier for a guild (for WISDOM bonus)
 * Server-only utility — called from mission-actions.ts
 */
export async function getXpMultiplier(guildId: string): Promise<number> {
    const isWisdomActive = await isBonusActive(guildId, BonusType.WISDOM);
    return isWisdomActive ? 1.5 : 1.0;
}

// --- Bonus Settings (Channel Config) ---

/**
 * Get the bonus notification config for a guild
 */
export async function getBonusConfig(
    guildId: string
): Promise<ActionResponse<{ bonusNotifyChannelId: string | null; channelName?: string }>> {
    try {
        await requireBonusManage(guildId);

        const config = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { bonusNotifyChannelId: true },
        });

        if (!config) {
            return { success: false, error: "Guilde introuvable" };
        }

        let channelName = undefined;
        if (config.bonusNotifyChannelId) {
            const { fetchChannel } = await import("@/server/discord");
            try {
                const channel = await fetchChannel(config.bonusNotifyChannelId);
                if (channel) channelName = channel.name;
            } catch (err) {
                console.error("Failed to fetch bonus channel name:", err);
            }
        }

        return { success: true, data: { bonusNotifyChannelId: config.bonusNotifyChannelId, channelName } };
    } catch (error) {
        return { success: false, error: (error as Error).message };
    }
}

/**
 * Update the bonus notification channel for a guild
 */
export async function updateBonusChannel(
    guildId: string,
    channelId: string | null
): Promise<ActionResponse> {
    try {
        await requireAdmin(guildId);

        // Validate channel ID format if provided
        if (channelId) {
            const channelSchema = z.string().regex(/^\d{17,20}$/, "ID Discord invalide");
            channelSchema.parse(channelId);

            // Verify channel belongs to this guild
            const { validateChannelBelongsToGuild } = await import("@/server/discord");
            const isValid = await validateChannelBelongsToGuild(channelId, guildId);
            if (!isValid) {
                return { success: false, error: "Ce salon n'appartient pas à votre serveur Discord" };
            }
        }

        await db.guildConfig.update({
            where: { discordGuildId: guildId },
            data: { bonusNotifyChannelId: channelId },
        });

        // Audit log
        const session = await auth();
        await createAuditLog({
            guildId,
            actorUserId: session?.user?.id || "unknown",
            actorName: session?.user?.name || "Admin",
            action: "SETTINGS_UPDATED" as any,
            targetType: "GUILD" as any,
            metadata: { field: "bonusNotifyChannelId", newValue: channelId }
        });

        revalidatePath(`/dashboard/${guildId}/admin/settings`);
        return { success: true };
    } catch (error) {
        if ((error as any).name === "ZodError") {
            return { success: false, error: "ID de salon Discord invalide" };
        }
        return { success: false, error: (error as Error).message };
    }
}

"use server";

/**
 * Calendar Module V2 - Server Actions
 * Handles guild events with 5 Dofus types, roster management, and Discord sync.
 */

import { z } from "zod";
import { revalidatePath } from "next/cache";
import { db } from "@/lib/prisma";
import { getUserContext } from "@/server/actions/user-actions";
import { deleteChannelMessage } from "@/server/discord";

// ============================================
// LOCAL ENUM DEFINITIONS (mirrors Prisma schema)
// ============================================

const GUILD_EVENT_TYPES = [
    "RAID_OFFICIAL",
    "EVENT_GUILD",
    "SESSION_MISSIONS",
    "SORTIE_FARM",
    "ALMANAX_BONUS",
    "GUILD_MISSION",
    "SONGES_RUN",
    "DUNGEON_FARM",
    "SOCIAL",
    "OFFICIAL_RESET",
    "OTHERS"
] as const;

const EVENT_STATUSES = ["DRAFT", "PUBLISHED", "COMPLETED", "CANCELLED"] as const;
const RECURRENCE_TYPES = ["UNIQUE", "WEEKLY", "MONTHLY"] as const;

// ============================================
// SCHEMAS
// ============================================

const GuildEventSchema = z.object({
    title: z.string().min(3, "Le titre doit faire au moins 3 caractères").max(100),
    description: z.string().max(2000).optional(),
    type: z.enum(GUILD_EVENT_TYPES),
    status: z.enum(EVENT_STATUSES).optional().default("PUBLISHED"),
    startDate: z.date(),
    endDate: z.date(),
    recurrence: z.enum(RECURRENCE_TYPES).optional().default("UNIQUE"),
    location: z.string().max(100).optional(),
    maxParticipants: z.number().int().min(1).nullable().optional(),
    notifyBefore: z.number().int().min(0).nullable().optional(),
    metadata: z.any().optional(), // Dynamic per type
    missionIds: z.array(z.string()).optional(), // For SESSION_MISSIONS
    publishOnDiscord: z.boolean().optional().default(false),
    mentionRoleIds: z.array(z.string()).optional().default([]),
}).refine(data => data.endDate > data.startDate, {
    message: "La date de fin doit être après la date de début",
    path: ["endDate"]
}).refine(data => {
    if (data.type === "RAID_OFFICIAL" && data.maxParticipants && data.maxParticipants > 16) {
        return false;
    }
    return true;
}, {
    message: "Les raids sont limités à 16 joueurs maximum",
    path: ["maxParticipants"]
});

const RegisterEventSchema = z.object({
    classe: z.string().max(50).optional(),
    comment: z.string().max(200).optional(),
});

// ============================================
// TYPES
// ============================================

export type GuildEventInput = z.infer<typeof GuildEventSchema>;

// ============================================
// READ ACTIONS
// ============================================

/**
 * Fetch events for a guild within a date range
 */
export async function getCalendarEvents(guildId: string, start: Date, end: Date) {
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated) return { success: false, error: "Non authentifié", events: [] };
    if (!ctx.isMember) return { success: false, error: "Accès restreint aux membres", events: [] };

    // SECURITY: Limit date range to prevent DB overload (max 60 days)
    const MAX_RANGE_MS = 60 * 24 * 60 * 60 * 1000;
    if (end.getTime() - start.getTime() > MAX_RANGE_MS) {
        return { success: false, error: "Plage de dates trop large (max 60 jours)", events: [] };
    }

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true }
        });
        if (!guildConfig) return { success: false, error: "Guilde non trouvée", events: [] };

        const events = await db.guildEvent.findMany({
            where: {
                guildId: guildConfig.id,
                startDate: { gte: start },
                endDate: { lte: end },
                // Only show published events to non-admins
                ...(ctx.canManageCalendar ? {} : { status: "PUBLISHED" })
            },
            include: {
                creator: {
                    select: { name: true, image: true }
                },
                participants: {
                    include: {
                        user: {
                            select: {
                                id: true,
                                name: true,
                                image: true,
                                profiles: {
                                    where: { guildId: guildConfig.id },
                                    select: { discordNickname: true }
                                }
                            }
                        }
                    },
                    orderBy: { position: "asc" },
                    take: 10
                },
                _count: {
                    select: { participants: true }
                }
            },
            orderBy: { startDate: "asc" },
            take: 500 // Limit max events per request
        });

        // Patch: Override type and SYNC COUNTS for Kralamoure events
        const hasKrala = events.some(e => (e.metadata as any)?.isKralamoure);
        let liveKralaEvents: any[] = [];
        
        if (hasKrala) {
            try {
                const { getKralamoureEvents } = await import("@/lib/metamob-client");
                // Fetch live events for the same range (or slightly wider to be safe)
                // Note: We need a server ID. We'll try to get it from the user's profile.
                const userProfile = await db.userProfile.findFirst({
                    where: { userId: ctx.id!, guild: { discordGuildId: guildId } },
                    select: { metamobServerId: true, metamobApiKey: true }
                });
                
                if (userProfile?.metamobServerId) {
                    const results = await getKralamoureEvents({
                        serverId: userProfile.metamobServerId,
                        from: start.toISOString(),
                        guildApiKey: userProfile.metamobApiKey,
                        revalidate: 60 // 1 minute cache
                    });
                    if (results) liveKralaEvents = results;
                }
            } catch (err) {
                console.error("[Calendar] Failed to sync Krala counts in list:", err);
            }
        }

        const patchedEvents = events.map(event => {
            const meta = event.metadata as any;
            if (meta?.isKralamoure) {
                let liveCount = meta.metamobParticipantsCount || 0;
                if (meta.metamobId && liveKralaEvents.length > 0) {
                    const match = liveKralaEvents.find(k => k.id === meta.metamobId);
                    if (match) liveCount = match.participants_count || 0;
                }
                
                return { 
                    ...event, 
                    type: "KRALAMOURE" as any,
                    _count: { participants: liveCount } // Override count for display
                };
            }
            return event;
        });

        return { success: true, events: patchedEvents };
    } catch (error) {
        console.error("[Calendar] getEvents Error:", error);
        return { success: false, error: "Erreur serveur", events: [] };
    }
}

/**
 * Get event details with participants
 */
export async function getCalendarEventDetails(guildId: string, eventId: string) {
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated) return { success: false, error: "Non authentifié" };


    // KRALAMOURE HANDLING
    if (eventId.startsWith("krala-")) {
        const kralaId = parseInt(eventId.split("-")[1]);
        if (isNaN(kralaId)) return { success: false, error: "ID invalide" };

        const { getExternalKralamoureDetails } = await import("@/server/actions/event-actions");
        const details = await getExternalKralamoureDetails(kralaId, guildId, 0); // Force fresh fetch for modal

        if (!details) return { success: false, error: "Événement Metamob introuvable" };

        // Check if current user has a Metamob API key (fallback to any of their profiles)
        const userProfile = await db.userProfile.findFirst({
            where: { 
                userId: ctx.id!, 
                metamobApiKey: { not: null } 
            },
            select: { metamobApiKey: true }
        });

        // Map to EventDetail structure
        const event = {
            id: eventId,
            title: `Ouverture Kralamoure (${details.server.name})`,
            description: details.description || "Pas de description",
            type: "KRALAMOURE", // Special type we will handle in frontend
            status: "PUBLISHED",
            startDate: new Date(details.event_datetime),
            endDate: new Date(new Date(details.event_datetime).getTime() + 60 * 60 * 1000), // Subtly incorrect but fine for display
            location: "Antre du Kralamoure Géant (-60, -8)",
            maxParticipants: 48,
            creator: {
                id: "metamob",
                name: details.creator,
                image: null
            },
            participants: (details.participants || []).map((p, i) => ({
                id: `krala-part-${i}`,
                status: "REGISTERED",
                position: i + 1,
                user: {
                    id: `external-${i}`,
                    name: `${p.username} (${p.character_count})`,
                    image: null,
                    profiles: []
                }
            })),
            _count: { participants: details.participants_count }
        };

        return { success: true, event, hasMetamobKey: !!userProfile?.metamobApiKey };
    }

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true }
        });
        if (!guildConfig) return { success: false, error: "Guilde non trouvée" };

        const event = await db.guildEvent.findUnique({
            where: { id: eventId, guildId: guildConfig.id },
            include: {
                creator: { select: { id: true, name: true, image: true } },
                participants: {
                    include: {
                        user: {
                            select: {
                                id: true,
                                name: true,
                                image: true,
                                profiles: {
                                    where: { guildId: guildConfig.id },
                                    select: { discordNickname: true }
                                }
                            }
                        }
                    },
                    orderBy: { position: "asc" }
                }
            }
        });

        if (!event) return { success: false, error: "Événement introuvable" };

        // Clone event to allow modification
        const eventData = { ...event };

        // KRALAMOURE HANDLING (Imported Events)
        const meta = eventData.metadata as any;
        if (meta?.isKralamoure && meta?.metamobId) {
            // Override type
            (eventData as any).type = "KRALAMOURE";

            // Try to fetch live participants from Metamob
            try {
                const { getExternalKralamoureDetails } = await import("@/server/actions/event-actions");
                const details = await getExternalKralamoureDetails(meta.metamobId, guildId, 0); // Force fresh fetch for modal

                if (details && details.participants) {
                    // Replace participants with live data
                    (eventData as any).participants = details.participants.map((p: any, i: number) => ({
                        id: `krala-part-${i}`,
                        status: "REGISTERED",
                        position: i + 1,
                        user: {
                            id: `external-${i}`,
                            name: `${p.username} (${p.character_count})`,
                            image: null,
                            profiles: []
                        }
                    }));
                    (eventData as any)._count = { participants: details.participants_count };

                    // Also update metadata cache for next time
                    db.guildEvent.update({
                        where: { id: eventId },
                        data: { metadata: { ...meta, metamobParticipants: details.participants } }
                    }).catch(() => { }); // Fire-and-forget
                }
            } catch (err) {
                console.error("Failed to refresh Kralamoure participants", err);
            }

            // Fallback: if live fetch failed or returned null, use cached metadata participants
            if ((eventData as any).participants.length === 0 && meta.metamobParticipants?.length > 0) {
                (eventData as any).participants = meta.metamobParticipants.map((p: any, i: number) => ({
                    id: `krala-cache-${i}`,
                    status: "REGISTERED",
                    position: i + 1,
                    user: {
                        id: `cached-${i}`,
                        name: typeof p === "string" ? p : `${p.username}${p.character_count ? ` (${p.character_count})` : ""}`,
                        image: null,
                        profiles: []
                    }
                }));
            }
        }

        const isKrala = meta?.isKralamoure && meta?.metamobId;
        let hasMetamobKey = false;
        if (isKrala) {
            const userProfile = await db.userProfile.findFirst({
                where: { 
                    userId: ctx.id!, 
                    metamobApiKey: { not: null }
                },
                select: { metamobApiKey: true }
            });
            hasMetamobKey = !!userProfile?.metamobApiKey;
        }

        // Annotate raid participants who already played this week
        if (eventData.type === "RAID_OFFICIAL" && eventData.participants.length > 0) {
            const weekStart = new Date();
            weekStart.setDate(weekStart.getDate() - weekStart.getDay() + 1);
            weekStart.setHours(0, 0, 0, 0);

            const participantsWithCompletedRaids = await db.eventParticipant.findMany({
                where: {
                    userId: { in: eventData.participants.map((p: any) => p.userId) },
                    status: "REGISTERED",
                    event: {
                        guildId: guildConfig.id,
                        type: "RAID_OFFICIAL",
                        status: "COMPLETED",
                        startDate: { gte: weekStart }
                    }
                },
                select: { userId: true }
            });
            const repeatUserIds = new Set(participantsWithCompletedRaids.map((p: any) => p.userId));
            (eventData as any).participants = eventData.participants.map((p: any) => ({
                ...p,
                hasParticipatedThisWeek: repeatUserIds.has(p.userId)
            }));
        }

        return { success: true, event: eventData, hasMetamobKey };
    } catch (error) {
        console.error("[Calendar] getEventDetails Error:", error);
        return { success: false, error: "Erreur serveur" };
    }
}

/**
 * Get upcoming events for widget
 */
export async function getUpcomingEvents(guildId: string, days: number = 7) {
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated) return { success: false, error: "Non authentifié", events: [] };
    if (!ctx.isMember) return { success: false, error: "Membre requis", events: [] };

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true }
        });
        if (!guildConfig) return { success: false, error: "Guilde non trouvée", events: [] };

        const now = new Date();
        const endDate = new Date();
        endDate.setDate(endDate.getDate() + days);

        const events = await db.guildEvent.findMany({
            where: {
                guildId: guildConfig.id,
                startDate: { gte: now, lte: endDate },
                status: "PUBLISHED"
            },
            include: {
                _count: { select: { participants: true } }
            },
            orderBy: { startDate: "asc" },
            take: 5
        });

        return { success: true, events };
    } catch (error) {
        console.error("[Calendar] getUpcomingEvents Error:", error);
        return { success: false, error: "Erreur serveur", events: [] };
    }
}

/**
 * Returns the currently active RAID_OFFICIAL event (if any).
 * A raid is "active" when its startDate <= now <= endDate and status is PUBLISHED.
 */
export async function getActiveRaid(guildId: string) {
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated || !ctx.isMember) return null;

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true }
        });
        if (!guildConfig) return null;

        const now = new Date();

        const raid = await db.guildEvent.findFirst({
            where: {
                guildId: guildConfig.id,
                type: "RAID_OFFICIAL",
                status: "PUBLISHED",
                startDate: { lte: now },
                endDate: { gte: now }
            },
            include: {
                _count: { select: { participants: true } }
            },
            orderBy: { startDate: "desc" }
        });

        return raid;
    } catch {
        return null;
    }
}

