const CATEGORY_EMOJI: Record<string, string> = {
    FEATURE: '✨', BUGFIX: '🐛', SECURITY: '🔒', PERFORMANCE: '⚡', DOCUMENTATION: '📄'
};
const CATEGORY_COLOR: Record<string, number> = {
    FEATURE: 0x22c55e, BUGFIX: 0xf59e0b, SECURITY: 0xef4444, PERFORMANCE: 0x3b82f6, DOCUMENTATION: 0xa855f7
};
const CATEGORY_FR: Record<string, string> = {
    FEATURE: 'Fonctionnalité', BUGFIX: 'Correction', SECURITY: 'Sécurité', PERFORMANCE: 'Performance', DOCUMENTATION: 'Documentation'
};

/**
 * DISC-1 — Publish a changelog entry to the SigilOS Hub (official Discord).
 * Requires hubChannelId in PlatformConfig. Super-admin only.
 */
export async function sendChangelogToDiscord(entryId: string) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) return { success: false, error: 'Unauthorized' };

    const platformConfig = await db.platformConfig.findUnique({ where: { id: "singleton" } });
    const hubChannelId = platformConfig?.hubChannelId;
    
    if (!hubChannelId) {
        return { success: false, error: 'Salon du Hub non configuré dans les paramètres GOD' };
    }

    if (!entryId || entryId.length > 64) return { success: false, error: 'ID invalide' };

    const entry = await db.changelogEntry.findUnique({ where: { id: entryId } });
    if (!entry) return { success: false, error: 'Entrée introuvable' };

    const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'https://sigilos.fr';
    const emoji = CATEGORY_EMOJI[entry.category] ?? '📝';
    const color = CATEGORY_COLOR[entry.category] ?? 0x9333ea;

    // SLIM FORMAT
    const fullDescription = [
        entry.summary || "_Améliorations et corrections de bugs._",
        '',
        `> 🔗 **[Consulter le changelog complet v${entry.version}](${appUrl}/changelog)**`
    ].join('\n');

    const embed = {
        embedTitle: `${emoji} SigilOS ${entry.version} — ${entry.title}`,
        embedUrl: `${appUrl}/changelog`,
        embedDescription: fullDescription.slice(0, 4096),
        embedColor: color,
        embedFooter: `SigilOS Updater • ${CATEGORY_FR[entry.category] ?? entry.category} • ${new Date(entry.publishedAt).toLocaleDateString('fr-FR')}`,
        embedThumbnail: `${getAppBaseUrl()}/assets/ui/logo-v2.png`
    };

    const { sendChannelMessage } = await import("@/server/discord");

    try {
        const mid = await sendChannelMessage(hubChannelId, "", embed);
        if (!mid) return { success: false, error: `Discord a rejeté le message (Salon introuvable ou permissions manquantes)` };
        return { success: true };
    } catch (error) {
        console.error('[Changelog Discord] Fetch error:', error);
        return { success: false, error: "Erreur réseau lors de l'envoi" };
    }
}


/**
 * Broadcast a SigilOS Changelog to ALL active guilds (systemNotifyChannelId)
 * Super-admin only.
 */
export async function broadcastChangelogToGuilds(entryId: string) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) return { success: false, error: 'Unauthorized' };

    const entry = await db.changelogEntry.findUnique({ where: { id: entryId } });
    if (!entry) return { success: false, error: 'Entrée introuvable' };

    const guilds = await db.guildConfig.findMany({
        where: { isActive: true, systemNotifyChannelId: { not: null } },
        select: { discordGuildId: true, systemNotifyChannelId: true, name: true }
    });

    const results = {
        total: guilds.length,
        success: 0,
        failed: 0,
        errors: [] as string[]
    };

    const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'https://sigilos.fr';
    const emoji = CATEGORY_EMOJI[entry.category] ?? '📝';
    const color = CATEGORY_COLOR[entry.category] ?? 0x9333ea;

    // SLIM FORMAT
    const fullDescription = [
        entry.summary || "_Améliorations et corrections de bugs._",
        '',
        `> 🔗 **[Découvrir les nouveautés v${entry.version} sur SigilOS](${appUrl}/changelog)**`
    ].join('\n');

    const embed = {
        embedTitle: `${emoji} SigilOS ${entry.version} — ${entry.title}`,
        embedUrl: `${appUrl}/changelog`,
        embedDescription: fullDescription.slice(0, 4096),
        embedColor: color,
        embedFooter: `SigilOS Updater • ${CATEGORY_FR[entry.category] ?? entry.category} • ${new Date(entry.publishedAt).toLocaleDateString('fr-FR')}`,
        embedThumbnail: `${getAppBaseUrl()}/assets/ui/logo-v2.png`
    };

    const { sendChannelMessage } = await import("@/server/discord");

    // Batch sending (serial to avoid rate limits)
    for (const guild of guilds) {
        try {
            const mid = await sendChannelMessage(guild.systemNotifyChannelId!, "", embed);
            if (mid) results.success++;
            else throw new Error(`API null response for ${guild.name}`);
        } catch (e) {
            results.failed++;
            results.errors.push(`${guild.name}: ${(e as Error).message}`);
        }
    }

    return { success: true, results };
}

"use server";

import { db } from "@/lib/prisma";
import { sendChannelMessage } from "@/server/discord";
import { isSuperAdmin } from "./super-admin-actions";
import { getMemberReconciliation } from "./member-actions";
import { getPlatformStats } from "./super-admin-actions";

/**
 * 📊 Envoie un rapport quotidien détaillé sur Discord.
 * Contrairement au Status Ping qui met à jour un message existant, 
 * celui-ci envoie un NOUVEAU message pour générer une notification.
 */
export async function sendDailySummaryReport(guildId: string, isManual = false) {
    if (isManual) {
        const isAdmin = await isSuperAdmin();
        if (!isAdmin) throw new Error("Accès refusé");
    }

    try {
        // En 2026, on veut du visuel et de la data utile.
        const [config, stats, reconciliation] = await Promise.all([
            db.guildConfig.findUnique({
                where: { discordGuildId: guildId },
                select: { 
                    name: true, 
                    systemNotifyChannelId: true,
                    _count: { select: { profiles: true } }
                }
            }),
            getPlatformStats(),
            getMemberReconciliation(guildId)
        ]);

        if (!config?.systemNotifyChannelId) {
            return { success: false, error: "Canal de notification système non configuré pour cette guilde." };
        }

        const unregisteredCount = reconciliation.success 
            ? reconciliation.data!.members.filter(m => !m.hasDashboardProfile).length 
            : 0;

        const { getAppBaseUrl } = await import("@/lib/utils");
        const dashboardUrl = `${getAppBaseUrl()}/dashboard/${guildId}/admin/members`;

        const embed = {
            embedTitle: `📅 Rapport Quotidien — ${config.name}`,
            embedUrl: dashboardUrl,
            embedDescription: `Voici le résumé de l'activité du serveur pour ces dernières 24 heures.\n[Gérer les Membres et l'Audit ➡️](${dashboardUrl})`,
            embedColor: 0x9333ea, // Purple
            embedThumbnail: "https://sigilos.fr/assets/ui/logo-v2.png",
            fields: [
                {
                    name: "👥 AUDIT MEMBRES",
                    value: `Inscrits: **${config._count.profiles}**\nNon-identifiés: **${unregisteredCount}** ⚠️`,
                    inline: true
                },
                {
                    name: "🛰️ INFRASTRUCTURE",
                    value: `Systèmes: **OPÉRATIONNELS**\nUptime: \`${Math.floor(process.uptime() / 3600)}h ${Math.floor((process.uptime() % 3600) / 60)}m\``,
                    inline: true
                },
                {
                    name: "📈 ACTIVITÉ GLOBALE",
                    value: `Utilisateurs actifs: **${stats.weeklyActiveUsers}** (semaine)\nMissions en cours: **${stats.totalMissions}**`,
                    inline: false
                }
            ],
            embedFooter: `SigilOS Intelligence Artificielle • Rapport du ${new Date().toLocaleDateString('fr-FR')}`,
        };

        const messageId = await sendChannelMessage(config.systemNotifyChannelId, "", embed);

        if (!messageId) {
            return { success: false, error: "Échec de l'envoi sur Discord." };
        }

        return { success: true, messageId };

    } catch (error: any) {
        console.error("[Daily Report] Error:", error);
        return { success: false, error: error.message || "Erreur lors de la génération du rapport" };
    }
}

"use server";

import { auth } from "@/auth";
import { db } from "@/lib/prisma";
import { getUserContext } from "./user-actions";
import { revalidatePath } from "next/cache";
import { logger } from "@/lib/logger";
import { validateChannelBelongsToGuild } from "@/server/discord";

export async function getDirectorySettings(guildId: string) {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Unauthorized" };

    const { requireGuildConfigAccess } = await import("./guards");
    const guard = await requireGuildConfigAccess(guildId);
    if (!guard.isAuthorized) return { success: false, error: guard.error || "Forbidden" };

    try {
        const config = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { userRequestChannelId: true }
        });

        return { success: true, data: config };
    } catch (error) {
        logger.error("Get Directory Settings Error", { error });
        return { success: false, error: "Erreur serveur" };
    }
}

export async function saveDirectorySettings(guildId: string, channelId: string | null) {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Unauthorized" };

    const { requireGuildConfigAccess } = await import("./guards");
    const guard = await requireGuildConfigAccess(guildId);
    if (!guard.isAuthorized) return { success: false, error: guard.error || "Forbidden" };

    if (channelId) {
        const belongs = await validateChannelBelongsToGuild(channelId, guildId);
        if (!belongs) {
            return { success: false, error: "Le salon sélectionné n'appartient pas à ce serveur Discord." };
        }
    }

    try {
        await db.guildConfig.update({
            where: { discordGuildId: guildId },
            data: { userRequestChannelId: channelId }
        });

        revalidatePath(`/dashboard/${guildId}/admin/settings`);
        return { success: true };
    } catch (error) {
        logger.error("Save Directory Settings Error", { error });
        return { success: false, error: "Erreur serveur" };
    }
}

/**
 * Discord Interaction Validation Actions
 *
 * Fonctions "internal" appelées UNIQUEMENT depuis /api/discord/interactions.
 * Elles bypassent auth() car la sécurité est garantie par :
 *   1. Vérification de signature Ed25519 Discord (dans le router interactions)
 *   2. internalCheckPermission → vérifie MISSIONS_VALIDATE sur le Discord ID de l'admin
 *
 * Jamais exposées en tant que Server Actions Next.js ("use server" absent intentionnellement).
 */

import { db } from "@/lib/prisma";
import { revalidatePath } from "next/cache";
import { PERMISSIONS } from "@/lib/permissions";
import { NotificationType, PrismaClient } from "@prisma/client";
import { createNotification } from "@/server/actions/notification-actions";
import { deleteProofFile } from "@/lib/storage-utils";
import { createAuditLog } from "@/server/actions/audit-actions";
import { grantRewards } from "@/server/actions/mission-actions";

const kamaDb = db as unknown as PrismaClient;


// ============================================================================
// HELPER — Permission check sans session (via Discord User ID)
// ============================================================================

async function requireDiscordAdmin(discordGuildId: string, discordUserId: string): Promise<
    { allowed: true; internalUserId: string; adminName: string } |
    { allowed: false; error: string }
> {
    const { internalCheckPermission } = await import("@/server/actions/user-actions");
    const hasPermission = await internalCheckPermission(discordGuildId, discordUserId, PERMISSIONS.MISSIONS_OFFICER);
    if (!hasPermission) return { allowed: false, error: "Permissions insuffisantes (MISSIONS_VALIDATE requis)." };

    const account = await db.account.findFirst({
        where: { provider: "discord", providerAccountId: discordUserId },
        select: { userId: true, user: { select: { name: true } } },
    });
    if (!account) return { allowed: false, error: "Admin inconnu sur SigilOS." };

    return { allowed: true, internalUserId: account.userId, adminName: account.user?.name || "Admin Discord" };
}

// ============================================================================
// 1. MISSION SUBMISSION
// ============================================================================

export async function internalValidateMissionSubmission(
    submissionId: string,
    status: "VALIDATED" | "REJECTED",
    discordGuildId: string,
    discordAdminId: string
): Promise<{ success: boolean; error?: string; memberName?: string; missionTitle?: string }> {
    const guard = await requireDiscordAdmin(discordGuildId, discordAdminId);
    if (!guard.allowed) return { success: false, error: guard.error };

    try {
        const submission = await db.submission.findUnique({
            where: { id: submissionId },
            include: {
                mission: { include: { guild: true } },
                profile: { include: { user: true } },
                helpers: true,
            },
        });
        if (!submission) return { success: false, error: "Soumission introuvable." };
        if (submission.status !== "PENDING") return { success: false, error: "Cette soumission a déjà été traitée." };
        if (submission.mission.guild.discordGuildId !== discordGuildId) return { success: false, error: "Guilde invalide." };

        // 1. Delete proof file
        await deleteProofFile(submission.proofUrl);

        // 2. Delete image hash
        await (db as any).imageHash.deleteMany({
            where: { guildId: submission.mission.guild.id, sourceType: "MISSION", sourceId: submissionId },
        });

        // 3. Delete Discord embed
        if (submission.discordMessageId && submission.discordMessageId.includes(":")) {
            const [channelId, msgId] = submission.discordMessageId.split(":");
            if (channelId && msgId) {
                try {
                    const { deleteChannelMessage } = await import("@/server/discord");
                    await deleteChannelMessage(channelId, msgId);
                } catch (e) {
                    console.error("[internalValidateMissionSubmission] Failed to delete Discord embed", e);
                }
            }
        }

        // 4. Update DB
        const updated = await db.submission.update({
            where: { id: submissionId },
            data: { status, validatorId: guard.internalUserId, proofUrl: "", discordMessageId: null },
            include: { profile: { include: { user: true } }, helpers: true },
        });

        // 4. Award XP & Guildatons (if validated)
        if (status === "VALIDATED") {
            const xpReward = (submission.mission as any).xpReward || 0;
            const guildatonsReward = (submission.mission as any).guildatonsReward || 0;
            const { getDofusWeek } = await import("@/lib/date-utils");
            const { week, year } = getDofusWeek();
            await grantRewards(updated.profileId, xpReward, guildatonsReward, submission.mission.weekNumber || week, (submission.mission as any).year || year);

            // Award helpers contribution points
            if (updated.helpers.length > 0) {
                const rankPointsMap: Record<number, number> = { 1: 5, 2: 10, 3: 20, 4: 50 };
                const points = rankPointsMap[(submission.mission as any).rank] || 5;
                await db.userProfile.updateMany({
                    where: { id: { in: updated.helpers.map((h: any) => h.id) } },
                    data: { contributionPoints: { increment: points } },
                });
            }
        }

        // 5. Notify submitter
        const notifType = status === "VALIDATED" ? "MISSION_VALIDATED" : "MISSION_REJECTED";
        const resultMsg = status === "VALIDATED" ? "✅ validée !" : "❌ refusée.";
        await createNotification(
            updated.profile.userId,
            notifType as NotificationType,
            `[Mission] ${submission.mission.title}`,
            `Votre preuve a été ${resultMsg}`,
            undefined,
            discordGuildId
        );

        // 6. Audit log
        await createAuditLog({
            guildId: discordGuildId,
            actorUserId: guard.internalUserId,
            actorName: guard.adminName,
            action: (status === "VALIDATED" ? "MISSION_VALIDATED" : "MISSION_REJECTED") as any,
            targetType: "MISSION" as any,
            targetId: submissionId,
            metadata: {
                missionTitle: submission.mission.title ?? undefined,
                submitterId: updated.profileId,
                submitterName: updated.profile.pseudoDofus || updated.profile.discordNickname || updated.profile.user?.name || "Membre",
                status,
                source: "discord_button",
                xpReward: status === "VALIDATED" ? ((submission.mission as any).xpReward || 0) : 0,
                guildatonsReward: status === "VALIDATED" ? ((submission.mission as any).guildatonsReward || 0) : 0,
                helpersCount: updated.helpers.length
            },
        });

        revalidatePath(`/dashboard/${discordGuildId}/missions`);
        revalidatePath(`/dashboard/${discordGuildId}/ladder`);
        revalidatePath(`/dashboard/${discordGuildId}/admin/validation`);

        // 🔥 Sync weekly mission embed jalons (fire-and-forget)
        if (status === "VALIDATED") {
            const { refreshMissionDiscordEmbed } = await import("./mission-actions");
            refreshMissionDiscordEmbed(discordGuildId).catch((e) =>
                console.error("[Discord] refreshMissionDiscordEmbed after Discord validation failed:", e)
            );
        }

        const memberName = updated.profile.discordNickname || updated.profile.pseudoDofus || updated.profile.user?.name || "Membre";
        return { success: true, memberName, missionTitle: submission.mission.title ?? undefined };
    } catch (error) {
        console.error("[internalValidateMissionSubmission]", error);
        return { success: false, error: "Erreur serveur." };
    }
}

// ============================================================================
// 3. KAMA DONATION
// ============================================================================

export async function internalReviewKamaDonation(
    donationId: string,
    action: "VALIDATE" | "REJECT",
    discordGuildId: string,
    discordAdminId: string
): Promise<{ success: boolean; error?: string; memberName?: string; amount?: number }> {
    const guard = await requireDiscordAdmin(discordGuildId, discordAdminId);
    if (!guard.allowed) return { success: false, error: guard.error };

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId },
            select: { id: true },
        });
        if (!guildConfig) return { success: false, error: "Guilde introuvable." };

        const donation = await (kamaDb as any).kamaDonation.findFirst({
            where: { id: donationId, guildId: guildConfig.id },
            include: { profile: { include: { user: true } } },
        });
        if (!donation) return { success: false, error: "Donation introuvable." };
        if (donation.status !== "PENDING") return { success: false, error: "Cette donation a déjà été traitée." };

        const newStatus = action === "VALIDATE" ? "VALIDATED" : "REJECTED";

        // Find admin profile
        const adminProfile = await db.userProfile.findFirst({
            where: { userId: guard.internalUserId, guildId: guildConfig.id },
            select: { id: true },
        });

        await (kamaDb as any).kamaDonation.update({
            where: { id: donationId },
            data: {
                status: newStatus,
                validatedById: adminProfile?.id ?? undefined,
                validatedAt: new Date(),
                rejectedReason: action === "REJECT" ? "Refusé via Discord" : null,
                discordMessageId: null,
            },
        });

        // Award rewards (if validated)
        if (newStatus === "VALIDATED") {
            const { KAMA_TRANCHE, REWARDS_PER_TRANCHE } = await import("@/lib/kama-constants");
            const tranches = Math.floor(donation.amount / KAMA_TRANCHE);
            const addedXp = tranches * REWARDS_PER_TRANCHE.xp;
            const addedGuildatons = tranches * REWARDS_PER_TRANCHE.guildatons;

            if (addedXp > 0 || addedGuildatons > 0) {
                // Use consistent reward function
                const { getDofusWeek } = await import("@/lib/date-utils");
                const { week, year } = getDofusWeek();
                await grantRewards(donation.profileId, addedXp, addedGuildatons, donation.weekNumber || week, donation.yearNumber || year);
            }
        }

        // Delete proof file + image hash (validation ET rejet)
        if (donation.proofUrl) {
            await deleteProofFile(donation.proofUrl);
            await (db as any).imageHash.deleteMany({
                where: { guildId: guildConfig.id, sourceType: "KAMA_DONATION", sourceId: donationId },
            });
        }

        // Delete Discord embed (validation ET rejet)
        if (donation.discordMessageId && donation.discordMessageId.includes(":")) {
            const [channelId, msgId] = donation.discordMessageId.split(":");
            if (channelId && msgId) {
                try {
                    const { deleteChannelMessage } = await import("@/server/discord");
                    await deleteChannelMessage(channelId, msgId);
                } catch (e) {
                    console.error("[internalReviewKamaDonation] Failed to delete Discord embed", e);
                }
            }
        }

        revalidatePath(`/dashboard/${discordGuildId}/missions`);
        revalidatePath(`/dashboard/${discordGuildId}/ladder`);
        revalidatePath(`/dashboard/${discordGuildId}/admin/validation`);

        // 🔥 Sync weekly mission embed jalons (fire-and-forget)
        if (newStatus === "VALIDATED") {
            const { refreshMissionDiscordEmbed } = await import("./mission-actions");
            refreshMissionDiscordEmbed(discordGuildId).catch((e) =>
                console.error("[Discord] refreshMissionDiscordEmbed after kama Discord validation failed:", e)
            );
        }

        const memberName = donation.profile?.discordNickname || donation.profile?.pseudoDofus || donation.profile?.user?.name || "Membre";
        return { success: true, memberName, amount: donation.amount };
    } catch (error) {
        console.error("[internalReviewKamaDonation]", error);
        return { success: false, error: "Erreur serveur." };
    }
}

