/**
 * Get the dungeon directory for a specific dungeon.
 * Returns two lists of members per achievement: those who have it, and those who don't.
 */
export async function getDungeonDirectory(
    guildId: string,
    dungeonId: string,
    dungeonName?: string
): Promise<ActionResponse<{
    achievementId: string;
    achievementName: string;
    iconUrl: string | null;
    points: number;
    hasCompleted: { id: string; name: string; imageUrl: string | null; classe: string | null }[];
    missing: { id: string; name: string; imageUrl: string | null; classe: string | null }[];
}[]>> {
    const user = await getUserContext(guildId);
    if (!user.canViewFinder) return { success: false, error: "Accès refusé" };

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true },
        });
        if (!guildConfig) return { success: false, error: "Guilde introuvable" };

        // 1. Get all achievements for this dungeon
        let targetDjId = dungeonId;

        // If dungeonId looks like a Dofus numeric ID or if no achievements found, try name lookup
        if (dungeonName || !dungeonId.startsWith('c')) {
            const resolvedDungeon = await db.dungeon.findFirst({
                where: {
                    OR: [
                        { name: { contains: dungeonName || dungeonId, mode: 'insensitive' } },
                        { bossName: { contains: dungeonName || dungeonId, mode: 'insensitive' } }
                    ]
                },
                select: { id: true }
            });
            if (resolvedDungeon) {
                targetDjId = resolvedDungeon.id;
            }
        }

        const dungeonAchievements = await (db as any).dungeonAchievement.findMany({
            where: { dungeonId: targetDjId },
            include: { challenge: { select: { name: true, iconUrl: true } } },
        });

        if (dungeonAchievements.length === 0) {
            return { success: true, data: [] };
        }

        // 2. Get all ACTIVE members of the guild
        const activeMembers = await db.userProfile.findMany({
            where: { guildId: guildConfig.id, status: "ACTIVE" },
            select: {
                id: true,
                discordNickname: true,
                pseudoDofus: true,
                classe: true,
                user: { select: { image: true } },
            },
        });

        // 3. Get all progress for these achievements within the guild
        const achievementIds = dungeonAchievements.map((a: any) => a.id);
        const allProgress = await (db as any).userDungeonProgress.findMany({
            where: {
                achievementId: { in: achievementIds },
                profile: { guildId: guildConfig.id, status: "ACTIVE" },
            },
            select: { profileId: true, achievementId: true },
        });

        // 4. Map them out
        const result = dungeonAchievements.map((a: any) => {
            const completedProfileIds = new Set(
                allProgress.filter((p: any) => p.achievementId === a.id).map((p: any) => p.profileId)
            );

            const hasCompleted: any[] = [];
            const missing: any[] = [];

            activeMembers.forEach((member) => {
                const memberData = {
                    id: member.id,
                    name: member.pseudoDofus || member.discordNickname || "Inconnu",
                    imageUrl: member.user.image,
                    classe: member.classe,
                };

                if (completedProfileIds.has(member.id)) {
                    hasCompleted.push(memberData);
                } else {
                    missing.push(memberData);
                }
            });

            // Sort alphabetically
            hasCompleted.sort((a: any, b: any) => a.name.localeCompare(b.name));
            missing.sort((a: any, b: any) => a.name.localeCompare(b.name));

            return {
                achievementId: a.id,
                achievementName: a.challenge.name,
                iconUrl: a.challenge.iconUrl,
                points: a.points,
                hasCompleted,
                missing,
            };
        });

        return { success: true, data: result };
    } catch (error) {
        console.error("[getDungeonDirectory]", error);
        return { success: false, error: "Erreur lors du chargement de l'annuaire" };
    }
}

"use server";

import { db } from "@/lib/prisma";
import { auth } from "@/auth";
import { redis } from "@/lib/redis";
import { logger } from "@/lib/logger";

import { getKralamoureEvents, getKralamoureEventDetails, MetamobApiError } from "@/lib/metamob-client";
import { decrypt } from "@/lib/encryption";

export type UpcomingEvent = {
    id: string;
    title: string;
    startDate: string; // ISO string — Date objects crash Next.js server→client serialization
    type: string;
    participantsCount: number;
    metadata?: any;
};

export async function getUpcomingGuildEvents(guildId: string, limit = 5): Promise<UpcomingEvent[]> {
    const session = await auth();
    if (!session?.user?.id) return [];

    const cacheKey = `guild:events:upcoming:${guildId}:${session.user.id}:${limit}`;

    try {
        const cached = await redis.get(cacheKey).catch(() => null);
        if (cached) return JSON.parse(cached) as UpcomingEvent[];

        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true }
        });
        if (!guildConfig) return [];

        const userProfile = await db.userProfile.findFirst({
            where: {
                userId: session.user.id,
                guildId: guildConfig.id
            },
            select: { metamobServerId: true, metamobApiKey: true }
        });

    const now = new Date();

    // 2. Fetch Internal Guild Events
    const dbEventsPromise = db.guildEvent.findMany({
        where: {
            guildId: guildConfig.id,
            startDate: { gte: now },
            status: { not: "CANCELLED" }
        },
        orderBy: { startDate: "asc" },
        take: limit, // Fetch more than needed to allow merging
        select: {
            id: true,
            title: true,
            startDate: true,
            type: true,
            metadata: true,
            _count: {
                select: { participants: { where: { status: "REGISTERED" } } }
            }
        }
    });

    // 3. Fetch Kralamoure Events (if user has a server configured)
    let kralaEvents: any[] = [];
    if (userProfile?.metamobServerId) {
        const cacheKey = `krala:events:${userProfile.metamobServerId}`;
        const apiKey = userProfile.metamobApiKey;
        
        try {
            // Check Redis cache first (short TTL: 60s)
            const cached = await redis.get(cacheKey);
            if (cached) {
                kralaEvents = JSON.parse(cached);
            } else {
                const results = await getKralamoureEvents({
                    serverId: userProfile.metamobServerId,
                    from: now.toISOString(),
                    guildApiKey: apiKey
                });
                
                if (results) {
                    kralaEvents = results;
                    await redis.set(cacheKey, JSON.stringify(kralaEvents), "EX", 60).catch(() => {});
                }
            }
        } catch (err) {
            console.error("[getUpcomingGuildEvents] Failed to fetch Kralamoure events:", err);
            kralaEvents = [];
        }
    }

    const dbEvents = await dbEventsPromise;

    // 4. Normalize & Merge
    const normalizedDbEvents: UpcomingEvent[] = dbEvents.map(e => {
        const meta = e.metadata as any;
        return {
            id: e.id,
            title: e.title,
            startDate: e.startDate.toISOString(),
            type: e.type,
            participantsCount: ((e.type as any) === "KRALAMOURE" || meta?.isKralamoure) 
                ? (meta?.metamobParticipantsCount || e._count.participants) 
                : e._count.participants
        };
    });

    const normalizedKralaEvents: UpcomingEvent[] = kralaEvents.map((k: any) => ({
        id: `krala-${k.id}`,
        title: `Ouverture Kralamoure`,
        startDate: new Date(k.event_datetime).toISOString(),
        type: "KRALAMOURE",
        participantsCount: k.participants_count || 0
    }));

    // 6. Fetch Active Game Sessions from Redis
    const [skribblRooms, garticRooms, geoRooms] = await Promise.all([
        redis.get(`guild:${guildId}:skribbl:rooms`),
        redis.get(`guild:${guildId}:gartic:rooms`),
        redis.get(`guild:${guildId}:geoguesser:rooms`),
    ]);

    const sessions: UpcomingEvent[] = [];



    const getGameTitle = (type: string, hostName: string) => {
        switch (type) {
            case 'SKRIBBL': return `🎨 Skribbl (${hostName})`;
            case 'GARTIC': return `📱 Phone (${hostName})`;
            case 'GEOGUESSER': return `🌍 Guesser (${hostName})`;
            default: return `🎮 ${type} (${hostName})`;
        }
    };

    const parseGameRooms = (rawData: string | null, type: string) => {
        if (!rawData) return;
        try {
            const rooms = JSON.parse(rawData);
            rooms.forEach((r: any) => {
                const roomId = r.roomId || r.id; // Support both naming variants
                sessions.push({
                    id: `game-${type}-${roomId}`,
                    title: getGameTitle(type, r.hostName || 'Inconnu'),
                    startDate: new Date().toISOString(), // Active now
                    type: `GAME_${type}`,
                    participantsCount: r.playerCount || 0,
                    metadata: {
                        roomId: roomId,
                        isLive: true,
                        state: r.state || 'LOBBY', // Needed to know if we can join or just spec
                    }
                });
            });
        } catch (e) {}
    };

    parseGameRooms(skribblRooms, 'SKRIBBL');
    parseGameRooms(garticRooms, 'GARTIC');
    parseGameRooms(geoRooms, 'GEOGUESSER');

    // 7. Combine, Deduplicate and Sort (Prioritize live games)
    // Map DB events by their Metamob ID for easy lookup
    const dbMetamobIds = new Set(
        normalizedDbEvents
            .filter(e => (e as any).metadata?.metamobId)
            .map(e => (e as any).metadata.metamobId.toString())
    );

    // Merge: Include live games, all DB events, and ONLY non-imported Kralamoure events
    const allEvents = [
        ...sessions,
        ...normalizedDbEvents.map(dbEv => {
            // If it's an imported Krala event, try to find the live version to update count
            const meta = (dbEv as any).metadata;
            if (meta?.isKralamoure && meta?.metamobId) {
                const liveMatch = normalizedKralaEvents.find(k => k.id === `krala-${meta.metamobId}`);
                if (liveMatch) {
                    return { ...dbEv, participantsCount: liveMatch.participantsCount };
                }
            }
            return dbEv;
        }),
        ...normalizedKralaEvents.filter(k => {
            const id = k.id.replace("krala-", "");
            return !dbMetamobIds.has(id);
        })
    ].sort((a, b) => {
        // Priority to live games
        const aLive = (a.metadata as any)?.isLive;
        const bLive = (b.metadata as any)?.isLive;
        return new Date(a.startDate).getTime() - new Date(b.startDate).getTime();
    });

    const result = allEvents.slice(0, limit);
    await redis.set(cacheKey, JSON.stringify(result), "EX", 15).catch(() => {});
    return result;
    } catch (error) {
        console.error("[getUpcomingGuildEvents] Error:", error);
        return [];
    }
}

export async function getExternalKralamoureDetails(kralaId: number, guildId: string, revalidate?: number) {
    const session = await auth();
    if (!session?.user?.id) return null;

    // SECURITY: Ensure user is a member of the requested guild
    const { getUserContext } = await import("@/server/actions/user-actions");
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated || !ctx.isMember) return null;

    // We need an API key. Try user's key first, then any member's key.
    const userProfile = await db.userProfile.findFirst({
        where: { 
            userId: session.user.id, 
            metamobApiKey: { not: null }
        },
        select: { metamobApiKey: true }
    });

    let apiKey = userProfile?.metamobApiKey;
    let keySource = userProfile?.metamobApiKey ? "user" : "none";

    // Fallback: grab any guild member's key if we still have none
    if (!apiKey) {
        const anyMemberWithKey = await db.userProfile.findFirst({
            where: { guildId: ctx.guildId, metamobApiKey: { not: null }, status: "ACTIVE" },
            select: { metamobApiKey: true },
        });
        apiKey = anyMemberWithKey?.metamobApiKey;
        keySource = anyMemberWithKey ? "fallback-member" : "none";
    }

    logger.error("[getExternalKralamoureDetails] Key resolution:", {
        kralaId,
        guildId,
        keySource,
        hasKey: !!apiKey,
        keyPreview: apiKey ? `${apiKey.substring(0, 8)}...` : "null",
    });

    if (!apiKey) return null; // No key anywhere — can't fetch

    try {
        const details = await getKralamoureEventDetails(kralaId, { 
            guildApiKey: apiKey,
            revalidate: revalidate ?? 3600 // Default to 1h if not specified
        });
        logger.error("[getExternalKralamoureDetails] SUCCESS:", {
            kralaId,
            participantsCount: details.participants_count,
            participantsList: details.participants?.length,
        });
        return details;
    } catch (error) {
        logger.error("[getExternalKralamoureDetails] Failed:", { error, kralaId, guildId, keySource });
        return null;
    }
}

"use server";

type AlmanaxData = {
    bonus: {
        description: string;
        type: {
            name: string;
            id: string;
        };
    };
    tribute: {
        item: {
            name: string;
            image_urls: {
                icon: string;
            };
        };
        quantity: number;
    };
    date: string;
};

/**
 * Calculate seconds until midnight in Paris timezone
 */
function getSecondsUntilMidnight(): number {
    const now = new Date();
    // Get current time in Paris timezone
    const parisTime = new Date(now.toLocaleString("en-US", { timeZone: "Europe/Paris" }));

    // Calculate midnight Paris time
    const midnight = new Date(parisTime);
    midnight.setDate(midnight.getDate() + 1);
    midnight.setHours(0, 0, 0, 0);

    // Calculate difference in seconds, add 60s buffer to ensure API has updated
    const secondsUntilMidnight = Math.floor((midnight.getTime() - parisTime.getTime()) / 1000) + 60;

    // Minimum 60 seconds, maximum 24 hours
    return Math.max(60, Math.min(secondsUntilMidnight, 86400));
}

export async function getAlmanaxData(): Promise<{
    success: boolean;
    data?: AlmanaxData;
    error?: string;
    secondsUntilMidnight?: number;
}> {
    try {
        // Use Paris timezone for date to match Dofus game day
        const parisDate = new Date().toLocaleDateString("sv-SE", { timeZone: "Europe/Paris" }); // YYYY-MM-DD format
        const secondsUntilMidnight = getSecondsUntilMidnight();
        const url = `https://api.dofusdu.de/dofus2/fr/almanax/${parisDate}`;

        let res = await fetch(url, {
            headers: {
                "Accept": "application/json",
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36"
            },
            next: { revalidate: secondsUntilMidnight }, // Dynamic cache until midnight
        });

        if (!res.ok) {
            console.warn(`Direct fetch for Almanax data failed (${res.status}), trying proxy...`);
            const proxyUrl = `https://api.allorigins.win/get?url=${encodeURIComponent(url)}`;
            res = await fetch(proxyUrl, {
                headers: { "User-Agent": "SigilOS/1.0" },
                next: { revalidate: secondsUntilMidnight }
            });

            if (res.ok) {
                const text = await res.text();
                try {
                    const json = JSON.parse(text);
                    if (json.contents) {
                        return { success: true, data: JSON.parse(json.contents), secondsUntilMidnight };
                    }
                } catch (e) {
                    throw new Error(`Proxy returned invalid JSON: ${text.slice(0, 100)}`);
                }
            }
            throw new Error(`Proxy fallback failed. Status: ${res.status}`);
        }

        const data = await res.json();
        return { success: true, data, secondsUntilMidnight };
    } catch (error) {
        console.error("Almanax Fetch Error:", error);
        return { success: false, error: "Impossible de charger l'Almanax" };
    }
}

// src/server/actions/feed-actions.ts
"use server";

import { db } from "@/lib/prisma";
import { getUserContext } from "./user-actions";
import { fetchDofusNews, fetchTwitchLiveStreams, fetchYouTubeLatestVideos, fetchDPLNNews, ExtractedContent } from "@/lib/feed-aggregators";
import { logger } from "@/lib/logger";
import { revalidatePath } from "next/cache";

const CACHE_MINUTES = 15;

// The creators we want to track
const TWITCH_HANDLES = ["huzounet", "skyziotv", "laniyelle", "barbe___douce", "sapeuh", "liche"];
const YOUTUBE_HANDLES = ["@Huzounet", "@Skyzio", "@Laniyelle", "@BarbeDouce-YT", "@SAPEUH1", "@Liche_fr"];

/**
 * Gets the aggregated feed of Dofus Content (News, YouTube, Twitch).
 * Uses a "Lazy Pull" strategy: only fetches external APIs if the cache is older than 15 mins.
 */
export async function getAggregatedFeed(guildId: string, forceRefresh = false) {
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated) return { success: false, error: "Unauthorized" };

    try {
        // Find internal guild ID
        let targetId = guildId;
        if (guildId.length > 15) {
            const guild = await db.guildConfig.findUnique({ where: { discordGuildId: guildId }, select: { id: true } });
            if (guild) targetId = guild.id;
        }

        // Fetch dynamic creators from DB
        const dbCreators = await (db as any).contentCreator.findMany({
            where: { guildId: targetId }
        });

        const twitchHandles = (dbCreators as any[]).filter(c => c.twitch).map(c => {
            const handle = c.handle || c.twitch?.split('/').pop();
            return handle?.toLowerCase();
        }).filter(Boolean) as string[];

        const youtubeHandles = (dbCreators as any[]).filter(c => c.youtube).map(c => {
            if (c.handle?.startsWith('@')) return c.handle;
            const handle = c.youtube?.split('/').pop();
            return handle?.startsWith('@') ? handle : `@${handle}`;
        }).filter(id => id && id !== '@') as string[];

        // @ts-ignore
        const newestCacheEntry = await db.contentCache.findFirst({
            where: { creatorId: { in: ["Ankama", "DPLN"] } },
            orderBy: { fetchedAt: 'desc' }
        });

        const now = new Date();
        const cacheLimit = CACHE_MINUTES * 60 * 1000;
        const needsRefresh = forceRefresh || !newestCacheEntry ||
            (now.getTime() - newestCacheEntry.fetchedAt.getTime() > cacheLimit);

        if (needsRefresh) {
            logger.info("Content cache stale, lazy-pulling fresh data...", { guildId, twitchHandles, youtubeHandles });

            // Fetch everything in parallel
            const [news, streams, videos, dpln] = await Promise.all([
                fetchDofusNews(),
                fetchTwitchLiveStreams(twitchHandles.length > 0 ? twitchHandles : ["huzounet"]),
                fetchYouTubeLatestVideos(youtubeHandles.length > 0 ? youtubeHandles : ["@Huzounet"]),
                fetchDPLNNews()
            ]);

            const allContent: ExtractedContent[] = [...news, ...streams, ...videos, ...dpln];

            // Update Database (Upsert based on unique constraint)
            if (allContent.length > 0) {
                // @ts-ignore
                await db.contentCache.deleteMany({
                    where: {
                        OR: [
                            { type: "TWITCH" },
                            { creatorId: "DPLN" },
                            { creatorId: "Ankama" }
                        ]
                    }
                });

                // Insert/Update new content
                // Prisma currently doesn't have an easy upsertMany without extensions, so we'll do individual upset tasks
                const upsertPromises = allContent.map(item =>
                    // @ts-ignore
                    db.contentCache.upsert({
                        where: {
                            type_creatorId_url: {
                                type: item.type,
                                creatorId: item.creatorId,
                                url: item.url
                            }
                        },
                        update: {
                            title: item.title,
                            thumbnail: item.thumbnail,
                            description: item.description || null,
                            published: item.published,
                            fetchedAt: now
                        },
                        create: {
                            type: item.type,
                            creatorId: item.creatorId,
                            title: item.title,
                            url: item.url,
                            thumbnail: item.thumbnail,
                            description: item.description || null,
                            published: item.published,
                            fetchedAt: now
                        }
                    })
                );

                await Promise.all(upsertPromises);
            }
        }

        // 2. Fetch the current fresh feed from the database
        // We limit to the newest 30 items
        // @ts-ignore
        const feed = await db.contentCache.findMany({
            orderBy: { published: 'desc' },
            take: 30
        });

        // Calculate "unread" items
        const rawUser = await db.user.findUnique({
            where: { id: ctx.id! }
        });

        // @ts-ignore
        const lastSeen = rawUser?.lastFeedViewedAt || new Date(0);
        const unreadCount = feed.filter((item: any) => item.published > lastSeen).length;

        return {
            success: true,
            data: feed,
            unreadCount
        };

    } catch (error) {
        logger.error("Failed to get aggregated feed", { error: (error as Error).message, guildId });
        return { success: false, error: "Internal Server Error" };
    }
}

/**
 * Gets currently live streamers from the cache.
 */
export async function getLiveStreamers(guildId: string) {
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated) return { success: false, error: "Unauthorized" };

    try {
        // @ts-ignore
        const live = await db.contentCache.findMany({
            where: { type: "TWITCH" },
            select: { creatorId: true, url: true, title: true }
        });

        return { success: true, data: live };
    } catch (error) {
        logger.error("Failed to get live streamers", { error: (error as Error).message, guildId });
        return { success: false, error: "Internal Server Error" };
    }
}

/**
 * Marks the feed as read for the current user.
 */
export async function markFeedAsRead(guildId: string) {
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated) return { success: false, error: "Unauthorized" };

    try {
        await db.user.update({
            where: { id: ctx.id! },
            // @ts-ignore
            data: { lastFeedViewedAt: new Date() }
        });

        revalidatePath(`/dashboard/${guildId}`);

        return { success: true };
    } catch (error) {
        logger.error("Failed to mark feed as read", { error: (error as Error).message, guildId });
        return { success: false, error: "Internal Server Error" };
    }
}

"use server";

import { db } from "@/lib/prisma";
import { getUserContext } from "./user-actions";
import { Prisma } from "@prisma/client";
import { revalidatePath } from "next/cache";
import { DOFUS_CLASSES } from "@/lib/dofus-assets";
import { logger } from "@/lib/logger";

const PAGE_SIZE = 24; // 24 cards per page (6 col × 4 rows)

export type GalleryBuild = {
    id: string;
    name: string;
    url: string;
    tags?: string[];
    classId?: string | number; // stored as string ("cra", "roublard") or number from legacy data
    previewData?: any; // Cached build info
    source?: "dofusbook";
    author: {
        id: string;
        name: string;
        image: string | null;
    };
    votesCount: number;
    hasVoted: boolean;
    createdAt?: string | null; // Date d'ajout du stuff
    updatedAt?: string | null; // Date de dernière modification
};

export type GalleryPage = {
    builds: GalleryBuild[];
    total: number;
    hasMore: boolean;
    nextPage: number | null;
    isDiscordShareConfigured: boolean;
};

export type GallerySkin = {
    id: string;
    name: string;
    url: string;
    provider: string;
    thumbnailUrl: string | null;
    equipment?: any;
    colors?: any;
    metadata: any;
    author: {
        id: string;
        name: string;
        image: string | null;
    };
    votesCount: number;
    hasVoted: boolean;
    createdAt: Date;
};

export type GallerySkinPage = {
    skins: GallerySkin[];
    total: number;
    hasMore: boolean;
    nextPage: number | null;
    isDiscordShareConfigured: boolean;
};

type ActionResponse<T = null> = {
    success: boolean;
    error?: string;
    data?: T;
};

/**
 * Paginated stuff gallery — scales to hundreds of builds.
 * Returns PAGE_SIZE (24) builds per page, filtered server-side.
 * Security: auth + canViewStuffGallery check enforced.
 */
export async function getStuffGalleryPage(
    guildId: string,
    page: number = 1,
    searchQuery?: string,
    tag?: string,
    classId?: string,
    sortBy?: "newest" | "votes",
    source?: "dofusbook"
): Promise<ActionResponse<GalleryPage>> {
    if (!guildId) return { success: false, error: "ID de guilde requis" };

    const user = await getUserContext(guildId);
    if (!user.isAuthenticated || !user.canViewStuffGallery) {
        return { success: false, error: "Accès refusé" };
    }

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true, name: true, stuffGalleryChannelId: true }
        });
        if (!guildConfig) return { success: false, error: "Guilde introuvable" };

        const [profiles, allVotes] = await Promise.all([
            // Optimization: Fetch profiles and filter in memory
            db.userProfile.findMany({
                where: {
                    guildId: guildConfig.id,
                    status: "ACTIVE",
                },
                select: {
                    id: true,
                    pseudoDofus: true,
                    discordNickname: true,
                    dofusBookLinks: true,
                    user: { select: { name: true, image: true } }
                },
            }),
            // Fetch all votes for this guild
            db.buildVote.findMany({
                where: { guildId: guildConfig.id },
                select: { buildId: true, userId: true }
            })
        ]);



        // Create vote maps for quick access
        const votesCountMap = new Map<string, number>();
        const userVotesSet = new Set<string>(); // Set of buildIds voted by current user

        allVotes.forEach((vote: { buildId: string, userId: string }) => {
            votesCountMap.set(vote.buildId, (votesCountMap.get(vote.buildId) || 0) + 1);
            if (user.id && vote.userId === user.id) {
                userVotesSet.add(vote.buildId);
            }
        });

        // Flatten all builds from all profiles into one list
        let allBuilds: GalleryBuild[] = [];
        profiles.forEach((profile: any) => {
            // Safety check: ensure links is actually an array
            if (!profile.dofusBookLinks || !Array.isArray(profile.dofusBookLinks)) {
                return;
            }

            const links = profile.dofusBookLinks as any[];
            links.forEach((link, idx) => {
                if (link?.url && link?.name) {
                    const isDofusRoom = /dofusroom\.com/.test(link.url);
                    if (isDofusRoom) return; // Skip DofusRoom links completely

                    const buildId = link.id || `${profile.id}-${idx}`; // Prefer real id if exists
                    const buildSource = "dofusbook" as const;
                    
                    const buildIdMatch = link.url.match(/(?:equipement\/(?:[a-z]+\/)?([\d]+)|d-bk\.net\/(?:fr\/)?d\/([a-zA-Z0-9]+))/i);
                    const parsedId = buildIdMatch ? (buildIdMatch[1] || buildIdMatch[2]) : null;
                    const numericMatch = parsedId?.match(/^(\d+)/);
                    const numericId = numericMatch ? numericMatch[1] : parsedId;
                    const thumbnail = link.previewData?.thumbnail || (numericId ? `https://static.dofusbook.net/equipement/render/${numericId}.png` : null);

                    allBuilds.push({
                        id: buildId,
                        name: link.name,
                        url: link.url,
                        tags: link.tags || [],
                        classId: link.classId,
                        source: buildSource,
                        previewData: {
                            ...link.previewData,
                            thumbnail
                        },
                        author: {
                            id: profile.id,
                            name: profile.pseudoDofus || profile.discordNickname || profile.user.name || "Membre",
                            image: profile.user.image
                        },
                        votesCount: votesCountMap.get(buildId) || 0,
                        hasVoted: userVotesSet.has(buildId),
                        createdAt: link.createdAt || null,
                        updatedAt: link.updatedAt || null
                    });
                }
            });
        });



        // Apply sort
        if (sortBy === "votes") {
            allBuilds = allBuilds.sort((a, b) => b.votesCount - a.votesCount);
        } else {
            // Default: newest first (by updatedAt or createdAt timestamp if available)
            allBuilds = allBuilds.sort((a, b) => {
                const dateA = a.updatedAt || a.createdAt;
                const dateB = b.updatedAt || b.createdAt;
                if (dateA && dateB) {
                    return new Date(dateB).getTime() - new Date(dateA).getTime();
                }
                if (dateA) return -1;
                if (dateB) return 1;
                return 0;
            });
        }

        // Apply search filter server-side
        if (searchQuery) {
            const q = searchQuery.toLowerCase();
            allBuilds = allBuilds.filter(b =>
                b.name.toLowerCase().includes(q) ||
                b.author.name.toLowerCase().includes(q)
            );
        }

        // Apply tag filter server-side
        if (tag) {
            allBuilds = allBuilds.filter(b => b.tags?.includes(tag));
        }

        // Apply class filter server-side
        if (classId) {
            allBuilds = allBuilds.filter(b => String(b.classId) === classId);
        }

        // Apply source filter server-side
        if (source) {
            allBuilds = allBuilds.filter(b => b.source === source);
        }

        const total = allBuilds.length;
        const offset = (page - 1) * PAGE_SIZE;
        const pageBuilds = allBuilds.slice(offset, offset + PAGE_SIZE);
        const hasMore = offset + PAGE_SIZE < total;

        return {
            success: true,
            data: {
                builds: pageBuilds,
                total,
                hasMore,
                nextPage: hasMore ? page + 1 : null,
                isDiscordShareConfigured: !!guildConfig.stuffGalleryChannelId
            }
        };
    } catch (error: any) {
        logger.error("Get Stuff Gallery Page Error:", { error });
        return { success: false, error: "Erreur serveur" };
    }
}

/**
 * Force re-fetch of Dofusbook metadata for a specific build in the gallery.
 * This updates the previewData in the user's profile.
 */
export async function refreshBuildMetadata(
    guildId: string,
    profileId: string,
    buildUrl: string
): Promise<ActionResponse> {
    if (!guildId || !profileId || !buildUrl) return { success: false, error: "Paramètres manquants" };

    const user = await getUserContext(guildId);
    if (!user.isAuthenticated) return { success: false, error: "Non authentifié" };

    try {
        const { revalidatePath } = await import("next/cache");
        const isDofusRoom = /dofusroom\.com/.test(buildUrl);
        if (isDofusRoom) {
            return { success: false, error: "L'intégration DofusRoom a été supprimée." };
        }
        let previewData = null;

        const { getDofusbookPreview } = await import("./dofusbook-actions");
        const res = await getDofusbookPreview(buildUrl, true);
        if (!res.success || !res.data) {
            return { success: false, error: res.error || "Impossible de récupérer les données" };
        }
        previewData = res.data;

        // 2. Update user profile dofusBookLinks
        const profile = await db.userProfile.findUnique({
            where: { id: profileId },
            select: { id: true, dofusBookLinks: true }
        });

        if (!profile) return { success: false, error: "Profil introuvable" };

        const links = (profile.dofusBookLinks as any[]) || [];
        const updatedLinks = links.map(link => {
            if (link.url === buildUrl) {
                return { ...link, previewData, source: "dofusbook" as const };
            }
            return link;
        });

        await db.userProfile.update({
            where: { id: profileId },
            data: { dofusBookLinks: updatedLinks as any }
        });

        // 3. Revalidate
        revalidatePath(`/dashboard/${guildId}/galerie-stuff`);
        revalidatePath(`/dashboard/${guildId}/members/${profileId}`);

        return { success: true };
    } catch (error) {
        logger.error("Refresh Build Metadata Error:", { error });
        return { success: false, error: "Erreur serveur lors du rafraîchissement" };
    }
}

/**
 * Paginated skin gallery.
 * Returns PAGE_SIZE (24) skins per page, filtered server-side.
 */
export async function getSkinGalleryPage(
    guildId: string,
    page: number = 1,
    searchQuery?: string,
    classFilter?: string,
    genderFilter?: string,
    sortBy: "newest" | "votes" = "newest"
): Promise<ActionResponse<GallerySkinPage>> {
    if (!guildId) return { success: false, error: "ID de guilde requis" };

    const user = await getUserContext(guildId);
    if (!user.isAuthenticated || !user.canViewStuffGallery) {
        return { success: false, error: "Accès refusé" };
    }

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true, skinGalleryChannelId: true }
        });
        if (!guildConfig) return { success: false, error: "Guilde introuvable" };

        const offset = (page - 1) * PAGE_SIZE;

        // Build filtering conditions
        const where: Prisma.UserSkinWhereInput = {
            profile: {
                guildId: guildConfig.id,
                status: "ACTIVE"
            }
        };

        if (searchQuery) {
            where.OR = [
                { name: { contains: searchQuery, mode: 'insensitive' } },
                { profile: { pseudoDofus: { contains: searchQuery, mode: 'insensitive' } } },
                { profile: { discordNickname: { contains: searchQuery, mode: 'insensitive' } } }
            ];
        }

        // Advanced filter for Barbofus skins (metadata-based)
        if (classFilter || genderFilter) {
            // Note: Handle legacy values (Homme, Femme, symbols) for robust filtering
            const genderValues = genderFilter === "M" 
                ? ["M", "Homme", "♂", "Mâle"]
                : ["F", "Femme", "♀", "Femelle"];

            const conditions: Prisma.UserSkinWhereInput[] = [];

            if (classFilter) {
                const targetClass = DOFUS_CLASSES.find(c => c.icon.includes(`/${classFilter}.png`));
                const classValues = [classFilter];
                if (targetClass) classValues.push(targetClass.name);

                conditions.push({ 
                    OR: classValues.map(v => ({ metadata: { path: ["class"], equals: v } }))
                });
            }

            if (genderFilter) {
                conditions.push({ 
                    OR: genderValues.map(v => ({ metadata: { path: ["gender"], equals: v } }))
                });
            }

            if (conditions.length > 0) {
                where.AND = conditions;
            }
        }


        const [skins, total] = await Promise.all([
            db.userSkin.findMany({
                where,
                include: {
                    profile: {
                        select: {
                            id: true,
                            pseudoDofus: true,
                            discordNickname: true,
                            user: { select: { name: true, image: true } }
                        }
                    },
                    _count: {
                        select: { votes: true }
                    },
                    votes: {
                        where: { userId: user.id },
                        take: 1
                    }
                },
                orderBy: sortBy === "votes" ? { votes: { _count: 'desc' } } : { createdAt: 'desc' },
                skip: offset,
                take: PAGE_SIZE
            }),
            db.userSkin.count({ where })
        ]);

        const mappedSkins: GallerySkin[] = skins.map(s => ({
            id: s.id,
            name: s.name,
            url: s.url,
            provider: s.provider,
            thumbnailUrl: s.thumbnailUrl,
            equipment: s.equipment,
            colors: s.colors,
            metadata: s.metadata,
            author: {
                id: s.profile.id,
                name: s.profile.pseudoDofus || s.profile.discordNickname || s.profile.user.name || "Membre",
                image: s.profile.user.image
            },
            votesCount: s._count.votes,
            hasVoted: s.votes.length > 0,
            createdAt: s.createdAt
        }));

        const hasMore = offset + PAGE_SIZE < total;

        return {
            success: true,
            data: {
                skins: mappedSkins,
                total,
                hasMore,
                nextPage: hasMore ? page + 1 : null,
                isDiscordShareConfigured: !!guildConfig.skinGalleryChannelId
            }
        };
    } catch (error) {
        logger.error("Get Skin Gallery Page Error:", { error });
        return { success: false, error: "Erreur serveur" };
    }
}

/**
 * Toggle vote for a skin in the gallery.
 */
export async function toggleSkinVote(guildId: string, skinId: string): Promise<ActionResponse<{ voted: boolean }>> {
    if (!guildId || !skinId) return { success: false, error: "Paramètres invalides" };

    const user = await getUserContext(guildId);
    if (!user.isAuthenticated || !user.id) {
        return { success: false, error: "Vous devez être connecté pour voter" };
    }

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true }
        });
        
        if (!guildConfig) return { success: false, error: "Guilde introuvable" };

        const existingVote = await db.skinVote.findUnique({
            where: {
                skinId_userId: {
                    skinId,
                    userId: user.id
                }
            }
        });

        if (existingVote) {
            await db.skinVote.delete({ where: { id: existingVote.id } });
            return { success: true, data: { voted: false } };
        } else {
            await db.skinVote.create({
                data: {
                    skinId,
                    userId: user.id,
                    guildId: guildConfig.id
                }
            });
            return { success: true, data: { voted: true } };
        }
    } catch (error) {
        logger.error("Toggle Skin Vote Error:", { error });
        return { success: false, error: "Erreur serveur lors du vote" };
    }
}

/**
 * Share a gallery item (Stuff or Skin) to Discord.
 * Enforces rate limiting and handles Forum vs Text channels.
 */
export async function shareGalleryItemOnDiscord(
    guildId: string,
    itemId: string,
    type: "STUFF" | "SKIN",
    authorProfileId?: string
): Promise<ActionResponse> {
    if (!guildId || !itemId) return { success: false, error: "Paramètres invalides" };

    const user = await getUserContext(guildId);
    if (!user.isAuthenticated || !user.id || !user.profileId) {
        return { success: false, error: "Vous devez être connecté pour partager" };
    }

    let embedImage: string | undefined = undefined;
    try {
        const { fetchChannel, sendChannelMessage, createForumPost } = await import("@/server/discord");

        // 1. Fetch SHARER Profile and check Rate Limit
        const sharerProfile = await db.userProfile.findUnique({
            where: { id: user.profileId },
            select: { id: true, lastGalleryShareAt: true, pseudoDofus: true, discordNickname: true }
        });

        if (!sharerProfile) return { success: false, error: "Profil introuvable" };

        const COOLDOWN_MS = 2 * 60 * 1000; // 2 minutes
        if (sharerProfile.lastGalleryShareAt) {
            const elapsed = Date.now() - sharerProfile.lastGalleryShareAt.getTime();
            if (elapsed < COOLDOWN_MS) {
                const remainingSeconds = Math.ceil((COOLDOWN_MS - elapsed) / 1000);
                const minutes = Math.floor(remainingSeconds / 60);
                const seconds = remainingSeconds % 60;
                return { 
                    success: false, 
                    error: `Anti-spam : veuillez patienter ${minutes > 0 ? `${minutes}m ` : ""}${seconds}s.` 
                };
            }
        }

        // 2. Fetch Guild Config for Channels
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { skinGalleryChannelId: true, stuffGalleryChannelId: true, id: true }
        });

        const channelId = type === "STUFF" ? guildConfig?.stuffGalleryChannelId : guildConfig?.skinGalleryChannelId;
        if (!channelId) return { success: false, error: "Le salon de partage n'est pas configuré pour cette guilde." };

        // 3. Fetch Item Details
        let embedTitle = "";
        let embedDescription = "";
        let embedThumbnail = "";
        let embedUrl = "";
        const fields: any[] = [];
        let itemName = "";
        let authorName = "Un membre";

        if (type === "STUFF") {
            // Find build globally in the guild if authorProfileId is known
            let build = null;
            if (authorProfileId) {
                const profile = await db.userProfile.findUnique({
                    where: { id: authorProfileId },
                    select: { dofusBookLinks: true, pseudoDofus: true, discordNickname: true }
                });
                build = (profile?.dofusBookLinks as any[])?.find(b => b.id === itemId);
                authorName = profile?.pseudoDofus || profile?.discordNickname || authorName;
            } else {
                // Fallback search in all guild profiles (Active)
                const profiles = await db.userProfile.findMany({
                    where: { guildId: guildConfig?.id, status: 'ACTIVE' },
                    select: { id: true, dofusBookLinks: true, pseudoDofus: true, discordNickname: true }
                });
                for (const p of profiles) {
                    const b = (p.dofusBookLinks as any[])?.find(x => x.id === itemId);
                    if (b) {
                        build = b;
                        authorName = p.pseudoDofus || p.discordNickname || authorName;
                        break;
                    }
                }
            }
            if (!build) return { success: false, error: "Build introuvable" };

            itemName = build.name;
            embedTitle = `🛡️ Build : ${build.name}`;
            embedUrl = build.url;
            embedDescription = `Partagé par **${authorName}** via SigilOS.`;
            
            // Premium UI 2026: Large image for the build + Site icon as thumbnail
            const rawBuildImg = build.previewData?.thumbnail?.trim();
            if (rawBuildImg) {
                try {
                    embedImage = new URL(rawBuildImg).href;
                } catch {
                    embedImage = undefined;
                }
            } else {
                embedImage = undefined;
            }
            embedThumbnail = "https://sigilos.fr/assets/ui/dofusbook.png";

            
            if (build.classId) {
                fields.push({ name: "Classe", value: String(build.classId).charAt(0).toUpperCase() + String(build.classId).slice(1), inline: true });
            }
            if (build.tags && build.tags.length > 0) {
                fields.push({ name: "Tags", value: build.tags.join(", "), inline: true });
            }
        } else {
            // Fetch skin from DB with Guild isolation
            const skin = await db.userSkin.findFirst({
                where: { 
                    id: itemId,
                    profile: { guildId: guildConfig?.id }
                },
                include: { profile: { select: { pseudoDofus: true, discordNickname: true } } }
            });
            if (!skin) return { success: false, error: "Skin introuvable" };

            itemName = skin.name;
            authorName = skin.profile.pseudoDofus || skin.profile.discordNickname || authorName;
            embedTitle = `✨ Skin : ${skin.name}`;
            embedUrl = skin.url;
            embedDescription = `Look partagé par **${authorName}**.`;
            
            // Premium UI 2026: Large image for the skin + Provider icon as thumbnail
            let rawImage = skin.thumbnailUrl?.trim();
            if (rawImage) {
                if (rawImage.startsWith("//")) {
                    rawImage = `https:${rawImage}`;
                } else if (!rawImage.startsWith("http://") && !rawImage.startsWith("https://")) {
                    rawImage = `https://${rawImage.replace(/^\/+/, '')}`;
                }
                try {
                    const parsedUrl = new URL(rawImage);
                    embedImage = parsedUrl.href;
                } catch {
                    embedImage = undefined;
                }
            } else {
                embedImage = undefined;
            }


            embedThumbnail = (skin.provider === "BARBOFUS" ? 
                "https://sigilos.fr/assets/ui/barbofus.png" : 
                "https://sigilos.fr/assets/ui/dofusskinmanga.png"
            );
            
            if ((skin.metadata as any)?.class) {
                const classData = DOFUS_CLASSES.find(c => {
                    const match = c.icon.match(/\/(\d+)\.png$/);
                    return match && match[1] === String((skin.metadata as any).class);
                });
                fields.push({ name: "Classe", value: classData ? classData.name : String((skin.metadata as any).class), inline: true });
            }
            if ((skin.metadata as any)?.gender) {
                fields.push({ name: "Sexe", value: String((skin.metadata as any).gender), inline: true });
            }
            if (Array.isArray(skin.equipment) && skin.equipment.length > 0) {
                const itemsList = skin.equipment.map((eq: any) => `• ${eq.name}${eq.type ? ` *(${eq.type})*` : ''}`).join("\n");
                if (itemsList.length <= 1024) {
                    fields.push({ name: "Équipements", value: itemsList, inline: false });
                }
            }

        }

        // 4. Determine Channel Type and Send
        const channelInfo = await fetchChannel(channelId);
        if (!channelInfo) return { success: false, error: "Impossible de joindre le salon Discord." };

        const embedOptions = {
            embedTitle,
            embedDescription,
            embedUrl,
            embedThumbnail,
            embedImage, // Large image added
            embedColor: type === "STUFF" ? 0x10b981 : 0xec4899,
            fields,
            embedFooter: `Partagé depuis SigilOS · ${new Date().toLocaleDateString()}`
        };

        let shareResult: any = null;
        try {
            if (channelInfo.type === 15) {
                // FORUM
                shareResult = await createForumPost(channelId, itemName, `Nouveau partage de ${type.toLowerCase()}`, embedOptions);
            } else {
                // TEXT CHANNEL
                shareResult = await sendChannelMessage(channelId, "", embedOptions);
            }
            logger.info(`[Gallery Share] Success: ${type} ${itemId} shared on channel ${channelId}. Result ID: ${channelInfo.type === 15 ? shareResult?.messageId : shareResult}`);
        } catch (discordError) {
            logger.error("[Gallery Share] Discord API Error:", { discordError });
            return { success: false, error: "Le salon Discord a refusé le message ou est mal configuré." };
        }

        // 5. Update last share time and SAVE discordMessageId
        const messageId = channelInfo.type === 15 ? shareResult?.messageId : shareResult;
        
        // Safety check to avoid Prisma errors if messageId is somehow weird
        if (!messageId || typeof messageId !== 'string') {
            logger.warn("[Gallery Share] No valid messageId returned from Discord, skipped DB link save.");
        }
        
        if (type === "STUFF") {
            // Find and update the JSON entry
            const profile = await db.userProfile.findUnique({
                where: { id: user.profileId },
                select: { dofusBookLinks: true }
            });
            const links = (profile?.dofusBookLinks as any[]) || [];
            const updatedLinks = links.map(l => l.id === itemId ? { ...l, discordMessageId: messageId } : l);
            
            await db.userProfile.update({
                where: { id: user.profileId },
                data: { 
                    dofusBookLinks: updatedLinks as any,
                    lastGalleryShareAt: new Date() 
                }
            });
        } else {
            // Update the column in UserSkin
            await db.userSkin.update({
                where: { id: itemId },
                data: { discordMessageId: messageId }
            });
            
            await db.userProfile.update({
                where: { id: user.profileId },
                data: { lastGalleryShareAt: new Date() }
            });
        }

        revalidatePath(`/dashboard/${guildId}/galerie-stuff`);

        return { success: true };
    } catch (error) {
        logger.error("Share Gallery Item Error:", { error });
        return { success: false, error: "Erreur lors du partage sur Discord" };
    }
}

/**
 * Sync deletion from Discord to Dashboard
 * Triggered by MESSAGE_DELETE webhook
 */
export async function handleDiscordGalleryDelete(discordGuildId: string, discordMessageId: string): Promise<void> {
    try {
        // 1. Try to find and delete in UserSkin
        const skin = await db.userSkin.findFirst({
            where: { discordMessageId },
            select: { id: true }
        });

        if (skin) {
            await db.userSkin.delete({ where: { id: skin.id } });
            logger.info(`[Gallery Sync] Deleted skin ${skin.id} after Discord message deletion`);
            revalidatePath(`/dashboard/${discordGuildId}/galerie-stuff`);
            return;
        }

        // 2. Try to find in UserProfile (JSON dofusBookLinks)
        // Find the guild internal ID first
        const guild = await db.guildConfig.findUnique({
            where: { discordGuildId },
            select: { id: true }
        });
        if (!guild) return;

        // Fetch all active profiles in the guild
        const profiles = await db.userProfile.findMany({
            where: { guildId: guild.id },
            select: { id: true, dofusBookLinks: true }
        });

        for (const profile of profiles) {
            const links = (profile.dofusBookLinks as any[]) || [];
            const found = links.find(l => l.discordMessageId === discordMessageId);
            if (found) {
                const updatedLinks = links.filter(l => l.discordMessageId !== discordMessageId);
                await db.userProfile.update({
                    where: { id: profile.id },
                    data: { dofusBookLinks: updatedLinks as any }
                });
                logger.info(`[Gallery Sync] Removed stuff link from profile ${profile.id} after Discord message deletion`);
                revalidatePath(`/dashboard/${discordGuildId}/galerie-stuff`);
                return;
            }
        }
    } catch (error) {
        logger.error("[Gallery Sync] Deletion sync error:", { error });
    }
}

