        // Update dungeon and sync achievements
        const dungeon = await db.$transaction(async (tx) => {
            // Update dungeon basic info
            const updated = await tx.dungeon.update({
                where: { id },
                data: {
                    ...dungeonData,
                    dpnlUrl: dungeonData.dpnlUrl || null,
