/**
 * Export all game data as JSON for cross-environment sync.
 * Includes: zones, families (with monsters), challenges, dungeons (with achievements).
 * IDs are exported for reference but the import uses name-based matching,
 * so the same export can be imported into any environment safely.
 */
export async function exportGameData(): Promise<ActionResponse<any>> {
    const userId = await requireSuperAdmin();
    if (!userId) return { success: false, error: "Accès refusé" };

    try {
        const [zones, families, challenges, dungeons] = await Promise.all([
            db.zone.findMany({ orderBy: { name: 'asc' } }),
            db.monsterFamily.findMany({
                include: {
                    monsters: true,
                    zones: { select: { id: true, name: true } }
                },
                orderBy: { name: 'asc' }
            }),
            db.challenge.findMany({ orderBy: { name: 'asc' } }),
            db.dungeon.findMany({
                include: {
                    achievements: {
                        include: { challenge: { select: { name: true, slug: true } } }
                    }
                },
                orderBy: { level: 'asc' }
            }),
        ]);

        const exportData = {
            version: "3.0",
            exportedAt: new Date().toISOString(),
            exportedBy: userId,
            data: {
                zones,
                families: families.map(f => ({
                    ...f,
                    zoneNames: f.zones?.map(z => z.name) || [],
                    zones: undefined,
                })),
                challenges,
                dungeons: dungeons.map(d => ({
                    ...d,
                    achievements: d.achievements.map(a => ({
                        ...a,
                        // Include challenge name for cross-env resolution
                        challengeName: a.challenge?.name || null,
                        challengeSlug: a.challenge?.slug || null,
                        challenge: undefined,
                    })),
                })),
            }
        };

        return { success: true, data: exportData };
    } catch (error) {
        console.error('[exportGameData] Error:', error);
        return { success: false, error: 'Erreur lors de l\'export' };
    }
}

/**
 * Export game data directly to Git seed file
 * Safe for use in development environment only
 */
export async function exportGameDataToGit(): Promise<ActionResponse<string>> {
    const userId = await requireSuperAdmin();
    if (!userId) return { success: false, error: "Accès refusé" };

    // Security: Only allow in development
    if (process.env.NODE_ENV === 'production') {
        return { success: false, error: "Cette fonction n'est disponible qu'en développement" };
    }

    try {
        const result = await exportGameData();
        if (!result.success || !result.data) {
            return { success: false, error: result.error || 'Erreur export' };
        }

        // Write to seed file
        const seedFilePath = join(process.cwd(), 'prisma', 'seed-data', 'game-data.json');
        writeFileSync(seedFilePath, JSON.stringify(result.data, null, 2), 'utf-8');

        const d = result.data.data;
        return {
            success: true,
            data: `Export réussi ! Fichier sauvegardé dans prisma/seed-data/game-data.json\n\n` +
                `Zones: ${d.zones?.length || 0} | Familles: ${d.families?.length || 0} | ` +
                `Challenges: ${d.challenges?.length || 0} | Donjons: ${d.dungeons?.length || 0}\n\n` +
                `💡 Commit ce fichier dans Git pour versionner tes données !`
        };
    } catch (error: any) {
        console.error('[exportGameDataToGit] Error:', error);
        return { success: false, error: `Erreur: ${error.message}` };
    }
}

/**
 * Import game data from JSON export. Handles cross-environment ID differences.
 * 
 * Strategy:
 *  - All entities are matched by their NATURAL KEY (name, name+bossName, etc.)
 *  - IDs from the source are remapped to the target DB's IDs
 *  - Cross-references (e.g. dungeon→challenge achievements) use remapped IDs
 *  - Entire import runs in a transaction for atomicity (safe for hot imports)
 *  - Supports both v2.0 and v3.0 export formats
 */
export async function importGameData(jsonData: string): Promise<ActionResponse<string>> {
    const userId = await requireSuperAdmin();
    if (!userId) return { success: false, error: "Accès refusé" };

    try {
        const parsed = JSON.parse(jsonData);

        if (!parsed.version || !parsed.data) {
            return { success: false, error: 'Format de fichier invalide' };
        }

        const stats = { zones: 0, families: 0, challenges: 0, dungeons: 0, achievements: 0, skipped: 0 };
        const warnings: string[] = [];

        await db.$transaction(async (tx) => {
            // ============================
            // PHASE 1: Import Zones
            // ============================
            const zoneIdMap = new Map<string, string>(); // oldId → newId

            if (parsed.data.zones) {
                for (const zone of parsed.data.zones) {
                    const existing = await tx.zone.findUnique({ where: { name: zone.name } });

                    if (existing) {
                        await tx.zone.update({
                            where: { id: existing.id },
                            data: {
                                level: zone.level,
                                dpnlUrl: zone.dpnlUrl || null,
                            }
                        });
                        zoneIdMap.set(zone.id, existing.id);
                    } else {
                        const created = await tx.zone.create({
                            data: {
                                name: zone.name,
                                level: zone.level,
                                dpnlUrl: zone.dpnlUrl || null,
                            }
                        });
                        zoneIdMap.set(zone.id, created.id);
                    }
                    stats.zones++;
                }
            }

            // ============================
            // PHASE 2: Import Challenges
            // ============================
            const challengeIdMap = new Map<string, string>(); // oldId → newId

            if (parsed.data.challenges) {
                for (const challenge of parsed.data.challenges) {
                    // Find by name (natural unique key) — slug as fallback
                    const existing = await tx.challenge.findFirst({
                        where: {
                            OR: [
                                { name: challenge.name },
                                ...(challenge.slug ? [{ slug: challenge.slug }] : []),
                            ]
                        }
                    });

                    const slug = challenge.slug || challenge.name.toLowerCase()
                        .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
                        .replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

                    if (existing) {
                        await tx.challenge.update({
                            where: { id: existing.id },
                            data: {
                                description: challenge.description,
                                iconUrl: challenge.iconUrl,
                                conditions: challenge.conditions || undefined,
                                slug: slug,
                            }
                        });
                        challengeIdMap.set(challenge.id, existing.id);
                    } else {
                        const created = await tx.challenge.create({
                            data: {
                                name: challenge.name,
                                slug: slug,
                                description: challenge.description,
                                iconUrl: challenge.iconUrl,
                                conditions: challenge.conditions || undefined,
                            }
                        });
                        challengeIdMap.set(challenge.id, created.id);
                    }
                    stats.challenges++;
                }
            }

            // ============================
            // PHASE 3: Import Families
            // ============================
            const familyIdMap = new Map<string, string>(); // oldId → newId

            if (parsed.data.families) {
                for (const family of parsed.data.families) {
                    const trimmedName = family.name.trim();
                    const existing = await tx.monsterFamily.findFirst({
                        where: { name: { equals: trimmedName, mode: 'insensitive' } }
                    });

                    if (existing) {
                        await tx.monsterFamily.update({
                            where: { id: existing.id },
                            data: {
                                level: family.level || null,
                                description: family.description || null,
                                imageUrl: family.imageUrl || null,
                            }
                        });
                        familyIdMap.set(family.id, existing.id);
                    } else {
                        const created = await tx.monsterFamily.create({
                            data: {
                                name: trimmedName,
                                level: family.level || null,
                                description: family.description || null,
                                imageUrl: family.imageUrl || null,
                            }
                        });
                        familyIdMap.set(family.id, created.id);
                    }

                    // Link to zones (v3.0 format: zoneNames)
                    const resolvedFamilyId = familyIdMap.get(family.id);
                    if (resolvedFamilyId && family.zoneNames && Array.isArray(family.zoneNames)) {
                        const zoneRecords = await tx.zone.findMany({
                            where: { name: { in: family.zoneNames } },
                            select: { id: true }
                        });
                        if (zoneRecords.length > 0) {
                            await tx.monsterFamily.update({
                                where: { id: resolvedFamilyId },
                                data: { zones: { set: zoneRecords.map(z => ({ id: z.id })) } }
                            });
                        }
                    }

                    stats.families++;
                }
            }

            // ============================
            // PHASE 4: Import Dungeons + Achievements
            // ============================
            if (parsed.data.dungeons) {
                for (const dungeon of parsed.data.dungeons) {
                    // Find by composite natural key: name + bossName
                    const existing = await tx.dungeon.findFirst({
                        where: { name: dungeon.name, bossName: dungeon.bossName }
                    });

                    let dungeonId: string;

                    if (existing) {
                        await tx.dungeon.update({
                            where: { id: existing.id },
                            data: {
                                level: dungeon.level,
                                dpnlUrl: dungeon.dpnlUrl || null,
                                imageUrl: dungeon.imageUrl || null,
                                isExpedition: dungeon.isExpedition ?? false,
                                expeditionModes: dungeon.expeditionModes || null,
                                expeditionMechanics: dungeon.expeditionMechanics || null,
                            }
                        });
                        dungeonId = existing.id;
                    } else {
                        const created = await tx.dungeon.create({
                            data: {
                                name: dungeon.name,
                                bossName: dungeon.bossName,
                                level: dungeon.level,
                                dpnlUrl: dungeon.dpnlUrl || null,
                                imageUrl: dungeon.imageUrl || null,
                                isExpedition: dungeon.isExpedition ?? false,
                                expeditionModes: dungeon.expeditionModes || null,
                                expeditionMechanics: dungeon.expeditionMechanics || null,
                            }
                        });
                        dungeonId = created.id;
                    }

                    // Import achievements with ID remapping
                    if (dungeon.achievements && Array.isArray(dungeon.achievements)) {
                        for (const ach of dungeon.achievements) {
                            // Resolve challengeId: try ID map first, then name/slug lookup
                            let resolvedChallengeId = challengeIdMap.get(ach.challengeId);

                            if (!resolvedChallengeId) {
                                // v3.0: use embedded challengeName/challengeSlug
                                // v2.0: lookup directly by old challengeId
                                const challengeLookup = await tx.challenge.findFirst({
                                    where: {
                                        OR: [
                                            ...(ach.challengeName ? [{ name: ach.challengeName }] : []),
                                            ...(ach.challengeSlug ? [{ slug: ach.challengeSlug }] : []),
                                            { id: ach.challengeId }, // last resort: same ID
                                        ]
                                    }
                                });

                                if (challengeLookup) {
                                    resolvedChallengeId = challengeLookup.id;
                                } else {
                                    warnings.push(`⚠️ Challenge introuvable pour succès donjon "${dungeon.name}" (challengeId: ${ach.challengeId})`);
                                    stats.skipped++;
                                    continue;
                                }
                            }

                            // Upsert the achievement
                            const existingAch = await tx.dungeonAchievement.findUnique({
                                where: {
                                    dungeonId_challengeId: {
                                        dungeonId: dungeonId,
                                        challengeId: resolvedChallengeId
                                    }
                                }
                            });

                            if (existingAch) {
                                await tx.dungeonAchievement.update({
                                    where: { id: existingAch.id },
                                    data: { points: ach.points || 10 }
                                });
                            } else {
                                await tx.dungeonAchievement.create({
                                    data: {
                                        dungeonId: dungeonId,
                                        challengeId: resolvedChallengeId,
                                        points: ach.points || 10,
                                    }
                                });
                            }
                            stats.achievements++;
                        }
                    }

                    stats.dungeons++;
                }
            }
        }, { timeout: 60000 }); // 60s timeout for large imports

        revalidatePath('/god/game-data');
        revalidatePath('/admin/missions');

        const summary = [
            `✅ Import terminé avec succès !`,
            ``,
            `📊 Résumé :`,
            stats.zones > 0 ? `  • Zones : ${stats.zones}` : null,
            `  • Familles : ${stats.families}`,
            `  • Challenges : ${stats.challenges}`,
            `  • Donjons : ${stats.dungeons}`,
            stats.achievements > 0 ? `  • Succès donjons : ${stats.achievements}` : null,
            stats.skipped > 0 ? `  • ⚠️ Ignorés : ${stats.skipped}` : null,
            ...warnings,
        ].filter(Boolean).join('\n');

        return { success: true, data: summary };
    } catch (error: any) {
        console.error('[importGameData] Error:', error);

        // Provide user-friendly error messages
        if (error.code === 'P2002') {
            const field = error.meta?.target?.join(', ') || 'unknown';
            return { success: false, error: `Conflit de données : le champ (${field}) existe déjà avec une valeur différente. Vérifiez les données du fichier.` };
        }

        return { success: false, error: `Erreur lors de l'import: ${error.message}` };
    }
}

"use server";

import { db } from "@/lib/prisma";
import { getUserContext } from "@/server/actions/user-actions";

const DOFUSDB_API = "https://api.dofusdb.fr";

export type QuestDelta = {
    dofusDbId: number;
    name: string;
    levelMin: number | null;
    levelMax: number | null;
    categoryId: number;
    type: "NEW" | "MODIFIED";
    localName?: string;
};

export async function checkDofusDbDeltas(guildId: string) {
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated || !ctx.isAdmin) {
        return { success: false, error: "Non autorisé" };
    }

    try {
        // 1. Fetch DofusDB total quests count to see if we need deep checking
        const countRes = await fetch(`${DOFUSDB_API}/quests?$limit=1`);
        const countJson = await countRes.json();
        const totalRemote = countJson.total;

        // 2. Load local quests that have a dofusDbId
        const localQuests = await db.gameQuest.findMany({
            where: { dofusDbId: { not: null } },
            select: { dofusDbId: true, name: true, levelMin: true, levelMax: true }
        });

        const localMap = new Map();
        for (const q of localQuests) {
            localMap.set(q.dofusDbId, q);
        }

        // 3. To find deltas, we fetch all quests lightly.
        // Doing this in chunks to avoid timeout on Vercel
        const limit = 500;
        let skip = 0;
        const deltas: QuestDelta[] = [];
        let totalProcessed = 0;

        while (skip < totalRemote) {
            const res = await fetch(`${DOFUSDB_API}/quests?$limit=${limit}&$skip=${skip}&$select=id,name,levelMin,levelMax,categoryId`);
            const json = await res.json();

            if (!json.data || json.data.length === 0) break;

            for (const remoteQuest of json.data) {
                const id = remoteQuest.id;
                const remoteName = remoteQuest.name?.fr;
                if (!remoteName) continue;

                const localQuest = localMap.get(id);

                if (!localQuest) {
                    // New quest!
                    deltas.push({
                        dofusDbId: id,
                        name: remoteName,
                        levelMin: remoteQuest.levelMin ?? null,
                        levelMax: remoteQuest.levelMax ?? null,
                        categoryId: remoteQuest.categoryId,
                        type: "NEW"
                    });
                } else {
                    // Check for modification (name or levels)
                    // Note: DofusDB name might have been deduplicated locally, so we check if local name starts with remote name or is exact.
                    const nameChanged = localQuest.name !== remoteName && !localQuest.name.startsWith(remoteName + " (#");
                    const levelMinChanged = localQuest.levelMin !== remoteQuest.levelMin;
                    const levelMaxChanged = localQuest.levelMax !== remoteQuest.levelMax;

                    if (nameChanged || levelMinChanged || levelMaxChanged) {
                        deltas.push({
                            dofusDbId: id,
                            name: remoteName,
                            localName: localQuest.name,
                            levelMin: remoteQuest.levelMin ?? null,
                            levelMax: remoteQuest.levelMax ?? null,
                            categoryId: remoteQuest.categoryId,
                            type: "MODIFIED"
                        });
                    }
                }
            }

            totalProcessed += json.data.length;
            skip += limit;
        }

        return {
            success: true,
            data: {
                totalLocal: localQuests.length,
                totalRemote,
                deltas,
            }
        };

    } catch (e: any) {
        console.error("checkDofusDbDeltas Error:", e);
        return { success: false, error: e.message || "Erreur inconnue" };
    }
}

export async function syncDeltas(guildId: string, selectedIds: number[]) {
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated || !ctx.isAdmin) {
        return { success: false, error: "Non autorisé" };
    }

    if (!selectedIds.length) {
        return { success: false, error: "Aucune quête sélectionnée" };
    }

    try {
        // 1. Fetch categories mappings
        const catRes = await fetch(`${DOFUSDB_API}/quest-categories?$limit=100`);
        const catJson = await catRes.json();
        const categoriesMap = new Map<number, string>();
        if (catJson.data) {
            for (const cat of catJson.data) {
                categoriesMap.set(cat.id, cat.name?.fr || "Non classé");
            }
        }

        let syncedCount = 0;

        // 2. Fetch specific quests from DofusDB and upsert
        for (const id of selectedIds) {
            const res = await fetch(`${DOFUSDB_API}/quests/${id}`);
            const remoteQuest = await res.json();

            if (!remoteQuest || !remoteQuest.name?.fr) continue;

            const categoryName = categoriesMap.get(remoteQuest.categoryId) || "Non classé";
            const rawName = remoteQuest.name.fr;

            // Check if name is already taken by another dofusDbId
            const existingByName = await db.gameQuest.findFirst({
                where: { name: rawName }
            });

            let finalName = rawName;
            if (existingByName && existingByName.dofusDbId !== id) {
                finalName = `${rawName} (#${id})`;
            }

            // Upsert by dofusDbId if possible, or by name if dofusDbId isn't there yet
            const existingById = await db.gameQuest.findFirst({
                where: { dofusDbId: id }
            });

            if (existingById) {
                await db.gameQuest.update({
                    where: { id: existingById.id },
                    data: {
                        name: finalName,
                        levelMin: remoteQuest.levelMin,
                        levelMax: remoteQuest.levelMax,
                        category: categoryName
                    }
                });
            } else {
                await db.gameQuest.upsert({
                    where: { name: finalName },
                    update: {
                        dofusDbId: id,
                        levelMin: remoteQuest.levelMin,
                        levelMax: remoteQuest.levelMax,
                        category: categoryName
                    },
                    create: {
                        name: finalName,
                        dofusDbId: id,
                        levelMin: remoteQuest.levelMin,
                        levelMax: remoteQuest.levelMax,
                        category: categoryName
                    }
                });
            }

            syncedCount++;
        }

        return { success: true, count: syncedCount };

    } catch (e: any) {
        console.error("syncDeltas Error:", e);
        return { success: false, error: e.message || "Erreur inconnue" };
    }
}

'use server';

import { db } from "@/lib/prisma";
import { auth } from "@/auth";
import { getUserContext } from "./user-actions";
import { revalidatePath } from "next/cache";

export async function submitGeoguesserScore(
    guildId: string,
    score: number,
    avgDistance: number,
    isSolo: boolean = false
) {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Non autorisé" };

    const ctx = await getUserContext(guildId);
    if (!ctx.isMember) return { success: false, error: "Non membre" };

    try {
        // Only update Hall of Fame for multiplay (/!\ the user asked not to count solo)
        if (!isSolo) {
            // Update aggregate rank (ladder)
            const rank = await db.geoguesserRank.upsert({
                where: {
                    guildId_userId: {
                        guildId,
                        userId: session.user.id
                    }
                },
                    create: {
                        guildId,
                        userId: session.user.id,
                        userName: ctx.name || "Inconnu",
                        userAvatar: ctx.image,
                        bestScore: score,
                        totalPoints: score,
                        gamesPlayed: 1,
                        avgDistance: avgDistance
                    },
                    update: {
                        totalPoints: { increment: score },
                        gamesPlayed: { increment: 1 },
                        avgDistance: {
                            set: avgDistance
                        },
                        userName: ctx.name || "Inconnu",
                        userAvatar: ctx.image,
                    }
            });

            // Re-check best score to ensure we don't overwrite with lower
            if (score > rank.bestScore) {
                await db.geoguesserRank.update({
                    where: { id: rank.id },
                    data: { bestScore: score }
                });
            }
        }

        // Always save individual score for history/stats if needed, 
        // but here we primarily use geoguesserScore model for all games.
        await db.geoguesserScore.create({
            data: {
                guildId,
                userId: session.user.id,
                userName: ctx.name || "Inconnu",
                userAvatar: ctx.image,
                score,
                distance: avgDistance
            }
        });

        revalidatePath(`/dashboard/${guildId}/mini-jeux`);
        return { success: true };
    } catch (error) {
        console.error("Failed to submit score:", error);
        return { success: false, error: "Erreur de base de données" };
    }
}

export async function getGeoguesserLadder(guildId: string, type: 'all_time' | 'month' = 'all_time') {
    try {
        if (type === 'all_time') {
            const ranks = await db.geoguesserRank.findMany({
                where: { guildId },
                orderBy: { bestScore: 'desc' },
                take: 10
            });
            return ranks.map(r => ({
                userId: r.userId,
                userName: r.userName,
                userAvatar: r.userAvatar,
                bestScore: r.bestScore
            }));
        }

        const startOfMonth = new Date();
        startOfMonth.setDate(1);
        startOfMonth.setHours(0, 0, 0, 0);

        const monthlyScores = await db.geoguesserScore.groupBy({
            by: ['userId', 'userName', 'userAvatar'],
            where: {
                guildId,
                createdAt: { gte: startOfMonth }
            },
            _max: {
                score: true
            },
            orderBy: {
                _max: {
                    score: 'desc'
                }
            },
            take: 10
        });

        return monthlyScores.map((s: any) => ({
            userId: s.userId,
            userName: s.userName,
            userAvatar: s.userAvatar,
            bestScore: s._max?.score || 0
        }));
    } catch (error) {
        console.error("Failed to fetch ladder:", error);
        return [];
    }
}

'use server';

import { db } from "@/lib/prisma";
import { auth } from "@/auth";
import { getUserContext } from "./user-actions";
import { revalidatePath } from "next/cache";
import { redis } from "@/lib/redis";

const LOBBY_CACHE_TTL = 5; // 5 seconds cache for lobby list (keep it very short for real-time games)

const getClient = () => ((db as any).geoguesserSession ? db : null) as any;

export async function createGeoguesserSession(guildId: string, maxRounds: number = 5, timePerRound: number = 30) {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Unauthorized" };

    const ctx = await getUserContext(guildId);
    if (!ctx.isMember) return { success: false, error: "Not a member" };

    try {
        const client = getClient();
        if (!client) return { success: false, error: "Database client not ready" };

        // Clean up ANY existing session for this host in this guild to prevent ghost rooms
        await client.geoguesserSession.deleteMany({
            where: {
                guildId,
                hostId: session.user.id
            }
        });

        const room = await client.geoguesserSession.create({
            data: {
                guildId,
                hostId: session.user.id,
                hostName: ctx.name || "Hôte",
                maxRounds,
                timePerRound,
                status: 'LOBBY',
                participants: {
                    create: {
                        userId: session.user.id,
                        userName: ctx.name || "Joueur",
                        userAvatar: session.user.image,
                    }
                }
            },
            include: {
                participants: true
            }
        });

        // Invalidate cache
        await redis.del(`lobby:guild:${guildId}`);

        revalidatePath(`/dashboard/${guildId}/mini-jeux`);
        return { success: true, data: room };
    } catch (error) {
        return { success: false, error: "Erreur de base de données" };
    }
}

export async function getActiveGeoguesserSessions(guildId: string) {
    const cacheKey = `lobby:guild:${guildId}`;

    // 1. Try Redis first
    if (redis.status === "ready") {
        try {
            const cached = await redis.get(cacheKey);
            if (cached) return JSON.parse(cached);
        } catch (e) {
            console.error("[Redis] Cache read error:", e);
        }
    }

    try {
        const client = (db as any).geoguesserSession ? db : null;
        if (!client) {
            console.error("CRITICAL: geoguesserSession model not found even in baseDb");
            return [];
        }

        const sessions = await (client as any).geoguesserSession.findMany({
            where: {
                guildId,
                status: { in: ['LOBBY', 'IN_PROGRESS'] },
                createdAt: { gte: new Date(Date.now() - 24 * 60 * 60 * 1000) } // Filtre 24h d'inactivité
            },
            include: {
                _count: {
                    select: { participants: true }
                },
                participants: {
                    select: {
                        userId: true,
                        userName: true,
                        userAvatar: true
                    }
                }
            },
            orderBy: { createdAt: 'desc' }
        });

        // 2. Store in Redis
        if (redis.status === "ready") {
            try {
                await redis.set(cacheKey, JSON.stringify(sessions), "EX", LOBBY_CACHE_TTL);
            } catch (e) {
                console.error("[Redis] Cache write error:", e);
            }
        }

        return sessions;
    } catch (error) {
        return [];
    }
}

export async function joinGeoguesserSession(sessionId: string, isSpectator: boolean = false) {
    const sessionToken = await auth();
    if (!sessionToken?.user?.id) return { success: false, error: "Unauthorized" };

    try {
        const client = getClient();
        if (!client) return { success: false, error: "Database client not ready" };

        if (isSpectator) {
             const room = await client.geoguesserSession.findUnique({ where: { id: sessionId } });
             if (!room) return { success: false, error: "Salon introuvable" };
             return { success: true };
        }

        const room = await client.geoguesserSession.findUnique({
            where: { id: sessionId },
            include: { participants: true }
        });

        if (!room) return { success: false, error: "Salon introuvable" };
        
        const isAlreadyIn = room.participants.some((p: any) => p.userId === sessionToken.user!.id);

        if (room.status !== 'LOBBY' && !isAlreadyIn) {
            return { success: false, error: "La partie a déjà commencé" };
        }
        
        if (!isAlreadyIn && room.participants.length >= 8) {
            return { success: false, error: "Le salon est complet (8 joueurs max)." };
        }

        if (!isAlreadyIn) {
            const ctx = await getUserContext(room.guildId);
            await client.geoguesserSessionPlayer.create({
                data: {
                    sessionId,
                    userId: sessionToken.user!.id,
                    userName: ctx.name || "Joueur",
                    userAvatar: sessionToken.user!.image,
                }
            });

            // Notifier le propriétaire du salon (si ce n'est pas lui-même)
            if (room.hostId !== sessionToken.user!.id && (client as any).notification) {
                try {
                    await (client as any).notification.create({
                        data: {
                            userId: room.hostId,
                            title: "SigilGuesser",
                            message: `${ctx.name} a rejoint votre salon !`,
                            type: "SYSTEM_INFO",
                            category: "SYSTEM",
                            link: `/dashboard/${room.guildId}/mini-jeux`
                        }
                    });
                } catch (e) {
                    console.error("Failed to send notification:", e);
                }
            }
        }

        // --- INVALIDATE CACHE ---
        await redis.del(`lobby:guild:${room.guildId}`);

        return { success: true };
    } catch (error) {
        return { success: false, error: "Erreur de base de données" };
    }
}

export async function startGeoguesserSession(sessionId: string, targetMapIds: number[]) {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Unauthorized" };

    try {
        const client = getClient();
        if (!client) return { success: false, error: "Database client not ready" };

        const room = await client.geoguesserSession.findUnique({
            where: { id: sessionId }
        });

        if (!room) return { success: false, error: "Room not found" };
        if (room.hostId !== session.user.id) return { success: false, error: "Only host can start" };

        await client.geoguesserSession.update({
            where: { id: sessionId },
            data: {
                status: 'IN_PROGRESS',
                targetMapIds,
                currentRound: 1
            }
        });

        // --- INVALIDATE CACHE ---
        await redis.del(`lobby:guild:${room.guildId}`);

        return { success: true };
    } catch (error) {
        console.error("Failed to start game:", error);
        return { success: false, error: "Database error" };
    }
}

export async function submitSessionGuess(
    sessionId: string,
    round: number,
    x: number,
    y: number,
    worldId: number,
    score: number,
    distance: number
) {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Unauthorized" };

    try {
        const client = getClient();
        if (!client) return { success: false, error: "Database client not ready" };

        const player = await client.geoguesserSessionPlayer.findUnique({
            where: { sessionId_userId: { sessionId, userId: session.user.id } }
        });

        if (!player) return { success: false, error: "Player not in session" };

        const currentGuesses = (player.guesses as any[]) || [];
        const newGuess = { round, x, y, score, distance, worldId };

        // Remove existing guess for this round if any (safety)
        const updatedGuesses = currentGuesses.filter(g => g.round !== round);
        updatedGuesses.push(newGuess);

        await client.geoguesserSessionPlayer.update({
            where: { id: player.id },
            data: {
                guesses: updatedGuesses,
                totalScore: { increment: score },
                hasGuessed: true
            }
        });

        return { success: true };
    } catch (error) {
        console.error("Failed to submit session guess:", error);
        return { success: false, error: "Database error" };
    }
}

export async function getSessionStatus(sessionId: string) {
    try {
        const client = getClient();
        if (!client) return null;

        return await client.geoguesserSession.findUnique({
            where: { id: sessionId },
            include: {
                participants: true
            }
        });
    } catch (error) {
        return null;
    }
}

export async function advanceSessionRound(sessionId: string, newRound: number) {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Unauthorized" };

    try {
        const client = getClient();
        if (!client) return { success: false, error: "Database client not ready" };

        await client.geoguesserSession.update({
            where: { id: sessionId },
            data: {
                currentRound: newRound,
                participants: {
                    updateMany: {
                        where: { sessionId },
                        data: { hasGuessed: false }
                    }
                }
            }
        });

        const room = await client.geoguesserSession.findUnique({ where: { id: sessionId } });
        if (room) {
            // --- INVALIDATE CACHE ---
            await redis.del(`lobby:guild:${room.guildId}`);
        }

        return { success: true };
    } catch (error) {
        console.error("Failed to advance round:", error);
        return { success: false, error: "Database error" };
    }
}

export async function leaveGeoguesserSession(sessionId: string) {
    const sessionToken = await auth();
    if (!sessionToken?.user?.id) return { success: false, error: "Unauthorized" };

    try {
        const client = getClient();
        if (!client) return { success: false, error: "Database client not ready" };

        const room = await client.geoguesserSession.findUnique({
            where: { id: sessionId },
            include: { participants: true }
        });

        if (!room) return { success: false, error: "Room not found" };

        // Save scores to perpetual ladder if it was a real game
        if (room.status === 'FINISHED' || room.status === 'IN_PROGRESS') {
            for (const p of room.participants) {
                if (p.totalScore > 0) {
                    await updateGeoguesserLadder(p.userName, p.totalScore);
                }
            }
        }

        if (room.hostId === sessionToken.user.id) {
            await client.geoguesserSession.delete({ where: { id: sessionId } });
        } else {
            await client.geoguesserSessionPlayer.deleteMany({
                where: { sessionId, userId: sessionToken.user.id }
            });
        }

        await redis.del(`lobby:guild:${room.guildId}`);
        return { success: true };
    } catch (error) {
        return { success: false, error: "Database error" };
    }
}

export async function finishGeoguesserSession(sessionId: string) {
    try {
        const client = getClient();
        if (!client) return;
        
        await client.geoguesserSession.update({
            where: { id: sessionId },
            data: { status: 'FINISHED' }
        });

        // Sync to ladder
        const room = await client.geoguesserSession.findUnique({
            where: { id: sessionId },
            include: { participants: true }
        });

        if (room) {
            for (const p of room.participants) {
                if (p.totalScore > 0) {
                    await updateGeoguesserLadder(p.userName, p.totalScore);
                }
            }
            // --- INVALIDATE CACHE ---
            await redis.del(`lobby:guild:${room.guildId}`);
        }
    } catch (e) {
        console.error("Failed to finish session:", e);
    }
}

export async function deleteGeoguesserSession(sessionId: string) {
    try {
        const client = getClient();
        if (!client) return;

        const room = await client.geoguesserSession.findUnique({ where: { id: sessionId } });
        if (room) {
            await client.geoguesserSession.delete({ where: { id: sessionId } });
            await redis.del(`lobby:guild:${room.guildId}`);
        }
    } catch (e) {
        // Silently fail if already deleted
    }
}

async function updateGeoguesserLadder(pseudo: string, score: number) {
    if (redis.status !== "ready") return;
    try {
        await redis.zincrby("sigilguesser:ladder:v1", score, pseudo);
    } catch (e) {
        console.error("Ladder update failed:", e);
    }
}

export async function getGeoguesserLadder(limit: number = 10) {
    if (redis.status !== "ready") return [];
    try {
        // ZREVRANGE returns the top scores
        const data = await redis.zrevrange("sigilguesser:ladder:v1", 0, limit - 1, "WITHSCORES");
        const results = [];
        for (let i = 0; i < data.length; i += 2) {
            results.push({
                pseudo: data[i],
                score: parseInt(data[i + 1], 10)
            });
        }
        return results;
    } catch (e) {
        return [];
    }
}

"use server";

import { db } from "@/lib/prisma";
import { getSuperAdminIds, isSuperAdmin } from "@/server/actions/super-admin-actions";
import { SystemIssueType, SystemIssueStatus } from "@prisma/client";
import { revalidatePath } from "next/cache";
import { auth } from "@/auth";
import { logger } from "@/lib/logger";

const SUPER_ADMINS = process.env.SUPER_ADMIN_IDS?.split(",") || [];

async function isGod() {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) return null;
    const session = await auth();
    if (!session?.user?.id) return null;
    return session.user.id;
}

export async function getSystemIssues() {
    const adminId = await isGod();
    if (!adminId) return { success: false, error: "Non autorisé" };

    try {
        const issues = await db.systemIssue.findMany({
            orderBy: [
                { status: 'asc' }, // A FAIRE first
                { createdAt: 'desc' },
            ],
        });
        return { success: true, data: issues };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
}

export async function getMemberSystemIssues(guildId: string) {
    const start = Date.now();
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Non authentifié" };

    try {
        // 1. Resolve internal guild ID from Discord ID
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true }
        });

        if (!guildConfig) {
            logger.error(`[Tracker] Guild config not found for Discord ID: ${guildId}`);
            return { success: false, error: "Guilde introuvable" };
        }

        const internalGuildId = guildConfig.id;

        // 2. Double check membership for security
        const membership = await db.userProfile.findFirst({
            where: {
                guildId: internalGuildId,
                userId: session.user.id,
                status: "ACTIVE"
            }
        });

        if (!membership) {
            logger.error(`[Tracker] Access denied for user ${session.user.id} in guild ${internalGuildId}`);
            return { success: false, error: "Accès refusé" };
        }

        const issues = await db.systemIssue.findMany({
            orderBy: [
                { status: 'asc' },
                { createdAt: 'desc' },
            ],
        });
        
        logger.debug(`[PERF] getMemberSystemIssues took ${Date.now() - start}ms`);
        return { success: true, data: issues };
    } catch (e: any) {
        logger.error(`[Tracker] Error:`, { error: e });
        return { success: false, error: e.message };
    }
}

export async function createSystemIssue(data: {
    type: SystemIssueType;
    category: string;
    priority: string;
    description: string;
    forumLink?: string;
}) {
    const adminId = await isGod();
    if (!adminId) return { success: false, error: "Non autorisé" };

    try {
        await db.systemIssue.create({
            data: {
                ...data,
                creatorId: adminId,
            }
        });
        revalidatePath("/god/bugs");
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
}

