export async function hardDeleteProfile(profileId: string) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) {
        return { success: false, error: 'Unauthorized' };
    }

    try {
        // Get profile data BEFORE delete
        const profile = await db.userProfile.findUnique({
            where: { id: profileId },
            select: { guildId: true }
        });

        if (!profile) {
            return { success: false, error: 'Profile not found' };
        }

        // Skip guild-level audit logging if the action is deemed "God-level stealth"
        // The user specifically mentioned "log des dashboard de guilde".
        // So skip AuditLog.create for guildId if actor is God.
        // This means we intentionally do NOT log this action to the guild's audit log.
        // If we wanted to log it to a *platform-level* audit log, that would be a separate implementation.

        await db.userProfile.delete({
            where: { id: profileId }
        });

        revalidatePath('/god');
        return { success: true };
    } catch (error) {
        console.error('[GOD] hardDeleteProfile error:', error);
        return { success: false, error: 'Failed to hard delete profile' };
    }
}

/**
 * Get soft-deleted guilds
 */
export async function getSoftDeletedGuilds() {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) return [];

    return db.guildConfig.findMany({
        where: {
            isActive: false,
            deletedAt: { not: null }
        },
        orderBy: { scheduledDeletion: 'asc' },
        select: {
            id: true,
            name: true,
            discordGuildId: true,
            isActive: true,
            deletedAt: true,
            deletionReason: true,
            scheduledDeletion: true,
            _count: { select: { profiles: true } }
        }
    });
}

/**
 * Get soft-deleted profiles
 */
export async function getSoftDeletedProfiles() {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) return [];

    return db.userProfile.findMany({
        where: {
            status: 'ARCHIVED',
            archivedAt: { not: null }
        },
        select: {
            id: true,
            userId: true,
            guildId: true,
            status: true,
            archivedAt: true,
            scheduledDeletion: true,
            guild: { select: { name: true } },
            user: { select: { name: true } }
        },
        orderBy: { scheduledDeletion: 'asc' }
    });
}

/**
 * Get all archived profiles (not just soft-deleted)
 */
export async function getArchivedProfiles() {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) return [];

    return db.userProfile.findMany({
        where: { status: 'ARCHIVED' },
        select: {
            id: true,
            userId: true,
            guildId: true,
            status: true,
            archivedAt: true,
            scheduledDeletion: true,
            guild: { select: { name: true } },
            user: { select: { name: true } }
        },
        orderBy: { archivedAt: 'desc' },
        take: 100
    });
}

/**
 * Get all active guilds for the control panel
 */
export async function getActiveGuilds() {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) return [];

    return db.guildConfig.findMany({
        where: { isActive: true },
        include: {
            _count: { select: { profiles: true } }
        },
        orderBy: { name: 'asc' }
    });
}

/**
 * Get all platform-level bans
 */
export async function getPlatformBans() {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) return [];

    return db.platformBan.findMany({
        select: {
            id: true,
            entityType: true,
            discordId: true,
            reason: true,
            bannedBy: true,
            createdAt: true
        },
        orderBy: { createdAt: 'desc' }
    });
}

/**
 * Ban an entity (Guild or User) at the platform level
 */
export async function banEntity(type: 'GUILD' | 'USER', discordId: string, reason: string) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) return { success: false, error: 'Unauthorized' };

    try {
        const session = await auth();
        await db.platformBan.create({
            data: {
                entityType: type,
                discordId,
                reason,
                bannedBy: session?.user?.id || 'UNKNOWN'
            }
        });

        revalidatePath('/god');
        return { success: true };
    } catch (error) {
        return { success: false, error: 'Failed to ban entity' };
    }
}

/**
 * Unban an entity
 */
export async function unbanEntity(banId: string) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) return { success: false, error: 'Unauthorized' };

    try {
        await db.platformBan.delete({
            where: { id: banId }
        });

        revalidatePath('/god');
        return { success: true };
    } catch (error) {
        return { success: false, error: 'Failed to unban entity' };
    }
}
/**
 * Get all members for a specific guild (God view)
 */
export async function getGuildMembersForGod(guildId: string) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) throw new Error("Unauthorized");

    const [members, guild] = await Promise.all([
        db.userProfile.findMany({
            where: { guildId },
            select: {
                id: true,
                userId: true,
                status: true,
                createdAt: true,
                updatedAt: true,
                archivedAt: true,
                archiveReason: true,
                pseudoDofus: true,
                discordNickname: true,
                scheduledDeletion: true,
                user: {
                    select: {
                        name: true,
                        image: true,
                        accounts: {
                            where: { provider: "discord" },
                            select: { providerAccountId: true }
                        }
                    }
                }
            },
            orderBy: { updatedAt: "desc" }
        }),
        db.guildConfig.findUnique({
            where: { id: guildId },
            select: { ownerId: true }
        })
    ]);

    return {
        ownerId: guild?.ownerId,
        members: members.map(m => ({
            id: m.id,
            userId: m.userId,
            status: m.status as "ACTIVE" | "ARCHIVED" | "BANNED",
            createdAt: m.createdAt.toISOString(),
            updatedAt: m.updatedAt.toISOString(),
            archivedAt: m.archivedAt?.toISOString() || null,
            archiveReason: m.archiveReason,
            pseudoDofus: m.pseudoDofus,
            discordNickname: m.discordNickname,
            scheduledDeletion: m.scheduledDeletion?.toISOString() || null,
            user: {
                name: m.user.name,
                image: m.user.image,
                accounts: m.user.accounts
            }
        }))
    };
}

/**
 * Transfer full ownership of a guild to another user (Super-admin only)
 */
export async function transferGuildOwnership(guildId: string, newOwnerUserId: string) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) return { success: false, error: 'Unauthorized' };

    try {
        await db.guildConfig.update({
            where: {
                // Use OR to support both internal ID and discordGuildId (ID mismatch fix)
                id: guildId.length < 25 ? undefined : guildId,
                discordGuildId: guildId.length < 25 ? guildId : undefined
            },
            data: { ownerId: newOwnerUserId }
        });

        revalidatePath('/god');
        return { success: true };
    } catch (error) {
        console.error('[GOD] transferGuildOwnership error:', error);
        return { success: false, error: 'Failed to transfer ownership' };
    }
}

"use server";

import { db } from "@/lib/prisma";
import { isSuperAdmin } from "./super-admin-actions";
import { revalidatePath } from "next/cache";
import { WorldMapService } from "../games/SigilGuesser/WorldMapService";
import { logger } from "@/lib/logger";

export async function getMiniGamesStatus() {
    // This action doesn't strictly need superadmin check if we want to show status on public/member pages,
    // but the management part MUST be protected.
    return db.miniGameStatus.findMany();
}

export async function updateMiniGameStatus(gameId: string, isEnabled: boolean, maintenanceMsg?: string) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) throw new Error("Unauthorized");

    const updated = await db.miniGameStatus.upsert({
        where: { gameId },
        update: { 
            isEnabled, 
            maintenanceMsg: maintenanceMsg || "🔧 Ce jeu est temporairement indisponible pour maintenance." 
        },
        create: { 
            gameId, 
            isEnabled, 
            maintenanceMsg: maintenanceMsg || "🔧 Ce jeu est temporairement indisponible pour maintenance." 
        },
    });

    revalidatePath("/god");
    revalidatePath("/dashboard/[guildId]/mini-jeux", "layout");
    return updated;
}

export async function getPlatformConfig() {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) throw new Error("Unauthorized");

    let config = await db.platformConfig.findUnique({ where: { id: "singleton" } });
    if (!config) {
        config = await db.platformConfig.create({ data: { id: "singleton" } });
    }
    logger.debug(`[PlatformConfig] Fetching singleton: ${(config.geoguesserReportedMaps as any[])?.length || 0} reported maps, ${config.geoguesserBlacklist?.length || 0} blacklisted.`);
    return config;
}

export async function updateGeoguesserConfig(data: { blacklist?: number[], reportedMaps?: any[] }) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) throw new Error("Unauthorized");

    const updated = await db.platformConfig.update({
        where: { id: "singleton" },
        data: {
            geoguesserBlacklist: data.blacklist,
            geoguesserReportedMaps: data.reportedMaps ? (data.reportedMaps as any) : undefined
        }
    });

    // Immediate sync for the current server instance
    if (data.blacklist) {
        WorldMapService.getInstance().setBlacklist(data.blacklist);
    }

    revalidatePath("/god/mini-games");
    revalidatePath("/dashboard/[guildId]/mini-jeux", "layout");
    return updated;
}

