    totalValidations: number;
    topValidatorsMonth: LeaderboardEntry[];
}

interface RetentionStats {
    growth: { month: string; joins: number; leaves: number }[];
    totalJoins: number;
    avgTenureDays: number;
}

interface GuildRecord {
    label: string;
    value: string;
    icon: string;
}

interface ServicesStats {
