            logger.error(`[Guildaton] Manual report API error: ${response.status}`, { errorText });
            return { success: false, error: "Échec de l'envoi Discord" };
        }
    } catch (error: any) {
        logger.error("[Guildaton] Manual report fetch error:", { error });
        return { success: false, error: "Erreur lors de l'envoi" };
    }
}

"use server";

import { db } from "@/lib/prisma";
import { getUserContext } from "@/server/actions/user-actions";
import { revalidatePath } from "next/cache";
import { z } from "zod";

/**
 * Schema for giving a help credit
 */
const GiveHelpCreditSchema = z.object({
    guildId: z.string(),
    toUserId: z.string(),
    missionId: z.string().optional(),
    message: z.string().max(100).optional(),
});

export type ActionResponse<T = any> = {
    success: boolean;
    data?: T;
    error?: string;
};

/**
 * Give a help credit to another member
 * 
 * Rules:
 * 1. Max 3 credits given per day (rolling 24h)
 * 2. Cannot thank the same person twice in 24h
 * 3. Cannot thank yourself
 * 4. Must be a member of the guild
 */
export async function giveHelpCredit(formData: z.infer<typeof GiveHelpCreditSchema>): Promise<ActionResponse> {
    const validation = GiveHelpCreditSchema.safeParse(formData);
    if (!validation.success) {
        return { success: false, error: "Données invalides : " + validation.error.message };
    }

    const { guildId, toUserId, missionId, message } = validation.data;

    // 1. Auth & Guild Isolation
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated) return { success: false, error: "Non authentifié" };
    if (!ctx.isMember) return { success: false, error: "Vous devez être membre de cette guilde" };

    const fromUserId = ctx.id!;

    // 2. Self-thank check
    if (fromUserId === toUserId) {
        return { success: false, error: "Vous ne pouvez pas vous remercier vous-même" };
    }

    try {
        const now = new Date();
        const rolling24h = new Date(now.getTime() - 24 * 60 * 60 * 1000);

        // 3. Check daily limit (3/day)
        const creditsToday = await (db as any).helpCredit.count({
            where: {
                guildId,
                fromUserId,
                createdAt: { gte: rolling24h }
            }
        });


        if (creditsToday >= 3) {
            return { success: false, error: "Limite de 3 remerciements par 24h atteinte" };
        }

        // 4. Check recipient cooldown (once per person per 24h)
        const recentCreditToUser = await (db as any).helpCredit.findFirst({
            where: {
                guildId,
                fromUserId,
                toUserId,
                createdAt: { gte: rolling24h }
            }
        });


        if (recentCreditToUser) {
            return { success: false, error: "Vous avez déjà remercié ce membre ces dernières 24h" };
        }

        // 5. Transaction: Create Credit + Update Points
        const pointsPerCredit = parseInt(process.env.ENTRAIDE_POINTS_PER_CREDIT || "5", 10);

        await db.$transaction([
            (db as any).helpCredit.create({
                data: {
                    guildId,
                    fromUserId,
                    toUserId,
                    missionId,
                    message,
                    points: pointsPerCredit
                }
            }),
            (db as any).userProfile.update({
                where: { userId_guildId: { userId: toUserId, guildId } },
                data: {
                    entraidePoints: { increment: pointsPerCredit }
                }
            })
        ]);

        // 6. Audit Log
        const { createAuditLog } = await import("@/server/actions/audit-actions");
        await createAuditLog({
            guildId,
            actorUserId: fromUserId,
            actorName: ctx.name || "Inconnu",
            action: "HELP_CREDIT_GIVEN",
            targetType: "PROFILE",
            targetId: toUserId,
            newValue: { toUserId, points: pointsPerCredit, missionId, message }
        });


        revalidatePath(`/dashboard/${guildId}/missions`);
        revalidatePath(`/dashboard/${guildId}/ladder`);

        return { success: true };
    } catch (error) {
        console.error("[HelpActions] Error giving credit:", error);
        return { success: false, error: "Une erreur est survenue lors de l'attribution du remerciement" };
    }
}

/**
 * Get help credits received by a user
 */
export async function getReceivedCredits(guildId: string, userId: string) {
    return await (db as any).helpCredit.findMany({
        where: { guildId, toUserId: userId },
        include: {
            fromProfile: {
                select: {
                    discordNickname: true,
                    userId: true
                }
            }
        },
        orderBy: { createdAt: "desc" }
    });
}


/**
 * Get stats for current user (limits remaining)
 */
export async function getHelpStats(guildId: string) {
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated) return null;

    const now = new Date();
    const rolling24h = new Date(now.getTime() - 24 * 60 * 60 * 1000);

    const creditsGiven = await (db as any).helpCredit.count({
        where: {
            guildId,
            fromUserId: ctx.id!,
            createdAt: { gte: rolling24h }
        }
    });


    return {
        remainingToday: Math.max(0, 3 - creditsGiven),
        limit: 3
    };
}

import { db } from "@/lib/prisma";
import { getMyOcreProgress, OcreProgressData } from "./ocre-actions";
import { getDreamRuns } from "./songes/dream-run-actions";
import { UserContext } from "./user-actions";

export type FocusCardType = "OCRE_STEP" | "SONGES_RECRUIT" | "MISSION_URGENT" | "WELCOME";

export interface FocusCardData {
    type: FocusCardType;
    title: string;
    description: string;
    actionLabel: string;
    actionHref: string;
    priority: number; // 0-100
    metadata?: any;
}

/**
 * The Brain of SigilOS Dashboard.
 * Analyzes user state and returns the most relevant "Focus" action.
 */
export async function getDashboardFocus(
    guildId: string, 
    user: UserContext,
    prefetchedOcre?: OcreProgressData
): Promise<FocusCardData> {
    const cards: FocusCardData[] = [];

    try {
        // 1. Check Ocre Progress (Use prefetched data if available to save DB connections)
        if (user.canViewOcre) {
            let ocreData = prefetchedOcre;
            
            if (!ocreData) {
                const ocre = await getMyOcreProgress(guildId);
                if (ocre.success) ocreData = ocre.data;
            }

            if (ocreData) {
                const stats = ocreData.stats;
                if (stats.progressPercent > 80 && stats.progressPercent < 100) {
                    cards.push({
                        type: "OCRE_STEP",
                        title: "Quête Ocre : Prochaine étape",
                        description: `Vous avez complété ${stats.progressPercent}% de la quête. Plus que ${stats.manquants} monstres pour valider l'étape.`,
                        actionLabel: "Voir les monstres",
                        actionHref: `/dashboard/${guildId}/archimonstres`,
                        priority: stats.progressPercent
                    });
                }
            }
        }

        // 2. Check Songes Runs in recruitment
        if (user.canViewSonges) {
            const songes = await getDreamRuns(guildId, ["RECRUITING"]);
            if (songes.success && songes.runs && songes.runs.length > 0) {
                const recruitingRuns = songes.runs.filter((run: any) => run.status === "RECRUITING" && run.members.length < 4);

                if (recruitingRuns.length > 0) {
                    if (recruitingRuns.length === 1) {
                        const run = recruitingRuns[0];
                        const missing = 4 - run.members.length;
                        cards.push({
                            type: "SONGES_RECRUIT",
                            title: "Recrutement Songes",
                            description: `Un groupe pour une run ${run.difficulty} cherche ${missing} ${missing > 1 ? 'joueurs' : 'joueur'}.`,
                            actionLabel: "Consulter la run",
                            actionHref: `/dashboard/${guildId}/songes`,
                            priority: 85
                        });
                    } else {
                        const totalMissing = recruitingRuns.reduce((acc: number, run: any) => acc + (4 - run.members.length), 0);
                        cards.push({
                            type: "SONGES_RECRUIT",
                            title: "Recrutements Songes",
                            description: `${recruitingRuns.length} groupes de runs cherchent actuellement un total de ${totalMissing} joueurs.`,
                            actionLabel: "Voir les runs",
                            actionHref: `/dashboard/${guildId}/songes`,
                            priority: 88
                        });
                    }
                }
            }
        }

        // 3. Check for Active / Upcoming Official Raids or Guild Events
        if (user.canViewCalendar) {
            const now = new Date();
            const upcomingEvents = await db.guildEvent.findMany({
                where: {
                    guild: { discordGuildId: guildId },
                    startDate: { lte: new Date(now.getTime() + 24 * 60 * 60 * 1000) }, // In next 24 hours
                    endDate: { gte: now }, // Not ended yet
                    status: "PUBLISHED",
                    type: { in: ["RAID_OFFICIAL", "EVENT_GUILD"] }
                },
                orderBy: { startDate: "asc" },
                take: 1
            });

            if (upcomingEvents.length > 0) {
                const event = upcomingEvents[0];
                const isRaid = event.type === "RAID_OFFICIAL";
                cards.push({
                    type: isRaid ? "SONGES_RECRUIT" : "WELCOME", // Reuses styling indicators
                    title: isRaid ? "🔥 RAID EN COURS / IMMINENT" : "🎉 ÉVÉNEMENT MAJEUR",
                    description: `Rejoignez "${event.title}" prévu le ${event.startDate.toLocaleDateString("fr-FR")} à ${event.startDate.toLocaleTimeString("fr-FR", { hour: '2-digit', minute: '2-digit' })}.`,
                    actionLabel: "S'inscrire / Rejoindre",
                    actionHref: `/dashboard/${guildId}/calendar?event=${event.id}`,
                    priority: 95 // Highest priority to put it at the very top of the Dashboard Focus Hero
                });
            }
        }

        // 4. Fallback: Welcome / Activities
        if (user.canViewMissions) {
            cards.push({
                type: "WELCOME",
                title: "Objectifs de Guilde",
                description: "Consultez les missions disponibles pour cette semaine et participez à l'effort collectif.",
                actionLabel: "Voir les missions",
                actionHref: `/dashboard/${guildId}/missions`,
                priority: 10
            });
        } else {
            // General fallback if missions are restricted
            cards.push({
                type: "WELCOME",
                title: "Découvrez SigilOS",
                description: "Consultez la présentation de la guilde et la documentation pour bien commencer.",
                actionLabel: "Lire le guide",
                actionHref: `/dashboard/${guildId}/presentation`,
                priority: 10
            });
        }

    } catch (e) {
        console.error("[Intelligence] Focus generation failed:", e);
    }

    // Return highest priority card
    return cards.sort((a, b) => b.priority - a.priority)[0];
}

"use server";

import { db } from "@/lib/prisma";
import { getUserContext, checkGuildPermission, type ActionResponse } from "./user-actions";
import { auth } from "@/auth";
import { PERMISSIONS } from "@/lib/permissions";
import { revalidatePath } from "next/cache";
import { z } from "zod";
import { logger } from "@/lib/logger";
import { PrismaClient } from "@prisma/client";
import {
    KAMA_TRANCHE,
    KAMA_MAX_TRANCHES,
    KAMA_MAX_PER_WEEK,
    REWARDS_PER_TRANCHE
} from "@/lib/kama-constants";
import { getDofusWeek } from "@/lib/date-utils";
import { grantRewards } from "./mission-actions";
import { hashImage } from "@/lib/llm-ocr";
import { getDiscordPublicUrl } from "@/lib/storage-utils";

// Le client etendu ($extends) masque les types TS des modeles, on caste vers PrismaClient
// pour acceder a kamaDonation avec les bons types. En runtime, tout fonctionne correctement.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const kamaDb = db as unknown as PrismaClient;

type KamaDonationStatus = "PENDING" | "VALIDATED" | "REJECTED";

// ============================================================================
// TYPES
// ============================================================================

export type KamaDonationEntry = {
    id: string;
    guildId: string;
    profileId: string;
    amount: number;
    tranches: number;
    proofUrl: string | null;
    status: KamaDonationStatus;
    validatedById: string | null;
    validatedAt: Date | null;
    rejectedReason: string | null;
    note: string | null;
    weekNumber: number | null;
    yearNumber: number | null;
    createdAt: Date;
    profile: {
        id: string;
        pseudoDofus: string | null;
        discordNickname: string | null;
        discordRoleColor: number | null;
        user: { name: string | null; image: string | null };
    };
};

export type KamaWeeklyStatus = {
    submittedThisWeek: number;
    validatedThisWeek: number;
    tranchesLeft: number;
    canContribute: boolean;
    weekDonations: Array<{ id: string; amount: number; status: KamaDonationStatus }>;
};

export type KamaLadderEntry = {
    rank: number;
    profileId: string;
    pseudoDofus: string | null;
    discordNickname: string | null;
    discordRoleColor: number | null;
    discordImage: string | null;
    totalAmount: number;
    donationCount: number;
    isCurrentUser: boolean;
};

export type KamaStats = {
    totalValidated: number;
    totalPending: number;
    donorCount: number;
    weeklyTotal: number;
    weeklyPending: number;
};

// ============================================================================
// SCHEMAS
// ============================================================================

const submitDonationSchema = z.object({
    guildId: z.string().min(1),
    tranches: z.number().int().min(1, "Minimum 1 tranche").max(KAMA_MAX_TRANCHES, `Maximum ${KAMA_MAX_TRANCHES} tranches`),
    note: z.string().max(300).optional().nullable(),
});

const reviewDonationSchema = z.object({
    guildId: z.string().min(1),
    donationId: z.string().min(1),
    action: z.enum(["VALIDATE", "REJECT"]),
    rejectedReason: z.string().max(200).optional().nullable(),
});

// ============================================================================
// HELPER
// ============================================================================
const profileSelect = {
    id: true,
    pseudoDofus: true,
    discordNickname: true,
    discordRoleColor: true,
    user: { select: { name: true, image: true } },
} as const;

// ============================================================================
// GET MY WEEKLY KAMA STATUS
// ============================================================================

export async function getMyWeeklyKamaStatus(
    guildId: string
): Promise<ActionResponse<KamaWeeklyStatus>> {
    const session = await auth();
    const guard = await checkGuildPermission(session, guildId, PERMISSIONS.COMMUNITY_ACCESS);
    if (!guard.allowed) return { success: false, error: guard.error };

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true },
        });
        if (!guildConfig) return { success: false, error: "Guilde introuvable" };

        const user = await getUserContext(guildId);
        if (!user.profileId) return { success: false, error: "Profil introuvable" };

        const { week, year } = getDofusWeek();

        const weekDonations: Array<{ id: string; amount: number; status: string }> = await kamaDb.kamaDonation.findMany({
            where: {
                guildId: guildConfig.id,
                profileId: user.profileId,
                weekNumber: week,
                yearNumber: year,
                status: { not: "REJECTED" },
            },
            select: { id: true, amount: true, status: true },
        });

        const submittedThisWeek = weekDonations.reduce((s, d) => s + d.amount, 0);
        const validatedThisWeek = weekDonations
            .filter(d => d.status === "VALIDATED")
            .reduce((s, d) => s + d.amount, 0);

        const tranchesUsed = Math.floor(submittedThisWeek / KAMA_TRANCHE);
        const tranchesLeft = Math.max(0, KAMA_MAX_TRANCHES - tranchesUsed);

        return {
            success: true,
            data: {
                submittedThisWeek,
                validatedThisWeek,
                tranchesLeft,
                canContribute: tranchesLeft > 0,
                weekDonations: weekDonations.map(d => ({
                    id: d.id,
                    amount: d.amount,
                    status: d.status as KamaDonationStatus,
                })),
            },
        };
    } catch (error) {
        logger.error("getMyWeeklyKamaStatus error", { error, guildId });
        return { success: false, error: "Erreur serveur" };
    }
}

// ============================================================================
// SUBMIT DONATION
// ============================================================================

export async function submitKamaDonation(
    input: z.infer<typeof submitDonationSchema>,
    proofFormData: FormData
): Promise<ActionResponse<{ id: string }>> {
    const session = await auth();
    const guard = await checkGuildPermission(session, input.guildId, PERMISSIONS.COMMUNITY_ACCESS);
    if (!guard.allowed) return { success: false, error: guard.error };

    const parsed = submitDonationSchema.safeParse(input);
    if (!parsed.success) return { success: false, error: parsed.error.errors[0]?.message || "Donnees invalides" };

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: input.guildId },
            select: { id: true, kamaNotifyChannelId: true, kamaNotifyRoleId: true } as Record<string, true>,
        }) as { id: string; kamaNotifyChannelId: string | null; kamaNotifyRoleId: string | null } | null;
        if (!guildConfig) return { success: false, error: "Guilde introuvable" };

        const user = await getUserContext(input.guildId);
        if (!user.profileId) return { success: false, error: "Profil introuvable" };

        const { week, year } = getDofusWeek();

        // Server-side weekly limit check
        const existingWeek = await kamaDb.kamaDonation.aggregate({
            where: {
                guildId: guildConfig.id,
                profileId: user.profileId,
                weekNumber: week,
                yearNumber: year,
                status: { not: "REJECTED" },
            },
            _sum: { amount: true },
        });
        const alreadyThisWeek: number = existingWeek._sum.amount ?? 0;
        const requestedAmount = parsed.data.tranches * KAMA_TRANCHE;

        if (alreadyThisWeek + requestedAmount > KAMA_MAX_PER_WEEK) {
            const remaining = KAMA_MAX_PER_WEEK - alreadyThisWeek;
            const tranchesLeft = Math.floor(remaining / KAMA_TRANCHE);
            return {
                success: false,
                error: `Limite hebdomadaire depassee. Il vous reste ${tranchesLeft} tranche(s) (${remaining.toLocaleString("fr-FR")} kamas max).`,
            };
        }

        // --- ANTI-DUPLICATE IMAGE CHECK ---
        const file = proofFormData.get("file") as File | null;
        if (!file) return { success: false, error: "Aucun fichier fourni" };
        const fileBuffer = Buffer.from(await file.arrayBuffer());
        const imageHash = await hashImage(fileBuffer);
        const existingHash = await db.imageHash.findFirst({
            where: { hash: imageHash }
        });
        if (existingHash) {
            return { success: false, error: "Cette image a déjà été utilisée pour une contribution dans cette guilde." };
        }

        // Re-build FormData since we consumed the file
        const rebuiltFormData = new FormData();
        rebuiltFormData.set("file", new File([fileBuffer], file.name, { type: file.type }));

        // Upload proof (required)
        const { uploadProofImage } = await import("./upload-actions");
        const uploadResult = await uploadProofImage(guildConfig.id, rebuiltFormData);
        if (!uploadResult.success || !uploadResult.url) {
            return { success: false, error: uploadResult.error || "Erreur upload screenshot" };
        }

        const donation = await kamaDb.kamaDonation.create({
            data: {
                guildId: guildConfig.id,
                profileId: user.profileId,
                amount: requestedAmount,
                proofUrl: uploadResult.url,
                note: parsed.data.note || null,
                weekNumber: week,
                yearNumber: year,
                status: "PENDING",
            },
        });

        // Store image hash to prevent reuse
        await (db as any).imageHash.create({
            data: {
                guildId: guildConfig.id,
                hash: imageHash,
                sourceType: "KAMA_DONATION",
                sourceId: donation.id,
                uploaderId: session!.user!.id,
            },
        });

        revalidatePath(`/dashboard/${input.guildId}/missions`);
        revalidatePath(`/dashboard/${input.guildId}/ladder`);
        logger.info("KamaDonation submitted", { donationId: donation.id, guildId: input.guildId, amount: requestedAmount });

        // Discord notification
        if (guildConfig.kamaNotifyChannelId) {
            try {
                const { sendChannelMessage } = await import("@/server/discord");
                const profile = await db.userProfile.findFirst({
                    where: { id: user.profileId!, guildId: guildConfig.id },
                    select: { discordNickname: true, pseudoDofus: true, user: { select: { name: true } } },
                });
                const userName = profile?.discordNickname || profile?.pseudoDofus || profile?.user?.name || "Un membre";
                const dashUrl = `${process.env.NEXT_PUBLIC_APP_URL}/dashboard/${input.guildId}/admin/validation`;
                const absoluteImageUrl = getDiscordPublicUrl(uploadResult.url);
                const mentionRole = (guildConfig as any).kamaNotifyRoleId;
                const content = mentionRole ? (mentionRole === "everyone" ? "Bonjour @everyone !" : `Bonjour <@&${mentionRole}> !`) : "Bonjour le Staff !";

                const discordMsgId = await sendChannelMessage(guildConfig.kamaNotifyChannelId, content, {
                    embedTitle: "💰 Nouvelle Contribution Kamas",
                    embedDescription: `**${userName}** a soumis un don de **${requestedAmount.toLocaleString("fr-FR")} kamas** (${parsed.data.tranches} tranche${parsed.data.tranches > 1 ? "s" : ""}).`,
                    embedColor: 0xeab308,
                    embedUrl: dashUrl,
                    embedImage: absoluteImageUrl,
                    embedFooter: "SigilOS • Contributions Kamas",
                    components: [
                        {
                            type: 1,
                            components: [
                                { type: 2, style: 3, label: "✅ Valider", custom_id: `validate:kama:${donation.id}:${input.guildId}` },
                                { type: 2, style: 4, label: "❌ Rejeter", custom_id: `validate:kama_reject:${donation.id}:${input.guildId}` },
                            ],
                        },
                    ],
                });

                // Save discordMessageId for later deletion on validation/rejection
                if (discordMsgId) {
                    await kamaDb.kamaDonation.update({
                        where: { id: donation.id },
                        data: { discordMessageId: `${guildConfig.kamaNotifyChannelId}:${discordMsgId}` },
                    });
                }
            } catch (discordError) {
                logger.error("[KamaDonation] Discord Notification Error", { error: discordError });
            }
        }

        return { success: true, data: { id: donation.id } };
    } catch (error) {
        logger.error("submitKamaDonation error", { error, guildId: input.guildId });
        return { success: false, error: "Erreur serveur" };
    }
}

// ============================================================================
