                const isInVacation = !!(p.vacationStart && p.vacationEnd && now >= p.vacationStart && now <= p.vacationEnd);
                return {
                    rank: idx + 1,
                    profileId: p.id,
                    discordNickname: p.discordNickname,
                    discordRoleColor: p.discordRoleColor,
                    discordImage: p.user.image,
                    pseudoDofus: p.pseudoDofus,
                    classe: p.classe,
                    value: p.contributionPoints || 0,
                    isAdmin: p.discordRoleName === "Administrateur" || adminRoleNames.has(p.discordRoleName ?? ""),
                    isInVacation
                };
            });
        });

        const totalCount = allRankedData.length;
        const entries = allRankedData.slice(skip, skip + pageSize).map((item: any) => ({
            ...item,
            isCurrentUser: item.profileId === currentProfile?.id
        }));

        return {
            success: true,
            data: {
                entries,
                totalCount,
                totalPages: Math.ceil(totalCount / pageSize),
                currentPage: page
            }
        };
    } catch (error) {
        console.error("[getContributionLadder] Error:", error);
        return { success: false, error: "Erreur lors du chargement du classement de contribution" };
    }
}

/**
 * Get Guildatons Ladder (Guild currency ranking)
 * @param view "weekly", "monthly", or "alltime"
 */
export async function getGuildatonsLadder(
    guildId: string,
    view: ActivityView = "alltime",
    page: number = 1,
    pageSize: number = 25
): Promise<ActionResponse<LadderResponse>> {
    try {
        const session = await auth();
        if (!session?.user?.id) {
            return { success: false, error: "Non authentifié" };
        }

        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true, rolesMapping: true }
        });

        if (!guildConfig) {
            return { success: false, error: "Guilde non trouvée" };
        }

        const currentProfile = await db.userProfile.findFirst({
            where: { userId: session.user.id, guildId: guildConfig.id }
        });

        const rolesMapping = (guildConfig.rolesMapping as Record<string, string[]>) || {};
        const adminRoleNames = new Set<string>();
        for (const [roleId, perms] of Object.entries(rolesMapping)) {
            if (perms.includes("admin:access")) adminRoleNames.add(roleId);
        }

        const skip = (page - 1) * pageSize;

        if (view === "weekly" || view === "monthly") {
            let startDate: Date;
            if (view === "weekly") {
                const now = new Date();
                const daysSinceTuesday = (now.getDay() + 7 - 2) % 7;
                const tuesday = new Date(now);
                tuesday.setDate(now.getDate() - daysSinceTuesday);
                tuesday.setHours(7, 0, 0, 0);
                if (now < tuesday) tuesday.setDate(tuesday.getDate() - 7);
                startDate = tuesday;
            } else {
                const now = new Date();
                startDate = new Date(now.getFullYear(), now.getMonth(), 1, 0, 0, 0, 0);
            }

            const cacheKey = `ladder:guildatons:${guildId}:${view}:${startDate.getTime()}`;
            const allRankedData = await withCache(cacheKey, 300, async () => {
                const { KAMA_TRANCHE, REWARDS_PER_TRANCHE } = await import("@/lib/kama-constants");
                
                const activeProfiles = await db.userProfile.findMany({
                    where: { guildId: guildConfig.id, status: "ACTIVE" },
                    select: {
                        id: true,
                        discordNickname: true,
                        discordRoleColor: true,
                        discordRoleName: true,
                        discordJoinedAt: true,
                        pseudoDofus: true,
                        classe: true,
                        vacationStart: true,
                        vacationEnd: true,
                        user: { select: { image: true } }
                    }
                });

                const guildatonsByProfile = await db.$queryRaw<{ profileId: string; total: number }[]>`
                    WITH MissionG AS (
                        SELECT s."profileId", COALESCE(SUM(m."guildatonsReward"), 0)::int AS g
                        FROM "Submission" s
                        JOIN "Mission" m ON s."missionId" = m."id"
                        JOIN "UserProfile" up ON s."profileId" = up."id"
                        WHERE s."status" = 'VALIDATED'
                          AND s."updatedAt" >= ${startDate}
                          AND up."guildId" = ${guildConfig.id}
                        GROUP BY s."profileId"
                    ),
                    KamaG AS (
                        SELECT k."profileId", COALESCE(SUM(FLOOR(k."amount" / ${KAMA_TRANCHE}) * ${REWARDS_PER_TRANCHE.guildatons || 0}), 0)::int AS g
                        FROM "KamaDonation" k
                        JOIN "UserProfile" up ON k."profileId" = up."id"
                        WHERE k."status" = 'VALIDATED'
                          AND k."validatedAt" >= ${startDate}
                          AND up."guildId" = ${guildConfig.id}
                        GROUP BY k."profileId"
                    ),
                    CombinedG AS (
                        SELECT "profileId", g FROM MissionG
                        UNION ALL
                        SELECT "profileId", g FROM KamaG
                    )
                    SELECT "profileId", COALESCE(SUM(g), 0)::int AS "total"
                    FROM CombinedG
                    GROUP BY "profileId"
                `;

                const guildatonsMap = new Map(guildatonsByProfile.map(g => [g.profileId, g.total]));

                const ranked = activeProfiles
                    .map((p: any) => {
                        const now = new Date();
                        const isInVacation = !!(p.vacationStart && p.vacationEnd && now >= p.vacationStart && now <= p.vacationEnd);
                        return {
                            ...p,
                            val: guildatonsMap.get(p.id) || 0,
                            isInVacation
                        };
                    })
                    .sort((a, b) => {
                        if (b.val !== a.val) return b.val - a.val;
                        return (a.discordJoinedAt?.getTime() || Infinity) - (b.discordJoinedAt?.getTime() || Infinity);
                    });

                return ranked.map((p: any, idx) => ({
                    rank: idx + 1,
                    profileId: p.id,
                    discordNickname: p.discordNickname,
                    discordRoleColor: p.discordRoleColor,
                    discordImage: (p as any).user?.image,
                    pseudoDofus: p.pseudoDofus,
                    classe: p.classe,
                    value: p.val,
                    isAdmin: p.discordRoleName === "Administrateur" || adminRoleNames.has(p.discordRoleName ?? ""),
                    isInVacation: p.isInVacation
                }));
            });

            const totalCount = allRankedData.length;
            const paginatedData = allRankedData.slice(skip, skip + pageSize).map((item: any) => ({
                ...item,
                isCurrentUser: item.profileId === currentProfile?.id
            }));

            return {
                success: true,
                data: {
                    entries: paginatedData,
                    totalCount,
                    totalPages: Math.ceil(totalCount / pageSize),
                    currentPage: page
                }
            };
        } else {
            // All-time: cumulative logic
            const cacheKey = `ladder:guildatons:${guildId}:alltime`;
            const allRankedData = await withCache(cacheKey, 600, async () => {
                const profiles = await db.userProfile.findMany({
                    where: { guildId: guildConfig.id, status: "ACTIVE" },
                    select: {
                        id: true,
                        discordNickname: true,
                        discordRoleColor: true,
                        discordRoleName: true,
                        discordJoinedAt: true,
                        pseudoDofus: true,
                        classe: true,
                        guildatons: true,
                        vacationStart: true,
                        vacationEnd: true,
                        user: { select: { image: true } }
                    },
                    orderBy: [{ guildatons: "desc" }, { discordJoinedAt: "asc" }]
                });

                return profiles.map((p: any, idx) => {
                    const now = new Date();
                    const isInVacation = !!(p.vacationStart && p.vacationEnd && now >= p.vacationStart && now <= p.vacationEnd);
                    return {
                        rank: idx + 1,
                        profileId: p.id,
                        discordNickname: p.discordNickname,
                        discordRoleColor: p.discordRoleColor,
                        discordImage: p.user.image,
                        pseudoDofus: p.pseudoDofus,
                        classe: p.classe,
                        value: p.guildatons || 0,
                        isAdmin: p.discordRoleName === "Administrateur" || adminRoleNames.has(p.discordRoleName ?? ""),
                        isInVacation
                    };
                });
            });

            const totalCount = allRankedData.length;
            const paginatedData = allRankedData.slice(skip, skip + pageSize).map((item: any) => ({
                ...item,
                isCurrentUser: item.profileId === currentProfile?.id
            }));

            return {
                success: true,
                data: {
                    entries: paginatedData,
                    totalCount,
                    totalPages: Math.ceil(totalCount / pageSize),
                    currentPage: page
                }
            };
        }
    } catch (error) {
        console.error("[getGuildatonsLadder] Error:", error);
        return { success: false, error: "Erreur lors du chargement du classement de guildatons" };
    }
}

/**
 * Get Raid Ladder (Raids completed, counts by type, and scores)
 */
export async function getRaidLadder(
    guildId: string,
    raidType: "all" | "jardin" | "gigalodon" = "all",
    page: number = 1,
    pageSize: number = 25
): Promise<ActionResponse<LadderResponse>> {
    try {
        const session = await auth();
        if (!session?.user?.id) {
            return { success: false, error: "Non authentifié" };
        }

        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true, rolesMapping: true }
        });

        if (!guildConfig) {
            return { success: false, error: "Guilde non trouvée" };
        }

        const currentProfile = await db.userProfile.findFirst({
            where: { userId: session.user.id, guildId: guildConfig.id }
        });

        const skip = (page - 1) * pageSize;

        // Fetch completed raid events
        const completedRaids = await db.guildEvent.findMany({
            where: {
                guildId: guildConfig.id,
                type: "RAID_OFFICIAL",
                status: "COMPLETED"
            },
            select: {
                id: true,
                metadata: true,
                participants: {
                    select: {
                        userId: true,
                        classe: true
                    }
                }
            }
        });

        // Calculate stats per user
        const statsByUser = new Map<string, {
            userId: string;
            totalCount: number;
            jardinCount: number;
            gigalodonCount: number;
            totalScore: number;
            scoreCount: number;
            classe: string | null;
        }>();

        for (const raid of completedRaids) {
            const meta = raid.metadata as any;
            const type = meta?.raidType || "jardin";
            const scoreStr = meta?.raidScore;
            
            let scoreVal = 0;
            if (scoreStr) {
                const cleaned = scoreStr.replace(/[^\d]/g, "");
                const parsed = parseInt(cleaned);
                if (!isNaN(parsed)) {
                    scoreVal = parsed;
                }
            }

            let participantUserIds: string[] = [];
            if (meta?.raidPresentUserIds && Array.isArray(meta.raidPresentUserIds) && meta.raidPresentUserIds.length > 0) {
                participantUserIds = meta.raidPresentUserIds;
            } else {
                participantUserIds = raid.participants.map(p => p.userId);
            }

            for (const userId of participantUserIds) {
                const pObj = raid.participants.find(p => p.userId === userId);
                const classUsed = pObj?.classe || null;

                let stats = statsByUser.get(userId);
                if (!stats) {
                    stats = {
                        userId,
                        totalCount: 0,
                        jardinCount: 0,
                        gigalodonCount: 0,
                        totalScore: 0,
                        scoreCount: 0,
                        classe: classUsed
                    };
                    statsByUser.set(userId, stats);
                }

                if (classUsed && !stats.classe) {
                    stats.classe = classUsed;
                }

                if (raidType === "all" || raidType === type) {
                    stats.totalCount += 1;
                    if (type === "jardin") {
                        stats.jardinCount += 1;
                    } else if (type === "gigalodon") {
                        stats.gigalodonCount += 1;
                    }

                    if (scoreVal > 0) {
                        stats.totalScore += scoreVal;
                        stats.scoreCount += 1;
                    }
                }
            }
        }

        const profiles = await db.userProfile.findMany({
            where: {
                guildId: guildConfig.id,
                status: "ACTIVE"
            },
            select: {
                id: true,
                userId: true,
                discordNickname: true,
                discordRoleColor: true,
                discordRoleName: true,
                discordJoinedAt: true,
                pseudoDofus: true,
                classe: true,
                vacationStart: true,
                vacationEnd: true,
                user: {
                    select: { image: true }
                }
            }
        });

        const rolesMapping = (guildConfig.rolesMapping as Record<string, string[]>) || {};
        const adminRoleNames = new Set<string>();
        for (const [roleId, perms] of Object.entries(rolesMapping)) {
            if (perms.includes("admin:access")) adminRoleNames.add(roleId);
        }

        const now = new Date();
        const entries = profiles
            .map((p) => {
                const stats = statsByUser.get(p.userId);
                const isInVacation = !!(p.vacationStart && p.vacationEnd && now >= p.vacationStart && now <= p.vacationEnd);
                const value = stats ? stats.totalCount : 0;

                return {
                    profileId: p.id,
                    discordNickname: p.discordNickname,
                    discordRoleColor: p.discordRoleColor,
                    discordImage: p.user.image,
                    pseudoDofus: p.pseudoDofus,
                    classe: stats?.classe || p.classe,
                    value: value,
                    isAdmin: p.discordRoleName === "Administrateur" || adminRoleNames.has(p.discordRoleName ?? ""),
                    isInVacation,
                    jardinCount: stats ? stats.jardinCount : 0,
                    gigalodonCount: stats ? stats.gigalodonCount : 0,
                    averageScore: stats && stats.scoreCount > 0 ? (stats.totalScore / stats.scoreCount) : 0
                };
            })
            .filter(entry => raidType === "all" || entry.value > 0)
            .sort((a, b) => {
                if (b.value !== a.value) return b.value - a.value;
                if (b.averageScore !== a.averageScore) return b.averageScore - a.averageScore;
                return (a.discordNickname || "").localeCompare(b.discordNickname || "");
            })
            .map((entry, idx) => ({
                ...entry,
                rank: idx + 1
            }));

        const totalCount = entries.length;
        const paginatedData = entries.slice(skip, skip + pageSize).map((item) => ({
            ...item,
            isCurrentUser: item.profileId === currentProfile?.id
        }));

        return {
            success: true,
            data: {
                entries: paginatedData,
                totalCount,
                totalPages: Math.ceil(totalCount / pageSize),
                currentPage: page
            }
        };
    } catch (error) {
        console.error("[getRaidLadder] Error:", error);
        return { success: false, error: "Erreur lors du chargement du classement des raids" };
    }
}

/**
 * Member Lifecycle Actions
 * Server actions for managing archived profiles and RGPD compliance
 */

"use server";

import { db } from "@/lib/prisma";
import { getUserContext, invalidateUserContextCache } from "./user-actions";
import { revalidatePath } from "next/cache";
import { Prisma } from "@prisma/client";
import { createAuditLog } from "./audit-actions";
import { auth } from "@/auth";

/**
 * Archive a profile (Self-service or Admin)
 */
export async function archiveProfile(guildId: string, profileId?: string, durationMonths?: number) {
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated) return { success: false, error: "Unauthorized" };

    const targetProfileId = profileId || ctx.profileId;
    if (!targetProfileId) return { success: false, error: "No profile found" };

    // Security check: Only self or manager can archive
    if (targetProfileId !== ctx.profileId && !ctx.canManageMembers) {
        return { success: false, error: "Forbidden" };
    }

    // 🔒 Prevent archival of the Discord guild owner
    const guildConfig = await db.guildConfig.findUnique({
        where: { discordGuildId: guildId },
        select: { ownerId: true }
    });

    const targetProfile = await db.userProfile.findUnique({
        where: { id: targetProfileId },
        include: {
            user: {
                include: {
                    accounts: {
                        where: { provider: "discord" },
                        select: { providerAccountId: true }
                    }
                }
            }
        }
    });

    if (targetProfile) {
        const targetDiscordId = targetProfile.user.accounts[0]?.providerAccountId;
        if (guildConfig?.ownerId && targetDiscordId && guildConfig.ownerId === targetDiscordId) {
            return { success: false, error: "Le propriétaire du serveur Discord ne peut pas être archivé. Transférez la propriété sur Discord d'abord." };
        }
    }

    try {
        // Admin Departure Log : Specific high-priority log if an admin leaves
        const userContext = await getUserContext(guildId);
        if (userContext.isAdmin && targetProfileId === ctx.profileId) { // Only log if the admin is archiving their own profile
            await createAuditLog({
                guildId,
                action: "MEMBER_LEFT" as any,
                actorUserId: ctx.id as string,
                actorName: ctx.name ?? "Inconnu",
                targetType: "ADMIN_ACTION" as any,
                metadata: {
                    priority: "HIGH",
                    description: `DÉPART CRITIQUE : L'administrateur ${ctx.name ?? ctx.id} a quitté la guilde.`,
                    impact: "Perte de privilèges administratifs"
                }
            });
        }

        const duration = durationMonths || 3; // Default to 3 months for self archival
        const days = duration * 30.5;
        const scheduledDeletion = new Date(Date.now() + Math.floor(days * 24 * 60 * 60 * 1000));

        const updatedProfile = await db.userProfile.update({
            where: { id: targetProfileId },
            include: { user: { include: { accounts: { where: { provider: "discord" }, select: { providerAccountId: true } } } } },
            data: {
                status: "ARCHIVED",
                archivedAt: new Date(),
                archiveReason: profileId ? "ADMIN_ACTION" : "USER_LEAVE",
                archiveDuration: duration,
                scheduledDeletion,
                reactivationRequestedAt: null,
                reactivationRequestReason: null,
            }
        });

        // 🔔 Lifecycle Notification — self-archive or admin archive
        const actorName = profileId ? ctx.name ?? "Un administrateur" : undefined;
        await sendLifecycleNotification(guildId, updatedProfile, "ARCHIVED", actorName);

        // Invalidate Redis cache to prevent stale restricted access
        await invalidateUserContextCache(
            updatedProfile.userId, 
            updatedProfile.guildId, // Internal UUID
            guildId                 // Discord ID
        );

        await createAuditLog({
            guildId,
            action: "MEMBER_ARCHIVED" as any,
            actorUserId: ctx.id as string,
            actorName: ctx.name ?? "Inconnu",
            targetType: "PROFILE" as any,
            targetId: targetProfileId,
            metadata: {
                description: profileId ? "Archivage administratif" : "Mise en sommeil volontaire",
                reason: profileId ? `Action par ${ctx.name ?? "un admin"}` : "Action utilisateur"
            }
        });

        revalidatePath(`/dashboard/${guildId}`, "layout");
        revalidatePath(`/dashboard/${guildId}/profile`);
        revalidatePath(`/dashboard/${guildId}/admin/settings`);
        return { success: true };
    } catch (e) {
        console.error("Archive error:", e);
        return { success: false, error: "Database error" };
    }
}

// =============================================================================
// HELPER: Types for lifecycle notifications
// =============================================================================

type LifecycleEventType = "LEFT" | "BANNED" | "ARCHIVED" | "DELETED" | "REACTIVATED";

const LIFECYCLE_COLORS: Record<LifecycleEventType, number> = {
    LEFT: 0xf59e0b,       // Amber — left voluntarily
    BANNED: 0xef4444,     // Red — banned
    ARCHIVED: 0x6366f1,   // Indigo — archived
    DELETED: 0xdc2626,    // Strong Red — permanently deleted
    REACTIVATED: 0x10b981,// Green — reactivated
};

const LIFECYCLE_EMOJIS: Record<LifecycleEventType, string> = {
    LEFT: "📤",
    BANNED: "🚫",
    ARCHIVED: "💤",
    DELETED: "🗑️",
    REACTIVATED: "🔄",
};

const LIFECYCLE_TITLES: Record<LifecycleEventType, string> = {
    LEFT: "Membre Parti (Discord)",
    BANNED: "Membre Banni (Discord)",
    ARCHIVED: "Membre Archivé",
    DELETED: "Membre Supprimé",
    REACTIVATED: "Membre Réactivé",
};

/**
 * Helper to send lifecycle notifications to the configured Discord channel
 * Supports: LEFT, BANNED, ARCHIVED, DELETED, REACTIVATED
 * Shows: who did it, when, discord pseudo, avatar link, action type
 */
async function sendLifecycleNotification(
    guildId: string, 
    profile: any, 
    type: LifecycleEventType, 
    actorName?: string // undefined = action by the member themselves
) {
    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { lifecycleNotifyChannelId: true, name: true }
        });

        if (!guildConfig?.lifecycleNotifyChannelId) return;

        const { sendChannelMessage } = await import("@/server/discord");
        
        const color = LIFECYCLE_COLORS[type] || 0x6366f1;
        const emoji = LIFECYCLE_EMOJIS[type] || "📋";
        const title = `${emoji} ${LIFECYCLE_TITLES[type] || "Événement Membre"}`;
        
        const discordName = profile.user?.name || profile.discordNickname || "Inconnu";
        const dofusPseudo = profile.pseudoDofus;
        const displayName = dofusPseudo || discordName;
        
        // Avatar URL from Discord
        const userAvatar = profile.user?.image || undefined;

        // Determine actor info
        const isSelfAction = !actorName;
        const actionBy = isSelfAction 
            ? "👤 Par lui-même" 
            : `🛡️ Par **${actorName}**`;

        // Build description
        let statusLabel = "";
        let retentionInfo = "";
        switch (type) {
            case "ARCHIVED":
                statusLabel = "Archivé";
                retentionInfo = profile.scheduledDeletion 
                    ? `Suppression programmée le <t:${Math.floor(new Date(profile.scheduledDeletion).getTime() / 1000)}:f>`
                    : "Aucune date de suppression définie";
                break;
            case "LEFT":
                statusLabel = "Parti (Discord)";
                retentionInfo = "Profil archivé automatiquement lors de la synchro Discord";
                break;
            case "BANNED":
                statusLabel = "Banni";
                retentionInfo = "Données personnelles anonymisées immédiatement";
                break;
            case "DELETED":
                statusLabel = "Supprimé définitivement";
                retentionInfo = "Toutes les données liées ont été purgées";
                break;
            case "REACTIVATED":
                statusLabel = "Réactivé";
                retentionInfo = "Le membre a retrouvé l'accès à ses données";
                break;
        }

        const appUrl = process.env.NEXT_PUBLIC_APP_URL || "https://sigilos.fr";
        const rosterLink = `${appUrl}/dashboard/${guildId}/admin/members?status=${type === "REACTIVATED" ? "ACTIVE" : type === "DELETED" ? "archived" : type}`;

        // Build avatar URL for Discord embed author
        const discordId = profile.user?.accounts?.[0]?.providerAccountId;
        const discordAvatarUrl = discordId && userAvatar
            ? `https://cdn.discordapp.com/avatars/${discordId}/${userAvatar}.${userAvatar.startsWith("a_") ? "gif" : "png"}?size=128`
            : undefined;

        const fields = [
            { name: "Pseudo Dofus", value: dofusPseudo || "Non défini", inline: true },
            { name: "Nom Discord", value: discordName, inline: true },
            { name: "Nouveau Statut", value: `**${statusLabel}**`, inline: true },
            { name: "Action effectuée par", value: actionBy, inline: false },
        ];

        // Add retention info for non-deletion events
        if (type !== "DELETED" && type !== "REACTIVATED") {
            fields.push({ name: "Rétention des données", value: retentionInfo, inline: false });
        }

        // Add reactivation info
        if (type === "REACTIVATED") {
            fields.push({ name: "Raison", value: retentionInfo, inline: false });
        }
        
        // Add guild name context
        if (guildConfig?.name) {
            fields.push({ name: "Guilde", value: guildConfig.name, inline: false });
        }

        await sendChannelMessage(guildConfig.lifecycleNotifyChannelId, "", {
            embedTitle: title,
            embedDescription: `Le membre **${displayName}** a changé de statut dans la guilde.`,
            embedColor: color,
            embedThumbnail: discordAvatarUrl || userAvatar,
            embedAuthor: discordAvatarUrl ? {
                name: displayName,
                iconUrl: discordAvatarUrl,
            } : undefined,
            fields,
            embedFooter: `SigilOS · Lifecycle · ${new Date().toLocaleString("fr-FR", { timeZone: "Europe/Paris" })}`,
        });
    } catch (err) {
        console.error("[Lifecycle Notification] Failed:", err);
    }
}

/**
 * Hard delete a profile from a guild (Super Admin only)
 * Purges all guild-scoped data and invalidates active sessions.
 * If this is the user's only guild profile → full account deletion (email, OAuth, sessions).
 * For explicit RGPD wipe, use handleGdprDeletionRequest() instead.
 */
export async function deleteProfileByAdmin(guildId: string, profileId: string) {
    const ctx = await getUserContext(guildId);
    // Guild admins with canManageMembers can delete archived/banned profiles.
    // SuperAdmins can delete any profile (including active ones as a last resort).
    if (!ctx.isAuthenticated) return { success: false, error: "Non authentifié" };
    if (!ctx.canManageMembers && !ctx.isAdmin && !ctx.isSuperAdmin) {
        return { success: false, error: "Permission 'Gérer les membres' requise" };
    }

    try {
        const target = await db.userProfile.findUnique({
            where: { id: profileId },
            include: {
                user: {
                    include: {
                        profiles: { select: { id: true } },
                        accounts: { where: { provider: "discord" }, select: { providerAccountId: true } }
                    }
                }
            }
        });

        if (!target) return { success: false, error: "Profile not found" };

        // 🔒 Prevent self-deletion
        if (target.userId === ctx.id) {
            return { success: false, error: "Vous ne pouvez pas supprimer votre propre profil." };
        }

        // 🔒 Prevent deletion of the Discord guild owner
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { ownerId: true }
        });
        const targetDiscordId = target.user.accounts[0]?.providerAccountId;
        if (guildConfig?.ownerId && targetDiscordId && guildConfig.ownerId === targetDiscordId) {
            return { success: false, error: "Le propriétaire du serveur Discord ne peut pas être supprimé depuis SigilOS." };
        }

        // Send notification BEFORE deletion while we still have the profile data
        await sendLifecycleNotification(guildId, target, "DELETED", ctx.name ?? "Un administrateur");

        const targetUserId = target.userId;
        const hasOtherProfiles = target.user.profiles.length > 1;

        // 1. Delete the UserProfile — cascades to all guild-scoped data
        await db.userProfile.delete({ where: { id: profileId } });

        // 2. Invalidate ALL active sessions (force re-auth immediately)
        await db.session.deleteMany({ where: { userId: targetUserId } });

        // 3. If no other guild profiles → full account wipe (User + Account OAuth + Notifications)
        if (!hasOtherProfiles) {
            await db.user.delete({ where: { id: targetUserId } });
        }

        await createAuditLog({
            guildId,
            action: "MEMBER_PURGED" as any,
            actorUserId: ctx.id as string,
            actorName: ctx.name ?? "Inconnu",
            targetType: "PROFILE" as any,
            targetId: targetUserId,
            metadata: {
                description: `Purge définitive : ${target.user.name || profileId}`,
                reason: "Purge administrative Super Admin",
                fullAccountDeleted: !hasOtherProfiles,
                sessionsInvalidated: true
            }
        });

        revalidatePath(`/dashboard/${guildId}/admin/settings`);
        return { success: true };
    } catch (e) {
        console.error("Delete error:", e);
        return { success: false, error: "Database error" };
    }
}

/**
 * Reactivate an ARCHIVED or BANNED profile — accessible to guild admins (canManageMembers)
 * Creates an audit log and clears the archival flags.
 */
export async function reactivateProfileByAdmin(
    guildId: string,
    profileId: string,
    reason?: string
): Promise<{ success: boolean; error?: string }> {
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated) return { success: false, error: "Non authentifié" };
    if (!ctx.canManageMembers && !ctx.isAdmin && !ctx.isSuperAdmin) {
        return { success: false, error: "Permission 'Gérer les membres' requise" };
    }

    try {
        const profile = await db.userProfile.findUnique({
            where: { id: profileId },
            include: {
                user: {
                    include: {
                        accounts: { where: { provider: "discord" }, select: { providerAccountId: true } }
                    }
                }
            }
        });

        if (!profile) return { success: false, error: "Profil introuvable" };
        if (profile.status === "ACTIVE") return { success: false, error: "Ce profil est déjà actif" };

        const previousStatus = profile.status;

        const updated = await db.userProfile.update({
            where: { id: profileId },
            data: {
                status: "ACTIVE",
                archivedAt: null,
                archiveReason: null,
                scheduledDeletion: null,
                // Restore anonymized fields only if they were wiped by a ban
                ...(previousStatus === "BANNED" ? {
                    pseudoDofus: null,     // Force member to re-set their pseudo
                    discordNickname: null, // Will be re-fetched on next login
                    lastActivityDesc: `Réactiv(é·e) manuellement par ${ctx.name ?? "un admin"} le ${new Date().toLocaleDateString("fr-FR")}.`
                } : {})
            }
        });

        // 🔔 Lifecycle Notification — reactivation
        await sendLifecycleNotification(guildId, profile, "REACTIVATED", ctx.name ?? "Un administrateur");

        // Invalidate Redis cache to ensure the user sees their restored access immediately
        await invalidateUserContextCache(
            updated.userId, 
            guildId, 
            profile.user.accounts[0]?.providerAccountId
        );

        // Invalidate sessions so they must re-auth (picks up new ACTIVE status)
        await db.session.deleteMany({ where: { userId: profile.userId } });

        await createAuditLog({
            guildId,
            action: "PROFILE_REACTIVATED" as any,
            actorUserId: ctx.id as string,
            actorName: ctx.name ?? "Inconnu",
            targetType: "PROFILE" as any,
            targetId: profileId,
            metadata: {
                description: `Réintégration manuelle (ancien statut : ${previousStatus})`,
                reason: reason || `Décision de ${ctx.name ?? "un admin"}`,
                previousStatus
            }
        });

        revalidatePath(`/dashboard/${guildId}/admin`);
        revalidatePath(`/dashboard/${guildId}/admin/members`);
        return { success: true };
    } catch (e) {
        console.error("[Reactivate] Error:", e);
        return { success: false, error: "Erreur base de données" };
    }
}

// Retention periods in days
const RETENTION_DAYS = {
    USER_LEAVE: 90,    // Voluntary departure: 90 days
    LEFT: 90,          // Left via sync: 90 days
    ADMIN_ACTION: 30,  // Archived by admin: 30 days
    KICKED: 30,        // Wiped by admin: 30 days
    BANNED: 0,         // Already anonymized immediately
    GDPR_REQUEST: 0    // Immediate deletion on GDPR request
};

/**
 * Cleanup expired archived profiles
 * Should be called by a cron job (e.g., daily)
 */
export async function cleanupExpiredProfiles(discordGuildId: string) {
    const ctx = await getUserContext(discordGuildId);
    if (!ctx.isAdmin) {
        return { success: false, error: "Unauthorized" };
    }

    const guild = await db.guildConfig.findUnique({
        where: { discordGuildId },
        select: { id: true }
    });

    if (!guild) {
        return { success: false, error: "Guild not found" };
    }

    const now = new Date();
    let deletedCount = 0;

    // Process each retention type
    for (const [reason, days] of Object.entries(RETENTION_DAYS)) {
        if (days === 0) continue; // Skip immediate deletion types (already handled)

        const cutoffDate = new Date(now.getTime() - days * 24 * 60 * 60 * 1000);

        const result = await db.userProfile.deleteMany({
            where: {
                guildId: guild.id,
                status: "ARCHIVED",
                archiveReason: reason,
                archivedAt: { lt: cutoffDate }
            }
        });

        deletedCount += result.count;
    }

    return { success: true, deletedCount };
}

/**
 * Reactivate a profile when a member returns to the Discord
 * Called automatically in getUserContext when detecting a returning archived member
 */
export async function reactivateProfile(userId: string, guildInternalId: string) {
    const result = await db.userProfile.updateMany({
        where: {
            userId,
            guildId: guildInternalId,
            status: "ARCHIVED" // Only reactivate if archived, not if banned
        },
        data: {
            status: "ACTIVE",
            archivedAt: null,
            archiveReason: null
        }
    });

    return result.count > 0;
}

/**
 * Get archived profiles for admin review
 */
export async function getArchivedProfiles(discordGuildId: string) {
    const ctx = await getUserContext(discordGuildId);
    // canManageMembers is enough to view archived/banned profiles
    if (!ctx.canManageMembers && !ctx.isAdmin) {
        return { success: false, error: "Permission 'Gérer les membres' requise", profiles: [] };
    }

    const guild = await db.guildConfig.findUnique({
        where: { discordGuildId },
        select: { id: true }
    });

    if (!guild) {
        return { success: false, error: "Guild not found", profiles: [] };
    }

    const profiles = await db.userProfile.findMany({
        where: {
            guildId: guild.id,
            status: { in: ["ARCHIVED", "BANNED"] }
        },
        orderBy: { archivedAt: "desc" },
        take: 100,
        select: {
            id: true,
            userId: true,
            status: true,
            archivedAt: true,
            scheduledDeletion: true,
            user: {
                select: {
                    name: true,
                    image: true,
                    accounts: {
                        where: { provider: "discord" },
                        select: { providerAccountId: true }
                    }
                }
            }
        }
    });

    return { success: true, profiles };
}

/**
 * Handle GDPR deletion request (Right to be Forgotten)
 * Total platform purge
 */
export async function handleGdprDeletionRequest() {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Unauthorized" };

    const userId = session.user.id;

    try {
        // Get Discord ID for correct owner check
        const account = await db.account.findFirst({
            where: { userId, provider: "discord" }
        });
        const discordId = account?.providerAccountId;

        // Get all guilds where this user is active
        const userProfiles = await db.userProfile.findMany({
            where: { userId, status: "ACTIVE" },
            include: { 
                guild: true,
                user: {
                    include: {
                        accounts: { where: { provider: "discord" }, select: { providerAccountId: true } }
                    }
                }
            }
        });

        const { fetchGuild } = await import("@/server/discord");
        const { createAuditLog } = await import("./audit-actions");

        let ownedCount = 0;
        let blockedGuildName = "";

        // Send notifications BEFORE deletion while we still have profile data
        for (const profile of userProfiles) {
            await sendLifecycleNotification(profile.guild.discordGuildId, profile, "DELETED", "RGPD (Suppression de compte)");
        }

        for (const profile of userProfiles) {
            let currentOwnerId = (profile.guild as any).ownerId;

            // Self-healing: If ownerId is missing or we suspect it's outdated, fetch from Discord
            if (!currentOwnerId) {
                try {
                    const discordGuild = await fetchGuild(profile.guild.discordGuildId);
                    currentOwnerId = discordGuild.owner_id;

                    // Update DB with the real owner for future checks
                    await db.guildConfig.update({
                        where: { id: profile.guild.id },
                        data: { ownerId: currentOwnerId } as any
                    });
                } catch (err) {
                    console.error(`[GDPR Deletion] Failed to fetch owner from Discord for ${profile.guild.name}:`, err);
                }
            }

            // check if user is the owner
            if (currentOwnerId && (currentOwnerId === userId || currentOwnerId === discordId)) {
                ownedCount++;
                blockedGuildName = profile.guild.name;
            }

            // Create Audit Log BEFORE deletion so it persist in God Dashboard
            try {
                await createAuditLog({
                    guildId: profile.guild.discordGuildId,
                    actorUserId: userId,
                    actorName: profile.pseudoDofus || "Unknown User",
                    action: "USER_GDPR_DELETE" as any,
                    targetType: "USER",
                    targetId: userId,
                    metadata: {
                        reason: "RGPD Deletion Request",
                        discordId: discordId,
                        guildName: profile.guild.name
                    }
                });
            } catch (auditErr) {
                console.error(`[GDPR Deletion] Audit log failed for guild ${profile.guild.name}:`, auditErr);
                // Don't block deletion if audit log fails, but it's bad
            }
        }

        if (ownedCount > 0) {
            console.warn(`[GDPR Deletion] Blocked: User is technical owner of ${ownedCount} guilds`);
            return {
                success: false,
                error: `Impossible de supprimer : vous êtes propriétaire de ${ownedCount} guilde(s) (ex: ${blockedGuildName}). Transférez la propriété sur Discord d'abord.`
            };
        }

        // Supprimons simplement le user (Cascade s'occupe du reste)
        // Mais invalidons d'abord les caches pour éviter les sessions fantômes
        for (const profile of userProfiles) {
            await invalidateUserContextCache(userId, profile.guild.id, profile.guild.discordGuildId);
        }

        await db.user.delete({
            where: { id: userId }
        });

        return { success: true };
    } catch (e: any) {
        console.error("[GDPR Deletion] FATAL:", e);
        return {
            success: false,
            error: "Une erreur interne s'est produite lors de la suppression. Veuillez contacter un administrateur."
        };
    }
}

/**
 * ARCHIVE & SYNC GUILD MEMBERS
 * Compares Discord members with local profiles and archives members who are no longer in the guild.
 */
export async function syncGuildMembers(discordGuildId: string) {
    const ctx = await getUserContext(discordGuildId);
    if (!ctx.isAdmin) {
        return { success: false, error: "Unauthorized" };
    }

    try {
        const { listGuildMembers, fetchGuildBans } = await import("@/server/discord");

        // 1. Fetch current members from Discord
        const discordMembers = await listGuildMembers(discordGuildId);
        const discordUserIds = new Set(discordMembers.map(m => m.user.id));

        // 2. Fetch all profiles for this guild with their Discord Accounts
        const profiles = await db.userProfile.findMany({
            where: {
                guild: { discordGuildId },
                status: "ACTIVE"
            },
            include: {
                user: {
                    include: {
                        accounts: {
                            where: { provider: "discord" },
                            select: { providerAccountId: true }
                        }
                    }
                }
            }
        });

        // 3. Fetch current bans from Discord
        const discordBans = await fetchGuildBans(discordGuildId);
        const bannedUserIds = new Set(discordBans.map(b => b.user.id));

        let archivedCount = 0;
        let bannedCount = 0;

        // 4. Compare and archive/anonymize
        for (const profile of profiles) {
            const discordId = profile.user.accounts[0]?.providerAccountId;

            if (discordId && !discordUserIds.has(discordId)) {
                // Check if they are banned or just left
                const isBanned = bannedUserIds.has(discordId);

                if (isBanned) {
                    await db.userProfile.update({
                        where: { id: profile.id },
                        data: {
                            status: "BANNED",
                            archivedAt: new Date(),
                            archiveReason: "BANNED",
                            pseudoDofus: "Utilisateur banni",
                            discordNickname: "Anonyme",
                            metamobPseudo: null,
                            metamobVerified: false,
                            altPseudos: Prisma.JsonNull,
                            availability: Prisma.JsonNull,
                            vacationStart: null,
                            vacationEnd: null,
                            vacationNotify: false,
                            lastActivityDesc: "Détecté banni lors de la synchronisation. Données nettoyées.",
                            succes: Prisma.JsonNull,
                            metiers: Prisma.JsonNull,
                            classeSecondaires: Prisma.JsonNull,
                            dofusBookLinks: Prisma.JsonNull
                        }
                    });

                    // 🔔 Lifecycle Notification
                    await sendLifecycleNotification(discordGuildId, profile, "BANNED", "SYNC (Détection automatique)");

                    // 📝 AUDIT LOG Departure (Banned)
                    try {
                        const { createAuditLog: log } = await import("./audit-actions");
                        await log({
                            guildId: discordGuildId,
                            actorUserId: "SYSTEM",
                            actorName: "Sync System",
                            action: "MEMBER_BANNED" as any,
                            targetType: "PROFILE",
                            targetId: profile.id,
                            metadata: { 
                                description: profile.pseudoDofus || profile.discordNickname || "Inconnu",
                                reason: "Bannissement Discord détecté lors de la synchro"
                            }
                        });
                    } catch (e) { console.error("[Lifecycle Sync] Audit failed", e); }

                    bannedCount++;
                } else {
                    const twelveMonthsFromNow = new Date();
                    twelveMonthsFromNow.setFullYear(twelveMonthsFromNow.getFullYear() + 1);

                    await db.userProfile.update({
                        where: { id: profile.id },
                        data: {
                            status: "ARCHIVED",
                            archivedAt: new Date(),
                            archiveReason: "LEFT",
                            scheduledDeletion: twelveMonthsFromNow
                        }
                    });

                    // 🔔 Lifecycle Notification
                    await sendLifecycleNotification(discordGuildId, profile, "LEFT", "SYNC (Détection automatique)");

                    // 📝 AUDIT LOG Departure (Left)
                    try {
                        const { createAuditLog: log } = await import("./audit-actions");
                        await log({
                            guildId: discordGuildId,
                            actorUserId: "SYSTEM",
                            actorName: "Sync System",
                            action: "MEMBER_LEFT" as any,
                            targetType: "PROFILE",
                            targetId: profile.id,
                            metadata: { 
                                description: profile.pseudoDofus || profile.discordNickname || "Inconnu",
                                reason: "Départ Discord détecté lors de la synchro"
                            }
                        });
                    } catch (e) { console.error("[Lifecycle Sync] Audit failed", e); }

                    archivedCount++;
                }
            }
        }

        revalidatePath(`/dashboard/${discordGuildId}/admin`);
        return {
            success: true,
            message: `${archivedCount} archivés et ${bannedCount} nettoyés (bans) sur ${profiles.length} vérifiés.`,
            count: archivedCount + bannedCount
        };
    } catch (error) {
        console.error("[Lifecycle Sync] Error:", error);
        return { success: false, error: "Échec de la synchronisation" };
    }
}

/**
 * MANUAL WIPE (RGPD)
 */
export async function wipeUserProfile(profileId: string, discordGuildId: string) {
    const ctx = await getUserContext(discordGuildId);
    if (!ctx.isAdmin) {
        return { success: false, error: "Unauthorized" };
    }

    try {
        const profile = await db.userProfile.findUnique({
            where: { id: profileId },
            include: {
                user: {
                    include: {
                        accounts: { where: { provider: "discord" }, select: { providerAccountId: true } }
                    }
                }
            }
        });
        if (!profile) return { success: false, error: "Profil introuvable" };

        // 🔒 Prevent self-wipe
        if (profile.userId === ctx.id) {
            return { success: false, error: "Vous ne pouvez pas nettoyer votre propre profil." };
        }

        // 🔒 Prevent wiping the Discord guild owner
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId },
            select: { ownerId: true }
        });
        const targetDiscordId = profile.user?.accounts[0]?.providerAccountId;
        if (guildConfig?.ownerId && targetDiscordId && guildConfig.ownerId === targetDiscordId) {
            return { success: false, error: "Le propriétaire du serveur Discord ne peut pas être nettoyé depuis SigilOS." };
        }

        // 🔔 Lifecycle Notification — before anonymization
        await sendLifecycleNotification(discordGuildId, profile, "BANNED", ctx.name ?? "Un administrateur");

        await db.userProfile.update({
            where: { id: profileId },
            data: {
                status: "BANNED",
                archiveReason: "KICKED",
                pseudoDofus: "Utilisateur nettoyé",
                discordNickname: "Anonyme",
                metamobPseudo: null,
                metamobVerified: false,
                altPseudos: Prisma.JsonNull,
                availability: Prisma.JsonNull,
                vacationStart: null,
                vacationEnd: null,
                vacationNotify: false,
                succes: Prisma.JsonNull,
                metiers: Prisma.JsonNull,
                classeSecondaires: Prisma.JsonNull,
                dofusBookLinks: Prisma.JsonNull,
                lastActivityDesc: "Données nettoyées manuellement par un administrateur.",
            }
        });

        revalidatePath(`/dashboard/${discordGuildId}/admin`);
        return { success: true };
    } catch (error) {
        console.error("[Manual Wipe] Error:", error);
        return { success: false, error: "Erreur lors du nettoyage" };
    }
}

import { formatDofusPseudo } from "@/lib/utils";

/**
 * Request reactivation for an ARCHIVED profile (User action)
 */
export async function requestProfileReactivation(guildId: string, pseudo?: string, reason?: string) {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Non authentifié" };

    try {
        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true, missionValidationChannelId: true, missionNotifyChannelId: true, missionValidationNotifyRoleId: true }
        });

        if (!guildConfig) return { success: false, error: "Guilde introuvable" };

        const profile = await db.userProfile.findUnique({
            where: {
                userId_guildId: {
                    userId: session.user.id,
                    guildId: guildConfig.id
                }
            },
            include: { user: { select: { name: true, image: true } } }
        });

        if (!profile) return { success: false, error: "Profil introuvable" };
        if (profile.status !== "ARCHIVED") return { success: false, error: "Seuls les comptes archivés peuvent demander une réintégration." };

        // 🛡️ Protection anti-spam : Une seule demande à la fois
        if (profile.reactivationRequestedAt) {
            return { success: false, error: "Une demande de réintégration est déjà en cours de traitement par le Staff." };
        }

        // Validation stricte du pseudo (pas de chiffres ni caractères spéciaux sauf crochets)
        if (pseudo && /[^a-zA-Z\u00C0-\u017F\u00DF\u00FF\u0100-\u017F\s-\[\]]/.test(pseudo)) {
            return { success: false, error: "Le pseudo contient des caractères invalides (chiffres ou symboles)." };
        }

        const cleanPseudo = pseudo ? formatDofusPseudo(pseudo) : profile.pseudoDofus;

        // Uniqueness check if pseudo changed
        if (cleanPseudo && cleanPseudo !== profile.pseudoDofus) {
            const existing = await db.userProfile.findFirst({
                where: {
                    guildId: guildConfig.id,
                    pseudoDofus: { equals: cleanPseudo, mode: "insensitive" },
                    userId: { not: session.user.id }
                }
            });
            if (existing) return { success: false, error: `Le pseudo "${cleanPseudo}" est déjà utilisé par un autre membre.` };
        }

        // Update profile
        await db.userProfile.update({
            where: { id: profile.id },
            data: {
                pseudoDofus: cleanPseudo,
                reactivationRequestedAt: new Date(),
                reactivationRequestReason: reason || "Demande via le Dashboard"
            }
        });

        // 📝 Audit Log
        const ctx = await getUserContext(guildId);
        const finalName = cleanPseudo || ctx.name || session.user.name || "Membre";

        await createAuditLog({
            guildId,
            action: "MEMBER_JOIN_REQUEST" as any,
            actorUserId: session.user.id,
            actorName: finalName,
            targetType: "PROFILE" as any,
            targetId: profile.id,
            metadata: {
                description: "Demande de réintégration (Retour d'archive)",
                reason: reason || "Action utilisateur"
            }
        });

        // 🔔 Discord Notification
        try {
            const channelId = guildConfig.missionValidationChannelId || guildConfig.missionNotifyChannelId;
            if (channelId) {
                const { sendChannelMessage } = await import("@/server/discord");
                const mentionMode = guildConfig.missionValidationNotifyRoleId;
                const mention = mentionMode ? (mentionMode === "everyone" ? "@everyone" : `<@&${mentionMode}>`) : "Staff";

                await sendChannelMessage(channelId, `Bonjour ${mention} !`, {
                    embedTitle: "🔄 Demande de Réintégration",
                    embedDescription: `Le membre **${finalName}** souhaite réintégrer la guilde.`,
                    embedColor: 0x10b981, // Green
                    embedThumbnail: profile.user.image || undefined,
                    fields: [
                        { name: "Raison", value: reason || "Non précisée" },
                        { name: "Lien Admin", value: `${process.env.NEXT_PUBLIC_APP_URL || "https://sigilos.fr"}/dashboard/${guildId}/admin/validation?tab=retours` }
                    ],
                    components: [
                        {
                            type: 1, // Action Row
                            components: [
                                {
                                    type: 2, style: 3, // Success
                                    label: "✅ Approuver",
                                    custom_id: `validate:reactivation:approve:${profile.id}:${guildId}`,
                                },
                                {
                                    type: 2, style: 4, // Danger
                                    label: "❌ Refuser",
                                    custom_id: `validate:reactivation:reject:${profile.id}:${guildId}`,
                                },
                            ],
                        },
                    ]
                });
            }
        } catch (discordErr) {
            console.error("Discord notification failed for reactivation request:", discordErr);
        }

        revalidatePath(`/dashboard/${guildId}`);
        revalidatePath(`/dashboard/${guildId}/admin/validation`);
        return { success: true };
    } catch (e) {
        console.error("Request reactivation error:", e);
        return { success: false, error: "Erreur lors de la demande" };
    }
}

/**
 * Get pending reactivation requests for admin validation
 */
export async function getPendingReactivations(guildId: string) {
    const ctx = await getUserContext(guildId);
    if (!ctx.isAdmin && !ctx.canValidateMissions) {
        return { success: false, error: "Forbidden" };
    }

    try {
        const requests = await db.userProfile.findMany({
            where: {
                guild: { discordGuildId: guildId },
                status: "ARCHIVED",
                reactivationRequestedAt: { not: null }
            },
            select: {
                id: true,
                userId: true,
                pseudoDofus: true,
                discordNickname: true,
                reactivationRequestedAt: true,
                reactivationRequestReason: true,
                archiveReason: true,
                archivedAt: true,
                scheduledDeletion: true,
                user: {
                    select: {
                        name: true,
                        image: true
                    }
                }
            },
            orderBy: { reactivationRequestedAt: "desc" }
        });

        return { success: true, data: requests };
    } catch (e) {
        console.error("Fetch pending reactivations error:", e);
        return { success: false, error: "Database error" };
    }
}

"use server";

import { db } from "@/lib/prisma";
import { getUserContext, type ActionResponse } from "./user-actions";
import { logServiceActivity } from "./activity-log-actions";
import { revalidatePath } from "next/cache";
import { z } from "zod";
import { LoanType, LoanStatus } from "@prisma/client";
import { sendChannelMessage, validateChannelBelongsToGuild } from "@/server/discord";
import { unlink } from "fs/promises";
import { existsSync } from "fs";
import path from "path";

// ---------------------------------------------------------------------------
// HELPERS
// ---------------------------------------------------------------------------

async function getDiscordId(userId: string): Promise<string | null> {
    const account = await db.account.findFirst({
        where: { userId, provider: "discord" },
        select: { providerAccountId: true },
    });
    return account?.providerAccountId ?? null;
}

import { LOAN_TYPE_LABELS, LOAN_STATUS_LABELS } from "./services-constants";
import { hashImage } from "@/lib/llm-ocr";
import { getDiscordPublicUrl } from "@/lib/storage-utils";

const profileSelect = {
    id: true,
    pseudoDofus: true,
    discordNickname: true,
    userId: true,
    user: { select: { name: true, image: true } },
};

// ---------------------------------------------------------------------------
// TYPES
// ---------------------------------------------------------------------------

export type LoanWithProfiles = {
    id: string;
    guildId: string;
    type: LoanType;
    status: LoanStatus;
    description: string;
    amount: string | null;
    proofUrl: string | null;
    returnProofUrl: string | null;
    linkedItemName: string | null;
    linkedItemIconUrl: string | null;
    lentAt: Date;
    dueDate: Date | null;
    returnedAt: Date | null;
    notes: string | null;
    lender: {
        id: string;
        pseudoDofus: string | null;
        discordNickname: string | null;
        userId: string;
        user: { name: string | null; image: string | null };
    };
    borrower: {
        id: string;
        pseudoDofus: string | null;
        discordNickname: string | null;
        userId: string;
        user: { name: string | null; image: string | null };
    };
};

// ---------------------------------------------------------------------------
// SCHEMAS
// ---------------------------------------------------------------------------

const createLoanSchema = z.object({
    borrowerProfileId: z.string().min(1, "Sélectionnez un emprunteur"),
    type: z.nativeEnum(LoanType),
    description: z.string().min(3, "Description requise (min 3 car.)").max(200),
    amount: z.string().max(100).optional().nullable(),
    dueDate: z.string().optional().nullable(),
    notes: z.string().max(1000).optional().nullable(),
    linkedItemName: z.string().max(200).optional().nullable(),
    linkedItemIconUrl: z.string().url().optional().nullable(),
    notifyDiscord: z.boolean().optional().default(false),
});

// ---------------------------------------------------------------------------
// CRUD
// ---------------------------------------------------------------------------

export async function getLoans(
    guildId: string,
    filters?: { status?: LoanStatus; profileId?: string }
): Promise<ActionResponse<LoanWithProfiles[]>> {
    try {
        const user = await getUserContext(guildId);
        if (!user.isAuthenticated || !user.isMember || !user.canViewServices) {
            return { success: false, error: "Accès refusé" };
        }

        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true },
        });
        if (!guildConfig) return { success: false, error: "Guilde introuvable" };

        const where: any = { guildId: guildConfig.id };

        if (filters?.status) {
            where.status = filters.status;
        }
        if (filters?.profileId) {
            where.OR = [
                { lenderId: filters.profileId },
                { borrowerId: filters.profileId },
            ];
        }

        const loans = await db.guildLoan.findMany({
            where,
            include: {
                lender: { select: profileSelect },
                borrower: { select: profileSelect },
            },
            orderBy: [{ status: "asc" }, { lentAt: "desc" }],
        });

        return { success: true, data: loans as unknown as LoanWithProfiles[] };
    } catch (error) {
        console.error("[getLoans]", error);
        return { success: false, error: "Erreur interne" };
    }
}

export async function createLoan(
    guildId: string,
    input: z.infer<typeof createLoanSchema>,
    proofFormData?: FormData
): Promise<ActionResponse<{ id: string }>> {
    try {
        const user = await getUserContext(guildId);
        if (!user.isAuthenticated || !user.isMember || !user.canViewServices) {
            return { success: false, error: "Accès refusé" };
        }
        if (!user.profileId) return { success: false, error: "Profil introuvable" };

        const parsed = createLoanSchema.safeParse(input);
        if (!parsed.success) {
            return { success: false, error: parsed.error.errors[0]?.message || "Données invalides" };
        }

        if (parsed.data.borrowerProfileId === user.profileId) {
            return { success: false, error: "Vous ne pouvez pas vous prêter à vous-même." };
        }

        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true, serviceLoansEnabled: true },
        });
        if (!guildConfig) return { success: false, error: "Guilde introuvable" };

        if (!guildConfig.serviceLoansEnabled && !user.isAdmin) {
            return { success: false, error: "Le service de prêts est actuellement en maintenance." };
        }

        // Verify borrower belongs to same guild
        const borrower = await db.userProfile.findUnique({
            where: { id: parsed.data.borrowerProfileId },
            select: { guildId: true },
        });
        if (!borrower || borrower.guildId !== guildConfig.id) {
            return { success: false, error: "L'emprunteur ne fait pas partie de cette guilde." };
        }

        // Handle proof upload
        let proofUrl: string | null = null;
        let finalImageHash: string | null = null;

        if (proofFormData) {
            const file = proofFormData.get("file") as File | null;
            if (file) {
                const buffer = Buffer.from(await file.arrayBuffer());
                finalImageHash = await hashImage(buffer);

                const existingHash = await db.imageHash.findFirst({
                    where: { hash: finalImageHash }
                });

                if (existingHash) {
                    return { success: false, error: "Cette image a déjà été utilisée pour une preuve dans l'application." };
                }

                const { uploadProofImage } = await import("./upload-actions");
                const uploadResult = await uploadProofImage(guildConfig.id, proofFormData);
                if (uploadResult.success && uploadResult.url) {
                    proofUrl = uploadResult.url;

                    // Store hash
                    await (db as any).imageHash.create({
                        data: {
                            guildId: guildConfig.id,
                            hash: finalImageHash,
                            sourceType: "LOAN",
                            sourceId: "PENDING", // Temporary
                            uploaderId: user.id!
                        }
                    });
                }
            }
        }

        const loan = await db.guildLoan.create({
            data: {
                guildId: guildConfig.id,
                lenderId: user.profileId,
                borrowerId: parsed.data.borrowerProfileId,
                type: parsed.data.type,
                description: parsed.data.description,
                amount: parsed.data.amount || null,
                proofUrl,
                dueDate: parsed.data.dueDate ? new Date(parsed.data.dueDate) : null,
                notes: parsed.data.notes || null,
                linkedItemName: parsed.data.linkedItemName || null,
                linkedItemIconUrl: parsed.data.linkedItemIconUrl || null,
            },
        });

        // Update image hash with the real sourceId
        if (proofUrl && finalImageHash) {
            await (db as any).imageHash.update({
                where: { hash: finalImageHash },
                data: { sourceId: loan.id }
            });
        }

        // Immutable activity log
        const borrowerProfile = await db.userProfile.findUnique({
            where: { id: parsed.data.borrowerProfileId },
            select: { pseudoDofus: true, discordNickname: true, userId: true, user: { select: { name: true, image: true } } },
        });
        const lenderProfile = await db.userProfile.findUnique({
            where: { id: user.profileId },
            select: { pseudoDofus: true, discordNickname: true, userId: true, user: { select: { name: true, image: true } } },
        });
        const borrowerName = borrowerProfile?.pseudoDofus || borrowerProfile?.discordNickname || borrowerProfile?.user?.name || "Membre";
        const lenderName = lenderProfile?.pseudoDofus || lenderProfile?.discordNickname || lenderProfile?.user?.name || "Membre";

        await logServiceActivity({
            guildId: guildConfig.id,
            actorId: user.profileId,
            module: "LOAN",
            action: "CREATED",
            entityId: loan.id,
            summary: `Prêt créé : ${parsed.data.description} → ${borrowerName}`,
            details: JSON.stringify({ type: parsed.data.type, amount: parsed.data.amount, borrowerId: parsed.data.borrowerProfileId }),
            metadata: proofUrl ? JSON.stringify({ proofUrl }) : undefined,
        });

        // ── Discord Embed ──────────────────────────────────────────────────────
        if (parsed.data.notifyDiscord) {
            try {
                const guildFull = await db.guildConfig.findUnique({
                    where: { id: guildConfig.id },
                    select: { discordGuildId: true, loansNotifyChannelId: true },
                });
                const channelId = guildFull?.loansNotifyChannelId;

                if (channelId) {
                    // SECURITY: Validate channel belongs to this guild
                    const valid = await validateChannelBelongsToGuild(channelId, guildId);
                    if (valid) {
                        const appUrl = process.env.NEXT_PUBLIC_APP_URL || "https://sigilos.fr";
                        const dashboardUrl = `${appUrl}/dashboard/${guildId}/services`;
                        // Discord needs an absolute URL with access token
                        const publicProofUrl = getDiscordPublicUrl(proofUrl);

                        // Discord mentions
                        const lenderDiscordId = await getDiscordId(lenderProfile?.userId || "").catch(() => null);
                        const borrowerDiscordId = await getDiscordId(borrowerProfile?.userId || "").catch(() => null);
                        const lenderMention = lenderDiscordId ? `<@${lenderDiscordId}>` : lenderName;
                        const borrowerMention = borrowerDiscordId ? `<@${borrowerDiscordId}>` : borrowerName;

                        const fields = [
                            { name: "📝 Description", value: parsed.data.description, inline: false },
                            { name: "💰 Montant / Quantité", value: parsed.data.amount || "_Non précisé_", inline: true },
                            { name: "📅 Échéance", value: parsed.data.dueDate ? new Date(parsed.data.dueDate).toLocaleDateString("fr-FR") : "_Aucune_", inline: true },
                            { name: "⚖️ Type", value: LOAN_TYPE_LABELS[parsed.data.type] ?? parsed.data.type, inline: true },
                            { name: "📎 Prêteur", value: lenderMention, inline: true },
                            { name: "🏦 Emprunteur", value: borrowerMention, inline: true },
                        ];

                        if (parsed.data.linkedItemName) {
                            fields.push({ name: "📦 Item lié", value: parsed.data.linkedItemName, inline: true });
                        }
                        fields.push({ name: "🔗 Voir sur le dashboard", value: `[Ouvrir SigilOS](${dashboardUrl})`, inline: false });

                        await sendChannelMessage(
                            channelId,
                            "",
                            {
                                embedTitle: `🤝 Nouveau prêt — ${parsed.data.description}`,
                                embedColor: 0xf59e0b,
                                embedFooter: "SigilOS • Coffre & Prêts",
                                embedThumbnail: parsed.data.linkedItemIconUrl || undefined,
                                embedImage: publicProofUrl,
                                fields,
                            }
                        );
                    } else {
                        console.warn(`[createLoan] Channel ${channelId} invalid for guild ${guildId}, skipping Discord notify`);
                    }
                }
            } catch (discordErr) {
                // Non-blocking: Discord failure must not break the loan creation
                console.error("[createLoan] Discord notify failed:", discordErr);
            }
        }

        revalidatePath(`/dashboard/${guildId}/services`);
        return { success: true, data: { id: loan.id } };
    } catch (error) {
        console.error("[createLoan]", error);
        return { success: false, error: "Erreur interne" };
    }
}

export async function markLoanReturned(
    guildId: string,
    loanId: string,
    returnProofFormData?: FormData,
    partial?: boolean
): Promise<ActionResponse> {
    try {
        const user = await getUserContext(guildId);
        if (!user.isAuthenticated || !user.isMember) {
            return { success: false, error: "Accès refusé" };
        }

        const loan = await db.guildLoan.findUnique({
            where: { id: loanId },
            select: { lenderId: true, borrowerId: true, status: true, guildId: true },
        });
        if (!loan) return { success: false, error: "Prêt introuvable" };
        if (loan.lenderId !== user.profileId && !user.isAdmin) {
            return { success: false, error: "Seul le prêteur ou un admin peut marquer ce prêt comme rendu." };
        }
        if (loan.status === "RETURNED" || loan.status === "CANCELLED") {
            return { success: false, error: "Ce prêt est déjà clos." };
        }

        let returnProofUrl: string | null = null;
        if (returnProofFormData) {
            const file = returnProofFormData.get("file") as File | null;
            if (file) {
                const buffer = Buffer.from(await file.arrayBuffer());
                const imageHash = await hashImage(buffer);

                const existingHash = await db.imageHash.findFirst({
                    where: { hash: imageHash }
                });

                if (existingHash) {
                    return { success: false, error: "Cette image a déjà été utilisée pour une preuve dans l'application." };
                }

                const { uploadProofImage } = await import("./upload-actions");
                const uploadResult = await uploadProofImage(loan.guildId, returnProofFormData);
                if (uploadResult.success && uploadResult.url) {
                    returnProofUrl = uploadResult.url;

                    // Store hash
                    await (db as any).imageHash.create({
                        data: {
                            guildId: loan.guildId,
                            hash: imageHash,
                            sourceType: "LOAN_RETURN",
                            sourceId: loanId,
                            uploaderId: user.id!
                        }
                    });
                }
            }
        }

        await db.guildLoan.update({
            where: { id: loanId },
            data: {
                status: partial ? "PARTIAL" : "RETURNED",
                returnedAt: new Date(),
                ...(returnProofUrl && { returnProofUrl }),
            },
        });

        // Auto-cleanup: si RETURNED (pas PARTIAL), supprimer les screenshots du VPS
        if (!partial) {
            const loanForCleanup = await db.guildLoan.findUnique({
                where: { id: loanId },
                select: { proofUrl: true, returnProofUrl: true, guildId: true },
            });
            if (loanForCleanup) {
                const urlsToDelete = [loanForCleanup.proofUrl, returnProofUrl || loanForCleanup.returnProofUrl].filter(Boolean) as string[];
                const { deleteProofFile } = await import("@/lib/storage-utils");
                for (const url of urlsToDelete) {
                    await deleteProofFile(url);
                }
                // Effacer les URLs en DB immédiatement
                await db.guildLoan.update({
                    where: { id: loanId },
                    data: { proofUrl: null, returnProofUrl: null },
                });
            }
        }

        // Immutable activity log
        if (user.profileId) {
            await logServiceActivity({
                guildId: loan.guildId,
                actorId: user.profileId,
                module: "LOAN",
                action: partial ? "PARTIAL_RETURN" : "RETURNED",
                entityId: loanId,
                summary: `Prêt marqué comme ${partial ? "partiellement rendu" : "rendu"}`,
                metadata: returnProofUrl ? JSON.stringify({ returnProofUrl }) : undefined,
            });
        }

        revalidatePath(`/dashboard/${guildId}/services`);
        return { success: true };
    } catch (error) {
        console.error("[markLoanReturned]", error);
        return { success: false, error: "Erreur interne" };
    }
}

export async function cancelLoan(
    guildId: string,
    loanId: string
): Promise<ActionResponse> {
    try {
        const user = await getUserContext(guildId);
        if (!user.isAuthenticated || !user.isMember) {
            return { success: false, error: "Accès refusé" };
        }

        const loan = await db.guildLoan.findUnique({
            where: { id: loanId },
            select: { lenderId: true, status: true, guildId: true },
        });
        if (!loan) return { success: false, error: "Prêt introuvable" };
        if (loan.lenderId !== user.profileId && !user.isAdmin) {
            return { success: false, error: "Seul le prêteur ou un admin peut annuler ce prêt." };
        }

        // Auto-cleanup: supprimer les screenshots lors de l'annulation
        const loanForCleanup = await db.guildLoan.findUnique({
            where: { id: loanId },
            select: { proofUrl: true, returnProofUrl: true, guildId: true },
        });

        await db.guildLoan.update({
            where: { id: loanId },
            data: { status: "CANCELLED" },
        });

        if (loanForCleanup) {
            const urlsToDelete = [loanForCleanup.proofUrl, loanForCleanup.returnProofUrl].filter(Boolean) as string[];
            const { deleteProofFile } = await import("@/lib/storage-utils");
            for (const url of urlsToDelete) {
                await deleteProofFile(url);
            }
            await db.guildLoan.update({
                where: { id: loanId },
                data: { proofUrl: null, returnProofUrl: null },
            });
        }

        // Immutable activity log
        if (user.profileId) {
            await logServiceActivity({
                guildId: loan.guildId,
                actorId: user.profileId,
                module: "LOAN",
                action: "CANCELLED",
                entityId: loanId,
                summary: `Prêt annulé (par ${user.isAdmin && loan.lenderId !== user.profileId ? "admin" : "le prêteur"})`,
            });
        }

        revalidatePath(`/dashboard/${guildId}/services`);
        return { success: true };
    } catch (error) {
        console.error("[cancelLoan]", error);
        return { success: false, error: "Erreur interne" };
    }
}

"use server";

import { db } from "@/lib/prisma";
import { auth } from "@/auth";
import { listGuildMembers, fetchGuildRoles, sendChannelMessage } from "@/server/discord";
import { getUserContext } from "./user-actions";
import { ActionResponse } from "./user-actions";
import { z } from "zod";
import { createAuditLog } from "./audit-actions";
import { redis } from "@/lib/redis";

export type MemberReconciliationData = {
    discordId: string;
    username: string;
    displayName: string;
    roles: string[];
    joinedAt: string | null;
    isBot: boolean;
    hasDashboardProfile: boolean;
    profileId?: string;
    ankamaId?: string | null;
    avatar?: string | null;
    discordMessageCountWeekly?: number;
    discordVoiceTimeWeekly?: number;
    discordMessageCountMonthly?: number;
    discordVoiceTimeMonthly?: number;
    discordMessageCountTotal?: number;
    discordVoiceTimeTotal?: number;
};

export type RoleStats = {
    roleId: string;
    roleName: string;
    roleColor: number;
    totalDiscord: number;
    totalDashboard: number;
    unregistered: number;
};

export async function getMemberReconciliation(guildId: string): Promise<ActionResponse<{
    members: MemberReconciliationData[];
    stats: RoleStats[];
    authorizedRoles: string[];
}>> {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Non authentifié" };
    if (!guildId) return { success: false, error: "ID de guilde manquant" };

    const ctx = await getUserContext(guildId);
    if (!ctx.isAdmin && !ctx.canManageMembers) {
        return { success: false, error: "Permission 'Gérer les membres' requise" };
    }

    try {
        const guild = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { id: true, rolesMapping: true }
        });

        if (!guild) return { success: false, error: "Guilde non configurée" };

        const [discordMembers, allRoles, dbProfiles] = await Promise.all([
            listGuildMembers(guildId, 1000) as Promise<any[]>,
            fetchGuildRoles(guildId, { excludeManaged: false }),
            db.userProfile.findMany({
                where: { guildId: guild.id, status: "ACTIVE" },
                select: { 
                    userId: true, 
                    id: true, 
                    ankamaId: true,
                    discordMessageCountWeekly: true,
                    discordVoiceTimeWeekly: true,
                    discordMessageCountMonthly: true,
                    discordVoiceTimeMonthly: true,
                    discordMessageCountTotal: true,
                    discordVoiceTimeTotal: true,
                    user: { 
                        select: { 
                            accounts: { 
                                where: { provider: "discord" }, 
                                select: { providerAccountId: true } 
                            } 
                        } 
                    } 
                }
            })
        ]);

        const roleMap = new Map(allRoles.map(r => [r.id, r]));
        const rolesMapping = (guild.rolesMapping as Record<string, string[]>) || {};
        
        // Roles that have at least one permission on the dashboard
        const authorizedRoleIds = Object.keys(rolesMapping).filter(rId => 
            Array.isArray(rolesMapping[rId]) && rolesMapping[rId].length > 0
        );

        // Map profiles by Discord ID
        const profileByDiscordId = new Map<string, { id: string, ankamaId?: string | null, discordMessageCountWeekly: number, discordVoiceTimeWeekly: number, discordMessageCountMonthly: number, discordVoiceTimeMonthly: number, discordMessageCountTotal: number, discordVoiceTimeTotal: number }>();
        dbProfiles.forEach(p => {
            const discordId = p.user.accounts[0]?.providerAccountId;
            if (discordId) profileByDiscordId.set(discordId, { 
                id: p.id, 
                ankamaId: p.ankamaId,
                discordMessageCountWeekly: p.discordMessageCountWeekly || 0,
                discordVoiceTimeWeekly: p.discordVoiceTimeWeekly || 0,
                discordMessageCountMonthly: p.discordMessageCountMonthly || 0,
                discordVoiceTimeMonthly: p.discordVoiceTimeMonthly || 0,
                discordMessageCountTotal: p.discordMessageCountTotal || 0,
                discordVoiceTimeTotal: p.discordVoiceTimeTotal || 0
            });
        });

        const reconciliation: MemberReconciliationData[] = discordMembers
            .filter((m: any) => !m.user.bot) // Exclude bots
            .filter((m: any) => m.roles.some((rId: string) => authorizedRoleIds.includes(rId))) // Only authorized roles
            .map((m: any) => ({
                discordId: m.user.id,
                username: m.user.username,
                displayName: m.nick || m.user.global_name || m.user.username,
                roles: m.roles,
                joinedAt: m.joined_at || null,
                isBot: !!m.user.bot,
                hasDashboardProfile: profileByDiscordId.has(m.user.id),
                profileId: profileByDiscordId.get(m.user.id)?.id,
                ankamaId: profileByDiscordId.get(m.user.id)?.ankamaId,
                avatar: m.user.avatar || null,
                discordMessageCountWeekly: profileByDiscordId.get(m.user.id)?.discordMessageCountWeekly || 0,
                discordVoiceTimeWeekly: profileByDiscordId.get(m.user.id)?.discordVoiceTimeWeekly || 0,
                discordMessageCountMonthly: profileByDiscordId.get(m.user.id)?.discordMessageCountMonthly || 0,
                discordVoiceTimeMonthly: profileByDiscordId.get(m.user.id)?.discordVoiceTimeMonthly || 0,
                discordMessageCountTotal: profileByDiscordId.get(m.user.id)?.discordMessageCountTotal || 0,
                discordVoiceTimeTotal: profileByDiscordId.get(m.user.id)?.discordVoiceTimeTotal || 0
            }));

        // Calculate Stats
        const stats: RoleStats[] = authorizedRoleIds.map((rId: string) => {
            const role = roleMap.get(rId);
            if (!role) return null;

            const discordInRole = reconciliation.filter(m => m.roles.includes(rId));
            const registeredInRole = discordInRole.filter(m => m.hasDashboardProfile);

            return {
                roleId: rId,
                roleName: role.name,
                roleColor: role.color,
                totalDiscord: discordInRole.length,
                totalDashboard: registeredInRole.length,
                unregistered: discordInRole.length - registeredInRole.length
            } as RoleStats;
        }).filter((s): s is RoleStats => s !== null);

        return {
            success: true,
            data: {
                members: reconciliation,
                stats: stats.sort((a, b) => b.totalDiscord - a.totalDiscord),
                authorizedRoles: authorizedRoleIds
            }
        };

    } catch (error) {
        console.error("[Member Actions] Reconciliation Error:", error);
        return { success: false, error: "Échec de la récupération des données" };
    }
}

const RosterReportSchema = z.object({
    guildId: z.string(),
    roleId: z.string(),
    channelId: z.string(),
    showMissingNames: z.boolean().default(true),
});

/**
 * Envoie un rapport d'audit d'inscription sur Discord.
 * Compare les membres Discord ayant un rôle spécifique avec les profils Dashboard actifs.
 */
export async function sendRosterAuditReport(rawData: z.infer<typeof RosterReportSchema>): Promise<ActionResponse> {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Non authentifié" };

    const validation = RosterReportSchema.safeParse(rawData);
    if (!validation.success) return { success: false, error: "Données invalides" };
    const { guildId, roleId, channelId, showMissingNames } = validation.data;

    const ctx = await getUserContext(guildId);
    if (!ctx.isAdmin && !ctx.canManageMembers) return { success: false, error: "Permission requise" };

    // --- RATE LIMITING (15 min per role) ---
    const rateLimitKey = `audit_report_ratelimit:${guildId}:${roleId}`;
    const lastSentStr = await redis.get(rateLimitKey);
    const lastSent = lastSentStr ? parseInt(lastSentStr, 10) : null;
    const nowTs = Date.now();
    const COOLDOWN = 15 * 60 * 1000; // 15 minutes

    if (lastSent && (nowTs - lastSent < COOLDOWN)) {
        const remainingMin = Math.ceil((COOLDOWN - (nowTs - lastSent)) / 60000);
        return { success: false, error: `Rapport déjà envoyé récemment. Réessayez dans ${remainingMin} min.` };
    }

    try {
        // 1. Récupérer les données de réconciliation
        const recon = await getMemberReconciliation(guildId);
        if (!recon.success || !recon.data) return { success: false, error: recon.error };

        const { members, stats } = recon.data;
        const roleStats = stats.find(s => s.roleId === roleId);

        if (!roleStats) return { success: false, error: "Statistiques introuvables pour ce rôle" };

        // 2. Identifier les manquants
        const missing = members
            .filter(m => m.roles.includes(roleId) && !m.hasDashboardProfile)
            .map(m => m.displayName || m.username);

        const totalInRole = roleStats.totalDiscord;
        const registered = roleStats.totalDashboard;
        const percent = totalInRole > 0 ? Math.round((registered / totalInRole) * 100) : 0;

        // Barre de progression visuelle (Format Premium)
        const filled = "🟩".repeat(Math.round(percent / 10));
        const empty = "⬜".repeat(10 - Math.round(percent / 10));

        const appUrl = process.env.NEXT_PUBLIC_APP_URL || "https://sigilos.fr";
        const dashboardUrl = `${appUrl}/dashboard/${guildId}`;

        // 3. Construction des champs visuels (colonnes)
        const fields: any[] = [];
        
        if (missing.length > 0) {
            if (missing.length <= 45) {
                // Construction en 3 colonnes pour une meilleure lisibilité
                const columnSize = Math.ceil(missing.length / 3);
                const col1 = missing.slice(0, columnSize).join("\n") || "-";
                const col2 = missing.slice(columnSize, columnSize * 2).join("\n") || "-";
                const col3 = missing.slice(columnSize * 2).join("\n") || "-";

                fields.push(
                    { name: "👥 Absence (1/3)", value: `\`\`\`\n${col1}\n\`\`\``, inline: true },
                    { name: "👥 Absence (2/3)", value: `\`\`\`\n${col2}\n\`\`\``, inline: true },
                    { name: "👥 Absence (3/3)", value: `\`\`\`\n${col3}\n\`\`\``, inline: true }
                );
            } else {
                // Trop de monde : On liste les 21 premiers et on met un résumé
                const preview = missing.slice(0, 21);
                const col1 = preview.slice(0, 7).join("\n");
                const col2 = preview.slice(7, 14).join("\n");
                const col3 = preview.slice(14, 21).join("\n");

                fields.push(
                    { name: "⚠️ Top Absences", value: `\`\`\`\n${col1}\n\`\`\``, inline: true },
                    { name: "---", value: `\`\`\`\n${col2}\n\`\`\``, inline: true },
                    { name: "---", value: `\`\`\`\n${col3}\n\`\`\``, inline: true }
                );
                
                fields.push({ 
                    name: "📌 Note", 
                    value: `*Et **${missing.length - 21} autres membres** ne sont pas encore inscrits sur le Dashboard.*`,
                    inline: false 
                });
            }
        }

        const description = [
            `📈 **Progression des inscriptions : ${percent}%**`,
            `${filled}${empty}`,
            "",
            `✅ **Validés** : ${registered} membres`,
            `⚠️ **En attente** : ${roleStats.unregistered} membres`,
            `👥 **Total Discord** : ${totalInRole} membres`,
            "",
            "*Consultez la liste complète et gérez les relances sur le Dashboard SigilOS via le bouton ci-dessous.*"
        ].join("\n");

        await sendChannelMessage(channelId, "", {
            embedTitle: `Rapport d'Audit — ${roleStats.roleName}`,
            embedDescription: description,
            embedColor: roleStats.roleColor || 0x5865F2,
            embedFooter: `SigilOS Audit • Rapport déclenché par ${ctx.name}`,
            fields,
            components: [
                {
                    type: 1,
                    components: [
                        {
                            type: 2,
                            style: 5,
                            label: "Accéder au Dashboard",
                            url: dashboardUrl,
                            emoji: { name: "🔗" }
                        }
                    ]
                }
            ]
        });

        // Appliquer le rate limit
        await redis.set(rateLimitKey, nowTs.toString(), "EX", 900); // Expirer après 15 min

        // 4. Audit Log
        const { createAuditLog } = await import("./audit-actions");
        await createAuditLog({
            guildId,
            actorUserId: session.user.id,
            actorName: ctx.name || "Admin",
            action: "ADMIN_ROSTER_AUDIT_SENT",
            targetType: "GUILD",
            targetId: guildId,
            metadata: { 
                roleId, 
                roleName: roleStats.roleName, 
                channelId,
                total: totalInRole,
                registered
            }
        });

        return { success: true };
    } catch (error) {
        console.error("[sendRosterAuditReport] Error:", error);
        return { success: false, error: "Erreur lors de l'envoi du rapport" };
    }
}
/**
 * Manual trigger from Dashboard
 * Automatically finds the system notification channel
 */
export async function sendManualRosterReport(guildId: string, roleId: string): Promise<ActionResponse> {
    try {
        const guild = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { systemNotifyChannelId: true }
        });

        if (!guild?.systemNotifyChannelId) {
            return { success: false, error: "Aucun salon de notifications système configuré dans Paramètres > Salons." };
        }

        return await sendRosterAuditReport({ 
            guildId, 
            roleId, 
            channelId: guild.systemNotifyChannelId,
            showMissingNames: true 
        });
    } catch (error) {
        console.error("[sendManualRosterReport] Error:", error);
        return { success: false, error: "Échec du déclenchement manuel" };
    }
}

