                pollsNotifyRoleId: data.pollsNotifyRoleId
            }
        });

        revalidatePath(`/dashboard/${guildId}/admin/settings`);
        return { success: true };
    } catch (error) {
        console.error("Update Poll Settings Error:", error);
        return { success: false, error: "Erreur serveur" };
