export async function acquirePollCreatorRole(discordGuildId: string): Promise<ActionResponse> {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Non authentifié" };

    const ctx = await getUserContext(discordGuildId);
    if (!ctx.profileId) return { success: false, error: "Profil introuvable" };

    try {
        const guildConfig = await db.guildConfig.findUniqueOrThrow({ where: { discordGuildId } });

        // Ensure role exists
        let role = await db.sigilRole.findUnique({
            where: { guildId_slug: { guildId: guildConfig.id, slug: "poll-creator" } }
        });

        if (!role) {
            role = await db.sigilRole.create({
                data: {
                    guildId: guildConfig.id,
                    slug: "poll-creator",
                    label: "Créateur de Sondages",
                    description: "Permet de créer des sondages (Micro de Guilde)",
                    permissions: ["polls:create"],
                    color: "#06b6d4"
                }
            });
        }

        // Check for active holder
        const activeGrant = await (db as any).sigilRoleGrant.findFirst({
            where: {
                roleId: role.id,
                revokedAt: null,
                expiresAt: { gt: new Date() }
            },
            include: { profile: true }
        });

        // Bypass active holder check only for SuperAdmins (GOD Mode)
        if (!ctx.isSuperAdmin && activeGrant) {
            if (activeGrant.profileId === ctx.profileId) {
                return { success: false, error: "Vous avez déjà le micro" };
            }
            const name = activeGrant.profile.pseudoDofus || activeGrant.profile.discordNickname || "Membre";
            return { success: false, error: `Le micro est déjà pris par ${name}` };
        }

        // --- SECURITY: 24h Cooldown (SuperAdmins bypass this) ---
        if (!ctx.isSuperAdmin) {
            const twentyFourHoursAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);
            const recentGrant = await (db as any).sigilRoleGrant.findFirst({
                where: {
                    roleId: role.id,
                    profileId: ctx.profileId,
                    grantedAt: { gt: twentyFourHoursAgo }
                },
                orderBy: { grantedAt: 'desc' }
            });

            if (recentGrant) {
                const diff = Date.now() - new Date(recentGrant.grantedAt).getTime();
                const remainingMs = (24 * 60 * 60 * 1000) - diff;
                const remainingHours = Math.floor(remainingMs / (1000 * 60 * 60));
                const remainingMins = Math.floor((remainingMs % (1000 * 60 * 60)) / (1000 * 60));

                const timeStr = remainingHours > 0
                    ? `${remainingHours}h ${remainingMins}min`
                    : `${remainingMins}min`;

                return {
                    success: false,
                    error: `Sécurité : Cooldown de 24h actif. Disponible dans environ ${timeStr}.`
                };
            }
        }
        // ------------------------------

        // Exclusivity: Revoke any other grants
        await db.sigilRoleGrant.updateMany({
            where: { roleId: role.id, revokedAt: null },
            data: { revokedAt: new Date() }
        });

        // Grant role for 1 hour
        const expiresAt = new Date();
        expiresAt.setHours(expiresAt.getHours() + 1);

        await (db as any).sigilRoleGrant.upsert({
            where: {
                roleId_profileId: {
                    roleId: role.id,
                    profileId: ctx.profileId
                }
            },
            create: {
                roleId: role.id,
                profileId: ctx.profileId,
                grantedBy: ctx.profileId,
                expiresAt,
                revokedAt: null
            },
            update: {
                grantedBy: ctx.profileId,
                grantedAt: new Date(),
                expiresAt,
                revokedAt: null
            }
        });

        // Audit Log
        const actorName = ctx.name || "Membre";
        await createAuditLog({
            guildId: discordGuildId,
            actorUserId: session.user.id,
            actorName,
            action: "POLL_CREATOR_ROLE_ACQUIRED",
            targetType: "ROLE",
            targetId: role.id,
            metadata: {
                roleSlug: "poll-creator",
                duration: "1h",
                reason: "Acquisition du droit de sondage"
            },
        });

        revalidatePath(`/dashboard/${discordGuildId}/sondages`);
        return { success: true };
    } catch (error) {
        logger.error("[Polls] acquirePollCreatorRole error", { error });
        return { success: false, error: "Erreur lors de l'acquisition du rôle" };
    }
}

export async function releasePollCreatorRole(discordGuildId: string): Promise<ActionResponse> {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Non authentifié" };

    const ctx = await getUserContext(discordGuildId);
    if (!ctx.profileId) return { success: false, error: "Profil introuvable" };

    try {
        const guildConfig = await db.guildConfig.findUniqueOrThrow({ where: { discordGuildId } });

        // Revoke the active grant for this profile and role
        // We use updateMany to be safe/simple, scoped to this profile.
        const result = await db.sigilRoleGrant.updateMany({
            where: {
                profileId: ctx.profileId,
                role: { guildId: guildConfig.id, slug: "poll-creator" },
                revokedAt: null
            },
            data: { revokedAt: new Date() }
        });

        if (result.count === 0) {
            return { success: false, error: "Vous n'avez pas le micro actuellement." };
        }

        // Audit Log
        await createAuditLog({
            guildId: discordGuildId,
            actorUserId: session.user.id,
            actorName: ctx.name || "Membre",
            action: "POLL_CREATOR_ROLE_RELEASED" as any,
            targetType: "ROLE",
            targetId: "poll-creator",
            metadata: { reason: "Libération manuelle" },
        });

        revalidatePath(`/dashboard/${discordGuildId}/sondages`);
        return { success: true };
    } catch (error) {
        logger.error("[Polls] releasePollCreatorRole error", { error });
        return { success: false, error: "Erreur lors de la libération du micro" };
    }
}

"use server";

import { db } from "@/lib/prisma";
import { auth } from "@/auth";
import { ProfileStatus } from "@prisma/client";
import { PresenceManager } from "@/lib/presence";

/**
 * Returns a list of users who have been active in the last X minutes.
 */
import { cache } from "react";

// In-memory cache for internal guild IDs (5min TTL)
const guildIdCache = new Map<string, { id: string, expiresAt: number }>();

async function getInternalGuildId(discordGuildId: string): Promise<string | null> {
    const now = Date.now();
    const cached = guildIdCache.get(discordGuildId);
    if (cached && cached.expiresAt > now) return cached.id;

    const guildConfig = await db.guildConfig.findUnique({
        where: { discordGuildId },
        select: { id: true }
    });

    if (guildConfig) {
        guildIdCache.set(discordGuildId, { id: guildConfig.id, expiresAt: now + 300_000 });
        return guildConfig.id;
    }
    return null;
}

/**
 * Returns a list of users who have been active in the last X minutes.
 */
export const getActivePresence = cache(async (guildId: string, limit: number = 20) => {
    try {
        const internalId = await getInternalGuildId(guildId);
        if (!internalId) return { success: false, data: [], totalActive: 0 };

        // --- NEW REDIS-FIRST LOGIC ---
        const activeIds = await PresenceManager.getActiveUserIds(internalId);

        let activeUsers: any[] = [];
        let totalActive = activeIds.length;

        if (activeIds.length > 0) {
            // Find active profiles based on the IDs from Redis
            activeUsers = await db.userProfile.findMany({
                where: {
                    userId: { in: activeIds },
                    guildId: internalId,
                    status: ProfileStatus.ACTIVE
                },
                select: {
                    id: true,
                    discordNickname: true,
                    pseudoDofus: true,
                    lastActivityAt: true,
                    user: { select: { name: true, image: true } }
                },
                orderBy: { lastActivityAt: "desc" },
                take: limit
            });
        }

        // Falls back to Prisma only if Redis returned absolutely nothing but thresholds say otherwise?
        if (totalActive === 0) {
            const threshold = new Date(Date.now() - 2 * 60 * 1000);
            totalActive = await db.userProfile.count({
                where: { guildId: internalId, lastActivityAt: { gte: threshold }, status: ProfileStatus.ACTIVE }
            });
            if (totalActive > 0) {
                activeUsers = await db.userProfile.findMany({
                    where: { guildId: internalId, lastActivityAt: { gte: threshold }, status: ProfileStatus.ACTIVE },
                    select: { id: true, discordNickname: true, pseudoDofus: true, lastActivityAt: true, user: { select: { name: true, image: true } } },
                    take: limit
                });
            }
        }

        return {
            success: true,
            totalActive,
            data: activeUsers.map(u => ({
                id: u.id,
                name: u.discordNickname || u.pseudoDofus || u.user.name || "Inconnu",
                image: u.user.image,
                lastActive: u.lastActivityAt
            }))
        };
    } catch (error) {
        console.error("[Presence] Failed to fetch active users:", error);
        return { success: false, data: [] };
    }
});

/**
 * Updates the lastActivityAt timestamp for the current user/guild.
 * Throttles database writes to once every 10 minutes per user/guild.
 * Always updates Redis for real-time presence.
 */
export async function updateHeartbeat(guildId: string) {
    try {
        const session = await auth();
        if (!session?.user?.id) return { success: false, error: "Unauthorized" };
        const userId = session.user.id;

        const internalId = await getInternalGuildId(guildId);
        if (!internalId) return { success: false };

        // 1. ALWAYS update Redis (High-performance tracker)
        await PresenceManager.updatePresence(internalId, userId);

        // 2. THOROTTLE database writes (lastActivityAt)
        // We only update the DB if the last update was more than 10 minutes ago
        const profile = await db.userProfile.findUnique({
            where: { 
                userId_guildId: {
                    userId,
                    guildId: internalId
                }
            },
            select: { id: true, lastActivityAt: true }
        });

        if (!profile) return { success: false };

        const tenMinutesAgo = new Date(Date.now() - 10 * 60 * 1000);
        const shouldUpdateDB = !profile.lastActivityAt || profile.lastActivityAt < tenMinutesAgo;

        if (shouldUpdateDB) {
            await db.userProfile.update({
                where: { id: profile.id },
                data: { lastActivityAt: new Date() }
            });
        }

        return { success: true };
    } catch (error) {
        console.error("[Presence] Heartbeat failed:", error);
        return { success: false };
    }
}

"use server";

import { db } from "@/lib/prisma";
import { revalidatePath } from "next/cache";
import { getUserContext } from "./user-actions";
import { uploadGuildImage, deleteGuildImage } from "./upload-actions";
