        const profile = await db.userProfile.findUnique({
            where: {
                userId_guildId: {
                    userId: session.user.id,
                    guildId: guildConfig.id
                }
            },
            include: {
                user: true,
                skins: {
                    orderBy: { createdAt: "desc" }
                },
                roleGrants: {
                    where: {
                        revokedAt: null,
                        OR: [
