                sigilRoles: profile.roleGrants.map(rg => ({
                    id: rg.role.id,
                    slug: rg.role.slug,
                    label: rg.role.label,
                    color: rg.role.color,
                    icon: rg.role.icon,
                    expiresAt: rg.expiresAt
