export async function contactPasseurAction(
    guildId: string,
    listingId: string,
    options: string[],
    customMessage: string | null
): Promise<ActionResponse> {
    try {
        const user = await getUserContext(guildId);
        if (!user.isAuthenticated || !user.isMember) {
            return { success: false, error: "Accès refusé" };
        }
        if (!user.profileId) return { success: false, error: "Profil introuvable" };

        const listing = await db.serviceListing.findUnique({
            where: { id: listingId },
            include: {
                profile: {
                    select: {
                        userId: true,
                        pseudoDofus: true,
                        discordNickname: true,
                        user: { select: { name: true } },
                    },
                },
            },
        });

        if (!listing) return { success: false, error: "Annonce introuvable" };
        if (listing.status !== "ACTIVE") return { success: false, error: "Cette annonce n'est pas active" };

        const guildConfig = await db.guildConfig.findUnique({
            where: { discordGuildId: guildId },
            select: { servicesNotifyChannelId: true, id: true },
        });

        if (!guildConfig?.servicesNotifyChannelId) {
            return {
                success: false,
                error: "Le salon de notification des services n'est pas configuré par l'administrateur.",
            };
        }

        // Fetch Discord IDs for provider and requester
        const [providerAccount, requesterAccount] = await Promise.all([
            db.account.findFirst({
                where: { userId: listing.profile.userId, provider: "discord" },
                select: { providerAccountId: true },
            }),
            db.account.findFirst({
                where: { userId: user.id, provider: "discord" },
                select: { providerAccountId: true },
            }),
        ]);

        const providerMention = providerAccount?.providerAccountId ? `<@${providerAccount.providerAccountId}>` : listing.profile.pseudoDofus || "Passeur";
        const requesterMention = requesterAccount?.providerAccountId ? `<@${requesterAccount.providerAccountId}>` : user.name || "Membre";

        // Call Discord Bot API to send mention message
        const token = process.env.DISCORD_BOT_TOKEN;
        if (!token) return { success: false, error: "Configuration Discord manquante" };

        const channelId = guildConfig.servicesNotifyChannelId;
        const appUrl = process.env.NEXT_PUBLIC_APP_URL || "https://sigilos.fr";

        const emoji = CATEGORY_EMOJIS[listing.category];
        const categoryLabel = CATEGORY_LABELS[listing.category];

        const embed = {
            title: `📩 Nouvelle demande de service`,
            description: [
                `**Service :** [${listing.title}](${appUrl}/dashboard/${guildId}/services)`,
                `**Catégorie :** ${emoji} ${categoryLabel}`,
                `**Client :** ${requesterMention}`,
                `**Passeur/Vendeur :** ${providerMention}`,
                `\n**Options sélectionnées :**`,
                options.length > 0
                    ? options.map(opt => `• ${opt}`).join("\n")
                    : listing.category === "PASSAGE_DONJON"
                        ? "• Passage classique"
                        : "• Service standard",
                customMessage ? `\n**Message du client :**\n*${customMessage}*` : "",
            ].filter(Boolean).join("\n"),
            color: CATEGORY_COLORS_HEX[listing.category as keyof typeof CATEGORY_COLORS_HEX] || 0x8b5cf6,
            timestamp: new Date().toISOString(),
            footer: { text: "SigilOS Services" },
        };

        const components = [{
            type: 1, components: [
                { type: 2, style: 1, label: "Répondre", emoji: { name: "💬" }, custom_id: `svc:reply:${user.id}:${listing.id}` },
                { type: 2, style: 5, label: "Voir sur le site", emoji: { name: "🔗" }, url: `${appUrl}/dashboard/${guildId}/services?replyTo=${user.id}&listingId=${listing.id}` },
            ]
        }];

        const res = await fetch(`https://discord.com/api/v10/channels/${channelId}/messages`, {
            method: "POST",
            headers: { Authorization: `Bot ${token}`, "Content-Type": "application/json" },
            body: JSON.stringify({
                content: `🔔 ${providerMention}, tu as une nouvelle demande de service de la part de ${requesterMention} !`,
                embeds: [embed],
                components,
            }),
        });

        if (!res.ok) {
            const err = await res.json();
            console.error("[contactPasseurAction] Discord API error:", JSON.stringify(err));
            return { success: false, error: "Impossible d'envoyer la notification Discord" };
        }

        // 🔔 Dashboard notification to the provider/seller
        try {
            await db.notification.create({
                data: {
                    userId: listing.profile.userId,
                    title: "Nouvelle demande de service",
                    message: `${user.name || "Un membre"} vous demande pour "${listing.title}". Message : "${customMessage || "aucun"}"`,
                    type: NotificationType.SYSTEM_INFO,
                    category: NotificationCategory.SYSTEM,
                    link: `/dashboard/${guildId}/services?replyTo=${user.id}&listingId=${listing.id}`,
                }
            });
        } catch (notifErr) {
            console.error("[contactPasseurAction] Dashboard notification failed:", notifErr);
        }

        // Log activity
        await logServiceActivity({
            guildId: guildConfig.id,
            actorId: user.profileId,
            module: "SERVICE",
            action: "STATUS_CHANGE",
            entityId: listing.id,
            summary: `Demande de service envoyée à ${listing.profile.pseudoDofus || "Passeur"}`,
            details: JSON.stringify({ options, hasMessage: !!customMessage }),
        });

        return { success: true };
    } catch (error) {
        console.error("[contactPasseurAction]", error);
        return { success: false, error: "Erreur interne" };
    }
}

export async function replyToServiceRequestAction(
    guildId: string,
    requesterUserId: string,
    listingId: string,
    replyMessage: string,
    providerUserId: string
): Promise<ActionResponse> {
    try {
        const { auth } = await import("@/auth");
        const session = await auth();
        const effectiveProviderId = session?.user?.id || providerUserId;

        if (!effectiveProviderId) return { success: false, error: "Non authentifié" };

        const listing = await db.serviceListing.findUnique({
            where: { id: listingId },
            include: {
                profile: {
                    select: {
                        pseudoDofus: true,
                        discordNickname: true,
                        userId: true,
                        user: { select: { name: true } }
                    }
                }
            }
        });

        if (!listing) return { success: false, error: "Annonce introuvable" };
        if (listing.profile.userId !== effectiveProviderId) {
            return { success: false, error: "Non autorisé" };
        }

        const providerName = getName(listing.profile);

        // 1. Dashboard Notification to client (requesterUserId)
        await db.notification.create({
            data: {
                userId: requesterUserId,
                title: `Réponse pour le service : ${listing.title}`,
                message: `${providerName} a répondu : "${replyMessage}"`,
                type: NotificationType.SYSTEM_INFO,
                category: NotificationCategory.SYSTEM,
                link: `/dashboard/${guildId}/services`,
            }
        });

        // 2. Discord Notification (DM / channel fallback)
        const clientAccount = await db.account.findFirst({
            where: { userId: requesterUserId, provider: "discord" },
            select: { providerAccountId: true }
        });

        if (clientAccount?.providerAccountId) {
            const token = process.env.DISCORD_BOT_TOKEN;
            const guildConfig = await db.guildConfig.findUnique({
                where: { discordGuildId: guildId },
                select: { servicesNotifyChannelId: true }
            });

            if (token && guildConfig?.servicesNotifyChannelId) {
                try {
                    const dmRes = await fetch(`https://discord.com/api/v10/users/@me/channels`, {
                        method: "POST",
                        headers: { Authorization: `Bot ${token}`, "Content-Type": "application/json" },
                        body: JSON.stringify({ recipient_id: clientAccount.providerAccountId })
                    });
                    if (dmRes.ok) {
                        const dmChannel = await dmRes.json() as { id: string };
                        await fetch(`https://discord.com/api/v10/channels/${dmChannel.id}/messages`, {
                            method: "POST",
                            headers: { Authorization: `Bot ${token}`, "Content-Type": "application/json" },
                            body: JSON.stringify({
                                content: `✉️ **${providerName}** a répondu à ta demande de service pour **${listing.title}** :\n> ${replyMessage}`
                            })
                        });
                    } else {
                        // Fallback: channel ping
                        await fetch(`https://discord.com/api/v10/channels/${guildConfig.servicesNotifyChannelId}/messages`, {
                            method: "POST",
                            headers: { Authorization: `Bot ${token}`, "Content-Type": "application/json" },
                            body: JSON.stringify({
                                content: `🔔 <@${clientAccount.providerAccountId}>, **${providerName}** a répondu à ta demande pour **${listing.title}** :\n> ${replyMessage}`
                            })
                        });
                    }
                } catch (discordErr) {
                    console.error("[replyToServiceRequestAction] Discord notification failed:", discordErr);
                }
            }
        }

        revalidatePath(`/dashboard/${guildId}/services`);
        return { success: true };
    } catch (err) {
        console.error("[replyToServiceRequestAction]", err);
        return { success: false, error: "Erreur interne" };
    }
}

"use server";

import { db } from "@/lib/prisma";
import { auth } from "@/auth";
import { ActionResponse, getUserContext } from "./user-actions";
import { z } from "zod";
import { revalidatePath } from "next/cache";
import * as cheerio from "cheerio";
import { DOFUS_CLASSES } from "@/lib/dofus-assets";

const SkinSchema = z.object({
    guildId: z.string(),
    url: z.string().url("URL invalide"),
    name: z.string().optional(),
    existingSkinId: z.string().optional()
});

export type SkinData = {
    name: string;
    thumbnailUrl: string | null;
    provider: "BARBOFUS" | "DOFUSSKINMANGA" | "OTHER";
    equipment?: any;
    colors?: any;
    metadata?: any;
};

/**
 * Detects the provider and extracts basic metadata (thumbnail, title)
 */
async function scrapeSkinMetadata(url: string): Promise<SkinData> {
    const lowerUrl = url.toLowerCase();
    
    // 1. Barbofus (Extraction avancée: Couleurs + Items)
    if (lowerUrl.includes("barbofus.com")) {
        const res = await fetch(url, { headers: { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36" } });
        const html = await res.text();
        const $ = cheerio.load(html);
        
        const colors: Record<string, string> = {};
        const equipment: any[] = [];

        // Extract Colors (Alpine.js structure)
        $('button').each((_, el) => {
            const label = $(el).find('p.text-lg').text().replace(' :', '').trim();
            if (label && (label.includes('Peau') || label.includes('Cheveux') || label.includes('Vêtements'))) {
                const styleAttr = $(el).find('div[style*="background-color"], div[:style*="background-color"]').attr(':style') || "";
                const hexMatch = styleAttr.match(/#?([a-fA-F0-9]{6})/);
                if (hexMatch) {
                    colors[label] = `#${hexMatch[1]}`;
                }
            }
        });

        // Extract Equipment — all item types (Objet vivant, Objet d'apparat, Mimibiotable, etc.)
        const BARBOFUS_ITEM_TYPES = new Set([
            "Objet d'apparat",
            "Objet vivant",
            "Mimibiotable",
            "Familier",
            "Dragodinde",
            "Monture",
        ]);

        $('p').each((_, el) => {
            const text = $(el).text().trim();
            if (BARBOFUS_ITEM_TYPES.has(text)) {
                const itemDiv = $(el).closest('div').next('div');
                if (itemDiv.length) {
                    const name = itemDiv.find('p').text().trim();
                    const icon = itemDiv.find('img').attr('src');
                    if (name) {
                        equipment.push({ name, type: text, icon });
                    }
                }
            }
        });

        
        // Extract Author (Robust)
        const author = $('h2:contains("par") span').first().text().trim() || 
                       $('h2:contains("par")').text().replace('par ', '').trim();

        // Metadata extraction (Robust positional selectors)
        let characterClass = $('div.justify-self-end p.text-secondary').first().text().trim();
        let gender = $('div.justify-self-start p.text-secondary').first().text().trim();

        // --- FUZZY FALLBACK ---
        // If selectors failed, search in the whole text for Dofus keywords
        const allText = $('body').text();
        const classes = ["Feca", "Osamodas", "Enutrof", "Sram", "Xelor", "Ecaflip", "Eniripsa", "Iop", "Cra", "Sadida", "Sacrieur", "Pandawa", "Roublard", "Zobal", "Steamer", "Eliotrope", "Huppermage", "Ouginak", "Forgelance"];
        
        if (!characterClass) {
            characterClass = classes.find(c => allText.includes(c)) || "";
        }
        if (!gender) {
            if (allText.includes("Homme") || allText.includes("♂")) gender = "Homme";
            else if (allText.includes("Femme") || allText.includes("♀")) gender = "Femme";
        }

        // Extract Face/Head icon
        const headIcon = $('img[alt="Visage"]').attr('src') || 
                         $('p:contains("Visage")').next('div').find('img').attr('src');
        
        return {
            name: $('meta[property="og:title"]').attr('content')?.replace(" - Barbofus", "") || "Skin Barbofus",
            thumbnailUrl: $('meta[property="og:image"]').attr('content') || null,
            provider: "BARBOFUS",
            colors,
            equipment,
            metadata: {
                class: characterClass || undefined,
                gender: gender || undefined,
                head: headIcon || undefined,
                author: author || undefined
            }
        };
    }

    // 2. DofusSkinManga (Nouveau standard)
    if (lowerUrl.includes("dofusskinmanga.com")) {
        const res = await fetch(url, { 
            headers: { 
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36",
                "Referer": "https://dofusskinmanga.com/"
            } 
        });
        const html = await res.text();
        const $ = cheerio.load(html);
        
        const colors: Record<string, string> = {};
        const equipment: any[] = [];

        // Extract Colors (.spec-row-sp)
        $('.spec-row-sp').each((_, el) => {
            const label = $(el).find('.spec-label-sp').text().trim();
            const hex = $(el).find('.hex-code-sp').text().replace('❏', '').trim();
            if (label && hex.startsWith('#')) {
                colors[label] = hex;
            }
        });

        // Extract Equipment (.item-card-sp)
        $('.item-card-sp').each((_, el) => {
            const type = $(el).find('.item-type-sp').text().trim();
            const name = $(el).find('.item-name-sp').text().trim();
            const icon = $(el).find('.item-icon-sp').attr('src');
            
            if (name && name !== "Aucun") {
                equipment.push({ 
                    name, 
                    type: type.replace('CHAPEAU', 'Coiffe').replace('ÉPAULIÈRES', 'Épaulières'), 
                    icon: icon?.startsWith('http') ? icon : `https://dofusskinmanga.com/${icon}`
                });
            }
        });

        // Precision extraction for UX 2026
        const name = $('h1 .brand-skin').first().text().trim() || 
                    $('h1').first().text().replace(/Classe:.*|Genre:.*|Tête:.*/gi, "").trim() ||
                    "Skin Manga";

        const subSpText = $('.sub-sp').text();
        const className = subSpText.match(/Classe:\s*([^\n|]+)/i)?.[1]?.trim() || 
                         html.match(/Classe:<\/(?:span|b|strong)>\s*([^<]+)/i)?.[1]?.trim();
        const genderName = subSpText.match(/Genre:\s*([^\n|]+)/i)?.[1]?.trim() || 
                          html.match(/Genre:<\/(?:span|b|strong)>\s*([^<]+)/i)?.[1]?.trim();
        const headMatch = subSpText.match(/Tête:\s*([^\n|]+)/i) || html.match(/Tête:<\/(?:span|b|strong)>\s*([^<]+)/i);

        // Map class name to ID for filter compatibility
        const classId = DOFUS_CLASSES.find(c => 
            c.name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "") === 
            className?.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "")
        )?.icon.match(/classes\/(\d+)\.png/)?.[1];

        return {
            name,
            thumbnailUrl: $('meta[property="og:image"]').attr('content') || null,
            provider: "DOFUSSKINMANGA",
            colors,
            equipment,
            metadata: {
                class: classId || className, // Store ID if found, fallback to name
                gender: genderName,
                head: headMatch ? (headMatch[1] || headMatch[0]).trim() : undefined,
                author: "Inconnu"
            }
        };
    }

    // Fallback Generic Scraper
    try {
        const res = await fetch(url, { headers: { "User-Agent": "SigilOS/1.0" } });
        const html = await res.text();
        const $ = cheerio.load(html);
        return {
            name: $('meta[property="og:title"]').attr('content') || $('title').text() || "Nouveau Skin",
            thumbnailUrl: $('meta[property="og:image"]').attr('content') || null,
            provider: "OTHER"
        };
    } catch {
        return { name: "Skin", thumbnailUrl: null, provider: "OTHER" };
    }
}

export async function addUserSkin(rawData: z.infer<typeof SkinSchema>): Promise<ActionResponse> {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Non authentifié" };

    const validation = SkinSchema.safeParse(rawData);
    if (!validation.success) return { success: false, error: validation.error.errors[0].message };
    const { guildId, url, name: manualName, existingSkinId } = validation.data;

    try {
        const ctx = await getUserContext(guildId);
        if (!ctx.profileId) return { success: false, error: "Profil introuvable" };
        
        // --- SPAM PROTECTION ---
        // Check if the user already has this skin URL on their profile
        if (!existingSkinId) {
            const alreadyOwned = await db.userSkin.findFirst({
                where: { 
                    profileId: ctx.profileId,
                    url: url
                }
            });
            if (alreadyOwned) {
                return { success: false, error: "Vous possédez déjà ce skin dans votre bibliothèque" };
            }
        }

        // --- CACHE LOGIC ---
        // 1. Check if we already have this skin in our global cache
        const existingInCache = await db.userSkin.findFirst({
            where: { url },
            orderBy: { updatedAt: 'desc' }
        });

        // 2. Decide if we need to scrape (Stale threshold: 7 days)
        // FORCE SCRAPE if existingSkinId is provided (manual sync)
        const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
        const isStale = !existingInCache || existingInCache.updatedAt < sevenDaysAgo;
        const shouldScrape = isStale || !!existingSkinId; 

        let skinData: SkinData;

        if (!shouldScrape && existingInCache) {
            skinData = {
                name: existingInCache.name,
                thumbnailUrl: existingInCache.thumbnailUrl,
                provider: existingInCache.provider as any,
                equipment: existingInCache.equipment,
                colors: existingInCache.colors,
                metadata: existingInCache.metadata
            };
        } else {
            try {
                skinData = await scrapeSkinMetadata(url);
            } catch (error) {
                if (existingInCache) {
                    skinData = {
                        name: existingInCache.name,
                        thumbnailUrl: existingInCache.thumbnailUrl,
                        provider: existingInCache.provider as any,
                        equipment: existingInCache.equipment,
                        colors: existingInCache.colors,
                        metadata: existingInCache.metadata
                    };
                } else {
                    throw error;
                }
            }
        }
        
        let skin;
        if (existingSkinId) {
            skin = await db.userSkin.update({
                where: { id: existingSkinId },
                data: {
                    name: manualName || skinData.name,
                    thumbnailUrl: skinData.thumbnailUrl,
                    equipment: skinData.equipment || {},
                    colors: skinData.colors || {},
                    metadata: skinData.metadata || {}
                }
            });
        } else {
            skin = await db.userSkin.create({
                data: {
                    profileId: ctx.profileId,
                    url: url,
                    name: manualName || skinData.name,
                    provider: skinData.provider,
                    thumbnailUrl: skinData.thumbnailUrl,
                    equipment: skinData.equipment || {},
                    colors: skinData.colors || {},
                    metadata: skinData.metadata || {}
                }
            });
        }

        revalidatePath(`/dashboard/${guildId}/profile`);
        return { success: true, data: skin };
    } catch (error) {
        console.error("[Skin Actions] Add Error:", error);
        return { success: false, error: "Impossible d'ajouter le skin" };
    }
}

export async function deleteUserSkin(guildId: string, skinId: string): Promise<ActionResponse> {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Non authentifié" };

    try {
        // Verify ownership
        const ctx = await getUserContext(guildId);
        const skin = await db.userSkin.findUnique({
            where: { id: skinId },
            select: { profileId: true }
        });

        if (!skin || skin.profileId !== ctx.profileId) {
            return { success: false, error: "Vous ne possédez pas ce skin" };
        }

        await db.userSkin.delete({ where: { id: skinId } });

        revalidatePath(`/dashboard/${guildId}/profile`);
        return { success: true };
    } catch (error) {
        console.error("[Skin Actions] Delete Error:", error);
        return { success: false, error: "Impossible de supprimer le skin" };
    }
}

export async function getUserSkins(guildId: string, profileId?: string): Promise<ActionResponse<any[]>> {
    try {
        const ctx = await getUserContext(guildId);
        const targetProfileId = profileId || ctx.profileId;

        const skins = await db.userSkin.findMany({
            where: { profileId: targetProfileId },
            orderBy: { createdAt: "desc" }
        });

        return { success: true, data: skins };
    } catch (error) {
        console.error("[Skin Actions] Get Error:", error);
        return { success: false, error: "Impossible de récupérer les skins" };
    }
}

export async function getSkinPreview(url: string): Promise<ActionResponse<SkinData>> {
    try {
        // 1. Check Cache
        const existingInCache = await db.userSkin.findFirst({
            where: { url },
            orderBy: { updatedAt: 'desc' }
        });

        const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
        const isStale = !existingInCache || existingInCache.updatedAt < sevenDaysAgo;

        if (!isStale && existingInCache) {
            return { 
                success: true, 
                data: {
                    name: existingInCache.name,
                    thumbnailUrl: existingInCache.thumbnailUrl,
                    provider: existingInCache.provider as any,
                    equipment: existingInCache.equipment,
                    colors: existingInCache.colors,
                    metadata: existingInCache.metadata
                } 
            };
        }

        // 2. Scrape if not in cache or stale
        const metadata = await scrapeSkinMetadata(url);
        return { success: true, data: metadata };
    } catch (error) {
        return { success: false, error: "Impossible de prévisualiser le skin" };
    }
}

export async function updateUserSkin(guildId: string, skinId: string, data: { name: string, url?: string }): Promise<ActionResponse> {
    const session = await auth();
    if (!session?.user?.id) return { success: false, error: "Non authentifié" };

    try {
        const ctx = await getUserContext(guildId);
        
        // Verify ownership
        const skin = await db.userSkin.findFirst({
            where: { 
                id: skinId,
                profileId: ctx.profileId
            }
        });

        if (!skin) {
            return { success: false, error: "Skin introuvable ou vous n'êtes pas le propriétaire" };
        }

        const updateData: any = { name: data.name };

        // If URL changed, we MUST re-scrape everything
        if (data.url && data.url.trim() !== skin.url) {
            try {
                const scraped = await scrapeSkinMetadata(data.url.trim());
                updateData.url = data.url.trim();
                updateData.thumbnailUrl = scraped.thumbnailUrl;
                updateData.provider = scraped.provider;
                updateData.equipment = scraped.equipment;
                updateData.colors = scraped.colors;
                updateData.metadata = scraped.metadata;
                // Note: We use the manual name provided in 'data.name' even if URL changed
            } catch (scrapeError) {
                return { success: false, error: "Impossible de valider le nouveau lien" };
            }
        }

        const updatedSkin = await db.userSkin.update({
            where: { id: skinId },
            data: updateData
        });

        revalidatePath(`/dashboard/${guildId}/profile`);
        revalidatePath(`/dashboard/${guildId}/galerie-stuff`);
        
        return { success: true, data: updatedSkin };
    } catch (error) {
        console.error("[Skin Actions] Update Error:", error);
        return { success: false, error: "Impossible de mettre à jour le skin" };
    }
}

"use server";

/**
 * Songes Module - Server Actions
 * CRUD operations for Dream Runs
 */

import { z } from "zod";
import { revalidatePath } from "next/cache";
import { db } from "@/lib/prisma";
import { getUserContext } from "@/server/actions/user-actions";
import { createNotification } from "@/server/actions/notification-actions";
import { sendChannelMessage } from "@/server/discord";
import { rateLimit } from "@/lib/ratelimit";

// ============================================
// CONSTANTS & HELPERS
// ============================================

const JOIN_REQUEST_TTL_MS = 24 * 60 * 60 * 1000; // 24 heures

/**
 * Clean up expired join requests (Auto-Reject)
 * Called lazily when data is accessed
 */
async function cleanupExpiredRequests(guildId: string) {
    const expirationThreshold = new Date(Date.now() - JOIN_REQUEST_TTL_MS);

    // Find expired pending requests
    const expiredRequests = await db.dreamJoinRequest.findMany({
        where: {
            run: { guildId },
            status: "PENDING",
            createdAt: { lt: expirationThreshold },
        },
        include: { run: true },
    });

    if (expiredRequests.length === 0) return;

    // Process each expired request
    for (const req of expiredRequests) {
        // 1. Mark as REJECTED
        await db.dreamJoinRequest.update({
            where: { id: req.id },
            data: {
                status: "REJECTED",
                respondedAt: new Date(),
            },
        });

        // 2. Notify the user
        await createNotification(
            req.userId,
            "SYSTEM_INFO",
            "Candidature expirée",
            `Votre candidature pour la run ${req.run.difficulty} a expiré (aucune réponse du leader sous 10 minutes).`,
            `/dashboard/${guildId}/songes`,
            guildId
        );
    }
}

// ============================================
// CONTEXT HELPER
// ============================================

async function getGuildUserContext(guildId: string) {
    const ctx = await getUserContext(guildId);
    if (!ctx.isAuthenticated || !ctx.id || !ctx.isMember) return null;

    return {
        ...ctx,
        userId: ctx.id,
        guildId: guildId, // This is the Discord Guild ID
    };
}

// ============================================
// SCHEMAS
// ============================================

const CreateRunSchema = z.object({
    difficulty: z.enum([
        "REVE_I", "REVE_II", "REVE_III",
        "PARADOXE_I", "PARADOXE_II", "PARADOXE_III", "PARADOXE_IV",
        "CAUCHEMAR_I", "CAUCHEMAR_II", "CAUCHEMAR_III"
    ]),
    objectives: z.array(z.enum([
        "MISSION_GUILDE", "DROP_LEGENDE", "SUCCES_NO_ACHAT", "FUN", "QUETE"
    ])).min(1, "Sélectionnez au moins un objectif"),
    publishToDiscord: z.boolean().optional(),
    epreuveCode: z.string().optional(), // Code épreuve (FONSOCAC, REVERSED, etc.) — null = run standard
    scheduledAt: z.date().optional().nullable(),
    mentionRoleIds: z.array(z.string()).default([]),
    linkedStuffId: z.string().nullable().optional(),
    linkedStuffName: z.string().nullable().optional(),
    linkedStuffThumbnail: z.string().nullable().optional(),
    linkedStuffUrl: z.string().nullable().optional(),
    leaderClass: z.string().optional(),
}).refine((data) => {
    if (data.epreuveCode) return true; // Épreuve bypasse la restriction objectifs
    const isParadoxeOrHigher = data.difficulty.startsWith("PARADOXE") || data.difficulty.startsWith("CAUCHEMAR");
    const restrictedObjectives = ["DROP_LEGENDE", "SUCCES_NO_ACHAT"];
    if (!isParadoxeOrHigher) {
        const hasRestricted = data.objectives.some(o => restrictedObjectives.includes(o));
        if (hasRestricted) return false;
    }
    return true;
}, {
    message: "Certains objectifs nécessitent une difficulté Paradoxe ou plus.",
    path: ["objectives"]
});

const AddFloorSchema = z.object({
    runId: z.string(),
    floorNumber: z.number().min(0).max(26), // Allow 0 for reset/entry
    roomType: z.enum(["COMBAT", "FONTAINE", "FAVEUR", "BOSS", "ENTREE"]),
    difficulty: z.number().min(1).max(60).optional(),
    pointsReveGained: z.number().min(0).default(0),
});

const AddBonusSchema = z.object({
    runId: z.string(),
    bonusName: z.string(),
    bonusType: z.string(),
    bonusRarete: z.string(),
    cost: z.number().min(0),
});

const DeleteBonusSchema = z.object({
    runId: z.string(),
    bonusId: z.string(),
});

const SetRoomSchema = z.object({
    runId: z.string(),
    roomNumber: z.number().min(0).max(26),
});

// ============================================
// CREATE RUN
// ============================================

export async function createDreamRun(guildId: string, data: z.infer<typeof CreateRunSchema>) {
    const ctx = await getGuildUserContext(guildId);
    if (!ctx) return { success: false, error: "Non authentifié ou non autorisé" };

    const validated = CreateRunSchema.safeParse(data);
    if (!validated.success) {
        return { success: false, error: validated.error.errors[0].message };
    }

    // RATE LIMIT: 3 créations par 10 minutes
    // 🛠️ Dev bypass : RATE_LIMIT_BYPASS_DISCORD_IDS (IDs Discord séparés par virgule)
    const bypassDiscordIds = (process.env.RATE_LIMIT_BYPASS_DISCORD_IDS ?? "").split(",").map(s => s.trim()).filter(Boolean);
    let isRateLimitBypassed = false;
    if (bypassDiscordIds.length > 0) {
        const account = await db.account.findFirst({
            where: { userId: ctx.userId, provider: "discord" },
            select: { providerAccountId: true },
        });
        isRateLimitBypassed = bypassDiscordIds.includes(account?.providerAccountId ?? "");
    }
    if (!isRateLimitBypassed) {
        const limiter = await rateLimit(`create_dream_run:${ctx.userId}:${guildId}`, 3, 10 * 60 * 1000);
        if (!limiter.success) return { success: false, error: "Trop de runs créées. Veuillez patienter.", resetAt: limiter.reset };
    }

    // Rule: A leader can only have one active run
    const existingRun = await db.dreamRun.findFirst({
        where: {
            guildId: ctx.guildId,
            leaderId: ctx.userId,
            status: { in: ["RECRUITING", "IN_PROGRESS"] },
        },
    });

    if (existingRun) {
        return { success: false, error: "Vous avez déjà une run active" };
    }

    const run = await db.dreamRun.create({
        data: {
            guildId: ctx.guildId,
            leaderId: ctx.userId,
            difficulty: validated.data.difficulty,
            objectives: validated.data.objectives,
            objective: validated.data.objectives[0], // Init legacy field
            epreuveCode: validated.data.epreuveCode ?? null,
            scheduledAt: validated.data.scheduledAt ?? null,
            mentionRoleId: validated.data.mentionRoleIds.length > 0 ? validated.data.mentionRoleIds.join(",") : null,
            status: "IN_PROGRESS",
            currentFloor: 1,
            startedAt: new Date(),
            members: {
                create: {
                    userId: ctx.userId,
                    slot: 1, // Leader takes slot 1
                    linkedStuffId: validated.data.linkedStuffId ?? null,
                    linkedStuffName: validated.data.linkedStuffName ?? null,
                    linkedStuffThumbnail: validated.data.linkedStuffThumbnail ?? null,
                    linkedStuffUrl: validated.data.linkedStuffUrl ?? null,
                },
            },
        },
    });

    // Create an ACCEPTED join request for the leader to store their class choice
    if (validated.data.leaderClass) {
        await db.dreamJoinRequest.create({
            data: {
                runId: run.id,
                userId: ctx.userId,
                classe: validated.data.leaderClass,
                status: "ACCEPTED",
                message: "Meneur de la run",
                linkedStuffId: validated.data.linkedStuffId ?? null,
                linkedStuffName: validated.data.linkedStuffName ?? null,
                linkedStuffThumbnail: validated.data.linkedStuffThumbnail ?? null,
                linkedStuffUrl: validated.data.linkedStuffUrl ?? null,
            }
        });
    }

    // Auto-publish to Discord if requested
    if (validated.data.publishToDiscord) {
        const { publishDiscordRun } = await import("@/server/songes-service");
        await publishDiscordRun(ctx.guildId, run.id);
    }

    revalidatePath(`/dashboard/${ctx.guildId}/songes`);

    return { success: true, runId: run.id };
}

/**
 * Lightweight public config fetch for Songes (no admin required)
 */
export async function getSongesPublicConfig(guildId: string) {
    const ctx = await getGuildUserContext(guildId);
    if (!ctx) return { success: false, error: "Non authentifié" };

