const logTelemetrySchema = z.object({
    guildId: z.string().optional().nullable(),
    path: z.string().min(1),
    eventType: z.enum(["PAGE_VIEW", "INTERACTION"]),
    elementId: z.string().optional().nullable(),
    details: z.any().optional(),
});

export async function logTelemetryEvent(rawInput: z.infer<typeof logTelemetrySchema>) {
    try {
        const session = await auth();
        if (!session?.user?.id) {
            return { success: false, error: "Unauthorized" };
        }

        const parsed = logTelemetrySchema.safeParse(rawInput);
        if (!parsed.success) {
            return { success: false, error: "Invalid inputs" };
        }

        const data = parsed.data;

        await dbAny.telemetryEvent.create({
            data: {
                userId: session.user.id,
                userName: session.user.name || "Membre",
                guildId: data.guildId || null,
                path: data.path,
                eventType: data.eventType,
                elementId: data.elementId || null,
                details: data.details || {},
            }
        });

        return { success: true };
    } catch (err) {
        console.error("[Telemetry] Failed to log telemetry event:", err);
        return { success: false, error: "Internal Error" };
    }
}

export async function getTelemetryStats(filterGuildId?: string) {
    try {
        const isAdmin = await isSuperAdmin();
        if (!isAdmin) {
            throw new Error("Unauthorized: Super-admin access required");
        }

        const now = new Date();
        const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
        const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

        // Build optional guild-scoped where clause
        const guildWhere = filterGuildId ? { guildId: filterGuildId } : undefined;
        const withGuild = (extra: object) => guildWhere ? { ...guildWhere, ...extra } : extra;

        const [
            totalEvents,
            pageViews24h,
            interactions24h,
            uniqueUsers24h,
            liveEvents,
            topPathsRaw,
            topInteractionsRaw,
            topUsersRaw,
            guildConfigs,
        ] = await Promise.all([
            // Total stats (guild-scoped if filter active)
            dbAny.telemetryEvent.count({ where: guildWhere }),
            // 24h page views
            dbAny.telemetryEvent.count({
                where: withGuild({
                    eventType: "PAGE_VIEW",
                    createdAt: { gte: oneDayAgo },
                })
            }),
            // 24h interactions
            dbAny.telemetryEvent.count({
                where: withGuild({
                    eventType: "INTERACTION",
                    createdAt: { gte: oneDayAgo },
                })
            }),
            // 24h unique users
            dbAny.telemetryEvent.groupBy({
                by: ["userId"],
                where: withGuild({ createdAt: { gte: oneDayAgo } }),
                _count: true
            }),
            // Live activity (last 100 events)
            dbAny.telemetryEvent.findMany({
                where: guildWhere,
                orderBy: { createdAt: "desc" },
                take: 100
            }),
            // Top Paths (Most Visited Pages)
            dbAny.telemetryEvent.groupBy({
                by: ["path"],
                where: withGuild({ eventType: "PAGE_VIEW" }),
                _count: true,
                orderBy: { _count: { path: "desc" } },
                take: 15
            }),
            // Top Clicks/Interactions
            dbAny.telemetryEvent.groupBy({
                by: ["elementId"],
                where: withGuild({
                    eventType: "INTERACTION",
                    elementId: { not: null }
                }),
                _count: true,
                orderBy: { _count: { elementId: "desc" } },
                take: 15
            }),
            // Top Active Users — group only by userId (lighter scan), enrich names later via profileMap
            dbAny.telemetryEvent.groupBy({
                by: ["userId"],
                where: guildWhere,
                _count: true,
                orderBy: { _count: { userId: "desc" } },
                take: 50
            }),
            // Fetch all guild configs to map names
            dbAny.guildConfig.findMany({
                select: {
                    id: true,
                    name: true,
                    discordGuildId: true,
                }
            })
        ]);

        // Build guild name lookup — both by internal CUID and by Discord Guild ID
        const guildMap = new Map<string, string>();
        guildConfigs.forEach((g: any) => {
            if (g.id) guildMap.set(g.id, g.name);
            if (g.discordGuildId) guildMap.set(g.discordGuildId, g.name);
        });

        // 1. Last-seen per user (capped at 200 to avoid huge loads)
        const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
        const lastSeenRaw = await dbAny.telemetryEvent.groupBy({
            by: ["userId"],
            _max: { createdAt: true },
            where: withGuild({ createdAt: { gte: thirtyDaysAgo } }),
            orderBy: {
                userId: "asc"
            },
            take: 200
        });

        // 2. For guildId per user: get distinct guildId per userId from a recent sample
        // (we can't groupBy userId+guildId efficiently at scale; just use the most recent event per user)
        const lastGuildPerUser = await dbAny.telemetryEvent.findMany({
            where: withGuild({
                userId: { in: lastSeenRaw.map((u: any) => u.userId) },
                createdAt: { gte: thirtyDaysAgo }
            }),
            select: { userId: true, guildId: true, userName: true },
            distinct: ["userId"],
            orderBy: { createdAt: "desc" },
        });
        const lastGuildMap = new Map<string, { guildId: string | null; userName: string }>();
        lastGuildPerUser.forEach((e: any) => {
            if (!lastGuildMap.has(e.userId)) {
                lastGuildMap.set(e.userId, { guildId: e.guildId || null, userName: e.userName });
            }
        });

        // 3. Resolve user names from UserProfile (pseudoDofus or discordNickname preferred)
        const allUserIds = Array.from(new Set([
            ...liveEvents.map((e: any) => e.userId),
            ...topUsersRaw.map((u: any) => u.userId),
            ...lastSeenRaw.map((u: any) => u.userId),
        ]));

        const userProfiles = await db.userProfile.findMany({
            where: { userId: { in: allUserIds } },
            select: {
                userId: true,
                guildId: true,
                pseudoDofus: true,
                discordNickname: true,
            }
        });

        // Key: userId -> best display name (guild-specific first, then any profile)
        const profileNameMap = new Map<string, string>(); // userId_guildId -> name
        const profileFallbackMap = new Map<string, string>(); // userId -> name
        userProfiles.forEach((p: any) => {
            const resolvedName = p.pseudoDofus || p.discordNickname;
            if (resolvedName) {
                profileNameMap.set(`${p.userId}_${p.guildId}`, resolvedName);
                if (!profileFallbackMap.has(p.userId)) {
                    profileFallbackMap.set(p.userId, resolvedName);
                }
            }
        });

        const resolveUserName = (userId: string, guildId: string | null, defaultName: string) => {
            if (guildId) {
                const name = profileNameMap.get(`${userId}_${guildId}`);
                if (name) return name;
            }
            return profileFallbackMap.get(userId) || defaultName;
        };

        const resolveGuildName = (guildId: string | null) => {
            if (!guildId) return "Sans Guilde";
            const name = guildMap.get(guildId);
            if (name) return name;
            return "Guilde Inconnue";
        };

        // 4. Build usersLastSeen
        const usersLastSeen = lastSeenRaw.map((u: any) => {
            const meta = lastGuildMap.get(u.userId);
            const gId = meta?.guildId || null;
            const rawName = meta?.userName || "Membre";
            return {
                userId: u.userId,
                userName: resolveUserName(u.userId, gId, rawName),
                guildId: gId || "None",
                guildName: resolveGuildName(gId),
                lastActive: u._max.createdAt ? u._max.createdAt.toISOString() : null
            };
        }).sort((a: any, b: any) => {
            const dateA = a.lastActive ? new Date(a.lastActive).getTime() : 0;
            const dateB = b.lastActive ? new Date(b.lastActive).getTime() : 0;
            return dateB - dateA;
        });

        // 5. Guild activity (7 days)
        const guildActivityRaw = await dbAny.telemetryEvent.groupBy({
            by: ["guildId"],
            _count: { id: true },
            where: { createdAt: { gte: sevenDaysAgo } }
        });

        const guildActivity = guildActivityRaw.map((ga: any) => {
            const gId = ga.guildId || null;
            return {
                guildId: gId || "None",
                guildName: resolveGuildName(gId),
                count: ga._count.id
            };
        }).sort((a: any, b: any) => b.count - a.count);

        // 6. Hourly chart — select only createdAt+eventType, guild-scoped
        const hourlyEvents = await dbAny.telemetryEvent.findMany({
            where: withGuild({ createdAt: { gte: oneDayAgo } }),
            select: { createdAt: true, eventType: true }
        });

        const hourlyMap = new Map<string, { views: number; interactions: number }>();
        for (let i = 23; i >= 0; i--) {
            const d = new Date(now.getTime() - i * 60 * 60 * 1000);
            const hourStr = d.getHours().toString().padStart(2, '0') + ":00";
            hourlyMap.set(hourStr, { views: 0, interactions: 0 });
        }
        hourlyEvents.forEach((event: any) => {
            const hour = new Date(event.createdAt).getHours().toString().padStart(2, '0') + ":00";
            if (hourlyMap.has(hour)) {
                const current = hourlyMap.get(hour)!;
                if (event.eventType === "PAGE_VIEW") current.views += 1;
                else current.interactions += 1;
            }
        });

        const chartData = Array.from(hourlyMap.entries()).map(([hour, counts]) => ({
            time: hour,
            views: counts.views,
            interactions: counts.interactions,
        }));

        // 7. Build topUsers with enriched name + guildId from lastGuildMap
        const topUsers = topUsersRaw.map((u: any) => {
            const meta = lastGuildMap.get(u.userId);
            const gId = meta?.guildId || null;
            const rawName = meta?.userName || "Membre";
            return {
                userId: u.userId,
                userName: resolveUserName(u.userId, gId, rawName),
                guildId: gId || "None",
                guildName: resolveGuildName(gId),
                count: u._count
            };
        });

        // Extract module name helper
        const getModuleName = (path: string) => {
            if (!path) return "Général";
            if (path.includes("/raids")) return "Raid Hub";
            if (path.includes("/stuff-gallery") || path.includes("/stuffs")) return "Galerie de Stuffs";
            if (path.includes("/almanax")) return "Almanax";
            if (path.includes("/shop")) return "Boutique";
            if (path.includes("/quests") || path.includes("/dofus")) return "Quêtes & Succès";
            if (path.includes("/minigames") || path.includes("/games")) return "Mini-Jeux";
            if (path.includes("/members") || path.includes("/roster")) return "Roster & Membres";
            if (path.includes("/god")) return "Administration God";
            if (path.includes("/settings") || path.includes("/config")) return "Configuration";
            if (path.includes("/dashboard") || path === "/") return "Accueil / Tableau de bord";
            return "Autre Module";
        };

        // Module Stats aggregation (groupBy path over 30 days to avoid fetching all raw events in memory)
        const moduleEventsRaw = await dbAny.telemetryEvent.groupBy({
            by: ["path", "eventType"],
            where: withGuild({ createdAt: { gte: thirtyDaysAgo } }),
            _count: { id: true }
        });

        const moduleStatsMap = new Map<string, { views: number; interactions: number; uniqueUsersCount: number }>();
        moduleEventsRaw.forEach((ev: any) => {
            const mod = getModuleName(ev.path);
            if (!moduleStatsMap.has(mod)) {
                moduleStatsMap.set(mod, { views: 0, interactions: 0, uniqueUsersCount: 0 });
            }
            const item = moduleStatsMap.get(mod)!;
            const count = ev._count?.id || 1;
            if (ev.eventType === "PAGE_VIEW") item.views += count;
            else item.interactions += count;
        });

        const moduleStats = Array.from(moduleStatsMap.entries()).map(([name, data]) => ({
            name,
            views: data.views,
            interactions: data.interactions,
            totalActions: data.views + data.interactions,
            uniqueUsersCount: data.views > 0 ? Math.ceil(data.views / 3) : 1
        })).sort((a, b) => b.totalActions - a.totalActions);

        // List of all available guilds for the dropdown selector
        const availableGuilds = guildConfigs.map((g: any) => ({
            id: g.id,
            discordGuildId: g.discordGuildId,
            name: g.name || "Guilde sans nom"
        }));

        return {
            summary: {
                totalEvents,
                pageViews24h,
                interactions24h,
                uniqueUsers24h: uniqueUsers24h.length,
                averageActionsPerUser: uniqueUsers24h.length > 0
                    ? Number(((pageViews24h + interactions24h) / uniqueUsers24h.length).toFixed(1))
                    : 0
            },
            availableGuilds,
            moduleStats,
            liveEvents: liveEvents.map((e: any) => {
                const resolvedGuildId = e.guildId || null;
                return {
                    id: e.id,
                    userId: e.userId,
                    userName: resolveUserName(e.userId, resolvedGuildId, e.userName),
                    guildId: resolvedGuildId,
                    guildName: resolveGuildName(resolvedGuildId),
                    path: e.path,
                    eventType: e.eventType,
                    elementId: e.elementId,
                    details: e.details,
                    createdAt: e.createdAt.toISOString()
                };
            }),
            topPaths: topPathsRaw.map((p: any) => ({
                path: p.path,
                count: p._count
            })),
            topInteractions: topInteractionsRaw.map((i: any) => ({
                elementId: i.elementId || "unknown",
                count: i._count
            })),
            topUsers,
            guildActivity,
            usersLastSeen,
            chartData
        };
    } catch (err) {
        console.error("[getTelemetryStats Error]:", err);
        throw err;
    }
}

"use server";

/**
 * Support Ticket Actions
 * 
 * Server actions for creating, managing, and closing tickets.
 * Handles guild validation triggers and Discord integrations.
 */

import { z } from "zod";
import { db } from "@/lib/prisma";
import { auth } from "@/auth";
import { isSuperAdmin, isDiscordSuperAdmin } from "@/server/actions/super-admin-actions";
import { revalidatePath } from "next/cache";
import {
    createPrivateThread,
    addUserToThread,
    addRoleToMember,
    archiveThread,
    sendChannelMessage,
    fetchChannel,
    fetchGuildRoles,
    fetchGuildChannels,
    fetchBotGuilds,
} from "@/server/discord";
import { getAppBaseUrl } from "@/lib/utils";

// =============================================================================
// SCHEMAS & CONSTANTS
// =============================================================================

const TicketCategorySchema = z.enum(["ACCESS_REQUEST", "BUG_REPORT", "FEATURE_REQUEST", "OTHER"]);
const TicketStatusSchema = z.enum(["OPEN", "IN_PROGRESS", "WAITING_RESPONSE", "CLOSED"]);

const CreateTicketSchema = z.object({
    channelId: z.string().min(15),
    discordGuildId: z.string().min(15),
    category: TicketCategorySchema,
    subject: z.string().min(2).max(100),
    description: z.string().min(10).max(2000),
    creatorDiscordId: z.string().min(15),
    creatorDiscordName: z.string().min(2),
    // Target metadata for ACCESS_REQUEST
    targetGuildId: z.string().optional(),
    targetGuildName: z.string().optional(),
    targetGuildMemberCount: z.number().int().min(1).max(500).optional(),
});

const TICKET_CATEGORY_LABELS: Record<string, string> = {
    ACCESS_REQUEST: "🔑 Accès",
    BUG_REPORT: "🐛 Bug",
    FEATURE_REQUEST: "💡 Feature",
    OTHER: "📩 Autre",
};

const TICKET_STATUS_COLORS: Record<string, number> = {
    ACCESS_REQUEST: 0x10b981, // green
    BUG_REPORT: 0xef4444,    // red
    FEATURE_REQUEST: 0x8b5cf6, // purple
    OTHER: 0x6366f1,         // indigo
};

// =============================================================================
// 1. CREATE TICKET (from Discord interaction)
// =============================================================================

export async function createSupportTicket(input: z.infer<typeof CreateTicketSchema>) {
    const parsed = CreateTicketSchema.safeParse(input);
    if (!parsed.success) return { success: false, error: "Données invalides" };

    const data = parsed.data;

    try {
        // 1. Double check for duplicate (except CLOSED)
        const existingTicket = await db.supportTicket.findFirst({
            where: {
                creatorDiscordId: data.creatorDiscordId,
                category: data.category,
                status: { not: "CLOSED" },
            },
        });

        if (existingTicket) {
            return {
                success: false,
                error: `⛔ ACCÈS REFUSÉ : Vous avez déjà un ticket ouvert dans la catégorie "${TICKET_CATEGORY_LABELS[data.category]}". \n\n💡 Un seul ticket par catégorie est autorisé simultanément pour éviter le spam. Veuillez fermer le ticket #${existingTicket.ticketNumber} avant d'en ouvrir un nouveau.`,
            };
        }

        // 2. CREATE IN DATABASE (FAST)
        const ticket = await db.supportTicket.create({
            data: {
                discordGuildId: data.discordGuildId,
                category: data.category,
                subject: data.subject,
                description: data.description,
                creatorDiscordId: data.creatorDiscordId,
                creatorDiscordName: data.creatorDiscordName,
                targetGuildId: data.targetGuildId,
                targetGuildName: data.targetGuildName,
                targetGuildMemberCount: data.targetGuildMemberCount,
            },
        });

        // 3. BACKGROUND DISCORD OPERATIONS
        // We do NOT await thread creation to respond to Discord interaction within 3s
        (async () => {
            try {
                const threadName = `🎫-${ticket.ticketNumber}-${data.creatorDiscordName}`.substring(0, 100);
                const thread = await createPrivateThread(data.channelId, threadName);

                if (thread) {
                    await db.supportTicket.update({
                        where: { id: ticket.id },
                        data: { discordThreadId: thread.id },
                    });
                    
                    await addUserToThread(thread.id, data.creatorDiscordId);
                    
                    // Force add all super-admins to the private thread so they can see and answer it
                    const { getSuperAdminIds } = await import("@/server/actions/super-admin-actions");
                    const admins = await getSuperAdminIds();
                    for (const adminId of admins) {
                        try {
                            if (adminId !== data.creatorDiscordId) {
                                await addUserToThread(thread.id, adminId);
                            }
                        } catch(e) {}
                    }

                    const categoryLabel = TICKET_CATEGORY_LABELS[data.category] || "📩 Ticket";
                    const embedColor = TICKET_STATUS_COLORS[data.category] || 0x6366f1;

                    await sendChannelMessage(thread.id, `<@${data.creatorDiscordId}>`, {
                        embedTitle: `${categoryLabel} — Ticket #${ticket.ticketNumber}`,
                        embedColor,
                        embedDescription: [
                            `**Auteur :** <@${data.creatorDiscordId}>`,
                            `**Catégorie :** ${categoryLabel}`,
                            `**Sujet :** ${data.subject}`,
                            "",
                            "**Description :**",
                            data.description,
                            "",
                            "─────────────────────────────",
                            "Un membre de l'équipe SigilOS va prendre en charge votre demande.",
                        ].join("\n"),
                        embedFooter: `SigilOS Support · Ticket #${ticket.ticketNumber}`,
                        components: [
                            {
                                type: 1,
                                components: [
                                    {
                                        type: 2, style: 4, label: "Fermer le ticket",
                                        emoji: { name: "🔒" },
                                        custom_id: `ticket:close:${ticket.id}`,
                                    },
                                ],
                            },
                        ],
                    });

                    // [NEW] GLOBAL GOD DASHBOARD NOTIFICATION
                    try {
                        const { notifyGod } = await import("@/server/actions/god-notif-actions");
                        await notifyGod({
                            title: `Nouveau Ticket #${ticket.ticketNumber}`,
                            message: `[${categoryLabel}] ${data.subject} par ${data.creatorDiscordName}`,
                            type: "TICKET",
                            success: true,
                            metadata: {
                                ticketId: ticket.id,
                                category: data.category,
                                creatorId: data.creatorDiscordId,
                                guildId: data.discordGuildId
                            }
                        });
                    } catch (notifErr) {
                        console.error("[Tickets] Dashboard notification failed:", notifErr);
                    }

                    // [NEW] GLOBAL GOD NOTIFICATION (Discord Ping)
                    const platformConfig = await db.platformConfig.findUnique({ where: { id: "singleton" } });
                    if ((platformConfig as any)?.godNotifyChannelId) {
                        const ping = (platformConfig as any).godNotifyRoleId ? `<@&${(platformConfig as any).godNotifyRoleId}>` : "";
                        await sendChannelMessage((platformConfig as any).godNotifyChannelId, ping, {
                            embedTitle: `🎫 Nouveau Ticket #${ticket.ticketNumber}`,
                            embedColor,
                            embedUrl: `${getAppBaseUrl()}/god`, // Link to God dashboard
                            embedDescription: [
                                `**Auteur :** ${data.creatorDiscordName} (<@${data.creatorDiscordId}>)`,
                                `**Catégorie :** ${categoryLabel}`,
                                `**Sujet :** ${data.subject}`,
                                "",
                                `[Voir le fil de discussion](https://discord.com/channels/${data.discordGuildId}/${thread.id})`,
                            ].join("\n"),
                            embedFooter: "SigilOS Administration",
                        });
                    }
                }
            } catch (e) {
                console.error("[Tickets] Async Discord setup failed:", e);
            }
        })();

        revalidatePath("/god");
        return { success: true, ticketNumber: ticket.ticketNumber };
    } catch (error) {
        console.error("[Tickets] Create error:", error);
        return { success: false, error: "Erreur serveur lors de la création." };
    }
}

// =============================================================================
// 2. CLOSE TICKET
// =============================================================================

export async function closeSupportTicket(
    ticketId: string,
    closedByDiscordId: string,
    closedByName: string,
    reason?: string
) {
    // Note: Can be called from Discord button (no session) or Dashboard (session)
    // We trust the discord interaction payload security for the button.

    try {
        const ticket = await db.supportTicket.findUnique({ where: { id: ticketId } });
        if (!ticket) return { success: false, error: "Ticket introuvable." };
        if (ticket.status === "CLOSED") return { success: false, error: "Ticket déjà fermé." };

        // RESTRICTION: Only dev (Super Admin from web), Discord dev, System, or the CREATOR can close
        const isWebAdmin = await isSuperAdmin();
        const isDiscordDev = await isDiscordSuperAdmin(closedByDiscordId);
        const isSystem = closedByDiscordId === "SYSTEM";
        const isCreator = closedByDiscordId === ticket.creatorDiscordId;

        if (!isWebAdmin && !isDiscordDev && !isSystem && !isCreator) {
            return { 
                success: false, 
                error: "🔒 Seule l'équipe technique SigilOS ou l'auteur du ticket peuvent fermer ce ticket." 
            };
        }

        await db.supportTicket.update({
            where: { id: ticketId },
            data: {
                status: "CLOSED",
                closedAt: new Date(),
                closedBy: closedByDiscordId,
                closedReason: reason || "Fermé par l'équipe",
            },
        });

        if (ticket.discordThreadId) {
            await sendChannelMessage(ticket.discordThreadId, "", {
                embedTitle: "🔒 Ticket Fermé",
                embedColor: 0x71717a,
                embedDescription: [
                    `Fermé par **${closedByName}**`,
                    reason ? `**Raison :** ${reason}` : "",
                    "",
                    "Ce fil sera archivé. Pour toute autre demande, ouvrez un nouveau ticket.",
                ].filter(Boolean).join("\n"),
                embedFooter: `SigilOS Support · Ticket #${ticket.ticketNumber}`,
            });
            await archiveThread(ticket.discordThreadId);
        }

        revalidatePath("/god");
        return { success: true };
    } catch (error) {
        console.error("[Tickets] Close error:", error);
        return { success: false, error: "Erreur lors de la fermeture." };
    }
}

// =============================================================================
// 2.5 DELETE TICKET
// =============================================================================

export async function deleteSupportTicket(ticketId: string) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) return { success: false, error: "Accès refusé" };

    try {
        const ticket = await db.supportTicket.findUnique({ where: { id: ticketId } });
        if (!ticket) return { success: false, error: "Ticket introuvable." };

        // 1. Delete associated thread if it exists
        if (ticket.discordThreadId) {
            try {
                const { deleteChannel } = await import("@/server/discord");
                await deleteChannel(ticket.discordThreadId);
            } catch (e) {
                console.warn("[Tickets] Failed to delete Discord thread, might already be gone:", e);
            }
        }

        // 2. Delete from DB
        await db.supportTicket.delete({ where: { id: ticketId } });

        revalidatePath("/god");
        return { success: true };
    } catch (error) {
        console.error("[Tickets] Delete error:", error);
        return { success: false, error: "Erreur lors de la suppression." };
    }
}

/**
 * Automatically close tickets waiting for a response for too long (Default: 7 days)
 */
export async function autoCloseStaleTickets(daysThreshold = 7) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) return { success: false, error: "Accès refusé" };

    try {
        const thresholdDate = new Date();
        thresholdDate.setDate(thresholdDate.getDate() - daysThreshold);

        const staleTickets = await db.supportTicket.findMany({
            where: {
                status: "WAITING_RESPONSE",
                updatedAt: { lt: thresholdDate }
            }
        });

        let closedCount = 0;
        for (const ticket of staleTickets) {
            await closeSupportTicket(
                ticket.id, 
                "SYSTEM", 
                "Automation SigilOS", 
                `Fermeture automatique : aucune réponse de l'utilisateur depuis plus de ${daysThreshold} jours.`
            );
            closedCount++;
        }

        revalidatePath("/god");
        return { success: true, count: closedCount };
    } catch (error) {
        console.error("[Tickets] Auto-close error:", error);
        return { success: false, error: "Erreur lors de la fermeture automatique." };
    }
}

// =============================================================================
// 3. VALIDATE GUILD ACCESS (New Trigger)
// =============================================================================

export async function validateGuildAccess(ticketId: string, discordGuildId: string, notes?: string, roleId?: string) {
    const isAdmin = await isSuperAdmin();
    if (!isAdmin) return { success: false, error: "Accès refusé" };

    try {
        const ticket = await db.supportTicket.findUnique({ where: { id: ticketId } });
        if (!ticket) return { success: false, error: "Ticket introuvable" };

        const session = await auth();

        // 1. Get fresh ticket data & platform config (for default role)
        const [freshTicket, platformConfig] = await Promise.all([
            db.supportTicket.findUnique({ where: { id: ticketId } }),
            db.platformConfig.findUnique({ where: { id: "singleton" } })
        ]);
        
        if (!freshTicket) throw new Error("Ticket introuvable");
        const threadId = freshTicket.discordThreadId;

        // 2. Create/Update AllowedGuild record (Whitelist) - PROMOTE PENDING → ACTIVE
        await db.allowedGuild.upsert({
            where: { discordGuildId },
            update: { 
                isActive: true,
                tier: "VIP",
                notes: notes || `Validé via ticket #${freshTicket.ticketNumber} — ${freshTicket.targetGuildName || "Anonyme"}` 
            },
            create: {
                discordGuildId,
                isActive: true,
                name: freshTicket.targetGuildName || null,
                addedBy: session?.user?.id || "SYSTEM",
                notes: notes || `Validé via ticket #${freshTicket.ticketNumber}`,
                tier: "VIP"
            }
        });

        // 3. [ROLE ASSIGNMENT] Use provided role or platform default
        // Note: role is added on the SUPPORT Discord server (freshTicket.discordGuildId)
        const effectiveRoleId = (roleId && roleId !== "SKIP") 
            ? roleId 
            : (roleId !== "SKIP" ? platformConfig?.ticketAutoRoleId : null);

        if (effectiveRoleId) {
            try {
                await addRoleToMember(freshTicket.discordGuildId, freshTicket.creatorDiscordId, effectiveRoleId);
            } catch (roleErr) {
                console.error("[Tickets] Role assignment failed (non-blocking):", roleErr);
                // Non-blocking: validation continues even if role fails
            }
        }

        // 4. Notify on Discord with PING + Mini-Tutorial
        if (threadId) {
            try {
                await sendChannelMessage(threadId, `<@${freshTicket.creatorDiscordId}>`, {
                    embedTitle: "🚀 Accès Approuvé — Bienvenue sur SigilOS",
                    embedColor: 0x10b981,
                    embedDescription: [
                        `Bonjour <@${ticket.creatorDiscordId}>,`,
                        "",
                        "Bonne nouvelle ! Votre demande d'accès à **SigilOS** a été validée par notre équipe technique.",
                        "",
                        "**📖 Mini-Guide d'Activation :**",
                        `1️⃣ Connectez-vous sur [sigilos.fr](${getAppBaseUrl()}) via Discord.`,
                        "2️⃣ Sur ton Dashboard, clique sur **'Inviter le Bot'** (sur la carte de ta guilde).",
                        "3️⃣ Une fois le bot sur ton serveur, clique sur **'Déployer'** pour installer l'architecture.",
                        "",
                        "💡 *Astuce : Si le bot est déjà présent mais inactif, 'Déployer' suffira à l'allumer.*",
                        "",
                        `**Note de l'administrateur :**`,
                        `> ${notes || "Votre serveur a été ajouté à la whitelist. Bon jeu !"}`
                    ].join("\n"),
                    embedFooter: `Validé par ${session?.user?.name || "L'Équipe SigilOS"}`,
                    embedThumbnail: `${getAppBaseUrl()}/assets/ui/logo-v2.png`
                });
            } catch (discordErr) {
                console.error("[Tickets] Discord notification failed (non-blocking):", discordErr);
            }
        }

        // 5. [AUDIT] Log for traceability — isolated: must NOT crash the validation
        try {
            const auditGuildConfig = await db.guildConfig.findFirst({
                where: { discordGuildId: freshTicket.discordGuildId },
                select: { id: true }
            });
            const auditGuildId = auditGuildConfig?.id || null;

            if (auditGuildId) {
                await db.auditLog.create({
                    data: {
                        guildId: auditGuildId,
                        actorUserId: session?.user?.id || "SYSTEM",
                        actorName: session?.user?.name || "System",
                        action: "GUILD_VALIDATE",
                        targetType: "GUILD",
                        targetId: discordGuildId,
                        metadata: {
                            ticketId,
                            ticketNumber: ticket.ticketNumber,
                            requesterDiscord: ticket.creatorDiscordName,
                            requesterId: ticket.creatorDiscordId,
                            roleAdded: roleId || null
                        }
                    }
                });
            }
        } catch (auditErr) {
            // Audit failure MUST NOT block ticket validation
            console.error("[Tickets] Audit log failed (non-blocking):", auditErr);
        }

        // 6. Mark ticket as CLOSED
        await db.supportTicket.update({
            where: { id: ticketId },
            data: {
                status: "CLOSED",
                closedAt: new Date(),
                closedBy: session?.user?.id || "SYSTEM",
                closedReason: "Accès validé et whitelist créée.",
            },
        });

        revalidatePath("/god");
        return { success: true };
    } catch (error) {
        console.error("[Tickets] Validation error:", error);
        return { success: false, error: "Échec de la validation de guilde." };
    }
}

