// ============================================
// NOTIFY ALL MEMBERS (Ping)
// ============================================

export async function notifyRunMembers(guildId: string, runId: string, message: string = "Le leader demande votre attention !") {
    try {
        const embedData = await buildRunEmbedData(guildId, runId);
        if (!embedData) return { success: false, error: "Données de la run introuvables" };

        const { run, diffConfig, dashboardUrl, fields } = embedData;
        if (!run.discordChannelId) return { success: false, error: "Run ou canal introuvable" };

        const mentions: string[] = [];
        for (const member of run.members) {
            const discordId = await getDiscordId(member.userId);
            if (discordId) mentions.push(`<@${discordId}>`);
        }

        if (mentions.length === 0) return { success: false, error: "Aucun ID Discord trouvé" };

        const { sendChannelMessage } = await import("@/server/discord");

        // Build a nice reminder embed
        const messageId = await sendChannelMessage(
            run.discordChannelId,
            message, // Becomes embed.description
            {
                mentionContent: mentions.join(" "), // Triggers the ping
                embedTitle: `🔔 Rappel Songes : ${diffConfig.emoji} ${diffConfig.label}${embedData.run.epreuveCode ? ` — ${EPREUVE_META[embedData.run.epreuveCode]?.label ?? ""}` : ""}`,
                embedUrl: dashboardUrl,
                embedColor: diffConfig.color,
                fields: [
                    { name: "🛡️ Étage", value: `**${run.currentFloor || 0}**`, inline: true },
                    ...fields.filter(f =>
                        f.name.includes("Équipe") ||
                        f.name.includes("Places")
                    ),
                    ...(embedData.run.epreuveCode && EPREUVE_META[embedData.run.epreuveCode]
                        ? [{ name: "🏆 Épreuve", value: `${EPREUVE_META[embedData.run.epreuveCode].icon} **${EPREUVE_META[embedData.run.epreuveCode].label}**`, inline: true }]
                        : []),
                ],
                embedFooter: `SigilOS • Songes Infinis`,
                embedThumbnail: embedData.thumbnailUrl
            }
        );

        return { success: true, messageId };
    } catch (error) {
        console.error("[Songes Service] notifyRunMembers Error:", error);
        return { success: false, error: "Erreur serveur" };
    }
}

// ============================================
// CLEANUP INACTIVE RUNS
// ============================================

export async function cleanupInactiveRuns(guildId: string) {
    try {
        const threeDaysAgo = new Date(Date.now() - 3 * 24 * 60 * 60 * 1000);

        // Find runs with no activity for 3 days
        const inactiveRuns = await db.dreamRun.findMany({
            where: {
                guildId,
                status: { in: ["RECRUITING", "IN_PROGRESS"] },
                updatedAt: { lt: threeDaysAgo }
            },
            select: { id: true }
        });

        for (const run of inactiveRuns) {
            // Remove embed first
            await deleteDiscordRunEmbed(guildId, run.id);

            // Mark as abandoned
            await db.dreamRun.update({
                where: { id: run.id },
                data: {
                    status: "ABANDONED",
                    completedAt: new Date()
                }
            });
        }
    } catch (error) {
        console.error("[Songes Service] cleanupInactiveRuns Error:", error);
    }
}

// ============================================
// PROCESS RUN JOIN (from Discord button)
// Creates a DreamJoinRequest (candidature), NOT a direct member add.
// The leader must accept/reject from the dashboard.
// ============================================

export async function processRunJoin(guildId: string, runId: string, userId: string, classe: string, message: string) {
    try {
        const guildConfig = await getGuildConfig(guildId);
        if (!guildConfig) return { success: false, error: "Guilde non trouvée" };

        const run = await db.dreamRun.findFirst({
            where: { id: runId, guildId },
            include: {
                members: { orderBy: { slot: "asc" } },
            },
        });

        if (!run) return { success: false, error: "Run non trouvée" };

        // Leader cannot apply to their own run
        if (run.leaderId === userId) {
            return { success: false, error: "Tu es le leader de cette run !" };
        }

        if (run.status !== "RECRUITING" && run.status !== "IN_PROGRESS") {
            return { success: false, error: "Cette run n'accepte plus de candidatures" };
        }

        // Already a member?
        if (run.members.some(m => m.userId === userId)) {
            return { success: false, error: "Tu es déjà dans cette run" };
        }

        // Already has a pending request?
        const existingPending = await db.dreamJoinRequest.findFirst({
            where: { runId: run.id, userId, status: "PENDING" },
        });
        if (existingPending) {
            return { success: false, error: "Tu as déjà une candidature en cours pour cette run" };
        }

        // Anti-spam: check if a notification was sent to the leader about this user in the last 5 min
        const requesterProfile = await getUserProfileData(userId, guildConfig.id);
        const candidateName = requesterProfile.name;
        const fiveMinutesAgo = new Date(Date.now() - 5 * 60 * 1000);
        const recentSpam = await db.notification.findFirst({
            where: {
                userId: run.leaderId,
                title: "Nouvelle candidature Songes",
                message: { contains: candidateName },
                createdAt: { gt: fiveMinutesAgo },
            },
        });

        if (recentSpam) {
            const remainingMs = 5 * 60 * 1000 - (Date.now() - recentSpam.createdAt.getTime());
            if (remainingMs > 0) {
                const minutes = Math.floor(remainingMs / 60000);
                const seconds = Math.floor((remainingMs % 60000) / 1000);
                return { success: false, error: `Patiente encore ${minutes}m ${seconds}s avant de postuler.` };
            }
        }

        // Delete old ACCEPTED/REJECTED requests to allow re-application
        await db.dreamJoinRequest.deleteMany({
            where: {
                runId: run.id,
                userId,
                status: { in: ["ACCEPTED", "REJECTED"] },
            },
        });

        // Create the candidature
        await db.dreamJoinRequest.create({
            data: {
                runId: run.id,
                userId,
                classe: classe,
                message: message || "Candidature via Discord",
            },
        });

        // Notify leader in-app
        const publicUrl = getAppBaseUrl();
        const dashboardUrl = `${publicUrl}/dashboard/${guildId}/songes`;

        // Notify leader in-app
        await createNotification(
            run.leaderId,
            "SONGES_JOIN_REQUEST",
            "Candidature Songes",
            `**${candidateName}** (${classe}) • Run ${run.difficulty}`,
            `/dashboard/${guildId}/songes`,
            guildId
        );

        // Ping leader in Discord channel
        if (run.discordChannelId) {
            const leaderDiscordId = await getDiscordId(run.leaderId);
            const leaderMention = leaderDiscordId ? `<@${leaderDiscordId}>` : "Leader";

            await sendChannelMessage(
                run.discordChannelId,
                `📩 ${leaderMention} — **${candidateName}** (${classe}) a postulé ! [Dashboard](${dashboardUrl})`,
                { suppressEmbeds: true },
            );
        }

        return { success: true };
    } catch (error) {
        console.error("[Songes Service] processRunJoin Error:", error);
        return { success: false, error: "Erreur serveur" };
    }
}

// ============================================
// PROCESS RUN LEAVE (from Discord button)
// Handles: member leave, waitlist leave, and candidature cancel
// ============================================

export async function processRunLeave(guildId: string, runId: string, userId: string) {
    try {
        const guildConfig = await getGuildConfig(guildId);
        if (!guildConfig) return { success: false, error: "Guilde non trouvée" };

        const run = await db.dreamRun.findFirst({
            where: { id: runId, guildId },
            include: {
                members: { orderBy: { slot: "asc" } },
                waitlist: { orderBy: { position: "asc" } },
            },
        });

        if (!run) return { success: false, error: "Run non trouvée" };

        // Cannot leave if you're the leader
        if (run.leaderId === userId) {
            return { success: false, error: "Le leader ne peut pas quitter depuis Discord. Utilise le dashboard." };
        }

        // 1. Check if member → leave + promote waitlist
        const member = run.members.find(m => m.userId === userId);
        if (member) {
            await db.dreamRunMember.delete({ where: { id: member.id } });

            // Promote first from waitlist
            const firstWaitlisted = run.waitlist[0];
            if (firstWaitlisted) {
                await db.$transaction([
                    db.dreamRunMember.create({
                        data: {
                            runId,
                            userId: firstWaitlisted.userId,
                            slot: member.slot,
                        },
                    }),
                    db.dreamWaitlist.delete({ where: { id: firstWaitlisted.id } }),
                    db.dreamWaitlist.updateMany({
                        where: { runId, position: { gt: firstWaitlisted.position } },
                        data: { position: { decrement: 1 } },
                    }),
                ]);

                // Notify promoted user in channel
                if (run.discordChannelId) {
                    const promotedDiscordId = await getDiscordId(firstWaitlisted.userId);
                    const promotedProfile = await getUserProfileData(firstWaitlisted.userId, guildConfig.id);
                    const promotedName = promotedProfile.name;
                    const mention = promotedDiscordId ? `<@${promotedDiscordId}>` : promotedName;
                    await sendChannelMessage(
                        run.discordChannelId,
                        `🎉 ${mention} — Une place s'est libérée ! Tu as été promu dans la run Songes.`,
                    );
                }
            }

            await updateDiscordRunEmbed(guildId, runId);
            return { success: true };
        }

        // 2. Check if on waitlist → remove
        const waitlisted = run.waitlist.find(w => w.userId === userId);
        if (waitlisted) {
            await db.$transaction([
                db.dreamWaitlist.delete({ where: { id: waitlisted.id } }),
                db.dreamWaitlist.updateMany({
                    where: { runId, position: { gt: waitlisted.position } },
                    data: { position: { decrement: 1 } },
                }),
            ]);

            await updateDiscordRunEmbed(guildId, runId);
            return { success: true };
        }

        // 3. Check if has pending candidature → cancel it
        const pendingRequest = await db.dreamJoinRequest.findFirst({
            where: { runId: run.id, userId, status: "PENDING" },
        });
        if (pendingRequest) {
            await db.dreamJoinRequest.delete({ where: { id: pendingRequest.id } });
            return { success: true };
        }

        return { success: false, error: "Tu n'es ni dans cette run, ni en file d'attente, ni candidat" };
    } catch (error) {
        console.error("[Songes Service] processRunLeave Error:", error);
        return { success: false, error: "Erreur serveur" };
    }
}

import "dotenv/config";
import { createServer } from "http";
import { Server, Socket } from "socket.io";
import { createAdapter } from "@socket.io/redis-adapter";
import { redis } from "../../lib/redis";
import { GeoguesserManager } from "../games/SigilGuesser/GeoguesserManager";
import { WorldMapService } from "../games/SigilGuesser/WorldMapService";
import { BombManager } from "../games/SigilBomb/BombManager";
import { rateLimit } from "../../lib/ratelimit";
import { DiscordVoiceService } from "../discord/voice-service";
import { getRushActiveMembers } from "../actions/rush-actions";
import { logger as AppLogger } from "../../lib/logger";

// Fallback if logger is not correctly initialized
const logger = AppLogger || console;

// Load Geoguesser data
WorldMapService.getInstance().loadData();

const PORT = 3001;

// Create standalone HTTP server for WebSockets
const httpServer = createServer((req, res) => {
    // Only log in dev — HTTP requests in prod pollute container logs
    logger.debug(`[HTTP] 📥 ${req.method} ${req.url}`);
    if (req.url === "/health") {
        res.writeHead(200);
        res.end("OK");
        return;
    }
});

const pubClient = redis.duplicate();
const subClient = redis.duplicate();

const isProd = process.env.NODE_ENV === "production";

const io = new Server(httpServer, {
    // 🔒 [SECURITY] Limit payload size to 1MB — prevents OOM from oversized canvas events
    maxHttpBufferSize: 1e6,
    // Socket timeouts — detect dead connections faster
    pingTimeout: 20_000,
    pingInterval: 25_000,
    cors: {
        origin: (origin, callback) => {
            // [AUDIT 2026] MED-04: Strict origin validation to prevent Cross-Site WebSocket Hijacking
            if (!isProd) {
                return callback(null, true);
            }
            
            const allowedOrigins = [
                "https://sigilos.fr",
                "https://beta.sigilos.fr"
            ];

            if (origin && allowedOrigins.includes(origin)) {
                callback(null, true);
            } else {
                logger.warn("[WS] ⚠️ Connexion bloquée par CORS (Origin non autorisée)", { origin });
                callback(new Error("Not allowed by CORS"));
            }
        },
        methods: ["GET", "POST"],
        credentials: true
    },
    // On n'active l'adapter Redis que si on a les clients prêts (utile pour le VPS)
    adapter: isProd ? createAdapter(pubClient, subClient) : undefined,
    path: "/socket.io/",
    // [AUDIT 2026] UX-01: Resilience for mobile/tunnel users
    connectionStateRecovery: {
        // Recovery window: 2 minutes (allow temporary signal loss)
        maxDisconnectionDuration: 2 * 60 * 1000,
        // Whether to discard events of some rooms when we can't recover the state
        skipMiddlewares: true,
    }
});

// [AUDIT 2026] HARD-03: Connection Rate Limiting
io.use(async (socket, next) => {
    const ip = socket.handshake.address;
    const { success } = await rateLimit(`ws-connect:${ip}`, 10, 60000);
    
    if (!success) {
        logger.warn("[WS] 🛑 Rate limit atteint pour la connexion (IP: ${ip})");
        return next(new Error("Rate limit exceeded. Please wait a minute."));
    }
    next();
});


const geoguesserManager = new GeoguesserManager(io);
const bombManager = new BombManager(io);

// === DISCORD VOICE MONITORING ===
const voiceService = DiscordVoiceService.getInstance();
voiceService.setOnUpdate((guildId, users) => {
    io.to(`guild:${guildId}`).emit("discord:voice:update", { 
        guildId, 
        users 
    });
    logger.info(`[WS] 🎤 Broadcast Voice Update (${users.length} users) for guild ${guildId}`);
});
voiceService.start().catch(err => logger.error("[WS] ❌ Erreur démarrage VoiceService:", err));

// [New] Broadcast Ocre Trade & DJ Finder Updates from Redis
subClient.subscribe("ocre:trade:update", "dj:finder:update", (err) => {
    if (err) logger.error("[WS] ❌ Erreur abonnement Redis:", { error: err });
});

subClient.on("message", (channel, message) => {
    if (channel === "ocre:trade:update" || channel === "dj:finder:update") {
        try {
            const data = JSON.parse(message);
            if (data.guildId) {
                io.to(`guild:${data.guildId}`).emit(channel, data);
                logger.info(`[WS] 🔄 Broadcast ${channel} pour guilde ${data.guildId}`);
            }
        } catch (e) {
            logger.error(`[WS] ❌ Erreur parsing message ${channel}:`, { error: e });
        }
    }
});

// Gestionnaire global des connexions
io.on("connection", (socket: Socket) => {
    let guildId = socket.handshake.query.guildId as string;
    if (guildId === "undefined" || guildId === "null" || !guildId) guildId = "global";

    if (guildId && guildId !== "global") {
        socket.join(`guild:${guildId}`);
        logger.info(`[WS] 🏢 Client ${socket.id} a rejoint le salon guilde: ${guildId}`);
        
        // [New] Send initial voice state immediately
        const residents = voiceService.getVoiceUsers(guildId);
        if (residents.length > 0) {
            socket.emit("discord:voice:update", { guildId, users: residents });
            logger.info(`[WS] 🎤 Initial Voice Sync (${residents.length} users) for ${socket.id}`);
        }
    } else {
        socket.join("guild:global");
    }

    logger.info(`[WS] 🟢 Client connecté: ${socket.id}`);
    socket.emit("test:heartbeat", { time: Date.now() });

    // === SIGIL-GUESSER ===
    logger.info(`[WS] Initialisation Geoguesser pour ${socket.id}`);
    geoguesserManager.registerSocket(socket);

    // === SIGIL BOMB ===
    logger.info(`[WS] Initialisation SigilBomb pour ${socket.id}`);
    bombManager.registerSocket(socket);

    // [New] Direct voice request for immediate sync
    socket.on("discord:voice:request", (data: { guildId: string }) => {
        if (!data.guildId) return;
        const residents = voiceService.getVoiceUsers(data.guildId);
        socket.emit("discord:voice:update", { guildId: data.guildId, users: residents });
        logger.info(`[WS] 🎤 Manual Voice Sync (${residents.length} users) for ${socket.id}`);
    });

    // === RUSH SYLVESTRE PRESENCE ===
    socket.on("rush:join", async (data: { guildId: string }) => {
        if (!data.guildId) return;
        logger.info(`[WS] 🏃 ${socket.id} joined rush in guild ${data.guildId}`);
        // Broadcast to guild room so everyone sees the update
        const result = await getRushActiveMembers(data.guildId);
        if (result.success) {
            io.to(`guild:${data.guildId}`).emit("rush:presence:update", {
                guildId: data.guildId,
                members: result.members,
            });
        }
    });

    socket.on("rush:leave", async (data: { guildId: string }) => {
        if (!data.guildId) return;
        logger.info(`[WS] 🏃 ${socket.id} left rush in guild ${data.guildId}`);
        const result = await getRushActiveMembers(data.guildId);
        if (result.success) {
            io.to(`guild:${data.guildId}`).emit("rush:presence:update", {
                guildId: data.guildId,
                members: result.members,
            });
        }
    });

    socket.on("rush:heartbeat", async (data: { guildId: string }) => {
        if (!data.guildId) return;
        // Broadcast updated presence to guild room
        const result = await getRushActiveMembers(data.guildId);
        if (result.success) {
            io.to(`guild:${data.guildId}`).emit("rush:presence:update", {
                guildId: data.guildId,
                members: result.members,
            });
        }
    });

    // Gestion de la déconnexion
    socket.on("disconnect", (reason) => {
        logger.info(`[WS] 🔴 Client déconnecté: ${socket.id} (Raison: ${reason})`);
        geoguesserManager.handleDisconnect(socket, reason);
        bombManager.handleDisconnect(socket);
    });
});

// On démarre sans spécifier d'IP pour laisser l'OS choisir (souvent :: et 0.0.0.0)
// En dev, on écoute partout pour éviter les soucis de résolution localhost
try {
    httpServer.listen(PORT, "::", () => {
        logger.info(`[WS] 🚀 Serveur WebSocket démarré sur le port ${PORT} (IPv4/IPv6)`);
        logger.info(`[WS] Testez via: http://localhost:${PORT}/health`);
    });
} catch (err: any) {
    logger.error("[WS] ❌ Erreur FATALE au démarrage:", err);
    process.exit(1);
}

httpServer.on("error", (err) => {
    logger.error("[WS] ❌ Erreur Serveur HTTP:", err);
});

// Gestion de l'extinction propre (Graceful Shutdown)
const shutdown = () => {
    logger.info("[WS] Extinction du serveur WebSocket...");
    io.close(() => {
        httpServer.close(() => {
            logger.info("[WS] Serveur fermé.");
            process.exit(0);
        });
    });
};

process.on("SIGINT", shutdown);
process.on("SIGTERM", shutdown);

/**
 * SigilOS — Ladder Sync Worker
 * ============================================================
 * Synchronises Dofus ladder data (success points + general XP)
 * into UserProfile for every active member of every guild.
 *
 * Data source: Cloudflare Worker (dofus-ladder-proxy)
 *   GET <DOFUS_LADDER_WORKER_URL>?server_id=295&name=Pseudo&type=succes
 *   GET <DOFUS_LADDER_WORKER_URL>?server_id=295&name=Pseudo&type=general
 *
 * ─── Anti-ban / Rate limit strategy ──────────────────────────────────────────
 *
 * The CF Worker itself calls dofus.com which uses Cloudflare for DDoS
 * protection. Sending too many simultaneous requests risks triggering
 * a bot-detection challenge (JS challenge, captcha, or IP-level block).
 *
 * Mitigations applied here:
 *   1. STRICTLY SEQUENTIAL per-profile processing (no parallel fetches)
 *   2. Random jitter between each call  (BASE_DELAY + 0-JITTER_MAX ms)
 *   3. HTTP 429 / 503 → exponential backoff with max 3 retries
 *   4. Shuffle profiles order each run (no predictable timing signature)
 *   5. `ladderLastSyncAt` timestamp check — skip profiles synced < 22h ago
 *      (safe guard if cron fires twice / multiple guilds share same player)
 *   6. Graceful abort: if 5 consecutive 429s received, stop the whole job
 *      to avoid getting the CF Worker's egress IP range flagged
 *
 * Schedule: Every day at 03:00 (cron via BullMQ repeat)
 *
 * Env vars required:
 *   DOFUS_LADDER_WORKER_URL  — URL of the deployed Cloudflare Worker
 *   DOFUS_LADDER_WORKER_KEY  — X-SigilOS-Key secret header
 */

import "dotenv/config";
import { Worker, Queue, Job } from "bullmq";
import { defaultQueueOptions } from "../lib/queue/metamob-queue";
import { db } from "../lib/prisma";
import { logger } from "../lib/logger";

// ─── Config ──────────────────────────────────────────────────────────────────

const LADDER_QUEUE_NAME = "sigilos-ladder-sync";
const WORKER_URL = process.env.DOFUS_LADDER_WORKER_URL;
const WORKER_KEY = process.env.DOFUS_LADDER_WORKER_KEY;

// Minimum delay between two calls to the CF Worker (ms)
// 1 call / 2s = 30 calls/min → very reasonable
const BASE_DELAY_MS = 2000;
// Added random jitter on top of base delay to avoid clock-signature detection
const JITTER_MAX_MS = 1000;
// Min hours between two syncs for the same profile (prevents double-sync)
const MIN_HOURS_BETWEEN_SYNC = 22;
// If this many consecutive 429/503 errors occur, abort the whole job
const MAX_CONSECUTIVE_ERRORS = 5;
// Max retries per individual request
const MAX_RETRIES = 3;

// ─── Types ────────────────────────────────────────────────────────────────────

interface CFSuccesResponse {
    found: boolean;
    points?: number;
    level?: number;
}

interface CFGeneralResponse {
    found: boolean;
    totalXp?: string;  // raw string to preserve BigInt precision
    level?: number;
    classe?: string;
}

type CFResponse = CFSuccesResponse | CFGeneralResponse;

// ─── Helpers ─────────────────────────────────────────────────────────────────

/** Random int between min and max (inclusive) */
function randomBetween(min: number, max: number): number {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

/** Shuffles array in-place (Fisher-Yates) */
function shuffle<T>(arr: T[]): T[] {
    for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
}

/** Polite pause with jitter */
async function politeDelay(): Promise<void> {
    const ms = BASE_DELAY_MS + randomBetween(0, JITTER_MAX_MS);
    await new Promise(r => setTimeout(r, ms));
}

/**
 * Fetch one ladder type for one character from the Cloudflare Worker.
 * Implements retry with exponential backoff on 429/503.
 * Returns null if the character isn't found or after exhausting retries.
 *
 * @throws {Error} if the server returns an unexpected error (not 429/503)
 */
async function fetchFromCloudflare(
    pseudo: string,
    serverId: string,
    type: "succes" | "general",
    attempt = 0
): Promise<CFResponse | null> {
    if (!WORKER_URL) return null;

    const url = `${WORKER_URL}?server_id=${encodeURIComponent(serverId)}&name=${encodeURIComponent(pseudo)}&type=${type}`;
    const headers: Record<string, string> = { "Accept": "application/json" };
    if (WORKER_KEY) headers["X-SigilOS-Key"] = WORKER_KEY;

    let res: Response;
    try {
        res = await fetch(url, {
            headers,
            signal: AbortSignal.timeout(20_000),
        });
    } catch (err: any) {
        // Network timeout or connection error
        if (attempt < MAX_RETRIES) {
            const backoff = (attempt + 1) * 3000 + randomBetween(0, 2000);
            logger.warn(`[LadderSync] Timeout ${pseudo} (${type}), retry ${attempt + 1}/${MAX_RETRIES} dans ${backoff}ms`);
            await new Promise(r => setTimeout(r, backoff));
            return fetchFromCloudflare(pseudo, serverId, type, attempt + 1);
        }
        logger.warn(`[LadderSync] Abandon après ${MAX_RETRIES} tentatives pour ${pseudo} (${type}): ${err.message}`);
        return null;
    }

    // Rate limited → exponential backoff + retry
    if (res.status === 429 || res.status === 503) {
        if (attempt < MAX_RETRIES) {
            const retryAfter = parseInt(res.headers.get("Retry-After") || "0", 10);
            // Respect Retry-After header if present, otherwise exponential backoff
            const backoff = retryAfter * 1000 || (Math.pow(2, attempt + 1) * 5000 + randomBetween(0, 3000));
            logger.warn(`[LadderSync] ${res.status} pour ${pseudo} (${type}) — backoff ${backoff}ms (retry ${attempt + 1}/${MAX_RETRIES})`);
            await new Promise(r => setTimeout(r, backoff));
            return fetchFromCloudflare(pseudo, serverId, type, attempt + 1);
        }
        // Signal to caller that this was a rate limit failure (not just "not found")
        throw new Error(`RATE_LIMIT:${res.status}`);
    }

    if (!res.ok) {
        logger.warn(`[LadderSync] CF Worker → ${res.status} pour ${pseudo} (${type})`);
        return null;
    }

    return await res.json() as CFResponse;
}

